def _configure_utf8_console_streams() -> None:
    """Unifica la codificación del proceso para logs y módulos importados."""
    for stream in (getattr(sys, "stdout", None), getattr(sys, "stderr", None)):
        reconfigure = getattr(stream, "reconfigure", None)
        if not callable(reconfigure):
            continue
        try:
            reconfigure(encoding="utf-8", errors="replace")
        except (OSError, ValueError):
            pass


_configure_utf8_console_streams()
ensure_runtime_layout()


WPSETTER_LOG_FILE = str(runtime_file("wpsetter_logs.txt"))
wpsetter_logger = logging.getLogger("wpsetter")
wpsetter_logger.setLevel(logging.INFO)
wpsetter_logger.propagate = False
if not wpsetter_logger.handlers:
    _wpsetter_file_handler = logging.FileHandler(WPSETTER_LOG_FILE, encoding="utf-8")
    _wpsetter_file_handler.setFormatter(logging.Formatter("%(asctime)s - %(levelname)s - %(message)s"))
    wpsetter_logger.addHandler(_wpsetter_file_handler)

_original_print = builtins.print


def _print_args_for_stream(args, stream):
    """Evita que una consola Windows cp1252 derribe el proceso por un emoji."""
    encoding = getattr(stream, "encoding", None)
    if not encoding:
        return args
    return tuple(
        str(arg).encode(encoding, errors="replace").decode(encoding)
        for arg in args
    )


def print(*args, **kwargs):
    stream = kwargs.get("file") or sys.stdout
    _original_print(*_print_args_for_stream(args, stream), **kwargs)
    try:
        sep = kwargs.get("sep", " ")
        end = kwargs.get("end", "\n")
        msg = sep.join(str(arg) for arg in args)
        if end and end != "\n":
            msg += str(end)
        if msg.strip():
            wpsetter_logger.info(msg.rstrip("\n"))
    except Exception:
        pass


def _log_unhandled_exception(exc_type, exc_value, exc_traceback):
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc_value, exc_traceback)
        return
    wpsetter_logger.exception("Excepción no controlada en WPSetter", exc_info=(exc_type, exc_value, exc_traceback))
    sys.__excepthook__(exc_type, exc_value, exc_traceback)


sys.excepthook = _log_unhandled_exception


