# FUNCIÓN: ORDENAR CALENDARIO (SÍNCRONA)
# ================================
def ordenar_calendario_sync() -> bool:
    """
    Ejecuta calendario.py --order de forma síncrona.
    Retorna True si se ejecutó correctamente.
    """
    try:
        script_dir = str(PROJECT_ROOT)
        calendario_path = os.path.join(script_dir, "calendario.py")

        if not os.path.exists(calendario_path):
            return False

        env = os.environ.copy()
        if sys.platform == 'win32':
            env['PYTHONIOENCODING'] = 'utf-8'
            env['PYTHONUTF8'] = '1'

        result = subprocess.run(
            [sys.executable, calendario_path, "--order"],
            capture_output=True,
            text=True,
            timeout=10,
            env=env,
            encoding='utf-8',
            errors='replace'
        )

        if result.returncode == 0:
            print(f"   ✅ [ORDER] Calendario ordenado correctamente")
            return True
        else:
            print(f"   ⚠️ [ORDER] Error: {result.stderr[:100] if result.stderr else 'sin error'}")
            return False

    except subprocess.TimeoutExpired:
        print(f"   ⚠️ [ORDER] Timeout ejecutando calendario.py --order")
        return False
    except Exception as e:
        print(f"   ⚠️ [ORDER] Error: {e}")
        return False

