async def _hay_chat_abierto(page) -> bool:
    """
    Verifica si hay un chat abierto en WhatsApp Web.
    Retorna True si el textarea de escritura está visible.
    """
    try:
        textarea = page.locator('div[contenteditable="true"][data-tab="10"]')
        return await textarea.count() > 0 and await textarea.is_visible()
    except Exception:
        return False


