    async def _verify_all_selectors(self, page):
        """
        🆕 Verifica TODOS los selectores aprendidos.
        """
        try:
            print("   🔍 [Verificación] Verificando selectores aprendidos...")

            # Verificar burbujas
            all_selector = await get_best_bubble_selector(page, "all", force_refresh=True)
            if all_selector:
                score = await _score_bubble_selector(page, all_selector, "all")
                print(f"   📊 All selector: {score['score']}/{score['total']} ({score['score']/max(score['total'],1):.0%})")

            user_selector = await get_best_bubble_selector(page, "user", force_refresh=True)
            if user_selector:
                score = await _score_bubble_selector(page, user_selector, "user")
                print(f"   📊 User selector: {score['score']}/{score['total']} ({score['score']/max(score['total'],1):.0%})")

            # Verificar navegación
            unread_selector = self.all_selectors["navigation"].get("unread_active") or self.all_selectors["navigation"].get("unread_ai")
            if unread_selector:
                try:
                    if await page.locator(unread_selector).count() > 0:
                        print(f"   ✅ Navigation: Unread selector funciona")
                except:
                    print(f"   ⚠️ Navigation: Unread selector falla")

            # Verificar input
            textarea_selector = self.all_selectors["input"].get("textarea_active")
            if textarea_selector:
                try:
                    if await page.locator(textarea_selector).count() > 0:
                        print(f"   ✅ Input: Textarea funciona")
                except:
                    print(f"   ⚠️ Input: Textarea falla")

            # Verificar chat list
            try:
                chat_list = page.locator("div[data-testid='chat-list']")
                if await chat_list.count() > 0:
                    print(f"   ✅ Chat List: Funciona")
            except:
                print(f"   ⚠️ Chat List: Falló")

            # Verificar sesión
            try:
                qr = page.locator("//div[normalize-space()='Escanea para iniciar sesión']")
                if await qr.count() == 0:
                    print(f"   ✅ Session: QR no visible (sesión activa)")
                else:
                    print(f"   ℹ️ Session: QR visible (sesión cerrada)")
            except:
                pass

            print("   ✅ [Verificación] Completada")

        except Exception as e:
            print(f"   ⚠️ [SelectorProactive] Error verificando selectores: {e}")

    def get_health_summary(self) -> str:
        """Obtiene un resumen de la salud de TODOS los selectores."""
        history = self.selector_health_history.get("history", [])
        if not history:
            return "Sin datos de salud disponibles"

        last = history[-1]
        health = last.get("health", {})
        avg_score = health.get("overall_score", 0)
        total = health.get("total_selectors", 0)
        working = health.get("working_selectors", 0)
        failed = health.get("failed_selectors", [])

        status = "🟢 BUENA" if avg_score > 0.7 else "🟡 MEDIA" if avg_score > 0.4 else "🔴 BAJA"

        return f"Salud: {status} ({avg_score:.0%}) | {working}/{total} selectores funcionando | Fallos: {len(failed)}"

    def get_detailed_report(self) -> str:
        """Genera un reporte detallado de TODOS los selectores."""
        history = self.selector_health_history.get("history", [])
        if not history:
            return "Sin historial de salud disponible"

        last = history[-1]
        health = last.get("health", {})

        report = []
        report.append("=" * 60)
        report.append("📊 REPORTE DETALLADO DE SELECTORES")
        report.append("=" * 60)
        report.append(f"Timestamp: {datetime.datetime.now().isoformat()}")
        report.append(f"Score general: {health.get('overall_score', 0):.0%}")
        report.append(f"Selectores funcionando: {health.get('working_selectors', 0)}/{health.get('total_selectors', 0)}")
        report.append(f"Selectores fallidos: {len(health.get('failed_selectors', []))}")

        if health.get('failed_selectors'):
            report.append("\n❌ SELECTORES FALLIDOS:")
            for s in health.get('failed_selectors', [])[:10]:
                report.append(f"  - {s}")

        if health.get('working_selectors_list'):
            report.append("\n✅ SELECTORES FUNCIONANDO:")
            for s in health.get('working_selectors_list', [])[:10]:
                report.append(f"  - {s}")

        report.append("=" * 60)
        return "\n".join(report)

