async def call_openai_async(**kwargs):
    """Ejecuta el cliente sincrono de OpenAI fuera del event loop."""
    global TOTAL_LLM_CALLS
    TOTAL_LLM_CALLS += 1
    turn_calls = AGENT_V2_TURN_LLM_CALLS.get()
    if turn_calls is not None:
        AGENT_V2_TURN_LLM_CALLS.set(int(turn_calls) + 1)
    return await asyncio.to_thread(client.chat.completions.create, **kwargs)


def _loads_llm_json_object(raw: str) -> Dict[str, Any]:
    """
    Carga JSON devuelto por LLM con defensas mínimas.

    `response_format=json_object` reduce muchísimo el riesgo, pero una respuesta
    truncada por max_tokens o envuelta en fences todavía puede romper json.loads.
    """
    text = str(raw or "").strip()
    text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*```$", "", text).strip()
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        start = text.find("{")
        end = text.rfind("}")
        if start >= 0 and end > start:
            data = json.loads(text[start:end + 1])
        else:
            raise
    return data if isinstance(data, dict) else {}

