def _conversation_state_key(telefono: str) -> str:
    """Clave estable para memoria persistente de conversación."""
    if telefono and str(telefono).startswith("NOMBRE:"):
        return str(telefono).strip()
    return normalize_phone(telefono) if telefono else "unknown"


def _memory_owner_key(telefono: str) -> str:
    """
    Namespace canónico de memoria.

    Un estado persistente solo puede pertenecer a UNA identidad. Nunca usamos
    datos temporales de otro teléfono/contacto y nunca consideramos "unknown"
    una identidad persistente válida para Agent V2.
    """
    return _conversation_state_key(telefono)


def _memory_owner_is_stable(telefono: str) -> bool:
    key = _memory_owner_key(telefono)
    return bool(key and key != "unknown")


def _load_persisted_conversation_states() -> Dict[str, Dict[str, Any]]:
    if not os.path.exists(CONVERSATION_STATE_FILE):
        return {}
    try:
        with open(CONVERSATION_STATE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {}
        for state in data.values():
            if not isinstance(state, dict):
                continue
            ultima = state.get("ultima_actualizacion")
            if isinstance(ultima, str):
                try:
                    state["ultima_actualizacion"] = datetime.datetime.fromisoformat(ultima)
                except Exception:
                    pass
        return data
    except Exception as e:
        print(f"   ⚠️ [MEMORIA] No pude cargar estado persistente: {e}")
        return {}


def _persist_conversation_states() -> bool:
    """Persistencia atómica: nunca deja el archivo a medio escribir."""
    try:
        base_dir = os.path.dirname(CONVERSATION_STATE_FILE) or "."
        fd, tmp_path = tempfile.mkstemp(prefix="conversation_states_", suffix=".tmp", dir=base_dir)
        os.close(fd)
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(conversation_states, f, ensure_ascii=False, indent=2, default=str)
        os.replace(tmp_path, CONVERSATION_STATE_FILE)
        return True
    except Exception as e:
        print(f"   ⚠️ [MEMORIA] No pude persistir estado conversacional: {e}")
        try:
            if 'tmp_path' in locals() and os.path.exists(tmp_path):
                os.remove(tmp_path)
        except Exception:
            pass
        return False


# Rehidrata contexto al arrancar el proceso.
conversation_states.update(_load_persisted_conversation_states())

class BotState:
    def __init__(self):
        self.is_active = True
        self.authorized_number = AUTHORIZED_NUMBER
        self.pause_control_number = AUTHORIZED_NUMBER
        self.authorized_mode = "admin"
        self.previous_mode = "admin"
        self.autonomy_level = DEFAULT_AUTONOMY_LEVEL
        self.last_proactive_run = 0
        self.last_state_change = datetime.datetime.now()

    def save(self):
        try:
            with open(STATE_FILE, 'wb') as f:
                pickle.dump(self.__dict__, f)
        except:
            pass

    def load(self):
        try:
            if os.path.exists(STATE_FILE):
                with open(STATE_FILE, 'rb') as f:
                    data = pickle.load(f)
                    self.__dict__.update(data)
                    if not hasattr(self, 'authorized_mode'):
                        self.authorized_mode = "admin"
                    if not hasattr(self, 'previous_mode'):
                        self.previous_mode = "admin"
                    if not hasattr(self, 'autonomy_level'):
                        self.autonomy_level = DEFAULT_AUTONOMY_LEVEL
                    if not hasattr(self, 'last_proactive_run'):
                        self.last_proactive_run = 0
                    if not hasattr(self, 'pause_control_number'):
                        self.pause_control_number = AUTHORIZED_NUMBER
        except:
            pass

bot_state = BotState()
bot_state.load()


def get_pause_control_number() -> str:
    numero = normalize_phone(getattr(bot_state, "pause_control_number", "") or "")
    if numero and numero in {normalize_phone(n) for n in AUTHORIZED_NUMBERS}:
        return numero
    numero = normalize_phone(getattr(bot_state, "authorized_number", "") or "")
    if numero and numero in {normalize_phone(n) for n in AUTHORIZED_NUMBERS}:
        return numero
    return normalize_phone(AUTHORIZED_NUMBER)


def set_pause_control_number(telefono: str) -> str:
    numero = normalize_phone(telefono or "")
    if not numero or numero not in {normalize_phone(n) for n in AUTHORIZED_NUMBERS}:
        numero = normalize_phone(AUTHORIZED_NUMBER)
    bot_state.pause_control_number = numero
    bot_state.authorized_number = numero
    return numero

