TOTAL_COST = 0.0
TOTAL_LLM_CALLS = 0
AGENT_V2_TURN_LLM_CALLS = contextvars.ContextVar(
    "agent_v2_turn_llm_calls",
    default=None,
)

def register_cost(resp):
    global TOTAL_COST
    try:
        usage = getattr(resp, "usage", None)
        if usage:
            prompt_t = getattr(usage, "prompt_tokens", 0) or getattr(usage, "input_tokens", 0) or 0
            completion_t = getattr(usage, "completion_tokens", 0) or getattr(usage, "output_tokens", 0) or 0
            cost = (prompt_t * 0.00000015) + (completion_t * 0.00000060)
            TOTAL_COST += cost
    except:
        pass

def detectar_despedida_ia(mensaje: str, conv_state: Dict = None) -> bool:
    """
    Detecta si un mensaje es una despedida usando IA con contexto completo.
    """
    if not conv_state:
        return _detectar_despedida_simple(mensaje)

    fase_actual = conv_state.get("fase", "inicial")
    historial = conv_state.get("historial", [])
    dia_propuesto = conv_state.get("dia_propuesto")
    hora_propuesta = conv_state.get("hora_propuesta")

    contexto = f"""
FASE ACTUAL: {fase_actual}
DÍA PROPUESTO: {dia_propuesto or "ninguno"}
HORA PROPUESTA: {hora_propuesta or "ninguna"}

ÚLTIMOS MENSAJES DEL HISTORIAL:
"""
    for msg in historial[-6:]:
        role = "Agente" if msg["role"] == "assistant" else "Usuario"
        contexto += f"{role}: {msg['content'][:150]}\n"

    contexto += f"\nMENSAJE A ANALIZAR: \"{mensaje}\"\n"

    try:
        resp = client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un clasificador de intención de mensajes de WhatsApp para reservas de canchas.\n\n"
                        "Tu tarea es determinar si el mensaje del usuario es una DESPEDIDA "
                        "(quiere terminar la conversación) o NO es una despedida.\n\n"
                        "REGLAS CRÍTICAS:\n"
                        "1. **DESPEDIDA = el usuario quiere cerrar la conversación**\n"
                        "   - 'gracias' después de una confirmación de turno → ES despedida\n"
                        "   - 'ok gracias' después de coordinar → ES despedida\n"
                        "   - 'muchas gracias', 'dale gracias', 'perfecto gracias' o 'listo gracias' "
                        "después de que el agente pidió horario o confirmó un turno → ES despedida\n"
                        "   - 'chau', 'adiós', 'hasta luego', 'nos vemos' → ES despedida\n"
                        "   - 'que tengas buen día' → ES despedida\n\n"
                        "2. **NO ES DESPEDIDA si el usuario:**\n"
                        "   - Responde 'ok', 'si', 'dale' a una pregunta del agente (aún espera respuesta)\n"
                        "   - Hace una pregunta nueva\n"
                        "   - Pide más información\n"
                        "   - Propone otro horario\n"
                        "   - Muestra interés en continuar\n\n"
                        "3. **CONTEXTO ES CLAVE:**\n"
                        "   - Si el agente acaba de confirmar un turno y el usuario dice 'gracias' → DESPEDIDA\n"
                        "   - Si el agente acaba de preguntar qué horario le queda mejor y el usuario responde "
                        "solo con un agradecimiento corto → DESPEDIDA, no vuelvas a pedir horario\n"
                        "   - Si el agente preguntó '¿te parece bien?' y el usuario dice 'gracias' → NO es despedida (espera confirmación)\n\n"
                        "Respondé SOLO con una de estas opciones:\n"
                        "- 'SI_CIERRE_CORTO' si es una despedida breve de agradecimiento/cierre.\n"
                        "- 'SI' si es otra despedida.\n"
                        "- 'NO' si no es despedida."
                    )
                },
                {"role": "user", "content": contexto}
            ],
            temperature=0.0,
            max_tokens=8
        )
        register_cost(resp)
        clasificacion = resp.choices[0].message.content.strip().upper()
        resultado = clasificacion.startswith("SI")

        if clasificacion.startswith("SI_CIERRE_CORTO"):
            print(f"   👋 [Despedida regla] Cierre corto detectado: '{mensaje}' | Fase: {fase_actual}")
        print(f"   🤖 [Despedida IA] Mensaje: '{mensaje}' | Fase: {fase_actual} | Clasificación: {clasificacion} | Es despedida: {resultado}")
        return resultado

    except Exception as e:
        print(f"⚠️ [Despedida IA] Error: {e}")
        return _detectar_despedida_simple(mensaje)


def _detectar_despedida_simple(mensaje: str) -> bool:
    mensaje_lower = mensaje.lower().strip()

    despedidas_claras = [
        "chau", "adiós", "adios", "bye", 
        "hasta luego", "hasta pronto", "nos vemos",
        "que tengas buen día", "que tengas buena semana"
    ]

    for despedida in despedidas_claras:
        if despedida in mensaje_lower:
            return True

    if mensaje_lower == "gracias" or mensaje_lower == "muchas gracias":
        return False

    return False

def generar_cierre_despedida_ia(mensaje: str, conv_state: Dict = None, prospecto: Dict = None) -> str:
    """
    Genera un cierre breve y contextual con IA cuando el cliente inicia la despedida.
    No usa plantilla fija: deja que el modelo decida el tono según historial y estado.
    """
    conv_state = conv_state or {}
    prospecto = prospecto or {}
    historial_texto = ""
    for msg in conv_state.get("historial", [])[-8:]:
        role = "Cliente" if msg.get("role") == "user" else "Agente"
        historial_texto += f"{role}: {str(msg.get('content', ''))[:220]}\n"

    try:
        resp = client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el agente de WhatsApp de un complejo de canchas. "
                        "El cliente acaba de cerrar la conversación con una despedida o agradecimiento.\n\n"
                        "Generá una única respuesta final, natural, argentina, cálida y breve. "
                        "No abras temas nuevos, no preguntes por horarios, no fuerces una reserva y no uses plantillas. "
                        "Si ya hay un turno o seña pendiente, podés dejar un cierre amable sin repetir toda la gestión. "
                        "Respondé SOLO el texto que se debe enviar por WhatsApp."
                    )
                },
                {
                    "role": "user",
                    "content": (
                        f"Cliente: {prospecto.get('nombre', 'sin nombre')}\n"
                        f"Fase actual: {conv_state.get('fase', 'inicial')}\n"
                        f"Día propuesto: {conv_state.get('dia_propuesto') or 'ninguno'}\n"
                        f"Hora propuesta: {conv_state.get('hora_propuesta') or 'ninguna'}\n"
                        f"Cancha propuesta: {conv_state.get('cancha_propuesta') or 'ninguna'}\n\n"
                        f"Historial reciente:\n{historial_texto or '(sin historial)'}\n"
                        f"Último mensaje del cliente: \"{mensaje}\""
                    )
                }
            ],
            temperature=0.4,
            max_tokens=90
        )
        register_cost(resp)
        respuesta = resp.choices[0].message.content.strip()
        respuesta = re.sub(r'^["""]+|["""]+$', '', respuesta).strip()
        print(f"   🤖 [Despedida IA] Cierre generado: {respuesta}")
        return respuesta
    except Exception as e:
        print(f"⚠️ [Despedida IA] Error generando cierre: {e}")
        return "Dale, gracias a vos. Que tengas buen día."

