def historial_tiene_despedida_previa(conv_state: Dict) -> bool:
    historial = conv_state.get("historial", [])
    mensajes_agente = [
        msg["content"] for msg in historial
        if msg.get("role") == "assistant"
    ]
    for msg_agente in mensajes_agente:
        if detectar_despedida_ia(msg_agente):
            return True
    return False

