def cliente_tiene_post_turno_followup_enviado(telefono: str, row: Dict[str, Any]) -> bool:
    if not telefono:
        return False
    memoria = cargar_memoria_cliente(telefono)
    key = _post_turno_followup_key(row)
    for item in memoria.get("post_turno_followups_enviados") or []:
        if isinstance(item, dict) and item.get("key") == key and item.get("estado") == "enviado":
            return True
        if isinstance(item, str) and item == key:
            return True
    return False


def registrar_post_turno_followup_memoria(
    telefono: str,
    row: Dict[str, Any],
    propuesta: Dict[str, Any],
    estado: str,
    sent_at: Optional[datetime.datetime] = None,
) -> None:
    if not telefono:
        return
    memoria = cargar_memoria_cliente(telefono)
    key = _post_turno_followup_key(row)
    registros = [item for item in (memoria.get("post_turno_followups_enviados") or []) if not (isinstance(item, dict) and item.get("key") == key)]
    sent = sent_at or datetime.datetime.now(TIMEZONE)
    if sent.tzinfo is None:
        sent = TIMEZONE.localize(sent)
    expires_at = sent + datetime.timedelta(hours=_post_turno_followup_ttl_hours())
    registros.append({
        "key": key,
        "estado": estado,
        "sent_at": sent.isoformat(),
        "expires_at": expires_at.isoformat(),
        "reserva": {
            "fecha": row.get("fecha"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha"),
        },
        "propuesta": propuesta,
    })
    memoria["post_turno_followups_enviados"] = registros[-20:]
    guardar_memoria_cliente(telefono, memoria)


