def obtener_confirmacion_asistencia_pendiente_scheduler(
    telefono: str,
    ahora: Optional[datetime.datetime] = None,
) -> Optional[Dict[str, Any]]:
    """Devuelve el recordatorio real que autoriza interpretar una respuesta."""
    telefono_norm = normalize_phone(telefono or "")
    if not telefono_norm or not os.path.exists(CALENDAR_DB):
        return None
    try:
        now = ahora or datetime.datetime.now(TIMEZONE)
        if now.tzinfo is None:
            now = TIMEZONE.localize(now)
        lower = now - datetime.timedelta(minutes=30)
        upper = now + datetime.timedelta(hours=12)
        candidates = []
        for event in _integrated_scheduler_events():
            event_dt = _parse_iso_datetime(event.get("event_datetime"))
            if (
                normalize_phone(event.get("user_phone") or "") == telefono_norm
                and str(event.get("status") or "active") == "active"
                and int(event.get("attendance_confirmation_sent") or 0) == 1
                and int(event.get("attendance_confirmed") or 0) == 0
                and event_dt
                and lower <= event_dt <= upper
            ):
                candidates.append((event_dt, event))
        return dict(sorted(candidates, key=lambda item: item[0])[0][1]) if candidates else None
    except Exception as e:
        print(f"[ASISTENCIA PENDIENTE] No pude consultar confirmacion: {e}")
        return None


async def detectar_respuesta_asistencia_ia(
    mensaje: str,
    event: Dict[str, Any],
) -> Dict[str, Any]:
    """Clasifica semánticamente una respuesta al recordatorio, sin keywords."""
    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un adjudicador semántico de respuestas a un recordatorio de turno. "
                        "Interpretá el significado completo de CURRENT_MESSAGE dentro de REMINDER_CONTEXT; "
                        "no clasifiques por coincidencia de palabras. "
                        "Elegí exactamente una clase: affirmative si confirma que asistirá; negative si avisa "
                        "que no asistirá o rechaza; ambiguous si no permite saberlo; other si habla de otro tema. "
                        "Una cortesía aislada no confirma salvo que pragmáticamente responda afirmativamente "
                        "a la solicitud de asistencia. Respondé SOLO JSON válido: "
                        "{\"classification\":\"affirmative|negative|ambiguous|other\","
                        "\"reason\":\"breve\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_message": str(mensaje or ""),
                        "reminder_context": {
                            "request": "confirmar asistencia al turno",
                            "event_id": event.get("id"),
                            "event_datetime": event.get("event_datetime"),
                            "court": event.get("court"),
                            "customer": event.get("customer_name"),
                        },
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=120,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        classification = str(data.get("classification") or "").strip().lower()
        if classification not in {"affirmative", "negative", "ambiguous", "other"}:
            classification = "ambiguous"
        result = {
            "classification": classification,
            "reason": str(data.get("reason") or "").strip()[:300],
        }
        print(
            "   🧠 [ASISTENCIA IA] "
            f"classification={classification} reason={result['reason']}"
        )
        return result
    except Exception as e:
        print(f"   ⚠️ [ASISTENCIA IA] no pude adjudicar respuesta: {e}")
        return {"classification": "ambiguous", "reason": f"error: {e}"}


def marcar_confirmacion_asistencia_scheduler(
    telefono: str,
    event_id: int,
) -> bool:
    telefono_norm = normalize_phone(telefono or "")
    if not telefono_norm or not event_id or not os.path.exists(CALENDAR_DB):
        return False
    try:
        conn = sqlite3.connect(CALENDAR_DB)
        cursor = conn.cursor()
        cursor.execute(
            """
            UPDATE events SET attendance_confirmed = 1
            WHERE id = ? AND status = 'active'
            AND attendance_confirmation_sent = 1
            AND attendance_confirmed = 0
            AND user_phone = ?
            """,
            (int(event_id), telefono_norm),
        )
        updated = int(cursor.rowcount or 0)
        conn.commit()
        conn.close()
        if updated != 1:
            return False
        registrar_metrica_operativa(
            "asistencia_ia_confirmada",
            {"telefono": telefono_norm, "event_id": int(event_id)},
        )
        return True
    except Exception as e:
        print(f"[ASISTENCIA IA] No pude marcar confirmacion: {e}")
        return False


def obtener_estado_ok_asistencia(row: Dict[str, Any]) -> str:
    telefono = normalize_phone(row.get("telefono") or "")
    if not telefono:
        return "sin teléfono"
    if not os.path.exists(CALENDAR_DB):
        return "asist. sin confirmar"
    try:
        inicio = _parse_reserva_datetime(row)
        if not inicio:
            return "asist. sin confirmar"
        conn = sqlite3.connect(CALENDAR_DB)
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT attendance_confirmation_sent, attendance_confirmed
            FROM events
            WHERE user_phone = ?
            AND court = ?
            AND datetime(event_datetime) = datetime(?)
            ORDER BY id DESC
            LIMIT 1
            """,
            (telefono, row.get("cancha") or "", inicio.isoformat())
        )
        data = cursor.fetchone()
        conn.close()
        if data and int(data[1] or 0) == 1:
            return "asist. confirmada"
        if data and int(data[0] or 0) == 1:
            return "asist. sin confirmar"
    except Exception:
        pass
    return "asist. sin confirmar"


