def _row_match_admin_no_show(row: Dict[str, Any], comando: Dict[str, Any]) -> bool:
    dia = normalizar_valor_nullable(comando.get("dia"))
    hora = normalizar_hora_detectada(comando.get("hora"))
    telefono = normalize_phone(comando.get("telefono") or "")
    nombre = normalizar_valor_nullable(comando.get("nombre")) or ""
    cancha = normalizar_valor_nullable(comando.get("cancha")) or ""

    if dia and not _reserva_coincide_slot(row, dia, row.get("hora"), None):
        return False
    if hora and normalizar_hora_detectada(row.get("hora")) != hora:
        return False
    if telefono and normalize_phone(row.get("telefono") or "") != telefono:
        return False
    if nombre and str(row.get("nombre") or "").strip().casefold() != nombre.casefold():
        return False
    if cancha and str(row.get("cancha") or "").strip().casefold() != cancha.casefold():
        return False
    return True


def _normalizar_reservation_id_admin(value: Any) -> str:
    text = str(value or "").strip()
    text = re.sub(r"(?i)^\s*(?:reserva|turno)?\s*id\s*[:#-]?\s*", "", text)
    text = text.strip(" #:-")
    if re.fullmatch(r"\d+", text):
        return str(int(text))
    return text


def _row_match_admin_target(row: Dict[str, Any], comando: Dict[str, Any]) -> bool:
    reservation_id = _normalizar_reservation_id_admin(
        (comando or {}).get("reservation_id") or (comando or {}).get("id")
    )
    if reservation_id:
        return _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
    return _row_match_admin_no_show(row, comando)


def _extraer_objetivo_senia_pagada_admin(texto: str) -> str:
    t = str(texto or "").strip()
    t = re.sub(r"(?i)\b(se[ñn?]a|senia|pagad[ao]s?|pago|pag[oó])\b", " ", t)
    t = re.sub(r"(?i)\b(marcar|cobrar|cobr[oó]|confirmar|confirm[oó]|como|en|efectivo|transferencia)\b", " ", t)
    t = re.sub(r"\s+", " ", t).strip(" .,:;-")
    return t


def _extraer_hora_admin_rapida(texto: str) -> str:
    limpio = re.sub(r"\+?\d[\d\s().-]{6,}\d", " ", str(texto or ""))
    limpio = re.sub(r"(?i)\bcancha\s*\d+\b", " ", limpio)
    m = re.search(r"\b(?:a\s+las\s*)?(\d{1,2})(?::(\d{2}))?\s*(?:hs?|horas?)?\b", limpio, re.I)
    if not m:
        return ""
    hora = int(m.group(1))
    minuto = int(m.group(2) or 0)
    if hora < 8:
        hora += 12
    if not (0 <= hora <= 23 and minuto in (0, 30)):
        return ""
    return f"{hora:02d}:{minuto:02d}"


def detectar_senia_pagada_admin(texto: str) -> Optional[Dict[str, Any]]:
    t = str(texto or "").strip()
    tl = t.lower()
    if not re.search(r"\b(se[ñn?]a|senia|pago|pag[oó]|pagada|pagado)\b", tl):
        return None
    if re.search(r"\b(cambiar|configurar|precio|monto)\b", tl):
        return None
    objetivo = extraer_telefono_del_texto(t) or _extraer_objetivo_senia_pagada_admin(t)
    if not objetivo:
        return None
    return {
        "accion": "marcar_senia_pagada",
        "telefono": normalize_phone(objetivo) if normalize_phone(objetivo) else "",
        "nombre": "" if normalize_phone(objetivo) else objetivo,
        "razon": "seña pagada manualmente por admin",
    }


def _expired_cash_hold_rows_by_id(
    rows: List[Dict[str, Any]],
    reservation_id: str,
) -> List[Dict[str, Any]]:
    reservation_id = _normalizar_reservation_id_admin(reservation_id)
    if not reservation_id:
        return []
    return [
        row for row in (rows or [])
        if _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
        and str(row.get("estado") or "").strip().lower() == "hold_expirado"
        and (
            str(row.get("senia_estado") or "").strip().lower() == "pendiente_efectivo"
            or str(row.get("payment_method") or "").strip().lower() == "efectivo"
        )
    ]


def _admin_cash_confirmation_conflict_message(
    reservation_id: str,
    row: Dict[str, Any],
    reason: str,
) -> str:
    reason_text = (
        "el horario original ya pasó"
        if reason == "slot_pasado"
        else "el turno original ya está ocupado o dejó de estar disponible"
    )
    agenda_libre = obtener_resumen_horarios_disponibles("hoy", incluir_cta=False)
    return (
        f"❌ No pude confirmar la reserva ID {reservation_id}: {reason_text}.\n\n"
        f"📅 Turno solicitado: {row.get('fecha') or 'sin fecha'} "
        f"{formatear_hora_para_mensaje(row.get('hora'))} "
        f"{row.get('cancha') or 'sin cancha'}\n\n"
        "🗓️ *HORARIOS LIBRES DE HOY*\n"
        f"{agenda_libre}"
    )


def _total_reserva_para_pago_admin(reserva: Dict[str, Any]) -> Optional[int]:
    """Obtiene el total verificable de una reserva, incluso para filas legacy."""
    reserva = reserva or {}
    total = _monto_a_int(reserva.get("precio_total"))
    if total is not None and total >= 0:
        return total

    duracion = normalizar_duracion_horas(
        reserva.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    total = calcular_precio_total(duracion)
    con_quincho = str(reserva.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1",
    }
    if con_quincho:
        quincho_total = _monto_a_int(reserva.get("quincho_precio_total"))
        if quincho_total is None:
            quincho_total = calcular_precio_quincho_total(
                reserva.get("quincho") or "",
                normalizar_duracion_horas(
                    reserva.get("quincho_duracion_horas")
                    or DEFAULT_TURN_DURATION_HOURS
                ),
            )
        total += quincho_total or 0
    return total


def _reserva_esta_pagada_total(reserva: Dict[str, Any]) -> bool:
    total = _total_reserva_para_pago_admin(reserva)
    pagado = _monto_a_int((reserva or {}).get("senia_monto")) or 0
    saldo_guardado = _monto_a_int((reserva or {}).get("monto_pendiente"))
    if saldo_guardado is not None:
        return saldo_guardado == 0
    return total is not None and pagado >= total


def _restore_expired_cash_hold_for_admin(
    reservation_id: str,
    expired_rows: List[Dict[str, Any]],
    monto: str = "",
    pago_total: bool = False,
) -> Dict[str, Any]:
    """Confirma un hold presencial vencido sólo si todo su bloque sigue libre."""
    reservation_id = _normalizar_reservation_id_admin(reservation_id)
    group = sorted(
        [dict(row) for row in (expired_rows or [])],
        key=lambda row: normalizar_hora_detectada(row.get("hora")) or "",
    )
    if not reservation_id or not group:
        return {"ok": False, "reason": "expired_hold_not_found"}

    primary = group[0]
    target_date = _parse_fecha_row(primary.get("fecha") or "")
    target_hours = {
        normalizar_hora_detectada(row.get("hora"))
        for row in group
        if hora_es_valida(normalizar_hora_detectada(row.get("hora")))
    }
    if not target_hours:
        target_hours = set(slots_para_bloque(
            primary.get("hora"),
            normalizar_duracion_horas(
                primary.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
            ),
        ))
    if not target_date or not target_hours:
        return {"ok": False, "reason": "invalid_expired_hold"}

    first_minutes = min(
        value for value in (_hora_a_minutos_local(hour) for hour in target_hours)
        if value is not None
    )
    first_naive = datetime.datetime.combine(
        target_date,
        datetime.time(first_minutes // 60, first_minutes % 60),
    )
    first_start = TIMEZONE.localize(first_naive)
    if first_start <= datetime.datetime.now(TIMEZONE):
        return {"ok": False, "reason": "slot_pasado", "row": primary}
    if not validar_fecha_en_dias_atencion(primary.get("fecha") or ""):
        return {"ok": False, "reason": "slot_no_disponible", "row": primary}
    if any(not validar_hora_en_franja(hour) for hour in target_hours):
        return {"ok": False, "reason": "slot_no_disponible", "row": primary}

    target_court = str(primary.get("cancha") or "").strip().casefold()
    active_statuses = {
        str(status or "").strip().lower() for status in ACTIVE_BOOKING_STATUSES
    }
    restored = []
    with calendario.atomic():
        current_rows = calendario._leer_todos()
        current_expired = _expired_cash_hold_rows_by_id(
            current_rows,
            reservation_id,
        )
        if not current_expired:
            already_paid = [
                row for row in current_rows
                if _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
                and str(row.get("senia_estado") or "").strip().lower() == "pagada"
                and str(row.get("estado") or "").strip().lower() in active_statuses
            ]
            if already_paid:
                return {"ok": True, "rows": already_paid, "idempotent": True}
            return {"ok": False, "reason": "expired_hold_not_found", "row": primary}

        occupied = []
        for current in current_rows:
            if str(current.get("estado") or "").strip().lower() not in active_statuses:
                continue
            if _normalizar_reservation_id_admin(current.get("reservation_id")) == reservation_id:
                continue
            if _parse_fecha_row(current.get("fecha") or "") != target_date:
                continue
            if str(current.get("cancha") or "").strip().casefold() != target_court:
                continue
            if normalizar_hora_detectada(current.get("hora")) in target_hours:
                occupied.append(dict(current))
        if occupied:
            return {
                "ok": False,
                "reason": "slot_occupied",
                "row": primary,
                "conflicts": occupied,
            }

        con_quincho = str(primary.get("con_quincho") or "").strip().lower() in (
            "si", "sí", "true", "1",
        )
        if con_quincho and not quincho_libre_para_bloque(
            primary.get("fecha") or "",
            primary.get("quincho_hora_inicio") or primary.get("hora") or "",
            normalizar_duracion_horas(
                primary.get("quincho_duracion_horas") or DEFAULT_TURN_DURATION_HOURS
            ),
            primary.get("quincho") or "",
        ):
            return {"ok": False, "reason": "slot_occupied", "row": primary}

        for current in current_rows:
            if not any(current is candidate for candidate in current_expired):
                continue
            current["estado"] = BOOKING_STATUS_RESERVED
            current["senia_estado"] = "pagada"
            current["payment_method"] = "efectivo"
            if monto:
                current["senia_monto"] = monto
            if pago_total:
                current["monto_pendiente"] = "0"
            current["notas"] = (
                str(current.get("notas") or "").strip()
                + (
                    " | hold vencido confirmado con pago total en efectivo por admin"
                    if pago_total
                    else " | hold vencido confirmado en efectivo por admin"
                )
            ).strip(" |")
            restored.append(dict(current))
        if not restored:
            return {"ok": False, "reason": "expired_hold_not_found", "row": primary}
        calendario._escribir_todos(current_rows, ordenar=True)

    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    _discard_stale_hold_expiration_notifications(state, primary)
    state["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
    _json_write(PROACTIVE_STATE_FILE, state)
    telefono = _telefono_reserva_para_mensaje(primary)
    if telefono:
        marcar_hold_expirado_pago_tardio(
            telefono,
            _pending_hold_key(primary),
            "confirmed_cash_by_admin",
        )
    return {"ok": True, "rows": restored, "restored_after_expiry": True}


def marcar_senia_pagada_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    rows = calendario.asegurar_ids_reservas_pendientes()
    pago_total_raw = (comando or {}).get("pago_total")
    pago_total = bool(
        pago_total_raw is True
        or str(pago_total_raw or "").strip().casefold()
        in {"1", "true", "si", "sí", "total"}
    )
    requested_id = _normalizar_reservation_id_admin(
        (comando or {}).get("reservation_id") or (comando or {}).get("id")
    )
    matching_active = [
        row for row in rows
        if _reserva_activa(row) and _row_match_admin_target(row, comando)
    ]
    already_paid = bool(matching_active) and all(
        str(row.get("senia_estado") or "").strip().lower() == "pagada"
        for row in matching_active
    )
    already_paid_total = already_paid and all(
        _reserva_esta_pagada_total(row) for row in matching_active
    )
    if (
        requested_id
        and already_paid
        and (not pago_total or already_paid_total)
    ):
        reserva = sorted(matching_active, key=lambda row: str(row.get("hora") or ""))[0]
        return {
            "ok": True,
            "motivo": "ya_confirmada",
            "reserva": reserva,
            "reservation_id": requested_id,
            "pago_total": already_paid_total,
            "respuesta": (
                f"✅ La reserva ID {requested_id} ya estaba "
                + ("pagada en su totalidad" if already_paid_total else "confirmada")
                + "; no hice cambios duplicados."
            ),
        }

    candidatas = [
        row for row in matching_active
        if reserva_tiene_senia_pendiente(row)
        or str(row.get("senia_estado") or "").strip().lower()
        == "parcial_efectivo_pendiente"
    ]
    if pago_total and matching_active:
        # También permite completar el saldo de una reserva cuya seña ya fue
        # confirmada previamente.
        candidatas = list(matching_active)
    restored_after_expiry = False
    promotion = None
    monto = ""
    if not candidatas:
        expired_group = _expired_cash_hold_rows_by_id(rows, requested_id)
        if requested_id and expired_group:
            reservation_id = requested_id
            reserva = sorted(
                expired_group,
                key=lambda row: normalizar_hora_detectada(row.get("hora")) or "",
            )[0]
            monto_total = _total_reserva_para_pago_admin(reserva)
            monto = (
                _monto_humano(monto_total)
                if pago_total
                else _monto_humano(_senia_guardada_o_configurada(reserva, monto_total))
            )
            promotion = _restore_expired_cash_hold_for_admin(
                reservation_id,
                expired_group,
                monto=monto,
                pago_total=pago_total,
            )
            if not promotion.get("ok"):
                reason = str(promotion.get("reason") or "no_se_pudo_confirmar")
                if reason in {"slot_occupied", "slot_no_disponible", "slot_pasado"}:
                    return {
                        "ok": False,
                        "motivo": reason,
                        "reservation_id": reservation_id,
                        "reserva": reserva,
                        "respuesta": _admin_cash_confirmation_conflict_message(
                            reservation_id,
                            reserva,
                            reason,
                        ),
                    }
                return {
                    "ok": False,
                    "motivo": reason,
                    "respuesta": f"No pude recuperar la reserva vencida ID {reservation_id}.",
                }
            restored_after_expiry = True
            group = promotion.get("rows") or expired_group
        else:
            id_text = f" con ID {requested_id}" if requested_id else ""
            return {
                "ok": False,
                "motivo": "sin_reserva",
                "respuesta": f"No encontré una reserva pendiente{id_text} para confirmar.",
            }

    if not restored_after_expiry:
        groups = {}
        for row in candidatas:
            reservation_id = _agent_v2_reservation_id(row)
            groups.setdefault(reservation_id, []).append(row)
        if len(groups) > 1:
            logical_rows = [
                sorted(group, key=lambda row: str(row.get("hora") or ""))[0]
                for group in groups.values()
            ]
            return {
                "ok": False,
                "motivo": "multiples_reservas",
                "reservas": logical_rows,
                "respuesta": (
                    "Encontré más de una reserva posible. Usá el ID exacto:\n"
                    + format_reservas_admin(logical_rows)
                ),
            }

        reservation_id, group = next(iter(groups.items()))
        reserva = sorted(group, key=lambda row: str(row.get("hora") or ""))[0]
        monto_total = _total_reserva_para_pago_admin(reserva)
        monto = (
            _monto_humano(monto_total)
            if pago_total
            else _monto_humano(_senia_guardada_o_configurada(reserva, monto_total))
        )
        mixed_cash_pending = (
            str(reserva.get("senia_estado") or "").strip().lower()
            == "parcial_efectivo_pendiente"
        )
        transferred_before_cash = _senia_pagada_acumulada(reserva, monto_total)
        cash_deposit_due = (
            _monto_a_int(reserva.get("senia_efectivo_pendiente")) or 0
            if mixed_cash_pending else 0
        )
        paid_after_cash = (
            monto_total
            if pago_total
            else min(
                monto_total,
                transferred_before_cash + cash_deposit_due,
            )
            if mixed_cash_pending
            else _senia_guardada_o_configurada(reserva, monto_total)
        )
        promotion = _promote_paid_hold_to_reserved(
            reserva,
            telefono=reserva.get("telefono") or "",
            nombre=reserva.get("nombre") or "",
            monto=monto,
            payment_method="transferencia+efectivo" if mixed_cash_pending else "efectivo",
            note=(
                "pago total confirmado en efectivo por admin"
                if pago_total
                else "seña confirmada en efectivo por admin"
            ),
            monto_pendiente=(
                0 if pago_total else max(0, monto_total - paid_after_cash)
            ),
            senia_pagada_monto=paid_after_cash,
        )

    if not promotion.get("ok"):
        id_text = f" con ID {requested_id}" if requested_id else ""
        return {
            "ok": False,
            "motivo": promotion.get("reason") or "no_se_pudo_confirmar",
            "respuesta": f"No pude confirmar de forma atómica la reserva{id_text}.",
        }

    reserva_confirmada = dict((promotion.get("rows") or [reserva])[0])
    memoria_key, memoria = _memoria_cliente_por_reserva(reserva_confirmada)
    memoria["senias_pagadas_ok"] = int(memoria.get("senias_pagadas_ok") or 0) + 1
    memoria["estado_actual"] = "senia_pagada"
    guardar_memoria_cliente(memoria_key, memoria)
    telefono_cliente = normalize_phone(reserva_confirmada.get("telefono") or "")
    if telefono_cliente:
        update_conversation_state(
            telefono_cliente,
            fase="coordinacion_confirmada",
            dia_propuesto=reserva_confirmada.get("fecha"),
            hora_propuesta=reserva_confirmada.get("hora"),
            cancha_propuesta=reserva_confirmada.get("cancha"),
            senia_estado="pagada",
            senia_monto=monto,
            senia_pagada_monto=reserva_confirmada.get("senia_pagada_monto") or monto,
            senia_pendiente_monto=0,
            senia_efectivo_pendiente=0,
            monto_pendiente=0 if pago_total else reserva_confirmada.get("monto_pendiente"),
        )
    registrar_metrica_operativa("reserva_confirmada_efectivo_admin", {
        "reservation_id": reservation_id,
        "reserva": reserva_confirmada,
        "slots_confirmados": len(promotion.get("rows") or []),
        "restored_after_expiry": restored_after_expiry,
        "pago_total": pago_total,
        "monto_registrado": monto,
    })
    return {
        "ok": True,
        "motivo": "confirmada_efectivo",
        "reservation_id": reservation_id,
        "reserva": reserva_confirmada,
        "rows": promotion.get("rows") or [],
        "restored_after_expiry": restored_after_expiry,
        "pago_total": pago_total,
        "respuesta": (
            f"✅ *Reserva ID {reservation_id} confirmada en efectivo"
            f"{' - pago total' if pago_total else ''}*\n\n"
            f"👤 *Cliente:* "
            f"{reserva_confirmada.get('nombre') or reserva_confirmada.get('telefono')}\n"
            f"📅 *Día:* {reserva_confirmada.get('fecha')}\n"
            f"{_court_booking_summary_label(reserva_confirmada.get('cancha'), bold_field=True)} de "
            f"{rango_horario_texto(reserva_confirmada.get('hora'), reserva_confirmada.get('duracion_horas') or DEFAULT_TURN_DURATION_HOURS)}"
            + (
                "\n\n♻️ El bloqueo había vencido, pero el turno seguía libre y fue recuperado."
                if restored_after_expiry else ""
            )
        ),
    }


def marcar_reserva_pendiente_pago_presencial(
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    conv_state: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Registra pago presencial sobre una reserva pendiente.

    CASOS:

    A) Ya existe transferencia parcial:
       -> la diferencia de SEÑA queda comprometida en efectivo.
       -> el turno queda FIRME inmediatamente.
       -> NO se espera confirmación del administrador.
       -> NO sigue corriendo el hold de 10 minutos.
       -> el efectivo todavía NO se marca como dinero recibido.

    B) No existe ninguna transferencia:
       -> se conserva el comportamiento de seña completamente
          presencial pendiente.

    CRÍTICO:
       Si la conversación viene inmediatamente de PAYMENT_PARTIAL,
       esa reservation_id tiene prioridad absoluta sobre señales
       legacy de día/hora/cancha.
    """
    prospecto = prospecto or {}
    conv_state = conv_state or {}

    telefono_norm = normalize_phone(
        telefono or ""
    )

    nombre_norm = str(
        prospecto.get("nombre")
        or ""
    ).strip().casefold()

    rows = (
        calendario.asegurar_ids_reservas_pendientes()
    )

    candidates = []

    for row in rows:

        if (
            not _reserva_activa(row)
            or not reserva_tiene_senia_pendiente(
                row
            )
        ):
            continue

        same_owner = bool(
            (
                telefono_norm
                and normalize_phone(
                    row.get("telefono")
                    or ""
                )
                == telefono_norm
            )
            or (
                nombre_norm
                and str(
                    row.get("nombre")
                    or ""
                ).strip().casefold()
                == nombre_norm
            )
        )

        if same_owner:
            candidates.append(
                dict(row)
            )

    # ==========================================================
    # AGRUPAR POR RESERVA LÓGICA
    # ==========================================================

    groups: Dict[
        str,
        List[Dict[str, Any]],
    ] = {}

    for row in candidates:

        reservation_id = (
            _agent_v2_reservation_id(
                row
            )
        )

        if reservation_id:

            groups.setdefault(
                reservation_id,
                [],
            ).append(
                row
            )

    if not groups:

        return {
            "ok": False,
            "motivo": "sin_reserva_pendiente",
            "respuesta": (
                f"Podés acercarte a {BUSINESS_NAME}, "
                f"en {BUSINESS_ADDRESS}, para pagar en efectivo. "
                "No encontré un turno pendiente para asociar el pago, "
                "así que al llegar indicá tu nombre y horario."
            ),
        }

    # ==========================================================
    # CONTINUIDAD DEL ÚLTIMO PAGO PARCIAL
    # ==========================================================

    av2 = (
        conv_state.get("agent_v2")
        or {}
    )

    facts = (
        av2.get("facts")
        or {}
    )

    last_partial = (
        facts.get("last_partial_payment")
        or {}
    )

    last_partial_id = ""

    if isinstance(
        last_partial,
        dict,
    ):
        last_partial_id = str(
            last_partial.get("reservation_id")
            or (
                last_partial.get("reserva")
                or {}
            ).get(
                "reservation_id"
            )
            or ""
        ).strip()

    if (
        last_partial_id
        and last_partial_id in groups
    ):

        group = groups[
            last_partial_id
        ]

        primary = sorted(
            group,
            key=lambda row: str(
                row.get("hora")
                or ""
            ),
        )[0]

        total = _monto_a_int(
            primary.get(
                "precio_total"
            )
        )

        if total is None:

            total = calcular_precio_total(
                primary.get(
                    "duracion_horas"
                )
                or DEFAULT_TURN_DURATION_HOURS
            )

        transferido = (
            _senia_pagada_acumulada(
                primary,
                total,
            )
        )

        faltante = (
            _senia_faltante_para_confirmar(
                primary,
                total,
            )
        )

        if (
            transferido > 0
            and faltante > 0
        ):
            groups = {
                last_partial_id: group
            }

            print(
                "   🔗 [PAYMENT CONTINUATION] "
                f"efectivo continúa reserva "
                f"PAYMENT_PARTIAL ID="
                f"{last_partial_id} "
                f"transferido={transferido} "
                f"faltante={faltante}"
            )

    # ==========================================================
    # FALLBACK CONTEXTUAL
    # ==========================================================
    #
    # Sólo si todavía existen varias reservas posibles.
    # ==========================================================

    if len(groups) > 1:

        target_day = (
            conv_state.get(
                "dia_propuesto"
            )
        )

        target_hour = (
            normalizar_hora_detectada(
                conv_state.get(
                    "hora_propuesta"
                )
            )
        )

        target_court = str(
            conv_state.get(
                "cancha_propuesta"
            )
            or ""
        ).strip().casefold()

        contextual_groups = {}

        for (
            reservation_id,
            group,
        ) in groups.items():

            primary = sorted(
                group,
                key=lambda row: str(
                    row.get("hora")
                    or ""
                ),
            )[0]

            matches_context = bool(
                (
                    not target_day
                    or _misma_fecha_reserva(
                        primary,
                        target_day,
                    )
                )
                and (
                    not hora_es_valida(
                        target_hour
                    )
                    or normalizar_hora_detectada(
                        primary.get("hora")
                    )
                    == target_hour
                )
                and (
                    not target_court
                    or str(
                        primary.get(
                            "cancha"
                        )
                        or ""
                    ).strip().casefold()
                    == target_court
                )
            )

            if matches_context:

                contextual_groups[
                    reservation_id
                ] = group

        if contextual_groups:

            groups = (
                contextual_groups
            )

    # ==========================================================
    # AMBIGÜEDAD REAL
    # ==========================================================

    if len(groups) > 1:

        return {
            "ok": False,
            "motivo": "multiples_reservas",
            "reservas": [
                sorted(
                    group,
                    key=lambda row: str(
                        row.get("hora")
                        or ""
                    ),
                )[0]
                for group in groups.values()
            ],
            "respuesta": (
                "Tenés más de una reserva pendiente. "
                "Decime a cuál querés asociar "
                "el pago en efectivo."
            ),
        }

    # ==========================================================
    # RESERVA OBJETIVO
    # ==========================================================

    (
        reservation_id,
        group,
    ) = next(
        iter(
            groups.items()
        )
    )

    primary = sorted(
        group,
        key=lambda row: str(
            row.get("hora")
            or ""
        ),
    )[0]

    total = _monto_a_int(
        primary.get(
            "precio_total"
        )
    )

    if total is None:

        total = calcular_precio_total(
            primary.get(
                "duracion_horas"
            )
            or DEFAULT_TURN_DURATION_HOURS
        )

    transferido = (
        _senia_pagada_acumulada(
            primary,
            total,
        )
    )

    faltante_senia = (
        _senia_faltante_para_confirmar(
            primary,
            total,
        )
    )

    # ==========================================================
    # CASO A:
    # TRANSFERENCIA PARCIAL + DIFERENCIA EN EFECTIVO
    # ==========================================================

    if (
        transferido > 0
        and faltante_senia > 0
    ):

        with calendario.atomic():

            current_rows = (
                calendario._leer_todos()
            )

            changed = []

            for row in current_rows:

                if (
                    _normalizar_reservation_id_admin(
                        row.get(
                            "reservation_id"
                        )
                    )
                    == reservation_id
                    and _reserva_activa(
                        row
                    )
                    and str(
                        row.get(
                            "senia_estado"
                        )
                        or ""
                    ).strip().casefold()
                    == "parcial"
                ):

                    # El slot queda FIRME.
                    row[
                        "estado"
                    ] = BOOKING_STATUS_RESERVED

                    # El efectivo NO se considera recibido.
                    # Se registra por separado.
                    row[
                        "senia_estado"
                    ] = "parcial_efectivo_pendiente"

                    row[
                        "senia_monto"
                    ] = str(
                        _senia_guardada_o_configurada(
                            row,
                            total,
                        )
                    )

                    row[
                        "senia_pagada_monto"
                    ] = str(
                        transferido
                    )

                    # Ya no falta DECIDIR cómo completar
                    # la seña: el cliente eligió efectivo.
                    row[
                        "senia_pendiente_monto"
                    ] = "0"

                    # Pero este dinero todavía debe cobrarse.
                    row[
                        "senia_efectivo_pendiente"
                    ] = str(
                        faltante_senia
                    )

                    row[
                        "payment_method"
                    ] = "transferencia+efectivo"

                    # Dinero TOTAL todavía no ingresado.
                    row[
                        "monto_pendiente"
                    ] = str(
                        max(
                            0,
                            total
                            - transferido,
                        )
                    )

                    row[
                        "notas"
                    ] = (
                        str(
                            row.get(
                                "notas"
                            )
                            or ""
                        ).strip()
                        + (
                            " | turno firme; "
                            f"${faltante_senia} "
                            "de seña pendientes "
                            "en efectivo"
                        )
                    ).strip(
                        " |"
                    )

                    changed.append(
                        dict(row)
                    )

            if not changed:

                return {
                    "ok": False,
                    "motivo": (
                        "reserva_cambio_de_estado"
                    ),
                    "respuesta": (
                        "El estado del turno cambió antes "
                        "de anotar la diferencia en efectivo."
                    ),
                }

            calendario._escribir_todos(
                current_rows,
                ordenar=True,
            )

        confirmed = sorted(
            changed,
            key=lambda row: str(
                row.get("hora")
                or ""
            ),
        )[0]

        # Ya no es un hold.
        # El turno quedó firme.
        _clear_pending_hold_tracking(
            confirmed
        )

        saldo_total = max(
            0,
            total - transferido,
        )

        registrar_metrica_operativa(
            "senia_parcial_efectivo_turno_firme",
            {
                "reservation_id": (
                    reservation_id
                ),
                "telefono": telefono,
                "monto_transferido": (
                    transferido
                ),
                "efectivo_pendiente": (
                    faltante_senia
                ),
                "saldo_total": (
                    saldo_total
                ),
            },
        )

        print(
            "   ✅ [PAGO MIXTO] "
            f"turno firme ID={reservation_id} "
            f"transferido={transferido} "
            f"seña_efectivo={faltante_senia} "
            f"saldo_total={saldo_total}"
        )

        return {
            "ok": True,
            "motivo": (
                "senia_parcial_efectivo_turno_firme"
            ),
            "reservation_id": (
                reservation_id
            ),
            "reserva": confirmed,
            "rows": changed,
            "booking_confirmed": True,
            "payment_method": (
                "transferencia+efectivo"
            ),
            "senia_estado": (
                "parcial_efectivo_pendiente"
            ),
            "monto_transferido": (
                transferido
            ),
            "monto_efectivo_pendiente": (
                faltante_senia
            ),
            "saldo_total": (
                saldo_total
            ),
            "respuesta": (
                build_turno_firme_pago_mixto_message(
                    confirmed,
                    transferido,
                    faltante_senia,
                    saldo_total,
                )
            ),
        }

    # ==========================================================
    # CASO B:
    # YA HABÍA ELEGIDO SEÑA COMPLETA EN EFECTIVO
    # ==========================================================

    if all(
        str(
            row.get(
                "senia_estado"
            )
            or ""
        ).strip().casefold()
        == "pendiente_efectivo"
        and str(
            row.get(
                "payment_method"
            )
            or ""
        ).strip().casefold()
        == "efectivo"
        for row in group
    ):

        hold_state = _json_read(
            PROACTIVE_STATE_FILE,
            {
                "sent": {}
            },
        )

        if not _pending_hold_started_at_from_state(
            hold_state,
            primary,
        ):
            registrar_inicio_senia_pendiente(
                primary
            )

        return {
            "ok": True,
            "motivo": (
                "pago_presencial_ya_registrado"
            ),
            "reservation_id": (
                reservation_id
            ),
            "reserva": primary,
            "rows": group,
            "payment_method": "efectivo",
            "senia_estado": (
                "pendiente_efectivo"
            ),
            "booking_confirmed": False,
            "respuesta": (
                f"Perfecto. Te esperamos en "
                f"{BUSINESS_NAME}, en "
                f"{BUSINESS_ADDRESS}, para "
                "abonar la seña en efectivo.\n\n"
                f"Tu reserva sigue pendiente "
                f"con ID {reservation_id}; "
                "el administrador la va a confirmar "
                "cuando reciba el pago. "
                "El bloqueo vence a los "
                f"{PENDING_DEPOSIT_HOLD_MINUTES} "
                "minutos desde que pediste el turno.\n\n"
                "¡Nos vemos!"
            ),
        }

    # ==========================================================
    # CASO C:
    # SEÑA COMPLETA EN EFECTIVO, SIN TRANSFERENCIA PREVIA
    # ==========================================================

    with calendario.atomic():

        current_rows = (
            calendario._leer_todos()
        )

        changed = []

        for row in current_rows:

            if (
                _normalizar_reservation_id_admin(
                    row.get(
                        "reservation_id"
                    )
                )
                == reservation_id
                and _reserva_activa(
                    row
                )
                and reserva_tiene_senia_pendiente(
                    row
                )
            ):

                row[
                    "senia_estado"
                ] = "pendiente_efectivo"

                row[
                    "payment_method"
                ] = "efectivo"

                row[
                    "notas"
                ] = (
                    str(
                        row.get(
                            "notas"
                        )
                        or ""
                    ).strip()
                    + (
                        " | cliente informó "
                        "pago presencial"
                    )
                ).strip(
                    " |"
                )

                changed.append(
                    dict(row)
                )

        if not changed:

            return {
                "ok": False,
                "motivo": (
                    "reserva_cambio_de_estado"
                ),
                "respuesta": (
                    "El estado del turno cambió antes "
                    "de registrar el pago presencial."
                ),
            }

        calendario._escribir_todos(
            current_rows,
            ordenar=True,
        )

    primary = sorted(
        changed,
        key=lambda row: str(
            row.get("hora")
            or ""
        ),
    )[0]

    hold_state = _json_read(
        PROACTIVE_STATE_FILE,
        {
            "sent": {}
        },
    )

    if not _pending_hold_started_at_from_state(
        hold_state,
        primary,
    ):
        registrar_inicio_senia_pendiente(
            primary
        )

    return {
        "ok": True,
        "motivo": (
            "pago_presencial_pendiente"
        ),
        "reservation_id": (
            reservation_id
        ),
        "reserva": primary,
        "rows": changed,
        "payment_method": "efectivo",
        "senia_estado": (
            "pendiente_efectivo"
        ),
        "booking_confirmed": False,
        "respuesta": (
            f"Perfecto. Te esperamos en "
            f"{BUSINESS_NAME}, en "
            f"{BUSINESS_ADDRESS}, para "
            "abonar la seña en efectivo.\n\n"
            f"Dejé tu reserva pendiente "
            f"con ID {reservation_id} para que "
            "el administrador la confirme cuando "
            "reciba el pago. El bloqueo vence "
            f"a los {PENDING_DEPOSIT_HOLD_MINUTES} "
            "minutos desde que pediste el turno; "
            "después el ID seguirá disponible, "
            "pero sólo podrá confirmarse si el "
            "horario continúa libre.\n\n"
            "¡Nos vemos!"
        ),
    }


def liberar_senia_pendiente_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    rows = calendario.asegurar_ids_reservas_pendientes()
    candidatas = [
        row for row in rows
        if _reserva_activa(row)
        and reserva_tiene_senia_pendiente(row)
        and _row_match_admin_target(row, comando)
    ]
    if not candidatas:
        return {"ok": False, "respuesta": "No encontré una reserva pendiente de seña con esos datos."}

    groups = {}
    for row in candidatas:
        groups.setdefault(_agent_v2_reservation_id(row), []).append(row)
    if len(groups) > 1:
        options = [
            sorted(group, key=lambda row: str(row.get("hora") or ""))[0]
            for group in groups.values()
        ]
        return {
            "ok": False,
            "respuesta": (
                "Encontré más de una seña pendiente posible. Precisame cuál liberar:\n"
                + format_reservas_admin(options)
            ),
        }

    reservation_id, group = next(iter(groups.items()))
    with calendario.atomic():
        current_rows = calendario._leer_todos()
        released = []
        for row in current_rows:
            if (
                _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
                and _reserva_activa(row)
                and reserva_tiene_senia_pendiente(row)
            ):
                row["estado"] = BOOKING_STATUS_CANCELLED
                row["notas"] = (
                    str(row.get("notas") or "").strip()
                    + " | seña pendiente liberada por admin"
                ).strip(" |")
                released.append(dict(row))
        calendario._escribir_todos(current_rows, ordenar=True)

    reserva = sorted(released or group, key=lambda row: str(row.get("hora") or ""))[0]
    _clear_pending_hold_tracking(reserva)
    registrar_metrica_operativa(
        "senia_pendiente_liberada_admin",
        {"reservation_id": reservation_id, "reservas": released},
    )
    return {
        "ok": True,
        "reservation_id": reservation_id,
        "reserva": reserva,
        "rows": released,
        "respuesta": (
            f"✅ Liberé la reserva pendiente ID {reservation_id} de "
            f"{reserva.get('nombre') or reserva.get('telefono')} "
            f"({reserva.get('fecha')} {reserva.get('hora')} {reserva.get('cancha')})."
        ),
    }


def _calendar_rows_with_universal_ids() -> List[Dict[str, Any]]:
    ensure_all = getattr(calendario, "asegurar_ids_reservas", None)
    if callable(ensure_all):
        return list(ensure_all() or [])
    return list(calendario.asegurar_ids_reservas_pendientes() or [])


def _reservation_rows_by_id(
    reservation_id: Any,
    *,
    include_finished: bool = False,
) -> List[Dict[str, Any]]:
    target_id = _normalizar_reservation_id_admin(reservation_id)
    if not target_id:
        return []
    rows = _calendar_rows_with_universal_ids()
    if include_finished:
        try:
            rows.extend(calendario._leer_terminadas() or [])
        except Exception:
            pass
    return [
        dict(row) for row in rows
        if _normalizar_reservation_id_admin(row.get("reservation_id")) == target_id
    ]


def _reservation_primary_row(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    return dict(sorted(
        rows or [],
        key=lambda row: (
            _parse_fecha_row(row.get("fecha") or "") or datetime.date.max,
            _hora_a_minutos_local(row.get("hora") or "") or 10**9,
        ),
    )[0]) if rows else {}


def build_reservation_id_message(reservation_id: Any) -> str:
    target_id = _normalizar_reservation_id_admin(reservation_id)
    rows = _reservation_rows_by_id(target_id, include_finished=True)
    if not rows:
        return f"No encontré una reserva con ID {target_id or reservation_id}."
    primary = _reservation_primary_row(rows)
    active_rows = [row for row in rows if _reserva_activa(row)]
    status_values = {
        str(row.get("estado") or "").strip().lower() for row in rows
    }
    if active_rows and any(reserva_tiene_senia_pendiente(row) for row in active_rows):
        status = "pendiente de seña"
    elif active_rows:
        status = "confirmada"
    elif "hold_expirado" in status_values:
        status = "hold vencido"
    elif str(BOOKING_STATUS_CANCELLED).strip().lower() in status_values:
        status = "cancelada"
    elif "no_show" in status_values:
        status = "no-show"
    else:
        status = next(iter(status_values), "sin estado")
    duration = normalizar_duracion_horas(
        primary.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    total = _monto_a_int(primary.get("precio_total"))
    deposit = _monto_a_int(primary.get("senia_monto"))
    balance = _monto_a_int(primary.get("monto_pendiente"))
    lines = [
        f"🆔 *RESERVA ID {target_id}*",
        "",
        f"📌 Estado: {status}",
        f"👤 Cliente: {primary.get('nombre') or 'Sin nombre'}",
        f"📱 Teléfono: {primary.get('telefono') or 'No disponible'}",
        f"📅 Día: {primary.get('fecha') or 'No disponible'}",
        (
            f"{_court_booking_summary_label(primary.get('cancha') or 'No disponible')} de "
            f"{rango_horario_texto(primary.get('hora'), duration)}"
        ),
        f"⏱️ Duración: {duration:g} hs",
    ]
    if str(primary.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1"
    }:
        qduration = normalizar_duracion_horas(
            primary.get("quincho_duracion_horas") or 1.0,
            1.0,
        )
        lines.extend([
            "",
            (
                f"🔥 Quincho/parrilla: {primary.get('quincho') or 'Quincho'} de "
                f"{rango_horario_texto(primary.get('quincho_hora_inicio'), qduration)}"
            ),
        ])
    if total is not None:
        lines.extend(["", f"💰 Total: {_fmt_precio(total)}"])
    if deposit is not None:
        deposit_label = (
            "Seña requerida"
            if active_rows and any(reserva_tiene_senia_pendiente(row) for row in active_rows)
            else "Seña registrada"
        )
        lines.append(f"💵 {deposit_label}: {_fmt_precio(deposit)}")
    if balance is not None:
        lines.append(f"💸 Saldo pendiente: {_fmt_precio(balance)}")
    return "\n".join(lines)


def cancelar_reserva_por_id_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    reservation_id = _normalizar_reservation_id_admin(
        (comando or {}).get("reservation_id") or (comando or {}).get("id")
    )
    rows = _reservation_rows_by_id(reservation_id)
    active = [row for row in rows if _reserva_activa(row)]
    if not rows:
        return {"ok": False, "respuesta": f"No encontré una reserva con ID {reservation_id}."}
    if not active:
        return {
            "ok": True,
            "motivo": "ya_cancelada",
            "reserva": _reservation_primary_row(rows),
            "respuesta": f"✅ La reserva ID {reservation_id} ya no estaba activa.",
        }
    reason = re.sub(r"\s+", " ", str((comando or {}).get("motivo") or "").strip())
    with calendario.atomic():
        current_rows = calendario._leer_todos()
        cancelled = []
        for row in current_rows:
            if (
                _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
                and _reserva_activa(row)
            ):
                row["estado"] = BOOKING_STATUS_CANCELLED
                note = "cancelada por admin mediante ID"
                if reason:
                    note += f": {reason[:300]}"
                row["notas"] = (
                    str(row.get("notas") or "").strip() + " | " + note
                ).strip(" |")
                cancelled.append(dict(row))
        calendario._escribir_todos(current_rows, ordenar=True)
    primary = _reservation_primary_row(cancelled or active)
    _clear_pending_hold_tracking(primary)
    registrar_metrica_operativa("reserva_cancelada_admin_por_id", {
        "reservation_id": reservation_id,
        "motivo": reason,
        "slots": len(cancelled),
    })
    return {
        "ok": True,
        "motivo": "cancelada",
        "reservation_id": reservation_id,
        "reserva": primary,
        "rows": cancelled,
        "respuesta": (
            f"✅ *Reserva ID {reservation_id} cancelada.*\n\n"
            f"👤 {primary.get('nombre') or primary.get('telefono')}\n"
            f"📅 {primary.get('fecha')}\n"
            f"⚽ {primary.get('cancha')} a las "
            f"{formatear_hora_para_mensaje(primary.get('hora'))}"
        ),
    }


def liberar_reserva_por_id_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    reservation_id = _normalizar_reservation_id_admin(
        (comando or {}).get("reservation_id") or (comando or {}).get("id")
    )
    rows = _reservation_rows_by_id(reservation_id)
    if not rows:
        return {"ok": False, "respuesta": f"No encontré una reserva con ID {reservation_id}."}
    pending = [
        row for row in rows
        if _reserva_activa(row) and reserva_tiene_senia_pendiente(row)
    ]
    if not pending:
        active = any(_reserva_activa(row) for row in rows)
        return {
            "ok": False,
            "motivo": "reserva_confirmada" if active else "ya_liberada",
            "respuesta": (
                f"La reserva ID {reservation_id} está confirmada. Para cancelarla usá "
                f"`cancelar ID {reservation_id} [motivo]`."
                if active else
                f"La reserva ID {reservation_id} ya estaba liberada o cancelada."
            ),
        }
    return liberar_senia_pendiente_admin({
        "reservation_id": reservation_id,
        "id": reservation_id,
    })


def _quincho_disponible_excluyendo_id(
    reservation_id: str,
    dia: str,
    hora_inicio: str,
    duracion_horas: float,
    quincho: str,
    rows: Optional[List[Dict[str, Any]]] = None,
) -> bool:
    target_date = _parse_fecha_row(dia)
    for row in rows or calendario._leer_todos():
        if not _reserva_activa(row):
            continue
        if _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id:
            continue
        if str(row.get("con_quincho") or "").strip().casefold() not in {
            "si", "sí", "true", "1"
        }:
            continue
        if target_date and _parse_fecha_row(row.get("fecha") or "") != target_date:
            continue
        if normalizar_nombre_quincho(row.get("quincho") or "") != quincho:
            continue
        row_start = normalizar_hora_detectada(
            row.get("quincho_hora_inicio") or row.get("hora")
        )
        row_duration = normalizar_duracion_horas(
            row.get("quincho_duracion_horas") or 1.0,
            1.0,
        )
        if _bloques_horarios_solapan(
            hora_inicio, duracion_horas, row_start, row_duration
        ):
            return False
    return True


def mover_reserva_por_id_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    reservation_id = _normalizar_reservation_id_admin(
        (comando or {}).get("reservation_id") or (comando or {}).get("id")
    )
    target_day = str((comando or {}).get("dia") or "").strip()
    target_hour = normalizar_hora_detectada((comando or {}).get("hora"))
    if not target_day or not target_hour:
        return {
            "ok": False,
            "motivo": "datos_faltantes",
            "respuesta": f"Indicame el nuevo día y hora. Ejemplo: `mover ID {reservation_id} mañana 20`.",
        }
    target_date = _parse_fecha_row(target_day)
    if not target_date:
        return {"ok": False, "respuesta": "No pude interpretar el nuevo día de la reserva."}
    if not validar_fecha_en_dias_atencion(target_date):
        return {"ok": False, "respuesta": "Ese día está fuera de los días de atención configurados."}
    if not hora_es_valida(target_hour) or not validar_hora_en_franja(target_hour):
        return {
            "ok": False,
            "respuesta": f"La hora {target_hour or '(sin hora)'} está fuera del horario de atención.",
        }
    target_naive = datetime.datetime.combine(
        target_date,
        datetime.time.fromisoformat(target_hour),
    )
    target_datetime = TIMEZONE.localize(target_naive)
    if target_datetime <= datetime.datetime.now(TIMEZONE):
        return {"ok": False, "respuesta": "No puedo mover una reserva a un horario que ya pasó."}

    rows = _calendar_rows_with_universal_ids()
    group = [
        row for row in rows
        if _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
        and _reserva_activa(row)
    ]
    if not group:
        return {"ok": False, "respuesta": f"No encontré una reserva activa con ID {reservation_id}."}
    primary = _reservation_primary_row(group)
    court = str(primary.get("cancha") or "").strip()
    old_start = normalizar_hora_detectada(primary.get("hora"))
    duration = normalizar_duracion_horas(
        primary.get("duracion_horas")
        or max(1.0, len(group) * float(TURN_DURATION_MINUTES or 60) / 60.0)
    )
    target_slots = slots_para_bloque(target_hour, duration)
    if not target_slots or any(not validar_hora_en_franja(slot) for slot in target_slots):
        return {"ok": False, "respuesta": "La duración del turno excede el horario de atención en ese nuevo horario."}

    checked_reservations = set()
    conflict_rows = sorted(
        rows,
        key=lambda row: (
            _normalizar_reservation_id_admin(row.get("reservation_id")),
            str(row.get("fecha") or ""),
            str(row.get("cancha") or "").strip().casefold(),
            str(row.get("hora") or ""),
        ),
    )
    for row in conflict_rows:
        if not _reserva_activa(row):
            continue
        row_reservation_id = _normalizar_reservation_id_admin(
            row.get("reservation_id")
        )
        if row_reservation_id == reservation_id:
            continue
        logical_key = row_reservation_id or "|".join([
            str(row.get("telefono") or row.get("nombre") or "").strip().casefold(),
            str(row.get("fecha") or "").strip(),
            str(row.get("cancha") or "").strip().casefold(),
            str(row.get("hora") or "").strip(),
        ])
        if logical_key in checked_reservations:
            continue
        checked_reservations.add(logical_key)
        if _parse_fecha_row(row.get("fecha") or "") != target_date:
            continue
        if str(row.get("cancha") or "").strip().casefold() != court.casefold():
            continue
        row_duration = normalizar_duracion_horas(
            row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        if _bloques_horarios_solapan(
            target_hour, duration, row.get("hora"), row_duration
        ):
            alternative = calendario.proximo_slot_libre(
                target_day, target_hour, cancha=court
            )
            return {
                "ok": False,
                "motivo": "slot_ocupado",
                "alternativa": alternative,
                "respuesta": (
                    f"No pude mover la reserva ID {reservation_id}: {court} está ocupada "
                    f"en ese horario. La alternativa más cercana es {alternative[0]} "
                    f"a las {formatear_hora_para_mensaje(alternative[1])}."
                ),
            }

    with_quincho = str(primary.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1"
    }
    new_qstart = ""
    qduration = 0.0
    qname = ""
    if with_quincho:
        old_start_min = _hora_a_minutos_local(old_start)
        new_start_min = _hora_a_minutos_local(target_hour)
        old_qstart_min = _hora_a_minutos_local(
            primary.get("quincho_hora_inicio") or hora_fin_bloque(old_start, duration)
        )
        if None in {old_start_min, new_start_min, old_qstart_min}:
            return {"ok": False, "respuesta": "No pude validar el horario actual del quincho."}
        new_qstart = _minutos_a_hora(
            new_start_min + (old_qstart_min - old_start_min)
        )
        qduration = normalizar_duracion_horas(
            primary.get("quincho_duracion_horas") or 1.0,
            1.0,
        )
        qname = normalizar_nombre_quincho(primary.get("quincho") or "")
        if (
            not hora_es_valida(new_qstart)
            or _hora_a_minutos_local(new_qstart) + int(round(qduration * 60)) > 24 * 60
            or not _quincho_disponible_excluyendo_id(
                reservation_id,
                target_day,
                new_qstart,
                qduration,
                qname,
                rows,
            )
        ):
            return {
                "ok": False,
                "motivo": "quincho_no_disponible",
                "respuesta": "La cancha está disponible, pero el quincho no está libre en el horario equivalente.",
            }

    target_label = f"{nombre_dia_es(target_date)} {target_date.strftime('%d/%m/%Y')}"
    old_start_min = _hora_a_minutos_local(old_start) or 0
    target_start_min = _hora_a_minutos_local(target_hour) or 0
    with calendario.atomic():
        current_rows = calendario._leer_todos()
        changed = []
        for row in current_rows:
            if (
                _normalizar_reservation_id_admin(row.get("reservation_id")) != reservation_id
                or not _reserva_activa(row)
            ):
                continue
            row_minute = _hora_a_minutos_local(row.get("hora"))
            offset = max(0, (row_minute or old_start_min) - old_start_min)
            row["fecha"] = target_label
            row["hora"] = _minutos_a_hora(target_start_min + offset)
            if with_quincho:
                row["quincho_hora_inicio"] = new_qstart
                row["quincho_hora_fin"] = hora_fin_bloque(new_qstart, qduration)
            row["notas"] = (
                str(row.get("notas") or "").strip()
                + " | reprogramada por admin mediante ID"
            ).strip(" |")
            changed.append(dict(row))
        calendario._escribir_todos(current_rows, ordenar=True)
    updated = _reservation_primary_row(changed)
    _clear_pending_hold_tracking(primary)
    if updated and reserva_tiene_senia_pendiente(updated):
        registrar_inicio_senia_pendiente(updated)
    registrar_metrica_operativa("reserva_movida_admin_por_id", {
        "reservation_id": reservation_id,
        "antes": {"dia": primary.get("fecha"), "hora": old_start, "cancha": court},
        "despues": {"dia": target_label, "hora": target_hour, "cancha": court},
    })
    return {
        "ok": True,
        "reservation_id": reservation_id,
        "reserva": updated,
        "reserva_anterior": primary,
        "rows": changed,
        "respuesta": (
            f"✅ *Reserva ID {reservation_id} reprogramada.*\n\n"
            f"📅 {target_label}\n"
            f"⚽ {court} de {rango_horario_texto(target_hour, duration)}"
            + (
                f"\n🔥 {qname} de {rango_horario_texto(new_qstart, qduration)}"
                if with_quincho else ""
            )
        ),
    }


def agregar_quincho_reserva_por_id_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    reservation_id = _normalizar_reservation_id_admin(
        (comando or {}).get("reservation_id") or (comando or {}).get("id")
    )
    if not CON_QUINCHO or not QUINCHOS:
        return {"ok": False, "respuesta": "El quincho/parrilla está deshabilitado o no está configurado."}
    rows = _calendar_rows_with_universal_ids()
    group = [
        row for row in rows
        if _normalizar_reservation_id_admin(row.get("reservation_id")) == reservation_id
        and _reserva_activa(row)
    ]
    if not group:
        return {"ok": False, "respuesta": f"No encontré una reserva activa con ID {reservation_id}."}
    primary = _reservation_primary_row(group)
    if str(primary.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1"
    }:
        return {
            "ok": True,
            "motivo": "ya_tenia_quincho",
            "reserva": primary,
            "respuesta": f"✅ La reserva ID {reservation_id} ya tenía quincho incluido.",
        }
    qname = normalizar_nombre_quincho((comando or {}).get("quincho") or "")
    qduration = normalizar_duracion_horas(
        (comando or {}).get("quincho_duracion_horas") or 1.0,
        1.0,
    )
    court_duration = normalizar_duracion_horas(
        primary.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    qstart = hora_fin_bloque(primary.get("hora"), court_duration)
    if not hora_es_valida(qstart) or _hora_a_minutos_local(qstart) + int(round(qduration * 60)) > 24 * 60:
        return {"ok": False, "respuesta": "El quincho quedaría fuera del horario operativo después del partido."}
    if not _quincho_disponible_excluyendo_id(
        reservation_id,
        primary.get("fecha") or "",
        qstart,
        qduration,
        qname,
        rows,
    ):
        return {
            "ok": False,
            "motivo": "quincho_ocupado",
            "respuesta": f"{qname} no está disponible de {rango_horario_texto(qstart, qduration)}.",
        }
    court_total = calcular_precio_total(court_duration)
    qtotal = calcular_precio_quincho_total(qname, qduration)
    total = court_total + qtotal
    deposit = (
        _senia_guardada_o_configurada(primary, total)
        if str(primary.get("senia_estado") or "").strip().lower() == "pagada"
        else _senia_para_total(total)
    )
    balance = calcular_monto_pendiente(total, deposit)
    with calendario.atomic():
        current_rows = calendario._leer_todos()
        changed = []
        for row in current_rows:
            if (
                _normalizar_reservation_id_admin(row.get("reservation_id")) != reservation_id
                or not _reserva_activa(row)
            ):
                continue
            row.update({
                "con_quincho": "Si",
                "quincho": qname,
                "quincho_hora_inicio": qstart,
                "quincho_hora_fin": hora_fin_bloque(qstart, qduration),
                "quincho_duracion_horas": str(qduration),
                "quincho_precio_hora": str(precio_hora_quincho(qname)),
                "quincho_precio_total": str(qtotal),
                "precio_total": str(total),
                "monto_pendiente": str(balance),
            })
            row["notas"] = (
                str(row.get("notas") or "").strip()
                + " | quincho agregado por admin mediante ID"
            ).strip(" |")
            changed.append(dict(row))
        calendario._escribir_todos(current_rows, ordenar=True)
    updated = _reservation_primary_row(changed)
    registrar_metrica_operativa("quincho_agregado_admin_por_id", {
        "reservation_id": reservation_id,
        "quincho": qname,
        "hora_inicio": qstart,
        "duracion_horas": qduration,
    })
    return {
        "ok": True,
        "reservation_id": reservation_id,
        "reserva": updated,
        "rows": changed,
        "respuesta": (
            f"✅ *Quincho agregado a la reserva ID {reservation_id}.*\n\n"
            f"🔥 {qname} de {rango_horario_texto(qstart, qduration)}\n"
            f"💰 Nuevo total: {_fmt_precio(total)}\n"
            f"💸 Saldo pendiente: {_fmt_precio(balance)}"
        ),
    }


def _load_waitlist() -> List[Dict[str, Any]]:
    data = _json_read(WAITLIST_FILE, [])
    return data if isinstance(data, list) else []


def _save_waitlist(items: List[Dict[str, Any]]) -> bool:
    return _json_write(WAITLIST_FILE, items)


def detectar_lista_espera_admin(texto: str) -> Optional[Dict[str, Any]]:
    t = str(texto or "").strip()
    tl = t.lower()
    if not re.search(r"\b(lista\s+espera|espera|anot[aá].*espera)\b", tl):
        return None
    dia = resolver_fecha_admin_desde_mensaje(t)
    hora = _extraer_hora_admin_rapida(t)
    cancha = _extraer_cancha_admin_desde_texto(t)
    telefono = extraer_telefono_del_texto(t) or ""
    nombre = t
    nombre = re.sub(r"(?i)\b(lista\s+de\s+espera|lista\s+espera|espera|anotar|anotá|agregar|sumar|para|el|la|a\s+las|cancha\s*\d+)\b", " ", nombre)
    if telefono:
        nombre = nombre.replace(telefono, " ")
    if dia:
        nombre = re.sub(r"(?i)\b(hoy|mañana|pasado mañana|lunes|martes|miercoles|miércoles|jueves|viernes|sabado|sábado|domingo|\d{1,2}/\d{1,2}(?:/\d{2,4})?)\b", " ", nombre)
    nombre = re.sub(r"\b\d{1,2}(?::\d{2})?\s*(?:hs?|horas?)?\b", " ", nombre, flags=re.I)
    nombre = re.sub(r"\s+", " ", nombre).strip(" .,:;-")
    return {
        "accion": "lista_espera",
        "dia": dia or "",
        "hora": hora or "",
        "cancha": cancha or "",
        "telefono": normalize_phone(telefono),
        "nombre": nombre,
        "razon": "lista de espera manual",
    }


def agregar_lista_espera_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    dia = normalizar_valor_nullable(comando.get("dia"))
    hora = normalizar_hora_detectada(comando.get("hora"))
    cancha = normalizar_valor_nullable(comando.get("cancha"))
    nombre = normalizar_valor_nullable(comando.get("nombre"))
    telefono = normalize_phone(comando.get("telefono") or "")
    faltan = []
    if not dia:
        faltan.append("día")
    if not hora_es_valida(hora):
        faltan.append("hora")
    if not cancha:
        faltan.append("cancha")
    if not nombre and not telefono:
        faltan.append("nombre o teléfono")
    if faltan:
        return {"ok": False, "respuesta": "Me faltan datos para lista de espera: " + ", ".join(faltan) + "."}
    items = _load_waitlist()
    item = {
        "id": uuid.uuid4().hex[:10],
        "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "dia": dia,
        "hora": hora,
        "cancha": cancha,
        "nombre": nombre or telefono,
        "telefono": telefono,
        "estado": "activa",
    }
    items.append(item)
    _save_waitlist(items)
    return {"ok": True, "item": item, "respuesta": f"✅ Anoté en lista de espera a {item['nombre']} para {dia} {formatear_hora_para_mensaje(hora)} en {cancha}."}


def agregar_lista_espera_cliente(
    telefono: str,
    prospecto: Dict[str, Any],
    dia: str,
    hora: str,
    cancha: str = "",
) -> Dict[str, Any]:
    """Backend cliente: reutiliza WAITLIST_FILE y evita duplicados activos."""
    dia = normalizar_valor_nullable(dia)
    hora = normalizar_hora_detectada(hora)
    cancha = normalizar_valor_nullable(cancha) or ""
    telefono = normalize_phone(telefono or "")
    nombre = normalizar_valor_nullable((prospecto or {}).get("nombre")) or telefono
    if not dia or not hora_es_valida(hora) or not (telefono or nombre):
        return {"ok": False, "motivo": "datos_incompletos"}

    items = _load_waitlist()
    for item in items:
        if item.get("estado") != "activa":
            continue
        same_client = bool(
            (telefono and normalize_phone(item.get("telefono") or "") == telefono)
            or (nombre and str(item.get("nombre") or "").strip().casefold() == str(nombre).strip().casefold())
        )
        same_slot = bool(
            _misma_fecha_reserva({"fecha": item.get("dia")}, dia)
            and normalizar_hora_detectada(item.get("hora")) == hora
            and str(item.get("cancha") or "").strip().casefold() == str(cancha or "").strip().casefold()
        )
        if same_client and same_slot:
            return {"ok": True, "status": "already_exists", "item": item}

    item = {
        "id": uuid.uuid4().hex[:10],
        "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "dia": dia,
        "hora": hora,
        # Vacío = cualquier cancha para ese día/hora.
        "cancha": cancha,
        "nombre": nombre or telefono,
        "telefono": telefono,
        "estado": "activa",
        "origen": "cliente_agent_v2",
    }
    items.append(item)
    if not _save_waitlist(items):
        return {"ok": False, "motivo": "error_guardando_waitlist"}
    return {"ok": True, "status": "success", "item": item}


def listar_lista_espera_admin(comando: Dict[str, Any] = None) -> str:
    comando = comando or {}
    dia = normalizar_valor_nullable(comando.get("dia"))
    hora = normalizar_hora_detectada(comando.get("hora"))
    items = []
    for item in _load_waitlist():
        if item.get("estado") not in ("activa", "avisado"):
            continue
        if dia and not _misma_fecha_reserva({"fecha": item.get("dia")}, dia):
            continue
        if hora_es_valida(hora) and normalizar_hora_detectada(item.get("hora")) != hora:
            continue
        items.append(item)
    if not items:
        return "📋 Lista de espera vacía para ese filtro."
    lines = ["📋 *LISTA DE ESPERA*"]
    for item in items[:30]:
        estado = "avisado" if item.get("estado") == "avisado" else "activa"
        lines.append(f"• {item.get('dia')} {formatear_hora_para_mensaje(item.get('hora'))} {item.get('cancha')} - {item.get('nombre')} {item.get('telefono') or ''} ({estado})")
    return "\n".join(lines)


def quitar_lista_espera_admin(comando: Dict[str, Any]) -> Dict[str, Any]:
    objetivo = normalizar_valor_nullable(comando.get("nombre")) or normalize_phone(comando.get("telefono") or "")
    if not objetivo:
        return {"ok": False, "respuesta": "Decime a quién saco de lista de espera. Ejemplo: `quitar lista espera Juan`."}
    objetivo_norm = objetivo.casefold()
    tel_obj = normalize_phone(objetivo)
    items = _load_waitlist()
    matches = []
    for idx, item in enumerate(items):
        if item.get("estado") not in ("activa", "avisado"):
            continue
        if (tel_obj and normalize_phone(item.get("telefono") or "") == tel_obj) or str(item.get("nombre") or "").strip().casefold() == objetivo_norm:
            matches.append((idx, item))
    if not matches:
        return {"ok": False, "respuesta": "No encontré a ese cliente en lista de espera."}
    if len(matches) > 1:
        return {"ok": False, "respuesta": "Encontré más de un item. Decime día y hora para sacarlo:\n" + "\n".join(f"• {i.get('dia')} {i.get('hora')} {i.get('cancha')} - {i.get('nombre')}" for _, i in matches[:6])}
    idx, item = matches[0]
    items[idx]["estado"] = "quitado"
    items[idx]["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
    _save_waitlist(items)
    return {"ok": True, "respuesta": f"✅ Saqué de lista de espera a {item.get('nombre')}."}


def waitlist_para_slot(row: Dict[str, Any]) -> List[Dict[str, Any]]:
    dia = row.get("fecha") or ""
    hora = normalizar_hora_detectada(row.get("hora"))
    cancha = str(row.get("cancha") or "").strip().casefold()
    matches = []
    for item in _load_waitlist():
        if item.get("estado") != "activa":
            continue
        item_court = str(item.get("cancha") or "").strip().casefold()
        court_matches = not item_court or item_court == cancha
        if _misma_fecha_reserva({"fecha": item.get("dia")}, dia) and normalizar_hora_detectada(item.get("hora")) == hora and court_matches:
            matches.append(item)
    return matches


async def avisar_waitlist_slot_liberado(page, row: Dict[str, Any]) -> None:
    matches = waitlist_para_slot(row)
    if not matches:
        return
    primero = matches[0]
    telefono_cliente = normalize_phone(primero.get("telefono") or "")
    mensaje_cliente = (
        f"⚽ ¡Se liberó el turno que estabas esperando! "
        f"{row.get('fecha')} a las {formatear_hora_para_mensaje(row.get('hora'))} "
        f"en {row.get('cancha')}. Si todavía te sirve, escribime y lo reservamos."
    )
    enviado = False
    if telefono_cliente:
        aviso_row = {
            "telefono": telefono_cliente,
            "nombre": primero.get("nombre") or "",
            "fecha": row.get("fecha"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha"),
        }
        enviado = await enviar_mensaje_cliente_por_reserva(page, aviso_row, mensaje_cliente)

    texto_admin = (
        f"Lista de espera: se liberó {row.get('fecha')} {formatear_hora_para_mensaje(row.get('hora'))} "
        f"en {row.get('cancha')}. Primer interesado: {primero.get('nombre')} {primero.get('telefono') or ''}. "
        f"Aviso cliente={'enviado' if enviado else 'pendiente'}."
    )
    await enviar_aviso_admin_operativo(page, texto_admin)

    # Solo consumir el turno de waitlist si el cliente efectivamente fue avisado.
    if enviado:
        items = _load_waitlist()
        for item in items:
            if item.get("id") == primero.get("id"):
                item["estado"] = "avisado"
                item["avisado_en"] = datetime.datetime.now(TIMEZONE).isoformat()
                item["slot_liberado"] = {"fecha": row.get("fecha"), "hora": row.get("hora"), "cancha": row.get("cancha")}
                break
        _save_waitlist(items)



def build_clientes_problema_message() -> str:
    memorias = _json_read(CLIENT_MEMORY_FILE, {})
    rows = calendario.listar_reservas()
    pendientes_por_cliente = {}
    for row in rows:
        if _reserva_activa(row) and str(row.get("senia_estado") or "").lower() == "pendiente":
            key = normalize_phone(row.get("telefono") or "") or f"NOMBRE:{row.get('nombre') or ''}"
            pendientes_por_cliente[key] = pendientes_por_cliente.get(key, 0) + 1
    items = []
    for key, mem in memorias.items():
        no_shows = int(mem.get("no_shows") or 0)
        cancel_tarde = int(mem.get("cancelaciones_tarde") or 0)
        turno_fijo = mem.get("turno_fijo") or {}
        pendientes = pendientes_por_cliente.get(key, 0)
        if no_shows or cancel_tarde or pendientes or (turno_fijo.get("activo") and no_shows):
            items.append((no_shows + cancel_tarde + pendientes, key, mem, pendientes))
    if not items:
        return "✅ No hay clientes en observación por ahora."
    items.sort(reverse=True, key=lambda x: x[0])
    lines = ["⚠️ *CLIENTES EN OBSERVACIÓN*"]
    for _, key, mem, pendientes in items[:20]:
        turno_fijo_txt = " | turno fijo" if (mem.get("turno_fijo") or {}).get("activo") else ""
        lines.append(f"• {mem.get('nombre') or key}: {mem.get('no_shows', 0)} no-shows, {mem.get('cancelaciones_tarde', 0)} cancelaciones tarde, {pendientes} señas pendientes{turno_fijo_txt}")
    return "\n".join(lines)


def build_motivos_cancelacion_message(periodo: str = "") -> str:
    memorias = _json_read(CLIENT_MEMORY_FILE, {})
    motivos = []
    desde = datetime.datetime.now(TIMEZONE) - datetime.timedelta(days=7) if periodo == "semana" else None
    for mem in memorias.values():
        nombre = mem.get("nombre") or mem.get("telefono") or mem.get("cliente_id")
        for item in mem.get("motivos_cancelacion") or []:
            registrado = item.get("registrado_en") or ""
            if desde:
                dt = _parse_iso_datetime(registrado)
                if not dt or dt < desde:
                    continue
            motivos.append((registrado, nombre, item.get("motivo") or ""))
    if not motivos:
        return "📉 No hay motivos de cancelación registrados para ese período."
    motivos.sort(reverse=True, key=lambda x: x[0])
    lines = [f"📉 *MOTIVOS DE CANCELACIÓN{(' - últimos 7 días' if periodo == 'semana' else '')}*"]
    for fecha, nombre, motivo in motivos[:20]:
        lines.append(f"• {nombre}: {motivo}")
    return "\n".join(lines)


def build_turnos_fijos_estado_message() -> str:
    memorias = _json_read(CLIENT_MEMORY_FILE, {})
    reservas = [r for r in calendario.listar_reservas() if _reserva_activa(r)]
    lines = ["🔗 *TURNOS FIJOS*"]
    count = 0
    for key, mem in memorias.items():
        tf = mem.get("turno_fijo") or {}
        if not tf or not tf.get("activo"):
            continue
        count += 1
        pendiente = buscar_turno_fijo_pendiente_senia(reservas, mem.get("telefono") or key, mem.get("nombre") or "", tf)
        estado = "seña pendiente" if pendiente else "al día"
        lines.append(
            f"• {mem.get('nombre') or key}: {tf.get('dia_nombre')} {formatear_hora_para_mensaje(tf.get('hora'))} "
            f"{tf.get('cancha')} - {estado} - no-shows {mem.get('no_shows', 0)}"
        )
    if count == 0:
        lines.append("No hay turnos fijos activos.")
    return "\n".join(lines)


def exportar_backup_operativo() -> Dict[str, Any]:
    backup_dir = os.path.abspath("backups_operativos")
    os.makedirs(backup_dir, exist_ok=True)
    stamp = datetime.datetime.now(TIMEZONE).strftime("%Y%m%d_%H%M%S")
    destino = os.path.join(backup_dir, stamp)
    os.makedirs(destino, exist_ok=True)
    archivos = [
        BOOKINGS_CSV,
        FINISHED_BOOKINGS_CSV,
        CLIENT_MEMORY_FILE,
        WAITLIST_FILE,
        PROACTIVE_STATE_FILE,
        HUMAN_CASES_FILE,
        OPERATIONS_METRICS_FILE,
    ]
    copiados = []
    copias = []
    for path in archivos:
        if os.path.exists(path):
            copia_path = os.path.join(destino, os.path.basename(path))
            shutil.copy2(path, copia_path)
            copiados.append(path)
            copias.append(copia_path)
    archivos_csv = [path for path in copias if str(path).lower().endswith(".csv")]
    return {"ok": True, "directorio": destino, "archivos": copiados, "copias": copias, "archivos_csv": archivos_csv}


def marcar_no_show_reserva(comando: Dict[str, Any]) -> Dict[str, Any]:
    if not normalizar_valor_nullable(comando.get("telefono")) and not normalizar_valor_nullable(comando.get("nombre")):
        return {"ok": False, "motivo": "faltan_datos", "respuesta": "Decime quién no vino. Ejemplo: `no vino Juan` o `no vino +549...`."}

    candidatas = []
    rows_activas = calendario._leer_todos()
    for idx, row in enumerate(rows_activas):
        estado = str(row.get("estado") or "").strip().lower()
        if estado in ("cancelado", "cancelada", "no_show", "no show", "no vino"):
            continue
        if _row_match_admin_no_show(row, comando):
            candidatas.append(("activas", idx, row))

    rows_terminadas = calendario._leer_terminadas()
    for idx, row in enumerate(rows_terminadas):
        estado = str(row.get("estado") or "").strip().lower()
        if estado in ("cancelado", "cancelada", "no_show", "no show", "no vino"):
            continue
        if _row_match_admin_no_show(row, comando):
            candidatas.append(("terminadas", idx, row))

    if not candidatas:
        return {"ok": False, "motivo": "sin_reserva", "respuesta": "No encontré una reserva para marcar como no-show con esos datos."}
    if len(candidatas) > 1:
        return {
            "ok": False,
            "motivo": "multiples_reservas",
            "reservas": [row for _, _, row in candidatas],
            "respuesta": "Encontré más de una reserva posible. Precisame cuál marcó no-show:\n" + format_reservas_admin([row for _, _, row in candidatas])
        }

    origen, idx, reserva = candidatas[0]
    if origen == "activas":
        rows_activas[idx]["estado"] = "no_show"
        rows_activas[idx]["notas"] = (str(rows_activas[idx].get("notas") or "").strip() + " | no_show marcado por admin").strip(" |")
        reserva = dict(rows_activas[idx])
        calendario._escribir_todos(rows_activas)
    else:
        rows_terminadas[idx]["estado"] = "no_show"
        rows_terminadas[idx]["notas"] = (str(rows_terminadas[idx].get("notas") or "").strip() + " | no_show marcado por admin").strip(" |")
        reserva = dict(rows_terminadas[idx])
        _write_finished_bookings(rows_terminadas)

    memoria_key, memoria = _memoria_cliente_por_reserva(reserva)
    memoria["no_shows"] = int(memoria.get("no_shows") or 0) + 1
    memoria["estado_actual"] = "no_show"
    guardar_memoria_cliente(memoria_key, memoria)
    registrar_metrica_operativa("no_show_marcado", {
        "cliente_id": memoria_key,
        "reserva": reserva,
        "no_shows": memoria["no_shows"],
        "turno_fijo": bool((memoria.get("turno_fijo") or {}).get("activo")),
    })
    return {"ok": True, "reserva": reserva, "memoria_key": memoria_key, "memoria": memoria}


def build_admin_added_booking_client_message(row: Dict[str, Any]) -> str:
    fecha = str(row.get("fecha") or "").replace("/2026", "")
    hora = str(row.get("hora") or "").strip()
    cancha = str(row.get("cancha") or "").strip()
    partes = [p for p in [fecha, f"a las {formatear_hora_para_mensaje(hora)}" if hora else "", f"en {cancha}" if cancha else ""] if p]
    detalle = " ".join(partes)
    return f"Te aviso que el encargado registró tu turno{f' para {detalle}' if detalle else ''}. Te esperamos en {BUSINESS_NAME}."


def build_admin_cancelled_booking_client_message(row: Dict[str, Any]) -> str:
    fecha = str(row.get("fecha") or "").replace("/2026", "")
    hora = str(row.get("hora") or "").strip()
    cancha = str(row.get("cancha") or "").strip()
    partes = [p for p in [fecha, f"a las {formatear_hora_para_mensaje(hora)}" if hora else "", f"en {cancha}" if cancha else ""] if p]
    detalle = " ".join(partes)
    return (
        f"Te aviso que el encargado canceló tu turno{f' de {detalle}' if detalle else ''}. "
        "Si querés, respondeme y buscamos otro horario."
    )


def build_admin_moved_booking_client_message(row: Dict[str, Any]) -> str:
    duration = normalizar_duracion_horas(
        (row or {}).get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    return (
        "El encargado reprogramó tu turno. Quedó así:\n\n"
        f"📅 {(row or {}).get('fecha') or 'Día no disponible'}\n"
        f"⚽ {(row or {}).get('cancha') or 'Cancha'} de "
        f"{rango_horario_texto((row or {}).get('hora'), duration)}"
        + (
            "\n\nLa seña y el estado de pago se mantuvieron sin cambios."
            if str((row or {}).get("senia_estado") or "").strip().casefold() == "pagada"
            else ""
        )
    )


def build_admin_added_quincho_client_message(row: Dict[str, Any]) -> str:
    qduration = normalizar_duracion_horas(
        (row or {}).get("quincho_duracion_horas") or 1.0,
        1.0,
    )
    total = _monto_a_int((row or {}).get("precio_total")) or 0
    balance = _monto_a_int((row or {}).get("monto_pendiente"))
    return (
        "El encargado agregó el quincho a tu reserva.\n\n"
        f"🔥 {(row or {}).get('quincho') or 'Quincho'} de "
        f"{rango_horario_texto((row or {}).get('quincho_hora_inicio'), qduration)}\n"
        f"💰 Nuevo total: {_fmt_precio(total)}"
        + (f"\n💸 Saldo pendiente: {_fmt_precio(balance)}" if balance is not None else "")
    )


def _misma_fecha_reserva(reserva: Optional[Dict[str, Any]], dia_texto: str) -> bool:
    if not reserva or not dia_texto:
        return False
    fecha_reserva = _parse_fecha_row(reserva.get("fecha"))
    fecha_objetivo = _parse_fecha_row(dia_texto)
    if not fecha_objetivo:
        fecha_objetivo = _parse_fecha_row(resolver_fecha(dia_texto))
    return bool(fecha_reserva and fecha_objetivo and fecha_reserva == fecha_objetivo)


def _misma_reserva_fecha_hora(
    reserva: Optional[Dict[str, Any]],
    dia_texto: str,
    hora_texto: str,
    cancha_texto: Optional[str] = None,
) -> bool:
    if not reserva or not hora_es_valida(hora_texto):
        return False
    hora_reserva = normalizar_hora_detectada(reserva.get("hora"))
    misma_cancha = (
        not cancha_texto
        or str(reserva.get("cancha") or "").strip() == str(cancha_texto or "").strip()
    )
    return (
        _misma_fecha_reserva(reserva, dia_texto)
        and hora_reserva == normalizar_hora_detectada(hora_texto)
        and misma_cancha
    )


def _reserva_activa(row: Dict[str, Any]) -> bool:
    estado = str(row.get("estado") or "").strip().lower()
    return estado not in (
        "cancelado",
        "cancelada",
        "borrado",
        "eliminado",
        "no_show",
        "no show",
        "no vino",
        "hold_expirado",
    )


def _dia_label(fecha: datetime.date) -> str:
    return f"{nombre_dia_es(fecha)} {fecha.strftime('%d/%m')}"


def _slot_count_por_hora(reservas: List[Dict[str, Any]]) -> Dict[str, int]:
    counts = {}
    for row in reservas:
        hora = normalizar_hora_detectada(row.get("hora")) if "normalizar_hora_detectada" in globals() else str(row.get("hora") or "")
        if hora:
            counts[hora] = counts.get(hora, 0) + 1
    return counts


def detectar_reservas_duplicadas(reservas: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    vistas = {}
    duplicadas = []
    for row in reservas:
        if not _reserva_activa(row):
            continue
        key = (
            str(row.get("fecha") or "").strip(),
            str(row.get("hora") or "").strip(),
            str(row.get("cancha") or "").strip(),
        )
        if key in vistas:
            duplicadas.append({"slot": key, "reservas": [vistas[key], row]})
        else:
            vistas[key] = row
    return duplicadas


def obtener_estado_operativo_predio() -> Dict[str, Any]:
    ahora = datetime.datetime.now(TIMEZONE)
    hoy = ahora.date()
    manana = hoy + datetime.timedelta(days=1)
    reservas = calendario.listar_reservas()
    activas = [r for r in reservas if _reserva_activa(r)]
    turnos_hoy = [r for r in activas if _parse_fecha_row(r.get("fecha")) == hoy]
    turnos_manana = [r for r in activas if _parse_fecha_row(r.get("fecha")) == manana]
    proximas_2h = []
    pendientes_senia = []
    clientes_no_pagaron = []
    por_dia = {hoy: turnos_hoy, manana: turnos_manana}

    for row in activas:
        inicio = _parse_reserva_datetime(row)
        senia_estado = str(row.get("senia_estado") or "").strip().lower()
        if senia_estado == "pendiente":
            pendientes_senia.append(row)
            clientes_no_pagaron.append({
                "telefono": row.get("telefono"),
                "nombre": row.get("nombre"),
                "fecha": row.get("fecha"),
                "hora": row.get("hora"),
                "cancha": row.get("cancha")
            })
        if inicio and ahora <= inicio <= ahora + datetime.timedelta(hours=2):
            proximas_2h.append(row)

    libres_por_franja = {}
    for fecha, rows_dia in por_dia.items():
        dia_texto = fecha.strftime("%d/%m/%Y")
        libres_por_franja[_dia_label(fecha)] = obtener_horarios_disponibles_para_dia(dia_texto)

    conversaciones_abandonadas = []
    for tel, state in conversation_states.items():
        fase = state.get("fase")
        ultima = state.get("ultima_actualizacion")
        if isinstance(ultima, datetime.datetime):
            if ultima.tzinfo is None:
                ultima = TIMEZONE.localize(ultima)
            minutos = (ahora - ultima).total_seconds() / 60
            if fase in ("coordinacion_propuesta", "senia_pendiente") and minutos >= PENDING_DEPOSIT_REMINDER_MINUTES:
                conversaciones_abandonadas.append({
                    "telefono": tel,
                    "fase": fase,
                    "minutos_sin_respuesta": int(minutos),
                    "dia": state.get("dia_propuesto"),
                    "hora": state.get("hora_propuesta")
                })

    todas_memorias = _json_read(CLIENT_MEMORY_FILE, {})
    clientes_frecuentes = [
        m for m in todas_memorias.values()
        if m.get("cliente_frecuente") or int(m.get("reservas_previas") or 0) >= 3
    ][:12]

    counts_hora = _slot_count_por_hora(activas)
    horarios_pico = sorted(counts_hora, key=lambda h: counts_hora[h], reverse=True)[:5]
    huecos_pico = []
    for dia_label, canchas in libres_por_franja.items():
        for cancha, horas in (canchas or {}).items():
            for hora in horas:
                if hora in PEAK_HOURS:
                    huecos_pico.append({"dia": dia_label, "hora": hora, "cancha": cancha})

    return {
        "generado_en": ahora.isoformat(),
        "turnos_hoy": turnos_hoy,
        "turnos_manana": turnos_manana,
        "canchas_libres_por_franja": libres_por_franja,
        "turnos_senia_pendiente": pendientes_senia,
        "turnos_proximos_2h": proximas_2h,
        "clientes_reservaron_no_pagaron": clientes_no_pagaron,
        "conversaciones_abandonadas": conversaciones_abandonadas,
        "clientes_frecuentes": clientes_frecuentes,
        "reservas_duplicadas_sospechosas": detectar_reservas_duplicadas(activas),
        "horarios_pico": horarios_pico,
        "huecos_pico_vacios": huecos_pico[:20]
    }


def resumir_estado_operativo_predio(estado: Dict[str, Any]) -> str:
    def fmt_reserva(row):
        return f"{row.get('fecha', '?')} {row.get('hora', '?')} {row.get('cancha', '?')} - {row.get('nombre') or row.get('telefono') or 'cliente'}"

    libres_lineas = []
    for dia, canchas in list((estado.get("canchas_libres_por_franja") or {}).items())[:2]:
        resumen_canchas = []
        for cancha, horas in (canchas or {}).items():
            horas_txt = ", ".join(horas[:8])
            if horas_txt:
                resumen_canchas.append(f"{cancha}: {horas_txt}")
        libres_lineas.append(f"{dia}: " + (" | ".join(resumen_canchas) if resumen_canchas else "sin huecos"))

    return "\n".join([
        "ESTADO OPERATIVO DEL PREDIO:",
        f"- Turnos hoy: {len(estado.get('turnos_hoy') or [])}",
        f"- Turnos manana: {len(estado.get('turnos_manana') or [])}",
        f"- Turnos en menos de 2 horas: {len(estado.get('turnos_proximos_2h') or [])}",
        f"- Senias pendientes: {len(estado.get('turnos_senia_pendiente') or [])}",
        f"- Conversaciones abandonadas: {len(estado.get('conversaciones_abandonadas') or [])}",
        f"- Duplicadas/sospechosas: {len(estado.get('reservas_duplicadas_sospechosas') or [])}",
        f"- Horarios pico historicos/actuales: {', '.join(estado.get('horarios_pico') or []) or 'sin datos'}",
        f"- Huecos pico vacios: {len(estado.get('huecos_pico_vacios') or [])}",
        "- Proximos turnos: " + ("; ".join(fmt_reserva(r) for r in (estado.get("turnos_proximos_2h") or [])[:5]) or "ninguno"),
        "- Disponibilidad resumida: " + (" / ".join(libres_lineas) if libres_lineas else "sin datos"),
    ])


def registrar_metrica_operativa(evento: str, payload: Dict[str, Any] = None) -> None:
    registro = {
        "timestamp": datetime.datetime.now(TIMEZONE).isoformat(),
        "evento": evento,
        "payload": payload or {}
    }
    try:
        with open(OPERATIONS_METRICS_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(registro, ensure_ascii=False) + "\n")
    except Exception as e:
        print(f"[METRICAS] Error guardando evento {evento}: {e}")


def _business_report_normalize_text(value: Any) -> str:
    text = unicodedata.normalize("NFKD", str(value or "").casefold())
    return re.sub(r"\s+", " ", text.encode("ascii", "ignore").decode("ascii")).strip()


def _business_report_month_end(day: datetime.date) -> datetime.date:
    next_month = (
        datetime.date(day.year + 1, 1, 1)
        if day.month == 12
        else datetime.date(day.year, day.month + 1, 1)
    )
    return next_month - datetime.timedelta(days=1)


def _business_report_period_from_text(
    text: str,
    report_type: str = "summary",
    now: Optional[datetime.datetime] = None,
) -> Dict[str, Any]:
    now = now or datetime.datetime.now(TIMEZONE)
    today = now.date()
    normalized = _business_report_normalize_text(text)
    week_start = today - datetime.timedelta(days=today.weekday())

    if re.search(r"\b(?:mes pasado|ultimo mes|mes anterior)\b", normalized):
        current_month_start = today.replace(day=1)
        end = current_month_start - datetime.timedelta(days=1)
        start = end.replace(day=1)
        mode = "previous_month"
    elif re.search(r"\b(?:semana pasada|ultima semana|semana anterior)\b", normalized):
        end = week_start - datetime.timedelta(days=1)
        start = end - datetime.timedelta(days=6)
        mode = "previous_week"
    elif re.search(r"\b(?:mensual|este mes|mes actual|mes)\b", normalized):
        start = today.replace(day=1)
        end = _business_report_month_end(start)
        mode = "month"
    elif re.search(r"\b(?:semanal|esta semana|semana actual|semana)\b", normalized):
        start = week_start
        end = start + datetime.timedelta(days=6)
        mode = "week"
    else:
        explicit = None
        iso_match = re.search(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", normalized)
        numeric_match = re.search(r"\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?\b", normalized)
        named_match = re.search(r"\b(\d{1,2})\s+de\s+([a-z]+)\b", normalized)
        try:
            if iso_match:
                explicit = datetime.date(
                    int(iso_match.group(1)),
                    int(iso_match.group(2)),
                    int(iso_match.group(3)),
                )
            elif numeric_match:
                year = int(numeric_match.group(3) or today.year)
                if year < 100:
                    year += 2000
                explicit = datetime.date(
                    year,
                    int(numeric_match.group(2)),
                    int(numeric_match.group(1)),
                )
            elif named_match and named_match.group(2) in MESES_ES:
                explicit = datetime.date(
                    today.year,
                    MESES_ES[named_match.group(2)],
                    int(named_match.group(1)),
                )
        except ValueError:
            explicit = None

        if explicit is None:
            if re.search(r"\bpasado manana\b", normalized):
                explicit = today + datetime.timedelta(days=2)
            elif re.search(r"\bmanana\b", normalized):
                explicit = today + datetime.timedelta(days=1)
            elif re.search(r"\bhoy\b", normalized):
                explicit = today
            else:
                for day_name, weekday in DIAS_SEMANA.items():
                    ascii_name = _business_report_normalize_text(day_name)
                    if re.search(rf"\b{re.escape(ascii_name)}\b", normalized):
                        explicit = week_start + datetime.timedelta(days=weekday)
                        break

        if explicit:
            start = end = explicit
            mode = "day"
        elif report_type == "summary" and "mensual" in normalized:
            start = today.replace(day=1)
            end = _business_report_month_end(start)
            mode = "month"
        else:
            start = week_start
            end = start + datetime.timedelta(days=6)
            mode = "week"

    if start == end:
        label = f"{nombre_dia_es(start)} {start.strftime('%d/%m/%Y')}"
    elif mode in {"month", "previous_month"}:
        month_name = next(
            (name.capitalize() for name, number in MESES_ES.items() if number == start.month),
            start.strftime("%m"),
        )
        label = f"{month_name} {start.year}"
    else:
        label = f"{start.strftime('%d/%m/%Y')} al {end.strftime('%d/%m/%Y')}"
    return {
        "mode": mode,
        "start_date": start.isoformat(),
        "end_date": end.isoformat(),
        "label": label,
    }


def detectar_reporte_negocio_admin(texto: str) -> Optional[Dict[str, Any]]:
    raw = str(texto or "").strip()
    normalized = _business_report_normalize_text(raw)
    if not normalized:
        return None

    report_type = ""
    if re.search(r"\b(?:ocupacion|ocupadas?|porcentaje de ocupacion)\b", normalized):
        report_type = "occupancy"
    elif re.search(r"\b(?:facturacion|finanzas?|ingresos?|saldo(?:s)? pendiente(?:s)?)\b", normalized):
        report_type = "finance"
    elif re.search(r"\b(?:cancelaciones?|no[ -]?shows?|inasistencias?)\b", normalized):
        report_type = "incidents"
    elif re.search(r"\b(?:conversion|convirtieron|consultas? a reservas?)\b", normalized):
        report_type = "conversion"
    elif (
        re.search(r"\bdemanda\b", normalized)
        or re.search(r"\bhorarios?\b.*\b(?:mayor|menor|mas|menos)\b", normalized)
    ):
        report_type = "demand"
    elif re.search(
        r"\b(?:resumen|reporte|informe)(?:\s+(?:del\s+)?negocio)?\s+(?:semanal|mensual|de la semana|del mes)\b",
        normalized,
    ):
        report_type = "summary"
    elif re.fullmatch(r"(?:reportes?|reportes? del negocio|informe del negocio)", normalized):
        report_type = "summary"
    else:
        return None

    period = _business_report_period_from_text(raw, report_type)
    court = _extraer_cancha_admin_desde_texto(raw)
    hour = ""
    if report_type in {"occupancy", "demand"}:
        hour_match = re.search(
            r"\b(?:hora|horario|a las|las)\s*(\d{1,2})(?::([0-5]\d))?\s*(?:hs?)?\b",
            normalized,
        )
        if not hour_match:
            hour_match = re.search(
                r"\b(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)\s+(\d{1,2})(?::([0-5]\d))?\s*(?:hs?)?\b",
                normalized,
            )
        if hour_match:
            try:
                candidate = f"{int(hour_match.group(1)):02d}:{int(hour_match.group(2) or 0):02d}"
                if validar_hora_en_franja(candidate):
                    hour = candidate
            except (TypeError, ValueError):
                hour = ""

    return {
        "accion": "reporte_negocio",
        "confianza": 1.0,
        "report_type": report_type,
        "period_mode": period["mode"],
        "start_date": period["start_date"],
        "end_date": period["end_date"],
        "period_label": period["label"],
        "cancha": court,
        "hora": hour,
        "datos_faltantes": [],
        "razon": "reporte administrativo determinista",
    }


def _business_report_read_jsonl(path: str) -> List[Dict[str, Any]]:
    records = []
    try:
        if not path or not os.path.exists(path):
            return records
        with open(path, "r", encoding="utf-8-sig") as handle:
            for line in handle:
                try:
                    item = json.loads(line)
                except (TypeError, ValueError, json.JSONDecodeError):
                    continue
                if isinstance(item, dict):
                    records.append(item)
    except OSError as exc:
        print(f"[REPORTES] No pude leer {path}: {exc}")
    return records


def _business_report_datetime(value: Any) -> Optional[datetime.datetime]:
    try:
        parsed = datetime.datetime.fromisoformat(str(value or "").replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        return TIMEZONE.localize(parsed)
    return parsed.astimezone(TIMEZONE)


def _business_report_is_real_booking(row: Dict[str, Any]) -> bool:
    phone = str(row.get("telefono") or "").strip()
    name = str(row.get("nombre") or "").strip().casefold()
    return bool(
        str(row.get("cancha") or "").strip()
        and not phone.startswith("ADMIN:CERRADO")
        and name != "cerrado"
        and (phone or name)
    )


def _business_report_booking_status(row: Dict[str, Any]) -> str:
    state = _business_report_normalize_text(row.get("estado"))
    deposit = _business_report_normalize_text(row.get("senia_estado"))
    if state in {"cancelado", "cancelada", "borrado", "eliminado"}:
        return "cancelled"
    if state in {"no show", "no_show", "no vino"}:
        return "no_show"
    if state == "hold expirado" or state == "hold_expirado":
        return "expired"
    if state == "pendiente" or deposit in {"pendiente", "pendiente efectivo", "pendiente_efectivo"}:
        return "pending"
    return "confirmed"


def _business_report_rows() -> List[Dict[str, Any]]:
    rows = []
    try:
        rows.extend(_calendar_rows_with_universal_ids())
    except Exception as exc:
        print(f"[REPORTES] No pude leer reservas activas: {exc}")
    try:
        rows.extend(calendario._leer_terminadas() or [])
    except Exception as exc:
        print(f"[REPORTES] No pude leer reservas terminadas: {exc}")

    unique = []
    fingerprints = set()
    for row in rows:
        clean = dict(row or {})
        if not _business_report_is_real_booking(clean):
            continue
        fingerprint = "|".join([
            str(clean.get("reservation_id") or "").strip(),
            str(clean.get("fecha") or "").strip(),
            str(clean.get("hora") or "").strip(),
            str(clean.get("cancha") or "").strip().casefold(),
            str(clean.get("telefono") or clean.get("nombre") or "").strip().casefold(),
            str(clean.get("estado") or "").strip().casefold(),
        ])
        if fingerprint in fingerprints:
            continue
        fingerprints.add(fingerprint)
        unique.append(clean)
    return unique


def _business_report_logical_bookings() -> List[Dict[str, Any]]:
    rows = _business_report_rows()
    groups = []
    by_id = {}
    legacy_buckets = {}
    for row in rows:
        reservation_id = _normalizar_reservation_id_admin(row.get("reservation_id"))
        if reservation_id:
            by_id.setdefault(reservation_id, []).append(row)
            continue
        duration = normalizar_duracion_horas(
            row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        key = (
            normalize_phone(row.get("telefono") or "")
            or str(row.get("nombre") or "").strip().casefold(),
            str(row.get("fecha") or "").strip(),
            str(row.get("cancha") or "").strip().casefold(),
            duration,
            _business_report_booking_status(row),
            _monto_a_int(row.get("precio_total")),
        )
        legacy_buckets.setdefault(key, []).append(row)

    for reservation_id, grouped_rows in by_id.items():
        groups.append({"reservation_id": reservation_id, "rows": grouped_rows})

    slot_minutes = max(1, int(TURN_DURATION_MINUTES or 60))
    for bucket_index, bucket_rows in enumerate(legacy_buckets.values(), start=1):
        pending = sorted(
            bucket_rows,
            key=lambda item: _hora_a_minutos_local(item.get("hora"))
            if _hora_a_minutos_local(item.get("hora")) is not None
            else 10**9,
        )
        while pending:
            primary = pending.pop(0)
            start_minute = _hora_a_minutos_local(primary.get("hora"))
            duration = normalizar_duracion_horas(
                primary.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
            )
            expected_count = max(1, int(round(duration * 60 / slot_minutes)))
            expected = {
                (start_minute + offset * slot_minutes)
                for offset in range(expected_count)
            } if start_minute is not None else set()
            grouped_rows = [primary]
            remaining = []
            for candidate in pending:
                candidate_minute = _hora_a_minutos_local(candidate.get("hora"))
                if candidate_minute in expected:
                    grouped_rows.append(candidate)
                else:
                    remaining.append(candidate)
            pending = remaining
            groups.append({
                "reservation_id": f"legacy-{bucket_index}-{len(groups) + 1}",
                "rows": grouped_rows,
            })

    logical = []
    for group in groups:
        primary = _reservation_primary_row(group.get("rows") or [])
        if not primary:
            continue
        duration = normalizar_duracion_horas(
            primary.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        logical.append({
            **group,
            "primary": primary,
            "date": _parse_fecha_row(primary.get("fecha") or ""),
            "hour": normalizar_hora_detectada(primary.get("hora")),
            "court": str(primary.get("cancha") or "Sin cancha").strip(),
            "duration": duration,
            "status": _business_report_booking_status(primary),
        })
    return logical


def _business_report_booking_slots(booking: Dict[str, Any]) -> List[str]:
    start = _hora_a_minutos_local(booking.get("hour"))
    if start is None:
        return []
    step = max(1, int(TURN_DURATION_MINUTES or 60))
    count = max(1, int(round(float(booking.get("duration") or 1.0) * 60 / step)))
    return [
        _minutos_a_hora(start + offset * step)
        for offset in range(count)
        if start + offset * step < 24 * 60
    ]


def _business_report_operating_hours() -> List[str]:
    step = max(1, int(TURN_DURATION_MINUTES or 60))
    hours = set()
    for start, end in obtener_franjas_atencion_minutos():
        current = start
        while current + step <= end:
            hours.add(_minutos_a_hora(current))
            current += step
    return sorted(hours)


def _business_report_context(command: Dict[str, Any]) -> Dict[str, Any]:
    today = datetime.datetime.now(TIMEZONE).date()
    try:
        start = datetime.date.fromisoformat(str(command.get("start_date") or ""))
        end = datetime.date.fromisoformat(str(command.get("end_date") or ""))
    except ValueError:
        start = today - datetime.timedelta(days=today.weekday())
        end = start + datetime.timedelta(days=6)
    if end < start:
        start, end = end, start
    court_filter = str(command.get("cancha") or "").strip()
    hour_filter = normalizar_hora_detectada(command.get("hora"))
    bookings = [
        item for item in _business_report_logical_bookings()
        if item.get("date")
        and start <= item["date"] <= end
        and (
            not court_filter
            or item.get("court", "").casefold() == court_filter.casefold()
        )
        and (
            not hour_filter
            or hour_filter in _business_report_booking_slots(item)
        )
    ]
    dates = [
        start + datetime.timedelta(days=offset)
        for offset in range((end - start).days + 1)
        if (start + datetime.timedelta(days=offset)).weekday() in set(ATTENTION_DAYS or [])
    ]
    configured_courts = [
        str(item.get("name") or "").strip()
        for item in COURTS or []
        if str(item.get("name") or "").strip()
    ]
    observed_courts = sorted({item.get("court") for item in bookings if item.get("court")})
    courts = [court_filter] if court_filter else list(dict.fromkeys(configured_courts + observed_courts))
    hours = _business_report_operating_hours()
    if hour_filter:
        hours = [hour_filter] if hour_filter in hours else []
    return {
        "start": start,
        "end": end,
        "label": command.get("period_label") or f"{start:%d/%m/%Y} al {end:%d/%m/%Y}",
        "court_filter": court_filter,
        "hour_filter": hour_filter,
        "bookings": bookings,
        "dates": dates,
        "courts": courts,
        "hours": hours,
    }


def _business_report_stats(command: Dict[str, Any]) -> Dict[str, Any]:
    context = _business_report_context(command)
    capacity = {
        (day, court, hour)
        for day in context["dates"]
        for court in context["courts"]
        for hour in context["hours"]
    }
    occupied = set()
    pending = set()
    demand_counts = {}
    demand_day = {}
    demand_court = {}
    reservations_by_status = {
        "confirmed": 0,
        "pending": 0,
        "cancelled": 0,
        "no_show": 0,
        "expired": 0,
    }
    finance = {
        "billed": 0,
        "collected": 0,
        "balance": 0,
        "pending_value": 0,
        "cancelled_value": 0,
        "unverified_count": 0,
        "unverified_value": 0,
        "by_court": {},
    }

    for booking in context["bookings"]:
        status = booking.get("status") or "confirmed"
        reservations_by_status[status] = reservations_by_status.get(status, 0) + 1
        primary = booking.get("primary") or {}
        slots = _business_report_booking_slots(booking)
        for hour in slots:
            key = (booking.get("date"), booking.get("court"), hour)
            if status in {"confirmed", "no_show"}:
                occupied.add(key)
            elif status == "pending":
                pending.add(key)
            demand_counts[hour] = demand_counts.get(hour, 0) + 1
            weekday = int(booking["date"].weekday())
            demand_day[weekday] = demand_day.get(weekday, 0) + 1
            court = booking.get("court") or "Sin cancha"
            demand_court[court] = demand_court.get(court, 0) + 1

        total = _monto_a_int(primary.get("precio_total"))
        if total is None:
            total = calcular_precio_total(booking.get("duration") or 1.0)
            total += _monto_a_int(primary.get("quincho_precio_total")) or 0
        deposit = _monto_a_int(primary.get("senia_monto")) or 0
        balance_raw = _monto_a_int(primary.get("monto_pendiente"))
        deposit_paid = _business_report_normalize_text(
            primary.get("senia_estado")
        ) == "pagada"
        court_finance = finance["by_court"].setdefault(
            booking.get("court") or "Sin cancha",
            {"billed": 0, "collected": 0, "balance": 0},
        )
        payment_verified = bool(deposit_paid or not REQUIRES_DEPOSIT)
        if status in {"confirmed", "no_show"} and payment_verified:
            balance = (
                max(0, balance_raw)
                if balance_raw is not None
                else max(0, total - deposit) if deposit_paid
                else total
            )
            collected = max(0, total - balance) if deposit_paid else 0
            finance["billed"] += total
            finance["collected"] += collected
            finance["balance"] += balance
            court_finance["billed"] += total
            court_finance["collected"] += collected
            court_finance["balance"] += balance
        elif status in {"confirmed", "no_show"}:
            finance["unverified_count"] += 1
            finance["unverified_value"] += total
        elif status == "pending":
            finance["pending_value"] += total
        elif status == "cancelled":
            finance["cancelled_value"] += total

    occupied &= capacity
    pending &= capacity
    context.update({
        "capacity": capacity,
        "occupied": occupied,
        "pending_slots": pending,
        "demand_counts": demand_counts,
        "demand_day": demand_day,
        "demand_court": demand_court,
        "reservations_by_status": reservations_by_status,
        "finance": finance,
    })
    return context


def _business_report_percent(value: int, total: int) -> str:
    return f"{(100.0 * value / total):.1f}%" if total else "0.0%"


def _business_report_filter_line(stats: Dict[str, Any]) -> str:
    filters = []
    if stats.get("court_filter"):
        filters.append(str(stats["court_filter"]))
    if stats.get("hour_filter"):
        filters.append(str(stats["hour_filter"]))
    return f"🔎 Filtro: {' - '.join(filters)}" if filters else ""


def _agent_v2_payment_financial_facts_from_observation(
    observation: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """
    Extrae exclusivamente importes VERIFICADOS de la Observation actual
    de registrar_senia / registrar_pago_presencial.

    PRINCIPIO:
        PYTHON OWNS MONEY.

    Esta función:
    - NO lee historial.
    - NO usa memoria vieja.
    - NO calcula intención.
    - NO inventa importes.
    - NO toma precios de conversaciones anteriores.
    - NO autoriza importes provenientes del LLM.

    Solamente proyecta los importes que la tool de pago acaba de
    verificar/producir en este mismo turno.
    """
    obs = observation or {}

    if (
        not isinstance(obs, dict)
        or not obs.get("ok")
    ):
        return []

    tool = str(
        obs.get("tool")
        or ""
    ).strip()

    if tool not in {
        "registrar_senia",
        "registrar_pago_presencial",
        "registrar_pago_inscripcion_evento",
        "registrar_saldo_efectivo_inscripcion_evento",
    }:
        return []

    if (
        str(
            obs.get("status")
            or ""
        ).strip()
        != "success"
    ):
        return []

    data = obs.get("data") or {}

    if not isinstance(
        data,
        dict,
    ):
        return []

    source = str(
        obs.get("observation_id")
        or tool
    )

    facts: List[Dict[str, Any]] = []

    seen = set()

    def add(
        field: str,
        value: Any,
    ) -> None:
        amount = _agent_v2_parse_money_value(
            value
        )

        if amount is None:
            return

        key = (
            str(field),
            str(amount),
            source,
        )

        if key in seen:
            return

        seen.add(
            key
        )

        facts.append({
            "field": str(field),
            "value": str(amount),
            "source": source,
        })

    # ==========================================================
    # TRANSFERENCIA / COMPROBANTE
    # ==========================================================

    if tool == "registrar_senia":

        # Todos estos valores ya salieron de la tool
        # confirmar_senia_reserva_pendiente().
        #
        # Son hechos financieros del TURNO ACTUAL.
        for field in (
            "monto",
            "monto_comprobante",
            "monto_requerido",
            "monto_pagado_acumulado",
            "monto_faltante",
            "saldo_total",
        ):
            add(
                field,
                data.get(field),
            )

        # La reserva devuelta por la misma operación también
        # representa el estado financiero persistido posterior
        # al pago.
        reserva = (
            data.get("reserva")
            or {}
        )

        if isinstance(
            reserva,
            dict,
        ):
            for field in (
                "precio_total",
                "senia_monto",
                "senia_pagada_monto",
                "senia_pendiente_monto",
                "monto_pendiente",
            ):
                add(
                    f"reserva.{field}",
                    reserva.get(field),
                )

    # ==========================================================
    # PAGO MIXTO / EFECTIVO
    # ==========================================================

    elif tool == "registrar_pago_presencial":

        for field in (
            "monto_transferido",
            "monto_efectivo_pendiente",
            "saldo_total",
        ):
            add(
                field,
                data.get(field),
            )

        reserva = (
            data.get("reserva")
            or {}
        )

        if isinstance(
            reserva,
            dict,
        ):
            for field in (
                "precio_total",
                "senia_monto",
                "senia_pagada_monto",
                "senia_pendiente_monto",
                "senia_efectivo_pendiente",
                "monto_pendiente",
            ):
                add(
                    f"reserva.{field}",
                    reserva.get(field),
                )

    # ==========================================================
    # EVENT REGISTRATION PAYMENT
    # ==========================================================
    elif tool in {
        "registrar_pago_inscripcion_evento",
        "registrar_saldo_efectivo_inscripcion_evento",
    }:

        # Todos estos importes son producidos por la tool transaccional
        # del Event Registration Engine en ESTE turno. Nunca salen del LLM.
        for field in (
            "payment_received",
            "required_payment",
            "paid_amount",
            "remaining_amount",
            "registration_price",
            "cash_pending_amount",
        ):
            add(field, data.get(field))

        registration = data.get("registration") or {}
        if isinstance(registration, dict):
            for field in (
                "registration_price",
                "required_payment",
                "paid_amount",
                "remaining_amount",
            ):
                add(
                    f"registration.{field}",
                    registration.get(field),
                )

        receipt = data.get("receipt") or {}
        if isinstance(receipt, dict):
            add("receipt.monto_detectado", receipt.get("monto_detectado"))

    return facts


def build_business_occupancy_report(command: Dict[str, Any]) -> str:
    stats = _business_report_stats(command)
    capacity = stats["capacity"]
    occupied = stats["occupied"]
    lines = [
        "📊 *REPORTE DE OCUPACIÓN*",
        f"📅 Período: {stats['label']}",
    ]
    filter_line = _business_report_filter_line(stats)
    if filter_line:
        lines.append(filter_line)
    lines.extend([
        "",
        f"🏟️ Slots tomados: *{len(occupied)} de {len(capacity)}*",
        f"📈 Ocupación: *{_business_report_percent(len(occupied), len(capacity))}*",
        f"⏳ Holds pendientes: {len(stats['pending_slots'])} slots",
        f"📋 Reservas confirmadas/no-show: "
        f"{stats['reservations_by_status'].get('confirmed', 0) + stats['reservations_by_status'].get('no_show', 0)}",
        "",
        "*Por cancha*",
    ])
    for court in stats["courts"]:
        court_capacity = {key for key in capacity if key[1] == court}
        court_occupied = {key for key in occupied if key[1] == court}
        lines.append(
            f"• {court}: {len(court_occupied)}/{len(court_capacity)} "
            f"({_business_report_percent(len(court_occupied), len(court_capacity))})"
        )

    lines.extend(["", "*Por día de la semana*"])
    for weekday in range(7):
        day_capacity = {key for key in capacity if key[0].weekday() == weekday}
        if not day_capacity:
            continue
        day_occupied = {key for key in occupied if key[0].weekday() == weekday}
        lines.append(
            f"• {NOMBRES_DIAS[weekday]}: {len(day_occupied)}/{len(day_capacity)} "
            f"({_business_report_percent(len(day_occupied), len(day_capacity))})"
        )

    lines.extend(["", "*Por horario*"])
    hour_parts = []
    for hour in stats["hours"]:
        hour_capacity = {key for key in capacity if key[2] == hour}
        hour_occupied = {key for key in occupied if key[2] == hour}
        hour_parts.append(
            f"{hour} {len(hour_occupied)}/{len(hour_capacity)} "
            f"({_business_report_percent(len(hour_occupied), len(hour_capacity))})"
        )
    for offset in range(0, len(hour_parts), 3):
        lines.append(" • ".join(hour_parts[offset:offset + 3]))
    lines.extend(["", "Fuente: calendario real y horario configurado."])
    return "\n".join(lines)


def build_business_finance_report(command: Dict[str, Any]) -> str:
    stats = _business_report_stats(command)
    finance = stats["finance"]
    statuses = stats["reservations_by_status"]
    lines = [
        "💰 *REPORTE DE FACTURACIÓN*",
        f"📅 Período de los turnos: {stats['label']}",
        "",
        f"🧾 Total de reservas firmes: *{_fmt_precio(finance['billed'])}*",
        f"✅ Cobrado registrado: *{_fmt_precio(finance['collected'])}*",
        f"💸 Saldo de reservas firmes por cobrar: *{_fmt_precio(finance['balance'])}*",
        f"⏳ Holds esperando seña: {statuses.get('pending', 0)} (no facturados)",
        f"⚠️ Reservas sin pago verificable: {finance['unverified_count']} (fuera del cálculo)",
        f"🚫 Turnos cancelados: {_fmt_precio(finance['cancelled_value'])} no facturados",
        "",
        "*Por cancha*",
    ]
    if not finance["by_court"]:
        lines.append("Sin reservas con importes registrados en este período.")
    for court, values in sorted(finance["by_court"].items()):
        lines.append(
            f"• {court}: facturado {_fmt_precio(values['billed'])} | "
            f"cobrado {_fmt_precio(values['collected'])} | "
            f"saldo firme por cobrar {_fmt_precio(values['balance'])}"
        )
    lines.extend([
        "",
        "Sólo las reservas con seña o pago verificado generan facturación y saldo por cobrar. Los holds pendientes quedan completamente fuera del cálculo.",
    ])
    return "\n".join(lines)


def _business_report_cancel_reason(primary: Dict[str, Any]) -> str:
    notes = re.sub(r"\s+", " ", str(primary.get("notas") or "").strip())
    match = re.search(r"cancelad[ao][^:|]*(?::\s*([^|]+))?", notes, re.I)
    if match and match.group(1):
        return match.group(1).strip()[:100]
    return "sin motivo registrado"


def build_business_incidents_report(command: Dict[str, Any]) -> str:
    stats = _business_report_stats(command)
    bookings = stats["bookings"]
    cancelled = [item for item in bookings if item.get("status") == "cancelled"]
    no_shows = [item for item in bookings if item.get("status") == "no_show"]
    base = len([item for item in bookings if item.get("status") != "expired"])
    incidents = len(cancelled) + len(no_shows)
    reason_counts = {}
    for item in cancelled:
        reason = _business_report_cancel_reason(item.get("primary") or {})
        reason_counts[reason] = reason_counts.get(reason, 0) + 1
    lines = [
        "⚠️ *CANCELACIONES Y NO-SHOWS*",
        f"📅 Período de los turnos: {stats['label']}",
        "",
        f"🚫 Cancelaciones: *{len(cancelled)}*",
        f"👤 No-shows: *{len(no_shows)}*",
        f"📉 Incidencia: *{_business_report_percent(incidents, base)}* "
        f"({incidents}/{base} reservas registradas)",
        "",
        "*Motivos de cancelación*",
    ]
    if reason_counts:
        for reason, count in sorted(reason_counts.items(), key=lambda item: (-item[1], item[0]))[:6]:
            lines.append(f"• {reason}: {count}")
    else:
        lines.append("Sin cancelaciones en el período.")
    details = sorted(
        cancelled + no_shows,
        key=lambda item: (item.get("date") or datetime.date.min, item.get("hour") or ""),
        reverse=True,
    )[:8]
    if details:
        lines.extend(["", "*Detalle reciente*"])
        for item in details:
            primary = item.get("primary") or {}
            label = "cancelación" if item.get("status") == "cancelled" else "no-show"
            lines.append(
                f"• {primary.get('fecha')} {primary.get('hora')} {item.get('court')} - "
                f"{primary.get('nombre') or primary.get('telefono') or 'cliente'} ({label})"
            )
    return "\n".join(lines)


def _business_report_conversion_stats(command: Dict[str, Any]) -> Dict[str, Any]:
    stats = _business_report_context(command)
    start_dt = TIMEZONE.localize(datetime.datetime.combine(stats["start"], datetime.time.min))
    end_dt = TIMEZONE.localize(datetime.datetime.combine(stats["end"], datetime.time.max))
    consulted = set()
    started = set()
    confirmed = set()
    turn_count = 0
    for record in _business_report_read_jsonl(OPERATIONS_METRICS_FILE):
        timestamp = _business_report_datetime(record.get("timestamp"))
        if not timestamp or not (start_dt <= timestamp <= end_dt):
            continue
        event = str(record.get("evento") or "").strip()
        payload = record.get("payload") if isinstance(record.get("payload"), dict) else {}
        nested = payload.get("reserva") if isinstance(payload.get("reserva"), dict) else {}
        phone = normalize_phone(payload.get("telefono") or nested.get("telefono") or "")
        if event == "agent_v2_turn" and phone:
            consulted.add(phone)
            turn_count += 1
        if event in {"reserva_confirmada", "reserva_confirmada_efectivo_admin"} and phone:
            started.add(phone)
            if event == "reserva_confirmada_efectivo_admin" or payload.get("senia_pagada"):
                confirmed.add(phone)
        if event == "senia_pagada_comprobante" and phone:
            started.add(phone)
            confirmed.add(phone)
    return {
        **stats,
        "consulted": consulted,
        "started": started,
        "confirmed": confirmed,
        "turn_count": turn_count,
        "started_from_consulted": started & consulted,
        "confirmed_from_consulted": confirmed & consulted,
    }


def build_business_conversion_report(command: Dict[str, Any]) -> str:
    stats = _business_report_conversion_stats(command)
    contacts = len(stats["consulted"])
    started = len(stats["started_from_consulted"])
    confirmed = len(stats["confirmed_from_consulted"])
    lines = [
        "🎯 *CONVERSIÓN DE CONSULTAS A RESERVAS*",
        f"📅 Período de interacción: {stats['label']}",
        "",
    ]
    if not contacts:
        lines.extend([
            "No hay consultas medidas por Agent V2 en este período.",
            "La conversión queda sin datos; no se informa como 0%.",
        ])
        return "\n".join(lines)
    lines.extend([
        f"💬 Contactos que consultaron: *{contacts}*",
        f"🔄 Turnos conversacionales: {stats['turn_count']}",
        f"📋 Contactos que iniciaron reserva: *{started}*",
        f"✅ Contactos con seña confirmada: *{confirmed}*",
        "",
        f"📈 Conversión a reserva iniciada: *{_business_report_percent(started, contacts)}*",
        f"💵 Conversión a reserva confirmada: *{_business_report_percent(confirmed, contacts)}*",
        "",
        "Cada contacto se cuenta una sola vez dentro del período.",
    ])
    return "\n".join(lines)


def _business_report_extremes(counts: Dict[Any, int], candidates: List[Any]) -> Tuple[List[Any], List[Any]]:
    if not candidates or not any(int(counts.get(item, 0)) > 0 for item in candidates):
        return [], []
    maximum = max(int(counts.get(item, 0)) for item in candidates)
    minimum = min(int(counts.get(item, 0)) for item in candidates)
    high = [item for item in candidates if int(counts.get(item, 0)) == maximum]
    low = [item for item in candidates if int(counts.get(item, 0)) == minimum]
    return high, low


def build_business_demand_report(command: Dict[str, Any]) -> str:
    stats = _business_report_stats(command)
    hours = stats["hours"]
    high_hours, low_hours = _business_report_extremes(stats["demand_counts"], hours)
    weekdays = sorted({day.weekday() for day in stats["dates"]})
    high_days, low_days = _business_report_extremes(stats["demand_day"], weekdays)
    courts = list(stats["courts"])
    high_courts, low_courts = _business_report_extremes(stats["demand_court"], courts)
    total_attempts = sum(stats["reservations_by_status"].values())
    lines = [
        "🔥 *REPORTE DE DEMANDA*",
        f"📅 Período de los turnos: {stats['label']}",
        "",
        f"📋 Reservas o intentos registrados: *{total_attempts}*",
    ]
    if not high_hours:
        lines.extend(["", "No hay demanda registrada en este período."])
        return "\n".join(lines)

    def count_text(items, counts, formatter=lambda value: str(value)):
        return ", ".join(
            f"{formatter(item)} ({counts.get(item, 0)})" for item in items[:5]
        )

    lines.extend([
        "",
        "*Horarios*",
        f"📈 Mayor demanda: {count_text(high_hours, stats['demand_counts'])}",
        f"📉 Menor demanda: {count_text(low_hours, stats['demand_counts'])}",
    ])
    if high_days:
        lines.extend([
            "",
            "*Días*",
            f"📈 Mayor demanda: {count_text(high_days, stats['demand_day'], lambda value: NOMBRES_DIAS[value])}",
            f"📉 Menor demanda: {count_text(low_days, stats['demand_day'], lambda value: NOMBRES_DIAS[value])}",
        ])
    if high_courts:
        lines.extend([
            "",
            "*Canchas*",
            f"📈 Mayor demanda: {count_text(high_courts, stats['demand_court'])}",
            f"📉 Menor demanda: {count_text(low_courts, stats['demand_court'])}",
        ])
    lines.extend([
        "",
        "Demanda observada: incluye reservas iniciadas aunque luego se cancelaran, vencieran o terminaran en no-show.",
    ])
    return "\n".join(lines)


def build_business_summary_report(command: Dict[str, Any]) -> str:
    stats = _business_report_stats(command)
    conversion = _business_report_conversion_stats(command)
    statuses = stats["reservations_by_status"]
    finance = stats["finance"]
    capacity = len(stats["capacity"])
    occupied = len(stats["occupied"])
    high_hours, low_hours = _business_report_extremes(
        stats["demand_counts"], stats["hours"]
    )
    contacts = len(conversion["consulted"])
    started = len(conversion["started_from_consulted"])
    title = "MENSUAL" if str(command.get("period_mode") or "").endswith("month") else "SEMANAL"
    lines = [
        f"📈 *RESUMEN {title} DEL NEGOCIO*",
        f"📅 Período: {stats['label']}",
        "",
        "*Ocupación*",
        f"• {occupied}/{capacity} slots ({_business_report_percent(occupied, capacity)})",
        f"• Confirmadas: {statuses.get('confirmed', 0)} | Holds: {statuses.get('pending', 0)}",
        "",
        "*Dinero*",
        f"• Total de reservas firmes: {_fmt_precio(finance['billed'])}",
        f"• Cobrado registrado: {_fmt_precio(finance['collected'])}",
        f"• Saldo de reservas firmes por cobrar: {_fmt_precio(finance['balance'])}",
        f"• Holds esperando seña: {statuses.get('pending', 0)} (no facturados)",
        "",
        "*Incidencias*",
        f"• Cancelaciones: {statuses.get('cancelled', 0)} | No-shows: {statuses.get('no_show', 0)}",
        "",
        "*Conversión*",
        (
            f"• {started}/{contacts} contactos ({_business_report_percent(started, contacts)}) iniciaron reserva"
            if contacts else
            "• Sin consultas medidas por Agent V2 en el período"
        ),
        "",
        "*Demanda*",
        f"• Horarios con mayor demanda: {', '.join(high_hours[:5]) or 'sin datos'}",
        f"• Horarios con menor demanda: {', '.join(low_hours[:5]) or 'sin datos'}",
        "",
        "Detalle disponible con: `reporte ocupación`, `reporte facturación`, "
        "`reporte cancelaciones`, `reporte conversión` y `reporte demanda`.",
    ]
    return "\n".join(lines)


def build_business_report_message(command: Dict[str, Any]) -> str:
    report_type = str(command.get("report_type") or "summary").strip()
    builders = {
        "occupancy": build_business_occupancy_report,
        "finance": build_business_finance_report,
        "incidents": build_business_incidents_report,
        "conversion": build_business_conversion_report,
        "demand": build_business_demand_report,
        "summary": build_business_summary_report,
    }
    builder = builders.get(report_type, build_business_summary_report)
    try:
        return builder(command)
    except Exception as exc:
        print(f"[REPORTES] Error generando {report_type}: {exc}")
        return "No pude generar el reporte de forma segura. Revisá los archivos de calendario y métricas."


def construir_decision_operativa(
    ultimo_mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    intencion: Dict = None,
    estado_operativo: Dict = None
) -> Dict[str, Any]:
    memoria = conv_state.get("memoria_cliente") or cargar_memoria_cliente(telefono)
    reserva_actual = None
    try:
        reserva_actual = calendario.obtener_reserva_por_telefono(telefono or "unknown", prospecto.get("nombre", "") if prospecto else "")
    except Exception:
        reserva_actual = None

    texto = str(ultimo_mensaje or "").lower()
    datos_faltantes = []
    situacion = "consulta_general"
    accion = "responder_contextual"
    riesgo = "bajo"
    restricciones = []

    if intencion and intencion.get("intencion") == "cancela":
        situacion = "cliente_quiere_cancelar"
        accion = "cancelar_turno"
        if reserva_actual and str(reserva_actual.get("senia_estado") or "").lower() == "pagada":
            restricciones.append("confirmar_cancelacion_con_senia_pagada_si_hay_ambiguedad")
            riesgo = "medio"
    elif intencion and intencion.get("intencion") == "evento_dia_completo":
        situacion = "cliente_quiere_evento_dia_completo"
        accion = "derivar_evento_dia_completo"
        riesgo = "medio"
    elif intencion and intencion.get("intencion") == "reservar_quincho":
        situacion = "cliente_quiere_reservar_quincho"
        accion = "validar_disponibilidad"
        if not conv_state.get("quincho_duracion_horas"):
            datos_faltantes.append("duracion_quincho")
        if REQUIRES_DEPOSIT:
            restricciones.append("requiere_senia")
    elif any(p in texto for p in ("cambiar", "mover", "pasar", "reprogramar")):
        situacion = "cliente_quiere_reprogramar"
        accion = "reprogramar_turno"
        if reserva_actual and str(reserva_actual.get("senia_estado") or "").lower() == "pagada":
            restricciones.append("preservar_senia_pagada")
            riesgo = "medio"
    elif any(p in texto for p in ("comprobante", "transfer", "te mande", "pague", "pago")) or "[imagen_enviada]" in texto:
        situacion = "cliente_envia_comprobante"
        accion = "analizar_comprobante"
        restricciones.append("escalar_si_comprobante_no_se_entiende")
    elif any(p in texto for p in ("reserv", "turno", "cancha", "horario", "libre")):
        situacion = "cliente_quiere_reservar"
        accion = "validar_disponibilidad"
        if not conv_state.get("dia_propuesto"):
            datos_faltantes.append("dia")
        if not conv_state.get("hora_propuesta"):
            datos_faltantes.append("hora")
        if REQUIRES_DEPOSIT:
            restricciones.append("requiere_senia")
    elif intencion and intencion.get("intencion") == "derivar_humano":
        situacion = "cliente_pide_humano"
        accion = "derivar_humano"
        riesgo = "medio"

    cliente_estado = "frecuente" if memoria.get("cliente_frecuente") else ("cliente" if memoria.get("es_cliente") else "nuevo")
    if reserva_actual:
        cliente_estado = "ya_tiene_turno"
        senia_estado = str(reserva_actual.get("senia_estado") or "").lower()
        if senia_estado in {"pendiente", "pendiente_efectivo"}:
            cliente_estado = "tiene_senia_pendiente"
        elif senia_estado == "parcial":
            cliente_estado = "tiene_senia_parcial"
        elif senia_estado == "parcial_efectivo_pendiente":
            cliente_estado = "turno_firme_con_efectivo_pendiente"
        elif senia_estado == "pagada":
            cliente_estado = "tiene_senia_pagada"

    if any(p in texto for p in ("enoja", "mal", "reclamo", "no puede ser", "problema")):
        riesgo = "alto"
        restricciones.append("escalar_cliente_molesto")

    decision = {
        "situacion": situacion,
        "cliente_estado": cliente_estado,
        "riesgo": riesgo,
        "datos_faltantes": datos_faltantes,
        "restricciones": restricciones,
        "accion_recomendada": accion,
        "confianza": 0.82 if accion != "responder_contextual" else 0.65,
        "autonomia_requerida": {
            "responder_contextual": AUTONOMY_LEVEL_SIMPLE_REPLIES,
            "validar_disponibilidad": AUTONOMY_LEVEL_SIMPLE_REPLIES,
            "analizar_comprobante": AUTONOMY_LEVEL_RESERVE_PENDING,
            "cancelar_turno": AUTONOMY_LEVEL_CHANGE_CANCEL,
            "reprogramar_turno": AUTONOMY_LEVEL_CHANGE_CANCEL,
            "derivar_humano": AUTONOMY_LEVEL_SIMPLE_REPLIES,
            "derivar_evento_dia_completo": AUTONOMY_LEVEL_SIMPLE_REPLIES,
        }.get(accion, AUTONOMY_LEVEL_SIMPLE_REPLIES),
        "memoria_cliente": {
            "cliente_frecuente": memoria.get("cliente_frecuente"),
            "cancha_preferida": memoria.get("cancha_preferida"),
            "horario_preferido": memoria.get("horario_preferido"),
            "dias_frecuentes": memoria.get("dias_frecuentes", [])
        },
        "estado_operativo_resumen": {
            "turnos_hoy": len((estado_operativo or {}).get("turnos_hoy") or []),
            "senias_pendientes": len((estado_operativo or {}).get("turnos_senia_pendiente") or []),
            "huecos_pico": len((estado_operativo or {}).get("huecos_pico_vacios") or [])
        }
    }
    conv_state["decision_actual"] = decision
    return decision


async def construir_decision_operativa_ia(
    ultimo_mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    intencion: Dict = None,
    estado_operativo: Dict = None
) -> Dict[str, Any]:
    """Razonamiento operativo IA + auditoría IA. Mantiene fallback determinístico si falla."""
    fallback = construir_decision_operativa(
        ultimo_mensaje,
        conv_state,
        prospecto,
        telefono,
        intencion=intencion,
        estado_operativo=estado_operativo,
    )
    memoria = conv_state.get("memoria_cliente") or cargar_memoria_cliente(telefono)
    try:
        reserva_actual = calendario.obtener_reserva_por_telefono(
            telefono or "unknown",
            prospecto.get("nombre", "") if prospecto else ""
        )
    except Exception:
        reserva_actual = None

    acciones_validas = {
        "responder_contextual": AUTONOMY_LEVEL_SIMPLE_REPLIES,
        "validar_disponibilidad": AUTONOMY_LEVEL_SIMPLE_REPLIES,
        "analizar_comprobante": AUTONOMY_LEVEL_RESERVE_PENDING,
        "cancelar_turno": AUTONOMY_LEVEL_CHANGE_CANCEL,
        "reprogramar_turno": AUTONOMY_LEVEL_CHANGE_CANCEL,
        "derivar_humano": AUTONOMY_LEVEL_SIMPLE_REPLIES,
        "derivar_evento_dia_completo": AUTONOMY_LEVEL_SIMPLE_REPLIES,
    }

    contexto = {
        "mensaje": ultimo_mensaje,
        "fase": conv_state.get("fase", "inicial"),
        "dia_propuesto": conv_state.get("dia_propuesto"),
        "hora_propuesta": conv_state.get("hora_propuesta"),
        "cancha_propuesta": conv_state.get("cancha_propuesta"),
        "con_quincho": conv_state.get("con_quincho"),
        "quincho_duracion_horas": conv_state.get("quincho_duracion_horas"),
        "intencion_previa": intencion or {},
        "prospecto": {
            "nombre": (prospecto or {}).get("nombre"),
            "es_cliente": (prospecto or {}).get("es_cliente"),
        },
        "memoria_cliente": {
            "cliente_frecuente": memoria.get("cliente_frecuente"),
            "cancha_preferida": memoria.get("cancha_preferida"),
            "horario_preferido": memoria.get("horario_preferido"),
            "dias_frecuentes": memoria.get("dias_frecuentes", []),
            "no_shows": memoria.get("no_shows"),
            "cancelaciones_tarde": memoria.get("cancelaciones_tarde"),
        },
        "reserva_actual": reserva_actual or {},
        "estado_operativo_resumen": {
            "turnos_hoy": len((estado_operativo or {}).get("turnos_hoy") or []),
            "senias_pendientes": len((estado_operativo or {}).get("turnos_senia_pendiente") or []),
            "huecos_pico": len((estado_operativo or {}).get("huecos_pico_vacios") or []),
        },
        "fallback_actual": fallback,
    }

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el módulo de razonamiento operativo de un agente IA para reservas de canchas.\n"
                        "Tu trabajo es decidir qué situación hay y qué acción debería ejecutar el sistema.\n"
                        "Razoná por contexto, memoria e intención real, no por palabras sueltas.\n"
                        "No ejecutes acciones: solo devolvé una decisión estructurada.\n"
                        "Acciones válidas: responder_contextual, validar_disponibilidad, analizar_comprobante, "
                        "cancelar_turno, reprogramar_turno, derivar_humano, derivar_evento_dia_completo.\n"
                        "Si el usuario está frustrado pero sigue preguntando disponibilidad, elegí validar_disponibilidad o responder_contextual, no derivar_humano.\n"
                        "Respondé SOLO JSON con: "
                        "{\"situacion\":\"texto\",\"riesgo\":\"bajo|medio|alto\","
                        "\"datos_faltantes\":[\"dia|hora|cancha|duracion_quincho|nombre\"],"
                        "\"restricciones\":[\"texto\"],\"accion_recomendada\":\"accion\","
                        "\"confianza\":0.0,\"razon\":\"breve\"}"
                    )
                },
                {"role": "user", "content": json.dumps(contexto, ensure_ascii=False)}
            ],
            temperature=0.0,
            max_tokens=320,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        decision_ia = json.loads(resp.choices[0].message.content.strip())
        decision_ia["accion_recomendada"] = decision_ia.get("accion_recomendada") if decision_ia.get("accion_recomendada") in acciones_validas else fallback["accion_recomendada"]
        decision_ia["riesgo"] = decision_ia.get("riesgo") if decision_ia.get("riesgo") in ("bajo", "medio", "alto") else fallback["riesgo"]
        decision_ia["datos_faltantes"] = decision_ia.get("datos_faltantes") if isinstance(decision_ia.get("datos_faltantes"), list) else []
        decision_ia["restricciones"] = decision_ia.get("restricciones") if isinstance(decision_ia.get("restricciones"), list) else []
        decision_ia["confianza"] = float(decision_ia.get("confianza", 0.0) or 0.0)

        decision = {**fallback, **decision_ia}
        decision["cliente_estado"] = fallback.get("cliente_estado")
        decision["autonomia_requerida"] = acciones_validas.get(decision["accion_recomendada"], AUTONOMY_LEVEL_SIMPLE_REPLIES)
        decision["memoria_cliente"] = fallback.get("memoria_cliente", {})
        decision["estado_operativo_resumen"] = fallback.get("estado_operativo_resumen", {})

        auditoria = await auditar_decision_operativa_ia(contexto, decision, fallback)
        if auditoria.get("corregir"):
            accion_corregida = auditoria.get("accion_recomendada")
            if accion_corregida in acciones_validas:
                decision["accion_recomendada"] = accion_corregida
                decision["autonomia_requerida"] = acciones_validas[accion_corregida]
            if auditoria.get("riesgo") in ("bajo", "medio", "alto"):
                decision["riesgo"] = auditoria.get("riesgo")
            if isinstance(auditoria.get("datos_faltantes"), list):
                decision["datos_faltantes"] = auditoria.get("datos_faltantes")
            if isinstance(auditoria.get("restricciones"), list):
                decision["restricciones"] = auditoria.get("restricciones")
            decision["confianza"] = float(auditoria.get("confianza", decision.get("confianza", 0.0)) or 0.0)
            decision["razon"] = f"Segunda lectura IA: {auditoria.get('razon', '')}"

        print(
            f"   [Decisión operativa IA] {decision.get('accion_recomendada')} "
            f"riesgo={decision.get('riesgo')} conf={decision.get('confianza')}"
        )
        conv_state["decision_actual"] = decision
        return decision
    except Exception as e:
        print(f"   [Decisión operativa IA] Error: {e}. Uso fallback operativo.")
        conv_state["decision_actual"] = fallback
        return fallback


async def auditar_decision_operativa_ia(contexto: Dict[str, Any], decision: Dict[str, Any], fallback: Dict[str, Any]) -> Dict[str, Any]:
    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos una segunda IA auditora de decisiones operativas para un agente de reservas.\n"
                        "Revisá si la acción recomendada es segura y coherente con contexto, memoria e intención.\n"
                        "No cambies disponibilidad, precios ni estados de agenda: eso lo verifican herramientas.\n"
                        "Corregí solo si la acción elegida contradice la intención real o el contexto.\n"
                        "Respondé SOLO JSON: "
                        "{\"corregir\":true|false,\"accion_recomendada\":\"accion\","
                        "\"riesgo\":\"bajo|medio|alto\",\"datos_faltantes\":[],\"restricciones\":[],"
                        "\"confianza\":0.0,\"razon\":\"breve\"}"
                    )
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "contexto": contexto,
                        "decision_auditada": decision,
                        "fallback_previo": fallback,
                    }, ensure_ascii=False)
                }
            ],
            temperature=0.0,
            max_tokens=260,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        data["corregir"] = bool(data.get("corregir"))
        data["confianza"] = float(data.get("confianza", 0.0) or 0.0)
        print(f"   [Decisión operativa IA auditora] corregir={data.get('corregir')} - {str(data.get('razon', ''))[:80]}")
        return data
    except Exception as e:
        print(f"   [Decisión operativa IA auditora] Error: {e}")
        return {"corregir": False, "accion_recomendada": decision.get("accion_recomendada"), "confianza": 0.0, "razon": f"error: {e}"}


def crear_plan_operativo(decision: Dict[str, Any], conv_state: Dict) -> Dict[str, Any]:
    accion = decision.get("accion_recomendada")
    if accion == "validar_disponibilidad":
        pasos = ["validar_dia", "validar_hora", "buscar_cancha_libre", "proponer_opcion", "pedir_senia", "marcar_senia_pendiente", "programar_recordatorio"]
        objetivo = "cerrar_reserva"
    elif accion == "reprogramar_turno":
        pasos = ["buscar_reserva_actual", "preservar_senia_si_corresponde", "validar_nueva_fecha_hora", "intentar_misma_cancha", "ofrecer_alternativa", "actualizar_calendario"]
        objetivo = "reprogramar_turno"
    elif accion == "cancelar_turno":
        pasos = ["buscar_reserva_actual", "verificar_ambiguedad", "controlar_senia_pagada", "cancelar_si_es_seguro", "ofrecer_reprogramacion"]
        objetivo = "cancelar_turno"
    elif accion == "analizar_comprobante":
        pasos = ["capturar_comprobante", "validar_monto", "marcar_senia_pagada", "confirmar_turno", "registrar_metrica"]
        objetivo = "confirmar_senia"
    elif accion == "derivar_evento_dia_completo":
        pasos = ["responder_cliente", "avisar_encargado", "esperar_coordinacion_manual"]
        objetivo = "coordinar_evento_dia_completo"
    else:
        pasos = ["entender_mensaje", "responder_directo", "mantener_contexto"]
        objetivo = "resolver_consulta"
    actual = next((p for p in pasos if p in (decision.get("datos_faltantes") or [])), pasos[0] if pasos else "responder")
    plan = {
        "objetivo": objetivo,
        "plan": pasos,
        "accion_actual": actual,
        "control": {
            "autonomia_actual": getattr(bot_state, "autonomy_level", DEFAULT_AUTONOMY_LEVEL),
            "autonomia_requerida": decision.get("autonomia_requerida", AUTONOMY_LEVEL_SIMPLE_REPLIES),
            "riesgo": decision.get("riesgo")
        }
    }
    conv_state["plan_actual"] = plan
    return plan


def validar_control_autonomia(decision: Dict[str, Any], plan: Dict[str, Any], reserva_actual: Dict = None) -> Dict[str, Any]:
    nivel_actual = getattr(bot_state, "autonomy_level", DEFAULT_AUTONOMY_LEVEL)
    nivel_requerido = int(decision.get("autonomia_requerida") or AUTONOMY_LEVEL_SIMPLE_REPLIES)
    if nivel_actual < nivel_requerido:
        return {"ok": False, "motivo": "autonomia_insuficiente", "detalle": f"nivel {nivel_actual} < requerido {nivel_requerido}"}
    if decision.get("riesgo") == "alto":
        return {"ok": False, "motivo": "riesgo_alto", "detalle": "escalar a humano"}
    restricciones = set(decision.get("restricciones") or [])
    if "preservar_senia_pagada" in restricciones and reserva_actual and str(reserva_actual.get("senia_estado") or "").lower() == "pagada":
        if decision.get("accion_recomendada") == "reprogramar_turno" and not decision.get("confirmacion_clara"):
            return {"ok": False, "motivo": "senia_pagada_requiere_confirmacion", "detalle": "no cambiar turno con senia pagada sin confirmacion clara"}
    return {"ok": True, "motivo": "permitido"}


def tool_buscar_disponibilidad(
    dia: str,
    hora: str = None,
    cancha_opcional: str = None,
    resource_types: Any = None,
) -> Dict[str, Any]:
    dia_resuelto = resolver_fecha(dia or "hoy")
    canonical_types = _canonical_configured_court_types(resource_types)
    candidate_courts = _court_names_compatible_with_resource_types(
        canonical_types, cancha_opcional
    )

    # Si PERCEPTION restringió a un tipo configurado pero una cancha explícita
    # contradice ese tipo, fail closed: no ampliamos la búsqueda a otro deporte.
    if cancha_opcional and canonical_types and not candidate_courts:
        return {
            "ok": False,
            "dia": dia_resuelto,
            "hora": hora,
            "canchas_libres": [],
            "alternativas": [],
            "resource_types": canonical_types,
            "razon": "resource_type_mismatch",
        }

    if not validar_fecha_en_dias_atencion(dia_resuelto):
        alt_dia, alt_hora = proximo_slot_reservable_con_anticipacion(
            dia_resuelto, hora or "", cancha=cancha_opcional,
            duracion_horas=DEFAULT_TURN_DURATION_HOURS, max_dias=14,
            resource_types=canonical_types,
        )
        return {
            "ok": False,
            "dia": dia_resuelto,
            "canchas_libres": [],
            "alternativas": ([{
                "dia": alt_dia, "hora": alt_hora, "cancha": cancha_opcional or ""
            }] if alt_dia and hora_es_valida(alt_hora) else []),
            "resource_types": canonical_types,
            "razon": "dia_fuera_de_atencion",
        }
    if hora and not validar_hora_en_franja(hora):
        return {
            "ok": False, "canchas_libres": [], "alternativas": [],
            "resource_types": canonical_types, "razon": "hora_fuera_de_franja"
        }
    canchas_libres = []
    if hora_es_valida(hora):
        for court_name in candidate_courts:
            if calendario.slot_esta_libre_en_cancha(dia_resuelto, hora, court_name):
                canchas_libres.append(court_name)
        alternativas = []
        if not canchas_libres:
            alt_dia, alt_hora = proximo_slot_reservable_con_anticipacion(
                dia_resuelto, hora, cancha=cancha_opcional,
                duracion_horas=DEFAULT_TURN_DURATION_HOURS, max_dias=14,
                resource_types=canonical_types,
            )
            if alt_dia and hora_es_valida(alt_hora):
                alternativas.append({
                    "dia": alt_dia, "hora": alt_hora, "cancha": cancha_opcional or ""
                })
        return {
            "ok": bool(canchas_libres), "dia": dia_resuelto, "hora": hora,
            "canchas_libres": canchas_libres, "alternativas": alternativas,
            "resource_types": canonical_types, "razon": "validado"
        }
    return {
        "ok": True,
        "dia": dia_resuelto,
        "canchas_libres_por_franja": obtener_horarios_disponibles_para_dia(
            dia_resuelto, resource_types=canonical_types, cancha_opcional=cancha_opcional
        ),
        "alternativas": [],
        "resource_types": canonical_types,
        "razon": "sin_hora_especifica",
    }


def tool_reservar_turno(
    telefono: str,
    nombre: str,
    dia: str,
    hora: str,
    cancha: str,
    estado_senia: str = "pendiente"
) -> Dict[str, Any]:
    disponibilidad = tool_buscar_disponibilidad(dia, hora, cancha)
    if not disponibilidad.get("ok"):
        return {"ok": False, "reserva_id": "", "mensaje_operativo": "slot_no_disponible", "disponibilidad": disponibilidad}
    return {
        "ok": True,
        "reserva_id": f"{_cliente_key(telefono)}-{resolver_fecha(dia)}-{hora}-{cancha}",
        "mensaje_operativo": "validacion_previa_ok",
        "input": {
            "telefono": telefono,
            "nombre": nombre,
            "dia": dia,
            "hora": hora,
            "cancha": cancha,
            "estado_senia": estado_senia
        }
    }


def _proactive_key(tipo: str, row: Dict[str, Any]) -> str:
    return "|".join([
        tipo,
        str(row.get("telefono") or ""),
        str(row.get("nombre") or ""),
        str(row.get("fecha") or ""),
        str(row.get("hora") or ""),
        str(row.get("cancha") or "")
    ])



# ============================================================
# V2.10.4 — REACTIVE HANDOFF
# ============================================================
# Las tareas proactivas pueden navegar directamente al chat de un cliente.
# Abrirlo puede consumir visualmente el badge "No leídos". Este handoff evita
# depender del badge después de haber detectado una entrada real.
_REACTIVE_HANDOFF = {
    "pending": False,
    "telefono": "",
    "source": "",
    "detected_at": "",
}


def _mark_reactive_handoff(telefono: str, source: str) -> None:
    telefono_norm = normalize_phone(telefono or "")
    _REACTIVE_HANDOFF.update({
        "pending": True,
        "telefono": telefono_norm,
        "source": str(source or "proactive_navigation"),
        "detected_at": datetime.datetime.now(TIMEZONE).isoformat(),
    })
    print(
        f"   🔁 [INBOX HANDOFF] chat abierto por proactivo tiene mensaje pendiente "
        f"telefono={telefono_norm or telefono} source={source}"
    )


def _reactive_handoff_pending() -> bool:
    return bool(_REACTIVE_HANDOFF.get("pending"))


def _clear_reactive_handoff(reason: str = "") -> None:
    if _REACTIVE_HANDOFF.get("pending"):
        print(
            f"   ✅ [INBOX HANDOFF] liberado"
            + (f" reason={reason}" if reason else "")
        )
    _REACTIVE_HANDOFF.update({
        "pending": False,
        "telefono": "",
        "source": "",
        "detected_at": "",
    })


# ============================================================
# V199 — MEDIA BROWSER RESTART RECOVERY
# ============================================================
# Si Chrome se cierra mientras se procesa un lote de audios/imágenes, el badge
# visual de "No leídos" puede quedar consumido. Conservamos el teléfono del chat
# y, tras levantar nuevamente WhatsApp Web, lo reabrimos con la ruta nativa
# /send?phone=...&text= SIN enviar ningún mensaje. Luego reutilizamos el handoff
# reactivo existente para procesar ese chat abierto antes de volver a los filtros.
# El recovery sólo se limpia cuando el lote multimedia logra leerse de nuevo.
_MEDIA_BROWSER_RECOVERY = {
    "pending": False,
    "telefono": "",
    "source": "",
    "detected_at": "",
    "restart_count": 0,
}


def _arm_media_browser_recovery(telefono: str, source: str = "media_browser_closed") -> bool:
    telefono_norm = normalize_phone(telefono or "")
    if not telefono_norm or str(telefono_norm).startswith("NOMBRE:"):
        print(
            "   ⚠️ [MEDIA RECOVERY] no pude armar recovery: "
            f"teléfono no navegable ({telefono or 'vacío'})"
        )
        return False

    previous_phone = normalize_phone(_MEDIA_BROWSER_RECOVERY.get("telefono") or "")
    previous_count = int(_MEDIA_BROWSER_RECOVERY.get("restart_count") or 0)
    restart_count = previous_count + 1 if previous_phone == telefono_norm else 1
    _MEDIA_BROWSER_RECOVERY.update({
        "pending": True,
        "telefono": telefono_norm,
        "source": str(source or "media_browser_closed"),
        "detected_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "restart_count": restart_count,
    })
    registrar_metrica_operativa(
        "media_browser_recovery_armed",
        {
            "telefono": telefono_norm,
            "source": str(source or "media_browser_closed"),
            "restart_count": restart_count,
        },
    )
    print(
        "   🧷 [MEDIA RECOVERY] armado para reabrir el chat después del restart "
        f"telefono={telefono_norm} intento={restart_count}"
    )
    return True


def _media_browser_recovery_pending() -> bool:
    return bool(_MEDIA_BROWSER_RECOVERY.get("pending"))


def _media_browser_recovery_matches(telefono: str) -> bool:
    if not _media_browser_recovery_pending():
        return False
    return normalize_phone(telefono or "") == normalize_phone(
        _MEDIA_BROWSER_RECOVERY.get("telefono") or ""
    )


def _clear_media_browser_recovery(reason: str = "") -> None:
    if _MEDIA_BROWSER_RECOVERY.get("pending"):
        print(
            "   ✅ [MEDIA RECOVERY] recovery multimedia liberado"
            + (f" reason={reason}" if reason else "")
        )
    _MEDIA_BROWSER_RECOVERY.update({
        "pending": False,
        "telefono": "",
        "source": "",
        "detected_at": "",
        "restart_count": 0,
    })


async def _restore_media_chat_after_browser_restart(page) -> bool:
    """Reabre el chat que falló durante media sin enviar un message-out.

    La navegación usa la misma ruta de WhatsApp Web "Send Message", pero deja
    `text=` vacío. No se llama `send_message`, no se presiona Enter y por lo
    tanto el historial del cliente permanece intacto para que los audios vuelvan
    a aparecer como backlog posterior al último message-out real.
    """
    if not _media_browser_recovery_pending():
        return False

    telefono = normalize_phone(_MEDIA_BROWSER_RECOVERY.get("telefono") or "")
    if not telefono or str(telefono).startswith("NOMBRE:"):
        return False

    chat_url = (
        "https://web.whatsapp.com/send?phone="
        f"{telefono.replace('+', '')}&text="
    )
    try:
        print(
            "   ♻️ [MEDIA RECOVERY] WhatsApp volvió; reabro el chat fallido "
            f"con Send Message vacío telefono={telefono}"
        )
        await page.goto(chat_url, timeout=120000, wait_until="domcontentloaded")
        await _resolve_whatsapp_message_composer(page, timeout_ms=30000)
        await asyncio.sleep(1.0)

        # Abrir el chat puede consumir visualmente el badge. El handoff reactivo
        # hace que automation_loop procese el chat YA ABIERTO antes de No leídos.
        _mark_reactive_handoff(telefono, "media_browser_restart_recovery")
        registrar_metrica_operativa(
            "media_browser_recovery_chat_reopened",
            {
                "telefono": telefono,
                "restart_count": int(_MEDIA_BROWSER_RECOVERY.get("restart_count") or 0),
            },
        )
        print(
            "   🎧 [MEDIA RECOVERY] chat restaurado; el próximo ciclo releerá "
            "el lote multimedia completo desde WhatsApp"
        )
        return True
    except Exception as exc:
        registrar_metrica_operativa(
            "media_browser_recovery_reopen_failed",
            {"telefono": telefono, "error": str(exc)},
        )
        print(f"   ⚠️ [MEDIA RECOVERY] no pude reabrir {telefono}: {exc}")
        return False


# ============================================================
# V2.10.4 — 10-MINUTE PENDING HOLD LEASE
# ============================================================
_LAST_PENDING_HOLD_SWEEP_TS = 0.0

def _migrate_pending_hold_tracking_after_reprogram(
    before_row: Dict[str, Any],
    after_row: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Mueve el lease pendiente desde el slot anterior al nuevo SIN reiniciar
    started_at/expires_at.

    IMPORTANTE:

        REPROGRAMAR != CREAR HOLD NUEVO

    La key actual del hold incluye fecha/hora/cancha, por eso una
    reprogramación cambia físicamente la key aunque continúe siendo
    la misma reserva lógica.

    Esta función conserva:

        - started_at
        - expires_at
        - recordatorios ya enviados
        - generación original del hold

    y actualiza únicamente el snapshot del nuevo slot.
    """
    before = dict(before_row or {})
    after = dict(after_row or {})

    if not before or not after:
        return {
            "ok": False,
            "reason": "missing_rows",
        }

    state = _json_read(
        PROACTIVE_STATE_FILE,
        {"sent": {}},
    )

    pending_seen = state.setdefault(
        "pending_deposit_seen_at",
        {},
    )

    holds = state.setdefault(
        "pending_deposit_holds",
        {},
    )

    sent = state.setdefault(
        "sent",
        {},
    )

    old_key = _pending_hold_key(
        before
    )

    new_key = _pending_hold_key(
        after
    )

    source_key = old_key

    payload = (
        holds.get(source_key)
        if isinstance(
            holds.get(source_key),
            dict,
        )
        else None
    )

    seen_value = pending_seen.get(
        source_key
    )

    # ==========================================================
    # COMPATIBILIDAD CON KEYS LEGACY
    # ==========================================================

    if payload is None:

        for (
            candidate_key,
            candidate_payload,
        ) in list(
            holds.items()
        ):

            if not isinstance(
                candidate_payload,
                dict,
            ):
                continue

            snapshot = (
                candidate_payload.get(
                    "reserva"
                )
            )

            if (
                isinstance(
                    snapshot,
                    dict,
                )
                and _hold_identity_matches(
                    snapshot,
                    before,
                )
            ):
                source_key = (
                    candidate_key
                )

                payload = (
                    candidate_payload
                )

                seen_value = (
                    pending_seen.get(
                        candidate_key
                    )
                )

                break

    # ==========================================================
    # RECUPERAR RELOJ ORIGINAL
    # ==========================================================

    started_at = (
        _parse_iso_datetime(
            (payload or {}).get(
                "started_at"
            )
        )
    )

    if not started_at:
        started_at = (
            _parse_iso_datetime(
                seen_value
            )
        )

    if not started_at:
        started_at = (
            _parse_iso_datetime(
                before.get(
                    "reservado_en"
                )
            )
        )

    if not started_at:

        print(
            "   ⚠️ [HOLD REPROGRAM MIGRATION] "
            "no encontré started_at previo; "
            "NO reinicio el lease automáticamente"
        )

        return {
            "ok": False,
            "reason": (
                "missing_original_hold_start"
            ),
        }

    expires_at = (
        _parse_iso_datetime(
            (payload or {}).get(
                "expires_at"
            )
        )
    )

    if not expires_at:

        expires_at = (
            started_at
            + datetime.timedelta(
                minutes=(
                    PENDING_DEPOSIT_HOLD_MINUTES
                )
            )
        )

    # ==========================================================
    # NUEVO SNAPSHOT, MISMO LEASE
    # ==========================================================

    migrated_payload = dict(
        payload
        or {}
    )

    migrated_payload[
        "started_at"
    ] = started_at.isoformat()

    migrated_payload[
        "expires_at"
    ] = expires_at.isoformat()

    migrated_payload[
        "reserva"
    ] = {
        "reservation_id": (
            after.get(
                "reservation_id"
            )
            or before.get(
                "reservation_id"
            )
        ),
        "telefono": (
            after.get(
                "telefono"
            )
            or before.get(
                "telefono"
            )
        ),
        "nombre": (
            after.get(
                "nombre"
            )
            or before.get(
                "nombre"
            )
        ),
        "fecha": (
            after.get(
                "fecha"
            )
            or after.get(
                "dia"
            )
        ),
        "hora": (
            after.get(
                "hora"
            )
        ),
        "cancha": (
            after.get(
                "cancha"
            )
        ),
        "duracion_horas": (
            after.get(
                "duracion_horas"
            )
            or before.get(
                "duracion_horas"
            )
        ),
    }

    # Eliminar identidad del slot anterior.
    if source_key != new_key:

        holds.pop(
            source_key,
            None,
        )

        pending_seen.pop(
            source_key,
            None,
        )

    # La key nueva hereda EXACTAMENTE
    # el reloj original.
    holds[
        new_key
    ] = migrated_payload

    pending_seen[
        new_key
    ] = started_at.isoformat()

    # ==========================================================
    # RECORDATORIO DE SEÑA
    # ==========================================================

    old_reminder_key = (
        _proactive_key(
            "senia_cliente_recordatorio",
            before,
        )
    )

    new_reminder_key = (
        _proactive_key(
            "senia_cliente_recordatorio",
            after,
        )
    )

    if (
        old_reminder_key
        in sent
        and new_reminder_key
        not in sent
    ):
        sent[
            new_reminder_key
        ] = sent.get(
            old_reminder_key
        )

    if (
        old_reminder_key
        != new_reminder_key
    ):
        sent.pop(
            old_reminder_key,
            None,
        )

    # ==========================================================
    # AVISOS DE EXPIRACIÓN DEL SLOT VIEJO
    # ==========================================================

    expiration_queue = (
        state.setdefault(
            "pending_hold_expiration_notifications",
            {},
        )
    )

    for (
        notification_key,
        notification,
    ) in list(
        expiration_queue.items()
    ):

        if (
            str(
                (
                    notification
                    or {}
                ).get(
                    "hold_key"
                )
                or ""
            )
            == source_key
        ):
            expiration_queue.pop(
                notification_key,
                None,
            )

    state[
        "updated_at"
    ] = (
        datetime.datetime.now(
            TIMEZONE
        ).isoformat()
    )

    _json_write(
        PROACTIVE_STATE_FILE,
        state,
    )

    print(
        "   ♻️ [HOLD REPROGRAM MIGRATION] "
        f"{source_key} → {new_key} | "
        f"started_at={started_at.isoformat()} | "
        f"expires_at={expires_at.isoformat()}"
    )

    return {
        "ok": True,
        "old_key": source_key,
        "new_key": new_key,
        "started_at": (
            started_at.isoformat()
        ),
        "expires_at": (
            expires_at.isoformat()
        ),
    }


def _pending_hold_key(row: Dict[str, Any]) -> str:
    return _proactive_key("senia_expiration", row or {})


def _pending_hold_started_at_from_state(
    state: Dict[str, Any],
    row: Dict[str, Any],
) -> Optional[datetime.datetime]:
    key = _pending_hold_key(row)
    holds = (state or {}).get("pending_deposit_holds") or {}
    payload = holds.get(key) if isinstance(holds, dict) else None
    if isinstance(payload, dict):
        started = _parse_iso_datetime(payload.get("started_at"))
        if started:
            return started

    # Migración transparente desde V2.10.3.
    pending_seen = (state or {}).get("pending_deposit_seen_at") or {}
    return _parse_iso_datetime(pending_seen.get(key))


def _pending_hold_is_expired(
    started_at: Optional[datetime.datetime],
    now: Optional[datetime.datetime] = None,
) -> bool:
    if not started_at:
        return False
    now = now or datetime.datetime.now(TIMEZONE)
    return (now - started_at) >= datetime.timedelta(
        minutes=PENDING_DEPOSIT_HOLD_MINUTES
    )


def _pending_hold_row_is_temporary(row: Dict[str, Any]) -> bool:
    """
    Solo las filas con seña pendiente son leases temporales.
    Una seña pagada jamás puede ser liberada por el sweeper.
    """
    if not row or not _reserva_activa(row):
        return False
    # Cuando ya ingresó dinero el turno deja de ser un hold descartable. Sigue
    # aceptando comprobantes, pero nunca se libera automáticamente con plata del
    # cliente registrada.
    if str(row.get("senia_estado") or "").strip().lower() not in {
        "pendiente", "pendiente_efectivo"
    }:
        return False
    estado = str(row.get("estado") or "").strip().lower()
    pending_status = str(BOOKING_STATUS_PENDING or "").strip().lower()
    return not pending_status or estado == pending_status


def _hold_identity_matches(
    row: Dict[str, Any],
    target: Dict[str, Any],
) -> bool:
    if not row or not target:
        return False
    if not _reserva_coincide_slot(
        row,
        target.get("fecha") or target.get("dia"),
        target.get("hora"),
        target.get("cancha"),
    ):
        return False

    target_tel = normalize_phone(target.get("telefono") or "")
    row_tel = normalize_phone(row.get("telefono") or "")
    if target_tel and row_tel:
        return target_tel == row_tel

    target_name = str(target.get("nombre") or "").strip().casefold()
    row_name = str(row.get("nombre") or "").strip().casefold()
    return bool(target_name and row_name and target_name == row_name)


def _clear_pending_hold_tracking(
    row: Dict[str, Any],
    state: Optional[Dict[str, Any]] = None,
    persist: bool = True,
) -> Dict[str, Any]:
    state = state if isinstance(state, dict) else _json_read(
        PROACTIVE_STATE_FILE,
        {"sent": {}},
    )
    key = _pending_hold_key(row)

    pending_seen = state.setdefault("pending_deposit_seen_at", {})
    holds = state.setdefault("pending_deposit_holds", {})
    sent = state.setdefault("sent", {})

    pending_seen.pop(key, None)
    holds.pop(key, None)
    sent.pop(key, None)
    sent.pop(_proactive_key("senia_cliente_recordatorio", row), None)

    state["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
    if persist:
        _json_write(PROACTIVE_STATE_FILE, state)
    return state


def _pending_hold_expiration_message(
    row: Dict[str, Any],
) -> str:
    """
    Mensaje canónico de expiración del hold.

    La última frase constituye una oferta conversacional real:
    si el usuario la acepta semánticamente, el sistema puede volver
    a verificar el bloque y recrear el hold sólo si sigue disponible.
    """
    row = dict(row or {})

    fecha_txt = str(
        row.get("fecha")
        or ""
    ).replace("/2026", "")

    pago_presencial = (
        str(
            row.get("senia_estado")
            or ""
        ).strip().lower()
        == "pendiente_efectivo"
        or str(
            row.get("payment_method")
            or ""
        ).strip().lower()
        == "efectivo"
    )

    validacion_pendiente = (
        "sin que el administrador confirmara "
        "el pago en efectivo"
        if pago_presencial
        else
        "sin que pudiéramos validar el comprobante"
    )

    hour = normalizar_hora_detectada(
        row.get("hora")
    )

    duration = normalizar_duracion_horas(
        row.get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )

    if hora_es_valida(hour):
        horario = rango_horario_texto(
            hour,
            duration,
        )
    else:
        horario = formatear_hora_para_mensaje(
            row.get("hora")
        )

    mensaje = (
        f"Pasaron los {PENDING_DEPOSIT_HOLD_MINUTES} "
        "minutos de bloqueo temporal "
        f"{validacion_pendiente}, así que liberé el turno "
        f"del {fecha_txt}"
    )

    if row.get("cancha"):
        mensaje += (
            f" en {row.get('cancha')}"
        )

    if horario:
        mensaje += (
            f" de {horario}"
        )

    mensaje += (
        ". Si todavía lo querés, decime y, "
        "si sigue disponible, vuelvo a bloquearlo para vos."
    )

    return mensaje


def _queue_pending_hold_expiration_notification(
    state: Dict[str, Any],
    row: Dict[str, Any],
    started_at: datetime.datetime,
    expired_at: datetime.datetime,
) -> str:
    queue = state.setdefault("pending_hold_expiration_notifications", {})
    hold_key = _pending_hold_key(row)
    notification_key = f"{hold_key}|{started_at.isoformat()}"
    queue[notification_key] = {
        "hold_key": hold_key,
        "queued_at": expired_at.isoformat(),
        "attempts": 0,
        "row": dict(row or {}),
        "message": _pending_hold_expiration_message(row),
    }
    return notification_key


def registrar_hold_expirado_para_pago_tardio(
    row: Dict[str, Any],
    expired_at: datetime.datetime,
) -> Optional[Dict[str, Any]]:
    """
    Conserva el turno liberado como referente operativo verificable.

    NO lo conserva como reserva activa.
    NO genera autorización de escritura.
    NO interpreta lenguaje del usuario.

    La decisión posterior de reconsultar o volver a reservar pertenece
    a Perception + Semantic Effect Verifier + ExecutionContract.
    """
    row = dict(row or {})

    reference = _agent_v2_build_released_booking_reference(
        row,
        expired_at,
    )

    if not reference:
        return None

    telefono = _telefono_reserva_para_mensaje(row)
    if not telefono:
        return None

    memoria = cargar_memoria_cliente(telefono)

    records = [
        item
        for item in (
            memoria.get("expired_deposit_holds")
            or []
        )
        if isinstance(item, dict)
    ]

    hold_key = str(
        reference.get("hold_key")
        or _pending_hold_key(row)
    )

    records = [
        item
        for item in records
        if str(item.get("hold_key") or "") != hold_key
    ]

    records.append({
        "hold_key": hold_key,
        "reference_id": reference.get("reference_id"),
        "expired_at": reference.get("expired_at"),
        "reference_expires_at": (
            reference.get("reference_expires_at")
        ),
        "status": "available_for_late_payment",
        "row": dict(row),
    })

    memoria["expired_deposit_holds"] = records[-20:]

    guardar_memoria_cliente(
        telefono,
        memoria,
    )

    return reference


def _agent_v2_recent_released_booking_context(
    telefono: str,
    ahora: Optional[datetime.datetime] = None,
) -> Optional[Dict[str, Any]]:
    """
    Devuelve el último hold liberado reciente como hecho histórico verificable.

    No devuelve una reserva activa.
    No autoriza WRITE.
    Sólo entrega contexto operativo al World Model.
    """
    now = ahora or datetime.datetime.now(TIMEZONE)

    if now.tzinfo is None:
        now = TIMEZONE.localize(now)
    else:
        now = now.astimezone(TIMEZONE)

    cutoff = now - datetime.timedelta(
        hours=EXPIRED_HOLD_REFERENCE_TTL_HOURS
    )

    expected_owner = _memory_owner_key(telefono)

    memoria = cargar_memoria_cliente(telefono)

    candidates = []

    for item in (
        memoria.get("expired_deposit_holds")
        or []
    ):
        if not isinstance(item, dict):
            continue

        if (
            str(item.get("status") or "")
            != "available_for_late_payment"
        ):
            continue

        expired_at = _post_turno_followup_datetime(
            item.get("expired_at")
        )

        row = (
            item.get("row")
            if isinstance(item.get("row"), dict)
            else {}
        )

        row_owner = _memory_owner_key(
            row.get("telefono") or ""
        )

        if (
            not expired_at
            or expired_at < cutoff
            or expired_at
            > now + datetime.timedelta(minutes=1)
            or row_owner == "unknown"
            or row_owner != expected_owner
        ):
            continue

        reference = _agent_v2_build_released_booking_reference(
            row,
            expired_at,
        )

        if not reference:
            continue

        stored_reference_id = str(
            item.get("reference_id") or ""
        ).strip()

        if stored_reference_id:
            reference["reference_id"] = (
                stored_reference_id
            )

        candidates.append(
            (
                expired_at,
                reference,
            )
        )

    if not candidates:
        return None

    _, reference = max(
        candidates,
        key=lambda value: value[0],
    )

    return reference


def _discard_stale_hold_expiration_notifications(
    state: Dict[str, Any],
    row: Dict[str, Any],
) -> int:
    """Evita avisar un vencimiento viejo si el mismo hold ya fue recreado."""
    queue = state.setdefault("pending_hold_expiration_notifications", {})
    hold_key = _pending_hold_key(row)
    stale_keys = [
        key for key, payload in list(queue.items())
        if str((payload or {}).get("hold_key") or "") == hold_key
    ]
    for key in stale_keys:
        queue.pop(key, None)
    return len(stale_keys)


def _purge_transient_booking_context_after_missing_reservation(
    telefono: str,
    *,
    reason: str,
) -> Dict[str, Any]:
    """
    V2.10.5 — GHOST BOOKING PURGE.

    Si CALENDARIO ya no contiene el hold/reserva que justificaba
    fase=senia_pendiente, ningún draft/target/auth/pending de Agent V2 puede
    sobrevivir y resucitar ese turno en una conversación futura.

    Conserva historial, memoria durable y facts históricos.
    """
    telefono_key = telefono or "unknown"
    state = get_conversation_state(telefono_key)
    av2_raw = state.get("agent_v2")
    av2 = dict(av2_raw) if isinstance(av2_raw, dict) else {}

    if av2:
        desires = dict(av2.get("desires") or {})
        for key in (
            "booking_draft",
            "reservation_target",
            "pending_payment_analysis",
            "explicit",
            "explicit_actions",
            "explicit_negations",
        ):
            desires.pop(key, None)
        av2["desires"] = desires

        auths = dict(av2.get("write_authorizations") or {})
        auths.pop("crear_reserva", None)
        av2["write_authorizations"] = auths
        av2["open_questions"] = []
        av2["availability_context"] = None
        av2["active_goals"] = []
        av2["current_plan"] = None
        av2["last_next_best_action"] = None
        av2["last_updated"] = datetime.datetime.now(TIMEZONE).isoformat()

    update_conversation_state(
        telefono_key,
        agent_v2=av2 if av2 else state.get("agent_v2"),
        fase="inicial",
        dia_propuesto=None,
        hora_propuesta=None,
        cancha_propuesta=None,
        canchas_libres=[],
        senia_estado="",
        senia_monto="",
        con_quincho=False,
        quincho="",
        quincho_hora_inicio="",
        quincho_hora_fin="",
        quincho_duracion_horas=None,
        quincho_confirmacion_origen=None,
        seleccion_cancha_pendiente=None,
        consulta_disponibilidad_pendiente=None,
        aclaracion_hora_contexto=None,
        hora_opciones=[],
        fase_previa_hora=None,
        booking_draft=None,
    )
    print(
        f"   👻 [AgentV2 GHOST PURGE] calendar=0 → limpio draft/target/auth/pending "
        f"reason={reason}"
    )
    return get_conversation_state(telefono_key)


def _clear_matching_conversation_hold(row: Dict[str, Any]) -> None:
    telefono = _telefono_cliente_desde_reserva(row)
    if not telefono:
        return
    try:
        state = get_conversation_state(telefono)
        # Un hold vencido sólo puede limpiar el contexto que lo identifica de
        # forma concreta. Antes los valores vacíos eran comodines: un hold viejo
        # de cualquier horario hacía purge de *todas* las preguntas pendientes,
        # incluida una CTA reciente de dos canchas que aún no tiene slot.
        proposed_day = state.get("dia_propuesto")
        proposed_hour = normalizar_hora_detectada(state.get("hora_propuesta"))
        proposed_court = str(state.get("cancha_propuesta") or "").strip()
        if not (proposed_day and hora_es_valida(proposed_hour) and proposed_court):
            print(
                "   🛡️ [HOLD LEASE] hold vencido sin contexto de slot coincidente "
                "→ conservo preguntas pendientes"
            )
            return
        same_day = _misma_fecha_reserva(
            {"fecha": proposed_day},
            row.get("fecha") or "",
        )
        same_hour = proposed_hour == normalizar_hora_detectada(row.get("hora"))
        same_court = proposed_court.casefold() == str(row.get("cancha") or "").strip().casefold()
        if same_day and same_hour and same_court:
            _purge_transient_booking_context_after_missing_reservation(
                telefono,
                reason="hold_lease_expired",
            )
    except Exception as e:
        print(f"   ⚠️ [HOLD LEASE] no pude limpiar contexto conversacional: {e}")


def _release_pending_hold_exact(row: Dict[str, Any]) -> Dict[str, Any]:
    """
    Elimina únicamente el bloque temporal pendiente de seña.

    Revalida dentro del lock que siga pendiente antes de tocar el calendario.
    Esto evita liberar un slot que haya sido confirmado justo antes del sweep.
    """
    target = dict(row or {})
    if not target:
        return {"ok": False, "reason": "empty_target", "removed": 0}

    duration = normalizar_duracion_horas(
        target.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    slots = set(slots_para_bloque(target.get("hora"), duration))
    if not slots:
        slots = {normalizar_hora_detectada(target.get("hora"))}

    ctx = calendario.atomic() if hasattr(calendario, "atomic") else contextlib.nullcontext()
    with ctx:
        rows = calendario._leer_todos()

        # El slot líder debe seguir existiendo y seguir siendo temporal.
        leader = next((
            current for current in rows
            if _hold_identity_matches(current, target)
        ), None)
        if not leader:
            return {"ok": False, "reason": "hold_not_found", "removed": 0}
        if not _pending_hold_row_is_temporary(leader):
            return {
                "ok": False,
                "reason": "hold_no_longer_pending",
                "removed": 0,
                "current": leader,
            }

        fecha_target = _parse_fecha_row(target.get("fecha") or target.get("dia"))
        target_tel = normalize_phone(target.get("telefono") or "")
        target_name = str(target.get("nombre") or "").strip().casefold()
        target_court = str(target.get("cancha") or "").strip().casefold()

        kept = []
        removed_rows = []
        for current in rows:
            current_date = _parse_fecha_row(current.get("fecha"))
            same_date = bool(fecha_target and current_date and fecha_target == current_date)
            same_hour = normalizar_hora_detectada(current.get("hora")) in slots
            same_court = (
                str(current.get("cancha") or "").strip().casefold()
                == target_court
            )
            current_tel = normalize_phone(current.get("telefono") or "")
            current_name = str(current.get("nombre") or "").strip().casefold()
            same_owner = (
                (target_tel and current_tel and target_tel == current_tel)
                or (
                    not target_tel
                    and target_name
                    and current_name == target_name
                )
            )
            is_target_slot = (
                same_date and same_hour and same_court and same_owner
                and _pending_hold_row_is_temporary(current)
            )

            if is_target_slot:
                removed_rows.append(dict(current))
                current["estado"] = "hold_expirado"
                current["notas"] = (
                    str(current.get("notas") or "").strip()
                    + f" | hold liberado tras {PENDING_DEPOSIT_HOLD_MINUTES} minutos"
                ).strip(" |")
                kept.append(current)
            else:
                kept.append(current)

        if not removed_rows:
            return {"ok": False, "reason": "nothing_to_release", "removed": 0}

        # La fila deja de ocupar agenda pero conserva su ID y datos exactos para
        # una eventual confirmación presencial tardía del administrador.
        calendario._escribir_todos(kept, ordenar=True)

    return {
        "ok": True,
        "reason": "hold_expired",
        "removed": len(removed_rows),
        "rows": removed_rows,
        "target": target,
    }


def _promote_paid_hold_to_reserved(
    reserva: Dict[str, Any],
    telefono: str = "",
    nombre: str = "",
    monto: str = "",
    payment_method: str = "",
    note: str = "",
    monto_pendiente: Optional[int] = None,
    senia_pagada_monto: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Pago validado -> lease temporal se convierte en reserva permanente.

    Promueve TODO el bloque, no solo la primera fila de una reserva multi-hora.
    """
    target = dict(reserva or {})
    if not target:
        return {"ok": False, "reason": "empty_target"}

    target.setdefault("telefono", telefono)
    target.setdefault("nombre", nombre)
    duration = normalizar_duracion_horas(
        target.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    slots = set(slots_para_bloque(target.get("hora"), duration))
    if not slots:
        slots = {normalizar_hora_detectada(target.get("hora"))}

    fecha_target = _parse_fecha_row(target.get("fecha") or target.get("dia"))
    target_tel = normalize_phone(target.get("telefono") or telefono or "")
    target_name = str(target.get("nombre") or nombre or "").strip().casefold()
    target_court = str(target.get("cancha") or "").strip().casefold()

    promoted = []
    ctx = calendario.atomic() if hasattr(calendario, "atomic") else contextlib.nullcontext()
    with ctx:
        rows = calendario._leer_todos()
        changed = False

        for current in rows:
            current_date = _parse_fecha_row(current.get("fecha"))
            same_date = bool(fecha_target and current_date and fecha_target == current_date)
            same_hour = normalizar_hora_detectada(current.get("hora")) in slots
            same_court = (
                str(current.get("cancha") or "").strip().casefold()
                == target_court
            )
            current_tel = normalize_phone(current.get("telefono") or "")
            current_name = str(current.get("nombre") or "").strip().casefold()
            same_owner = (
                (target_tel and current_tel and target_tel == current_tel)
                or (
                    not target_tel
                    and target_name
                    and current_name == target_name
                )
            )

            if not (same_date and same_hour and same_court and same_owner):
                continue

            current["estado"] = BOOKING_STATUS_RESERVED
            current["senia_estado"] = "pagada"
            if monto:
                current["senia_monto"] = monto
            paid_amount = (
                max(0, int(senia_pagada_monto))
                if senia_pagada_monto is not None
                else _monto_a_int(monto)
            )
            if paid_amount is not None:
                current["senia_pagada_monto"] = str(paid_amount)
                current["senia_pendiente_monto"] = "0"
                current["senia_efectivo_pendiente"] = ""
            if monto_pendiente is not None:
                current["monto_pendiente"] = str(max(0, int(monto_pendiente)))
            if payment_method:
                current["payment_method"] = payment_method
            if note:
                current["notas"] = (
                    str(current.get("notas") or "").strip() + f" | {note}"
                ).strip(" |")
            promoted.append(dict(current))
            changed = True

        if changed:
            calendario._escribir_todos(rows, ordenar=True)

    if promoted:
        # El lease se identifica por el primer slot.
        _clear_pending_hold_tracking(target)
        print(
            f"   🔒 [HOLD → CONFIRMED] comprobante validado → reserva permanente "
            f"{target.get('fecha') or target.get('dia')} {target.get('hora')} "
            f"{target.get('cancha')} slots={len(promoted)}"
        )
        return {"ok": True, "rows": promoted}

    return {"ok": False, "reason": "reservation_not_found_after_payment"}


async def expirar_holds_senia_vencidos(
    page=None,
    force: bool = False,
) -> Dict[str, Any]:
    """
    Sweeper crítico independiente de PROACTIVE_TASK_INTERVAL_SECONDS.

    La liberación del calendario no depende de la navegación de WhatsApp. Si no
    recibe una página, encola el aviso de forma durable para enviarlo cuando el
    router confirme que el inbox está libre.
    """
    global _LAST_PENDING_HOLD_SWEEP_TS

    now_ts = time.time()
    if (
        not force
        and now_ts - _LAST_PENDING_HOLD_SWEEP_TS
        < PENDING_HOLD_SWEEP_INTERVAL_SECONDS
    ):
        return {"ok": True, "expired": 0, "throttled": True}
    _LAST_PENDING_HOLD_SWEEP_TS = now_ts

    now = datetime.datetime.now(TIMEZONE)
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    pending_seen = state.setdefault("pending_deposit_seen_at", {})
    holds = state.setdefault("pending_deposit_holds", {})

    # El sweeper solo necesita filas pendientes. No construir el dashboard
    # operativo completo (que además calcula disponibilidad de hoy/mañana) en
    # cada turno reactivo.
    try:
        pending_rows = [
            row for row in (calendario.listar_reservas() or [])
            if _pending_hold_row_is_temporary(row)
        ]
    except Exception as e:
        print(f"   ⚠️ [HOLD LEASE] no pude leer reservas pendientes: {e}")
        pending_rows = []
    expired = []
    live_keys = set()

    for row in pending_rows:
        if not _pending_hold_row_is_temporary(row):
            continue

        key = _pending_hold_key(row)
        live_keys.add(key)

        started_at = _pending_hold_started_at_from_state(state, row)
        if not started_at:
            started_at = now
            pending_seen[key] = started_at.isoformat()
            holds[key] = {
                "started_at": started_at.isoformat(),
                "expires_at": (
                    started_at
                    + datetime.timedelta(minutes=PENDING_DEPOSIT_HOLD_MINUTES)
                ).isoformat(),
                "reserva": {
                    "telefono": row.get("telefono"),
                    "nombre": row.get("nombre"),
                    "fecha": row.get("fecha"),
                    "hora": row.get("hora"),
                    "cancha": row.get("cancha"),
                    "duracion_horas": row.get("duracion_horas"),
                },
            }

        if not _pending_hold_is_expired(started_at, now):
            continue

        result = _release_pending_hold_exact(row)
        if result.get("reason") == "hold_no_longer_pending":
            # La seña pudo validarse entre lectura y lock.
            _clear_pending_hold_tracking(row, state=state, persist=False)
            continue
        if not result.get("ok"):
            continue

        _clear_pending_hold_tracking(row, state=state, persist=False)
        _clear_matching_conversation_hold(row)
        expired.append(row)
        discarded_admin_alerts = _discard_pending_booking_admin_alerts_for_reservation(
            state,
            row.get("reservation_id"),
            reason="pending_hold_expired",
        )
        if discarded_admin_alerts:
            print(
                "   🧹 [PENDING ADMIN ALERT] "
                f"descarté {discarded_admin_alerts} entrega(s) de la reserva "
                f"ID={row.get('reservation_id')} porque venció el hold"
            )
        notification_key = _queue_pending_hold_expiration_notification(
            state,
            row,
            started_at,
            now,
        )
        registrar_hold_expirado_para_pago_tardio(row, now)

        age_minutes = int((now - started_at).total_seconds() // 60)
        print(
            f"   ⏳ [HOLD EXPIRED] liberado automáticamente tras "
            f"{age_minutes} min: {row.get('fecha')} {row.get('hora')} "
            f"{row.get('cancha')} - {row.get('nombre') or row.get('telefono')}"
        )
        registrar_metrica_operativa("senia_hold_10m_expirado", {
            "reserva": row,
            "minutos_limite": PENDING_DEPOSIT_HOLD_MINUTES,
            "edad_minutos": age_minutes,
            "slots_liberados": result.get("removed"),
            "notification_key": notification_key,
        })

    # Limpiar leases ya inexistentes/pagados.
    pending_keys_now = {
        _pending_hold_key(row)
        for row in pending_rows
        if _pending_hold_row_is_temporary(row)
    }
    for old_key in list(pending_seen.keys()):
        if old_key not in pending_keys_now and old_key not in live_keys:
            pending_seen.pop(old_key, None)
            holds.pop(old_key, None)

    state["updated_at"] = now.isoformat()
    _json_write(PROACTIVE_STATE_FILE, state)
    delivery = {"sent": 0, "pending": len(
        state.get("pending_hold_expiration_notifications") or {}
    )}
    if page is not None:
        delivery = await enviar_notificaciones_holds_senia_vencidos(page)
    return {
        "ok": True,
        "expired": len(expired),
        "rows": expired,
        "notifications": delivery,
    }


def registrar_inicio_senia_pendiente(row: Dict[str, Any]) -> None:
    """
    Crea/reinicia el lease temporal EXACTAMENTE cuando se escribe una nueva
    reserva pendiente de seña.
    """
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    pending_seen = state.setdefault("pending_deposit_seen_at", {})
    holds = state.setdefault("pending_deposit_holds", {})
    key = _pending_hold_key(row)
    now = datetime.datetime.now(TIMEZONE)

    discarded_notices = _discard_stale_hold_expiration_notifications(state, row)
    if discarded_notices:
        print(
            f"   🧹 [HOLD NOTICE] descarto {discarded_notices} aviso(s) viejo(s) "
            "porque el turno volvió a bloquearse"
        )

    # No setdefault: si el mismo slot fue liberado y se vuelve a pedir, nace un lease nuevo.
    pending_seen[key] = now.isoformat()
    holds[key] = {
        "started_at": now.isoformat(),
        "expires_at": (
            now + datetime.timedelta(minutes=PENDING_DEPOSIT_HOLD_MINUTES)
        ).isoformat(),
        "reserva": {
            "telefono": row.get("telefono"),
            "nombre": row.get("nombre"),
            "fecha": row.get("fecha"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha"),
            "duracion_horas": row.get("duracion_horas"),
        },
    }
    state["updated_at"] = now.isoformat()
    _json_write(PROACTIVE_STATE_FILE, state)
    print(
        f"   ⏳ [HOLD LEASE] slot bloqueado temporalmente "
        f"{PENDING_DEPOSIT_HOLD_MINUTES} min → "
        f"{row.get('fecha')} {row.get('hora')} {row.get('cancha')}"
    )


def _parse_iso_datetime(value: str) -> Optional[datetime.datetime]:
    if not value:
        return None
    try:
        dt = datetime.datetime.fromisoformat(str(value))
        if dt.tzinfo is None:
            dt = TIMEZONE.localize(dt)
        return dt
    except Exception:
        return None


def _reserva_coincide_slot(reserva: Dict[str, Any], dia: str, hora: str, cancha: str = None) -> bool:
    if not reserva:
        return False
    fecha_reserva = _parse_fecha_row(reserva.get("fecha"))
    fecha_objetivo = _parse_fecha_row(dia) or _parse_fecha_row(resolver_fecha(dia))
    misma_fecha = fecha_reserva and fecha_objetivo and fecha_reserva == fecha_objetivo
    misma_hora = normalizar_hora_detectada(reserva.get("hora")) == normalizar_hora_detectada(hora)
    misma_cancha = not cancha or str(reserva.get("cancha") or "").strip().casefold() == str(cancha or "").strip().casefold()
    return bool(misma_fecha and misma_hora and misma_cancha)


def _telefono_cliente_desde_reserva(row: Dict[str, Any]) -> str:
    """Resuelve un teléfono real para una reserva sin modificar el estado conversacional."""
    telefono = str((row or {}).get("telefono") or "").strip()
    if telefono.startswith("NOMBRE:"):
        telefono = buscar_telefono_real_por_nombre_csv(
            telefono.replace("NOMBRE:", "").strip() or str((row or {}).get("nombre") or "")
        ) or ""
    if not telefono and (row or {}).get("nombre"):
        telefono = buscar_telefono_real_por_nombre_csv(str((row or {}).get("nombre") or "")) or ""
    return normalize_phone(telefono)


async def cliente_tiene_entrada_pendiente(page, row: Dict[str, Any]) -> bool:
    """
    Barrera transaccional para acciones proactivas.

    Antes de enviar un recordatorio, liberar una seña o ejecutar cualquier acción
    autónoma sobre un cliente, abre su chat y verifica si existe entrada del usuario
    todavía no procesada. Si existe, la acción proactiva DEBE ceder prioridad al inbox.
    """
    telefono = _telefono_cliente_desde_reserva(row)
    if not telefono or telefono.startswith("NOMBRE:"):
        return False
    try:
        await page.goto(f"https://web.whatsapp.com/send?phone={telefono.replace('+', '')}&text=")
        await asyncio.sleep(2.0)
        if await has_unread_user_messages(page):
            print(
                f"   🚦 [PRIORIDAD INBOX] {telefono} tiene mensajes pendientes → "
                "acción proactiva pospuesta"
            )
            _mark_reactive_handoff(
                telefono,
                "cliente_tiene_entrada_pendiente",
            )
            registrar_metrica_operativa("proactivo_pospuesto_por_entrada_pendiente", {
                "telefono": telefono,
                "fecha": (row or {}).get("fecha"),
                "hora": (row or {}).get("hora"),
                "cancha": (row or {}).get("cancha"),
            })
            return True
        return False
    except Exception as e:
        # Fail-safe: ante una duda de lectura no hacemos una acción autónoma que pueda
        # pisar la conversación o cancelar una reserva legítima.
        print(f"   ⚠️ [PRIORIDAD INBOX] No pude verificar inbox de {telefono}: {e} → pospongo proactivo")
        registrar_metrica_operativa("proactivo_pospuesto_por_error_inbox", {
            "telefono": telefono,
            "error": str(e),
            "reserva": row,
        })
        return True


async def enviar_mensaje_cliente_por_reserva(
    page,
    row: Dict[str, Any],
    texto: str,
    respetar_inbox: bool = True,
    respetar_pausa: bool = True,
) -> bool:
    telefono = _telefono_cliente_desde_reserva(row)
    if not telefono or telefono.startswith("NOMBRE:"):
        registrar_metrica_operativa("aviso_cliente_senia_expirada_sin_telefono", {"reserva": row})
        return False
    if respetar_pausa and obtener_pausa_contacto_humano(telefono):
        print(f"[PAUSA HUMANA] aviso al cliente {telefono} pospuesto sin abrir su chat")
        return False
    try:
        await page.goto(f"https://web.whatsapp.com/send?phone={telefono.replace('+', '')}&text=")
        await asyncio.sleep(2.0)

        # Última barrera antes del message-out: si el cliente escribió mientras el
        # proactivo se preparaba, NO enviamos nada. Su mensaje debe pasar primero por
        # el router reactivo/multi-intent.
        if respetar_inbox and await has_unread_user_messages(page):
            print(
                f"   🚦 [PRIORIDAD INBOX] No envío proactivo a {telefono}: "
                "hay mensajes del usuario sin procesar"
            )
            _mark_reactive_handoff(
                telefono,
                "enviar_mensaje_cliente_por_reserva",
            )
            registrar_metrica_operativa("proactivo_envio_bloqueado_por_inbox", {
                "telefono": telefono,
                "texto": str(texto or "")[:500],
                "reserva": row,
            })
            return False

        await send_message(page, texto)
        registrar_metrica_operativa("aviso_cliente_senia_expirada_enviado", {
            "telefono": telefono,
            "fecha": row.get("fecha"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha")
        })
        return True
    except Exception as e:
        print(f"[PROACTIVO] No pude avisar al cliente por seña expirada: {e}")
        registrar_metrica_operativa("aviso_cliente_senia_expirada_error", {"error": str(e), "reserva": row})
        return False


async def enviar_notificaciones_holds_senia_vencidos(
    page,
    max_notifications: int = 3,
) -> Dict[str, Any]:
    """
    Envía avisos de holds vencidos previamente encolados.

    Invariante nuevo:
    si el mensaje contiene una oferta de volver a bloquear el turno,
    esa oferta se registra como pending_decision SOLAMENTE después de
    que WhatsApp confirmó el envío.

    Nunca se registra una pregunta que el usuario no recibió.
    """
    snapshot = _json_read(
        PROACTIVE_STATE_FILE,
        {"sent": {}},
    )

    queued = (
        snapshot.get(
            "pending_hold_expiration_notifications"
        )
        or {}
    )

    ordered = sorted(
        queued.items(),
        key=lambda item: str(
            (
                item[1]
                or {}
            ).get("queued_at")
            or ""
        ),
    )

    # Un contacto pausado no consume cupo
    # ni bloquea avisos de otros clientes.
    ordered = [
        item
        for item in ordered
        if not obtener_pausa_contacto_humano(
            _telefono_cliente_desde_reserva(
                (
                    item[1]
                    or {}
                ).get("row")
                or {}
            )
        )
    ]

    sent_count = 0

    for (
        notification_key,
        payload,
    ) in ordered[
        :max(
            1,
            int(
                max_notifications
                or 1
            ),
        )
    ]:
        payload = (
            payload
            if isinstance(payload, dict)
            else {}
        )

        row = dict(
            payload.get("row")
            or {}
        )

        message = str(
            payload.get("message")
            or ""
        ).strip()

        if not row or not message:
            latest = _json_read(
                PROACTIVE_STATE_FILE,
                {"sent": {}},
            )

            latest.setdefault(
                "pending_hold_expiration_notifications",
                {},
            ).pop(
                notification_key,
                None,
            )

            latest["updated_at"] = (
                datetime.datetime.now(
                    TIMEZONE
                ).isoformat()
            )

            _json_write(
                PROACTIVE_STATE_FILE,
                latest,
            )
            continue

        sent = (
            await enviar_mensaje_cliente_por_reserva(
                page,
                row,
                message,
                respetar_inbox=True,
            )
        )

        # Releer después del await porque el reloj puede
        # haber encolado otros eventos mientras WhatsApp navegaba.
        latest = _json_read(
            PROACTIVE_STATE_FILE,
            {"sent": {}},
        )

        latest_queue = latest.setdefault(
            "pending_hold_expiration_notifications",
            {},
        )

        current = latest_queue.get(
            notification_key
        )

        if sent:
            # =====================================================
            # STATEFUL OFFER
            # =====================================================
            #
            # El mensaje REALMENTE salió.
            # Ahora sí existe una pregunta del agente que el usuario
            # puede responder semánticamente.
            #
            # NO analizamos la futura respuesta acá.
            # NO regex.
            # NO keyword matching.
            # =====================================================

            try:
                _agent_v2_register_released_booking_rebook_offer_after_send(
                    row=row,
                    message=message,
                    expired_at=(
                        payload.get("queued_at")
                        or datetime.datetime.now(
                            TIMEZONE
                        )
                    ),
                )
            except Exception as e:
                print(
                    "   ⚠️ [AgentV2 PROACTIVE OFFER] "
                    "aviso enviado pero no pude registrar "
                    f"pending_decision: {e}"
                )

                # Como el mensaje sí fue enviado, conservarlo al menos
                # en historial para no perder la realidad conversacional.
                try:
                    telefono = (
                        _telefono_reserva_para_mensaje(
                            row
                        )
                    )

                    if telefono:
                        add_to_history(
                            telefono,
                            "assistant",
                            message,
                        )
                except Exception:
                    pass

            latest_queue.pop(
                notification_key,
                None,
            )

            sent_count += 1

            print(
                "   ✅ [HOLD NOTICE] "
                "aviso de liberación enviado + "
                "oferta stateful registrada"
            )

            registrar_metrica_operativa(
                "senia_hold_10m_aviso_enviado",
                {
                    "notification_key": (
                        notification_key
                    ),
                    "reserva": row,
                    "stateful_offer": (
                        "released_booking_rebook"
                    ),
                },
            )

        elif isinstance(
            current,
            dict,
        ):
            current["attempts"] = (
                int(
                    current.get(
                        "attempts"
                    )
                    or 0
                )
                + 1
            )

            current["last_attempt_at"] = (
                datetime.datetime.now(
                    TIMEZONE
                ).isoformat()
            )

            latest_queue[
                notification_key
            ] = current

        latest["updated_at"] = (
            datetime.datetime.now(
                TIMEZONE
            ).isoformat()
        )

        _json_write(
            PROACTIVE_STATE_FILE,
            latest,
        )

        if (
            not sent
            or _reactive_handoff_pending()
        ):
            break

    final_state = _json_read(
        PROACTIVE_STATE_FILE,
        {"sent": {}},
    )

    pending_count = len(
        final_state.get(
            "pending_hold_expiration_notifications"
        )
        or {}
    )

    return {
        "ok": True,
        "sent": sent_count,
        "pending": pending_count,
    }


def _authorized_alert_recipients() -> List[str]:
    """Lista viva, ordenada y sin duplicados de destinatarios administrativos."""
    recipients = []
    configured = list(AUTHORIZED_NUMBERS or [])
    if AUTHORIZED_NUMBER:
        configured.insert(0, AUTHORIZED_NUMBER)
    for raw in configured:
        phone = normalize_phone(raw)
        if phone and phone not in recipients:
            recipients.append(phone)
    return recipients


def _admin_alert_delivery_id(category: str, batch_key: str, recipient: str) -> str:
    raw_id = f"{category}|{batch_key}|{recipient}"
    return "admin_alert_" + hashlib.sha256(raw_id.encode("utf-8")).hexdigest()[:24]


def _pending_booking_admin_alert_reservation_id(item: Dict[str, Any]) -> str:
    item = item or {}
    if str(item.get("category") or "").strip() not in {
        "pending_booking_created",
        "pending_booking_rescheduled",
    }:
        return ""
    context = item.get("context")
    if isinstance(context, dict) and context.get("reservation_id"):
        return str(context.get("reservation_id") or "").strip()
    batch_key = str(item.get("batch_key") or "").strip()
    match = re.match(r"^(?:pending_booking|pending_reprogram):([^:]+)(?::|$)", batch_key)
    return str(match.group(1) if match else "").strip()


def _archive_admin_alert_queue_item(
    state: Dict[str, Any],
    delivery_id: str,
    item: Dict[str, Any],
    *,
    bucket: str,
    reason: str,
) -> None:
    archive = state.setdefault(bucket, {})
    archived = dict(item or {})
    archived["resolved_at"] = datetime.datetime.now(TIMEZONE).isoformat()
    archived["resolution_reason"] = str(reason or "")
    archive[delivery_id] = archived
    if len(archive) > 500:
        oldest = sorted(
            archive,
            key=lambda key: str((archive.get(key) or {}).get("resolved_at") or ""),
        )[:len(archive) - 500]
        for old_id in oldest:
            archive.pop(old_id, None)


def _discard_pending_booking_admin_alerts_for_reservation(
    state: Dict[str, Any],
    reservation_id: str,
    *,
    reason: str,
) -> int:
    target_id = str(reservation_id or "").strip()
    if not target_id:
        return 0
    queue = state.setdefault("admin_alert_queue", {})
    discarded = 0
    for delivery_id, item in list(queue.items()):
        if _pending_booking_admin_alert_reservation_id(item) != target_id:
            continue
        queue.pop(delivery_id, None)
        _archive_admin_alert_queue_item(
            state,
            delivery_id,
            item,
            bucket="admin_alert_discarded",
            reason=reason,
        )
        discarded += 1
    return discarded


def _active_pending_booking_reservation_ids() -> Optional[set]:
    try:
        rows = calendario.asegurar_ids_reservas_pendientes() or []
    except Exception as exc:
        print(f"   ⚠️ [ADMIN ALERT QUEUE] no pude validar reservas pendientes: {exc}")
        return None
    return {
        str(row.get("reservation_id") or "").strip()
        for row in rows
        if isinstance(row, dict)
        and _pending_hold_row_is_temporary(row)
        and str(row.get("reservation_id") or "").strip()
    }


def _prune_stale_pending_booking_admin_alerts(
    state: Dict[str, Any],
    active_ids: Optional[set] = None,
) -> int:
    resolved_active_ids = (
        active_ids
        if active_ids is not None
        else _active_pending_booking_reservation_ids()
    )
    if resolved_active_ids is None:
        return 0
    queue = state.setdefault("admin_alert_queue", {})
    discarded = 0
    for delivery_id, item in list(queue.items()):
        reservation_id = _pending_booking_admin_alert_reservation_id(item)
        if not reservation_id or reservation_id in resolved_active_ids:
            continue
        queue.pop(delivery_id, None)
        _archive_admin_alert_queue_item(
            state,
            delivery_id,
            item,
            bucket="admin_alert_discarded",
            reason="pending_booking_no_longer_active",
        )
        discarded += 1
    if discarded:
        print(
            "   🧹 [ADMIN ALERT QUEUE] "
            f"descarté {discarded} alerta(s) de reservas que ya no están pendientes"
        )
    return discarded


def _admin_alert_retry_delay_seconds(item: Dict[str, Any]) -> int:
    attempts = max(0, int((item or {}).get("attempts") or 0))
    if attempts <= 0:
        return 0
    return min(
        ADMIN_ALERT_RETRY_MAX_SECONDS,
        ADMIN_ALERT_RETRY_BASE_SECONDS * (2 ** min(attempts - 1, 10)),
    )


def _admin_alert_retry_is_due(
    item: Dict[str, Any],
    now: Optional[datetime.datetime] = None,
) -> bool:
    attempts = max(0, int((item or {}).get("attempts") or 0))
    if attempts <= 0:
        return True
    last_attempt = _parse_iso_datetime((item or {}).get("last_attempt_at"))
    if not last_attempt:
        return True
    current = now or datetime.datetime.now(TIMEZONE)
    return current >= last_attempt + datetime.timedelta(
        seconds=_admin_alert_retry_delay_seconds(item)
    )


_ADMIN_ALERT_QUICK_COMMANDS_MARKER = "🧰 *COMANDOS ÚTILES*"


def build_admin_alert_quick_commands(
    telefono: str = "",
    reservation_id: Any = "",
    context_kind: str = "",
) -> str:
    """Atajos operativos que acompañan las alertas enviadas al encargado."""
    if str(context_kind or "").strip().casefold() in {
        "event_registration_pending", "event_registration_confirmed",
    }:
        registration_id = str(reservation_id or "").strip()
        admin_id = (
            _event_registration_admin_public_id(registration_id, create=True)
            if registration_id else ""
        )
        display_id = str(admin_id or registration_id).strip()
        commands = [_ADMIN_ALERT_QUICK_COMMANDS_MARKER]
        if display_id:
            commands.extend([
                f"• Ver la inscripción: `ver ID {display_id}`",
                f"• Confirmar la seña/efectivo recibido: `confirmar seña ID {display_id}`",
                f"• Confirmar el pago total: `confirmar total ID {display_id}`",
                f"• Liberar el cupo: `liberar ID {display_id}`",
            ])
        commands.extend([
            "• Ver torneos y cupos: `listar torneos`",
            "• Ver casos abiertos: `casos pendientes`",
            "• Comprobar la IA: `estado agente`",
            "• Ver todos los comandos: `ayuda torneos`",
        ])
        return "\n".join(commands)
    raw_phone = str(telefono or "").strip()
    normalized_phone = normalize_phone(raw_phone)
    phone_digits = re.sub(r"\D", "", normalized_phone or "")
    if (
        normalized_phone
        and not normalized_phone.startswith("NOMBRE:")
        and len(phone_digits) >= 8
    ):
        block_line = (
            "• Bloquear este contacto: "
            f"`bloquear {normalized_phone}`"
        )
        unblock_line = (
            "• Desbloquear este contacto: "
            f"`desbloquear {normalized_phone}`"
        )
        no_show_target = normalized_phone
    else:
        block_line = "• Bloquear un contacto: `bloquear [número o nombre]`"
        unblock_line = "• Desbloquear un contacto: `desbloquear [número o nombre]`"
        no_show_target = "[nombre o teléfono]"

    booking_id = str(reservation_id or "").strip()
    pending_label = (
        f"• Revisar pendientes (ID {booking_id}): `mostrar pendientes`"
        if booking_id
        else "• Revisar reservas pendientes: `mostrar pendientes`"
    )
    commands = [
        _ADMIN_ALERT_QUICK_COMMANDS_MARKER,
        pending_label,
    ]
    if booking_id:
        commands.extend([
            f"• Ver el detalle: `ver ID {booking_id}`",
            f"• Registrar la seña: `confirmar seña ID {booking_id}`",
            f"• Registrar el pago total: `confirmar total ID {booking_id}`",
            f"• Agregar quincho/parrilla: `agregar quincho ID {booking_id}`",
            f"• Mover el turno: `mover ID {booking_id} [día] [hora]`",
            f"• Cancelar el turno: `cancelar ID {booking_id} [motivo]`",
            f"• Liberar un pendiente: `liberar ID {booking_id}`",
        ])
    if str(context_kind or "").strip().casefold() in {
        "attendance", "attendance_pending", "no_show",
    }:
        commands.append(
            "• Si finalmente no asiste: "
            f"`no vino {no_show_target}`"
        )

    commands.extend([
        "• Turnos de hoy: `agenda hoy`",
        "• Turnos de mañana: `agenda mañana`",
        "• Horas disponibles hoy: `horarios libres hoy`",
        (
            "• Agregar una reserva manual: "
            "`agregar reserva [día] [hora] [cancha] [nombre]`"
        ),
        block_line,
        unblock_line,
        "• Ver casos abiertos: `casos pendientes`",
        "• Comprobar la IA: `estado agente`",
    ])
    if not getattr(bot_state, "is_active", True):
        commands.append("• Reactivar la IA general: `reanudar agente`")
    commands.extend([
        "• Ver todos los comandos: `ayuda`",
    ])
    return "\n".join(commands)


def _with_admin_alert_quick_commands(
    texto: str,
    telefono: str = "",
    reservation_id: Any = "",
    context_kind: str = "",
) -> str:
    text = str(texto or "").strip()
    if not text or _ADMIN_ALERT_QUICK_COMMANDS_MARKER in text:
        return text
    return (
        f"{text}\n\n"
        f"{build_admin_alert_quick_commands(telefono, reservation_id, context_kind)}"
    )


def _enqueue_admin_alert_batch(
    texto: str,
    *,
    category: str,
    dedupe_key: str = "",
    attachment_path: str = "",
    attachment_title: str = "",
    context: Optional[Dict[str, Any]] = None,
) -> List[str]:
    """Encola una copia durable por admin y devuelve sus IDs de entrega."""
    alert_context = dict(context or {})
    text = _with_admin_alert_quick_commands(
        texto,
        alert_context.get("telefono") or alert_context.get("phone") or "",
        alert_context.get("reservation_id")
        or alert_context.get("reserva_id")
        or alert_context.get("registration_id")
        or "",
        alert_context.get("context_kind") or category or "",
    )
    recipients = _authorized_alert_recipients()
    if not text or not recipients:
        return []

    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.setdefault("admin_alert_queue", {})
    sent_registry = state.setdefault("admin_alert_sent", {})
    batch_key = str(dedupe_key or uuid.uuid4().hex).strip()
    now_iso = datetime.datetime.now(TIMEZONE).isoformat()
    delivery_ids = []
    added_count = 0

    for recipient in recipients:
        delivery_id = _admin_alert_delivery_id(category, batch_key, recipient)
        delivery_ids.append(delivery_id)
        if delivery_id in sent_registry or delivery_id in queue:
            continue
        queue[delivery_id] = {
            "delivery_id": delivery_id,
            "batch_key": batch_key,
            "category": str(category or "admin_alert"),
            "recipient": recipient,
            "text": text,
            "attachment_path": str(attachment_path or ""),
            "attachment_title": str(attachment_title or ""),
            "context": alert_context,
            "text_sent": False,
            "attachment_title_sent": False,
            "attempts": 0,
            "created_at": now_iso,
            "last_attempt_at": None,
            "last_error": "",
        }
        added_count += 1

    state["updated_at"] = now_iso
    _json_write(PROACTIVE_STATE_FILE, state)
    if added_count:
        print(
            "   📥 [ADMIN ALERT QUEUE] "
            f"category={category} recipients={len(recipients)} "
            f"added={added_count} already_known={len(delivery_ids) - added_count}"
        )
    return delivery_ids


def _resolve_pending_booking_for_admin_alert(
    payload: Dict[str, Any],
    telefono: str = "",
    prospecto: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    """Reconcilia el resultado del tool con la fila pendiente real del calendario."""
    payload = dict(payload or {})
    nested = payload.get("reserva_verificada") or payload.get("reserva")
    source = dict(nested) if isinstance(nested, dict) else {}
    source.update(payload)
    requested_id = str(
        source.get("reservation_id") or source.get("reserva_id") or ""
    ).strip()
    phone = normalize_phone(
        source.get("telefono")
        or telefono
        or (prospecto or {}).get("telefono")
        or ""
    )
    name = str(
        source.get("nombre")
        or (prospecto or {}).get("nombre")
        or (prospecto or {}).get("negocio")
        or ""
    ).strip()
    day = str(source.get("fecha") or source.get("dia") or "").strip()
    hour = normalizar_hora_detectada(source.get("hora"))
    court = str(source.get("cancha") or "").strip()

    try:
        # La migración sólo agrega IDs. Releemos para obtener el slot real
        # post-WRITE, en vez de seleccionar una copia previa por ID.
        calendario.asegurar_ids_reservas_pendientes()
        rows = calendario.listar_reservas() or []
    except Exception as exc:
        print(f"   ⚠️ [PENDING ADMIN ALERT] no pude reconciliar calendario: {exc}")
        return None

    pending_rows = [
        dict(row) for row in rows
        if isinstance(row, dict) and _pending_hold_row_is_temporary(row)
    ]
    matches = []
    if requested_id:
        id_matches = [
            row for row in pending_rows
            if str(row.get("reservation_id") or "").strip() == requested_id
        ]
        if day and hora_es_valida(hour):
            matches = [
                row for row in id_matches
                if _reserva_coincide_slot(row, day, hour, court or None)
            ]
        if not matches and day:
            matches = [
                row for row in id_matches
                if _row_fecha_coincide_dia(row, day)
                and (not court or str(row.get("cancha") or "").strip().casefold()
                     == court.casefold())
            ]
        if not matches:
            matches = id_matches
    else:
      for row in pending_rows:
        row_phone = normalize_phone(row.get("telefono") or "")
        row_name = str(row.get("nombre") or "").strip().casefold()
        owner_matches = bool(
            (phone and row_phone == phone)
            or (name and row_name == name.casefold())
        )
        if not owner_matches:
            continue
        if day and not _row_fecha_coincide_dia(row, day):
            continue
        if hour and normalizar_hora_detectada(row.get("hora")) != hour:
            continue
        if court and str(row.get("cancha") or "").strip().casefold() != court.casefold():
            continue
        matches.append(row)

    if not matches:
        return None
    primary = sorted(matches, key=lambda row: (
        _parse_fecha_row(row.get("fecha")) or datetime.date.max,
        _hora_a_minutos_local(row.get("hora") or "")
        if _hora_a_minutos_local(row.get("hora") or "") is not None else 10**9,
    ))[0]
    reservation_id = str(primary.get("reservation_id") or "").strip()
    if not reservation_id:
        return None

    resolved = dict(primary)
    for key, value in source.items():
        if key in {"fecha", "dia", "hora", "cancha"}:
            continue
        if value is not None and value != "":
            resolved[key] = value
    resolved["reservation_id"] = reservation_id
    resolved["reserva_id"] = reservation_id
    resolved["fecha"] = primary.get("fecha") or source.get("fecha") or source.get("dia")
    resolved["hora"] = primary.get("hora") or source.get("hora")
    resolved["cancha"] = primary.get("cancha") or source.get("cancha")
    resolved["telefono"] = primary.get("telefono") or phone
    resolved["nombre"] = primary.get("nombre") or name or "Cliente"
    return resolved


def build_pending_booking_admin_alert(reserva: Dict[str, Any]) -> str:
    reservation_id = str(reserva.get("reservation_id") or "").strip()
    duration = normalizar_duracion_horas(
        reserva.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    total = _monto_a_int(reserva.get("precio_total"))
    deposit = _senia_guardada_o_configurada(reserva, total)
    balance = _monto_a_int(reserva.get("monto_pendiente"))
    if balance is None and total is not None:
        balance = calcular_monto_pendiente(total, deposit)
    payment_method = str(reserva.get("payment_method") or "").strip().lower()
    deposit_state = str(reserva.get("senia_estado") or "").strip().lower()
    cash = payment_method == "efectivo" or deposit_state == "pendiente_efectivo"
    payment_label = "Efectivo en el complejo" if cash else "Transferencia - comprobante pendiente"
    with_quincho = str(reserva.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1"
    }

    lines = [
        "⏳ *NUEVA RESERVA PENDIENTE*",
        "",
        f"🆔 *ID {reservation_id}*",
        f"👤 Cliente: {reserva.get('nombre') or 'Cliente'}",
        f"📱 Teléfono: {reserva.get('telefono') or 'No disponible'}",
        f"📅 Día: {reserva.get('fecha') or reserva.get('dia') or 'No disponible'}",
        (
            f"{_court_booking_summary_label(reserva.get('cancha') or 'No disponible')} "
            f"de {rango_horario_texto(reserva.get('hora'), duration)}"
        ),
        f"⏱️ Duración: {duration:g} hs",
    ]
    if with_quincho:
        lines.extend([
            "",
            (
                f"🔥 Quincho/parrilla: {reserva.get('quincho') or 'Quincho'} "
                f"de {rango_horario_texto(reserva.get('quincho_hora_inicio'), reserva.get('quincho_duracion_horas') or 1)}"
            ),
        ])
    lines.extend(["", f"💳 Medio de pago: {payment_label}"])
    if total is not None:
        lines.append(f"💰 Total: {_fmt_precio(total)}")
    lines.append(f"💵 Seña requerida: {_fmt_precio(deposit)}")
    if balance is not None:
        lines.append(f"💸 Saldo pendiente: {_fmt_precio(balance)}")
    lines.extend([
        "",
        f"⏳ El bloqueo vence a los {PENDING_DEPOSIT_HOLD_MINUTES} minutos si no se valida la seña.",
    ])
    return _with_admin_alert_quick_commands(
        "\n".join(lines),
        reserva.get("telefono") or "",
        reservation_id,
    )


def build_pending_multiple_booking_admin_alert(
    reservas: List[Dict[str, Any]],
    batch_data: Optional[Dict[str, Any]] = None,
) -> str:
    """Una única alerta factual para un batch de canchas/turnos pendientes."""
    rows = [dict(row) for row in (reservas or []) if isinstance(row, dict)]
    if not rows:
        return ""
    batch_data = dict(batch_data or {})
    primary = rows[0]
    ids = [str(row.get("reservation_id") or "").strip() for row in rows]
    ids = [reservation_id for reservation_id in ids if reservation_id]
    total = _monto_a_int(batch_data.get("precio_total"))
    if total is None:
        total = sum(_monto_a_int(row.get("precio_total")) or 0 for row in rows)
    deposit = _monto_a_int(batch_data.get("senia_monto"))
    if deposit is None:
        deposit = sum(
            _senia_guardada_o_configurada(
                row,
                _monto_a_int(row.get("precio_total")),
            )
            for row in rows
        )
    balance = _monto_a_int(batch_data.get("monto_pendiente"))
    if balance is None:
        balance = sum(
            _monto_a_int(row.get("monto_pendiente"))
            if _monto_a_int(row.get("monto_pendiente")) is not None
            else max(
                0,
                (_monto_a_int(row.get("precio_total")) or 0)
                - _senia_guardada_o_configurada(
                    row, _monto_a_int(row.get("precio_total"))
                ),
            )
            for row in rows
        )
    lines = [
        "⏳ *NUEVO BLOQUE DE RESERVAS PENDIENTES*",
        "",
        f"🆔 *IDs:* {', '.join(ids) or 'No disponibles'}",
        f"👤 Cliente: {primary.get('nombre') or 'Cliente'}",
        f"📱 Teléfono: {primary.get('telefono') or 'No disponible'}",
        f"📅 Día: {primary.get('fecha') or primary.get('dia') or 'No disponible'}",
        "⚽ Canchas bloqueadas:",
    ]
    for row in rows:
        duration = normalizar_duracion_horas(
            row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        lines.append(
            f"• {row.get('cancha') or 'Cancha'} de "
            f"{rango_horario_texto(row.get('hora'), duration)}"
        )
    lines.extend([
        "",
        "💳 Medio de pago: Transferencia - comprobante pendiente",
        f"💰 *Total del bloque:* {_fmt_precio(total)}",
        f"💵 *Seña total requerida:* {_fmt_precio(deposit)}",
        f"💸 *Saldo pendiente:* {_fmt_precio(balance)}",
        "",
        f"⏳ El bloqueo de ambas canchas vence a los {PENDING_DEPOSIT_HOLD_MINUTES} minutos si no se valida la seña.",
        "",
        "🧰 *ACCIONES:*",
        "Confirmar la seña para cada ID del bloque o liberarlos individualmente si corresponde.",
    ])
    return "\n".join(lines).strip()


def _pending_multiple_booking_admin_alert_batch_key(
    reservas: List[Dict[str, Any]],
) -> str:
    identity = [
        {
            "reservation_id": str(row.get("reservation_id") or "").strip(),
            "hold_key": _pending_hold_key(row),
        }
        for row in (reservas or [])
        if isinstance(row, dict)
    ]
    fingerprint = hashlib.sha256(
        json.dumps(identity, ensure_ascii=False, sort_keys=True).encode("utf-8")
    ).hexdigest()[:16]
    return f"pending_booking_batch:{fingerprint}"


def enqueue_pending_multiple_booking_admin_alert(
    payload: Dict[str, Any],
    telefono: str = "",
    prospecto: Optional[Dict[str, Any]] = None,
) -> List[str]:
    """Encola una sola alerta por destinatario para un batch pendiente."""
    payload = dict(payload or {})
    resolved_rows = []
    seen_ids = set()
    for row in (payload.get("reservas") or []):
        resolved = _resolve_pending_booking_for_admin_alert(row, telefono, prospecto)
        reservation_id = str((resolved or {}).get("reservation_id") or "").strip()
        if resolved and reservation_id and reservation_id not in seen_ids:
            seen_ids.add(reservation_id)
            resolved_rows.append(resolved)
    if len(resolved_rows) < 2:
        return []
    state_before = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    known_before = set((state_before.get("admin_alert_queue") or {}).keys()) | set(
        (state_before.get("admin_alert_sent") or {}).keys()
    )
    reservation_ids = [str(row.get("reservation_id") or "") for row in resolved_rows]
    delivery_ids = _enqueue_admin_alert_batch(
        build_pending_multiple_booking_admin_alert(resolved_rows, payload),
        category="pending_booking_created",
        dedupe_key=_pending_multiple_booking_admin_alert_batch_key(resolved_rows),
        attachment_path=BOOKINGS_CSV,
        attachment_title="📅 *CALENDARIO DE TURNOS*",
        context={
            "reservation_id": reservation_ids[0],
            "reservation_ids": reservation_ids,
            "hold_keys": [_pending_hold_key(row) for row in resolved_rows],
            "telefono": resolved_rows[0].get("telefono") or telefono or "",
            "context_kind": "pending_booking_multiple_created",
        },
    )
    added = [delivery_id for delivery_id in delivery_ids if delivery_id not in known_before]
    if added:
        print(
            "   📥 [PENDING ADMIN ALERT] "
            f"batch IDs={reservation_ids} encolado para {len(added)} admin(s)"
        )
    # Si una reconciliación alcanzó a encolar filas individuales antes de que el
    # post-response procesara el resultado multi, se reemplazan mientras aún
    # estén en cola. Nunca se borran alertas de otros IDs ni ya entregadas.
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.setdefault("admin_alert_queue", {})
    removed = 0
    covered = set(reservation_ids)
    for delivery_id, item in list(queue.items()):
        if not isinstance(item, dict):
            continue
        if str(item.get("category") or "") != "pending_booking_created":
            continue
        context = item.get("context") or {}
        individual_id = str(context.get("reservation_id") or "").strip()
        is_individual = not list(context.get("reservation_ids") or [])
        if is_individual and individual_id in covered:
            queue.pop(delivery_id, None)
            _archive_admin_alert_queue_item(
                state,
                delivery_id,
                item,
                bucket="admin_alert_discarded",
                reason="replaced_by_pending_booking_batch",
            )
            removed += 1
    if removed:
        state["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
        _json_write(PROACTIVE_STATE_FILE, state)
        print(
            "   🧹 [PENDING ADMIN ALERT] "
            f"batch reemplazó {removed} alerta(s) individual(es) en cola"
        )
    return delivery_ids


def _pending_booking_batch_covers_individual_alert(
    state: Dict[str, Any],
    item: Dict[str, Any],
) -> bool:
    """Indica si una alerta individual ya está representada por un batch."""
    if str((item or {}).get("category") or "") != "pending_booking_created":
        return False
    context = (item or {}).get("context") or {}
    reservation_id = str(context.get("reservation_id") or "").strip()
    if not reservation_id or context.get("reservation_ids"):
        return False
    recipient = normalize_phone((item or {}).get("recipient") or "")
    for registry_name in ("admin_alert_queue", "admin_alert_sent"):
        for candidate in ((state or {}).get(registry_name) or {}).values():
            if not isinstance(candidate, dict) or candidate is item:
                continue
            if str(candidate.get("category") or "") != "pending_booking_created":
                continue
            if normalize_phone(candidate.get("recipient") or "") != recipient:
                continue
            covered = {
                str(value or "").strip()
                for value in ((candidate.get("context") or {}).get("reservation_ids") or [])
            }
            if reservation_id in covered:
                return True
    return False


def build_pending_reprogram_admin_alert(data: Dict[str, Any]) -> str:
    """Alerta administrativa para una reserva pendiente reprogramada."""
    data = dict(data or {})
    nested = data.get("reserva_verificada") or data.get("reserva") or {}
    row = dict(nested) if isinstance(nested, dict) else {}
    row.update({key: value for key, value in data.items() if value not in (None, "")})
    reservation_id = str(row.get("reservation_id") or "").strip()
    duration = normalizar_duracion_horas(
        row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    total = _monto_a_int(row.get("precio_total"))
    deposit = _senia_guardada_o_configurada(row, total)
    paid = _senia_pagada_acumulada(row, total) if total is not None else 0
    balance = _monto_a_int(row.get("monto_pendiente"))
    if balance is None and total is not None:
        balance = max(0, total - paid)
    previous_day = data.get("previous_dia") or "No disponible"
    previous_hour = normalizar_hora_detectada(data.get("previous_hora"))
    previous_court = data.get("previous_cancha") or "No disponible"
    new_day = data.get("dia") or row.get("fecha") or row.get("dia") or "No disponible"
    new_hour = normalizar_hora_detectada(data.get("hora") or row.get("hora"))
    new_court = data.get("cancha") or row.get("cancha") or "No disponible"
    lines = ["🔄 *TURNO REPROGRAMADO*", ""]
    if reservation_id:
        lines.append(f"🆔 *Reserva ID:* {reservation_id}")
    lines.extend([
        f"👤 *Cliente:* {row.get('nombre') or 'Cliente'}",
        f"📱 *Teléfono:* {row.get('telefono') or 'No disponible'}", "",
        "⬅️ *ANTES*", f"📅 {previous_day}",
        (f"⚽ {previous_court} de {rango_horario_texto(previous_hour, duration)}"
         if hora_es_valida(previous_hour) else f"⚽ {previous_court}"), "",
        "➡️ *AHORA*", f"📅 {new_day}",
        (f"⚽ {new_court} de {rango_horario_texto(new_hour, duration)}"
         if hora_es_valida(new_hour) else f"⚽ {new_court}"),
        f"⏱️ *Duración:* {duration:g} hs", "",
    ])
    if total is not None:
        lines.append(f"💰 *Total del turno:* {_fmt_precio(total)}")
    lines.append(f"💵 *Seña requerida:* {_fmt_precio(deposit)}")
    if paid > 0:
        lines.append(f"💳 *Pagado hasta ahora:* {_fmt_precio(paid)}")
    if balance is not None:
        lines.append(f"💸 *Saldo pendiente:* {_fmt_precio(balance)}")
    state_label = {
        "pendiente": "Seña pendiente", "pendiente_efectivo": "Seña pendiente en efectivo",
        "parcial": "Seña parcialmente abonada", "pagada": "Seña pagada",
    }.get(str(row.get("senia_estado") or "pendiente").strip().casefold(), "Pendiente")
    lines.extend([f"📌 *Estado:* {state_label}", "",
                  "ℹ️ Es la misma reserva reprogramada: no se creó un turno nuevo ni una seña nueva."])
    return "\n".join(lines).strip()


def _pending_booking_admin_alert_batch_key(reserva: Dict[str, Any]) -> str:
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    started_at = _pending_hold_started_at_from_state(state, reserva or {})
    identity = {
        "reservation_id": str((reserva or {}).get("reservation_id") or "").strip(),
        "telefono": normalize_phone((reserva or {}).get("telefono") or ""),
        "fecha": str((reserva or {}).get("fecha") or (reserva or {}).get("dia") or "").strip(),
        "hora": normalizar_hora_detectada((reserva or {}).get("hora")),
        "cancha": str((reserva or {}).get("cancha") or "").strip().casefold(),
        "hold_started_at": started_at.isoformat() if started_at else "",
        "reservado_en": str((reserva or {}).get("reservado_en") or "").strip(),
    }
    fingerprint = hashlib.sha256(
        json.dumps(identity, ensure_ascii=False, sort_keys=True).encode("utf-8")
    ).hexdigest()[:16]
    return f"pending_booking:{identity['reservation_id']}:{fingerprint}"


def _legacy_pending_alert_ids_cover_current_hold(
    reserva: Dict[str, Any],
) -> List[str]:
    """Comprueba cobertura de alta o reprogramación del hold actual."""
    reservation_id = str((reserva or {}).get("reservation_id") or "").strip()
    if not reservation_id:
        return []
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.get("admin_alert_queue") or {}
    sent = state.get("admin_alert_sent") or {}

    # Un batch multi-cancha ya cubre cada uno de sus IDs. Sin esta verificación,
    # la reconciliación posterior a la escritura volvería a encolar alertas
    # individuales y rompería la unidad administrativa del bloque.
    batch_delivery_ids = []
    for recipient in _authorized_alert_recipients():
        candidates = []
        for registry_name, registry in (("queue", queue), ("sent", sent)):
            for delivery_id, item in registry.items():
                if not isinstance(item, dict):
                    continue
                if str(item.get("category") or "") != "pending_booking_created":
                    continue
                if normalize_phone(item.get("recipient") or "") != normalize_phone(recipient or ""):
                    continue
                context = item.get("context") or {}
                covered_ids = {
                    str(value or "").strip()
                    for value in (context.get("reservation_ids") or [])
                }
                if reservation_id not in covered_ids:
                    continue
                # Los IDs de reserva son durables y el batch enumera ambos.
                # Esa relación es una prueba más fuerte que el timestamp: el
                # scheduler puede reconciliar unos segundos después de crear
                # los holds y antes de enviar la alerta batch.
                event_time = _parse_iso_datetime(item.get(
                    "sent_at" if registry_name == "sent" else "created_at"
                )) or datetime.datetime.min.replace(tzinfo=TIMEZONE)
                candidates.append((event_time, delivery_id))
        if not candidates:
            batch_delivery_ids = []
            break
        batch_delivery_ids.append(max(candidates, key=lambda value: value[0])[1])
    if batch_delivery_ids:
        return batch_delivery_ids

    started_at = _pending_hold_started_at_from_state(state, reserva or {})
    if not started_at:
        return []
    tolerance = datetime.timedelta(seconds=5)

    delivery_ids = []
    for recipient in _authorized_alert_recipients():
        candidates = []
        for registry_name, registry in (("queue", queue), ("sent", sent)):
            for delivery_id, item in registry.items():
                if not isinstance(item, dict):
                    continue
                if str(item.get("category") or "") not in {
                    "pending_booking_created", "pending_booking_rescheduled",
                }:
                    continue
                if normalize_phone(item.get("recipient") or "") != normalize_phone(recipient or ""):
                    continue
                if _pending_booking_admin_alert_reservation_id(item) != reservation_id:
                    continue
                event_time = _parse_iso_datetime(item.get(
                    "sent_at" if registry_name == "sent" else "created_at"))
                if event_time and event_time + tolerance >= started_at:
                    candidates.append((event_time, delivery_id))
        if not candidates:
            return []
        delivery_ids.append(max(candidates, key=lambda value: value[0])[1])
    return delivery_ids


def enqueue_pending_booking_admin_alert(
    payload: Dict[str, Any],
    telefono: str = "",
    prospecto: Optional[Dict[str, Any]] = None,
) -> List[str]:
    """Encola el resumen pendiente después de que el cliente recibió la solicitud."""
    reserva = _resolve_pending_booking_for_admin_alert(
        payload,
        telefono,
        prospecto,
    )
    if not reserva:
        return []
    reservation_id = str(reserva.get("reservation_id") or "").strip()
    legacy_delivery_ids = _legacy_pending_alert_ids_cover_current_hold(reserva)
    if legacy_delivery_ids:
        return legacy_delivery_ids
    state_before = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    known_before = set((state_before.get("admin_alert_queue") or {}).keys()) | set(
        (state_before.get("admin_alert_sent") or {}).keys()
    )
    delivery_ids = _enqueue_admin_alert_batch(
        build_pending_booking_admin_alert(reserva),
        category="pending_booking_created",
        dedupe_key=_pending_booking_admin_alert_batch_key(reserva),
        attachment_path=BOOKINGS_CSV,
        attachment_title="📅 *CALENDARIO DE TURNOS*",
        context={
            "reservation_id": reservation_id,
            "hold_key": _pending_hold_key(reserva),
            "telefono": reserva.get("telefono") or telefono or "",
        },
    )
    added_delivery_ids = [
        delivery_id for delivery_id in delivery_ids
        if delivery_id not in known_before
    ]
    if added_delivery_ids:
        print(
            "   📥 [PENDING ADMIN ALERT] "
            f"reserva ID={reservation_id} encolada para "
            f"{len(added_delivery_ids)} admin(s)"
        )
        registrar_metrica_operativa(
            "reserva_pendiente_alerta_admin_encolada",
            {
                "reservation_id": reservation_id,
                "telefono": reserva.get("telefono"),
                "destinatarios": len(added_delivery_ids),
            },
        )
    return delivery_ids


def enqueue_pending_booking_admin_alerts_from_agent_result(
    agent_result: Dict[str, Any],
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    payloads = []
    multiple_batches = []
    for observation in (agent_result or {}).get("observations") or []:
        if not observation.get("ok"):
            continue
        data = observation.get("data") or {}
        if observation.get("tool") == "crear_reserva":
            payloads.append(data)
        elif observation.get("tool") == "crear_reservas_multiples":
            # Un batch es una sola decisión comercial: no aplanar sus filas en
            # dos alertas independientes. Conservamos los totales verificados
            # por Python y sus IDs para una única alerta administrativa.
            multiple_batches.append(dict(data))

    reservation_ids = set()
    delivery_ids = []
    for batch in multiple_batches:
        rows = list(batch.get("reservas") or [])
        batch_ids = {
            str(row.get("reservation_id") or "").strip()
            for row in rows if isinstance(row, dict)
        }
        batch_ids.discard("")
        ids = enqueue_pending_multiple_booking_admin_alert(
            batch, telefono, prospecto
        )
        if ids:
            reservation_ids.update(batch_ids)
            delivery_ids.extend(ids)
    for payload in payloads:
        resolved = _resolve_pending_booking_for_admin_alert(
            payload,
            telefono,
            prospecto,
        )
        reservation_id = str((resolved or {}).get("reservation_id") or "").strip()
        if not reservation_id or reservation_id in reservation_ids:
            continue
        reservation_ids.add(reservation_id)
        delivery_ids.extend(
            enqueue_pending_booking_admin_alert(resolved, telefono, prospecto)
        )
    return {
        "reservations": len(reservation_ids),
        "delivery_ids": delivery_ids,
    }


def enqueue_pending_reprogram_admin_alerts_from_agent_result(
    agent_result: Dict[str, Any],
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Encola una alerta propia sólo para reprogramaciones aún pendientes."""
    reservation_ids, delivery_ids = set(), []
    for observation in (agent_result or {}).get("observations") or []:
        if not (
            observation.get("tool") == "reprogramar_reserva"
            and observation.get("ok")
            and observation.get("status") == "success"
        ):
            continue
        data = dict(observation.get("data") or {})
        nested = data.get("reserva_verificada") or data.get("reserva") or {}
        final_row = dict(nested) if isinstance(nested, dict) else {}
        for source_key, row_key in (
            ("reservation_id", "reservation_id"), ("dia", "fecha"),
            ("hora", "hora"), ("cancha", "cancha"),
            ("duracion_horas", "duracion_horas"), ("senia_estado", "senia_estado"),
        ):
            if data.get(source_key) not in (None, ""):
                final_row[row_key] = data[source_key]
        final_row["telefono"] = final_row.get("telefono") or telefono or (prospecto or {}).get("telefono")
        final_row["nombre"] = final_row.get("nombre") or (prospecto or {}).get("nombre") or "Cliente"
        if not _pending_hold_row_is_temporary(final_row):
            continue
        reservation_id = str(final_row.get("reservation_id") or "").strip()
        if not reservation_id or reservation_id in reservation_ids:
            continue
        reservation_ids.add(reservation_id)
        state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
        discarded = _discard_pending_booking_admin_alerts_for_reservation(
            state, reservation_id,
            reason="pending_booking_reprogrammed_before_delivery",
        )
        if discarded:
            state["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            _json_write(PROACTIVE_STATE_FILE, state)
        identity = {
            "reservation_id": reservation_id,
            "previous_dia": data.get("previous_dia"),
            "previous_hora": normalizar_hora_detectada(data.get("previous_hora")),
            "previous_cancha": data.get("previous_cancha"),
            "dia": final_row.get("fecha"),
            "hora": normalizar_hora_detectada(final_row.get("hora")),
            "cancha": final_row.get("cancha"),
        }
        fingerprint = hashlib.sha256(json.dumps(identity, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]
        alert_data = {**data, "reserva_verificada": final_row}
        ids = _enqueue_admin_alert_batch(
            build_pending_reprogram_admin_alert(alert_data),
            category="pending_booking_rescheduled",
            dedupe_key=f"pending_reprogram:{reservation_id}:{fingerprint}",
            attachment_path=BOOKINGS_CSV,
            attachment_title="📅 *CALENDARIO DE TURNOS*",
            context={
                "reservation_id": reservation_id,
                "hold_key": _pending_hold_key(final_row),
                "telefono": final_row.get("telefono") or "",
                "context_kind": "pending_booking_rescheduled",
                "event_kind": "rescheduled",
            },
        )
        delivery_ids.extend(ids)
        print(f"   📥 [PENDING REPROGRAM ALERT] ID={reservation_id} encolada para {len(ids)} admin(s)")
    return {"reservations": len(reservation_ids), "delivery_ids": delivery_ids}


def reconcile_pending_booking_admin_alerts() -> Dict[str, int]:
    """Rehidrata alertas perdidas usando las reservas pendientes reales."""
    try:
        rows = calendario.asegurar_ids_reservas_pendientes() or []
    except Exception as exc:
        print(f"   ⚠️ [PENDING ADMIN ALERT] reconciliación fallida: {exc}")
        return {"reservations": 0, "added": 0}

    active_pending_ids = {
        str(row.get("reservation_id") or "").strip()
        for row in rows
        if isinstance(row, dict)
        and _pending_hold_row_is_temporary(row)
        and str(row.get("reservation_id") or "").strip()
    }
    before = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    discarded = _prune_stale_pending_booking_admin_alerts(
        before,
        active_ids=active_pending_ids,
    )
    if discarded:
        before["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
        _json_write(PROACTIVE_STATE_FILE, before)
    known_before = set((before.get("admin_alert_queue") or {}).keys()) | set(
        (before.get("admin_alert_sent") or {}).keys()
    )
    seen_ids = set()
    reservations = 0
    for row in sorted(
        (dict(item) for item in rows if isinstance(item, dict)),
        key=lambda item: (
            str(item.get("reservation_id") or ""),
            normalizar_hora_detectada(item.get("hora")) or "99:99",
        ),
    ):
        if not _pending_hold_row_is_temporary(row):
            continue
        reservation_id = str(row.get("reservation_id") or "").strip()
        if not reservation_id or reservation_id in seen_ids:
            continue
        seen_ids.add(reservation_id)
        reservations += 1
        enqueue_pending_booking_admin_alert(row, row.get("telefono") or "")

    after = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    known_after = set((after.get("admin_alert_queue") or {}).keys()) | set(
        (after.get("admin_alert_sent") or {}).keys()
    )
    added = len(known_after - known_before)
    if added:
        print(
            "   ♻️ [PENDING ADMIN ALERT] reconciliación recuperó "
            f"{added} entrega(s) faltante(s)"
        )
        registrar_metrica_operativa(
            "reserva_pendiente_alerta_admin_rehidratada",
            {"reservas": reservations, "entregas": added},
        )
    return {"reservations": reservations, "added": added, "discarded": discarded}


def _admin_alert_batch_delivered(delivery_ids: List[str]) -> bool:
    if not delivery_ids:
        return False
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    sent_registry = state.get("admin_alert_sent") or {}
    return all(delivery_id in sent_registry for delivery_id in delivery_ids)


async def flush_admin_alert_queue(
    page,
    *,
    max_deliveries: int = 20,
    respect_inbox: bool = False,
    only_delivery_ids: Optional[List[str]] = None,
    force_retry: bool = False,
) -> Dict[str, int]:
    """Entrega secuencialmente la cola usando la misma pestaña de WhatsApp."""
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.setdefault("admin_alert_queue", {})
    discarded_count = _prune_stale_pending_booking_admin_alerts(state)
    dead_lettered_count = 0
    for delivery_id, item in list(queue.items()):
        if int((item or {}).get("attempts") or 0) < ADMIN_ALERT_MAX_ATTEMPTS:
            continue
        queue.pop(delivery_id, None)
        _archive_admin_alert_queue_item(
            state,
            delivery_id,
            item,
            bucket="admin_alert_dead_letter",
            reason="max_attempts_exceeded",
        )
        dead_lettered_count += 1
    if discarded_count or dead_lettered_count:
        state["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
        _json_write(PROACTIVE_STATE_FILE, state)
    if dead_lettered_count:
        print(
            "   🛑 [ADMIN ALERT QUEUE] "
            f"moví {dead_lettered_count} entrega(s) agotada(s) a auditoría"
        )

    allowed_ids = set(only_delivery_ids or [])
    now = datetime.datetime.now(TIMEZONE)
    deferred_count = 0
    delivery_ids = [
        delivery_id
        for delivery_id, item in queue.items()
        if not allowed_ids or delivery_id in allowed_ids
        if force_retry or _admin_alert_retry_is_due(item, now)
    ][:max(1, int(max_deliveries or 1))]
    if not force_retry:
        deferred_count = sum(
            1
            for delivery_id, item in queue.items()
            if (not allowed_ids or delivery_id in allowed_ids)
            and not _admin_alert_retry_is_due(item, now)
        )
    sent_count = 0
    failed_count = 0

    for delivery_id in delivery_ids:
        if respect_inbox and _reactive_handoff_pending():
            break

        latest = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
        latest_queue = latest.setdefault("admin_alert_queue", {})
        item = latest_queue.get(delivery_id)
        if not isinstance(item, dict):
            continue

        if str(item.get("category") or "") in {
            "pending_booking_created", "pending_booking_rescheduled",
        }:
            if _pending_booking_batch_covers_individual_alert(latest, item):
                latest_queue.pop(delivery_id, None)
                _archive_admin_alert_queue_item(
                    latest,
                    delivery_id,
                    item,
                    bucket="admin_alert_discarded",
                    reason="individual_pending_alert_covered_by_batch",
                )
                latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                _json_write(PROACTIVE_STATE_FILE, latest)
                discarded_count += 1
                continue
            active_ids = _active_pending_booking_reservation_ids()
            reservation_id = _pending_booking_admin_alert_reservation_id(item)
            if active_ids is not None and reservation_id and reservation_id not in active_ids:
                latest_queue.pop(delivery_id, None)
                _archive_admin_alert_queue_item(
                    latest,
                    delivery_id,
                    item,
                    bucket="admin_alert_discarded",
                    reason="pending_booking_became_inactive_before_send",
                )
                latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                _json_write(PROACTIVE_STATE_FILE, latest)
                discarded_count += 1
                continue

        recipient = normalize_phone(item.get("recipient") or "")
        if not recipient or recipient not in set(_authorized_alert_recipients()):
            latest_queue.pop(delivery_id, None)
            latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            _json_write(PROACTIVE_STATE_FILE, latest)
            continue

        try:
            # Siempre reabrir el destinatario. En reintentos parciales text_sent=True,
            # pero la vuelta anterior pudo dejar la pestaña en la lista de chats.
            alert_chat_url = (
                "https://web.whatsapp.com/send?phone="
                f"{recipient.replace('+', '')}&text="
            )
            await page.goto(alert_chat_url)
            await asyncio.sleep(3)

            if not item.get("text_sent"):
                delivered = await send_message(page, str(item.get("text") or ""))
                if delivered is not True:
                    raise RuntimeError("WhatsApp no confirmó el texto de la alerta")
                item["text_sent"] = True
                latest_queue[delivery_id] = item
                latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                _json_write(PROACTIVE_STATE_FILE, latest)

            attachment_path = str(item.get("attachment_path") or "")
            if attachment_path:
                attachment_title = str(item.get("attachment_title") or "")
                if attachment_title and not item.get("attachment_title_sent"):
                    title_ok = await send_message(page, attachment_title)
                    if title_ok is not True:
                        raise RuntimeError("WhatsApp no confirmó el título del adjunto")
                    item["attachment_title_sent"] = True
                    latest = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
                    latest_queue = latest.setdefault("admin_alert_queue", {})
                    latest_queue[delivery_id] = item
                    latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                    _json_write(PROACTIVE_STATE_FILE, latest)
                attachment_ok = await send_file_to_current_chat(
                    page,
                    attachment_path,
                    title="",
                )
                if attachment_ok is not True:
                    raise RuntimeError("WhatsApp no confirmó el adjunto de la alerta")

            latest = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
            latest_queue = latest.setdefault("admin_alert_queue", {})
            completed = latest_queue.pop(delivery_id, item)
            sent_registry = latest.setdefault("admin_alert_sent", {})
            sent_registry[delivery_id] = {
                "recipient": recipient,
                "category": completed.get("category"),
                "batch_key": completed.get("batch_key"),
                # La cobertura de una alerta multi-reserva vive en context.
                # Conservarla al pasar de queue a sent evita que la
                # reconciliación vuelva a emitir una alerta por cada ID hijo.
                "context": dict(completed.get("context") or {}),
                "sent_at": datetime.datetime.now(TIMEZONE).isoformat(),
            }
            if len(sent_registry) > 2000:
                oldest = sorted(
                    sent_registry,
                    key=lambda key: str((sent_registry.get(key) or {}).get("sent_at") or ""),
                )[:len(sent_registry) - 2000]
                for old_id in oldest:
                    sent_registry.pop(old_id, None)
            latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            _json_write(PROACTIVE_STATE_FILE, latest)
            sent_count += 1
            print(
                "   ✅ [ADMIN ALERT QUEUE] "
                f"entregada category={completed.get('category')} recipient={recipient}"
            )
        except Exception as exc:
            latest = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
            latest_queue = latest.setdefault("admin_alert_queue", {})
            current = latest_queue.get(delivery_id)
            if isinstance(current, dict):
                current["attempts"] = int(current.get("attempts") or 0) + 1
                current["last_attempt_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                current["last_error"] = str(exc)[:500]
                if current["attempts"] >= ADMIN_ALERT_MAX_ATTEMPTS:
                    latest_queue.pop(delivery_id, None)
                    _archive_admin_alert_queue_item(
                        latest,
                        delivery_id,
                        current,
                        bucket="admin_alert_dead_letter",
                        reason="max_attempts_exceeded",
                    )
                    dead_lettered_count += 1
                else:
                    latest_queue[delivery_id] = current
            latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            _json_write(PROACTIVE_STATE_FILE, latest)
            failed_count += 1
            if isinstance(current, dict) and current.get("attempts", 0) >= ADMIN_ALERT_MAX_ATTEMPTS:
                print(
                    "   🛑 [ADMIN ALERT QUEUE] "
                    f"agotada recipient={recipient} attempts={current.get('attempts')} error={exc}"
                )
            else:
                retry_seconds = _admin_alert_retry_delay_seconds(current or {})
                print(
                    "   ⚠️ [ADMIN ALERT QUEUE] "
                    f"pendiente recipient={recipient} retry_in={retry_seconds}s error={exc}"
                )

    pending_count = len(
        (_json_read(PROACTIVE_STATE_FILE, {"sent": {}}).get("admin_alert_queue") or {})
    )
    return {
        "sent": sent_count,
        "failed": failed_count,
        "pending": pending_count,
        "deferred": deferred_count,
        "discarded": discarded_count,
        "dead_lettered": dead_lettered_count,
    }


async def _send_admin_alert_batch(
    page,
    texto: str,
    *,
    category: str,
    dedupe_key: str = "",
    attachment_path: str = "",
    attachment_title: str = "",
    respect_inbox: bool = False,
) -> bool:
    delivery_ids = _enqueue_admin_alert_batch(
        texto,
        category=category,
        dedupe_key=dedupe_key,
        attachment_path=attachment_path,
        attachment_title=attachment_title,
    )
    if not delivery_ids:
        return False
    await flush_admin_alert_queue(
        page,
        max_deliveries=max(20, len(delivery_ids)),
        respect_inbox=respect_inbox,
        only_delivery_ids=delivery_ids,
    )
    return _admin_alert_batch_delivered(delivery_ids)


async def enviar_aviso_admin_operativo(page, texto: str) -> bool:
    if getattr(bot_state, "autonomy_level", DEFAULT_AUTONOMY_LEVEL) < AUTONOMY_LEVEL_PROACTIVE:
        print(f"[PROACTIVO] Nivel < 5, aviso solo registrado: {texto[:140]}")
        return False
    delivered = await _send_admin_alert_batch(
        page,
        texto,
        category="operational_notice",
        respect_inbox=True,
    )
    registrar_metrica_operativa(
        "aviso_admin_enviado" if delivered else "aviso_admin_error",
        {"texto": texto[:500], "recipients": _authorized_alert_recipients()},
    )
    return delivered


async def enviar_aviso_admin_directo(
    page,
    texto: str,
    *,
    dedupe_key: str = "",
    attachment_path: str = "",
    attachment_title: str = "",
    respect_inbox: bool = True,
) -> bool:
    delivered = await _send_admin_alert_batch(
        page,
        texto,
        category="direct_admin_notice",
        dedupe_key=dedupe_key,
        attachment_path=attachment_path,
        attachment_title=attachment_title,
        respect_inbox=respect_inbox,
    )
    registrar_metrica_operativa(
        "aviso_admin_directo_enviado" if delivered else "aviso_admin_directo_no_confirmado",
        {"texto": texto[:500], "recipients": _authorized_alert_recipients()},
    )
    return delivered


_LAST_INTEGRATED_ALERT_SCHEDULER_TS = 0.0


def _integrated_scheduler_config_int(name: str, default: int) -> int:
    try:
        from cancheria.config import legacy_config as cfg
        return max(0, int(getattr(cfg, name, default)))
    except Exception:
        return max(0, int(default))


def _integrated_scheduler_daily_time() -> str:
    try:
        from cancheria.config import legacy_config as cfg
        value = str(getattr(cfg, "DAILY_AGENDA_SUMMARY_TIME", "08:00") or "08:00")
    except Exception:
        value = "08:00"
    return value if re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", value) else "08:00"


def init_integrated_alert_scheduler_db() -> bool:
    """Base compatible con AlertScheduler, ahora propiedad de WPSetter."""
    try:
        conn = sqlite3.connect(CALENDAR_DB)
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_description TEXT NOT NULL,
                event_datetime TEXT NOT NULL,
                alert_30min_datetime TEXT,
                alert_5min_datetime TEXT,
                user_phone TEXT NOT NULL,
                event_key TEXT,
                court TEXT,
                customer_name TEXT,
                duration_minutes TEXT,
                deposit_status TEXT,
                deposit_amount TEXT,
                reservation_id TEXT,
                total_amount TEXT,
                paid_amount TEXT,
                cash_deposit_due TEXT,
                balance_due TEXT,
                payment_method TEXT,
                notes TEXT,
                source TEXT,
                status TEXT DEFAULT 'active',
                alert_30min_sent INTEGER DEFAULT 0,
                alert_5min_sent INTEGER DEFAULT 0,
                deposit_admin_alert_sent INTEGER DEFAULT 0,
                attendance_confirmation_sent INTEGER DEFAULT 0,
                attendance_confirmed INTEGER DEFAULT 0,
                attendance_no_response_alert_sent INTEGER DEFAULT 0,
                coordination_alert_sent INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)
        cursor.execute("PRAGMA table_info(events)")
        columns = {str(row[1]) for row in cursor.fetchall()}
        migrations = {
            "alert_30min_datetime": "TEXT",
            "alert_5min_datetime": "TEXT",
            "event_key": "TEXT",
            "court": "TEXT",
            "customer_name": "TEXT",
            "duration_minutes": "TEXT",
            "deposit_status": "TEXT",
            "deposit_amount": "TEXT",
            "reservation_id": "TEXT",
            "total_amount": "TEXT",
            "paid_amount": "TEXT",
            "cash_deposit_due": "TEXT",
            "balance_due": "TEXT",
            "payment_method": "TEXT",
            "notes": "TEXT",
            "source": "TEXT",
            "status": "TEXT DEFAULT 'active'",
            "alert_30min_sent": "INTEGER DEFAULT 0",
            "alert_5min_sent": "INTEGER DEFAULT 0",
            "deposit_admin_alert_sent": "INTEGER DEFAULT 0",
            "attendance_confirmation_sent": "INTEGER DEFAULT 0",
            "attendance_confirmed": "INTEGER DEFAULT 0",
            "attendance_no_response_alert_sent": "INTEGER DEFAULT 0",
            # Las filas del scheduler legacy se insertaban después de avisar.
            "coordination_alert_sent": "INTEGER DEFAULT 1",
            "created_at": "TEXT",
        }
        for column, column_type in migrations.items():
            if column not in columns:
                cursor.execute(f"ALTER TABLE events ADD COLUMN {column} {column_type}")
        conn.commit()
        conn.close()
        return True
    except Exception as e:
        print(f"   ⚠️ [SCHEDULER INTEGRADO] no pude inicializar DB: {e}")
        registrar_metrica_operativa("scheduler_integrado_db_error", {"error": str(e)})
        return False


def _calendar_rows_operativas_y_rescatadas(
    include_finished: bool = True,
) -> List[Dict[str, Any]]:
    """
    Fuente operativa robusta para agenda y scheduler.

    Prioridad de verdad:
      1) CSV activo crudo (_leer_todos)
      2) vista pública listar_reservas()
      3) histórico/terminadas como rescate

    El histórico NO vuelve una reserva válida por sí solo: los consumidores
    todavía deben aplicar _reserva_activa(), fecha y estado operativo.
    Se deduplica por identidad+slot conservando siempre la fuente de mayor
    prioridad para no revivir una copia histórica cuando existe una activa.
    """
    fuentes: List[List[Dict[str, Any]]] = []

    raw_reader = getattr(calendario, "_leer_todos", None)
    if callable(raw_reader):
        try:
            fuentes.append([
                dict(row) for row in (raw_reader() or [])
                if isinstance(row, dict)
            ])
        except Exception as exc:
            print(f"   ⚠️ [CALENDAR SOURCE] _leer_todos falló: {exc}")

    try:
        fuentes.append([
            dict(row) for row in (calendario.listar_reservas() or [])
            if isinstance(row, dict)
        ])
    except Exception as exc:
        print(f"   ⚠️ [CALENDAR SOURCE] listar_reservas falló: {exc}")

    if include_finished:
        finished_reader = getattr(calendario, "_leer_terminadas", None)
        if callable(finished_reader):
            try:
                fuentes.append([
                    dict(row) for row in (finished_reader() or [])
                    if isinstance(row, dict)
                ])
            except Exception as exc:
                print(f"   ⚠️ [CALENDAR SOURCE] _leer_terminadas falló: {exc}")

    unique: Dict[Tuple[Any, ...], Dict[str, Any]] = {}

    for rows in fuentes:
        for row in rows:
            reservation_id = str(row.get("reservation_id") or "").strip()
            fecha = str(row.get("fecha") or "").strip()
            hora = (
                normalizar_hora_detectada(row.get("hora"))
                or str(row.get("hora") or "").strip()
            )
            cancha = str(row.get("cancha") or "").strip().casefold()

            if reservation_id:
                key = (
                    "reservation",
                    reservation_id,
                    fecha,
                    hora,
                    cancha,
                )
            else:
                owner = (
                    normalize_phone(row.get("telefono") or "")
                    or str(row.get("nombre") or "").strip().casefold()
                )
                key = (
                    "legacy",
                    owner,
                    fecha,
                    hora,
                    cancha,
                )

            # La primera aparición gana:
            # activo crudo > vista pública > histórico.
            if key not in unique:
                unique[key] = dict(row)

    return list(unique.values())


def _reserva_operativamente_firme(
    row: Dict[str, Any],
) -> bool:
    """
    Única definición de 'turno firme' para agenda y scheduler.

    Incluye el caso válido de seña parcial + diferencia en efectivo, que ya es
    un turno operativo confirmado aunque todavía quede dinero para cobrar en el
    complejo.
    """
    if not row or not _reserva_activa(row):
        return False

    if (
        str(row.get("telefono") or "").startswith("ADMIN:CERRADO")
        or str(row.get("nombre") or "").strip().casefold() == "cerrado"
    ):
        return False

    deposit = str(
        row.get("senia_estado")
        or ""
    ).strip().casefold()

    status = str(
        row.get("estado")
        or ""
    ).strip().casefold()

    firm_deposit_states = {
        "pagada",
        "parcial_efectivo_pendiente",
    }

    firm_booking_states = {
        str(
            BOOKING_STATUS_RESERVED
            or ""
        ).strip().casefold(),

        str(
            BOOKING_STATUS_CONFIRMED
            or ""
        ).strip().casefold(),

        "reservado",
        "confirmado",
    }

    return (
        deposit in firm_deposit_states
        or status in firm_booking_states
    )


def _agenda_reservas_logicas(
    rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """
    Colapsa las filas horarias de una misma reserva lógica para contadores.

    Un bloque de 2 horas no debe contar como 2 clientes confirmados.
    Se conserva una reserva por reservation_id+cancha.

    Filas legacy sin ID se mantienen por:
        owner + fecha + hora + cancha.
    """
    logical: Dict[
        Tuple[Any, ...],
        Dict[str, Any],
    ] = {}

    for raw in rows or []:
        if not isinstance(raw, dict):
            continue

        row = dict(raw)

        reservation_id = str(
            row.get("reservation_id")
            or ""
        ).strip()

        cancha = str(
            row.get("cancha")
            or ""
        ).strip().casefold()

        if reservation_id:
            key = (
                "reservation",
                reservation_id,
                cancha,
            )

        else:
            key = (
                "legacy",

                normalize_phone(
                    row.get("telefono")
                    or ""
                )
                or str(
                    row.get("nombre")
                    or ""
                ).strip().casefold(),

                str(
                    row.get("fecha")
                    or ""
                ).strip(),

                normalizar_hora_detectada(
                    row.get("hora")
                )
                or str(
                    row.get("hora")
                    or ""
                ).strip(),

                cancha,
            )

        previous = logical.get(key)

        if previous is None:
            logical[key] = row
            continue

        prev_min = _hora_a_minutos_local(
            previous.get("hora")
            or ""
        )

        curr_min = _hora_a_minutos_local(
            row.get("hora")
            or ""
        )

        if (
            curr_min is not None
            and (
                prev_min is None
                or curr_min < prev_min
            )
        ):
            logical[key] = row

    return list(
        logical.values()
    )


def _integrated_scheduler_row_is_confirmed(
    row: Dict[str, Any],
) -> bool:
    """
    Compatibilidad:
    agenda y scheduler comparten exactamente la misma autoridad
    para determinar si un turno está operativo/firme.
    """
    return _reserva_operativamente_firme(
        row
    )

def _integrated_scheduler_ensure_reprogram_columns() -> bool:
    """
    Migración backward-compatible del scheduler.

    Permite diferenciar:

        NUEVO TURNO
        vs
        TURNO REPROGRAMADO

    sin borrar la DB actual.
    """
    try:

        conn = sqlite3.connect(
            CALENDAR_DB
        )

        cursor = conn.cursor()

        cursor.execute(
            "PRAGMA table_info(events)"
        )

        columns = {
            str(
                row[
                    1
                ]
            )
            for row
            in cursor.fetchall()
        }

        migrations = {
            "coordination_alert_kind": (
                "TEXT DEFAULT 'new'"
            ),
            "previous_event_datetime": (
                "TEXT"
            ),
            "previous_court": (
                "TEXT"
            ),
        }

        for (
            column,
            column_type,
        ) in migrations.items():

            if column not in columns:

                cursor.execute(
                    f"ALTER TABLE events "
                    f"ADD COLUMN {column} {column_type}"
                )

        conn.commit()
        conn.close()

        return True

    except Exception as exc:

        print(
            "   ⚠️ [SCHEDULER REPROGRAM MIGRATION] "
            f"{exc}"
        )

        return False


def _integrated_scheduler_event_key(
    row: Dict[str, Any],
) -> str:
    """
    event_key representa una ENTREGA concreta del scheduler.

    reservation_id representa la IDENTIDAD de la reserva.

    Esto es deliberado:

        reservation_id = 31
            permanece igual

        10:00 -> 20:00
            cambia event_key

    Así podemos detectar que es la misma reserva reprogramada,
    pero generar un nuevo dedupe_key para avisarle al admin
    sobre el cambio.
    """
    row = row or {}

    reservation_id = str(
        row.get(
            "reservation_id"
        )
        or ""
    ).strip()

    schedule_part = "|".join([
        str(
            row.get(
                "fecha"
            )
            or ""
        ).strip(),

        str(
            row.get(
                "hora"
            )
            or ""
        ).strip(),

        str(
            row.get(
                "cancha"
            )
            or ""
        ).strip(),
    ])

    if reservation_id:

        return (
            f"reservation|"
            f"{reservation_id}|"
            f"{schedule_part}"
        )

    # Sólo para filas legacy sin ID.
    return (
        "legacy|"
        + "|".join([
            schedule_part,

            str(
                row.get(
                    "telefono"
                )
                or row.get(
                    "nombre"
                )
                or ""
            ).strip(),
        ])
    )


def _integrated_scheduler_sync_calendar(
    now: Optional[
        datetime.datetime
    ] = None,
) -> Dict[str, Any]:
    """
    Sincroniza calendario -> scheduler.

    CORRECCIONES:

    1. UNA reserva lógica = UN evento.
       Un turno 20:00-22:00 no genera dos eventos
       por las filas 20:00 y 21:00.

    2. reservation_id identifica la reserva.

    3. Si el mismo reservation_id cambia de fecha/hora/cancha:
           coordination_alert_kind = rescheduled

    4. Se conserva la información financiera.

    5. Se rearman recordatorios para el nuevo horario.

    6. Una reprogramación no se transforma en una falsa
       reserva nueva.
    """
    now = (
        now
        or datetime.datetime.now(
            TIMEZONE
        )
    )

    if not (
        init_integrated_alert_scheduler_db()
    ):
        return {
            "ok": False,
            "inserted": 0,
            "live": 0,
        }

    if not (
        _integrated_scheduler_ensure_reprogram_columns()
    ):
        return {
            "ok": False,
            "inserted": 0,
            "live": 0,
            "error": (
                "scheduler_migration_failed"
            ),
        }

    try:

        # ======================================================
        # CALENDAR -> LOGICAL BOOKINGS
        # ======================================================

        logical: Dict[
            str,
            Tuple[
                Dict[str, Any],
                datetime.datetime,
            ],
        ] = {}

        for raw in (
            calendario.listar_reservas()
            or []
        ):

            if not isinstance(
                raw,
                dict,
            ):
                continue

            row = dict(
                raw
            )

            event_dt = (
                _parse_reserva_datetime(
                    row
                )
            )

            if not (
                _integrated_scheduler_row_is_confirmed(
                    row
                )
                and event_dt
                and event_dt > now
            ):
                continue

            reservation_id = str(
                row.get(
                    "reservation_id"
                )
                or ""
            ).strip()

            if reservation_id:

                identity = (
                    f"reservation|"
                    f"{reservation_id}"
                )

            else:

                identity = (
                    "legacy|"
                    + "|".join([
                        str(
                            row.get(
                                "telefono"
                            )
                            or row.get(
                                "nombre"
                            )
                            or ""
                        ).strip(),

                        str(
                            row.get(
                                "fecha"
                            )
                            or ""
                        ).strip(),

                        str(
                            row.get(
                                "cancha"
                            )
                            or ""
                        ).strip(),
                    ])
                )

            previous = (
                logical.get(
                    identity
                )
            )

            # El anchor de un bloque es la hora inicial.
            if (
                previous is None
                or event_dt
                < previous[
                    1
                ]
            ):

                logical[
                    identity
                ] = (
                    row,
                    event_dt,
                )

        live_rows = list(
            logical.values()
        )

        client_before = (
            _integrated_scheduler_config_int(
                "CLIENT_REMINDER_MINUTES_BEFORE",
                120,
            )
        )

        owner_before = (
            _integrated_scheduler_config_int(
                "FINAL_OWNER_REMINDER_MINUTES_BEFORE",
                5,
            )
        )

        conn = sqlite3.connect(
            CALENDAR_DB
        )

        conn.row_factory = (
            sqlite3.Row
        )

        cursor = conn.cursor()

        inserted = 0
        reprogrammed = 0

        live_reservation_ids = {
            str(
                row.get(
                    "reservation_id"
                )
                or ""
            ).strip()
            for (
                row,
                _,
            ) in live_rows
            if str(
                row.get(
                    "reservation_id"
                )
                or ""
            ).strip()
        }

        live_keys = {
            _integrated_scheduler_event_key(
                row
            )
            for (
                row,
                _,
            ) in live_rows
        }

        # ======================================================
        # CANCELAR EVENTOS QUE REALMENTE YA NO EXISTEN
        # ======================================================

        active_events = (
            cursor.execute(
                """
                SELECT
                    id,
                    event_key,
                    event_datetime,
                    reservation_id
                FROM events
                WHERE status = 'active'
                """
            ).fetchall()
        )

        for event in active_events:

            event_id = int(
                event[
                    "id"
                ]
            )

            event_key = str(
                event[
                    "event_key"
                ]
                or ""
            )

            reservation_id = str(
                event[
                    "reservation_id"
                ]
                or ""
            ).strip()

            parsed = (
                _parse_iso_datetime(
                    event[
                        "event_datetime"
                    ]
                )
            )

            # Mismo reservation_id:
            # NO cancelar por cambio de event_key.
            #
            # Precisamente puede haber sido reprogramado.
            if (
                reservation_id
                and reservation_id
                in live_reservation_ids
            ):
                continue

            if (
                (
                    event_key
                    and event_key
                    not in live_keys
                )
                or (
                    parsed
                    and parsed <= now
                )
            ):

                cursor.execute(
                    """
                    UPDATE events
                    SET status = ?
                    WHERE id = ?
                    """,
                    (
                        (
                            "expired"
                            if (
                                parsed
                                and parsed
                                <= now
                            )
                            else "cancelled"
                        ),
                        event_id,
                    ),
                )

        # ======================================================
        # UPSERT
        # ======================================================

        for (
            row,
            event_dt,
        ) in live_rows:

            event_key = (
                _integrated_scheduler_event_key(
                    row
                )
            )

            phone = (
                _telefono_reserva_para_mensaje(
                    row
                )
            )

            court = str(
                row.get(
                    "cancha"
                )
                or ""
            ).strip()

            name = str(
                row.get(
                    "nombre"
                )
                or "Cliente"
            ).strip()

            description = (
                f"Turno "
                f"{court or 'sin cancha'} "
                f"con {name}"
            )

            duration = str(
                _duracion_minutos_row(
                    row
                )
            )

            total_amount = (
                _monto_a_int(
                    row.get(
                        "precio_total"
                    )
                )
            )

            if total_amount is None:

                total_amount = (
                    calcular_precio_total(
                        normalizar_duracion_horas(
                            row.get(
                                "duracion_horas"
                            )
                            or DEFAULT_TURN_DURATION_HOURS
                        )
                    )
                )

            deposit_required = (
                _senia_guardada_o_configurada(
                    row,
                    total_amount,
                )
            )

            paid_amount = (
                _senia_pagada_acumulada(
                    row,
                    total_amount,
                )
            )

            cash_deposit_due = (
                _monto_a_int(
                    row.get(
                        "senia_efectivo_pendiente"
                    )
                )
                or 0
            )

            balance_due = (
                _monto_a_int(
                    row.get(
                        "monto_pendiente"
                    )
                )
            )

            if balance_due is None:

                balance_due = max(
                    0,
                    total_amount
                    - paid_amount,
                )

            payment_method = str(
                row.get(
                    "payment_method"
                )
                or ""
            ).strip()

            reservation_id = str(
                row.get(
                    "reservation_id"
                )
                or ""
            ).strip()

            alert_client = (
                event_dt
                - datetime.timedelta(
                    minutes=client_before
                )
            )

            alert_owner = (
                event_dt
                - datetime.timedelta(
                    minutes=owner_before
                )
            )

            # ==================================================
            # BUSCAR PRIMERO POR reservation_id
            # ==================================================

            existing = None

            if reservation_id:

                existing = (
                    cursor.execute(
                        """
                        SELECT *
                        FROM events
                        WHERE
                            reservation_id = ?
                            AND status = 'active'
                        ORDER BY id DESC
                        LIMIT 1
                        """,
                        (
                            reservation_id,
                        ),
                    ).fetchone()
                )

            if existing is None:

                existing = (
                    cursor.execute(
                        """
                        SELECT *
                        FROM events
                        WHERE
                            event_key = ?
                            AND status = 'active'
                        ORDER BY id DESC
                        LIMIT 1
                        """,
                        (
                            event_key,
                        ),
                    ).fetchone()
                )

            common_values = (
                description,
                event_dt.isoformat(),
                alert_client.isoformat(),
                alert_owner.isoformat(),
                phone,
                event_key,
                court,
                name,
                duration,
                str(
                    row.get(
                        "senia_estado"
                    )
                    or ""
                ),
                str(
                    deposit_required
                ),
                str(
                    row.get(
                        "notas"
                    )
                    or ""
                ),
                reservation_id,
                str(
                    total_amount
                ),
                str(
                    paid_amount
                ),
                str(
                    cash_deposit_due
                ),
                str(
                    balance_due
                ),
                payment_method,
            )

            # ==================================================
            # EXISTENTE
            # ==================================================

            if existing is not None:

                old_dt = (
                    _parse_iso_datetime(
                        existing[
                            "event_datetime"
                        ]
                    )
                )

                old_court = str(
                    existing[
                        "court"
                    ]
                    or ""
                ).strip()

                schedule_changed = bool(
                    (
                        old_dt
                        and old_dt
                        != event_dt
                    )
                    or (
                        old_court.casefold()
                        != court.casefold()
                    )
                )

                alert_was_sent = bool(
                    int(
                        existing[
                            "coordination_alert_sent"
                        ]
                        or 0
                    )
                )

                alert_kind = str(
                    existing[
                        "coordination_alert_kind"
                    ]
                    or "new"
                ).strip() or "new"

                previous_event_datetime = (
                    existing[
                        "previous_event_datetime"
                    ]
                )

                previous_court = (
                    existing[
                        "previous_court"
                    ]
                )

                coordination_alert_sent = int(
                    existing[
                        "coordination_alert_sent"
                    ]
                    or 0
                )

                alert_30min_sent = int(
                    existing[
                        "alert_30min_sent"
                    ]
                    or 0
                )

                alert_5min_sent = int(
                    existing[
                        "alert_5min_sent"
                    ]
                    or 0
                )

                attendance_confirmation_sent = int(
                    existing[
                        "attendance_confirmation_sent"
                    ]
                    or 0
                )

                attendance_confirmed = int(
                    existing[
                        "attendance_confirmed"
                    ]
                    or 0
                )

                attendance_no_response_alert_sent = int(
                    existing[
                        "attendance_no_response_alert_sent"
                    ]
                    or 0
                )

                if schedule_changed:

                    previous_event_datetime = (
                        existing[
                            "event_datetime"
                        ]
                    )

                    previous_court = (
                        existing[
                            "court"
                        ]
                    )

                    # Si el admin YA conocía el turno,
                    # esto no es una reserva nueva.
                    if alert_was_sent:

                        alert_kind = (
                            "rescheduled"
                        )

                    coordination_alert_sent = 0

                    # El horario cambió:
                    # rearmar recordatorios.
                    alert_30min_sent = 0
                    alert_5min_sent = 0
                    attendance_confirmation_sent = 0
                    attendance_confirmed = 0
                    attendance_no_response_alert_sent = 0

                    reprogrammed += 1

                cursor.execute(
                    """
                    UPDATE events SET
                        event_description = ?,
                        event_datetime = ?,
                        alert_30min_datetime = ?,
                        alert_5min_datetime = ?,
                        user_phone = ?,
                        event_key = ?,
                        court = ?,
                        customer_name = ?,
                        duration_minutes = ?,
                        deposit_status = ?,
                        deposit_amount = ?,
                        notes = ?,
                        reservation_id = ?,
                        total_amount = ?,
                        paid_amount = ?,
                        cash_deposit_due = ?,
                        balance_due = ?,
                        payment_method = ?,
                        status = 'active',
                        coordination_alert_kind = ?,
                        previous_event_datetime = ?,
                        previous_court = ?,
                        coordination_alert_sent = ?,
                        alert_30min_sent = ?,
                        alert_5min_sent = ?,
                        attendance_confirmation_sent = ?,
                        attendance_confirmed = ?,
                        attendance_no_response_alert_sent = ?
                    WHERE id = ?
                    """,
                    common_values
                    + (
                        alert_kind,
                        previous_event_datetime,
                        previous_court,
                        coordination_alert_sent,
                        alert_30min_sent,
                        alert_5min_sent,
                        attendance_confirmation_sent,
                        attendance_confirmed,
                        attendance_no_response_alert_sent,
                        int(
                            existing[
                                "id"
                            ]
                        ),
                    ),
                )

                continue

            # ==================================================
            # NUEVO EVENTO
            # ==================================================

            cursor.execute(
                """
                INSERT INTO events (
                    event_description,
                    event_datetime,
                    alert_30min_datetime,
                    alert_5min_datetime,
                    user_phone,
                    event_key,
                    court,
                    customer_name,
                    duration_minutes,
                    deposit_status,
                    deposit_amount,
                    notes,
                    reservation_id,
                    total_amount,
                    paid_amount,
                    cash_deposit_due,
                    balance_due,
                    payment_method,
                    source,
                    status,
                    coordination_alert_kind,
                    previous_event_datetime,
                    previous_court,
                    coordination_alert_sent,
                    alert_30min_sent,
                    alert_5min_sent,
                    attendance_confirmation_sent,
                    attendance_confirmed,
                    attendance_no_response_alert_sent,
                    created_at
                )
                VALUES (
                    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?, ?, ?, ?,
                    'wpsetter_integrated',
                    'active',
                    'new',
                    NULL,
                    NULL,
                    0, 0, 0, 0, 0, 0,
                    ?
                )
                """,
                common_values
                + (
                    now.isoformat(),
                ),
            )

            inserted += 1

        conn.commit()
        conn.close()

        return {
            "ok": True,
            "inserted": (
                inserted
            ),
            "reprogrammed": (
                reprogrammed
            ),
            "live": (
                len(
                    live_rows
                )
            ),
        }

    except Exception as exc:

        print(
            "   ⚠️ [SCHEDULER INTEGRADO] "
            "error sincronizando calendario: "
            f"{exc}"
        )

        registrar_metrica_operativa(
            "scheduler_integrado_sync_error",
            {
                "error": str(
                    exc
                )
            },
        )

        return {
            "ok": False,
            "inserted": 0,
            "live": 0,
            "error": str(
                exc
            ),
        }


def _integrated_scheduler_sync_calendar_operational(
    now: Optional[datetime.datetime] = None,
) -> Dict[str, Any]:
    """
    Ejecuta la sincronización existente usando una snapshot operativa robusta.

    _integrated_scheduler_sync_calendar() es síncrona y no hace await.
    Por eso podemos sustituir listar_reservas() sólo durante esa llamada
    y restaurarlo inmediatamente, sin exponer el override al resto del
    loop de WhatsApp.

    Esto rescata una reserva futura firme que haya quedado en terminadas
    o que no esté siendo devuelta por listar_reservas(), evitando que el
    scheduler la marque como cancelada y pierda el recordatorio de 2 horas.
    """

    snapshot = (
        _calendar_rows_operativas_y_rescatadas(
            include_finished=True
        )
    )

    original_listar = (
        calendario.listar_reservas
    )

    def _snapshot_reader() -> List[Dict[str, Any]]:
        return [
            dict(row)
            for row in snapshot
        ]

    try:
        calendario.listar_reservas = (
            _snapshot_reader
        )

        result = (
            _integrated_scheduler_sync_calendar(
                now
            )
        )

    finally:
        calendario.listar_reservas = (
            original_listar
        )

    if result.get("ok"):
        print(
            "   ♻️ [SCHEDULER SOURCE] "
            f"snapshot_operativa={len(snapshot)} "
            f"live={result.get('live', 0)} "
            f"inserted={result.get('inserted', 0)} "
            f"reprogrammed={result.get('reprogrammed', 0)}"
        )

    return result


def _integrated_scheduler_events() -> List[Dict[str, Any]]:
    if not init_integrated_alert_scheduler_db():
        return []
    try:
        conn = sqlite3.connect(CALENDAR_DB)
        conn.row_factory = sqlite3.Row
        rows = [dict(row) for row in conn.execute(
            "SELECT * FROM events WHERE status = 'active' ORDER BY datetime(event_datetime) ASC"
        ).fetchall()]
        conn.close()
        return rows
    except Exception as e:
        print(f"   ⚠️ [SCHEDULER INTEGRADO] no pude leer eventos: {e}")
        return []


def _integrated_scheduler_update_event(event_id: int, **flags: Any) -> None:
    allowed = {
        "coordination_alert_sent", "alert_30min_sent", "alert_5min_sent",
        "attendance_confirmation_sent", "attendance_confirmed",
        "attendance_no_response_alert_sent", "status",
    }
    clean = {key: value for key, value in flags.items() if key in allowed}
    if not clean:
        return
    try:
        conn = sqlite3.connect(CALENDAR_DB)
        assignments = ", ".join(f"{key} = ?" for key in clean)
        conn.execute(
            f"UPDATE events SET {assignments} WHERE id = ?",
            tuple(clean.values()) + (int(event_id),),
        )
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"   ⚠️ [SCHEDULER INTEGRADO] no pude actualizar evento {event_id}: {e}")


def _repair_admin_client_attendance_flags_v235_once(
    now: Optional[datetime.datetime] = None,
) -> int:
    """Repara flags falsos creados al confundir cliente y administrador."""
    migration_key = "attendance_admin_client_repair_v2_35"
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    migrations = state.setdefault("migrations", {})
    if migrations.get(migration_key):
        return 0

    repaired = 0
    try:
        if not init_integrated_alert_scheduler_db():
            return 0
        now = now or datetime.datetime.now(TIMEZONE)
        if now.tzinfo is None:
            now = TIMEZONE.localize(now)
        recipients = set(_authorized_alert_recipients())
        conn = sqlite3.connect(CALENDAR_DB)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """
            SELECT id, user_phone, event_datetime
            FROM events
            WHERE status = 'active'
              AND attendance_confirmation_sent = 1
              AND attendance_confirmed = 0
            """
        ).fetchall()
        for row in rows:
            event_dt = _parse_iso_datetime(row["event_datetime"])
            if (
                normalize_phone(row["user_phone"] or "") in recipients
                and event_dt
                and event_dt > now
            ):
                conn.execute(
                    """
                    UPDATE events
                    SET alert_30min_sent = 0,
                        attendance_confirmation_sent = 0,
                        attendance_no_response_alert_sent = 0
                    WHERE id = ?
                    """,
                    (int(row["id"]),),
                )
                repaired += 1
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"   ⚠️ [SCHEDULER MIGRATION V2.35] no pude reparar flags: {e}")
        return 0

    migrations[migration_key] = {
        "completed_at": (now or datetime.datetime.now(TIMEZONE)).isoformat(),
        "repaired": repaired,
    }
    state["updated_at"] = (now or datetime.datetime.now(TIMEZONE)).isoformat()
    _json_write(PROACTIVE_STATE_FILE, state)
    if repaired:
        print(
            "   🧹 [SCHEDULER MIGRATION V2.35] "
            f"recordatorios falsamente marcados reparados={repaired}"
        )
        registrar_metrica_operativa(
            "scheduler_attendance_flags_repaired",
            {"count": repaired},
        )
    return repaired


def _integrated_scheduler_event_as_row(event: Dict[str, Any]) -> Dict[str, Any]:
    event_dt = _parse_iso_datetime(event.get("event_datetime"))
    return {
        "fecha": event_dt.strftime("%d/%m/%Y") if event_dt else "",
        "hora": event_dt.strftime("%H:%M") if event_dt else "",
        "telefono": event.get("user_phone") or "",
        "nombre": event.get("customer_name") or "Cliente",
        "cancha": event.get("court") or "",
        "duracion_minutos": event.get("duration_minutes") or "",
        "senia_estado": event.get("deposit_status") or "",
        "senia_monto": event.get("deposit_amount") or "",
        "reservation_id": event.get("reservation_id") or "",
        "precio_total": event.get("total_amount") or "",
        "senia_pagada_monto": event.get("paid_amount") or "",
        "senia_efectivo_pendiente": event.get("cash_deposit_due") or "",
        "monto_pendiente": event.get("balance_due") or "",
        "payment_method": event.get("payment_method") or "",
        "notas": event.get("notes") or "",
    }


def _integrated_scheduler_payment_status_label(status: str) -> str:
    normalized = str(status or "").strip().casefold()
    labels = {
        "pagada": "Seña pagada - turno firme",
        "parcial": "Seña parcial",
        "parcial_efectivo_pendiente": "Seña parcial + efectivo pendiente",
        "pendiente_efectivo": "Seña pendiente en efectivo",
        "pendiente": "Seña pendiente",
    }
    return labels.get(normalized, "Turno firme")


def _integrated_scheduler_admin_display_notes(notes: Any) -> str:
    """Oculta trazas contables internas ya representadas en el resumen visual."""
    visible = []
    technical_prefixes = (
        "reserva de bloque:",
        "transferencia registrada",
        "turno firme;",
    )
    for fragment in str(notes or "").split("|"):
        clean = fragment.strip()
        normalized = _texto_simple_para_detector(clean)
        if not clean or normalized.startswith(technical_prefixes):
            continue
        visible.append(clean)
    return " | ".join(visible)


def build_integrated_scheduler_booking_alert(
    event: Dict[str, Any],
) -> str:
    """
    Renderer de alerta administrativa.

    Distingue:

        NUEVO TURNO CONFIRMADO

    de:

        TURNO REPROGRAMADO

    El estado financiero se muestra aparte.

    Por lo tanto:

        "turno firme"
            NO significa
        "todo el dinero fue recibido".

    `parcial_efectivo_pendiente` continúa siendo un turno
    operativo firme con dinero pendiente en efectivo.
    """
    event = (
        event
        or {}
    )

    event_dt = (
        _parse_iso_datetime(
            event.get(
                "event_datetime"
            )
        )
    )

    previous_dt = (
        _parse_iso_datetime(
            event.get(
                "previous_event_datetime"
            )
        )
    )

    phone = str(
        event.get(
            "user_phone"
        )
        or ""
    ).strip() or "No disponible"

    reservation_id = str(
        event.get(
            "reservation_id"
        )
        or ""
    ).strip()

    duration_minutes = (
        _monto_a_int(
            event.get(
                "duration_minutes"
            )
        )
        or 60
    )

    duration_hours = max(
        1 / 60,
        duration_minutes
        / 60,
    )

    deposit_status = str(
        event.get(
            "deposit_status"
        )
        or ""
    ).strip()

    payment_method = str(
        event.get(
            "payment_method"
        )
        or ""
    ).strip().casefold()

    total = (
        _monto_a_int(
            event.get(
                "total_amount"
            )
        )
    )

    deposit_required = (
        _monto_a_int(
            event.get(
                "deposit_amount"
            )
        )
    )

    paid = (
        _monto_a_int(
            event.get(
                "paid_amount"
            )
        )
    )

    cash_deposit_due = (
        _monto_a_int(
            event.get(
                "cash_deposit_due"
            )
        )
        or 0
    )

    balance_due = (
        _monto_a_int(
            event.get(
                "balance_due"
            )
        )
    )

    alert_kind = str(
        event.get(
            "coordination_alert_kind"
        )
        or "new"
    ).strip().casefold()

    if (
        paid is None
        and deposit_status.casefold()
        == "pagada"
    ):
        paid = (
            deposit_required
        )

    if (
        balance_due is None
        and total is not None
        and paid is not None
    ):
        balance_due = max(
            0,
            total
            - paid,
        )

    # ==========================================================
    # TITLE
    # ==========================================================

    if (
        alert_kind
        == "rescheduled"
    ):

        lines = [
            "🔄 *TURNO REPROGRAMADO*",
            "",
            "📋 *DATOS DEL TURNO*",
        ]

    else:

        lines = [
            "✅ *NUEVO TURNO CONFIRMADO*",
            "",
            "📋 *DATOS DEL TURNO*",
        ]

    if reservation_id:

        lines.append(
            f"🆔 *Reserva ID:* "
            f"{reservation_id}"
        )

    lines.extend([
        (
            f"👤 *Cliente:* "
            f"{event.get('customer_name') or 'Cliente'}"
        ),
        (
            f"📱 *Teléfono:* "
            f"{phone}"
        ),
    ])

    # ==========================================================
    # BEFORE / AFTER
    # ==========================================================

    if (
        alert_kind
        == "rescheduled"
        and previous_dt
    ):

        previous_court = str(
            event.get(
                "previous_court"
            )
            or event.get(
                "court"
            )
            or "No disponible"
        ).strip()

        lines.extend([
            "",
            "⬅️ *ANTES*",
            (
                f"📅 "
                f"{previous_dt.strftime('%d/%m/%Y')}"
            ),
            (
                f"{_court_booking_summary_label(previous_court)} de "
                f"{rango_horario_texto(previous_dt.strftime('%H:%M'), duration_hours)}"
            ),
            "",
            "➡️ *AHORA*",
        ])

    lines.extend([
        (
            f"📅 *Fecha:* "
            f"{event_dt.strftime('%d/%m/%Y')}"
            if event_dt
            else "📅 *Fecha:* No disponible"
        ),
        (
            (
                f"{_court_booking_summary_label(event.get('court') or 'No disponible', bold_field=True)} "
                f"de "
                f"{rango_horario_texto(event_dt.strftime('%H:%M'), duration_hours)}"
            )
            if event_dt
            else (
                f"{_court_booking_summary_label(event.get('court') or 'No disponible', bold_field=True)}"
            )
        ),
        (
            f"⏱️ *Duración:* "
            f"{duration_hours:g} hs"
        ),
        "",
    ])

    # ==========================================================
    # FINANCE
    # ==========================================================

    if total is not None:

        lines.append(
            f"💰 *Total del turno:* "
            f"{_fmt_precio(total)}"
        )

    if deposit_required is not None:

        lines.append(
            f"💵 *Seña requerida:* "
            f"{_fmt_precio(deposit_required)}"
        )

    if paid is not None:

        paid_label = (
            "Transferencia recibida"
            if "transferencia"
            in payment_method
            else "Pagado hasta ahora"
        )

        lines.append(
            f"💳 *{paid_label}:* "
            f"{_fmt_precio(paid)}"
        )

    if cash_deposit_due > 0:

        lines.append(
            "💵 *Diferencia de la seña para "
            "pagar en efectivo:* "
            f"{_fmt_precio(cash_deposit_due)}"
        )

    if balance_due is not None:

        lines.append(
            "💸 *Total pendiente para abonar "
            "en el complejo:* "
            f"{_fmt_precio(balance_due)}"
        )

    status_label = (
        _integrated_scheduler_payment_status_label(
            deposit_status
        )
    )

    if (
        deposit_status.casefold()
        == "parcial_efectivo_pendiente"
    ):

        status_label = (
            "Turno firme - "
            "seña parcial + efectivo pendiente"
        )

    lines.append(
        f"📌 *Estado:* "
        f"{status_label}"
    )

    notes = (
        _integrated_scheduler_admin_display_notes(
            event.get(
                "notes"
            )
        )
    )

    if notes:

        lines.extend([
            "",
            (
                f"📝 *Observaciones:* "
                f"{notes}"
            ),
        ])

    return (
        _with_admin_alert_quick_commands(
            "\n".join(
                lines
            ),
            phone,
            reservation_id,
        )
    )

def build_integrated_scheduler_client_reminder(event: Dict[str, Any]) -> str:
    event_dt = _parse_iso_datetime(event.get("event_datetime"))
    hour = event_dt.strftime("%H:%M") if event_dt else ""
    name = str(event.get("customer_name") or "").strip()
    greeting = f"Hola {name}!" if name and name.casefold() not in {"yo", "cliente"} else "Hola!"
    return (
        "🔔 *RECORDATORIO DE TURNO*\n\n"
        f"{greeting} Te esperamos hoy a las *{hour}* en "
        f"*{event.get('court') or BUSINESS_NAME}*.\n\n"
        f"📍 Dirección: {BUSINESS_ADDRESS}\n\n"
        "Si necesitás reprogramar, avisanos con tiempo por este mismo chat."
    )


def build_integrated_scheduler_no_ok_alert(event: Dict[str, Any]) -> str:
    """V188: compatibilidad nominal; la alerta por falta de ACK fue eliminada."""
    return ""


def _integrated_scheduler_no_ok_due(
    event: Dict[str, Any],
    now: datetime.datetime,
) -> bool:
    """V188: la falta de respuesta al recordatorio nunca genera alerta admin."""
    return False


def build_integrated_scheduler_owner_reminder(
    event: Dict[str, Any],
    minutes_before: int,
) -> str:
    event_dt = _parse_iso_datetime(event.get("event_datetime"))
    event_time = event_dt.strftime("%d/%m %H:%M") if event_dt else "sin fecha"
    return _with_admin_alert_quick_commands((
        f"⚠️ *ALERTA DE TURNO - {minutes_before} MINUTOS* ⏰\n\n"
        "📋 *DATOS DEL TURNO:*\n"
        f"👤 *Cliente:* {event.get('customer_name') or 'No disponible'}\n"
        f"📅 *Fecha/Hora:* {event_time}\n"
        f"🏟️ *Cancha:* {event.get('court') or 'No disponible'}\n"
        f"📱 *Teléfono:* {event.get('user_phone') or 'No disponible'}\n\n"
        "🟢 *Estado:* Próximo a comenzar\n"
        f"🔔 El turno comienza en {minutes_before} minutos\n"
        "✅ Preparar cancha y recepción"
    ), event.get("user_phone") or "", context_kind="attendance_pending")


def _integrated_scheduler_daily_summary_due(
    state: Dict[str, Any],
    now: datetime.datetime,
) -> Tuple[bool, str]:
    summary_time = _integrated_scheduler_daily_time()
    hour, minute = [int(part) for part in summary_time.split(":")]
    due_at = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
    key = f"scheduler_daily_summary|{now.date().isoformat()}"
    sent = (state.get("sent") or {}).get(key)
    return bool(now >= due_at and not sent), key


async def ejecutar_alertas_scheduler_integradas(
    page,
    force: bool = False,
    now: Optional[datetime.datetime] = None,
) -> Dict[str, Any]:
    """
    AlertScheduler dentro del único loop/página de WPSetter.

    Correcciones:
      - sincroniza desde la fuente operativa robusta,
        no sólo listar_reservas();
      - conserva/rescata eventos futuros firmes aunque
        hayan quedado en histórico;
      - envía el recordatorio al cliente a
        CLIENT_REMINDER_MINUTES_BEFORE (120 min);
      - la agenda diaria usa fecha ISO explícita.
    """
    global _LAST_INTEGRATED_ALERT_SCHEDULER_TS
    now_ts = time.time()
    interval = max(
        1,
        _integrated_scheduler_config_int("SCHEDULER_CHECK_INTERVAL_SECONDS", 3),
    )
    if not force and now_ts - _LAST_INTEGRATED_ALERT_SCHEDULER_TS < interval:
        return {"ok": True, "throttled": True, "sent": 0}
    _LAST_INTEGRATED_ALERT_SCHEDULER_TS = now_ts

    now = now or datetime.datetime.now(TIMEZONE)
    if now.tzinfo is None:
        now = TIMEZONE.localize(now)
    sync = _integrated_scheduler_sync_calendar_operational(now)
    if not sync.get("ok"):
        return {"ok": False, "sent": 0, "sync": sync}
    _repair_admin_client_attendance_flags_v235_once(now)

    sent_count = 0
    events = _integrated_scheduler_events()
    final_owner_before = _integrated_scheduler_config_int(
        "FINAL_OWNER_REMINDER_MINUTES_BEFORE",
        5,
    )
    client_before = _integrated_scheduler_config_int(
        "CLIENT_REMINDER_MINUTES_BEFORE",
        120,
    )

    # 1) La reserva firme se comunica al encargado antes de sus recordatorios.
    for event in events:
        if int(event.get("coordination_alert_sent") or 0):
            continue
        if await enviar_aviso_admin_directo(
            page,
            build_integrated_scheduler_booking_alert(event),
            dedupe_key=f"scheduler_booking|{event.get('event_key') or event.get('id')}",
            attachment_path=BOOKINGS_CSV,
            attachment_title="📅 *CALENDARIO DE TURNOS*",
            respect_inbox=True,
        ):
            _integrated_scheduler_update_event(
                event["id"],
                coordination_alert_sent=1,
            )
            sent_count += 1
            registrar_metrica_operativa("scheduler_turno_confirmado_admin", {
                "event_id": event.get("id"),
                "event_key": event.get("event_key"),
            })
        if sent_count >= 4:
            return {"ok": True, "sent": sent_count, "sync": sync}

    # 2) Un único mensaje al cliente dos horas antes, ya con confirmación OK.
    events = _integrated_scheduler_events()
    for event in events:
        event_dt = _parse_iso_datetime(event.get("event_datetime"))
        if not event_dt:
            continue
        remaining = (event_dt - now).total_seconds() / 60.0
        if remaining <= 0:
            _integrated_scheduler_update_event(event["id"], status="expired")
            continue
        already_sent = bool(
            int(event.get("alert_30min_sent") or 0)
            and int(event.get("attendance_confirmation_sent") or 0)
        )
        reminder_due = bool(
            client_before > 0
            and 0 < remaining <= client_before
            and not already_sent
        )
        if reminder_due:
            row = _integrated_scheduler_event_as_row(event)
            phone = _telefono_reserva_para_mensaje(row)
            if not phone:
                print(
                    "   ⚠️ [SCHEDULER CLIENT REMINDER] "
                    f"evento={event.get('id')} sin teléfono; no marco entrega"
                )
                registrar_metrica_operativa(
                    "scheduler_recordatorio_cliente_sin_telefono",
                    {"event_id": event.get("id")},
                )
                continue
            if obtener_pausa_contacto_humano(phone):
                print(
                    "   ⏸️ [SCHEDULER CLIENT REMINDER] "
                    f"telefono={phone} pausado por humano; reintento pendiente"
                )
                continue
            sent = await enviar_mensaje_cliente_por_reserva(
                page,
                row,
                build_integrated_scheduler_client_reminder(event),
                respetar_inbox=True,
            )
            if sent:
                _integrated_scheduler_update_event(
                    event["id"],
                    alert_30min_sent=1,
                    attendance_confirmation_sent=1,
                )
                sent_count += 1
                registrar_metrica_operativa("scheduler_recordatorio_cliente_2h", {
                    "event_id": event.get("id"),
                    "telefono": phone,
                    "minutes_before_config": client_before,
                    "remaining_minutes": round(remaining, 2),
                })
                print(
                    "   🔔 [SCHEDULER CLIENT REMINDER] "
                    f"enviado event_id={event.get('id')} "
                    f"phone={phone} remaining={remaining:.1f}m"
                )
            else:
                print(
                    "   ⚠️ [SCHEDULER CLIENT REMINDER] "
                    f"no enviado event_id={event.get('id')} "
                    f"phone={phone}; queda pendiente"
                )
            if _reactive_handoff_pending() or not sent:
                return {"ok": True, "sent": sent_count, "sync": sync}
            if sent_count >= 4:
                return {"ok": True, "sent": sent_count, "sync": sync}

    # 3) Si el cliente no respondió OK, el encargado lo sabe 45 min antes.
    events = _integrated_scheduler_events()
    for event in events:
        if _integrated_scheduler_no_ok_due(event, now):
            if await enviar_aviso_admin_directo(
                page,
                build_integrated_scheduler_no_ok_alert(event),
                dedupe_key=f"scheduler_no_ok|{event.get('event_key') or event.get('id')}",
                respect_inbox=True,
            ):
                _integrated_scheduler_update_event(
                    event["id"],
                    attendance_no_response_alert_sent=1,
                )
                sent_count += 1
                registrar_metrica_operativa("scheduler_cliente_sin_ok_admin", {
                    "event_id": event.get("id"),
                })
            if sent_count >= 4:
                return {"ok": True, "sent": sent_count, "sync": sync}

    # 4) Último aviso al encargado según config (5 min en la configuración actual).
    events = _integrated_scheduler_events()
    for event in events:
        event_dt = _parse_iso_datetime(event.get("event_datetime"))
        if not event_dt:
            continue
        remaining = (event_dt - now).total_seconds() / 60.0
        if (
            final_owner_before > 0
            and 0 < remaining <= final_owner_before
            and not int(event.get("alert_5min_sent") or 0)
        ):
            if await enviar_aviso_admin_directo(
                page,
                build_integrated_scheduler_owner_reminder(
                    event,
                    final_owner_before,
                ),
                dedupe_key=f"scheduler_owner_final|{event.get('event_key') or event.get('id')}",
                respect_inbox=True,
            ):
                _integrated_scheduler_update_event(event["id"], alert_5min_sent=1)
                sent_count += 1
                registrar_metrica_operativa("scheduler_recordatorio_admin_final", {
                    "event_id": event.get("id"),
                    "minutes_before": final_owner_before,
                })
            if sent_count >= 4:
                return {"ok": True, "sent": sent_count, "sync": sync}

    # 5) Resumen diario a las 08:00 o en la primera ventana ociosa posterior.
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    daily_due, daily_key = _integrated_scheduler_daily_summary_due(state, now)
    if daily_due:
        agenda_date = now.date().isoformat()
        if await enviar_aviso_admin_directo(
            page,
            build_turnos_dia_message(agenda_date),
            dedupe_key=daily_key,
            respect_inbox=True,
        ):
            latest = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
            latest.setdefault("sent", {})[daily_key] = now.isoformat()
            latest["updated_at"] = now.isoformat()
            _json_write(PROACTIVE_STATE_FILE, latest)
            sent_count += 1
            registrar_metrica_operativa("scheduler_resumen_diario_admin", {
                "date": now.date().isoformat(),
                "scheduled_time": _integrated_scheduler_daily_time(),
            })

    return {"ok": True, "sent": sent_count, "sync": sync}


def build_turno_fijo_generado_cliente_message(resultado: Dict[str, Any], turno_fijo: Dict[str, Any]) -> str:
    dia = resultado.get("dia") or ""
    hora = resultado.get("hora") or turno_fijo.get("hora") or ""
    cancha = resultado.get("cancha") or turno_fijo.get("cancha") or ""
    senia = _monto_a_int(resultado.get("senia_valor"))
    if senia is None:
        senia = _senia_para_total(
            resultado.get("precio_total")
            or calcular_precio_total(
                turno_fijo.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
            )
        )
    return (
        f"Te aviso que ya te dejé reservado tu turno fijo semanal para {dia} "
        f"a las {formatear_hora_para_mensaje(hora)} en {cancha}.\n\n"
        f"Mandame el comprobante de la seña de {_monto_humano(senia)} para confirmarlo."
    )


def build_recordatorio_senia_cliente_message(row: Dict[str, Any], minutos_restantes: int) -> str:
    fecha = str(row.get("fecha") or "").replace("/2026", "")
    hora = str(row.get("hora") or "").strip()
    cancha = str(row.get("cancha") or "").strip()
    partes = [p for p in [fecha, f"a las {formatear_hora_para_mensaje(hora)}" if hora else "", f"en {cancha}" if cancha else ""] if p]
    detalle = " ".join(partes)
    return (
        f"Todavía no me llegó el comprobante de la seña para tu turno{f' de {detalle}' if detalle else ''}. "
        f"Mandámelo cuando puedas; si no llega en unos {max(1, int(minutos_restantes))} minutos, liberamos el horario."
    )


def reserva_es_turno_fijo_pendiente_senia(
    row: Dict[str, Any],
    telefono_cliente: str,
    nombre: str,
    turno_fijo: Dict[str, Any]
) -> bool:
    if not _reserva_activa(row):
        return False
    if str(row.get("senia_estado") or "").strip().lower() != "pendiente":
        return False

    telefono_row = normalize_phone(row.get("telefono") or "")
    telefono_objetivo = normalize_phone(telefono_cliente or "")
    nombre_row = str(row.get("nombre") or "").strip().casefold()
    nombre_objetivo = str(nombre or "").strip().casefold()
    mismo_cliente = bool(
        (telefono_objetivo and telefono_row == telefono_objetivo)
        or (nombre_objetivo and nombre_row == nombre_objetivo)
    )
    if not mismo_cliente:
        return False

    origen = " ".join(str(row.get(campo) or "") for campo in ("website", "notas")).casefold()
    if "turno fijo" in origen:
        return True

    fecha_row = _parse_reserva_datetime(row)
    try:
        dia_semana = int(turno_fijo.get("dia_semana"))
    except Exception:
        dia_semana = None
    misma_frecuencia = bool(fecha_row and dia_semana is not None and fecha_row.weekday() == dia_semana)
    misma_hora = normalizar_hora_detectada(row.get("hora")) == normalizar_hora_detectada(turno_fijo.get("hora"))
    misma_cancha = str(row.get("cancha") or "").strip().casefold() == str(turno_fijo.get("cancha") or "").strip().casefold()
    return misma_frecuencia and misma_hora and misma_cancha


def buscar_turno_fijo_pendiente_senia(
    reservas_activas: List[Dict[str, Any]],
    telefono_cliente: str,
    nombre: str,
    turno_fijo: Dict[str, Any]
) -> Optional[Dict[str, Any]]:
    for row in reservas_activas:
        if reserva_es_turno_fijo_pendiente_senia(row, telefono_cliente, nombre, turno_fijo):
            return row
    return None


async def generar_turnos_fijos_proactivos(page, sent: Dict[str, Any], ahora: datetime.datetime) -> None:
    memorias = _json_read(CLIENT_MEMORY_FILE, {})
    if not isinstance(memorias, dict):
        return

    reservas_activas = [row for row in calendario.listar_reservas() if _reserva_activa(row)]

    for cliente_id, memoria in list(memorias.items()):
        turno_fijo = (memoria or {}).get("turno_fijo") or {}
        if not turno_fijo or not turno_fijo.get("activo"):
            continue

        try:
            dia_semana = int(turno_fijo.get("dia_semana"))
        except Exception:
            registrar_metrica_operativa("turno_fijo_invalido", {"cliente_id": cliente_id, "turno_fijo": turno_fijo})
            continue

        hora = normalizar_hora_detectada(turno_fijo.get("hora"))
        cancha = normalizar_valor_nullable(turno_fijo.get("cancha"))
        if not hora_es_valida(hora) or not cancha:
            registrar_metrica_operativa("turno_fijo_incompleto", {"cliente_id": cliente_id, "turno_fijo": turno_fijo})
            continue

        fecha_obj = _proxima_fecha_para_dia_semana(dia_semana, ahora.date())
        dia_texto = fecha_obj.strftime("%d/%m/%Y")
        if str(turno_fijo.get("ultima_reserva_fecha") or "") == fecha_obj.isoformat():
            continue

        key = f"turno_fijo|{cliente_id}|{fecha_obj.isoformat()}|{hora}|{cancha}"
        if sent.get(key):
            continue

        nombre = str(memoria.get("nombre") or "").strip()
        telefono_cliente = normalize_phone(memoria.get("telefono") or cliente_id)
        if not telefono_cliente and str(cliente_id).startswith("NOMBRE:"):
            telefono_cliente = cliente_id
            nombre = nombre or cliente_id.replace("NOMBRE:", "", 1).strip()
        if obtener_pausa_contacto_humano(telefono_cliente):
            continue

        turno_fijo_pendiente = buscar_turno_fijo_pendiente_senia(
            reservas_activas,
            telefono_cliente or cliente_id,
            nombre,
            turno_fijo
        )
        if turno_fijo_pendiente:
            registrar_metrica_operativa("turno_fijo_bloqueado_por_senia_pendiente", {
                "cliente_id": cliente_id,
                "turno_fijo": turno_fijo,
                "pendiente": turno_fijo_pendiente,
                "proximo_intento": {
                    "dia": dia_texto,
                    "hora": hora,
                    "cancha": cancha,
                }
            })
            continue

        ya_existe = any(
            _reserva_coincide_slot(row, dia_texto, hora, cancha)
            and (
                normalize_phone(row.get("telefono") or "") == normalize_phone(telefono_cliente or "")
                or str(row.get("nombre") or "").strip().casefold() == nombre.casefold()
            )
            for row in reservas_activas
        )
        if ya_existe:
            turno_fijo["ultima_reserva_fecha"] = fecha_obj.isoformat()
            memoria["turno_fijo"] = turno_fijo
            guardar_memoria_cliente(cliente_id, memoria)
            sent[key] = ahora.isoformat()
            registrar_metrica_operativa("turno_fijo_ya_existia", {"cliente_id": cliente_id, "dia": dia_texto, "hora": hora, "cancha": cancha})
            continue

        prospecto_fijo = {
            "nombre": nombre or "Turno fijo",
            "negocio": nombre or "Turno fijo",
            "telefono": telefono_cliente or cliente_id,
            "website": "Turno fijo semanal",
            "whatsapp_link": "",
            "es_cliente": CLIENTE_SI,
        }
        resultado = reservar_turno_en_calendario(
            telefono_cliente or cliente_id,
            prospecto_fijo,
            dia_texto,
            hora,
            cancha=cancha,
            estado_reserva=BOOKING_STATUS_PENDING,
            senia_estado="pendiente",
            senia_monto="",
            duracion_horas=turno_fijo.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )

        if resultado.get("ok"):
            turno_fijo["ultima_reserva_fecha"] = fecha_obj.isoformat()
            turno_fijo["ultima_generacion"] = ahora.isoformat()
            memoria["turno_fijo"] = turno_fijo
            guardar_memoria_cliente(cliente_id, memoria)
            sent[key] = ahora.isoformat()
            mensaje_cliente = build_turno_fijo_generado_cliente_message(resultado, turno_fijo)
            row_aviso = {
                "fecha": resultado.get("dia") or dia_texto,
                "hora": resultado.get("hora") or hora,
                "cancha": resultado.get("cancha") or cancha,
                "telefono": telefono_cliente or cliente_id,
                "nombre": nombre,
            }
            enviado = await enviar_mensaje_cliente_por_reserva(page, row_aviso, mensaje_cliente)
            if _reactive_handoff_pending():
                print("   🔁 [INBOX HANDOFF] turno fijo cede al mensaje entrante")
                return
            if enviado:
                update_conversation_state(
                    telefono_cliente or cliente_id,
                    fase="senia_pendiente",
                    dia_propuesto=resultado.get("dia") or dia_texto,
                    hora_propuesta=resultado.get("hora") or hora,
                    cancha_propuesta=resultado.get("cancha") or cancha,
                    duracion_propuesta=turno_fijo.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS,
                    senia_estado="pendiente",
                    senia_monto=_monto_humano(
                        _monto_a_int(resultado.get("senia_valor"))
                        if _monto_a_int(resultado.get("senia_valor")) is not None
                        else _senia_para_total(resultado.get("precio_total"))
                    )
                )
                add_to_history(telefono_cliente or cliente_id, "assistant", mensaje_cliente)
                enqueue_pending_booking_admin_alert(
                    resultado,
                    telefono_cliente or cliente_id,
                    prospecto_fijo,
                )
            registrar_metrica_operativa("turno_fijo_generado", {
                "cliente_id": cliente_id,
                "dia": dia_texto,
                "hora": hora,
                "cancha": cancha,
                "aviso_cliente": enviado,
            })
            continue

        sent[key] = ahora.isoformat()
        await enviar_aviso_admin_operativo(
            page,
            (
                f"No pude generar turno fijo de {nombre or cliente_id}: "
                f"{dia_texto} {hora} {cancha}. Motivo: {resultado.get('respuesta') or resultado.get('motivo') or 'sin detalle'}"
            )
        )
        registrar_metrica_operativa("turno_fijo_no_generado", {
            "cliente_id": cliente_id,
            "dia": dia_texto,
            "hora": hora,
            "cancha": cancha,
            "motivo": resultado.get("motivo") or resultado.get("respuesta")
        })


async def ejecutar_followups_post_turno_integrados(
    page,
    ahora: Optional[datetime.datetime] = None,
    max_messages: int = 2,
) -> Dict[str, Any]:
    """Ejecuta el follow-up a los 5 minutos sin depender del barrido de 10 min."""
    now = ahora or datetime.datetime.now(TIMEZONE)
    if now.tzinfo is None:
        now = TIMEZONE.localize(now)
    proactive_state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    sent = proactive_state.setdefault("sent", {})
    rows = []
    seen = set()
    for source_name, source_rows in (
        ("finished", calendario._leer_terminadas()),
        ("active", calendario._leer_todos()),
    ):
        for raw in source_rows or []:
            row = dict(raw)
            row["_post_turno_source"] = source_name
            key = _post_turno_followup_key(row)
            if key in seen:
                continue
            seen.add(key)
            rows.append(row)

    delivered = 0
    for row in rows:
        if (
            not _reserva_habilita_post_turno_followup(row)
            or not _post_turno_followup_due(row, now)
        ):
            continue
        key = _post_turno_followup_key(row)
        if sent.get(key):
            continue
        propuesta = _propuesta_semana_siguiente(row)
        telefono_cliente = _telefono_reserva_para_mensaje(row)
        if not propuesta or not telefono_cliente:
            sent[key] = now.isoformat()
            registrar_metrica_operativa(
                "post_turno_followup_sin_destino",
                {"reserva": row},
            )
            continue
        if cliente_tiene_post_turno_followup_enviado(telefono_cliente, row):
            sent[key] = now.isoformat()
            continue
        if obtener_pausa_contacto_humano(telefono_cliente):
            continue

        mensaje_cliente = build_post_turno_followup_message(row, propuesta)
        enviado = await enviar_mensaje_cliente_por_reserva(
            page,
            row,
            mensaje_cliente,
            respetar_inbox=True,
        )
        if _reactive_handoff_pending():
            proactive_state["updated_at"] = now.isoformat()
            _json_write(PROACTIVE_STATE_FILE, proactive_state)
            return {"ok": True, "sent": delivered, "handoff": True}
        registrar_post_turno_followup_memoria(
            telefono_cliente,
            row,
            propuesta,
            "enviado" if enviado else "fallido",
            sent_at=now,
        )
        if not enviado:
            proactive_state["updated_at"] = now.isoformat()
            _json_write(PROACTIVE_STATE_FILE, proactive_state)
            return {"ok": False, "sent": delivered}

        followup_expires_at = now + datetime.timedelta(
            hours=_post_turno_followup_ttl_hours()
        )
        # Esta propuesta es memoria lateral. No cambia la fase ni escribe el
        # draft operativo principal de la conversación.
        followup_payload = {
            "activo": True,
            "estado": "ofrecido",
            "origen": row,
            "dia": propuesta["dia"],
            "hora": propuesta["hora"],
            "cancha": propuesta.get("cancha"),
            "duracion_horas": propuesta.get("duracion_horas"),
            "recurring_series_id": propuesta.get("recurring_series_id"),
            "recurring_plan": copy.deepcopy(propuesta.get("recurring_plan") or {}),
            "renewal_kind": propuesta.get("renewal_kind"),
            "mensaje_enviado": mensaje_cliente,
            "sent_at": now.isoformat(),
            "expires_at": followup_expires_at.isoformat(),
        }
        update_conversation_state(
            telefono_cliente,
            post_turno_followup=followup_payload,
        )
        canonical_pending_setter = globals().get("_canonical_v188_set_repeat_pending")
        if callable(canonical_pending_setter):
            canonical_pending_setter(telefono_cliente, followup_payload)
        add_to_history(telefono_cliente, "assistant", mensaje_cliente)
        sent[key] = now.isoformat()
        delivered += 1
        registrar_metrica_operativa(
            "post_turno_followup_enviado",
            {"telefono": telefono_cliente, "reserva": row, "propuesta": propuesta},
        )
        proactive_state["updated_at"] = now.isoformat()
        _json_write(PROACTIVE_STATE_FILE, proactive_state)
        if delivered >= max(1, int(max_messages)):
            break

    proactive_state["updated_at"] = now.isoformat()
    _json_write(PROACTIVE_STATE_FILE, proactive_state)
    return {"ok": True, "sent": delivered}


async def ejecutar_tareas_proactivas(page) -> None:
    # AlertScheduler integrado corre únicamente desde la rama que ya verificó
    # inbox vacío. Tiene su propio intervalo corto y comparte esta misma página.
    expirar_post_turno_followups_vencidos()
    recurring_reconciler = globals().get("_v195_reconcile_recurring_plans")
    if callable(recurring_reconciler):
        recurring_reconciler()
    reconcile_pending_booking_admin_alerts()
    reconcile_pending_event_registration_admin_alerts()
    await flush_admin_alert_queue(page, max_deliveries=20, respect_inbox=True)
    if _reactive_handoff_pending():
        return
    await ejecutar_alertas_scheduler_integradas(page)
    if _reactive_handoff_pending():
        return
    await ejecutar_followups_post_turno_integrados(page)
    if _reactive_handoff_pending():
        return

    ahora_ts = time.time()
    if ahora_ts - float(getattr(bot_state, "last_proactive_run", 0) or 0) < PROACTIVE_TASK_INTERVAL_SECONDS:
        return
    bot_state.last_proactive_run = ahora_ts
    bot_state.save()

    estado = obtener_estado_operativo_predio()
    proactive_state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    sent = proactive_state.setdefault("sent", {})
    pending_seen = proactive_state.setdefault("pending_deposit_seen_at", {})
    ahora = datetime.datetime.now(TIMEZONE)

    tareas = []
    pending_keys_vivos = set()

    await generar_turnos_fijos_proactivos(page, sent, ahora)
    if _reactive_handoff_pending():
        proactive_state["updated_at"] = ahora.isoformat()
        _json_write(PROACTIVE_STATE_FILE, proactive_state)
        print("   🔁 [INBOX HANDOFF] aborto tareas proactivas → cede al router reactivo")
        return

    # V2.10.4: las señas pendientes ya NO vencen dentro del scheduler general.
    # El hold crítico de 10 minutos lo gobierna expirar_holds_senia_vencidos(),
    # independiente de PROACTIVE_TASK_INTERVAL_SECONDS y sin navegar al chat.
    for row in estado.get("turnos_senia_pendiente") or []:
        expiration_key = _pending_hold_key(row)
        pending_keys_vivos.add(expiration_key)
        if not _pending_hold_started_at_from_state(proactive_state, row):
            registrar_inicio_senia_pendiente(row)
            # Rehidratar porque registrar_inicio persiste en disco.
            proactive_state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
            sent = proactive_state.setdefault("sent", {})
            pending_seen = proactive_state.setdefault("pending_deposit_seen_at", {})

    for old_key in list(pending_seen.keys()):
        if old_key not in pending_keys_vivos:
            pending_seen.pop(old_key, None)

    for item in estado.get("huecos_pico_vacios") or []:
        key = f"hueco_pico|{item.get('dia')}|{item.get('hora')}|{item.get('cancha')}"
        if sent.get(key):
            continue
        tareas.append({
            "tipo": "hueco_pico",
            "key": key,
            "texto": f"Hueco pico libre: {item.get('dia')} {item.get('hora')} en {item.get('cancha')}. Podés ofrecerlo a clientes frecuentes.",
            "row": item
        })
        break

    for dup in estado.get("reservas_duplicadas_sospechosas") or []:
        key = f"duplicada|{dup.get('slot')}"
        if sent.get(key):
            continue
        tareas.append({
            "tipo": "reserva_duplicada",
            "key": key,
            "texto": f"Posible doble reserva detectada en slot {dup.get('slot')}. Revisar calendario antes de confirmar más cambios.",
            "row": dup
        })

    for tarea in tareas[:6]:
        registrar_metrica_operativa("tarea_proactiva_detectada", tarea)
        await enviar_aviso_admin_operativo(page, tarea["texto"])
        sent[tarea["key"]] = ahora.isoformat()

    proactive_state["updated_at"] = ahora.isoformat()
    _json_write(PROACTIVE_STATE_FILE, proactive_state)


# ================================
# FUNCIÓN: PARSEAR DÍA Y HORA A OBJETO DATETIME
# ================================
def parse_to_datetime(dia_resuelto: str, hora: str) -> datetime.datetime:
    try:
        now = datetime.datetime.now(TIMEZONE)

        date_match = re.search(r'(\d{1,2})/(\d{1,2})', dia_resuelto)
        if date_match:
            day = int(date_match.group(1))
            month = int(date_match.group(2))
            year = now.year

            if month < now.month or (month == now.month and day < now.day):
                year += 1

            event_date = datetime.date(year, month, day)

        elif "mañana" in dia_resuelto.lower():
            event_date = now.date() + datetime.timedelta(days=1)
        elif "hoy" in dia_resuelto.lower():
            event_date = now.date()
        else:
            for i, dia_nombre in enumerate(NOMBRES_DIAS):
                if dia_nombre.lower() in dia_resuelto.lower():
                    days_ahead = (i - now.weekday()) % 7
                    if days_ahead == 0:
                        days_ahead = 7
                    event_date = now.date() + datetime.timedelta(days=days_ahead)
                    break
            else:
                event_date = now.date() + datetime.timedelta(days=1)

        if ':' in hora:
            hour, minute = map(int, hora.split(':'))
        else:
            hour = int(hora)
            minute = 0

        event_datetime = TIMEZONE.localize(datetime.datetime(
            event_date.year, event_date.month, event_date.day, hour, minute
        ))

        if event_datetime <= now:
            event_datetime += datetime.timedelta(days=1)

        return event_datetime

    except Exception as e:
        print(f"⚠️ [CALENDARIO] Error parseando fecha: {e}")
        tomorrow = now + datetime.timedelta(days=1)
        return TIMEZONE.localize(datetime.datetime(
            tomorrow.year, tomorrow.month, tomorrow.day, 10, 0
        ))


def _agent_v2_midnight_display(value: Any) -> str:
    """Representación civil: medianoche siempre es 00:00, nunca 24:00."""
    raw = str(value or "").strip()
    normalized = normalizar_hora_config(raw)
    if normalized == "24:00" or raw in {"24", "24hs", "24:00hs"}:
        return "00:00"
    return normalized or raw


def _business_knowledge_snapshot() -> Dict[str, Any]:
    """Fuente de verdad configurable para consultas informativas del cliente."""
    # Puede ser llamado desde flujos legacy fuera del runtime V2. El stat evita
    # servir conocimiento viejo después de un comando admin.
    try:
        _refresh_runtime_config_if_changed(reason="business_snapshot")
    except NameError:
        # Durante import inicial el helper todavía puede no estar definido.
        pass
    courts = []
    for court in (COURTS or []):
        if isinstance(court, dict):
            courts.append({
                "nombre": court.get("name") or court.get("nombre") or "",
                "tipo": court.get("type") or court.get("tipo") or "",
                "datos": {k: v for k, v in court.items() if k not in {"name", "nombre", "type", "tipo"}},
            })
        else:
            courts.append({"nombre": str(court), "tipo": "", "datos": {}})

    return {
        "negocio": BUSINESS_NAME,
        "direccion": BUSINESS_ADDRESS,
        "canchas": courts,
        "servicios": [dict(item) for item in (BUSINESS_SERVICES or []) if isinstance(item, dict)],
        "precios": PRICES,
        "quincho_habilitado": bool(CON_QUINCHO),
        "quinchos": QUINCHOS,
        "precios_quincho": QUINCHOS_PRICES,
        "requiere_senia": bool(REQUIRES_DEPOSIT),
        "modalidad_senia": DEPOSIT_MODE,
        "monto_senia": DEPOSIT_AMOUNT,
        "porcentaje_senia": DEPOSIT_PERCENTAGE,
        "alias_pago": PAYMENT_ALIAS,
        "politica_cancelacion": CANCELLATION_POLICY,
        # V2.8: las reglas de duración son conocimiento del negocio, no contexto de calendario.
        # Permite responder preguntas como “¿se puede hora y media?” sin listar turnos.
        "duracion_slot_minutos": int(TURN_DURATION_MINUTES),
        "duracion_default_horas": float(DEFAULT_TURN_DURATION_HOURS),
        "duraciones_permitidas_horas": [
            float(x) for x in (ALLOWED_TURN_DURATIONS or [DEFAULT_TURN_DURATION_HOURS])
        ],
        "dias_atencion": descripcion_dias_atencion(),
        "dias_atencion_indices": [int(x) for x in (ATTENTION_DAYS or [])],
        "franjas_atencion": descripcion_franjas_atencion_mensaje(),
        "franjas_atencion_raw": [
            {
                "inicio": _agent_v2_midnight_display(inicio),
                "fin": _agent_v2_midnight_display(fin),
            }
            for inicio, fin in (CALL_TIME_WINDOWS or [])
        ],
        # La cantidad de canchas es un hecho de configuración. Permite responder
        # capacidad simultánea sin consultar el calendario ni asumir que dos
        # canchas tienen el mismo precio.
        "cantidad_canchas_configuradas": len(courts),
    }


async def responder_consulta_informativa_ia(
    pregunta: str,
    conv_state: Dict = None,
    prospecto: Dict = None,
) -> str:
    """
    Resuelve preguntas de conocimiento del negocio usando SOLO config como fuente de verdad.
    No toca calendario ni modifica el estado operativo de la reserva.
    """
    conv_state = conv_state or {}
    prospecto = prospecto or {}
    conocimiento = _business_knowledge_snapshot()
    historial = []
    for msg in conv_state.get("historial", [])[-10:]:
        historial.append({
            "role": "user" if msg.get("role") == "user" else "assistant",
            "content": str(msg.get("content") or ""),
        })

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        f"Sos {AGENT_NAME}, asistente de {BUSINESS_NAME}.\n"
                        "Respondé la pregunta informativa del cliente de forma directa, breve y natural.\n"
                        "FUENTE DE VERDAD: solo podés afirmar datos presentes en DATOS_CONFIG. "
                        "No inventes tipos de cancha, inclusiones, precios, políticas, medios de pago ni servicios.\n"
                        "Si pregunta varias cosas en el mismo fragmento, respondelas todas. "
                        "Una consulta sobre si un servicio está incluido NO significa que el cliente quiera reservarlo.\n"
                        "Si pregunta por duración (por ejemplo si acepta 1,5 h, 2 h o solo 1 h), respondé desde "
                        "duraciones_permitidas_horas. No listes disponibilidad salvo que también la haya pedido explícitamente.\n"
                        "No prometas 'voy a verificar' ni cambies el estado de una reserva. "
                        "Si falta el dato en config, decilo con claridad y ofrecé derivar esa consulta puntual.\n"
                        "Respondé SOLO el texto para WhatsApp."
                    ),
                },
                *historial,
                {
                    "role": "user",
                    "content": (
                        f"Cliente: {prospecto.get('nombre') or 'sin nombre'}\n"
                        f"DATOS_CONFIG: {json.dumps(conocimiento, ensure_ascii=False, default=str)}\n\n"
                        f"Pregunta actual: {pregunta}"
                    ),
                },
            ],
            temperature=0.1,
            max_tokens=240,
        )
        register_cost(resp)
        respuesta = (resp.choices[0].message.content or "").strip()
        return respuesta or "No tengo ese dato configurado todavía. Si querés, te lo confirma el encargado."
    except Exception as e:
        print(f"   ⚠️ [Consulta informativa] Error: {e}")
        return "No tengo ese dato confirmado en la configuración. Si querés, te lo confirma el encargado."



PENDING_COURT_SELECTION_TTL_MINUTES = 30
BOOKING_DRAFT_TTL_MINUTES = 45


def _parse_context_timestamp(value) -> Optional[datetime.datetime]:
    if not value:
        return None
    try:
        dt = datetime.datetime.fromisoformat(str(value))
        if dt.tzinfo is None:
            dt = TIMEZONE.localize(dt)
        return dt
    except Exception:
        return None


def _contexto_pendiente_sigue_adyacente(
    conv_state: Dict,
    contexto: Dict,
) -> bool:
    """
    Una decisión efímera solo pertenece al turno actual si, desde que se creó,
    existe exactamente UNA respuesta del agente: la pregunta/oferta que abrió
    esa decisión.

    Esto evita que un contexto de hace 20 minutos sobreviva únicamente porque
    su TTL todavía no venció.
    """
    if not isinstance(contexto, dict) or not contexto.get("activo", True):
        return False

    creado_dt = _parse_context_timestamp(contexto.get("creado_en"))
    if not creado_dt:
        return False

    respuestas_agente = 0
    for msg in (conv_state or {}).get("historial", []) or []:
        if not isinstance(msg, dict) or msg.get("role") != "assistant":
            continue
        msg_dt = _parse_context_timestamp(msg.get("timestamp"))
        if msg_dt and msg_dt >= creado_dt:
            respuestas_agente += 1

    return respuestas_agente == 1


def _ultimo_mensaje_asistente(conv_state: Dict) -> Dict[str, Any]:
    for msg in reversed((conv_state or {}).get("historial", []) or []):
        if isinstance(msg, dict) and msg.get("role") == "assistant":
            return {
                "content": str(msg.get("content") or ""),
                "timestamp": msg.get("timestamp"),
            }
    return {"content": "", "timestamp": None}


def sanear_contextos_transitorios_decision_engine(
    telefono: str,
    conv_state: Dict,
) -> Dict:
    """
    Descarta memoria efímera obsoleta sin tocar reserva real, cliente ni seña.
    """
    conv_state = conv_state or {}
    cambios = {}
    stale = []

    seleccion = conv_state.get("seleccion_cancha_pendiente")
    if isinstance(seleccion, dict) and not _contexto_pendiente_sigue_adyacente(conv_state, seleccion):
        cambios["seleccion_cancha_pendiente"] = None
        stale.append("seleccion_cancha")

        draft = conv_state.get("booking_draft")
        if isinstance(draft, dict) and draft.get("estado") == "esperando_cancha":
            cambios["booking_draft"] = None
            stale.append("booking_draft_esperando_cancha")

    consulta = conv_state.get("consulta_disponibilidad_pendiente")
    if isinstance(consulta, dict) and not _contexto_pendiente_sigue_adyacente(conv_state, consulta):
        cambios["consulta_disponibilidad_pendiente"] = None
        stale.append("consulta_disponibilidad")

    if conv_state.get("fase") == "esperando_aclaracion_hora":
        aclaracion = conv_state.get("aclaracion_hora_contexto")
        contexto_base = None

        if isinstance(aclaracion, dict) and aclaracion.get("creado_en"):
            contexto_base = aclaracion
        elif isinstance(aclaracion, dict):
            nested = aclaracion.get("consulta_disponibilidad")
            if isinstance(nested, dict):
                contexto_base = nested

        if contexto_base and not _contexto_pendiente_sigue_adyacente(conv_state, contexto_base):
            fase_previa = conv_state.get("fase_previa_hora") or "inicial"
            if fase_previa == "esperando_aclaracion_hora":
                fase_previa = "inicial"
            cambios.update({
                "fase": fase_previa,
                "hora_opciones": [],
                "fase_previa_hora": None,
                "aclaracion_hora_contexto": None,
            })
            stale.append("aclaracion_hora")

    if cambios:
        print(f"   🧹 [CONTEXT FRESHNESS] Descarto contexto efímero obsoleto: {stale}")
        update_conversation_state(telefono or "unknown", **cambios)
        return get_conversation_state(telefono or "unknown")

    return conv_state


def _booking_draft_activo(conv_state: Dict) -> Optional[Dict]:
    draft = (conv_state or {}).get("booking_draft")
    if not isinstance(draft, dict) or not draft.get("activo"):
        return None
    creado_en = draft.get("creado_en")
    if creado_en:
        try:
            creado_dt = datetime.datetime.fromisoformat(str(creado_en))
            if creado_dt.tzinfo is None:
                creado_dt = TIMEZONE.localize(creado_dt)
            if (
                datetime.datetime.now(TIMEZONE) - creado_dt
            ).total_seconds() > BOOKING_DRAFT_TTL_MINUTES * 60:
                return None
        except Exception:
            pass
    return draft


def crear_booking_draft_desde_oferta(
    telefono: str,
    dia: str,
    hora: str,
    canchas: List[str],
) -> Dict[str, Any]:
    """
    Crea un borrador NUEVO para la gestión actual.

    Invariante: ningún extra se hereda de una reserva o conversación anterior.
    El quincho empieza explícitamente en False.
    """
    draft = {
        "activo": True,
        "draft_id": str(uuid.uuid4()),
        "dia": str(dia or ""),
        "hora": normalizar_hora_detectada(hora) or str(hora or ""),
        "cancha": None,
        "canchas_opciones": [str(c) for c in (canchas or []) if str(c).strip()],
        "estado": "esperando_cancha",
        "addons": {
            "quincho": {
                "solicitado": False,
                "confirmado": False,
                "origen": None,
            }
        },
        "creado_en": datetime.datetime.now(TIMEZONE).isoformat(),
    }
    update_conversation_state(
        telefono or "unknown",
        booking_draft=draft,
    )
    print(
        f"   🧠 [BOOKING DRAFT] Nuevo borrador {draft['draft_id'][:8]}: "
        f"{draft['dia']} {draft['hora']} opciones={draft['canchas_opciones']} "
        "quincho=False"
    )
    return draft


def actualizar_booking_draft(
    telefono: str,
    **cambios,
) -> Optional[Dict]:
    state = get_conversation_state(telefono or "unknown")
    draft = _booking_draft_activo(state)
    if not draft:
        return None
    nuevo = dict(draft)
    nuevo.update(cambios)
    nuevo["actualizado_en"] = datetime.datetime.now(TIMEZONE).isoformat()
    update_conversation_state(telefono or "unknown", booking_draft=nuevo)
    return nuevo


def marcar_quincho_solicitado_en_draft(
    telefono: str,
    solicitado: bool,
    origen: str = "usuario",
) -> Optional[Dict]:
    state = get_conversation_state(telefono or "unknown")
    draft = _booking_draft_activo(state)
    if draft:
        nuevo = dict(draft)
        addons = dict(nuevo.get("addons") or {})
        q = dict(addons.get("quincho") or {})
        q.update({
            "solicitado": bool(solicitado),
            "confirmado": bool(solicitado),
            "origen": origen if solicitado else None,
        })
        addons["quincho"] = q
        nuevo["addons"] = addons
        nuevo["actualizado_en"] = datetime.datetime.now(TIMEZONE).isoformat()
        update_conversation_state(telefono or "unknown", booking_draft=nuevo)
        draft = nuevo

    update_conversation_state(
        telefono or "unknown",
        quincho_confirmacion_origen=origen if solicitado else None,
        con_quincho=bool(solicitado),
        **(
            {}
            if solicitado
            else {
                "quincho": "",
                "quincho_hora_inicio": "",
                "quincho_hora_fin": "",
                "quincho_duracion_horas": None,
            }
        ),
    )
    return draft


def quincho_autorizado_para_confirmacion(
    conv_state: Dict,
    dia: str = "",
    hora: str = "",
    cancha: str = "",
) -> bool:
    """
    Un bool viejo no alcanza para cobrar/reservar un extra.

    El quincho solo está autorizado para una NUEVA escritura si el borrador/estado
    actual demuestra que el usuario lo pidió explícitamente. Una reserva histórica
    puede conservar quincho para mostrar su estado, pero no transferirlo a otro turno.
    """
    conv_state = conv_state or {}
    draft = _booking_draft_activo(conv_state)
    if draft:
        # Si el draft corresponde al turno actual, su decisión manda sobre memoria vieja.
        draft_dia = str(draft.get("dia") or "")
        draft_hora = normalizar_hora_detectada(draft.get("hora"))
        mismo_dia = (
            not dia
            or not draft_dia
            or _misma_fecha_reserva({"fecha": draft_dia}, dia)
        )
        misma_hora = (
            not hora
            or not draft_hora
            or normalizar_hora_detectada(hora) == draft_hora
        )
        if mismo_dia and misma_hora:
            q = ((draft.get("addons") or {}).get("quincho") or {})
            return bool(q.get("solicitado") and q.get("origen") == "usuario")

    origen = str(conv_state.get("quincho_confirmacion_origen") or "")
    # "reserva_existente" sirve para describir la reserva real, NO para copiar
    # automáticamente ese extra a una operación nueva.
    return bool(
        conv_state.get("con_quincho")
        and origen == "usuario"
    )


def _reserva_indica_quincho(reserva: Dict) -> bool:
    valor = str((reserva or {}).get("con_quincho") or "").strip().lower()
    return valor in {"si", "sí", "true", "1", "yes"}


def _limpiar_quincho_del_draft(telefono: str) -> None:
    marcar_quincho_solicitado_en_draft(
        telefono or "unknown",
        False,
        origen="usuario",
    )


def guardar_seleccion_cancha_pendiente(
    telefono: str,
    dia: str,
    hora: str,
    canchas: List[str],
    fragmento_origen: str = "",
) -> None:
    """
    Guarda una OFERTA conversacional, no una reserva.

    Permite que una respuesta posterior como "la 2" / "Cancha 2" se interprete
    contra las opciones que el agente acaba de ofrecer, sin contaminar ni
    reemplazar una reserva activa.
    """
    if not telefono or not dia or not hora_es_valida(hora):
        return

    canchas_validas = []
    nombres_config = {
        str(court.get("name") or "").strip()
        for court in COURTS
        if isinstance(court, dict)
    }
    for cancha in canchas or []:
        nombre = str(cancha or "").strip()
        if nombre and nombre in nombres_config and nombre not in canchas_validas:
            canchas_validas.append(nombre)

    if not canchas_validas:
        update_conversation_state(
            telefono or "unknown",
            seleccion_cancha_pendiente=None,
        )
        return

    contexto = {
        "activo": True,
        "dia": str(dia),
        "hora": normalizar_hora_detectada(hora) or str(hora),
        "canchas": canchas_validas,
        "fragmento_origen": str(fragmento_origen or ""),
        "creado_en": datetime.datetime.now(TIMEZONE).isoformat(),
    }
    update_conversation_state(
        telefono or "unknown",
        seleccion_cancha_pendiente=contexto,
    )
    crear_booking_draft_desde_oferta(
        telefono or "unknown",
        contexto["dia"],
        contexto["hora"],
        contexto["canchas"],
    )
    print(
        f"   🧠 [MEMORIA OFERTA] Espero elección de cancha para "
        f"{contexto['dia']} {contexto['hora']}: {contexto['canchas']}"
    )


def obtener_seleccion_cancha_pendiente(conv_state: Dict) -> Optional[Dict]:
    contexto = (conv_state or {}).get("seleccion_cancha_pendiente")
    if not isinstance(contexto, dict) or not contexto.get("activo"):
        return None

    dia = str(contexto.get("dia") or "").strip()
    hora = normalizar_hora_detectada(contexto.get("hora"))
    canchas = [
        str(c).strip()
        for c in (contexto.get("canchas") or [])
        if str(c).strip()
    ]
    if not dia or not hora_es_valida(hora) or not canchas:
        return None

    creado_en = contexto.get("creado_en")
    if creado_en:
        try:
            creado_dt = datetime.datetime.fromisoformat(str(creado_en))
            if creado_dt.tzinfo is None:
                creado_dt = TIMEZONE.localize(creado_dt)
            ahora = datetime.datetime.now(TIMEZONE)
            if (ahora - creado_dt).total_seconds() > PENDING_COURT_SELECTION_TTL_MINUTES * 60:
                return None
        except Exception:
            pass

    if not _contexto_pendiente_sigue_adyacente(conv_state, contexto):
        return None

    return {
        **contexto,
        "dia": dia,
        "hora": hora,
        "canchas": canchas,
    }



PENDING_AVAILABILITY_CONTEXT_TTL_MINUTES = 30


def guardar_consulta_disponibilidad_pendiente(
    telefono: str,
    dia_consulta: str,
    fragmento_origen: str = "",
) -> None:
    """
    Guarda el tema conversacional "estamos mirando disponibilidad para este día".

    Es memoria efímera y NO modifica una reserva existente. Permite que una respuesta
    posterior como "a las 11" herede el día que el usuario acababa de consultar.
    """
    if not telefono or not dia_consulta:
        return

    dia_resuelto = resolver_fecha(dia_consulta)
    if not dia_resuelto:
        return

    contexto = {
        "activo": True,
        "dia_consulta": str(dia_consulta),
        "dia_resuelto": str(dia_resuelto),
        "fragmento_origen": str(fragmento_origen or ""),
        "creado_en": datetime.datetime.now(TIMEZONE).isoformat(),
    }
    update_conversation_state(
        telefono or "unknown",
        consulta_disponibilidad_pendiente=contexto,
    )
    print(
        f"   🧠 [MEMORIA DISPONIBILIDAD] Siguiente hora se interpretará para "
        f"{contexto['dia_resuelto']}"
    )


def obtener_consulta_disponibilidad_pendiente(conv_state: Dict) -> Optional[Dict]:
    contexto = (conv_state or {}).get("consulta_disponibilidad_pendiente")
    if not isinstance(contexto, dict) or not contexto.get("activo"):
        return None

    dia_resuelto = str(contexto.get("dia_resuelto") or "").strip()
    if not dia_resuelto:
        return None

    creado_en = contexto.get("creado_en")
    if creado_en:
        try:
            creado_dt = datetime.datetime.fromisoformat(str(creado_en))
            if creado_dt.tzinfo is None:
                creado_dt = TIMEZONE.localize(creado_dt)
            ahora = datetime.datetime.now(TIMEZONE)
            if (ahora - creado_dt).total_seconds() > PENDING_AVAILABILITY_CONTEXT_TTL_MINUTES * 60:
                return None
        except Exception:
            pass

    if not _contexto_pendiente_sigue_adyacente(conv_state, contexto):
        return None

    return contexto


def responder_hora_en_consulta_disponibilidad(
    telefono: str,
    contexto: Dict,
    hora: str,
) -> Optional[str]:
    """
    Resuelve una hora ya desambiguada dentro de la consulta de disponibilidad pendiente.

    No crea una reserva. Solo consulta calendario y, si hay opciones, deja preparada
    la siguiente decisión de cancha.
    """
    if not contexto or not hora_es_valida(hora):
        return None

    dia_resuelto = str(contexto.get("dia_resuelto") or "").strip()
    dia_consulta = str(contexto.get("dia_consulta") or dia_resuelto).strip()
    fragmento_origen = str(contexto.get("fragmento_origen") or dia_consulta).strip()
    if not dia_resuelto:
        return None

    canchas_libres = [
        court["name"] for court in COURTS
        if calendario.slot_esta_libre_en_cancha(
            dia_resuelto,
            hora,
            court["name"],
        )
    ]

    dia_txt = formatear_dia_para_cliente_con_mensaje(
        dia_consulta,
        fragmento_origen,
    )
    hora_txt = formatear_hora_para_mensaje(hora)

    if canchas_libres:
        canchas_txt = " o ".join(canchas_libres)
        guardar_seleccion_cancha_pendiente(
            telefono or "unknown",
            dia_resuelto,
            hora,
            canchas_libres,
            fragmento_origen=f"{dia_consulta} {hora}",
        )
        update_conversation_state(
            telefono or "unknown",
            consulta_disponibilidad_pendiente=None,
        )
        if len(canchas_libres) == 1:
            return (
                f"Para {dia_txt} a las {hora_txt} tengo {canchas_libres[0]} libre. "
                "¿Querés esa?"
            )
        return (
            f"Para {dia_txt} a las {hora_txt} tengo {canchas_txt} libre. "
            "¿Cuál preferís?"
        )

    return f"Para {dia_txt} a las {hora_txt} no tengo cancha libre."


READ_ONLY_INTENTS = {
    "pedir_horarios",
    "pedir_precio",
    "consulta_informativa",
    "consultar_mi_turno",
}


def lote_es_solo_lectura(sub_intenciones: List[Dict]) -> bool:
    """
    Decide por EFECTO, no solamente por la etiqueta de intención.

    Si el auditor semántico marcó un fragmento como ``lectura``, una etiqueta inicial
    imperfecta (por ejemplo reservar_quincho ante una pregunta sobre el quincho) no
    convierte la consulta en una mutación. Si el auditor no pudo ejecutarse, usamos
    las intenciones clásicas como fallback conservador.
    """
    if not sub_intenciones:
        return False

    evaluadas = []
    for item in sub_intenciones:
        if not isinstance(item, dict):
            continue
        tipo = str(item.get("intencion") or "").strip()
        efecto = str(item.get("efecto") or "").strip().lower()
        if efecto in {"lectura", "escritura"}:
            evaluadas.append(efecto == "lectura")
        else:
            evaluadas.append(tipo in READ_ONLY_INTENTS)

    return bool(evaluadas) and all(evaluadas)


async def resolver_lote_solo_lectura(
    sub_intenciones: List[Dict],
    conv_state: Dict = None,
    prospecto: Dict = None,
    telefono: str = None,
) -> Optional[str]:
    """
    Ejecuta TODAS las sub-intenciones informativas/read-only en orden.

    Invariante transaccional: esta función jamás crea, cambia ni cancela una reserva.
    Sí puede guardar una "oferta pendiente" efímera (día/hora/canchas ofrecidas) para
    interpretar correctamente la siguiente elección del usuario.
    """
    if not lote_es_solo_lectura(sub_intenciones):
        return None

    conv_state = conv_state or {}
    prospecto = prospecto or {}
    respuestas: List[str] = []

    # Para preguntas nuevas de disponibilidad no heredamos el día/hora/cancha de una
    # reserva pendiente. La memoria sigue disponible para consultas sobre "mi turno",
    # pero no debe contaminar un pedido nuevo como "qué tenés para el domingo".
    contexto_neutro = dict(conv_state)
    contexto_neutro["dia_propuesto"] = None
    contexto_neutro["hora_propuesta"] = None
    contexto_neutro["cancha_propuesta"] = None
    contexto_neutro["fase"] = "consulta_solo_lectura"
    contexto_neutro["historial"] = []

    for idx, item in enumerate(sub_intenciones, start=1):
        tipo = str(item.get("intencion") or "").strip()
        fragmento = str(item.get("fragmento") or "").strip()
        if not fragmento:
            continue

        print(f"   📚 [BATCH READ-ONLY {idx}/{len(sub_intenciones)}] {tipo}: {fragmento[:100]}")

        if tipo == "pedir_horarios":
            dia_consulta = await extraer_dia_con_ia(fragmento, contexto_neutro)
            hora_consulta = await extraer_hora_de_texto(fragmento, contexto_neutro)

            if not dia_consulta:
                respuestas.append("¿Para qué día querés que te pase los horarios disponibles?")
                continue

            if hora_es_valida(hora_consulta):
                dia_resuelto = resolver_fecha(dia_consulta)
                canchas_libres = [
                    court["name"] for court in COURTS
                    if calendario.slot_esta_libre_en_cancha(dia_resuelto, hora_consulta, court["name"])
                ]
                dia_txt = formatear_dia_para_cliente_con_mensaje(dia_consulta, fragmento)
                hora_txt = formatear_hora_para_mensaje(hora_consulta)
                if canchas_libres:
                    canchas_txt = " o ".join(canchas_libres)
                    respuestas.append(f"Para {dia_txt} a las {hora_txt} tengo {canchas_txt} libre.")
                    if telefono:
                        guardar_seleccion_cancha_pendiente(
                            telefono,
                            dia_resuelto,
                            hora_consulta,
                            canchas_libres,
                            fragmento_origen=fragmento,
                        )
                        update_conversation_state(
                            telefono or "unknown",
                            consulta_disponibilidad_pendiente=None,
                        )
                else:
                    respuestas.append(f"Para {dia_txt} a las {hora_txt} no tengo cancha libre.")
                    if telefono:
                        update_conversation_state(
                            telefono or "unknown",
                            seleccion_cancha_pendiente=None,
                        )
            else:
                respuestas.append(obtener_resumen_horarios_disponibles(dia_consulta, incluir_cta=False))
                if telefono:
                    guardar_consulta_disponibilidad_pendiente(
                        telefono or "unknown",
                        dia_consulta,
                        fragmento_origen=fragmento,
                    )
            continue

        # Si el auditor determinó que el efecto real es solo lectura pero el primer
        # clasificador dejó una etiqueta operativa, tratamos el fragmento como consulta
        # informativa. La etiqueta nunca tiene prioridad sobre el efecto semántico.
        efecto = str(item.get("efecto") or "").strip().lower()
        if tipo in {"pedir_precio", "consulta_informativa"} or (
            efecto == "lectura" and tipo not in {"pedir_horarios", "consultar_mi_turno"}
        ):
            respuesta_info = await responder_consulta_informativa_ia(
                fragmento,
                contexto_neutro,
                prospecto,
            )
            if respuesta_info:
                respuestas.append(respuesta_info.strip())
            continue

        if tipo == "consultar_mi_turno":
            dia = conv_state.get("dia_propuesto")
            hora = conv_state.get("hora_propuesta")
            cancha = conv_state.get("cancha_propuesta")
            if dia and hora_es_valida(hora):
                detalle = f"Tenés un turno para {dia} a las {formatear_hora_para_mensaje(hora)}"
                if cancha:
                    detalle += f" en {cancha}"
                if str(conv_state.get("senia_estado") or "").strip().lower() == "pendiente":
                    detalle += ", pendiente de seña"
                respuestas.append(detalle + ".")
            else:
                respuestas.append("No tengo un turno actual completo en memoria para mostrarte.")

    # Deduplicar respuestas idénticas sin alterar el orden.
    unicas: List[str] = []
    vistas = set()
    for respuesta in respuestas:
        limpia = str(respuesta or "").strip()
        clave = re.sub(r"\s+", " ", limpia).lower()
        if limpia and clave not in vistas:
            vistas.add(clave)
            unicas.append(limpia)

    return "\n\n".join(unicas) if unicas else None


async def detectar_multiples_intenciones(mensaje: str) -> List[Dict]:
    """
    Descompone TODO el lote pendiente en unidades semánticas independientes.
    Las preguntas informativas nunca quedan absorbidas por una intención operativa.
    """
    if not mensaje or len(mensaje.strip()) < 3:
        return [{"intencion": "necesita_contexto", "fragmento": mensaje}]

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el router semántico de un agente de reservas. Recibís uno o varios mensajes "
                        "pendientes del mismo cliente y debés extraer TODAS las acciones y preguntas independientes.\n\n"
                        "No uses coincidencias de frases exactas: razoná por significado. Conservá el orden original.\n\n"
                        "INTENCIONES:\n"
                        "- reservar_cancha: quiere pedir/agendar una cancha.\n"
                        "- reservar_quincho: quiere agregar, usar o reservar quincho/salón/parrilla como recurso.\n"
                        "- pedir_horarios: consulta disponibilidad de día/hora/turnos.\n"
                        "- pedir_precio: consulta exclusivamente precios o tarifas.\n"
                        "- consulta_informativa: pregunta por características o conocimiento del negocio: "
                        "tipo/tamaño de cancha, qué incluye un servicio, instalaciones, políticas, ubicación, "
                        "formas de pago, condiciones o cualquier dato que no requiera consultar ocupación del calendario.\n"
                        "- confirmar_reserva: acepta una propuesta concreta ya hecha por el agente.\n"
                        "- cancelar_turno: quiere cancelar un turno existente.\n"
                        "- reprogramar_turno: quiere mover/cambiar un turno existente.\n"
                        "- consultar_mi_turno: pregunta por una reserva que ya tiene.\n"
                        "- evento_dia_completo: quiere cerrar/reservar el predio por jornada o evento especial.\n"
                        "- otra: conversación no operativa.\n"
                        "- necesita_contexto: solo si realmente no se puede comprender aun mirando el lote.\n\n"
                        "REGLAS CRÍTICAS:\n"
                        "1. Si un lote contiene una selección de cancha/hora Y además una pregunta, devolvé ambas intenciones.\n"
                        "2. Una pregunta acerca de un recurso no implica reservar ese recurso. Si pregunta si un recurso "
                        "existe, está incluido, viene junto con otro servicio, cuánto cuesta, cómo funciona o qué características "
                        "tiene, es consulta_informativa/pedir_precio, NO reservar_quincho ni reservar_cancha.\n"
                        "3. reservar_quincho/reservar_cancha requieren voluntad real de agregar o crear una reserva; la sola "
                        "mención del recurso dentro de una pregunta nunca alcanza.\n"
                        "4. Si una misma pregunta pide dos datos relacionados (por ejemplo característica + precio), "
                        "podés mantenerla como una consulta_informativa única para responderla completa.\n"
                        "5. No absorbas preguntas en confirmar_reserva ni en reservar_quincho.\n"
                        "6. 'fragmento' debe conservar el texto relevante del cliente; puede abarcar más de una línea.\n\n"
                        "Respondé SOLO JSON válido: "
                        "{\"intenciones\": [{\"intencion\": \"tipo\", \"fragmento\": \"texto\"}]}"
                    ),
                },
                {"role": "user", "content": f"Lote pendiente del cliente:\n{mensaje}"},
            ],
            temperature=0.0,
            max_tokens=400,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        result = json.loads(resp.choices[0].message.content.strip())
        intenciones = result.get("intenciones", [])
        if not intenciones:
            return [{"intencion": "necesita_contexto", "fragmento": mensaje}]

        limpias = []
        permitidas = {
            "reservar_cancha", "reservar_quincho", "pedir_horarios", "pedir_precio",
            "consulta_informativa", "confirmar_reserva", "cancelar_turno",
            "reprogramar_turno", "consultar_mi_turno", "evento_dia_completo",
            "otra", "necesita_contexto",
        }
        for item in intenciones:
            if not isinstance(item, dict):
                continue
            tipo = str(item.get("intencion") or "otra").strip()
            fragmento = str(item.get("fragmento") or mensaje).strip()
            if tipo not in permitidas:
                tipo = "otra"
            limpias.append({"intencion": tipo, "fragmento": fragmento})

        print(
            f"   🧠 [Multi-intent] {len(limpias)} intención(es): "
            f"{[(i.get('intencion'), i.get('fragmento', '')[:40]) for i in limpias]}"
        )
        return limpias or [{"intencion": "necesita_contexto", "fragmento": mensaje}]
    except Exception as e:
        print(f"   ⚠️ [Multi-intent] Error: {e}")
        return [{"intencion": "necesita_contexto", "fragmento": mensaje}]

async def auditar_efectos_lote_ia(
    mensaje_lote: str,
    sub_intenciones: List[Dict],
    conv_state: Dict = None,
) -> List[Dict]:
    """
    Segunda lectura independiente del router principal.

    Separa dos conceptos que antes estaban mezclados:
      1) de qué habla el usuario (intención), y
      2) si pretende MODIFICAR algo o solamente CONSULTAR.

    Invariante: mencionar una cancha, un quincho, una reserva o una seña no implica
    por sí mismo una acción. Para marcar ``escritura`` debe existir una voluntad real
    de crear, confirmar, agregar, cancelar o modificar una operación.
    """
    if not sub_intenciones:
        return sub_intenciones

    conv_state = conv_state or {}
    candidatos = []
    for idx, item in enumerate(sub_intenciones):
        if not isinstance(item, dict):
            continue
        candidatos.append({
            "indice": idx,
            "intencion": str(item.get("intencion") or "otra"),
            "fragmento": str(item.get("fragmento") or ""),
        })

    if not candidatos:
        return sub_intenciones

    permitidas = {
        "reservar_cancha", "reservar_quincho", "pedir_horarios", "pedir_precio",
        "consulta_informativa", "confirmar_reserva", "cancelar_turno",
        "reprogramar_turno", "consultar_mi_turno", "evento_dia_completo",
        "otra", "necesita_contexto",
    }

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el AUDITOR DE EFECTOS de un agente de reservas. Ya existe una primera "
                        "clasificación, pero puede estar equivocada. Tu única prioridad es distinguir "
                        "CONSULTAR de MODIFICAR por significado, no por palabras.\n\n"
                        "Para cada fragmento devolvé: efecto=lectura o escritura, e intencion_corregida.\n"
                        "Si la intención previa ya es una lectura razonable (pedir_horarios, pedir_precio, "
                        "consulta_informativa o consultar_mi_turno), CONSERVALA salvo contradicción semántica fuerte.\n\n"
                        "LECTURA: el cliente pide información, disponibilidad, horarios, precios, qué incluye "
                        "algo, características, tipos de cancha, instalaciones, políticas, dirección, formas "
                        "de pago o información sobre su turno. Preguntar por un recurso NO significa reservarlo. "
                        "Preguntar si algo viene incluido NO significa agregarlo. Preguntar qué turnos hay NO "
                        "significa crear una reserva.\n\n"
                        "ESCRITURA: el cliente manifiesta voluntad de crear/reservar, confirmar una propuesta, "
                        "agregar un recurso a una reserva, cancelar, reprogramar o modificar una operación. "
                        "La voluntad de cambio debe estar semánticamente presente; no la infieras por mencionar "
                        "cancha, quincho, seña, turno o una hora.\n"
                        "EXCEPCIÓN CONTEXTUAL IMPORTANTE: si OFERTA_CANCHA_PENDIENTE contiene opciones concretas "
                        "que el agente acaba de ofrecer para un día/hora, y el usuario responde eligiendo una de "
                        "esas opciones (por nombre, número, ordinal o equivalente semántico), eso ES una acción "
                        "de confirmación/selección y debe ser efecto=escritura con intencion_corregida=confirmar_reserva.\n\n"
                        "Si el primer router marcó reservar_quincho/reservar_cancha pero el fragmento en realidad "
                        "es una pregunta, corregí la intención a pedir_horarios, pedir_precio o consulta_informativa "
                        "según corresponda. Conservá el mismo fragmento y el mismo índice.\n\n"
                        "Respondé SOLO JSON válido con este formato: "
                        "{\"items\":[{\"indice\":0,\"efecto\":\"lectura\","
                        "\"intencion_corregida\":\"consulta_informativa\",\"razon\":\"...\"}]}"
                    ),
                },
                {
                    "role": "user",
                    "content": (
                        f"FASE_ACTUAL: {conv_state.get('fase', 'inicial')}\n"
                        f"OFERTA_CANCHA_PENDIENTE: "
                        f"{json.dumps(conv_state.get('seleccion_cancha_pendiente'), ensure_ascii=False, default=str)}\n"
                        f"HISTORIAL_RECIENTE: "
                        f"{json.dumps((conv_state.get('historial') or [])[-6:], ensure_ascii=False, default=str)}\n"
                        f"LOTE_ORIGINAL:\n{mensaje_lote}\n\n"
                        f"CLASIFICACION_PREVIA:\n{json.dumps(candidatos, ensure_ascii=False)}"
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=500,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        auditados = data.get("items") or []
        por_indice = {}
        for audit in auditados:
            if not isinstance(audit, dict):
                continue
            try:
                idx = int(audit.get("indice"))
            except Exception:
                continue
            efecto = str(audit.get("efecto") or "").strip().lower()
            corregida = str(audit.get("intencion_corregida") or "").strip()
            if efecto not in {"lectura", "escritura"}:
                continue
            if corregida not in permitidas:
                corregida = ""
            por_indice[idx] = {
                "efecto": efecto,
                "intencion_corregida": corregida,
                "razon_efecto": str(audit.get("razon") or "").strip(),
            }

        resultado = []
        for idx, item in enumerate(sub_intenciones):
            nuevo = dict(item) if isinstance(item, dict) else {"intencion": "otra", "fragmento": str(item)}
            audit = por_indice.get(idx)
            if audit:
                anterior = str(nuevo.get("intencion") or "otra")
                corregida = audit.get("intencion_corregida") or anterior

                # El auditor decide EFECTO. No debe cambiar una intención read-only
                # razonable por otra read-only y perder semántica útil.
                if (
                    anterior in READ_ONLY_INTENTS
                    and corregida in READ_ONLY_INTENTS
                    and audit["efecto"] == "lectura"
                ):
                    corregida = anterior

                nuevo["intencion_original"] = anterior
                nuevo["intencion"] = corregida
                nuevo["efecto"] = audit["efecto"]
                nuevo["razon_efecto"] = audit.get("razon_efecto", "")
            resultado.append(nuevo)

        print(
            "   🧭 [Efecto lote] "
            + str([
                (i.get("intencion_original", i.get("intencion")), i.get("intencion"), i.get("efecto", "fallback"))
                for i in resultado
            ])
        )
        return resultado
    except Exception as e:
        print(f"   ⚠️ [Efecto lote] Auditor no disponible: {e} → uso clasificación original")
        return sub_intenciones


