def _decision_engine_reserva_actual(
    telefono: str,
    prospecto: Dict = None,
) -> Dict:
    """Obtiene la reserva real del contacto sin convertirla en controlador de la conversación."""
    try:
        return calendario.obtener_reserva_por_telefono(
            telefono or "unknown",
            (prospecto or {}).get("nombre", ""),
        ) or {}
    except Exception:
        return {}


def construir_snapshot_decision_engine(
    mensaje_lote: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    sub_intenciones: List[Dict] = None,
) -> Dict[str, Any]:
    """
    Construye una fotografía inmutable/lógica del turno actual.

    La fase es solamente UNA señal dentro del snapshot. No determina por sí sola
    qué rama debe ejecutarse.
    """
    conv_state = conv_state or {}
    prospecto = prospecto or {}

    seleccion_cancha = obtener_seleccion_cancha_pendiente(conv_state)
    consulta_disp = obtener_consulta_disponibilidad_pendiente(conv_state)

    aclaracion_hora = None
    if (
        conv_state.get("fase") == "esperando_aclaracion_hora"
        and (conv_state.get("hora_opciones") or [])
    ):
        aclaracion_hora = {
            "tipo": "aclaracion_hora",
            "opciones": list(conv_state.get("hora_opciones") or []),
            "fase_previa": conv_state.get("fase_previa_hora"),
            "contexto": conv_state.get("aclaracion_hora_contexto"),
        }

    pending_decisions = []
    if aclaracion_hora:
        pending_decisions.append(aclaracion_hora)
    if seleccion_cancha:
        pending_decisions.append({
            "tipo": "seleccion_cancha",
            "dia": seleccion_cancha.get("dia"),
            "hora": seleccion_cancha.get("hora"),
            "opciones": list(seleccion_cancha.get("canchas") or []),
        })

    fase_legacy = conv_state.get("fase", "inicial")
    tarea_legacy_pendiente = None
    if fase_legacy in DECISION_ENGINE_PENDING_LEGACY_PHASES:
        tarea_legacy_pendiente = {
            "tipo": "tarea_legacy_pendiente",
            "fase": fase_legacy,
            "expected_answer": DECISION_ENGINE_PENDING_LEGACY_PHASES[fase_legacy],
        }
        pending_decisions.append(tarea_legacy_pendiente)

    historial = []
    for msg in (conv_state.get("historial") or [])[-10:]:
        if isinstance(msg, dict):
            historial.append({
                "role": msg.get("role"),
                "content": str(msg.get("content") or "")[:350],
            })

    snapshot = {
        "engine_version": DECISION_ENGINE_VERSION,
        "mensaje_actual": str(mensaje_lote or "").strip(),
        "fase_legacy": conv_state.get("fase", "inicial"),
        "reserva_actual": _decision_engine_reserva_actual(telefono, prospecto),
        "propuesta_actual": {
            "dia": conv_state.get("dia_propuesto"),
            "hora": conv_state.get("hora_propuesta"),
            "cancha": conv_state.get("cancha_propuesta"),
            "con_quincho": bool(conv_state.get("con_quincho")),
            "quincho": conv_state.get("quincho"),
        },
        "pending_decisions": pending_decisions,
        "consulta_disponibilidad_pendiente": consulta_disp,
        "seleccion_cancha_pendiente": seleccion_cancha,
        "booking_draft": _booking_draft_activo(conv_state),
        "aclaracion_hora_pendiente": aclaracion_hora,
        "tarea_legacy_pendiente": tarea_legacy_pendiente,
        "intenciones_auditadas": sub_intenciones or [],
        "historial_reciente": historial,
        "ultimo_mensaje_asistente": _ultimo_mensaje_asistente(conv_state),
        "quincho_confirmacion_origen": conv_state.get("quincho_confirmacion_origen"),
        "cliente": {
            "nombre": prospecto.get("nombre"),
            "es_cliente": prospecto.get("es_cliente"),
        },
    }
    return snapshot



async def interpretar_respuesta_oferta_cancha_ia(
    mensaje: str,
    oferta: Dict,
    conv_state: Dict,
) -> Dict[str, Any]:
    """
    Interpreta la respuesta a una oferta de canchas SIN usar frases rígidas.

    modos:
      - seleccion: eligió una cancha concreta
      - acepta_cualquiera: autoriza elegir cualquiera de las ofrecidas
      - acepta_sin_elegir: muestra acuerdo/continuidad pero con varias opciones no resueltas
      - cambia_tema: pregunta/pide otra cosa
      - otra
    """
    opciones = list((oferta or {}).get("canchas") or [])
    historial = []
    for msg in (conv_state or {}).get("historial", [])[-6:]:
        if isinstance(msg, dict):
            historial.append({
                "role": msg.get("role"),
                "content": str(msg.get("content") or "")[:260],
            })

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un intérprete de continuidad conversacional para un complejo de canchas.\\n"
                        "El agente acaba de ofrecer una o más canchas para un día/hora.\\n"
                        "Decidí qué hace la respuesta actual.\\n\\n"
                        "REGLAS:\\n"
                        "- Si elige explícitamente una opción por nombre, número u ordinal: modo=seleccion.\\n"
                        "- Si dice que cualquiera le sirve / le da igual / elegí cualquiera: modo=acepta_cualquiera.\\n"
                        "- Si simplemente acepta, asiente o quiere continuar PERO hay varias opciones y no eligió una: "
                        "modo=acepta_sin_elegir. NO inventes una cancha.\\n"
                        "- Si hace otra pregunta o cambia de asunto: modo=cambia_tema.\\n"
                        "- Con UNA sola opción, una aceptación natural puede devolver modo=seleccion con esa opción.\\n"
                        "Respondé SOLO JSON: "
                        '{"modo":"seleccion|acepta_cualquiera|acepta_sin_elegir|cambia_tema|otra",'
                        '"cancha":"nombre exacto o null","confianza":0.0,"razon":"breve"}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "mensaje": mensaje,
                            "oferta": oferta,
                            "opciones_validas": opciones,
                            "historial_reciente": historial,
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        modo = str(data.get("modo") or "otra").strip().lower()
        cancha = normalizar_valor_nullable(data.get("cancha"))
        if cancha not in opciones:
            cancha = None
        return {
            "modo": modo,
            "cancha": cancha,
            "confianza": float(data.get("confianza", 0.0) or 0.0),
            "razon": str(data.get("razon") or ""),
        }
    except Exception as e:
        print(f"   ⚠️ [Oferta cancha IA] Error: {e}")
        return {
            "modo": "otra",
            "cancha": None,
            "confianza": 0.0,
            "razon": f"error: {e}",
        }


async def detectar_correccion_quincho_reserva_ia(
    mensaje: str,
    snapshot: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Detecta reparación de quincho con PROCEDENCIA LOCAL.

    Una queja histórica no puede reaparecer frente a un mensaje nuevo.
    """
    mensaje = str(mensaje or "").strip()
    ultimo_asistente = snapshot.get("ultimo_mensaje_asistente") or {}
    texto_asistente = str(ultimo_asistente.get("content") or "").strip()

    draft = snapshot.get("booking_draft")
    draft_q = (
        ((draft or {}).get("addons") or {}).get("quincho") or {}
        if isinstance(draft, dict)
        else {}
    )
    reserva = snapshot.get("reserva_actual") or {}
    propuesta = snapshot.get("propuesta_actual") or {}
    origen_q = str(snapshot.get("quincho_confirmacion_origen") or "")

    objetivo_reparable = bool(
        _reserva_indica_quincho(reserva)
        or bool(draft_q.get("solicitado"))
        or (
            bool(propuesta.get("con_quincho"))
            and origen_q in {"usuario", "reserva_existente"}
        )
    )

    if not objetivo_reparable:
        return {
            "accion": "ninguna",
            "confianza": 1.0,
            "razon": "No existe un quincho verificable para quitar.",
            "evidence_source": "none",
            "evidence_quote": "",
            "continuacion_anaforica": False,
        }

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un detector CONSERVADOR de reparación de reserva.\\n"
                        "Decidí si el MENSAJE ACTUAL pide quitar un quincho/parrilla agregado por error.\\n\\n"
                        "REGLAS DE PROCEDENCIA:\\n"
                        "- La evidencia preferida debe estar explícita en el MENSAJE ACTUAL.\\n"
                        "- También puede ser una continuación anafórica ('corregilo', 'eso te dije') SOLO si el "
                        "ÚLTIMO MENSAJE DEL AGENTE inmediatamente anterior estaba hablando de corregir ese quincho.\\n"
                        "- NO uses reclamos antiguos ni historial lejano.\\n"
                        "- Si el mensaje actual inicia un objetivo nuevo claro (disponibilidad, horarios, precio, "
                        "otra reserva, saludo), accion=ninguna aunque antes haya existido un problema.\\n"
                        "- evidence_quote debe ser una CITA TEXTUAL EXACTA del mensaje actual o del último mensaje "
                        "del agente. No parafrasees.\\n\\n"
                        "Respondé SOLO JSON: "
                        '{"accion":"quitar_quincho|ninguna","confianza":0.0,'
                        '"evidence_source":"mensaje_actual|ultimo_asistente|none",'
                        '"evidence_quote":"cita exacta","continuacion_anaforica":true|false,"razon":"breve"}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "mensaje_actual": mensaje,
                            "ultimo_mensaje_asistente": texto_asistente,
                            "reserva_actual": reserva,
                            "booking_draft": draft,
                            "propuesta_actual": propuesta,
                            "intenciones_actuales": snapshot.get("intenciones_auditadas") or [],
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=220,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())

        accion = str(data.get("accion") or "ninguna").strip().lower()
        confianza = float(data.get("confianza", 0.0) or 0.0)
        source = str(data.get("evidence_source") or "none").strip().lower()
        quote = str(data.get("evidence_quote") or "").strip()
        anaforica = bool(data.get("continuacion_anaforica"))

        if accion != "quitar_quincho":
            return {
                "accion": "ninguna",
                "confianza": confianza,
                "razon": str(data.get("razon") or ""),
                "evidence_source": source,
                "evidence_quote": quote,
                "continuacion_anaforica": anaforica,
            }

        quote_norm = normalizar_texto_ia(quote)
        msg_norm = normalizar_texto_ia(mensaje)
        assistant_norm = normalizar_texto_ia(texto_asistente)

        evidencia_valida = False
        if source == "mensaje_actual":
            evidencia_valida = bool(
                quote_norm and quote_norm in msg_norm and confianza >= 0.70
            )
        elif source == "ultimo_asistente":
            evidencia_valida = bool(
                anaforica
                and quote_norm
                and quote_norm in assistant_norm
                and confianza >= 0.82
            )

        intents = {
            str(i.get("intencion") or "")
            for i in (snapshot.get("intenciones_auditadas") or [])
            if isinstance(i, dict)
        }
        if (
            intents
            and intents.issubset({"pedir_horarios", "pedir_precio", "consultar_mi_turno"})
            and source != "mensaje_actual"
        ):
            evidencia_valida = False

        if not evidencia_valida:
            print(
                f"   🛡️ [REPAIR PROVENANCE] Rechazo reparación sin evidencia local "
                f"(source={source}, quote={quote!r}, confianza={confianza:.2f})"
            )
            return {
                "accion": "ninguna",
                "confianza": confianza,
                "razon": "Sin evidencia local válida para reparar.",
                "evidence_source": source,
                "evidence_quote": quote,
                "continuacion_anaforica": anaforica,
            }

        return {
            "accion": "quitar_quincho",
            "confianza": confianza,
            "razon": str(data.get("razon") or ""),
            "evidence_source": source,
            "evidence_quote": quote,
            "continuacion_anaforica": anaforica,
        }

    except Exception as e:
        print(f"   ⚠️ [Reparación quincho IA] Error: {e}")
        return {
            "accion": "ninguna",
            "confianza": 0.0,
            "razon": f"error: {e}",
            "evidence_source": "none",
            "evidence_quote": "",
            "continuacion_anaforica": False,
        }


def build_resumen_reserva_sin_quincho_corregida(
    reserva: Dict[str, Any],
    precio_cancha: int,
    senia_valor: int,
    saldo: int,
) -> str:
    reserva = reserva or {}
    dia = str(reserva.get("fecha") or "")
    hora = str(reserva.get("hora") or "")
    cancha = str(reserva.get("cancha") or "")
    duracion = normalizar_duracion_horas(
        reserva.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    senia_estado = str(reserva.get("senia_estado") or "").strip().lower()

    lineas = [
        "Listo, ya lo corregí. La reserva queda solo con la cancha, sin quincho.",
        "",
        f"📅 {dia}" if dia else "",
        f"{_court_booking_summary_label(cancha)} de {rango_horario_texto(hora, duracion)}",
        f"💲 {_fmt_precio(precio_cancha)}",
        "",
        f"💰 Total: {_fmt_precio(precio_cancha)}",
    ]
    if senia_estado == "pagada":
        lineas.append("✅ La seña ya está registrada.")
        lineas.append(f"💸 Saldo pendiente: {_fmt_precio(saldo)}")
    else:
        lineas.extend([
            f"💵 Seña: {_fmt_precio(senia_valor)}",
            f"💸 Saldo pendiente: {_fmt_precio(saldo)}",
            "",
            f"Para dejarlo firme, mandame el comprobante al alias {PAYMENT_ALIAS}.",
        ])
    return "\n".join(linea for linea in lineas if linea is not None)


def corregir_reserva_quitar_quincho(
    telefono: str,
    prospecto: Dict,
    snapshot: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Reparación idempotente: conserva cancha/día/hora y elimina SOLO quincho.

    Nunca re-reserva, nunca reprograma y nunca trata la propia reserva como ocupación.
    """
    telefono_key = telefono or "unknown"
    reserva = dict(snapshot.get("reserva_actual") or {})

    if not reserva:
        try:
            reserva = calendario.obtener_reserva_por_telefono(
                telefono_key,
                (prospecto or {}).get("nombre", ""),
            ) or {}
            if not reserva and (prospecto or {}).get("nombre"):
                reserva = calendario.obtener_reserva_por_nombre(
                    (prospecto or {}).get("nombre", "")
                ) or {}
        except Exception:
            reserva = {}

    # Si todavía es un borrador y no llegó al calendario, corregir memoria es suficiente.
    if not reserva:
        _limpiar_quincho_del_draft(telefono_key)
        state = get_conversation_state(telefono_key)
        draft = _booking_draft_activo(state)
        if draft:
            return {
                "ok": True,
                "respuesta": "Listo, lo dejé corregido: la reserva en curso es solo de cancha, sin quincho.",
                "tipo": "draft",
            }
        return {
            "ok": False,
            "respuesta": "No encontré una reserva activa para corregir. Decime cuál turno querés revisar.",
            "tipo": "sin_reserva",
        }

    dia = reserva.get("fecha") or reserva.get("dia") or ""
    hora = normalizar_hora_detectada(reserva.get("hora"))
    cancha = reserva.get("cancha") or ""
    duracion = normalizar_duracion_horas(
        reserva.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    precio_cancha = calcular_precio_total(duracion)
    senia_estado_actual = str(reserva.get("senia_estado") or "").strip().lower()

    # V59 — al quitar un addon antes de pagar, cambia el importe REQUERIDO de
    # la seña. No conservar la seña vieja calculada sobre cancha+quincho.
    # Si ya fue pagada, preservamos lo efectivamente registrado.
    if senia_estado_actual == "pagada":
        senia_valor = _senia_guardada_o_configurada(reserva, precio_cancha)
    else:
        senia_valor = _senia_para_total(precio_cancha)

    saldo = calcular_monto_pendiente(precio_cancha, senia_valor)

    if dia and hora_es_valida(hora) and cancha:
        actualizar_metadata_reserva_bloque(
            dia,
            slots_para_bloque(hora, duracion),
            cancha,
            str(reserva.get("telefono") or telefono_key),
            duracion,
            precio_cancha,
            senia_valor,
            saldo,
            extra_fields={
                "con_quincho": "No",
                "quincho": "",
                "quincho_hora_inicio": "",
                "quincho_hora_fin": "",
                "quincho_duracion_horas": "",
                "quincho_precio_hora": "",
                "quincho_precio_total": "",
            },
        )

    _limpiar_quincho_del_draft(telefono_key)
    update_conversation_state(
        telefono_key,
        con_quincho=False,
        quincho="",
        quincho_hora_inicio="",
        quincho_hora_fin="",
        quincho_duracion_horas=None,
        quincho_confirmacion_origen=None,
        ultima_reparacion={
            "tipo": "quitar_quincho",
            "dia": dia,
            "hora": hora,
            "cancha": cancha,
            "timestamp": datetime.datetime.now(TIMEZONE).isoformat(),
        },
    )

    # Releer el MISMO slot. Buscar sólo por teléfono devolvería la reserva más
    # próxima y mezclaría resúmenes cuando el contacto tiene varios turnos.
    try:
        exact_matches = [
            row
            for row in _agent_v2_reservas_reales(telefono_key, prospecto)
            if _agent_v2_same_slot(row, dia, hora, cancha)
        ]
        reserva_verificada = exact_matches[0] if len(exact_matches) == 1 else reserva
    except Exception:
        reserva_verificada = reserva
    reserva_verificada = dict(reserva_verificada or reserva)
    reserva_verificada["con_quincho"] = "No"
    reserva_verificada["quincho"] = ""
    reserva_verificada["quincho_hora_inicio"] = ""
    reserva_verificada["quincho_hora_fin"] = ""
    reserva_verificada["quincho_duracion_horas"] = ""
    reserva_verificada["quincho_precio_hora"] = ""
    reserva_verificada["quincho_precio_total"] = ""
    reserva_verificada["precio_cancha_total"] = str(precio_cancha)
    reserva_verificada["precio_total"] = str(precio_cancha)
    reserva_verificada["senia_monto"] = str(senia_valor)
    reserva_verificada["senia_valor"] = str(senia_valor)
    reserva_verificada["monto_pendiente"] = str(saldo)

    return {
        "ok": True,
        "respuesta": build_resumen_reserva_sin_quincho_corregida(
            reserva_verificada,
            precio_cancha,
            senia_valor,
            saldo,
        ),
        "reserva": reserva_verificada,
        "tipo": "reserva",
    }



def reconciliar_estado_con_fuente_de_verdad(
    telefono: str,
    conv_state: Dict,
    prospecto: Dict,
) -> Dict:
    """
    Rehidrata el estado conversacional operativo desde CALENDARIO.

    CALENDAR OWNS TRUTH.

    Corrige dos clases de inconsistencia:

    A)
        conversation_state:
            fase = senia_pendiente

        calendario:
            estado = reservado
            senia_estado = parcial_efectivo_pendiente

        => conversación debe quedar:
            fase = coordinacion_confirmada

    B)
        conversation_state conserva día/hora/cancha viejos
        pero calendario ya fue reprogramado.

        => calendario gana.

    No interpreta lenguaje.
    No decide intención.
    No usa regex de intención.

    Si existen varias reservas distintas y no puede saberse cuál
    debe proyectarse sobre el legacy state único, no inventa una.
    """
    telefono_key = (
        telefono
        or "unknown"
    )

    conv_state = (
        conv_state
        or {}
    )

    # ==========================================================
    # HANDOFF ACTIVO
    # ==========================================================
    #
    # No pisar una intervención humana activa solamente
    # porque existe una reserva en calendario.
    # ==========================================================

    if conv_state.get(
        "fase"
    ) in {
        "derivado_humano",
        "derivado_evento_dia_completo",
        "derivado_quincho",
    }:
        return conv_state

    # ==========================================================
    # SOURCE OF TRUTH
    # ==========================================================

    reservas = (
        _agent_v2_reservas_reales(
            telefono_key,
            prospecto
            or {},
        )
    )

    # ==========================================================
    # NO HAY RESERVA REAL
    # ==========================================================

    if not reservas:

        if (
            conv_state.get(
                "fase"
            )
            == "senia_pendiente"
        ):
            print(
                "   🧽 [STATE RECONCILE] "
                "fase=senia_pendiente sin reserva real → "
                "limpio estado fantasma"
            )

            return (
                _purge_transient_booking_context_after_missing_reservation(
                    telefono_key,
                    reason=(
                        "state_reconcile_missing_calendar_reservation"
                    ),
                )
            )

        return conv_state

    # ==========================================================
    # AGRUPAR RESERVAS LÓGICAS
    # ==========================================================
    #
    # Un booking de 2 horas puede ocupar varias filas físicas.
    # reservation_id representa la entidad lógica.
    # ==========================================================

    logical: Dict[
        str,
        Dict[str, Any],
    ] = {}

    for raw_row in reservas:

        if not isinstance(
            raw_row,
            dict,
        ):
            continue

        row = (
            _agent_v2_enrich_reservation(
                raw_row
            )
        )

        reservation_id = (
            _agent_v2_reservation_id(
                row
            )
        )

        if reservation_id:

            key = (
                f"id:{reservation_id}"
            )

        else:

            key = "|".join([
                str(
                    row.get(
                        "fecha"
                    )
                    or row.get(
                        "dia"
                    )
                    or ""
                ),
                str(
                    row.get(
                        "hora"
                    )
                    or ""
                ),
                str(
                    row.get(
                        "cancha"
                    )
                    or ""
                ),
            ])

        logical.setdefault(
            key,
            row,
        )

    if not logical:
        return conv_state

    # ==========================================================
    # ELEGIR RESERVA PARA PROYECTAR AL LEGACY STATE
    # ==========================================================

    target = None

    if len(logical) == 1:

        target = next(
            iter(
                logical.values()
            )
        )

    else:

        # Hay varias reservas.
        # Solamente usar el slot que el estado legacy YA
        # identifica inequívocamente.
        state_day = (
            conv_state.get(
                "dia_propuesto"
            )
        )

        state_hour = (
            normalizar_hora_detectada(
                conv_state.get(
                    "hora_propuesta"
                )
            )
        )

        state_court = str(
            conv_state.get(
                "cancha_propuesta"
            )
            or ""
        ).strip().casefold()

        matches = []

        for row in logical.values():

            row_day = (
                row.get(
                    "fecha"
                )
                or row.get(
                    "dia"
                )
                or ""
            )

            row_hour = (
                normalizar_hora_detectada(
                    row.get(
                        "hora"
                    )
                )
            )

            row_court = str(
                row.get(
                    "cancha"
                )
                or ""
            ).strip().casefold()

            same_day = bool(
                not state_day
                or _misma_fecha_reserva(
                    {
                        "fecha": (
                            row_day
                        )
                    },
                    str(
                        state_day
                    ),
                )
            )

            same_hour = bool(
                not hora_es_valida(
                    state_hour
                )
                or row_hour
                == state_hour
            )

            same_court = bool(
                not state_court
                or row_court
                == state_court
            )

            if (
                same_day
                and same_hour
                and same_court
            ):
                matches.append(
                    row
                )

        if len(matches) == 1:

            target = matches[
                0
            ]

    # No aplastar varias reservas distintas dentro
    # de un único legacy conversation_state.
    if not target:
        return conv_state

    target = (
        _agent_v2_enrich_reservation(
            target
        )
    )

    # ==========================================================
    # ESTADO OPERATIVO REAL
    # ==========================================================

    firme = (
        _agent_v2_reprogrammed_booking_is_firm(
            target
        )
    )

    try:

        pendiente = bool(
            reserva_tiene_senia_pendiente(
                target
            )
        )

    except Exception:

        pendiente = False

    if firme:

        canonical_phase = (
            "coordinacion_confirmada"
        )

    elif pendiente:

        canonical_phase = (
            "senia_pendiente"
        )

    else:

        canonical_phase = (
            conv_state.get(
                "fase"
            )
            or "inicial"
        )

    # ==========================================================
    # PROYECCIÓN DEL CALENDARIO
    # ==========================================================

    patch: Dict[
        str,
        Any,
    ] = {
        "fase": (
            canonical_phase
        ),
        "dia_propuesto": (
            target.get(
                "fecha"
            )
            or target.get(
                "dia"
            )
        ),
        "hora_propuesta": (
            target.get(
                "hora"
            )
        ),
        "cancha_propuesta": (
            target.get(
                "cancha"
            )
        ),
        "senia_estado": (
            target.get(
                "senia_estado"
            )
            or ""
        ),
    }

    # ==========================================================
    # SETTLEMENT FINANCIERO
    # ==========================================================

    for key in (
        "senia_monto",
        "senia_pagada_monto",
        "senia_pendiente_monto",
        "senia_efectivo_pendiente",
        "payment_method",
        "monto_pendiente",
        "precio_total",
    ):

        if (
            key in target
            and target.get(
                key
            )
            is not None
        ):
            patch[
                key
            ] = target.get(
                key
            )

    # ==========================================================
    # NO WRITE SI YA ESTÁ SINCRONIZADO
    # ==========================================================

    changed = any(
        conv_state.get(
            key
        )
        != value

        for (
            key,
            value,
        ) in patch.items()
    )

    if not changed:

        return conv_state

    print(
        "   🔄 [STATE RECONCILE CALENDAR AUTHORITY] "
        f"reservation_id={_agent_v2_reservation_id(target)} "
        f"fase={conv_state.get('fase')}→{canonical_phase} "
        f"slot={patch.get('dia_propuesto')} "
        f"{patch.get('hora_propuesta')} "
        f"{patch.get('cancha_propuesta')} "
        f"senia_estado={patch.get('senia_estado')}"
    )

    update_conversation_state(
        telefono_key,
        **patch,
    )

    return (
        get_conversation_state(
            telefono_key
        )
    )

def _agent_v2_plan_idempotent_existing_booking(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    progress: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """
    Fast-path idempotente para un create_booking cuyo desired state
    YA coincide exactamente con una reserva real del cliente.

    CASO:

        calendario:
            ID 31
            hoy 20:00
            Cancha 1
            duración 2h

        usuario:
            quiere hoy 20:00

        SemanticFrame:
            create_booking

    Resultado:

        NO consultar disponibilidad como si fuera un turno nuevo.
        NO crear otro hold.
        NO reprogramar.
        NO pedir comprobante.

        Ejecutar crear_reserva contra el MISMO slot.
        La propia tool devolverá:

            status = already_exists

    Este helper NO interpreta lenguaje.
    NO convierte create_booking en reschedule_booking.
    Sólo compara desired state congelado vs calendario.
    """
    world = (
        world
        or {}
    )

    perception = (
        perception
        or {}
    )

    goals = (
        goals
        or {}
    )

    observations = (
        observations
        or []
    )

    # ==========================================================
    # SEMÁNTICA AUTORIZADA
    # ==========================================================

    acts = [
        act

        for act in (
            _agent_v2_authoritative_semantic_acts(
                perception
            )
        )

        if (
            isinstance(
                act,
                dict,
            )
            and str(
                act.get(
                    "operation"
                )
                or ""
            )
            not in {
                "greet",
                "close_conversation",
            }
        )
    ]

    # No tragarse un mensaje con múltiples
    # subintenciones independientes.
    if len(acts) != 1:
        return None

    act = acts[
        0
    ]

    if (
        str(
            act.get(
                "operation"
            )
            or ""
        )
        != "create_booking"
    ):
        return None

    if not bool(
        (
            act.get(
                "commitment"
            )
            or {}
        ).get(
            "wants_write"
        )
    ):
        return None

    goal_names = {
        str(
            goal.get(
                "goal"
            )
            or ""
        )

        for goal in (
            goals.get(
                "goals"
            )
            or []
        )

        if isinstance(
            goal,
            dict,
        )
    }

    if (
        "crear_reserva"
        not in goal_names
    ):
        return None

    # ==========================================================
    # RESERVAS REALES
    # ==========================================================

    reservations = [
        row

        for row in (
            (
                world.get(
                    "facts"
                )
                or {}
            ).get(
                "reservas_reales"
            )
            or []
        )

        if isinstance(
            row,
            dict,
        )
    ]

    if not reservations:
        return None

    entities = (
        perception.get(
            "entities"
        )
        or {}
    )

    temporal = (
        act.get(
            "temporal"
        )
        if isinstance(
            act.get(
                "temporal"
            ),
            dict,
        )
        else {}
    )

    target = (
        act.get(
            "target"
        )
        if isinstance(
            act.get(
                "target"
            ),
            dict,
        )
        else {}
    )

    quantity = (
        act.get(
            "quantity"
        )
        if isinstance(
            act.get(
                "quantity"
            ),
            dict,
        )
        else {}
    )

    requested_day = (
        entities.get(
            "dia_resuelto"
        )
        or entities.get(
            "dia"
        )
        or temporal.get(
            "day"
        )
    )

    requested_hour = (
        normalizar_hora_detectada(
            entities.get(
                "hora"
            )
            or temporal.get(
                "start"
            )
        )
    )

    requested_court = str(
        entities.get(
            "cancha"
        )
        or target.get(
            "label"
        )
        or ""
    ).strip().casefold()

    if (
        not requested_day
        or not hora_es_valida(
            requested_hour
        )
    ):
        return None

    # ==========================================================
    # DURACIÓN SOLICITADA
    # ==========================================================

    requested_duration = (
        entities.get(
            "duracion_horas"
        )
        or quantity.get(
            "duration_hours"
        )
        or temporal.get(
            "duration_hours"
        )
    )

    requested_duration_number = None

    if (
        requested_duration
        is not None
    ):
        try:
            requested_duration_number = float(
                requested_duration
            )

        except (
            TypeError,
            ValueError,
        ):
            return None

    # ==========================================================
    # BUSCAR MISMO DESIRED STATE
    # ==========================================================

    matches: Dict[
        str,
        Dict[str, Any],
    ] = {}

    for raw_row in reservations:

        row = (
            _agent_v2_enrich_reservation(
                raw_row
            )
        )

        row_day = (
            row.get(
                "fecha"
            )
            or row.get(
                "dia"
            )
            or ""
        )

        row_hour = (
            normalizar_hora_detectada(
                row.get(
                    "hora"
                )
            )
        )

        row_court = str(
            row.get(
                "cancha"
            )
            or ""
        ).strip().casefold()

        if not _misma_fecha_reserva(
            {
                "fecha": (
                    row_day
                )
            },
            str(
                requested_day
            ),
        ):
            continue

        if (
            row_hour
            != requested_hour
        ):
            continue

        if (
            requested_court
            and row_court
            != requested_court
        ):
            continue

        row_duration = (
            normalizar_duracion_horas(
                row.get(
                    "duracion_horas"
                )
                or DEFAULT_TURN_DURATION_HOURS
            )
        )

        # Si el usuario está pidiendo explícitamente
        # otra duración, ya no es el mismo desired state.
        if (
            requested_duration_number
            is not None
            and abs(
                float(
                    row_duration
                )
                - requested_duration_number
            )
            > 1e-9
        ):
            continue

        reservation_id = (
            _agent_v2_reservation_id(
                row
            )
        )

        logical_key = (
            reservation_id
            or "|".join([
                str(
                    row_day
                ),
                str(
                    row_hour
                ),
                str(
                    row_court
                ),
            ])
        )

        matches.setdefault(
            logical_key,
            row,
        )

    if len(matches) != 1:
        return None

    existing = next(
        iter(
            matches.values()
        )
    )

    # ==========================================================
    # IDEMPOTENT CREATE
    # ==========================================================

    exact_args = {
        "dia": (
            existing.get(
                "fecha"
            )
            or existing.get(
                "dia"
            )
            or requested_day
        ),
        "hora": (
            requested_hour
        ),
        "cancha": (
            existing.get(
                "cancha"
            )
        ),
        "duracion_horas": (
            existing.get(
                "duracion_horas"
            )
            or DEFAULT_TURN_DURATION_HOURS
        ),
        "requested_hours": [
            requested_hour
        ],
        "booking_shape": (
            "single"
        ),
    }

    if (
        _agent_v2_step_already_satisfied(
            "crear_reserva",
            exact_args,
            observations,
        )
    ):
        return {
            "steps": [],
            "done_if": (
                "el turno solicitado "
                "ya existe a nombre del cliente"
            ),
            "reason": (
                "idempotent existing booking already observed"
            ),
            "goal_progress": (
                progress
            ),
        }

    print(
        "   ♻️ [AgentV2 IDEMPOTENT BOOKING] "
        f"requested={exact_args['dia']} "
        f"{exact_args['hora']} "
        f"{exact_args['cancha']} "
        f"→ reservation_id="
        f"{_agent_v2_reservation_id(existing)} "
        "ya existe"
    )

    return {
        "steps": [{
            "tool": (
                "crear_reserva"
            ),
            "args": (
                exact_args
            ),
            "reason": (
                "desired state coincide exactamente "
                "con una reserva real del mismo cliente; "
                "ejecutar create idempotente"
            ),
            "replan_after": (
                False
            ),
        }],
        "done_if": (
            "crear_reserva devuelve already_exists"
        ),
        "reason": (
            "idempotent existing booking authority"
        ),
        "goal_progress": (
            progress
        ),
    }


async def generar_candidatos_decision_engine(
    mensaje_lote: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
) -> Tuple[Dict[str, Any], List[Dict], List[Dict]]:
    """
    Evalúa señales en paralelo lógico: crea TODOS los candidatos que son compatibles
    con mensaje + estado. Ningún candidato gana por estar escrito antes en el código.
    """
    mensaje_lote = str(mensaje_lote or "").strip()
    conv_state = conv_state or {}

    conv_state = sanear_contextos_transitorios_decision_engine(
        telefono or "unknown",
        conv_state,
    )
    conv_state = reconciliar_estado_con_fuente_de_verdad(
        telefono or "unknown",
        conv_state,
        prospecto or {},
    )

    sub_intenciones = (
        await detectar_multiples_intenciones(mensaje_lote)
        if mensaje_lote
        else []
    )
    if sub_intenciones:
        sub_intenciones = await auditar_efectos_lote_ia(
            mensaje_lote,
            sub_intenciones,
            conv_state,
        )

    snapshot = construir_snapshot_decision_engine(
        mensaje_lote,
        conv_state,
        prospecto,
        telefono,
        sub_intenciones=sub_intenciones,
    )

    candidatos: List[Dict[str, Any]] = []

    def add_candidate(
        candidate_id: str,
        action: str,
        compatibility: float,
        evidence: str,
        payload: Dict = None,
    ):
        candidatos.append({
            "id": candidate_id,
            "action": action,
            "compatibility": max(0.0, min(float(compatibility), 1.0)),
            "evidence": str(evidence or ""),
            "payload": payload or {},
            "valid": True,
        })

    # Candidato: resolver una aclaración de hora ya abierta.
    aclaracion = snapshot.get("aclaracion_hora_pendiente")
    if aclaracion:
        hora_resuelta = resolver_respuesta_aclaracion_hora(
            mensaje_lote,
            aclaracion.get("opciones") or [],
        )
        if hora_es_valida(hora_resuelta):
            add_candidate(
                "pending_hour_answer",
                "resolver_aclaracion_hora",
                0.99,
                "El mensaje resuelve semánticamente una aclaración horaria pendiente.",
                {
                    "hora": hora_resuelta,
                    "aclaracion": aclaracion,
                },
            )

    # Candidato: selección de una cancha previamente ofrecida.
    seleccion_ctx = snapshot.get("seleccion_cancha_pendiente")
    respuesta_oferta = None
    if seleccion_ctx and mensaje_lote:
        respuesta_oferta = await interpretar_respuesta_oferta_cancha_ia(
            mensaje_lote,
            seleccion_ctx,
            conv_state,
        )
        snapshot["respuesta_seleccion_cancha"] = respuesta_oferta
        opciones_oferta = list(seleccion_ctx.get("canchas") or [])
        cancha_elegida = respuesta_oferta.get("cancha")

        if (
            respuesta_oferta.get("modo") == "seleccion"
            and cancha_elegida in opciones_oferta
        ):
            add_candidate(
                "pending_court_answer",
                "seleccionar_cancha_ofrecida",
                0.995,
                "El usuario eligió semánticamente una cancha de la oferta pendiente.",
                {
                    "cancha": cancha_elegida,
                    "oferta": seleccion_ctx,
                    "modo": "seleccion",
                },
            )
        elif respuesta_oferta.get("modo") == "acepta_cualquiera" and opciones_oferta:
            # Si al cliente realmente le da igual, elegir la primera opción todavía libre
            # es una decisión válida y reproducible. No se usa para un simple "dale".
            add_candidate(
                "pending_court_any",
                "seleccionar_cancha_ofrecida",
                0.985,
                "El cliente autorizó explícitamente elegir cualquiera de las canchas ofrecidas.",
                {
                    "cancha": opciones_oferta[0],
                    "oferta": seleccion_ctx,
                    "modo": "acepta_cualquiera",
                },
            )
        elif respuesta_oferta.get("modo") == "acepta_sin_elegir":
            if len(opciones_oferta) == 1:
                add_candidate(
                    "pending_court_single_accept",
                    "seleccionar_cancha_ofrecida",
                    0.99,
                    "Solo había una cancha ofrecida y el cliente la aceptó.",
                    {
                        "cancha": opciones_oferta[0],
                        "oferta": seleccion_ctx,
                        "modo": "acepta_unica",
                    },
                )
            elif len(opciones_oferta) > 1:
                add_candidate(
                    "pending_court_needs_choice",
                    "solicitar_eleccion_cancha",
                    0.995,
                    "El cliente quiere continuar pero todavía no eligió entre varias canchas.",
                    {
                        "oferta": seleccion_ctx,
                    },
                )
        elif respuesta_oferta.get("modo") == "otra" and len(opciones_oferta) > 1:
            add_candidate(
                "pending_court_ambiguous",
                "solicitar_eleccion_cancha",
                0.94,
                "Hay varias canchas pendientes y el mensaje no resolvió cuál; pedir una elección es más seguro que inventarla.",
                {
                    "oferta": seleccion_ctx,
                },
            )

    # Reparación explícita de un error de quincho.
    correccion_quincho = await detectar_correccion_quincho_reserva_ia(
        mensaje_lote,
        snapshot,
    )
    snapshot["correccion_quincho"] = correccion_quincho
    if (
        correccion_quincho.get("accion") == "quitar_quincho"
        and correccion_quincho.get("evidence_source") in {"mensaje_actual", "ultimo_asistente"}
        and float(correccion_quincho.get("confianza", 0.0) or 0.0) >= 0.70
    ):
        add_candidate(
            "repair_remove_quincho",
            "corregir_reserva_sin_quincho",
            0.999,
            "El usuario está corrigiendo un error: conservar la cancha y quitar solo el quincho.",
            {
                "razon": correccion_quincho.get("razon"),
            },
        )

    # Candidatos ligados a una consulta de disponibilidad abierta.
    consulta_disp = snapshot.get("consulta_disponibilidad_pendiente")
    if consulta_disp and mensaje_lote:
        hora_corta = resolver_hora_corta_por_franja(mensaje_lote)
        if hora_corta.get("requiere_aclaracion"):
            add_candidate(
                "availability_hour_ambiguous",
                "pedir_aclaracion_hora",
                0.97,
                "El mensaje aporta una hora ambigua dentro de la consulta de disponibilidad activa.",
                {
                    "opciones": hora_corta.get("opciones") or [],
                    "consulta_disponibilidad": consulta_disp,
                },
            )
        elif (
            hora_corta.get("detectada")
            and hora_es_valida(hora_corta.get("hora"))
        ):
            add_candidate(
                "availability_hour_resolved",
                "aplicar_hora_a_disponibilidad",
                0.96,
                "El mensaje aporta una hora válida para el día que se está consultando.",
                {
                    "hora": hora_corta.get("hora"),
                    "consulta_disponibilidad": consulta_disp,
                },
            )

    # Candidato de continuidad de una tarea legacy explícita.
    # Importante: se agrega como OPCIÓN, no como prioridad. Si el usuario cambia de
    # tema y hace una pregunta nueva, el planner puede elegir read_only en su lugar.
    tarea_legacy = snapshot.get("tarea_legacy_pendiente")
    if tarea_legacy and mensaje_lote:
        add_candidate(
            "pending_legacy_task",
            "despachar_tarea_pendiente_legacy",
            0.84,
            (
                "Existe una tarea/pregunta explícita pendiente en la conversación; "
                "el planner debe decidir si el mensaje actual realmente la responde."
            ),
            {
                "fase": tarea_legacy.get("fase"),
                "expected_answer": tarea_legacy.get("expected_answer"),
                "sub_intenciones": sub_intenciones,
            },
        )

    # Candidato de lectura pura: se crea por EFECTO auditado, no por fase.
    if sub_intenciones and lote_es_solo_lectura(sub_intenciones):
        add_candidate(
            "read_only_batch",
            "responder_lote_lectura",
            0.91,
            "Todas las sub-intenciones auditadas tienen efecto de lectura.",
            {
                "sub_intenciones": sub_intenciones,
            },
        )

    # Candidato write/mixed: el engine decide el objetivo, el executor legacy mantiene
    # las herramientas transaccionales que ya están probadas.
    if sub_intenciones and not lote_es_solo_lectura(sub_intenciones):
        add_candidate(
            "write_or_mixed_batch",
            "despachar_escritura_o_mixto",
            0.88,
            "Existe al menos una intención de escritura o el lote es mixto.",
            {
                "sub_intenciones": sub_intenciones,
            },
        )

    # Siempre existe una salida conservadora.
    add_candidate(
        "legacy_fallback",
        "fallback_legacy",
        0.20,
        "Fallback conservador si ninguna interpretación contextual explica bien el mensaje.",
        {
            "sub_intenciones": sub_intenciones,
        },
    )

    return snapshot, candidatos, sub_intenciones


async def planificar_decision_engine_ia(
    snapshot: Dict[str, Any],
    candidatos: List[Dict],
) -> Dict[str, Any]:
    """
    El LLM compara todos los candidatos contra el snapshot completo.

    Importante: NO recibe una cadena de if/elif. Recibe un conjunto de acciones
    simultáneamente posibles y debe elegir la que mejor explica el mensaje actual.
    """
    candidatos_publicos = [
        {
            "id": c.get("id"),
            "action": c.get("action"),
            "compatibility": c.get("compatibility"),
            "evidence": c.get("evidence"),
            "payload": c.get("payload"),
        }
        for c in candidatos
        if c.get("valid")
    ]

    fallback = max(
        candidatos_publicos,
        key=lambda c: float(c.get("compatibility", 0.0) or 0.0),
        default={"id": "legacy_fallback", "action": "fallback_legacy"},
    )

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el PLANNER CENTRAL de un agente de reservas de canchas.\n"
                        "Recibís un SNAPSHOT completo del contacto y una LISTA DE CANDIDATOS válidos.\n"
                        "Elegí la acción que MEJOR EXPLICA el mensaje en este contexto.\n\n"
                        "REGLA ARQUITECTÓNICA: no existe prioridad por orden de código. Evaluá todos "
                        "los candidatos simultáneamente por coherencia semántica con el mensaje, historial, "
                        "pero NO resucites intenciones históricas que no tengan un candidato vigente en el snapshot. "
                        "reserva real, propuesta actual y decisiones pendientes.\n\n"
                        "Una fase legacy es evidencia, NO una orden. Una reserva existente no debe secuestrar "
                        "una consulta nueva. Si hay VARIAS canchas ofrecidas y el cliente solo asiente/acepta sin "
                        "elegir una, NO confirmes ni inventes cancha: elegí solicitar_eleccion_cancha. "
                        "Si denuncia que el sistema agregó quincho por error, elegí corregir_reserva_sin_quincho: "
                        "eso es una reparación real, no una consulta informativa. "
                        "Una decisión/tarea pendiente tampoco debe secuestrar una pregunta nueva "
                        "si el mensaje claramente cambia de tema. Pero si el mensaje responde de forma natural "
                        "a una pregunta/opción/tarea pendiente (por ejemplo nombre solicitado, motivo solicitado, "
                        "duración solicitada o decisión de reagendar), elegí el candidato de continuidad correspondiente.\n\n"
                        "No inventes candidate_id ni acciones. Elegí SOLO uno de los candidatos entregados.\n"
                        "Respondé SOLO JSON: "
                        "{\"candidate_id\":\"id\",\"confidence\":0.0,"
                        "\"goal\":\"objetivo breve\",\"reason\":\"por qué este candidato explica mejor el mensaje\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "snapshot": snapshot,
                            "candidatos": candidatos_publicos,
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=260,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        candidate_id = str(data.get("candidate_id") or "").strip()
        ids_validos = {str(c.get("id")) for c in candidatos_publicos}
        if candidate_id not in ids_validos:
            candidate_id = fallback.get("id")

        return {
            "candidate_id": candidate_id,
            "confidence": float(data.get("confidence", 0.0) or 0.0),
            "goal": str(data.get("goal") or ""),
            "reason": str(data.get("reason") or ""),
            "source": "planner_ia",
        }
    except Exception as e:
        print(f"   ⚠️ [DecisionEngine Planner] Error: {e} → fallback por compatibilidad")
        return {
            "candidate_id": fallback.get("id"),
            "confidence": float(fallback.get("compatibility", 0.0) or 0.0),
            "goal": "fallback_semantico",
            "reason": f"Planner IA no disponible: {e}",
            "source": "compatibility_fallback",
        }


async def auditar_plan_decision_engine_ia(
    snapshot: Dict[str, Any],
    candidatos: List[Dict],
    plan: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Segunda lectura independiente: revisa que la elección del planner sea coherente
    con el estado completo. Puede elegir otro candidato, nunca inventar uno.
    """
    candidatos_publicos = [
        {
            "id": c.get("id"),
            "action": c.get("action"),
            "compatibility": c.get("compatibility"),
            "evidence": c.get("evidence"),
            "payload": c.get("payload"),
        }
        for c in candidatos
        if c.get("valid")
    ]
    ids_validos = {str(c.get("id")) for c in candidatos_publicos}

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el AUDITOR del planner de un agente de reservas.\n"
                        "Revisá la elección usando mensaje + estado completo + candidatos.\n"
                        "No existe prioridad por orden de código.\n"
                        "Corregí únicamente si otro candidato explica claramente mejor el mensaje.\n"
                        "No permitas que una reserva o fase previa secuestre una consulta independiente ni que una "
                        "pregunta informativa se convierta en escritura. Si hay varias canchas pendientes y el usuario "
                        "solo acepta sin elegir, no permitas confirmar reserva: debe pedirse la cancha. Si el usuario "
                        "pide quitar un quincho agregado por error, no lo conviertas en charla: debe ejecutarse la "
                        "reparación y corregirse calendario/precio/resumen. A la inversa, una respuesta que contesta "
                        "claramente una pregunta/tarea pendiente o elige una opción que el agente acaba de ofrecer "
                        "no debe degradarse a información.\n"
                        "Respondé SOLO JSON: "
                        "{\"keep\":true|false,\"candidate_id\":\"id\",\"confidence\":0.0,\"reason\":\"breve\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "snapshot": snapshot,
                            "candidatos": candidatos_publicos,
                            "plan_elegido": plan,
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=220,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        proposed = str(data.get("candidate_id") or plan.get("candidate_id") or "").strip()
        if proposed not in ids_validos:
            proposed = str(plan.get("candidate_id") or "")
        return {
            "candidate_id": proposed,
            "confidence": float(data.get("confidence", plan.get("confidence", 0.0)) or 0.0),
            "reason": str(data.get("reason") or ""),
            "corrected": not bool(data.get("keep", True)),
        }
    except Exception as e:
        print(f"   ⚠️ [DecisionEngine Auditor] Error: {e} → conservo planner")
        return {
            "candidate_id": plan.get("candidate_id"),
            "confidence": plan.get("confidence", 0.0),
            "reason": f"Auditor no disponible: {e}",
            "corrected": False,
        }


def validar_candidato_decision_engine(
    candidate: Dict[str, Any],
    snapshot: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Python valida PRECONDICIONES. El LLM interpreta; Python protege la verdad.

    Esta función no decide por prioridad: solo comprueba si la acción elegida puede
    ejecutarse con la evidencia que figura en el snapshot/candidate payload.
    """
    if not candidate or not candidate.get("valid"):
        return {"ok": False, "reason": "candidato_inexistente_o_invalido"}

    action = candidate.get("action")
    payload = candidate.get("payload") or {}

    if action == "resolver_aclaracion_hora":
        hora = payload.get("hora")
        if not snapshot.get("aclaracion_hora_pendiente") or not hora_es_valida(hora):
            return {"ok": False, "reason": "sin_aclaracion_hora_resoluble"}

    elif action == "pedir_aclaracion_hora":
        opciones = payload.get("opciones") or []
        if not snapshot.get("consulta_disponibilidad_pendiente") or len(opciones) < 2:
            return {"ok": False, "reason": "sin_ambiguedad_horaria_valida"}

    elif action == "aplicar_hora_a_disponibilidad":
        if (
            not snapshot.get("consulta_disponibilidad_pendiente")
            or not hora_es_valida(payload.get("hora"))
        ):
            return {"ok": False, "reason": "sin_contexto_disponibilidad_o_hora"}

    elif action == "seleccionar_cancha_ofrecida":
        oferta = snapshot.get("seleccion_cancha_pendiente") or {}
        cancha = str(payload.get("cancha") or "")
        if not cancha or cancha not in (oferta.get("canchas") or []):
            return {"ok": False, "reason": "cancha_no_pertenece_a_oferta_pendiente"}

    elif action == "solicitar_eleccion_cancha":
        oferta = snapshot.get("seleccion_cancha_pendiente") or {}
        if len(oferta.get("canchas") or []) < 2:
            return {"ok": False, "reason": "no_hay_eleccion_multiple_pendiente"}

    elif action == "corregir_reserva_sin_quincho":
        correccion = snapshot.get("correccion_quincho") or {}
        if correccion.get("accion") != "quitar_quincho":
            return {"ok": False, "reason": "sin_reparacion_quincho_solicitada"}

    elif action == "responder_lote_lectura":
        if (snapshot.get("correccion_quincho") or {}).get("accion") == "quitar_quincho":
            return {"ok": False, "reason": "una_reparacion_no_es_read_only"}
        subs = payload.get("sub_intenciones") or []
        if not lote_es_solo_lectura(subs):
            return {"ok": False, "reason": "lote_no_es_solo_lectura"}

    elif action == "despachar_escritura_o_mixto":
        if (snapshot.get("correccion_quincho") or {}).get("accion") == "quitar_quincho":
            return {"ok": False, "reason": "reparacion_especifica_debe_usar_executor_de_reparacion"}
        subs = payload.get("sub_intenciones") or []
        oferta = snapshot.get("seleccion_cancha_pendiente") or {}
        respuesta_oferta = snapshot.get("respuesta_seleccion_cancha") or {}
        confirmar_sin_cancha = any(
            str(item.get("intencion") or "") in {"confirmar_reserva", "reservar_cancha"}
            for item in subs
            if isinstance(item, dict)
        )
        if (
            confirmar_sin_cancha
            and len(oferta.get("canchas") or []) > 1
            and respuesta_oferta.get("modo") not in {"seleccion", "acepta_cualquiera"}
        ):
            return {"ok": False, "reason": "confirmacion_bloqueada_hasta_elegir_cancha"}
        if not subs or lote_es_solo_lectura(subs):
            return {"ok": False, "reason": "sin_escritura_real"}

    elif action == "despachar_tarea_pendiente_legacy":
        tarea = snapshot.get("tarea_legacy_pendiente") or {}
        if not tarea or payload.get("fase") != tarea.get("fase"):
            return {"ok": False, "reason": "tarea_pendiente_no_coincide"}

    elif action == "fallback_legacy":
        if (snapshot.get("correccion_quincho") or {}).get("accion") == "quitar_quincho":
            return {"ok": False, "reason": "reparacion_no_puede_caer_a_legacy"}
        oferta = snapshot.get("seleccion_cancha_pendiente") or {}
        respuesta_oferta = snapshot.get("respuesta_seleccion_cancha") or {}
        if (
            len(oferta.get("canchas") or []) > 1
            and respuesta_oferta.get("modo") not in {"seleccion", "acepta_cualquiera", "cambia_tema"}
        ):
            return {"ok": False, "reason": "falta_eleccion_cancha"}

    else:
        return {"ok": False, "reason": "accion_no_registrada"}

    return {"ok": True, "reason": "precondiciones_ok"}


async def ejecutar_candidato_decision_engine(
    candidate: Dict[str, Any],
    snapshot: Dict[str, Any],
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    mensaje_lote: str,
    sub_intenciones_default: List[Dict],
) -> Dict[str, Any]:
    """
    Ejecuta la acción YA ELEGIDA.

    Acá un switch no representa prioridad: el planner ya tomó la decisión. Este bloque
    es solamente un dispatcher de herramientas.
    """
    action = candidate.get("action")
    payload = candidate.get("payload") or {}
    telefono_key = telefono or "unknown"

    result = {
        "handled": False,
        "response": None,
        "sub_intenciones": sub_intenciones_default or [],
        "texto_normalizado": None,
        "action": action,
    }

    if action == "resolver_aclaracion_hora":
        hora = payload.get("hora")
        aclaracion = payload.get("aclaracion") or {}
        fase_anterior = aclaracion.get("fase_previa") or conv_state.get("fase_previa_hora") or "inicial"
        if fase_anterior == "esperando_aclaracion_hora":
            fase_anterior = "inicial"

        contexto_aclaracion = aclaracion.get("contexto")
        if not isinstance(contexto_aclaracion, dict):
            contexto_aclaracion = conv_state.get("aclaracion_hora_contexto")
        if not isinstance(contexto_aclaracion, dict):
            contexto_aclaracion = {}

        if contexto_aclaracion.get("tipo") == "consulta_disponibilidad":
            contexto_disp = contexto_aclaracion.get("consulta_disponibilidad")
            if not isinstance(contexto_disp, dict):
                contexto_disp = obtener_consulta_disponibilidad_pendiente(conv_state) or {}

            update_conversation_state(
                telefono_key,
                fase=fase_anterior,
                hora_opciones=[],
                fase_previa_hora=None,
                aclaracion_hora_contexto=None,
            )
            respuesta = responder_hora_en_consulta_disponibilidad(
                telefono_key,
                contexto_disp,
                hora,
            )
            if respuesta:
                result["handled"] = True
                result["response"] = respuesta
                return result

        # Aclaración de un flujo transaccional: resolvemos el valor y devolvemos el
        # control al executor legacy con contexto ya normalizado.
        update_conversation_state(
            telefono_key,
            fase=fase_anterior,
            hora_propuesta=hora,
            hora_opciones=[],
            fase_previa_hora=None,
            aclaracion_hora_contexto=None,
        )
        result["texto_normalizado"] = f"a las {hora}"
        result["sub_intenciones"] = [{
            "intencion": "confirmar_reserva",
            "fragmento": f"a las {hora}",
            "efecto": "escritura",
            "razon_efecto": "hora elegida al resolver una aclaración explícita del agente",
            "decision_engine": True,
        }]
        return result

    if action == "pedir_aclaracion_hora":
        opciones = payload.get("opciones") or []
        contexto_disp = payload.get("consulta_disponibilidad") or {}
        respuesta = build_hora_ambigua_message(opciones)
        update_conversation_state(
            telefono_key,
            fase="esperando_aclaracion_hora",
            hora_opciones=opciones,
            fase_previa_hora=conv_state.get("fase", "inicial"),
            aclaracion_hora_contexto={
                "tipo": "consulta_disponibilidad",
                "consulta_disponibilidad": contexto_disp,
                "creado_en": datetime.datetime.now(TIMEZONE).isoformat(),
            },
        )
        result["handled"] = True
        result["response"] = respuesta
        return result

    if action == "aplicar_hora_a_disponibilidad":
        respuesta = responder_hora_en_consulta_disponibilidad(
            telefono_key,
            payload.get("consulta_disponibilidad") or {},
            payload.get("hora"),
        )
        if respuesta:
            result["handled"] = True
            result["response"] = respuesta
        return result

    if action == "seleccionar_cancha_ofrecida":
        oferta = payload.get("oferta") or {}
        cancha = payload.get("cancha")
        actualizar_booking_draft(
            telefono_key,
            cancha=cancha,
            estado="cancha_elegida",
        )
        # Nueva propuesta limpia: NO hereda quincho ni extras de una gestión anterior.
        update_conversation_state(
            telefono_key,
            fase="coordinacion_propuesta",
            dia_propuesto=oferta.get("dia"),
            hora_propuesta=oferta.get("hora"),
            cancha_propuesta=cancha,
            canchas_libres=oferta.get("canchas") or [],
            con_quincho=False,
            quincho="",
            quincho_hora_inicio="",
            quincho_hora_fin="",
            quincho_duracion_horas=None,
            quincho_confirmacion_origen=None,
        )
        result["sub_intenciones"] = [{
            "intencion": "confirmar_reserva",
            "intencion_original": "seleccion_contextual",
            "fragmento": mensaje_lote,
            "efecto": "escritura",
            "razon_efecto": "selecciona una cancha perteneciente a la oferta pendiente",
            "seleccion_contextual": True,
            "decision_engine": True,
        }]
        return result

    if action == "solicitar_eleccion_cancha":
        oferta = payload.get("oferta") or snapshot.get("seleccion_cancha_pendiente") or {}
        opciones = list(oferta.get("canchas") or [])
        if len(opciones) > 1:
            oferta_reanclada = dict(oferta)
            oferta_reanclada["activo"] = True
            oferta_reanclada["creado_en"] = datetime.datetime.now(TIMEZONE).isoformat()
            update_conversation_state(
                telefono_key,
                seleccion_cancha_pendiente=oferta_reanclada,
            )
            result["handled"] = True
            result["response"] = (
                f"Sí, ese horario está disponible en {' o '.join(opciones)}. "
                "¿Cuál preferís?"
            )
        return result

    if action == "corregir_reserva_sin_quincho":
        reparacion = corregir_reserva_quitar_quincho(
            telefono_key,
            prospecto,
            snapshot,
        )
        result["handled"] = True
        result["response"] = reparacion.get("respuesta")
        result["repair"] = reparacion
        return result

    if action == "responder_lote_lectura":
        respuesta = await resolver_lote_solo_lectura(
            payload.get("sub_intenciones") or [],
            conv_state,
            prospecto,
            telefono_key,
        )
        if respuesta:
            result["handled"] = True
            result["response"] = respuesta
        return result

    if action == "despachar_escritura_o_mixto":
        result["sub_intenciones"] = payload.get("sub_intenciones") or sub_intenciones_default or []
        return result

    if action == "despachar_tarea_pendiente_legacy":
        # La fase/herramienta específica ya existe y está probada más abajo.
        # El Decision Engine decide que ESTE mensaje pertenece a esa tarea; el legacy
        # actúa solamente como executor, no como router.
        result["sub_intenciones"] = payload.get("sub_intenciones") or sub_intenciones_default or []
        return result

    # fallback_legacy
    return result


async def ejecutar_decision_engine_turno(
    mensaje_lote: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
) -> Dict[str, Any]:
    """
    Front controller del turno conversacional.

    Flujo:
      snapshot -> candidatos -> planner IA -> auditor IA -> validación Python -> executor

    El código legacy queda detrás como executor/fallback, pero ya no decide estas rutas
    según la posición física de bloques if.
    """
    if not DECISION_ENGINE_ENABLED:
        return {
            "handled": False,
            "response": None,
            "sub_intenciones": [],
            "texto_normalizado": None,
            "action": "decision_engine_disabled",
            "snapshot": {},
            "plan": {},
        }

    snapshot, candidatos, sub_intenciones = await generar_candidatos_decision_engine(
        mensaje_lote,
        conv_state,
        prospecto,
        telefono,
    )

    print(
        "   🧩 [DecisionEngine] candidatos="
        + str([
            (c.get("id"), c.get("action"), round(float(c.get("compatibility", 0.0)), 2))
            for c in candidatos
        ])
    )

    # Si existe un único candidato sustantivo además del fallback, no hay nada
    # que "razonar" entre alternativas: usarlo directamente reduce latencia y evita
    # que el LLM resucite contexto histórico inexistente.
    candidatos_sustantivos = [
        c for c in candidatos
        if c.get("action") != "fallback_legacy"
        and float(c.get("compatibility", 0.0) or 0.0) >= 0.80
        and validar_candidato_decision_engine(c, snapshot).get("ok")
    ]

    if len(candidatos_sustantivos) == 1:
        unico = candidatos_sustantivos[0]
        plan = {
            "candidate_id": unico.get("id"),
            "confidence": float(unico.get("compatibility", 0.0) or 0.0),
            "goal": "single_candidate_dominance",
            "reason": "Solo existe un candidato sustantivo válido en el snapshot saneado.",
            "source": "deterministic_single_candidate",
        }
        auditoria = {
            "candidate_id": unico.get("id"),
            "confidence": plan["confidence"],
            "reason": "No requiere auditoría: no hay conflicto entre candidatos.",
            "corrected": False,
        }
        print(
            f"   ✅ [DecisionEngine DETERMINISTIC] único candidato válido: "
            f"{unico.get('id')} / {unico.get('action')}"
        )
    else:
        plan = await planificar_decision_engine_ia(snapshot, candidatos)
        auditoria = await auditar_plan_decision_engine_ia(snapshot, candidatos, plan)

    candidate_id = auditoria.get("candidate_id") or plan.get("candidate_id")
    candidate_map = {str(c.get("id")): c for c in candidatos}
    candidate = candidate_map.get(str(candidate_id))

    validacion = validar_candidato_decision_engine(candidate, snapshot)
    if not validacion.get("ok"):
        # No elegimos por orden. Tomamos el candidato VÁLIDO con mayor compatibilidad.
        validos = [
            c for c in candidatos
            if validar_candidato_decision_engine(c, snapshot).get("ok")
        ]
        candidate = max(
            validos,
            key=lambda c: float(c.get("compatibility", 0.0) or 0.0),
            default=candidate_map.get("legacy_fallback"),
        )
        candidate_id = candidate.get("id") if candidate else "legacy_fallback"
        validacion = validar_candidato_decision_engine(candidate, snapshot)
        print(
            f"   🛡️ [DecisionEngine] candidato IA inválido → "
            f"fallback semántico={candidate_id}"
        )

    decision_record = {
        "version": DECISION_ENGINE_VERSION,
        "candidate_id": candidate_id,
        "action": (candidate or {}).get("action"),
        "planner_confidence": plan.get("confidence"),
        "planner_reason": plan.get("reason"),
        "auditor_confidence": auditoria.get("confidence"),
        "auditor_reason": auditoria.get("reason"),
        "auditor_corrected": auditoria.get("corrected"),
        "validation": validacion,
        "snapshot_summary": {
            "fase_legacy": snapshot.get("fase_legacy"),
            "pending_decisions": snapshot.get("pending_decisions"),
            "has_reserva_actual": bool(snapshot.get("reserva_actual")),
            "has_consulta_disponibilidad": bool(snapshot.get("consulta_disponibilidad_pendiente")),
        },
    }
    update_conversation_state(
        telefono or "unknown",
        decision_engine_actual=decision_record,
    )
    registrar_metrica_operativa(
        "decision_engine",
        {
            "telefono": telefono or "unknown",
            "candidate_id": candidate_id,
            "action": (candidate or {}).get("action"),
            "planner_confidence": plan.get("confidence"),
            "auditor_corrected": auditoria.get("corrected"),
        },
    )

    print(
        f"   🎯 [DecisionEngine] action={(candidate or {}).get('action')} "
        f"candidate={candidate_id} "
        f"planner={plan.get('confidence')} "
        f"audit_corrected={auditoria.get('corrected')}"
    )

    executed = await ejecutar_candidato_decision_engine(
        candidate or candidate_map.get("legacy_fallback") or {},
        snapshot,
        conv_state,
        prospecto,
        telefono,
        mensaje_lote,
        sub_intenciones,
    )
    executed["snapshot"] = snapshot
    executed["plan"] = decision_record
    return executed


