def _agent_v2_last_created_reservation_target(
    world: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """Vincula una corrección inmediata con el último write verificado."""
    facts = (world or {}).get("facts") or {}
    reservations = list(facts.get("reservas_reales") or [])
    last_created = facts.get("last_reservation_created") or {}
    if not reservations or not isinstance(last_created, dict):
        return None

    reservation_id = str(last_created.get("reservation_id") or "").strip()
    if reservation_id:
        target = _agent_v2_find_reservation_by_id(reservations, reservation_id)
        if target:
            return target

    entities = {
        "dia": last_created.get("dia") or last_created.get("fecha"),
        "hora": last_created.get("hora"),
        "cancha": last_created.get("cancha"),
    }
    matches = [
        row
        for row in reservations
        if _agent_v2_reservation_matches_current_entities(row, entities)
    ]
    return _agent_v2_enrich_reservation(matches[0]) if matches else None


def _agent_v2_turn_is_immediate_correction(perception: Dict[str, Any]) -> bool:
    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame)
    return bool(
        (perception or {}).get("references_prior_user_input")
        or relation.get("references_previous_user_turn")
        or relation.get("references_agent_offer")
        or str(frame.get("turn_type") or "") in {"complaint", "denial"}
    )


def _agent_v2_pending_payment_is_fresh(data: Dict[str, Any]) -> bool:
    if not isinstance(data, dict):
        return False
    created = _parse_context_timestamp(data.get("created_at"))
    if not created:
        return False
    return (datetime.datetime.now(TIMEZONE) - created).total_seconds() <= AGENT_V2_PENDING_PAYMENT_TTL_MINUTES * 60


def _agent_v2_pending_deposit_reservations(rows: Any) -> List[Dict[str, Any]]:
    """Devuelve solo reservas reales que todavía pueden recibir una seña."""
    return [
        dict(row)
        for row in (rows or [])
        if isinstance(row, dict)
        and reserva_tiene_senia_pendiente(row)
    ]


def _agent_v2_payment_contract(comprobante: Dict[str, Any]) -> Dict[str, Any]:
    """Contrato de pago: acepta importes parciales si la evidencia es segura."""
    confidence = float((comprobante or {}).get("confianza", 0.0) or 0.0)
    fingerprints = _receipt_fingerprints(comprobante or {})
    reasons = []
    if not (comprobante or {}).get("es_comprobante"):
        reasons.append("no_es_comprobante")
    detected_amount = _monto_a_int((comprobante or {}).get("monto_detectado"))
    if detected_amount is None or detected_amount <= 0:
        reasons.append("monto_no_detectado")
    if confidence < AGENT_V2_PAYMENT_MIN_CONFIDENCE:
        reasons.append("confianza_insuficiente")
    if not fingerprints:
        reasons.append("sin_huella")
    return {
        "ok": not reasons,
        "confidence": confidence,
        "minimum_confidence": AGENT_V2_PAYMENT_MIN_CONFIDENCE,
        "fingerprints": fingerprints,
        "detected_amount": detected_amount,
        "reasons": reasons,
    }


def _agent_v2_build_multiple_separate_request(entities: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Construye un batch para horas separadas o canchas simultáneas."""
    entities = dict(entities or {})
    hours = _agent_v2_dedupe_hours(entities.get("horas") or [])
    single_hour = normalizar_hora_detectada(entities.get("hora"))
    if hora_es_valida(single_hour) and single_hour not in hours:
        hours.insert(0, single_hour)
    try:
        court_count = int(float(entities.get("court_count") or 0))
    except (TypeError, ValueError):
        court_count = 0
    multiple_hours = len(hours) >= 2
    parallel_courts = court_count >= 2 and len(hours) == 1
    if not multiple_hours and not parallel_courts:
        return None
    duration_raw = entities.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    duration_check = _agent_v2_validate_requested_duration(duration_raw)
    base = {
        "booking_shape": "multiple_separate",
        "requested_hours": hours,
        "court_count": court_count or (len(hours) if multiple_hours else 0),
        "parallel_courts": parallel_courts,
        "duration_valid": bool(duration_check.get("valid")),
    }
    if not duration_check.get("valid"):
        return {
            **base,
            "requested_duration_horas": duration_check.get("requested"),
            "allowed_durations": list(duration_check.get("allowed") or []),
            "reservas": [],
        }
    duration = duration_check.get("duration_horas")
    return {
        **base,
        "duration_horas": duration,
        "reservas": [
            {"hora": hour, "duracion_horas": duration}
            for hour in ([hours[0]] * court_count if parallel_courts else hours)
        ],
    }


def _agent_v2_purge_ghost_reservation_state(
    telefono: str,
    prospecto: Dict,
) -> bool:
    """
    El calendario es la fuente de verdad.

    Si no existe ninguna reserva real, eliminamos únicamente referencias que
    presuponen que YA existía una reserva (reservation_id / pago / target).
    Un draft pre-reserva sin reservation_id se conserva.
    """
    reservas = _agent_v2_reservas_reales(telefono, prospecto or {})
    if reservas:
        return False

    state = get_conversation_state(telefono)
    av2 = _agent_v2_state(state)
    draft = (
        state.get("booking_draft")
        or (av2.get("desires") or {}).get("booking_draft")
        or {}
    )
    target = (av2.get("desires") or {}).get("reservation_target") or {}
    bound_questions = [
        q for q in (av2.get("open_questions") or [])
        if (
            str(q.get("field") or "") in {"reserva", "reserva_especifica", "comprobante"}
            or q.get("reservation_id")
        )
    ]

    draft_reservation_id = str(
        draft.get("reservation_id")
        or draft.get("reserva_id")
        or ""
    ).strip()
    stale_payment_phase = str(state.get("fase") or "") == "senia_pendiente"

    if not (
        draft_reservation_id
        or target
        or bound_questions
        or stale_payment_phase
    ):
        return False

    agent_v2_reduce(
        telefono,
        {
            "type": "PURGE_GHOST_RESERVATION_STATE",
            "payload": {
                "clear_draft": bool(draft_reservation_id or stale_payment_phase),
                "clear_legacy_slot": bool(draft_reservation_id or stale_payment_phase),
                "reason": "calendar has zero real reservations",
            },
        },
    )
    return True


def _agent_v2_stored_memory(world: Dict[str, Any]) -> Dict[str, Any]:
    """Devuelve memoria persistida; nunca implica permiso de ejecución."""
    stored = (world or {}).get("stored_memory")
    if isinstance(stored, dict):
        return stored
    # Compatibilidad exclusiva para fixtures anteriores a ContextAuthorization.
    return {
        "desires": dict((world or {}).get("desires") or {}),
        "active_goals": list((world or {}).get("active_goals") or []),
        "write_authorizations": dict((world or {}).get("write_authorizations") or {}),
        "pending_decisions": list((world or {}).get("pending_decisions") or []),
        "availability_context": (world or {}).get("availability_context"),
        "history": list((world or {}).get("history") or []),
        "inferences": dict((world or {}).get("inferences") or {}),
        "legacy_signal": dict((world or {}).get("legacy_signal") or {}),
        "recent_released_booking": ((world or {}).get("facts") or {}).get(
            "recent_released_booking"
        ),
        "scopes": dict((world or {}).get("scopes") or {}),
    }


def _agent_v2_context_inventory(world: Dict[str, Any]) -> Dict[str, Any]:
    """Inventario sin valores: permite detectar elipsis sin activar memoria."""
    stored = _agent_v2_stored_memory(world)
    pending = [q for q in stored.get("pending_decisions") or [] if isinstance(q, dict)]
    return {
        "pending": [
            {
                "field": q.get("field"),
                "option_count": len(q.get("options") or []),
                "has_offer_contract": bool(
                    isinstance(q.get("offer_contract"), dict)
                    and (q.get("offer_contract") or {}).get("requested_resources")
                ),
            }
            for q in pending
        ],
        "has_booking_draft": bool((stored.get("desires") or {}).get("booking_draft")),
        "has_availability_context": bool(stored.get("availability_context")),
        "has_recent_released_booking": bool(stored.get("recent_released_booking")),
        "previous_user_turn_count": sum(
            1 for item in stored.get("history") or []
            if isinstance(item, dict) and item.get("role") == "user"
        ),
        "real_reservation_count": len(((world or {}).get("facts") or {}).get("reservas_reales") or []),
    }


def _agent_v2_history_with_reference_ids(world: Dict[str, Any]) -> List[Dict[str, Any]]:
    stored = _agent_v2_stored_memory(world)
    rows = []
    for index, item in enumerate(stored.get("history") or []):
        if not isinstance(item, dict) or item.get("role") != "user":
            continue
        row = dict(item)
        row["reference_id"] = str(
            row.get("reference_id")
            or f"user_turn:{row.get('timestamp') or index}:{index}"
        )
        rows.append(row)
    return rows


def _agent_v2_context_candidates(world: Dict[str, Any]) -> Dict[str, Any]:
    """Candidatos mínimos para la segunda etapa de resolución contextual."""
    stored = _agent_v2_stored_memory(world)
    pending_raw = [
        dict(q)
        for q in stored.get("pending_decisions") or []
        if isinstance(q, dict)
    ]

    # Compatibilidad retroactiva v65: released_booking_rebook podía existir sin
    # scope_id. Derivarlo no autoriza memoria; sólo completa la identidad que
    # ContextResolver deberá vincular semánticamente.
    for question in pending_raw:
        if (
            str(question.get("field") or question.get("type") or "").strip()
            == "released_booking_rebook"
            and not str(question.get("scope_id") or "").strip()
        ):
            question["scope_id"] = (
                _agent_v2_released_booking_rebook_scope_id(question)
            )

    snapshot_world = {**dict(world or {}), "pending_decisions": pending_raw}
    pending = _agent_v2_pending_semantic_snapshot(snapshot_world)
    raw_by_id = {str(q.get("question_id") or ""): q for q in pending_raw}
    pending = [
        {
            **item,
            "scope_id": (
                raw_by_id.get(
                    str(item.get("question_id") or ""),
                    {},
                ).get("scope_id")
                or _agent_v2_released_booking_rebook_scope_id(
                    raw_by_id.get(
                        str(item.get("question_id") or ""),
                        {},
                    )
                )
            ),
            "dia": raw_by_id.get(str(item.get("question_id") or ""), {}).get("dia"),
            "hora": raw_by_id.get(str(item.get("question_id") or ""), {}).get("hora"),
            "cancha": raw_by_id.get(str(item.get("question_id") or ""), {}).get("cancha"),
            "duracion_horas": raw_by_id.get(str(item.get("question_id") or ""), {}).get("duracion_horas"),
            "event_id": raw_by_id.get(str(item.get("question_id") or ""), {}).get("event_id"),
            "event_name": raw_by_id.get(str(item.get("question_id") or ""), {}).get("event_name"),
            "event_date": raw_by_id.get(str(item.get("question_id") or ""), {}).get("event_date"),
            "resource_types": list(
                raw_by_id.get(str(item.get("question_id") or ""), {}).get("resource_types")
                or []
            ),
            "resource_type": raw_by_id.get(str(item.get("question_id") or ""), {}).get("resource_type"),
            "requested_resources": list(
                raw_by_id.get(str(item.get("question_id") or ""), {}).get("requested_resources")
                or item.get("requested_resources")
                or []
            ),
            "offer_contract": (
                dict(
                    raw_by_id.get(str(item.get("question_id") or ""), {}).get("offer_contract")
                    or item.get("offer_contract")
                    or {}
                )
                if isinstance(
                    raw_by_id.get(str(item.get("question_id") or ""), {}).get("offer_contract")
                    or item.get("offer_contract"),
                    dict,
                )
                else {}
            ),
        }
        for item in pending
    ]
    draft = dict((stored.get("desires") or {}).get("booking_draft") or {})
    availability = dict(stored.get("availability_context") or {})
    reservations = []
    for row in ((world or {}).get("facts") or {}).get("reservas_reales") or []:
        if not isinstance(row, dict):
            continue
        clean = dict(row)
        clean["reference_id"] = str(
            _agent_v2_reservation_id(clean) or clean.get("reservation_id") or ""
        )
        reservations.append(clean)
    return {
        "pending_questions": pending,
        "scoped_booking_memory": [
            item for item in (
                {"source": "booking_draft", **draft} if draft else None,
                {"source": "availability_context", **availability} if availability else None,
            ) if item
        ],
        "archived_scopes": [
            {
                **dict(scope),
                "reference_id": f"scope:{scope_id}",
            }
            for scope_id, scope in list((stored.get("scopes") or {}).items())[-8:]
            if isinstance(scope, dict)
        ],
        "previous_user_turns": _agent_v2_history_with_reference_ids(world)[-8:],
        "real_reservations": reservations,
        "recent_released_booking": stored.get("recent_released_booking"),
    }


def _agent_v2_contextual_provenance(perception: Dict[str, Any]) -> List[Dict[str, Any]]:
    rows = []
    for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or []):
        if not isinstance(act, dict):
            continue
        for item in act.get("provenance") or []:
            if isinstance(item, dict) and (
                item.get("source") in {"pending_option", "previous_user_turn"}
                or (
                    item.get("source") == "world_fact"
                    and item.get("reference_id")
                )
            ):
                rows.append(dict(item))
        for change in act.get("changes") or []:
            if isinstance(change, dict) and (
                change.get("source") in {"pending_option", "previous_user_turn"}
                or (
                    change.get("source") == "world_fact"
                    and change.get("reference_id")
                )
            ):
                rows.append(dict(change))
    return rows


def _agent_v2_context_authorization(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Valida IDs, owner, scope, fuente y campo de cada lectura histórica."""
    frame = _agent_v2_semantic_frame(perception or {})
    relation = dict(_agent_v2_semantic_context_relation(frame) or {})
    relation_type = str(relation.get("type") or "no_pending")
    base = {
        "relation": relation_type,
        "authorized": False,
        "question_id": None,
        "reference_id": None,
        "scope_id": None,
        "allowed_fields": [],
        "allowed_sources": [],
        "bindings": [],
        "reason": "current_turn_does_not_authorize_memory",
    }
    if relation_type not in {"answers_pending", "references_previous"}:
        return base

    stored = _agent_v2_stored_memory(world)
    expected_owner = str(((world or {}).get("facts") or {}).get("memory_owner") or "")
    provenance = _agent_v2_contextual_provenance(perception)
    bindings = []

    if relation_type == "answers_pending":
        question_id = str(relation.get("question_id") or "").strip()
        if not question_id:
            return {**base, "reason": "answers_pending_without_question_id"}
        question = next((
            q for q in stored.get("pending_decisions") or []
            if isinstance(q, dict) and str(q.get("question_id") or "") == question_id
        ), None)
        if not question:
            return {**base, "reason": "pending_question_id_not_found"}
        owner = str(question.get("_memory_owner") or "")
        if expected_owner and owner and owner != expected_owner:
            return {**base, "reason": "pending_question_owner_mismatch"}
        expires_at = _parse_context_timestamp(question.get("expires_at"))
        if expires_at and datetime.datetime.now(TIMEZONE) > expires_at:
            return {**base, "reason": "pending_question_expired"}
        scope_id = (
            str(question.get("scope_id") or "").strip()
            or _agent_v2_released_booking_rebook_scope_id(question)
        )
        operations = {
            str(act.get("operation") or "")
            for act in frame.get("acts") or [] if isinstance(act, dict)
        }
        field = str(question.get("field") or "")
        compatible_operations = {
            "hora": {"create_booking", "query_availability", "reschedule_booking"},
            "hora_aclaracion": {"create_booking", "query_availability", "reschedule_booking"},
            "dia": {"create_booking", "query_availability", "reschedule_booking"},
            "dia_hora_reserva": {"create_booking", "query_availability"},
            # Slots propios del BookingObjective. El Dialogue Context Resolver
            # puede vincularlos correctamente, pero sin esta compatibilidad la
            # segunda frontera de autorización rechazaba el plan antes del
            # preflight (incidente real: respuesta "fútbol 5").
            "resource_type": {"create_booking", "query_availability"},
            "duracion_horas": {"create_booking", "query_availability", "reschedule_booking"},
            "cancha": {"create_booking"},
            "waitlist_offer": {"join_waitlist"},
            "confirmar_slot": {"create_booking"},
            "released_booking_rebook": {"create_booking"},
            "confirmar_reprogramacion": {"reschedule_booking"},
            "reserva_especifica": {
                "cancel_booking", "reschedule_booking", "modify_resource",
                "remove_resource", "register_payment", "choose_payment_method",
                "query_reservation",
            },
            "comprobante": {"register_payment"},
            # Event Registration: respuestas stateful tipadas. No decide intención;
            # sólo impide que otra operación consuma accidentalmente estos pendings.
            "team_name": {"register_event"},
            "event_selection": {"register_event", "query_event"},
            "inscripcion_evento": {"register_event_payment"},
            "payment_destination": {"register_payment", "register_event_payment"},
        }
        allowed_operations = compatible_operations.get(field)
        if allowed_operations is not None and not operations.intersection(allowed_operations):
            return {**base, "reason": "pending_operation_type_mismatch"}
        question_snapshot = _agent_v2_pending_semantic_snapshot({
            "pending_decisions": [question],
        })
        snapshot_options = list(
            ((question_snapshot[0] if question_snapshot else {}).get("options") or [])
        )
        valid_option_ids = {
            str(option.get("option_id") or "")
            for option in snapshot_options if isinstance(option, dict)
        }
        option_values = [
            (
                option.get("value")
                or option.get("label")
                or option.get("hora")
                or option.get("cancha")
            )
            if isinstance(option, dict)
            else option
            for option in question.get("options") or []
        ]
        for item in provenance:
            if item.get("source") != "pending_option":
                continue
            if str(item.get("question_id") or "") != question_id:
                print(
                    "   🚫 [CONTEXT AUTH DETAIL] pending provenance qid mismatch "
                    f"field={item.get('field')!r} expected={question_id!r} "
                    f"got={str(item.get('question_id') or '')!r} "
                    f"source={item.get('source')!r} scope={item.get('scope_id')!r}"
                )
                return {**base, "reason": "pending_provenance_question_mismatch"}

            item_scope_id = str(
                item.get("scope_id")
                or ""
            ).strip()

            # Migración fail-closed para un frame v65/v66 ya enlazado al MISMO
            # released_booking_rebook. No acepta scopes diferentes ni aplica a
            # ningún otro pending: sólo completa el scope derivado del propio
            # question persistido cuando el qid ya coincide exactamente.
            if (
                not item_scope_id
                and field == "released_booking_rebook"
                and scope_id
            ):
                item_scope_id = scope_id
                item["scope_id"] = scope_id

            if (
                not scope_id
                or item_scope_id != scope_id
            ):
                return {
                    **base,
                    "reason": "pending_provenance_scope_mismatch",
                }
            option_id = str(item.get("option_id") or "")
            if option_id and valid_option_ids and option_id not in valid_option_ids:
                return {**base, "reason": "pending_option_id_not_found"}
            if option_values and not option_id:
                entities = dict((perception or {}).get("entities") or {})
                selected_value = None
                if field in {"hora", "hora_aclaracion"}:
                    selected_value = entities.get("hora") or next((
                        (act.get("temporal") or {}).get("start")
                        for act in frame.get("acts") or [] if isinstance(act, dict)
                        and (act.get("temporal") or {}).get("start")
                    ), None)
                    selected_value = normalizar_hora_detectada(selected_value)
                    normalized_options = {normalizar_hora_detectada(value) for value in option_values}
                elif field == "cancha":
                    selected_value = entities.get("cancha") or next((
                        (act.get("target") or {}).get("label")
                        for act in frame.get("acts") or [] if isinstance(act, dict)
                        and (act.get("target") or {}).get("label")
                    ), None)
                    normalized_options = {str(value or "").strip().casefold() for value in option_values}
                    selected_value = str(selected_value or "").strip().casefold()
                else:
                    normalized_options = {str(value or "").strip().casefold() for value in option_values}
                    selected_value = str(selected_value or "").strip().casefold()
                if not selected_value or selected_value not in normalized_options:
                    return {**base, "reason": "pending_option_value_not_found"}
            bindings.append(item)
        if not bindings:
            return {**base, "reason": "pending_binding_not_proven"}
        base.update(
            authorized=True,
            question_id=question_id,
            scope_id=scope_id,
            reason="verified_pending_binding",
        )
    else:
        history_ids = {
            str(row.get("reference_id") or "")
            for row in _agent_v2_history_with_reference_ids(world)
        }
        reservation_ids = {
            str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "")
            for row in ((world or {}).get("facts") or {}).get("reservas_reales") or []
            if isinstance(row, dict)
        }
        released = stored.get("recent_released_booking") or {}
        released_id = str(
            released.get("reference_id")
            or ((released.get("booking") or {}).get("reservation_id") if isinstance(released, dict) else "")
            or ""
        )
        valid_ids = history_ids | reservation_ids | ({released_id} if released_id else set())
        # Event Registration también publica entidades durables con identidad
        # propia. Una continuación de pago puede leer esa fila como world_fact
        # sin convertirla en una reserva de cancha.
        event_fact = ((world or {}).get("facts") or {}).get("event_registration") or {}
        event_registration_ids = {
            str(row.get("registration_id") or "").strip()
            for row in (event_fact.get("registrations_for_contact") or [])
            if isinstance(row, dict) and str(row.get("registration_id") or "").strip()
        }
        active_event_registration = event_fact.get("active_registration") or {}
        if isinstance(active_event_registration, dict):
            active_event_registration_id = str(
                active_event_registration.get("registration_id") or ""
            ).strip()
            if active_event_registration_id:
                event_registration_ids.add(active_event_registration_id)
        valid_ids.update(event_registration_ids)
        valid_ids.update(
            f"scope:{scope_id}"
            for scope_id in (stored.get("scopes") or {}).keys()
        )
        for item in provenance:
            reference_id = str(item.get("reference_id") or "").strip()
            if item.get("source") not in {"previous_user_turn", "world_fact"}:
                continue
            if not reference_id or reference_id not in valid_ids:
                return {**base, "reason": "historical_reference_id_not_found"}
            if reference_id.startswith("scope:"):
                expected_scope = reference_id.split(":", 1)[1]
                if str(item.get("scope_id") or "") != expected_scope:
                    return {**base, "reason": "historical_scope_id_mismatch"}
            bindings.append(item)
        if not bindings:
            return {**base, "reason": "historical_binding_not_proven"}
        reference_ids = {str(item.get("reference_id") or "") for item in bindings}
        if len(reference_ids) != 1:
            return {**base, "reason": "historical_reference_not_unique"}
        reference_id = next(iter(reference_ids))
        base.update(
            authorized=True,
            reference_id=reference_id,
            scope_id=next((item.get("scope_id") for item in bindings if item.get("scope_id")), None),
            reason="verified_historical_reference",
        )

    base["bindings"] = bindings
    base["allowed_fields"] = sorted({str(item.get("field") or "") for item in bindings if item.get("field")})
    base["allowed_sources"] = sorted({str(item.get("source") or "") for item in bindings if item.get("source")})
    return base


def _agent_v2_archive_active_scope(av2: Dict[str, Any], reason: str) -> None:
    """Conserva el scope saliente como memoria pasiva antes de cambiar de flujo."""
    scope_id = str((av2 or {}).get("active_scope_id") or "").strip()
    if not scope_id:
        return
    scopes = av2.setdefault("scopes", {})
    previous = dict(scopes.get(scope_id) or {})
    desires = dict(av2.get("desires") or {})
    snapshot = {
        **previous,
        "scope_id": scope_id,
        "desires": desires,
        "active_goals": [dict(g) for g in av2.get("active_goals") or [] if isinstance(g, dict)],
        "open_questions": [dict(q) for q in av2.get("open_questions") or [] if isinstance(q, dict)],
        "availability_context": dict(av2.get("availability_context") or {}),
        "write_authorizations": dict(av2.get("write_authorizations") or {}),
        "archived_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "archive_reason": str(reason or "scope_transition"),
    }
    if any((snapshot["desires"], snapshot["active_goals"], snapshot["open_questions"], snapshot["availability_context"])):
        scopes[scope_id] = snapshot


def _agent_v2_publish_context_authorization(
    world: Dict[str, Any],
    authorization: Dict[str, Any],
) -> None:
    """
    Publica exclusivamente la memoria que ContextAuthorization autorizó.

    La memoria persistida sigue intacta en ``stored_memory``. Las vistas
    operativas se reconstruyen en cada publicación y permanecen vacías salvo
    para el question_id/reference_id exacto autorizado.

    Importante: si references_previous apunta a un turno USER, se publica
    únicamente ESE turno en ``world["history"]``. Sin esto, una autorización
    válida podía quedar inutilizable porque el normalizador veía history=[].
    """
    if not isinstance(world, dict):
        return

    auth = dict(authorization or {})
    stored = _agent_v2_stored_memory(world)
    previous_auth = dict(world.get("authorized_context") or {})

    # Cada turno independiente recibe identidad propia; una continuidad validada
    # conserva exactamente el scope al que apunta. El reducer usa esta identidad
    # para archivar el scope saliente sin destruirlo.
    authorized_scope = str(auth.get("scope_id") or "").strip()
    if auth.get("authorized") and authorized_scope:
        world["current_scope_id"] = authorized_scope
    elif str(auth.get("relation") or "") in {
        "new_request", "new_question", "unrelated", "no_pending",
    }:
        turn_id = str(world.get("turn_id") or uuid.uuid4().hex)
        world["current_scope_id"] = f"turn_{turn_id}"

    # Siempre empezamos desde una vista operativa vacía.
    # Esto NO borra memoria persistida.
    world["authorized_context"] = auth
    world["pending_decisions"] = []
    world["open_questions"] = []
    world["desires"] = {}
    world["active_goals"] = []
    world["write_authorizations"] = {}
    world["availability_context"] = None
    world["history"] = []
    world["inferences"] = {}
    world["legacy_signal"] = {}

    facts = dict(world.get("facts") or {})
    facts.pop("recent_released_booking", None)
    world["facts"] = facts

    if not auth.get("authorized"):
        if previous_auth != auth:
            print(
                "   🔐 [CONTEXT AUTH] "
                f"relation={auth.get('relation')} authorized=False"
            )
        return

    # =========================================================
    # PENDING AUTORIZADO
    # =========================================================

    qid = str(auth.get("question_id") or "").strip()

    if qid:
        matched = [
            dict(question)
            for question in (stored.get("pending_decisions") or [])
            if isinstance(question, dict)
            and str(question.get("question_id") or "").strip() == qid
        ]

        # ContextAuthorization ya validó owner/scope/question_id.
        # Publicamos exclusivamente la pregunta autorizada.
        if len(matched) == 1:
            world["pending_decisions"] = matched
            world["open_questions"] = matched

    # =========================================================
    # REFERENCIA HISTÓRICA AUTORIZADA
    # =========================================================

    reference_id = str(
        auth.get("reference_id") or ""
    ).strip()

    allowed_sources = {
        str(value or "").strip()
        for value in (auth.get("allowed_sources") or [])
        if str(value or "").strip()
    }

    # ---------------------------------------------------------
    # TURNO USER ANTERIOR
    # ---------------------------------------------------------
    #
    # stored_memory mantiene todo el historial.
    #
    # Pero world["history"] operacional recibe solamente
    # EL turno cuyo reference_id fue explícitamente autorizado.
    # ---------------------------------------------------------

    if (
        reference_id
        and "previous_user_turn" in allowed_sources
    ):
        history_rows = _agent_v2_history_with_reference_ids(
            world
        )

        matched_history = [
            dict(row)
            for row in history_rows
            if str(
                row.get("reference_id") or ""
            ).strip() == reference_id
        ]

        if len(matched_history) == 1:
            world["history"] = matched_history

            print(
                "   🔗 [AUTHORIZED MEMORY] "
                f"source=previous_user_turn "
                f"reference_id={reference_id}"
            )

        else:
            # Fail closed:
            # nunca reemplazar una referencia que desapareció
            # por "el mensaje más parecido" o "el último".
            print(
                "   🚫 [CONTEXT AUTH] "
                f"reference_id user_history "
                f"no publicable={reference_id!r}"
            )

    # =========================================================
    # RECENT RELEASED BOOKING
    # =========================================================
    #
    # Es un world_fact especial oculto por defecto.
    # Sólo reaparece si ESA referencia fue autorizada.
    # =========================================================

    released = (
        stored.get("recent_released_booking")
        or {}
    )

    released_id = str(
        released.get("reference_id")
        or (
            (released.get("booking") or {}).get(
                "reservation_id"
            )
            if (
                isinstance(released, dict)
                and isinstance(
                    released.get("booking"),
                    dict,
                )
            )
            else ""
        )
        or (
            released.get("reservation_id")
            if isinstance(released, dict)
            else ""
        )
        or ""
    ).strip()

    if (
        reference_id
        and "world_fact" in allowed_sources
        and released_id
        and reference_id == released_id
    ):
        world["facts"][
            "recent_released_booking"
        ] = released

    if previous_auth != auth:
        print(
            "   🔐 [CONTEXT AUTH] "
            f"relation={auth.get('relation')} "
            f"question_id={auth.get('question_id')} "
            f"reference_id={auth.get('reference_id')} "
            f"fields={auth.get('allowed_fields')} "
            f"sources={auth.get('allowed_sources')}"
        )


def _agent_v2_rehydrate_authorized_context_for_execution(
    world: Dict[str, Any],
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Revalida y republica ContextAuthorization sobre un World recién reconstruido.

    ``construir_world_state_agent_v2()`` es deliberadamente fail-closed:
    devuelve ``open_questions=[]``, ``pending_decisions=[]`` y
    ``authorized_context=unresolved`` hasta que una autorización contextual
    proyecta únicamente la memoria permitida.

    El executor reconstruye World antes de Planner y antes de cada Tool Policy.
    v67 no republicaba la autorización después de esos refreshes; por eso una
    continuidad ya demostrada como ``released_booking_rebook`` perdía la
    pregunta visible justo antes de Policy y terminaba en
    ``hora_sin_evidencia_del_usuario``.

    Esta función NO confía ciegamente en la autorización anterior:
    vuelve a ejecutar ``_agent_v2_context_authorization`` contra la memoria
    persistida del World fresco y sólo entonces publica la proyección.
    """
    if not isinstance(world, dict):
        return world

    perception = perception or {}
    frame = _agent_v2_semantic_frame(perception) or {}
    relation = _agent_v2_semantic_context_relation(frame) or {}
    relation_type = str(relation.get("type") or "no_pending")

    if relation_type not in {
        "answers_pending",
        "references_previous",
    }:
        return world

    fresh_auth = _agent_v2_context_authorization(
        perception,
        world,
    )

    # Defensa extra: si el ExecutionContract ya había congelado una
    # autorización, el refresh sólo puede conservar EXACTAMENTE ese binding.
    execution_contract = (
        perception.get("execution_contract")
        if isinstance(perception.get("execution_contract"), dict)
        else {}
    )
    frozen_auth = (
        execution_contract.get("authorized_context")
        if isinstance(execution_contract.get("authorized_context"), dict)
        else {}
    )

    if frozen_auth.get("authorized"):
        mismatches = []

        for key in (
            "relation",
            "question_id",
            "reference_id",
            "scope_id",
        ):
            expected = str(frozen_auth.get(key) or "").strip()
            actual = str(fresh_auth.get(key) or "").strip()

            # Sólo comparamos identificadores que estaban materializados en el
            # contrato congelado. Nunca completamos uno con otro scope.
            if expected and expected != actual:
                mismatches.append(
                    f"{key}:{expected!r}!={actual!r}"
                )

        if mismatches:
            # V172: consumir una PendingInteraction NO puede borrar la autoridad
            # del mismo turno antes de ejecutar el write que esa interacción
            # acaba de autorizar. El World fresco ya no contiene la pregunta
            # abierta, pero Perception conserva una resolución stateful,
            # el ExecutionContract congelado y el Semantic Effect Verifier.
            #
            # Sólo preservamos el binding congelado cuando TODO coincide:
            #   - la resolución actual confirmó exactamente ese pending;
            #   - el contrato autoritativo contiene un único create_booking;
            #   - ese mismo act_id está autorizado para WRITE;
            #   - el BookingObjective del mismo act está READY.
            #
            # No se interpreta texto ni se revive memoria arbitraria.
            resolution = (
                perception.get("context_resolution")
                if isinstance(perception.get("context_resolution"), dict)
                else {}
            )
            frozen_question_id = str(
                frozen_auth.get("question_id") or ""
            ).strip()
            resolved_question_id = str(
                resolution.get("question_id")
                or resolution.get("interaction_id")
                or ""
            ).strip()
            resolution_kind = str(
                resolution.get("type") or ""
            ).strip()
            resolution_value = str(
                resolution.get("resolution") or ""
            ).strip()

            contract_acts = [
                dict(item)
                for item in (execution_contract.get("acts") or [])
                if isinstance(item, dict)
                and str(item.get("operation") or "") == "create_booking"
            ]
            create_act = (
                contract_acts[0]
                if len(contract_acts) == 1
                else {}
            )
            create_act_id = str(
                create_act.get("act_id") or ""
            ).strip()

            verification = (
                perception.get("semantic_effect_verification")
                if isinstance(
                    perception.get("semantic_effect_verification"),
                    dict,
                )
                else {}
            )
            verified_write = bool(
                verification.get("status") == "verified"
                and create_act_id
                and any(
                    isinstance(item, dict)
                    and item.get("authorized") is True
                    and str(item.get("act_id") or "").strip() == create_act_id
                    and str(item.get("operation") or "").strip()
                    in {"", "create_booking"}
                    for item in (
                        verification.get("write_authorizations")
                        or []
                    )
                )
            )

            objective = (
                perception.get("booking_objective")
                if isinstance(
                    perception.get("booking_objective"),
                    dict,
                )
                else {}
            )
            objective_ready = bool(
                str(objective.get("operation") or "")
                == "create_booking"
                and str(objective.get("act_id") or "").strip()
                == create_act_id
                and not [
                    str(value or "").strip()
                    for value in (
                        objective.get("missing_fields")
                        or []
                    )
                    if str(value or "").strip()
                ]
            )

            consumed_pending_same_turn = bool(
                execution_contract.get("authoritative") is True
                and frozen_auth.get("authorized") is True
                and resolution.get("resolved") is True
                and resolution_kind == "answers_pending"
                and resolution_value in {
                    "confirm",
                    "accept",
                    "select",
                }
                and frozen_question_id
                and resolved_question_id == frozen_question_id
                and create_act_id
                and verified_write
                and objective_ready
            )

            if consumed_pending_same_turn:
                fresh_auth = copy.deepcopy(frozen_auth)
                fresh_auth["authorized"] = True
                fresh_auth["reason"] = (
                    "consumed_pending_same_turn_execution_continuation"
                )
                fresh_auth["rehydrated_after_pending_consumed"] = True
                print(
                    "   🔐 [AgentV2 V172 CONSUMED PENDING AUTHORITY] "
                    f"question_id={frozen_question_id} "
                    f"act_id={create_act_id} "
                    "→ autorización congelada preservada hasta ejecutar write"
                )
            else:
                fresh_auth = {
                    **dict(fresh_auth or {}),
                    "authorized": False,
                    "allowed_fields": [],
                    "allowed_sources": [],
                    "bindings": [],
                    "reason": (
                        "execution_context_rehydration_mismatch:"
                        + ",".join(mismatches)
                    ),
                }

    _agent_v2_publish_context_authorization(
        world,
        fresh_auth,
    )

    if fresh_auth.get("authorized"):
        print(
            "   ♻️ [AgentV2 CONTEXT REHYDRATE] "
            f"relation={fresh_auth.get('relation')} "
            f"question_id={fresh_auth.get('question_id')} "
            f"scope_id={fresh_auth.get('scope_id')} "
            f"pending={len(world.get('open_questions') or [])}"
        )
    else:
        print(
            "   🚫 [AgentV2 CONTEXT REHYDRATE] "
            f"relation={relation_type} "
            f"reason={fresh_auth.get('reason')}"
        )

    return world


def construir_world_state_agent_v2(
    telefono: str,
    prospecto: Dict,
    conv_state: Dict,
    mensaje_actual: str,
    image_path: str = "",
) -> Dict[str, Any]:
    """
    WORLD STATE único. Separa hechos, inferencias y deseos.

    - facts: calendario/config/cliente verificados
    - inferences: interpretaciones IA, nunca autorizan una escritura por sí solas
    - desires: elecciones/pedidos explícitos y booking draft actual
    """
    conv_state = conv_state or {}
    av2 = _agent_v2_state(conv_state)
    reservas = _agent_v2_reservas_reales(telefono, prospecto)
    # V2 lee exclusivamente su estado canónico. Los campos legacy se escriben
    # por compatibilidad, pero no vuelven a ser autoridad de World.
    draft = (av2.get("desires") or {}).get("booking_draft")
    recent_released_booking = _agent_v2_recent_released_booking_context(telefono)

    # reservation_target solo puede apuntar a una fila REAL de calendario.
    desires_snapshot = dict(av2.get("desires") or {})
    if not reservas and desires_snapshot.get("reservation_target"):
        print(
            "   👻 [AgentV2 WORLD GUARD] reservation_target sin reserva real → "
            "ignorado en este turno"
        )
        desires_snapshot.pop("reservation_target", None)

    expected_owner = _memory_owner_key(telefono)
    pending = []
    for q in av2.get("open_questions") or []:
        question = dict(q)
        question_owner = str(question.get("_memory_owner") or "").strip()
        if question_owner and question_owner != expected_owner:
            print(
                f"   🚨 [AgentV2 MEMORY ISOLATION] pregunta descartada "
                f"owner={question_owner} expected={expected_owner}"
            )
            continue
        question["_memory_owner"] = expected_owner
        question.setdefault(
            "scope_id",
            f"question_{str(question.get('question_id') or uuid.uuid4().hex)[:24]}",
        )
        pending.append(question)
    # No se crean preguntas V2 desde seleccion_cancha_pendiente, fase,
    # aclaracion_hora_contexto ni ninguna otra réplica legacy.

    historial = []

    for msg in (conv_state.get("historial") or [])[-12:]:
        if not isinstance(msg, dict):
            continue

        msg_owner = str(msg.get("_memory_owner") or "").strip()

        # Compatibilidad: entradas anteriores a V2.7.1 no tenían owner.
        # Si SÍ tienen owner y no coincide, jamás entran al World State.
        if msg_owner and msg_owner != expected_owner:
            print(
                f"   🚨 [AgentV2 MEMORY ISOLATION] historial descartado "
                f"owner={msg_owner} expected={expected_owner}"
            )
            continue

        historial.append({
            "_memory_owner": expected_owner,
            "role": msg.get("role"),
            "content": str(msg.get("content") or "")[:500],
            "timestamp": msg.get("timestamp"),
        })

    # Primero cache auxiliar; después las fuentes reales lo SOBRESCRIBEN.
    facts = dict(av2.get("facts") or {})
    facts.update({
        "memory_owner": expected_owner,
        "reservas_reales": reservas,
        "cliente": {
            "nombre": (prospecto or {}).get("nombre"),
            "telefono": telefono,
            "es_cliente": (prospecto or {}).get("es_cliente"),
        },
        "negocio": _business_knowledge_snapshot(),
        "image_received": bool(image_path),
        "calendar_is_source_of_truth": True,
        "deposit_credit": obtener_credito_senia_disponible(telefono),
    })

    stored_memory = {
        "desires": {**desires_snapshot, "booking_draft": draft},
        "active_goals": list(av2.get("active_goals") or []),
        "write_authorizations": dict(av2.get("write_authorizations") or {}),
        "pending_decisions": pending,
        "availability_context": av2.get("availability_context"),
        "history": historial,
        "inferences": dict(av2.get("inferences") or {}),
        "recent_released_booking": recent_released_booking,
        "scopes": dict(av2.get("scopes") or {}),
        # Sólo diagnóstico/compatibilidad: ninguna capa V2 operacional lee esto.
        "legacy_signal": {
            "fase": conv_state.get("fase", "inicial"),
            "dia": conv_state.get("dia_propuesto"),
            "hora": conv_state.get("hora_propuesta"),
            "cancha": conv_state.get("cancha_propuesta"),
            "senia_estado": conv_state.get("senia_estado"),
        },
    }
    world = {
        "version": AGENT_V2_VERSION,
        "turn_id": av2.get("last_turn_id"),
        "message": str(mensaje_actual or ""),
        "facts": facts,
        "current_turn_context": {
            "message": str(mensaje_actual or ""),
            "turn_id": av2.get("last_turn_id"),
            "now": datetime.datetime.now(TIMEZONE).isoformat(),
        },
        "stored_memory": stored_memory,
        "authorized_context": {
            "relation": "unresolved",
            "authorized": False,
            "allowed_fields": [],
            "allowed_sources": [],
        },
        # Compatibilidad de interfaces: estas vistas son deliberadamente
        # pasivas hasta que ContextAuthorization publique una proyección.
        "inferences": {},
        "desires": {},
        "active_goals": [],
        "write_authorizations": {},
        "pending_decisions": [],
        "open_questions": [],
        "availability_context": None,
        "history": [],
        "legacy_signal": {},
        "tool_catalog": AGENT_V2_TOOL_CATALOG,
    }
    print(
        "   🧠 [MEMORY STORED] "
        f"pending={len(pending)} draft={bool(draft)} "
        f"availability={bool(stored_memory.get('availability_context'))}"
    )
    return world


def _agent_v2_pending_question(world: Dict, field: str) -> Optional[Dict[str, Any]]:
    expected_owner = str(
        ((world or {}).get("facts") or {}).get("memory_owner") or ""
    ).strip()
    for q in reversed((world or {}).get("open_questions") or []):
        question_owner = str((q or {}).get("_memory_owner") or "").strip()
        if expected_owner and question_owner and question_owner != expected_owner:
            continue
        if str(q.get("field") or "") == field:
            return q
    return None


def _agent_v2_preserve_missing_question_context(
    world: Dict[str, Any],
    field: str,
    incoming: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Conserva el contexto verificado al volver a pedir el mismo dato.

    Una barrera de Policy puede descubrir que la hora inferida no estaba
    respaldada por el turno actual y volver a solicitarla. Esa nueva pregunta no
    debe borrar las opciones que una consulta real de disponibilidad ya había
    verificado. Si el alcance (día) sigue siendo el mismo, heredamos esas opciones
    y metadatos; ante un día distinto no se conserva nada.

    Esta función sólo combina estado estructurado. No interpreta lenguaje.
    """
    clean = dict(incoming or {})
    clean["field"] = field
    clean.setdefault("scope_id", (world or {}).get("current_scope_id"))
    authorization = (world or {}).get("authorized_context") or {}
    if not authorization.get("authorized"):
        return clean
    previous = _agent_v2_pending_question(world or {}, field) or {}
    if not previous:
        return clean

    authorized_question_id = str(authorization.get("question_id") or "")
    incoming_question_id = str(clean.get("question_id") or authorized_question_id)
    previous_question_id = str(previous.get("question_id") or "")
    authorized_scope = str(authorization.get("scope_id") or "")
    incoming_scope = str(clean.get("scope_id") or authorized_scope)
    previous_scope = str(previous.get("scope_id") or "")
    same_scope = bool(
        authorized_question_id
        and incoming_question_id == authorized_question_id == previous_question_id
        and authorized_scope
        and incoming_scope == authorized_scope == previous_scope
    )
    if not same_scope:
        return clean

    clean["question_id"] = authorized_question_id
    clean["scope_id"] = authorized_scope

    if not list(clean.get("options") or []):
        clean["options"] = list(previous.get("options") or [])
    for key in (
        "dia", "hora", "cancha", "duracion_horas", "booking_shape",
        "requested_hours", "goal_context", "booking_choice",
    ):
        if clean.get(key) in (None, "", []):
            previous_value = previous.get(key)
            if previous_value not in (None, "", []):
                clean[key] = (
                    list(previous_value)
                    if isinstance(previous_value, list)
                    else previous_value
                )
    return clean




def _agent_v2_current_message_is_asap(mensaje: str) -> bool:
    """
    Grounding semántico de urgencia temporal.

    La IA decide intención; este detector es una barrera de seguridad para expresiones
    inequívocas de "lo antes posible". No convierte "ya te dije" en ASAP.
    """
    norm = normalizar_texto_ia(mensaje or "")
    if not norm:
        return False
    return bool(
        re.search(
            r"\b(?:ahora(?:\s+mismo)?|en\s+este\s+momento|lo\s+antes\s+posible|cuanto\s+antes|para\s+ahora)\b",
            norm,
        )
    )


def _agent_v2_current_message_references_prior_user_input(mensaje: str) -> bool:
    """
    Fallback de grounding para referencias metaconversacionales.

    PERCEPTION es la fuente principal; esto solo evita perder una referencia obvia
    como "ya te dije" / "en el audio te dije". Nunca toma una propuesta del agente
    como elección del usuario.
    """
    norm = normalizar_texto_ia(mensaje or "")
    if not norm:
        return False
    return bool(
        re.search(
            r"\b(?:ya\s+te\s+dije|te\s+dije\s+(?:antes|cual|cuales)|"
            r"en\s+el\s+audio\s+te\s+dije|lo\s+que\s+te\s+dije|"
            r"los?\s+que\s+te\s+dije|como\s+te\s+dije)\b",
            norm,
        )
    )


def _agent_v2_dedupe_hours(values: List[Any]) -> List[str]:
    seen = set()
    clean = []
    for raw in values or []:
        hour = normalizar_hora_detectada(raw)
        if not hora_es_valida(hour) or hour in seen:
            continue
        seen.add(hour)
        clean.append(hour)
    return clean


def _agent_v2_recent_referenced_user_text(
    world: Dict[str, Any],
    current_message: str,
) -> str:
    """
    Resuelve referencias SOLO contra mensajes previos del mismo contacto.

    `world.history` ya proviene del conversation_state identificado por teléfono.
    Se excluyen mensajes assistant y el texto metaconversacional actual.
    """
    current_norm = normalizar_texto_ia(current_message or "")
    user_candidates = []
    for item in reversed(list((world or {}).get("history") or [])):
        if not isinstance(item, dict) or item.get("role") != "user":
            continue
        text = str(item.get("content") or "").strip()
        if not text:
            continue
        if current_norm and normalizar_texto_ia(text) == current_norm:
            continue
        user_candidates.append(text)

    # Preferir la solicitud previa que contiene horas explícitas; si no, el último
    # mensaje del usuario. Jamás usar texto del agente para inferir una elección.
    for text in user_candidates:
        if _agent_v2_dedupe_hours(extraer_horas_reales_de_texto(text)):
            return text
    return user_candidates[0] if user_candidates else ""


def _agent_v2_validate_requested_duration(value: Any) -> Dict[str, Any]:
    """
    Valida duración EXPLÍCITA sin el fallback silencioso de normalizar_duracion_horas().

    Una solicitud de 3 horas nunca puede degradarse accidentalmente a 1 hora.
    """
    allowed = sorted({
        float(v)
        for v in (ALLOWED_TURN_DURATIONS or [DEFAULT_TURN_DURATION_HOURS])
    })
    try:
        requested = float(str(value).replace(",", ".").strip())
    except (TypeError, ValueError):
        return {
            "valid": False,
            "requested": None,
            "duration_horas": None,
            "allowed": allowed,
        }

    valid = any(abs(requested - option) < 1e-9 for option in allowed)
    return {
        "valid": valid,
        "requested": requested,
        "duration_horas": requested if valid else None,
        "allowed": allowed,
    }


def _agent_v2_infer_booking_shape_from_text(
    mensaje: str,
    requested_hours: List[str],
    model_shape: str = "",
) -> str:
    allowed = {"single", "contiguous_block", "multiple_separate", "unknown"}
    if extraer_rango_horario_de_texto(mensaje):
        return "contiguous_block"
    shape = str(model_shape or "").strip().lower()
    if shape not in allowed:
        shape = "unknown"

    if len(requested_hours) <= 1:
        return "single"

    # Las expresiones estructurales inequívocas del texto son hechos lingüísticos
    # del turno y corrigen una eventual clasificación contradictoria del LLM.
    norm = normalizar_texto_ia(mensaje or "")
    if re.search(
        r"\b(?:junt[ao]s?|seguid[ao]s?|de\s+corrido|continu[ao]s?|"
        r"todas?\s+esas?\s+horas?|sin\s+cortar)\b",
        norm,
    ):
        return "contiguous_block"
    if re.search(
        r"\b(?:por\s+separado|separad[ao]s?|turnos?\s+distintos?|reservas?\s+distintas?)\b",
        norm,
    ):
        return "multiple_separate"

    return shape


def _agent_v2_build_contiguous_block_request(
    requested_hours: List[str],
) -> Optional[Dict[str, Any]]:
    """
    Convierte horas nombradas + intención "juntas" en un bloque continuo.

    Ej.: 17:00 + 19:00, con slots de 60 min => 17:00-20:00 (3 horas).
    """
    clean = _agent_v2_dedupe_hours(requested_hours)
    if len(clean) < 2:
        return None

    minute_pairs = []
    for hour in clean:
        minute = _hora_a_minutos_local(hour)
        if minute is None:
            continue
        minute_pairs.append((minute, hour))
    if len(minute_pairs) < 2:
        return None

    minute_pairs.sort(key=lambda x: x[0])
    start_min, start_hour = minute_pairs[0]
    last_min, _ = minute_pairs[-1]
    slot_minutes = int(TURN_DURATION_MINUTES or 60)
    requested_duration = (last_min - start_min + slot_minutes) / 60.0
    validation = _agent_v2_validate_requested_duration(requested_duration)

    # requested_slots representa lo que el usuario quiere ocupar como bloque,
    # independientemente de si la duración está habilitada comercialmente.
    slots_count = max(1, int(round(requested_duration * 60 / slot_minutes)))
    requested_slots = [
        _minutos_a_hora(start_min + idx * slot_minutes)
        for idx in range(slots_count)
    ]
    return {
        "booking_shape": "contiguous_block",
        "start_time": start_hour,
        "requested_hours": clean,
        "requested_slots": requested_slots,
        "requested_duration_horas": requested_duration,
        "duration_horas": validation.get("duration_horas"),
        "duration_valid": bool(validation.get("valid")),
        "allowed_durations": list(validation.get("allowed") or []),
    }



def _agent_v2_block_request_from_start_duration(
    start_time: str,
    duration_horas: Any,
    requested_hours: List[str] = None,
) -> Optional[Dict[str, Any]]:
    start = normalizar_hora_detectada(start_time)
    validation = _agent_v2_validate_requested_duration(duration_horas)
    if not hora_es_valida(start):
        return None

    requested_duration = validation.get("requested")
    if requested_duration is None:
        return None

    requested_slots = slots_para_bloque(start, requested_duration)
    return {
        "booking_shape": "contiguous_block",
        "start_time": start,
        "requested_hours": _agent_v2_dedupe_hours(requested_hours or []),
        "requested_slots": requested_slots,
        "requested_duration_horas": requested_duration,
        "duration_horas": validation.get("duration_horas"),
        "duration_valid": bool(validation.get("valid")),
        "allowed_durations": list(validation.get("allowed") or []),
    }


def _agent_v2_day_mention_is_negated(
    normalized_text: str,
    start: int,
    end: int,
) -> bool:
    """Distingue una fecha pedida de una fecha que el usuario descartó."""
    before = normalized_text[max(0, start - 32):start]
    after = normalized_text[end:end + 24]
    rejected_before = bool(re.search(
        r"\b(?:no|nunca)\s+(?:(?:me\s+sirve|me\s+queda|puedo|quiero|podria|podemos)\s+)?"
        r"(?:(?:para|el|la)\s+)*$",
        before,
    ))
    rejected_after = bool(re.match(
        r"\s*(?:no|tampoco)\b(?:\s+(?:puedo|quiero|me\s+sirve|me\s+queda))?",
        after,
    ))
    return rejected_before or rejected_after


def _agent_v2_resolve_reservation_target(
    world: Dict,
    perception: Dict,
    reservation_id: str = "",
) -> Optional[Dict[str, Any]]:
    """
    Resuelve qué reserva REAL del calendario es el objetivo del turno actual.

    ORDEN DE AUTORIDAD:

    1. reservation_id explícito.
    2. Entidades explícitas/grounded del mensaje actual.
    3. Continuidad financiera desde el último PAYMENT_PARTIAL.
    4. Si existe una única reserva con transferencia parcial,
       usar esa reserva para choose_payment_method.
    5. Si existe una única reserva real, usarla.
    6. Si sigue habiendo ambigüedad, devolver None.

    IMPORTANTE:
    - NO interpreta lenguaje.
    - NO usa regex para decidir intención.
    - NO decide si el usuario quiere pagar en efectivo.
    - La intención ya debe venir autorizada por SemanticFrame /
      ExecutionContract.
    - Esta función únicamente resuelve IDENTIDAD DE RESERVA.
    """

    world = world or {}
    perception = perception or {}

    facts = (
        world.get("facts")
        or {}
    )

    reservations = list(
        facts.get("reservas_reales")
        or []
    )

    if not reservations:
        return None

    # ==========================================================
    # NORMALIZAR RESERVAS LÓGICAS
    # ==========================================================
    #
    # Una reserva de 2 horas puede ocupar varias filas físicas
    # del calendario pero compartir el mismo reservation_id.
    # ==========================================================

    logical_reservations: Dict[str, Dict[str, Any]] = {}

    for raw_row in reservations:

        if not isinstance(raw_row, dict):
            continue

        enriched = _agent_v2_enrich_reservation(
            raw_row
        )

        rid = _agent_v2_reservation_id(
            enriched
        )

        if not rid:
            continue

        if rid not in logical_reservations:
            logical_reservations[rid] = enriched

    if not logical_reservations:
        return None

    # ==========================================================
    # 1. RESERVATION_ID EXPLÍCITO
    # ==========================================================

    requested_id = str(
        reservation_id
        or (
            perception.get("reservation_target")
            or {}
        ).get("reservation_id")
        or (
            (
                world.get("desires")
                or {}
            ).get("reservation_target")
            or {}
        ).get("reservation_id")
        or ""
    ).strip()

    if requested_id:

        target = _agent_v2_find_reservation_by_id(
            reservations,
            requested_id,
        )

        if target:

            print(
                "   🎯 [AgentV2 RESERVATION TARGET] "
                f"ID explícito → {requested_id}"
            )

            return target

    # ==========================================================
    # 2. ENTIDADES DEL TURNO ACTUAL
    # ==========================================================

    entities = (
        perception.get("entities")
        or {}
    )

    entity_matches: Dict[str, Dict[str, Any]] = {}

    for row in reservations:

        if not isinstance(row, dict):
            continue

        if not _agent_v2_reservation_matches_current_entities(
            row,
            entities,
        ):
            continue

        enriched = _agent_v2_enrich_reservation(
            row
        )

        rid = _agent_v2_reservation_id(
            enriched
        )

        if rid:
            entity_matches.setdefault(
                rid,
                enriched,
            )

    if len(entity_matches) == 1:

        target = next(
            iter(entity_matches.values())
        )

        print(
            "   🎯 [AgentV2 RESERVATION TARGET] "
            "entidades actuales → "
            f"{_agent_v2_reservation_id(target)}"
        )

        return target

    # ==========================================================
    # DETERMINAR SI ESTA OPERACIÓN ES UNA CONTINUACIÓN
    # DE MÉTODO DE PAGO
    # ==========================================================
    #
    # Esto NO interpreta el texto.
    # Sólo lee operaciones YA AUTORIZADAS por SemanticFrame.
    # ==========================================================

    operations = set()

    try:
        for act in _agent_v2_authoritative_semantic_acts(
            perception
        ):

            if not isinstance(act, dict):
                continue

            operation = str(
                act.get("operation")
                or ""
            ).strip()

            if operation:
                operations.add(
                    operation
                )

    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 RESERVATION TARGET] "
            "no pude leer acts autoritativos: "
            f"{type(exc).__name__}: {exc}"
        )

    choosing_payment_method = (
        "choose_payment_method"
        in operations
    )

    # ==========================================================
    # 3. CONTINUIDAD FINANCIERA:
    # last_partial_payment
    # ==========================================================
    #
    # Ejemplo:
    #
    # registrar_senia(ID 29)
    #     ↓
    # PAYMENT_PARTIAL(ID 29)
    #     ↓
    # agente ofrece completar diferencia
    #     ↓
    # usuario elige efectivo
    #     ↓
    # choose_payment_method
    #
    # La acción DEBE seguir vinculada a ID 29.
    # ==========================================================

    if choosing_payment_method:

        last_partial = (
            facts.get("last_partial_payment")
            or {}
        )

        if isinstance(
            last_partial,
            dict,
        ):

            last_partial_id = str(
                last_partial.get("reservation_id")
                or (
                    last_partial.get("reserva")
                    or {}
                ).get("reservation_id")
                or ""
            ).strip()

            if last_partial_id:

                target = _agent_v2_find_reservation_by_id(
                    reservations,
                    last_partial_id,
                )

                if target:

                    total = _monto_a_int(
                        target.get("precio_total")
                    )

                    if total is None:
                        total = calcular_precio_total(
                            target.get("duracion_horas")
                            or DEFAULT_TURN_DURATION_HOURS
                        )

                    transferido = (
                        _senia_pagada_acumulada(
                            target,
                            total,
                        )
                    )

                    faltante = (
                        _senia_faltante_para_confirmar(
                            target,
                            total,
                        )
                    )

                    # La referencia financiera sólo es válida
                    # si la reserva TODAVÍA representa un pago
                    # parcial pendiente de completar.
                    if (
                        transferido > 0
                        and faltante > 0
                    ):

                        print(
                            "   🔗 [AgentV2 PAYMENT CONTINUATION] "
                            "choose_payment_method continúa "
                            f"PAYMENT_PARTIAL ID={last_partial_id} "
                            f"transferido={transferido} "
                            f"faltante={faltante}"
                        )

                        return target

    # ==========================================================
    # 4. ÚNICA RESERVA CON TRANSFERENCIA PARCIAL
    # ==========================================================
    #
    # Puede haber varias reservas del mismo usuario.
    #
    # Pero si choose_payment_method está autorizado y solamente
    # UNA de ellas posee dinero efectivamente transferido +
    # diferencia pendiente, esa reserva es la continuación
    # financiera natural.
    #
    # No usamos contenido textual para decidirlo.
    # ==========================================================

    if choosing_payment_method:

        partial_candidates: Dict[
            str,
            Dict[str, Any],
        ] = {}

        for rid, row in logical_reservations.items():

            total = _monto_a_int(
                row.get("precio_total")
            )

            if total is None:

                try:
                    total = calcular_precio_total(
                        row.get("duracion_horas")
                        or DEFAULT_TURN_DURATION_HOURS
                    )
                except Exception:
                    continue

            try:
                transferido = (
                    _senia_pagada_acumulada(
                        row,
                        total,
                    )
                )

                faltante = (
                    _senia_faltante_para_confirmar(
                        row,
                        total,
                    )
                )

            except Exception:
                continue

            senia_estado = str(
                row.get("senia_estado")
                or ""
            ).strip().casefold()

            if (
                transferido > 0
                and faltante > 0
                and senia_estado == "parcial"
            ):

                partial_candidates[
                    rid
                ] = row

        if len(partial_candidates) == 1:

            rid, target = next(
                iter(
                    partial_candidates.items()
                )
            )

            print(
                "   🔗 [AgentV2 PAYMENT CONTINUATION] "
                "única reserva con pago parcial → "
                f"ID={rid}"
            )

            return target

        if len(partial_candidates) > 1:

            print(
                "   ⚠️ [AgentV2 PAYMENT CONTINUATION] "
                "múltiples reservas poseen pago parcial; "
                "no selecciono una automáticamente"
            )

            # FAIL CLOSED.
            return None

    # ==========================================================
    # 5. UNA ÚNICA RESERVA REAL
    # ==========================================================

    if len(logical_reservations) == 1:

        rid, target = next(
            iter(
                logical_reservations.items()
            )
        )

        print(
            "   🎯 [AgentV2 RESERVATION TARGET] "
            f"única reserva real → {rid}"
        )

        return target

    # ==========================================================
    # 6. AMBIGÜEDAD REAL
    # ==========================================================

    print(
        "   ⚠️ [AgentV2 RESERVATION TARGET] "
        f"ambigüedad entre {len(logical_reservations)} "
        "reservas reales"
    )

    return None

def _agent_v2_explicit_day_from_current_message(mensaje: str) -> Optional[str]:
    """
    Extrae el DÍA únicamente del mensaje ACTUAL.

    No consulta historial, booking draft ni reserva activa. Esto evita que una
    reserva real existente haga que Perception omita o reemplace "hoy/mañana".
    """
    raw = str(mensaje or "").strip()
    norm = normalizar_texto_ia(raw)
    if not norm:
        return None

    # Relativos: preservar forma humana para que el planner/tool resuelvan con
    # la zona horaria real al ejecutar.
    match = re.search(r"\bpasado\s+manana\b", norm)
    if match and not _agent_v2_day_mention_is_negated(norm, *match.span()):
        return "pasado mañana"
    match = re.search(r"\bhoy\b", norm)
    if match and not _agent_v2_day_mention_is_negated(norm, *match.span()):
        return "hoy"
    match = re.search(r"\bmanana\b", norm)
    if match:
        # "mañana" aislado puede ser tomorrow o morning. Si aparece con una
        # preposición típica de franja ("a la mañana", "por la mañana"), no lo
        # tratamos como día salvo que exista además un relativo inequívoco.
        if (
            not re.search(r"\b(?:a|por|de)\s+la\s+manana\b", norm)
            and not _agent_v2_day_mention_is_negated(norm, *match.span())
        ):
            return "mañana"

    # Un typo corto no debe borrar un temporal que Perception ya resolvió. Este
    # fuzzy matching está limitado al lexema temporal "mañana" y no clasifica
    # intención; sólo aporta grounding equivalente al literal.
    for match in re.finditer(r"\b[a-z]{5,7}\b", norm):
        token = match.group(0)
        if not token.startswith("ma"):
            continue
        similarity = difflib.SequenceMatcher(None, token, "manana").ratio()
        if similarity < 0.82:
            continue
        prefix = norm[max(0, match.start() - 12):match.start()]
        if re.search(r"(?:a|por|de)\s+la\s+$", prefix):
            continue
        print(
            f"   🗓️ [AgentV2 TEMPORAL TYPO] {token!r} → mañana "
            f"similarity={similarity:.2f}"
        )
        return "mañana"

    # ISO / DD-MM / DD/MM
    m_iso = re.search(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", raw)
    if m_iso and not _agent_v2_day_mention_is_negated(norm, *m_iso.span()):
        return m_iso.group(0)

    m_num = re.search(r"\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?\b", raw)
    if m_num and not _agent_v2_day_mention_is_negated(norm, *m_num.span()):
        return m_num.group(0)

    # "8 de agosto"
    m_text = re.search(
        r"\b(\d{1,2})\s+de\s+"
        r"(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b",
        norm,
    )
    if m_text and not _agent_v2_day_mention_is_negated(norm, *m_text.span()):
        return m_text.group(0)

    # Día de mes aislado: "para el 07" / "el día 7". Se devuelve ISO para
    # conservar también el año si la próxima ocurrencia cae en enero.
    day_of_month = _dia_del_mes_explicito_en_mensaje(raw)
    if day_of_month:
        return day_of_month.isoformat()

    # Día de semana explícito.
    for day in (
        "lunes", "martes", "miercoles", "jueves",
        "viernes", "sabado", "domingo"
    ):
        for match in re.finditer(rf"\b{day}\b", norm):
            if not _agent_v2_day_mention_is_negated(norm, *match.span()):
                return day

    return None


def _agent_v2_explicit_daypart_from_current_message(mensaje: str) -> Optional[str]:
    """
    Extrae franja únicamente cuando está expresada en el mensaje actual.
    Evita usar 'mañana' desnudo como franja porque también significa tomorrow.
    """
    norm = normalizar_texto_ia(mensaje or "")
    if not norm:
        return None

    patterns = (
        ("mañana", (
            r"\ba\s+la\s+manana\b",
            r"\bpor\s+la\s+manana\b",
            r"\bde\s+la\s+manana\b",
        )),
        ("tarde", (
            r"\ba\s+la\s+tarde\b",
            r"\bpor\s+la\s+tarde\b",
            r"\bde\s+la\s+tarde\b",
            r"\besta\s+tarde\b",
        )),
        ("noche", (
            r"\ba\s+la\s+noche\b",
            r"\bpor\s+la\s+noche\b",
            r"\bde\s+la\s+noche\b",
            r"\besta\s+noche\b",
        )),
    )
    for value, regs in patterns:
        if any(re.search(reg, norm) for reg in regs):
            return value
    return None


def _agent_v2_ground_current_message_temporal_entities(
    mensaje: str,
    entities: Dict[str, Any],
    *,
    references_prior_user_input: bool = False,
    temporal_mode: str = "",
) -> Dict[str, Any]:
    """
    Proyección TEMPORAL conservadora del turno actual.

    Esta función ya NO interpreta días ni franjas desde texto crudo.

    La comprensión de lenguaje temporal pertenece a PERCEPTION / al resolvedor
    semántico de fechas. Python solamente conserva valores estructurados ya
    emitidos y aplica invariantes operativas simples.

    Esto evita degradaciones como:

        "viernes de la semana que viene"
            -> parser encuentra "viernes"
            -> resolver_fecha("viernes")
            -> viernes inmediato

    perdiendo el modificador semántico "de la semana que viene".
    """

    grounded = dict(
        entities
        or {}
    )

    mode = str(
        temporal_mode
        or grounded.get(
            "temporal_mode"
        )
        or ""
    ).strip().lower()

    # =========================================================
    # ASAP
    # =========================================================
    #
    # "asap" ya fue una decisión semántica de Perception.
    #
    # Python aplica únicamente su consecuencia operacional.
    # No vuelve a interpretar el mensaje.
    # =========================================================

    if mode == "asap":

        grounded[
            "temporal_mode"
        ] = "asap"

        grounded[
            "dia"
        ] = "hoy"

        try:
            grounded[
                "dia_resuelto"
            ] = resolver_fecha(
                "hoy"
            )

        except Exception:
            grounded[
                "dia_resuelto"
            ] = "hoy"

        grounded[
            "franja_dia"
        ] = None

        grounded[
            "hora"
        ] = None

        return grounded

    grounded[
        "temporal_mode"
    ] = None

    # =========================================================
    # IMPORTANTE
    # =========================================================
    #
    # NO ejecutar:
    #
    #     _agent_v2_explicit_day_from_current_message()
    #
    # acá.
    #
    # Tampoco:
    #
    #     resolver_fecha("viernes")
    #
    # usando un fragmento textual reducido.
    #
    # Los valores presentes todavía son una hipótesis de
    # Perception.
    #
    # _agent_v2_resolve_current_turn_date_with_ai()
    # adjudicará la expresión COMPLETA antes de Planner/Tools.
    # =========================================================

    return grounded


def _agent_v2_semantic_calendar_day(
    data: Dict[str, Any],
) -> Optional[datetime.date]:
    """
    Devuelve la fecha absoluta semántica vigente SIN reinterpretar texto.

    Orden de autoridad:

    1. validated_temporal_resolution validado por el adjudicador temporal.
    2. Un único ISO futuro consistente entre Perception/entities/frame/acts.
    3. Si existen varios ISO distintos, falla cerrado y devuelve None.

    IMPORTANTE:

    - No lee `mensaje`.
    - No usa regex.
    - Un ISO producido por Perception es un candidato estructurado,
      no una verdad incuestionable cuando otras capas discrepan.
    """

    clean = (
        data
        if isinstance(
            data,
            dict,
        )
        else {}
    )

    today = (
        datetime.datetime.now(
            TIMEZONE
        ).date()
    )

    # =========================================================
    # 1. AUTORIDAD TEMPORAL YA VALIDADA
    # =========================================================

    authority = (
        clean.get(
            "validated_temporal_resolution"
        )
        if isinstance(
            clean.get(
                "validated_temporal_resolution"
            ),
            dict,
        )
        else {}
    )

    if (
        authority.get(
            "validated"
        )
        is True
    ):

        value = str(
            authority.get(
                "date"
            )
            or ""
        ).strip()

        try:

            parsed = (
                datetime.date.fromisoformat(
                    value
                )
            )

        except ValueError:

            parsed = None

        if (
            parsed is not None
            and parsed >= today
        ):

            return parsed

        if value:

            print(
                "   🚫 [AgentV2 VERIFIED DATE AUTHORITY] "
                f"autoridad temporal inválida/pasada={value!r}"
            )

    # =========================================================
    # 2. CANDIDATOS ESTRUCTURADOS
    # =========================================================

    raw_candidates = []

    for mention in (
        clean.get(
            "temporal_mentions"
        )
        or []
    ):

        if not isinstance(
            mention,
            dict,
        ):
            continue

        if (
            str(
                mention.get(
                    "kind"
                )
                or ""
            )
            .strip()
            .casefold()
            == "day"
        ):

            raw_candidates.append(
                mention.get(
                    "resolved_value"
                )
            )

    entities = (
        clean.get(
            "entities"
        )
        if isinstance(
            clean.get(
                "entities"
            ),
            dict,
        )
        else {}
    )

    raw_candidates.append(
        entities.get(
            "dia"
        )
    )

    raw_candidates.append(
        entities.get(
            "dia_resuelto"
        )
    )

    frame = (
        _agent_v2_semantic_frame(
            clean
        )
    )

    if isinstance(
        frame,
        dict,
    ):

        temporal = (
            frame.get(
                "temporal"
            )
            if isinstance(
                frame.get(
                    "temporal"
                ),
                dict,
            )
            else {}
        )

        raw_candidates.append(
            temporal.get(
                "day"
            )
        )

        for act in (
            frame.get(
                "acts"
            )
            or []
        ):

            if not isinstance(
                act,
                dict,
            ):
                continue

            act_temporal = (
                act.get(
                    "temporal"
                )
                if isinstance(
                    act.get(
                        "temporal"
                    ),
                    dict,
                )
                else {}
            )

            raw_candidates.append(
                act_temporal.get(
                    "day"
                )
            )

    # =========================================================
    # 3. NORMALIZAR ÚNICAMENTE ISO
    # =========================================================

    parsed_candidates = {}

    for candidate in (
        raw_candidates
    ):

        value = str(
            candidate
            or ""
        ).strip()

        if not value:
            continue

        try:

            parsed = (
                datetime.date.fromisoformat(
                    value
                )
            )

        except ValueError:

            # Formatos humanos como:
            #
            #     Lunes 21/09
            #
            # NO se reinterpretan acá.
            continue

        if parsed < today:

            print(
                "   🧼 [AgentV2 SEMANTIC DATE AUTHORITY] "
                f"descarto fecha pasada ISO={value}"
            )

            continue

        parsed_candidates[
            parsed.isoformat()
        ] = parsed

    # =========================================================
    # 4. UNA SOLA FECHA ESTRUCTURADA
    # =========================================================

    if (
        len(
            parsed_candidates
        )
        == 1
    ):

        return next(
            iter(
                parsed_candidates.values()
            )
        )

    # =========================================================
    # 5. CONFLICTO
    # =========================================================
    #
    # Antes:
    #
    # candidatos:
    #   2026-09-19
    #   2026-09-21
    #
    # → se quedaba con el primero.
    #
    # Ahora:
    #
    # → ninguna capa puede ganar por orden accidental.
    # → adjudicador temporal debe decidir.
    # =========================================================

    if (
        len(
            parsed_candidates
        )
        > 1
    ):

        print(
            "   🚫 [AgentV2 SEMANTIC DATE CONFLICT] "
            f"candidatos={sorted(parsed_candidates)} "
            "→ requiere adjudicación"
        )

    return None


def _agent_v2_apply_current_turn_day_authority(
    data: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    """
    Proyecta una fecha semántica estructurada sobre todas las capas.

    IMPORTANTE:

    - NO interpreta `mensaje`.
    - NO usa regex para decidir el día.
    - semantic_frame.temporal.day permanece en ISO.
    - act.temporal.day permanece en ISO.
    - entities.dia permanece en ISO.
    - entities.dia_resuelto contiene el formato humano/calendario.

    Ejemplo:

        semantic:
            2026-09-25

        presentación:
            Viernes 25/09

    Nunca mezclamos ambos formatos dentro del contrato semántico.
    """

    semantic_date = (
        _agent_v2_semantic_calendar_day(
            data
        )
    )

    if semantic_date is None:
        return data

    current_day = (
        semantic_date.isoformat()
    )

    try:
        resolved_day = (
            resolver_fecha(
                current_day
            )
        )

    except Exception:
        resolved_day = (
            current_day
        )

    clean = dict(
        data
        or {}
    )

    authority = (
        clean.get(
            "validated_temporal_resolution"
        )
    )

    authority = (
        authority
        if isinstance(
            authority,
            dict,
        )
        else {}
    )

    evidence_source = str(
        authority.get(
            "source"
        )
        or "semantic_frame"
    ).strip()

    evidence_text = str(
        authority.get(
            "evidence"
        )
        or current_day
    ).strip()

    # =========================================================
    # ENTITIES
    # =========================================================

    entities = dict(
        clean.get(
            "entities"
        )
        or {}
    )

    previous_days = {
        str(value).strip()

        for value in (
            entities.get(
                "dia"
            ),
            entities.get(
                "dia_resuelto"
            ),
        )

        if str(
            value
            or ""
        ).strip()
    }

    entities[
        "dia"
    ] = current_day

    entities[
        "dia_resuelto"
    ] = resolved_day

    clean[
        "entities"
    ] = entities

    # =========================================================
    # TEMPORAL MENTIONS
    # =========================================================

    mentions = []

    for raw_mention in (
        clean.get(
            "temporal_mentions"
        )
        or []
    ):

        if not isinstance(
            raw_mention,
            dict,
        ):
            mentions.append(
                raw_mention
            )
            continue

        mention = dict(
            raw_mention
        )

        if (
            str(
                mention.get(
                    "kind"
                )
                or ""
            )
            .strip()
            .casefold()
            == "day"
        ):

            if mention.get(
                "resolved_value"
            ):
                previous_days.add(
                    str(
                        mention.get(
                            "resolved_value"
                        )
                    ).strip()
                )

            mention[
                "resolved_value"
            ] = current_day

            if (
                evidence_text
                and not str(
                    mention.get(
                        "evidence"
                    )
                    or ""
                ).strip()
            ):
                mention[
                    "evidence"
                ] = evidence_text

        mentions.append(
            mention
        )

    clean[
        "temporal_mentions"
    ] = mentions

    # =========================================================
    # SEMANTIC FRAME
    # =========================================================

    frame = dict(
        _agent_v2_semantic_frame(
            clean
        )
        or {}
    )

    if frame:

        frame_temporal = dict(
            frame.get(
                "temporal"
            )
            or {}
        )

        if frame_temporal.get(
            "day"
        ):
            previous_days.add(
                str(
                    frame_temporal.get(
                        "day"
                    )
                ).strip()
            )

        # SIEMPRE ISO dentro del contrato.
        frame_temporal[
            "day"
        ] = current_day

        frame[
            "temporal"
        ] = frame_temporal

        day_sensitive_operations = {
            "query_availability",
            "query_reservation",
            "create_booking",
            "cancel_booking",
            "reschedule_booking",
            "modify_resource",
            "add_resource",
            "remove_resource",
            "join_waitlist",
        }

        grounded_acts = []

        for raw_act in (
            frame.get(
                "acts"
            )
            or []
        ):

            if not isinstance(
                raw_act,
                dict,
            ):
                grounded_acts.append(
                    raw_act
                )
                continue

            act = dict(
                raw_act
            )

            temporal = (
                dict(
                    act.get(
                        "temporal"
                    )
                    or {}
                )

                if isinstance(
                    act.get(
                        "temporal"
                    ),
                    dict,
                )

                else {}
            )

            should_receive_day = bool(
                temporal.get(
                    "day"
                )

                or str(
                    act.get(
                        "operation"
                    )
                    or ""
                )
                in day_sensitive_operations
            )

            if not should_receive_day:

                grounded_acts.append(
                    act
                )

                continue

            if temporal.get(
                "day"
            ):
                previous_days.add(
                    str(
                        temporal.get(
                            "day"
                        )
                    ).strip()
                )

            temporal[
                "day"
            ] = current_day

            act[
                "temporal"
            ] = temporal

            # =============================================
            # PROVENANCE
            # =============================================

            provenance = [
                dict(item)

                for item in (
                    act.get(
                        "provenance"
                    )
                    or []
                )

                if (
                    isinstance(
                        item,
                        dict,
                    )

                    and str(
                        item.get(
                            "field"
                        )
                        or ""
                    )
                    .strip()
                    .lower()
                    != "temporal.day"
                )
            ]

            provenance_source = (
                "current_user_turn"

                if evidence_source
                in {
                    "current_user_turn_semantic_date",
                    "semantic_date_adjudicator",
                    "semantic_frame",
                }

                else evidence_source
            )

            provenance.append({
                "field": (
                    "temporal.day"
                ),
                "source": (
                    provenance_source
                ),
                "evidence": (
                    evidence_text
                ),
            })

            act[
                "provenance"
            ] = provenance

            grounded_acts.append(
                act
            )

        frame[
            "acts"
        ] = grounded_acts

        clean[
            "semantic_frame"
        ] = frame

    # =========================================================
    # RESERVATION TARGET
    # =========================================================

    reservation_target = (
        clean.get(
            "reservation_target"
        )
    )

    if isinstance(
        reservation_target,
        dict,
    ):

        target = dict(
            reservation_target
        )

        for key in (
            "dia",
            "fecha",
            "day",
        ):

            if (
                key in target
                and target.get(
                    key
                )
            ):
                target[
                    key
                ] = resolved_day

        clean[
            "reservation_target"
        ] = target

    # =========================================================
    # LOG
    # =========================================================

    stale_days = sorted(
        day

        for day in previous_days

        if (
            day
            and day
            not in {
                current_day,
                resolved_day,
            }
        )
    )

    if stale_days:

        print(
            "   🧼 "
            "[AgentV2 CURRENT DAY AUTHORITY] "
            f"descarto={stale_days} "
            f"actual={current_day} "
            f"→ {resolved_day}"
        )

    if authority.get(
        "validated"
    ):

        print(
            "   ✅ "
            "[AgentV2 VERIFIED DATE AUTHORITY] "
            f"ISO={current_day} "
            f"→ {resolved_day} "
            f"mode={authority.get('mode')} "
            f"evidence={evidence_text!r}"
        )

    else:

        print(
            "   🗓️ "
            "[AgentV2 SEMANTIC DATE AUTHORITY] "
            f"ISO={current_day} "
            f"→ {resolved_day}"
        )

    return clean


