def _event_registration_operations(perception: Dict[str, Any]) -> set:
    contract = (perception or {}).get("execution_contract") or {}
    raw_acts = (
        contract.get("acts")
        if contract.get("authoritative")
        else (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
    )
    event_operations = {
        "query_event", "register_event", "register_event_payment",
        "choose_event_payment_method",
    }
    return {
        str(act.get("operation") or "")
        for act in raw_acts
        if isinstance(act, dict)
        and str(act.get("operation") or "") in event_operations
    }



_EVENT_REGISTRATION_STALE_CLARIFICATION_FIELDS = {
    "operation", "operacion", "intent", "semantic_clarification",
}


def _agent_v2_apply_event_registration_stale_operation_authority(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    """Una nueva inscripción verificada desplaza un pending ``operation`` viejo.

    Corrige el caso observado en producción donde:
      - Perception entiende ``register_event``;
      - Semantic Effect Verifier autoriza ese WRITE por el turno actual;
      - una aclaración genérica ``field=operation`` de un intento anterior fuerza
        ``answers_pending`` sin un binding verificable y vuelve el contrato no
        autoritativo.

    No hay regex de intención. La autoridad proviene exclusivamente del
    SemanticFrame + Semantic Effect Verifier + schema de la pregunta persistida.
    """
    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    relation = dict(_agent_v2_semantic_context_relation(frame) or {})
    if str(relation.get("type") or "").strip() != "answers_pending":
        return clean

    register_acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") == "register_event"
    ]
    if not register_acts:
        return clean

    verification = (
        clean.get("semantic_effect_verification")
        if isinstance(clean.get("semantic_effect_verification"), dict)
        else {}
    )
    if verification.get("status") != "verified":
        return clean
    authorized_write_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }
    register_ids = {
        str(act.get("act_id") or "").strip()
        for act in register_acts if str(act.get("act_id") or "").strip()
    }
    if not register_ids or not register_ids.issubset(authorized_write_ids):
        return clean

    # La autorización debe estar respaldada por el current user turn. Esto evita
    # que una operación heredada de memoria pueda borrar un pending legítimo.
    verified_current_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("evidence_type") or "").strip() in {
            "current_user_turn", "offline_eval_fixture",
        }
    }
    has_current_act_evidence = any(
        any(
            isinstance(item, dict)
            and str(item.get("source") or "").strip() == "current_user_turn"
            and bool(str(item.get("evidence") or "").strip())
            for item in (list(act.get("provenance") or []) + list(act.get("changes") or []))
        )
        for act in register_acts
    )
    if not (register_ids.intersection(verified_current_ids) or has_current_act_evidence):
        return clean

    stored = _agent_v2_stored_memory(world or {})
    pending = [
        dict(q) for q in (stored.get("pending_decisions") or [])
        if isinstance(q, dict)
    ]
    stale = [
        q for q in pending
        if str(q.get("field") or "").strip().casefold()
        in _EVENT_REGISTRATION_STALE_CLARIFICATION_FIELDS
        and str(q.get("source") or "").strip().casefold() == "semantic_adjudicator"
    ]
    if not stale:
        return clean

    relation_qid = str(relation.get("question_id") or "").strip()
    stale_ids = {str(q.get("question_id") or "").strip() for q in stale}
    stale_ids.discard("")
    if relation_qid and relation_qid not in stale_ids:
        # Está apuntando a otra pregunta real: no la secuestramos.
        return clean

    existing_auth = _agent_v2_context_authorization(clean, world or {})
    if existing_auth.get("authorized"):
        # Un binding contextual real siempre gana.
        return clean

    # Esta relación vieja no tiene autorización y el WRITE actual sí. Abrimos un
    # scope nuevo. También quitamos valores de booking que sólo podían provenir
    # del contexto residual, evitando que el date resolver herede un día viejo.
    grounded_fields = set()
    for act in register_acts:
        for item in list(act.get("provenance") or []) + list(act.get("changes") or []):
            if not isinstance(item, dict):
                continue
            if str(item.get("source") or "").strip() != "current_user_turn":
                continue
            field_name = str(item.get("field") or "").strip().casefold()
            if field_name:
                grounded_fields.add(field_name)

    current_event_date_grounded = bool(
        grounded_fields.intersection({"event_date", "temporal.day", "day", "dia"})
        or any(
            isinstance(item, dict)
            and str(item.get("kind") or "").strip().casefold() == "day"
            and bool(str(item.get("evidence") or "").strip())
            for item in (clean.get("temporal_mentions") or [])
        )
    )

    repaired_acts = []
    for raw_act in frame.get("acts") or []:
        if not isinstance(raw_act, dict):
            continue
        act = dict(raw_act)
        if str(act.get("operation") or "") == "register_event":
            temporal = dict(act.get("temporal") or {})
            if not current_event_date_grounded:
                temporal["day"] = None
            for key in ("start", "end", "times", "daypart", "mode", "after", "before", "relation", "duration_hours", "offset"):
                if key == "times":
                    temporal[key] = []
                else:
                    temporal[key] = None
            act["temporal"] = temporal
            act["provenance"] = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
                and str(item.get("source") or "") != "pending_option"
            ]
            act["changes"] = [
                dict(item) for item in (act.get("changes") or [])
                if isinstance(item, dict)
                and str(item.get("source") or "") != "pending_option"
            ]
        repaired_acts.append(act)

    new_relation = {
        "type": "new_request",
        "question_id": None,
        "references_previous_user_turn": False,
        "references_agent_offer": False,
        "answers_pending_question": False,
    }
    frame["context_relation"] = new_relation
    frame["acts"] = repaired_acts
    if isinstance(frame.get("temporal"), dict):
        top_temporal = dict(frame.get("temporal") or {})
        if not current_event_date_grounded:
            top_temporal["day"] = None
        for key in ("start", "end", "times", "daypart", "mode", "after", "before", "relation", "duration_hours", "offset"):
            top_temporal[key] = [] if key == "times" else None
        frame["temporal"] = top_temporal

    entities = dict(clean.get("entities") or {})
    for key in ("dia", "dia_resuelto", "hora", "franja_dia", "temporal_mode"):
        entities[key] = None
    entities["horas"] = []
    if not current_event_date_grounded:
        entities["event_date"] = None
    clean["entities"] = entities
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "new_request"
    clean["suspend_pending_this_turn"] = True
    clean["allow_historical_booking_context_this_turn"] = False
    clean["references_prior_user_input"] = False
    clean["reference_resolution"] = {"source": "none", "resolved": False}
    clean["context_request"] = {"needed": False, "relation": "none", "candidate_types": []}
    clean["context_resolution"] = {
        "requested": True,
        "resolved": False,
        "relation": "new_request",
        "question_id": None,
        "reference_id": None,
        "scope_id": None,
        "reason": "verified_register_event_supersedes_stale_operation_clarification",
    }
    clean.pop("answers_pending_field", None)
    clean["semantic_clarification_required"] = False
    clean.pop("semantic_clarification", None)
    clean["_superseded_pending_fields"] = sorted({
        str(q.get("field") or "").strip()
        for q in stale if str(q.get("field") or "").strip()
    })

    clean["execution_contract"] = _agent_v2_build_execution_contract(clean, world or {})
    if not (clean.get("execution_contract") or {}).get("authoritative"):
        # Fail closed: si el contrato sigue roto por otra causa, no ocultamos el
        # problema ni afirmamos que quedó reparado.
        return perception

    print(
        "   🧹 [EVENT REGISTRATION CONTEXT RESET] "
        f"stale_fields={clean.get('_superseded_pending_fields')} "
        "verified register_event → new_request"
    )
    return clean


def _event_registration_semantic_values(
    perception: Dict[str, Any], world: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Lee exclusivamente hechos estructurados de Perception/World Model."""
    entities = dict((perception or {}).get("entities") or {})
    values = {
        "event_id": entities.get("event_id"),
        "event_name": entities.get("event_name"),
        "event_date": entities.get("event_date"),
        "team_name": entities.get("team_name"),
        "registration_id": entities.get("registration_id"),
    }
    for act in _agent_v2_authoritative_semantic_acts(perception or {}):
        if not isinstance(act, dict) or act.get("operation") not in {
            "query_event", "register_event", "register_event_payment",
            "choose_event_payment_method",
        }:
            continue
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        resource = str(target.get("resource") or "")
        if resource in {"event", "event_registration"}:
            values["event_name"] = values.get("event_name") or target.get("label")
        if resource == "team":
            values["team_name"] = values.get("team_name") or target.get("label")
        values["registration_id"] = (
            values.get("registration_id") or target.get("registration_id")
        )
        temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
        values["event_date"] = values.get("event_date") or temporal.get("day")
        for change in act.get("changes") or []:
            if not isinstance(change, dict):
                continue
            field = str(change.get("field") or "").strip().lower()
            if field in values and change.get("value") not in (None, ""):
                values[field] = change.get("value")
    event_world = (((world or {}).get("facts") or {}).get("event_registration") or {})
    draft = event_world.get("draft") if isinstance(event_world.get("draft"), dict) else {}
    active = (
        event_world.get("active_registration")
        if isinstance(event_world.get("active_registration"), dict) else {}
    )
    for field in values:
        values[field] = values.get(field) or draft.get(field) or active.get(field)
    return values


def _event_registration_find_event(values: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if values.get("event_id"):
        return event_registration.get_business_event(event_id=values.get("event_id"))
    candidates = event_registration.resolve_business_events(
        name=values.get("event_name"), event_date=values.get("event_date")
    )
    if len(candidates) == 1:
        return candidates[0]
    if not values.get("event_name") and not values.get("event_date"):
        active = event_registration.list_business_events()
        return active[0] if len(active) == 1 else None
    return None


_construir_world_state_agent_v2_event_base = construir_world_state_agent_v2


def construir_world_state_agent_v2(
    telefono: str,
    prospecto: Dict,
    conv_state: Dict,
    mensaje_actual: str,
    image_path: str = "",
) -> Dict[str, Any]:
    world = _construir_world_state_agent_v2_event_base(
        telefono, prospecto, conv_state, mensaje_actual, image_path
    )
    event_state = dict((conv_state or {}).get("event_registration") or {})
    active_events = event_registration.list_business_events()
    draft = dict(event_state.get("draft") or {})
    if not draft.get("event_id"):
        # Recuperación de estados escritos por builds anteriores que perdían
        # el contexto al emitir solicitar_dato(team_name). Solo se completa
        # cuando nombre/fecha identifican una edición o existe una única
        # edición activa; nunca se elige arbitrariamente entre varias.
        try:
            recovered_event = _event_registration_find_event(draft)
        except event_registration.EventRegistrationError:
            recovered_event = None
        if recovered_event:
            draft.update({
                "event_id": recovered_event.get("event_id"),
                "event_name": recovered_event.get("name"),
                "event_date": recovered_event.get("date"),
                "team_name": draft.get("team_name"),
            })
            event_state["draft"] = draft
    active_rows = event_registration.list_event_registrations_for_phone(
        telefono, statuses={"pending_payment", "expired", "confirmed"}
    )
    event_state["registrations_for_contact"] = [
        {
            **item["registration"],
            "event_name": item["event"].get("name"),
            "event_date": item["event"].get("date"),
        }
        for item in active_rows
    ]
    if active_rows:
        latest = active_rows[0]
        event = latest["event"]
        registration = latest["registration"]
        # La fila durable manda sobre cualquier snapshot conversacional viejo.
        # Esto permite que confirmaciones/liberaciones admin apliquen sin reinicio.
        event_state["active_registration"] = {
            **registration,
            "event_name": event.get("name"),
            "event_date": event.get("date"),
        }
    else:
        event_state["active_registration"] = None
    event_state["active_events"] = [
        {
            "event_id": event.get("event_id"), "event_name": event.get("name"),
            "event_date": event.get("date"), "registration_price": event.get("registration_price"),
            "prize": event.get("prize"), "capacity": event.get("capacity"),
        }
        for event in active_events
    ]
    world.setdefault("facts", {})["event_registration"] = event_state
    world.setdefault("stored_memory", {})["event_registration"] = event_state
    return world




_EVENT_REGISTRATION_CASH_PREFERENCE_LOCK = threading.RLock()


def _event_registration_payable_matches_for_phone(
    telefono: str,
    *,
    include_expired: bool = True,
) -> List[Dict[str, Any]]:
    """Fuente de verdad para obligaciones de torneo que todavía admiten pago.

    No interpreta texto. Lee exclusivamente las filas durables del Event
    Registration Engine para el teléfono real del canal.
    """
    phone = normalize_phone(telefono or "") or str(telefono or "").strip()
    if not phone:
        return []
    statuses = {"pending_payment"}
    if include_expired:
        statuses.add("expired")
    try:
        rows = event_registration.list_event_registrations_for_phone(
            phone,
            statuses=statuses,
        )
    except Exception as exc:
        print(f"   ⚠️ [EVENT PAYMENT CONTEXT] no pude consultar inscripciones: {exc}")
        return []
    return [dict(item) for item in (rows or []) if isinstance(item, dict)]


def _event_registration_has_payable_context(telefono: str) -> bool:
    """Se usa sólo para impedir que el router legacy de bookings robe un recibo."""
    return bool(_event_registration_payable_matches_for_phone(telefono))


def _event_registration_pinned_registration_id(world: Dict[str, Any]) -> str:
    event_fact = ((world or {}).get("facts") or {}).get("event_registration") or {}
    active = event_fact.get("active_registration") or {}
    return str(active.get("registration_id") or "").strip() if isinstance(active, dict) else ""


def _event_registration_structured_cash_choice(
    perception: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """Devuelve el act IA sólo si YA expresó elección de efectivo.

    Python no busca palabras en el mensaje. Se apoya en el SemanticFrame y en
    el change tipado ``payment_method`` producido por la IA.
    """
    frame = _agent_v2_semantic_frame(perception or {})
    if (frame.get("ambiguity") or {}).get("required"):
        return None
    candidates = []
    for raw_act in frame.get("acts") or []:
        if not isinstance(raw_act, dict):
            continue
        if str(raw_act.get("operation") or "") != "choose_payment_method":
            continue
        act = dict(raw_act)
        # El LLM puede describir genéricamente el target como ``reservation``
        # porque choose_payment_method nació en el dominio booking. No usamos
        # esa etiqueta como verdad operativa. La vinculación final se decide
        # contra IDs/obligaciones REALES en WORLD_STATE dentro del canonicalizer.
        cash_change = None
        for raw_change in act.get("changes") or []:
            if not isinstance(raw_change, dict):
                continue
            if str(raw_change.get("field") or "").strip().casefold() != "payment_method":
                continue
            value = normalizar_texto_ia(raw_change.get("value") or "")
            if value not in {"cash", "efectivo"}:
                continue
            if str(raw_change.get("source") or "") != "current_user_turn":
                continue
            cash_change = dict(raw_change)
            break
        if cash_change:
            candidates.append((act, cash_change))
    if len(candidates) != 1:
        return None
    return {"act": candidates[0][0], "change": candidates[0][1]}


def _agent_v2_canonicalize_event_cash_balance_choice(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
    *,
    rebuild_contract: bool = True,
) -> Dict[str, Any]:
    """Convierte choose_payment_method → choose_event_payment_method de forma grounded.

    Requiere simultáneamente:
      - elección ``cash``/``efectivo`` ya estructurada por IA;
      - una única inscripción de torneo pendiente con pago parcial real;
      - ``paid_amount > 0`` y ``remaining_amount > 0``;
      - si hay otras obligaciones, el ``active_registration`` del Event Engine
        debe fijar inequívocamente esta inscripción.

    Nunca marca dinero como cobrado y nunca confirma la inscripción.
    """
    structured = _event_registration_structured_cash_choice(perception)
    if not structured:
        return perception

    registration = _agent_v2_unique_partial_event_payment_target(world or {})
    if not registration:
        return perception

    registration = dict(registration)
    registration_id = str(registration.get("registration_id") or "").strip()
    event_id = str(registration.get("event_id") or "").strip()
    event = {
        "event_id": event_id,
        "name": registration.get("event_name"),
        "date": registration.get("event_date"),
    }
    if not registration_id or not event_id:
        return perception

    original_act = dict(structured["act"])
    act_id = str(original_act.get("act_id") or "event_cash_balance_current_turn")

    # La conversión sólo puede ocurrir DESPUÉS de que el Effect Verifier haya
    # autorizado este mismo acto del usuario actual. Así el WORLD_STATE decide
    # el target real, pero nunca inventa la voluntad de pagar en efectivo.
    verification = (
        perception.get("semantic_effect_verification")
        if isinstance(perception.get("semantic_effect_verification"), dict)
        else {}
    )
    authorized_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }
    if verification.get("status") != "verified" or act_id not in authorized_ids:
        return perception

    # Si el modelo apuntó a un reservation_id REAL, respetamos ese target. Una
    # etiqueta genérica resource='reservation' sin ID real no puede secuestrar
    # una inscripción de torneo inequívoca.
    target = original_act.get("target") if isinstance(original_act.get("target"), dict) else {}
    claimed_reservation_id = str(target.get("reservation_id") or "").strip()
    real_reservation_ids = {
        str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "").strip()
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
    }
    if claimed_reservation_id and claimed_reservation_id in real_reservation_ids:
        return perception

    # Si también existe una reserva parcial real, sólo seguimos el torneo cuando
    # el estado conversacional activo fija exactamente esta inscripción. Esto
    # permite continuidad stateful sin adivinar entre dos obligaciones reales.
    booking_partial = _agent_v2_unique_partial_payment_target(world or {})
    pinned = _event_registration_pinned_registration_id(world or {})
    if booking_partial is not None and pinned != registration_id:
        return perception

    evidence = str(structured["change"].get("evidence") or mensaje or "").strip()[:500]
    canonical_act = {
        **original_act,
        "act_id": act_id,
        "operation": "choose_event_payment_method",
        "domain": "event_registration",
        "target": {
            "resource": "event_registration",
            "registration_id": registration_id,
            "label": event.get("name"),
            "source": "world_fact",
            "evidence": f"inscripción activa {registration_id}",
        },
        "temporal": {"day": event.get("date")},
        "changes": [{
            "field": "payment_method",
            "value": "cash",
            "operation": "set",
            "unit": None,
            "anchor": None,
            "source": "current_user_turn",
            "evidence": evidence,
            "reference_id": registration_id,
        }],
        "provenance": [{
            "field": "payment_method",
            "source": "current_user_turn",
            "evidence": evidence,
            "question_id": None,
            "option_id": None,
            "reference_id": registration_id,
        }, {
            "field": "registration_id",
            "source": "world_fact",
            "evidence": f"active event registration {registration_id}",
            "reference_id": registration_id,
        }],
        "requested_facts": [],
        "commitment": {"wants_write": True, "wants_information": False},
    }
    frame = dict(_agent_v2_semantic_frame(perception or {}) or {})
    social = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and act.get("operation") in {"greet", "close_conversation"}
    ]
    frame.update({
        "source": "system_event_cash_balance",
        "schema_valid": True,
        "turn_type": "request",
        "intent": {"domain": "event_registration", "operation": "choose_event_payment_method"},
        "targets": [canonical_act["target"]],
        "temporal": canonical_act["temporal"],
        "requested_changes": list(canonical_act["changes"]),
        "requested_facts": [],
        "commitment": canonical_act["commitment"],
        "context_relation": {
            "type": "references_previous",
            "question_id": None,
            "references_previous_user_turn": False,
            "references_agent_offer": True,
            "answers_pending_question": False,
        },
        "acts": social + [canonical_act],
        "ambiguity": {"required": False, "field": None, "reason": "", "alternatives": []},
    })
    clean = dict(perception or {})
    clean["entities"] = {
        **dict(clean.get("entities") or {}),
        "event_id": event_id,
        "event_name": event.get("name"),
        "event_date": event.get("date"),
        "registration_id": registration_id,
        "payment_method": "cash",
    }
    clean["semantic_frame"] = _agent_v2_normalize_semantic_frame(
        {**clean, "semantic_frame": frame}, world, mensaje
    )
    clean["semantic_effect_verification"] = {
        "status": "verified",
        "mode": "trusted_system_event_cash_balance",
        "write_authorizations": [{
            "act_id": act_id,
            "authorized": True,
            "evidence_type": "current_user_turn",
            "authority": "event_partial_registration_cash_choice",
        }],
    }
    if rebuild_contract:
        clean["execution_contract"] = _agent_v2_build_execution_contract(clean, world)
    else:
        clean.pop("execution_contract", None)
    print(
        "   💵 [EVENT REGISTRATION CASH CONTINUITY] "
        f"registration_id={registration_id} team={registration.get('team_name')!r} "
        f"paid={registration.get('paid_amount')} remaining={registration.get('remaining_amount')} "
        "→ choose_event_payment_method"
    )
    return clean


def _event_registration_apply_mixed_cash_confirmation_fields(
    row: Dict[str, Any],
    *,
    now_iso: str,
) -> Dict[str, Any]:
    """Promueve una inscripción parcial a FIRME sin inventar dinero cobrado.

    Equivalente conceptual de ``parcial_efectivo_pendiente`` en bookings:
      - el cupo queda confirmado;
      - lo transferido sigue siendo el único dinero recibido;
      - ``remaining_amount`` conserva el efectivo pendiente;
      - el admin podrá confirmar después la seña/total cuando cobre ese efectivo.
    """
    updated = dict(row or {})
    paid = _monto_a_int(updated.get("paid_amount")) or 0
    remaining = _monto_a_int(updated.get("remaining_amount")) or 0
    if str(updated.get("status") or "").strip() != "pending_payment":
        raise ValueError("registration_not_pending_payment")
    if paid <= 0 or remaining <= 0:
        raise ValueError("registration_has_no_partial_balance")

    updated["status"] = "confirmed"
    updated["payment_status"] = "partial"
    updated["payment_method"] = "transferencia+efectivo"
    updated["confirmed_at"] = str(updated.get("confirmed_at") or now_iso)
    # Ya no es un hold temporal: ocupa cupo como inscripción firme.
    updated["hold_expires_at"] = ""
    updated["expired_at"] = ""
    updated["updated_at"] = now_iso
    # paid_amount / remaining_amount se conservan intencionalmente.
    return updated


def _event_registration_mark_remaining_cash(
    event: Dict[str, Any],
    registration_id: str,
) -> Dict[str, Any]:
    """Confirma el cupo y registra el saldo pendiente en efectivo.

    Igual que una reserva normal con transferencia parcial + diferencia en
    efectivo: la operación queda FIRME aunque el efectivo todavía no haya sido
    cobrado. Confirmar no significa ``payment_complete``.
    """
    event = dict(event or {})
    registration_id = str(registration_id or "").strip()
    if not event or not registration_id:
        return {"ok": False, "reason": "registration_not_found"}
    persisted = str(event.get("registrations_csv_path") or "").strip()
    if not persisted:
        return {"ok": False, "reason": "event_csv_missing"}
    path = os.path.abspath(
        persisted if os.path.isabs(persisted)
        else os.path.join(str(event_registration.BASE_DIR), persisted)
    )
    if not os.path.exists(path):
        return {"ok": False, "reason": "event_csv_missing"}

    with _EVENT_REGISTRATION_CASH_PREFERENCE_LOCK:
        try:
            with open(path, "rb") as raw_f:
                has_bom = raw_f.read(3) == b"\xef\xbb\xbf"
            encoding = "utf-8-sig" if has_bom else "utf-8"
            with open(path, "r", encoding=encoding, newline="") as f:
                reader = csv.DictReader(f)
                fieldnames = list(reader.fieldnames or [])
                rows = [dict(row) for row in reader]
        except Exception as exc:
            return {"ok": False, "reason": "event_csv_read_failed", "detail": str(exc)}

        if not fieldnames:
            return {"ok": False, "reason": "event_csv_invalid_header"}
        for field in (
            "payment_method", "payment_status", "confirmed_at",
            "hold_expires_at", "expired_at", "updated_at",
        ):
            if field not in fieldnames:
                fieldnames.append(field)

        updated = None
        now_iso = datetime.datetime.now(TIMEZONE).isoformat()
        for index, row in enumerate(rows):
            if str(row.get("registration_id") or "").strip() != registration_id:
                continue
            try:
                promoted = _event_registration_apply_mixed_cash_confirmation_fields(
                    row,
                    now_iso=now_iso,
                )
            except ValueError as exc:
                return {"ok": False, "reason": str(exc)}
            rows[index] = promoted
            updated = dict(promoted)
            break
        if updated is None:
            return {"ok": False, "reason": "registration_not_found"}

        base_dir = os.path.dirname(path) or "."
        fd, tmp_path = tempfile.mkstemp(prefix="event_cash_confirmed_", suffix=".tmp", dir=base_dir)
        try:
            with os.fdopen(fd, "w", encoding=encoding, newline="") as f:
                writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
                writer.writeheader()
                writer.writerows(rows)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except OSError:
                    pass
            os.replace(tmp_path, path)
        except Exception as exc:
            try:
                os.remove(tmp_path)
            except OSError:
                pass
            return {"ok": False, "reason": "event_csv_write_failed", "detail": str(exc)}

    try:
        refreshed = event_registration.get_event_registration(registration_id=registration_id)
    except Exception:
        refreshed = None
    registration = dict((refreshed or {}).get("registration") or updated)
    refreshed_event = dict((refreshed or {}).get("event") or event)
    remaining = _monto_a_int(registration.get("remaining_amount")) or 0
    paid = _monto_a_int(registration.get("paid_amount")) or 0
    required = _monto_a_int(registration.get("required_payment")) or (paid + remaining)
    try:
        capacity_state = event_registration.get_event_capacity_state(refreshed_event)
    except Exception:
        capacity_state = {}
    return {
        "ok": True,
        "event": refreshed_event,
        "registration": registration,
        "capacity_state": capacity_state,
        "payment_method": "transferencia+efectivo",
        "paid_amount": paid,
        "remaining_amount": remaining,
        "required_payment": required,
        "cash_pending_amount": remaining,
        "payment_complete": False,
        "registration_confirmed": True,
    }

# V77 — PRE-CONTRACT EVENT CASH CANONICALIZATION
# ------------------------------------------------------------
# ``percibir_turno_agent_v2`` base llama este nombre global en runtime. Al
# envolver el Effect Verifier aquí, convertimos una elección de método de pago
# YA VERIFICADA al dominio event_registration ANTES de construir el
# ExecutionContract. Así el guard de reservas no puede descartarla por no
# existir una reserva de cancha.
_agent_v2_verify_semantic_effects_event_cash_base = _agent_v2_verify_semantic_effects


async def _agent_v2_verify_semantic_effects(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    verified = await _agent_v2_verify_semantic_effects_event_cash_base(
        mensaje,
        perception,
        world,
    )
    return _agent_v2_canonicalize_event_cash_balance_choice(
        verified,
        world,
        mensaje,
        rebuild_contract=False,
    )


_percibir_turno_agent_v2_event_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str, world: Dict, image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_event_base(
        mensaje, world, image_path, learning_policy
    )
    # Un register_event inequívoco y verificado pertenece al turno actual. Una
    # aclaración genérica `operation` de un intento previo no puede convertirlo
    # en answers_pending sin question_id/provenance y secuestrar el contrato.
    perception = _agent_v2_apply_event_registration_stale_operation_authority(
        perception, world, mensaje
    )
    if not image_path:
        return _agent_v2_canonicalize_event_cash_balance_choice(
            perception, world, mensaje
        )
    event_fact = ((world or {}).get("facts") or {}).get("event_registration") or {}
    payable = [
        row for row in (event_fact.get("registrations_for_contact") or [])
        if row.get("status") in {"pending_payment", "expired"}
    ]
    active = payable[0] if len(payable) == 1 else {}
    event_id = str(active.get("event_id") or "").strip()
    registration_id = str(active.get("registration_id") or "").strip()
    if not payable:
        return perception
    pending_bookings = [
        row for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if _pending_hold_row_is_temporary(row)
    ]
    # Si el propio Event Registration Engine dejó esta inscripción como contexto
    # activo (el agente acaba de pedir SU comprobante), esa referencia stateful
    # es más específica que un hold booking histórico. No dejamos que una fila
    # vieja secuestre la imagen que el agente acaba de solicitar para el torneo.
    pinned_registration_id = _event_registration_pinned_registration_id(world)
    event_payment_pinned = bool(
        len(payable) == 1
        and registration_id
        and pinned_registration_id == registration_id
    )
    if event_payment_pinned:
        if pending_bookings:
            print(
                "   🏆 [EVENT PAYMENT PRIORITY] inscripción activa fijada por contexto "
                f"registration_id={registration_id}; suspendo {len(pending_bookings)} "
                "destino(s) booking durante este comprobante"
            )
        pending_bookings = []
    if pending_bookings:
        # Hay más de un destino financiero real. Se reemplaza cualquier
        # inferencia previa por una ambigüedad estructurada y no ejecutable.
        alternatives = []
        if pending_bookings:
            alternatives.append({
                "operation": "register_payment",
                "target_resource": "reservation",
                "reason": "existe una reserva de cancha pendiente de pago",
            })
        if payable:
            alternatives.append({
                "operation": "register_event_payment",
                "target_resource": "event_registration",
                "reason": "existe una inscripción de torneo pendiente de pago",
            })
        ambiguity_frame = {
            "source": "system_event_payment_media", "schema_valid": True,
            "turn_type": "request",
            "intent": {"domain": "payment", "operation": "clarify"},
            "targets": [], "temporal": {}, "requested_changes": [],
            "requested_facts": ["payment_destination"],
            "commitment": {"wants_write": False, "wants_information": True},
            "context_relation": {
                "type": "references_previous", "question_id": None,
                "references_previous_user_turn": False,
                "references_agent_offer": True,
                "answers_pending_question": False,
            },
            "acts": [{
                "act_id": "event_payment_media_ambiguous",
                "operation": "clarify", "domain": "payment",
                "target": {"resource": "payment", "evidence": "current WhatsApp image"},
                "requested_facts": ["payment_destination"],
                "commitment": {"wants_write": False, "wants_information": True},
            }],
            "ambiguity": {
                "required": True, "field": "payment_destination",
                "reason": "el comprobante puede corresponder a más de una obligación real",
                "alternatives": alternatives,
            },
        }
        clean = dict(perception or {})
        clean["semantic_frame"] = _agent_v2_normalize_semantic_frame(
            {**clean, "semantic_frame": ambiguity_frame}, world, mensaje
        )
        clean["semantic_effect_verification"] = {
            "status": "not_required", "mode": "clarification_only",
            "write_authorizations": [],
        }
        clean["payment_media_grounded"] = True
        clean["execution_contract"] = _agent_v2_build_execution_contract(clean, world)
        clean["semantic_clarification_required"] = True
        clean["semantic_clarification"] = {
            "field": "payment_destination",
            "reasons": ["multiple_real_payment_destinations"],
            "alternatives": alternatives,
        }
        return clean
    act = {
        "act_id": "event_payment_media_current_turn",
        "operation": "register_event_payment",
        "domain": "event_registration",
        "target": {
            "resource": "event_registration", "registration_id": registration_id,
            "label": active.get("event_name"), "source": "world_fact",
            "evidence": "current WhatsApp image",
        },
        "temporal": {"day": active.get("event_date")},
        "changes": [], "requested_facts": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "provenance": [{
            "field": "payment_image", "source": "current_user_turn",
            "evidence": os.path.basename(image_path), "reference_id": registration_id,
        }, {
            "field": "registration_id", "source": "world_fact",
            "evidence": f"active event registration {registration_id}",
            "reference_id": registration_id,
        }],
    }
    frame = {
        "source": "system_event_payment_media", "schema_valid": True,
        "turn_type": "request",
        "intent": {"domain": "event_registration", "operation": "register_event_payment"},
        "targets": [act["target"]], "temporal": act["temporal"],
        "requested_changes": [], "requested_facts": [],
        "commitment": act["commitment"],
        "context_relation": {
            "type": "references_previous", "question_id": None,
            "references_previous_user_turn": False, "references_agent_offer": True,
            "answers_pending_question": False,
        },
        "acts": [act],
    }
    clean = dict(perception or {})
    clean["entities"] = {
        **dict(clean.get("entities") or {}), "event_id": event_id,
        "event_name": active.get("event_name"), "event_date": active.get("event_date"),
        "registration_id": registration_id,
    }
    clean["semantic_frame"] = _agent_v2_normalize_semantic_frame(
        {**clean, "semantic_frame": frame}, world, mensaje
    )
    clean["semantic_effect_verification"] = {
        "status": "verified", "mode": "trusted_system_event",
        "write_authorizations": [{
            "act_id": act["act_id"], "authorized": True,
            "evidence_type": "current_user_turn_media",
        }],
    }
    clean["payment_media_grounded"] = True
    clean["execution_contract"] = _agent_v2_build_execution_contract(clean, world)
    return clean


_planificar_agent_v2_event_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    operations = _event_registration_operations(perception)
    if not operations:
        return await _planificar_agent_v2_event_base(
            world, perception, goals, observations, offline_mode, learning_policy
        )
    values = _event_registration_semantic_values(perception, world)
    event = _event_registration_find_event(values)
    progress = _agent_v2_goal_progress(goals, observations)

    if "choose_event_payment_method" in operations:
        matches = event_registration.list_event_registrations_for_phone(
            ((world.get("facts") or {}).get("cliente") or {}).get("telefono"),
            statuses={"pending_payment"},
        )
        values_registration_id = str(values.get("registration_id") or "").strip()
        if values_registration_id:
            matches = [
                item for item in matches
                if str((item.get("registration") or {}).get("registration_id") or "").strip()
                == values_registration_id
            ]
        matches = [
            item for item in matches
            if (_monto_a_int((item.get("registration") or {}).get("paid_amount")) or 0) > 0
            and (_monto_a_int((item.get("registration") or {}).get("remaining_amount")) or 0) > 0
        ]
        if len(matches) != 1:
            return {
                "steps": [{
                    "tool": "solicitar_dato",
                    "args": {
                        "campo": "inscripcion_evento",
                        "opciones": [
                            f"{item['event'].get('name')} — "
                            f"{event_registration.format_event_date(item['event'].get('date'))} — "
                            f"{item['registration'].get('team_name')}"
                            for item in matches
                        ],
                        "motivo": "necesito identificar qué inscripción tendrá el saldo en efectivo",
                    },
                    "reason": "destino de saldo en efectivo ambiguo",
                    "replan_after": False,
                }],
                "done_if": "inscripción inequívoca",
                "reason": "event cash payment targeting",
                "goal_progress": progress,
            }
        match = matches[0]
        return {
            "steps": [{
                "tool": "registrar_saldo_efectivo_inscripcion_evento",
                "args": {
                    "event_id": match["event"].get("event_id"),
                    "registration_id": match["registration"].get("registration_id"),
                },
                "reason": "usuario eligió efectivo para el saldo real de la inscripción",
                "replan_after": False,
            }],
            "done_if": "método de pago persistido sin confirmar dinero no recibido",
            "reason": "event mixed payment method",
            "goal_progress": progress,
        }

    if "register_event_payment" in operations:
        matches = event_registration.list_event_registrations_for_phone(
            ((world.get("facts") or {}).get("cliente") or {}).get("telefono"),
            statuses={"pending_payment", "expired"},
        )
        if values.get("registration_id"):
            matches = [
                item for item in matches
                if item["registration"].get("registration_id") == values["registration_id"]
            ]
        if len(matches) != 1:
            return {
                "steps": [{
                    "tool": "solicitar_dato",
                    "args": {
                        "campo": "inscripcion_evento", "opciones": [
                            f"{item['event'].get('name')} — {event_registration.format_event_date(item['event'].get('date'))} — {item['registration'].get('team_name')}"
                            for item in matches
                        ],
                        "motivo": "necesito identificar a qué inscripción corresponde el comprobante",
                    },
                    "reason": "destino de pago ambiguo", "replan_after": False,
                }],
                "done_if": "inscripción de destino inequívoca", "reason": "payment targeting",
                "goal_progress": progress,
            }
        match = matches[0]
        return {
            "steps": [{
                "tool": "registrar_pago_inscripcion_evento",
                "args": {
                    "event_id": match["event"].get("event_id"),
                    "registration_id": match["registration"].get("registration_id"),
                },
                "reason": "comprobante dirigido a inscripción real", "replan_after": False,
            }],
            "done_if": "pago aplicado o revisión humana registrada", "reason": "event payment",
            "goal_progress": progress,
        }

    candidates = event_registration.resolve_business_events(
        name=values.get("event_name"), event_date=values.get("event_date")
    )
    if event is None:
        return {
            "steps": [{
                "tool": "listar_eventos",
                "args": {
                    "event_name": values.get("event_name"),
                    "event_date": values.get("event_date"),
                    "for_registration": "register_event" in operations,
                },
                "reason": "identificar edición real del torneo", "replan_after": False,
            }],
            "done_if": "evento identificado o ausencia informada", "reason": "event selection",
            "goal_progress": progress,
        }

    if "query_event" in operations and "register_event" not in operations:
        return {
            "steps": [{
                "tool": "consultar_evento",
                "args": {"event_id": event.get("event_id")},
                "reason": "consulta factual del torneo", "replan_after": False,
            }],
            "done_if": "información del evento observada", "reason": "event query",
            "goal_progress": progress,
        }

    capacity_obs = next((
        obs for obs in reversed(observations or [])
        if obs.get("tool") == "consultar_cupos_evento"
        and (obs.get("data") or {}).get("event_id") == event.get("event_id")
    ), None)
    if capacity_obs is None:
        return {
            "steps": [{
                "tool": "consultar_cupos_evento",
                "args": {"event_id": event.get("event_id")},
                "reason": "Capacity Guard obligatorio antes de pedir el equipo",
                "replan_after": True,
            }],
            "done_if": "capacity verificada", "reason": "capacity-first registration",
            "goal_progress": progress,
        }
    if bool((capacity_obs.get("data") or {}).get("is_full")):
        return {
            "steps": [], "done_if": "torneo lleno informado sin pedir team_name",
            "reason": "event full terminal", "goal_progress": progress,
        }

    team_name = normalizar_valor_nullable(values.get("team_name"))
    if not team_name:
        return {
            "steps": [{
                "tool": "solicitar_dato",
                "args": {
                    "campo": "team_name", "opciones": [],
                    "motivo": "falta el nombre del equipo",
                    "event_id": event.get("event_id"), "event_name": event.get("name"),
                    "event_date": event.get("date"),
                },
                "reason": "capacity disponible; recién ahora pedir equipo", "replan_after": False,
            }],
            "done_if": "team_name conocido", "reason": "event team pending",
            "goal_progress": progress,
        }
    return {
        "steps": [{
            "tool": "crear_hold_inscripcion_evento",
            "args": {"event_id": event.get("event_id"), "team_name": team_name},
            "reason": "revalidar capacity y crear hold atómico", "replan_after": False,
        }],
        "done_if": "hold persistido o full factual", "reason": "event registration commit",
        "goal_progress": progress,
    }


_validar_tool_agent_v2_event_base = validar_tool_agent_v2


def validar_tool_agent_v2(
    tool: str, args: Dict, world: Dict, perception: Dict, goals: Dict,
    image_path: str = "",
) -> Dict[str, Any]:
    event_tools = {
        "listar_eventos", "consultar_evento", "consultar_cupos_evento",
        "crear_hold_inscripcion_evento", "obtener_inscripcion_evento",
        "registrar_pago_inscripcion_evento", "registrar_saldo_efectivo_inscripcion_evento",
        "cancelar_inscripcion_evento",
    }
    if tool not in event_tools:
        return _validar_tool_agent_v2_event_base(
            tool, args, world, perception, goals, image_path
        )
    contract = (perception or {}).get("execution_contract") or {}
    if not contract.get("authoritative") or tool not in set(contract.get("allowed_tools") or []):
        return {"ok": False, "reason": "tool_fuera_de_execution_contract", "fatal": True}
    clean = dict(args or {})
    event = event_registration.get_business_event(event_id=clean.get("event_id")) if clean.get("event_id") else None
    if tool in {
        "consultar_evento", "consultar_cupos_evento", "crear_hold_inscripcion_evento",
        "registrar_pago_inscripcion_evento", "registrar_saldo_efectivo_inscripcion_evento",
        "cancelar_inscripcion_evento",
    } and not event:
        return {"ok": False, "reason": "event_not_found", "fatal": False}
    if tool == "crear_hold_inscripcion_evento" and not normalizar_valor_nullable(clean.get("team_name")):
        return {"ok": False, "reason": "missing_team_name", "fatal": False, "missing": ["team_name"]}
    if tool == "registrar_pago_inscripcion_evento":
        if not clean.get("registration_id"):
            return {"ok": False, "reason": "registration_not_found", "fatal": False}
        if not image_path:
            return {"ok": False, "reason": "missing_payment_image", "fatal": False, "missing": ["comprobante"]}
    if tool == "registrar_saldo_efectivo_inscripcion_evento":
        if not clean.get("registration_id"):
            return {"ok": False, "reason": "registration_not_found", "fatal": False}
        match = event_registration.get_event_registration(
            registration_id=clean.get("registration_id")
        )
        registration = dict((match or {}).get("registration") or {})
        if not match or str((match.get("event") or {}).get("event_id") or "") != str(event.get("event_id") or ""):
            return {"ok": False, "reason": "registration_not_found", "fatal": False}
        if str(registration.get("status") or "") != "pending_payment":
            return {"ok": False, "reason": "registration_not_pending_payment", "fatal": False}
        if (_monto_a_int(registration.get("paid_amount")) or 0) <= 0 or (_monto_a_int(registration.get("remaining_amount")) or 0) <= 0:
            return {"ok": False, "reason": "registration_has_no_partial_balance", "fatal": False}
    return {"ok": True, "args": clean}


def _event_registration_observation(tool: str, result: Dict[str, Any]) -> Dict[str, Any]:
    ok = bool(result.get("ok"))
    status = "success" if ok else (
        "needs_human_review" if result.get("requires_human_review")
        else "unavailable" if result.get("is_full") or result.get("reason") == "event_full"
        else "needs_user_input" if result.get("reason") in {"event_ambiguous", "no_active_events"}
        else "rejected"
    )
    extra = {}
    if status == "needs_user_input":
        extra["missing"] = [result.get("field") or "event_selection"]
        extra["options"] = list(result.get("options") or [])
    return _agent_v2_observation(tool, ok, status, result, **extra)


_ejecutar_tool_agent_v2_event_base = ejecutar_tool_agent_v2
_event_registration_original_ejecutar_tool_agent_v2 = ejecutar_tool_agent_v2


async def ejecutar_tool_agent_v2(
    tool: str, args: Dict, world: Dict, perception: Dict, goals: Dict,
    telefono: str, prospecto: Dict, user_messages: List[str], page=None,
    image_path: str = "",
) -> Dict[str, Any]:
    if tool not in {
        "listar_eventos", "consultar_evento", "consultar_cupos_evento",
        "crear_hold_inscripcion_evento", "obtener_inscripcion_evento",
        "registrar_pago_inscripcion_evento", "registrar_saldo_efectivo_inscripcion_evento",
        "cancelar_inscripcion_evento",
    }:
        return await _ejecutar_tool_agent_v2_event_base(
            tool, args, world, perception, goals, telefono, prospecto,
            user_messages, page=page, image_path=image_path,
        )
    try:
        if tool == "listar_eventos":
            events = event_registration.resolve_business_events(
                name=args.get("event_name"), event_date=args.get("event_date")
            )
            if not events:
                case = registrar_caso_humano(
                    "event_registration_no_active_event", "\n".join(user_messages or []),
                    telefono, prospecto, reason="sin torneo activo compatible",
                    source="event_registration",
                )
                return _event_registration_observation(tool, {
                    "ok": False, "reason": "no_active_events", "field": "event_selection",
                    "options": [], "human_case_id": case.get("case_id"),
                })
            summaries = []
            for event in events:
                summaries.append({
                    "event": event,
                    "capacity_state": event_registration.get_event_capacity_state(event),
                })
            if args.get("for_registration") and len(summaries) > 1:
                return _event_registration_observation(tool, {
                    "ok": False, "reason": "event_ambiguous", "field": "event_selection",
                    "events": summaries,
                    "options": [
                        f"{item['event'].get('name')} — {event_registration.format_event_date(item['event'].get('date'))}"
                        for item in summaries
                    ],
                })
            return _event_registration_observation(tool, {"ok": True, "events": summaries})

        event = event_registration.get_business_event(event_id=args.get("event_id"))
        if tool in {"consultar_evento", "consultar_cupos_evento"}:
            state = event_registration.get_event_capacity_state(event)
            return _event_registration_observation(tool, {
                "ok": True, "event": event, "event_id": event.get("event_id"), **state,
            })
        if tool == "crear_hold_inscripcion_evento":
            result = event_registration.create_event_registration_hold(
                event, args.get("team_name"),
                (prospecto or {}).get("nombre") or (prospecto or {}).get("negocio") or "",
                normalize_phone(telefono or "") or telefono,
            )
            if result.get("ok"):
                registration_status = str(
                    (result.get("registration") or {}).get("status") or ""
                ).strip().casefold()
                metric_name = (
                    "event_registration_hold_created"
                    if not result.get("idempotent")
                    and registration_status == "pending_payment"
                    else "event_registration_existing_reused"
                )
                registrar_metrica_operativa(metric_name, {
                    "event_id": event.get("event_id"),
                    "registration_id": result["registration"].get("registration_id"),
                    "status": registration_status,
                    "idempotent": bool(result.get("idempotent")),
                })
            else:
                registrar_metrica_operativa("event_registration_capacity_rejected", {
                    "event_id": event.get("event_id"), **dict(result.get("capacity_state") or {}),
                })
            return _event_registration_observation(tool, result)
        if tool == "obtener_inscripcion_evento":
            match = event_registration.get_event_registration(
                registration_id=args.get("registration_id"), phone=telefono,
                statuses={"pending_payment", "expired", "confirmed"},
            )
            return _event_registration_observation(tool, {
                "ok": bool(match), "reason": "registration_not_found" if not match else "",
                **(match or {}),
            })
        if tool == "cancelar_inscripcion_evento":
            return _event_registration_observation(
                tool, event_registration.cancel_event_registration(event, args.get("registration_id"))
            )
        if tool == "registrar_saldo_efectivo_inscripcion_evento":
            result = _event_registration_mark_remaining_cash(
                event,
                args.get("registration_id"),
            )
            if result.get("ok"):
                registrar_metrica_operativa(
                    "event_registration_cash_balance_selected",
                    {
                        "event_id": event.get("event_id"),
                        "registration_id": args.get("registration_id"),
                        "remaining_amount": result.get("remaining_amount"),
                    },
                )
            return _event_registration_observation(tool, result)
        if tool == "registrar_pago_inscripcion_evento":
            match = event_registration.get_event_registration(
                registration_id=args.get("registration_id")
            )
            if not match or match["event"].get("event_id") != event.get("event_id"):
                return _event_registration_observation(tool, {"ok": False, "reason": "registration_not_found"})
            registration = match["registration"]
            required = int(float(registration.get("remaining_amount") or registration.get("required_payment") or 0))
            receipt = analizar_comprobante_senia(image_path, required)
            amount = _monto_a_int(receipt.get("monto_detectado"))
            confidence = float(receipt.get("confianza") or 0.0)
            if not receipt.get("es_comprobante") or not receipt.get("monto_valido") or not amount or confidence < AGENT_V2_PAYMENT_MIN_CONFIDENCE:
                return _event_registration_observation(tool, {
                    "ok": False, "reason": "receipt_not_reliably_validated",
                    "requires_human_review": True, "receipt": receipt,
                    "event": event, "registration": registration,
                })
            receipt_row = {
                "fecha": event.get("date"), "hora": "EVENT",
                "cancha": event.get("event_id"),
            }
            duplicate = registrar_comprobante_usado(
                receipt, receipt_row, telefono,
                str((prospecto or {}).get("nombre") or registration.get("contact_name") or ""),
                estado="confirmando",
            )
            if duplicate:
                registrar_metrica_operativa("event_registration_duplicate_blocked", {
                    "registration_id": registration.get("registration_id"),
                })
                return _event_registration_observation(tool, {
                    "ok": False, "reason": "receipt_already_used", "duplicate": duplicate,
                    "event": event, "registration": registration,
                })
            result = event_registration.register_event_payment(
                event, registration.get("registration_id"), amount,
                receipt_fingerprint="|".join(_receipt_fingerprints(receipt)),
            )
            result["receipt"] = receipt
            if result.get("reason") == "late_payment_event_full":
                actualizar_estado_comprobante_usado(receipt, "revision_humana", "pago_tardio_sin_cupo")
                case = registrar_caso_humano(
                    "event_registration_late_payment_full", "\n".join(user_messages or []),
                    telefono, prospecto,
                    reason=f"pago recibido sin cupo para {event.get('name')} {event.get('date')}",
                    source="event_registration",
                )
                result["human_case_id"] = case.get("case_id")
                return _event_registration_observation(tool, result)
            if not result.get("ok"):
                actualizar_estado_comprobante_usado(receipt, "fallido", result.get("reason") or "event_payment_failed")
                return _event_registration_observation(tool, result)
            registrar_comprobante_usado(
                receipt, receipt_row, telefono,
                str((prospecto or {}).get("nombre") or registration.get("contact_name") or ""),
                estado="pagado" if result.get("payment_complete") else "parcial",
            )
            registrar_metrica_operativa(
                "event_registration_confirmed" if result.get("payment_complete") else "event_registration_partial_payment",
                {"event_id": event.get("event_id"), "registration_id": registration.get("registration_id")},
            )
            return _event_registration_observation(tool, result)
    except event_registration.EventRegistrationError as exc:
        return _event_registration_observation(tool, exc.as_dict())


_event_ejecutar_tool_agent_v2_adapter = ejecutar_tool_agent_v2


_aplicar_observation_agent_v2_event_base = aplicar_observation_agent_v2
_event_registration_original_aplicar_observation_agent_v2 = aplicar_observation_agent_v2


def aplicar_observation_agent_v2(
    telefono: str, observation: Dict, world: Dict,
    perception: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    state = _aplicar_observation_agent_v2_event_base(
        telefono, observation, world, perception
    )
    tool = observation.get("tool")
    data = observation.get("data") or {}
    if tool == "solicitar_dato" and data.get("field") == "team_name":
        draft = {
            "event_id": data.get("event_id"), "event_name": data.get("event_name"),
            "event_date": data.get("event_date"), "team_name": None,
        }
        update_conversation_state(
            telefono, event_registration={"draft": draft, "active_registration": None}
        )
        agent_v2_reduce(telefono, {"type": "SET_OPEN_QUESTION", "payload": {
            "field": "team_name", "options": [], "goal_context": ["inscribir_equipo_evento"],
            "event_id": draft["event_id"], "event_name": draft["event_name"],
            "event_date": draft["event_date"], "source": "event_capacity_verified",
            "source_message": (world or {}).get("message"),
        }})
    elif tool == "crear_hold_inscripcion_evento" and data.get("ok"):
        registration = dict(data.get("registration") or {})
        event = dict(data.get("event") or {})
        update_conversation_state(telefono, event_registration={
            "draft": {
                "event_id": event.get("event_id"), "event_name": event.get("name"),
                "event_date": event.get("date"), "team_name": registration.get("team_name"),
            },
            "active_registration": registration,
        })
        agent_v2_reduce(telefono, {"type": "CLEAR_OPEN_QUESTION", "payload": {"field": "team_name"}})
    elif tool in {
        "registrar_pago_inscripcion_evento",
        "registrar_saldo_efectivo_inscripcion_evento",
    } and data.get("ok"):
        update_conversation_state(telefono, event_registration={
            "draft": {
                "event_id": (data.get("event") or {}).get("event_id"),
                "event_name": (data.get("event") or {}).get("name"),
                "event_date": (data.get("event") or {}).get("date"),
                "team_name": (data.get("registration") or {}).get("team_name"),
            },
            "active_registration": data.get("registration"),
        })
    return state


_event_aplicar_observation_agent_v2_adapter = aplicar_observation_agent_v2


def build_agent_v2_event_registration_message(observations: List[Dict[str, Any]]) -> str:
    event_obs = next((
        obs for obs in reversed(observations or [])
        if obs.get("tool") in {
            "listar_eventos", "consultar_evento", "consultar_cupos_evento",
            "crear_hold_inscripcion_evento", "obtener_inscripcion_evento",
            "registrar_pago_inscripcion_evento", "registrar_saldo_efectivo_inscripcion_evento",
        }
    ), None)
    if not event_obs:
        return ""
    data = event_obs.get("data") or {}
    tool = event_obs.get("tool")
    if data.get("reason") == "no_active_events":
        return "En este momento no tengo un torneo activo cargado para gestionar automáticamente. Voy a dejar tu consulta al encargado."
    if data.get("reason") == "event_ambiguous":
        options = data.get("options") or []
        return "Hay más de una edición disponible. ¿A cuál querés inscribir el equipo?\n\n" + "\n".join(f"• {item}" for item in options)
    event = data.get("event") or {}
    if (
        (tool == "consultar_cupos_evento" and data.get("is_full"))
        or data.get("reason") == "event_full"
    ):
        name = event.get("name") or "El torneo"
        registrar_metrica_operativa("event_registration_full_response", {"event_id": event.get("event_id")})
        return f"{name} ya llegó al maximo de equipos, nos vemos en la próxima!"
    if tool == "listar_eventos" and data.get("events"):
        parts = []
        for item in data["events"]:
            ev = item.get("event") or {}
            state = item.get("capacity_state") or {}
            availability = "🚫 No quedan lugares disponibles." if state.get("is_full") else f"✅ Lugares disponibles: {state.get('available')}"
            parts.append(
                f"🏆 {ev.get('name')}\n📅 Fecha: {event_registration.format_event_date(ev.get('date'))}\n"
                f"💰 Inscripción: {_fmt_event_money(ev.get('registration_price'))} por equipo\n"
                f"🏅 Premio: {_fmt_event_prize(ev.get('prize'))}\n"
                f"👥 Máximo: {ev.get('capacity')} equipos\n{availability}"
            )
        return "\n\n".join(parts)
    if tool == "consultar_evento" and event:
        availability = "🚫 No quedan lugares disponibles." if data.get("is_full") else f"✅ Lugares disponibles: {data.get('available')}"
        return (
            f"🏆 {event.get('name')}\n"
            f"📅 Fecha: {event_registration.format_event_date(event.get('date'))}\n"
            f"💰 Inscripción: {_fmt_event_money(event.get('registration_price'))} por equipo\n"
            f"🏅 Premio: {_fmt_event_prize(event.get('prize'))}\n"
            f"👥 Máximo: {event.get('capacity')} equipos\n"
            f"{availability}"
        )
    missing_team = next((
        obs for obs in reversed(observations or [])
        if obs.get("tool") == "solicitar_dato"
        and (obs.get("data") or {}).get("field") == "team_name"
    ), None)
    if missing_team:
        md = missing_team.get("data") or {}
        # La Observation de capacidad es autoridad factual y funciona como
        # respaldo para estados antiguos o adapters que no hayan propagado
        # todavía el contexto adicional de solicitar_dato.
        event_name = md.get("event_name") or event.get("name") or "el torneo"
        event_date = md.get("event_date") or event.get("date")
        date_suffix = (
            f" del {event_registration.format_event_date(event_date)}"
            if event_date
            else ""
        )
        return (
            f"🏆 Dale. Para inscribirte en {event_name}{date_suffix}, "
            "¿cuál es el nombre del equipo?"
        )
    if tool == "crear_hold_inscripcion_evento" and data.get("ok"):
        registration = data.get("registration") or {}
        registration_status = str(
            registration.get("status") or ""
        ).strip().casefold()
        if registration_status == "confirmed":
            remaining = _monto_a_int(registration.get("remaining_amount")) or 0
            cash_pending = bool(
                remaining > 0
                and str(registration.get("payment_method") or "").strip().casefold()
                == "transferencia+efectivo"
            )
            balance_line = (
                f"\n💵 Saldo en efectivo pendiente: {_fmt_event_money(remaining)}"
                if cash_pending
                else ""
            )
            return (
                "✅ *EQUIPO YA INSCRIPTO*\n\n"
                f"🏆 {event.get('name')}\n"
                f"📅 Fecha: {event_registration.format_event_date(event.get('date'))}\n"
                f"⚽ Equipo: {registration.get('team_name')}\n"
                "👥 El cupo ya figura confirmado."
                f"{balance_line}\n\n"
                "No generé una inscripción duplicada ni un nuevo vencimiento."
            )
        alias = event.get("payment_alias") or PAYMENT_ALIAS
        return (
            f"🏆 *INSCRIPCIÓN — {str(event.get('name') or '').upper()}*\n\n"
            f"📅 Fecha: {event_registration.format_event_date(event.get('date'))}\n"
            f"⚽ Equipo: {registration.get('team_name')}\n"
            f"💰 Seña de inscripción: {_fmt_event_money(registration.get('required_payment'))}\n"
            f"💳 Alias: {alias}\n\n"
            f"⏳ Te guardo 1 cupo durante {event_registration.EVENT_REGISTRATION_HOLD_MINUTES} minutos.\n\n"
            "Para confirmar la inscripción, enviame el comprobante de la transferencia."
        )
    if tool == "registrar_pago_inscripcion_evento":
        registration = data.get("registration") or {}
        if data.get("reason") == "receipt_already_used":
            return "Ese comprobante ya fue utilizado. Enviame el comprobante nuevo para continuar."
        if data.get("reason") == "late_payment_event_full":
            return "Recibí el comprobante, pero el torneo ya no tiene cupos. No confirmé un equipo extra y dejé el pago al encargado para resolverlo."
        if data.get("requires_human_review"):
            return "Recibí el comprobante, pero no lo pude validar con seguridad. No confirmé la inscripción y lo dejé al encargado para revisión."
        if data.get("ok") and not data.get("payment_complete"):
            remaining = _monto_a_int(registration.get("remaining_amount")) or 0
            return (
                "✅ *PAGO PARCIAL REGISTRADO — TORNEO*\n\n"
                f"🏆 {event.get('name')}\n"
                f"⚽ Equipo: {registration.get('team_name')}\n"
                f"💳 Recibido ahora: {_fmt_event_money(data.get('payment_received'))}\n"
                f"💵 Pagado acumulado: {_fmt_event_money(registration.get('paid_amount'))}\n"
                f"💸 Saldo pendiente: {_fmt_event_money(remaining)}\n\n"
                f"Podés completar {_fmt_event_money(remaining)} con otra transferencia, incluso desde otra cuenta. "
                "Si preferís pagar la diferencia en efectivo, decime y dejo el cupo firme con ese importe anotado como pendiente en efectivo.\n\n"
                "⏳ Mientras tanto mantengo tu cupo reservado."
            )
        if data.get("ok") and data.get("payment_complete"):
            return (
                "✅ *INSCRIPCIÓN CONFIRMADA*\n\n"
                f"🏆 {event.get('name')}\n"
                f"📅 Fecha: {event_registration.format_event_date(event.get('date'))}\n"
                f"⚽ Equipo: {registration.get('team_name')}\n"
                f"💰 Seña recibida: {_fmt_event_money(registration.get('paid_amount'))}\n"
                "👥 Cupo confirmado\n\n"
                "¡Listo! Tu equipo quedó inscripto en el torneo."
            )
    if tool == "registrar_saldo_efectivo_inscripcion_evento" and data.get("ok"):
        registration = data.get("registration") or {}
        event = data.get("event") or {}
        return (
            "✅ *INSCRIPCIÓN CONFIRMADA — PAGO MIXTO*\n\n"
            f"🏆 {event.get('name')}\n"
            f"📅 Fecha: {event_registration.format_event_date(event.get('date'))}\n"
            f"⚽ Equipo: {registration.get('team_name')}\n"
            f"💳 Transferido: {_fmt_event_money(registration.get('paid_amount'))}\n"
            f"💵 A pagar en efectivo: {_fmt_event_money(registration.get('remaining_amount'))}\n"
            "👥 Cupo confirmado\n\n"
            "¡Listo! Tu equipo ya quedó inscripto en el torneo. "
            "El saldo en efectivo queda pendiente hasta que el encargado registre que lo recibió."
        )
    return ""


_componer_respuesta_agent_v2_event_base = None


async def componer_respuesta_agent_v2(
    mensaje: str, world: Dict, perception: Dict, goals: Dict,
    observations: List[Dict], status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> str:
    event_message = build_agent_v2_event_registration_message(observations)
    if event_message:
        return event_message
    return await _componer_respuesta_agent_v2_event_base(
        mensaje, world, perception, goals, observations, status, learning_policy
    )


_event_componer_respuesta_agent_v2_adapter = componer_respuesta_agent_v2


_agent_v2_fallback_response_event_base = None


def _agent_v2_fallback_response(
    goals: Dict, observations: List[Dict], world: Dict, perception: Dict = None,
) -> str:
    event_message = build_agent_v2_event_registration_message(observations)
    return event_message or _agent_v2_fallback_response_event_base(
        goals, observations, world, perception
    )


