def _event_registration_csv_attachment(event: Dict[str, Any]) -> str:
    persisted = str((event or {}).get("registrations_csv_path") or "")
    path = os.path.abspath(
        persisted if os.path.isabs(persisted)
        else os.path.join(str(event_registration.BASE_DIR), persisted)
    )
    return path


def _discard_pending_event_registration_alerts_for_registration(
    registration_id: str,
) -> int:
    """Evita que un alerta de HOLD viejo llegue después de la confirmación."""
    registration_id = str(registration_id or "").strip()
    if not registration_id:
        return 0
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.get("admin_alert_queue") or {}
    discarded = 0
    for delivery_id, item in list(queue.items()):
        if not isinstance(item, dict):
            continue
        context = item.get("context") or {}
        if (
            str(item.get("category") or "") == "event_registration_pending"
            and str(context.get("registration_id") or "").strip() == registration_id
        ):
            queue.pop(delivery_id, None)
            discarded += 1
    if discarded:
        state["admin_alert_queue"] = queue
        state["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
        _json_write(PROACTIVE_STATE_FILE, state)
        print(
            "   🧹 [EVENT ADMIN ALERT] descarté "
            f"{discarded} alerta(s) pending obsoleta(s) para {registration_id}"
        )
    return discarded


def build_mixed_cash_confirmed_event_registration_admin_alert(
    event: Dict[str, Any],
    registration: Dict[str, Any],
    capacity_state: Dict[str, Any],
) -> str:
    """Alerta factual: cupo confirmado, efectivo aún pendiente."""
    admin_id = _event_registration_admin_public_id(
        registration.get("registration_id"), create=True
    )
    display_id = admin_id or str(registration.get("registration_id") or "").strip()
    return (
        "✅ *INSCRIPCIÓN CONFIRMADA — PAGO MIXTO*\n\n"
        f"🏆 {event.get('name')}\n"
        f"📅 {event_registration.format_event_date(event.get('date'))}\n"
        f"⚽ Equipo: {registration.get('team_name')}\n"
        f"👤 Contacto: {registration.get('contact_name') or 'sin nombre'}\n"
        f"📱 {registration.get('phone') or 'sin teléfono'}\n"
        f"🆔 ID {display_id}\n\n"
        f"💳 Transferido y validado: {_fmt_event_money(registration.get('paid_amount'))}\n"
        f"💵 Efectivo pendiente: {_fmt_event_money(registration.get('remaining_amount'))}\n"
        f"💰 Inscripción total: {_fmt_event_money(registration.get('registration_price') or registration.get('required_payment'))}\n"
        "👥 *El cupo ya está confirmado.*\n"
        "El efectivo pendiente todavía NO está marcado como cobrado.\n\n"
        f"📊 Confirmados: {capacity_state.get('confirmed', 0)} | "
        f"Holds: {capacity_state.get('active_holds', 0)} | "
        f"Disponibles: {capacity_state.get('available', 0)}"
    )


def enqueue_pending_event_registration_admin_alert(
    event: Dict[str, Any], registration: Dict[str, Any], capacity_state: Dict[str, Any],
) -> List[str]:
    if str(registration.get("status") or "").strip().casefold() != "pending_payment":
        print(
            "   🛡️ [EVENT ADMIN ALERT] omito pending para inscripción "
            f"status={registration.get('status') or 'desconocido'} "
            f"ID={registration.get('registration_id') or '-'}"
        )
        return []
    fingerprint = event_registration.event_registration_hold_fingerprint(registration)
    pending_alert_text = _event_registration_publicize_admin_alert_text(
        event_registration.build_pending_event_registration_admin_alert(
            event, registration, capacity_state
        ),
        registration,
    )
    ids = _enqueue_admin_alert_batch(
        pending_alert_text,
        category="event_registration_pending",
        dedupe_key=f"event_registration_pending:{registration.get('registration_id')}:{fingerprint}",
        attachment_path=_event_registration_csv_attachment(event),
        attachment_title=f"📎 Inscripciones — {event.get('name')} — {event_registration.format_event_date(event.get('date'))}",
        context={
            "context_kind": "event_registration_pending", "event_id": event.get("event_id"),
            "registration_id": registration.get("registration_id"), "phone": registration.get("phone"),
        },
    )
    registrar_metrica_operativa("event_registration_pending_alert_queued", {
        "registration_id": registration.get("registration_id"), "deliveries": len(ids),
    })
    return ids


def enqueue_confirmed_event_registration_admin_alert(
    event: Dict[str, Any], registration: Dict[str, Any], capacity_state: Dict[str, Any],
) -> List[str]:
    registration_id = str(registration.get("registration_id") or "").strip()
    _discard_pending_event_registration_alerts_for_registration(registration_id)
    fingerprint = event_registration.event_registration_confirmation_fingerprint(registration)
    mixed_cash_pending = bool(
        str(registration.get("payment_method") or "").strip().casefold()
        == "transferencia+efectivo"
        and (_monto_a_int(registration.get("remaining_amount")) or 0) > 0
    )
    alert_text = (
        build_mixed_cash_confirmed_event_registration_admin_alert(
            event, registration, capacity_state
        )
        if mixed_cash_pending
        else event_registration.build_confirmed_event_registration_admin_alert(
            event, registration, capacity_state
        )
    )
    alert_text = _event_registration_publicize_admin_alert_text(
        alert_text, registration
    )
    ids = _enqueue_admin_alert_batch(
        alert_text,
        category="event_registration_confirmed",
        dedupe_key=f"event_registration_confirmed:{registration_id}:{fingerprint}",
        attachment_path=_event_registration_csv_attachment(event),
        attachment_title=f"📎 Inscripciones — {event.get('name')} — {event_registration.format_event_date(event.get('date'))}",
        context={
            "context_kind": "event_registration_confirmed", "event_id": event.get("event_id"),
            "registration_id": registration_id, "phone": registration.get("phone"),
        },
    )
    registrar_metrica_operativa("event_registration_confirmed_alert_queued", {
        "registration_id": registration_id, "deliveries": len(ids),
        "mixed_cash_pending": mixed_cash_pending,
    })
    return ids


def reconcile_pending_event_registration_admin_alerts() -> Dict[str, int]:
    pending = confirmed = 0
    for item in event_registration.iter_alert_reconciliation_candidates():
        if item["category"] == "event_registration_pending":
            enqueue_pending_event_registration_admin_alert(
                item["event"], item["registration"], item["capacity_state"]
            )
            pending += 1
        else:
            enqueue_confirmed_event_registration_admin_alert(
                item["event"], item["registration"], item["capacity_state"]
            )
            confirmed += 1
    if pending or confirmed:
        registrar_metrica_operativa("event_registration_alert_rehydrated", {
            "pending": pending, "confirmed": confirmed,
        })
    return {"pending": pending, "confirmed": confirmed}


_ejecutar_notificaciones_post_respuesta_agent_v2_event_base = None


async def ejecutar_notificaciones_post_respuesta_agent_v2(
    page, agent_result: Dict[str, Any], telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
) -> Dict[str, int]:
    result = await _ejecutar_notificaciones_post_respuesta_agent_v2_event_base(
        page, agent_result, telefono, prospecto
    )
    queued = 0
    for observation in agent_result.get("observations") or []:
        data = observation.get("data") or {}
        event = data.get("event") or {}
        registration = data.get("registration") or {}
        capacity_state = data.get("capacity_state") or {}
        if observation.get("tool") == "crear_hold_inscripcion_evento" and observation.get("ok"):
            if str(registration.get("status") or "").strip().casefold() == "pending_payment":
                queued += len(enqueue_pending_event_registration_admin_alert(event, registration, capacity_state))
            else:
                print(
                    "   ♻️ [EVENT REGISTRATION IDEMPOTENT] "
                    f"status={registration.get('status') or 'desconocido'}; "
                    "no encolo alerta pending"
                )
        elif (
            observation.get("tool") == "registrar_pago_inscripcion_evento"
            and observation.get("ok") and data.get("payment_complete")
        ):
            queued += len(enqueue_confirmed_event_registration_admin_alert(event, registration, capacity_state))
        elif (
            observation.get("tool") == "registrar_saldo_efectivo_inscripcion_evento"
            and observation.get("ok") and data.get("registration_confirmed")
        ):
            queued += len(enqueue_confirmed_event_registration_admin_alert(event, registration, capacity_state))
    result["queued"] = int(result.get("queued") or 0) + queued
    return result


_event_ejecutar_notificaciones_post_respuesta_agent_v2_adapter = (
    ejecutar_notificaciones_post_respuesta_agent_v2
)


