def build_agent_v2_cash_selection_message(
    observation: Dict[str, Any],
) -> str:
    """
    Renderer determinista de registrar_pago_presencial.

    Si la operación convirtió una transferencia parcial +
    efectivo pendiente en un turno firme, esa situación
    tiene su propia plantilla y NO puede degradarse a la
    plantilla de "seña completa en efectivo".
    """
    data = (
        (observation or {}).get(
            "data"
        )
        or {}
    )

    existing = str(
        data.get(
            "respuesta"
        )
        or ""
    ).strip()

    booking_confirmed = bool(
        data.get(
            "booking_confirmed"
        )
    )

    payment_method = str(
        data.get(
            "payment_method"
        )
        or ""
    ).strip().casefold()

    # ==========================================================
    # PAGO MIXTO + TURNO FIRME
    # ==========================================================

    if (
        booking_confirmed
        and payment_method
        == "transferencia+efectivo"
    ):

        if existing:
            return existing

        reserva = (
            data.get("reserva")
            or {}
        )

        return (
            build_turno_firme_pago_mixto_message(
                reserva,
                _monto_a_int(
                    data.get(
                        "monto_transferido"
                    )
                )
                or 0,
                _monto_a_int(
                    data.get(
                        "monto_efectivo_pendiente"
                    )
                )
                or 0,
                _monto_a_int(
                    data.get(
                        "saldo_total"
                    )
                )
                or 0,
            )
        ).strip()

    # ==========================================================
    # PAGO PRESENCIAL NORMAL
    # ==========================================================

    return existing


def build_agent_v2_payment_confirmation_message(
    observation: Dict[str, Any],
) -> str:
    """
    Renderer DETERMINISTA del resultado de registrar_senia.

    Estados posibles:

        payment_complete=True
            -> la seña quedó completada.

        payment_complete=False
            -> fue un pago parcial acumulado.

    Nunca convierte un pago parcial en una seña completa.
    Nunca recalcula el monto desde lenguaje natural.
    Nunca usa GPT para redactar importes.
    """
    data = (
        (observation or {}).get("data")
        or {}
    )

    # ==========================================================
    # RESPUESTA PRODUCIDA POR LA TOOL
    # ==========================================================
    #
    # confirmar_senia_reserva_pendiente() ya distingue:
    #
    # completa:
    #   build_confirmacion_senia_registrada_message()
    #
    # parcial:
    #   build_pago_parcial_senia_message()
    #
    # Ésta es nuestra principal autoridad.
    # ==========================================================

    existing = str(
        data.get(
            "respuesta_confirmacion"
        )
        or ""
    ).strip()

    if existing:
        return existing

    reserva = (
        data.get("reserva")
        or {}
    )

    payment_complete = bool(
        data.get(
            "payment_complete"
        )
    )

    # ==========================================================
    # PAGO PARCIAL
    # ==========================================================

    if not payment_complete:

        monto_comprobante = (
            _monto_a_int(
                data.get(
                    "monto_comprobante"
                )
            )
        )

        if monto_comprobante is None:
            monto_comprobante = (
                _monto_a_int(
                    data.get(
                        "monto"
                    )
                )
            )

        if (
            isinstance(
                reserva,
                dict,
            )
            and reserva
            and monto_comprobante
            is not None
            and monto_comprobante > 0
        ):
            return (
                build_pago_parcial_senia_message(
                    reserva,
                    monto_comprobante,
                ).strip()
            )

        # No inventar números si la Observation quedó incompleta.
        return (
            "✅ Recibí el comprobante y registré un pago parcial.\n\n"
            "El turno continúa pendiente hasta completar la seña."
        )

    # ==========================================================
    # SEÑA COMPLETA
    # ==========================================================

    return (
        build_confirmacion_senia_registrada_message(
            reserva,
            data.get("dia") or "",
            data.get("hora") or "",
            data.get("cancha") or "",
        ).strip()
    )


def _agent_v2_successful_create_observation(
    observations: List[Dict],
) -> Optional[Dict[str, Any]]:
    """
    FINAL RESERVATION STATE CONTRACT.

    Si el mismo turno hace crear_reserva -> agregar_quincho, el Composer
    debe renderizar el estado FINAL posterior al último write, no la primera
    Observation de crear_reserva.
    """
    observations = list(observations or [])

    created_index = None
    created_obs = None
    for idx in range(len(observations) - 1, -1, -1):
        obs = observations[idx]
        if (
            obs.get("tool") == "crear_reserva"
            and obs.get("ok")
            and obs.get("status") == "success"
        ):
            created_index = idx
            created_obs = obs
            break

    if created_obs is None:
        return None

    final_obs = dict(created_obs)
    final_data = dict((created_obs.get("data") or {}))

    def _boolish(value) -> bool:
        if isinstance(value, bool):
            return value
        return str(value or "").strip().lower() in {
            "si", "sí", "true", "1", "yes", "y"
        }

    def _merge_verified_reservation(row: Dict[str, Any]) -> None:
        if not isinstance(row, dict) or not row:
            return

        field_map = {
            "dia": row.get("fecha") or row.get("dia"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha"),
            "duracion_horas": row.get("duracion_horas"),
            "precio_total": row.get("precio_total"),
            # Si una fila histórica no tiene precio_cancha_total explícito,
            # no pisamos el valor que ya vino de la Observation de creación.
            "precio_cancha_total": row.get("precio_cancha_total"),
            "senia_estado": row.get("senia_estado"),
            "senia_monto": row.get("senia_monto"),
            "monto_pendiente": row.get("monto_pendiente"),
            "quincho": row.get("quincho"),
            "quincho_hora_inicio": row.get("quincho_hora_inicio"),
            "quincho_duracion_horas": row.get("quincho_duracion_horas"),
            "quincho_precio_total": row.get("quincho_precio_total"),
        }
        for key, value in field_map.items():
            if value not in (None, ""):
                final_data[key] = value

        if "con_quincho" in row:
            final_data["con_quincho"] = _boolish(row.get("con_quincho"))

        final_data["reserva_verificada"] = dict(row)

    _merge_verified_reservation(final_data.get("reserva_verificada") or {})

    for obs in observations[(created_index + 1):]:
        if not obs.get("ok") or obs.get("status") != "success":
            continue

        tool = str(obs.get("tool") or "")
        data = obs.get("data") or {}

        if tool == "agregar_quincho":
            _merge_verified_reservation(data.get("reserva") or {})

            qname = data.get("quincho") or final_data.get("quincho") or ""
            qstart = (
                data.get("hora_inicio")
                or final_data.get("quincho_hora_inicio")
                or final_data.get("hora")
            )
            qdur = (
                data.get("duracion_horas")
                or final_data.get("quincho_duracion_horas")
                or final_data.get("duracion_horas")
            )
            qprice = (
                _monto_a_int(data.get("precio_quincho"))
                or _monto_a_int(final_data.get("quincho_precio_total"))
                or 0
            )
            total = (
                _monto_a_int(data.get("total"))
                or _monto_a_int(final_data.get("precio_total"))
                or 0
            )

            final_data["con_quincho"] = True
            final_data["quincho"] = qname
            final_data["quincho_hora_inicio"] = qstart
            final_data["quincho_duracion_horas"] = qdur
            final_data["quincho_precio_total"] = qprice

            if total:
                final_data["precio_total"] = total
                senia = (
                    _senia_guardada_o_configurada(final_data, total)
                    if str(final_data.get("senia_estado") or "").lower() == "pagada"
                    else _senia_para_total(total)
                )
                final_data["senia_monto"] = senia
                final_data["monto_pendiente"] = calcular_monto_pendiente(
                    total,
                    senia,
                )

        elif tool == "quitar_quincho":
            _merge_verified_reservation(data.get("reserva") or {})
            final_data["con_quincho"] = False
            final_data["quincho"] = ""
            final_data["quincho_hora_inicio"] = ""
            final_data["quincho_duracion_horas"] = None
            final_data["quincho_precio_total"] = 0

        elif tool == "reprogramar_reserva":
            for key in ("dia", "hora", "cancha"):
                if data.get(key) not in (None, ""):
                    final_data[key] = data.get(key)

    final_data["final_state_contract"] = True
    final_data["write_chain"] = [
        str(obs.get("tool") or "")
        for obs in observations[created_index:]
        if obs.get("ok") and obs.get("status") == "success"
    ]

    final_obs["data"] = final_data
    final_obs["verified_facts"] = {
        **dict(created_obs.get("verified_facts") or {}),
        "final_reservation_state": dict(final_data),
    }

    if len(final_data.get("write_chain") or []) > 1:
        print(
            f"   🧾 [AgentV2 FINAL RESERVATION STATE] "
            f"writes={final_data.get('write_chain')} "
            f"dia={final_data.get('dia')} hora={final_data.get('hora')} "
            f"cancha={final_data.get('cancha')} "
            f"quincho={bool(final_data.get('con_quincho'))} "
            f"total={_monto_a_int(final_data.get('precio_total'))}"
        )

    return final_obs


def _agent_v2_render_open_question(
    question: Dict[str, Any],
) -> str:

    q = (
        question
        or {}
    )

    field = q.get(
        "field"
    )

    options = list(
        q.get(
            "options"
        )
        or []
    )

    # =========================================================
    # CANCHA
    # =========================================================

    if (
        field == "cancha"
        and options
    ):

        return (
            f"¿Cuál preferís: "
            f"{' o '.join(str(x) for x in options)}?"
        )

    # =========================================================
    # HORA AMBIGUA
    # =========================================================

    if (
        field == "hora_aclaracion"
        and options
    ):

        return (
            build_hora_ambigua_message(
                options
            )
        )

    # =========================================================
    # HORA
    # =========================================================

    if field == "hora":

        if (
            q.get(
                "ux_mode"
            )
            == "duration_followup"
        ):

            return (
                "¿A qué hora te gustaría reservar?"
            )

        return (
            "¿Qué hora te gustaría reservar?"
            if q.get(
                "booking_choice"
            )
            else
            "¿Qué hora te sirve?"
        )

    # =========================================================
    # DÍA + HORA
    # =========================================================

    if (
        field
        == "dia_hora_reserva"
    ):

        return (
            "¿Qué día y hora te gustaría reservar?"
        )

    # =========================================================
    # CONFIRMAR SLOT
    # =========================================================

    if (
        field
        == "confirmar_slot"
    ):

        day = str(
            q.get(
                "dia"
            )
            or ""
        ).strip()

        hour = (
            normalizar_hora_detectada(
                q.get(
                    "hora"
                )
            )
        )

        if (
            day
            and hora_es_valida(
                hour
            )
        ):

            return (
                "Confirmame si querés reservar "
                f"el *{day} a las {hour}*."
            )

        return (
            "Confirmame si querés reservar este turno."
        )

    # =========================================================
    # REBOOK
    # =========================================================

    if (
        field
        == "released_booking_rebook"
    ):

        if (
            q.get(
                "offer_kind"
            )
            == "nearest_alternative"
        ):

            return (
                "¿Querés que te reserve esa alternativa?"
            )

        return (
            "¿Querés que vuelva a reservarlo?"
        )

    # =========================================================
    # ACLARACIÓN SEMÁNTICA
    # =========================================================

    if (
        field
        == "semantic_clarification"
    ):

        return (
            "No quiero asumir mal. "
            "¿Me lo aclarás con un poco más de detalle?"
        )

    # =========================================================
    # DÍA
    # =========================================================

    if (
        field
        == "dia"
    ):

        return (
            "¿Para qué día lo querés?"
        )

    # =========================================================
    # DURACIÓN
    # =========================================================

    if (
        field
        == "duracion_horas"
    ):

        if options:

            formatted = (
                " o ".join(
                    f"{float(x):g} "
                    f"hora{'s' if float(x) != 1 else ''}"

                    for x
                    in options
                )
            )

            return (
                f"Podés reservar {formatted}. "
                "¿Cuál te sirve?"
            )

        return (
            "¿Cuántas horas querés reservar?"
        )

    # =========================================================
    # ESTRUCTURA HORARIOS
    # =========================================================

    if (
        field
        == "estructura_horarios"
    ):

        return (
            "Entendí varias horas. "
            "¿Las querés seguidas como un bloque "
            "o como turnos separados?"
        )

    # =========================================================
    # DURACIÓN QUINCHO
    # =========================================================

    if (
        field
        == "quincho_duracion_horas"
    ):

        return (
            "¿Por cuántas horas querés el quincho?"
        )

    # =========================================================
    # COMPROBANTE
    # =========================================================

    if (
        field
        == "comprobante"
    ):

        monto = q.get(
            "senia_monto"
        )

        if (
            _monto_a_int(
                monto
            )
            is None
        ):

            monto = (
                _senia_para_total(
                    q.get(
                        "precio_total"
                    )
                    or calcular_precio_total(
                        DEFAULT_TURN_DURATION_HOURS
                    )
                )
            )

        return (
            "¿Podés mandarme el comprobante "
            f"de la seña de {_monto_humano(monto)} "
            f"al alias {PAYMENT_ALIAS}?"
        )

    # =========================================================
    # RESERVA ESPECÍFICA
    # =========================================================

    if (
        field
        == "reserva_especifica"
    ):

        rows = [
            item

            for item
            in options

            if isinstance(
                item,
                dict,
            )
        ]

        if not rows:

            return (
                "Tenés más de una reserva activa. "
                "¿Cuál querés modificar?"
            )

        lines = [
            "Tenés más de una reserva activa. "
            "¿Cuál querés modificar?"
        ]

        for (
            idx,
            item,
        ) in enumerate(
            rows[:6],
            1,
        ):

            day = str(
                item.get(
                    "dia"
                )
                or ""
            )

            hour = (
                formatear_hora_para_mensaje(
                    item.get(
                        "hora"
                    )
                )
            )

            court = str(
                item.get(
                    "cancha"
                )
                or ""
            )

            lines.append(
                f"{idx}. "
                f"{day} "
                f"{hour} "
                f"{court}".strip()
            )

        return "\n".join(
            lines
        )

    # =========================================================
    # WAITLIST
    # =========================================================

    if (
        field
        == "waitlist_offer"
    ):

        day = (
            q.get(
                "dia"
            )
            or "ese día"
        )

        hour = (
            formatear_hora_para_mensaje(
                q.get(
                    "hora"
                )
            )

            if q.get(
                "hora"
            )

            else "ese horario"
        )

        court = (
            f" en {q.get('cancha')}"

            if q.get(
                "cancha"
            )

            else ""
        )

        return (
            "Si querés, te aviso si se libera "
            f"{day} a las {hour}{court}. "
            "¿Te anoto en lista de espera?"
        )

    # =========================================================
    # HORARIOS MÚLTIPLES
    # =========================================================

    if (
        field
        == "horarios_multiples_alternativas"
    ):

        failures = [
            item

            for item
            in options

            if (
                isinstance(
                    item,
                    dict,
                )

                and not item.get(
                    "ok"
                )
            )
        ]

        if failures:

            details = []

            for item in failures[:4]:

                hour = (
                    formatear_hora_para_mensaje(
                        item.get(
                            "hora"
                        )
                    )
                )

                alternative = (
                    item.get(
                        "alternativa"
                    )
                    or {}
                )

                if alternative.get(
                    "hora"
                ):

                    details.append(
                        f"{hour} no está libre; "
                        f"alternativa {alternative.get('dia')} "
                        f"{formatear_hora_para_mensaje(alternative.get('hora'))}"
                    )

                else:

                    details.append(
                        f"{hour} no está libre"
                    )

            return (
                "No puedo confirmar todos los turnos "
                "sin hacer una reserva parcial. "
                + "; ".join(
                    details
                )
                + ". ¿Qué horarios querés cambiar?"
            )

        return (
            "Uno o más horarios del pedido "
            "no están disponibles. "
            "¿Qué horarios querés cambiar?"
        )

    # =========================================================
    # FALLBACK
    # =========================================================

    # V117: no existe fallback conversacional genérico. Si un campo no tiene
    # renderer determinista, el Composer grounded recibe el FactPack completo.
    return ""

def _agent_v2_verified_missing_input_response(
    observations: List[Dict[str, Any]],
    world: Optional[Dict[str, Any]] = None,
) -> str:
    """
    Renderiza una pregunta pendiente sin introducir un saludo
    por el estado inicial o por la ausencia de historial.

    El saludo requiere business_welcome=True explícito.
    """
    observations = [
        obs
        for obs in (observations or [])
        if isinstance(obs, dict)
    ]

    if not observations or not all(
        obs.get("tool") == "solicitar_dato"
        and obs.get("status") == "needs_user_input"
        for obs in observations
    ):
        return ""

    fields = {
        str(
            (obs.get("data") or {}).get("field") or ""
        ).strip()
        for obs in observations
    }
    fields.discard("")

    if len(fields) != 1:
        return ""

    field = next(iter(fields))

    if field == "dia_hora_reserva":
        explicit_welcome = any(
            (obs.get("data") or {}).get("business_welcome") is True
            for obs in observations
        )

        if explicit_welcome:
            return build_agent_v2_welcome_message(world or {})

        return "¿Qué día y hora te gustaría reservar?"

    return _agent_v2_render_open_question(
        observations[-1].get("data") or {}
    )


def _agent_v2_current_available_slot(perception: Dict, observations: List[Dict]) -> Optional[Dict]:
    """Un único slot READ verificado, incluso si el turno también contiene FAQs."""
    acts = _agent_v2_authoritative_semantic_acts(perception or {})
    if not any(a.get("operation") == "query_availability" for a in acts):
        return None
    if any(
        not str(a.get("operation") or "").startswith("query_")
        or (a.get("commitment") or {}).get("wants_write")
        for a in acts
    ):
        return None
    slots = {}
    for obs in observations or []:
        if obs.get("tool") != "consultar_disponibilidad":
            continue
        data = obs.get("data") or {}
        day = str(data.get("dia") or "").strip()
        hour = normalizar_hora_detectada(data.get("hora"))
        if (not obs.get("ok") or obs.get("status") not in {"success", "needs_user_input"}
                or not day or not hora_es_valida(hour) or not _agent_v2_exact_available_courts(data)):
            return None
        if data.get("booking_shape") in {"multiple_separate", "contiguous_block"}:
            return None
        slots[(day, hour)] = data
    return next(iter(slots.values())) if len(slots) == 1 else None


def _agent_v2_nba_candidates(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
) -> List[Dict[str, Any]]:
    """Genera acciones de conversación permitidas; no redacta ni inventa hechos."""
    candidates = []

    # Una acción operativa terminal ya cumplió el objetivo del usuario.
    terminal_tools = {
        "crear_reserva",
        "crear_reservas_multiples",
        "cancelar_reserva",
        "reprogramar_reserva",
        "registrar_senia",
        "registrar_pago_presencial",
        "anotarse_lista_espera",
        "solicitar_handoff_humano",
        "agregar_quincho",
        "quitar_quincho",
    }

    if any(
        obs.get("ok")
        and obs.get("tool") in terminal_tools
        for obs in (observations or [])
    ):
        return []

    # =========================================================
    # DURACIÓN FAQ → CONTINUIDAD LIMPIA
    # =========================================================
    policy_obs_early = (
        _agent_v2_policy_contract_observation(
            observations
        )
    )

    policy_contract_early = (
        (
            (policy_obs_early or {}).get("data")
            or {}
        ).get("policy_fact_contract")
        or {}
    )

    no_real_reservation_early = not bool(
        (world.get("facts") or {}).get(
            "reservas_reales"
        )
        or []
    )

    draft_early = (
        world.get("desires") or {}
    ).get(
        "booking_draft"
    ) or {}

    has_validated_slot_early = bool(
        draft_early.get("activo")
        and draft_early.get("dia")
        and draft_early.get("hora")
        and draft_early.get("cancha")
        and not draft_early.get("reservation_id")
    )

    if (
        policy_obs_early
        and policy_contract_early.get("type")
        == "duration_policy"
        and no_real_reservation_early
        and not has_validated_slot_early
    ):
        availability = (
            world.get("availability_context")
            or {}
        )

        # La pregunta de horario anterior puede haber sido suspendida como
        # context_only mientras respondíamos la FAQ de duración. Sigue siendo
        # la fuente verificada de los horarios que YA se mostraron al cliente.
        previous_hour_question = (
            _agent_v2_pending_question(
                world,
                "hora",
            )
            or {}
        )

        previous_options = (
            _agent_v2_dedupe_hours(
                previous_hour_question.get("options")
                or []
            )
        )

        known_day = (
            previous_hour_question.get("dia")
            or availability.get("dia")
            or availability.get("dia_resuelto")
        )

        requested_duration = None

        for item in (
            policy_contract_early.get(
                "requested_durations"
            )
            or []
        ):
            if not isinstance(
                item,
                dict,
            ):
                continue

            if not item.get(
                "allowed"
            ):
                continue

            try:
                requested_duration = round(
                    float(
                        item.get(
                            "hours"
                        )
                    ),
                    4,
                )

            except (
                TypeError,
                ValueError,
            ):
                requested_duration = None

            if requested_duration:
                break

        if requested_duration is None:
            try:
                requested_duration = float(
                    (
                        perception.get(
                            "entities"
                        )
                        or {}
                    ).get(
                        "duracion_horas"
                    )
                )

            except (
                TypeError,
                ValueError,
            ):
                requested_duration = None

        # Si ya conocemos el día por la disponibilidad
        # inmediatamente anterior, no volvemos a preguntar
        # día+hora ni repetimos la parrilla.
        #
        # Abrimos únicamente una decisión "hora" con las
        # opciones verificadas que ya vio el cliente.
        if known_day:
            return [
                {
                    "action": (
                        "ask_booking_datetime"
                    ),
                    "question": {
                        "field": "hora",

                        # Las opciones se conservan internamente
                        # para interpretar la respuesta.
                        # NO se muestran otra vez.
                        "options": (
                            previous_options
                        ),

                        "booking_choice": True,

                        # Activa redacción especial:
                        # "¿A qué hora te gustaría reservar?"
                        "ux_mode": (
                            "duration_followup"
                        ),

                        "dia": known_day,

                        "duracion_horas": (
                            requested_duration
                        ),

                        # Si dijo 2h, la próxima hora elegida
                        # representa un bloque continuo.
                        "booking_shape": (
                            "contiguous_block"
                            if requested_duration
                            else previous_hour_question.get(
                                "booking_shape"
                            )
                        ),

                        "requested_hours": [],

                        "goal_context": [
                            "buscar_turno",
                            "crear_reserva",
                        ],

                        "source": (
                            "next_best_action_current_turn"
                        ),

                        "replace_booking_questions": True,
                    },

                    "reason_code": (
                        "duration_policy_booking_bridge"
                    ),

                    "reason": (
                        "FAQ de duración resuelta; conservar el día "
                        "y pedir solo la hora sin repetir horarios "
                        "ya mostrados"
                    ),
                }
            ]

        # Si realmente no existe ningún día vigente,
        # recién ahí pedimos ambos.
        return [
            {
                "action": (
                    "ask_booking_datetime"
                ),

                "question": {
                    "field": (
                        "dia_hora_reserva"
                    ),

                    "options": [],

                    "booking_choice": True,

                    "dia": None,

                    "duracion_horas": (
                        requested_duration
                    ),

                    "booking_shape": (
                        "contiguous_block"
                        if requested_duration
                        else None
                    ),

                    "goal_context": [
                        "buscar_turno",
                        "crear_reserva",
                    ],

                    "source": (
                        "next_best_action_current_turn"
                    ),

                    "replace_booking_questions": True,
                },

                "reason_code": (
                    "duration_policy_booking_bridge"
                ),

                "reason": (
                    "FAQ de duración resuelta; "
                    "falta día vigente para continuar"
                ),
            }
        ]

    if _agent_v2_information_only_turn(
        perception
    ):
        return candidates

    # =========================================================
    # HOLD LIBERADO
    # =========================================================
    released_recheck = (
        _agent_v2_released_booking_recheck_data(
            perception,
            observations,
        )
    )

    if released_recheck:
        return [
            {
                "action": (
                    "confirm_released_booking"
                ),

                "question": {
                    "field": (
                        "released_booking_rebook"
                    ),

                    "options": [],

                    "booking_choice": True,

                    "dia": (
                        released_recheck.get(
                            "dia"
                        )
                    ),

                    "hora": (
                        released_recheck.get(
                            "hora"
                        )
                    ),

                    "cancha": (
                        released_recheck.get(
                            "cancha"
                        )
                    ),

                    "duracion_horas": (
                        released_recheck.get(
                            "duracion_horas"
                        )
                    ),

                    "reference_id": (
                        released_recheck.get(
                            "reference_id"
                        )
                    ),

                    "goal_context": [
                        "crear_reserva"
                    ],

                    "source": (
                        "next_best_action_current_turn"
                    ),
                },

                "reason_code": (
                    "released_booking_recheck"
                ),

                "reason": (
                    "el slot liberado sigue disponible "
                    "y puede bloquearse otra vez"
                ),
            }
        ]

    released_alternative = (
        _agent_v2_released_booking_alternative_data(
            perception,
            observations,
        )
    )

    if released_alternative:
        return [
            {
                "action": (
                    "confirm_released_booking"
                ),

                "question": {
                    "field": (
                        "released_booking_rebook"
                    ),

                    "options": [],

                    "booking_choice": True,

                    "offer_kind": (
                        "nearest_alternative"
                    ),

                    "dia": (
                        released_alternative.get(
                            "dia"
                        )
                    ),

                    "hora": (
                        released_alternative.get(
                            "hora"
                        )
                    ),

                    "cancha": (
                        released_alternative.get(
                            "cancha"
                        )
                    ),

                    "duracion_horas": (
                        released_alternative.get(
                            "duracion_horas"
                        )
                    ),

                    "reference_id": (
                        released_alternative.get(
                            "reference_id"
                        )
                    ),

                    "goal_context": [
                        "crear_reserva"
                    ],

                    "source": (
                        "next_best_action_current_turn"
                    ),
                },

                "reason_code": (
                    "released_booking_nearest_alternative"
                ),

                "reason": (
                    "el slot liberado fue ocupado; "
                    "ofrecer la alternativa real más cercana"
                ),
            }
        ]

    # =========================================================
    # SLOT EXACTO DISPONIBLE
    # =========================================================
    current_slot = (
        _agent_v2_current_available_slot(
            perception,
            observations,
        )
    )

    if current_slot:
        pending_slot = (
            _agent_v2_pending_question(
                world,
                "confirmar_slot",
            )
            or {}
        )

        if (
            pending_slot.get("dia")
            == current_slot.get("dia")
            and normalizar_hora_detectada(
                pending_slot.get("hora")
            )
            == current_slot.get("hora")
        ):
            return []

        return [
            {
                "action": (
                    "confirm_exact_slot"
                ),

                "question": {
                    "field": "confirmar_slot",

                    "options": [],

                    "booking_choice": True,

                    "dia": (
                        current_slot["dia"]
                    ),

                    "hora": (
                        current_slot["hora"]
                    ),

                    "canchas": (
                        _agent_v2_exact_available_courts(
                            current_slot
                        )
                    ),

                    "duracion_horas": (
                        current_slot.get(
                            "duracion_horas"
                        )
                        or DEFAULT_TURN_DURATION_HOURS
                    ),

                    "goal_context": [
                        "crear_reserva",
                        "buscar_turno",
                    ],

                    "source": (
                        "next_best_action_current_turn"
                    ),

                    "source_message": (
                        world.get("message")
                        or ""
                    ),

                    "replace_booking_questions": True,
                },

                "reason_code": (
                    "current_exact_slot_available"
                ),

                "reason": (
                    "día y hora ya verificados; "
                    "confirmar ese turno, no volver a pedirlos"
                ),
            }
        ]

    # =========================================================
    # SERVICE FAQ CONTINUITY
    # =========================================================
    service_domains = set(
        _agent_v2_normalize_question_domains(
            perception or {}
        )
    )

    policy_obs = (
        _agent_v2_policy_contract_observation(
            observations
        )
    )

    service_contract = (
        (
            (policy_obs or {}).get(
                "data"
            )
            or {}
        ).get(
            "policy_fact_contract"
        )
        or {}
    )

    no_real_reservation = not bool(
        (
            world.get("facts")
            or {}
        ).get(
            "reservas_reales"
        )
        or []
    )

    draft_now = (
        world.get("desires")
        or {}
    ).get(
        "booking_draft"
    ) or {}

    has_validated_slot = bool(
        draft_now.get("activo")
        and draft_now.get("dia")
        and draft_now.get("hora")
        and draft_now.get("cancha")
        and not draft_now.get(
            "reservation_id"
        )
    )

    if (
        (
            "service_policy"
            in service_domains
            or service_contract.get(
                "type"
            )
            == "quincho_service_policy"
        )
        and policy_obs
        and service_contract.get(
            "available"
        )
        is not False
        and no_real_reservation
        and not has_validated_slot
    ):
        pending_booking = next(
            (
                q
                for q in reversed(
                    list(
                        world.get(
                            "open_questions"
                        )
                        or []
                    )
                )
                if q.get("field")
                in {
                    "dia_hora_reserva",
                    "hora",
                    "hora_aclaracion",
                    "cancha",
                    "duracion_horas",
                }
            ),
            None,
        )

        if pending_booking:
            return [
                {
                    "action": (
                        "resume_pending"
                    ),

                    "question": {
                        **pending_booking,

                        "source": (
                            "next_best_action_current_turn"
                        ),
                    },

                    "reason": (
                        "FAQ de servicio resuelta; conservar "
                        "la decisión de reserva pendiente"
                    ),
                }
            ]

        availability = (
            world.get(
                "availability_context"
            )
            or {}
        )

        candidates.append(
            {
                "action": (
                    "ask_booking_datetime"
                ),

                "question": {
                    "field": (
                        "dia_hora_reserva"
                    ),

                    "options": [],

                    "booking_choice": True,

                    "dia": (
                        availability.get(
                            "dia"
                        )
                        or availability.get(
                            "dia_resuelto"
                        )
                    ),

                    "goal_context": [
                        "buscar_turno",
                        "crear_reserva",
                    ],

                    "source": (
                        "next_best_action_current_turn"
                    ),

                    "replace_booking_questions": True,
                },

                "reason_code": (
                    "service_policy_booking_bridge"
                ),

                "reason": (
                    "FAQ de servicio resuelta; abrir una sola "
                    "próxima decisión de reserva"
                ),
            }
        )

    # =========================================================
    # RETOMAR PREGUNTA SUSPENDIDA
    # =========================================================
    if _agent_v2_pending_is_suspended_this_turn(
        perception
    ):
        for q in reversed(
            list(
                (
                    world
                    or {}
                ).get(
                    "open_questions"
                )
                or []
            )
        ):
            if q.get("field") in {
                "dia_hora_reserva",
                "hora",
                "hora_aclaracion",
                "cancha",
                "duracion_horas",
                "reserva_especifica",
            }:
                qcopy = dict(
                    q
                )

                qcopy["source"] = (
                    "next_best_action_current_turn"
                )

                candidates.append(
                    {
                        "action": (
                            "resume_pending"
                        ),

                        "question": (
                            qcopy
                        ),

                        "reason": (
                            "había un booking activo y la pregunta "
                            "actual fue una interrupción informativa"
                        ),
                    }
                )

                break

    # =========================================================
    # LISTA DE ESPERA
    # =========================================================
    for obs in reversed(
        observations
        or []
    ):
        if (
            obs.get("tool")
            != "consultar_disponibilidad"
            or obs.get("ok")
        ):
            continue

        data = (
            obs.get("data")
            or {}
        )

        hour = (
            normalizar_hora_detectada(
                data.get("hora")
                or (
                    perception.get(
                        "entities"
                    )
                    or {}
                ).get(
                    "hora"
                )
            )
        )

        day = (
            data.get("dia")
            or (
                perception.get(
                    "entities"
                )
                or {}
            ).get(
                "dia_resuelto"
            )
            or (
                perception.get(
                    "entities"
                )
                or {}
            ).get(
                "dia"
            )
        )

        if (
            day
            and hora_es_valida(
                hour
            )
        ):
            candidates.append(
                {
                    "action": (
                        "offer_waitlist"
                    ),

                    "question": {
                        "field": (
                            "waitlist_offer"
                        ),

                        "options": [
                            "si",
                            "no",
                        ],

                        "dia": day,

                        "hora": hour,

                        "cancha": (
                            data.get(
                                "cancha"
                            )
                            or (
                                perception.get(
                                    "entities"
                                )
                                or {}
                            ).get(
                                "cancha"
                            )
                        ),

                        "goal_context": [
                            "lista_espera"
                        ],

                        "source": (
                            "next_best_action_current_turn"
                        ),
                    },

                    "reason": (
                        "el horario exacto pedido "
                        "no está disponible"
                    ),
                }
            )

            break

    # =========================================================
    # BOOKING SIN PREGUNTA ABIERTA
    # =========================================================
    explicit_actions = set(
        perception.get(
            "explicit_actions"
        )
        or []
    )

    booking_signal = bool(
        explicit_actions.intersection(
            {
                "reservar",
                "reservar_cancha",
                "crear_reserva",
            }
        )
        or (
            world.get(
                "desires"
            )
            or {}
        ).get(
            "booking_draft"
        )
    )

    if (
        booking_signal
        and not (
            world.get(
                "open_questions"
            )
            or []
        )
    ):
        known = (
            perception.get(
                "entities"
            )
            or {}
        )

        known_day = (
            known.get(
                "dia_resuelto"
            )
            or known.get(
                "dia"
            )
        )

        known_hour = (
            normalizar_hora_detectada(
                known.get(
                    "hora"
                )
            )
        )

        missing_field = (
            None
            if (
                known_day
                and hora_es_valida(
                    known_hour
                )
            )
            else "hora"
            if known_day
            else "dia"
            if hora_es_valida(
                known_hour
            )
            else "dia_hora_reserva"
        )

        if missing_field:
            candidates.append(
                {
                    "action": (
                        "ask_booking_datetime"
                    ),

                    "question": {
                        "field": (
                            missing_field
                        ),

                        "dia": (
                            known_day
                        ),

                        "hora": (
                            known_hour
                        ),

                        "options": [],

                        "booking_choice": True,

                        "goal_context": [
                            "buscar_turno",
                            "crear_reserva",
                        ],

                        "source": (
                            "next_best_action_current_turn"
                        ),
                    },

                    "reason": (
                        "hay intención de reservar; pedir sólo "
                        "el dato temporal faltante"
                    ),
                }
            )

    return candidates


def _agent_v2_price_quote_booking_bridge_candidate_legacy(
    world: Dict,
    perception: Dict,
    observations: List[Dict],
) -> Optional[Dict[str, Any]]:
    """
    Continuidad comercial stateful después de una cotización de cancha.

    PRINCIPIO:
    - Python decide si existe una próxima pregunta válida.
    - La IA NO inventa una pregunta por su cuenta.
    - Una consulta de precio resuelta puede continuar naturalmente hacia reserva.
    - No consulta disponibilidad todavía.
    - No crea ninguna reserva.
    - No inventa día/hora.
    """

    quote_obs = next((
        obs
        for obs in reversed(observations or [])
        if (
            obs.get("tool") == "consultar_precio"
            and obs.get("ok")
            and (obs.get("data") or {}).get("incluir_cancha")
        )
    ), None)

    if not quote_obs:
        return None

    quote_data = quote_obs.get("data") or {}

    # ---------------------------------------------------------
    # 1. La duración cotizada debe ser una duración habilitada.
    # ---------------------------------------------------------
    quoted_duration = normalizar_duracion_horas(
        quote_data.get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )

    allowed_durations = set()

    for item in (ALLOWED_TURN_DURATIONS or []):
        try:
            allowed_durations.add(
                round(float(item), 4)
            )
        except (TypeError, ValueError):
            continue

    if (
        allowed_durations
        and round(float(quoted_duration), 4)
        not in allowed_durations
    ):
        return None

    # ---------------------------------------------------------
    # 2. Si ya existe una reserva real activa, una consulta
    #    de precio podría ser solamente informativa.
    #    No abrimos otra venta automáticamente.
    # ---------------------------------------------------------
    real_reservations = (
        (world.get("facts") or {}).get(
            "reservas_reales"
        )
        or []
    )

    if real_reservations:
        return None

    # ---------------------------------------------------------
    # 3. Si había una pregunta de reserva suspendida porque
    #    el usuario hizo una FAQ intermedia, retomamos ESA
    #    pregunta en lugar de abrir una nueva.
    # ---------------------------------------------------------
    if _agent_v2_pending_is_suspended_this_turn(
        perception or {}
    ):
        pending = next((
            q
            for q in reversed(
                list(
                    world.get(
                        "open_questions"
                    )
                    or []
                )
            )
            if q.get("field") in {
                "dia_hora_reserva",
                "dia",
                "hora",
                "hora_aclaracion",
                "cancha",
                "duracion_horas",
            }
        ), None)

        if pending:
            qcopy = dict(pending)

            qcopy["source"] = (
                "next_best_action_current_turn"
            )

            return {
                "action": "resume_pending",

                "question": qcopy,

                "reason_code": (
                    "price_quote_resume_booking"
                ),

                "reason": (
                    "precio resuelto; retomar la decisión "
                    "de reserva que ya estaba abierta"
                ),
            }

    # ---------------------------------------------------------
    # 4. Leer SOLO datos temporales del mensaje actual.
    #
    #    No heredamos día/hora históricos porque una consulta
    #    de precio puede ser una conversación nueva.
    # ---------------------------------------------------------
    entities = (
        (perception or {}).get(
            "entities"
        )
        or {}
    )

    known_day = (
        entities.get("dia_resuelto")
        or entities.get("dia")
    )

    known_hour = normalizar_hora_detectada(
        entities.get("hora")
    )

    # ---------------------------------------------------------
    # 5. Si ya dijo día + hora, no preguntarlos de nuevo.
    #
    #    El flujo normal deberá consultar disponibilidad.
    # ---------------------------------------------------------
    if (
        known_day
        and hora_es_valida(
            known_hour
        )
    ):
        return None

    # ---------------------------------------------------------
    # 6. Preguntar solamente lo que falta.
    # ---------------------------------------------------------
    if known_day:
        field = "hora"

    elif hora_es_valida(
        known_hour
    ):
        field = "dia"

    else:
        field = "dia_hora_reserva"

    return {
        "action": (
            "ask_booking_datetime"
        ),

        "question": {
            "field": field,

            "options": [],

            "booking_choice": True,

            "dia": (
                known_day
            ),

            "hora": (
                known_hour
                if hora_es_valida(
                    known_hour
                )
                else None
            ),

            "duracion_horas": (
                quoted_duration
            ),

            # La duración elegida representa un bloque continuo.
            "booking_shape": (
                "contiguous_block"
                if quoted_duration
                else None
            ),

            "goal_context": [
                "buscar_turno",
                "crear_reserva",
            ],

            "source": (
                "next_best_action_current_turn"
            ),

            "replace_booking_questions": True,
        },

        "reason_code": (
            "price_quote_booking_bridge"
        ),

        "reason": (
            "cotización resuelta; pedir únicamente "
            "el dato temporal faltante para avanzar"
        ),
    }

async def elegir_next_best_action_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:

    if not AGENT_V2_NEXT_BEST_ACTION_ENABLED:
        return {
            "action": "none",
            "reason": "disabled",
        }

    candidates = _agent_v2_nba_candidates(
        world,
        perception,
        goals,
        observations,
        status,
    )

    # =========================================================
    # PRICE QUOTE → BOOKING CONTINUITY
    # =========================================================
    #
    # Las consultas puras de precio suelen salir de
    # _agent_v2_nba_candidates() como information_only.
    #
    # Pero comercialmente una cotización de cancha tiene una
    # continuación natural:
    #
    #   Precio respondido
    #       ↓
    #   ¿Qué día y hora te gustaría reservar?
    #
    # Esto NO reserva nada.
    # Solo registra formalmente la siguiente pregunta.
    # =========================================================

    if not candidates:

        price_bridge = (
            _agent_v2_price_quote_booking_bridge_candidate(
                world,
                perception,
                observations,
            )
        )

        if price_bridge:

            chosen = dict(
                price_bridge
            )

            chosen[
                "decision_reason"
            ] = (
                "continuidad determinista: "
                "cotización → próximo dato de reserva"
            )

            print(
                "   🧭 [AgentV2 PRICE NBA] "
                "cotización resuelta → "
                f"field={((chosen.get('question') or {}).get('field'))}"
            )

            return chosen

        return {
            "action": "none",
            "reason": "sin próxima acción útil",
        }

    # =========================================================
    # RELEASED BOOKING
    # =========================================================

    released_recheck = next((
        candidate
        for candidate in candidates
        if candidate.get(
            "reason_code"
        )
        in {
            "released_booking_recheck",
            "released_booking_nearest_alternative",
        }
    ), None)

    if released_recheck:

        chosen = dict(
            released_recheck
        )

        chosen[
            "decision_reason"
        ] = (
            "continuidad determinista: "
            "slot liberado reconsultado"
        )

        return chosen

    # =========================================================
    # ÚNICO CANDIDATO
    # =========================================================
    #
    # Si Python produjo exactamente una continuación válida,
    # no necesitamos gastar otro LLM para decidir entre una
    # sola opción.
    # =========================================================

    if (
        AGENT_V2_MINIMAL_LLM_MODE
        and len(candidates) == 1
    ):

        chosen = dict(
            candidates[0]
        )

        chosen[
            "decision_reason"
        ] = (
            "único candidato NBA autorizado por Python"
        )

        print(
            "   [AgentV2 NBA BUDGET] "
            "candidato único; NBA LLM omitido"
        )

        return chosen

    # =========================================================
    # SERVICE FAQ BRIDGE
    # =========================================================

    service_bridge = next(
        (
            candidate
            for candidate in candidates
            if candidate.get(
                "reason_code"
            )
            == "service_policy_booking_bridge"
        ),
        None,
    )

    if service_bridge:

        chosen = dict(
            service_bridge
        )

        chosen[
            "decision_reason"
        ] = (
            "continuidad determinista: "
            "Policy Fact de servicio → día+horario"
        )

        return chosen

    # =========================================================
    # RETOMAR BOOKING DESPUÉS DE FAQ
    # =========================================================

    if (
        _agent_v2_is_read_only_turn(
            perception
        )
        and
        _agent_v2_pending_is_suspended_this_turn(
            perception
        )
    ):

        resume = next(
            (
                candidate
                for candidate in candidates
                if candidate.get(
                    "action"
                )
                == "resume_pending"
            ),
            None,
        )

        if resume:

            chosen = dict(
                resume
            )

            chosen[
                "decision_reason"
            ] = (
                "continuidad determinista: "
                "FAQ resuelta con booking pendiente fresco"
            )

            return chosen

    # =========================================================
    # NBA IA
    # =========================================================

    allowed = [
        candidate.get(
            "action"
        )
        for candidate in candidates
    ] + [
        "none"
    ]

    try:

        resp = await call_openai_async(
            model=OPENAI_MODEL,

            messages=[
                {
                    "role": "system",

                    "content": (
                        "Sos NEXT BEST ACTION de un recepcionista de canchas. "
                        "Elegí si conviene avanzar la conversación después de "
                        "haber resuelto el mensaje actual. "

                        "Solo podés elegir una action de CANDIDATES o none. "

                        "No fuerces una reserva si el usuario solo hizo una "
                        "consulta aislada y no existe una continuidad comercial "
                        "stateful ya autorizada por Python. "

                        "Si había una coordinación de reserva y el usuario hizo "
                        "una FAQ intermedia, retomar la decisión pendiente suele "
                        "ser útil. "

                        "Si se pidió un slot exacto ocupado, ofrecer waitlist "
                        "es útil. "

                        "No inventes datos. "

                        + _agent_learning_prompt(
                            "nba",
                            world.get(
                                "message"
                            )
                            or "",
                            world,
                            learning_policy,
                        )

                        + "\nRespondé SOLO JSON: "
                        "{\"action\":\"...\",\"reason\":\"breve\"}."
                    ),
                },

                {
                    "role": "user",

                    "content": json.dumps(
                        {
                            "message": (
                                world.get(
                                    "message"
                                )
                            ),

                            "status": status,

                            "perception": perception,

                            "goals": goals,

                            "candidates": [
                                {
                                    "action": (
                                        candidate.get(
                                            "action"
                                        )
                                    ),

                                    "reason": (
                                        candidate.get(
                                            "reason"
                                        )
                                    ),
                                }

                                for candidate
                                in candidates
                            ],
                        },

                        ensure_ascii=False,

                        default=str,
                    ),
                },
            ],

            temperature=0.0,

            max_tokens=140,

            response_format={
                "type": "json_object"
            },
        )

        register_cost(
            resp
        )

        data = json.loads(
            resp
            .choices[0]
            .message
            .content
            .strip()
        )

        action = str(
            data.get(
                "action"
            )
            or "none"
        )

        if action not in allowed:
            action = "none"

        if action == "none":

            return {
                "action": "none",

                "reason": str(
                    data.get(
                        "reason"
                    )
                    or "modelo decidió no avanzar"
                ),
            }

        chosen = next(
            (
                candidate
                for candidate in candidates
                if candidate.get(
                    "action"
                )
                == action
            ),
            None,
        )

        if chosen:

            chosen = dict(
                chosen
            )

            chosen[
                "decision_reason"
            ] = str(
                data.get(
                    "reason"
                )
                or chosen.get(
                    "reason"
                )
                or ""
            )

            return chosen

    except Exception as e:

        print(
            f"   ⚠️ [AgentV2 NEXT BEST ACTION] "
            f"{e} → fallback seguro"
        )

    # =========================================================
    # FALLBACK SEGURO
    # =========================================================

    return next(
        (
            candidate
            for candidate in candidates
            if candidate.get(
                "action"
            )
            in {
                "resume_pending",
                "offer_waitlist",
            }
        ),

        {
            "action": "none",
            "reason": "fallback none",
        },
    )

def _agent_v2_price_quote_text_is_safe(
    text: str,
    observations: List[Dict],
) -> bool:
    """
    Guard determinista para cotizaciones humanizadas.

    Protege el ALCANCE, no sólo los números:
    - Cada componente cotizado por una Observation debe conservar su importe.
    - Un campo financiero perteneciente a un recurso NO incluido no autoriza
      ninguna afirmación sobre ese recurso.
    - En cotizaciones multi-act se prohíbe sustituir dos precios por una sola
      cifra o por una afirmación de gratuidad/inclusión sin mostrar el precio.
    - No usa el texto del usuario ni clasifica intención.
    """
    quotes = [
        dict(obs.get("data") or {})
        for obs in (observations or [])
        if (
            isinstance(obs, dict)
            and obs.get("tool") == "consultar_precio"
            and obs.get("ok")
            and (
                (obs.get("data") or {}).get("incluir_cancha")
                or (obs.get("data") or {}).get("incluir_quincho")
            )
        )
    ]

    if not quotes:
        return True

    def extract_money_values(value_text: str) -> set:
        values = set()

        matches = re.findall(
            r"\$\s*([0-9][0-9\.,]*)",
            str(value_text or ""),
        )

        for raw in matches:
            digits = re.sub(r"\D", "", raw)

            if not digits:
                continue

            try:
                values.add(int(digits))
            except ValueError:
                continue

        return values

    allowed = set()
    required = set()

    for data in quotes:
        include_court = bool(
            data.get("incluir_cancha")
        )
        include_quincho = bool(
            data.get("incluir_quincho")
        )

        if include_court:
            court_price = _monto_a_int(
                data.get("precio_cancha")
            )

            if court_price is not None:
                allowed.add(int(court_price))
                required.add(int(court_price))

        if include_quincho:
            qprice = _monto_a_int(
                data.get("precio_quincho")
            )

            if qprice is not None:
                allowed.add(int(qprice))
                required.add(int(qprice))

        if include_court and include_quincho:
            total = _monto_a_int(
                data.get("total")
            )

            if total is not None:
                allowed.add(int(total))
                required.add(int(total))

    if len(quotes) == 1:
        data = quotes[0]

        if data.get("requiere_senia"):
            deposit = _monto_a_int(
                data.get("senia_monto")
            )

            if deposit is not None:
                allowed.add(int(deposit))
                required.add(int(deposit))

    mentioned = extract_money_values(
        text
    )

    if required and not required.issubset(
        mentioned
    ):
        return False

    if mentioned and not mentioned.issubset(
        allowed
    ):
        return False

    return True



def aplicar_next_best_action_agent_v2(telefono: str, nba: Dict[str, Any]) -> None:
    action = str((nba or {}).get("action") or "none")
    agent_v2_reduce(telefono, {"type": "NEXT_BEST_ACTION_SET", "payload": nba or {}})
    question = (nba or {}).get("question")
    if action != "none" and isinstance(question, dict) and question.get("field"):
        payload = dict(question)
        if action == "resume_pending":
            # Se vuelve a formular ahora; conservar ID/opciones, no su antiguedad
            # conversacional anterior a la FAQ que acabamos de responder.
            payload["created_at"] = datetime.datetime.now(TIMEZONE).isoformat()

        # Una pregunta genérica de día+horario sustituye decisiones viejas del
        # booking, pero conserva availability_context como memoria semántica.
        if (
            action in {"ask_booking_datetime", "confirm_exact_slot"}
            and payload.get("replace_booking_questions")
        ):
            for old_field in (
                "hora", "hora_aclaracion", "cancha", "dia",
                "duracion_horas", "reserva", "reserva_especifica", "comprobante",
                # Una CTA nueva de reserva reemplaza también una oferta de
                # re-reserva vencida. Dejarla activa hace que el siguiente
                # "mañana a las ..." se lea como aceptación de aquella oferta
                # vieja, aunque esté respondiendo la CTA recién emitida.
                "released_booking_rebook",
            ):
                agent_v2_reduce(
                    telefono,
                    {"type": "CLEAR_OPEN_QUESTION", "payload": {"field": old_field}},
                )

        payload["source"] = "next_best_action_current_turn"
        payload["nba_action"] = action
        agent_v2_reduce(telefono, {"type": "SET_OPEN_QUESTION", "payload": payload})


def _agent_v2_append_nba_question(
    response: str,
    world: Dict,
) -> str:
    nba_questions = [
        q
        for q in (
            world.get(
                "open_questions"
            )
            or []
        )
        if (
            q.get("source")
            == "next_best_action_current_turn"
            and not q.get(
                "context_only"
            )
        )
    ]

    if not nba_questions:
        return response

    current_question = (
        nba_questions[-1]
    )

    question = (
        _agent_v2_render_open_question(
            current_question
        )
    )

    base = str(
        response
        or ""
    ).strip()

    # =========================================================
    # UX FAQ DURACIÓN
    # =========================================================
    #
    # El Policy Fact Contract puede verbalizar:
    #
    # "Sí, se puede jugar 2 horas."
    #
    # pero dentro del flujo de reservas queremos:
    #
    # "Sí, se puede reservar la cancha por 2 horas."
    #
    # No cambia ningún hecho; solo la redacción.
    # =========================================================
    if (
        current_question.get(
            "ux_mode"
        )
        == "duration_followup"
        and base.startswith(
            "Sí, se puede jugar "
        )
    ):
        base = base.replace(
            "Sí, se puede jugar ",
            "Sí, se puede reservar la cancha por ",
            1,
        )

    if (
        not question
        or question in base
    ):
        return base

    # El Composer y las plantillas deterministas
    # ya pueden verbalizar la misma pregunta
    # stateful con otra redacción.
    #
    # El contrato permite UNA sola pregunta.
    if (
        "?" in base
        or "¿" in base
    ):
        print(
            "   🧹 "
            "[AgentV2 NBA QUESTION DEDUPE] "
            "la respuesta ya contiene una pregunta "
            "autorizada; no anexo otra"
        )

        return base

    return (
        f"{base}\n\n{question}"
    ).strip()

def _agent_v2_format_reservation_query_observation(
    observation: Dict[str, Any],
) -> str:
    rows = [
        row for row in ((observation.get("data") or {}).get("reservas") or [])
        if isinstance(row, dict)
    ]
    if not rows:
        return "No encontré ningún turno activo a tu nombre."

    lines = [
        "Tenés este turno activo:"
        if len(rows) == 1
        else "Tenés estos turnos activos:"
    ]
    for row in rows[:6]:
        day = str(row.get("fecha") or row.get("dia") or "").strip()
        hour = formatear_hora_para_mensaje(row.get("hora"))
        court = str(row.get("cancha") or "la cancha").strip()
        deposit = str(row.get("senia_estado") or "").strip().casefold()
        deposit_label = (
            "seña pagada" if deposit == "pagada"
            else "seña pendiente" if deposit == "pendiente"
            else str(row.get("estado") or "activo").strip()
        )
        lines.append(f"📅 {day} a las *{hour}* — {court} ({deposit_label})")
    return "\n".join(lines)


def _agent_v2_fallback_response(
    goals: Dict,
    observations: List[Dict],
    world: Dict,
    perception: Dict = None,
) -> str:
    """
    Fallback agregado: responde TODOS los resultados del turno, no solo la última tool.
    """
    if not observations:
        if goals.get("primary_goal") == "saludar":
            return build_agent_v2_welcome_message(world)
        return "Decime qué necesitás y lo resolvemos."

    parts = []
    successful_create = _agent_v2_successful_create_observation(observations)
    rich_availability_message = ""

    policy_obs = _agent_v2_policy_contract_observation(observations)
    if policy_obs:
        policy_message = build_agent_v2_policy_fact_message(policy_obs)
        if policy_message:
            parts.append(policy_message)
    if _agent_v2_has_unrendered_policy_observation(observations):
        # Último recurso si el Composer IA falla: declarar la limitación, nunca
        # convertir una consulta sin resolver en una confirmación de reserva.
        parts.append("No tengo información confirmada para responder esa consulta sobre el negocio.")

    released_recheck_message = build_agent_v2_released_booking_recheck_message(
        perception or {},
        observations,
    )
    if released_recheck_message:
        parts.append(released_recheck_message)
    released_alternative_message = (
        build_agent_v2_released_booking_alternative_message(
            perception or {},
            observations,
        )
    )
    if released_alternative_message:
        parts.append(released_alternative_message)

    # El preflight de disponibilidad es evidencia interna cuando el mismo turno
    # ya creó el hold. La respuesta debe mostrar el resultado terminal asignado.
    if not successful_create and not released_recheck_message:
        # En un lote multi-intención se conserva la MISMA presentación comercial
        # que en una consulta simple: canchas, precio, iconos, horarios y CTA.
        rich_availability_message = build_agent_v2_detailed_availability_price_message(
            (world or {}).get("message") or "",
            world or {},
            observations,
            perception or {},
        )
        if rich_availability_message:
            parts.append(rich_availability_message)
        else:
            for obs in observations:
                if obs.get("tool") == "consultar_disponibilidad" and obs.get("ok"):
                    txt = _agent_v2_format_availability_observation(obs.get("data") or {})
                    if txt:
                        parts.append(txt)

    unavailable = next((
        obs for obs in reversed(observations)
        if obs.get("tool") == "consultar_disponibilidad"
        and obs.get("status") == "unavailable"
    ), None)
    if unavailable and not released_alternative_message:
        data = unavailable.get("data") or {}
        day = str(data.get("dia") or "ese día").strip()
        hour = normalizar_hora_detectada(data.get("hora"))
        court = str(data.get("cancha") or "").strip()
        if hora_es_valida(hour):
            target = f"{day} a las *{formatear_hora_para_mensaje(hour)}*"
            if court:
                target += f" en {court}"
            text = f"Ese horario no está disponible para {target}."
        else:
            if data.get("razon") == "sin_hora_especifica":
                text = f"No hay horarios disponibles para {day}."
            else:
                text = f"No encontré disponibilidad válida para {day}."
        if data.get("razon") == "anticipacion_insuficiente_reserva":
            minimum_notice = data.get("minimum_notice_minutes", MIN_BOOKING_NOTICE_MINUTES)
            if minimum_notice > 0:
                text += f" Para reservar necesitamos al menos {minimum_notice} minutos de anticipación."

        alternative_question = next((
            obs for obs in reversed(observations)
            if obs.get("tool") == "solicitar_dato"
            and (obs.get("data") or {}).get("field") == "hora"
            and (obs.get("data") or {}).get("options")
        ), None)
        if alternative_question:
            alternative_hours = [
                formatear_hora_para_mensaje(item)
                for item in (alternative_question.get("data") or {}).get("options") or []
                if hora_es_valida(item)
            ]
            if alternative_hours:
                text += (
                    "\n\nComo alternativa tengo "
                    + " o ".join(f"*{item}*" for item in alternative_hours)
                    + "."
                )
        day_summary = _agent_v2_format_availability_observation(data.get("day_availability") or {})
        if day_summary:
            text += f"\n\n{day_summary}"
        parts.append(text)

    for obs in observations:
        if obs.get("tool") == "consultar_precio" and obs.get("ok"):
            # La plantilla rica ya incorporó todas las cotizaciones verificadas.
            if rich_availability_message:
                continue
            data = obs.get("data") or {}
            if data.get("incluir_quincho") and not data.get("incluir_cancha"):
                qname = str(data.get("quincho") or "").strip() or "El quincho"
                qduration = normalizar_duracion_horas(
                    data.get("quincho_duracion_horas")
                    or data.get("duracion_horas")
                    or 1.0,
                    1.0,
                )
                if abs(float(qduration) - 1.0) < 1e-9:
                    parts.append(
                        f"{qname} sale {_fmt_precio(data.get('precio_quincho') or 0)} por hora."
                    )
                else:
                    parts.append(
                        f"{qname} por {qduration:g} horas sale "
                        f"{_fmt_precio(data.get('precio_quincho') or 0)}."
                    )
            elif data.get("incluir_quincho"):
                parts.append(
                    f"Cancha más quincho por {data.get('duracion_horas')} horas sale "
                    f"{_fmt_precio(data.get('total') or 0)}."
                )
            else:
                precio = data.get("precio_cancha")
                if precio is not None:
                    parts.append(f"La hora de cancha sale {_fmt_precio(precio)}.")

    # Escrituras observadas.
    for obs in observations:
        tool = obs.get("tool")
        data = obs.get("data") or {}
        if tool == "crear_reserva" and obs.get("ok"):
            if obs.get("status") == "already_exists":
                parts.append("Ese turno ya está tomado a tu nombre; no hace falta reservarlo de nuevo.")
            else:
                parts.append(build_agent_v2_created_reservation_message(obs))
        elif tool == "registrar_senia" and obs.get("ok"):
            parts.append(build_agent_v2_payment_confirmation_message(obs))
        elif tool == "registrar_pago_presencial" and obs.get("ok"):
            parts.append(build_agent_v2_cash_selection_message(obs))
        elif tool == "cancelar_reserva" and obs.get("ok"):
            parts.append("Listo, cancelé tu turno.")
        elif tool == "reprogramar_reserva" and obs.get("ok"):
            parts.append(
                f"Listo, pasé tu turno para {data.get('dia')} "
                f"a las {formatear_hora_para_mensaje(data.get('hora'))}."
            )
        elif tool == "quitar_quincho" and obs.get("ok"):
            corrected_summary = build_agent_v2_quincho_change_message(obs)
            parts.append(
                corrected_summary
                or "Listo, saqué el quincho y mantuve la reserva de la cancha."
            )

    for obs in observations:
        tool = obs.get("tool")
        data = obs.get("data") or {}
        if tool == "obtener_reserva" and obs.get("ok"):
            parts.append(_agent_v2_format_reservation_query_observation(obs))
        elif tool == "crear_reservas_multiples" and obs.get("ok"):
            parts.append(build_agent_v2_multiple_created_message(obs))
        elif tool == "anotarse_lista_espera" and obs.get("ok"):
            court = f" en {data.get('cancha')}" if data.get("cancha") else ""
            parts.append(
                f"✅ Listo, te anoté para {data.get('dia')} a las "
                f"{formatear_hora_para_mensaje(data.get('hora'))}{court}. "
                "Si se libera, te aviso por acá."
            )
        elif (
            tool == "solicitar_handoff_humano"
            and (obs.get("ok") or data.get("handoff_registered"))
        ):
            parts.append(str(data.get("respuesta") or "").strip())
        elif tool == "registrar_senia" and obs.get("status") == "needs_human_review":
            parts.append(
                "Recibí el comprobante, pero no lo puedo validar con suficiente seguridad. "
                "No marqué la seña como pagada; se lo dejé al encargado para revisión."
            )

    # La ÚNICA pregunta permitida sale del estado, no de imaginación del Composer.
    # Un Policy Fact Contract responde una consulta informativa autónoma; no debe
    # pegar al final una pregunta vieja de booking.
    questions = [q for q in world.get("open_questions") or [] if not q.get("context_only")]
    if policy_obs or _agent_v2_is_read_only_turn(perception or {}):
        current_missing_fields = {
            (obs.get("data") or {}).get("field") for obs in observations or []
            if obs.get("status") == "needs_user_input"
        }
        questions = [q for q in questions if q.get("field") in current_missing_fields]
    elif _agent_v2_pending_is_suspended_this_turn(perception or {}):
        # Suspender el pending anterior no puede ocultar la pregunta que una tool
        # acaba de abrir para resolver ESTE mensaje (comprobante, target, etc.).
        current_message = normalizar_texto_ia(world.get("message") or "")
        questions = [
            q for q in questions
            if q.get("source") == "next_best_action_current_turn"
            or (
                current_message
                and normalizar_texto_ia(q.get("source_message") or "")
                == current_message
            )
        ]
    if questions:
        if rich_availability_message:
            # La plantilla clásica ya contiene la CTA horaria con su icono.
            questions = [q for q in questions if q.get("field") != "hora"]
    if questions:
        qtext = _agent_v2_render_open_question(questions[-1])
        if qtext and qtext not in "\n\n".join(parts):
            parts.append(qtext)

    if parts:
        return "\n\n".join(parts)

    last = observations[-1]
    if last.get("status") == "needs_user_input":
        # V117: una pregunta no renderizada no puede degradar todo el turno a una
        # frase vacía de contexto. El Composer grounded decidirá cómo verbalizar
        # el PendingInteraction usando field/reason/options reales.
        return ""
    return "No pude confirmar el resultado de esa consulta."


def _agent_v2_has_unrendered_policy_observation(
    observations: List[Dict],
) -> bool:
    """
    Indica si quedó una consulta factual de negocio sin respuesta renderizable.

    Una lectura auxiliar de `consultar_informacion_negocio` NO se considera
    "consulta sin resolver" cuando sólo pertenece al dominio `availability`
    y el mismo turno ya obtuvo disponibilidad real mediante calendario.

    Esto evita anteponer mensajes como:
    "No tengo información confirmada para responder esa consulta sobre el negocio."
    a una plantilla de disponibilidad que sí está completamente verificada.
    """
    observations = list(observations or [])

    # =========================================================
    # 1. ¿EL CALENDARIO YA RESPONDIÓ DISPONIBILIDAD REAL?
    # =========================================================
    has_verified_availability = any(
        obs.get("tool")
        in {
            "consultar_disponibilidad",
            "consultar_disponibilidad_multiple",
        }
        and obs.get("ok")
        and obs.get("status")
        in {
            "success",
            "needs_user_input",
        }
        for obs in observations
        if isinstance(obs, dict)
    )

    # =========================================================
    # 2. REVISAR CONSULTAS FACTUALES DE NEGOCIO
    # =========================================================
    for obs in observations:
        if not isinstance(obs, dict):
            continue

        if obs.get("tool") != "consultar_informacion_negocio":
            continue

        # Una tool que realmente falló no pertenece a este helper.
        # Este helper sólo distingue observaciones OK renderizables/no renderizables.
        if not obs.get("ok"):
            continue

        # =====================================================
        # 3. SI HAY POLICY CONTRACT RENDERIZABLE, TODO BIEN
        # =====================================================
        if build_agent_v2_policy_fact_message(obs):
            continue

        data = obs.get("data") or {}

        domains = {
            str(item or "").strip().lower()
            for item in (
                data.get("question_domains")
                or []
            )
            if str(item or "").strip()
        }

        # =====================================================
        # 4. DISPONIBILIDAD NO ES UNA POLICY FAQ
        # =====================================================
        #
        # Caso real:
        #
        # usuario:
        #   "buen dia"
        #   "para reserva la cancha?"
        #
        # Perception puede producir:
        #
        # consultar_informacion_negocio
        #   question_domains=["availability"]
        #   requested_facts=["service.available"]
        #
        # +
        #
        # consultar_disponibilidad
        #   → agenda real verificada
        #
        # El primer READ es auxiliar/redundante.
        # La verdadera respuesta factual ya la dio calendario.
        #
        # JAMÁS mostrar:
        #
        # "No tengo información confirmada..."
        #
        # si inmediatamente después tenemos disponibilidad real.
        # =====================================================
        if (
            has_verified_availability
            and domains
            and domains.issubset(
                {
                    "availability",
                }
            )
        ):
            print(
                "   🧹 [AgentV2 POLICY NOISE GUARD] "
                "consulta informativa availability sin contrato "
                "→ ignorada porque calendario ya respondió"
            )

            continue

        # =====================================================
        # 5. COMPATIBILIDAD CON OBSERVACIONES ANTIGUAS
        # =====================================================
        #
        # Versiones anteriores pueden no haber persistido
        # question_domains dentro del data.
        #
        # Si:
        # - hay disponibilidad verificada
        # - no hay dominio factual
        # - no hay Policy Fact Contract
        #
        # consideramos ese READ auxiliar y no una consulta
        # pendiente que debamos verbalizar como error.
        # =====================================================
        if (
            has_verified_availability
            and not domains
            and not isinstance(
                data.get(
                    "policy_fact_contract"
                ),
                dict,
            )
        ):
            print(
                "   🧹 [AgentV2 POLICY NOISE GUARD] "
                "READ informativo vacío sin dominio "
                "→ disponibilidad verificada tiene precedencia"
            )

            continue

        # =====================================================
        # 6. ESTA SÍ ES UNA CONSULTA FACTUAL SIN RESPUESTA
        # =====================================================
        #
        # Ejemplo:
        # usuario pregunta una política real del negocio,
        # config no tiene ese dato y no existe otra tool
        # específica que lo haya respondido.
        #
        # En ese caso conservar el mecanismo de seguridad.
        # =====================================================
        return True

    return False


def _agent_v2_verified_alternative_hours_response(
    observations: List[Dict],
    world: Dict,
    perception: Dict,
) -> str:
    """Renderiza únicamente resultados de calendario para horas alternativas."""
    acts = _agent_v2_authoritative_semantic_acts(perception or {})
    if (
        not acts
        or any(
            act.get("operation") != "query_availability"
            or bool((act.get("commitment") or {}).get("wants_write"))
            for act in acts
        )
    ):
        return ""

    for obs in reversed(observations or []):
        if obs.get("tool") != "consultar_disponibilidad":
            continue
        data = obs.get("data") or {}
        results = [
            row for row in (data.get("requested_hour_results") or [])
            if isinstance(row, dict) and hora_es_valida(row.get("hora"))
        ]
        if len(results) < 2:
            continue

        day = str(data.get("dia") or "").strip()
        day_label = _agent_v2_relative_day_label(
            str((world or {}).get("message") or ""),
            day,
        ) or day
        lines = [f"Consulté la disponibilidad para *{day_label}*:", ""]
        available_hours = []
        for row in results:
            hour = normalizar_hora_detectada(row.get("hora"))
            courts = [
                str(court) for court in (row.get("canchas_libres") or [])
                if str(court).strip()
            ]
            if courts:
                available_hours.append(hour)
                lines.append(f"✅ *{hour}* — disponible en:")
                lines.extend(f"   {_court_display_identity(court)}" for court in courts)
            else:
                lines.append(f"❌ *{hour}* — sin canchas disponibles")
            lines.append("")

        if available_hours:
            choices = " o ".join(available_hours)
            lines.append(f"¿Cuál preferís, *{choices}*?")
        else:
            lines.append("Esos horarios no están disponibles. ¿Querés que busque otras opciones?")
        return "\n".join(lines).strip()
    return ""


def _agent_v2_verified_exact_availability_response(
    goals: Dict, observations: List[Dict], world: Dict, perception: Dict,
) -> str:
    """Salida canónica para READ exacto: confirma ese slot y espera consentimiento."""
    alternatives = _agent_v2_verified_alternative_hours_response(
        observations,
        world,
        perception,
    )
    if alternatives:
        return alternatives
    if not _agent_v2_is_pure_exact_availability_read(perception or {}):
        return ""
    for obs in reversed(observations or []):
        if (
            obs.get("tool") == "consultar_disponibilidad"
            and obs.get("ok")
            and obs.get("status") == "success"
            and (obs.get("data") or {}).get("hora")
        ):
            data = obs.get("data") or {}
            # ``day_availability`` es evidencia auxiliar de la tool, no cambia la
            # pregunta que hizo el usuario. Si la consulta tiene una hora exacta,
            # responder la grilla del día y volver a pedir hora contradice el
            # resultado factual recién obtenido.
            router_booking = globals().get(
                "_agent_v2_v128_router_booking_intent"
            )
            if callable(router_booking) and router_booking():
                day = str(data.get("dia") or "").strip()
                hour = normalizar_hora_detectada(data.get("hora"))
                courts = _agent_v2_exact_available_courts(data)
                if day and hora_es_valida(hour) and courts:
                    return "\n".join([
                        f"✅ Sí, para el *{day} a las {hour}* tenemos disponibilidad:",
                        "",
                        *[_court_display_identity(court) for court in courts],
                    ]).strip()
            rendered = build_agent_v2_exact_slot_confirmation_message(obs)
            if rendered:
                return rendered
    return ""


def _agent_v2_current_turn_response_payload(
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    """Resume significado actual que una respuesta no puede omitir.

    No relee el mensaje con keywords. Usa exclusivamente el SemanticFrame y las
    menciones que Perception atribuyó al turno actual. Sirve para distinguir una
    confirmación vacía (donde una pregunta corta puede alcanzar) de una respuesta
    coloquial que además aportó o consultó duración, fecha, recurso, política u
    otro dato que merece una contestación antes de pedir el campo faltante.
    """
    perception = perception or {}
    mentions = []
    for mention in perception.get("temporal_mentions") or []:
        if not isinstance(mention, dict):
            continue
        evidence = str(mention.get("evidence") or "").strip()
        if not evidence:
            continue
        mentions.append({
            "kind": str(mention.get("kind") or "").strip(),
            "evidence": evidence,
            "resolved_value": mention.get("resolved_value"),
        })

    operations = []
    requested_facts = []
    quantities = []
    changes = []
    specific_targets = []
    for act in _agent_v2_authoritative_semantic_acts(perception):
        if not isinstance(act, dict):
            continue
        operation = str(act.get("operation") or "").strip()
        # query_availability por sí sola ya queda cubierta por las plantillas de
        # calendario. Las demás consultas sí representan contenido adicional que
        # no puede reducirse a "¿qué horario?".
        if (
            operation.startswith("query_")
            and operation != "query_availability"
            and operation not in operations
        ):
            operations.append(operation)
        # Normalization may copy frame-level requested_facts into sibling acts
        # (for example `greet`). Only a semantic query owns those facts; a
        # greeting must not turn a normal onboarding reply into AI regeneration.
        if operation.startswith("query_") and operation != "query_availability":
            for fact in act.get("requested_facts") or []:
                fact_text = str(fact or "").strip()
                if fact_text and fact_text not in requested_facts:
                    requested_facts.append(fact_text)

        quantity = act.get("quantity") if isinstance(act.get("quantity"), dict) else {}
        temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
        duration = quantity.get("duration_hours")
        if duration is None:
            duration = temporal.get("duration_hours")
        if duration is not None and any(
            str(item.get("kind") or "") == "duration" for item in mentions
        ):
            quantities.append({"duration_hours": duration})

        for change in act.get("changes") or []:
            if not isinstance(change, dict):
                continue
            if (
                str(change.get("source") or "") == "current_user_turn"
                and str(change.get("evidence") or "").strip()
            ):
                changes.append({
                    "field": change.get("field"),
                    "value": change.get("value"),
                    "evidence": change.get("evidence"),
                })

        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        target_evidence = str(target.get("evidence") or "").strip()
        target_label = str(target.get("label") or "").strip()
        if target_label and target_evidence:
            specific_targets.append({
                "resource": target.get("resource"),
                "label": target_label,
                "evidence": target_evidence,
            })

    question_domains = _agent_v2_normalize_question_domains(perception)
    non_availability_domains = [
        domain for domain in question_domains if domain != "availability"
    ]
    return {
        "semantic_queries": operations,
        "question_domains": non_availability_domains,
        "requested_facts": requested_facts,
        "temporal_mentions": mentions,
        "quantities": quantities,
        "changes": changes,
        "specific_targets": specific_targets,
    }


def _agent_v2_requires_contextual_response_composition(
    perception: Dict[str, Any],
) -> bool:
    payload = _agent_v2_current_turn_response_payload(perception)
    return any(bool(value) for value in payload.values())


async def componer_respuesta_agent_v2(
    mensaje: str,
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> str:
    """
    RESPONSE COMPOSER único.

    El Composer debe responder TODOS los goals y no puede inventar una pregunta.
    Las preguntas autorizadas vienen exclusivamente de open_questions.
    """
    if _agent_v2_is_read_only_turn(perception) and any(
        o.get("ok") and o.get("tool") in {"consultar_informacion_negocio", "consultar_precio", "obtener_reserva"}
        for o in observations
    ) and not any(o.get("tool") in {"consultar_disponibilidad", "consultar_disponibilidad_multiple", "solicitar_handoff_humano"} for o in observations):
        return await _agent_v2_compose_from_fact_pack(
            mensaje, world, perception, goals, observations, status, learning_policy
        )
    exact_availability = _agent_v2_verified_exact_availability_response(
        goals, observations, world, perception
    )
    if exact_availability:
        print(
            "   ✅ [AgentV2 EXACT AVAILABILITY → CONFIRM SLOT] "
            f"build={AGENT_V2_EXACT_SLOT_CONFIRM_BUILD}"
        )
        return exact_availability
    missing_input_response = _agent_v2_verified_missing_input_response(
        observations,
        world,
    )
    if missing_input_response:
        if _agent_v2_requires_contextual_response_composition(perception):
            print(
                "   🧠 [AgentV2 CONTEXTUAL RESPONSE] "
                "el turno aportó significado además del dato faltante → "
                "Composer IA con entorno completo"
            )
            return await _agent_v2_compose_from_fact_pack(
                mensaje,
                world,
                perception,
                goals,
                observations,
                status,
                learning_policy,
            )
        print(
            "   🧱 [AgentV2 MISSING INPUT CONTRACT] "
            "Policy pidió un dato; Composer LLM omitido"
        )
        return missing_input_response
    if perception.get("semantic_clarification_required"):
        clarification = perception.get("semantic_clarification") or {}
        v86_pending = _agent_v2_v86_semantic_clarification_pending_payload(
            perception,
            world,
            clarification,
        )
        if str(v86_pending.get("field") or "") == "confirmar_reprogramacion":
            target_hour = normalizar_hora_detectada(v86_pending.get("hora"))
            target_day = str(v86_pending.get("dia") or "").strip()
            when = ""
            if target_day and hora_es_valida(target_hour):
                when = f" para {target_day} a las {formatear_hora_para_mensaje(target_hour)}"
            elif hora_es_valida(target_hour):
                when = f" para las {formatear_hora_para_mensaje(target_hour)}"
            return f"¿Querés que reprograme tu reserva{when}?"
        alternatives = [
            str(item.get("operation") or "")
            for item in (clarification.get("alternatives") or [])
            if isinstance(item, dict) and item.get("operation")
        ]
        labels = {
            "query_availability": "consultar disponibilidad",
            "query_price": "consultar precios",
            "query_policy": "hacer una consulta",
            "create_booking": "hacer una reserva",
            "cancel_booking": "cancelar una reserva",
            "reschedule_booking": "reprogramar una reserva",
            "modify_resource": "modificar una reserva",
            "register_payment": "aplicar el comprobante a la reserva de cancha",
            "register_event_payment": "aplicarlo a la inscripción del torneo",
            "handoff_human": "hablar con el encargado",
        }
        choices = list(dict.fromkeys(labels.get(op, op) for op in alternatives if op != "unknown"))
        if len(choices) >= 2:
            return f"¿Querés {choices[0]} o {choices[1]}?"
        return (
            "No llegué a identificar la operación. "
            "¿Querés consultar disponibilidad, hacer una reserva o gestionar una reserva existente?"
        )

    semantic_operations = {
        act.get("operation")
        for act in _agent_v2_authoritative_semantic_acts(perception)
    }
    query_acts = [
        act for act in _agent_v2_authoritative_semantic_acts(perception)
        if str(act.get("operation") or "").startswith("query_")
    ]
    rich_availability_for_multi = build_agent_v2_detailed_availability_price_message(
        mensaje, world, observations, perception
    )
    if len(query_acts) >= 2 and rich_availability_for_multi:
        # Contrato universal de respuesta multi-consulta: ninguna plantilla
        # especializada ni el primary_goal puede retornar antes de incluir las
        # observaciones de TODOS los actos READ del lote actual. Si existe agenda,
        # se resuelve antes que cualquier Composer libre para preservar su formato.
        composite = _agent_v2_fallback_response(
            goals,
            observations,
            world,
            perception,
        )
        if composite:
            print(
                "   🧩 [AgentV2 MULTI-SUBINTENT COMPOSER] "
                f"{len(query_acts)} consultas → respuesta agregada única"
            )
            return composite

    # La lectura de config puede haber funcionado sin producir una respuesta
    # factual renderizable. En un lote con disponibilidad, la rama multi de arriba
    # conserva primero la plantilla comercial y declara la consulta no resuelta;
    # nunca entrega toda la agenda al Composer libre para que cambie su formato.
    if _agent_v2_has_unrendered_policy_observation(observations):
        return await _agent_v2_compose_from_fact_pack(
            mensaje, world, perception, goals, observations, status, learning_policy
        )

    if len(query_acts) >= 2:
        composite = _agent_v2_fallback_response(
            goals,
            observations,
            world,
            perception,
        )
        if composite:
            print(
                "   🧩 [AgentV2 MULTI-SUBINTENT COMPOSER] "
                f"{len(query_acts)} consultas → respuesta agregada única"
            )
            return composite
    if (
        "clarify" in semantic_operations
        and (_agent_v2_semantic_frame(perception).get("turn_type") == "denial")
        and not observations
    ):
        return "Tenés razón, perdón, me apuré. ¡Hola!"

    if goals.get("primary_goal") == "cerrar_conversacion" and not observations and not world.get("open_questions"):
        return "Dale, gracias a vos. ¡Que tengas buen día!"

    multi_created_obs = _agent_v2_successful_multiple_create_observation(observations)
    if multi_created_obs:
        print("   🧾 [AgentV2 MULTI BOOKING TEMPLATE] batch atómico creado")
        return build_agent_v2_multiple_created_message(multi_created_obs)

    handoff_obs = next((
        o for o in reversed(observations or [])
        if o.get("tool") == "solicitar_handoff_humano"
        and (o.get("ok") or (o.get("data") or {}).get("handoff_registered"))
    ), None)
    if handoff_obs:
        return str((handoff_obs.get("data") or {}).get("respuesta") or build_human_derivation_response()).strip()

    waitlist_obs = next((o for o in reversed(observations or []) if o.get("tool") == "anotarse_lista_espera" and o.get("ok")), None)
    if waitlist_obs:
        d = waitlist_obs.get("data") or {}
        court = f" en {d.get('cancha')}" if d.get("cancha") else ""
        return (
            f"✅ Listo, te anoté para {d.get('dia')} a las {formatear_hora_para_mensaje(d.get('hora'))}{court}. "
            "Si se libera, te aviso por acá."
        )

    payment_review_obs = next((o for o in reversed(observations or []) if o.get("tool") == "registrar_senia" and o.get("status") == "needs_human_review"), None)
    if payment_review_obs:
        return (
            "Recibí el comprobante, pero no lo puedo validar con suficiente seguridad. "
            "No marqué la seña como pagada; se lo dejé al encargado para revisión."
        )

    cash_selection_obs = _agent_v2_successful_cash_selection_observation(
        observations
    )
    if cash_selection_obs:
        print(
            "   💵 [AgentV2 CASH TEMPLATE] reserva pendiente por ID → "
            "confirmación administrativa requerida"
        )
        return build_agent_v2_cash_selection_message(cash_selection_obs)

    quincho_change_obs = _agent_v2_successful_quincho_change_observation(
        observations
    )
    if quincho_change_obs:
        quincho_change_message = build_agent_v2_quincho_change_message(
            quincho_change_obs
        )
        if quincho_change_message:
            print(
                "   🔥 [AgentV2 QUINCHO UPDATE TEMPLATE] "
                "horario actualizado → seña/resumen determinista"
            )
            return quincho_change_message

    created_obs = _agent_v2_successful_create_observation(observations)
    if created_obs:
        print("   🧾 [AgentV2 BOOKING TEMPLATE] reserva creada → seña + resumen determinista")
        return build_agent_v2_created_reservation_message(created_obs)

    payment_obs = _agent_v2_successful_payment_observation(observations)
    if payment_obs:
        print(
            "   ✅ [AgentV2 PAYMENT TEMPLATE] comprobante validado → "
            "confirmación de seña + resumen determinista"
        )
        return build_agent_v2_payment_confirmation_message(payment_obs)

    if any(
        obs.get("tool") == "consultar_disponibilidad"
        and obs.get("status") == "unavailable"
        and (obs.get("data") or {}).get("razon") == "anticipacion_insuficiente_reserva"
        for obs in observations
    ):
        return _agent_v2_fallback_response(goals, observations, world, perception)

    # V2.9 CURRENT-TURN PRIORITY: si el último no leído es una consulta
    # informativa con Policy Fact Contract, esa respuesta gana incluso si por
    # defensa hay otra Observation de contexto en el turno.
    policy_obs = _agent_v2_policy_contract_observation(observations)
    if policy_obs and (
        _agent_v2_is_read_only_turn(perception)
        or _agent_v2_pending_is_suspended_this_turn(perception)
    ):
        policy_message = await compose_agent_v2_policy_fact_message(
            policy_obs,
            mensaje,
        )
        if policy_message:
            print(
                "   🥇 [AgentV2 CURRENT TURN RESPONSE] "
                "consulta actual grounded → no repetir respuesta anterior"
            )
            return policy_message

    asap_obs = _agent_v2_asap_availability_observation(observations)
    if asap_obs:
        asap_message = build_agent_v2_asap_availability_message(mensaje, asap_obs)
        if asap_message:
            print("   ⚡ [AgentV2 ASAP TEMPLATE] próximo turno real → no listar franja inventada")
            return asap_message

    released_recheck_message = build_agent_v2_released_booking_recheck_message(
        perception,
        observations,
    )
    if released_recheck_message:
        print(
            "   🔁 [AgentV2 RELEASED BOOKING TEMPLATE] "
            "slot exacto reconsultado → ofrecer rebloqueo"
        )
        return released_recheck_message

    released_alternative_message = (
        build_agent_v2_released_booking_alternative_message(
            perception,
            observations,
        )
    )
    if released_alternative_message:
        print(
            "   🧭 [AgentV2 RELEASED BOOKING ALTERNATIVE TEMPLATE] "
            "slot ocupado → ofrecer opción verificada más cercana"
        )
        return released_alternative_message

    detailed_availability = build_agent_v2_detailed_availability_price_message(
        mensaje, world, observations, perception
    )
    if detailed_availability:
        print("   📋 [AgentV2 AVAILABILITY TEMPLATE] canchas + precio + horarios detallados")
        return detailed_availability

    unavailable_day_obs = next((
        obs for obs in reversed(observations or [])
        if obs.get("tool") == "consultar_disponibilidad"
        and obs.get("status") in {"success", "unavailable"}
        and (obs.get("data") or {}).get("razon") == "sin_hora_especifica"
        and not (obs.get("data") or {}).get("horas_disponibles")
    ), None)
    if unavailable_day_obs:
        rendered = _agent_v2_format_availability_observation(
            unavailable_day_obs.get("data") or {}
        )
        if rendered:
            print(
                "   📋 [AgentV2 NO AVAILABILITY TEMPLATE] "
                "calendario sin huecos → Composer LLM omitido"
            )
            return rendered

    policy_obs = _agent_v2_policy_contract_observation(observations)
    if policy_obs:
        policy_message = await compose_agent_v2_policy_fact_message(
            policy_obs,
            mensaje,
        )
        if policy_message:
            print(
                "   📐 [AgentV2 POLICY FACT RESPONSE] "
                "hechos finitos de config → respuesta no contradictoria"
            )
            return policy_message

    # Identidad institucional y oferta de servicios vienen de config.py.
    # No dejamos que un LLM improvise/degrade el primer contacto.
    if goals.get("primary_goal") == "saludar" and not observations:
        return build_agent_v2_welcome_message(world)

    price_quote = build_agent_v2_price_quote_message(observations)
    if price_quote and not any(
        obs.get("tool") in {"consultar_disponibilidad", "consultar_disponibilidad_multiple"}
        and obs.get("ok")
        for obs in observations or []
    ):
        print(
            "   💲 [AgentV2 PRICE TEMPLATE] cotización + seña calculada "
            "desde config; Composer LLM omitido"
        )
        return price_quote

    return await _agent_v2_compose_from_fact_pack(
        mensaje, world, perception, goals, observations, status, learning_policy
    )


async def _agent_v2_compose_from_fact_pack(
    mensaje: str, world: Dict, perception: Dict, goals: Dict,
    observations: List[Dict], status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> str:
    fact_pack = _agent_v2_response_facts(world, observations, goals, perception)
    authorized_fields = {
        str(q.get("field") or "")
        for q in fact_pack.get("authorized_questions") or []
        if q.get("field")
    }

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        f"Sos {AGENT_NAME}, recepcionista IA de {BUSINESS_NAME}. Solo redactás la respuesta final.\n\n"
                        "REGLAS:\n"
                        "- Respondé TODOS los goals del mensaje que tengan observaciones disponibles; no solo el primary_goal.\n"
                        "- Antes de formular una pregunta pendiente, respondé o reconocé TODO el significado nuevo del "
                        "turno actual: duración, fecha, horario, recurso, cambio y cada requested_fact. Una pregunta sola "
                        "no es respuesta si el usuario también aportó o consultó uno de esos datos.\n"
                        "- Si el usuario consulta una duración y Perception la dejó en temporal_mentions, entities o "
                        "quantity.duration_hours, verificá si está permitida usando "
                        "FACT_PACK.business.duraciones_permitidas_horas y respondé sí/no de forma natural.\n"
                        "- Una lectura exitosa de config no implica que la pregunta esté respondida. Si falta un dato, "
                        "decí que no tenés información confirmada; nunca respondas solamente 'Listo' a una consulta.\n"
                        "- Si hay precio + disponibilidad, incluí ambos.\n"
                        "- Una franja (tarde/noche/etc.) es una franja, no una hora exacta.\n"
                        "- Solo podés hacer una pregunta si aparece en AUTHORIZED_QUESTIONS.\n"
                        "- Si la pregunta autorizada field=hora tiene booking_choice=true, preguntá qué horario quiere "
                        "reservar; la próxima hora válida será una decisión de reserva.\n"
                        "- Si AUTHORIZED_QUESTIONS está vacío, NO abras una pregunta nueva ni preguntes si quiere reservar.\n"
                        "- Si perception.current_turn_read_only=true, suspend_pending_this_turn=true o question_domains contiene "
                        "políticas/capacidades, respondé SOLO el objetivo del MENSAJE ACTUAL; no listes disponibilidad ni retomes "
                        "una pregunta de booking vieja salvo que el usuario la haya respondido explícitamente.\n"
                        "- Para preguntas de duración, usá business.duraciones_permitidas_horas y respondé natural, como agente, "
                        "no como plantilla de disponibilidad.\n"
                        "- Para attention_schedule, respondé el horario de atención desde CALL_TIME_WINDOWS/franjas_atencion; "
                        "NO lo conviertas en una consulta de disponibilidad del calendario.\n"
                        "- Para service_policy sobre quincho, nunca copies la pregunta del usuario: respondé desde el "
                        "Policy Fact Contract (disponible, incluido o cobrado aparte, y precio si está configurado).\n"
                        "- POLICY_FACT_CONTRACTS son hechos lógicos autoritativos. Nunca digas que una opción está prohibida "
                        "si el contrato la marca allowed=true, ni que está permitida si marca allowed=false.\n"
                        "- El onboarding de saludo usa un contrato especial dia_hora_reserva ya registrado por el runtime; "
                        "no reemplaces la identidad ni los servicios configurados por saludos genéricos.\n"
                        "- Si el usuario ya dijo que quiere cancha/reservar, no le vuelvas a preguntar si quiere reservar.\n"
                        "- No hables de seña/alias/pago antes de que una tool haya creado una reserva o procesado pago.\n"
                        "- Solo afirmá fechas, horarios, canchas y precios presentes en FACT_PACK.\n"
                        "- Sólo current_financial_facts autoriza importes; business e history no son una cotización. No calcules porcentajes: usá la seña calculada por Python.\n"
                        "- Español argentino natural con voseo.\n"
                        + _agent_learning_prompt(
                            "composer",
                            mensaje,
                            world,
                            learning_policy,
                        )
                        + "\n\nRespondé SOLO JSON: "
                        '{"response":"texto WhatsApp","asks_user":true|false,"question_field":"campo|null"}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "message": mensaje,
                        "goals": goals,
                        "perception": perception,
                        "status": status,
                        "current_turn_response_payload": _agent_v2_current_turn_response_payload(perception),
                        "fact_pack": fact_pack,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.20,
            max_tokens=520,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        response = str(data.get("response") or "").strip()
        asks_user = bool(data.get("asks_user"))
        question_field = normalizar_valor_nullable(data.get("question_field"))

        # Contrato conversacional: no existe pregunta sin estado.
        if asks_user and question_field not in authorized_fields:
            print(
                f"   🛡️ [AgentV2 DIALOGUE CONTRACT] pregunta no autorizada "
                f"field={question_field!r}; uso fallback grounded"
            )
            return _agent_v2_fallback_response(goals, observations, world, perception)

        if not response:
            return _agent_v2_fallback_response(goals, observations, world, perception)
        return response

    except Exception as e:
        print(f"   ⚠️ [AgentV2 COMPOSER] {e}")
        return _agent_v2_fallback_response(goals, observations, world, perception)



def _agent_v2_expected_policy_response_with_nba(
    policy_obs: Dict[str, Any],
    world: Dict,
) -> str:
    """
    Respuesta confiable = Policy Fact Contract + pregunta NBA autorizada.

    Permite que Grounding preserve tanto el hecho verificado como la continuidad
    stateful sin volver a pasar ese texto por generación libre.
    """
    base = build_agent_v2_policy_fact_message(policy_obs)
    if not base:
        return ""
    return _agent_v2_append_nba_question(base, world)

def build_agent_v2_reprogrammed_reservation_message(
    observation: Dict[str, Any],
) -> str:
    """
    Render DETERMINISTA del estado final después de reprogramar.

    PRINCIPIO CENTRAL:

        REPROGRAMAR CAMBIA EL TURNO,
        NO REINICIA EL SETTLEMENT.

    Estados contemplados:

    - pagada
    - parcial
    - parcial_efectivo_pendiente
    - pendiente_efectivo
    - pendiente

    Nunca convierte automáticamente un estado existente
    en `pendiente`.
    """
    if not isinstance(
        observation,
        dict,
    ):
        return ""

    data = (
        observation.setdefault(
            "data",
            {},
        )
    )

    if not isinstance(
        data,
        dict,
    ):
        return ""

    reservation_id = str(
        data.get(
            "reservation_id"
        )
        or ""
    ).strip()

    try:

        rows = (
            calendario.listar_reservas()
            or []
        )

    except Exception as exc:

        print(
            "   ⚠️ [AgentV2 REPROGRAM SUMMARY] "
            f"no pude releer calendario: {exc}"
        )

        rows = []

    active_rows = [
        row
        for row
        in rows
        if (
            isinstance(
                row,
                dict,
            )
            and _reserva_activa(
                row
            )
        )
    ]

    verified = None

    if reservation_id:

        verified = (
            _agent_v2_find_reservation_by_id(
                active_rows,
                reservation_id,
            )
        )

    if not verified:

        day = data.get(
            "dia"
        )

        hour = (
            normalizar_hora_detectada(
                data.get(
                    "hora"
                )
            )
        )

        court = data.get(
            "cancha"
        )

        matches = [
            row
            for row
            in active_rows
            if _reserva_coincide_slot(
                row,
                day,
                hour,
                court,
            )
        ]

        if matches:

            verified = (
                _agent_v2_enrich_reservation(
                    matches[
                        0
                    ]
                )
            )

    if not verified:

        print(
            "   ⚠️ [AgentV2 REPROGRAM SUMMARY] "
            "reprogramación sin reserva verificable; "
            "no genero resumen financiero"
        )

        return ""

    row = dict(
        verified
    )

    dia = (
        row.get(
            "fecha"
        )
        or row.get(
            "dia"
        )
        or data.get(
            "dia"
        )
        or ""
    )

    hora = (
        normalizar_hora_detectada(
            row.get(
                "hora"
            )
            or data.get(
                "hora"
            )
        )
    )

    cancha = (
        row.get(
            "cancha"
        )
        or data.get(
            "cancha"
        )
        or ""
    )

    if (
        not dia
        or not hora_es_valida(
            hora
        )
        or not cancha
    ):
        return ""

    duracion = (
        normalizar_duracion_horas(
            row.get(
                "duracion_horas"
            )
            or data.get(
                "duracion_horas"
            )
            or DEFAULT_TURN_DURATION_HOURS
        )
    )

    court_price = (
        calcular_precio_total(
            duracion
        )
    )

    con_quincho = str(
        row.get(
            "con_quincho"
        )
        or ""
    ).strip().casefold() in {
        "si",
        "sí",
        "true",
        "1",
        "yes",
    }

    quincho = (
        normalizar_nombre_quincho(
            row.get(
                "quincho"
            )
            or ""
        )
        if con_quincho
        else ""
    )

    quincho_hora_inicio = (
        normalizar_hora_detectada(
            row.get(
                "quincho_hora_inicio"
            )
            or ""
        )
        if con_quincho
        else ""
    )

    if (
        con_quincho
        and not hora_es_valida(
            quincho_hora_inicio
        )
    ):

        quincho_hora_inicio = (
            hora_fin_bloque(
                hora,
                duracion,
            )
        )

    quincho_duracion = (
        normalizar_duracion_horas(
            row.get(
                "quincho_duracion_horas"
            )
            or 1.0,
            1.0,
        )
        if con_quincho
        else None
    )

    quincho_price = (
        _monto_a_int(
            row.get(
                "quincho_precio_total"
            )
        )
        if con_quincho
        else 0
    )

    if (
        con_quincho
        and quincho_price
        is None
    ):

        quincho_price = (
            calcular_precio_quincho_total(
                quincho,
                quincho_duracion,
            )
        )

    quincho_price = int(
        quincho_price
        or 0
    )

    precio_total = (
        _monto_a_int(
            row.get(
                "precio_total"
            )
        )
    )

    if precio_total is None:

        precio_total = (
            court_price
            + quincho_price
        )

    # ==========================================================
    # FINANCIAL STATE — CALENDAR OWNS TRUTH
    # ==========================================================

    senia_estado = str(
        row.get(
            "senia_estado"
        )
        or data.get(
            "senia_estado"
        )
        or ""
    ).strip().casefold()

    senia_requerida = (
        _monto_a_int(
            row.get(
                "senia_monto"
            )
        )
    )

    if senia_requerida is None:

        senia_requerida = (
            _senia_guardada_o_configurada(
                row,
                precio_total,
            )
        )

    transferido = (
        _senia_pagada_acumulada(
            row,
            precio_total,
        )
    )

    cash_due = (
        _monto_a_int(
            row.get(
                "senia_efectivo_pendiente"
            )
        )
        or 0
    )

    senia_faltante = (
        _senia_faltante_para_confirmar(
            row,
            precio_total,
        )
    )

    monto_pendiente = (
        _monto_a_int(
            row.get(
                "monto_pendiente"
            )
        )
    )

    if monto_pendiente is None:

        monto_pendiente = max(
            0,
            precio_total
            - transferido,
        )

    firme = (
        _agent_v2_reprogrammed_booking_is_firm(
            row
        )
    )

    # FACT PACK / MONEY GUARD recibe exactamente
    # el settlement verificado.
    data.update({
        "dia": (
            dia
        ),
        "hora": (
            hora
        ),
        "cancha": (
            cancha
        ),
        "duracion_horas": (
            duracion
        ),
        "precio_total": (
            precio_total
        ),
        "estado": (
            row.get(
                "estado"
            )
        ),
        "senia_estado": (
            senia_estado
        ),
        "senia_monto": (
            senia_requerida
        ),
        "senia_pagada_monto": (
            transferido
        ),
        "senia_pendiente_monto": (
            row.get(
                "senia_pendiente_monto"
            )
        ),
        "senia_efectivo_pendiente": (
            cash_due
        ),
        "payment_method": (
            row.get(
                "payment_method"
            )
        ),
        "monto_pendiente": (
            monto_pendiente
        ),
        "con_quincho": (
            con_quincho
        ),
        "quincho": (
            quincho
        ),
        "quincho_hora_inicio": (
            quincho_hora_inicio
            if con_quincho
            else ""
        ),
        "quincho_duracion_horas": (
            quincho_duracion
            if con_quincho
            else None
        ),
        "quincho_precio_total": (
            quincho_price
            if con_quincho
            else 0
        ),
        "reserva": (
            row
        ),
        "reserva_verificada": (
            row
        ),
        "booking_confirmed": (
            firme
        ),
        "final_state_contract": True,
    })

    observation[
        "verified_facts"
    ] = {
        **dict(
            observation.get(
                "verified_facts"
            )
            or {}
        ),
        "reservation_reprogrammed": (
            dict(
                data
            )
        ),
        "final_reservation_state": (
            dict(
                data
            )
        ),
    }

    # ==========================================================
    # BASE
    # ==========================================================

    lines = [
        "✅ Listo, reprogramé tu turno.",
        "",
        f"📅 Día: {dia}",
        (
            f"{_court_booking_summary_label(cancha)} de "
            f"{rango_horario_texto(hora, duracion)}"
        ),
        f"💲 {_fmt_precio(court_price)}",
    ]

    if con_quincho:

        lines.extend([
            "",
            (
                f"🔥 Quincho/parrilla: "
                f"{quincho} de "
                f"{rango_horario_texto(quincho_hora_inicio, quincho_duracion)}"
            ),
            (
                f"💲 "
                f"{_fmt_precio(quincho_price)}"
            ),
        ])

    lines.extend([
        "",
        f"💰 Total: {_fmt_precio(precio_total)}",
    ])

    # ==========================================================
    # SEÑA PAGADA
    # ==========================================================

    if senia_estado == "pagada":

        lines.extend([
            "✅ Seña: pagada",
            (
                "💸 Saldo pendiente: "
                f"{_fmt_precio(monto_pendiente)}"
            ),
            "",
            (
                "✅ El turno continúa firme. "
                "No necesitás enviar otro comprobante."
            ),
        ])

        return "\n".join(
            lines
        ).strip()

    # ==========================================================
    # PAGO MIXTO — TURNO FIRME
    # ==========================================================

    if (
        senia_estado
        == "parcial_efectivo_pendiente"
        or (
            firme
            and "transferencia"
            in str(
                row.get(
                    "payment_method"
                )
                or ""
            ).casefold()
            and cash_due > 0
        )
    ):

        lines.extend([
            (
                "💵 Seña requerida: "
                f"{_fmt_precio(senia_requerida)}"
            ),
            (
                "💳 Transferencia recibida: "
                f"{_fmt_precio(transferido)}"
            ),
            (
                "💵 Diferencia de la seña para "
                "pagar en efectivo: "
                f"{_fmt_precio(cash_due)}"
            ),
            (
                "💸 Total pendiente para abonar "
                "en el complejo: "
                f"{_fmt_precio(monto_pendiente)}"
            ),
            "",
            (
                "✅ El turno continúa firme. "
                "No necesitás enviar otro comprobante."
            ),
        ])

        return "\n".join(
            lines
        ).strip()

    # ==========================================================
    # TRANSFERENCIA PARCIAL
    # ==========================================================

    if (
        senia_estado
        == "parcial"
        and transferido > 0
    ):

        lines.extend([
            (
                "💵 Seña requerida: "
                f"{_fmt_precio(senia_requerida)}"
            ),
            (
                "💳 Transferencia recibida: "
                f"{_fmt_precio(transferido)}"
            ),
            (
                "💵 Falta completar de la seña: "
                f"{_fmt_precio(senia_faltante)}"
            ),
            (
                "💸 Total pendiente: "
                f"{_fmt_precio(monto_pendiente)}"
            ),
        ])

        if senia_faltante > 0:

            lines.extend([
                "",
                (
                    "Si querés completar la seña "
                    "por transferencia, podés enviar "
                    f"{_fmt_precio(senia_faltante)} "
                    f"al alias {PAYMENT_ALIAS} y "
                    "mandarme el comprobante."
                ),
                (
                    "También podés indicarme si preferís "
                    "completar esa diferencia en efectivo."
                ),
            ])

        return "\n".join(
            lines
        ).strip()

    # ==========================================================
    # SEÑA COMPLETA EN EFECTIVO
    # ==========================================================

    if (
        senia_estado
        == "pendiente_efectivo"
    ):

        lines.extend([
            (
                "💵 Seña requerida: "
                f"{_fmt_precio(senia_requerida)}"
            ),
            (
                "💵 Forma de pago de la seña: "
                "efectivo"
            ),
            (
                "💸 Total pendiente: "
                f"{_fmt_precio(monto_pendiente)}"
            ),
            "",
            (
                "La modalidad de pago en efectivo "
                "sigue registrada. "
                f"Te esperamos en {BUSINESS_ADDRESS}."
            ),
            (
                f"⏳ Como modificamos el turno, reinicié el bloqueo por "
                f"{PENDING_DEPOSIT_HOLD_MINUTES} minutos desde ahora."
            ),
        ])

        return "\n".join(
            lines
        ).strip()

    # La seña pendiente pertenece a la misma reserva lógica. V114 conserva el
    # settlement, pero toda modificación efectiva de un booking todavía pendiente
    # inicia un lease NUEVO de PENDING_DEPOSIT_HOLD_MINUTES.
    if REQUIRES_DEPOSIT:
        lines.extend([
            f"💵 Seña pendiente: {_fmt_precio(senia_faltante or senia_requerida)}",
            f"💸 Saldo pendiente: {_fmt_precio(monto_pendiente)}",
            "",
            "🧾 La seña pendiente sigue asociada a esta misma reserva.",
            (
                f"⏳ Como modificamos el turno, reinicié el bloqueo por "
                f"{PENDING_DEPOSIT_HOLD_MINUTES} minutos desde ahora."
            ),
        ])
        return "\n".join(lines).strip()

    lines.extend([
        (
            "💸 Saldo pendiente: "
            f"{_fmt_precio(monto_pendiente)}"
        ),
        "",
        "✅ El turno continúa firme.",
    ])

    return "\n".join(
        lines
    ).strip()


def _agent_v2_verified_terminal_template(
    observations: List[Dict],
) -> str:
    """
    Salida exacta para WRITEs cuyo estado final
    ya fue verificado en Python.
    """
    handoff = next((
        obs
        for obs in reversed(
            observations
            or []
        )
        if (
            obs.get("tool")
            == "solicitar_handoff_humano"
            and (
                obs.get("ok")
                or (
                    obs.get("data")
                    or {}
                ).get(
                    "handoff_registered"
                )
            )
        )
    ), None)

    if handoff:
        return str(
            (
                handoff.get("data")
                or {}
            ).get("respuesta")
            or ""
        ).strip()

    cash_selection = (
        _agent_v2_successful_cash_selection_observation(
            observations
        )
    )

    if cash_selection:
        return (
            build_agent_v2_cash_selection_message(
                cash_selection
            ).strip()
        )

    payment = (
        _agent_v2_successful_payment_observation(
            observations
        )
    )

    if payment:
        return (
            build_agent_v2_payment_confirmation_message(
                payment
            ).strip()
        )

    # ==========================================================
    # REPROGRAMACIÓN
    # ==========================================================
    #
    # Antes esta operación NO tenía terminal template.
    #
    # Terminaba cayendo en:
    #
    # "Listo, pasé tu turno para..."
    #
    # y perdía:
    # - nuevo pedido de seña
    # - alias
    # - resumen
    # - total
    # - saldo
    #
    # Ahora reprogramar_reserva tiene exactamente
    # la misma autoridad terminal que crear_reserva.
    # ==========================================================

    reprogrammed = next((
        obs
        for obs in reversed(
            observations
            or []
        )
        if (
            obs.get("tool")
            == "reprogramar_reserva"
            and obs.get("ok")
            and obs.get("status")
            == "success"
        )
    ), None)

    if reprogrammed:
        message = (
            build_agent_v2_reprogrammed_reservation_message(
                reprogrammed
            ).strip()
        )

        if message:
            print(
                "   🧾 [AgentV2 REPROGRAM TEMPLATE] "
                "reserva reprogramada → "
                "estado final + seña/resumen determinista"
            )

            return message

    multi_created = (
        _agent_v2_successful_multiple_create_observation(
            observations
        )
    )

    if multi_created:
        return (
            build_agent_v2_multiple_created_message(
                multi_created
            ).strip()
        )

    quincho_change = (
        _agent_v2_successful_quincho_change_observation(
            observations
        )
    )

    if quincho_change:
        return (
            build_agent_v2_quincho_change_message(
                quincho_change
            ).strip()
        )

    created = (
        _agent_v2_successful_create_observation(
            observations
        )
    )

    if created:
        return (
            build_agent_v2_created_reservation_message(
                created
            ).strip()
        )

    return ""


def _agent_v2_apply_released_booking_rebook_reciprocity(
    response: str,
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> str:
    """
    Humaniza una reactivación REAL de un hold vencido.

    No analiza palabras del usuario. Sólo actúa cuando Perception ya vinculó
    semánticamente el turno a ``released_booking_rebook`` y una tool
    ``crear_reserva`` terminó con éxito.
    """
    current = str(response or "").strip()
    if not current:
        return current

    structured_rebook = bool(
        (perception or {}).get("answers_pending_field")
        == "released_booking_rebook"
        or any(
            str((act or {}).get("act_id") or "")
            == "released_booking_rebook_acceptance"
            for act in _agent_v2_authoritative_semantic_acts(
                perception or {}
            )
            if isinstance(act, dict)
        )
    )

    if not structured_rebook:
        return current

    recreated = any(
        obs.get("tool") == "crear_reserva"
        and obs.get("ok")
        and obs.get("status") == "success"
        for obs in (observations or [])
        if isinstance(obs, dict)
    )

    if not recreated:
        # Si el slot ya no estaba libre, jamás prometemos esperar un pago.
        return current

    prefix = (
        "Dale, te espero el comprobante. "
        "Volví a bloquear este turno para vos."
    )

    if current.startswith(prefix):
        return current

    return f"{prefix}\n\n{current}"


def _agent_v2_deterministic_response_kind(
    response: str,
    mensaje: str,
    world: Dict,
    observations: List[Dict],
    goals: Dict,
    perception: Dict,
) -> str:
    """Identifica builders Python exactos que no necesitan otro juez LLM."""
    actual = str(response or "").strip()
    if not actual:
        return ""

    candidates: List[Tuple[str, str]] = []
    exact_availability = _agent_v2_verified_exact_availability_response(goals, observations, world, perception)
    if exact_availability:
        candidates.append(("exact_slot_confirmation_template", exact_availability))
    unavailable_day_obs = next((
        obs for obs in reversed(observations or [])
        if obs.get("tool") == "consultar_disponibilidad"
        and obs.get("status") == "unavailable"
        and (obs.get("data") or {}).get("razon") == "sin_hora_especifica"
        and not (obs.get("data") or {}).get("horas_disponibles")
    ), None)
    if unavailable_day_obs:
        candidates.append((
            "no_availability_template",
            _agent_v2_format_availability_observation(
                unavailable_day_obs.get("data") or {}
            ),
        ))
    terminal = _agent_v2_verified_terminal_template(observations)
    if terminal:
        candidates.append(("terminal_tool_template", terminal))

    missing_input = _agent_v2_verified_missing_input_response(
        observations,
        world,
    )
    if missing_input:
        candidates.append(("missing_input_template", missing_input))

    asap_obs = _agent_v2_asap_availability_observation(observations)
    if asap_obs:
        candidates.append((
            "asap_availability_template",
            _agent_v2_append_nba_question(
                build_agent_v2_asap_availability_message(mensaje, asap_obs),
                world,
            ),
        ))

    detailed = build_agent_v2_detailed_availability_price_message(
        mensaje,
        world,
        observations,
        perception,
    )
    if detailed:
        candidates.append((
            "availability_template",
            _agent_v2_append_nba_question(detailed, world),
        ))

    policy_obs = _agent_v2_policy_contract_observation(observations)
    if policy_obs:
        candidates.append((
            "config_policy_template",
            _agent_v2_expected_policy_response_with_nba(policy_obs, world),
        ))

    if (goals or {}).get("primary_goal") == "saludar" and not observations:
        candidates.append((
            "welcome_template",
            _agent_v2_append_nba_question(build_agent_v2_welcome_message(world), world),
        ))

    price_quote = build_agent_v2_price_quote_message(observations)
    if price_quote and not any(
        obs.get("tool") in {"consultar_disponibilidad", "consultar_disponibilidad_multiple"}
        and obs.get("ok")
        for obs in observations or []
    ):
        candidates.append(("price_quote_template", price_quote))

    fallback = _agent_v2_fallback_response(
        goals or {"goals": []},
        observations,
        world,
        perception or {},
    )
    if fallback:
        candidates.append((
            "deterministic_fallback",
            _agent_v2_append_nba_question(fallback, world),
        ))

    for kind, expected in candidates:
        if expected and actual == str(expected).strip():
            return kind
    return ""


async def grounding_respuesta_agent_v2(
    response: str,
    mensaje: str,
    world: Dict,
    observations: List[Dict],
    goals: Dict = None,
    perception: Dict = None,
    protect_trusted_templates: bool = True,
) -> str:
    """
    Audita grounding + contrato de diálogo.

    ARQUITECTURA:

        HECHOS DETERMINISTAS
                ↓
        REDACCIÓN NATURAL IA
                ↓
        GUARD PYTHON DE MONTOS
                ↓
        VALIDATOR FINAL

    Para cotizaciones READ permitimos que la IA humanice la respuesta.

    Para operaciones terminales WRITE seguimos preservando las
    plantillas deterministas verificadas.
    """

    if (
        not AGENT_V2_GROUNDING_CHECK
        or not response
    ):
        return response

    original_response = str(
        response
        or ""
    ).strip()

    # =========================================================
    # DETECTAR COTIZACIÓN DE CANCHA
    # =========================================================

    price_quote_observations = [
        obs
        for obs in (observations or [])
        if (
            isinstance(obs, dict)
            and obs.get("tool") == "consultar_precio"
            and obs.get("ok")
            and (
                (obs.get("data") or {}).get("incluir_cancha")
                or (obs.get("data") or {}).get("incluir_quincho")
            )
        )
    ]

    quote_obs = (
        price_quote_observations[-1]
        if price_quote_observations
        else None
    )

    has_availability = any(
        (
            obs.get("tool")
            in {
                "consultar_disponibilidad",
                "consultar_disponibilidad_multiple",
            }

            and obs.get(
                "ok"
            )
        )

        for obs
        in observations or []
    )

    trusted_terminal = (
        _agent_v2_verified_terminal_template(
            observations
        )
    )

    # =========================================================
    # HUMANIZAR SOLO READ PRICE QUOTES
    # =========================================================

    quote_scope_count = 0

    if quote_obs:
        quote_data = quote_obs.get("data") or {}
        quote_scope_count = int(bool(quote_data.get("incluir_cancha"))) + int(
            bool(quote_data.get("incluir_quincho"))
        )

    humanize_price_quote = bool(
        quote_obs
        and len(price_quote_observations) == 1
        and quote_scope_count == 1
        and not has_availability
        and not trusted_terminal
    )

    deterministic_kind = (
        _agent_v2_deterministic_response_kind(
            original_response,
            mensaje,
            world,
            observations,
            goals
            or {
                "goals": []
            },
            perception
            or {},
        )
    )

    # =========================================================
    # MINIMAL LLM MODE
    # =========================================================
    #
    # Las plantillas siguen saltándose Grounding LLM...
    #
    # EXCEPTO price_quote:
    # ahí queremos deliberadamente lenguaje IA.
    # =========================================================

    if (
        AGENT_V2_MINIMAL_LLM_MODE
        and deterministic_kind
        and not humanize_price_quote
    ):

        print(
            "   [AgentV2 GROUNDING BUDGET] "
            "Python verifico "
            f"{deterministic_kind}; "
            "Grounding LLM omitido"
        )

        return original_response

    # =========================================================
    # TERMINAL WRITES
    # =========================================================

    if (
        protect_trusted_templates
        and trusted_terminal
        and original_response
        == trusted_terminal
    ):

        print(
            "   🔒 [AgentV2 GROUNDING] "
            "plantilla terminal confiable → no modificar"
        )

        return original_response

    # =========================================================
    # ASAP
    # =========================================================

    asap_obs = (
        _agent_v2_asap_availability_observation(
            observations
        )
    )

    if (
        protect_trusted_templates
        and asap_obs
    ):

        expected_asap = (
            build_agent_v2_asap_availability_message(
                mensaje,
                asap_obs,
            )
        )

        if (
            expected_asap
            and original_response
            == expected_asap.strip()
        ):

            print(
                "   🔒 [AgentV2 GROUNDING] "
                "plantilla ASAP confiable → no modificar"
            )

            return original_response

    # =========================================================
    # DISPONIBILIDAD DETALLADA
    # =========================================================

    detailed_availability = (
        build_agent_v2_detailed_availability_price_message(
            mensaje,
            world,
            observations,
        )
    )

    if (
        protect_trusted_templates
        and detailed_availability
        and original_response
        == detailed_availability.strip()
    ):

        print(
            "   🔒 [AgentV2 GROUNDING] "
            "plantilla detallada de disponibilidad "
            "confiable → no modificar"
        )

        return original_response

    # =========================================================
    # POLICY FACT
    # =========================================================

    policy_obs = (
        _agent_v2_policy_contract_observation(
            observations
        )
    )

    if (
        protect_trusted_templates
        and policy_obs
    ):

        expected_policy = (
            build_agent_v2_policy_fact_message(
                policy_obs
            )
        )

        expected_policy_with_nba = (
            _agent_v2_expected_policy_response_with_nba(
                policy_obs,
                world,
            )
        )

        if (
            expected_policy
            and original_response
            in {
                expected_policy.strip(),
                expected_policy_with_nba.strip(),
            }
        ):

            print(
                "   🔒 [AgentV2 GROUNDING] "
                "Policy Fact Contract + NBA confiable "
                "→ no reescribir hechos"
            )

            return original_response

    # =========================================================
    # FACT PACK
    # =========================================================

    fact_pack = (
        _agent_v2_response_facts(
            world,
            observations,
            goals
            or {
                "goals": []
            },
            perception,
        )
    )

    authorized_questions = (
        fact_pack.get(
            "authorized_questions"
        )
        or []
    )

    # =========================================================
    # PREGUNTA STATEFUL EXACTA
    # =========================================================
    #
    # Si NBA decidió que corresponde preguntar día/hora,
    # la IA puede humanizar todo lo anterior, pero debe
    # terminar con esta pregunta.
    # =========================================================

    exact_stateful_question = ""

    current_nba_questions = [
        question

        for question
        in (
            world.get(
                "open_questions"
            )
            or []
        )

        if (
            question.get(
                "source"
            )
            == "next_best_action_current_turn"

            and not question.get(
                "context_only"
            )
        )
    ]

    if current_nba_questions:

        exact_stateful_question = (
            _agent_v2_render_open_question(
                current_nba_questions[-1]
            )
        )

    # =========================================================
    # DURACIONES AUTORIZADAS
    # =========================================================

    allowed_turn_durations = []

    for duration in (
        ALLOWED_TURN_DURATIONS
        or []
    ):

        try:
            allowed_turn_durations.append(
                float(
                    duration
                )
            )

        except (
            TypeError,
            ValueError,
        ):
            continue

    # =========================================================
    # IA: GROUNDING + HUMANIZACIÓN
    # =========================================================

    try:

        resp = await call_openai_async(
            model=OPENAI_MODEL,

            messages=[
                {
                    "role": "system",

                    "content": (
                        "Sos el auditor de grounding y redacción final "
                        "de un agente IA de reservas por WhatsApp.\n\n"

                        "========================================\n"
                        "REGLAS DE VERDAD\n"
                        "========================================\n"

                        "- FACT_PACK manda. No inventes ni recalcules precios, "
                        "días, horarios, canchas, reservas o pagos.\n"

                        "- price_quotes y availability contienen hechos "
                        "verificados. Preservá sus datos relevantes.\n"

                        "- Una seña cotizada dentro de price_quotes "
                        "(senia_monto / senia_porcentaje) SÍ puede mencionarse "
                        "antes de crear una reserva porque forma parte de la "
                        "cotización comercial.\n"

                        "- Si payment_context_allowed=false, NO agregues alias, "
                        "instrucciones para transferir, afirmaciones de pago "
                        "realizado ni afirmaciones de reserva confirmada.\n"

                        "- Informar cuánto sería la seña NO significa que el "
                        "usuario ya tenga que pagarla ni que exista una reserva.\n"

                        "- policy_fact_contracts son autoritativos.\n"

                        "- Solo podés hacer preguntas listadas en "
                        "AUTHORIZED_QUESTIONS.\n"

                        "- Nunca afirmes que una reserva quedó creada si no "
                        "existe una tool WRITE exitosa que lo demuestre.\n\n"

                        "========================================\n"
                        "REGLAS DE LENGUAJE\n"
                        "========================================\n"

                        "- Español argentino natural, usando voseo.\n"

                        "- Soná como un encargado humano de una cancha, no "
                        "como un sistema de facturación.\n"

                        "- Respondé primero exactamente lo que preguntó el "
                        "usuario y después continuá el flujo.\n"

                        "- Para una pregunta simple usá normalmente entre "
                        "1 y 3 bloques cortos.\n"

                        "- No conviertas cada dato en una oración separada si "
                        "puede expresarse naturalmente.\n"

                        "- Evitá frases administrativas como "
                        "'Para confirmar, la seña es del 50%: $20.000'.\n"

                        "- Preferí expresiones naturales como "
                        "'la seña para confirmar sería de $20.000'.\n"

                        "- No repitas saludos en follow-ups.\n"

                        "- No repitas innecesariamente información que el "
                        "usuario acaba de recibir.\n"

                        "- Como máximo UNA pregunta final.\n\n"

                        "========================================\n"
                        "HUMANIZE_PRICE_QUOTE\n"
                        "========================================\n"

                        "- Si HUMANIZE_PRICE_QUOTE=true, NO conserves "
                        "literalmente la plantilla determinista si suena "
                        "robótica.\n"

                        "- La plantilla es un ESQUELETO FACTUAL, no una "
                        "obligación de redacción.\n"

                        "- Podés cambiar completamente la forma de decir los "
                        "hechos, pero NO sus valores.\n"

                        "- Si el usuario pregunta si puede reservar cierta "
                        "duración y esa duración aparece en "
                        "ALLOWED_TURN_DURATIONS, respondé primero de forma "
                        "natural que sí se puede.\n"

                        "- Ejemplo conceptual: "
                        "'Sí, claro. Se puede reservar por 2 horas.'\n"

                        "- Después informá naturalmente el total cotizado.\n"

                        "- Si existe senia_monto, informá naturalmente cuánto "
                        "sería la seña para confirmar.\n"

                        "- NO agregues instrucciones de pago ni alias.\n"

                        "- Si EXACT_STATEFUL_QUESTION no está vacío, terminá "
                        "con ESA pregunta exacta y no agregues otra pregunta.\n\n"

                        "Respondé SOLO JSON:\n"

                        "{"
                        "\"ok\":true|false,"
                        "\"response\":\"texto final para WhatsApp\","
                        "\"reason\":\"breve\""
                        "}"
                    ),
                },

                {
                    "role": "user",

                    "content": json.dumps(
                        {
                            "message": mensaje,

                            "response": (
                                original_response
                            ),

                            "fact_pack": (
                                fact_pack
                            ),

                            "authorized_questions": (
                                authorized_questions
                            ),

                            "HUMANIZE_PRICE_QUOTE": (
                                humanize_price_quote
                            ),

                            "EXACT_STATEFUL_QUESTION": (
                                exact_stateful_question
                            ),

                            "ALLOWED_TURN_DURATIONS": (
                                allowed_turn_durations
                            ),
                        },

                        ensure_ascii=False,

                        default=str,
                    ),
                },
            ],

            # Un poco de libertad estilística únicamente
            # para las cotizaciones.
            temperature=(
                0.25
                if humanize_price_quote
                else 0.0
            ),

            max_tokens=520,

            response_format={
                "type": "json_object"
            },
        )

        register_cost(
            resp
        )

        data = _loads_llm_json_object(
            resp
            .choices[0]
            .message
            .content
            .strip()
        )

        corrected = str(
            data.get(
                "response"
            )
            or original_response
        ).strip()

        if not data.get(
            "ok",
            True,
        ):

            print(
                "   🛡️ [AgentV2 GROUNDING] "
                "respuesta corregida: "
                f"{data.get('reason')}"
            )

        # =====================================================
        # PRICE QUOTE PYTHON GUARD
        # =====================================================

        if humanize_price_quote:

            # La pregunta stateful elegida por NBA debe
            # permanecer presente.
            if (
                exact_stateful_question
                and exact_stateful_question
                not in corrected
            ):

                print(
                    "   🧱 [AgentV2 PRICE HUMANIZER] "
                    "faltó pregunta stateful exacta "
                    "→ fallback determinista"
                )

                return original_response

            # Los montos siguen bajo autoridad de Python.
            if not _agent_v2_price_quote_text_is_safe(
                corrected,
                observations,
            ):

                print(
                    "   🧱 [AgentV2 PRICE HUMANIZER] "
                    "montos omitidos o inventados "
                    "→ fallback determinista"
                )

                return original_response

            print(
                "   ✨ [AgentV2 PRICE HUMANIZER] "
                "hechos deterministas + lenguaje IA"
            )

        # =====================================================
        # ECHO GUARD
        # =====================================================

        if (
            str(
                (
                    perception
                    or {}
                ).get(
                    "speech_act"
                )
                or ""
            )
            == "ask"

            and normalizar_texto_ia(
                corrected
            )
            == normalizar_texto_ia(
                mensaje
            )
        ):

            print(
                "   🚫 [AgentV2 ECHO GUARD] "
                "respuesta == pregunta del usuario "
                "→ fallback grounded"
            )

            safe = (
                _agent_v2_fallback_response(
                    goals
                    or {
                        "goals": []
                    },

                    observations,

                    world,

                    perception
                    or {},
                )
            )

            return (
                _agent_v2_append_nba_question(
                    safe,
                    world,
                )
            )

        if (perception is not None and _agent_v2_is_read_only_turn(perception)
            and data.get("ok") is True and corrected == original_response):
            perception["_read_grounding_validated_response"] = corrected
        return corrected or original_response

    except Exception as e:

        print(
            f"   ⚠️ [AgentV2 GROUNDING] {e}"
        )

        return original_response

def _agent_v2_visual_response_issues(
    texto: str,
    recent_dialogue: Optional[List[Dict[str, Any]]] = None,
    current_user_message: str = "",
) -> List[str]:
    """Detecta problemas visuales/redundancias obvias antes del envío.

    No decide hechos ni intención operativa.
    Solo audita presentación WhatsApp y repetición evidente
    respecto del diálogo reciente.
    """
    t = str(texto or "").strip()

    if not t:
        return [
            "respuesta_vacia"
        ]

    issues: List[str] = []

    lines = [
        line.rstrip()
        for line in t.splitlines()
    ]

    nonempty = [
        line.strip()
        for line in lines
        if line.strip()
    ]

    # WhatsApp no debería abrir negrita en una línea
    # y cerrarla en otra.
    #
    # Ejemplo roto:
    # - *10:00
    # - 11:00*
    if any(
        line.count("*") % 2
        for line in nonempty
    ):
        issues.append(
            "asteriscos_desbalanceados_por_linea"
        )

    # Una parrilla larga con un horario por renglón
    # es difícil de leer.
    time_only_lines = 0

    for line in nonempty:
        clean = re.sub(
            r"^[\-•·]+\s*",
            "",
            line,
        ).strip()

        clean = clean.strip("*").strip()

        if re.fullmatch(
            r"\d{1,2}(?::\d{2}|\s*hs)?",
            clean,
            flags=re.IGNORECASE,
        ):
            time_only_lines += 1

    if time_only_lines >= 5:
        issues.append(
            "horarios_fragmentados_uno_por_linea"
        )

    if re.search(
        r"\n{4,}",
        t,
    ):
        issues.append(
            "exceso_de_lineas_vacias"
        )

    # Si el usuario solo consultó una duración
    # y la respuesta vuelve a copiar muchos horarios
    # ya mostrados, es redundante.
    duration_question = bool(
        _agent_v2_extract_duration_candidates(
            current_user_message
        )
    )

    if (
        duration_question
        and recent_dialogue
    ):
        last_assistant = ""

        for item in reversed(
            recent_dialogue
        ):
            if not isinstance(item, dict):
                continue

            if str(
                item.get("role") or ""
            ).lower() in {
                "assistant",
                "agente",
                "bot",
            }:
                last_assistant = str(
                    item.get("content") or ""
                )

                break

        if last_assistant:
            current_times = set(
                re.findall(
                    r"\b(?:[01]?\d|2[0-3]):[0-5]\d\b",
                    t,
                )
            )

            previous_times = set(
                re.findall(
                    r"\b(?:[01]?\d|2[0-3]):[0-5]\d\b",
                    last_assistant,
                )
            )

            if (
                len(
                    current_times.intersection(
                        previous_times
                    )
                )
                >= 6
            ):
                issues.append(
                    "repite_parrilla_horaria_en_followup_de_duracion"
                )

            greeting_tokens = (
                "¡hola!",
                "hola!",
                "buenas tardes",
                "buenas noches",
                "buen día",
                "buen dia",
            )

            current_norm = (
                normalizar_texto_ia(t)
            )

            previous_norm = (
                normalizar_texto_ia(
                    last_assistant
                )
            )

            if (
                any(
                    token.strip("¡!")
                    in current_norm
                    for token
                    in greeting_tokens
                )
                and any(
                    token.strip("¡!")
                    in previous_norm
                    for token
                    in greeting_tokens
                )
                and len(
                    str(
                        current_user_message
                        or ""
                    ).split()
                )
                <= 12
            ):
                issues.append(
                    "saludo_repetido_en_followup_corto"
                )

    return list(
        dict.fromkeys(
            issues
        )
    )


def _agent_v2_response_validation_context(
    mensaje: str,
    response: str,
    world: Dict,
    observations: List[Dict],
    goals: Dict,
    perception: Dict,
    status: str,
) -> Dict[str, Any]:
    """Contexto compacto y verificable para el juez final semántico + visual."""
    fact_pack = _agent_v2_response_facts(
        world,
        observations,
        goals or {
            "goals": []
        },
        perception or {},
    )

    recent_dialogue = []

    for item in (
        world.get("history")
        or []
    )[-8:]:
        if not isinstance(item, dict):
            continue

        role = str(
            item.get("role") or ""
        ).strip().lower()

        content = str(
            item.get("content") or ""
        ).strip()

        if role and content:
            recent_dialogue.append({
                "role": role,
                "content": content[:1800],
            })

    visual_issues = (
        _agent_v2_visual_response_issues(
            response,
            recent_dialogue=recent_dialogue,
            current_user_message=mensaje,
        )
    )

    return {
        "current_user_message": mensaje,
        "response_to_validate": response,
        "turn_status": status,
        "goals": goals or {},
        "semantic_frame": (
            _agent_v2_semantic_frame(
                perception or {}
            )
        ),
        "pending_relation": (
            perception or {}
        ).get(
            "pending_relation"
        ),
        "current_turn_read_only": bool(
            (
                perception or {}
            ).get(
                "current_turn_read_only"
            )
        ),
        "current_turn_response_payload": (
            _agent_v2_current_turn_response_payload(
                perception or {}
            )
        ),
        "pending_questions": (
            fact_pack.get(
                "authorized_questions"
            )
            or []
        ),
        "recent_dialogue": (
            recent_dialogue
        ),
        "visual_audit": {
            "issues": visual_issues,
            "format_score": (
                puntaje_formato_whatsapp(
                    response
                )
            ),
            "line_count": len(
                str(
                    response or ""
                ).splitlines()
            ),
        },
        "tool_observations": [
            {
                "tool": obs.get("tool"),
                "ok": bool(
                    obs.get("ok")
                ),
                "status": obs.get(
                    "status"
                ),
                "data": (
                    obs.get("data")
                    or {}
                ),
            }
            for obs in (
                observations or []
            )
            if isinstance(
                obs,
                dict,
            )
        ],
        "fact_pack": {
            "agent_identity": (
                fact_pack.get(
                    "agent_identity"
                )
            ),
            "booking_onboarding": (
                fact_pack.get(
                    "booking_onboarding"
                )
            ),
            "business": (
                fact_pack.get(
                    "business"
                )
            ),
            "active_reservations": (
                fact_pack.get(
                    "active_reservations"
                )
            ),
            "price_quotes": (
                fact_pack.get(
                    "price_quotes"
                )
            ),
            "availability": (
                fact_pack.get(
                    "availability"
                )
            ),
            "reservation_query_results": (
                fact_pack.get(
                    "reservation_query_results"
                )
            ),
            "write_results": (
                fact_pack.get(
                    "write_results"
                )
            ),
            "policy_fact_contracts": (
                fact_pack.get(
                    "policy_fact_contracts"
                )
            ),
            "authorized_questions": (
                fact_pack.get(
                    "authorized_questions"
                )
            ),
            "payment_context_allowed": (
                fact_pack.get(
                    "payment_context_allowed"
                )
            ),
            "payment_confirmed": (
                fact_pack.get(
                    "payment_confirmed"
                )
            ),
        },
    }


async def seleccionar_mejor_respuesta_agent_v2(
    original: str,
    regenerated: str,
    mensaje: str,
    world: Dict,
    observations: List[Dict],
    goals: Dict,
    perception: Dict,
    status: str,
    original_validation: Optional[Dict[str, Any]] = None,
) -> str:
    """Valida y compara la respuesta inicial contra la regenerada.

    Ninguna regeneración llega al usuario por el solo hecho de haber sido
    producida. El juez ve el mismo escenario y FACT_PACK para ambas, declara
    cuáles son válidas y elige la mejor. Si no puede demostrar una ganadora,
    falla cerrado hacia la plantilla determinista basada en Observations.
    """
    original = str(original or "").strip()
    regenerated = str(regenerated or "").strip()
    original_money_valid = _agent_v2_monetary_claims_valid(original, observations)
    regenerated_money_valid = _agent_v2_monetary_claims_valid(regenerated, observations)
    if not regenerated_money_valid:
        return _agent_v2_enforce_monetary_claims(original, observations, world)
    if not original_money_valid:
        # The comparator only ever sees financially grounded candidates.
        original = _agent_v2_enforce_monetary_claims(original, observations, world)
    if not regenerated or regenerated == original:
        return original

    original_context = _agent_v2_response_validation_context(
        mensaje, original, world, observations, goals, perception, status,
    )
    regenerated_context = _agent_v2_response_validation_context(
        mensaje, regenerated, world, observations, goals, perception, status,
    )
    original_visual_issues = list(
        ((original_context.get("visual_audit") or {}).get("issues")) or []
    )
    regenerated_visual_issues = list(
        ((regenerated_context.get("visual_audit") or {}).get("issues")) or []
    )

    try:
        comparison_resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el selector FINAL de respuestas de un agente de reservas "
                        "por WhatsApp. Compará RESPONSE_ORIGINAL y RESPONSE_REGENERATED "
                        "contra el MISMO escenario actual, FACT_PACK, tool_observations, "
                        "preguntas autorizadas y diálogo reciente.\n\n"
                        "Primero validá cada respuesta por separado. Una respuesta es "
                        "inválida si contradice u omite el pedido actual, revive contexto "
                        "viejo, inventa disponibilidad/precio/reserva/pago, afirma una "
                        "operación sin tool exitosa, pregunta algo no autorizado, repite "
                        "un dato ya aportado o tiene defectos visuales objetivos.\n"
                        "Elegí una respuesta válida sobre una inválida. Si ambas son "
                        "válidas, elegí la más pertinente, completa, clara y breve para "
                        "este escenario, preservando detalles operativos verificados. "
                        "Si ninguna es válida, elegí neither. No reescribas respuestas.\n"
                        "Respondé SOLO JSON: "
                        '{"winner":"original|regenerated|neither",'
                        '"original_valid":true|false,'
                        '"regenerated_valid":true|false,'
                        '"reason":"breve"}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "current_user_message": mensaje,
                            "turn_status": status,
                            "original_validator_result": original_validation or {},
                            "shared_scenario": {
                                "goals": original_context.get("goals"),
                                "semantic_frame": original_context.get("semantic_frame"),
                                "pending_relation": original_context.get("pending_relation"),
                                "current_turn_read_only": original_context.get("current_turn_read_only"),
                                "current_turn_response_payload": original_context.get("current_turn_response_payload"),
                                "pending_questions": original_context.get("pending_questions"),
                                "recent_dialogue": original_context.get("recent_dialogue"),
                                "tool_observations": original_context.get("tool_observations"),
                                "fact_pack": original_context.get("fact_pack"),
                            },
                            "response_original": original,
                            "response_original_visual_audit": original_context.get("visual_audit"),
                            "response_regenerated": regenerated,
                            "response_regenerated_visual_audit": regenerated_context.get("visual_audit"),
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=360,
            response_format={"type": "json_object"},
        )
        register_cost(comparison_resp)
        comparison = _loads_llm_json_object(
            comparison_resp.choices[0].message.content.strip()
        )
        winner = str(comparison.get("winner") or "neither").strip().casefold()
        original_valid = comparison.get("original_valid") is True
        regenerated_valid = comparison.get("regenerated_valid") is True

        # Los guards objetivos de Python tienen poder de veto aunque el juez los
        # pase por alto. No enviamos formato roto ni eco evidente.
        original_eligible = bool(original_valid and not original_visual_issues)
        regenerated_eligible = bool(regenerated_valid and not regenerated_visual_issues)

        if winner == "regenerated" and regenerated_eligible:
            selected = regenerated
        elif winner == "original" and original_eligible:
            selected = original
        elif regenerated_eligible and not original_eligible:
            selected = regenerated
            winner = "regenerated"
        elif original_eligible and not regenerated_eligible:
            selected = original
            winner = "original"
        else:
            selected = ""
            winner = "neither"

        print(
            "   🏆 [AgentV2 RESPONSE COMPARATOR] "
            f"winner={winner} original_valid={original_eligible} "
            f"regenerated_valid={regenerated_eligible} "
            f"reason={str(comparison.get('reason') or '')[:240]}"
        )
        if selected:
            return selected
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 RESPONSE COMPARATOR] "
            f"error; no envío la regeneración sin validar: {exc}"
        )

    deterministic = _agent_v2_fallback_response(
        goals or {"goals": []}, observations, world, perception or {},
    )
    deterministic = _agent_v2_append_nba_question(deterministic, world)
    deterministic = str(deterministic or "").strip()
    if deterministic:
        print(
            "   🛡️ [AgentV2 RESPONSE COMPARATOR] "
            "ninguna candidata demostró ser válida → fallback determinista"
        )
        return deterministic
    return original


async def validar_y_regenerar_respuesta_agent_v2(
    response: str,
    mensaje: str,
    world: Dict,
    observations: List[Dict],
    goals: Dict,
    perception: Dict,
    status: str,
    prospecto: Optional[Dict[str, Any]] = None,
) -> str:
    """Última barrera V2: pertinencia factual, continuidad y calidad visual."""
    response = _agent_v2_enforce_monetary_claims(response, observations, world)
    if (
        not AGENT_V2_RESPONSE_VALIDATOR_CHECK
        or not str(response or "").strip()
    ):
        return response

    original = str(
        response or ""
    ).strip()

    recent_dialogue = [
        item
        for item in (
            world.get("history")
            or []
        )[-8:]
        if isinstance(
            item,
            dict,
        )
    ]

    visual_issues = (
        _agent_v2_visual_response_issues(
            original,
            recent_dialogue=recent_dialogue,
            current_user_message=mensaje,
        )
    )

    deterministic_kind = (
        _agent_v2_deterministic_response_kind(
            original,
            mensaje,
            world,
            observations,
            goals or {
                "goals": []
            },
            perception or {},
        )
    )

    contextual_review_required = bool(
        deterministic_kind
        == "missing_input_template"
        and _agent_v2_requires_contextual_response_composition(
            perception or {}
        )
    )

    visual_review_required = bool(
        visual_issues
    )
    if (not visual_review_required and _agent_v2_is_read_only_turn(perception)
        and perception.get("_read_grounding_validated_response") == original):
        print("   [AgentV2 VALIDATOR BUDGET] READ ya validado contra facts; revisión duplicada omitida")
        return original

    # Las plantillas deterministas pueden saltarse
    # el LLM solo si también pasan el guard visual.
    if (
        AGENT_V2_MINIMAL_LLM_MODE
        and deterministic_kind
        and not contextual_review_required
        and not visual_review_required
    ):
        print(
            "   [AgentV2 VALIDATOR BUDGET] "
            "Python verifico "
            f"{deterministic_kind}; "
            "Validator LLM omitido"
        )

        return original

    if contextual_review_required:
        print(
            "   🔎 [AgentV2 SEMANTIC COVERAGE] "
            "pregunta determinista no cubre todo el turno "
            "→ Validator IA obligatorio"
        )

    if visual_review_required:
        print(
            "   🎨 [AgentV2 VISUAL VALIDATOR] "
            "revisión obligatoria: "
            + ", ".join(
                visual_issues
            )
        )

    context = (
        _agent_v2_response_validation_context(
            mensaje,
            original,
            world,
            observations,
            goals,
            perception,
            status,
        )
    )

    try:
        validation_resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el validador FINAL semántico y visual "
                        "de un agente IA de reservas de canchas por WhatsApp. "
                        "Evaluá la respuesta contra el ÚLTIMO mensaje, FACT_PACK, "
                        "las preguntas autorizadas y el diálogo reciente.\n\n"

                        "INVALIDÁ por CONTENIDO si: ignora o responde parcialmente "
                        "el pedido actual; retoma una fase vieja; pregunta algo que "
                        "el usuario ya dio; afirma una acción que ninguna tool completó; "
                        "contradice FACT_PACK; hace una pregunta fuera de "
                        "authorized_questions; o ante una consulta amplia de "
                        "disponibilidad oculta horarios verificados relevantes.\n"

                        "Si current_turn_response_payload contiene duración, fecha, "
                        "recurso, cambio, dominio o requested_fact, una respuesta que "
                        "solo repite la pregunta pendiente es inválida: primero debe "
                        "contestar ese contenido.\n\n"

                        "INVALIDÁ por PRESENTACIÓN si la salida se ve defectuosa en "
                        "WhatsApp: asteriscos de negrita abiertos en una línea y "
                        "cerrados en otra; horarios fragmentados artificialmente uno "
                        "por renglón; listas con bullets rotos; bloques vacíos excesivos; "
                        "saludo repetido en un follow-up corto; o una respuesta "
                        "innecesariamente larga/redundante para una pregunta simple.\n"

                        "Si RECENT_DIALOGUE muestra que el agente acaba de listar muchos "
                        "horarios y el usuario ahora solo pregunta si puede jugar/reservar "
                        "cierta duración, NO vuelvas a copiar toda la parrilla salvo que "
                        "el usuario la haya pedido de nuevo o exista una nueva observation "
                        "de disponibilidad necesaria para contestar. Lo correcto es "
                        "responder la duración de forma breve y luego hacer, como máximo, "
                        "una pregunta autorizada de continuidad.\n"

                        "Una respuesta breve de 1 a 3 bloques NO necesita emojis ni "
                        "listas para ser visualmente válida. No fuerces decoración.\n"

                        "No reescribas todavía. Respondé SOLO JSON: "
                        '{"es_valida":true|false,'
                        '"razon":"breve",'
                        '"sugerencia":"corrección concreta"}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        context,
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=420,
            response_format={
                "type": "json_object"
            },
        )

        register_cost(
            validation_resp
        )

        validation = (
            _loads_llm_json_object(
                validation_resp
                .choices[0]
                .message
                .content
                .strip()
            )
        )

    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 RESPONSE VALIDATOR] "
            f"error no fatal: {exc}"
        )

        # Si la IA auditora falla pero Python encontró
        # un problema visual, al menos se intenta formatear.
        if visual_issues:
            formatted = (
                await formatear_respuesta_whatsapp_con_ia(
                    mensaje,
                    original,
                    {},
                    prospecto,
                )
            )

            return str(
                formatted or original
            ).strip()

        return original

    # El guard determinista tiene poder de veto visual.
    if (
        bool(
            validation.get(
                "es_valida"
            )
        )
        and visual_issues
    ):
        validation = {
            **validation,
            "es_valida": False,
            "razon": (
                "problema visual objetivo: "
                + ", ".join(
                    visual_issues
                )
            ),
            "sugerencia": (
                "reformatear de forma breve, con asteriscos "
                "balanceados y sin repetir la parrilla horaria "
                "ya mostrada"
            ),
        }

    if bool(
        validation.get(
            "es_valida"
        )
    ):
        print(
            "   ✅ [AgentV2 RESPONSE VALIDATOR] "
            "respuesta pertinente y visualmente correcta"
        )

        return original

    reason = str(
        validation.get("razon")
        or "respuesta no pertinente"
    )[:500]

    suggestion = str(
        validation.get("sugerencia")
        or ""
    )[:700]

    trusted_terminal = (
        _agent_v2_verified_terminal_template(
            observations
        )
    )

    if (
        trusted_terminal
        and original == trusted_terminal
        and not visual_issues
    ):
        print(
            "   🔒 [AgentV2 RESPONSE VALIDATOR] "
            "falso positivo descartado → "
            "plantilla terminal verificada preservada "
            f"({reason})"
        )

        return original

    print(
        "   🔄 [AgentV2 RESPONSE VALIDATOR] "
        f"inválida → regenero: {reason}"
    )

    try:
        regeneration_resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        f"Sos {AGENT_NAME}, agente IA de reservas de "
                        f"{BUSINESS_NAME}. Corregí una respuesta rechazada "
                        "por el validador final.\n\n"

                        "REGLAS DE CONTENIDO:\n"

                        "- Respondé directamente el ÚLTIMO mensaje usando "
                        "únicamente FACT_PACK y tool_observations.\n"

                        "- Cubrí cada elemento de current_turn_response_payload "
                        "antes de cualquier continuidad.\n"

                        "- Para una duración consultada, verificá "
                        "FACT_PACK.business.duraciones_permitidas_horas o "
                        "policy_fact_contracts. Si está permitida, respondé eso "
                        "en una sola frase natural.\n"

                        "- No inventes disponibilidad, precio, reserva, pago, "
                        "cancha, día ni horario.\n"

                        "- Solo podés hacer preguntas incluidas en "
                        "authorized_questions.\n"

                        "- Si el agente ya mostró la parrilla de horarios en "
                        "RECENT_DIALOGUE y el usuario ahora solo consulta duración, "
                        "NO la repitas.\n\n"

                        "REGLAS VISUALES WHATSAPP:\n"

                        "- Priorizá brevedad para follow-ups simples: normalmente "
                        "1 a 3 bloques cortos.\n"

                        "- No repitas saludo si el agente ya saludó en el turno "
                        "anterior.\n"

                        "- Nunca abras *negrita* en una línea y la cierres en otra. "
                        "Cada línea debe tener asteriscos balanceados.\n"

                        "- Nunca pongas una parrilla larga con un horario por "
                        "bullet/renglón salvo pedido explícito del usuario.\n"

                        "- Si necesitás mostrar muchos horarios, usá el estilo de "
                        "plantilla: '🕐 Horarios disponibles:' y luego una sola "
                        "línea separada por comas y 'y'.\n"

                        "- RESPONSE_ORIGINAL sirve solo como referencia de los "
                        "bloques que estén bien. NO preserves una estructura que "
                        "el validador marcó como fea, redundante o rota.\n"

                        "- No agregues emojis por obligación a una respuesta breve.\n"

                        "Respondé SOLO JSON: "
                        '{"response":"texto exacto para WhatsApp"}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            **context,
                            "validator_reason": reason,
                            "validator_suggestion": suggestion,
                            "response_original": original,
                            "prospect": {
                                "name": (
                                    prospecto or {}
                                ).get("nombre"),
                                "is_client": (
                                    prospecto or {}
                                ).get("es_cliente"),
                            },
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=680,
            response_format={
                "type": "json_object"
            },
        )

        register_cost(
            regeneration_resp
        )

        regenerated_data = (
            _loads_llm_json_object(
                regeneration_resp
                .choices[0]
                .message
                .content
                .strip()
            )
        )

        regenerated = str(
            regenerated_data.get("response")
            or ""
        ).strip()

        if not regenerated:
            return original

        regenerated = await grounding_respuesta_agent_v2(
            regenerated,
            mensaje,
            world,
            observations,
            goals,
            perception,
            protect_trusted_templates=False,
        )

        if not _agent_v2_monetary_claims_valid(regenerated, observations):
            return _agent_v2_enforce_monetary_claims(original, observations, world)

        regenerated = str(
            regenerated or ""
        ).strip()

        if not regenerated:
            return original

        post_visual_issues = (
            _agent_v2_visual_response_issues(
                regenerated,
                recent_dialogue=recent_dialogue,
                current_user_message=mensaje,
            )
        )

        original_structured = bool(
            original.count("\n") >= 3
            or "\n\n" in original
            or puntaje_formato_whatsapp(
                original
            ) >= 8
        )

        visual_regression = bool(
            original_structured
            and puntaje_formato_whatsapp(
                regenerated
            )
            < max(
                6,
                puntaje_formato_whatsapp(
                    original
                ) - 3,
            )
        )

        if (
            post_visual_issues
            or visual_regression
        ):
            regenerated = (
                await formatear_respuesta_whatsapp_con_ia(
                    mensaje,
                    regenerated,
                    {},
                    prospecto,
                )
            )

            print(
                "   🧱 [AgentV2 RESPONSE FORMAT GUARD] "
                "regeneración remaquetada sin cambiar hechos"
            )

        selected = await seleccionar_mejor_respuesta_agent_v2(
            original,
            regenerated,
            mensaje,
            world,
            observations,
            goals,
            perception,
            status,
            original_validation=validation,
        )
        print(
            "   ✅ [AgentV2 RESPONSE REGEN] "
            "respuesta ganadora validada y lista para enviar"
        )
        return str(selected or original).strip()

    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 RESPONSE REGEN] "
            f"error no fatal: {exc}"
        )

        return original


AGENT_V2_SAFE_MISSING_FIELDS = {
    "dia", "hora", "hora_aclaracion", "cancha", "duracion_horas",
    "dia_hora_reserva", "confirmar_slot", "quincho", "quincho_duracion_horas",
    "hora_inicio_quincho", "reserva", "reserva_especifica",
    "comprobante", "waitlist_offer", "released_booking_rebook",
    "motivo_cancelacion",
    # Event Registration puede cerrar el turno esperando exactamente un dato
    # estructurado, igual que día/hora/cancha, sin derivación humana.
    "team_name", "inscripcion_evento", "event_selection", "payment_destination",
}


def build_agent_v2_universal_handoff_response(reason_code: str = "") -> str:
    if reason_code == "human_review_required":
        intro = (
            "Para revisar esto correctamente y darte una confirmación segura, "
            "necesito que lo vea personalmente el encargado."
        )
    else:
        intro = (
            "Para brindarte una atención personalizada y resolver correctamente "
            "este caso, necesito que lo vea el encargado."
        )
    return (
        f"{intro}\n\n"
        f"{HUMAN_CONTACT_NAME} se va a comunicar con vos para ayudarte.\n\n"
        f"📱 Su WhatsApp es {HUMAN_WHATSAPP}.\n\n"
        "Ya registré tu consulta para que pueda revisarla."
    )


def _agent_v2_current_safe_question_fields(
    world: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> List[str]:
    fields = []

    def add(field: Any) -> None:
        field = str(field or "").strip()
        if field in AGENT_V2_SAFE_MISSING_FIELDS and field not in fields:
            fields.append(field)

    for observation in observations or []:
        if observation.get("status") != "needs_user_input":
            continue
        data = observation.get("data") or {}
        add(data.get("field"))
        for missing in observation.get("missing") or []:
            add(missing)

    for question in (world.get("open_questions") or world.get("pending_decisions") or []):
        if isinstance(question, dict) and not question.get("context_only"):
            add(question.get("field"))
    return fields


def evaluar_salida_segura_agent_v2(
    response: str,
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    status: str,
) -> Dict[str, Any]:
    """Exige una de las cinco salidas operativas seguras antes de enviar."""
    observations = observations or []
    response = str(response or "").strip()
    question_fields = _agent_v2_current_safe_question_fields(world or {}, observations)

    handoff = next((
        obs for obs in reversed(observations)
        if obs.get("tool") == "solicitar_handoff_humano"
        and (obs.get("ok") or (obs.get("data") or {}).get("handoff_registered"))
    ), None)
    if handoff:
        return {"safe": True, "state": "human_handoff", "evidence": ["solicitar_handoff_humano"]}

    human_review = [
        obs for obs in observations
        if obs.get("status") == "needs_human_review"
    ]
    if human_review:
        return {
            "safe": False,
            "state": "unsafe",
            "reason_code": "human_review_required",
            "reason": "una tool requiere revisión humana y todavía no existe handoff registrado",
        }

    progress = _agent_v2_goal_progress(goals or {}, observations)
    unresolved = [
        name for name, meta in progress.items()
        if meta.get("state") in {"pending", "delegate_legacy"}
    ]
    blocking = [
        obs for obs in observations
        if obs.get("status") in {"policy_blocked", "error", "rejected", "delegate_legacy"}
    ]
    pure_read = bool((_agent_v2_semantic_frame(perception).get("acts") or [])) and all(
        str(a.get("operation") or "").startswith("query_")
        for a in _agent_v2_semantic_frame(perception).get("acts") or []
    )
    if pure_read and not blocking and not any(o.get("tool") in {"consultar_disponibilidad", "consultar_disponibilidad_multiple"} for o in observations) and any(
        o.get("ok") and AGENT_V2_TOOL_CATALOG.get(o.get("tool"), {}).get("effect") == "read"
        for o in observations
    ) and response:
        return {"safe": True, "state": "confirmed_fact", "evidence": [o.get("observation_id") for o in observations if o.get("ok")]}
    if perception.get("semantic_clarification_required") and not blocking and "?" in response:
        return {"safe": True, "state": "one_missing_datum", "field": "operation", "evidence": ["semantic_clarification"]}

    created = _agent_v2_successful_create_observation(observations)
    if created and not blocking and not unresolved:
        return {"safe": True, "state": "verified_operation", "evidence": [created.get("observation_id")]}

    # Consultar calendario real es uno de los cinco estados terminales seguros.
    # Debe ganar antes que el conteo de goals: una reserva todavía no creada o
    # varias preguntas internas no convierten una respuesta grounded en handoff.
    availability = [
        obs for obs in observations
        if obs.get("tool") in {"consultar_disponibilidad", "consultar_disponibilidad_multiple"}
        and obs.get("status") in {"success", "needs_user_input", "unavailable"}
    ]
    if availability and not blocking:
        return {
            "safe": True,
            "state": "real_availability",
            "evidence": [obs.get("observation_id") for obs in availability],
        }

    if (unresolved or blocking) and len(question_fields) != 1:
        return {
            "safe": False,
            "state": "unsafe",
            "reason_code": "unresolved_operational_outcome",
            "reason": (
                f"goals sin resolver={unresolved or []}; "
                f"bloqueos={[o.get('status') for o in blocking]}"
            ),
        }

    verified_writes = [
        obs for obs in observations
        if AGENT_V2_TOOL_CATALOG.get(obs.get("tool"), {}).get("effect") == "write"
        and obs.get("tool") != "solicitar_handoff_humano"
        and obs.get("ok")
        and obs.get("status") in {"success", "already_exists"}
    ]
    if verified_writes and not unresolved:
        return {
            "safe": True,
            "state": "verified_operation",
            "evidence": [obs.get("observation_id") for obs in verified_writes],
        }

    confirmed_reads = [
        obs for obs in observations
        if obs.get("tool") in {
            "consultar_precio", "consultar_informacion_negocio", "obtener_reserva",
            "cancelar_reserva", "reprogramar_reserva",
        }
        and (
            obs.get("ok")
            or obs.get("status") in {"not_found", "unavailable"}
        )
        and obs.get("status") not in {"needs_user_input", "needs_human_review"}
    ]
    if confirmed_reads and not unresolved:
        return {
            "safe": True,
            "state": "confirmed_fact",
            "evidence": [obs.get("observation_id") for obs in confirmed_reads],
        }

    has_verified_user_input_request = any(
        obs.get("status") == "needs_user_input" for obs in observations
    )
    if (
        len(question_fields) == 1
        and (status == "waiting_user" or has_verified_user_input_request)
        and ("?" in response or "¿" in response)
    ):
        return {
            "safe": True,
            "state": "one_missing_datum",
            "field": question_fields[0],
            "evidence": [question_fields[0]],
        }

    semantic_acts = _agent_v2_authoritative_semantic_acts(perception or {})
    semantic_operations = {
        str(act.get("operation") or "") for act in semantic_acts
        if isinstance(act, dict)
    }
    primary = str((goals or {}).get("primary_goal") or "")
    turn_type = str(_agent_v2_semantic_frame(perception or {}).get("turn_type") or "")
    safe_social = bool(
        primary in {"saludar", "cerrar_conversacion"}
        or (
            semantic_operations
            and semantic_operations.issubset({"greet", "close_conversation"})
        )
        or (
            turn_type == "denial"
            and semantic_operations
            and semantic_operations.issubset({"clarify"})
        )
    )
    if safe_social and response:
        return {
            "safe": True,
            "state": "confirmed_conversational_response",
            "evidence": sorted(semantic_operations) or [primary],
        }

    return {
        "safe": False,
        "state": "unsafe",
        "reason_code": "no_verified_terminal_outcome",
        "reason": (
            f"status={status}; primary={primary}; observations="
            f"{[(o.get('tool'), o.get('status')) for o in observations]}"
        ),
    }


def aplicar_regla_universal_salida_segura_agent_v2(
    response: str,
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    status: str,
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    page=None,
    dry_run: bool = False,
) -> Tuple[str, Dict[str, Any]]:
    exact_availability = _agent_v2_verified_exact_availability_response(goals, observations, world, perception)
    if exact_availability:
        response = exact_availability
    else:
        missing_input_response = _agent_v2_verified_missing_input_response(
            observations
        )
        if missing_input_response:
            preserve_contextual_response = bool(
                _agent_v2_requires_contextual_response_composition(perception)
                and str(response or "").strip()
                and ("?" in str(response) or "¿" in str(response))
            )
            if preserve_contextual_response:
                print(
                    "   🧠 [AgentV2 RESPONSE CONTRACT] la consulta actual contiene "
                    "información semántica; preservo la respuesta IA contextual "
                    "antes de pedir el dato pendiente"
                )
            else:
                if str(response or "").strip() != missing_input_response:
                    print(
                        "   🧱 [AgentV2 RESPONSE CONTRACT] sólo falta un dato; "
                        "descarto afirmaciones no respaldadas y restauro la pregunta"
                    )
                response = missing_input_response
    assessment = evaluar_salida_segura_agent_v2(
        response, world, perception, goals, observations, status
    )
    if assessment.get("safe"):
        print(
            "   ✅ [AgentV2 SAFE EXIT] "
            f"state={assessment.get('state')} evidence={assessment.get('evidence') or assessment.get('field')}"
        )
        return response, assessment

    reason_code = str(assessment.get("reason_code") or "no_verified_terminal_outcome")
    reason = str(assessment.get("reason") or reason_code)
    contract_issues = set((perception.get("execution_contract") or {}).get("clarification_reasons") or [])
    contract_issues.update((perception.get("semantic_clarification") or {}).get("reasons") or [])
    read_acts = _agent_v2_semantic_frame(perception).get("acts") or []
    if (read_acts and all(str(a.get("operation") or "").startswith("query_") for a in read_acts)
        and contract_issues and contract_issues.issubset({"fact_operation_inconsistent"})
        and not any(o.get("status") in {"error", "needs_human_review"} for o in observations)):
        # Defense for older persisted frames that bypassed normal READ repair.
        # Never register/notify a human solely because our fact enum was missing.
        return "No tengo ese dato confirmado todavía.", {
            "safe": True, "state": "confirmed_conversational_response",
            "reason_code": "internal_read_representation_failure", "evidence": [],
        }
    data = {
        "tipo": "humano",
        "reason": f"universal_safe_exit:{reason_code}: {reason}"[:1000],
        "mensaje_usuario": str((world or {}).get("message") or ""),
        "admin_notified": False,
        "notification_attempted": False,
        "notification_pending": bool(page is not None and not dry_run),
        "handoff_registered": True,
        "safe_exit_fallback": True,
        # Una salida universal significa que falló nuestro procesamiento, no que
        # el usuario pidió hablar con una persona. Se registra y se alerta, pero
        # nunca se revela el fallback interno en el chat del cliente.
        "silent_handoff": True,
        "handoff_mode": "silent_internal_failure",
        "customer_response_suppressed": True,
        "delivery_policy": "suppress_customer",
        "respuesta": build_agent_v2_universal_handoff_response(reason_code),
    }
    handoff = _agent_v2_observation(
        "solicitar_handoff_humano",
        True,
        "success",
        data,
        verified_facts={"handoff": data},
    )
    observations.append(handoff)
    if not dry_run:
        for stale_field in ("semantic_clarification", "intent", "operacion", "operation"):
            agent_v2_reduce(
                telefono,
                {"type": "CLEAR_OPEN_QUESTION", "payload": {"field": stale_field}},
            )
        aplicar_observation_agent_v2(
            telefono,
            handoff,
            world,
            perception,
        )
    registrar_metrica_operativa(
        "agent_v2_universal_safe_exit_handoff",
        {
            "telefono": telefono,
            "nombre": (prospecto or {}).get("nombre") or "",
            "reason_code": reason_code,
            "reason": reason[:500],
            "goal": (goals or {}).get("primary_goal"),
            "status": status,
        },
    )
    safe_exit = {
        "safe": True,
        "state": "human_handoff",
        "fallback_applied": True,
        "reason_code": reason_code,
        "reason": reason,
        "evidence": [handoff.get("observation_id")],
    }
    print(
        "   🛟 [AgentV2 SAFE EXIT] sin salida verificable → "
        f"handoff reason={reason_code}"
    )
    return data["respuesta"], safe_exit


def _agent_v2_should_reset_booking_scope(
    world: Dict,
    perception: Dict,
    goals: Dict,
) -> bool:
    """
    Context Freshness responde si una pregunta sigue adyacente.
    Scope Freshness responde si el usuario sigue hablando de ESA decision.

    Ejemplo de scope nuevo:
      pending viejo: "¿Cancha 1 o Cancha 2?"
      usuario ahora: "Cancha para hoy a la tarde, ¿cuanto sale?"
    """
    pending = list((world or {}).get("open_questions") or [])
    draft = (world or {}).get("desires", {}).get("booking_draft")
    auth = (world or {}).get("write_authorizations", {}).get("crear_reserva")
    if not pending and not draft and not auth:
        return False

    goal_names = {
        str(g.get("goal") or "")
        for g in ((goals or {}).get("goals") or [])
        if isinstance(g, dict)
    }
    if "buscar_turno" not in goal_names:
        return False

    # V2.10.6: una broad availability actual abre scope aunque Perception haya
    # heredado cancha/answers_pending del booking viejo. El runtime pre-Perception
    # ya usa esta misma autoridad; esto queda como defensa en profundidad.
    current_message = str((world or {}).get("message") or "")
    if _agent_v2_current_message_is_broad_availability_query(current_message):
        return True

    # Una referencia semántica a un mensaje previo del MISMO usuario no abre scope:
    # primero hay que resolver lo que ya había pedido.
    if (perception or {}).get("references_prior_user_input"):
        return False

    # Un bloque horario explícito es continuidad/decisión, no una consulta broad nueva.
    if (perception or {}).get("booking_block_request"):
        return False

    # Si el usuario realmente contesta una decision pendiente, conservar continuidad.
    if (perception or {}).get("answers_pending_field") in {
        "cancha", "hora", "hora_aclaracion", "dia_hora_reserva", "confirmar_slot",
        "duracion_horas", "estructura_horarios", "reserva_especifica",
        "waitlist_offer", "horarios_multiples_alternativas",
    }:
        return False

    entities = (perception or {}).get("entities") or {}
    has_new_scope = bool(
        entities.get("dia")
        or entities.get("dia_resuelto")
        or entities.get("franja_dia")
    )
    if not has_new_scope:
        return False

    # Una cancha explicitamente seleccionada pertenece al flujo pendiente.
    if entities.get("cancha"):
        return False

    return True


def _agent_v2_fresh_availability_request(
    perception: Dict,
    goals: Dict,
) -> bool:
    """Consulta nueva por dia/franja sin hora concreta: primero READs reales."""
    goal_names = {
        str(g.get("goal") or "")
        for g in ((goals or {}).get("goals") or [])
        if isinstance(g, dict)
    }
    entities = (perception or {}).get("entities") or {}
    hora = normalizar_hora_detectada(entities.get("hora"))
    return bool(
        "buscar_turno" in goal_names
        and (entities.get("dia") or entities.get("dia_resuelto") or entities.get("franja_dia"))
        and not hora_es_valida(hora)
        and entities.get("temporal_mode") != "asap"
        and not (perception or {}).get("booking_block_request")
        and not (perception or {}).get("answers_pending_field")
    )



def _agent_v2_message_mentions_exact_hour(mensaje: str) -> bool:
    """
    Solo responde si el MENSAJE ACTUAL contiene una hora concreta.
    No intenta resolver AM/PM; Perception conserva esa tarea. Acá únicamente
    impedimos que una hora venga heredada del historial.
    """
    return bool(extraer_horas_reales_de_texto(str(mensaje or "")))


def _agent_v2_message_mentions_explicit_court(mensaje: str) -> bool:
    """
    Una mención genérica a 'cancha' no equivale a elegir Cancha 1/2.
    Exige el nombre configurado o una forma inequívoca 'cancha N'.
    """
    raw = normalizar_texto_ia(mensaje or "")
    if not raw:
        return False

    for court in COURTS or []:
        name = str((court or {}).get("name") or "").strip()
        if name and normalizar_texto_ia(name) in raw:
            return True

    return bool(re.search(r"\bcancha\s*\d+\b", raw))


def _agent_v2_sanitize_perception_after_scope_reset(
    mensaje: str,
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    """
    CURRENT TURN GROUNDING.

    Al detectar scope nuevo, día/franja pueden venir del mensaje actual, pero
    hora/cancha no pueden sobrevivir solo porque aparecieron en historial/estado
    previo. Se preservan únicamente si el texto ACTUAL las menciona.
    """
    clean = dict(perception or {})
    entities = dict(clean.get("entities") or {})

    if _agent_v2_has_authoritative_semantics(clean):
        acts = _agent_v2_authoritative_semantic_acts(clean)
        semantic_hours = []
        semantic_court = None
        for act in acts:
            temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
            semantic_hours.extend(temporal.get("times") or [])
            if temporal.get("start"):
                semantic_hours.append(temporal.get("start"))
            target = act.get("target") if isinstance(act.get("target"), dict) else {}
            if target.get("resource") == "court" and target.get("label"):
                semantic_court = target.get("label")
            selection = act.get("selection") if isinstance(act.get("selection"), dict) else {}
            if selection.get("resolved_value") and str(selection.get("resolved_value")) in {
                str((court or {}).get("name") or "")
                if isinstance(court, dict)
                else str(court or "")
                for court in (COURTS or [])
            }:
                semantic_court = selection.get("resolved_value")

        semantic_hours = _agent_v2_dedupe_hours(semantic_hours)
        entities["horas"] = semantic_hours
        entities["hora"] = semantic_hours[0] if len(semantic_hours) == 1 else None
        entities["cancha"] = semantic_court
        clean["entities"] = entities
        clean["scope_reset_this_turn"] = True
        print(
            "   🔒 [AgentV2 SCOPE RESET] entidades preservadas por provenance "
            "del ExecutionContract"
        )
        return clean

    if not _agent_v2_message_mentions_exact_hour(mensaje):
        if entities.get("hora"):
            print(
                f"   🧼 [AgentV2 ENTITY GROUNDING] descarto hora heredada="
                f"{entities.get('hora')} (no aparece en mensaje actual)"
            )
        entities["hora"] = None
        clean.pop("booking_time_choice", None)

        selection = clean.get("selection")
        if isinstance(selection, dict) and selection.get("type") == "hour":
            clean["selection"] = {"type": "none", "value": None}

    if not _agent_v2_message_mentions_explicit_court(mensaje):
        if entities.get("cancha"):
            print(
                f"   🧼 [AgentV2 ENTITY GROUNDING] descarto cancha heredada="
                f"{entities.get('cancha')} (no aparece en mensaje actual)"
            )
        entities["cancha"] = None

        selection = clean.get("selection")
        if isinstance(selection, dict) and selection.get("type") == "court":
            clean["selection"] = {"type": "none", "value": None}

    # Por definición acabamos de determinar que el mensaje NO estaba contestando
    # la decisión anterior.
    clean.pop("answers_pending_field", None)
    clean["entities"] = entities
    clean["scope_reset_this_turn"] = True
    return clean


def _agent_v2_prune_stale_booking_goal_after_scope_reset(
    goals: Dict,
    perception: Dict,
) -> Dict[str, Any]:
    """Quita crear_reserva si venia solo arrastrado por el scope viejo."""
    explicit = set((perception or {}).get("explicit_actions") or [])
    keep_create = bool(
        (perception or {}).get("booking_time_choice")
        or (perception or {}).get("answers_pending_field") in {"cancha", "hora", "hora_aclaracion"}
        or explicit.intersection({"crear_reserva", "reservar", "reservar_cancha", "confirmar_reserva"})
    )
    if keep_create:
        return goals

    clean = dict(goals or {})
    clean_goals = [
        dict(g) for g in (clean.get("goals") or [])
        if g.get("goal") != "crear_reserva"
    ]
    clean["goals"] = clean_goals
    if clean.get("primary_goal") == "crear_reserva":
        clean["primary_goal"] = (clean_goals[0].get("goal") if clean_goals else "buscar_turno")
    return clean


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Runtime completo:
      PERCEPTION → WORLD MODEL → GOALS → PLAN → POLICY → TOOL → OBSERVE
      → STATE REDUCER → REPLAN → RESPONSE COMPOSER.
    """
    pause = obtener_pausa_contacto_humano(telefono)
    if pause:
        return {
            "handled": True, "delegate_legacy": False, "status": "paused_human",
            "response": "", "observations": [], "llm_calls": 0,
            "goals": {"primary_goal": "derivar_humano", "goals": []},
            "pause": pause,
        }
    if sincronizar_reanudacion_humana(telefono):
        conv_state = get_conversation_state(telefono)
    if not AGENT_V2_ENABLED:
        return {"handled": False, "delegate_legacy": True, "reason": "agent_v2_disabled"}

    # Contador aislado por task/contexto. Los judges en background conservan su
    # propio contexto y no inflan el presupuesto del siguiente chat.
    AGENT_V2_TURN_LLM_CALLS.set(0)

    # Hot config: si un admin cambió días/horarios/duraciones/precios/seña,
    # el siguiente usuario lo ve sin reiniciar WPSetter.
    _refresh_runtime_config_if_changed(reason="before_agent_v2_turn")
    print(f"   🧬 [AgentV2 BUILD] {AGENT_V2_EXACT_SLOT_CONFIRM_BUILD}")

    # V2.17 — REACTIVE HOLD FRESHNESS.
    # El inbox tiene prioridad sobre los proactivos, por lo que un mensaje puede
    # llegar justo después de vencer un hold y antes del sweep de la vuelta idle.
    # Liberar leases vencidos ANTES de construir World evita consultar/planificar
    # contra un calendario que ya debería estar libre. page=None impide navegar o
    # enviar avisos mientras estamos atendiendo al usuario actual.
    try:
        expired_before_turn = await expirar_holds_senia_vencidos(
            page=None,
            force=True,
        )
        if expired_before_turn.get("expired"):
            print(
                "   ⏳ [AgentV2 PRE-TURN HOLD SWEEP] "
                f"liberados={expired_before_turn.get('expired')} antes de World"
            )
    except Exception as e:
        print(f"   ⚠️ [AgentV2 PRE-TURN HOLD SWEEP] error no fatal: {e}")

    # V2.11 — learned behavior policy is hot-reloaded per turn and then frozen
    # for the whole turn. Evals may inject a candidate policy without touching
    # production's learned_policy.json.
    AGENT_LEARNING_MANAGER.hot_reload()
    _learning_eval_context_raw = (
        eval_context if isinstance(eval_context, dict) else {}
    )
    learning_policy_for_turn = (
        _learning_eval_context_raw.get("learning_policy")
        if isinstance(_learning_eval_context_raw.get("learning_policy"), dict)
        else AGENT_LEARNING_MANAGER.active_policy()
    )

    telefono_key = telefono or "unknown"
    owner_key = _memory_owner_key(telefono_key)

    if owner_key == "unknown":
        print(
            "   🚫 [AgentV2 MEMORY ISOLATION] no ejecuto Agent V2 "
            "sin identidad de chat estable"
        )
        return {
            "handled": False,
            "status": "identity_unresolved",
            "response": "",
            "observations": [],
            "goals": {"primary_goal": "otro", "goals": []},
        }

    # Nunca confiar en un conv_state recibido por referencia si pertenece
    # a otro namespace. Rehidratar SIEMPRE desde la clave canónica actual.
    received_owner = str((conv_state or {}).get("_memory_owner") or "").strip()
    if received_owner and received_owner != owner_key:
        print(
            f"   🚨 [AgentV2 MEMORY ISOLATION] conv_state externo rechazado "
            f"owner={received_owner} expected={owner_key}"
        )

    conv_state = get_conversation_state(telefono_key)

    print(
        f"   🔐 [AgentV2 MEMORY] owner={owner_key} "
        f"history={len(conv_state.get('historial') or [])}"
    )

    # La memoria no se limpia por heurística al iniciar el turno. Reconciliation
    # sólo invalida referencias contradichas por la fuente de verdad.
    conv_state = reconciliar_estado_con_fuente_de_verdad(telefono_key, conv_state, prospecto or {})

    # V2.10.7: una fila inexistente de calendario invalida cualquier reservation_id
    # residual ANTES de construir World/Perception.
    if _agent_v2_purge_ghost_reservation_state(telefono_key, prospecto or {}):
        conv_state = get_conversation_state(telefono_key)

    turn_id = str(uuid.uuid4())
    agent_v2_reduce(telefono_key, {"type": "TURN_STARTED", "payload": {"turn_id": turn_id}})
    world = construir_world_state_agent_v2(telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path)

    learning_world_before = AGENT_LEARNING_MANAGER.compact_world(world)

    # AgentScenarioRunner puede inyectar únicamente la capa semántica para ejecutar
    # el resto del pipeline REAL (planner/policy/tools/reducer/NBA/composer fallback)
    # sin consumir API. Producción nunca pasa eval_context.
    eval_context = dict(eval_context or {})
    offline_e2e = bool(eval_context.get("offline"))
    perception_override = eval_context.get("perception")
    if isinstance(perception_override, dict):
        # eval_context no existe en producción: toda inyección del runner debe
        # declarar explícitamente su contrato de efecto de fixture.
        perception_override = _agent_v2_attach_offline_eval_semantics(
            perception_override,
            eval_context.get("goals"),
            mensaje,
        )
        perception = _agent_v2_normalize_perception(
            dict(perception_override), world, mensaje, image_path
        )
        print("   🧪 [AgentV2 E2E] perception override determinista")
    else:
        perception = await percibir_turno_agent_v2(
            mensaje,
            world,
            image_path,
            learning_policy=learning_policy_for_turn,
        )

    # Segunda capa IA dedicada sólo a identificar el día de la oración actual.
    # Se ejecuta aunque Perception haya omitido la mención, para corregir cualquier
    # default provisional antes de que pending/planner/tools puedan usarlo.
    if not offline_e2e:
        perception = await _agent_v2_resolve_current_turn_date_with_ai(
            perception,
            mensaje,
            world,
        )

    # El runner puede inyectar Perception y producción puede recibir un frame
    # normalizado por una versión anterior. Aplicar la misma autoridad semántica
    # en el borde garantiza una sola conducta en ambos caminos.
    perception = _agent_v2_apply_duration_policy_question_authority(
        perception,
        mensaje,
        world,
    )

    # Una voluntad de reservar sin hora concreta todavía no puede crear un
    # turno. Si Perception ya aportó día/franja, primero consultamos agenda del
    # alcance actual. Esto ocurre antes de cualquier oferta stateful vencida.
    perception = _agent_v2_apply_slotless_booking_availability_authority(
        perception,
        mensaje,
        world,
    )

    # Una referencia reconocida por Perception al turno que el propio sistema
    # liberó se resuelve contra memoria operativa verificada, no contra texto libre.
    perception = _agent_v2_apply_recent_released_booking_reference_authority(
        perception,
        mensaje,
        world,
    )

    # Un evento o jornada completa sale del dominio autónomo aun si los dos pases
    # semánticos devolvieron una lectura incompleta. La tool avisa al encargado.
    perception = _agent_v2_apply_special_event_perception_authority(
        perception,
        mensaje,
        world,
    )

    # Una pregunta de capacidad simultánea se responde con la cantidad/precios
    # configurados, no inicia una reserva ni pide día/hora.
    perception = _agent_v2_apply_parallel_courts_policy_authority(
        perception,
        mensaje,
        world,
    )

    # V80 — RESOURCE-SCOPE REPAIR. La primera Perception ya debe conservar
    # resource_type/resource_types; si los omitió, una segunda lectura IA muy
    # estrecha puede recuperarlos exclusivamente contra los tipos configurados.
    # Python no interpreta palabras de deportes ni usa regex para esta decisión.
    if not offline_e2e:
        perception = await _agent_v2_repair_current_court_resource_scope_with_ai(
            perception,
            mensaje,
            world,
        )

    # Grounding de catálogo antes de disponibilidad. Si la consulta menciona un
    # tipo concreto de cancha, V80 conserva ese scope y añade disponibilidad real
    # de ese mismo tipo para hoy, sin convertir la consulta en una reserva.
    perception = _agent_v2_apply_court_catalog_perception_authority(
        perception,
        mensaje,
        world,
    )

    # Toda FAQ que Perception haya entendido, pero que no pueda respaldarse con
    # un Policy Fact Contract de config.py, se deriva al encargado.
    perception = _agent_v2_apply_unconfigured_business_handoff_authority(
        perception,
        mensaje,
        world,
    )

    # Recuperar una omisión horaria sin sobrescribir horas, actos ni restricciones
    # ya resueltas por Perception. El calendario recibe el contrato semántico.
    perception = _agent_v2_force_exact_availability_current_turn_authority(
        perception,
        mensaje,
        world,
    )

    # Defensa independiente del modelo: SOLO una consulta realmente amplia puede
    # limpiar filtros. Una hora escrita AHORA nunca llega a esta rama.
    perception = _agent_v2_apply_fresh_availability_perception_authority(
        perception,
        mensaje,
        world,
    )
    if not offline_e2e:
        perception = await _agent_v2_recover_missing_availability_day(perception, world, mensaje, image_path)

    # Exact availability READ authority. Unlike a broad-only reset, this also
    # neutralizes a stale onboarding/draft when the current message asks a concrete
    # day+hour as information (e.g. "horario disponible lunes 18 hs").
    if _agent_v2_is_pure_exact_availability_read(perception):
        perception["booking_time_choice"] = False
        perception["booking_block_choice"] = False
        perception["accepts_any_option"] = False
        perception["answers_pending_field"] = None
        perception["pending_relation"] = "new_question"
        perception["suspend_pending_this_turn"] = False
        perception["references_operational_context"] = False
        frame = dict(_agent_v2_semantic_frame(perception) or {})
        relation = dict(frame.get("context_relation") or {})
        relation.update({
            "type": "new_question",
            "question_id": None,
            "references_agent_offer": False,
            "answers_pending_question": False,
        })
        frame["context_relation"] = relation
        perception["semantic_frame"] = frame
        perception["execution_contract"] = _agent_v2_build_execution_contract(perception, world)
        print(
            "   🔐 [AgentV2 EXACT READ AUTHORITY] "
            f"build={AGENT_V2_EXACT_SLOT_CONFIRM_BUILD} memory=passive"
        )

    # Todas las authorities anteriores sólo pueden proponer/reparar el frame.
    # Éste es el único borde final de proyección antes de persistir Perception.
    perception = dict(perception or {})
    verified_turn_plan = (
        _agent_v2_v125_copy.deepcopy(perception.get("turn_semantic_plan"))
        if isinstance(perception.get("turn_semantic_plan"), dict)
        and perception.get("turn_semantic_plan", {}).get("status") == "verified"
        and perception.get("turn_semantic_plan", {}).get("bindings")
        else {}
    )
    verified_turn_contract = (
        _agent_v2_v125_copy.deepcopy(perception.get("execution_contract"))
        if verified_turn_plan
        and isinstance(perception.get("execution_contract"), dict)
        and perception.get("execution_contract", {}).get("source")
            == "verified_turn_semantic_plan"
        and perception.get("execution_contract", {}).get("authoritative") is True
        else {}
    )
    perception.pop("execution_contract", None)
    perception = _agent_v2_normalize_perception(
        perception, world, mensaje, image_path
    )

    # El normalizador general no puede reapropiarse de slots heredados por una
    # continuación verificada. En el incidente real, la hora 18:00 venía del
    # BookingObjective anterior, pero el texto actual "1 hora" terminaba usado
    # como evidencia de reloj y bloqueaba todo el contrato. Conservamos las
    # validaciones de contexto del normalizador y restauramos solamente los actos
    # congelados por Dialogue Binding + Effect Verifier.
    normalized_contract = dict(perception.get("execution_contract") or {})
    normalized_context = dict(normalized_contract.get("authorized_context") or {})
    if verified_turn_contract and normalized_context.get("authorized") is True:
        restored_contract = _agent_v2_v125_copy.deepcopy(verified_turn_contract)
        restored_contract["authorized_context"] = normalized_context
        restored_contract["validation_issues"] = []
        restored_contract["clarification_reasons"] = []
        restored_contract["rejected_acts"] = list(
            verified_turn_contract.get("rejected_acts") or []
        )
        frame = dict(_agent_v2_semantic_frame(perception) or {})
        frame["acts"] = _agent_v2_v125_copy.deepcopy(
            restored_contract.get("acts") or []
        )
        perception["semantic_frame"] = frame
        perception["execution_contract"] = restored_contract
        print(
            "   🧊 [AgentV2 V127 VERIFIED CONTINUATION] "
            "actos congelados restaurados después de normalización; "
            "slots heredados conservan su autoridad original"
        )
    # V84: cualquier READ system-grounded del bundle catálogo+agenda debe estar
    # dentro del ExecutionContract ANTES de Goal Compiler/Planner/Policy Guard.
    # Planner nunca vuelve a ampliar permisos por su cuenta.
    perception = _agent_v2_v84_authorize_specific_court_catalog_bundle_contract(
        perception, world, mensaje
    )

    # Si Event Registration abrió un new_request verificado sobre una aclaración
    # genérica obsoleta, eliminamos solamente esos campos de la memoria durable.
    # No tocamos hora/cancha/team_name ni ninguna decisión operativa legítima.
    superseded_pending_fields = [
        str(field or "").strip()
        for field in (perception.get("_superseded_pending_fields") or [])
        if str(field or "").strip() in _EVENT_REGISTRATION_STALE_CLARIFICATION_FIELDS
    ]
    if superseded_pending_fields and not dry_run:
        for stale_field in dict.fromkeys(superseded_pending_fields):
            agent_v2_reduce(
                telefono_key,
                {"type": "CLEAR_OPEN_QUESTION", "payload": {"field": stale_field}},
            )
        print(
            "   🧹 [EVENT REGISTRATION MEMORY CLEANUP] "
            f"pending obsoleto eliminado={list(dict.fromkeys(superseded_pending_fields))}"
        )

    perception = _agent_v2_persist_customer_context(
        telefono_key,
        mensaje,
        perception,
        prospecto,
    )
    agent_v2_reduce(telefono_key, {"type": "PERCEPTION_UPDATED", "payload": perception})
    if _agent_v2_information_only_turn(perception):
        agent_v2_reduce(telefono_key, {"type": "SUSPEND_PENDING_FOR_INFORMATION"})
        world = construir_world_state_agent_v2(
            telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path
        )
    if isinstance(perception.get("reservation_target"), dict) and perception.get("reservation_target", {}).get("reservation_id"):
        agent_v2_reduce(telefono_key, {"type": "RESERVATION_TARGET_SET", "payload": perception.get("reservation_target")})

    goals_override = eval_context.get("goals")
    if isinstance(goals_override, dict):
        goals = dict(goals_override)
        goals.setdefault("goals", [])
        goals.setdefault("primary_goal", (goals.get("goals") or [{}])[0].get("goal", "otro"))
        goals.setdefault("reason", "AgentScenarioRunner semantic override")
        print("   🧪 [AgentV2 E2E] goals override determinista")
    else:
        goals = await inferir_goals_agent_v2(
            perception,
            world,
            learning_policy=learning_policy_for_turn,
        )

    freeze_meaning = _agent_v2_execution_contract_freezes_meaning(
        perception,
        goals_override,
    )
    if freeze_meaning:
        print(
            "   🧊 [AgentV2 FREEZE MEANING] goals compilados desde ExecutionContract; "
            "capas posteriores no reinterpretan el mensaje"
        )
    else:
        # Compatibilidad para fixtures legacy o contratos semánticos inválidos.
        goals = _agent_v2_enforce_current_turn_goal_firewall(
            goals,
            perception,
            world,
            mensaje,
        )
        goals = _agent_v2_force_fresh_availability_goals(
            goals,
            perception,
            mensaje,
        )
        goals = _agent_v2_enforce_explicit_single_booking_goals(
            goals,
            perception,
            world,
            mensaje,
        )
        goals = _agent_v2_enforce_quincho_schedule_amendment_goals(
            goals,
            perception,
            world,
            mensaje,
        )
    # Una operación de booking autónoma abre un scope nuevo por semántica
    # contractual, no por regex ni por presencia de memoria vieja. El reducer
    # archiva el scope saliente antes de desactivar sus vistas canónicas.
    execution_contract_now = perception.get("execution_contract") or {}
    contract_relation = str(
        (execution_contract_now.get("context_relation") or {}).get("type") or ""
    )
    contract_operations = {
        str(act.get("operation") or "")
        for act in execution_contract_now.get("acts") or []
        if isinstance(act, dict)
    }
    opens_independent_booking_scope = bool(
        contract_relation in {"new_request", "new_question", "unrelated", "no_pending"}
        and contract_operations.intersection({"query_availability", "create_booking"})
    )
    desired_scope_id = str(world.get("current_scope_id") or "").strip()
    active_scope_id = str(
        _agent_v2_state(get_conversation_state(telefono_key)).get("active_scope_id") or ""
    ).strip()
    if opens_independent_booking_scope and desired_scope_id and desired_scope_id != active_scope_id:
        has_real_reservation = bool(
            world.get("facts", {}).get("reservas_reales") or []
        )
        agent_v2_reduce(
            telefono_key,
            {
                "type": "BEGIN_CONTEXT_SCOPE",
                "payload": {
                    "reason": "execution contract opens independent booking scope",
                    "scope_id": desired_scope_id,
                    "clear_legacy_slot": not has_real_reservation,
                },
            },
        )
        world = construir_world_state_agent_v2(
            telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path
        )
        _agent_v2_publish_context_authorization(
            world,
            execution_contract_now.get("authorized_context")
            or _agent_v2_context_authorization(perception, world),
        )

    agent_v2_reduce(telefono_key, {"type": "GOALS_UPDATED", "payload": goals})

    print(f"   🌍 [AgentV2 WORLD] reservas={len(world.get('facts', {}).get('reservas_reales') or [])} draft={bool(world.get('desires', {}).get('booking_draft'))} pending={[q.get('field') for q in world.get('pending_decisions') or []]}")
    print(f"   🎯 [AgentV2 GOAL] primary={goals.get('primary_goal')} goals={[(g.get('goal'), g.get('priority')) for g in goals.get('goals') or []]}")

    observations: List[Dict[str, Any]] = []
    status = "continue"
    last_plan = None
    blocked_without_progress = set()
    failed_tool_attempts = {}
    execution_contract = perception.get("execution_contract") or {}
    # Saludo/cierre solo se resuelven sin tools si TODOS los goals del turno son sociales.
    goal_names_turno = {g.get("goal") for g in (goals.get("goals") or [])}
    if perception.get("semantic_clarification_required"):
        semantic_clarification = perception.get("semantic_clarification") or {}
        if not dry_run:
            agent_v2_reduce(
                telefono_key,
                {
                    "type": "SET_OPEN_QUESTION",
                    "payload": _agent_v2_v86_semantic_clarification_pending_payload(
                        perception,
                        world,
                        semantic_clarification,
                    ),
                },
            )
        status = "waiting_user"
        print(
            "   🛡️ [AgentV2 SEMANTIC CLARIFICATION] "
            "turno detenido antes de Planner por "
            f"{semantic_clarification.get('reasons') or ['operacion_no_reconocida']}"
        )
    elif (
        goal_names_turno
        and goal_names_turno.issubset({"saludar", "cerrar_conversacion"})
        and not perception.get("explicit_actions")
    ):
        if "saludar" in goal_names_turno and "cerrar_conversacion" not in goal_names_turno:
            if not dry_run:
                _agent_v2_open_booking_onboarding_question(
                    telefono_key,
                    source_message=mensaje,
                )
            status = "waiting_user"
            print(
                "   🙋 [AgentV2 SOCIAL] saludo resuelto sin tools; "
                "pregunta activa=dia_hora_reserva"
            )
        else:
            status = "complete"
    elif (
        execution_contract.get("authoritative")
        and not (execution_contract.get("allowed_tools") or [])
    ):
        # Greeting, correction, denial or conversational turn: there is no tool
        # contract to execute, even if stale booking state still exists in memory.
        status = "complete"
        print(
            "   🔒 [AgentV2 EXECUTION CONTRACT] turno conversacional sin tools; "
            "memoria operativa no participa"
        )
    else:
        for cycle in range(AGENT_V2_MAX_REPLANS):
            # Reconstruir mundo después de cada ciclo: source-of-truth > memoria.
            world = construir_world_state_agent_v2(
                telefono_key,
                prospecto,
                get_conversation_state(telefono_key),
                mensaje,
                image_path,
            )
            world = _agent_v2_rehydrate_authorized_context_for_execution(
                world,
                perception,
            )
            plan = await planificar_agent_v2(
                world,
                perception,
                goals,
                observations,
                offline_mode=offline_e2e,
                learning_policy=learning_policy_for_turn,
            )
            last_plan = plan
            agent_v2_reduce(telefono_key, {"type": "PLAN_UPDATED", "payload": plan})
            print(f"   🧭 [AgentV2 PLAN {cycle+1}] {[(s.get('tool'), s.get('args')) for s in plan.get('steps') or []]}")

            if not plan.get("steps"):
                status = "complete"
                break

            replan_requested = False
            plan_steps = list(plan.get("steps") or [])
            for step_index, step in enumerate(plan_steps):
                tool = step.get("tool")
                args = step.get("args") or {}
                # Mundo fresco antes de validar CADA escritura/paso.
                world = construir_world_state_agent_v2(
                    telefono_key,
                    prospecto,
                    get_conversation_state(telefono_key),
                    mensaje,
                    image_path,
                )
                world = _agent_v2_rehydrate_authorized_context_for_execution(
                    world,
                    perception,
                )
                validation = validar_tool_agent_v2(
                    tool,
                    args,
                    world,
                    perception,
                    goals,
                    image_path,
                )
                if not validation.get("ok"):
                    print(f"   🛡️ [AgentV2 POLICY] bloquea {tool}: {validation.get('reason')}")
                    missing = validation.get("missing") or []
                    if missing and not validation.get("fatal"):
                        missing_field = missing[0]
                        goal_names = {
                            str(goal.get("goal") or "")
                            for goal in ((goals or {}).get("goals") or [])
                            if isinstance(goal, dict)
                        }
                        missing_question = _agent_v2_preserve_missing_question_context(
                            world,
                            missing_field,
                            {
                                "field": missing_field,
                                "options": list(validation.get("options") or []),
                                "reason": validation.get("reason"),
                                "dia": args.get("dia"),
                                "hora": args.get("hora") if missing_field != "hora" else None,
                                "cancha": args.get("cancha"),
                                "duracion_horas": args.get("duracion_horas"),
                                "booking_shape": args.get("booking_shape"),
                                "requested_hours": list(args.get("requested_hours") or []),
                                "goal_context": list(goal_names),
                                "booking_choice": bool(
                                    missing_field == "hora"
                                    and "crear_reserva" in goal_names
                                ),
                            },
                        )
                        obs = _agent_v2_observation("solicitar_dato", True, "needs_user_input", {
                            **missing_question,
                            "booking_choice": bool(
                                missing_field == "hora"
                                and "crear_reserva" in goal_names
                            ),
                        }, missing=missing, options=list(missing_question.get("options") or []))
                        observations.append(obs)
                        aplicar_observation_agent_v2(telefono_key, obs, world, perception)
                        status = "waiting_user"
                    else:
                        obs = _agent_v2_observation(tool, False, "policy_blocked", {"reason": validation.get("reason")})
                        observations.append(obs)
                        agent_v2_reduce(telefono_key, {"type": "OBSERVATION", "payload": obs})
                        # No dejamos que una escritura bloqueada caiga al legacy y ocurra igual.
                        # Replanificamos con la observación de bloqueo para buscar una acción segura (p.ej. READ).
                        blocked_key = json.dumps(
                            {"tool": tool, "args": args, "reason": validation.get("reason")},
                            sort_keys=True, default=str,
                        )
                        cannot_retry = validation.get("fatal") or blocked_key in blocked_without_progress
                        blocked_without_progress.add(blocked_key)
                        status = "policy_blocked" if cannot_retry else "continue"
                        replan_requested = not cannot_retry
                    break

                args = validation.get("args") or args
                attempt_key = json.dumps({"tool": tool, "args": args}, sort_keys=True, default=str)
                if attempt_key in failed_tool_attempts:
                    print(f"   🛑 [AgentV2 NO PROGRESS] {tool}: misma firma y fallo={failed_tool_attempts[attempt_key]}")
                    status = "policy_blocked"
                    replan_requested = False
                    break
                if dry_run:
                    obs = _agent_v2_observation(tool, True, "dry_run", {"args": args})
                else:
                    try:
                        obs = await ejecutar_tool_agent_v2(
                            tool, args, world, perception, goals, telefono_key, prospecto,
                            user_messages or [mensaje], page=page, image_path=image_path,
                        )
                    except Exception as exc:
                        # TOOL ERROR BOUNDARY: ninguna integración puede derribar el
                        # loop ni convertirse en un éxito verbal. El World Model se
                        # reconstruye abajo y Safe Exit registra el handoff.
                        print(
                            f"   ⚠️ [AgentV2 TOOL ERROR] {tool}: "
                            f"{type(exc).__name__}: {exc}"
                        )
                        registrar_metrica_operativa(
                            "agent_v2_tool_exception",
                            {
                                "telefono": telefono_key,
                                "tool": tool,
                                "error_type": type(exc).__name__,
                            },
                        )
                        obs = _agent_v2_observation(
                            tool,
                            False,
                            "needs_human_review",
                            {
                                "reason": "tool_execution_exception",
                                "error_type": type(exc).__name__,
                                "requires_handoff": True,
                            },
                        )
                observations.append(obs)
                if not obs.get("ok"):
                    failed_tool_attempts[attempt_key] = (obs.get("data") or {}).get("reason") or obs.get("status")
                elif AGENT_V2_TOOL_CATALOG.get(tool, {}).get("effect") == "write":
                    failed_tool_attempts.clear()
                if obs.get("ok"):
                    blocked_without_progress.clear()
                print(f"   👁️ [AgentV2 OBSERVE] tool={tool} ok={obs.get('ok')} status={obs.get('status')}")

                if not dry_run:
                    aplicar_observation_agent_v2(telefono_key, obs, world, perception)

                if obs.get("status") == "delegate_legacy":
                    status = "delegate_legacy"
                    break
                # V107 — INTERNAL PREFLIGHT REPLAN AUTHORITY.
                # `status=needs_user_input` describe la salida conversacional normal
                # de algunas READ tools, pero un paso marcado explícitamente con
                # replan_after=True pertenece al TaskGraph interno. Si la Observation
                # fue exitosa y NO descubrió ningún dato realmente faltante, primero
                # volvemos al Planner para que consuma ese hecho (por ejemplo:
                # disponibilidad exacta -> crear HOLD -> pedir comprobante).
                if _agent_v2_should_replan_after_observation(step, obs):
                    print(
                        "   ♻️ [AgentV2 V107 PREFLIGHT REPLAN] "
                        f"tool={tool} status={obs.get('status')} "
                        "sin missing real → vuelvo al Planner"
                    )
                    replan_requested = True
                    status = "continue"
                    break

                if obs.get("status") == "needs_user_input":
                    # La tool de disponibilidad puede descubrir que falta cancha.
                    if tool == "consultar_disponibilidad" and obs.get("missing"):
                        opts = obs.get("options") or []
                        missing_field = obs.get("missing")[0]
                        q_goal_context = list(_agent_v2_goal_for_tool(tool, goals))
                        booking_choice = bool(missing_field == "hora")
                        if booking_choice and "crear_reserva" not in q_goal_context:
                            q_goal_context.append("crear_reserva")

                        qobs = _agent_v2_observation(
                            "solicitar_dato",
                            True,
                            "needs_user_input",
                            {
                                "field": missing_field,
                                "options": opts,
                                "reason": "resultado de disponibilidad",
                                "goal_context": q_goal_context,
                                "booking_choice": booking_choice,
                                "dia": (obs.get("data") or {}).get("dia"),
                                "franja_dia": (obs.get("data") or {}).get("franja_dia"),
                            },
                            missing=obs.get("missing"),
                            options=opts,
                        )
                        observations.append(qobs)
                        if not dry_run:
                            aplicar_observation_agent_v2(
                                telefono_key,
                                qobs,
                                construir_world_state_agent_v2(
                                    telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path
                                ),
                                perception,
                            )
                    status = "waiting_user"
                    remaining_steps = plan_steps[step_index + 1:]
                    remaining_are_safe_reads = bool(remaining_steps) and all(
                        AGENT_V2_TOOL_CATALOG.get(
                            str(remaining.get("tool") or ""), {}
                        ).get("effect") == "read"
                        for remaining in remaining_steps
                        if isinstance(remaining, dict)
                    )
                    if remaining_are_safe_reads:
                        print(
                            "   🧩 [AgentV2 MULTI-SUBINTENT EXECUTOR] "
                            "un READ abrió pregunta, pero continúo los READs "
                            "independientes restantes"
                        )
                        continue
                    break
                if step.get("replan_after"):
                    replan_requested = True
                    break

                # Rebuild after observation for the next tool in the SAME plan.
                world = construir_world_state_agent_v2(telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path)

            if status in {"waiting_user", "delegate_legacy", "complete", "policy_blocked"}:
                break
            status = _agent_v2_goal_status(goals, observations)
            if status in {"complete", "waiting_user", "delegate_legacy"}:
                break
            if not replan_requested and observations:
                # Si ejecutamos un plan sin pedir replan, evaluar estado actual una vez más.
                status = _agent_v2_goal_status(goals, observations)
                if status != "continue":
                    break

    if status == "delegate_legacy":
        if not AGENT_V2_ALLOW_LANGUAGE_ROUTER_FALLBACK:
            print(
                "   🛟 [AgentV2 SAFE EXIT] capacidad no nativa; "
                "la regla universal resolverá el turno con handoff"
            )
            status = "needs_human_capability"
        else:
            return {
                "handled": False,
                "delegate_legacy": True,
                "world": world,
                "perception": perception,
                "goals": goals,
                "plan": last_plan,
                "observations": observations,
            }

    world = construir_world_state_agent_v2(telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path)

    # V2.10 NEXT BEST ACTION: después de resolver los goals, decidir si conviene
    # avanzar con UNA próxima pregunta stateful. El Composer no la inventa.
    nba = {"action": "none", "reason": "dry_run" if dry_run else ""}
    if not dry_run:
        nba_override = eval_context.get("next_best_action")
        if isinstance(nba_override, dict):
            nba = dict(nba_override)
        elif offline_e2e:
            # Offline E2E no consulta al LLM: usa exactamente los candidatos que
            # producción le entrega al selector NBA y elige conservadoramente la
            # primera continuación operativa disponible.
            candidates = _agent_v2_nba_candidates(world, perception, goals, observations, status)
            nba = next(
                (
                    c for c in candidates
                    if c.get("action") in {
                        "resume_pending", "offer_waitlist",
                        "ask_booking_datetime", "confirm_released_booking",
                    }
                ),
                {"action": "none", "reason": "sin próxima acción E2E"},
            )
            if nba.get("action") != "none":
                nba = dict(nba)
                nba["decision_reason"] = "AgentScenarioRunner offline candidate"
        else:
            nba = await elegir_next_best_action_agent_v2(
                world,
                perception,
                goals,
                observations,
                status,
                learning_policy=learning_policy_for_turn,
            )
        aplicar_next_best_action_agent_v2(telefono_key, nba)
        world = construir_world_state_agent_v2(
            telefono_key, prospecto, get_conversation_state(telefono_key), mensaje, image_path
        )
    print(
        f"   🧭 [AgentV2 NEXT BEST ACTION] action={nba.get('action')} "
        f"field={((nba.get('question') or {}).get('field'))} "
        f"reason={nba.get('decision_reason') or nba.get('reason')}"
    )

    response_obligations = _agent_v2_build_response_obligations(
        perception, observations, world, status
    )
    perception["response_obligations"] = list(
        response_obligations.get("items") or []
    )
    deterministic_response = _agent_v2_render_complete_response_obligations(
        response_obligations
    )

    if deterministic_response:
        response = deterministic_response
        print(
            "   🧾 [AgentV2 RESPONSE OBLIGATIONS] "
            "cobertura determinística completa; Composer/grounding/regenerator omitidos"
        )
    elif offline_e2e:
        # El runner prueba el contrato del Composer con hechos/observaciones reales
        # usando el fallback determinista; el modo live conserva Composer+Grounding LLM.
        response = _agent_v2_fallback_response(goals, observations, world, perception)
    else:
        response = await componer_respuesta_agent_v2(
            mensaje,
            world,
            perception,
            goals,
            observations,
            status,
            learning_policy=learning_policy_for_turn,
        )
    response = _agent_v2_append_nba_question(response, world)
    if not offline_e2e and not deterministic_response:
        response = await grounding_respuesta_agent_v2(response, mensaje, world, observations, goals, perception)
        response = await validar_y_regenerar_respuesta_agent_v2(
            response,
            mensaje,
            world,
            observations,
            goals,
            perception,
            status,
            prospecto,
        )
        verified_terminal = _agent_v2_verified_terminal_template(observations)
        if verified_terminal and str(response or "").strip() != verified_terminal:
            print(
                "   🧱 [AgentV2 TERMINAL TEMPLATE GUARD] "
                "restauro salida determinista posterior a tools verificadas"
            )
            response = verified_terminal

    response = _agent_v2_enforce_response_obligations(
        response, response_obligations
    )

    response = _agent_v2_apply_released_booking_rebook_reciprocity(
        response,
        perception,
        observations,
    )

    response, safe_exit = aplicar_regla_universal_salida_segura_agent_v2(
        response,
        world,
        perception,
        goals,
        observations,
        status,
        telefono_key,
        prospecto,
        page=page,
        dry_run=dry_run,
    )
    response = _agent_v2_enforce_monetary_claims(response, observations, world)
    if safe_exit.get("state") == "human_handoff":
        status = "complete"
    response = aplicar_negrita_fechas_horas_whatsapp(response)

    llm_calls_this_turn = int(AGENT_V2_TURN_LLM_CALLS.get() or 0)
    print(
        f"   [AgentV2 LLM BUDGET] calls_turn={llm_calls_this_turn} "
        f"mode={'minimal' if AGENT_V2_MINIMAL_LLM_MODE else 'full'}"
    )
    registrar_metrica_operativa("agent_v2_turn", {
        "telefono": telefono_key,
        "turn_id": turn_id,
        "goal": goals.get("primary_goal"),
        "status": status,
        "tools": [o.get("tool") for o in observations],
        "writes": [o.get("tool") for o in observations if AGENT_V2_TOOL_CATALOG.get(o.get("tool"), {}).get("effect") == "write"],
        "next_best_action": nba.get("action"),
        "safe_exit_state": safe_exit.get("state"),
        "safe_exit_fallback": bool(safe_exit.get("fallback_applied")),
        "llm_calls": llm_calls_this_turn,
        "learning_policy_version": int(
            (learning_policy_for_turn or {}).get("version") or 1
        ),
    })
    print(f"   ✅ [AgentV2 COMPLETE] goal={goals.get('primary_goal')} status={status} tools={[o.get('tool') for o in observations]}")
    result = {
        "handled": True,
        "delegate_legacy": False,
        "response": response,
        "world": world,
        "perception": perception,
        "goals": goals,
        "plan": last_plan,
        "observations": observations,
        "status": status,
        "next_best_action": nba,
        "safe_exit": safe_exit,
        "llm_calls": llm_calls_this_turn,
    }

    # V2.11 EXPERIENCE DB: producción se registra una sola vez, después de que
    # el turno terminó. Evals/dry-run jamás contaminan el dataset.
    if not dry_run and not eval_context:
        try:
            _agent_learning_capture_and_schedule(
                turn_id=turn_id,
                phone=telefono_key,
                message=mensaje,
                world_before=learning_world_before,
                world_after=world,
                perception=perception,
                goals=goals,
                plan=last_plan,
                observations=observations,
                status=status,
                nba=nba,
                response=response,
                learning_policy=learning_policy_for_turn,
            )
        except Exception as learning_exc:
            print(
                f"   ⚠️ [LEARNING CAPTURE] "
                f"{str(learning_exc)[:300]}"
            )

    return result


# ---------------------------------------------------------------------------
# AUTOMATIC BEHAVIOR EVALUATIONS
# ---------------------------------------------------------------------------
