def build_listar_torneos_admin_message() -> str:
    events = event_registration.list_business_events()
    if not events:
        return "🏆 No hay torneos activos configurados."
    blocks = ["🏆 *TORNEOS ACTIVOS*"]
    for index, event in enumerate(events, 1):
        state = event_registration.get_event_capacity_state(event)
        availability = (
            "🚫 COMPLETO" if state["is_full"]
            else f"✅ {state['available']} lugares disponibles"
        )
        blocks.append(
            f"{index}. {event.get('name')}\n"
            f"📅 {event_registration.format_event_date(event.get('date'))}\n"
            f"💰 {_fmt_event_money(event.get('registration_price'))} por equipo\n"
            f"🏅 Premio: {_fmt_event_prize(event.get('prize'))}\n"
            f"👥 {state['confirmed']}/{state['capacity']} confirmados\n"
            f"🔒 {state['active_holds']} cupos en hold\n"
            f"{availability}"
        )
    return "\n\n".join(blocks)



def _admin_business_events_store() -> Dict[str, Any]:
    """Lee business_events preservando el contenedor real del módulo."""
    raw = event_registration.read_business_events()
    if isinstance(raw, list):
        return {"raw": raw, "events": [dict(x) for x in raw if isinstance(x, dict)], "mode": "list", "key": None}
    if isinstance(raw, dict):
        for key in ("events", "business_events"):
            value = raw.get(key)
            if isinstance(value, list):
                return {
                    "raw": dict(raw),
                    "events": [dict(x) for x in value if isinstance(x, dict)],
                    "mode": "dict_list",
                    "key": key,
                }
        # Compatibilidad con un store indexado por event_id.
        mapping_events = [
            dict(value)
            for value in raw.values()
            if isinstance(value, dict) and value.get("event_id")
        ]
        if mapping_events:
            return {"raw": dict(raw), "events": mapping_events, "mode": "mapping", "key": None}
    raise RuntimeError("No pude interpretar business_events.json.")


def _admin_write_business_events_store(store: Dict[str, Any], events: List[Dict[str, Any]]) -> None:
    """Persiste el store usando la API del módulo y conserva su forma original."""
    mode = str((store or {}).get("mode") or "")
    raw = (store or {}).get("raw")
    if mode == "list":
        payload = [dict(x) for x in events]
    elif mode == "dict_list":
        payload = dict(raw or {})
        payload[(store or {}).get("key") or "events"] = [dict(x) for x in events]
    elif mode == "mapping":
        payload = {
            str(event.get("event_id")): dict(event)
            for event in events
            if event.get("event_id")
        }
    else:
        raise RuntimeError("Formato de business_events.json no soportado.")

    writer = getattr(event_registration, "write_business_events_atomic", None)
    if not callable(writer):
        raise RuntimeError(
            "El Event Registration Engine no expone write_business_events_atomic."
        )
    result = writer(payload)
    if result is False:
        raise RuntimeError("No pude persistir business_events.json.")


def _admin_normalize_event_date_optional(value: Any) -> Optional[str]:
    value = normalizar_valor_nullable(value)
    if not value:
        return None
    return event_registration.normalize_event_date(value)


def _admin_event_identity_text(event: Dict[str, Any]) -> str:
    return (
        f"{event.get('name')} — "
        f"{event_registration.format_event_date(event.get('date'))} — "
        f"ID {event.get('event_id')}"
    )


def _admin_resolve_business_event(comando: Dict[str, Any], *, editing: bool = False) -> Dict[str, Any]:
    """Resuelve una edición sin elegir arbitrariamente entre torneos homónimos."""
    store = _admin_business_events_store()
    events = [
        event for event in store["events"]
        if str(event.get("category") or "tournament").strip().casefold() == "tournament"
    ]
    event_id = str(comando.get("torneo_event_id") or "").strip()
    name = normalizar_valor_nullable(comando.get("nombre_torneo"))
    target_date_raw = comando.get("fecha_torneo_actual")
    if not editing and not target_date_raw:
        # En borrar_torneo una fecha provista identifica la edición.
        target_date_raw = comando.get("fecha_torneo")
    target_date = _admin_normalize_event_date_optional(target_date_raw)

    if event_id:
        matches = [
            event for event in events
            if str(event.get("event_id") or "").strip().casefold() == event_id.casefold()
        ]
    elif name:
        name_norm = normalizar_texto_ia(name)
        matches = [
            event for event in events
            if normalizar_texto_ia(event.get("name")) == name_norm
        ]
        if target_date:
            matches = [
                event for event in matches
                if str(event.get("date") or "") == target_date
            ]
    else:
        return {
            "ok": False,
            "reason": "missing_event_identity",
            "store": store,
            "response": (
                "Decime qué torneo querés modificar. Podés indicar el nombre o el ID. "
                "Ejemplo: `editar torneo Copa Primavera precio 150000`."
                if editing
                else "Decime qué torneo querés borrar. Ejemplo: `borrar torneo Copa Primavera`."
            ),
        }

    if not matches:
        return {
            "ok": False,
            "reason": "event_not_found",
            "store": store,
            "response": "No encontré un torneo que coincida con esos datos.",
        }
    if len(matches) > 1:
        opciones = "\n".join(f"• {_admin_event_identity_text(event)}" for event in matches[:10])
        verbo = "editar" if editing else "borrar"
        return {
            "ok": False,
            "reason": "event_ambiguous",
            "store": store,
            "matches": matches,
            "response": (
                f"Encontré más de una edición. Indicame cuál querés {verbo} usando su ID "
                f"o su fecha actual:\n{opciones}"
            ),
        }
    return {"ok": True, "store": store, "event": matches[0]}


def _admin_event_csv_path(event: Dict[str, Any]) -> str:
    persisted = str((event or {}).get("registrations_csv_path") or "").strip()
    if not persisted:
        return ""
    if os.path.isabs(persisted):
        return os.path.abspath(persisted)
    return os.path.abspath(os.path.join(str(event_registration.BASE_DIR), persisted))


def _admin_atomic_write_csv(path: str, fieldnames: List[str], rows: List[Dict[str, Any]]) -> None:
    os.makedirs(os.path.dirname(os.path.abspath(path)) or ".", exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(
        prefix=os.path.basename(path) + ".",
        suffix=".tmp",
        dir=os.path.dirname(os.path.abspath(path)) or ".",
    )
    os.close(fd)
    try:
        with open(tmp_path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(
                f,
                fieldnames=list(fieldnames),
                extrasaction="ignore",
            )
            writer.writeheader()
            writer.writerows(rows)
        os.replace(tmp_path, path)
    finally:
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except Exception:
            pass


def _admin_event_registration_fieldnames(path: str = "") -> List[str]:
    if path and os.path.exists(path):
        try:
            with open(path, "r", newline="", encoding="utf-8-sig") as f:
                reader = csv.reader(f)
                header = next(reader, [])
            header = [str(item or "").strip() for item in header if str(item or "").strip()]
            if header:
                return header
        except Exception:
            pass

    for attr in (
        "EVENT_REGISTRATION_FIELDNAMES",
        "EVENT_REGISTRATION_FIELDS",
        "REGISTRATION_FIELDNAMES",
        "REGISTRATION_FIELDS",
    ):
        value = getattr(event_registration, attr, None)
        if isinstance(value, (list, tuple)) and value:
            return [str(item) for item in value]

    return [
        "registration_id", "admin_id", "event_id", "event_name", "event_date",
        "team_name", "contact_name", "phone", "status",
        "registration_price", "required_payment", "paid_amount",
        "remaining_amount", "payment_status", "created_at",
        "hold_started_at", "hold_expires_at", "confirmed_at",
        "cancelled_at", "expired_at", "updated_at",
        "payment_method", "receipt_fingerprint", "last_payment_at",
    ]


def _admin_sync_event_registration_csv_identity(
    event: Dict[str, Any],
    *,
    new_name: Optional[str] = None,
    new_date: Optional[str] = None,
) -> None:
    path = _admin_event_csv_path(event)
    if not path or not os.path.exists(path):
        return
    try:
        with open(path, "r", newline="", encoding="utf-8-sig") as f:
            reader = csv.DictReader(f)
            fieldnames = [fn for fn in (reader.fieldnames or []) if fn]
            rows = [dict(row) for row in reader]
        if not fieldnames:
            fieldnames = _admin_event_registration_fieldnames(path)
        changed = False
        for row in rows:
            if new_name is not None and "event_name" in fieldnames:
                row["event_name"] = new_name
                changed = True
            if new_date is not None and "event_date" in fieldnames:
                row["event_date"] = new_date
                changed = True
        if changed:
            _admin_atomic_write_csv(path, fieldnames, rows)
    except Exception as exc:
        print(f"⚠️ [ADMIN TORNEO] No pude sincronizar identidad del CSV {path}: {exc}")


def _admin_refresh_event_runtime_state(
    event_id: str,
    event: Optional[Dict[str, Any]] = None,
    *,
    deleted: bool = False,
) -> None:
    """Actualiza/limpia referencias vivas para no requerir reinicio."""
    target_id = str(event_id or "").strip()
    if not target_id:
        return
    changed_any = False
    for state in conversation_states.values():
        if not isinstance(state, dict):
            continue
        changed = False
        event_state = state.get("event_registration")
        if isinstance(event_state, dict):
            event_state = dict(event_state)
            draft = dict(event_state.get("draft") or {})
            if str(draft.get("event_id") or "") == target_id:
                if deleted:
                    event_state["draft"] = {}
                    event_state["active_registration"] = None
                else:
                    draft["event_name"] = (event or {}).get("name")
                    draft["event_date"] = (event or {}).get("date")
                    event_state["draft"] = draft
                changed = True

            active = dict(event_state.get("active_registration") or {})
            if str(active.get("event_id") or "") == target_id:
                if deleted:
                    event_state["active_registration"] = None
                else:
                    active["event_name"] = (event or {}).get("name")
                    active["event_date"] = (event or {}).get("date")
                    event_state["active_registration"] = active
                changed = True

            for list_key in ("registrations_for_contact", "active_events"):
                rows = event_state.get(list_key)
                if not isinstance(rows, list):
                    continue
                new_rows = []
                for raw in rows:
                    if not isinstance(raw, dict):
                        new_rows.append(raw)
                        continue
                    row = dict(raw)
                    if str(row.get("event_id") or "") != target_id:
                        new_rows.append(row)
                        continue
                    changed = True
                    if deleted:
                        continue
                    row["event_name"] = (event or {}).get("name")
                    row["event_date"] = (event or {}).get("date")
                    if list_key == "active_events":
                        row["registration_price"] = (event or {}).get("registration_price")
                        row["capacity"] = (event or {}).get("capacity")
                    new_rows.append(row)
                event_state[list_key] = new_rows
            state["event_registration"] = event_state

        av2 = state.get("agent_v2")
        if isinstance(av2, dict):
            av2 = dict(av2)
            questions = []
            for raw in av2.get("open_questions") or []:
                if not isinstance(raw, dict):
                    continue
                q = dict(raw)
                if str(q.get("event_id") or "") != target_id:
                    questions.append(q)
                    continue
                changed = True
                if deleted:
                    continue
                q["event_name"] = (event or {}).get("name")
                q["event_date"] = (event or {}).get("date")
                questions.append(q)
            av2["open_questions"] = questions
            state["agent_v2"] = av2

        if changed:
            state["ultima_actualizacion"] = datetime.datetime.now(TIMEZONE)
            changed_any = True
    if changed_any:
        _persist_conversation_states()


def _admin_prune_event_alert_queue(event_id: str) -> None:
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.get("admin_alert_queue")
    changed = False
    if isinstance(queue, dict):
        for key in list(queue.keys()):
            item = queue.get(key)
            context = (item or {}).get("context") if isinstance(item, dict) else {}
            if isinstance(context, dict) and str(context.get("event_id") or "") == str(event_id):
                queue.pop(key, None)
                changed = True
    elif isinstance(queue, list):
        filtered = []
        for item in queue:
            context = (item or {}).get("context") if isinstance(item, dict) else {}
            if isinstance(context, dict) and str(context.get("event_id") or "") == str(event_id):
                changed = True
                continue
            filtered.append(item)
        if changed:
            state["admin_alert_queue"] = filtered
    if changed:
        _json_write(PROACTIVE_STATE_FILE, state)


