_ADMIN_EVENT_REGISTRATION_MUTATION_LOCK = threading.RLock()
_EVENT_REGISTRATION_ADMIN_ID_LOCK = threading.RLock()
# Namespace humano reservado para inscripciones de torneo. Las reservas normales
# usan IDs numéricos bajos; arrancar en 10001 evita colisiones prácticas y el
# resolver igualmente verifica la existencia real antes de enrutar un comando.
_EVENT_REGISTRATION_ADMIN_ID_MIN = 10001


def _event_registration_iter_admin_rows() -> List[Dict[str, Any]]:
    """Lee todas las filas de inscripción junto con su evento, sin reinterpretar nada."""
    rows: List[Dict[str, Any]] = []
    try:
        events = list((_admin_business_events_store() or {}).get("events") or [])
    except Exception:
        events = []
    for event in events:
        if not isinstance(event, dict):
            continue
        path = _admin_event_csv_path(event)
        if not path or not os.path.exists(path):
            continue
        try:
            with open(path, "r", encoding="utf-8-sig", newline="") as f:
                for raw in csv.DictReader(f):
                    if not isinstance(raw, dict):
                        continue
                    row = dict(raw)
                    row["__event"] = dict(event)
                    rows.append(row)
        except Exception as exc:
            print(f"⚠️ [EVENT ADMIN ID] No pude leer {path}: {exc}")
    return rows


def _event_registration_booking_numeric_ids() -> set:
    """IDs de reservas existentes para no entregar el mismo número a un torneo."""
    used = set()
    try:
        booking_rows = list(_calendar_rows_with_universal_ids() or [])
    except Exception:
        booking_rows = []
    try:
        booking_rows.extend(list(calendario._leer_terminadas() or []))
    except Exception:
        pass
    for row in booking_rows:
        if not isinstance(row, dict):
            continue
        raw = _normalizar_reservation_id_admin(row.get("reservation_id"))
        if raw and str(raw).isdigit():
            used.add(int(raw))
    return used


def _event_registration_internal_id_from_public_id(value: Any) -> str:
    """Resuelve el ID humano numérico a registration_id técnico."""
    raw = str(value or "").strip()
    raw = re.sub(r"(?i)^\s*(?:inscripcion\s+|torneo\s+|equipo\s+)?id\s*[:#-]?\s*", "", raw).strip()
    if raw.casefold().startswith("reg_"):
        return raw
    if not raw.isdigit():
        return ""
    wanted = str(int(raw))
    for row in _event_registration_iter_admin_rows():
        admin_id = str(row.get("admin_id") or "").strip()
        if admin_id.isdigit() and str(int(admin_id)) == wanted:
            return str(row.get("registration_id") or "").strip()
    return ""


def _event_registration_resolve_admin_identifier(value: Any) -> str:
    """Acepta tanto el ID técnico legado como el nuevo ID numérico humano."""
    raw = str(value or "").strip()
    if raw.casefold().startswith("reg_"):
        return raw
    return _event_registration_internal_id_from_public_id(raw)


def _event_registration_admin_public_id(
    registration_id: Any,
    *,
    create: bool = True,
) -> str:
    """Obtiene/asigna un ID numérico estable a una inscripción real.

    El registration_id `reg_...` permanece como PK interna. `admin_id` es sólo
    una clave operativa humana y se persiste dentro del CSV de la edición.
    """
    internal_id = _event_registration_resolve_admin_identifier(registration_id)
    if not internal_id:
        raw = str(registration_id or "").strip()
        if raw.casefold().startswith("reg_"):
            internal_id = raw
    if not internal_id:
        return ""

    try:
        match = event_registration.get_event_registration(registration_id=internal_id)
    except Exception:
        match = None
    if not isinstance(match, dict):
        return ""
    current = str(((match.get("registration") or {}).get("admin_id")) or "").strip()
    if current.isdigit():
        return str(int(current))
    if not create:
        return ""

    with _EVENT_REGISTRATION_ADMIN_ID_LOCK:
        try:
            refreshed = event_registration.get_event_registration(registration_id=internal_id)
        except Exception:
            refreshed = None
        current = str((((refreshed or {}).get("registration") or {}).get("admin_id")) or "").strip()
        if current.isdigit():
            return str(int(current))

        used = _event_registration_booking_numeric_ids()
        for row in _event_registration_iter_admin_rows():
            candidate_raw = str(row.get("admin_id") or "").strip()
            if candidate_raw.isdigit():
                used.add(int(candidate_raw))

        candidate = int(_EVENT_REGISTRATION_ADMIN_ID_MIN)
        while candidate in used:
            candidate += 1

        def attach_admin_id(row: Dict[str, Any]) -> Dict[str, Any]:
            existing = str(row.get("admin_id") or "").strip()
            if existing.isdigit():
                return row
            row["admin_id"] = str(candidate)
            row["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            return row

        result = _admin_mutate_event_registration_row(internal_id, attach_admin_id)
        if not result.get("ok"):
            return ""
        persisted = str(((result.get("registration") or {}).get("admin_id")) or "").strip()
        if persisted.isdigit():
            print(
                "   🆔 [EVENT ADMIN ID] "
                f"{internal_id} → ID {int(persisted)}"
            )
            return str(int(persisted))
    return ""


def _event_registration_publicize_admin_alert_text(
    text: str,
    registration: Dict[str, Any],
) -> str:
    """Oculta el PK técnico en mensajes al encargado y muestra el ID humano."""
    body = str(text or "")
    internal_id = str((registration or {}).get("registration_id") or "").strip()
    if not internal_id:
        return body
    public_id = _event_registration_admin_public_id(internal_id, create=True)
    if not public_id:
        return body
    body = body.replace(f"🆔 {internal_id}", f"🆔 ID {public_id}")
    body = body.replace(f"ID {internal_id}", f"ID {public_id}")
    body = body.replace(internal_id, public_id)
    return body


def _admin_get_event_registration_by_id(registration_id: str) -> Optional[Dict[str, Any]]:
    registration_id = _event_registration_resolve_admin_identifier(registration_id)
    if not registration_id:
        return None
    try:
        match = event_registration.get_event_registration(registration_id=registration_id)
    except Exception:
        match = None
    return dict(match) if isinstance(match, dict) else None


def _admin_mutate_event_registration_row(
    registration_id: str,
    mutator,
) -> Dict[str, Any]:
    registration_id = _event_registration_resolve_admin_identifier(registration_id)
    match = _admin_get_event_registration_by_id(registration_id)
    if not match:
        return {"ok": False, "reason": "registration_not_found"}
    event = dict(match.get("event") or {})
    path = _admin_event_csv_path(event)
    if not path or not os.path.exists(path):
        return {"ok": False, "reason": "event_csv_missing"}

    with _ADMIN_EVENT_REGISTRATION_MUTATION_LOCK:
        try:
            with open(path, "r", encoding="utf-8-sig", newline="") as f:
                reader = csv.DictReader(f)
                fieldnames = list(reader.fieldnames or [])
                rows = [dict(row) for row in reader]
        except Exception as exc:
            return {"ok": False, "reason": "event_csv_read_failed", "detail": str(exc)}
        if not fieldnames:
            fieldnames = _admin_event_registration_fieldnames(path)

        updated = None
        for index, row in enumerate(rows):
            if str(row.get("registration_id") or "").strip() != str(registration_id):
                continue
            candidate = mutator(dict(row))
            if not isinstance(candidate, dict):
                return {"ok": False, "reason": "event_registration_mutation_rejected"}
            for key in candidate.keys():
                if key not in fieldnames:
                    fieldnames.append(key)
            rows[index] = candidate
            updated = dict(candidate)
            break
        if updated is None:
            return {"ok": False, "reason": "registration_not_found"}

        base_dir = os.path.dirname(path) or "."
        fd, tmp_path = tempfile.mkstemp(prefix="admin_event_registration_", suffix=".tmp", dir=base_dir)
        try:
            with os.fdopen(fd, "w", encoding="utf-8-sig", newline="") as f:
                writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
                writer.writeheader()
                writer.writerows(rows)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except OSError:
                    pass
            os.replace(tmp_path, path)
        except Exception as exc:
            try:
                os.remove(tmp_path)
            except OSError:
                pass
            return {"ok": False, "reason": "event_csv_write_failed", "detail": str(exc)}

    refreshed = _admin_get_event_registration_by_id(registration_id)
    registration = dict((refreshed or {}).get("registration") or updated)
    refreshed_event = dict((refreshed or {}).get("event") or event)
    try:
        capacity_state = event_registration.get_event_capacity_state(refreshed_event)
    except Exception:
        capacity_state = {}
    return {
        "ok": True,
        "event": refreshed_event,
        "registration": registration,
        "capacity_state": capacity_state,
    }


