def _fecha_obj_desde_texto_admin(dia_texto: str = "") -> datetime.date:
    hoy = datetime.datetime.now(TIMEZONE).date()
    dia_texto = normalizar_valor_nullable(dia_texto)
    if not dia_texto:
        return hoy

    texto = str(dia_texto).strip().lower()
    if texto == "hoy":
        return hoy
    if texto == "mañana":
        return hoy + datetime.timedelta(days=1)
    if texto in ("pasado mañana", "pasado"):
        return hoy + datetime.timedelta(days=2)

    m_iso = re.search(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", texto)
    if m_iso:
        try:
            return datetime.date(int(m_iso.group(1)), int(m_iso.group(2)), int(m_iso.group(3)))
        except ValueError:
            pass

    dia_resuelto = resolver_fecha(texto)
    m = re.search(r"(\d{1,2})/(\d{1,2})(?:/(\d{2,4}))?", dia_resuelto)
    if m:
        dia = int(m.group(1))
        mes = int(m.group(2))
        anio = int(m.group(3)) if m.group(3) else hoy.year
        if anio < 100:
            anio += 2000
        try:
            return datetime.date(anio, mes, dia)
        except ValueError:
            pass

    return hoy


def _fecha_row_es_fecha(fecha_raw: str, fecha_objetivo: datetime.date) -> bool:
    texto = str(fecha_raw or "").strip().lower()
    if not fecha_objetivo:
        return False

    m = re.search(r"(\d{1,2})/(\d{1,2})(?:/(\d{2,4}))?", texto)
    if not m:
        return False

    dia = int(m.group(1))
    mes = int(m.group(2))
    anio = int(m.group(3)) if m.group(3) else fecha_objetivo.year
    if anio < 100:
        anio += 2000
    try:
        return datetime.date(anio, mes, dia) == fecha_objetivo
    except ValueError:
        return False


def _fmt_horas_operativas(horas: float) -> str:
    try:
        valor = float(horas)
    except (TypeError, ValueError):
        valor = 0.0
    if valor.is_integer():
        return f"{int(valor)} h"
    return f"{valor:g} h"


def _agenda_hora_limite_texto(hora: Any) -> str:
    minutos = _hora_a_minutos(hora)
    if minutos is None:
        return str(hora or "").strip()
    hora_numero = (minutos // 60) % 24
    minuto_numero = minutos % 60
    if minuto_numero:
        return f"{hora_numero:02d}:{minuto_numero:02d}"
    return f"{hora_numero:02d}"


def _agenda_franjas_atencion_texto() -> str:
    franjas = []
    for inicio_raw, fin_raw in CALL_TIME_WINDOWS:
        inicio = _hora_a_minutos(inicio_raw)
        fin = _hora_a_minutos(fin_raw)
        if fin == 0 and inicio is not None and inicio > 0:
            fin = 24 * 60
        if inicio is None or fin is None or fin <= inicio:
            continue
        franjas.append(
            f"de {_agenda_hora_limite_texto(inicio_raw)} "
            f"a {_agenda_hora_limite_texto(fin_raw)}hs"
        )
    return " y ".join(franjas) or "durante el horario de atención"


def _slot_agenda_ocupado_por_rango(turnos_dia: List[Dict[str, Any]], cancha: str, hora_slot: str) -> bool:
    slot_inicio = _hora_a_minutos_local(hora_slot)
    if slot_inicio is None:
        return False
    paso = int(TURN_DURATION_MINUTES or 60)
    slot_fin = slot_inicio + paso
    cancha_norm = str(cancha or "").strip().casefold()

    for row in turnos_dia:
        row_cancha = str(row.get("cancha") or "").strip().casefold()
        if row_cancha != cancha_norm:
            continue
        row_inicio = _hora_a_minutos_local(row.get("hora") or "")
        if row_inicio is None:
            continue
        row_duracion = normalizar_duracion_horas(row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS)
        row_fin = row_inicio + int(round(row_duracion * 60))
        if slot_inicio < row_fin and slot_fin > row_inicio:
            return True
    return False


def build_turnos_dia_message(dia_texto: str = "") -> str:
    # Regex se usa únicamente para parsear ISO.
    # No se utiliza para inferir intención semántica.
    fecha_objetivo = None
    iso_match = re.search(
        r"(\d{4})-(\d{1,2})-(\d{1,2})",
        str(dia_texto or ""),
    )
    if iso_match:
        try:
            fecha_objetivo = datetime.date(int(iso_match.group(1)), int(iso_match.group(2)), int(iso_match.group(3)))
        except ValueError:
            fecha_objetivo = None

    if not fecha_objetivo:
        fecha_objetivo = _fecha_obj_desde_texto_admin(dia_texto)

    dia_label = f"{nombre_dia_es(fecha_objetivo)} {fecha_objetivo.strftime('%d/%m')}"
    reservas = _calendar_rows_operativas_y_rescatadas(include_finished=True)
    turnos_dia = [
        dict(row)
        for row in reservas
        if _fecha_row_es_fecha(row.get("fecha", ""), fecha_objetivo)
        and _reserva_activa(row)
    ]
    ahora = datetime.datetime.now(TIMEZONE)
    es_bloqueo = lambda r: str(r.get("telefono") or "").startswith("ADMIN:CERRADO") or str(r.get("nombre") or "").strip().casefold() == "cerrado"
    turnos_reales = [r for r in turnos_dia if not es_bloqueo(r)]
    turnos_logicos = _agenda_reservas_logicas(turnos_reales)
    confirmados = [
        row for row in turnos_logicos
        if _reserva_operativamente_firme(row)
    ]
    pendientes = [
        row for row in turnos_logicos
        if not _reserva_operativamente_firme(row)
        and str(row.get("senia_estado") or "").strip().casefold()
        in {"pendiente", "parcial"}
    ]
    sin_telefono = [
        row for row in turnos_logicos
        if not normalize_phone(row.get("telefono") or "")
    ]
    proximos_2h = []
    for row in turnos_logicos:
        inicio = _parse_reserva_datetime(row)
        if inicio and ahora <= inicio <= ahora + datetime.timedelta(hours=2):
            proximos_2h.append(row)

    clientes_riesgo = []
    for row in turnos_logicos:
        tel = _telefono_reserva_para_mensaje(row)
        nombre = str(row.get("nombre") or "").strip()
        memoria = cargar_memoria_cliente(tel) if tel else cargar_memoria_cliente(f"NOMBRE:{nombre}") if nombre else {}
        no_shows = int(memoria.get("no_shows") or 0)
        cancelaciones_tarde = int(memoria.get("cancelaciones_tarde") or 0)
        if no_shows or cancelaciones_tarde:
            clientes_riesgo.append((nombre or tel or "cliente", no_shows, cancelaciones_tarde))
    riesgo_txt = "; ".join(f"{n} ({ns} no-show, {ct} tarde)" for n, ns, ct in clientes_riesgo[:4]) or "ninguno"

    por_cancha = {}
    turnos_mostrados = set()
    for row in sorted(
        turnos_dia,
        key=lambda item: (
            str(item.get("cancha") or "").casefold(),
            _hora_a_minutos_local(item.get("hora") or "") or 10**9,
        ),
    ):
        cancha = row.get("cancha") or "Sin cancha"
        hora = row.get("hora") or "sin hora"
        reservation_id = _normalizar_reservation_id_admin(row.get("reservation_id"))
        display_key = (str(cancha).casefold(), reservation_id) if reservation_id else (
            str(cancha).casefold(),
            normalize_phone(row.get("telefono") or "") or str(row.get("nombre") or "").casefold(),
            normalizar_hora_detectada(hora) or str(hora),
        )
        if display_key in turnos_mostrados:
            continue
        turnos_mostrados.add(display_key)
        nombre = row.get("nombre") or "Cliente"
        telefono = row.get("telefono") or "sin tel"
        duracion = normalizar_duracion_horas(
            row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        rango_turno = rango_horario_texto(hora, duracion)
        if es_bloqueo(row):
            texto_turno = f"⛔ {rango_turno} - bloqueado"
            if row.get("notas"):
                texto_turno += f" - {row.get('notas')}"
        else:
            senia_estado = str(row.get("senia_estado") or "").strip().lower()
            ok_estado = obtener_estado_ok_asistencia(row)
            estado_icono = "✅" if _reserva_operativamente_firme(row) else "💵" if senia_estado in {"pendiente", "parcial"} else "📌"
            estado_txt = (
                "confirmado"
                if senia_estado == "pagada"
                else "confirmado - diferencia de seña en efectivo"
                if senia_estado == "parcial_efectivo_pendiente"
                else "seña parcial"
                if senia_estado == "parcial"
                else "seña pendiente"
                if senia_estado == "pendiente"
                else str(row.get("estado") or "").strip()
            )
            texto_turno = f"{estado_icono} {rango_turno} - {nombre}"
            detalle = []
            if normalize_phone(telefono):
                detalle.append(f"📱 {telefono}")
            else:
                detalle.append("📵 sin teléfono")
            if estado_txt:
                detalle.append(estado_txt)
            if ok_estado:
                detalle.append(ok_estado)
            if detalle:
                texto_turno += "\n   " + " | ".join(detalle)
            if str(row.get("con_quincho") or "").strip().lower() in ("si", "sí", "true", "1"):
                quincho_nombre = row.get("quincho") or "Quincho/parrilla"
                q_inicio = row.get("quincho_hora_inicio") or hora
                q_duracion = normalizar_duracion_horas(row.get("quincho_duracion_horas") or DEFAULT_TURN_DURATION_HOURS)
                texto_turno += f"\n   🔥 {quincho_nombre} {rango_horario_texto(q_inicio, q_duracion)}"
        por_cancha.setdefault(cancha, []).append((normalizar_hora_detectada(hora) or hora, texto_turno.strip()))

    horas_slot = float(TURN_DURATION_MINUTES or 60) / 60.0
    slots_referencia = []
    for inicio, fin in obtener_franjas_atencion_minutos():
        actual = inicio
        paso_minutos = int(TURN_DURATION_MINUTES or 60)
        while actual is not None and fin is not None and actual + paso_minutos <= fin:
            slots_referencia.append(_minutos_a_hora(actual))
            actual += paso_minutos

    court_names = [court.get("name") or "Cancha" for court in COURTS]
    canchas_horas_libres = 0.0
    for cancha in court_names:
        for hora_slot in slots_referencia:
            if not _slot_agenda_ocupado_por_rango(turnos_dia, cancha, hora_slot):
                canchas_horas_libres += horas_slot

    canchas_horas_reservadas = sum(
        normalizar_duracion_horas(
            row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        for row in turnos_logicos
        if str(row.get("cancha") or "").strip()
    )
    quincho_horas_reservadas = 0.0
    quincho_horas_libres = 0.0
    if CON_QUINCHO and QUINCHOS:
        quincho_horas_reservadas = sum(
            normalizar_duracion_horas(r.get("quincho_duracion_horas") or DEFAULT_TURN_DURATION_HOURS)
            for r in turnos_logicos
            if str(r.get("con_quincho") or "").strip().lower() in ("si", "sí", "true", "1")
        )
        capacidad_quincho = len(slots_referencia) * len(QUINCHOS) * horas_slot
        quincho_horas_libres = max(
            0.0,
            capacidad_quincho - quincho_horas_reservadas,
        )
    lines = [
        f"📅 *Agenda - {dia_label}*",
        "",
        "*Resumen*",
        f"✅ Confirmados: {len(confirmados)}",
        f"💵 Pendientes de seña: {len(pendientes)}",
        f"📵 Sin teléfono: {len(sin_telefono)}",
        f"⏰ Próximos 2 hs: {len(proximos_2h)}",
        f"⚠️ Clientes con riesgo: {riesgo_txt}",
        "",
        "*Ocupación*",
        f"⚽ Canchas: {_fmt_horas_operativas(canchas_horas_reservadas)} reservadas / {_fmt_horas_operativas(canchas_horas_libres)} libres",
        (
            f"🔥 Quincho/parrilla: {_fmt_horas_operativas(quincho_horas_reservadas)} reservadas / {_fmt_horas_operativas(quincho_horas_libres)} libres"
            if CON_QUINCHO else
            "🔥 Quincho/parrilla: deshabilitado"
        ),
        "",
        "━━━━━━━━━━━━━━",
        "*Disponibilidad y turnos por cancha*",
        "",
    ]
    if not turnos_dia:
        lines.append(f"No hay turnos reservados para {dia_label}.")
    franja_atencion = _agenda_franjas_atencion_texto()
    for cancha in sorted(set(court_names) | set(por_cancha.keys())):
        items = sorted(por_cancha.get(cancha) or [], key=lambda item: item[0])
        if items:
            lines.append(f"🟢 *{cancha}:* libre {franja_atencion}, excepto:")
            lines.extend(texto for _, texto in items)
        else:
            lines.append(f"🟢 *{cancha}:* {franja_atencion} libre")
        lines.append("")
    return "\n".join(lines).strip()


def build_senias_pendientes_message(dia_texto: str = "") -> str:
    fecha_objetivo = _fecha_obj_desde_texto_admin(dia_texto) if dia_texto else None
    rows = list(calendario.asegurar_ids_reservas_pendientes() or [])
    try:
        rows.extend(calendario._leer_terminadas() or [])
    except Exception as exc:
        print(f"[PENDIENTES ADMIN] No pude leer turnos terminados: {exc}")

    groups = {}
    seen_rows = set()
    for row in rows:
        reservation_id = _normalizar_reservation_id_admin(row.get("reservation_id"))
        if not reservation_id:
            continue
        if fecha_objetivo and not _fecha_row_es_fecha(row.get("fecha", ""), fecha_objetivo):
            continue
        fingerprint = "|".join([
            reservation_id,
            str(row.get("fecha") or "").strip(),
            str(row.get("hora") or "").strip(),
            str(row.get("cancha") or "").strip().casefold(),
            str(row.get("estado") or "").strip().casefold(),
        ])
        if fingerprint in seen_rows:
            continue
        seen_rows.add(fingerprint)
        groups.setdefault(reservation_id, []).append(dict(row))

    saldos_firmes = []
    holds_senia = []
    revisar_pago = []
    vencidas_efectivo = []
    for reservation_id, group in groups.items():
        row = _reservation_primary_row(group)
        states = {
            _business_report_normalize_text(item.get("estado"))
            for item in group
        }
        if any(reserva_tiene_senia_pendiente(item) and _reserva_activa(item) for item in group):
            holds_senia.append((reservation_id, row))
            continue
        if "hold_expirado" in states or "hold expirado" in states:
            if any(
                _business_report_normalize_text(item.get("senia_estado"))
                in {"pendiente efectivo", "pendiente_efectivo"}
                or _business_report_normalize_text(item.get("payment_method")) == "efectivo"
                for item in group
            ):
                vencidas_efectivo.append((reservation_id, row))
            continue
        if states.intersection({"cancelado", "cancelada", "no_show", "no show", "no vino"}):
            continue

        total = _monto_a_int(row.get("precio_total"))
        if total is None:
            duration = normalizar_duracion_horas(
                row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
            )
            total = calcular_precio_total(duration)
            total += _monto_a_int(row.get("quincho_precio_total")) or 0
        deposit = _senia_pagada_acumulada(row, total)
        due = _monto_a_int(row.get("monto_pendiente"))
        deposit_state = _business_report_normalize_text(row.get("senia_estado"))
        deposit_paid = deposit_state == "pagada"
        payment_verified = bool(
            deposit_paid
            or deposit_state in {"parcial efectivo pendiente", "parcial_efectivo_pendiente"}
            or not REQUIRES_DEPOSIT
        )
        if due is None:
            due = max(0, total - deposit) if (payment_verified or deposit > 0) else total
        if due <= 0:
            continue
        item = (reservation_id, row, total, deposit, due)
        if payment_verified:
            saldos_firmes.append(item)
        elif any(_reserva_activa(group_row) for group_row in group):
            revisar_pago.append(item)

    def sort_key(item: tuple) -> tuple:
        row = item[1]
        return (
            _parse_fecha_row(row.get("fecha") or "") or datetime.date.max,
            normalizar_hora_detectada(row.get("hora")) or "",
            str(row.get("cancha") or ""),
        )

    saldos_firmes.sort(key=sort_key)
    holds_senia.sort(key=sort_key)
    revisar_pago.sort(key=sort_key)
    vencidas_efectivo.sort(key=sort_key)

    titulo = "💰 *PENDIENTES DE COBRO Y CONFIRMACIÓN*"
    if fecha_objetivo:
        titulo += f" - {nombre_dia_es(fecha_objetivo)} {fecha_objetivo.strftime('%d/%m')}"
    if not saldos_firmes and not holds_senia and not revisar_pago and not vencidas_efectivo:
        return titulo + "\n\nNo hay saldos firmes por cobrar, holds esperando seña ni reservas para revisar."

    state = _json_read(PROACTIVE_STATE_FILE, {"pending_deposit_seen_at": {}})
    pending_seen = state.get("pending_deposit_seen_at") or {}
    ahora = datetime.datetime.now(TIMEZONE)
    total_saldo_firme = sum(item[4] for item in saldos_firmes)
    lines = [
        titulo,
        "",
        "*Resumen*",
        f"💸 Saldo firme total por cobrar: {_fmt_precio(total_saldo_firme)}",
        f"✅ Reservas firmes con saldo: {len(saldos_firmes)}",
        f"⏳ Holds esperando seña: {len(holds_senia)}",
        f"⚠️ Estados de pago a revisar: {len(revisar_pago)}",
        "",
    ]

    def append_common(lines_out: List[str], reservation_id: str, row: Dict[str, Any]) -> tuple:
        duracion = normalizar_duracion_horas(
            row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
        )
        total = _monto_a_int(row.get("precio_total"))
        if total is None:
            total = calcular_precio_total(duracion)
            total += _monto_a_int(row.get("quincho_precio_total")) or 0
        senia = _senia_guardada_o_configurada(row, total)
        lines_out.extend([
            f"*ID {reservation_id}*",
            f"👤 {row.get('nombre') or 'Cliente'}",
            f"📱 {row.get('telefono') or 'sin teléfono'}",
            f"📅 {row.get('fecha') or 'sin fecha'}",
            f"⚽ {row.get('cancha') or 'sin cancha'} - {rango_horario_texto(row.get('hora'), duracion)} ({duracion:g} hs)",
        ])
        if str(row.get("con_quincho") or "").strip().lower() in ("si", "sí", "true", "1"):
            lines_out.append(
                f"🔥 {row.get('quincho') or 'Quincho'} - "
                f"{rango_horario_texto(row.get('quincho_hora_inicio'), row.get('quincho_duracion_horas') or 1)}"
            )
        lines_out.append(f"💰 Total del turno: {_fmt_precio(total)}")
        return total, senia

    if saldos_firmes:
        lines.extend(["✅ *RESERVAS FIRMES CON SALDO A COBRAR*", ""])
        for reservation_id, row, total, deposit, due in saldos_firmes[:40]:
            append_common(lines, reservation_id, row)
            if REQUIRES_DEPOSIT:
                cash_pending = _monto_a_int(row.get("senia_efectivo_pendiente")) or 0
                lines.append(f"💵 Transferido: {_fmt_precio(deposit)}")
                if cash_pending:
                    lines.append(f"💵 Diferencia de seña en efectivo: {_fmt_precio(cash_pending)}")
                else:
                    lines.append("✅ Seña requerida completada")
            else:
                lines.append("💵 Seña: no requerida")
            lines.extend([
                f"💸 *Saldo firme por cobrar: {_fmt_precio(due)}*",
                f"Para registrar pago total: `confirmar total ID {reservation_id}`",
                "",
            ])

    if holds_senia:
        lines.extend(["⏳ *HOLDS ESPERANDO SEÑA - NO SON DEUDA FIRME*", ""])
        for reservation_id, row in holds_senia[:40]:
            _, senia = append_common(lines, reservation_id, row)
            transferido = _senia_pagada_acumulada(row, row.get("precio_total"))
            faltante = _senia_faltante_para_confirmar(row, row.get("precio_total"))
            seen = _parse_iso_datetime(
                pending_seen.get(_proactive_key("senia_expiration", row))
            )
            age = ""
            if seen:
                age = f" - hace {max(0, int((ahora - seen).total_seconds() / 60))} min"
            payment_method = _business_report_normalize_text(
                row.get("payment_method") or "transferencia"
            )
            lines.extend([
                f"💵 Seña requerida: {_fmt_precio(senia)} - pendiente ({payment_method}){age}",
                *(
                    [
                        f"✅ Transferido y validado: {_fmt_precio(transferido)}",
                        f"💸 Falta para confirmar: {_fmt_precio(faltante)}",
                    ]
                    if transferido > 0 else []
                ),
                "📌 Todavía no se contabiliza como saldo a cobrar.",
                f"Para confirmar la seña: `confirmar seña ID {reservation_id}`",
                "",
            ])

    if revisar_pago:
        lines.extend(["⚠️ *RESERVAS CON PAGO SIN VERIFICAR*", ""])
        for reservation_id, row, _total, _deposit, _due in revisar_pago[:30]:
            append_common(lines, reservation_id, row)
            lines.extend([
                "💵 No hay seña o pago verificado en el calendario.",
                "📌 Fuera del saldo firme hasta que un administrador revise el pago.",
                f"Ver detalle: `ver ID {reservation_id}`",
                "",
            ])

    if vencidas_efectivo:
        lines.extend(["⚠️ *PRESENCIALES VENCIDAS - HORARIO LIBERADO*", ""])
        for reservation_id, row in vencidas_efectivo[:30]:
            append_common(lines, reservation_id, row)
            lines.extend([
                "⚠️ El turno está libre y debe revalidarse antes de confirmar.",
                f"Para revalidar y confirmar la seña: `confirmar seña ID {reservation_id}`",
                "",
            ])

    lines.extend([
        "*Comandos de cobro*",
        "• Seña en efectivo: `confirmar seña ID <número>`",
        "• Pago total: `confirmar total ID <número>`",
    ])
    return "\n".join(lines)


def _normalizar_categoria_ayuda(texto: str) -> str:
    texto_norm = unicodedata.normalize("NFKD", str(texto or "").lower())
    texto_norm = "".join(ch for ch in texto_norm if not unicodedata.combining(ch))
    texto_norm = re.sub(r"\b(ayuda|help|comandos?|disponibles|que podes hacer|que puedes hacer)\b", " ", texto_norm)
    texto_norm = re.sub(r"\s+", " ", texto_norm).strip()

    if not texto_norm:
        return "todos"
    if re.search(r"\b(blacklist|bloqueados|bloquear numero|bloquear contacto|desbloquear numero|desbloquear contacto)\b", texto_norm):
        return "blacklist"
    if re.search(r"\b(admin|admins|autorizado|autorizados)\b", texto_norm):
        return "admins"
    if re.search(r"\b(caso|casos|derivacion|derivaciones|atencion humana)\b", texto_norm):
        return "casos"
    if re.search(r"\b(no show|no-show|no vino|asistencia|ausencia)\b", texto_norm):
        return "asistencia"
    if re.search(r"\b(fijo|fijos|recurrente|recurrentes)\b", texto_norm):
        return "turnos_fijos"
    if re.search(r"\b(bloquear dia|desbloquear dia|cerrar|abrir|feriado|mantenimiento)\b", texto_norm):
        return "bloqueos"
    if re.search(r"\b(reporte|reportes|informe|informes|ocupacion|facturacion|finanzas|conversion|demanda|resumen semanal|resumen mensual)\b", texto_norm):
        return "reportes"
    if re.search(r"\b(torneo|torneos|campeonato|campeonatos|inscripciones)\b", texto_norm):
        return "torneos"
    if re.search(r"\b(csv|datos|comprobantes usados|used payment receipts|reset de datos|mantenimiento de datos)\b", texto_norm):
        return "datos"
    if re.search(r"\b(config|configuracion|negocio|asistente|direccion|alias|cancha|canchas|quincho|quinchos|parrilla|parrillas|precio|precios|senia|seña|horario|atencion)\b", texto_norm):
        return "config"
    if re.search(r"\b(reserva|reservas|agenda|turno|turnos|borrar|agregar)\b", texto_norm):
        return "reservas"
    if re.search(r"\b(agente|pausar|reanudar|estado|modo|prueba|pruebas|usuario)\b", texto_norm):
        return "agente"
    return "todos"


