# FUNCIÓN: ACTUALIZAR ESTADO EN NEGOCIOS_CONTACTADOS.CSV
# ================================
def actualizar_estado_en_negocios_csv(telefono: str, nuevo_estado: str, razon_ia: str = ""):
    if not telefono:
        return False

    telefono_normalizado = normalize_phone(telefono)

    if not os.path.exists(NEGOCIOS_CSV):
        return False

    try:
        rows = []
        actualizado = False

        with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            fieldnames = [fn for fn in (reader.fieldnames or []) if fn is not None]
            for row in reader:
                row = {k: v for k, v in row.items() if k is not None}
                if normalize_phone(row.get("telefono", "")) == telefono_normalizado:
                    row["estado"] = nuevo_estado
                    actualizado = True
                    print(f"📝 [CSV] Actualizando: {row.get('nombre')} -> {nuevo_estado}")
                rows.append(row)

        fieldnames, rows, columna_actualizada = asegurar_columna_cliente(fieldnames, rows)

        if actualizado or columna_actualizada:
            with open(NEGOCIOS_CSV, 'w', encoding='utf-8-sig', newline='') as f:
                writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
                writer.writeheader()
                writer.writerows(rows)
            return True
        return False
    except Exception as e:
        print(f"⚠️ [CSV] Error actualizando: {e}")
        return False

def actualizar_cliente_en_negocios_csv(telefono: str, es_cliente: bool = True, nuevo_estado: str = "Cliente existente"):
    if not telefono or str(telefono).startswith("NOMBRE:"):
        return False

    telefono_normalizado = normalize_phone(telefono)

    if not os.path.exists(NEGOCIOS_CSV):
        return False

    try:
        rows = []
        actualizado = False

        with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            fieldnames = [fn for fn in (reader.fieldnames or []) if fn is not None]
            for row in reader:
                row = {k: v for k, v in row.items() if k is not None}
                if normalize_phone(row.get("telefono", "")) == telefono_normalizado:
                    row[CLIENTE_FIELD] = CLIENTE_SI if es_cliente else CLIENTE_NO
                    if nuevo_estado:
                        row["estado"] = nuevo_estado
                    actualizado = True
                    print(f"📝 [CSV] {row.get('nombre')} -> {CLIENTE_FIELD}={row[CLIENTE_FIELD]}")
                rows.append(row)

        fieldnames, rows, columna_actualizada = asegurar_columna_cliente(fieldnames, rows)

        if actualizado or columna_actualizada:
            with open(NEGOCIOS_CSV, 'w', encoding='utf-8-sig', newline='') as f:
                writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
                writer.writeheader()
                writer.writerows(rows)
            return actualizado
        return False
    except Exception as e:
        print(f"⚠️ [CSV] Error actualizando '{CLIENTE_FIELD}': {e}")
        return False

def agregar_o_actualizar_contacto_en_csv(telefono: str, nombre: str, es_cliente: bool = False, estado: str = "Contacto agendado"):
    """
    Agrega un contacto al CSV si no existe, o actualiza sus datos si existe.
    """
    if not telefono:
        return False

    identificador = telefono
    es_agendado = telefono.startswith("NOMBRE:")

    if es_agendado:
        nombre_limpio = telefono.replace("NOMBRE:", "")
        identificador = f"AGENDADO:{nombre_limpio}"

    file_exists = os.path.exists(NEGOCIOS_CSV)

    try:
        rows = []
        encontrado = False
        fieldnames = []

        if file_exists:
            with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig') as f:
                reader = csv.DictReader(f)
                fieldnames = [fn for fn in (reader.fieldnames or []) if fn is not None]
                for row in reader:
                    row = {k: v for k, v in row.items() if k is not None}
                    telefono_row = row.get("telefono", "")

                    if es_agendado:
                        if telefono_row == telefono:
                            encontrado = True
                            row[CLIENTE_FIELD] = CLIENTE_SI if es_cliente else CLIENTE_NO
                            if estado:
                                row["estado"] = estado
                            row["nombre"] = nombre
                            print(f"   📝 [CSV] Contacto agendado ACTUALIZADO: {telefono} -> es_cliente={row[CLIENTE_FIELD]}")
                    else:
                        telefono_normalizado = normalize_phone(telefono_row)
                        if telefono_normalizado == normalize_phone(telefono):
                            encontrado = True
                            row[CLIENTE_FIELD] = CLIENTE_SI if es_cliente else CLIENTE_NO
                            if estado:
                                row["estado"] = estado
                            if nombre and nombre != "No especificado":
                                row["nombre"] = nombre
                            print(f"   📝 [CSV] Contacto ACTUALIZADO: {telefono} -> es_cliente={row[CLIENTE_FIELD]}")

                    rows.append(row)

        if not encontrado:
            ahora = datetime.datetime.now()

            if es_agendado:
                nombre_limpio = telefono.replace("NOMBRE:", "")
                nuevo_registro = {
                    "fecha_hora": ahora.strftime("%Y-%m-%d %H:%M:%S"),
                    "nombre": nombre_limpio,
                    "telefono": telefono,
                    "website": "No disponible",
                    "whatsapp_link": "",
                    "estado": estado or "Contacto agendado",
                    "mensaje_personalizado": "Contacto agendado desde WhatsApp (sin número real)",
                    "contactado": "si",
                    CLIENTE_FIELD: CLIENTE_SI if es_cliente else CLIENTE_NO,
                }
            else:
                nuevo_registro = {
                    "fecha_hora": ahora.strftime("%Y-%m-%d %H:%M:%S"),
                    "nombre": nombre or "No especificado",
                    "telefono": normalize_phone(telefono),
                    "website": "No disponible",
                    "whatsapp_link": f"https://wa.me/{normalize_phone(telefono).replace('+', '')}",
                    "estado": estado or "Contacto nuevo",
                    "mensaje_personalizado": "Agregado automáticamente por WPSetter",
                    "contactado": "si",
                    CLIENTE_FIELD: CLIENTE_SI if es_cliente else CLIENTE_NO,
                }

            rows.append(nuevo_registro)
            print(f"   📝 [CSV] NUEVO contacto agregado: {telefono} -> es_cliente={nuevo_registro[CLIENTE_FIELD]}")

        if not fieldnames:
            fieldnames = NEGOCIOS_FIELDNAMES.copy()

        fieldnames, rows, _ = asegurar_columna_cliente(fieldnames, rows)

        with open(NEGOCIOS_CSV, 'w', encoding='utf-8-sig', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
            writer.writeheader()
            writer.writerows(rows)

        return True

    except Exception as e:
        print(f"⚠️ [CSV] Error agregando/actualizando contacto: {e}")
        return False


def actualizar_telefono_contacto_agendado_csv(nombre_contacto: str, telefono_real: str) -> bool:
    """
    Reemplaza el identificador NOMBRE:... por el número real de WhatsApp en la fila del contacto.
    """
    nombre_contacto = str(nombre_contacto or "").strip()
    telefono_real = normalize_phone(telefono_real)
    if not nombre_contacto or not telefono_real or telefono_real.startswith("NOMBRE:"):
        return False

    try:
        file_exists = os.path.exists(NEGOCIOS_CSV)
        rows = []
        fieldnames = []
        actualizado = False

        if file_exists:
            with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig', newline='') as f:
                reader = csv.DictReader(f)
                fieldnames = [fn for fn in (reader.fieldnames or []) if fn is not None]
                for row in reader:
                    row = {k: v for k, v in row.items() if k is not None}
                    nombre_row = str(row.get("nombre", "")).strip().lower()
                    telefono_row = str(row.get("telefono", "")).strip()
                    es_misma_fila = (
                        nombre_row == nombre_contacto.lower()
                        or telefono_row == f"NOMBRE:{nombre_contacto}"
                    )
                    if es_misma_fila:
                        row["nombre"] = row.get("nombre") or nombre_contacto
                        row["telefono"] = telefono_real
                        row["whatsapp_link"] = f"https://wa.me/{telefono_real.replace('+', '')}"
                        if not row.get("estado"):
                            row["estado"] = "Contacto agendado"
                        actualizado = True
                        print(f"   📝 [CSV] Teléfono real guardado para {nombre_contacto}: {telefono_real}")
                    rows.append(row)

        if not actualizado:
            ahora = datetime.datetime.now()
            if not fieldnames:
                fieldnames = NEGOCIOS_FIELDNAMES.copy()
            rows.append({
                "fecha_hora": ahora.strftime("%Y-%m-%d %H:%M:%S"),
                "nombre": nombre_contacto,
                "telefono": telefono_real,
                "website": "No disponible",
                "whatsapp_link": f"https://wa.me/{telefono_real.replace('+', '')}",
                "estado": "Contacto agendado",
                "mensaje_personalizado": "Número real obtenido desde ficha de WhatsApp",
                "contactado": "si",
                CLIENTE_FIELD: CLIENTE_NO,
            })
            actualizado = True
            print(f"   📝 [CSV] Contacto creado con teléfono real: {nombre_contacto} -> {telefono_real}")

        fieldnames, rows, _ = asegurar_columna_cliente(fieldnames, rows)
        with open(NEGOCIOS_CSV, 'w', encoding='utf-8-sig', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
            writer.writeheader()
            writer.writerows(rows)

        return actualizado
    except Exception as e:
        print(f"⚠️ [CSV] Error guardando teléfono real para {nombre_contacto}: {e}")
        return False


def buscar_telefono_real_por_nombre_csv(nombre_contacto: str) -> Optional[str]:
    nombre_contacto = str(nombre_contacto or "").strip()
    if not nombre_contacto or not os.path.exists(NEGOCIOS_CSV):
        return None

    try:
        with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig', newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                row = {k: v for k, v in row.items() if k is not None}
                if str(row.get("nombre", "")).strip().lower() != nombre_contacto.lower():
                    continue
                telefono_row = str(row.get("telefono", "")).strip()
                telefono_norm = normalize_phone(telefono_row)
                if telefono_norm and not telefono_norm.startswith("NOMBRE:"):
                    return telefono_norm
    except Exception as e:
        print(f"⚠️ [CSV] Error buscando teléfono por nombre {nombre_contacto}: {e}")
    return None


async def obtener_numero_desde_ficha_contacto(page) -> Optional[str]:
    """
    Abre la ficha del contacto, extrae el número de WhatsApp y vuelve al chat con Escape.
    """
    try:
        await page.locator('xpath=//header//span[@dir="auto"]').click()
        await asyncio.sleep(1)

        numero_selectors = [
            "xpath=//span[starts-with(normalize-space(), '+')]",
            "xpath=//*[contains(text(), '+')]",
        ]

        for selector in numero_selectors:
            try:
                locator = page.locator(selector).first
                await locator.wait_for(state="visible", timeout=3000)
                texto = (await locator.inner_text()).strip()
                match = re.search(r"\+\d[\d\s\-\(\)]{6,}", texto)
                if match:
                    numero = normalize_phone(match.group(0))
                    if numero:
                        print(f"📱 [Ficha contacto] Número detectado: {numero}")
                        return numero
            except Exception:
                continue

        print("⚠️ [Ficha contacto] No se encontró número con '+'")
        return None
    except Exception as e:
        print(f"⚠️ [Ficha contacto] Error obteniendo número: {e}")
        return None
    finally:
        try:
            await page.keyboard.press("Escape")
            await asyncio.sleep(0.5)
            print("⎋ [Ficha contacto] Volviendo al chat")
        except Exception:
            pass



def _retag_memory_owner_after_contact_resolution(
    value: Any,
    source_owner: str,
    target_owner: str,
) -> Any:
    """
    Reetiqueta exclusivamente metadatos de identidad de memoria.

    No interpreta contenido del usuario ni modifica valores operativos
    (día/hora/cancha/evento/team_name). Su único objetivo es conservar la
    continuidad del MISMO chat cuando WhatsApp primero lo identifica como
    NOMBRE:<contacto> y después revela el teléfono real.
    """
    if isinstance(value, dict):
        migrated = {}
        for key, item in value.items():
            if key in {"_memory_owner", "memory_owner", "cliente_id"}:
                item_text = str(item or "").strip()
                migrated[key] = (
                    target_owner
                    if item_text == source_owner
                    else _retag_memory_owner_after_contact_resolution(
                        item,
                        source_owner,
                        target_owner,
                    )
                )
            else:
                migrated[key] = _retag_memory_owner_after_contact_resolution(
                    item,
                    source_owner,
                    target_owner,
                )
        return migrated

    if isinstance(value, list):
        return [
            _retag_memory_owner_after_contact_resolution(
                item,
                source_owner,
                target_owner,
            )
            for item in value
        ]

    if isinstance(value, tuple):
        return tuple(
            _retag_memory_owner_after_contact_resolution(
                item,
                source_owner,
                target_owner,
            )
            for item in value
        )

    return value


def _merge_conversation_histories_after_identity_resolution(
    target_history: Any,
    source_history: Any,
    target_owner: str,
) -> List[Dict[str, Any]]:
    """Fusiona historial previo por teléfono + turno actual por NOMBRE sin duplicar."""
    merged: List[Dict[str, Any]] = []
    seen = set()

    for raw in list(target_history or []) + list(source_history or []):
        if not isinstance(raw, dict):
            continue

        item = dict(raw)
        item["_memory_owner"] = target_owner

        fingerprint = (
            str(item.get("role") or ""),
            str(item.get("content") or ""),
            str(item.get("timestamp") or ""),
        )
        if fingerprint in seen:
            continue
        seen.add(fingerprint)
        merged.append(item)

    try:
        max_history = int(MAX_CONVERSATION_HISTORY)
    except Exception:
        max_history = 30

    if max_history > 0 and len(merged) > max_history:
        merged = merged[-max_history:]

    return merged


def migrar_memoria_contacto_agendado_a_telefono_real(
    nombre_contacto: str,
    telefono_real: str,
) -> bool:
    """
    Promueve de forma transaccional la memoria del chat:

        NOMBRE:<contacto>  ->  +teléfono_real

    Esto es necesario porque WhatsApp Web puede no exponer el número al abrir
    por primera vez un contacto agendado. Si AgentV2 abrió un pending antes de
    conocer el número (por ejemplo ``team_name`` de un torneo), ese pending no
    puede perderse cuando en la siguiente iteración se descubre el teléfono.

    Seguridad:
    - sólo corre después de que el MISMO chat resolvió un teléfono real;
    - no fusiona identidades desconocidas;
    - los transitorios del chat activo (source/NOMBRE) mandan;
    - el historial previo del teléfono se conserva y se deduplica;
    - todos los owner tags internos se reetiquetan al teléfono canónico.
    """
    nombre = str(nombre_contacto or "").strip()
    phone = normalize_phone(telefono_real)

    if not nombre or not phone or str(phone).startswith("NOMBRE:"):
        return False

    source_identity = f"NOMBRE:{nombre}"
    source_owner = _memory_owner_key(source_identity)
    target_owner = _memory_owner_key(phone)

    if (
        not source_owner
        or source_owner == "unknown"
        or not target_owner
        or target_owner == "unknown"
        or source_owner == target_owner
    ):
        return False

    source_state = conversation_states.get(source_owner)
    target_state = conversation_states.get(target_owner)

    migrated_conversation = False

    if isinstance(source_state, dict):
        # El estado NOMBRE pertenece al chat que acaba de revelar este número:
        # sus pending/draft/scope actuales son la autoridad transaccional.
        promoted = copy.deepcopy(source_state)

        if isinstance(target_state, dict):
            promoted["historial"] = (
                _merge_conversation_histories_after_identity_resolution(
                    target_state.get("historial"),
                    source_state.get("historial"),
                    target_owner,
                )
            )

            # La memoria de cliente por teléfono puede contener estadísticas
            # históricas más ricas que el alias temporal. No la pisamos.
            target_client_memory = target_state.get("memoria_cliente")
            if isinstance(target_client_memory, dict) and target_client_memory:
                promoted["memoria_cliente"] = copy.deepcopy(
                    target_client_memory
                )
        else:
            promoted["historial"] = (
                _merge_conversation_histories_after_identity_resolution(
                    [],
                    source_state.get("historial"),
                    target_owner,
                )
            )

        promoted = _retag_memory_owner_after_contact_resolution(
            promoted,
            source_owner,
            target_owner,
        )
        promoted["_memory_owner"] = target_owner
        promoted["ultima_actualizacion"] = datetime.datetime.now(TIMEZONE)

        conversation_states[target_owner] = promoted
        conversation_states.pop(source_owner, None)
        _persist_conversation_states()
        migrated_conversation = True

    # client_memory.json también usa el namespace de identidad. Si existe una
    # entrada temporal NOMBRE:..., la promovemos sin destruir una memoria
    # histórica ya existente bajo el teléfono real.
    try:
        memories = _json_read(CLIENT_MEMORY_FILE, {})
        if isinstance(memories, dict) and source_owner in memories:
            source_memory = memories.get(source_owner)
            target_memory = memories.get(target_owner)

            if isinstance(target_memory, dict):
                merged_memory = copy.deepcopy(target_memory)

                # Conservamos solamente contexto conversacional útil del alias
                # cuando el destino todavía no lo tenía.
                if isinstance(source_memory, dict):
                    if (
                        not str(
                            merged_memory.get("resumen_conversacion") or ""
                        ).strip()
                        and str(
                            source_memory.get("resumen_conversacion") or ""
                        ).strip()
                    ):
                        merged_memory["resumen_conversacion"] = (
                            source_memory.get("resumen_conversacion")
                        )

                    if (
                        not str(
                            merged_memory.get("nombre") or ""
                        ).strip()
                        and str(source_memory.get("nombre") or "").strip()
                    ):
                        merged_memory["nombre"] = source_memory.get("nombre")
            elif isinstance(source_memory, dict):
                merged_memory = copy.deepcopy(source_memory)
            else:
                merged_memory = _default_client_memory(phone)

            merged_memory = _retag_memory_owner_after_contact_resolution(
                merged_memory,
                source_owner,
                target_owner,
            )
            merged_memory["_memory_owner"] = target_owner
            merged_memory["cliente_id"] = target_owner
            merged_memory["telefono"] = phone

            memories[target_owner] = merged_memory
            memories.pop(source_owner, None)
            _json_write(CLIENT_MEMORY_FILE, memories)
    except Exception as exc:
        # La conversación canónica ya quedó promovida. Un fallo de la memoria
        # auxiliar no debe destruir el pending del turno.
        print(
            "   ⚠️ [IDENTITY PROMOTION] client_memory auxiliar no migrada: "
            f"{exc}"
        )

    if migrated_conversation:
        migrated_state = conversation_states.get(target_owner) or {}
        migrated_agent = _agent_v2_state(migrated_state)
        pending_fields = [
            str(item.get("field") or "")
            for item in (migrated_agent.get("open_questions") or [])
            if isinstance(item, dict)
        ]
        event_state = dict(migrated_state.get("event_registration") or {})
        event_draft = dict(event_state.get("draft") or {})

        print(
            "   🔗 [AgentV2 V174 IDENTITY PROMOTION] "
            f"{source_owner} → {target_owner} "
            f"pending={pending_fields or []} "
            f"event_id={event_draft.get('event_id') or 'n/a'}"
        )

    return migrated_conversation


async def resolver_telefono_real_si_es_nombre(page, telefono: str) -> str:
    if not telefono or not str(telefono).startswith("NOMBRE:"):
        return telefono

    nombre_contacto = telefono.replace("NOMBRE:", "").strip()
    numero_guardado = buscar_telefono_real_por_nombre_csv(nombre_contacto)
    if numero_guardado:
        # V174: el contacto ya fue resuelto antes, pero este proceso puede seguir
        # teniendo el turno actual bajo NOMBRE:<contacto>. Promovemos la memoria
        # ANTES de devolver el teléfono para no perder pending/team_name/etc.
        migrar_memoria_contacto_agendado_a_telefono_real(
            nombre_contacto,
            numero_guardado,
        )
        print(f"📱 [CSV] Teléfono real recuperado para {nombre_contacto}: {numero_guardado}")
        return numero_guardado

    numero_real = await obtener_numero_desde_ficha_contacto(page)
    if not numero_real:
        return telefono

    actualizar_telefono_contacto_agendado_csv(nombre_contacto, numero_real)

    # V174: este es el momento exacto en que una identidad temporal se convierte
    # en teléfono canónico. La memoria conversacional debe viajar con ella.
    migrar_memoria_contacto_agendado_a_telefono_real(
        nombre_contacto,
        numero_real,
    )
    return numero_real


