async def obtener_datos_prospecto(page, telefono: str, user_messages: list) -> Dict:
    prospecto = {
        "telefono": telefono or "No disponible",
        "nombre": "No especificado",
        "negocio": "No especificado",
        "website": "No disponible",
        "whatsapp_link": "",
        "estado_actual": "",
        "es_cliente": CLIENTE_NO,
        "fuente": "desconocida"
    }

    es_contacto_agendado = telefono and telefono.startswith("NOMBRE:")

    if es_contacto_agendado:
        nombre_contacto = telefono.replace("NOMBRE:", "")
        prospecto["nombre"] = nombre_contacto
        prospecto["fuente"] = "contacto_agendado"
        prospecto["telefono"] = nombre_contacto
        print(f"📇 [Contacto agendado] Nombre: {nombre_contacto}")

        encontrado = False

        if os.path.exists(NEGOCIOS_CSV):
            try:
                with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig') as f:
                    reader = csv.DictReader(f)
                    for row in reader:
                        row = {k: v for k, v in row.items() if k is not None}
                        nombre_csv = row.get("nombre", "")
                        if nombre_csv and nombre_csv.strip().lower() == nombre_contacto.strip().lower():
                            prospecto["es_cliente"] = normalizar_es_cliente(row.get(CLIENTE_FIELD, CLIENTE_NO))
                            prospecto["estado_actual"] = row.get("estado", "")
                            prospecto["negocio"] = row.get("negocio", prospecto["negocio"])
                            prospecto["website"] = row.get("website", prospecto["website"])
                            prospecto["whatsapp_link"] = row.get("whatsapp_link", "")
                            prospecto["telefono"] = row.get("telefono", prospecto["telefono"])
                            prospecto["fuente"] = f"{CONTACTS_CSV} (por nombre)"
                            encontrado = True
                            print(f"   ✅ [CSV] Contacto agendado ENCONTRADO por nombre: {nombre_contacto} -> es_cliente={prospecto['es_cliente']}")
                            break
            except Exception as e:
                print(f"   ⚠️ [CSV] Error buscando por nombre: {e}")

        if not encontrado and os.path.exists(NEGOCIOS_CSV):
            try:
                with open(NEGOCIOS_CSV, 'r', encoding='utf-8-sig') as f:
                    reader = csv.DictReader(f)
                    for row in reader:
                        row = {k: v for k, v in row.items() if k is not None}
                        telefono_csv = row.get("telefono", "")
                        if telefono_csv == telefono:
                            prospecto["es_cliente"] = normalizar_es_cliente(row.get(CLIENTE_FIELD, CLIENTE_NO))
                            prospecto["estado_actual"] = row.get("estado", "")
                            prospecto["negocio"] = row.get("negocio", prospecto["negocio"])
                            prospecto["website"] = row.get("website", prospecto["website"])
                            prospecto["whatsapp_link"] = row.get("whatsapp_link", "")
                            prospecto["telefono"] = row.get("telefono", prospecto["telefono"])
                            prospecto["nombre"] = row.get("nombre", prospecto["nombre"])
                            prospecto["fuente"] = f"{CONTACTS_CSV} (por contacto agendado)"
                            encontrado = True
                            print(f"   ✅ [CSV] Contacto agendado ENCONTRADO por identificador: {telefono} -> es_cliente={prospecto['es_cliente']}")
                            break
            except Exception as e:
                print(f"   ⚠️ [CSV] Error buscando por identificador de contacto agendado: {e}")

        if not encontrado:
            print(f"   📝 [CSV] Contacto agendado NO encontrado en CSV: {nombre_contacto}")

        return prospecto

    if telefono and not telefono.startswith("NOMBRE:"):
        csv_data = buscar_en_negocios_csv(telefono)
        if csv_data.get("existe"):
            prospecto.update({
                "nombre": csv_data.get("nombre", "No especificado"),
                "negocio": csv_data.get("negocio", "No especificado"),
                "website": csv_data.get("website", "No disponible"),
                "whatsapp_link": csv_data.get("whatsapp_link", ""),
                "estado_actual": csv_data.get("estado_actual", ""),
                "es_cliente": csv_data.get("es_cliente", CLIENTE_NO),
                "fuente": CONTACTS_CSV
            })

    return prospecto

# ================================
# FUNCIÓN: OBTENER TELÉFONO DEL CHAT
# ================================
def _normalizar_texto_grupo_whatsapp(texto: str) -> str:
    texto = str(texto or "").lower()
    texto = unicodedata.normalize("NFKD", texto).encode("ascii", "ignore").decode("ascii")
    texto = re.sub(r"\s+", " ", texto)
    return texto.strip()


async def es_chat_grupo_whatsapp(page) -> bool:
    """
    Detecta si el chat abierto es un grupo de WhatsApp.
    Si hay duda, prioriza no responder en grupos para evitar atender mensajes ajenos.
    """
    try:
        await asyncio.sleep(0.5)

        group_selectors = [
            "header [data-testid*='group' i]",
            "header [aria-label*='grupo' i]",
            "header [aria-label*='group' i]",
            "header [title*='grupo' i]",
            "header [title*='group' i]",
            "span[data-icon='default-group']",
            "span[data-icon='group']",
        ]
        for selector in group_selectors:
            try:
                locator = page.locator(selector).first
                if await locator.count() > 0 and await locator.is_visible():
                    print(f"👥 [Grupo] Detectado por selector: {selector}")
                    return True
            except Exception:
                continue

        header = page.locator("header").first
        if await header.count() == 0:
            return False

        try:
            header_text = await header.inner_text()
        except Exception:
            header_text = ""

        header_norm = _normalizar_texto_grupo_whatsapp(header_text)
        if re.search(r"\b\d+\s+(participantes|participants|miembros|members)\b", header_norm):
            print(f"👥 [Grupo] Detectado por cantidad de participantes: {header_text[:120]}")
            return True
        if re.search(r"\b(participantes|participants|miembros del grupo|group members|info\.? del grupo|group info)\b", header_norm):
            print(f"👥 [Grupo] Detectado por texto de grupo: {header_text[:120]}")
            return True

        try:
            data = await page.evaluate(
                """() => {
                    const header = document.querySelector('header');
                    if (!header) return { text: '', attrs: [] };
                    const attrs = [];
                    header.querySelectorAll('*').forEach(el => {
                        ['aria-label', 'title', 'data-testid', 'data-icon'].forEach(name => {
                            const value = el.getAttribute(name);
                            if (value) attrs.push(value);
                        });
                    });
                    return { text: header.innerText || '', attrs };
                }"""
            )
            attrs_norm = _normalizar_texto_grupo_whatsapp(" ".join(data.get("attrs") or []))
            if re.search(r"\b(default-group|group|grupo)\b", attrs_norm):
                print(f"👥 [Grupo] Detectado por atributos header: {attrs_norm[:160]}")
                return True

            lineas = [line.strip() for line in str(data.get("text") or header_text).splitlines() if line.strip()]
            subtitulo = " ".join(lineas[1:3])
            subtitulo_norm = _normalizar_texto_grupo_whatsapp(subtitulo)
            telefono_en_header = bool(re.search(r"\+?\d[\d\s().-]{6,}\d", str(data.get("text") or header_text)))
            participantes_estimados = [
                p.strip()
                for p in re.split(r",|\s+y\s+|\s+and\s+", subtitulo)
                if p.strip()
            ]
            if len(participantes_estimados) > 2 and not telefono_en_header:
                print(f"👥 [Grupo] Detectado por multiples integrantes sin telefono: {subtitulo[:120]}")
                return True
            if "," in subtitulo and not re.search(r"\b(online|en linea|ult\.|ultima vez|escribiendo)\b", subtitulo_norm):
                print(f"👥 [Grupo] Detectado por lista de integrantes: {subtitulo[:120]}")
                return True
        except Exception as e:
            print(f"⚠️ [Grupo] No pude inspeccionar atributos del header: {e}")

        return False
    except Exception as e:
        print(f"⚠️ [Grupo] Error detectando grupo: {e}")
        return False


async def get_phone_from_chat(page):
    try:
        if await es_chat_grupo_whatsapp(page):
            print("👥 [Grupo] No extraigo telefono/nombre de un chat grupal")
            return None

        title_selectors = [
            "//header//span[@dir='auto']",
            "//span[@data-testid='conversation-info-header-chat-title']"
        ]

        for selector in title_selectors:
            if await page.locator(selector).count() > 0:
                text = await page.locator(selector).inner_text()
                text = text.strip()

                if not text:
                    continue

                numbers = re.findall(r'\+?54[\d\s\-]+', text)
                if numbers:
                    return normalize_phone(numbers[0])

                nombre_limpio = re.sub(r'[^\w\sáéíóúñÑüÜ]', '', text)
                nombre_limpio = nombre_limpio.strip()

                if nombre_limpio and len(nombre_limpio) > 1:
                    print(f"📱 [Teléfono] No se detectó número. Contacto agendado: '{nombre_limpio}'")
                    return f"NOMBRE:{nombre_limpio}"

        return None
    except Exception as e:
        print(f"⚠️ [Teléfono] Error: {e}")
        return None

# ================================
# FUNCIONES DE AUDIO
# ================================
async def transcribe_audio_to_text(audio_file_path):
    try:
        print(f"🎵 [AUDIO] Transcribiendo audio: {audio_file_path}")

        if not os.path.exists(audio_file_path):
            print(f"❌ [AUDIO] Archivo no encontrado: {audio_file_path}")
            return None

        file_size = os.path.getsize(audio_file_path) / (1024 * 1024)
        if file_size > 25:
            print(f"⚠️ [AUDIO] Archivo demasiado grande ({file_size:.2f} MB). Límite: 25 MB")
            return "Audio demasiado largo. Por favor, escríbeme tu mensaje."

        with open(audio_file_path, "rb") as audio_file:
            response = client.audio.transcriptions.create(
                model="whisper-1",
                file=audio_file,
                response_format="text",
                language="es"
            )

        transcribed_text = response.strip()
        print(f"📝 [AUDIO] Transcripción completada: {transcribed_text[:100]}...")
        return transcribed_text

    except Exception as e:
        print(f"❌ [AUDIO] Error transcribiendo audio: {e}")
        return None

async def delete_audio_file(audio_file_path):
    try:
        if os.path.exists(audio_file_path):
            os.remove(audio_file_path)
            print(f"🗑️ [AUDIO] Archivo eliminado: {audio_file_path}")
            return True
        return False
    except Exception as e:
        print(f"❌ [AUDIO] Error eliminando archivo: {e}")
        return False


# ================================
# FUNCIONES DE COMPROBANTE / SEÑA
# ================================
def _parse_monto_config(monto) -> Optional[float]:
    texto = str(monto or "").strip()
    if not texto:
        return None
    texto = texto.replace("$", "").replace("ARS", "").replace("ars", "").strip()
    texto = re.sub(r"[^\d,\.]", "", texto)
    if not texto:
        return None
    if "," in texto and "." in texto:
        texto = texto.replace(".", "").replace(",", ".")
    elif "," in texto:
        texto = texto.replace(",", ".")
    try:
        return float(texto)
    except ValueError:
        return None


def _monto_humano(monto) -> str:
    esperado = _parse_monto_config(monto)
    if esperado is None:
        return str(monto or "la seña configurada")
    if esperado.is_integer():
        return f"${int(esperado)}"
    return f"${esperado:.2f}"


async def responder_pregunta_directa_con_ia(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict = None,
    incluir_recordatorio_senia: bool = False,
) -> str:
    """
    Genera una respuesta para una pregunta directa cuando hay una seña pendiente.
    El recordatorio de seña es opcional y solo se agrega si el razonador lo solicita.
    """
    prospecto = prospecto or {}

    from cancheria.config.legacy_config import PRICES, BUSINESS_ADDRESS, PAYMENT_ALIAS

    # 🔧 OBTENER DATOS DEL TURNO PENDIENTE DEL ESTADO
    dia_pendiente = conv_state.get("dia_propuesto")
    hora_pendiente = conv_state.get("hora_propuesta")
    cancha_pendiente = conv_state.get("cancha_propuesta")
    monto_senia = conv_state.get("senia_monto") or _monto_humano(
        _senia_para_total(calcular_precio_total(
            conv_state.get("duracion_propuesta") or DEFAULT_TURN_DURATION_HOURS
        ))
    )

    # Formatear hora para mensaje
    hora_formateada = formatear_hora_para_mensaje(hora_pendiente) if hora_pendiente else ""

    # Construir el recordatorio COMPLETO del turno pendiente (igual al original)
    recordatorio_turno = ""
    if dia_pendiente and hora_pendiente and cancha_pendiente:
        recordatorio_turno = (
            f" Recordá que tenés un turno pendiente de seña para el {dia_pendiente} "
            f"a las {hora_formateada} en la {cancha_pendiente}, con una seña de {monto_senia} "
            f"al alias {PAYMENT_ALIAS}. Si tenés efectivo podés acercarte a {BUSINESS_ADDRESS} a reservar, gracias."
        )
    elif dia_pendiente and hora_pendiente:
        recordatorio_turno = (
            f" Recordá que tenés un turno pendiente de seña para el {dia_pendiente} "
            f"a las {hora_formateada}, con una seña de {monto_senia} "
            f"al alias {PAYMENT_ALIAS}. Si tenés efectivo podés acercarte a {BUSINESS_ADDRESS} a reservar, gracias."
        )
    elif dia_pendiente:
        recordatorio_turno = (
            f" Recordá que tenés un turno pendiente de seña para el {dia_pendiente}, "
            f"con una seña de {monto_senia} al alias {PAYMENT_ALIAS}. "
            f"Si tenés efectivo podés acercarte a {BUSINESS_ADDRESS} a reservar, gracias."
        )
    elif cancha_pendiente and not dia_pendiente:
        # Caso raro: solo hay cancha
        recordatorio_turno = (
            f" Recordá que tenés un turno pendiente de seña en la {cancha_pendiente}, "
            f"con una seña de {monto_senia} al alias {PAYMENT_ALIAS}. "
            f"Si tenés efectivo podés acercarte a {BUSINESS_ADDRESS} a reservar, gracias."
        )

    # Construir información útil del negocio
    precios_str = ", ".join([f"{p['description']}: ${p['amount']}" for p in PRICES]) if PRICES else "$15000 la hora"

    info_negocio = f"""
INFORMACIÓN DEL NEGOCIO:
- Nombre: {BUSINESS_NAME}
- Dirección: {BUSINESS_ADDRESS}
- Horario de atención: {descripcion_franjas_atencion_mensaje()}
- Precios: {precios_str}
- Seña requerida: {_descripcion_senia_runtime()} (alias: {PAYMENT_ALIAS})
"""

    historial_texto = ""
    for msg in conv_state.get("historial", [])[-6:]:
        role = "Usuario" if msg["role"] == "user" else "Agente"
        historial_texto += f"{role}: {msg['content'][:200]}\n"

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        f"Sos {AGENT_NAME}, asistente de {BUSINESS_NAME}.\n\n"
                        "El usuario tiene un TURNO PENDIENTE DE SEÑA, pero acaba de hacer una pregunta.\n\n"
                        "REGLAS:\n"
                        "1. Respondé DIRECTAMENTE a la pregunta actual del usuario.\n"
                        "2. El turno pendiente es CONTEXTO, no el tema obligatorio de cada respuesta.\n"
                        f"3. ¿Debés recordar la seña al final?: {'SI' if incluir_recordatorio_senia else 'NO'}.\n"
                        "4. Si la respuesta anterior es NO, no menciones alias, seña, efectivo ni el turno pendiente.\n"
                        "5. Sé breve, natural, con tono argentino informal.\n"
                        "6. NO uses emojis a menos que sea para algo puntual.\n\n"
                        f"{info_negocio}\n\n"
                        "Respondé SOLO el texto de WhatsApp, sin JSON."
                    )
                },
                {
                    "role": "user",
                    "content": (
                        f"Cliente: {prospecto.get('nombre', 'Cliente')}\n"
                        f"HISTORIAL:\n{historial_texto or '(sin historial)'}\n\n"
                        f"PREGUNTA DEL USUARIO:\n\"{mensaje}\"\n\n"
                        f"DATOS DEL TURNO PENDIENTE:\n"
                        f"Día: {dia_pendiente or 'no especificado'}\n"
                        f"Hora: {hora_formateada or 'no especificada'}\n"
                        f"Cancha: {cancha_pendiente or 'no especificada'}\n"
                        f"Monto seña: {monto_senia}\n"
                        f"Alias: {PAYMENT_ALIAS}\n"
                        f"Dirección: {BUSINESS_ADDRESS}\n\n"
                        f"Respondé la pregunta actual. Recordatorio de seña habilitado: {incluir_recordatorio_senia}."
                    )
                }
            ],
            temperature=0.5,
            max_tokens=280
        )
        register_cost(resp)
        respuesta = resp.choices[0].message.content.strip()

        # El recordatorio solo se anexa si el razonador lo pidió explícitamente.
        if incluir_recordatorio_senia and recordatorio_turno:
            if PAYMENT_ALIAS not in respuesta and "alias" not in respuesta.lower():
                respuesta += recordatorio_turno

        print(f"   💬 [Pregunta directa IA] Respuesta: {respuesta[:200]}...")
        return respuesta

    except Exception as e:
        print(f"   ⚠️ [Pregunta directa IA] Error: {e}")
        # Fallback factual; tampoco fuerza la seña si el razonador no la pidió.
        precio_fallback = PRICES[0]['amount'] if PRICES else '15000'
        respuesta_fallback = f"La hora sale ${precio_fallback}."
        if incluir_recordatorio_senia and recordatorio_turno:
            respuesta_fallback += recordatorio_turno
        return respuesta_fallback


async def detectar_accion_senia_pendiente_ia(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict = None
) -> Dict[str, Any]:
    """
    Decide la acción operativa cuando hay un turno pendiente de seña.
    La decisión principal es contextual por IA; las reglas regex quedan solo como fallback si falla la llamada.
    """
    prospecto = prospecto or {}
    historial_texto = ""
    for msg in conv_state.get("historial", [])[-8:]:
        role_label = "Usuario" if msg.get("role") == "user" else "Agente"
        historial_texto += f"{role_label}: {str(msg.get('content', ''))[:240]}\n"

    dia = normalizar_valor_nullable(conv_state.get("dia_propuesto"))
    hora = normalizar_hora_detectada(conv_state.get("hora_propuesta"))
    cancha = normalizar_valor_nullable(conv_state.get("cancha_propuesta"))

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el módulo de razonamiento operativo de un agente IA para reservas de canchas.\n"
                        "No clasifiques por palabras clave: interpretá intención, contexto, memoria y objetivo.\n\n"
                        "Pilares que tenés que aplicar:\n"
                        "- Percepción: leé el mensaje, historial y reserva pendiente.\n"
                        "- Memoria: usá el turno pendiente como contexto, no como único tema.\n"
                        "- Razonamiento: distinguí consultar horarios, cancelar, reprogramar, pagar, enviar comprobante o charla.\n"
                        "- Planificación: elegí la próxima acción mínima correcta.\n"
                        "- Uso de herramientas: indicá cuándo se debe usar calendario o validación de comprobante.\n"
                        "- Acción: la acción debe ser ejecutable por el bot.\n"
                        "- Adaptación: si el usuario cambia de tema, respondé eso y no fuerces la seña.\n"
                        "- Comunicación: la respuesta final debe poder ser breve y natural.\n"
                        "- Evaluación: si falta información, pedila en vez de inventarla.\n\n"
                        "Acciones válidas:\n"
                        "- cancelar_turno: quiere cancelar/anular/bajar el turno pendiente.\n"
                        "- consultar_horarios: pide horarios disponibles o disponibilidad general, sin pedir mover el turno pendiente a una hora concreta.\n"
                        "- reprogramar_turno: pide cambiar/mover el turno pendiente a otro día, hora o cancha concreta.\n"
                        "- pagar_en_lugar: quiere pagar en efectivo/en cancha/en el lugar.\n"
                        "- posible_comprobante: parece estar enviando, reclamando, confirmando o hablando de un comprobante de pago. Incluye cuando el usuario dice que ya lo mando, que ya pago, que ya transfirio, que ya envio la captura, o pregunta si llego el comprobante.\n"
                        "- responder_pregunta_directa: el usuario hace una pregunta puntual (precios, horarios de atención, dirección, políticas, etc.) que NO está relacionada con modificar el turno pendiente. En este caso, NO fuerces recordatorio de seña.\n"
                        "- saludo_o_charla: saludo, agradecimiento o charla breve sin acción operativa.\n"
                        "- ambiguo: no alcanza para decidir.\n\n"
                        "REGLAS CRÍTICAS:\n"
                        "1. Si el usuario pregunta por PRECIOS ('cuanto sale la hora', 'precios', 'cuanto cuesta', 'tarifa') → accion='responder_pregunta_directa', requiere_recordatorio_senia=False\n"
                        "2. Si el usuario pregunta por HORARIOS DE ATENCIÓN ('hasta que hora abren', 'de que hora a que hora') → accion='responder_pregunta_directa', requiere_recordatorio_senia=False\n"
                        "3. Si el usuario pregunta por DIRECCIÓN/DÓNDE ESTÁN ('donde quedan', 'dirección') → accion='responder_pregunta_directa', requiere_recordatorio_senia=False\n"
                        "4. Si el usuario pregunta por POLÍTICAS DE CANCELACIÓN o SEÑAS ('como cancelo', 'la seña es reembolsable') → accion='responder_pregunta_directa', requiere_recordatorio_senia=False\n"
                        "5. Si el usuario hace UNA PREGUNTA QUE NO SEA sobre modificar/cancelar el turno pendiente → responder_pregunta_directa\n"
                        "6. Si el usuario afirma que ya envio el comprobante o que ya pago, accion='posible_comprobante'. No confirmes el turno desde texto: el bot debe validar una imagen/captura real antes de marcar la senia como pagada.\n"
                        "7. SOLO forzar recordatorio de seña (requiere_recordatorio_senia=True) si el usuario NO preguntó nada y solo saludó, o si está en medio del flujo de pago.\n\n"
                        "Respondé SOLO JSON válido con este formato:\n"
                        "{"
                        "\"accion\":\"una_accion_valida\","
                        "\"confianza\":0.0,"
                        "\"requiere_recordatorio_senia\":true,"
                        "\"razon\":\"breve\","
                        "\"datos_faltantes\":[\"dia\",\"hora\",\"cancha\"]"
                        "}"
                    )
                },
                {
                    "role": "user",
                    "content": (
                        f"TURNO PENDIENTE:\n"
                        f"Día: {dia or 'sin día'}\n"
                        f"Hora: {hora or 'sin hora'}\n"
                        f"Cancha: {cancha or 'sin cancha'}\n"
                        f"Cliente: {prospecto.get('nombre', '')}\n\n"
                        f"HISTORIAL RECIENTE:\n{historial_texto or '(sin historial)'}\n"
                        f"MENSAJE ACTUAL:\n\"{mensaje}\""
                    )
                }
            ],
            temperature=0.0,
            max_tokens=220,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        raw = resp.choices[0].message.content.strip()
        result = json.loads(raw)
        accion = str(result.get("accion") or "ambiguo").strip()
        acciones_validas = {
            "cancelar_turno", "consultar_horarios", "reprogramar_turno",
            "pagar_en_lugar", "posible_comprobante", "responder_pregunta_directa",
            "saludo_o_charla", "ambiguo"
        }
        if accion not in acciones_validas:
            accion = "ambiguo"
        result["accion"] = accion
        result["confianza"] = float(result.get("confianza", 0.0) or 0.0)
        result["requiere_recordatorio_senia"] = bool(result.get("requiere_recordatorio_senia", True))
        print(f"   🧠 [SEÑA IA] Acción: {result}")
        return result
    except Exception as e:
        print(f"⚠️ [SEÑA IA] Error clasificando acción: {e}")
        return {"accion": "ambiguo", "confianza": 0.0, "requiere_recordatorio_senia": True, "razon": f"error: {e}", "datos_faltantes": []}


async def detectar_ajuste_quincho_pendiente_ia(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict = None,
) -> Dict[str, Any]:
    """Detecta si el usuario corrige solo el horario/duración del quincho de una reserva pendiente."""
    prospecto = prospecto or {}
    rango = extraer_rango_horario_de_texto(mensaje)
    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos una IA verificadora de cambios sobre una reserva pendiente de seña.\n"
                        "Tu tarea es decidir si el mensaje modifica SOLO el quincho/parrilla, "
                        "sin cambiar la hora de cancha ni la cancha.\n"
                        "Razoná intención y contexto; no clasifiques por palabras sueltas.\n\n"
                        "Ejemplo: 'el quincho lo necesito de 16 a 18' significa ajustar el quincho "
                        "a inicio 16:00 y duración 2 horas.\n"
                        "Si el usuario habla de cambiar el partido/cancha/turno principal, ajustar=false.\n\n"
                        "Respondé SOLO JSON: "
                        "{\"ajustar\":true,\"hora_inicio\":\"HH:MM|null\",\"duracion_horas\":0.0,\"confianza\":0.0,\"razon\":\"breve\"}"
                    )
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "mensaje": mensaje,
                        "reserva_pendiente": {
                            "dia": (conv_state or {}).get("dia_propuesto"),
                            "hora_cancha": (conv_state or {}).get("hora_propuesta"),
                            "cancha": (conv_state or {}).get("cancha_propuesta"),
                            "con_quincho": (conv_state or {}).get("con_quincho"),
                            "quincho": (conv_state or {}).get("quincho"),
                            "quincho_hora_inicio": (conv_state or {}).get("quincho_hora_inicio"),
                            "quincho_duracion_horas": (conv_state or {}).get("quincho_duracion_horas"),
                        },
                        "rango_detectado": {
                            "inicio": rango[0],
                            "fin": rango[1],
                            "duracion_horas": rango[2],
                        } if rango else None,
                        "cliente": prospecto.get("nombre", ""),
                    }, ensure_ascii=False)
                }
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        data["ajustar"] = bool(data.get("ajustar"))
        data["hora_inicio"] = normalizar_hora_detectada(data.get("hora_inicio"))
        data["duracion_horas"] = normalizar_duracion_horas(data.get("duracion_horas") or None)
        data["confianza"] = float(data.get("confianza", 0.0) or 0.0)
        if rango and data.get("ajustar"):
            data["hora_inicio"] = rango[0]
            data["duracion_horas"] = normalizar_duracion_horas(rango[2])
            data["confianza"] = max(float(data.get("confianza", 0.0) or 0.0), 0.85)
        print(f"   🔥 [Ajuste quincho IA] {data}")
        return data
    except Exception as e:
        print(f"⚠️ [Ajuste quincho IA] Error: {e}")
        if rango and mensaje_pide_quincho(mensaje):
            return {
                "ajustar": True,
                "hora_inicio": rango[0],
                "duracion_horas": normalizar_duracion_horas(rango[2]),
                "confianza": 0.75,
                "razon": "rango horario de quincho detectado como fallback",
            }
        return {"ajustar": False, "hora_inicio": None, "duracion_horas": 0, "confianza": 0.0, "razon": str(e)}

def _image_to_b64(path: str) -> str:
    with open(path, "rb") as f:
        return base64.b64encode(f.read()).decode("utf-8")


def _file_sha256(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _normalizar_operation_id(value: Any) -> str:
    text = re.sub(r"[^a-zA-Z0-9]", "", str(value or "")).strip().lower()
    return text if len(text) >= 6 else ""


def _receipt_fingerprints(comprobante: Dict[str, Any]) -> List[str]:
    fingerprints = []
    operation_id = _normalizar_operation_id(comprobante.get("operation_id"))
    if operation_id:
        fingerprints.append(f"op:{operation_id}")
    image_hash = str(comprobante.get("image_sha256") or "").strip().lower()
    if image_hash:
        fingerprints.append(f"sha256:{image_hash}")
    return fingerprints


def comprobante_ya_usado(comprobante: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    used = _json_read(USED_PAYMENT_RECEIPTS_FILE, {"receipts": {}})
    receipts = used.setdefault("receipts", {})
    for fingerprint in _receipt_fingerprints(comprobante):
        existing = receipts.get(fingerprint)
        if existing and existing.get("estado") != "fallido":
            return existing
    return None


def registrar_comprobante_usado(
    comprobante: Dict[str, Any],
    reserva: Dict[str, Any],
    telefono: str,
    nombre: str,
    estado: str = "pagado",
    credit_id: str = "",
    allow_credit_application: bool = False,
) -> Optional[Dict[str, Any]]:
    used = _json_read(USED_PAYMENT_RECEIPTS_FILE, {"receipts": {}})
    receipts = used.setdefault("receipts", {})
    fingerprints = _receipt_fingerprints(comprobante)
    if not fingerprints:
        return {"estado": "fallido", "motivo": "sin_huella_comprobante"}
    for fingerprint in fingerprints:
        existing = receipts.get(fingerprint)
        if existing and existing.get("estado") != "fallido":
            same_owner = normalize_phone(existing.get("telefono") or "") == normalize_phone(
                telefono or ""
            )
            if (
                allow_credit_application
                and same_owner
                and existing.get("estado") == "credito_disponible"
                and (
                    not credit_id
                    or str(existing.get("credit_id") or "") == str(credit_id)
                )
            ):
                continue
            misma_reserva = (
                str(existing.get("telefono") or "") == str(telefono or "")
                and str(existing.get("fecha") or "") == str((reserva or {}).get("fecha") or "")
                and str(existing.get("hora") or "") == str((reserva or {}).get("hora") or "")
                and str(existing.get("cancha") or "") == str((reserva or {}).get("cancha") or "")
            )
            if not (existing.get("estado") == "confirmando" and misma_reserva):
                return existing

    now = datetime.datetime.now(TIMEZONE).isoformat()
    record = {
        "used_at": now,
        "estado": estado,
        "telefono": telefono,
        "nombre": nombre,
        "fecha": (reserva or {}).get("fecha"),
        "hora": (reserva or {}).get("hora"),
        "cancha": (reserva or {}).get("cancha"),
        "monto_detectado": comprobante.get("monto_detectado"),
        "operation_id": comprobante.get("operation_id"),
        "image_sha256": comprobante.get("image_sha256"),
        "credit_id": credit_id or None,
    }
    for fingerprint in fingerprints:
        receipts[fingerprint] = record
    used["updated_at"] = now
    if not _json_write(USED_PAYMENT_RECEIPTS_FILE, used):
        return {"estado": "fallido", "motivo": "error_guardando_comprobante"}
    return None


def actualizar_estado_comprobante_usado(comprobante: Dict[str, Any], estado: str, motivo: str = "") -> bool:
    fingerprints = _receipt_fingerprints(comprobante)
    if not fingerprints:
        return False
    used = _json_read(USED_PAYMENT_RECEIPTS_FILE, {"receipts": {}})
    receipts = used.setdefault("receipts", {})
    changed = False
    now = datetime.datetime.now(TIMEZONE).isoformat()
    for fingerprint in fingerprints:
        record = receipts.get(fingerprint)
        if isinstance(record, dict):
            record["estado"] = estado
            record["updated_at"] = now
            if motivo:
                record["motivo"] = motivo
            receipts[fingerprint] = record
            changed = True
    if not changed:
        return False
    used["updated_at"] = now
    return _json_write(USED_PAYMENT_RECEIPTS_FILE, used)


# Selectores de burbujas de WhatsApp.
# WhatsApp dejo de exponer message-in/message-out en algunas vistas; estas clases
# nuevas distinguen direccion de mensaje en los contenedores focusable-list-item.
WA_MESSAGE_IN_CLASS = "x1cy8zhl"
WA_MESSAGE_OUT_CLASS = "xuk3077"
SELECTOR_ADAPTATION_CACHE_FILE = str(runtime_file("selector_adaptation_cache.json"))
SELECTOR_CACHE = {}
RUNTIME_MESSAGE_IN_CLASSES = {"message-in", WA_MESSAGE_IN_CLASS}
RUNTIME_MESSAGE_OUT_CLASSES = {"message-out", WA_MESSAGE_OUT_CLASS}
WA_ALL_BUBBLES_SELECTOR = (
    f"div.message-in, div.message-out, "
    f"div.focusable-list-item.{WA_MESSAGE_IN_CLASS}, "
    f"div.focusable-list-item.{WA_MESSAGE_OUT_CLASS}"
)
WA_USER_BUBBLES_SELECTOR = (
    f"div.message-in, div.focusable-list-item.{WA_MESSAGE_IN_CLASS}"
)
WA_LAST_USER_BUBBLE_XPATH = (
    "(//div[contains(@class,'message-in') or "
    "(contains(@class,'focusable-list-item') and "
    f"contains(concat(' ', normalize-space(@class), ' '), ' {WA_MESSAGE_IN_CLASS} '))])[last()]"
)


def _load_selector_adaptation_cache():
    global SELECTOR_CACHE
    try:
        if not os.path.exists(SELECTOR_ADAPTATION_CACHE_FILE):
            return
        with open(SELECTOR_ADAPTATION_CACHE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        SELECTOR_CACHE = data.get("selectors", {}) if isinstance(data.get("selectors"), dict) else {}
        for key, selector in list(SELECTOR_CACHE.items()):
            if _selector_is_unsafe_broad(selector):
                print(f"⚠️ [Auto-adaptación] Ignoro selector cacheado demasiado amplio ({key}): {selector}")
                SELECTOR_CACHE.pop(key, None)
        for cls in data.get("message_in_classes", []):
            if cls:
                RUNTIME_MESSAGE_IN_CLASSES.add(str(cls))
        for cls in data.get("message_out_classes", []):
            if cls:
                RUNTIME_MESSAGE_OUT_CLASSES.add(str(cls))
    except Exception as e:
        print(f"⚠️ [Auto-adaptación] No pude cargar cache de selectores: {e}")

# ================================
# OBJETO DE ADAPTACIÓN DE SELECTORES
# ================================
class SelectorAdaptation:
    def __init__(self):
        self.selector_health = {}  # {'all': 85, 'user': 90}
        self.known_selectors = {
            "chat_list": [],
            "chat_item": [],
            "unread_badge": [],
        }
        self.last_adaptation = None

selector_adaptation = SelectorAdaptation()


def _save_selector_adaptation_cache():
    try:
        data = {
            "updated_at": datetime.datetime.now().isoformat(),
            "selectors": SELECTOR_CACHE,
            "message_in_classes": sorted(RUNTIME_MESSAGE_IN_CLASSES),
            "message_out_classes": sorted(RUNTIME_MESSAGE_OUT_CLASSES),
        }
        with open(SELECTOR_ADAPTATION_CACHE_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"⚠️ [Auto-adaptación] No pude guardar cache de selectores: {e}")


def _classes_have_any(classes: str, tokens: set) -> bool:
    class_tokens = set(str(classes or "").split())
    return any(token in class_tokens for token in tokens)


def _selector_is_unsafe_broad(selector: str) -> bool:
    """
    Versión mejorada que rechaza selectores sin scope de tag y clases sueltas.
    """
    selector = str(selector or "")

    # Si tiene focusable-list-item, es más confiable
    if "focusable-list-item" in selector:
        return False

    # CUALQUIER selector de clase suelta sin tag es peligroso
    # Ej: .x10l6tqk.xh8yej3.x1g42fcv (sin div.)
    if re.match(r'^\s*\.[\w-]+(\.[\w-]+)*\s*$', selector):
        return True

    runtime_classes = RUNTIME_MESSAGE_IN_CLASSES | RUNTIME_MESSAGE_OUT_CLASSES
    broad_runtime_classes = [cls for cls in runtime_classes if cls.startswith("x") and f"div.{cls}" in selector]
    return bool(broad_runtime_classes) and "focusable-list-item" not in selector


def _bubble_class_selector(cls: str) -> str:
    cls = str(cls or "").strip()
    if cls in {"message-in", "message-out"}:
        return f"div.{cls}"
    return f"div.focusable-list-item.{cls}"


_load_selector_adaptation_cache()


def _bubble_is_user_from_classes(classes: str) -> bool:
    return _classes_have_any(classes, RUNTIME_MESSAGE_IN_CLASSES)


def _bubble_is_ours_from_classes(classes: str) -> bool:
    return _classes_have_any(classes, RUNTIME_MESSAGE_OUT_CLASSES)


def _bubble_score_is_own_only_snapshot(score: Dict[str, int]) -> bool:
    """El selector funciona, pero el chat abierto sólo contiene mensajes nuestros."""
    sample = int((score or {}).get("sample") or 0)
    return bool(
        sample > 0
        and int((score or {}).get("classified") or 0) == sample
        and int((score or {}).get("ours") or 0) == sample
        and int((score or {}).get("user") or 0) == 0
        and int((score or {}).get("ambiguous") or 0) == 0
    )


async def get_best_bubble_selector(
    page,
    selector_type: str = "all",
    force_refresh: bool = False,
    _allow_proactive_learning: bool = True,
) -> str:
    """
    🧠 Versión PROACTIVA: Obtiene el mejor selector, usando el sistema proactivo.
    🔧 CORREGIDO: Verifica que haya chat abierto antes de aprender.
    """
    cache_key = selector_type if selector_type in {"all", "user"} else "all"

    # Si no se fuerza refresh, intentar usar caché
    if not force_refresh and cache_key in SELECTOR_CACHE:
        cached = SELECTOR_CACHE[cache_key]
        try:
            score = await _score_bubble_selector(page, cached, cache_key)
            if score["score"] > 0 and score.get("ambiguous", 0) == 0:
                selector_adaptation.selector_health[cache_key] = min(100, int(score["score"] / max(score["total"], 1) * 100))
                print(f"   🔄 [Auto-adaptación] Selector cacheado ({cache_key}): {score}")
                return cached
            elif cache_key == "all" and _bubble_score_is_own_only_snapshot(score):
                selector_adaptation.selector_health[cache_key] = 100
                print(
                    "   🔄 [Auto-adaptación] Selector cacheado (all) válido; "
                    "el chat actual sólo contiene mensajes propios"
                )
                return cached
            else:
                print(f"   ⚠️ [Auto-adaptación] Selector cacheado ({cache_key}) inválido/ambiguo: {score} → descartando")
                SELECTOR_CACHE.pop(cache_key, None)
                _save_selector_adaptation_cache()
        except Exception:
            SELECTOR_CACHE.pop(cache_key, None)

    best_selector = WA_USER_BUBBLES_SELECTOR if cache_key == "user" else WA_ALL_BUBBLES_SELECTOR
    best_score = {"score": 0, "total": 0, "ambiguous": 0}
    own_only_selector = ""
    print(f"   🔍 [Auto-adaptación] Probando selectores ({cache_key})...")

    for item in _selector_candidates(cache_key):
        selector = item["selector"]
        if not selector:
            continue
        if _selector_is_unsafe_broad(selector):
            print(f"      {item['name']}: descartado por ser demasiado amplio")
            continue
        try:
            score = await _score_bubble_selector(page, selector, cache_key)
            print(f"      {item['name']}: {score}")
            if score.get("ambiguous", 0) == 0 and score["score"] > best_score["score"]:
                best_selector = selector
                best_score = score
            if not own_only_selector and _bubble_score_is_own_only_snapshot(score):
                own_only_selector = selector
        except Exception as e:
            print(f"      {item['name']}: error {str(e)[:60]}")

    # Un chat de alertas/admin puede contener únicamente message-out. Eso no
    # prueba que el selector esté roto y no justifica gastar IA para repararlo.
    if best_score["score"] == 0 and own_only_selector:
        if cache_key == "all":
            SELECTOR_CACHE[cache_key] = own_only_selector
            _save_selector_adaptation_cache()
            selector_adaptation.selector_health[cache_key] = 100
            best_selector = own_only_selector
        print(
            f"   ⏭️ [Auto-adaptación] Chat con mensajes propios únicamente; "
            f"no inicio aprendizaje para '{cache_key}'"
        )
        return best_selector

    # Si no se encontró ningún selector válido, activar aprendizaje IA
    if best_score["score"] == 0:
        if proactive_monitor and proactive_monitor.learning_in_progress:
            print(
                f"   ⏭️ [Auto-adaptación] Aprendizaje ya en curso; "
                f"uso fallback para '{cache_key}'"
            )
            return best_selector

        if not _allow_proactive_learning:
            print(
                f"   ⏭️ [Auto-adaptación] Reintento de aprendizaje agotado; "
                f"uso fallback para '{cache_key}'"
            )
            return best_selector

        if proactive_monitor and (
            time.time() - proactive_monitor.last_learning_time
        ) < proactive_monitor.learning_interval:
            print(
                f"   ⏭️ [Auto-adaptación] Aprendizaje en cooldown; "
                f"uso fallback para '{cache_key}'"
            )
            return best_selector

        # 🔧 NUEVO: Verificar que haya un chat abierto ANTES de aprender
        if not await _hay_chat_abierto(page):
            print(f"   ⏭️ [Auto-adaptación] Sin chat abierto, salto el aprendizaje IA para '{cache_key}'")
            return best_selector

        if proactive_monitor:
            print(f"   🧠 [Auto-adaptación] Activando aprendizaje proactivo para '{cache_key}'...")
            await proactive_monitor._learn_all_selectors_proactive(page)
            return await get_best_bubble_selector(
                page,
                cache_key,
                force_refresh=True,
                _allow_proactive_learning=False,
            )
        else:
            print(f"   🧹 [Auto-adaptación] Ningún selector válido. Purgando clases runtime aprendidas.")
            RUNTIME_MESSAGE_IN_CLASSES.clear()
            RUNTIME_MESSAGE_IN_CLASSES.add("message-in")
            RUNTIME_MESSAGE_OUT_CLASSES.clear()
            RUNTIME_MESSAGE_OUT_CLASSES.add("message-out")
            SELECTOR_CACHE.clear()
            _save_selector_adaptation_cache()

    if best_score["score"] > 0:
        SELECTOR_CACHE[cache_key] = best_selector
        _save_selector_adaptation_cache()
        selector_adaptation.selector_health[cache_key] = min(100, int(best_score["score"] / max(best_score["total"], 1) * 100))
        print(f"   ✅ [Auto-adaptación] Mejor selector ({cache_key}): {best_selector[:80]} | {best_score}")
    else:
        print(f"   ⚠️ [Auto-adaptación] Sin burbujas clasificables ({cache_key}); uso fallback estático")

    return best_selector

async def ensure_selector_health(page):
    """
    🧠 Versión MEJORADA: Verifica la salud de los selectores y aprende nuevos si es necesario.
    """
    try:
        print("   🔍 [SelectorHealth] Verificando selectores activos...")

        # 1. Probar los selectores actuales
        for selector_type in ["all", "user"]:
            selector = await get_best_bubble_selector(page, selector_type, force_refresh=False)
            if selector:
                score = await _score_bubble_selector(page, selector, selector_type)
                print(f"   📊 {selector_type}: score={score['score']}/{score['total']}, user={score['user']}, ours={score['ours']}")

                # Si el score es bajo (< 3) y hay mensajes, activar aprendizaje
                if score["score"] < 3 and score["total"] > 5:
                    print(f"   ⚠️ [SelectorHealth] {selector_type} score bajo ({score['score']}) → activando aprendizaje IA...")
                    await _ask_ai_for_bubble_selectors(page)
                    # Reintentar con el selector aprendido
                    selector = await get_best_bubble_selector(page, selector_type, force_refresh=True)
                    print(f"   ✅ [SelectorHealth] Nuevo selector aprendido para {selector_type}")
                    break

        # 2. Si no hay mensajes, aprender selectores de la lista de chats
        chat_list = page.locator("div[data-testid='chat-list']")
        if await chat_list.count() == 0:
            print("   🔍 [SelectorHealth] Sin lista de chats visible, aprendiendo estructura...")
            await proactive_monitor._learn_chat_selectors(page)

        # 3. Guardar el estado de salud
        _save_selector_adaptation_cache()

        print("   ✅ [SelectorHealth] Verificación completada")

    except Exception as e:
        print(f"   ⚠️ [SelectorHealth] Error: {e}")

def _selector_candidates(selector_type: str) -> List[Dict[str, str]]:
    dynamic_in = ", ".join(_bubble_class_selector(cls) for cls in sorted(RUNTIME_MESSAGE_IN_CLASSES))
    dynamic_out = ", ".join(_bubble_class_selector(cls) for cls in sorted(RUNTIME_MESSAGE_OUT_CLASSES))
    dynamic_all = ", ".join(part for part in [dynamic_in, dynamic_out] if part)
    candidates = {
        "all": [
            {"name": "cache/dinamico", "selector": dynamic_all or WA_ALL_BUBBLES_SELECTOR},
            {"name": "combinado", "selector": WA_ALL_BUBBLES_SELECTOR},
            {"name": "clasico", "selector": "div.message-in, div.message-out"},
            {"name": "nuevas clases", "selector": f"div.focusable-list-item.{WA_MESSAGE_IN_CLASS}, div.focusable-list-item.{WA_MESSAGE_OUT_CLASS}"},
            {"name": "focusable", "selector": "div.focusable-list-item"},
            {"name": "message parcial", "selector": "div[class*='message']"},
            {"name": "row", "selector": "div[role='row']"},
        ],
        "user": [
            {"name": "cache/dinamico usuario", "selector": dynamic_in or WA_USER_BUBBLES_SELECTOR},
            {"name": "usuario combinado", "selector": WA_USER_BUBBLES_SELECTOR},
            {"name": "usuario clasico", "selector": "div.message-in"},
            {"name": "usuario nueva clase", "selector": f"div.focusable-list-item.{WA_MESSAGE_IN_CLASS}"},
            {"name": "focusable", "selector": "div.focusable-list-item"},
        ],
    }
    return candidates.get(selector_type, candidates["all"])


async def _score_bubble_selector(page, selector: str, selector_type: str) -> Dict[str, int]:
    locator = page.locator(selector)
    total = await locator.count()
    sample_limit = min(total, 80)
    user_count = 0
    ours_count = 0
    ambiguous_count = 0
    text_count = 0
    for i in range(sample_limit):
        try:
            bubble = locator.nth(i)
            classes = await bubble.get_attribute("class") or ""
            text = (await bubble.inner_text(timeout=500) or "").strip()
            if text:
                text_count += 1

            es_usuario = _bubble_is_user_from_classes(classes)
            es_nuestro = _bubble_is_ours_from_classes(classes)

            if es_usuario and es_nuestro:
                # Burbuja imposible: clasificada como ambas direcciones a la vez.
                # No la contamos ni como user ni como ours.
                ambiguous_count += 1
                continue

            if es_usuario:
                user_count += 1
            if es_nuestro:
                ours_count += 1
        except Exception:
            continue

    classified = user_count + ours_count
    score = user_count if selector_type == "user" else classified

    if ambiguous_count > 0:
        # Un selector que produce burbujas ambiguas es peor que uno que
        # simplemente no clasifica nada. Penalizamos fuerte.
        score = max(0, score - ambiguous_count * 10)

    if selector_type == "all" and user_count == 0:
        score = 0

    return {
        "total": total,
        "sample": sample_limit,
        "user": user_count,
        "ours": ours_count,
        "ambiguous": ambiguous_count,
        "text": text_count,
        "classified": classified,
        "score": score,
    }

async def _ask_ai_for_bubble_selectors(page) -> bool:
    try:
        samples = await page.locator(
            "div.focusable-list-item, div[class*='message'], div[role='row']"
        ).evaluate_all(
            """els => els.slice(-80).map(el => ({
                tag: el.tagName.toLowerCase(),
                className: String(el.className || ''),
                role: el.getAttribute('role') || '',
                aria: el.getAttribute('aria-label') || '',
                text: (el.innerText || '').slice(0, 180)
            })).filter(x => x.className || x.text)"""
        )
        if not samples:
            return False

        prompt = (
            "Analiza esta muestra del DOM de WhatsApp Web. Necesito detectar burbujas de chat.\n"
            "Devuelve JSON estricto con estas claves: message_in_class, message_out_class, "
            "all_selector, user_selector, confidence, reason.\n"
            "Usa clases exactas que veas en la muestra. No inventes clases. "
            "message_in_class es la burbuja recibida por el usuario; message_out_class es nuestra burbuja enviada.\n"
            f"MUESTRA:\n{json.dumps(samples, ensure_ascii=False)[:12000]}"
        )
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": "Sos un asistente experto en selectores CSS robustos para Playwright."},
                {"role": "user", "content": prompt},
            ],
            temperature=0.0,
            max_tokens=350,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        result = json.loads(resp.choices[0].message.content.strip())

        # 🔧 NUEVO: Validar que message_in_class != message_out_class
        in_cls = str(result.get("message_in_class") or "").strip().lstrip(".")
        out_cls = str(result.get("message_out_class") or "").strip().lstrip(".")

        if in_cls and out_cls and in_cls == out_cls:
            print(f"⚠️ [Auto-adaptación IA] Rechazado: message_in_class == message_out_class ('{in_cls}')")
            return False

        confidence = float(result.get("confidence", 0.0) or 0.0)
        if confidence < 0.45:
            print(f"⚠️ [Auto-adaptación IA] Confianza baja: {confidence} | {result.get('reason', '')}")
            return False

        learned = False
        for key, target in (("message_in_class", RUNTIME_MESSAGE_IN_CLASSES), ("message_out_class", RUNTIME_MESSAGE_OUT_CLASSES)):
            cls = str(result.get(key) or "").strip().lstrip(".")
            if cls and re.match(r"^[A-Za-z0-9_-]+$", cls):
                target.add(cls)
                learned = True

        for key in ("all_selector", "user_selector"):
            selector = str(result.get(key) or "").strip()
            if selector and len(selector) <= 240:
                if _selector_is_unsafe_broad(selector):
                    print(f"⚠️ [Auto-adaptación IA] Rechazo selector demasiado amplio: {selector}")
                    continue
                cache_key = "all" if key == "all_selector" else "user"
                try:
                    if await page.locator(selector).count() > 0:
                        SELECTOR_CACHE[cache_key] = selector
                        learned = True
                except Exception:
                    pass

        if learned:
            _save_selector_adaptation_cache()
            print(f"🧠 [Auto-adaptación IA] Selectores/clases aprendidos: {result}")
        return learned
    except Exception as e:
        print(f"⚠️ [Auto-adaptación IA] Error analizando DOM: {e}")
        return False



