def build_credito_senia_confirmar_slot_message(
    credit: Dict[str, Any],
    candidate: Dict[str, Any],
) -> str:
    duration = normalizar_duracion_horas(
        candidate.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    total = calcular_precio_total(duration)
    deposit = _monto_a_int(credit.get("amount"))
    if deposit is None:
        deposit = _senia_para_total(total)
    return (
        "Encontré este turno disponible para aplicar tu seña a favor:\n\n"
        f"📅 Día: {candidate.get('dia')}\n"
        f"{_court_booking_summary_label(candidate.get('cancha'))} de "
        f"{rango_horario_texto(candidate.get('hora'), duration)}\n"
        f"💲 {_fmt_precio(total)}\n\n"
        f"💵 Seña ya acreditada: {_fmt_precio(deposit)}\n"
        f"💸 Saldo pendiente: {_fmt_precio(calcular_monto_pendiente(total, deposit))}\n\n"
        "¿Confirmás que aplique tu seña a este turno?"
    )


async def detectar_respuesta_credito_senia_ia(
    mensaje: str,
    credit: Dict[str, Any],
) -> Dict[str, Any]:
    candidate = dict((credit or {}).get("candidate") or {})
    phase = "confirm_slot" if candidate else "select_slot"
    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un adjudicador semántico para aplicar una seña a favor a un turno. "
                        "Interpretá el mensaje completo dentro de CREDIT_CONTEXT; no uses keywords. "
                        "Elegí una action: select_slot si propone o modifica día/hora; confirm_slot "
                        "si acepta firmemente el candidato exacto; reject_slot si lo rechaza; other "
                        "si habla de otro tema; ambiguous si no alcanza para decidir. Para select_slot "
                        "extraé day usando la expresión del usuario o DD/MM, time HH:MM y court si lo pide. "
                        "Nunca uses confirm_slot si agrega una condición o cambia un dato. "
                        "Respondé SOLO JSON válido: {\"action\":\"select_slot|confirm_slot|"
                        "reject_slot|other|ambiguous\",\"day\":null,\"time\":null,"
                        "\"court\":null,\"reason\":\"breve\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_date": datetime.datetime.now(TIMEZONE).date().isoformat(),
                        "phase": phase,
                        "current_message": str(mensaje or ""),
                        "candidate": candidate or None,
                        "source_hold": (credit or {}).get("source_hold"),
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=160,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        action = str(data.get("action") or "").strip().lower()
        if action not in {
            "select_slot", "confirm_slot", "reject_slot", "other", "ambiguous"
        }:
            action = "ambiguous"
        result = {
            "action": action,
            "day": normalizar_valor_nullable(data.get("day")),
            "time": normalizar_hora_detectada(data.get("time")),
            "court": normalizar_valor_nullable(data.get("court")),
            "reason": str(data.get("reason") or "").strip()[:300],
        }
        print(
            "   🧠 [CREDIT SLOT IA] "
            f"action={action} day={result['day']} time={result['time']}"
        )
        return result
    except Exception as e:
        print(f"   ⚠️ [CREDIT SLOT IA] no pude adjudicar respuesta: {e}")
        return {"action": "ambiguous", "reason": f"error: {e}"}


def _resolve_credit_day(value: Any) -> Optional[str]:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.date.fromisoformat(raw)
        return f"{nombre_dia_es(parsed)} {parsed.strftime('%d/%m')}"
    except Exception:
        pass
    return normalizar_valor_nullable(resolver_fecha(raw))


def _credit_candidate_from_semantics(
    semantics: Dict[str, Any],
    credit: Dict[str, Any],
) -> Dict[str, Any]:
    current = dict((credit or {}).get("candidate") or {})
    day = _resolve_credit_day(semantics.get("day")) or current.get("dia")
    hour = normalizar_hora_detectada(semantics.get("time")) or current.get("hora")
    duration = normalizar_duracion_horas(
        current.get("duracion_horas")
        or ((credit or {}).get("source_hold") or {}).get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )
    if not day or not hora_es_valida(hour):
        return {
            "ok": False,
            "missing": [
                field for field, value in (("dia", day), ("hora", hour)) if not value
            ],
        }
    free = canchas_libres_para_bloque(day, hour, duration)
    requested_court = str(semantics.get("court") or "").strip()
    court = next((
        item for item in free
        if requested_court
        and normalizar_texto_ia(item) == normalizar_texto_ia(requested_court)
    ), None)
    if not court:
        source_court = str(((credit or {}).get("source_hold") or {}).get("cancha") or "")
        court = next((item for item in free if item == source_court), None)
    if not court and free:
        court = free[0]
    if not court:
        alt_day, alt_hour = calendario.proximo_slot_libre(
            dia_preferido=day,
            hora_preferida=hour,
            cancha=requested_court or None,
        )
        return {
            "ok": False,
            "unavailable": True,
            "dia": alt_day,
            "hora": alt_hour,
            "cancha": requested_court or None,
        }
    return {
        "ok": True,
        "candidate": {
            "dia": day,
            "hora": hour,
            "cancha": court,
            "duracion_horas": duration,
        },
    }


def _rollback_credit_pending_reservation(row: Dict[str, Any]) -> None:
    if not row:
        return
    _release_pending_hold_exact(row)
    _clear_pending_hold_tracking(row)


def aplicar_credito_senia_a_candidato(
    telefono: str,
    prospecto: Dict[str, Any],
    credit: Dict[str, Any],
    user_messages: List[str],
) -> Dict[str, Any]:
    candidate = dict((credit or {}).get("candidate") or {})
    if not candidate:
        return {"ok": False, "reason": "missing_candidate"}
    free = canchas_libres_para_bloque(
        candidate.get("dia"),
        candidate.get("hora"),
        candidate.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS,
        candidate.get("cancha"),
    )
    if candidate.get("cancha") not in free:
        credit["status"] = "available"
        credit["candidate"] = None
        _save_deposit_credit(telefono, credit)
        update_conversation_state(
            telefono or "unknown",
            fase="deposit_credit_select_slot",
            deposit_credit_id=credit.get("credit_id"),
        )
        return {
            "ok": False,
            "reason": "candidate_no_longer_available",
            "respuesta": (
                "Ese horario acaba de ocuparse y no apliqué tu seña. "
                "Tu turno señado sigue disponible. ¿Qué otro día y hora te sirve?"
            ),
        }

    created = reservar_turno_en_calendario(
        telefono,
        prospecto,
        candidate.get("dia"),
        candidate.get("hora"),
        cancha=candidate.get("cancha"),
        estado_reserva=BOOKING_STATUS_PENDING,
        senia_estado="pendiente",
        senia_monto="",
        duracion_horas=candidate.get("duracion_horas"),
        es_nuevo_turno=True,
    )
    if not created.get("ok"):
        credit["status"] = "available"
        credit["candidate"] = None
        _save_deposit_credit(telefono, credit)
        return {**created, "ok": False}

    reservations = _agent_v2_pending_deposit_reservations(
        _agent_v2_reservas_reales(telefono, prospecto)
    )
    selected = next((
        row for row in reservations
        if _reserva_coincide_slot(
            row,
            created.get("dia"),
            created.get("hora"),
            created.get("cancha"),
        )
    ), None)
    if not selected:
        _rollback_credit_pending_reservation({
            "telefono": telefono,
            "nombre": (prospecto or {}).get("nombre") or "",
            "fecha": created.get("dia"),
            "hora": created.get("hora"),
            "cancha": created.get("cancha"),
            "senia_estado": "pendiente",
            "estado": BOOKING_STATUS_PENDING,
        })
        return {"ok": False, "reason": "created_reservation_not_verified"}

    confirmed = confirmar_senia_reserva_pendiente(
        telefono,
        prospecto,
        get_conversation_state(telefono),
        dict(credit.get("receipt") or {}),
        reserva_objetivo=selected,
        allow_credit_application=True,
        credit_id=str(credit.get("credit_id") or ""),
    )
    if not confirmed.get("ok"):
        _rollback_credit_pending_reservation(selected)
        return confirmed

    credit["status"] = "applied"
    credit["candidate"] = candidate
    credit["applied_at"] = datetime.datetime.now(TIMEZONE).isoformat()
    credit["reservation"] = {
        "fecha": confirmed.get("dia") or candidate.get("dia"),
        "hora": confirmed.get("hora") or candidate.get("hora"),
        "cancha": confirmed.get("cancha") or candidate.get("cancha"),
    }
    _save_deposit_credit(telefono, credit)
    update_conversation_state(
        telefono or "unknown",
        fase="coordinacion_confirmada",
        deposit_credit_id=None,
        deposit_credit_candidate=None,
        dia_propuesto=confirmed.get("dia") or candidate.get("dia"),
        hora_propuesta=confirmed.get("hora") or candidate.get("hora"),
        cancha_propuesta=confirmed.get("cancha") or candidate.get("cancha"),
        senia_estado="pagada",
    )
    registrar_turno_confirmado_en_csv(
        telefono,
        prospecto,
        user_messages,
        confirmed.get("dia") or candidate.get("dia"),
        confirmed.get("hora") or candidate.get("hora"),
    )
    registrar_metrica_operativa("late_payment_credit_applied", {
        "telefono": telefono,
        "credit_id": credit.get("credit_id"),
        "reservation": credit.get("reservation"),
    })
    return {**confirmed, "ok": True, "credit_applied": True}


async def manejar_pago_tardio_o_credito_senia(
    telefono: str,
    prospecto: Dict[str, Any],
    user_messages: List[str],
    image_path: str = "",
) -> Optional[Dict[str, Any]]:
    pending = _agent_v2_pending_deposit_reservations(
        _agent_v2_reservas_reales(telefono, prospecto)
    )
    if pending:
        return None

    credit = obtener_credito_senia_disponible(telefono)
    expired_hold = obtener_hold_expirado_pago_tardio(telefono)
    if image_path and os.path.isfile(image_path) and (expired_hold or credit):
        source_hold = dict((expired_hold or {}).get("row") or {})
        monto_tardio_esperado = (
            _monto_a_int((credit or {}).get("amount"))
            or _senia_guardada_o_configurada(source_hold, source_hold.get("precio_total"))
        )
        comprobante = analizar_comprobante_senia(
            image_path,
            monto_esperado=monto_tardio_esperado,
        )
        try:
            os.remove(image_path)
        except Exception:
            pass
        contract = _agent_v2_payment_contract(comprobante)
        if not contract.get("ok"):
            return {
                "handled": True,
                "ok": False,
                "admin_alert": (
                    "⚠️ Comprobante tardío requiere revisión manual. "
                    f"Cliente: {(prospecto or {}).get('nombre') or telefono}. "
                    f"Teléfono: {telefono}. Motivos: {contract.get('reasons')}"
                ),
                "admin_dedupe_key": (
                    f"late_payment_review|{normalize_phone(telefono)}|"
                    f"{'|'.join(contract.get('fingerprints') or [])}"
                ),
                "respuesta": (
                    "Recibí la imagen, pero no pude validar el comprobante con "
                    "seguridad. No acredité ninguna seña y lo tiene que revisar el encargado."
                ),
            }

        used = comprobante_ya_usado(comprobante)
        if used:
            same_owner = normalize_phone(used.get("telefono") or "") == normalize_phone(
                telefono or ""
            )
            if not (
                same_owner
                and used.get("estado") == "credito_disponible"
                and credit
                and used.get("credit_id") == credit.get("credit_id")
            ):
                return {
                    "handled": True,
                    "ok": False,
                    "respuesta": (
                        "Ese comprobante ya fue aplicado o acreditado anteriormente. "
                        "No generé un segundo turno señado."
                    ),
                }
            return {
                "handled": True,
                "ok": True,
                "respuesta": build_credito_senia_pedir_slot_message(credit),
            }

        if expired_hold:
            source = dict(expired_hold.get("row") or {})
            restore = reservar_turno_en_calendario(
                telefono,
                prospecto,
                source.get("fecha"),
                source.get("hora"),
                cancha=source.get("cancha"),
                estado_reserva=BOOKING_STATUS_PENDING,
                senia_estado="pendiente",
                senia_monto="",
                duracion_horas=source.get("duracion_horas")
                    or DEFAULT_TURN_DURATION_HOURS,
                con_quincho=str(source.get("con_quincho") or "").strip().casefold()
                    in {"si", "sí", "true", "1"},
                quincho=source.get("quincho") or "",
                quincho_hora_inicio=source.get("quincho_hora_inicio") or "",
                quincho_duracion_horas=source.get("quincho_duracion_horas"),
                es_nuevo_turno=True,
            )
            if restore.get("ok"):
                restored_rows = _agent_v2_pending_deposit_reservations(
                    _agent_v2_reservas_reales(telefono, prospecto)
                )
                restored = next((
                    row for row in restored_rows
                    if _reserva_coincide_slot(
                        row,
                        restore.get("dia"),
                        restore.get("hora"),
                        restore.get("cancha"),
                    )
                ), None)
                confirmed = confirmar_senia_reserva_pendiente(
                    telefono,
                    prospecto,
                    get_conversation_state(telefono),
                    comprobante,
                    reserva_objetivo=restored,
                ) if restored else {"ok": False, "motivo": "restore_not_verified"}
                if confirmed.get("ok"):
                    marcar_hold_expirado_pago_tardio(
                        telefono,
                        expired_hold.get("hold_key"),
                        "restored_and_paid",
                    )
                    return {
                        "handled": True,
                        **confirmed,
                        "respuesta": confirmed.get("respuesta"),
                    }
                if restored:
                    _rollback_credit_pending_reservation(restored)
                else:
                    _rollback_credit_pending_reservation({
                        "telefono": telefono,
                        "nombre": (prospecto or {}).get("nombre") or "",
                        "fecha": restore.get("dia"),
                        "hora": restore.get("hora"),
                        "cancha": restore.get("cancha"),
                        "senia_estado": "pendiente",
                        "estado": BOOKING_STATUS_PENDING,
                    })

            credit_result = crear_credito_senia_desde_comprobante(
                telefono,
                prospecto,
                comprobante,
                expired_hold,
            )
            if not credit_result.get("ok"):
                return {
                    "handled": True,
                    "ok": False,
                    "respuesta": (
                        "El comprobante ya figura utilizado y no generé otro "
                        "turno señado. El encargado debe revisar este caso."
                    ),
                }
            credit = dict(credit_result.get("credit") or {})
            update_conversation_state(
                telefono or "unknown",
                fase="deposit_credit_select_slot",
                deposit_credit_id=credit.get("credit_id"),
                deposit_credit_candidate=None,
            )
            return {
                "handled": True,
                "ok": True,
                "credit_created": True,
                "admin_alert": build_credito_senia_admin_alert(
                    telefono,
                    prospecto,
                    credit,
                ),
                "admin_dedupe_key": (
                    f"late_payment_credit|{credit.get('credit_id')}"
                ),
                "respuesta": build_credito_senia_pedir_slot_message(credit),
            }

    if not credit:
        return None

    message = " ".join(user_messages or []).strip()
    semantics = await detectar_respuesta_credito_senia_ia(message, credit)
    action = semantics.get("action")
    if action == "confirm_slot" and credit.get("candidate"):
        result = aplicar_credito_senia_a_candidato(
            telefono,
            prospecto,
            credit,
            user_messages,
        )
        return {"handled": True, **result}
    if action == "reject_slot":
        credit["status"] = "available"
        credit["candidate"] = None
        _save_deposit_credit(telefono, credit)
        update_conversation_state(
            telefono or "unknown",
            fase="deposit_credit_select_slot",
            deposit_credit_candidate=None,
        )
        return {
            "handled": True,
            "ok": True,
            "respuesta": "Dale, no apliqué la seña. ¿Qué otro día y hora te sirve?",
        }
    if action == "select_slot":
        resolved = _credit_candidate_from_semantics(semantics, credit)
        if resolved.get("missing"):
            missing = resolved.get("missing") or []
            question = (
                "¿Qué día y hora te gustaría reservar?"
                if len(missing) > 1
                else "¿Para qué día lo querés?"
                if "dia" in missing
                else "¿A qué hora te gustaría reservar?"
            )
            return {"handled": True, "ok": False, "respuesta": question}
        if resolved.get("unavailable"):
            return {
                "handled": True,
                "ok": False,
                "respuesta": (
                    "Ese horario ya está ocupado y tu seña sigue guardada. "
                    f"¿Te sirve {resolved.get('dia')} a las "
                    f"{formatear_hora_para_mensaje(resolved.get('hora'))}?"
                ),
            }
        candidate = dict(resolved.get("candidate") or {})
        credit["status"] = "pending_confirmation"
        credit["candidate"] = candidate
        _save_deposit_credit(telefono, credit)
        update_conversation_state(
            telefono or "unknown",
            fase="deposit_credit_confirm_slot",
            deposit_credit_id=credit.get("credit_id"),
            deposit_credit_candidate=candidate,
            dia_propuesto=candidate.get("dia"),
            hora_propuesta=candidate.get("hora"),
            cancha_propuesta=candidate.get("cancha"),
        )
        return {
            "handled": True,
            "ok": True,
            "respuesta": build_credito_senia_confirmar_slot_message(
                credit,
                candidate,
            ),
        }
    return None





# ================================
# FUNCIONES DE MEDIA (AUDIO E IMAGEN) - VERSIÓN DEFINITIVA
# ================================

# ================================
# FUNCIONES DE MEDIA CORREGIDAS
# ================================

# Fuente canónica: bloque copiado sin modificaciones desde
# `WPSetter - copia (500).py`. La prueba test_media_handler_copy500_integrity.py
# protege las siete funciones del handler contra cambios accidentales.

async def _bubble_is_audio(bubble) -> bool:
    """
    Detecta si la burbuja contiene un mensaje de audio.

    CRITERIOS DE DETECCIÓN (en orden de prioridad):
    1. Íconos específicos de audio (data-icon)
    2. Aria-label relacionado con audio/mensaje de voz
    3. Formato de duración (MM:SS) sin texto adicional
    4. NO detecta como audio si tiene "Foto" o "Imagen"
    """
    try:
        # 1. VERIFICAR ÍCONOS DE AUDIO (más confiable)
        icon_selectors = [
            "xpath=.//span[@data-icon='audio-play']",
            "xpath=.//span[@data-icon='ptt-play']",
            "xpath=.//span[@data-icon='audio-play-large']",
            "xpath=.//span[@data-icon='ptt']",
            "xpath=.//span[@data-icon='audio-download']",
            "xpath=.//span[@data-icon='audio-cancel']",
        ]
        for sel in icon_selectors:
            if await bubble.locator(sel).count() > 0:
                return True

        # 2. VERIFICAR ARIA-LABEL (texto alternativo)
        aria_selectors = [
            "xpath=.//button[contains(@aria-label,'Reproducir') or contains(@aria-label,'reproducir')]",
            "xpath=.//*[contains(@aria-label,'mensaje de voz') or contains(@aria-label,'Mensaje de voz')]",
            "xpath=.//*[contains(@aria-label,'audio') or contains(@aria-label,'Audio')]",
        ]
        for sel in aria_selectors:
            if await bubble.locator(sel).count() > 0:
                return True

        # 3. VERIFICAR CONTENIDO DE TEXTO
        try:
            inner_text = await bubble.inner_text()
        except Exception:
            inner_text = ""

        # Si tiene "Foto" o "Imagen", NO es audio
        if re.search(r"\b(Foto|Imagen|Image|Photo)\b", str(inner_text or ""), re.IGNORECASE):
            return False

        # Analizar líneas del texto
        lines = [line.strip() for line in str(inner_text or "").splitlines() if line.strip()]
        if not lines:
            return False

        # El primer elemento suele ser la duración (MM:SS)
        first_line = lines[0]
        if re.fullmatch(r'\d{1,2}:\d{2}', first_line):
            # Si solo tiene una línea (la duración), es audio
            if len(lines) == 1:
                return True

            # Si tiene más líneas, verificar que ninguna sea "Foto" o "Imagen"
            texto_completo = " ".join(lines)
            if not re.search(r"\b(Foto|Imagen|Image|Photo)\b", texto_completo, re.IGNORECASE):
                return True

        # 4. VERIFICAR CLASES ESPECÍFICAS DE WHATSAPP PARA AUDIO
        audio_class_selectors = [
            "xpath=.//div[contains(@class, 'audio')]",
            "xpath=.//div[contains(@class, 'ptt')]",
        ]
        for sel in audio_class_selectors:
            if await bubble.locator(sel).count() > 0:
                return True

        return False

    except Exception as e:
        return False

async def _bubble_is_image(bubble) -> bool:
    """
    Detecta si la burbuja contiene una imagen.

    CRITERIOS DE DETECCIÓN:
    1. Elemento <img> dentro de la burbuja (PERO excluyendo íconos de audio)
    2. Aria-label relacionado con imagen
    3. Texto "Foto" o "Imagen" en el contenido
    4. 🔧 EXCLUYE EXPLÍCITAMENTE los audios e íconos de audio
    """
    try:
        # ============================================================
        # 1. PRIMERO: SI TIENE ÍCONOS DE AUDIO, NO ES IMAGEN
        # ============================================================
        audio_icons = [
            "xpath=.//span[@data-icon='audio-play']",
            "xpath=.//span[@data-icon='ptt-play']",
            "xpath=.//span[@data-icon='audio-play-large']",
            "xpath=.//span[@data-icon='ptt']",
            "xpath=.//button[contains(@aria-label,'Reproducir') or contains(@aria-label,'reproducir')]",
        ]
        for sel in audio_icons:
            if await bubble.locator(sel).count() > 0:
                return False

        # ============================================================
        # 2. SI EL TEXTO ES SOLO UNA DURACIÓN (MM:SS), ES AUDIO
        # ============================================================
        try:
            inner_text = await bubble.inner_text()
        except Exception:
            inner_text = ""

        lines = [line.strip() for line in str(inner_text or "").splitlines() if line.strip()]
        if lines and len(lines) == 1:
            first_line = lines[0]
            # Si solo tiene formato de duración de audio (MM:SS), NO es imagen
            if re.fullmatch(r'\d{1,2}:\d{2}', first_line):
                return False

        # ============================================================
        # 3. BUSCAR ELEMENTO IMG (real) - PERO FILTRAR ÍCONOS PEQUEÑOS
        # ============================================================
        img = bubble.locator("xpath=.//img")
        if await img.count() > 0:
            # Verificar si la imagen es un ícono pequeño (como el de audio)
            try:
                width = await img.first.get_attribute("width") or "0"
                height = await img.first.get_attribute("height") or "0"
                try:
                    # Los íconos de audio suelen ser < 40px
                    if int(width) < 40 or int(height) < 40:
                        # Verificar si es audio por si acaso
                        if await _bubble_is_audio(bubble):
                            return False
                        # Si no es audio, pero es pequeño, podría ser un sticker o emoji
                        # Mejor verificar si el texto contiene "Foto"
                        if "Foto" not in inner_text and "Imagen" not in inner_text:
                            return False
                except (ValueError, TypeError):
                    pass
            except:
                pass

            # Si tiene texto "Foto" o "Imagen", es imagen
            if "Foto" in inner_text or "Imagen" in inner_text:
                return True

            # Si el texto NO es solo una duración y tiene img, probablemente es imagen
            if lines and len(lines) > 0:
                if not re.fullmatch(r'\d{1,2}:\d{2}', lines[0]):
                    return True

            return False

        # ============================================================
        # 4. VERIFICAR ARIA-LABEL DE IMAGEN
        # ============================================================
        aria_selectors = [
            "xpath=.//*[contains(@aria-label,'imagen') or contains(@aria-label,'Imagen')]",
            "xpath=.//*[contains(@aria-label,'foto') or contains(@aria-label,'Foto')]",
        ]
        for sel in aria_selectors:
            if await bubble.locator(sel).count() > 0:
                return True

        # ============================================================
        # 5. VERIFICAR CONTENIDO DE TEXTO
        # ============================================================
        # Si tiene "Foto" o "Imagen" en el texto, es imagen
        if re.search(r"\b(Foto|Imagen|Image|Photo)\b", str(inner_text or ""), re.IGNORECASE):
            # Verificar que no sea audio (por si acaso)
            if await _bubble_is_audio(bubble):
                return False
            return True

        # ============================================================
        # 6. VERIFICAR CLASES ESPECÍFICAS DE WHATSAPP PARA IMAGEN
        # ============================================================
        image_class_selectors = [
            "xpath=.//div[contains(@class, 'image')]",
            "xpath=.//div[contains(@class, 'photo')]",
        ]
        for sel in image_class_selectors:
            if await bubble.locator(sel).count() > 0:
                if await _bubble_is_audio(bubble):
                    return False
                return True

        return False

    except Exception as e:
        return False


async def _detectar_tipo_media_bubble(bubble) -> str:
    """
    Determina el tipo real de la burbuja: 'audio', 'imagen' o 'ninguno'.
    Las señales son mutuamente excluyentes: un <img> genérico (avatar, sticker,
    thumbnail de link) NO alcanza para clasificar como imagen si hay evidencia de audio.
    """
    try:
        try:
            inner_text = await bubble.inner_text()
        except Exception:
            inner_text = ""
        texto = str(inner_text or "")

        # --- Señales FUERTES de audio: iconos específicos de reproducción/voz ---
        audio_icon_selectors = [
            "xpath=.//span[@data-icon='audio-play']",
            "xpath=.//span[@data-icon='ptt-play']",
            "xpath=.//span[@data-icon='audio-play-large']",
            "xpath=.//span[@data-icon='ptt']",
            "xpath=.//span[@data-icon='audio-download']",
            "xpath=.//span[@data-icon='audio-cancel']",
            "xpath=.//button[contains(@aria-label,'Reproducir') or contains(@aria-label,'reproducir')]",
            "xpath=.//*[contains(@aria-label,'mensaje de voz') or contains(@aria-label,'Mensaje de voz') or contains(@aria-label,'audio') or contains(@aria-label,'Audio')]",
        ]
        es_audio_por_icono = False
        for sel in audio_icon_selectors:
            if await bubble.locator(sel).count() > 0:
                es_audio_por_icono = True
                break

        # --- Señales FUERTES de imagen: iconos específicos de media/imagen ---
        image_icon_selectors = [
            "xpath=.//span[@data-icon='media-download']",
            "xpath=.//span[@data-icon='image-download']",
            "xpath=.//span[@data-icon='image']",
        ]
        es_imagen_por_icono = False
        for sel in image_icon_selectors:
            if await bubble.locator(sel).count() > 0:
                es_imagen_por_icono = True
                break

        tiene_texto_foto = bool(re.search(r"\b(Foto|Imagen|Image|Photo)\b", texto, re.IGNORECASE))

        # Patrón típico de duración de audio: una línea tipo "0:08"
        lineas = [l.strip() for l in texto.splitlines() if l.strip()]
        texto_sin_hora = "\n".join(lineas[1:]) if lineas and re.fullmatch(r"\d{1,2}:\d{2}", lineas[0]) else "\n".join(lineas)
        parece_duracion_audio = bool(re.fullmatch(r"\d{1,2}:\d{2}", texto_sin_hora.strip()))

        es_audio = es_audio_por_icono or (parece_duracion_audio and not tiene_texto_foto and not es_imagen_por_icono)
        es_imagen = (es_imagen_por_icono or tiene_texto_foto) and not es_audio

        # <img> genérico SOLO cuenta como último recurso, y solo si no hay ninguna
        # señal de audio (ni icono ni patrón de duración)
        if not es_audio and not es_imagen and not es_audio_por_icono and not parece_duracion_audio:
            try:
                if await bubble.locator("xpath=.//img").count() > 0:
                    es_imagen = True
            except Exception:
                pass

        if es_audio:
            return "audio"
        if es_imagen:
            return "imagen"
        return "ninguno"
    except Exception:
        return "ninguno"


async def _extract_audio_blob_from_bubble(page, bubble) -> Optional[Dict[str, Any]]:
    """
    Extrae el audio desde el DOM de WhatsApp sin abrir el menú Descargar.

    WhatsApp suele exponer un ``audio.currentSrc`` blob después de cargar o
    reproducir el mensaje. Esta vía evita que Chrome gestione una descarga de UI,
    que en algunas versiones puede cerrar el contexto persistente.
    """
    if page is None or page.is_closed():
        return None

    extraction_script = """
        async (root) => {
            const candidates = [];
            const audioElements = [
                ...root.querySelectorAll('audio'),
                ...Array.from(document.querySelectorAll('audio')).filter(
                    audio => !root.contains(audio)
                ),
            ];
            audioElements.sort((a, b) => Number(a.paused) - Number(b.paused));
            for (const audio of audioElements) {
                for (const value of [
                    audio.currentSrc,
                    audio.src,
                    audio.querySelector('source')?.src,
                ]) {
                    if (value && !candidates.includes(value)) candidates.push(value);
                }
            }
            for (const element of root.querySelectorAll('[src], [data-src], [href]')) {
                for (const attr of ['src', 'data-src', 'href']) {
                    const value = element.getAttribute(attr) || '';
                    if (
                        value &&
                        (value.startsWith('blob:') || value.startsWith('data:audio/')) &&
                        !candidates.includes(value)
                    ) candidates.push(value);
                }
            }
            for (const src of candidates) {
                try {
                    const response = await fetch(src);
                    if (!response.ok) continue;
                    const blob = await response.blob();
                    if (!blob || blob.size <= 0) continue;
                    const dataUrl = await new Promise((resolve, reject) => {
                        const reader = new FileReader();
                        reader.onload = () => resolve(reader.result);
                        reader.onerror = () => reject(reader.error);
                        reader.readAsDataURL(blob);
                    });
                    return {
                        data_url: dataUrl,
                        mime_type: blob.type || 'audio/ogg',
                        size: blob.size,
                    };
                } catch (_) {}
            }
            return null;
        }
    """

    async def extract_once():
        try:
            payload = await bubble.evaluate(extraction_script)
            return payload if isinstance(payload, dict) else None
        except Exception:
            return None

    payload = await extract_once()
    if payload:
        return payload

    # Si todavía no existe currentSrc, pedirle al reproductor de WhatsApp que
    # cargue el medio. Este click no abre el gestor de descargas del navegador.
    loader_selectors = [
        "xpath=.//span[@data-icon='audio-download']",
        "xpath=.//span[@data-icon='ptt-download']",
        "xpath=.//button[contains(@aria-label,'Descargar audio')]",
    ]
    play_selectors = [
        "xpath=.//span[@data-icon='audio-play']",
        "xpath=.//span[@data-icon='ptt-play']",
        "xpath=.//button[contains(@aria-label,'Reproducir') or contains(@aria-label,'reproducir')]",
    ]
    clicked = False
    for selector in [*loader_selectors, *play_selectors]:
        try:
            control = bubble.locator(selector)
            if await control.count() > 0:
                await control.first.click()
                clicked = True
                await asyncio.sleep(1.2)
                break
        except Exception:
            continue

    if not clicked or page.is_closed():
        return None

    # La burbuja anterior del lote puede tardar algunos segundos en materializar
    # el Blob descifrado. También puede montar el <audio> fuera de la burbuja;
    # ``extract_once`` ya contempla ambos lugares.
    payload = None
    for _ in range(12):
        if page.is_closed():
            break
        payload = await extract_once()
        if payload:
            break
        await asyncio.sleep(0.5)
    # No dejar un audio sonando después de obtener el Blob.
    try:
        await bubble.evaluate(
            "root => root.querySelectorAll('audio').forEach(audio => audio.pause())"
        )
    except Exception:
        pass
    return payload


async def _transcribe_audio_blob_payload(payload: Dict[str, Any]) -> Any:
    """Persiste temporalmente un Blob ya extraído y usa el transcriptor normal."""
    data_url = str((payload or {}).get("data_url") or "")
    if "," not in data_url:
        return False
    try:
        encoded = data_url.split(",", 1)[1]
        raw_audio = base64.b64decode(encoded, validate=True)
    except Exception:
        return False
    if not raw_audio:
        return False

    mime = str((payload or {}).get("mime_type") or "audio/ogg").lower()
    extension = ".webm" if "webm" in mime else ".mp3" if "mpeg" in mime else ".ogg"
    os.makedirs("audios", exist_ok=True)
    save_path = os.path.join("audios", f"{uuid.uuid4()}{extension}")
    try:
        with open(save_path, "wb") as audio_file:
            audio_file.write(raw_audio)
        print(
            f"💾 [AUDIO DOM] Guardado sin menú: {save_path} "
            f"({len(raw_audio)} bytes)"
        )
        return await transcribe_audio_to_text(save_path)
    finally:
        await delete_audio_file(save_path)


async def last_message_media_handler(
    page,
    target_bubble=None,
    allow_context_menu_fallback=True,
):
    """
    Detecta y procesa el último mensaje del usuario.

    DETECCIÓN:
    - Si es AUDIO → descarga y transcribe
    - Si es IMAGEN → captura por screenshot
    - Si no es media → retorna False

    🔧 CORREGIDO: Usa _detectar_tipo_media_bubble para determinar el tipo real.
    """
    try:
        # Sin target conserva exactamente la ruta estable de copia (132). El
        # orquestador batch puede pasar una burbuja pendiente concreta para
        # reutilizar la misma descarga/transcripción sin limitarse a la última.
        last_user_bubble = (
            target_bubble
            if target_bubble is not None
            else await _last_user_bubble_locator(page)
        )

        if await last_user_bubble.count() == 0:
            return False

        # ============================================================
        # 1. DETECTAR TIPO DE MEDIA (USANDO SEÑALES MUTUAMENTE EXCLUYENTES)
        # ============================================================
        tipo_media = await _detectar_tipo_media_bubble(last_user_bubble)

        # LOG DE DETECCIÓN
        print(f"   📊 [Media] Tipo detectado: {tipo_media}")

        # Si no es ni audio ni imagen, salir
        if tipo_media == "ninguno":
            return False

        # ============================================================
        # 2. PROCESAR SEGÚN EL TIPO DETECTADO
        # ============================================================

        # --- CASO 1: ES AUDIO ---
        if tipo_media == "audio":
            print(f"🎬 [AUDIO] Detectado, extrayendo desde el reproductor...")

            # Primera vía: Blob ya descifrado por WhatsApp. Es obligatoria para
            # audios anteriores del mismo lote porque abrir su menú contextual
            # puede cerrar el contexto persistente de Chrome.
            blob_payload = await _extract_audio_blob_from_bubble(
                page,
                last_user_bubble,
            )
            if blob_payload:
                transcribed_text = await _transcribe_audio_blob_payload(blob_payload)
                if transcribed_text:
                    print("   ✅ [AUDIO DOM] Transcripción obtenida sin menú Descargar")
                    return transcribed_text
            if page is None or page.is_closed():
                return False
            print("   ↪️ [AUDIO DOM] WhatsApp no expuso Blob; evalúo descarga UI segura")

            # Hover para que aparezca la flecha
            await last_user_bubble.hover()
            await asyncio.sleep(0.5)

            # Buscar la flecha (chevron)
            chevron_selectors = [
                "xpath=.//span[@data-icon='chevron-down']",
                "xpath=.//span[@data-icon='ic-chevron-down-menu']",
                "xpath=.//span[@data-icon='down-context']",
                "xpath=.//span[@data-icon='chevron-down-alt']",
                "xpath=.//button[contains(@aria-label,'Menú') or contains(@aria-label,'Menu')]",
                "xpath=.//*[@role='button' and (contains(@aria-label,'Menú') or contains(@aria-label,'Menu'))]",
            ]

            chevron_clicked = False
            for sel in chevron_selectors:
                try:
                    chevron = last_user_bubble.locator(sel)
                    if await chevron.count() > 0:
                        await chevron.first.click()
                        chevron_clicked = True
                        print(f"   ✅ [AUDIO] Flecha clickeada")
                        await asyncio.sleep(0.3)
                        break
                except:
                    continue

            if not chevron_clicked:
                if not allow_context_menu_fallback:
                    print(
                        "   ⚠️ [AUDIO BATCH] Audio anterior sin menú seguro; "
                        "no uso click derecho para no cerrar Chrome"
                    )
                    return False
                print(f"   ⚠️ [AUDIO] No se encontró la flecha, probando click derecho")
                await last_user_bubble.click(button="right")
                await asyncio.sleep(0.5)

            # Buscar y click en 'Descargar'
            download_selectors = [
                "xpath=//span[normalize-space()='Descargar']",
                "xpath=//li[contains(.,'Descargar')]",
            ]

            download_option = None
            for sel in download_selectors:
                try:
                    opt = page.locator(sel)
                    await opt.first.wait_for(state="visible", timeout=2000)
                    download_option = opt.first
                    print(f"   ✅ [AUDIO] Opción Descargar encontrada")
                    break
                except:
                    continue

            if not download_option:
                print(f"   ❌ [AUDIO] No se encontró opción 'Descargar'")
                await page.keyboard.press("Escape")
                return False

            # Descargar y transcribir
            async with page.expect_download() as download_info:
                await download_option.click()

            download = await download_info.value
            os.makedirs("audios", exist_ok=True)
            filename = f"{uuid.uuid4()}_{download.suggested_filename}"
            save_path = f"audios/{filename}"

            # V173 MEDIA500:
            # Conservamos el handler de V500, pero no usamos save_as como vía
            # principal. En el incidente live esa llamada cerró el
            # page/context/browser después de que Playwright ya había recibido
            # correctamente el Download. `download.path()` espera la descarga
            # completa y luego copiamos el temporal con Python, sin volver a
            # tocar el gestor de descargas de Chrome.
            temp_download_path = await download.path()
            if not temp_download_path or not os.path.exists(temp_download_path):
                raise RuntimeError(
                    "media_download_temp_path_unavailable: "
                    f"{download.suggested_filename}"
                )
            shutil.copy2(temp_download_path, save_path)
            print(f"💾 [AUDIO] Guardado (MEDIA500 path-copy): {save_path}")

            transcribed_text = await transcribe_audio_to_text(save_path)
            if transcribed_text:
                await delete_audio_file(save_path)
                return transcribed_text
            await delete_audio_file(save_path)
            return False

        # --- CASO 2: ES IMAGEN ---
        if tipo_media == "imagen":
            print(f"🖼️ [IMAGEN] Detectada, capturando por screenshot...")
            os.makedirs("comprobantes", exist_ok=True)

            # Hacer hover para que la imagen se vea bien
            await last_user_bubble.hover()
            await asyncio.sleep(0.3)

            # Capturar screenshot de la burbuja
            path = os.path.join("comprobantes", f"comprobante_{uuid.uuid4()}.png")
            await last_user_bubble.screenshot(path=path)
            print(f"🖼️ [IMAGEN] Capturada: {path}")
            return path

        # Si llegamos aquí, algo salió mal
        return False

    except Exception as e:
        print(f"❌ [MEDIA] Error: {e}")
        return False


async def read_user_messages_with_pending_media(page) -> Tuple[List[str], Optional[str]]:
    """
    Procesa TODO el lote pendiente preservando el orden conversacional.

    ``read_user_messages`` define el backlog posterior al último mensaje-out y
    conserva la posición DOM de cada burbuja. Cada audio de ese conjunto se
    procesa con la descarga estable de copia (132); luego las transcripciones
    reemplazan sus placeholders antes de entrar al agente. El lote es atómico:
    si un audio no se puede transcribir, no se responde parcialmente.
    """
    global _LAST_READ_USER_MESSAGE_META

    user_messages = await read_user_messages(page)
    metadata = list(_LAST_READ_USER_MESSAGE_META or [])
    if not user_messages or len(metadata) != len(user_messages):
        # Conserva la compatibilidad para una imagen sin texto/caption que no
        # haya producido un registro legible en el recorrido del backlog.
        media_result = await last_message_media_handler(page)
        if isinstance(media_result, str):
            if media_result.lower().endswith(
                (".png", ".jpg", ".jpeg", ".gif", ".webp")
            ):
                return ["[IMAGEN_ENVIADA]"], media_result
            return [media_result], None
        return user_messages, None

    try:
        bubble_selector = await get_best_bubble_selector(page, "all")
        all_bubbles = page.locator(bubble_selector)
        bubble_count = await all_bubbles.count()
    except Exception as exc:
        print(f"   ⚠️ [MEDIA BATCH] no pude resolver burbujas pendientes: {exc}")
        return user_messages, None

    processed = list(user_messages)
    image_path = None
    audio_count = 0
    failed_media_positions = []

    for message_index, item in enumerate(metadata):
        try:
            position = int(item.get("posicion"))
        except (TypeError, ValueError):
            if str(item.get("media_type") or "").lower() in {"audio", "imagen"}:
                failed_media_positions.append(item.get("posicion"))
            continue
        if position < 0 or position >= bubble_count:
            if str(item.get("media_type") or "").lower() in {"audio", "imagen"}:
                failed_media_positions.append(position)
            continue

        bubble = all_bubbles.nth(position)
        hinted_media_type = str(item.get("media_type") or "ninguno").strip().lower()
        try:
            detected_media_type = await _detectar_tipo_media_bubble(bubble)
        except Exception as exc:
            print(
                f"   ⚠️ [MEDIA BATCH] no pude inspeccionar burbuja #{position}: {exc}"
            )
            detected_media_type = "ninguno"
        # El snapshot inicial es autoridad: WhatsApp puede re-renderizar la
        # burbuja y ocultar transitoriamente la señal de una foto reenviada.
        media_type = (
            detected_media_type
            if detected_media_type in {"audio", "imagen"}
            else hinted_media_type
        )
        if media_type not in {"audio", "imagen"}:
            continue

        media_result = False
        attempts = 2
        for attempt in range(1, attempts + 1):
            media_result = await last_message_media_handler(
                page,
                target_bubble=bubble,
                allow_context_menu_fallback=(message_index == len(metadata) - 1),
            )
            if isinstance(media_result, str) and media_result.strip():
                break
            if page is None or page.is_closed():
                break
            if attempt < attempts:
                print(
                    f"   🔁 [MEDIA BATCH] reintento de audio "
                    f"#{message_index + 1}/{len(metadata)}"
                )
                try:
                    await page.keyboard.press("Escape")
                except Exception:
                    pass
                await asyncio.sleep(0.4)

        if media_type == "audio":
            if not isinstance(media_result, str) or not media_result.strip():
                failed_media_positions.append(position)
                continue
            audio_count += 1
            transcript = media_result.strip()
            processed[message_index] = transcript
            metadata[message_index]["texto"] = transcript
            metadata[message_index]["media_type"] = "audio"
            print(
                f"🎤 [AUDIO BATCH] {audio_count}: "
                f"{transcript[:120]}{'...' if len(transcript) > 120 else ''}"
            )
        elif media_type == "imagen" and (
            not isinstance(media_result, str) or not media_result.strip()
        ):
            # Último recurso seguro para fotos reenviadas: conservamos la
            # evidencia visual de la burbuja exacta, no una foto genérica.
            try:
                os.makedirs("comprobantes", exist_ok=True)
                direct_path = os.path.join(
                    "comprobantes", f"comprobante_{uuid.uuid4()}.png"
                )
                await bubble.hover()
                await asyncio.sleep(0.2)
                await bubble.screenshot(path=direct_path)
                media_result = direct_path
                print(f"   ✅ [MEDIA BATCH IMAGE FALLBACK] burbuja #{position}: {direct_path}")
            except Exception as exc:
                print(f"   ⚠️ [MEDIA BATCH IMAGE FALLBACK] burbuja #{position}: {exc}")

        if media_type == "imagen" and isinstance(media_result, str) and media_result.lower().endswith(
            (".png", ".jpg", ".jpeg", ".gif", ".webp")
        ):
            processed[message_index] = "[IMAGEN_ENVIADA]"
            metadata[message_index]["texto"] = "[IMAGEN_ENVIADA]"
            metadata[message_index]["media_type"] = "imagen"
            image_path = media_result
        elif media_type == "imagen":
            failed_media_positions.append(position)

    if failed_media_positions:
        print(
            "   ❌ [MEDIA BATCH] lote multimedia incompleto; no respondo parcialmente. "
            f"burbujas pendientes={failed_media_positions}"
        )
        return [], None

    _LAST_READ_USER_MESSAGE_META = metadata
    if audio_count:
        print(
            f"   ✅ [AUDIO BATCH] {audio_count} audio(s) transcripto(s) "
            "en orden → una sola intervención para el agente"
        )
    return processed, image_path

# ================================
# V2.10.5 — CURRENT USER TURN AUTHORITY
# ================================
# Varios message-in posteriores al último message-out pueden pertenecer a turnos
# distintos. Una pausa larga separa intervenciones; el backlog viejo queda fuera
# del mensaje operativo que entra a Perception/Goals/Planner.
CURRENT_USER_TURN_MAX_GAP_MINUTES = max(
    1,
    int(os.getenv("CURRENT_USER_TURN_MAX_GAP_MINUTES", "15")),
)
_LAST_READ_USER_MESSAGE_META: List[Dict[str, Any]] = []


def _whatsapp_minute_from_timestamp_text(raw_text: str) -> Optional[int]:
    """Extrae HH:MM desde data-pre-plain-text o desde la línea final visible."""
    raw = str(raw_text or "").strip()
    match = re.search(r"\[(\d{1,2}):(\d{2})(?:,|\])", raw)
    if not match:
        match = re.search(r"(?:^|\n)(\d{1,2}):(\d{2})\s*$", raw)
    if not match:
        return None
    try:
        hour = int(match.group(1))
        minute = int(match.group(2))
    except Exception:
        return None
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        return None
    return hour * 60 + minute


def _resolve_current_user_turn(
    user_messages: List[str],
    metadata: Optional[List[Dict[str, Any]]] = None,
) -> Tuple[List[str], List[str]]:
    """
    Resuelve el backlog sin responder en una única intervención actual.

    Mensajes separados por <= CURRENT_USER_TURN_MAX_GAP_MINUTES siguen juntos para
    soportar multipartes. Una pausa mayor crea un boundary y todo lo anterior deja
    de tener autoridad operativa. Sin timestamps confiables no corta el lote.
    """
    messages = [str(x or "").strip() for x in (user_messages or []) if str(x or "").strip()]
    if len(messages) <= 1:
        return messages, []

    meta = list(metadata or [])
    if len(meta) != len(messages):
        return messages, []
    if any(str(meta[i].get("texto") or "").strip() != messages[i] for i in range(len(messages))):
        return messages, []

    # WhatsApp puede mantener dos representaciones DOM de la misma burbuja durante
    # una actualización. Si texto y timestamp coinciden, es una sola intervención,
    # no dos mensajes distintos con autoridad duplicada.
    deduped_messages = []
    deduped_meta = []
    for message, item in zip(messages, meta):
        minute = item.get("minute_of_day")
        is_render_duplicate = bool(
            deduped_messages
            and minute is not None
            and deduped_meta[-1].get("minute_of_day") == minute
            and normalizar_texto_ia(deduped_messages[-1])
                == normalizar_texto_ia(message)
        )
        if is_render_duplicate:
            print(
                "   🧹 [CURRENT TURN DEDUPE] burbuja DOM duplicada descartada: "
                f"'{message[:100]}'"
            )
            continue
        deduped_messages.append(message)
        deduped_meta.append(item)

    messages = deduped_messages
    meta = deduped_meta
    if len(messages) <= 1:
        return messages, []

    boundary = 0
    reliable = False
    for idx in range(len(messages) - 1, 0, -1):
        prev_minute = meta[idx - 1].get("minute_of_day")
        curr_minute = meta[idx].get("minute_of_day")
        if prev_minute is None or curr_minute is None:
            continue
        reliable = True
        gap = (int(curr_minute) - int(prev_minute)) % (24 * 60)
        if gap > CURRENT_USER_TURN_MAX_GAP_MINUTES:
            boundary = idx
            break

    if not reliable or boundary <= 0:
        return messages, []

    superseded = messages[:boundary]
    current = messages[boundary:]
    print(
        f"   🧭 [CURRENT TURN RESOLVER] backlog={len(messages)} current={len(current)} "
        f"superseded={len(superseded)} gap_limit={CURRENT_USER_TURN_MAX_GAP_MINUTES}m"
    )
    for old in superseded[-3:]:
        print(
            "   ⏭️ [CURRENT TURN AUTHORITY] mensaje anterior no ejecutable en este turno: "
            f"'{old[:100]}'"
        )
    print(f"   🎯 [CURRENT TURN] '{current[-1][:140]}'")
    return current, superseded


# ================================
# FUNCIÓN: LEER MENSAJES DEL USUARIO
# ================================
async def read_user_messages(page):
    """
    Lee SOLO los mensajes del usuario que NO tienen respuesta nuestra después.
    Conserva metadata temporal mínima para resolver el CURRENT USER TURN.
    """
    global _LAST_READ_USER_MESSAGE_META
    _LAST_READ_USER_MESSAGE_META = []
    print("📥 [Lectura] Leyendo mensajes sin respuesta...")

    try:
        await wait_until_finished_typing(page, max_wait_time=60, check_interval=0.5)
        await asyncio.sleep(1.5)

        bubble_selector = await get_best_bubble_selector(page, "all")
        all_bubbles = page.locator(bubble_selector)
        total = await all_bubbles.count()

        if total == 0:
            bubble_selector = await get_best_bubble_selector(page, "all", force_refresh=True)
            all_bubbles = page.locator(bubble_selector)
            total = await all_bubbles.count()
        if total == 0:
            return []

        async def collect_records(bubbles, count):
            records = []
            for i in range(count):
                bubble = bubbles.nth(i)
                try:
                    classes = await bubble.get_attribute("class") or ""
                    es_usuario = _bubble_is_user_from_classes(classes)
                    es_nuestro = _bubble_is_ours_from_classes(classes)
                    # Ante una clasificación ambigua privilegiamos no perder
                    # una entrada del cliente, especialmente un comprobante.
                    if es_usuario and es_nuestro:
                        print(f"   ⚠️ [Lectura] Burbuja #{i} ambigua (in+out) → usuario")
                        es_nuestro = False
                    if not (es_usuario or es_nuestro):
                        continue
                    try:
                        raw = await bubble.inner_text()
                    except Exception:
                        raw = ""
                    raw = str(raw or "")

                    # WhatsApp suele exponer el timestamp real en data-pre-plain-text.
                    # Es preferible a confundir una hora escrita por el usuario con
                    # el reloj de la burbuja.
                    pre_plain = await bubble.get_attribute("data-pre-plain-text") or ""
                    if not pre_plain:
                        stamped = bubble.locator("[data-pre-plain-text]")
                        if await stamped.count() > 0:
                            pre_plain = await stamped.last.get_attribute("data-pre-plain-text") or ""
                    minute_of_day = (
                        _whatsapp_minute_from_timestamp_text(pre_plain)
                        or _whatsapp_minute_from_timestamp_text(raw)
                    )
                    # La media se detecta ANTES de descartar una burbuja sin
                    # texto: fotos reenviadas pueden no tener caption ni texto.
                    media_type = "ninguno"
                    if es_usuario:
                        try:
                            media_type = await _detectar_tipo_media_bubble(bubble)
                        except Exception as exc:
                            print(f"   ⚠️ [Lectura MEDIA] burbuja #{i}: {exc}")
                    texto_clean = re.sub(r'\n?\d{1,2}:\d{2}\s*$', '', raw.strip()).strip()
                    if es_usuario and media_type == "imagen":
                        texto_clean = "[IMAGEN_ENVIADA]"
                    elif es_usuario and media_type == "audio" and not texto_clean:
                        texto_clean = "[AUDIO_ENVIADO]"
                    if not texto_clean and media_type not in {"imagen", "audio"}:
                        continue
                    message_id = ""
                    for attr in ("data-id", "data-message-id", "id"):
                        try:
                            message_id = str(await bubble.get_attribute(attr) or "").strip()
                            if message_id:
                                break
                        except Exception:
                            pass
                    if not message_id:
                        try:
                            holders = bubble.locator("[data-id]")
                            if await holders.count() > 0:
                                message_id = str(await holders.first.get_attribute("data-id") or "").strip()
                        except Exception:
                            pass
                    records.append({
                        "posicion": i,
                        "es_usuario": es_usuario,
                        "es_nuestro": es_nuestro,
                        "texto": texto_clean,
                        "raw_text": raw,
                        "minute_of_day": minute_of_day,
                        "pre_plain_text": str(pre_plain or ""),
                        "media_type": media_type,
                        "message_id": message_id,
                    })
                except Exception:
                    continue
            return records

        mensajes = await collect_records(all_bubbles, total)
        if not mensajes and total > 0:
            print("   ⚠️ [Lectura] Hay elementos, pero ninguno clasificable. Forzando auto-adaptación IA...")
            bubble_selector = await get_best_bubble_selector(page, "all", force_refresh=True)
            all_bubbles = page.locator(bubble_selector)
            total = await all_bubbles.count()
            mensajes = await collect_records(all_bubbles, total)

        ultima_posicion_nuestra = -1
        for i, msg in enumerate(mensajes):
            if msg["es_nuestro"]:
                ultima_posicion_nuestra = i

        meta = [
            {
                "texto": msg["texto"],
                "raw_text": msg.get("raw_text") or "",
                "posicion": msg.get("posicion"),
                "minute_of_day": msg.get("minute_of_day"),
                "pre_plain_text": msg.get("pre_plain_text") or "",
                "media_type": msg.get("media_type") or "ninguno",
                "message_id": msg.get("message_id") or "",
            }
            for i, msg in enumerate(mensajes)
            if i > ultima_posicion_nuestra and msg["es_usuario"]
        ]
        _LAST_READ_USER_MESSAGE_META = meta
        unanswered = [msg["texto"] for msg in meta]

        print(f"📨 [Lectura] {len(unanswered)} mensajes del usuario sin respuesta")
        for i, texto in enumerate(unanswered):
            print(f"   [{i+1}] {texto[:80]}")
        return unanswered

    except Exception as e:
        _LAST_READ_USER_MESSAGE_META = []
        print(f"⚠️ [Lectura] Error: {e}")
        return []

# ================================
# FUNCIÓN: VERIFICAR SI HAY MENSAJES DEL USUARIO SIN RESPONDER (CORREGIDA)
# ================================
async def has_unread_user_messages(page):
    """
    Verifica si hay mensajes del usuario sin respuesta.
    IMPORTANTE: Solo retorna True si hay algún mensaje del usuario
    que NO tenga un mensaje NUESTRO después.
    """
    try:
        await asyncio.sleep(1.5)

        bubble_selector = await get_best_bubble_selector(page, "all")
        all_bubbles = page.locator(bubble_selector)
        total = await all_bubbles.count()

        if total == 0:
            bubble_selector = await get_best_bubble_selector(page, "all", force_refresh=True)
            all_bubbles = page.locator(bubble_selector)
            total = await all_bubbles.count()

        if total == 0:
            print("⏭️ No hay mensajes en este chat")
            return False

        # Recolectar todos los mensajes con su posición y tipo
        mensajes = []
        for i in range(total):
            bubble = all_bubbles.nth(i)
            try:
                classes = await bubble.get_attribute("class") or ""
                es_usuario = _bubble_is_user_from_classes(classes)
                es_nuestro = _bubble_is_ours_from_classes(classes)

                if es_usuario and es_nuestro:
                    # Burbuja ambigua: la clase detectada matchea ambos sets
                    # (in y out) a la vez, lo cual es imposible en una burbuja real.
                    # Ante la duda, la tratamos como mensaje de usuario SIN responder:
                    # es más seguro responder de más que quedarse mudo con un cliente.
                    print(f"   ⚠️ [Clasificación] Burbuja #{i} ambigua (in+out simultáneo) → tratando como usuario sin responder")
                    es_usuario = True
                    es_nuestro = False

                if es_usuario or es_nuestro:
                    texto = (await bubble.inner_text()).strip()
                    mensajes.append({
                        "posicion": i,
                        "es_usuario": es_usuario,
                        "es_nuestro": es_nuestro,
                        "texto": texto
                    })
            except:
                continue

        if not mensajes:
            print("   ⚠️ [Verificación] Hay elementos, pero ninguno clasificable. Forzando auto-adaptación IA...")
            bubble_selector = await get_best_bubble_selector(page, "all", force_refresh=True)
            all_bubbles = page.locator(bubble_selector)
            total = await all_bubbles.count()
            for i in range(total):
                bubble = all_bubbles.nth(i)
                try:
                    classes = await bubble.get_attribute("class") or ""
                    es_usuario = _bubble_is_user_from_classes(classes)
                    es_nuestro = _bubble_is_ours_from_classes(classes)

                    if es_usuario and es_nuestro:
                        print(f"   ⚠️ [Clasificación] Burbuja #{i} ambigua (in+out simultáneo) → tratando como usuario sin responder")
                        es_usuario = True
                        es_nuestro = False

                    if es_usuario or es_nuestro:
                        texto = (await bubble.inner_text()).strip()
                        mensajes.append({
                            "posicion": i,
                            "es_usuario": es_usuario,
                            "es_nuestro": es_nuestro,
                            "texto": texto
                        })
                except:
                    continue

        if not mensajes:
            return False

        # Si hay un mensaje nuestro en el medio, lo anterior ya fue respondido.
        # Solo importa el bloque de mensajes del usuario posterior al último mensaje nuestro.
        ultima_posicion_nuestra = -1
        for i, msg in enumerate(mensajes):
            if msg["es_nuestro"]:
                ultima_posicion_nuestra = i
        mensajes_sin_responder = [
            msg for i, msg in enumerate(mensajes)
            if i > ultima_posicion_nuestra and msg["es_usuario"]
        ]

        if mensajes_sin_responder:
            print(f"📨 [INBOX] {len(mensajes_sin_responder)} mensaje(s) del usuario pendientes antes de responder:")
            for idx, msg in enumerate(mensajes_sin_responder, 1):
                texto_log = re.sub(r"\s+", " ", str(msg.get("texto") or "")).strip()
                print(
                    f"   [{idx}] ✅ SIN RESPUESTA: '{texto_log[:160]}' "
                    f"(posición {msg['posicion']})"
                )
            return True

        print("⏭️ Todos los mensajes del usuario ya tienen respuesta nuestra")
        return False

    except Exception as e:
        print(f"⚠️ [Verificación] Error: {e}")
        return False

def reparar_respuesta_con_ia(result: Dict, prompt_original: str, motivo: str) -> Dict:
    respuesta_original = str(result.get("respuesta") or "")
    if not respuesta_original:
        return result

    try:
        repair_prompt = f"""
Tenés que reparar una respuesta de un asistente de WhatsApp para reservas de canchas.

CONTEXTO ORIGINAL USADO POR EL AGENTE:
{prompt_original}

RESPUESTA GENERADA QUE TIENE UNA CONTRADICCIÓN:
"{respuesta_original}"

MOTIVO DE LA REPARACIÓN:
{motivo}

TAREA:
- Reescribí SOLO la respuesta a enviar.
- Mantené el tono natural, argentino, conversacional y breve.
- Respondé el mensaje actual del usuario.
- No uses una plantilla fija.
- No contradigas la memoria ni las restricciones del contexto.

Respondé SOLO JSON válido:
{{
  "respuesta": "texto reparado",
  "razon_reparacion": "1 línea"
}}
"""
        resp = client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un reparador de respuestas de un agente IA. "
                        "No decidís el flujo de reservas: solo corregís contradicciones con la memoria y el contexto."
                    )
                },
                {"role": "user", "content": repair_prompt}
            ],
            temperature=0.5,
            max_tokens=220,
            response_format={"type": "json_object"}
        )
        register_cost(resp)

        raw = resp.choices[0].message.content.strip()
        repaired = json.loads(raw)
        respuesta_reparada = str(repaired.get("respuesta") or "").strip()
        if respuesta_reparada:
            result["respuesta"] = respuesta_reparada
            result["razon"] = f"{result.get('razon', '')} | Reparación IA: {repaired.get('razon_reparacion', motivo)}".strip(" |")
        return result
    except Exception as e:
        print(f"⚠️ [Reparación IA] Error: {e}")
        result["respuesta"] = "Perdón, me expresé mal. ¿Me aclarás qué necesitás puntualmente y te respondo bien?"
        result["razon"] = f"{result.get('razon', '')} | Reparación IA falló: {e}".strip(" |")
        return result

def actualizar_cliente_si_corresponde(telefono: str, conv_state: Dict, prospecto: Dict) -> Dict:
    """
    Detecta si el usuario dijo ser cliente (por keyword o IA) y actualiza estado.
    """
    if not telefono:
        return prospecto

    historial = conv_state.get("historial", [])
    ultimo_mensaje_usuario = ""
    for msg in reversed(historial):
        if msg.get("role") == "user":
            ultimo_mensaje_usuario = msg.get("content", "")
            break

    if not ultimo_mensaje_usuario:
        return prospecto

    hechos = conv_state.setdefault("hechos", {})
    es_cliente = bool(
        prospecto_es_cliente(prospecto)
        or hechos.get("cliente_estado") == "cliente_existente"
    )

    nombre = prospecto.get("nombre", "No especificado")
    if telefono.startswith("NOMBRE:"):
        nombre = telefono.replace("NOMBRE:", "")

    estado_csv = "Cliente existente" if es_cliente else "Contacto agendado - pendiente"
    agregar_o_actualizar_contacto_en_csv(telefono, nombre, es_cliente, estado_csv)

    if es_cliente:
        prospecto["es_cliente"] = CLIENTE_SI
        prospecto["estado_actual"] = "Cliente existente"
    else:
        if telefono.startswith("NOMBRE:") and prospecto.get("es_cliente", CLIENTE_NO) != CLIENTE_SI:
            prospecto["es_cliente"] = CLIENTE_NO
            prospecto["estado_actual"] = "Contacto agendado"

    if es_cliente:
        hechos["cliente_estado"] = "cliente_existente"
        hechos["cliente_estado_origen"] = ultimo_mensaje_usuario
        hechos.setdefault("cliente_detectado_por", "fuente_durable")
        print(f"   ✅ [MEMORIA] Cliente marcado en memoria: {telefono}")
    else:
        print(f"   📇 [MEMORIA] Contacto agendado registrado: {telefono}")

    return prospecto


# ================================
# FUNCIÓN: OBTENER HORARIOS DISPONIBLES POR CANCHA
# ================================
def obtener_horarios_disponibles_para_dia(
    dia: str,
    resource_types: Any = None,
    cancha_opcional: str = None,
) -> Dict[str, List[str]]:
    """
    Consulta el calendario real para obtener los horarios disponibles para un día.
    Retorna un diccionario {cancha: [horarios_disponibles]}
    Usa CALL_TIME_WINDOWS desde config para determinar la franja horaria.
    """
    try:
        from cancheria.config.legacy_config import COURTS, TURN_DURATION_MINUTES, obtener_franjas_atencion_minutos, _minutos_a_hora

        duracion_turno = TURN_DURATION_MINUTES

        # Resolver canchas candidatas. Sin type explícito se mantienen TODAS.
        canchas = _court_names_compatible_with_resource_types(
            resource_types, cancha_opcional
        )

        # Inicializar resultado
        horarios_por_cancha = {cancha: [] for cancha in canchas}

        # Resolver fecha una sola vez
        dia_resuelto = resolver_fecha(dia)
        if not validar_fecha_en_dias_atencion(dia_resuelto):
            print(f"   [Calendario] {dia_resuelto} fuera de dias de atencion ({descripcion_atencion_mensaje()})")
            return {}

        # Obtener la franja horaria desde config
        franjas = obtener_franjas_atencion_minutos()

        if not franjas:
            print(f"   ⚠️ [Calendario] No hay franjas horarias configuradas en CALL_TIME_WINDOWS")
            return {}

        # Tomar el inicio más temprano y el fin más tarde de todas las franjas
        inicio_minutos = min(inicio for inicio, _ in franjas)
        fin_minutos = max(fin for _, fin in franjas)

        print(
            "   📅 [Calendario] Franja horaria: "
            f"{_agent_v2_midnight_display(_minutos_a_hora(inicio_minutos))} a "
            f"{_agent_v2_midnight_display(_minutos_a_hora(fin_minutos))}"
        )
        print(f"   📅 [Calendario] Consultando disponibilidad para {dia_resuelto} en {len(canchas)} canchas")

        # Generar todos los horarios posibles dentro de la franja
        hora_actual = inicio_minutos

        while hora_actual + duracion_turno <= fin_minutos:
            hora_str = f"{hora_actual // 60:02d}:{hora_actual % 60:02d}"

            for cancha in canchas:
                # Verificar si el slot está libre en el calendario para esta cancha
                if calendario.slot_esta_libre_en_cancha(dia_resuelto, hora_str, cancha):
                    horarios_por_cancha[cancha].append(hora_str)
                    print(f"      ✅ {cancha} - {hora_str} disponible")
                else:
                    print(f"      ❌ {cancha} - {hora_str} ocupado")

            hora_actual += duracion_turno

        # Filtrar canchas vacías para logging
        for cancha, horarios in horarios_por_cancha.items():
            if horarios:
                print(f"   📋 {cancha}: {len(horarios)} horarios disponibles")
            else:
                print(f"   ⚠️ {cancha}: sin horarios disponibles")

        return horarios_por_cancha

    except Exception as e:
        print(f"⚠️ [Calendario] Error obteniendo horarios para {dia}: {e}")
        import traceback
        traceback.print_exc()
        return {}


def obtener_resumen_horarios_disponibles(dia: str, incluir_cta: bool = True) -> str:
    """
    Genera un resumen legible de horarios disponibles por cancha.
    incluir_cta=False se usa cuando la disponibilidad forma parte de una respuesta
    multi-intent y todavía faltan otras preguntas por responder.
    """
    horarios_por_cancha = obtener_horarios_disponibles_para_dia(dia)

    if not horarios_por_cancha:
        base = (
            f"Para {dia} no encontré horarios disponibles dentro de nuestra franja "
            f"({descripcion_franjas_atencion_mensaje()})."
        )
        return f"{base} ¿Querés que busque el horario más cercano?" if incluir_cta else base

    # Filtrar canchas con horarios disponibles
    canchas_con_horarios = {c: h for c, h in horarios_por_cancha.items() if h}

    if not canchas_con_horarios:
        base = (
            f"Para {dia} no encontré horarios disponibles en ninguna cancha dentro de nuestra franja "
            f"({descripcion_franjas_atencion_mensaje()})."
        )
        return f"{base} ¿Querés que busque el horario más cercano?" if incluir_cta else base

    # Construir mensaje
    partes = []
    for cancha, horarios in canchas_con_horarios.items():
        if horarios:
            horarios_formateados = [formatear_hora_para_mensaje(h) for h in sorted(horarios)]
            horarios_str = ", ".join(horarios_formateados)
            partes.append(f"⚽ {cancha}: {horarios_str}")
    if CON_QUINCHO and QUINCHOS:
        dia_resuelto = resolver_fecha(dia or "hoy")
        slots_referencia = []
        for inicio, fin in obtener_franjas_atencion_minutos():
            actual = inicio
            paso_minutos = int(TURN_DURATION_MINUTES or 60)
            while actual is not None and fin is not None and actual + paso_minutos <= fin:
                slots_referencia.append(_minutos_a_hora(actual))
                actual += paso_minutos
        for quincho in QUINCHOS:
            q_name = quincho.get("name") or ""
            libres_q = [
                hora_slot for hora_slot in slots_referencia
                if quincho_libre_para_bloque(dia_resuelto, hora_slot, 1.0, q_name)
            ]
            if libres_q:
                horarios_str = ", ".join(formatear_hora_para_mensaje(h) for h in sorted(libres_q))
                partes.append(f"🔥 {q_name}: {horarios_str}")

    if len(partes) == 1:
        base = f"Para {dia} tengo disponible en {partes[0]}."
        return f"{base} ¿A qué hora querés?" if incluir_cta else base
    else:
        base = f"Para {dia} tengo disponible:\n" + "\n".join(partes)
        return f"{base}\n\n¿En qué cancha y a qué hora querés reservar?" if incluir_cta else base

def _bubble_is_user_from_classes(classes: str) -> bool:
    """
    👤 Detecta si una burbuja es del usuario (recibida).
    """
    if not classes:
        return False

    class_tokens = set(str(classes or "").split())

    # Clases que indican mensaje del usuario
    user_indicators = {
        "message-in",
        "x1cy8zhl",
        "x1n2onr6",
        "x1hl2kvy",
    }

    # Clases que indican mensaje nuestro (para excluir)
    ours_indicators = {
        "message-out",
        "xuk3077",
    }

    # Si tiene indicador de mensaje nuestro, NO es usuario
    if class_tokens & ours_indicators:
        return False

    # Si tiene indicador de mensaje usuario, ES usuario
    if class_tokens & user_indicators:
        return True

    # Fallback: si tiene "message" y no "out" → probablemente usuario
    if "message" in classes and "out" not in classes:
        return True

    return False


async def _last_user_bubble_locator(page):
    """
    🎯 Obtiene el locator de la última burbuja del usuario en el chat actual.
    Usa selectores dinámicos y fallbacks para máxima compatibilidad.
    """
    try:
        # ESTRATEGIA 1: Usar el sistema de selectores adaptativos
        selector = await get_best_bubble_selector(page, "user", force_refresh=False)
        bubbles = page.locator(selector)
        total = await bubbles.count()

        if total > 0:
            # Verificar que el último elemento sea realmente del usuario
            last_bubble = bubbles.nth(total - 1)
            try:
                classes = await last_bubble.get_attribute("class") or ""
                if _bubble_is_user_from_classes(classes):
                    return last_bubble
            except Exception:
                pass

            # Si el último no es del usuario, buscar hacia atrás
            for i in range(min(total - 2, 4), -1, -1):
                try:
                    bubble = bubbles.nth(i)
                    classes = await bubble.get_attribute("class") or ""
                    if _bubble_is_user_from_classes(classes):
                        return bubble
                except Exception:
                    continue

        # ESTRATEGIA 2: Forzar refresh y reintentar
        selector = await get_best_bubble_selector(page, "user", force_refresh=True)
        bubbles = page.locator(selector)
        total = await bubbles.count()

        if total > 0:
            for i in range(min(total - 1, 5), -1, -1):
                try:
                    bubble = bubbles.nth(i)
                    classes = await bubble.get_attribute("class") or ""
                    if _bubble_is_user_from_classes(classes):
                        return bubble
                except Exception:
                    continue

        # ESTRATEGIA 3: Usar XPath con clases conocidas
        wa_message_in_classes = sorted(RUNTIME_MESSAGE_IN_CLASSES)
        if wa_message_in_classes:
            xpath_parts = []
            for cls in wa_message_in_classes:
                if cls in {"message-in"}:
                    xpath_parts.append(f"contains(@class, '{cls}')")
                else:
                    xpath_parts.append(f"contains(concat(' ', normalize-space(@class), ' '), ' {cls} ')")

            if xpath_parts:
                xpath_conditions = " or ".join(xpath_parts)
                xpath = f"(//div[({xpath_conditions})])[last()]"
                try:
                    last_bubble = page.locator(f"xpath={xpath}")
                    if await last_bubble.count() > 0:
                        return last_bubble
                except Exception:
                    pass

        # ESTRATEGIA 4: Fallback - usar selectores CSS
        fallback_selectors = [
            f"div.focusable-list-item.{WA_MESSAGE_IN_CLASS}",
            "div.message-in",
            "div.focusable-list-item.x1cy8zhl",
            "div[class*='message-in']",
            "div[class*='x1cy8zhl']",
        ]

        for selector in fallback_selectors:
            try:
                bubbles = page.locator(selector)
                total = await bubbles.count()
                if total > 0:
                    for i in range(min(total - 1, 5), -1, -1):
                        try:
                            bubble = bubbles.nth(i)
                            if await bubble.is_visible():
                                classes = await bubble.get_attribute("class") or ""
                                if _bubble_is_user_from_classes(classes):
                                    return bubble
                        except Exception:
                            continue
            except Exception:
                continue

        # ESTRATEGIA 5: Último recurso - buscar por clase genérica
        try:
            all_messages = page.locator("div[class*='message']")
            total = await all_messages.count()
            if total > 0:
                for i in range(min(total - 1, 10), -1, -1):
                    try:
                        bubble = all_messages.nth(i)
                        classes = await bubble.get_attribute("class") or ""
                        if _bubble_is_user_from_classes(classes):
                            return bubble
                    except Exception:
                        continue
        except Exception:
            pass

        # Si nada funciona, devolver un locator vacío
        return page.locator("xpath=(//div[contains(@class,'message-in')])[last()]")

    except Exception as e:
        print(f"⚠️ [_last_user_bubble_locator] Error: {e}")
        return page.locator("xpath=(//div[contains(@class,'message-in')])[last()]")



def _bubble_is_ours_from_classes(classes: str) -> bool:
    """
    🤖 Detecta si una burbuja es NUESTRA (enviada por el bot).
    """
    if not classes:
        return False

    class_tokens = set(str(classes or "").split())

    # Clases que indican mensaje nuestro
    ours_indicators = {
        "message-out",
        "xuk3077",
        "x1n2onr6",
    }

    # Clases que indican mensaje usuario (para excluir)
    user_indicators = {
        "message-in",
        "x1cy8zhl",
    }

    # Si tiene indicador de mensaje usuario, NO es nuestro
    if class_tokens & user_indicators:
        return False

    # Si tiene indicador de mensaje nuestro, ES nuestro
    if class_tokens & ours_indicators:
        return True

    # Fallback: si tiene "message" y "out" → probablemente nuestro
    if "message" in classes and "out" in classes:
        return True

    return False


# ================================
# FUNCIÓN: DETECTAR SI EL USUARIO PIDE HABLAR CON HUMANO
# ================================
def detectar_pedido_humano(mensaje: str) -> bool:
    """Detecta si el usuario pide hablar con un humano o con el encargado."""
    if not mensaje:
        return False

    texto = _texto_simple_para_detector(mensaje)

    patrones_humano = [
        r"quiero hablar con (un humano|una persona|el encargado|el dueno|alguien)",
        r"hablar con (un humano|una persona|el encargado|el dueno|alguien)",
        r"poneme con (el encargado|el dueno|alguien|un humano)",
        r"pasame con (el encargado|el dueno|alguien|un humano)",
        r"pasame (al|a la|con el|con la)?\s*(encargado|encargada|dueno|duena|responsable|administrador|admin)\b",
        r"necesito hablar con (un humano|una persona|el encargado)",
        r"no quiero hablar con (un bot|una maquina|un robot)",
        r"quiero que me atienda (una persona|el encargado|un humano)",
        r"hablar con el responsable",
        r"hablar con el administrador",
        r"atendeme vos",
        r"hablame vos",
        r"sos un bot\?",
        r"es usted un bot\?",
    ]

    for patron in patrones_humano:
        if re.search(patron, texto):
            print(f"   🧑 [Humano detectado] Patrón '{patron}' match en: {mensaje[:50]}")
            return True

    return False


