# ================================
def build_human_derivation_response() -> str:
    """Genera la respuesta para derivar al humano."""
    return (
        f"Dale, le aviso al {HUMAN_CONTACT_NAME} que necesitas hablar con el.\n\n"
        f"Apenas pueda te va a responder! En caso de ser urgente, te dejo su WhatsApp: {HUMAN_WHATSAPP} {HUMAN_CONTACT_NAME}.\n\n"
        f"Para reservas, utilizar este mismo chat."
    )


async def detectar_pedido_humano_ia(mensaje: str, conv_state: Dict = None) -> Dict[str, Any]:
    """Detecta con IA si el usuario pide hablar con un humano o encargado."""
    if not mensaje or len(str(mensaje).strip()) < 2:
        return {"es_pedido_humano": False, "confianza": 0.0, "razon": "mensaje vacio"}

    historial = []
    for msg in (conv_state or {}).get("historial", [])[-6:]:
        role = "user" if msg.get("role") == "user" else "assistant"
        historial.append({"role": role, "content": str(msg.get("content") or "")})

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un clasificador para un agente de reservas por WhatsApp.\n"
                        "Detecta si el usuario quiere hablar con una persona real, encargado, dueño, responsable, administrador, "
                        "o si rechaza seguir hablando con un bot.\n"
                        "No clasifiques como pedido humano si solo pregunta horarios, precios, disponibilidad, direccion o reserva.\n"
                        "No clasifiques como pedido humano si el usuario corrige un día/fecha/hora o se queja con insultos, "
                        "salvo que pida explícitamente hablar con una persona, encargado o humano.\n"
                        "Ejemplo NO humano: 'Pero es viernes pasado mañana perro'.\n"
                        "Ejemplo NO humano: 'Para pasado mañana tenes? sino cerra nomas tu cancha'.\n"
                        "Ejemplo SÍ humano: 'pasame con el encargado' o 'quiero hablar con una persona'.\n"
                        "Responde SOLO JSON valido: "
                        "{\"es_pedido_humano\":true|false,\"confianza\":0.0,\"razon\":\"breve\"}"
                    )
                },
                *historial,
                {"role": "user", "content": str(mensaje)}
            ],
            temperature=0.0,
            max_tokens=160,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        data["es_pedido_humano"] = bool(data.get("es_pedido_humano"))
        data["confianza"] = float(data.get("confianza", 0.0) or 0.0)
        print(f"   [Humano IA] {data.get('es_pedido_humano')} (conf: {data.get('confianza')}) - {data.get('razon', '')[:80]}")
        return data
    except Exception as e:
        print(f"   [Humano IA] Error: {e}")
        return {"es_pedido_humano": False, "confianza": 0.0, "razon": f"error: {e}"}


async def validar_derivacion_humano_con_ia(
    mensaje_original: str,
    fragmento: str = "",
    conv_state: Dict = None,
    primera_decision: str = "",
    respuesta_ya_generada: str = "",
) -> Dict[str, Any]:
    """Segunda lectura IA: decide si corresponde derivar o seguir resolviendo la reserva."""
    conv_state = conv_state or {}
    historial = []
    for msg in conv_state.get("historial", [])[-8:]:
        role = "user" if msg.get("role") == "user" else "assistant"
        historial.append({"role": role, "content": str(msg.get("content") or "")})

    contexto = (
        f"Fase actual: {conv_state.get('fase', 'inicial')}\n"
        f"Día propuesto: {conv_state.get('dia_propuesto') or 'ninguno'}\n"
        f"Hora propuesta: {conv_state.get('hora_propuesta') or 'ninguna'}\n"
        f"Cancha propuesta: {conv_state.get('cancha_propuesta') or 'ninguna'}\n"
        f"Respuesta útil ya generada por otra intención: {respuesta_ya_generada or 'ninguna'}\n"
        f"Primera decisión IA que se está auditando: {primera_decision or 'derivar_humano'}"
    )

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos una segunda IA auditora para un agente de reservas de canchas por WhatsApp.\n"
                        "Tu tarea es revisar si una decisión previa de DERIVAR A HUMANO fue correcta.\n\n"
                        "Razoná por intención real, contexto y conversación, no por keywords sueltas.\n"
                        "Derivá solo si el usuario realmente pide hablar con una persona, encargado, dueño, responsable, "
                        "administrador, o rechaza seguir con el bot.\n"
                        "No derives si el usuario está enojado, insulta, ironiza o se queja, pero todavía está preguntando "
                        "por horarios, fechas, disponibilidad, precio, reserva, cancelación o reprogramación.\n"
                        "Si el mensaje tiene varias partes, separá mentalmente la parte operativa de la queja y decidí si "
                        "la parte operativa puede responderse sin humano.\n\n"
                        "Respondé SOLO JSON válido con este formato: "
                        "{\"derivar\":true|false,\"confianza\":0.0,\"razon\":\"breve\",\"accion_correcta\":\"seguir_reserva|derivar_humano|pedir_contexto\"}"
                    )
                },
                *historial,
                {
                    "role": "user",
                    "content": (
                        f"CONTEXTO:\n{contexto}\n\n"
                        f"MENSAJE COMPLETO DEL USUARIO:\n{mensaje_original or ''}\n\n"
                        f"FRAGMENTO QUE LA PRIMERA IA QUISO DERIVAR:\n{fragmento or mensaje_original or ''}"
                    )
                }
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        data["derivar"] = bool(data.get("derivar"))
        data["confianza"] = float(data.get("confianza", 0.0) or 0.0)
        print(
            f"   [Humano IA auditor] derivar={data.get('derivar')} "
            f"(conf: {data.get('confianza')}) - {str(data.get('razon', ''))[:90]}"
        )
        return data
    except Exception as e:
        print(f"   [Humano IA auditor] Error: {e}. Mantengo la decisión previa para no ocultar un posible pedido humano.")
        return {
            "derivar": True,
            "confianza": 0.5,
            "razon": f"error auditor: {e}",
            "accion_correcta": "derivar_humano",
        }


def mensaje_es_operativo_de_calendario(texto: str, conv_state: Dict = None) -> bool:
    conv_state = conv_state or {}
    texto_simple = _texto_simple_para_detector(texto)
    if resolver_fecha_admin_desde_mensaje(texto or ""):
        return True
    if extraer_horas_reales_de_texto(texto or ""):
        return True
    if hora_es_valida(conv_state.get("hora_propuesta")) and re.search(
        r"\b(tenes|tenes?|ten[eé]s|hay|libre|disponible|pasado|manana|mañana|viernes|lunes|martes|miercoles|jueves|sabado|domingo)\b",
        texto_simple,
    ):
        return True
    if re.search(r"\b(cancha|turno|reserva|horario|hora|quincho|parrilla)\b", texto_simple):
        return True
    return False


def _human_alert_case_actions(telefono: str, case_id: Any) -> str:
    if not case_id:
        return ""
    actions = f"\n\n✅ Para cerrar el caso y reanudar la IA: `resolver caso ID {case_id}`"
    if _human_pause_contact_key(telefono):
        actions += (
            "\n\n⏸️ *La IA queda en pausa para este contacto.*"
            f"\nPara reanudarla sin cerrar el caso: `continuar ID {case_id}`"
            + (f"\nO por teléfono: `continuar {telefono}`" if not str(telefono).startswith("NOMBRE:") else "")
        )
    return actions


def build_human_alert_message(
    mensaje_usuario: str,
    telefono: str = "",
    prospecto: Dict = None,
    reason: str = "",
    case_id: Any = "",
) -> str:
    nombre = ""
    if isinstance(prospecto, dict):
        nombre = str(prospecto.get("nombre") or "").strip()
    contacto = nombre or "Sin nombre"
    numero = telefono or "sin telefono detectado"
    automatic_safe_exit = str(reason or "").startswith("universal_safe_exit:")
    heading = (
        "❗ ALERTA: el agente necesita atención humana"
        if automatic_safe_exit
        else "❗ ALERTA: usuario quiere hablar con un humano"
    )
    diagnostic = (
        f"\n\n🛠️ Motivo interno: {str(reason or '').strip()[:700]}"
        if automatic_safe_exit and str(reason or "").strip()
        else ""
    )
    return _with_admin_alert_quick_commands((
        f"{heading}\n\n"
        + (f"🆔 *CASO ID {case_id}*\n\n" if case_id else "")
        +
        f"📩 Mensaje que disparo la alerta:\n{mensaje_usuario or '(sin mensaje)'}\n\n"
        f"👤 Usuario: {contacto}\n"
        f"📱 Telefono: {numero}\n\n"
        "💡 Acción: contactar al usuario y resolver personalmente el punto pendiente."
        + diagnostic
        + _human_alert_case_actions(telefono, case_id)
    ), telefono)


async def enviar_alerta_humano_admin(
    page,
    mensaje_usuario: str,
    telefono: str = "",
    prospecto: Dict = None,
    reason: str = "",
    case_id: Any = "",
) -> bool:
    try:
        if not case_id:
            caso = registrar_caso_humano(
                "humano",
                mensaje_usuario,
                telefono,
                prospecto,
                reason=reason,
                source="legacy_handoff",
            )
            case_id = caso.get("case_id")
        alerta = build_human_alert_message(
            mensaje_usuario,
            telefono,
            prospecto,
            reason=reason,
            case_id=case_id,
        )
        delivered = await _send_admin_alert_batch(
            page,
            alerta,
            category="human_handoff",
            respect_inbox=False,
        )
        registrar_metrica_operativa("alerta_humano_admin_enviada", {
            "case_id": case_id,
            "telefono": telefono or "unknown",
            "mensaje": str(mensaje_usuario or "")[:500],
            "reason": str(reason or "")[:500],
            "authorized": _authorized_alert_recipients(),
        })
        actualizar_estado_alerta_caso_humano(
            case_id,
            "sent" if delivered else "pending",
        )
        return delivered
    except Exception as e:
        print(f"[ALERTA HUMANO] No pude enviar alerta al admin: {e}")
        registrar_metrica_operativa("alerta_humano_admin_error", {
            "case_id": case_id,
            "telefono": telefono or "unknown",
            "reason": str(reason or "")[:500],
            "error": str(e),
        })
        actualizar_estado_alerta_caso_humano(case_id, "failed")
        return False


async def manejar_derivacion_humano(page, telefono: str, user_messages: List[str], ultimo_mensaje: str, prospecto: Dict = None) -> str:
    respuesta = build_human_derivation_response()
    await send_message(page, respuesta)
    add_to_history(telefono or "unknown", "assistant", respuesta)
    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
    update_conversation_state(telefono or "unknown", fase="derivado_humano")
    await enviar_alerta_humano_admin(page, ultimo_mensaje or " ".join(user_messages or []), telefono or "unknown", prospecto)
    return respuesta


def build_full_day_event_response(admin_notified: Optional[bool] = None) -> str:
    contact = (
        f"{HUMAN_CONTACT_NAME} se va a comunicar con vos para coordinarlo.\n\n"
        f"📱 Su WhatsApp es {HUMAN_WHATSAPP}."
    )
    if admin_notified is True:
        return f"Perfecto, este tipo de evento lo coordina directamente el encargado. {contact}\n\n✅ Ya le envié la alerta."
    if admin_notified is False:
        return (
            f"Perfecto, este tipo de evento lo coordina directamente el encargado. {contact}\n\n"
            "⚠️ No pude entregarle la alerta automática en este momento; podés escribirle directamente a ese número."
        )
    return (
        f"Perfecto, este tipo de evento lo coordina directamente el encargado. {contact}\n\n"
        "Registré tu pedido para coordinarlo."
    )


