async def _send_admin_alert_in_active_page(page, alert_chat_url: str, alerta: str) -> None:
    """Navega al encargado y envía la alerta usando siempre la pestaña activa."""
    if page is None or not hasattr(page, "goto"):
        raise RuntimeError("pestaña activa no disponible para alerta administrativa")

    await page.goto(alert_chat_url)
    await asyncio.sleep(3)
    sent = await send_message(page, alerta)
    if sent is not True:
        raise RuntimeError("WhatsApp no confirmó el envío de la alerta en la pestaña activa")
    print("   ✅ [ALERTA ADMIN] alerta enviada desde la misma pestaña")


async def enviar_alerta_evento_dia_completo_admin(
    page,
    mensaje_usuario: str,
    telefono: str = "",
    prospecto: Dict = None,
    case_id: Any = "",
    reason: str = "evento_especial",
) -> bool:
    try:
        if not case_id:
            caso = registrar_caso_humano(
                "evento_especial",
                mensaje_usuario,
                telefono,
                prospecto,
                reason=reason,
                source="legacy_event_handoff",
            )
            case_id = caso.get("case_id")
        alerta = build_full_day_event_alert_message(
            mensaje_usuario, telefono, prospecto, case_id=case_id
        )
        delivered = await _send_admin_alert_batch(
            page,
            alerta,
            category="special_event",
            respect_inbox=False,
        )
        registrar_metrica_operativa("alerta_evento_dia_completo_admin_enviada", {
            "case_id": case_id,
            "telefono": telefono or "unknown",
            "mensaje": str(mensaje_usuario or "")[:500],
            "authorized": _authorized_alert_recipients(),
        })
        actualizar_estado_alerta_caso_humano(
            case_id,
            "sent" if delivered else "pending",
        )
        return delivered
    except Exception as e:
        print(f"[ALERTA EVENTO DIA COMPLETO] No pude enviar alerta al admin: {e}")
        registrar_metrica_operativa("alerta_evento_dia_completo_admin_error", {
            "case_id": case_id,
            "telefono": telefono or "unknown",
            "error": str(e),
        })
        actualizar_estado_alerta_caso_humano(case_id, "failed")
        return False


