async def manejar_evento_dia_completo(page, telefono: str, user_messages: List[str], ultimo_mensaje: str, prospecto: Dict = None) -> str:
    respuesta = build_full_day_event_response()
    await send_message(page, respuesta)
    add_to_history(telefono or "unknown", "assistant", respuesta)
    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
    update_conversation_state(telefono or "unknown", fase="derivado_evento_dia_completo")
    await enviar_alerta_evento_dia_completo_admin(page, ultimo_mensaje or " ".join(user_messages or []), telefono or "unknown", prospecto)
    return respuesta


async def manejar_reserva_quincho(page, telefono: str, user_messages: List[str], ultimo_mensaje: str, prospecto: Dict = None) -> str:
    respuesta = build_full_day_event_response()
    await send_message(page, respuesta)
    add_to_history(telefono or "unknown", "assistant", respuesta)
    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
    update_conversation_state(telefono or "unknown", fase="derivado_quincho")
    await enviar_alerta_quincho_admin(page, ultimo_mensaje or " ".join(user_messages or []), telefono or "unknown", prospecto)
    return respuesta


async def validar_respuesta_con_ia(
    mensaje_usuario: str, 
    respuesta_generada: str, 
    conv_state: Dict,  # <--- Recibir estado completo
    prospecto: Dict = None
) -> Dict:
    """
    Valida si la respuesta generada es apropiada para el mensaje del usuario.
    Analiza el contexto completo: historial, fase, si es cliente, etc.
    """
    try:
        # Preparar contexto completo
        fase_actual = conv_state.get("fase", "inicial")
        historial = conv_state.get("historial", [])
        tiene_historial = len(historial) > 0
        es_primer_mensaje_agente = len([m for m in historial if m.get("role") == "assistant"]) == 0

        # Construir historial para el prompt
        historial_texto = ""
        for msg in historial[-6:]:  # Últimos 6 mensajes
            role = "Usuario" if msg["role"] == "user" else "Agente"
            historial_texto += f"{role}: {msg['content'][:150]}\n"

        contexto_completo = f"""
FASE ACTUAL: {fase_actual}
¿TIENE HISTORIAL?: {tiene_historial}
¿ES PRIMER MENSAJE DEL AGENTE?: {es_primer_mensaje_agente}
¿ES CLIENTE?: {prospecto.get('es_cliente', 'no') if prospecto else 'no'}

HISTORIAL RECIENTE:
{historial_texto if historial_texto else "(sin historial)"}

MENSAJE DEL USUARIO ACTUAL:
"{mensaje_usuario}"

RESPUESTA DEL AGENTE A EVALUAR:
"{respuesta_generada}"
"""

        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un validador de respuestas de un asistente de WhatsApp para reservas de canchas.\n\n"
                        "Tu tarea es evaluar si la respuesta del asistente es APROPIADA para el mensaje del usuario, "
                        "teniendo en cuenta TODO el contexto de la conversación.\n\n"
                        "CRITERIOS DE RESPUESTA VÁLIDA:\n\n"
                        "1. **PRIMER CONTACTO (sin historial previo)**:\n"
                        "   - El usuario saludó ('hola', 'buenas', etc.)\n"
                        "   - El asistente DEBE presentarse ANTES de pedir horario\n"
                        "   - Respuesta VÁLIDA: '🙋 ¡Hola! Soy [nombre] de [negocio] 🏟️. ¿Qué día y horario querés reservar?'\n"
                        "   - Respuesta INVÁLIDA: solo '¿Qué día y horario querés reservar?' sin presentación\n\n"
                        "2. **CONVERSACIÓN EXISTENTE (con historial)**:\n"
                        "   - Si el usuario saluda de vuelta, el asistente NO necesita volver a presentarse\n"
                        "   - Responde DIRECTAMENTE a lo que preguntó el usuario\n"
                        "   - Mantiene el hilo de la conversación\n\n"
                        "3. **RESPUESTA INVÁLIDA EN CUALQUIER CASO**:\n"
                        "   - Ignora completamente la pregunta del usuario\n"
                        "   - Es incoherente con el contexto\n"
                        "   - Promete hacer algo sin concretar (ej: 'voy a chequear')\n"
                        "   - Responde con algo que NO tiene relación con reservar canchas\n\n"
                        "   - Dice que no hay disponibilidad sin mostrar una alternativa o sin respetar una hora/día ya detectados en memoria.\n"
                        "   - Contradice datos de memoria del turno propuesto (día, hora o cancha) sin que el usuario los haya cambiado.\n\n"
                        "4. **SEÑA OBLIGATORIA (CRÍTICO)**:\n"
                        f"   - Requiere seña: {REQUIRES_DEPOSIT}. Modalidad: {_descripcion_senia_runtime()}. Alias: {PAYMENT_ALIAS}.\n"
                        "   - Si se requiere seña y el usuario todavía NO envió comprobante válido, la respuesta NO puede decir "
                        "'reserva confirmada', 'está confirmada', 'queda firme' ni similares.\n"
                        "   - En ese caso debe pedir comprobante de seña y mostrar el detalle del turno/precio si ya tiene los datos.\n"
                        "   - Solo es válido decir que queda firme después de validar comprobante o si la seña ya figura pagada.\n\n"
                        "5. **IDENTIDAD DEL AGENTE (CRÍTICO)**:\n"
                        "   - El agente es un BOT de reservas de un predio de canchas. NO es una persona, "
                        "NO juega al fútbol y NO participa de los partidos.\n"
                        "   - Si el mensaje del usuario incluye una pregunta social/personal dirigida a un "
                        "humano (ej: '¿te vas a jugar?', '¿vas a venir?', '¿jugás vos?'), el agente NO debe "
                        "responderla en primera persona como si fuera a jugar o participar.\n"
                        "   - Una respuesta que dice cosas como 'sí, voy a jugar' es INVÁLIDA por inventar "
                        "una participación personal falsa, sin importar si el resto es correcto.\n"
                        "   - Si esa pregunta social no tiene relación con reservar, el agente debe IGNORARLA "
                        "y responder solo la parte operativa.\n\n"
                        "Respondé SOLO JSON con: \n"
                        "{\"es_valida\": true/false, \"razon\": \"explicación breve de por qué\", \"sugerencia\": \"cómo debería ser la respuesta correcta\"}"
                    )
                },
                {"role": "user", "content": contexto_completo}
            ],
            temperature=0.0,
            max_tokens=350,
            response_format={"type": "json_object"}
        )
        register_cost(resp)

        raw = resp.choices[0].message.content.strip()
        raw = re.sub(r'^```json\s*', '', raw)
        raw = re.sub(r'\s*```$', '', raw)
        result = json.loads(raw)

        print(f"   🔍 [Validación IA] Válida: {result.get('es_valida', False)} - {result.get('razon', '')}")
        return result

    except Exception as e:
        print(f"   ⚠️ [Validación IA] Error: {e}")
        return {"es_valida": True, "razon": f"Error en validación: {e}", "sugerencia": ""}


async def regenerar_respuesta_con_ia(
    mensaje_usuario: str, 
    conv_state: Dict,
    sugerencia: str,
    prospecto: Dict = None,
    respuesta_original: str = ""
) -> str:
    """
    Regenera una respuesta usando IA cuando la validación falla.
    🔧 CORREGIDO: Elimina la condición tiene_historial (siempre True) y usa solo es_primer_mensaje_agente.
    🔧 CORREGIDO: Formato correcto con emoji 🏟️ al inicio de la segunda línea.
    """
    try:
        fase_actual = conv_state.get("fase", "inicial")
        historial = conv_state.get("historial", [])

        # 🔧 CRÍTICO: Verificar cuántos mensajes del agente hay en el historial
        mensajes_agente = [m for m in historial if m.get("role") == "assistant"]
        es_primer_mensaje_agente = len(mensajes_agente) == 0

        from cancheria.config.legacy_config import AGENT_NAME, BUSINESS_NAME

        # Construir historial
        historial_texto = ""
        for msg in historial[-6:]:
            role = "Usuario" if msg["role"] == "user" else "Agente"
            historial_texto += f"{role}: {msg['content'][:150]}\n"

        contexto_completo = f"""
FASE ACTUAL: {fase_actual}
ES PRIMER MENSAJE DEL AGENTE: {es_primer_mensaje_agente}
ES CLIENTE: {prospecto.get('es_cliente', 'no') if prospecto else 'no'}
DÍA EN MEMORIA: {conv_state.get('dia_propuesto') or ''}
HORA EN MEMORIA: {conv_state.get('hora_propuesta') or ''}
CANCHA EN MEMORIA: {conv_state.get('cancha_propuesta') or ''}
FRANJA DE ATENCIÓN: {descripcion_franjas_atencion_mensaje()}

HISTORIAL:
{historial_texto if historial_texto else "(sin historial)"}

MENSAJE DEL USUARIO: "{mensaje_usuario}"
RESPUESTA ORIGINAL A CORREGIR:
"{respuesta_original or ''}"
SUGERENCIA: {sugerencia}
"""

        system_prompt = (
            f"Sos {AGENT_NAME}, asistente de WhatsApp de {BUSINESS_NAME} para reservas de canchas de fútbol 5.\n"
            "Respondés de forma natural, corta y directa, con tono argentino informal.\n"
            "Tu misión es ayudar a reservar turnos, informar precios y disponibilidad.\n\n"
            "REGLAS DE REGENERACIÓN:\n"
            "- Corregí solamente la parte marcada como mala por la sugerencia.\n"
            "- Tomá la RESPUESTA ORIGINAL como base. No la reemplaces por una respuesta inventada.\n"
            "- Conservá datos correctos del contexto/memoria: día, hora, cancha, precio, seña y disponibilidad.\n"
            "- Si la respuesta original dice que hay cancha libre o disponible para un día/hora, NO podés cambiarlo a 'no tengo disponibilidad'.\n"
            "- Si la respuesta original contiene una disponibilidad verificada, conservá exactamente ese día, fecha, hora y canchas.\n"
            "- Si hay una hora en memoria y el usuario cambia solo el día, respondé sobre esa misma hora.\n"
            "- No inventes falta de disponibilidad. Si falta consultar calendario, pedí el dato faltante o usá la propuesta de memoria.\n"
            "- No reemplaces una respuesta útil completa por una respuesta genérica.\n\n"
            f"⚠️ SEÑA OBLIGATORIA: Requiere seña={REQUIRES_DEPOSIT}, modalidad={_descripcion_senia_runtime()}, alias={PAYMENT_ALIAS}.\n"
            "Si el usuario todavía no envió un comprobante válido ni la seña figura pagada, NO digas "
            "'reserva confirmada', 'está confirmada', 'queda firme' ni similares. "
            "Pedí el comprobante de seña y conservá el detalle del turno/precio si está disponible.\n\n"
            "⚠️ IDENTIDAD (CRÍTICO): Sos un bot administrativo del predio, NO una persona y NO jugás al fútbol.\n"
            "Si el mensaje del usuario tiene una pregunta social/personal dirigida a un humano "
            "(ej: '¿te vas a jugar?', '¿vas a venir vos?'), NO la respondas en primera persona "
            "ni inventes que vas a jugar, ir o participar. Ignorá esa parte del mensaje.\n\n"
            f"Tu nombre es {AGENT_NAME} y el negocio se llama {BUSINESS_NAME}."
        )

        # 🔧 FIX CLAUDE: SIN la condición tiene_historial (siempre True)
        if es_primer_mensaje_agente:
            system_prompt += (
                f"\n⚠️ IMPORTANTE - PRIMER CONTACTO:\n"
                f"El usuario acaba de saludar y este es el primer mensaje del agente en la conversación.\n"
                f"DEBÉS RESPONDER CON ESTE FORMATO EXACTO:\n"
                f"'🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\\n\\n🏟️ ' + [EL RESTO DE LA RESPUESTA]\n"
                f"El salto de línea después de la presentación es OBLIGATORIO.\n"
                f"El emoji 🏟️ va al inicio de la segunda línea, ANTES del resto del mensaje.\n"
                f"NO uses punto después del emoji. El emoji es el inicio de la segunda línea.\n"
                f"NO inventes otro nombre para vos mismo: usá exactamente '{AGENT_NAME}'.\n"
                f"NO digas 'bot del predio' ni ninguna variante genérica.\n"
            )

        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": f"CONTEXTO:\n{contexto_completo}\n\nGenerá la respuesta apropiada para este mensaje."}
            ],
            temperature=0.7,
            max_tokens=250
        )
        register_cost(resp)

        respuesta = resp.choices[0].message.content.strip()

        # 🔧 RED DE SEGURIDAD EXTRA (post-check)
        if es_primer_mensaje_agente:
            # Verificar que el nombre del agente esté en la respuesta
            if AGENT_NAME.lower() not in respuesta.lower():
                print(f"   ⚠️ [Regeneración IA] Nombre de agente ausente, forzando saludo correcto")
                # Si la respuesta ya tiene un saludo, reemplazarlo
                if "hola" in respuesta.lower() or "buen" in respuesta.lower():
                    # Extraer el resto del mensaje sin el saludo
                    partes = respuesta.split("\n")
                    cuerpo = "\n".join(partes[1:]) if len(partes) > 1 else respuesta
                    # Si el cuerpo sigue teniendo "bot" genérico, limpiarlo
                    cuerpo = cuerpo.replace("bot el predio", AGENT_NAME).replace("bot del predio", AGENT_NAME)
                    # 🔧 FIX: Emoji al inicio de la segunda línea
                    respuesta = f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ {cuerpo}"
                else:
                    # No hay saludo, forzar el completo con emoji en segunda línea
                    respuesta = f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ {respuesta}"

            # Si todavía tiene "bot el predio", reemplazar directamente
            if "bot el predio" in respuesta.lower() or "bot del predio" in respuesta.lower():
                print(f"   🔧 [Regeneración] Detectado 'bot el predio' - corrigiendo con {AGENT_NAME}")
                respuesta = respuesta.replace("bot el predio", AGENT_NAME).replace("bot del predio", AGENT_NAME)

        # 🔧 FIX ADICIONAL: Asegurar formato correcto en PRIMER CONTACTO
        if es_primer_mensaje_agente:
            # Verificar que el salto de línea existe
            if "\n\n" not in respuesta[:80]:
                # Buscar dónde está el emoji
                if "🏟️" in respuesta:
                    # Si el emoji está en la primera línea, moverlo a la segunda
                    idx_emoji = respuesta.index("🏟️")
                    if idx_emoji < 80:
                        # Reemplazar según el caso
                        if "🏟️." in respuesta:
                            respuesta = respuesta.replace("🏟️.", ".\n\n🏟️")
                        elif "🏟️ " in respuesta:
                            respuesta = respuesta.replace("🏟️ ", ".\n\n🏟️")
                        else:
                            # Forzar formato completo
                            respuesta = f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ {respuesta}"
                else:
                    # Si no hay emoji, agregarlo en segunda línea
                    respuesta = f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ {respuesta}"

            # Verificar que el formato sea: Línea1 (sin emoji), salto, Línea2 (con emoji al inicio)
            lineas = respuesta.split("\n")
            if len(lineas) >= 3:  # Tiene el salto de línea
                # Asegurar que la primera línea NO tenga el emoji
                if "🏟️" in lineas[0]:
                    # Mover emoji de la primera línea a la segunda
                    lineas[0] = lineas[0].replace("🏟️", "").replace("  ", " ").strip()
                    if not lineas[1].startswith("🏟️"):
                        lineas[1] = f"🏟️ {lineas[1].lstrip()}"
                    respuesta = "\n".join(lineas)

        print(f"   🔄 [Regeneración IA] Nueva respuesta: {respuesta[:100]}...")
        return respuesta

    except Exception as e:
        print(f"   ⚠️ [Regeneración IA] Error: {e}")
        from cancheria.config.legacy_config import AGENT_NAME, BUSINESS_NAME
        # 🔧 FIX: Emoji al inicio de la segunda línea
        return f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ Decime qué día y horario querés reservar."


# ================================
# NUEVAS FUNCIONES AGÉNTICAS (AGREGADAS)
# ================================

def _respuesta_contiene_disponibilidad_verificada(texto: str) -> bool:
    t = str(texto or "").lower()
    t_simple = _texto_simple_para_detector(texto or "")
    return (
        ("libre para" in t or "disponible para" in t or "tengo disponible" in t)
        and ("cancha" in t)
        and (
            "cual preferis" in t_simple
            or "la reservo" in t_simple
            or "confirmamos" in t_simple
            or "que cancha" in t_simple
        )
    )


def _respuesta_declara_no_disponible(texto: str) -> bool:
    t = str(texto or "").lower()
    return (
        "no tengo disponibilidad" in t
        or "no hay disponibilidad" in t
        or "está ocupado" in t
        or "esta ocupado" in t
    )


def seleccionar_respuesta_factual_verificada(respuestas: List[str]) -> str:
    candidatas = [r.strip() for r in (respuestas or []) if _respuesta_contiene_disponibilidad_verificada(r)]
    if not candidatas:
        return ""
    candidatas.sort(key=len)
    return candidatas[0]


def puntaje_formato_whatsapp(
    texto: str,
) -> int:
    if not texto:
        return 0

    t = str(texto)
    score = 0

    lineas = [
        linea
        for linea in t.splitlines()
    ]

    lineas_no_vacias = [
        linea.strip()
        for linea in lineas
        if linea.strip()
    ]

    score += min(
        t.count("\n"),
        8,
    )

    score += min(
        t.count("\n\n") * 2,
        8,
    )

    iconos_bloque = (
        "🙋",
        "✅",
        "🏟️",
        "⚽",
        "🔥",
        "💲",
        "💰",
        "💵",
        "💸",
        "📅",
        "1️⃣",
        "2️⃣",
        "━━━━━━━━",
    )

    score += (
        sum(
            1
            for icono in iconos_bloque
            if icono in t
        )
        * 2
    )

    score += sum(
        1
        for linea in lineas_no_vacias
        if linea.startswith(
            iconos_bloque
        )
    )

    if "━━━━━━━━" in t:
        score += 4

    if re.search(
        r"\n\s*\n.*\n\s*\n",
        t,
        flags=re.S,
    ):
        score += 4

    if len(
        lineas_no_vacias
    ) >= 4:
        score += 3

    if (
        len(
            lineas_no_vacias
        ) <= 2
        and len(t) > 120
    ):
        score -= 8

    # Muchos saltos de línea por sí solos ya no pueden
    # convertir una respuesta rota en "bien formateada".
    issues = (
        _agent_v2_visual_response_issues(
            t
        )
    )

    score -= min(
        24,
        len(issues) * 8,
    )

    return score

def necesita_formateo_whatsapp(
    texto: str,
) -> bool:
    if not texto:
        return False

    t = str(texto)

    # Un formato objetivamente roto siempre
    # pasa por el formateador.
    if _agent_v2_visual_response_issues(
        t
    ):
        return True

    if (
        t.count("\n") >= 3
        or "\n\n" in t
    ):
        return False

    iconos = (
        "🙋",
        "✅",
        "🏟️",
        "⚽",
        "🔥",
        "💲",
        "💰",
        "💵",
        "💸",
        "📅",
        "1️⃣",
        "2️⃣",
        "━━━━━━━━",
    )

    iconos_presentes = sum(
        1
        for icono in iconos
        if icono in t
    )

    return (
        len(t) > 110
        or iconos_presentes >= 2
    )

def _tokens_factuales_para_formato(texto: str) -> List[str]:
    t = str(texto or "")
    patrones = [
        r"\$\s?[\d.,]+",
        r"\b\d{1,2}:\d{2}\b",
        r"\b\d{1,2}\s*hs\b",
        r"\b\d{1,2}/\d{1,2}\b",
        r"\bCancha\s+\d+\b",
        r"\bQuincho\s+\d+\b",
        r"\b[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+\s+\d{1,2}/\d{1,2}\b",
    ]
    tokens = []
    for patron in patrones:
        tokens.extend(re.findall(patron, t, flags=re.IGNORECASE))
    return [re.sub(r"\s+", " ", token).strip().casefold() for token in tokens if str(token).strip()]


def formato_preserva_datos_factuales(original: str, formateada: str) -> bool:
    original_tokens = _tokens_factuales_para_formato(original)
    if not original_tokens:
        return True
    formateada_norm = re.sub(r"\s+", " ", str(formateada or "")).casefold()
    return all(token in formateada_norm for token in original_tokens)


def aplicar_negrita_fechas_horas_whatsapp(texto: str) -> str:
    if not texto:
        return texto
    t = str(texto)

    def bold(match):
        valor = match.group(0)
        if valor.startswith("*") and valor.endswith("*"):
            return valor
        return f"*{valor}*"

    patrones = [
        r"(?<!\*)\b(?:Lunes|Martes|Miércoles|Miercoles|Jueves|Viernes|Sábado|Sabado|Domingo)\s+\d{1,2}/\d{1,2}\b(?!\*)",
        r"(?<!\*)\b\d{1,2}hs\s*(?:-|a)\s*\d{1,2}hs\b(?!\*)",
        r"(?<!\*)\b\d{1,2}:\d{2}\s*(?:-|a)\s*\d{1,2}:\d{2}\b(?!\*)",
        r"(?<!\*)\b\d{1,2}hs\b(?!\*)",
        r"(?<!\*)\b\d{1,2}:\d{2}\s*hs\b(?!\*)",
    ]

    partes = re.split(r"(\*[^*\n]+\*)", t)
    for i, parte in enumerate(partes):
        if parte.startswith("*") and parte.endswith("*"):
            continue
        for patron in patrones:
            parte = re.sub(patron, bold, parte)
        partes[i] = parte
    t = "".join(partes)

    t = re.sub(r"\*{2,}", "*", t)
    return t


def aplicar_saludo_primer_contacto_si_corresponde(texto: str, conv_state: Dict = None) -> str:
    texto = str(texto or "").strip()
    if not texto:
        return texto

    texto_lower = texto.lower()
    if texto.startswith("🙋") or f"soy {AGENT_NAME.lower()}" in texto_lower:
        return texto

    historial = (conv_state or {}).get("historial") or []
    ya_respondio_agente = any(
        str(msg.get("role") or "").lower() in ("assistant", "agente", "bot")
        for msg in historial
        if isinstance(msg, dict)
    )
    if ya_respondio_agente:
        return texto

    prefijo_cuerpo = "" if texto.startswith(("🏟️", "✅", "⚽", "🔥")) else "🏟️ "
    return f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n{prefijo_cuerpo}{texto}"


async def consolidar_respuestas_ia(
    mensaje_usuario: str,
    respuestas: List[str],
    conv_state: Dict = None,
    prospecto: Dict = None
) -> str:
    """
    Combina respuestas parciales de sub-intenciones en un solo mensaje final.
    """
    respuestas = [r.strip() for r in (respuestas or []) if r and r.strip()]
    if not respuestas:
        return ""
    if len(respuestas) == 1:
        return respuestas[0]

    vistos = set()
    unicas = []
    for respuesta in respuestas:
        key = re.sub(r"\s+", " ", respuesta.strip().lower())
        if key not in vistos:
            vistos.add(key)
            unicas.append(respuesta)
    if len(unicas) == 1:
        print("   [Consolidacion IA] Respuestas duplicadas; se envia una sola.")
        return unicas[0]

    factual_verificada = seleccionar_respuesta_factual_verificada(unicas)
    if factual_verificada:
        print("   [Consolidacion] Preservo disponibilidad verificada por calendario y descarto respuesta contextual secundaria.")
        return factual_verificada

    bloques = "\n---\n".join(f"Respuesta {i + 1}: {r}" for i, r in enumerate(unicas))
    contexto_extra = ""
    if conv_state:
        contexto_extra = (
            f"Fase: {conv_state.get('fase', '')} | "
            f"Dia: {conv_state.get('dia_propuesto')} | "
            f"Hora: {conv_state.get('hora_propuesta')} | "
            f"Cancha: {conv_state.get('cancha_propuesta')}"
        )

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el redactor final de un agente de WhatsApp para reservas de canchas.\n"
                        "El mensaje del usuario disparo varias sub-intenciones y cada una genero una "
                        "respuesta parcial, pero SOLO se puede enviar UN mensaje de WhatsApp.\n\n"
                        "Fusiona esas respuestas parciales en UNA sola respuesta breve, natural y coherente, "
                        "sin repetir informacion ni contradecirte.\n"
                        "Si dos respuestas dicen basicamente lo mismo, quedate con una sola version.\n"
                        "Si son complementarias, unilas en un mensaje fluido.\n"
                        "No agregues saludos ni cierres de mas. Responde SOLO el texto final a enviar.\n\n"
                        "Si una respuesta parcial contiene disponibilidad verificada por calendario "
                        "('libre/disponible para día/hora/cancha') y otra solo responde a una queja o insulto, "
                        "conservá la respuesta de disponibilidad y no inventes falta de disponibilidad.\n"
                        "Nunca cambies un 'libre/disponible' por 'no tengo disponibilidad'.\n\n"
                        "IDENTIDAD: Sos un bot de reservas, no una persona ni un jugador. Nunca agregues "
                        "frases como 'voy a jugar', 'nos vemos ahi' o similares que impliquen que vos "
                        "participas del partido. Si el mensaje original del usuario tenia una pregunta "
                        "social dirigida a un humano, no la contestes."
                    )
                },
                {
                    "role": "user",
                    "content": (
                        f"Mensaje original del usuario: \"{mensaje_usuario}\"\n"
                        f"Contexto: {contexto_extra}\n\n"
                        f"Respuestas parciales generadas:\n{bloques}\n\n"
                        "Devolve el mensaje final unico a enviar."
                    )
                }
            ],
            temperature=0.3,
            max_tokens=220
        )
        register_cost(resp)
        final = resp.choices[0].message.content.strip()
        final = re.sub(r'^[\'"]+|[\'"]+$', "", final).strip()
        return final or unicas[0]
    except Exception as e:
        print(f"   [Consolidacion IA] Error: {e}")
        return unicas[0]


async def arbitrar_respuesta_final_ia(
    mensaje_usuario: str,
    candidatos: List[Dict[str, str]],
    validacion: Dict,
    conv_state: Dict = None,
    prospecto: Dict = None
) -> str:
    """IA final: compara candidatos, conserva hechos verificados y elige/combina la respuesta correcta."""
    candidatos_limpios = []
    for item in candidatos or []:
        texto = str(item.get("texto") or "").strip()
        if not texto:
            continue
        candidatos_limpios.append({
            "origen": str(item.get("origen") or "candidato"),
            "texto": texto,
            "contiene_disponibilidad_verificada": _respuesta_contiene_disponibilidad_verificada(texto),
            "declara_no_disponible": _respuesta_declara_no_disponible(texto),
            "puntaje_formato_whatsapp": puntaje_formato_whatsapp(texto),
            "cantidad_saltos_linea": texto.count("\n"),
        })
    if not candidatos_limpios:
        return ""

    if len(candidatos_limpios) == 1:
        return candidatos_limpios[0]["texto"]

    hechos = {
        "fase": (conv_state or {}).get("fase"),
        "dia_propuesto": (conv_state or {}).get("dia_propuesto"),
        "hora_propuesta": (conv_state or {}).get("hora_propuesta"),
        "cancha_propuesta": (conv_state or {}).get("cancha_propuesta"),
        "con_quincho": (conv_state or {}).get("con_quincho"),
        "quincho": (conv_state or {}).get("quincho"),
        "validacion": validacion or {},
        "prospecto": {
            "nombre": (prospecto or {}).get("nombre"),
            "es_cliente": (prospecto or {}).get("es_cliente"),
        },
    }

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos la IA árbitro final de un agente de reservas de canchas.\n"
                        "Recibís varias respuestas candidatas generadas por módulos distintos, una validación y hechos de memoria.\n"
                        "Tu tarea NO es inventar una respuesta nueva desde cero: tenés que elegir o combinar SOLO las partes correctas de los candidatos.\n\n"
                        "Reglas críticas:\n"
                        "1. Los datos factuales de calendario, precio, seña, fecha, hora y cancha son sagrados.\n"
                        "2. Si un candidato contiene disponibilidad verificada ('libre/disponible para día/hora/cancha'), no podés transformarla en falta de disponibilidad.\n"
                        "3. Si otro candidato solo responde a un insulto/queja y contradice o distrae de la disponibilidad, descartalo.\n"
                        "4. Si combinás, hacelo breve y natural, pero conservando exactamente día, fecha, hora y canchas del candidato factual.\n"
                        "5. Si la validación dice que hay una parte mala, corregí solo esa parte usando los candidatos buenos.\n"
                        "6. No agregues datos comerciales o disponibilidad que no aparezcan en candidatos o hechos.\n\n"
                        f"Regla de negocio de seña: Requiere seña={REQUIRES_DEPOSIT}, modalidad={_descripcion_senia_runtime()}, alias={PAYMENT_ALIAS}.\n"
                        "Si no hay comprobante validado ni seña pagada en los candidatos/hechos, no podés decir "
                        "'reserva confirmada', 'está confirmada', 'queda firme' ni equivalentes. "
                        "La respuesta correcta debe pedir comprobante de seña o conservar un candidato que lo pida.\n\n"
                        "Reglas de formato WhatsApp:\n"
                        "7. Primero elegí por validez real, no por estética.\n"
                        "8. Si la respuesta correcta ya existe pero está mal formateada, devolvé la correcta igual; otra IA se encargará del formato.\n"
                        "9. Si podés conservar saltos de línea de un candidato correcto, hacelo, pero nunca elijas una respuesta inválida solo porque se ve mejor.\n\n"
                        "Respondé SOLO JSON: "
                        "{\"respuesta_final\":\"texto exacto a enviar\",\"origenes_usados\":[\"origen\"],\"razon\":\"breve\"}"
                    )
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "mensaje_usuario": mensaje_usuario,
                        "hechos": hechos,
                        "candidatos": candidatos_limpios,
                    }, ensure_ascii=False)
                }
            ],
            temperature=0.0,
            max_tokens=360,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        respuesta = str(data.get("respuesta_final") or "").strip()
        print(f"   [Árbitro final IA] {str(data.get('razon', ''))[:120]}")
        if not respuesta:
            return candidatos_limpios[0]["texto"]

        factuales = [c for c in candidatos_limpios if c.get("contiene_disponibilidad_verificada")]
        if factuales and _respuesta_declara_no_disponible(respuesta):
            print("   [Árbitro final IA] Descarto salida porque contradijo disponibilidad verificada.")
            return factuales[0]["texto"]
        return respuesta
    except Exception as e:
        print(f"   [Árbitro final IA] Error: {e}")
        factual = seleccionar_respuesta_factual_verificada([c["texto"] for c in candidatos_limpios])
        return factual or candidatos_limpios[0]["texto"]


async def formatear_respuesta_whatsapp_con_ia(
    mensaje_usuario: str,
    respuesta_correcta: str,
    conv_state: Dict = None,
    prospecto: Dict = None,
) -> str:
    """IA de presentación: corrige maquetación WhatsApp sin alterar hechos."""
    if (
        not respuesta_correcta
        or not necesita_formateo_whatsapp(
            respuesta_correcta
        )
    ):
        return aplicar_negrita_fechas_horas_whatsapp(
            respuesta_correcta
        )

    ejemplos = (
        "EJEMPLO 1:\n"
        "🙋 ¡Hola! Soy Seba de La Cancha Futbol 5.\n\n"
        "✅ Para hoy a las *20hs* tengo disponible:\n\n"
        "⚽ Cancha 1 o Cancha 2\n"
        "💲 $15,000 por hora\n\n"
        "🔥 Quincho 1\n"
        "💲 $10,000 por hora\n\n"
        "Por defecto, el quincho comienza cuando termina la cancha "
        "a las 21hs, salvo que prefieras otro horario.\n\n"
        "¿Cuántas horas querés reservar el quincho/parrilla?\n\n"

        "EJEMPLO 2:\n"
        "Perfecto.\n\n"
        "⚽ Cancha: *20hs a 21hs* (1 hora)\n"
        "💲 $15,000\n\n"
        "🔥 Quincho/Parrilla: *21hs a 23hs* (2 horas)\n"
        "💲 $20,000\n\n"
        "━━━━━━━━━━━━━━\n"
        "💰 Total: $35,000\n"
        "━━━━━━━━━━━━━━\n"
        "¿Qué cancha preferís para hoy a las *20hs*?\n\n"
        "1️⃣ Cancha 1\n"
        "2️⃣ Cancha 2\n\n"

        "EJEMPLO 3:\n"
        "Para dejar firme el turno, por favor envía el comprobante "
        "de la seña de $7,500 al alias ALIAS.A.CONFIGURAR.\n"
        "Si tenés efectivo, podés acercarte a Direccion a configurar "
        "para reservar. Gracias.\n\n"
        "⚽ Cancha: Cancha 1 Futbol 5 de *20hs-21hs*\n"
        "💲 $15,000\n\n"
        "🔥 Quincho/parrilla: Quincho 1 de *21hs-23hs*\n"
        "💲 $20,000\n\n"
        "💰 Total: $35,000\n"
        "💵 Seña: $7,500\n"
        "💸 Saldo pendiente: $27,500"
    )

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos una IA formateadora de mensajes de WhatsApp "
                        "para un agente de reservas de canchas.\n"

                        "La respuesta que recibís YA FUE elegida como correcta "
                        "por otra IA. No decidas contenido.\n"

                        "Tu única tarea es mejorar la legibilidad y reparar "
                        "defectos visuales. No decidas hechos.\n\n"

                        "Reglas obligatorias:\n"

                        "1. No cambies disponibilidad, día, fecha, hora, cancha, "
                        "quincho, precio, seña, alias ni dirección.\n"

                        "2. No agregues datos nuevos.\n"

                        "3. No elimines hechos necesarios para responder; "
                        "sí podés quitar duplicaciones textuales puramente "
                        "redundantes.\n"

                        "4. No cambies una respuesta disponible por no disponible "
                        "ni al revés.\n"

                        "5. Mantené respuestas simples breves: no agregues bloques, "
                        "títulos o emojis innecesarios.\n"

                        "6. Cada línea debe tener asteriscos balanceados. "
                        "Nunca abras *negrita en una línea y la cierres en otra*.\n"

                        "7. Nunca muestres cinco o más horarios como un horario "
                        "por bullet/renglón. Si ya están presentes, unilos en una "
                        "sola línea separada por comas y 'y', sin cambiar ningún "
                        "horario.\n"

                        "8. Usá negrita WhatsApp solo cuando ayude: "
                        "*Jueves 06/08*, *15hs*, *15hs-16hs*.\n"

                        "9. Si la respuesta ya está prolija, devolvela "
                        "prácticamente igual.\n"

                        "Respondé SOLO JSON: "
                        '{"respuesta_formateada":"texto"}'
                    ),
                },
                {
                    "role": "user",
                    "content": (
                        f"Mensaje usuario: {mensaje_usuario}\n\n"
                        f"Ejemplos de formato esperado:\n"
                        f"{ejemplos}\n\n"
                        f"Respuesta correcta a formatear:\n"
                        f"{respuesta_correcta}"
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=520,
            response_format={
                "type": "json_object"
            },
        )

        register_cost(
            resp
        )

        data = json.loads(
            resp
            .choices[0]
            .message
            .content
            .strip()
        )

        formateada = str(
            data.get(
                "respuesta_formateada"
            )
            or ""
        ).strip()

        if not formateada:
            return aplicar_negrita_fechas_horas_whatsapp(
                respuesta_correcta
            )

        if not formato_preserva_datos_factuales(
            respuesta_correcta,
            formateada,
        ):
            print(
                "   [Formato WhatsApp IA] "
                "Descartado: cambió datos factuales."
            )

            return aplicar_negrita_fechas_horas_whatsapp(
                respuesta_correcta
            )

        if (
            _respuesta_contiene_disponibilidad_verificada(
                respuesta_correcta
            )
            and _respuesta_declara_no_disponible(
                formateada
            )
        ):
            print(
                "   [Formato WhatsApp IA] "
                "Descartado: contradijo disponibilidad factual."
            )

            return aplicar_negrita_fechas_horas_whatsapp(
                respuesta_correcta
            )

        print(
            "   [Formato WhatsApp IA] "
            "Respuesta formateada sin cambiar datos."
        )

        return aplicar_negrita_fechas_horas_whatsapp(
            formateada
        )

    except Exception as e:
        print(
            "   [Formato WhatsApp IA] "
            f"Error: {e}"
        )

        return aplicar_negrita_fechas_horas_whatsapp(
            respuesta_correcta
        )


def limpiar_identidad_agente_en_respuesta(texto: str) -> str:
    """Compatibilidad: la identidad ahora se corrige con validar_respuesta_con_ia + regenerar_respuesta_con_ia."""
    return texto

def construir_contexto_agente(conv_state: Dict, prospecto: Dict, telefono: str) -> str:
    """Construye el contexto completo para la IA."""
    historial_texto = ""
    for msg in conv_state.get("historial", [])[-10:]:
        role = "Usuario" if msg["role"] == "user" else "Agente"
        historial_texto += f"{role}: {msg['content'][:200]}\n"

    from cancheria.config.legacy_config import obtener_franjas_atencion_minutos, _minutos_a_hora

    horarios_posibles = []
    for inicio_min, fin_min in obtener_franjas_atencion_minutos():
        hora_actual = inicio_min
        while hora_actual + TURN_DURATION_MINUTES <= fin_min:
            horarios_posibles.append(_minutos_a_hora(hora_actual))
            hora_actual += TURN_DURATION_MINUTES

    todas_reservas = []
    reservas_raw = []
    try:
        reservas_raw = calendario.listar_reservas()
        for r in reservas_raw[:30]:
            todas_reservas.append(f"  • {r.get('fecha', '?')} {r.get('hora', '?')} - {r.get('cancha', '?')} - {r.get('nombre', '?')}")
    except:
        todas_reservas = ["(no se pudo consultar calendario)"]

    reserva_existente = "No tiene reserva activa"
    if telefono and telefono != "unknown" and not telefono.startswith("NOMBRE:"):
        try:
            reserva = calendario.obtener_reserva_por_telefono(telefono)
            if reserva:
                reserva_existente = f"{reserva.get('fecha', 'sin fecha')} {reserva.get('hora', 'sin hora')} en {reserva.get('cancha', 'sin cancha')}"
        except:
            pass

    estado_operativo = obtener_estado_operativo_predio()
    resumen_operativo = resumir_estado_operativo_predio(estado_operativo)
    memoria_cliente = conv_state.get("memoria_cliente") or cargar_memoria_cliente(telefono or "unknown")
    contexto = f"""
DATOS DEL NEGOCIO:
- Nombre: {BUSINESS_NAME}
- Horario: {descripcion_franjas_atencion_mensaje()}
- Canchas: {[c['name'] for c in COURTS]}
- Precios: {PRICES}
- Requiere seña: {REQUIRES_DEPOSIT} (modalidad: {_descripcion_senia_runtime()}, alias: {PAYMENT_ALIAS})

CONTACTO ACTUAL:
- Nombre: {prospecto.get('nombre', 'No especificado')}
- Es cliente: {prospecto.get('es_cliente', CLIENTE_NO)}
- Memoria persistente: cliente_frecuente={memoria_cliente.get('cliente_frecuente')}, cancha_preferida={memoria_cliente.get('cancha_preferida') or 'sin dato'}, horario_preferido={memoria_cliente.get('horario_preferido') or 'sin dato'}, dias_frecuentes={memoria_cliente.get('dias_frecuentes') or []}
- Resumen conversacion persistente: {memoria_cliente.get('resumen_conversacion') or '(sin resumen persistente)'}

ESTADO CONVERSACIÓN:
- Fase: {conv_state.get('fase', 'inicial')}
- Día propuesto: {conv_state.get('dia_propuesto', 'ninguno')}
- Hora propuesta: {conv_state.get('hora_propuesta', 'ninguna')}
- Cancha propuesta: {conv_state.get('cancha_propuesta', 'ninguna')}
- Decision actual: {conv_state.get('decision_actual') or '(todavia sin decision)'}
- Plan actual: {conv_state.get('plan_actual') or '(todavia sin plan)'}

HISTORIAL:
{historial_texto if historial_texto else '(inicio)'}

{resumen_operativo}

📅 CALENDARIO COMPLETO:
{chr(10).join(todas_reservas) if todas_reservas else 'No hay reservas'}

🔍 RESERVA DE ESTE CONTACTO:
{reserva_existente}

⚠️ REGLA OPERATIVA: No inventes disponibilidad. Siempre validá calendario antes de confirmar, cancelar o reprogramar.
⚠️ IDENTIDAD: Sos el encargado virtual de {BUSINESS_NAME}. Administrá turnos como una persona del predio: claro, rápido, práctico, sin vueltas y cuidando señas, agenda y conflictos.
"""
    return contexto

async def agente_analizar(ultimo_mensaje: str, conv_state: Dict, prospecto: Dict, telefono: str) -> Dict:
    """IA analiza el mensaje y decide el TIPO de acción usando el PROMPT_SETTER del config."""
    from cancheria.config.legacy_config import AGENT_NAME, BUSINESS_NAME, PROMPT_SETTER, COURTS, TURN_DURATION_MINUTES, DEPOSIT_AMOUNT

    contexto = construir_contexto_agente(conv_state, prospecto, telefono)

    # 🔧 PASO 1: Extraer hora específica con IA
    hora_extraida = await extraer_hora_de_texto(ultimo_mensaje, conv_state)
    if hora_extraida:
        print(f"   🕒 [agente_analizar] Hora extraída: {hora_extraida}")

    # 🔧 PASO 2: Extraer cancha específica con IA (usando el mensaje completo, no fragmento)
    cancha_extraida = extraer_cancha_de_mensaje(ultimo_mensaje, conv_state)
    if cancha_extraida:
        print(f"   🏟️ [agente_analizar] Cancha extraída: {cancha_extraida}")
        # 🧠 MEMORIA CRÍTICA: Guardar la cancha que el usuario eligió
        conv_state["cancha_propuesta"] = cancha_extraida
        print(f"   🧠 [MEMORIA] Usuario eligió {cancha_extraida} - guardando en estado")

    # 🔧 PASO 3: Obtener la reserva ACTUAL del usuario
    es_contacto_agendado = telefono and telefono.startswith("NOMBRE:")
    reserva_actual = None

    if es_contacto_agendado:
        nombre_contacto = telefono.replace("NOMBRE:", "").strip()
        print(f"   🔍 [agente_analizar] Buscando reserva para contacto agendado: '{nombre_contacto}'")
        reserva_actual = calendario.obtener_reserva_por_nombre(nombre_contacto)
    elif telefono:
        reserva_actual = calendario.obtener_reserva_por_telefono(telefono)
        if not reserva_actual and prospecto.get("nombre"):
            print(f"   🔍 [agente_analizar] No encontrada por teléfono, buscando por nombre: '{prospecto.get('nombre')}'")
            reserva_actual = calendario.obtener_reserva_por_nombre(prospecto.get("nombre"))

    cancha_actual = reserva_actual.get("cancha") if reserva_actual else None
    hora_actual_reserva = reserva_actual.get("hora") if reserva_actual else None
    dia_actual_reserva = reserva_actual.get("fecha") if reserva_actual else None

    # 🔧 CRÍTICO: Verificar si la reserva actual tiene SEÑA PAGADA
    tenia_senia_pagada = False
    monto_senia_original = _monto_humano(_senia_para_total(calcular_precio_total(DEFAULT_TURN_DURATION_HOURS)))

    if reserva_actual:
        tenia_senia_pagada = reserva_actual.get("senia_estado") == "pagada"
        monto_senia_original = reserva_actual.get("senia_monto") or _monto_humano(
            _senia_guardada_o_configurada(reserva_actual, reserva_actual.get("precio_total"))
        )
        print(f"   📋 [agente_analizar] Reserva actual encontrada: {dia_actual_reserva} {hora_actual_reserva} - Cancha: {cancha_actual}")
        print(f"   💰 [agente_analizar] Estado seña: {reserva_actual.get('senia_estado', 'sin seña')} | Monto: {monto_senia_original}")
        if tenia_senia_pagada:
            print(f"   🔧 [agente_analizar] USUARIO TIENE SEÑA PAGADA - se preservará en reprogramación")
    else:
        print(f"   📋 [agente_analizar] No se encontró reserva actual para contacto: {telefono}, nombre: {prospecto.get('nombre')}")
    print(f"   🏟️ [agente_analizar] Cancha actual del usuario: {cancha_actual or 'ninguna'}")

    # 🔧 PASO 4: Detectar si es un pedido de reprogramación
    es_reprogramacion = False
    palabras_reprogramacion = ["cambiar", "mover", "pasar", "modificar", "reprogramar", "cambio", "muevo", "paso", "modifico"]
    for palabra in palabras_reprogramacion:
        if palabra in ultimo_mensaje.lower():
            es_reprogramacion = True
            print(f"   🔄 [agente_analizar] Pedido de REPROGRAMACIÓN detectado por '{palabra}'")
            break

    # 🔧 PASO 5: Si es reprogramación y hay hora específica
    if es_reprogramacion and hora_extraida:
        dia_propuesto = "hoy"
        hora_propuesta = hora_extraida

        print(f"   🔄 [REPROGRAMACIÓN] Usuario quiere cambiar a las {hora_propuesta}")
        print(f"   🏟️ Cancha actual del usuario: {cancha_actual or 'ninguna'}")
        print(f"   ⏰ Hora actual del usuario: {hora_actual_reserva or 'ninguna'}")
        if tenia_senia_pagada:
            print(f"   💰 [REPROGRAMACIÓN] Preservando estado de SEÑA PAGADA (monto: {monto_senia_original})")

        # Verificar si la cancha actual está disponible a la nueva hora
        dia_resuelto = resolver_fecha(dia_propuesto)

        if cancha_actual:
            misma_cancha_libre = calendario.slot_esta_libre_en_cancha(dia_resuelto, hora_propuesta, cancha_actual)
            print(f"   🔍 ¿Cancha actual {cancha_actual} libre a las {hora_propuesta}? {misma_cancha_libre}")

            if misma_cancha_libre:
                print(f"   ✅ [PRIORIDAD 1] Misma cancha {cancha_actual} disponible. Reprogramando automáticamente.")

                # 🔧 CRÍTICO: Generar respuesta según si tenía seña pagada o no
                if tenia_senia_pagada:
                    respuesta = f"✅ Perfecto, te cambio tu turno a {cancha_actual} para hoy a las {formatear_hora_para_mensaje(hora_propuesta)}. (La seña ya estaba registrada)"
                else:
                    respuesta = f"✅ Perfecto, te cambio tu turno a {cancha_actual} para hoy a las {formatear_hora_para_mensaje(hora_propuesta)}. Confirmo?"

                return {
                    "tipo": "reprogramacion_automatica",
                    "dia": dia_propuesto,
                    "hora": hora_propuesta,
                    "cancha": cancha_actual,
                    "respuesta": respuesta,
                    "tenia_senia_pagada": tenia_senia_pagada,
                    "monto_senia_original": monto_senia_original
                }
            else:
                print(f"   ❌ [PRIORIDAD 1] Misma cancha {cancha_actual} NO disponible a las {hora_propuesta}")

        # PRIORIDAD 2: Buscar OTRAS canchas compatibles a la misma hora.
        # Si existe una reserva real, su type forma parte del contexto operativo:
        # una reprogramación de Fútbol 5 nunca migra a Tenis/Pádel por disponibilidad.
        tipo_actual = _court_type_for_name(cancha_actual) if cancha_actual else None
        resource_types_reprogramacion = [tipo_actual] if tipo_actual else []
        canchas_libres = []
        for court_name in _court_names_compatible_with_resource_types(
            resource_types_reprogramacion
        ):
            if calendario.slot_esta_libre_en_cancha(dia_resuelto, hora_propuesta, court_name):
                canchas_libres.append(court_name)

        print(f"   🔍 Otras canchas libres a las {hora_propuesta}: {canchas_libres}")

        if canchas_libres:
            if len(canchas_libres) == 1:
                print(f"   ✅ [PRIORIDAD 2] Una cancha alternativa disponible: {canchas_libres[0]}")
                if tenia_senia_pagada:
                    respuesta = f"✅ Tu cancha habitual ({cancha_actual}) está ocupada a las {formatear_hora_para_mensaje(hora_propuesta)}, pero tengo libre {canchas_libres[0]}. ¿Te la cambio a esa? (La seña ya estaba registrada)"
                else:
                    if cancha_actual:
                        respuesta = f"✅ Tu cancha habitual ({cancha_actual}) está ocupada a las {formatear_hora_para_mensaje(hora_propuesta)}, pero tengo libre {canchas_libres[0]}. ¿Te la cambio a esa?"
                    else:
                        respuesta = f"✅ Tengo disponible {canchas_libres[0]} para hoy a las {formatear_hora_para_mensaje(hora_propuesta)}. ¿Confirmo?"

                return {
                    "tipo": "reprogramacion_automatica",
                    "dia": dia_propuesto,
                    "hora": hora_propuesta,
                    "cancha": canchas_libres[0],
                    "respuesta": respuesta,
                    "tenia_senia_pagada": tenia_senia_pagada,
                    "monto_senia_original": monto_senia_original
                }
            else:
                canchas_str = " o ".join(canchas_libres)
                print(f"   📋 [PRIORIDAD 2] Múltiples canchas disponibles: {canchas_libres}")
                if tenia_senia_pagada:
                    respuesta = f"Tu cancha habitual ({cancha_actual}) está ocupada a las {formatear_hora_para_mensaje(hora_propuesta)}, pero tengo libre {canchas_str}. ¿Cuál preferís? (La seña ya estaba registrada)"
                else:
                    if cancha_actual:
                        respuesta = f"Tu cancha habitual ({cancha_actual}) está ocupada a las {formatear_hora_para_mensaje(hora_propuesta)}, pero tengo libre {canchas_str}. ¿Cuál preferís?"
                    else:
                        respuesta = f"Tengo {canchas_str} libre para hoy a las {formatear_hora_para_mensaje(hora_propuesta)}. ¿Cuál preferís?"

                return {
                    "tipo": "reprogramacion_con_alternativa",
                    "dia": dia_propuesto,
                    "hora": hora_propuesta,
                    "cancha": None,
                    "respuesta": respuesta,
                    "tenia_senia_pagada": tenia_senia_pagada,
                    "monto_senia_original": monto_senia_original
                }

        # PRIORIDAD 3: No hay canchas libres a esa hora → buscar otro horario en el MISMO día
        print(f"   🔍 [PRIORIDAD 3] No hay canchas libres a las {hora_propuesta}. Buscando otro horario para hoy.")

        from cancheria.config.legacy_config import obtener_franjas_atencion_minutos
        franjas = obtener_franjas_atencion_minutos()
        hora_preferida_minutos = int(hora_propuesta.split(':')[0]) * 60 + int(hora_propuesta.split(':')[1])

        mejor_horario = None
        menor_diferencia = float('inf')
        cancha_para_mejor_horario = None

        for inicio_minutos, fin_minutos in franjas:
            hora_actual = inicio_minutos
            while hora_actual + TURN_DURATION_MINUTES <= fin_minutos:
                hora_candidato = f"{hora_actual // 60:02d}:{hora_actual % 60:02d}"

                for court_name in _court_names_compatible_with_resource_types(
                    resource_types_reprogramacion
                ):
                    if calendario.slot_esta_libre_en_cancha(dia_resuelto, hora_candidato, court_name):
                        diferencia = abs(hora_actual - hora_preferida_minutos)
                        if diferencia < menor_diferencia:
                            menor_diferencia = diferencia
                            mejor_horario = hora_candidato
                            cancha_para_mejor_horario = court_name
                        break

                hora_actual += TURN_DURATION_MINUTES

        if mejor_horario:
            print(f"   ✅ [PRIORIDAD 3] Horario alternativo encontrado: {mejor_horario} en {cancha_para_mejor_horario}")
            if tenia_senia_pagada:
                respuesta = f"Ese horario está ocupado en todas las canchas. ¿Te sirve hoy a las {formatear_hora_para_mensaje(mejor_horario)} en {cancha_para_mejor_horario}? (La seña ya estaba registrada)"
            else:
                respuesta = f"Ese horario está ocupado en todas las canchas. ¿Te sirve hoy a las {formatear_hora_para_mensaje(mejor_horario)} en {cancha_para_mejor_horario}?"

            return {
                "tipo": "reprogramacion_con_alternativa",
                "dia": dia_propuesto,
                "hora": mejor_horario,
                "cancha": cancha_para_mejor_horario,
                "respuesta": respuesta,
                "tenia_senia_pagada": tenia_senia_pagada,
                "monto_senia_original": monto_senia_original
            }

        # PRIORIDAD 4: Buscar en días siguientes
        print(f"   🔍 [PRIORIDAD 4] No hay horarios disponibles hoy. Buscando en días siguientes.")
        dia_alternativo, hora_alternativa = proximo_slot_reservable_con_anticipacion(
            dia_resuelto,
            hora_propuesta,
            duracion_horas=DEFAULT_TURN_DURATION_HOURS,
            max_dias=14,
            resource_types=resource_types_reprogramacion,
        )

        if tenia_senia_pagada:
            respuesta = f"No tengo disponibilidad hoy a las {formatear_hora_para_mensaje(hora_propuesta)}. ¿Te sirve {dia_alternativo} a las {formatear_hora_para_mensaje(hora_alternativa)}? (La seña ya estaba registrada)"
        else:
            respuesta = f"No tengo disponibilidad hoy a las {formatear_hora_para_mensaje(hora_propuesta)}. ¿Te sirve {dia_alternativo} a las {formatear_hora_para_mensaje(hora_alternativa)}?"

        return {
            "tipo": "reprogramacion_con_alternativa",
            "dia": dia_alternativo,
            "hora": hora_alternativa,
            "cancha": None,
            "respuesta": respuesta,
            "tenia_senia_pagada": tenia_senia_pagada,
            "monto_senia_original": monto_senia_original
        }

    # ============================================================
    # DETECTAR PRIMER CONTACTO CON IA
    # ============================================================
    historial_anterior = conv_state.get("historial", [])
    mensajes_agente_previos = [m for m in historial_anterior if m.get("role") == "assistant"]
    es_primer_mensaje_agente = len(mensajes_agente_previos) == 0

    if es_primer_mensaje_agente:
        try:
            resp_deteccion = await call_openai_async(
                model=OPENAI_MODEL,
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "Sos un clasificador de intenciones. Determiná si este mensaje es "
                            "un saludo inicial SIN intención clara de reservar (solo 'hola', 'buenas', "
                            "saludo corto sin pedir horarios, precios o disponibilidad). "
                            "Respondé SOLO con 'SI' o 'NO'."
                        )
                    },
                    {"role": "user", "content": f"Mensaje: '{ultimo_mensaje}'"}
                ],
                temperature=0.0,
                max_tokens=5
            )
            register_cost(resp_deteccion)
            es_saludo_sin_intencion = resp_deteccion.choices[0].message.content.strip().upper() == "SI"
        except Exception as e:
            print(f"   ⚠️ [Detección primer contacto] Error: {e}")
            es_saludo_sin_intencion = False

        if es_saludo_sin_intencion:
            # 🔧 FIX: Usar AGENT_NAME y BUSINESS_NAME desde config con salto de línea y emoji en segunda línea
            respuesta_saludo = f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ ¿Qué día y horario querés reservar?"
            print(f"   🆕 [PRIMER CONTACTO IA] Usando saludo con {AGENT_NAME}")
            return {
                "tipo": "saludo_inicial",
                "dia": None,
                "hora": None,
                "cancha": None,
                "respuesta": respuesta_saludo
            }

    # ============================================================
    # ANÁLISIS NORMAL CON IA (usando el PROMPT_SETTER)
    # ============================================================
    historial_texto = ""
    for msg in conv_state.get("historial", [])[-6:]:
        role = "Usuario" if msg["role"] == "user" else "Agente"
        historial_texto += f"{role}: {msg['content'][:200]}\n"

    fase_actual = conv_state.get("fase", "inicial")
    dia_previo = conv_state.get("dia_propuesto", "ninguno")
    hora_previa = conv_state.get("hora_propuesta", "ninguna")
    cancha_previa = conv_state.get("cancha_propuesta", "ninguna")

    system_prompt_con_config = PROMPT_SETTER.format(
        fase_actual=fase_actual,
        dia_previo=dia_previo,
        hora_previa=hora_previa,
        duracion_previa=conv_state.get("duracion_propuesta", "ninguna"),
        historial_texto=historial_texto or "(sin historial)",
        ultimo_mensaje=ultimo_mensaje,
        nombre=prospecto.get("nombre", "No especificado"),
        negocio=prospecto.get("negocio", "No especificado"),
        es_cliente=prospecto.get("es_cliente", "no"),
        # V2.29: la identidad de cliente ya viene en prospecto/memoria desde
        # Perception; el analizador legacy no vuelve a ejecutar Pilares.
        contexto_restriccion=""
    )

    user_prompt = f"""
CONTEXTO ADICIONAL (calendario real):
{contexto}

CANCHA PREVIAMENTE SELECCIONADA POR EL USUARIO: {cancha_previa if cancha_previa != "ninguna" else "ninguna"}

MENSAJE DEL USUARIO: "{ultimo_mensaje}"

INSTRUCCIÓN:
Analizá el mensaje y respondé con el JSON que pide el PROMPT_SETTER.
Si el usuario ya seleccionó una cancha previamente (cancha_previa no es "ninguna"), 
recordala y úsala en la respuesta.
"""

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": system_prompt_con_config},
                {"role": "user", "content": user_prompt}
            ],
            temperature=0.3,
            max_tokens=500,
            response_format={"type": "json_object"}
        )
        register_cost(resp)

        raw = resp.choices[0].message.content.strip()
        raw = re.sub(r'^```json\s*', '', raw)
        raw = re.sub(r'\s*```$', '', raw)
        resultado = json.loads(raw)

        if "tipo" not in resultado:
            resultado["tipo"] = "necesita_contexto"
        if "respuesta" not in resultado:
            resultado["respuesta"] = "¿Podés repetirme eso? ¿Para qué día y horario querés reservar?"

        resultado["dia"] = resultado.get("dia") if resultado.get("dia") not in (None, "null", "None") else None
        resultado["hora"] = resultado.get("hora") if resultado.get("hora") not in (None, "null", "None") else None
        resultado["cancha"] = resultado.get("cancha") if resultado.get("cancha") not in (None, "null", "None") else None
        duracion_texto = extraer_duracion_de_texto(ultimo_mensaje)
        duracion_ia = resultado.get("duracion_detectada") if resultado.get("duracion_detectada") not in (None, "null", "None") else None
        duracion_detectada = duracion_texto if duracion_texto is not None else duracion_ia
        resultado["duracion_detectada"] = normalizar_duracion_horas(
            duracion_detectada,
            conv_state.get("duracion_propuesta") or DEFAULT_TURN_DURATION_HOURS
        )

        # 🧠 MEMORIA: Si el usuario ya tenía una cancha seleccionada y la IA no detectó ninguna, usar la guardada
        if not resultado.get("cancha") and cancha_previa and cancha_previa != "ninguna":
            resultado["cancha"] = cancha_previa
            print(f"   🧠 [MEMORIA] Usando cancha guardada: {cancha_previa}")

        if hora_extraida and not resultado.get("hora"):
            resultado["hora"] = hora_extraida
            print(f"   🔧 [agente_analizar] Forzando hora = {hora_extraida}")

        # 🧠 MEMORIA: Si el usuario eligió una cancha en este mensaje, ya la guardamos al principio
        if cancha_extraida:
            resultado["cancha"] = cancha_extraida

        print(f"   🧠 [IA] Tipo: {resultado['tipo']} | Dia: {resultado.get('dia')} | Hora: {resultado.get('hora')} | Cancha: {resultado.get('cancha')}")
        return resultado

    except Exception as e:
        print(f"   ⚠️ [IA Error] {e}")
        # 🔧 FIX: Fallback usando AGENT_NAME y BUSINESS_NAME desde config con salto de línea y emoji en segunda línea
        from cancheria.config.legacy_config import AGENT_NAME, BUSINESS_NAME
        return {
            "tipo": "consulta",
            "dia": None,
            "hora": hora_extraida if hora_extraida else None,
            "cancha": cancha_extraida if cancha_extraida else (cancha_previa if cancha_previa != "ninguna" else None),
            "respuesta": f"Voy a verificar disponibilidad para las {formatear_hora_para_mensaje(hora_extraida)}..." if hora_extraida else f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ ¿Qué día y horario querés reservar?"
        }

# 🔧 FUNCIÓN AUXILIAR PARA EXTRAER DÍA CON IA (si no existe)
async def extraer_dia_con_ia(texto: str, conv_state: Dict = None, *, current_turn_only: bool = False) -> Optional[str]:
    """Extrae el día mencionado usando IA."""
    if not texto:
        return None

    dia_previo = conv_state.get("dia_propuesto") if conv_state and not current_turn_only else None
    current_turn_rule = (
        "No tomes una fecha negada como elegida. Si menciona alternativas sin elegir "
        "una fecha o no indica día en el mensaje actual, devolvé null. "
        "No completes desde una pregunta anterior.\n\n"
    ) if current_turn_only else ""
    hoy = datetime.datetime.now(TIMEZONE).date()
    texto_lower = str(texto).strip().lower()
    dia_relativo_contextual = resolver_fecha_admin_desde_mensaje(texto_lower)

    match_fecha_texto = re.search(r"\b(\d{1,2})\s+de\s+([a-záéíóúñ]+)\b", texto_lower)
    if not current_turn_only and match_fecha_texto and MESES_ES.get(match_fecha_texto.group(2)):
        dia_texto = f"{int(match_fecha_texto.group(1))} de {match_fecha_texto.group(2)}"
        print(f"   📅 [extraer_dia_local] '{texto[:40]}' → {dia_texto}")
        return dia_texto

    match_fecha_num = re.search(r"\b(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?\b", texto_lower)
    if not current_turn_only and match_fecha_num:
        dia_texto = match_fecha_num.group(0)
        print(f"   📅 [extraer_dia_local] '{texto[:40]}' → {dia_texto}")
        return dia_texto

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un extractor de días para reservas de canchas en Argentina.\n\n"
                        f"Hoy es {hoy.strftime('%A %d/%m')}.\n\n"
                        "Extraé el DÍA que el usuario quiere reservar.\n\n"
                        f"{current_turn_rule}"
                        "Valores posibles:\n"
                        "- 'hoy', 'mañana', 'pasado mañana'\n"
                        "- 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'\n"
                        "- fechas naturales como '22 de junio', '2/6', '22/06' o '22/06/2026'\n"
                        "- null si no menciona día\n\n"
                        "Si el usuario menciona una fecha natural, devolvela como la dijo de forma normalizada "
                        "(ej: '22 de junio').\n\n"
                        "Respondé SOLO JSON: {\"dia\": \"valor o null\", \"razon\": \"breve\"}"
                    )
                },
                {"role": "user", "content": f"Mensaje: \"{texto}\"\nDía previo en conversación: {dia_previo or 'ninguno'}"}
            ],
            temperature=0.0,
            max_tokens=120,
            response_format={"type": "json_object"}
        )
        register_cost(resp)

        raw = resp.choices[0].message.content.strip()
        result = json.loads(raw)
        dia = result.get("dia")

        if dia and dia != "null":
            if dia_relativo_contextual and not current_turn_only:
                dia_resuelto_ia = resolver_fecha(dia)
                dia_resuelto_contextual = resolver_fecha(dia_relativo_contextual)
                if _parse_fecha_row(dia_resuelto_ia) != _parse_fecha_row(dia_resuelto_contextual):
                    print(
                        f"   📅 [extraer_dia_con_ia] Segunda lectura fecha: {dia} -> {dia_relativo_contextual} "
                        f"según datetime actual"
                    )
                    return dia_relativo_contextual
            print(f"   📅 [extraer_dia_con_ia] '{texto[:40]}' → {dia}")
            return dia

        return None

    except Exception as e:
        print(f"   ⚠️ [extraer_dia_con_ia] Error: {e}")
        return None


# ================================
# MODIFICAR analyze_message_with_context (REEMPLAZAR la función completa)
# ================================

async def analyze_message_with_context(ultimo_mensaje: str, conv_state: Dict, prospecto: Dict, telefono: str = None) -> Dict:
    """
    MODIFICADA: Usa IA para analizar el mensaje + extracción específica de hora con IA.
    Ahora pasa el contexto de conversación a extraer_hora_de_texto para desambiguar.

    🔧 CORREGIDO: Ahora extrae la cancha PASANDO EL CONTEXTO para que entienda que 
    "la 2" es respuesta a la pregunta "¿Cuál preferís?"

    🔧 FIX CLAUDE: Agregado mapeo de "coordinacion_confirmada" → "confirmado"
    🔧 FIX CLAUDE: Usa dia_efectivo y hora_efectiva combinando con estado
    """
    # 🔧 PASO 1: Extraer hora específica con IA (PASANDO EL CONTEXTO para desambiguar)
    # Esto es CRÍTICO para diferenciar "la 1" (cancha) de "a las 1" (hora)
    hora_extraida = await extraer_hora_de_texto(ultimo_mensaje, conv_state)
    if hora_extraida:
        print(f"   🕒 [analyze_message] Hora detectada por extraer_hora_de_texto: {hora_extraida}")
    else:
        print(f"   🏟️ [analyze_message] extraer_hora_de_texto determinó que NO es hora")

    dia_extraido = await extraer_dia_con_ia(ultimo_mensaje, conv_state)

    # 🔧 PASO 2: Extraer cancha específica con IA (PASANDO EL CONTEXTO)
    # Esto es CRÍTICO para detectar "la 2" como cancha cuando el agente preguntó "¿Cuál preferís?"
    cancha_extraida = extraer_cancha_de_mensaje(ultimo_mensaje, conv_state)
    if cancha_extraida:
        print(f"   🏟️ [analyze_message] Cancha detectada por extraer_cancha_de_mensaje: {cancha_extraida}")
        # Actualizar estado inmediatamente
        update_conversation_state(telefono or "unknown", cancha_propuesta=cancha_extraida)

    # PASO 3: Usar la IA agéntica para analizar el resto
    analysis = await agente_analizar(ultimo_mensaje, conv_state, prospecto, telefono or "unknown")

    tipo = analysis.get("tipo", "necesita_contexto")
    dia = analysis.get("dia")
    hora = analysis.get("hora")
    cancha = analysis.get("cancha")
    duracion = normalizar_duracion_horas(
        analysis.get("duracion_detectada") or extraer_duracion_de_texto(ultimo_mensaje),
        conv_state.get("duracion_propuesta") or DEFAULT_TURN_DURATION_HOURS
    )
    respuesta = analysis.get("respuesta", "")

    # 🔧 PRIORIZAR cancha_extraida sobre lo que detectó agente_analizar
    if cancha_extraida:
        cancha = cancha_extraida
        print(f"   🔧 [analyze_message] Usando cancha extraída: {cancha}")

    if dia_extraido and not dia:
        dia = dia_extraido
        print(f"   🔧 [analyze_message] Forzando dia_detectado = {dia_extraido}")

    # 🔧 PASO 4: SOBREESCRIBIR la hora con lo que detectó extraer_hora_de_texto (si es hora)
    # Si extraer_hora_de_texto devolvió None, significa que el mensaje NO contiene una hora
    # (por ejemplo, "la 1" cuando se elige cancha)
    if hora_extraida:
        hora = hora_extraida
        print(f"   🔧 [analyze_message] Forzando hora_detectada = {hora_extraida} (sobreescribe IA)")
        # Si la IA había puesto tipo "lista_horarios" pero tenemos hora específica, cambiar a "consulta"
        if tipo == "lista_horarios" and hora_extraida:
            tipo = "consulta"
            print(f"   🔧 [analyze_message] Cambiando tipo de 'lista_horarios' a 'consulta' porque hay hora específica")
    else:
        # Si extraer_hora_de_texto devolvió None pero la IA detectó hora, puede ser falsa positiva
        # (ej: "la 1" detectado como 01:00 por la IA)
        if hora and tipo in ("confirmacion_sin_hora", "lista_horarios"):
            # Esto es una señal de que la IA confundió cancha con hora
            print(f"   🔧 [analyze_message] IA detectó hora {hora} pero extraer_hora_de_texto dijo None → probablemente es CANCHA, no hora")
            hora = None
            # Si además hay una cancha detectada, priorizar la cancha
            if not cancha and cancha_extraida:
                cancha = cancha_extraida
                print(f"   🔧 [analyze_message] Usando cancha extraída: {cancha}")

    # 🔧 NUEVO: Si es saludo_inicial, devolver respuesta DIRECTA sin procesar horarios
    if tipo == "saludo_inicial":
        return {
            "tipo": "respuesta_directa",
            "dia_detectado": None,
            "hora_detectada": None,
            "cancha_detectada": None,
            "nueva_fase": "inicial",
            "razon": "Primer contacto - saludo inicial",
            "respuesta": respuesta
        }

    # 🔧 VALIDACIÓN ADICIONAL: Si hay cancha_extraida pero no cancha en analysis, usar la extraída
    if cancha_extraida and not cancha:
        cancha = cancha_extraida
        print(f"   🔧 [analyze_message] Asignando cancha extraída a cancha_detectada: {cancha}")

    # ============================================================
    # 🔧 FIX CLAUDE: MAPEO COMPLETO CON "coordinacion_confirmada"
    # ============================================================
    tipo_map = {
        "consulta": "coordinacion_nueva",
        "confirmacion": "confirmado",
        "coordinacion_confirmada": "confirmado",  # 🆕 ¡Este es el fix crítico!
        "cancelacion": "cancelacion",
        "reprogramacion": "reprogramacion",
        "informacion": "explicacion_pedida",
        "derivar_humano": "derivar_humano",
        "necesita_contexto": "necesita_contexto",
        "lista_horarios": "coordinacion_nueva",
        "confirmacion_sin_hora": "confirmado",
        "renegociacion": "coordinacion_nueva",
        "coordinacion_propuesta": "coordinacion_propuesta",
        "coordinacion_nueva": "coordinacion_nueva",
    }

    # ============================================================
    # 🔧 FIX CLAUDE: USAR VALORES EFECTIVOS (COMBINANDO CON ESTADO)
    # ============================================================
    # Determinar nueva fase usando valores efectivos (del mensaje + estado)
    nueva_fase = conv_state.get("fase", "inicial")

    # 🔧 CORRECCIÓN CLAUDE: Usar dia_efectivo y hora_efectiva
    dia_efectivo = dia or conv_state.get("dia_propuesto")
    hora_efectiva = hora or conv_state.get("hora_propuesta")
    tiene_dia_hora_sin_cancha = bool(dia and hora_es_valida(hora) and not cancha)

    # 🔧 CORRECCIÓN CLAUDE: El chequeo de confirmación usa valores efectivos
    if cancha and hora_es_valida(hora_efectiva) and dia_efectivo:
        # El usuario ya eligió cancha, hora y día → podemos confirmar
        dia = dia_efectivo
        hora = hora_efectiva
        nueva_fase = "coordinacion_confirmada"
        tipo_efectivo = "confirmado"
        print(f"   🔧 [analyze_message] Usuario tiene cancha={cancha}, hora={hora_efectiva}, dia={dia_efectivo} → confirmando")
    elif tipo in ("consulta", "lista_horarios"):
        nueva_fase = "coordinacion_propuesta"
        tipo_efectivo = tipo_map.get(tipo, tipo)
    elif tipo in ("confirmacion", "confirmacion_sin_hora"):
        if tiene_dia_hora_sin_cancha:
            nueva_fase = "coordinacion_propuesta"
            tipo_efectivo = "coordinacion_nueva"
            if respuesta_es_placeholder_verificacion(respuesta):
                respuesta = ""
            print(
                "   🔧 [analyze_message] Tiene día+hora pero no cancha; "
                "lo trato como consulta de disponibilidad, no como reserva confirmada"
            )
        else:
            nueva_fase = "coordinacion_confirmada"
            tipo_efectivo = "confirmado"
    else:
        # Si el tipo ya está en el mapa, usarlo
        tipo_efectivo = tipo_map.get(tipo, tipo)
        if tipo_efectivo == "confirmado":
            nueva_fase = "coordinacion_confirmada"
        elif tipo_efectivo in ("coordinacion_nueva", "coordinacion_propuesta"):
            nueva_fase = "coordinacion_propuesta"

    # 🔧 Si hay hora detectada pero tipo sigue siendo "lista_horarios", forzar a "coordinacion_nueva"
    if hora and tipo == "lista_horarios":
        tipo_efectivo = "coordinacion_nueva"
        print(f"   🔧 [analyze_message] Forzando tipo de 'lista_horarios' a 'coordinacion_nueva' porque hay hora: {hora}")

    if tipo_efectivo == "confirmado" and tiene_dia_hora_sin_cancha:
        tipo_efectivo = "coordinacion_nueva"
        nueva_fase = "coordinacion_propuesta"
        if respuesta_es_placeholder_verificacion(respuesta):
            respuesta = ""
        print(
            "   🔧 [analyze_message] Corrección final: no confirmo una reserva "
            "con día+hora si todavía falta elegir cancha"
        )

    # 🔧 LOG FINAL para debugging
    print(f"   📊 [analyze_message] Resultado final: tipo={tipo_efectivo}, dia={dia}, hora={hora}, cancha={cancha}")

    return {
        "tipo": tipo_efectivo,
        "dia_detectado": dia,
        "hora_detectada": hora,
        "cancha_detectada": cancha,
        "duracion_detectada": duracion,
        "nueva_fase": nueva_fase,
        "razon": f"IA decidió: {tipo} | Hora extraída: {hora_extraida or 'ninguna'} | Cancha extraída: {cancha_extraida or 'ninguna'}",
        "respuesta": respuesta
    }


# ================================
# FUNCIÓN: ENVIAR MENSAJE
# ================================
async def _resolve_whatsapp_message_composer(page, timeout_ms: int = 30000):
    """Encuentra el compositor visible sin depender de un data-tab inestable."""
    selectors = [
        'footer div[contenteditable="true"][role="textbox"]',
        'footer div[contenteditable="true"][data-tab]',
        'footer div[contenteditable="true"]',
        'div[contenteditable="true"][role="textbox"][data-tab]',
        'div[contenteditable="true"][data-tab="10"]',
    ]
    per_selector_timeout = max(1000, int(timeout_ms / len(selectors)))
    errors = []
    for selector in selectors:
        try:
            locator = page.locator(selector).last
            await locator.wait_for(state="visible", timeout=per_selector_timeout)
            if await locator.is_visible():
                print(f"   🧭 [Enviar] Compositor detectado con selector adaptable: {selector}")
                return locator
        except Exception as exc:
            errors.append(f"{selector}: {str(exc)[:120]}")
    raise RuntimeError(
        "No se encontró un compositor visible de WhatsApp. "
        + " | ".join(errors[-2:])
    )


async def send_message(page, text, *, escape_on_error: bool = True):
    try:
        text = str(text or "").replace("\r\n", "\n").replace("\r", "\n")
        # V207 — última frontera común de salida. Ningún marcador interno de
        # composición puede llegar a WhatsApp, aunque un executor nuevo omita
        # accidentalmente su limpiador específico.
        text = _canonical_v207_customer_safe_response(text)
        # Última barrera de presentación: 24:00 puede existir como límite
        # matemático interno, pero una hora civil enviada al usuario es 00:00.
        text = re.sub(r"(?<!\d)24:00(?!\d)", "00:00", text)
        # Limpiar el textarea antes de escribir
        box = await _resolve_whatsapp_message_composer(page)
        await box.click()
        await page.keyboard.press("Control+A")
        await page.keyboard.press("Backspace")

        pegado_ok = False
        try:
            await page.context.grant_permissions(
                ["clipboard-read", "clipboard-write"],
                origin="https://web.whatsapp.com"
            )
            await page.evaluate("texto => navigator.clipboard.writeText(texto)", text)
            await page.keyboard.press("Control+V")
            await asyncio.sleep(0.2)
            pegado_ok = True
            print("   📋 [Enviar] Texto pegado desde clipboard para preservar formato")
        except Exception as paste_error:
            print(f"   ⚠️ [Enviar] No pude pegar desde clipboard, uso tipeo: {paste_error}")

        if not pegado_ok:
            # IMPORTANTE: Reemplazar saltos de línea con Shift+Enter para mantener el formato
            # pero evitar que se envíe como múltiples mensajes.
            lines = text.split('\n')
            for i, line in enumerate(lines):
                await box.type(line, delay=3)
                if i < len(lines) - 1:
                    # Usar Shift+Enter para nueva línea dentro del mismo mensaje
                    await page.keyboard.down('Shift')
                    await page.keyboard.press('Enter')
                    await page.keyboard.up('Shift')

        # Esperar un momento antes de enviar
        await asyncio.sleep(0.3)

        # Enviar el mensaje completo
        await page.keyboard.press("Enter")
        await asyncio.sleep(0.5)
        print("✅ Mensaje enviado (completo)")

        await asyncio.sleep(1)
        return True

    except Exception as e:
        print(f"❌ [Enviar] Error: {e}")
        if escape_on_error:
            await escape_chat(page)
        return False


async def ejecutar_notificaciones_post_respuesta_agent_v2(
    page,
    agent_result: Dict[str, Any],
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
) -> Dict[str, int]:
    """Encola pendientes y ejecuta handoffs sólo después de responder al cliente."""
    attempted = 0
    delivered = 0
    failed = 0
    queued = 0

    pending_alerts = enqueue_pending_booking_admin_alerts_from_agent_result(
        agent_result,
        telefono,
        prospecto,
    )
    pending_count = int(pending_alerts.get("reservations") or 0)
    if pending_count:
        attempted += pending_count
        queued += len(pending_alerts.get("delivery_ids") or [])
        print(
            "   ✅ [AgentV2 POST-RESPONSE] "
            f"{pending_count} reserva(s) pendiente(s) encolada(s) para admins"
        )

    # Las pendientes reprogramadas no deben reutilizar la alerta de alta.
    # Las firmes siguen siendo responsabilidad del scheduler integrado.
    reprogram_alerts = enqueue_pending_reprogram_admin_alerts_from_agent_result(
        agent_result,
        telefono,
        prospecto,
    )
    reprogram_count = int(reprogram_alerts.get("reservations") or 0)
    if reprogram_count:
        attempted += reprogram_count
        queued += len(reprogram_alerts.get("delivery_ids") or [])
        print(
            "   🔄 [AgentV2 POST-RESPONSE] "
            f"{reprogram_count} reprogramación(es) pendiente(s) encolada(s) para admins"
        )

    for observation in agent_result.get("observations") or []:
        if observation.get("tool") != "solicitar_handoff_humano":
            continue
        data = observation.get("data") or {}
        if not data.get("notification_pending"):
            continue

        attempted += 1
        tipo = str(data.get("tipo") or "humano")
        mensaje_usuario = str(data.get("mensaje_usuario") or "")
        if tipo == "evento_especial":
            notified = await enviar_alerta_evento_dia_completo_admin(
                page,
                mensaje_usuario,
                telefono,
                prospecto,
                case_id=data.get("case_id"),
                reason=str(data.get("reason") or "evento_especial"),
            )
        else:
            notified = await enviar_alerta_humano_admin(
                page,
                mensaje_usuario,
                telefono,
                prospecto,
                reason=str(data.get("reason") or ""),
                case_id=data.get("case_id"),
            )

        data["notification_pending"] = False
        data["notification_attempted"] = True
        data["admin_notified"] = notified is True
        if notified is True:
            delivered += 1
            print("   ✅ [AgentV2 POST-RESPONSE] alerta al encargado enviada")
        else:
            failed += 1
            observation["status"] = "needs_human_review"
            print(
                "   ⚠️ [AgentV2 POST-RESPONSE] respuesta al cliente enviada, "
                "pero falló la alerta al encargado"
            )

    return {
        "attempted": attempted,
        "delivered": delivered,
        "queued": queued,
        "failed": failed,
    }


async def enviar_respuesta_agent_v2_antes_de_alertas(
    page,
    response: str,
    agent_result: Dict[str, Any],
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
) -> bool:
    """Entrega cliente/admin respetando el contrato de handoff silencioso."""

    silent_handoff = any(
        isinstance(observation, dict)
        and observation.get("tool") == "solicitar_handoff_humano"
        and (
            ((observation.get("data") or {}).get("customer_response_suppressed") is True)
            or ((observation.get("data") or {}).get("silent_handoff") is True)
            or str((observation.get("data") or {}).get("delivery_policy") or "")
            == "suppress_customer"
            or (
                (observation.get("data") or {}).get("safe_exit_fallback") is True
                and str((observation.get("data") or {}).get("reason") or "")
                .startswith("universal_safe_exit:")
            )
        )
        for observation in (agent_result.get("observations") or [])
    )
    if silent_handoff:
        agent_result["customer_response_suppressed"] = True
        agent_result["delivery_policy"] = "suppress_customer"
        agent_result["silent_handoff"] = True
        print(
            "   🤫 [AgentV2 SILENT HANDOFF] "+
            "respuesta cliente suprimida; notifico sólo a números autorizados"
        )
        await ejecutar_notificaciones_post_respuesta_agent_v2(
            page,
            agent_result,
            telefono,
            prospecto,
        )
        # False evita que el caller persista como enviado un texto que nunca se
        # mostró al cliente. El caso y las alertas ya quedaron procesados.
        return False

    # Snapshot tomado por read_user_messages_with_pending_media antes de que
    # AgentV2 trabajara. No llamamos read_user_messages acá porque resetearía
    # ese baseline justo antes de compararlo.
    baseline_meta = list(_LAST_READ_USER_MESSAGE_META or [])

    def signature(item: Dict[str, Any]) -> Tuple[Any, ...]:
        message_id = str(item.get("message_id") or "").strip()
        media_type = str(item.get("media_type") or "ninguno").strip().lower()
        if message_id:
            return ("id", message_id, media_type)
        text = "" if media_type in {"imagen", "audio"} else str(item.get("texto") or "").strip()
        return ("fallback", item.get("posicion"), item.get("minute_of_day"), media_type, text)

    async def pending_meta_now() -> List[Dict[str, Any]]:
        selector = await get_best_bubble_selector(page, "all")
        bubbles = page.locator(selector)
        total = await bubbles.count()
        if not total:
            selector = await get_best_bubble_selector(page, "all", force_refresh=True)
            bubbles = page.locator(selector)
            total = await bubbles.count()
        last_ours = -1
        for i in range(total):
            try:
                classes = await bubbles.nth(i).get_attribute("class") or ""
                is_user = _bubble_is_user_from_classes(classes)
                is_ours = _bubble_is_ours_from_classes(classes)
                if is_ours and not is_user:
                    last_ours = i
            except Exception:
                continue
        records = []
        for i in range(last_ours + 1, total):
            bubble = bubbles.nth(i)
            try:
                classes = await bubble.get_attribute("class") or ""
                is_user = _bubble_is_user_from_classes(classes)
                is_ours = _bubble_is_ours_from_classes(classes)
                if not is_user or is_ours:
                    continue
                raw = str(await bubble.inner_text() or "")
                try:
                    media_type = await _detectar_tipo_media_bubble(bubble)
                except Exception:
                    media_type = "ninguno"
                text = re.sub(r"\n?\d{1,2}:\d{2}\s*$", "", raw.strip()).strip()
                if media_type == "imagen":
                    text = "[IMAGEN_ENVIADA]"
                elif media_type == "audio" and not text:
                    text = "[AUDIO_ENVIADO]"
                if not text and media_type not in {"imagen", "audio"}:
                    continue
                message_id = ""
                for attr in ("data-id", "data-message-id", "id"):
                    message_id = str(await bubble.get_attribute(attr) or "").strip()
                    if message_id:
                        break
                pre_plain = await bubble.get_attribute("data-pre-plain-text") or ""
                records.append({
                    "texto": text, "posicion": i, "media_type": media_type,
                    "message_id": message_id,
                    "minute_of_day": _whatsapp_minute_from_timestamp_text(pre_plain)
                    or _whatsapp_minute_from_timestamp_text(raw),
                })
            except Exception as exc:
                print(f"   ⚠️ [AgentV2 PRE-SEND BARRIER] burbuja #{i}: {exc}")
        return records

    # Pequeña ventana para absorber texto + adjunto que WhatsApp entrega en dos
    # pasos consecutivos.
    await asyncio.sleep(0.35)
    try:
        if await is_user_typing(page):
            _mark_reactive_handoff(telefono or "", "agent_v2_pre_send_user_typing")
            print("   🛑 [AgentV2 PRE-SEND BARRIER] usuario escribiendo → cancelo respuesta vieja")
            return False
        if baseline_meta:
            current_meta = await pending_meta_now()
            baseline = {signature(item) for item in baseline_meta}
            current = {signature(item) for item in current_meta}
            if current - baseline or len(current_meta) > len(baseline_meta):
                _mark_reactive_handoff(telefono or "", "agent_v2_pre_send_new_user_message")
                print("   🛑 [AgentV2 PRE-SEND BARRIER] nueva burbuja durante el razonamiento → no envío respuesta vieja")
                registrar_metrica_operativa(
                    "agent_v2_pre_send_barrier_blocked",
                    {"telefono": telefono, "baseline_count": len(baseline_meta),
                     "current_count": len(current_meta), "reason": "new_user_message"},
                )
                return False
    except Exception as exc:
        # El fallo del inspector no debe inmovilizar las conversaciones.
        print(f"   ⚠️ [AgentV2 PRE-SEND BARRIER] no pude validar inbox: {exc} → continúo")

    customer_sent = await send_message(page, response)
    if customer_sent is not True:
        print(
            "   ⚠️ [AgentV2 CUSTOMER-FIRST] no se confirmó la respuesta al cliente; "
            "omito alertas posteriores"
        )
        return False

    await ejecutar_notificaciones_post_respuesta_agent_v2(
        page,
        agent_result,
        telefono,
        prospecto,
    )
    return True


async def send_file_to_current_chat(page, file_path: str, title: str = "") -> bool:
    """Adjunta un archivo en el chat actualmente abierto de WhatsApp Web."""
    if not file_path or not os.path.exists(file_path):
        print(f"⚠️ [Archivo] No existe el archivo para enviar: {file_path}")
        return False

    try:
        if title:
            title_sent = await send_message(page, title, escape_on_error=False)
            if title_sent is not True:
                print("⚠️ [Archivo] No se pudo enviar el título; pospongo el adjunto.")
                return False
            await asyncio.sleep(1)

        attach_button = None
        for selector in [
            'button[aria-label="Adjuntar"]',
            'button[aria-label="Attach"]',
            'div[aria-label="Adjuntar"]',
            'div[aria-label="Attach"]',
            'span[data-icon="plus-rounded"]',
            'span[data-icon="plus"]',
            'button[title="Adjuntar"]',
            'button[title="Attach"]',
        ]:
            locator = page.locator(selector).first
            if await locator.count() > 0 and await locator.is_visible():
                attach_button = locator
                break

        if not attach_button:
            print("⚠️ [Archivo] No encontré el botón Adjuntar.")
            return False

        await attach_button.click()
        await asyncio.sleep(1.5)

        document_option = None
        for selector in [
            'li[data-testid="mi-attach-document"]',
            'span[data-icon="document-filled-refreshed"]',
            'span[data-icon="document"]',
            'button[aria-label="Documento"]',
            'button[aria-label="Document"]',
            '[role="menuitem"]:has-text("Documento")',
            '[role="menuitem"]:has-text("Document")',
        ]:
            locator = page.locator(selector)
            if await locator.count() > 0:
                document_option = locator.first
                break

        if not document_option:
            # WhatsApp suele mantener inputs ocultos aunque cambie los textos del menú.
            # Elegimos uno que acepte documentos y evitamos los exclusivos de imágenes.
            inputs = page.locator('input[type="file"]')
            for index in range(await inputs.count()):
                file_input = inputs.nth(index)
                accept = str(await file_input.get_attribute("accept") or "").lower()
                image_only = (
                    accept
                    and "image" in accept
                    and "application" not in accept
                    and "*" not in accept
                )
                if image_only:
                    continue
                try:
                    await file_input.set_input_files(os.path.abspath(file_path))
                    await asyncio.sleep(1.5)
                    await page.keyboard.press("Enter")
                    await asyncio.sleep(3)
                    print(f"✅ Archivo enviado mediante input: {file_path}")
                    return True
                except Exception:
                    continue
            await page.keyboard.press("Escape")
            print("⚠️ [Archivo] No encontré una opción válida para adjuntar documentos.")
            return False

        async with page.expect_file_chooser() as fc_info:
            await document_option.click()

        file_chooser = await fc_info.value
        await file_chooser.set_files(os.path.abspath(file_path))
        await asyncio.sleep(1)
        await page.keyboard.press("Enter")
        await asyncio.sleep(3)
        print(f"✅ Archivo enviado: {file_path}")
        return True

    except Exception as e:
        print(f"❌ [Archivo] Error enviando archivo: {e}")
        try:
            await page.keyboard.press("Escape")
        except Exception:
            pass
        return False


# ================================
# FUNCIÓN: CLICK EN "NO LEÍDOS"
# ================================
async def click_no_leidos(page):
    try:
        business_selectors = [
            "button[aria-label='No leídos']",
            "button[aria-label='No leidos']",
            "button[aria-label='Unread']",
            "button:has-text('No leídos')",
            "button:has-text('No leidos')",
            "div[role='tab']:has-text('No leídos')",
            "div[role='tab']:has-text('No leidos')",
            "[data-testid='chat-list-filter-unread']",
        ]

        for selector in business_selectors:
            try:
                item = page.locator(selector).first
                if await item.count() > 0 and await item.is_visible():
                    await item.click()
                    await asyncio.sleep(1)
                    print(f"✅ Click en 'No leídos' (selector semántico: {selector})")
                    return True
            except Exception as e:
                continue

        standard_selectors = [
            "xpath=//span[contains(text(), 'No leídos')]",
            "xpath=//span[contains(text(), 'No leidos')]",
            "button:has-text('No leídos')",
            "button:has-text('No leidos')",
            "span:has-text('No leídos')",
            "span:has-text('No leidos')",
            "xpath=//*[@role='button' or @role='tab'][.//*[contains(normalize-space(.), 'No leídos') or contains(normalize-space(.), 'No leidos')]]",
        ]

        for selector in standard_selectors:
            try:
                item = page.locator(selector).first
                if await item.count() > 0 and await item.is_visible():
                    await item.click()
                    await asyncio.sleep(1)
                    print("✅ Click en 'No leídos' (WhatsApp Web)")
                    return True
            except Exception as e:
                continue

        try:
            buttons = await page.locator("button").all()
            for button in buttons:
                try:
                    text = await button.inner_text()
                    if "No leídos" in text or "No leidos" in text:
                        await button.click()
                        await asyncio.sleep(1)
                        print(f"✅ Click en 'No leídos' (fallback): {text[:30]}")
                        return True
                except:
                    continue
        except:
            pass

        print("⚠️ No se encontró el botón 'No leídos'")
        return False

    except Exception as e:
        print(f"⚠️ [No leídos] Error: {e}")
        return False

# ================================
# FUNCIÓN: CLICK EN PRIMER CHAT
# ================================
async def click_first_chat(page):
    try:
        await asyncio.sleep(1)

        chat_selectors = [
            "#pane-side div[role='listitem']",
            "#pane-side div[role='row']",
            "#pane-side [data-testid='cell-frame-container']",
            "#pane-side [data-testid='chat-list-item']",
            "div[data-testid='chat-list'] [role='listitem']",
            "div[data-testid='chat-list'] [role='row']",
            "div[class*='_ak8l']",
        ]

        for selector in chat_selectors:
            try:
                candidates = page.locator(selector)
                for index in range(min(await candidates.count(), 12)):
                    chat = candidates.nth(index)
                    if not await chat.is_visible():
                        continue
                    inner_text = (await chat.inner_text()).strip()
                    if not inner_text:
                        continue
                    await chat.click()
                    await asyncio.sleep(1.2)
                    print(f"✅ Click en primer chat: {inner_text[:50]}...")
                    return True
            except Exception as e:
                continue

        # If WhatsApp changed the row wrapper again, anchor the search on the
        # unread badge and climb to the nearest semantic row.  This also works
        # when the visual filter was slow to settle.
        unread_badges = [
            "#pane-side [aria-label*='mensaje no leído']",
            "#pane-side [aria-label*='mensajes no leídos']",
            "#pane-side [aria-label*='unread message']",
            "#pane-side [data-testid='icon-unread-count']",
        ]
        for selector in unread_badges:
            try:
                badge = page.locator(selector).first
                if await badge.count() == 0 or not await badge.is_visible():
                    continue
                row = badge.locator("xpath=ancestor::*[@role='listitem' or @role='row'][1]")
                if await row.count() == 0:
                    row = badge.locator("xpath=ancestor::div[@tabindex='-1'][1]")
                if await row.count() > 0 and await row.is_visible():
                    inner_text = (await row.inner_text()).strip()
                    await row.click()
                    await asyncio.sleep(1.2)
                    print(f"✅ Click en chat no leído (badge): {inner_text[:50]}...")
                    return True
            except Exception:
                continue

        xpath_selectors = [
            "//*[@id='pane-side']//*[@role='listitem']",
            "//*[@id='pane-side']//*[@role='row']",
            "//*[@id='pane-side']//*[@data-testid='cell-frame-container']",
            "//div[@data-testid='chat-list']//*[@data-testid='chat-list-item']",
            "//div[contains(@class, '_ak8l')]",
        ]

        for xpath in xpath_selectors:
            try:
                chat = page.locator(f"xpath={xpath}").first
                if await chat.count() > 0 and await chat.is_visible():
                    inner_text = await chat.inner_text()
                    if inner_text and len(inner_text.strip()) > 0:
                        await chat.click()
                        await asyncio.sleep(2)
                        print(f"✅ Click en primer chat (XPath): {inner_text[:50]}...")
                        return True
            except:
                continue

        print("⚠️ No se encontró ningún chat para clickear")
        await escape_chat(page)
        await click_todos(page)  # Volver a filtro 'Todos'
        return False

    except Exception as e:
        print(f"❌ [Click Chat] Error: {e}")
        return False

# ================================
# FUNCIÓN: GUARDAR CONTACTO/RESERVA EN CSV
# ================================
def save_to_csv(prospect_data):
    try:
        if prospect_data.get("intencion") not in ("RESERVA", "INTERESADO"):
            return False

        now = datetime.datetime.now()
        data = {
            "fecha_hora": now.strftime("%Y-%m-%d %H:%M:%S"),
            "nombre": prospect_data.get("nombre", "No especificado"),
            "telefono": prospect_data.get("telefono", ""),
            "website": prospect_data.get("website", "No disponible"),
            "whatsapp_link": prospect_data.get("whatsapp_link", ""),
            "estado": "Turno reservado",
            "mensaje_personalizado": prospect_data.get("razon", ""),
            "contactado": "si",
            CLIENTE_FIELD: normalizar_es_cliente(prospect_data.get("es_cliente", CLIENTE_NO)),
        }

        fieldnames = NEGOCIOS_FIELDNAMES

        file_exists = os.path.exists(CSV_FILENAME)
        with open(CSV_FILENAME, 'a', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
            if not file_exists:
                writer.writeheader()
            writer.writerow(data)

        print(f"✅ [CSV] Guardado: {data['nombre']}")
        return True
    except Exception as e:
        print(f"⚠️ [CSV] Error: {e}")
        return False

async def escape_chat(page):
    try:
        await page.keyboard.press("Escape")
        await asyncio.sleep(0.5)
        print("⎋ [ESC] Chat escapado")
    except Exception as e:
        print(f"⚠️ [ESC] Error: {e}")


def reservar_turno_en_calendario(
    telefono: str,
    prospecto: Dict,
    dia_raw: str,
    hora_final: str,
    cancha: str = None,
    estado_reserva: str = BOOKING_STATUS_RESERVED,
    senia_estado: str = "",
    senia_monto: str = "",
    duracion_horas: float = None,
    con_quincho: bool = False,
    quincho: str = "",
    quincho_hora_inicio: str = "",
    quincho_duracion_horas: float = None,
    es_reprogramacion: bool = False,
    es_nuevo_turno: bool = False  # 🆕 NUEVO PARÁMETRO PARA DISTINGUIR NUEVO TURNO
) -> Dict:
    """
    Reserva un turno en el calendario.

    🆕 es_reprogramacion: Si es True, preserva el estado de seña pagada de la reserva existente.
    🆕 es_nuevo_turno: Si es True (cuando el usuario dice "nuevo turno" aparte), 
                       NO hereda la seña pagada, fuerza estado pendiente.
    """
    _refresh_runtime_config_if_changed(reason="before_current_booking")
    dia_raw = normalizar_valor_nullable(dia_raw)
    duracion_horas = normalizar_duracion_horas(duracion_horas)
    con_quincho = bool(CON_QUINCHO and con_quincho)
    quincho = normalizar_nombre_quincho(quincho) if con_quincho else ""
    # V110 — default global del addon:
    # si no se indicó otro horario, el quincho comienza cuando termina la cancha.
    quincho_duracion_horas = (
        normalizar_duracion_horas(quincho_duracion_horas, 1.0)
        if con_quincho else 0
    )
    quincho_default_start = (
        _quincho_default_start_after_court(hora_final, duracion_horas)
        if con_quincho else ""
    )
    quincho_hora_inicio = (
        normalizar_hora_detectada(
            quincho_hora_inicio or quincho_default_start
        )
        if con_quincho else ""
    )
    quincho_hora_fin = hora_fin_bloque(
        quincho_hora_inicio,
        quincho_duracion_horas,
    ) if con_quincho else ""
    precio_cancha_total = calcular_precio_total(duracion_horas)
    quincho_precio_hora = precio_hora_quincho(quincho) if con_quincho else 0
    quincho_precio_total = calcular_precio_quincho_total(quincho, quincho_duracion_horas) if con_quincho else 0
    precio_total = precio_cancha_total + quincho_precio_total
    senia_valor_configurado = _senia_para_total(precio_total)
    senia_monto_configurado = _monto_humano(senia_valor_configurado)
    senia_valor_int = (
        _monto_a_int(senia_monto)
        if senia_estado == "pagada" and _monto_a_int(senia_monto) is not None
        else senia_valor_configurado
    )
    monto_pendiente = calcular_monto_pendiente(precio_total, senia_valor_int)
    if not dia_raw:
        print("   ⚠️ [CALENDARIO] Intento de reserva sin día. No se escribe CSV.")
        return {
            "ok": False,
            "dia": None,
            "hora": hora_final,
            "cancha": cancha,
            "respuesta": "Me falta el día del turno. ¿Para qué día lo querés reservar?"
        }

    dia_resuelto = resolver_fecha(dia_raw)
    if not normalizar_valor_nullable(dia_resuelto):
        print(f"   ⚠️ [CALENDARIO] No pude resolver fecha para '{dia_raw}'. No se escribe CSV.")
        return {
            "ok": False,
            "dia": None,
            "hora": hora_final,
            "cancha": cancha,
            "respuesta": "Me falta confirmar el día del turno. ¿Para qué día lo querés reservar?"
        }

    if not validar_fecha_en_dias_atencion(dia_resuelto):
        print(f"   [CALENDARIO] Intento de reserva fuera de dias de atencion: {dia_resuelto}. No se escribe CSV.")
        alt_dia, alt_hora = calendario.proximo_slot_libre(dia_resuelto, hora_final, cancha=cancha)
        dia_fuera_msg = "Hoy no abrimos" if str(dia_raw or "").strip().lower() == "hoy" else "Ese dia no atendemos"
        return {
            "ok": False,
            "dia": dia_resuelto,
            "hora": hora_final,
            "cancha": cancha,
            "respuesta": (
                f"{dia_fuera_msg}. Estamos disponibles {descripcion_atencion_mensaje()}. "
                f"Queres reservar dentro de esos dias y horarios? Por ejemplo {alt_dia} a las {formatear_hora_para_mensaje(alt_hora)}."
            ),
            "motivo": "dia_fuera_de_atencion"
        }

    # ============================================================
    # 🔧 PASO 1: BUSCAR RESERVA EXISTENTE DEL CONTACTO
    # ============================================================
    hora_final = normalizar_hora_detectada(hora_final)
    if not hora_es_valida(hora_final) or not validar_hora_en_franja(hora_final):
        print(f"   ⚠️ [CALENDARIO] Intento de reserva fuera de franja: {hora_final}. No se escribe CSV.")
        return {
            "ok": False,
            "dia": dia_resuelto,
            "hora": hora_final,
            "cancha": cancha,
            "respuesta": (
                f"Ese horario esta fuera de nuestra franja de atencion "
                f"({descripcion_franjas_atencion_mensaje()}). ¿Que horario dentro de esa franja te sirve?"
            ),
            "motivo": "hora_fuera_de_franja"
        }

    minutos_para_turno = minutos_hasta_turno(dia_resuelto, hora_final)
    if MIN_BOOKING_NOTICE_MINUTES > 0 and minutos_para_turno is not None and minutos_para_turno < MIN_BOOKING_NOTICE_MINUTES:
        alt_dia, alt_hora = proximo_slot_reservable_con_anticipacion(
            dia_resuelto,
            hora_final,
            cancha=cancha,
            duracion_horas=duracion_horas,
        )
        if alt_dia and alt_hora:
            respuesta_anticipacion = (
                f"Para reservar necesito al menos {MIN_BOOKING_NOTICE_MINUTES // 60} horas de anticipacion. "
                f"El próximo horario reservable que encontré es {alt_dia} a las "
                f"{formatear_hora_para_mensaje(alt_hora)}. ¿Te sirve?"
            )
        else:
            respuesta_anticipacion = (
                f"Para reservar necesito al menos {MIN_BOOKING_NOTICE_MINUTES // 60} horas de anticipacion. "
                "Ese horario ya queda demasiado cerca. ¿Querés que te muestre los próximos horarios reservables?"
            )
        return {
            "ok": False,
            "dia": dia_resuelto,
            "hora": hora_final,
            "cancha": cancha,
            "respuesta": respuesta_anticipacion,
            "motivo": "anticipacion_insuficiente_reserva"
        }

    reserva_existente = calendario.obtener_reserva_por_telefono(telefono or "desconocido")
    if not reserva_existente and prospecto and prospecto.get("nombre"):
        reserva_existente = calendario.obtener_reserva_por_nombre(prospecto.get("nombre"))

    # También verificar por nombre si el teléfono es agendado
    if not reserva_existente and telefono and telefono.startswith("NOMBRE:"):
        nombre_contacto = telefono.replace("NOMBRE:", "").strip()
        reserva_existente = calendario.obtener_reserva_por_nombre(nombre_contacto)

    ya_tenia_senia_pagada = False
    monto_original = senia_monto_configurado

    # ============================================================
    # 🔧 PASO 2: DETECTAR SI ES UN SLOT QUE YA TIENE RESERVADO (mismo día, hora, cancha)
    # ============================================================
    if reserva_existente:
        misma_fecha = str(reserva_existente.get("fecha") or "").strip() == str(dia_resuelto or "").strip()
        misma_hora = str(reserva_existente.get("hora") or "").strip() == str(hora_final or "").strip()
        misma_cancha = not cancha or str(reserva_existente.get("cancha") or "").strip().lower() == str(cancha or "").strip().lower()

        if misma_fecha and misma_hora and misma_cancha:
            print("   ℹ️ [CALENDARIO] El contacto ya tiene ese mismo turno activo; no se duplica.")
            return {
                "ok": False,
                "dia": reserva_existente.get("fecha") or dia_resuelto,
                "hora": reserva_existente.get("hora") or hora_final,
                "cancha": reserva_existente.get("cancha") or cancha,
                "respuesta": respuesta_reserva_existente(reserva_existente),
                "motivo": "reserva_activa_existente",
                "reserva_existente": True
            }

    # ============================================================
    # 🔧 PASO 3: DETERMINAR EL ESTADO DE SEÑA SEGÚN EL TIPO DE OPERACIÓN
    # ============================================================

    # 🆕 CASO 1: NUEVO TURNO (aparte, no reprogramación)
    # El usuario dijo "nuevo turno" → NO heredar seña pagada del turno anterior
    if es_nuevo_turno:
        print(f"   🔧 [CALENDARIO] NUEVO TURNO: No se hereda seña pagada de otro turno.")
        # Forzar estado pendiente para el nuevo turno
        senia_estado = "pendiente"
        senia_monto = senia_monto_configurado
        estado_reserva = BOOKING_STATUS_PENDING
        print(f"   🔧 [CALENDARIO]   → Nuevo turno será PENDIENTE (no hereda seña pagada)")

    # CASO 2: REPROGRAMACIÓN → Preservar seña pagada si existía
    elif es_reprogramacion:
        if reserva_existente and reserva_existente.get("senia_estado") == "pagada":
            ya_tenia_senia_pagada = True
            monto_original = reserva_existente.get("senia_monto") or senia_monto_configurado

        if ya_tenia_senia_pagada:
            print(f"   🔧 [CALENDARIO] REPROGRAMACIÓN: Usuario ya tenía seña PAGADA. Preservando estado.")
            senia_estado = "pagada"
            senia_monto = monto_original
            estado_reserva = BOOKING_STATUS_RESERVED
            print(f"   🔧 [CALENDARIO]   → Forzando senia_estado='pagada', senia_monto={senia_monto}, estado_reserva=RESERVED")
        else:
            # Reprogramación sin seña pagada → queda pendiente
            if senia_estado == "" or senia_estado == "pagada":
                senia_estado = "pendiente"
                senia_monto = senia_monto_configurado
                estado_reserva = BOOKING_STATUS_PENDING
                print(f"   🔧 [CALENDARIO]   → Reprogramación sin seña pagada → pendiente")

    # CASO 3: No es reprog ni nuevo → verificar si el parámetro senia_estado ya es "pagada"
    elif senia_estado == "pagada":
        # Si se pasó "pagada" pero no es reprogramación, probablemente es error
        print(f"   ⚠️ [CALENDARIO] senia_estado='pagada' pero no es reprogramación. Cambiando a 'pendiente'")
        senia_estado = "pendiente"
        senia_monto = senia_monto_configurado
        estado_reserva = BOOKING_STATUS_PENDING

    # La seña de una reserva nueva siempre nace del total definitivo. Solo una
    # seña ya pagada al reprogramar conserva el importe histórico persistido.
    if senia_estado == "pagada" and _monto_a_int(senia_monto) is not None:
        senia_valor_int = _monto_a_int(senia_monto) or 0
    else:
        senia_valor_int = senia_valor_configurado
        senia_monto = senia_monto_configurado
    monto_pendiente = calcular_monto_pendiente(precio_total, senia_valor_int)

    # ============================================================
    # 🔧 PASO 4: SI EL USUARIO NO ESPECIFICÓ CANCHA, BUSCAR LA PRIMERA LIBRE
    # ============================================================
    cancha_a_usar = normalizar_valor_nullable(cancha)

    if not cancha_a_usar:
        # Buscar qué canchas están libres a esa hora
        canchas_libres = canchas_libres_para_bloque(dia_resuelto, hora_final, duracion_horas)

        if canchas_libres:
            # Usar la primera cancha libre
            cancha_a_usar = canchas_libres[0]
            print(f"   🔧 [CALENDARIO] Usuario no especificó cancha. Horario {hora_final} libre en: {canchas_libres}. Usando {cancha_a_usar}")
        else:
            # No hay ninguna cancha libre a esa hora, buscar alternativa
            print(f"   ❌ [CALENDARIO] Horario {hora_final} ocupado en TODAS las canchas")
            dia_alternativo, hora_alternativa = calendario.proximo_slot_libre(
                dia_preferido=dia_resuelto,
                hora_preferida=hora_final
            )
            return {
                "ok": False,
                "dia": dia_alternativo,
                "hora": hora_alternativa,
                "cancha": None,
                "respuesta": f"Ese horario está ocupado en todas las canchas. ¿Te sirve {dia_alternativo} a las {hora_alternativa}hs?"
            }

    # Si llegamos acá, tenemos una cancha específica
    print(f"   📅 Fecha resuelta: '{dia_raw}' → '{dia_resuelto}'")
    print(f"   🥅 Cancha a reservar: {cancha_a_usar}")
    if con_quincho:
        print(f"   🔥 Quincho a reservar: {quincho} {quincho_hora_inicio}-{quincho_hora_fin} ({quincho_duracion_horas:g} hs)")
    print(f"   💰 Estado seña: {senia_estado} | Monto: {senia_monto}")

    # ============================================================
    # 🔧 PASO 5: VERIFICAR DISPONIBILIDAD CON tool_reservar_turno
    # ============================================================
    if cancha_a_usar and not cancha_libre_para_bloque(dia_resuelto, hora_final, duracion_horas, cancha_a_usar):
        dia_alternativo, hora_alternativa = calendario.proximo_slot_libre(
            dia_preferido=dia_resuelto,
            hora_preferida=hora_final,
            cancha=cancha_a_usar
        )
        return {
            "ok": False,
            "dia": dia_alternativo,
            "hora": hora_alternativa,
            "cancha": cancha_a_usar,
            "respuesta": f"Ese bloque en {cancha_a_usar} no está disponible. ¿Te sirve {dia_alternativo} a las {hora_alternativa}hs?"
        }

    if con_quincho and not quincho_libre_para_bloque(dia_resuelto, quincho_hora_inicio, quincho_duracion_horas, quincho):
        return {
            "ok": False,
            "dia": dia_resuelto,
            "hora": hora_final,
            "cancha": cancha_a_usar,
            "respuesta": f"Tengo la cancha disponible, pero {quincho} no está libre de {rango_horario_texto(quincho_hora_inicio, quincho_duracion_horas)}. ¿Querés que busque otro horario con cancha y quincho disponibles?",
            "motivo": "quincho_ocupado"
        }

    contrato_reserva = tool_reservar_turno(
        telefono or "desconocido",
        prospecto.get("nombre", ""),
        dia_resuelto,
        hora_final,
        cancha_a_usar,
        estado_senia=senia_estado or "sin_senia"
    )
    if not contrato_reserva.get("ok"):
        disponibilidad = contrato_reserva.get("disponibilidad") or {}
        alternativa = (disponibilidad.get("alternativas") or [{}])[0]
        registrar_metrica_operativa("reserva_bloqueada_por_tool", {
            "telefono": telefono,
            "dia": dia_resuelto,
            "hora": hora_final,
            "cancha": cancha_a_usar,
            "razon": disponibilidad.get("razon")
        })
        return {
            "ok": False,
            "dia": alternativa.get("dia"),
            "hora": alternativa.get("hora"),
            "cancha": alternativa.get("cancha") or cancha_a_usar,
            "respuesta": f"Ese horario en {cancha_a_usar} no está disponible. ¿Te sirve {alternativa.get('dia')} a las {alternativa.get('hora')}hs?"
        }

    # ============================================================
    # 🔧 PASO 6: RESERVAR EN EL CALENDARIO
    # ============================================================
    horas_bloque = slots_para_bloque(hora_final, duracion_horas)
    metadata_quincho = {}
    if con_quincho:
        metadata_quincho = {
            "con_quincho": "Si",
            "quincho": quincho,
            "quincho_hora_inicio": quincho_hora_inicio,
            "quincho_hora_fin": quincho_hora_fin,
            "quincho_duracion_horas": str(quincho_duracion_horas),
            "quincho_precio_hora": str(quincho_precio_hora),
            "quincho_precio_total": str(quincho_precio_total),
        }
    reservas_bloque = []
    slot_ok = True
    dia_reservado, hora_reservada = dia_resuelto, hora_final
    reservation_id = ""
    with calendario.atomic():
        reservation_id = calendario.siguiente_reservation_id()
        metadata_quincho["reservation_id"] = reservation_id
        for hora_slot in horas_bloque:
            slot_ok, (dia_reservado, hora_reservada) = calendario.reservar(
                dia_resuelto, hora_slot,
                telefono or "desconocido",
                prospecto.get("nombre", ""),
                prospecto.get("website", ""),
                cancha=cancha_a_usar,
                estado=estado_reserva,
                senia_estado=senia_estado,
                senia_monto=senia_monto,
                extra_fields=metadata_quincho
            )
            if not slot_ok:
                remover_slots_reserva_bloque(
                    dia_resuelto,
                    reservas_bloque,
                    cancha_a_usar,
                    telefono or "desconocido"
                )
                break
            reservas_bloque.append(hora_slot)
        hora_reservada = hora_final

        if slot_ok:
            actualizar_metadata_reserva_bloque(
                dia_reservado,
                reservas_bloque,
                cancha_a_usar,
                telefono or "desconocido",
                duracion_horas,
                precio_total,
                senia_valor_int,
                monto_pendiente,
                extra_fields=metadata_quincho
            )

    if not slot_ok:
        # El slot específico está ocupado, buscar alternativa
        dia_alternativo, hora_alternativa = calendario.proximo_slot_libre(
            dia_preferido=dia_resuelto,
            hora_preferida=hora_final,
            cancha=cancha_a_usar
        )
        return {
            "ok": False,
            "dia": dia_alternativo,
            "hora": hora_alternativa,
            "cancha": cancha_a_usar,
            "respuesta": f"Ese horario en {cancha_a_usar} ya está ocupado. ¿Te sirve {dia_alternativo} a las {hora_alternativa}hs?"
        }

    # ============================================================
    # 🔧 PASO 7: ACTUALIZAR SEÑA Y MEMORIA
    # ============================================================
    cancha_reservada = cancha_a_usar
    reserva_objetivo = {
        "fecha": dia_reservado,
        "hora": hora_reservada,
        "cancha": cancha_reservada,
        "telefono": telefono or "desconocido",
        "nombre": prospecto.get("nombre", ""),
    }

    # Solo actualizar la seña si se proporcionó un estado (no vacío)
    if senia_estado and senia_estado != "":
        senia_actualizada = calendario.actualizar_senia_reserva_especifica(
            reserva_objetivo,
            senia_estado,
            senia_monto,
        )
        if not senia_actualizada:
            print(
                "   ⚠️ [CALENDARIO] No pude verificar la actualización de seña "
                f"para el slot exacto {dia_reservado} {hora_reservada} {cancha_reservada}"
            )
        else:
            print(
                "   💰 [CALENDARIO] Seña actualizada en reserva exacta: "
                f"{dia_reservado} {hora_reservada} {cancha_reservada} "
                f"→ {senia_estado} - {senia_monto}"
            )
        memoria = cargar_memoria_cliente(telefono or "desconocido")
        if senia_estado == "pagada":
            memoria["senias_pagadas_ok"] = int(memoria.get("senias_pagadas_ok") or 0) + 1
            memoria["estado_actual"] = "senia_pagada"
            registrar_metrica_operativa("senia_pagada", {"telefono": telefono, "monto": senia_monto, "dia": dia_reservado, "hora": hora_reservada})
        elif senia_estado == "pendiente":
            memoria["senias_pendientes"] = int(memoria.get("senias_pendientes") or 0) + 1
            memoria["estado_actual"] = "senia_pendiente"
            registrar_metrica_operativa("senia_pendiente", {"telefono": telefono, "monto": senia_monto, "dia": dia_reservado, "hora": hora_reservada})
            registrar_inicio_senia_pendiente({
                "telefono": telefono or "desconocido",
                "nombre": prospecto.get("nombre", ""),
                "fecha": dia_reservado,
                "hora": hora_reservada,
                "cancha": cancha_reservada,
                "duracion_horas": duracion_horas,
            })
        guardar_memoria_cliente(telefono or "desconocido", memoria)

    # ============================================================
    # 🔧 PASO 8: CONSTRUIR MENSAJE DE CONFIRMACIÓN
    # ============================================================

    # Si la seña ya está pagada, NO mostrar solicitud de seña
    if senia_estado == "pagada":
        respuesta = (
            f"✅ Listo, queda reservado para {dia_reservado} a las {formatear_hora_para_mensaje(hora_reservada)}.\n"
            f"Te esperamos en {BUSINESS_NAME}.\n"
            f"Cancha: {cancha_reservada}\n\n"
            f"✅ Seña ya registrada correctamente.\n\n"
            f"📌 Si necesitan cambiar o cancelar, avisen con tiempo por este WhatsApp."
        )
        print(f"   🔧 [CALENDARIO] Mensaje sin solicitud de seña (ya estaba pagada)")
    else:
        # Construir mensaje normal con solicitud de seña
        monto_numero = None
        if senia_monto:
            try:
                if isinstance(senia_monto, str):
                    monto_limpio = re.sub(r'[^\d]', '', str(senia_monto))
                    if monto_limpio:
                        monto_numero = int(monto_limpio)
                else:
                    monto_numero = int(senia_monto) if isinstance(senia_monto, (int, float)) else None
            except (ValueError, TypeError):
                monto_numero = None

        respuesta = build_confirmation_message(
            dia_reservado, 
            hora_reservada, 
            cancha_reservada, 
            duracion_horas=duracion_horas,
            precio_total=precio_total,
            senia_estado=senia_estado,
            senia_valor=monto_numero,
            monto_pendiente=monto_pendiente
        )
        if con_quincho:
            respuesta = (
                respuesta
                + f"\n\n🔥 Quincho/parrilla: {quincho} de {rango_horario_texto(quincho_hora_inicio, quincho_duracion_horas)}"
                + (f"\n💰 Quincho: ${quincho_precio_total:,}" if quincho_precio_total else "")
            )

    return {
        "ok": True,
        "dia": dia_reservado,
        "hora": hora_reservada,
        "cancha": cancha_reservada,
        "con_quincho": bool(con_quincho),
        "quincho": quincho,
        "quincho_hora_inicio": quincho_hora_inicio,
        "quincho_hora_fin": quincho_hora_fin,
        "quincho_duracion_horas": quincho_duracion_horas,
        "quincho_precio_total": quincho_precio_total,
        # V58 — COMPONENT FINANCIAL AUTHORITY.
        # El resumen determinista muestra por separado cancha y quincho. Ambos
        # importes deben viajar en el resultado operativo verificado para que
        # MONEY GUARD pueda demostrar cada cifra sin recurrir a memoria ni LLM.
        "precio_cancha_total": precio_cancha_total,
        "quincho_precio_hora": quincho_precio_hora,
        "precio_total": precio_total,
        "senia_valor": senia_valor_int,
        "monto_pendiente": monto_pendiente,
        "reserva_id": reservation_id or contrato_reserva.get("reserva_id"),
        "reservation_id": reservation_id or contrato_reserva.get("reserva_id"),
        "respuesta": respuesta
    }

def registrar_turno_confirmado_en_csv(telefono: str, prospecto: Dict, user_messages: List[str], dia: str, hora: str):
    razon_completa = f"Turno reservado: {dia} {hora}"

    if telefono:
        actualizar_estado_en_negocios_csv(telefono, "Turno reservado", razon_completa)

    prospect_data = {
        "intencion": "RESERVA",
        "nivel": "ALTO",
        "razon": razon_completa,
        "accion": "reservar_turno",
        "nombre": prospecto["nombre"],
        "negocio": prospecto["negocio"],
        "telefono": telefono or "No especificado",
        "website": prospecto.get("website", "No disponible"),
        "whatsapp_link": prospecto.get("whatsapp_link", ""),
        "es_cliente": prospecto.get("es_cliente", CLIENTE_NO),
        "conversacion": " | ".join(user_messages[:2])
    }
    save_to_csv(prospect_data)
    memoria = cargar_memoria_cliente(telefono)
    memoria["reservas_previas"] = int(memoria.get("reservas_previas") or 0) + 1
    memoria["cliente_frecuente"] = memoria["reservas_previas"] >= 3 or bool(memoria.get("cliente_frecuente"))
    memoria["horario_preferido"] = hora or memoria.get("horario_preferido", "")
    try:
        reserva_mem = calendario.obtener_reserva_por_telefono(telefono or "desconocido", prospecto.get("nombre", ""))
        if reserva_mem and reserva_mem.get("cancha"):
            memoria["cancha_preferida"] = reserva_mem.get("cancha")
    except Exception:
        pass
    fecha_obj = _parse_fecha_row(dia)
    if fecha_obj:
        dia_nombre = nombre_dia_es(fecha_obj)
        dias = list(memoria.get("dias_frecuentes") or [])
        if dia_nombre not in dias:
            dias.append(dia_nombre)
        memoria["dias_frecuentes"] = dias[-4:]
    memoria["estado_actual"] = "turno_reservado"
    guardar_memoria_cliente(telefono, memoria)
    registrar_metrica_operativa("reserva_confirmada", {
        "telefono": telefono,
        "cliente": prospecto.get("nombre"),
        "dia": dia,
        "hora": hora,
        "senia_pagada": False,
        "mensaje_usuario": " | ".join(user_messages[:2])
    })
    print(f"📅 [CALENDARIO] Turno reservado registrado: {dia} {hora} - {prospecto['nombre']}")

def ejecutar_cancelacion_turno_contacto(telefono: str, prospecto: Dict) -> Dict[str, Any]:
    nombre = prospecto.get("nombre", "") if prospecto else ""
    resultado = calendario.cancelar_por_contacto(telefono or "", nombre or "")
    if resultado.get("ok"):
        reserva = resultado.get("reserva") or {}
        fecha = str(reserva.get("fecha") or "").replace("/2026", "")
        hora = str(reserva.get("hora") or "").strip()
        cancha = str(reserva.get("cancha") or "").strip()
        cancelacion_tarde = reserva_es_cancelacion_tarde(reserva)
        partes = [p for p in [fecha, f"a las {hora}hs" if hora else "", f"en {cancha}" if cancha else ""] if p]
        detalle = " ".join(partes)
        respuesta = f"Listo, cancelé tu turno{f' de {detalle}' if detalle else ''}. ¿Fue por clima, falta de jugadores u otro motivo? Si querés, también buscamos otro horario."
        if cancelacion_tarde:
            politica = str(CANCELLATION_POLICY or "").strip()
            detalle_politica = f" {politica}" if politica else ""
            respuesta = (
                f"Listo, cancele tu turno{f' de {detalle}' if detalle else ''}. "
                f"Como fue con menos de {MIN_CANCELLATION_NOTICE_MINUTES // 60} horas de anticipacion, "
                f"la seña queda perdida segun la politica de cancelacion.{detalle_politica} "
                "Fue por clima, falta de jugadores u otro motivo? Si queres, tambien buscamos otro horario."
            )
        if telefono:
            actualizar_estado_en_negocios_csv(telefono, "Turno cancelado", "Cancelado por pedido del usuario")
            memoria = cargar_memoria_cliente(telefono)
            memoria["cancelaciones"] = int(memoria.get("cancelaciones") or 0) + 1
            if cancelacion_tarde:
                memoria["cancelaciones_tarde"] = int(memoria.get("cancelaciones_tarde") or 0) + 1
            memoria["estado_actual"] = "turno_cancelado"
            guardar_memoria_cliente(telefono, memoria)
        registrar_metrica_operativa("reserva_cancelada", {"telefono": telefono, "nombre": nombre, "reserva": reserva, "cancelacion_tarde": cancelacion_tarde})
        return {"ok": True, "respuesta": respuesta, "motivo": "cancelada", "reserva": reserva}

    reservas = resultado.get("reservas") or []
    if resultado.get("motivo") == "multiples_reservas" and reservas:
        opciones = []
        for reserva in reservas[:4]:
            fecha = str(reserva.get("fecha") or "").replace("/2026", "")
            hora = str(reserva.get("hora") or "").strip()
            cancha = str(reserva.get("cancha") or "").strip()
            opciones.append(" ".join(p for p in [fecha, f"{hora}hs" if hora else "", cancha] if p))
        respuesta = (
            "Encontré más de un turno a tu nombre. Decime cuál querés cancelar: "
            + "; ".join(opciones)
        )
        return {"ok": False, "respuesta": respuesta, "motivo": "multiples_reservas"}

    return {
        "ok": False,
        "respuesta": "No encontré un turno activo a tu nombre o a tu número para cancelar. ¿Querés consultar disponibilidad?",
        "motivo": resultado.get("motivo", "sin_reserva")
    }

# ================================
# FUNCIÓN: INICIALIZAR CSV
# ================================
def _post_turno_followup_booking_shape(
    followup: Dict[str, Any],
    target_hour: str,
) -> Dict[str, Any]:
    """Copia la forma del último turno sin heredar estado operativo viejo."""
    origin = dict((followup or {}).get("origen") or {})
    duration = normalizar_duracion_horas(
        (followup or {}).get("duracion_horas")
        or origin.get("duracion_horas")
        or (
            float(_duracion_minutos_row(origin)) / 60.0
            if origin else DEFAULT_TURN_DURATION_HOURS
        )
    )
    with_quincho = bool(
        CON_QUINCHO
        and str(origin.get("con_quincho") or "").strip().casefold()
        in {"si", "sí", "true", "1", "yes"}
    )
    quincho = normalizar_nombre_quincho(origin.get("quincho") or "") if with_quincho else ""
    quincho_duration = (
        normalizar_duracion_horas(origin.get("quincho_duracion_horas"), 1.0)
        if with_quincho else 0
    )
    quincho_start = ""
    if with_quincho:
        origin_hour = normalizar_hora_detectada(origin.get("hora"))
        origin_quincho_start = normalizar_hora_detectada(
            origin.get("quincho_hora_inicio")
        )
        origin_minutes = _hora_a_minutos_local(origin_hour)
        quincho_minutes = _hora_a_minutos_local(origin_quincho_start)
        target_minutes = _hora_a_minutos_local(target_hour)
        if (
            origin_minutes is not None
            and quincho_minutes is not None
            and target_minutes is not None
        ):
            quincho_start = _minutos_a_hora(
                target_minutes + (quincho_minutes - origin_minutes)
            )
        if not hora_es_valida(quincho_start):
            quincho_start = hora_fin_bloque(target_hour, duration)
    return {
        "duracion_horas": duration,
        "con_quincho": with_quincho,
        "quincho": quincho,
        "quincho_hora_inicio": quincho_start,
        "quincho_duracion_horas": quincho_duration,
    }


async def manejar_respuesta_post_turno_followup(telefono: str, prospecto: Dict, user_messages: List[str], conv_state: Dict) -> Optional[Dict[str, Any]]:
    conv_state, expired = expirar_post_turno_followup_si_corresponde(
        telefono or "unknown",
        conv_state,
    )
    if expired:
        return None
    ultimo_mensaje = user_messages[-1] if user_messages else ""
    followup = (conv_state or {}).get("post_turno_followup") or {}
    if not followup.get("activo"):
        return None

    # Un contexto persistido antes de endurecer el scheduler puede seguir
    # marcado como activo aunque su reserva de origen nunca haya quedado firme.
    # Validarlo otra vez al CONSUMIR la propuesta evita que una seña pendiente
    # reviva días/horas/canchas antiguas y capture una consulta nueva (por
    # ejemplo: "¿puede ser 2 horas?"). Fallamos cerrados y no gastamos IA.
    origin = dict(followup.get("origen") or {})
    if not _reserva_habilita_post_turno_followup(origin):
        print(
            "   🧹 [POST-TURNO INVALID ORIGIN] la reserva de origen no "
            "está confirmada con seña validada; desactivo la propuesta y "
            "continúa AgentV2"
        )
        update_conversation_state(
            telefono or "unknown",
            fase=(
                "inicial"
                if conv_state.get("fase") == "post_turno_followup"
                else conv_state.get("fase", "inicial")
            ),
            dia_propuesto=(
                None
                if conv_state.get("fase") == "post_turno_followup"
                else conv_state.get("dia_propuesto")
            ),
            hora_propuesta=(
                None
                if conv_state.get("fase") == "post_turno_followup"
                else conv_state.get("hora_propuesta")
            ),
            cancha_propuesta=(
                None
                if conv_state.get("fase") == "post_turno_followup"
                else conv_state.get("cancha_propuesta")
            ),
            post_turno_followup={
                **followup,
                "activo": False,
                "estado": "origen_no_confirmado",
            },
        )
        return None

    # El contexto es autosuficiente: nunca completa datos desde el draft normal.
    dia = followup.get("dia")
    hora = followup.get("hora")
    cancha = followup.get("cancha")
    booking_shape = _post_turno_followup_booking_shape(followup, hora)
    duracion = booking_shape["duracion_horas"]
    if not (
        normalizar_valor_nullable(dia)
        and hora_es_valida(hora)
        and normalizar_valor_nullable(cancha)
    ):
        print(
            "   🧹 [POST-TURNO STALE] propuesta incompleta; "
            "libero el turno actual para AgentV2"
        )
        update_conversation_state(
            telefono or "unknown",
            fase=(
                "inicial"
                if conv_state.get("fase") == "post_turno_followup"
                else conv_state.get("fase", "inicial")
            ),
            post_turno_followup={
                **followup,
                "activo": False,
                "estado": "invalido",
            },
        )
        return None

    decision = await detectar_afirmacion_post_turno_ia(ultimo_mensaje, conv_state)
    classification = str(decision.get("classification") or "ambiguous")
    addresses_proposal = decision.get("addresses_proposal")
    accepts_exact_offer = decision.get("accepts_exact_offer") is True
    has_new_booking_request = bool(decision.get("has_new_booking_request"))
    if classification == "new_request" or has_new_booking_request:
        print(
            "   🥇 [POST-TURNO CURRENT REQUEST] solicitud nueva detectada; "
            "desactivo la propuesta semanal y continúa AgentV2"
        )
        update_conversation_state(
            telefono or "unknown",
            post_turno_followup={
                **followup,
                "activo": False,
                "estado": "reemplazado_por_solicitud_nueva",
            },
        )
        return None

    if (
        classification == "accepted"
        and addresses_proposal is True
        and accepts_exact_offer
    ):
        if not nombre_cliente_identificado(prospecto):
            update_conversation_state(
                telefono or "unknown",
                fase="esperando_nombre_reserva",
                dia_propuesto=dia,
                hora_propuesta=hora,
                cancha_propuesta=cancha,
                duracion_propuesta=duracion,
                senia_estado="pendiente",
                senia_monto="",
                nombre_reserva_pendiente=True,
                con_quincho=booking_shape["con_quincho"],
                quincho=booking_shape["quincho"],
                quincho_hora_inicio=booking_shape["quincho_hora_inicio"],
                quincho_duracion_horas=booking_shape["quincho_duracion_horas"],
                quincho_confirmacion_origen=(
                    "usuario" if booking_shape["con_quincho"] else None
                ),
                post_turno_followup={
                    **followup,
                    "activo": False,
                    "estado": "aceptado_esperando_nombre",
                },
            )
            return {
                "ok": False,
                "respuesta": build_pedido_nombre_reserva_message(),
                "motivo": "nombre_requerido_post_turno"
            }

        resultado = reservar_turno_en_calendario(
            telefono or "desconocido",
            prospecto,
            dia,
            hora,
            cancha=cancha,
            estado_reserva=BOOKING_STATUS_PENDING,
            senia_estado="pendiente",
            senia_monto="",
            duracion_horas=duracion,
            con_quincho=booking_shape["con_quincho"],
            quincho=booking_shape["quincho"],
            quincho_hora_inicio=booking_shape["quincho_hora_inicio"],
            quincho_duracion_horas=booking_shape["quincho_duracion_horas"],
            es_nuevo_turno=True,
        )
        if resultado.get("ok"):
            precio_total = (
                _monto_a_int(resultado.get("precio_total"))
                or calcular_precio_total(duracion)
            )
            senia_valor = _monto_a_int(resultado.get("senia_valor"))
            if senia_valor is None:
                senia_valor = _senia_para_total(precio_total)
            monto_pendiente = (
                _monto_a_int(resultado.get("monto_pendiente"))
            )
            if monto_pendiente is None:
                monto_pendiente = calcular_monto_pendiente(
                    precio_total,
                    senia_valor,
                )
            resultado["respuesta"] = build_reserva_pendiente_senia_message(
                resultado.get("dia") or dia,
                resultado.get("hora") or hora,
                resultado.get("cancha") or cancha,
                duracion,
                precio_total,
                senia_valor,
                monto_pendiente,
                con_quincho=bool(resultado.get("con_quincho")),
                quincho=resultado.get("quincho") or booking_shape["quincho"],
                quincho_hora_inicio=(
                    resultado.get("quincho_hora_inicio")
                    or booking_shape["quincho_hora_inicio"]
                ),
                quincho_duracion_horas=(
                    resultado.get("quincho_duracion_horas")
                    or booking_shape["quincho_duracion_horas"]
                ),
                quincho_precio_total=(
                    _monto_a_int(resultado.get("quincho_precio_total")) or 0
                ),
            ).replace("__NO_CONSOLIDAR__", "", 1).strip()
            update_conversation_state(
                telefono or "unknown",
                fase="senia_pendiente",
                dia_propuesto=resultado.get("dia") or dia,
                hora_propuesta=resultado.get("hora") or hora,
                cancha_propuesta=resultado.get("cancha") or cancha,
                duracion_propuesta=duracion,
                senia_estado="pendiente",
                senia_monto=_monto_humano(senia_valor),
                con_quincho=bool(resultado.get("con_quincho")),
                quincho=resultado.get("quincho") or "",
                quincho_hora_inicio=resultado.get("quincho_hora_inicio") or "",
                quincho_duracion_horas=(
                    resultado.get("quincho_duracion_horas") or 0
                ),
                quincho_confirmacion_origen=(
                    "usuario" if resultado.get("con_quincho") else None
                ),
                post_turno_followup={
                    **followup,
                    "activo": False,
                    "estado": "aceptado_hold_creado",
                },
            )
            registrar_turno_confirmado_en_csv(
                telefono or "desconocido",
                prospecto,
                user_messages,
                resultado.get("dia") or dia,
                resultado.get("hora") or hora
            )
            registrar_metrica_operativa(
                "post_turno_followup_aceptado_hold_creado",
                {
                    "telefono": telefono,
                    "dia": resultado.get("dia") or dia,
                    "hora": resultado.get("hora") or hora,
                    "cancha": resultado.get("cancha") or cancha,
                    "con_quincho": bool(resultado.get("con_quincho")),
                    "hold_minutes": PENDING_DEPOSIT_HOLD_MINUTES,
                },
            )
        else:
            # El recordatorio sólo representa el mismo turno anterior. Si ese
            # slot ya no está disponible, una alternativa pertenece al flujo
            # normal y no se transforma en otro follow-up oculto.
            update_conversation_state(
                telefono or "unknown",
                post_turno_followup={
                    **followup,
                    "activo": False,
                    "estado": "aceptado_no_disponible",
                },
            )
        return resultado

    if classification == "rejected" and addresses_proposal is True:
        update_conversation_state(
            telefono or "unknown",
            post_turno_followup={
                **followup,
                "activo": False,
                "estado": "rechazado",
            },
        )
        print(
            "   🧹 [POST-TURNO MEMORY] propuesta rechazada; "
            "la respuesta actual queda a cargo de AgentV2"
        )
        return None

    if classification == "rejected":
        print(
            "   🛡️ [POST-TURNO AUTHORITY] rejected sin vínculo estructural "
            "con la propuesta; continúa AgentV2"
        )

    if classification == "accepted":
        print(
            "   🛡️ [POST-TURNO AUTHORITY] aceptación no vinculada de forma "
            "inequívoca al mismo turno; no autorizo reserva"
        )

    if addresses_proposal is True and classification in {"ambiguous", "accepted"}:
        print("   [POST-TURNO CLARIFICATION] conservo dia, hora y cancha de la propuesta vigente")
        return {
            "ok": False,
            "motivo": "confirmacion_propuesta_post_turno",
            "respuesta": (
                f"¿Querés que te reserve el {dia} a las "
                f"{formatear_hora_para_mensaje(hora)} en {cancha}?"
            ),
        }

    # Las consultas ajenas a la propuesta siguen bajo autoridad de AgentV2.
    return None


async def detectar_respuesta_no_show_reagendar_ia(mensaje: str, conv_state: Dict) -> Dict[str, Any]:
    if not mensaje or len(str(mensaje).strip()) < 1:
        return {"accion": "ambiguo", "confianza": 0.0, "razon": "mensaje vacio"}

    no_show_ctx = (conv_state or {}).get("no_show_reagendar") or {}
    reserva = no_show_ctx.get("reserva") or {}
    historial = []
    for msg in (conv_state or {}).get("historial", [])[-6:]:
        role = "user" if msg.get("role") == "user" else "assistant"
        historial.append({"role": role, "content": str(msg.get("content") or "")[:400]})

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un clasificador contextual para un agente IA de reservas de canchas.\n"
                        "El agente acaba de avisar al cliente que no vino a jugar y le pregunto si queria reagendar.\n"
                        "Tu tarea es interpretar la respuesta actual del cliente por intencion real, no por keywords.\n\n"
                        "Acciones validas:\n"
                        "- quiere_reagendar: acepta o muestra intención de buscar otro turno.\n"
                        "- propone_fecha_hora: ya responde con dia, hora o una propuesta concreta para reagendar.\n"
                        "- rechaza: no quiere reagendar o cierra la conversación.\n"
                        "- pregunta: pregunta algo antes de decidir.\n"
                        "- ambiguo: no se entiende.\n\n"
                        "Respondé SOLO JSON valido: "
                        "{\"accion\":\"quiere_reagendar|propone_fecha_hora|rechaza|pregunta|ambiguo\",\"confianza\":0.0,\"razon\":\"breve\"}"
                    )
                },
                *historial,
                {
                    "role": "user",
                    "content": (
                        f"Reserva original no-show: {json.dumps(reserva, ensure_ascii=False)[:800]}\n"
                        f"Mensaje actual del cliente: {mensaje}"
                    )
                }
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"}
        )
        register_cost(resp)
        data = json.loads(resp.choices[0].message.content.strip())
        accion = str(data.get("accion") or "ambiguo").strip()
        if accion not in ("quiere_reagendar", "propone_fecha_hora", "rechaza", "pregunta", "ambiguo"):
            accion = "ambiguo"
        data["accion"] = accion
        data["confianza"] = float(data.get("confianza", 0.0) or 0.0)
        print(f"   [No-show IA] {accion} (conf: {data['confianza']}) - {str(data.get('razon') or '')[:80]}")
        return data
    except Exception as e:
        print(f"   [No-show IA] Error: {e}")
        return {"accion": "ambiguo", "confianza": 0.0, "razon": f"error: {e}"}


async def manejar_nombre_reserva_pendiente(telefono: str, prospecto: Dict, user_messages: List[str], conv_state: Dict) -> Dict[str, Any]:
    ultimo_mensaje = user_messages[-1] if user_messages else ""
    nombre = extraer_nombre_reserva_desde_mensaje(ultimo_mensaje)
    if not nombre:
        return {
            "ok": False,
            "respuesta": "Necesito el nombre para dejarlo bien anotado. A nombre de quien reservo?",
            "motivo": "nombre_invalido"
        }

    prospecto = guardar_nombre_reserva_en_prospecto(telefono or "unknown", prospecto, nombre)
    dia = conv_state.get("dia_propuesto")
    hora = conv_state.get("hora_propuesta")
    cancha = conv_state.get("cancha_propuesta")
    duracion = conv_state.get("duracion_propuesta") or DEFAULT_TURN_DURATION_HOURS

    if not (normalizar_valor_nullable(dia) and hora_es_valida(hora) and cancha):
        update_conversation_state(
            telefono or "unknown",
            fase="inicial",
            nombre_reserva_pendiente=None
        )
        return {
            "ok": False,
            "respuesta": "Gracias. Decime de nuevo dia, horario y cancha y te lo reservo a ese nombre.",
            "motivo": "datos_reserva_incompletos"
        }

    resultado = reservar_turno_en_calendario(
        telefono or "desconocido",
        prospecto,
        dia,
        hora,
        cancha=cancha,
        estado_reserva=BOOKING_STATUS_PENDING,
        senia_estado="pendiente",
        senia_monto="",
        duracion_horas=duracion
    )

    if resultado.get("ok"):
        dia_guardado = resultado.get("dia") or dia
        hora_guardada = resultado.get("hora") or hora
        cancha_guardada = resultado.get("cancha") or cancha
        update_conversation_state(
            telefono or "unknown",
            fase="senia_pendiente",
            dia_propuesto=dia_guardado,
            hora_propuesta=hora_guardada,
            cancha_propuesta=cancha_guardada,
            duracion_propuesta=duracion,
            senia_estado="pendiente",
            senia_monto=_monto_humano(
                _monto_a_int(resultado.get("senia_valor"))
                if _monto_a_int(resultado.get("senia_valor")) is not None
                else _senia_para_total(resultado.get("precio_total"))
            ),
            nombre_reserva_pendiente=None
        )
        registrar_turno_confirmado_en_csv(
            telefono or "desconocido",
            prospecto,
            user_messages,
            dia_guardado,
            hora_guardada
        )
    else:
        update_conversation_state(
            telefono or "unknown",
            fase="coordinacion_propuesta",
            dia_propuesto=resultado.get("dia") or dia,
            hora_propuesta=resultado.get("hora") or hora,
            cancha_propuesta=resultado.get("cancha") or cancha,
            duracion_propuesta=duracion,
            nombre_reserva_pendiente=None
        )

    return resultado


async def manejar_respuesta_no_show_reagendar(telefono: str, user_messages: List[str], conv_state: Dict) -> Optional[Dict[str, Any]]:
    ultimo_mensaje = user_messages[-1] if user_messages else ""
    if not ultimo_mensaje:
        return None

    decision = await detectar_respuesta_no_show_reagendar_ia(ultimo_mensaje, conv_state)
    accion = decision.get("accion", "ambiguo")
    confianza = float(decision.get("confianza", 0.0) or 0.0)

    if accion == "quiere_reagendar" and confianza >= 0.7:
        update_conversation_state(
            telefono or "unknown",
            fase="coordinacion_nueva",
            no_show_reagendar={"activo": False}
        )
        return {
            "ok": True,
            "respuesta": "Dale, lo reagendamos. Decime qué día y horario te sirve."
        }

    if accion == "propone_fecha_hora" and confianza >= 0.7:
        update_conversation_state(
            telefono or "unknown",
            fase="coordinacion_nueva",
            no_show_reagendar={"activo": False}
        )
        return None

    if accion == "rechaza" and confianza >= 0.7:
        update_conversation_state(
            telefono or "unknown",
            fase="inicial",
            no_show_reagendar={"activo": False}
        )
        return {
            "ok": True,
            "respuesta": "Dale, no hay problema. Cuando quieras buscar otro turno me escribís."
        }

    return None


