async def click_todos(page):
    """Hace clic en el filtro 'Todos' para ver todos los chats."""
    try:
        # 🆕 EJECUTAR calendario.py --order ANTES de clickear "Todos"
        # Esto asegura que el calendario esté ordenado antes de revisar mensajes
        ordenar_calendario_sync()

        # XPath para WhatsApp Web estándar
        todos_selector = "//button[@id='all-filter']"

        if await page.locator(todos_selector).count() > 0:
            await page.locator(todos_selector).click()
            await asyncio.sleep(1)
            await page.keyboard.press("Escape")
            print("✅ Click en 'Todos' (WhatsApp Web)")
            return True

        # Fallback: buscar cualquier botón que contenga 'Todos'
        fallback_selectors = [
            "//button[contains(text(), 'Todos')]",
            "//button[contains(@aria-label, 'Todos')]",
            "//span[contains(text(), 'Todos')]/ancestor::button"
        ]

        for selector in fallback_selectors:
            if await page.locator(selector).count() > 0:
                await page.locator(selector).first.click()
                await asyncio.sleep(1)
                print(f"✅ Click en 'Todos' (fallback): {selector}")
                return True

        print("⚠️ No se encontró el botón 'Todos'")
        return False

    except Exception as e:
        print(f"⚠️ [Todos] Error: {e}")
        return False

