# FUNCIÓN: MANEJAR POP-UP INICIAL "CONTINUAR"
# ================================
STARTUP_CONTINUE_SELECTOR = "//div/div[2]/button"


async def handle_startup_continue_popup(page):
    """Cierra el modal inicial y registra el selector que funcionó.

    El XPath estructural solicitado puede coincidir con otros botones. Por eso
    sólo se pulsa una coincidencia visible cuyo texto sea exactamente Continuar.
    Si el popup no aparece, el inicio continúa normalmente.
    """
    selectors = list(dict.fromkeys(filter(None, (
        STARTUP_CONTINUE_SELECTOR,
        SELECTOR_CACHE.get("startup_continue"),
        "button:has-text('Continuar')",
        "//button[normalize-space()='Continuar']",
    ))))
    try:
        # El modal puede terminar su animación unos instantes después de que
        # WhatsApp informa que la sesión ya está activa.
        for _ in range(12):
            for selector in selectors:
                locator = page.locator(selector)
                for index in range(await locator.count()):
                    button = locator.nth(index)
                    if not await button.is_visible():
                        continue
                    text = " ".join((await button.inner_text()).casefold().split())
                    if text != "continuar":
                        continue
                    proactive_monitor.all_selectors["popup"]["continuar_active"] = selector
                    SELECTOR_CACHE["startup_continue"] = selector
                    _save_selector_adaptation_cache()
                    print(f"   🧠 [SelectorProactive] Popup Continuar aprendido: {selector}")
                    await button.click(timeout=3000)
                    print("✅ Click en 'Continuar' del popup inicial")
                    return True
            await asyncio.sleep(0.25)
    except Exception as e:
        print(f"   ⚠️ [Startup Popup] No pude cerrar 'Continuar': {e}")
    return False

