# ================================
async def monitor_alert_chat_during_pause(page):
    try:
        ahora = time.time()
        last_open = getattr(monitor_alert_chat_during_pause, "_last_control_open", 0)
        control_number = get_pause_control_number()  # 🔧 FIX: usar el admin que pausó, no AUTHORIZED_NUMBER fijo
        alert_chat_url = f"https://web.whatsapp.com/send?phone={control_number.replace('+', '')}&text="

        if ahora - last_open >= PAUSE_CONTROL_RECHECK_SECONDS:
            print(f"⏸️ [PAUSA] Reabriendo chat autorizado de control ({control_number})")
            await page.goto(alert_chat_url)
            monitor_alert_chat_during_pause._last_control_open = ahora
            await asyncio.sleep(5)

        user_selector = await get_best_bubble_selector(page, "user")
        bubbles = page.locator(user_selector)
        total = await bubbles.count()

        if total > 0:
            last_msg = await bubbles.nth(total - 1).inner_text()
            message_key = f"{total}:{last_msg.strip()}"
            if message_key == getattr(monitor_alert_chat_during_pause, "_last_control_message_key", ""):
                return False

            comando = await detectar_comando_control_ia(last_msg)
            if comando.get("accion") == "reanudar_agente" and comando.get("confianza", 0.0) >= 0.45:
                monitor_alert_chat_during_pause._last_control_message_key = message_key
                bot_state.is_active = True
                bot_state.last_state_change = datetime.datetime.now()
                bot_state.save()
                await send_message(page, "✅ Agente encendido. Vuelvo a responder clientes.")
                await page.goto("https://web.whatsapp.com")
                await asyncio.sleep(3)
                return True

            if comando.get("accion") in ("continuar_contacto", "reporte_negocio", "agenda_hoy", "listar_horarios_libres", "estado_agente", "listar_blacklist", "bloquear_numero", "desbloquear_numero", "agregar_reserva", "borrar_reserva", "marcar_no_show", "marcar_senia_pagada", "liberar_senia_pendiente", "listar_senias_pendientes", "listar_casos_humanos", "resolver_caso_humano", "ver_reserva_id", "mover_reserva_id", "cancelar_reserva_id", "liberar_reserva_id", "agregar_quincho_reserva_id", "ver_inscripcion_evento_id", "confirmar_pago_inscripcion_evento_admin", "liberar_inscripcion_evento_id", "lista_espera", "quitar_lista_espera", "clientes_problema", "motivos_cancelacion", "listar_turnos_fijos", "exportar_agenda", "agregar_turno_fijo", "quitar_turno_fijo", "bloquear_dia", "desbloquear_dia", "cambiar_horario_atencion", "cambiar_dias_atencion", "cambiar_business_name", "cambiar_agent_name", "cambiar_business_address", "cambiar_payment_alias", "cambiar_canchas", "cambiar_con_quincho", "cambiar_quinchos", "quitar_quincho", "cambiar_precio_quincho"):
                monitor_alert_chat_during_pause._last_control_message_key = message_key
                await manejar_comando_autorizado(page, control_number, [last_msg])  # 🔧 FIX: usar control_number
                return True

            if comando.get("accion") == "pausar_agente":
                monitor_alert_chat_during_pause._last_control_message_key = message_key
                await send_message(page, "⏸️ Sigo pausado. Escribime cuando quieras reanudar.")
                return True

        return False
    except Exception as e:
        print(f"⚠️ [PAUSA] Error: {e}")
        return False


