# FUNCIÓN: AGREGAR LEAD DESDE REFERIDO
# ================================
def agregar_lead_desde_referido(telefono_nuevo: str, referido_por: str = "", negocio: str = "") -> bool:
    telefono_normalizado = normalize_phone(telefono_nuevo)
    if not telefono_normalizado:
        print(f"⚠️ [Referido] Teléfono inválido: {telefono_nuevo}")
        return False

    if os.path.exists(NEGOCIOS_CSV):
        try:
            with open(NEGOCIOS_CSV, 'r', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                for row in reader:
                    if normalize_phone(row.get("telefono", "")) == telefono_normalizado:
                        print(f"⚠️ [Referido] Teléfono ya existe en CSV: {telefono_normalizado}")
                        return False
        except Exception as e:
            print(f"⚠️ [Referido] Error verificando duplicado: {e}")

    now = datetime.datetime.now()
    nueva_fila = {
        "fecha_hora": now.strftime("%Y-%m-%d %H:%M:%S"),
        "nombre": "No especificado",
        "telefono": telefono_normalizado,
        "website": "No disponible",
        "whatsapp_link": f"https://wa.me/{telefono_normalizado.replace('+', '')}",
        "estado": "Referido - pendiente contacto",
        "mensaje_personalizado": f"Referido por {referido_por or 'secretario'} de {negocio or 'negocio desconocido'}",
        "contactado": "no",
        CLIENTE_FIELD: CLIENTE_NO,
    }

    fieldnames = NEGOCIOS_FIELDNAMES

    try:
        file_exists = os.path.exists(NEGOCIOS_CSV)
        with open(NEGOCIOS_CSV, 'a', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
            if not file_exists:
                writer.writeheader()
            writer.writerow(nueva_fila)
        print(f"✅ [Referido] Nuevo lead agregado: {telefono_normalizado}")
        return True
    except Exception as e:
        print(f"⚠️ [Referido] Error guardando: {e}")
        return False

# ================================
# FUNCIÓN: EXTRAER TELÉFONO ARGENTINO DEL TEXTO
# ================================
def extraer_telefono_del_texto(texto: str) -> Optional[str]:
    if not texto:
        return None

    texto_limpio = texto.replace('\u00a0', ' ')

    patrones = [
        r'\+54\s*9?\s*\d{2,4}[\s\-]?\d{3,4}[\s\-]?\d{4}',
        r'(?<!\d)54\s*9?\s*\d{2,4}[\s\-]?\d{3,4}[\s\-]?\d{4}(?!\d)',
        r'(?<!\d)(?:0?15[\s\-]?)?\d{3,4}[\s\-]?\d{3,4}[\s\-]?\d{4}(?!\d)',
        r'(?<!\d)\d{10}(?!\d)',
    ]

    for patron in patrones:
        match = re.search(patron, texto_limpio)
        if match:
            numero_raw = match.group(0)
            numero_norm = normalize_phone(numero_raw)
            digitos = re.sub(r'\D', '', numero_norm)
            if len(digitos) >= 10:
                print(f"   📞 [Extraer tel] Encontrado: '{numero_raw}' → '{numero_norm}'")
                return numero_norm

    return None

def detectar_referido_ia(texto_combinado: str, prospecto: Dict = None) -> Dict:
    texto_combinado = str(texto_combinado or "").strip()
    if not texto_combinado:
        return {"es_referido": False, "razon": "Sin texto para analizar"}

    prospecto = prospecto or {}
    contexto = {
        "nombre": prospecto.get("nombre", ""),
        "negocio": prospecto.get("negocio", ""),
        "telefono": prospecto.get("telefono", ""),
    }

    try:
        resp = client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un clasificador de conversaciones de WhatsApp para reservas de canchas. "
                        "Tenés que detectar si el usuario está derivando la conversación a otra persona "
                        "o indicando que el contacto correcto es otro.\n\n"
                        "Respondé SOLO JSON válido con estas claves:\n"
                        "{"
                        "\"es_referido\": boolean, "
                        "\"pide_o_entrega_otro_contacto\": boolean, "
                        "\"razon\": string"
                        "}\n\n"
                        "Marcá es_referido=true cuando el usuario: dice que no es el encargado/responsable, "
                        "dice que otra persona maneja reservas/decisiones, ofrece pasar un teléfono/contacto, "
                        "pasa directamente el número de otra persona, dice que hay que hablar con alguien más, "
                        "o se presenta como secretario/empleado/intermediario y deriva.\n"
                        "Marcá false si solo pregunta información, rechaza la propuesta, saluda, pide detalles, "
                        "coordina horario, o responde como si fuera la persona correcta."
                    )
                },
                {
                    "role": "user",
                    "content": (
                        f"Contexto contacto: {json.dumps(contexto, ensure_ascii=False)}\n\n"
                        f"Mensajes del usuario:\n{texto_combinado}"
                    )
                }
            ],
            temperature=0.0,
            max_tokens=120,
            response_format={"type": "json_object"}
        )
        register_cost(resp)

        raw = resp.choices[0].message.content.strip()
        result = json.loads(raw)
        return {
            "es_referido": bool(result.get("es_referido", False)),
            "pide_o_entrega_otro_contacto": bool(result.get("pide_o_entrega_otro_contacto", False)),
            "razon": str(result.get("razon", "")).strip(),
        }
    except Exception as e:
        print(f"⚠️ [Referido IA] Error: {e}")
        return {
            "es_referido": False,
            "pide_o_entrega_otro_contacto": False,
            "razon": f"Error en análisis IA: {e}",
        }

def detectar_saludo_retorno_ia(mensaje: str, tiene_historial: bool) -> bool:
    if not tiene_historial:
        return False
    try:
        resp = client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos un clasificador binario. Respondés SOLO con 'SI' o 'NO'.\n"
                        "¿El mensaje es un saludo simple, sin contenido informativo, "
                        "sin preguntas, sin objeciones, sin propuestas? "
                        "Ejemplos de SI: 'hola', 'buenas tardes', 'hola buenas', 'buen día!', "
                        "'hey', 'holis', 'buenas!', 'holaa'. "
                        "Ejemplos de NO: preguntas, objeciones, interés explícito, "
                        "respuestas con contenido, despedidas."
                    )
                },
                {"role": "user", "content": mensaje}
            ],
            temperature=0.0,
            max_tokens=5
        )
        register_cost(resp)
        return resp.choices[0].message.content.strip().upper().startswith("SI")
    except Exception as e:
        print(f"⚠️ [Saludo retorno IA] Error: {e}")
        return False

# ================================
# DETECCIÓN DE BOT POR VELOCIDAD DE RESPUESTA
# ================================
bot_quarantine = {}
BOT_DETECTION_THRESHOLD = CONFIG_BOT_DETECTION_THRESHOLD
BOT_QUARANTINE_TIME = BOT_QUARANTINE_SECONDS
BOT_RESPONSE_TIME_THRESHOLD = CONFIG_BOT_RESPONSE_TIME_THRESHOLD
bot_suspect_timestamps = {}

async def es_respuesta_de_bot(page, telefono: str = None) -> bool:
    try:
        if await is_user_typing(page):
            print("⌨️ [BOT DETECT] Usuario está escribiendo → probablemente humano")
            return False

        if telefono:
            tiempo_actual = time.time()
            key = normalize_phone(telefono) if telefono else "unknown"

            if key not in bot_suspect_timestamps:
                bot_suspect_timestamps[key] = []

            bot_suspect_timestamps[key].append(tiempo_actual)
            bot_suspect_timestamps[key] = [ts for ts in bot_suspect_timestamps[key] if tiempo_actual - ts <= 10]

            if len(bot_suspect_timestamps[key]) >= 2:
                diferencia = bot_suspect_timestamps[key][-1] - bot_suspect_timestamps[key][-2]
                if diferencia <= BOT_RESPONSE_TIME_THRESHOLD:
                    return await _registrar_deteccion_bot(telefono, f"velocidad_{diferencia:.1f}s")

        return False
    except Exception as e:
        print(f"⚠️ [BOT DETECT] Error: {e}")
        return False

async def _registrar_deteccion_bot(telefono: str, motivo: str) -> bool:
    if not telefono:
        return True

    key = normalize_phone(telefono)
    tiempo_actual = time.time()

    if key in bot_quarantine:
        if tiempo_actual - bot_quarantine[key].get("ultima_deteccion", 0) > BOT_QUARANTINE_TIME:
            bot_quarantine[key] = {"detecciones": 0, "ultima_deteccion": tiempo_actual, "en_cuarentena": False}
    else:
        bot_quarantine[key] = {"detecciones": 0, "ultima_deteccion": tiempo_actual, "en_cuarentena": False}

    if bot_quarantine[key].get("en_cuarentena", False):
        return True

    bot_quarantine[key]["detecciones"] += 1
    bot_quarantine[key]["ultima_deteccion"] = tiempo_actual

    detecciones = bot_quarantine[key]["detecciones"]

    if detecciones >= BOT_DETECTION_THRESHOLD:
        bot_quarantine[key]["en_cuarentena"] = True
        print(f"🤖 [Cuarentena] Teléfono {key} MARCADO COMO BOT")
        return True

    return False

def limpiar_cuarentena_bots():
    tiempo_actual = time.time()
    keys_to_remove = []
    for key, data in bot_quarantine.items():
        if tiempo_actual - data.get("ultima_deteccion", 0) > BOT_QUARANTINE_TIME * 2:
            keys_to_remove.append(key)
    for key in keys_to_remove:
        del bot_quarantine[key]

def obtener_estado_cuarentena(telefono: str) -> Dict:
    if not telefono:
        return {"en_cuarentena": False, "detecciones": 0}
    key = normalize_phone(telefono)
    if key in bot_quarantine:
        return bot_quarantine[key]
    return {"en_cuarentena": False, "detecciones": 0}

