# ============================================================
#
# Las reservas de cancha ya tenían un reloj crítico independiente que libera
# el slot y encola un aviso al cliente. Las inscripciones de torneo, en cambio,
# persistían hold_expires_at pero no tenían un sweeper equivalente en WPSetter.
# Resultado: el Event Registration Engine podía considerar vencido/libre el
# cupo, pero el cliente no recibía el aviso de los 10 minutos.
#
# Este bloque NO interpreta texto del usuario. Trabaja sólo con estado durable:
# status, hold_expires_at, paid_amount y registration_id.
# ============================================================

_EVENT_REGISTRATION_EXPIRY_QUEUE_KEY = "pending_event_registration_expiration_notifications"
_EVENT_REGISTRATION_EXPIRY_SENT_KEY = "event_registration_expiration_notified"
_LAST_EVENT_REGISTRATION_HOLD_SWEEP_TS = 0.0


def _event_registration_expiration_notification_key(
    event: Dict[str, Any],
    registration: Dict[str, Any],
) -> str:
    event_id = str((event or {}).get("event_id") or "").strip()
    registration_id = str((registration or {}).get("registration_id") or "").strip()
    expired_at = str((registration or {}).get("expired_at") or "").strip()
    return f"event_hold_expired|{event_id}|{registration_id}|{expired_at}"


def _event_registration_expiration_message(
    event: Dict[str, Any],
    registration: Dict[str, Any],
) -> str:
    minutes = int(getattr(event_registration, "EVENT_REGISTRATION_HOLD_MINUTES", 10) or 10)
    event_name = str((event or {}).get("name") or (registration or {}).get("event_name") or "el torneo").strip()
    event_date = str((event or {}).get("date") or (registration or {}).get("event_date") or "").strip()
    team_name = str((registration or {}).get("team_name") or "tu equipo").strip()
    date_text = event_registration.format_event_date(event_date) if event_date else ""
    lines = [
        f"⏳ Pasaron los {minutes} minutos del bloqueo temporal y no recibimos un comprobante validado, así que liberé el cupo de {event_name}.",
        "",
        f"⚽ Equipo: {team_name}",
    ]
    if date_text:
        lines.append(f"📅 Fecha: {date_text}")
    lines.extend([
        "",
        "Si todavía quieren participar, decime y vuelvo a consultar si quedan cupos disponibles.",
    ])
    return "\n".join(lines).strip()


def _event_registration_read_rows_for_event(event: Dict[str, Any]) -> List[Dict[str, Any]]:
    path = _admin_event_csv_path(event)
    if not path or not os.path.exists(path):
        return []
    try:
        with open(path, "r", newline="", encoding="utf-8-sig") as f:
            return [dict(row) for row in csv.DictReader(f)]
    except Exception as exc:
        print(
            "   ⚠️ [EVENT HOLD CLOCK] no pude leer inscripciones "
            f"event_id={(event or {}).get('event_id')}: {exc}"
        )
        return []


def _event_registration_sync_expired_conversation_state(
    event: Dict[str, Any],
    registration: Dict[str, Any],
) -> int:
    registration_id = str((registration or {}).get("registration_id") or "").strip()
    if not registration_id:
        return 0
    changed_count = 0
    for _, state in list(conversation_states.items()):
        if not isinstance(state, dict):
            continue
        event_state = state.get("event_registration")
        if not isinstance(event_state, dict):
            continue
        event_state = dict(event_state)
        changed = False
        active = event_state.get("active_registration")
        if isinstance(active, dict) and str(active.get("registration_id") or "").strip() == registration_id:
            updated_active = dict(active)
            updated_active.update({
                "status": "expired",
                "expired_at": registration.get("expired_at"),
                "hold_expires_at": "",
                "event_name": (event or {}).get("name"),
                "event_date": (event or {}).get("date"),
            })
            event_state["active_registration"] = updated_active
            changed = True
        rows = event_state.get("registrations_for_contact")
        if isinstance(rows, list):
            refreshed = []
            for raw in rows:
                item = dict(raw) if isinstance(raw, dict) else raw
                if isinstance(item, dict) and str(item.get("registration_id") or "").strip() == registration_id:
                    item.update({
                        "status": "expired",
                        "expired_at": registration.get("expired_at"),
                        "hold_expires_at": "",
                    })
                    changed = True
                refreshed.append(item)
            event_state["registrations_for_contact"] = refreshed
        if changed:
            state["event_registration"] = event_state
            state["ultima_actualizacion"] = datetime.datetime.now(TIMEZONE)
            changed_count += 1
    if changed_count:
        _persist_conversation_states()
    return changed_count


def _event_registration_expire_row_if_due(
    event: Dict[str, Any],
    registration: Dict[str, Any],
    now: datetime.datetime,
) -> Tuple[Dict[str, Any], bool]:
    row = dict(registration or {})
    if str(row.get("status") or "").strip().casefold() != "pending_payment":
        return row, False

    # Si ya existe dinero registrado no hacemos una liberación automática. Ese
    # caso pertenece al flujo de pago parcial/revisión, igual que en bookings.
    if (_monto_a_int(row.get("paid_amount")) or 0) > 0:
        return row, False

    expires_at = _parse_iso_datetime(row.get("hold_expires_at"))
    if not expires_at:
        return row, False
    if now < expires_at:
        return row, False

    registration_id = str(row.get("registration_id") or "").strip()
    if not registration_id:
        return row, False

    def mutate(current: Dict[str, Any]) -> Dict[str, Any]:
        current = dict(current or {})
        if str(current.get("status") or "").strip().casefold() != "pending_payment":
            return current
        if (_monto_a_int(current.get("paid_amount")) or 0) > 0:
            return current
        current_expiry = _parse_iso_datetime(current.get("hold_expires_at"))
        if not current_expiry or now < current_expiry:
            return current
        now_iso = now.isoformat()
        current["status"] = "expired"
        current["expired_at"] = str(current.get("expired_at") or now_iso)
        current["hold_expires_at"] = ""
        current["updated_at"] = now_iso
        return current

    result = _admin_mutate_event_registration_row(registration_id, mutate)
    if not result.get("ok"):
        return row, False
    updated = dict(result.get("registration") or row)
    expired = str(updated.get("status") or "").strip().casefold() == "expired"
    return updated, expired


async def expirar_holds_inscripcion_evento_vencidos(
    page=None,
    force: bool = False,
) -> Dict[str, Any]:
    """Libera holds de torneo vencidos y encola el aviso al cliente.

    Es independiente de PROACTIVE_TASK_INTERVAL_SECONDS. El reloj puede correr
    sin `page`; la navegación de WhatsApp ocurre después, con inbox vacío.
    """
    global _LAST_EVENT_REGISTRATION_HOLD_SWEEP_TS

    now_ts = time.time()
    interval = max(1.0, float(PENDING_HOLD_SWEEP_INTERVAL_SECONDS or 2))
    if (
        not force
        and now_ts - _LAST_EVENT_REGISTRATION_HOLD_SWEEP_TS < interval
    ):
        return {"ok": True, "expired": 0, "queued": 0, "throttled": True}
    _LAST_EVENT_REGISTRATION_HOLD_SWEEP_TS = now_ts

    now = datetime.datetime.now(TIMEZONE)
    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queue = state.setdefault(_EVENT_REGISTRATION_EXPIRY_QUEUE_KEY, {})
    notified = state.setdefault(_EVENT_REGISTRATION_EXPIRY_SENT_KEY, {})
    expired_count = 0
    queued_count = 0
    state_changed = False

    try:
        store = _admin_business_events_store()
        events = [dict(item) for item in (store.get("events") or []) if isinstance(item, dict)]
    except Exception as exc:
        print(f"   ⚠️ [EVENT HOLD CLOCK] no pude cargar torneos: {exc}")
        return {"ok": False, "expired": 0, "queued": 0, "error": str(exc)}

    for event in events:
        # Este reloj debe ser quien realice la transición pending_payment ->
        # expired. Si get_event_capacity_state() corre antes, el engine consume
        # silenciosamente esa transición y acá ya no podemos sincronizar memoria,
        # descartar la alerta pending ni registrar/encolar el vencimiento.
        rows = _event_registration_read_rows_for_event(event)
        for original in rows:
            row = dict(original or {})
            row, expired_now = _event_registration_expire_row_if_due(event, row, now)
            if expired_now:
                expired_count += 1
                _discard_pending_event_registration_alerts_for_registration(
                    str(row.get("registration_id") or "").strip()
                )
                _event_registration_sync_expired_conversation_state(event, row)
                registrar_metrica_operativa(
                    "event_registration_hold_10m_expired",
                    {
                        "event_id": event.get("event_id"),
                        "registration_id": row.get("registration_id"),
                        "team_name": row.get("team_name"),
                        "phone": row.get("phone"),
                    },
                )
                print(
                    "   ⏳ [EVENT HOLD EXPIRED] "
                    f"cupo liberado → {event.get('name')} | "
                    f"{row.get('team_name')} | ID={row.get('registration_id')}"
                )

            if str(row.get("status") or "").strip().casefold() != "expired":
                continue

            expired_at = _parse_iso_datetime(row.get("expired_at"))
            if not expired_at:
                continue

            # V175 puede instalarse después de que un hold ya haya vencido. Lo
            # rehidrata sólo dentro de una ventana corta para no mandar avisos
            # históricos al arrancar una versión nueva.
            if now - expired_at > datetime.timedelta(hours=2):
                continue

            key = _event_registration_expiration_notification_key(event, row)
            if notified.get(key) or queue.get(key):
                continue

            phone = normalize_phone(row.get("phone") or "") or str(row.get("phone") or "").strip()
            queue[key] = {
                "queued_at": now.isoformat(),
                "attempts": 0,
                "event": {
                    "event_id": event.get("event_id"),
                    "name": event.get("name"),
                    "date": event.get("date"),
                },
                "registration": dict(row),
                "phone": phone,
                "message": _event_registration_expiration_message(event, row),
            }
            queued_count += 1
            state_changed = True
            print(
                "   📬 [EVENT HOLD NOTICE] aviso de expiración encolado → "
                f"{row.get('team_name')} {phone or 'sin teléfono'}"
            )

    if state_changed or expired_count:
        state["updated_at"] = now.isoformat()
        _json_write(PROACTIVE_STATE_FILE, state)

    delivery = {"sent": 0, "pending": len(queue)}
    if page is not None:
        delivery = await enviar_notificaciones_holds_inscripcion_evento_vencidos(page)
    return {
        "ok": True,
        "expired": expired_count,
        "queued": queued_count,
        "notifications": delivery,
    }


async def enviar_notificaciones_holds_inscripcion_evento_vencidos(
    page,
    max_notifications: int = 3,
) -> Dict[str, Any]:
    """Drena avisos de torneo vencidos sólo cuando WhatsApp puede navegar seguro."""
    snapshot = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    queued = snapshot.get(_EVENT_REGISTRATION_EXPIRY_QUEUE_KEY) or {}
    ordered = sorted(
        queued.items(),
        key=lambda item: str((item[1] or {}).get("queued_at") or ""),
    )
    sent_count = 0

    for key, raw_payload in ordered[:max(1, int(max_notifications or 1))]:
        payload = dict(raw_payload or {})
        registration = dict(payload.get("registration") or {})
        event = dict(payload.get("event") or {})
        message = str(payload.get("message") or "").strip()
        phone = normalize_phone(payload.get("phone") or registration.get("phone") or "")
        if not registration or not message or not phone:
            continue
        if obtener_pausa_contacto_humano(phone):
            continue

        synthetic_row = {
            "telefono": phone,
            "nombre": registration.get("contact_name") or registration.get("team_name") or "",
            "fecha": event.get("date") or registration.get("event_date") or "",
            "hora": "EVENT",
            "cancha": event.get("name") or registration.get("event_name") or "Torneo",
        }
        sent = await enviar_mensaje_cliente_por_reserva(
            page,
            synthetic_row,
            message,
            respetar_inbox=True,
            respetar_pausa=True,
        )

        latest = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
        latest_queue = latest.setdefault(_EVENT_REGISTRATION_EXPIRY_QUEUE_KEY, {})
        latest_notified = latest.setdefault(_EVENT_REGISTRATION_EXPIRY_SENT_KEY, {})
        current = latest_queue.get(key)

        if sent:
            latest_queue.pop(key, None)
            latest_notified[key] = datetime.datetime.now(TIMEZONE).isoformat()
            sent_count += 1
            try:
                add_to_history(phone, "assistant", message)
            except Exception:
                pass
            registrar_metrica_operativa(
                "event_registration_hold_expiration_notice_sent",
                {
                    "event_id": event.get("event_id"),
                    "registration_id": registration.get("registration_id"),
                    "phone": phone,
                },
            )
            print(
                "   ✅ [EVENT HOLD NOTICE] aviso de cupo liberado enviado → "
                f"{registration.get('team_name')}"
            )
        elif isinstance(current, dict):
            current["attempts"] = int(current.get("attempts") or 0) + 1
            current["last_attempt_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            latest_queue[key] = current

        latest["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
        _json_write(PROACTIVE_STATE_FILE, latest)

        if not sent or _reactive_handoff_pending():
            break

    final_state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    return {
        "ok": True,
        "sent": sent_count,
        "pending": len(final_state.get(_EVENT_REGISTRATION_EXPIRY_QUEUE_KEY) or {}),
    }


async def _run_pending_hold_clock():
    """Reloj de leases: no usa la página ni espera que el inbox quede vacío."""
    print(
        f"⏱️ [HOLD CLOCK] activo; revisión cada "
        f"{PENDING_HOLD_SWEEP_INTERVAL_SECONDS:g}s"
    )
    while True:
        try:
            if bot_state.is_active:
                result = await expirar_holds_senia_vencidos(page=None)
                if result.get("expired"):
                    print(
                        f"   📬 [HOLD CLOCK] {result.get('expired')} hold(s) liberado(s); "
                        "aviso encolado para envío seguro"
                    )
                event_result = await expirar_holds_inscripcion_evento_vencidos(page=None)
                if event_result.get("expired") or event_result.get("queued"):
                    print(
                        f"   🏆 [HOLD CLOCK] torneos expired={event_result.get('expired', 0)} "
                        f"queued={event_result.get('queued', 0)}"
                    )
        except asyncio.CancelledError:
            raise
        except Exception as e:
            print(f"   ⚠️ [HOLD CLOCK] error no fatal: {e}")
            registrar_metrica_operativa("senia_hold_clock_error", {"error": str(e)})
        await asyncio.sleep(PENDING_HOLD_SWEEP_INTERVAL_SECONDS)


async def automation_loop(page, profile):
    print("🚀 Iniciando loop de automatización")
    await handle_startup_continue_popup(page)
    print(f"📁 Buscando contactos/reservas en: {NEGOCIOS_CSV}")
    print("🧠 [SelectorAI] Sistema PROACTIVO de auto-aprendizaje activado")
    print("   → Monitorea continuamente la salud de los selectores")
    print("   → Aprende nuevos selectores en segundo plano")
    print("   → Se anticipa a cambios en la UI de WhatsApp")

    init_csv()
    init_integrated_alert_scheduler_db()
    print(
        "🔔 [SCHEDULER INTEGRADO] alertas activas en la misma pestaña; "
        "se envían sólo con inbox vacío"
    )
    registrar_metrica_operativa("automation_loop_start", {"profile": str(profile), "autonomy_level": getattr(bot_state, "autonomy_level", DEFAULT_AUTONOMY_LEVEL)})
    iteracion_count = 0
    proactive_check_interval = 5
    background_tasks = set()
    pending_hold_clock_task = asyncio.create_task(_run_pending_hold_clock())

    async def stop_loop_background_tasks():
        pending_hold_clock_task.cancel()
        for task in list(background_tasks):
            if not task.done():
                task.cancel()
        await asyncio.gather(
            pending_hold_clock_task,
            *list(background_tasks),
            return_exceptions=True,
        )

    while True:
        if page is None or page.is_closed():
            registrar_metrica_operativa(
                "browser_page_closed",
                {"stage": "automation_loop_start", "profile": str(profile)},
            )
            print(
                "🛑 [BROWSER] La página de Chrome se cerró; corto el loop "
                "para permitir un reinicio limpio"
            )
            await stop_loop_background_tasks()
            return "restart_browser"

        iteracion_count += 1

        # 🔍 MONITOREO PROACTIVO DE SELECTORES (EN SEGUNDO PLANO)
        if iteracion_count % proactive_check_interval == 0:
            if not any(not task.done() for task in background_tasks):
                task = asyncio.create_task(_run_proactive_monitor_safely(page))
                background_tasks.add(task)
                task.add_done_callback(background_tasks.discard)

        if iteracion_count % 100 == 0:
            limpiar_cuarentena_bots()

        if not bot_state.is_active:
            print("⏸️ Bot PAUSADO, monitoreando chat de alerta...")
            await monitor_alert_chat_during_pause(page)
            await asyncio.sleep(5)
            continue

        # ============================================================
        # PRIORIDAD ABSOLUTA: INBOX REACTIVO > TAREAS PROACTIVAS
        # ============================================================
        # Un message-out proactivo enviado antes de leer el inbox puede quedar detrás
        # de varios mensajes del cliente y hacer que el detector cronológico los tome
        # falsamente como "ya respondidos". Primero drenamos No leídos. Solo cuando no
        # existe ningún chat pendiente habilitamos recordatorios/expiraciones proactivas.
        await handle_microphone_popup(page)

        # V2.10.4 REACTIVE HANDOFF:
        # una tarea proactiva pudo haber abierto el chat y, al hacerlo, consumir
        # visualmente el badge de "No leídos". Si ya detectó mensajes pendientes,
        # procesamos EL CHAT ABIERTO directamente.
        handoff_chat_abierto = False
        if _reactive_handoff_pending():
            try:
                if await has_unread_user_messages(page):
                    handoff_chat_abierto = True
                    print(
                        "🔁 [INBOX HANDOFF] procesando chat ya abierto; "
                        "no dependo del badge No leídos"
                    )
                else:
                    _clear_reactive_handoff("chat_abierto_sin_pendientes")
            except Exception as e:
                print(f"   ⚠️ [INBOX HANDOFF] no pude validar chat abierto: {e}")
                _clear_reactive_handoff("validation_error")

        if not handoff_chat_abierto:
            if not await click_no_leidos(page):
                print("📭 [INBOX] No pude abrir No leídos → no ejecuto proactivos en esta vuelta")
                await asyncio.sleep(3)
                continue

            if not await click_first_chat(page):
                print("📭 [INBOX] Sin chats no leídos → verifico holds y luego proactivos")

                # El reloj ya liberó el calendario sin navegar. Acá, con inbox
                # vacío confirmado, sólo drenamos los avisos persistentes.
                await enviar_notificaciones_holds_senia_vencidos(page)
                await enviar_notificaciones_holds_inscripcion_evento_vencidos(page)
                if _reactive_handoff_pending():
                    print(
                        "🔁 [INBOX HANDOFF] mensaje entrante detectado durante sweep "
                        "→ proceso reactivo en próxima vuelta"
                    )
                    await asyncio.sleep(0.5)
                    continue

                await ejecutar_tareas_proactivas(page)
                if _reactive_handoff_pending():
                    print(
                        "🔁 [INBOX HANDOFF] proactivo cedió ante mensaje entrante "
                        "→ proceso reactivo en próxima vuelta"
                    )
                    await asyncio.sleep(0.5)
                    continue

                await asyncio.sleep(3)
                continue

        print("📨 [INBOX] Chat pendiente detectado → proceso mensajes ANTES de cualquier proactivo")

        if await es_chat_grupo_whatsapp(page):
            print("👥 [Grupo] Chat grupal descartado → no respondo ni registro mensajes")
            registrar_metrica_operativa("chat_grupo_descartado", {"motivo": "grupo_whatsapp"})
            await escape_chat(page)
            await asyncio.sleep(2)
            continue

        telefono = await get_phone_from_chat(page)
        if telefono:
            print(f"📱 Teléfono detectado: {telefono}")
            telefono = await resolver_telefono_real_si_es_nombre(page, telefono)
            if telefono and not str(telefono).startswith("NOMBRE:"):
                print(f"📱 Teléfono real activo: {telefono}")
        else:
            print("⚠️ No se pudo detectar teléfono")

        if telefono_en_blacklist(telefono or ""):
            print(f"🚫 [BLACKLIST] {telefono} bloqueado → escapando sin responder")
            await escape_chat(page)
            await asyncio.sleep(2)
            continue

        if await omitir_chat_pausado_por_humano(page, telefono or ""):
            await asyncio.sleep(2)
            continue

        if not await has_unread_user_messages(page):
            print("⏭️ No hay mensajes del usuario sin responder")
            if iteracion_count % 30 == 0:
                await diagnostic_bubble_selectors(page)
            await page.keyboard.press("Escape")
            await click_todos(page)
            await check_session_and_alert(page)
            await enviar_notificaciones_holds_senia_vencidos(page)
            await enviar_notificaciones_holds_inscripcion_evento_vencidos(page)
            if _reactive_handoff_pending():
                print(
                    "🔁 [INBOX HANDOFF] aviso de hold cedió ante mensaje entrante "
                    "→ proceso reactivo en próxima vuelta"
                )
                await asyncio.sleep(0.5)
                continue
            await asyncio.sleep(1)
            continue

        # Lee primero el backlog posterior al último message-out y procesa cada
        # audio pendiente con la ruta estable de copia (132). Todas las
        # transcripciones llegan juntas y en orden a Perception/subintenciones.
        user_messages, image_path_recibida = (
            await read_user_messages_with_pending_media(page)
        )
        if image_path_recibida:
            print(f"🖼️ [IMAGEN] Archivo descargado: {image_path_recibida}")

        if page is None or page.is_closed():
            recovery_armed = _arm_media_browser_recovery(
                telefono or "",
                "browser_closed_during_media_batch",
            )
            registrar_metrica_operativa(
                "browser_page_closed",
                {
                    "stage": "after_media_handler",
                    "profile": str(profile),
                    "telefono": str(telefono or ""),
                    "media_recovery_armed": bool(recovery_armed),
                },
            )
            print(
                "🛑 [BROWSER] Chrome se cerró durante el procesamiento multimedia; "
                "guardo el chat y corto el loop para permitir un reinicio limpio"
            )
            await stop_loop_background_tasks()
            return "restart_browser"

        # Un batch de audio incompleto no se marca como respondido. Conservamos
        # el chat abierto para reintentar aunque WhatsApp ya haya consumido el
        # badge visual de No leídos.
        if not user_messages and await has_unread_user_messages(page):
            _mark_reactive_handoff(
                telefono or "",
                "media_batch_incomplete",
            )

        # V199: si venimos de un restart causado por media, el recovery sólo se
        # considera resuelto cuando el backlog multimedia volvió a materializarse
        # correctamente. Hasta entonces el target permanece armado para otro
        # restart/reintento y jamás se crea un message-out artificial.
        if user_messages and _media_browser_recovery_matches(telefono or ""):
            _clear_media_browser_recovery("media_batch_reprocessed_successfully")

        # CURRENT USER TURN AUTHORITY: jamás concatenar un pedido viejo con uno
        # nuevo solo porque ambos siguen sin message-out en WhatsApp.
        user_messages, superseded_user_messages = _resolve_current_user_turn(
            user_messages,
            _LAST_READ_USER_MESSAGE_META,
        )

        if handoff_chat_abierto and user_messages:
            _clear_reactive_handoff("reactive_router_claimed")

        if not _memory_owner_is_stable(telefono or ""):
            print(
                "🚫 [MEMORY ISOLATION] No pude resolver una identidad estable "
                "para este chat → no respondo para evitar memoria compartida"
            )
            registrar_metrica_operativa(
                "chat_identity_unresolved",
                {"telefono_detectado": str(telefono or "")},
            )
            await escape_chat(page)
            await asyncio.sleep(2)
            continue

        sincronizar_reanudacion_humana(telefono)
        conv_state = get_conversation_state(telefono)
        conv_state, _ = expirar_post_turno_followup_si_corresponde(
            telefono or "unknown",
            conv_state,
        )

        if user_messages and await manejar_comando_autorizado(page, telefono or "", user_messages):
            await asyncio.sleep(3)
            continue

        es_bot = await es_respuesta_de_bot(page, telefono)

        if es_bot:
            estado_cuarentena = obtener_estado_cuarentena(telefono)
            if estado_cuarentena.get("en_cuarentena", False):
                print("🤖 [BOT DETECT] Contacto confirmado como bot → escapando chat")
                await escape_chat(page)
                if telefono:
                    actualizar_estado_en_negocios_csv(telefono, "Bot - descartado")
            await asyncio.sleep(3)
            continue

        if not user_messages and conv_state.get("fase") != "senia_pendiente":
            print("⚠️ No hay mensajes del usuario")
            await asyncio.sleep(1)
            await click_todos(page)
            continue

        print(f"\n📨 Mensajes ({len(user_messages)}):")
        for msg in user_messages:
            print(f"   • {msg[:80]}")

        prospecto = await obtener_datos_prospecto(page, telefono, user_messages)

        print(f"\n📋 CONTACTO:")
        print(f"   👤 Nombre: {prospecto['nombre']}")
        print(f"   🏟️ Referencia: {prospecto['negocio']}")
        print(f"   🌐 Website: {prospecto['website']}")
        print(f"   📱 Teléfono: {prospecto['telefono']}")
        print(f"   🤝 Es cliente?: {prospecto.get('es_cliente', CLIENTE_NO)}")

        if _normalizar_nombre_blacklist(prospecto.get("nombre")) == "whatsapp business":
            print("[BLACKLIST POR DEFECTO] WhatsApp Business -> escapo sin procesar la conversacion")
            await escape_chat(page)
            await asyncio.sleep(2)
            continue

        if user_messages and await manejar_comando_autorizado(page, telefono or "", user_messages, prospecto):
            await asyncio.sleep(3)
            continue

        prospecto = actualizar_cliente_si_corresponde(telefono, conv_state, prospecto)

        sincronizar_cliente_desde_prospecto(conv_state, prospecto)
        memoria_cliente = actualizar_memoria_cliente_desde_prospecto(telefono or "unknown", prospecto, conv_state)
        conv_state["memoria_cliente"] = memoria_cliente
        print(
            f"\n📊 Estado conversación: fase={conv_state['fase']}, "
            f"día={conv_state.get('dia_propuesto')}, "
            f"hora={conv_state.get('hora_propuesta')}, "
            f"cancha={conv_state.get('cancha_propuesta')}"
        )

        ultimo_mensaje = user_messages[-1] if user_messages else ""
        cliente_existente_actual = bool(
            prospecto_es_cliente(prospecto)
            or (conv_state.get("hechos") or {}).get("cliente_estado")
            == "cliente_existente"
        )

        if cliente_existente_actual:
            prospecto["es_cliente"] = CLIENTE_SI
            prospecto["estado_actual"] = "Cliente existente"

        for msg in user_messages:
            add_to_history(telefono or "unknown", "user", msg)

        fase_actual = conv_state.get("fase", "inicial")
        # user_messages ya representa exclusivamente el CURRENT USER TURN.
        texto_combinado = " ".join(user_messages)
        lote_semantico = "\n".join(user_messages)
        estaba_esperando_duracion_quincho = fase_actual == "esperando_duracion_quincho"

        # Sólo un recordatorio realmente entregado habilita este ACK. La IA
        # interpreta el lenguaje; Python confirma el evento exacto.
        attendance_event = obtener_confirmacion_asistencia_pendiente_scheduler(
            telefono or "",
        )
        if attendance_event:
            attendance_semantics = await detectar_respuesta_asistencia_ia(
                texto_combinado,
                attendance_event,
            )
            if (
                attendance_semantics.get("classification") == "affirmative"
                and marcar_confirmacion_asistencia_scheduler(
                    telefono or "",
                    attendance_event.get("id"),
                )
            ):
                respuesta_asistencia = "Perfecto, asistencia confirmada. Te esperamos."
                await send_message(page, respuesta_asistencia)
                add_to_history(
                    telefono or "unknown",
                    "assistant",
                    respuesta_asistencia,
                )
                guardar_historial_chat(
                    telefono or "unknown",
                    user_messages,
                    respuesta_asistencia,
                )
                await asyncio.sleep(3)
                continue
            print(
                "   🧠 [ASISTENCIA IA] respuesta no afirmativa; "
                "continúa al agente para resolver el mensaje completo"
            )

        # La propuesta semanal es memoria temporal lateral, no una fase. Sólo
        # una aceptación semántica inequívoca del mismo turno puede usarla.
        followup_context = (conv_state.get("post_turno_followup") or {})
        if followup_context.get("activo"):
            resultado_followup = await manejar_respuesta_post_turno_followup(
                telefono or "unknown",
                prospecto,
                user_messages,
                conv_state,
            )
            if resultado_followup:
                respuesta_followup = (
                    resultado_followup.get("respuesta")
                    or "Perfecto, bloqueé el turno mientras espero la seña."
                )
                followup_sent = await send_message(page, respuesta_followup)
                if followup_sent is True and resultado_followup.get("ok"):
                    enqueue_pending_booking_admin_alert(
                        resultado_followup,
                        telefono or "unknown",
                        prospecto,
                    )
                add_to_history(
                    telefono or "unknown",
                    "assistant",
                    respuesta_followup,
                )
                guardar_historial_chat(
                    telefono or "unknown",
                    user_messages,
                    respuesta_followup,
                )
                await asyncio.sleep(3)
                continue
            conv_state = get_conversation_state(telefono or "unknown")
            fase_actual = conv_state.get("fase", "inicial")

        # Event Registration tiene prioridad sobre el recuperador legacy de
        # señas/holds de cancha cuando existe una obligación de torneo real.
        # Sin esta barrera, una imagen enviada justo después de que el agente
        # pide el comprobante del torneo puede ser consumida por una reserva
        # histórica y recibir importes/fecha/cancha equivocados.
        event_payment_priority = bool(
            image_path_recibida
            and _event_registration_has_payable_context(telefono or "unknown")
        )
        if event_payment_priority:
            print(
                "   🏆 [EVENT PAYMENT ROUTER] comprobante reservado para "
                "Event Registration; omito late-booking credit legacy"
            )
            credit_flow_result = None
        else:
            credit_flow_result = await manejar_pago_tardio_o_credito_senia(
                telefono or "unknown",
                prospecto,
                user_messages,
                image_path=image_path_recibida or "",
            )
        if credit_flow_result and credit_flow_result.get("handled"):
            image_path_recibida = None
            respuesta_credito = str(
                credit_flow_result.get("respuesta")
                or "Tu seña sigue registrada y necesito que el encargado revise el caso."
            ).strip()
            credit_failure_signal = _agent_v2_v140_internal_failure_signal(
                respuesta_credito
            )
            if credit_failure_signal:
                respuesta_credito, sent_credit_response = (
                    await _agent_v2_v140_send_legacy_internal_handoff(
                        page,
                        source=credit_failure_signal,
                        original_response=respuesta_credito,
                        telefono=telefono or "unknown",
                        prospecto=prospecto,
                        mensaje_usuario=" ".join(user_messages or []),
                    )
                )
            else:
                sent_credit_response = await send_message(page, respuesta_credito)
            if sent_credit_response:
                add_to_history(
                    telefono or "unknown",
                    "assistant",
                    respuesta_credito,
                )
                guardar_historial_chat(
                    telefono or "unknown",
                    user_messages,
                    respuesta_credito,
                )
                admin_alert = str(
                    credit_flow_result.get("admin_alert") or ""
                ).strip()
                if admin_alert and not credit_failure_signal:
                    await enviar_aviso_admin_directo(
                        page,
                        admin_alert,
                        dedupe_key=str(
                            credit_flow_result.get("admin_dedupe_key") or ""
                        ),
                        respect_inbox=True,
                    )
            await asyncio.sleep(3)
            continue

        # ============================================================
        # AGENT V2 — WORLD → GOALS → PLAN → TOOLS → OBSERVE → REPLAN
        # ============================================================
        agent_v2_result = await ejecutar_agente_real_v2_turno(
            lote_semantico,
            conv_state,
            prospecto,
            telefono or "unknown",
            user_messages=user_messages,
            page=page,
            image_path=image_path_recibida or "",
        )

        if agent_v2_result.get("status") == "paused_human":
            _clear_reactive_handoff("agent_v2_contacto_pausado")
            await escape_chat(page)
            continue

        if agent_v2_result.get("handled"):
            respuesta_agent_v2 = agent_v2_result.get("response")

            # V190: SILENT HANDOFF ES TERMINAL. Un resultado manejado cuya
            # política de entrega suprime al cliente consume el turno aunque la
            # respuesta sea "". Nunca cae a DecisionEngine/legacy y por lo tanto
            # jamás puede enviar un fallback después de registrar el handoff.
            suppress_customer = bool(
                agent_v2_result.get("silent_handoff")
                or agent_v2_result.get("customer_response_suppressed")
                or str(agent_v2_result.get("delivery_policy") or "") == "suppress_customer"
            )
            if suppress_customer:
                print(
                    "   🤫 [CANONICAL V190 TERMINAL SUPPRESSION] "
                    "turno consumido; DecisionEngine/legacy omitidos"
                )
                try:
                    await escape_chat(page)
                except Exception:
                    pass
                await asyncio.sleep(0)
                continue

            if respuesta_agent_v2:
                print(
                    f"   🧠 [AGENT V2 EXEC] goal="
                    f"{(agent_v2_result.get('goals') or {}).get('primary_goal')} "
                    f"status={agent_v2_result.get('status')}"
                )
                customer_response_sent = await enviar_respuesta_agent_v2_antes_de_alertas(
                    page,
                    respuesta_agent_v2,
                    agent_v2_result,
                    telefono or "unknown",
                    prospecto,
                )
                if customer_response_sent:
                    add_to_history(telefono or "unknown", "assistant", respuesta_agent_v2)
                    guardar_historial_chat(
                        telefono or "unknown",
                        user_messages,
                        respuesta_agent_v2,
                    )
                await asyncio.sleep(3)
                continue

        # ============================================================
        # DECISION ENGINE V1 — COMPATIBILIDAD / EXECUTOR LEGACY
        # ============================================================
        # Solo se alcanza si Agent V2 delegó explícitamente una capacidad todavía no
        # encapsulada. V1 ya no es el cerebro principal.
        decision_engine_result = await ejecutar_decision_engine_turno(
            lote_semantico,
            get_conversation_state(telefono or "unknown"),
            prospecto,
            telefono or "unknown",
        )

        sub_intenciones_lote = decision_engine_result.get("sub_intenciones") or []

        texto_normalizado_engine = decision_engine_result.get("texto_normalizado")
        if texto_normalizado_engine:
            ultimo_mensaje = texto_normalizado_engine
            texto_combinado = texto_normalizado_engine
            lote_semantico = texto_normalizado_engine

        # El executor del engine puede haber actualizado memoria/estado.
        conv_state = get_conversation_state(telefono or "unknown")
        fase_actual = conv_state.get("fase", "inicial")
        estaba_esperando_duracion_quincho = fase_actual == "esperando_duracion_quincho"

        if decision_engine_result.get("handled"):
            respuesta_engine = decision_engine_result.get("response")
            if respuesta_engine:
                respuesta_engine = aplicar_negrita_fechas_horas_whatsapp(respuesta_engine)
                print(
                    f"   ✅ [DecisionEngine EXEC] "
                    f"{decision_engine_result.get('action')} resolvió el turno"
                )
                await send_message(page, respuesta_engine)
                add_to_history(telefono or "unknown", "assistant", respuesta_engine)
                guardar_historial_chat(
                    telefono or "unknown",
                    user_messages,
                    respuesta_engine,
                )
                await asyncio.sleep(3)
                continue

        hay_accion_quincho_lote = any(
            str(item.get("intencion") or "") == "reservar_quincho"
            and str(item.get("efecto") or "escritura").lower() != "lectura"
            for item in sub_intenciones_lote
            if isinstance(item, dict)
        )

        if (
            (estaba_esperando_duracion_quincho or hay_accion_quincho_lote)
            and not mensaje_pide_evento_o_dia_completo(texto_combinado)
        ):
            quincho_nombre = normalizar_nombre_quincho(conv_state.get("quincho") or "")
            duracion_quincho = extraer_duracion_quincho_de_texto(texto_combinado)
            if fase_actual == "esperando_duracion_quincho" and duracion_quincho is None:
                duracion_quincho = extraer_duracion_de_texto(texto_combinado)

            dia_quincho = None
            hora_quincho = None
            cancha_quincho = None
            if not estaba_esperando_duracion_quincho:
                dia_quincho = await extraer_dia_con_ia(texto_combinado, conv_state)
                hora_quincho = await extraer_hora_de_texto(texto_combinado, conv_state)
                cancha_quincho = extraer_cancha_de_mensaje(texto_combinado, conv_state)
            marcar_quincho_solicitado_en_draft(
                telefono or "unknown",
                True,
                origen="usuario",
            )
            update_payload = {
                "con_quincho": True,
                "quincho": quincho_nombre,
                "quincho_confirmacion_origen": "usuario",
            }
            if dia_quincho:
                update_payload["dia_propuesto"] = dia_quincho
            if hora_es_valida(hora_quincho):
                update_payload["hora_propuesta"] = hora_quincho
                update_payload["quincho_hora_inicio"] = hora_quincho
            if cancha_quincho:
                update_payload["cancha_propuesta"] = cancha_quincho
            if duracion_quincho is not None:
                duracion_quincho_norm = normalizar_duracion_horas(duracion_quincho)
                hora_base_quincho = hora_quincho if hora_es_valida(hora_quincho) else conv_state.get("hora_propuesta")
                if fase_actual == "esperando_duracion_quincho" and not conv_state.get("duracion_cancha_explicita"):
                    duracion_base_cancha = normalizar_duracion_horas(DEFAULT_TURN_DURATION_HOURS)
                else:
                    duracion_base_cancha = normalizar_duracion_horas(
                        conv_state.get("duracion_cancha_horas")
                        or conv_state.get("duracion_propuesta")
                        or DEFAULT_TURN_DURATION_HOURS
                    )
                quincho_inicio_detectado = await extraer_inicio_quincho_con_ia(
                    texto_combinado,
                    hora_base_quincho,
                    duracion_base_cancha,
                    duracion_quincho_norm
                ) if hora_base_quincho else ""
                update_payload["duracion_propuesta"] = duracion_base_cancha
                update_payload["duracion_cancha_horas"] = duracion_base_cancha
                update_payload["quincho_hora_inicio"] = quincho_inicio_detectado or hora_base_quincho or ""
                update_payload["quincho_hora_fin"] = hora_fin_bloque(update_payload["quincho_hora_inicio"], duracion_quincho_norm) if update_payload["quincho_hora_inicio"] else ""
                update_payload["quincho_duracion_horas"] = duracion_quincho_norm
                update_payload["fase"] = "coordinacion_propuesta"
            update_conversation_state(telefono or "unknown", **update_payload)
            conv_state = get_conversation_state(telefono or "unknown")
            fase_actual = conv_state.get("fase", "inicial")

            if (
                fase_actual == "coordinacion_propuesta"
                and mensaje_pide_quincho(texto_combinado)
                and conv_state.get("dia_propuesto")
                and hora_es_valida(conv_state.get("hora_propuesta"))
                and conv_state.get("cancha_propuesta")
                and not estaba_esperando_duracion_quincho
            ):
                dia_q = conv_state.get("dia_propuesto")
                hora_q = conv_state.get("hora_propuesta")
                cancha_q = conv_state.get("cancha_propuesta")
                duracion_cancha_q = normalizar_duracion_horas(
                    conv_state.get("duracion_cancha_horas")
                    or conv_state.get("duracion_propuesta")
                    or DEFAULT_TURN_DURATION_HOURS
                )
                duracion_quincho_q = normalizar_duracion_horas(
                    conv_state.get("quincho_duracion_horas") or duracion_cancha_q
                )
                quincho_inicio_q = (
                    conv_state.get("quincho_hora_inicio")
                    or _quincho_default_start_after_court(
                        hora_q,
                        conv_state.get("duracion_cancha_horas")
                        or conv_state.get("duracion_propuesta")
                        or DEFAULT_TURN_DURATION_HOURS,
                    )
                )
                quincho_fin_q = hora_fin_bloque(quincho_inicio_q, duracion_quincho_q)
                quincho_nombre = normalizar_nombre_quincho(conv_state.get("quincho") or quincho_nombre)

                if not quincho_libre_para_bloque(dia_q, quincho_inicio_q, duracion_quincho_q, quincho_nombre):
                    respuesta = (
                        f"Tengo {cancha_q} disponible a las {formatear_hora_para_mensaje(hora_q)}, "
                        f"pero {quincho_nombre} no está libre de {rango_horario_texto(quincho_inicio_q, duracion_quincho_q)}. "
                        "¿Querés que busque otro horario con cancha y quincho disponibles?"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        con_quincho=True,
                        quincho=quincho_nombre,
                        quincho_hora_inicio=quincho_inicio_q,
                        quincho_hora_fin=quincho_fin_q,
                        quincho_duracion_horas=duracion_quincho_q,
                    )
                    await send_message(page, aplicar_negrita_fechas_horas_whatsapp(respuesta))
                    add_to_history(telefono or "unknown", "assistant", respuesta)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                    await asyncio.sleep(3)
                    continue

                resultado_pendiente = reservar_turno_en_calendario(
                    telefono or "desconocido",
                    prospecto,
                    dia_q,
                    hora_q,
                    cancha=cancha_q,
                    estado_reserva=BOOKING_STATUS_PENDING,
                    senia_estado="pendiente",
                    senia_monto="",
                    duracion_horas=duracion_cancha_q,
                    con_quincho=True,
                    quincho=quincho_nombre,
                    quincho_hora_inicio=quincho_inicio_q,
                    quincho_duracion_horas=duracion_quincho_q,
                    es_nuevo_turno=True,
                )
                if resultado_pendiente.get("ok"):
                    precio_total_pendiente = _monto_a_int(resultado_pendiente.get("precio_total")) or (
                        calcular_precio_total(duracion_cancha_q) + calcular_precio_quincho_total(quincho_nombre, duracion_quincho_q)
                    )
                    senia_valor_pendiente = _monto_a_int(resultado_pendiente.get("senia_valor"))
                    if senia_valor_pendiente is None:
                        senia_valor_pendiente = _senia_para_total(precio_total_pendiente)
                    monto_pendiente_reserva = calcular_monto_pendiente(precio_total_pendiente, senia_valor_pendiente)
                    respuesta = build_reserva_pendiente_senia_message(
                        resultado_pendiente.get("dia") or dia_q,
                        resultado_pendiente.get("hora") or hora_q,
                        resultado_pendiente.get("cancha") or cancha_q,
                        duracion_cancha_q,
                        precio_total_pendiente,
                        senia_valor_pendiente,
                        monto_pendiente_reserva,
                        con_quincho=True,
                        quincho=resultado_pendiente.get("quincho") or quincho_nombre,
                        quincho_hora_inicio=resultado_pendiente.get("quincho_hora_inicio") or quincho_inicio_q,
                        quincho_duracion_horas=resultado_pendiente.get("quincho_duracion_horas") or duracion_quincho_q,
                        quincho_precio_total=_monto_a_int(resultado_pendiente.get("quincho_precio_total")) or calcular_precio_quincho_total(quincho_nombre, duracion_quincho_q),
                    ).replace("__NO_CONSOLIDAR__", "", 1).strip()
                    update_conversation_state(
                        telefono or "unknown",
                        fase="senia_pendiente",
                        dia_propuesto=resultado_pendiente.get("dia") or dia_q,
                        hora_propuesta=resultado_pendiente.get("hora") or hora_q,
                        cancha_propuesta=resultado_pendiente.get("cancha") or cancha_q,
                        duracion_propuesta=duracion_cancha_q,
                        duracion_cancha_horas=duracion_cancha_q,
                        duracion_cancha_explicita=bool(conv_state.get("duracion_cancha_explicita")),
                        con_quincho=True,
                        quincho=resultado_pendiente.get("quincho") or quincho_nombre,
                        quincho_hora_inicio=resultado_pendiente.get("quincho_hora_inicio") or quincho_inicio_q,
                        quincho_hora_fin=resultado_pendiente.get("quincho_hora_fin") or quincho_fin_q,
                        quincho_duracion_horas=duracion_quincho_q,
                        senia_estado="pendiente",
                        senia_monto=_monto_humano(senia_valor_pendiente),
                        quiere_nuevo_turno=False,
                    )
                    registrar_turno_confirmado_en_csv(
                        telefono or "desconocido",
                        prospecto,
                        user_messages,
                        resultado_pendiente.get("dia") or dia_q,
                        resultado_pendiente.get("hora") or hora_q,
                    )
                else:
                    respuesta = resultado_pendiente.get("respuesta") or "No pude guardar ese turno. ¿Querés que busque otro horario?"

                respuesta = aplicar_negrita_fechas_horas_whatsapp(respuesta)
                pending_failure_signal = _agent_v2_v140_internal_failure_signal(
                    respuesta
                )
                if pending_failure_signal:
                    respuesta, pending_sent = (
                        await _agent_v2_v140_send_legacy_internal_handoff(
                            page,
                            source=pending_failure_signal,
                            original_response=respuesta,
                            telefono=telefono or "unknown",
                            prospecto=prospecto,
                            mensaje_usuario=" ".join(user_messages or []),
                        )
                    )
                else:
                    pending_sent = await send_message(page, respuesta)
                if pending_sent is True and resultado_pendiente.get("ok"):
                    enqueue_pending_booking_admin_alert(
                        resultado_pendiente,
                        telefono or "unknown",
                        prospecto,
                    )
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            if estaba_esperando_duracion_quincho and conv_state.get("quincho_duracion_horas"):
                dia_q = conv_state.get("dia_propuesto")
                hora_q = conv_state.get("hora_propuesta")
                cancha_q = conv_state.get("cancha_propuesta")
                duracion_cancha_q = normalizar_duracion_horas(
                    conv_state.get("duracion_cancha_horas") if conv_state.get("duracion_cancha_explicita") else DEFAULT_TURN_DURATION_HOURS
                )
                duracion_quincho_q = normalizar_duracion_horas(conv_state.get("quincho_duracion_horas"))
                quincho_hora_inicio_q = await extraer_inicio_quincho_con_ia(
                    texto_combinado,
                    hora_q,
                    duracion_cancha_q,
                    duracion_quincho_q
                ) or conv_state.get("quincho_hora_inicio") or _quincho_default_start_after_court(
                    hora_q,
                    conv_state.get("duracion_cancha_horas")
                    or conv_state.get("duracion_propuesta")
                    or DEFAULT_TURN_DURATION_HOURS,
                )
                quincho_hora_fin_q = hora_fin_bloque(quincho_hora_inicio_q, duracion_quincho_q)
                canchas_libres_q = conv_state.get("canchas_libres") or []
                if dia_q and hora_es_valida(hora_q):
                    if not canchas_libres_q:
                        canchas_libres_q = canchas_libres_para_bloque(dia_q, hora_q, duracion_cancha_q, cancha_q)
                    if cancha_q and cancha_q not in canchas_libres_q:
                        canchas_libres_q = [cancha_q] + [c for c in canchas_libres_q if c != cancha_q]
                    if not quincho_libre_para_bloque(dia_q, quincho_hora_inicio_q, duracion_quincho_q, quincho_nombre):
                        respuesta = (
                            f"Tengo cancha disponible a las {formatear_hora_para_mensaje(hora_q)}, "
                            f"pero {quincho_nombre} no está libre de {rango_horario_texto(quincho_hora_inicio_q, duracion_quincho_q)}. "
                            "¿Querés que busque otro horario con cancha y quincho disponibles?"
                        )
                    else:
                        respuesta = build_resumen_preconfirmacion_con_quincho(
                            dia_q,
                            hora_q,
                            cancha_q if cancha_q in canchas_libres_q else "",
                            canchas_libres_q,
                            duracion_cancha_q,
                            quincho_nombre,
                            duracion_quincho_q,
                            quincho_hora_inicio_q
                        )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_q,
                        hora_propuesta=hora_q,
                        cancha_propuesta=cancha_q if cancha_q in canchas_libres_q else None,
                        canchas_libres=canchas_libres_q,
                        duracion_propuesta=duracion_cancha_q,
                        duracion_cancha_horas=duracion_cancha_q,
                        con_quincho=True,
                        quincho=quincho_nombre,
                        quincho_hora_inicio=quincho_hora_inicio_q,
                        quincho_hora_fin=quincho_hora_fin_q,
                        quincho_duracion_horas=duracion_quincho_q
                    )
                    await send_message(page, respuesta)
                    add_to_history(telefono or "unknown", "assistant", respuesta)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                    await asyncio.sleep(3)
                    continue

            if fase_actual == "esperando_duracion_quincho" and not conv_state.get("quincho_duracion_horas"):
                respuesta = build_pregunta_duracion_quincho_message(quincho_nombre, conv_state.get("hora_propuesta") or "")
                receipt_failure_signal = _agent_v2_v140_internal_failure_signal(
                    respuesta
                )
                if receipt_failure_signal:
                    respuesta, _ = await _agent_v2_v140_send_legacy_internal_handoff(
                        page,
                        source=receipt_failure_signal,
                        original_response=respuesta,
                        telefono=telefono or "unknown",
                        prospecto=prospecto,
                        mensaje_usuario=" ".join(user_messages or []),
                    )
                else:
                    await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            if fase_actual == "esperando_duracion_quincho":
                update_conversation_state(telefono or "unknown", fase="coordinacion_propuesta")
                conv_state = get_conversation_state(telefono or "unknown")
                fase_actual = conv_state.get("fase", "inicial")

        if fase_actual == "esperando_motivo_cancelacion":
            motivo_cancelacion = texto_combinado.strip()
            registrar_motivo_cancelacion_cliente(telefono or "unknown", motivo_cancelacion)
            update_conversation_state(telefono or "unknown", fase="inicial", motivo_cancelacion_pendiente=None)
            respuesta = "Gracias, lo dejo anotado. Cuando quieras buscamos otro horario."
            await send_message(page, respuesta)
            add_to_history(telefono or "unknown", "assistant", respuesta)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
            await asyncio.sleep(3)
            continue

        if fase_actual == "esperando_nombre_reserva":
            resultado_nombre = await manejar_nombre_reserva_pendiente(
                telefono or "unknown",
                prospecto,
                user_messages,
                conv_state
            )
            respuesta = resultado_nombre.get("respuesta") or "Perfecto, te lo dejo reservado. Mandame el comprobante de la seña para confirmarlo."
            name_response_sent = await send_message(page, respuesta)
            if name_response_sent is True and resultado_nombre.get("ok"):
                enqueue_pending_booking_admin_alert(
                    resultado_nombre,
                    telefono or "unknown",
                    prospecto,
                )
            add_to_history(telefono or "unknown", "assistant", respuesta)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
            await asyncio.sleep(3)
            continue

        if fase_actual == "no_show_reagendar":
            resultado_reagendar = await manejar_respuesta_no_show_reagendar(
                telefono or "unknown",
                user_messages,
                conv_state
            )
            if resultado_reagendar:
                respuesta = resultado_reagendar.get("respuesta") or "Dale, decime qué día y horario te sirve."
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

        # La aclaración horaria ya se resolvió con prioridad al inicio del turno.

        hora_corta = resolver_hora_corta_por_franja(texto_combinado)
        if hora_corta.get("requiere_aclaracion") and not _mensaje_responde_pregunta_de_cancha(conv_state):
            respuesta = build_hora_ambigua_message(hora_corta.get("opciones") or [])
            contexto_disp_para_aclaracion = obtener_consulta_disponibilidad_pendiente(conv_state)
            update_conversation_state(
                telefono or "unknown",
                fase="esperando_aclaracion_hora",
                hora_opciones=hora_corta.get("opciones") or [],
                fase_previa_hora=fase_actual,
                aclaracion_hora_contexto=(
                    {
                        "tipo": "consulta_disponibilidad",
                        "consulta_disponibilidad": contexto_disp_para_aclaracion,
                        "creado_en": datetime.datetime.now(TIMEZONE).isoformat(),
                    }
                    if contexto_disp_para_aclaracion
                    else {
                        "tipo": "flujo_general",
                        "creado_en": datetime.datetime.now(TIMEZONE).isoformat(),
                    }
                ),
            )
            await send_message(page, respuesta)
            add_to_history(telefono or "unknown", "assistant", respuesta)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
            await asyncio.sleep(3)
            continue

        reserva_pendiente_excel = calendario.obtener_reserva_por_telefono(
            telefono or "unknown",
            prospecto.get("nombre")
        )
        if reserva_tiene_senia_pendiente(reserva_pendiente_excel):
            if propuesta_activa_distinta_de_reserva(conv_state, reserva_pendiente_excel):
                print(
                    f"   🧾 [SEÑA] Hay una seña pendiente en CSV, pero preservo la propuesta activa: "
                    f"{conv_state.get('dia_propuesto')} {conv_state.get('hora_propuesta')} "
                    f"(pendiente CSV: {reserva_pendiente_excel.get('fecha')} {reserva_pendiente_excel.get('hora')})"
                )
            else:
                reserva_pendiente_con_quincho = _reserva_indica_quincho(reserva_pendiente_excel)
                update_conversation_state(
                    telefono or "unknown",
                    fase="senia_pendiente",
                    dia_propuesto=reserva_pendiente_excel.get("fecha"),
                    hora_propuesta=reserva_pendiente_excel.get("hora"),
                    cancha_propuesta=reserva_pendiente_excel.get("cancha"),
                    con_quincho=reserva_pendiente_con_quincho,
                    quincho_confirmacion_origen=("reserva_existente" if reserva_pendiente_con_quincho else None),
                    quincho=(reserva_pendiente_excel.get("quincho") or "") if reserva_pendiente_con_quincho else "",
                    quincho_hora_inicio=(reserva_pendiente_excel.get("quincho_hora_inicio") or "") if reserva_pendiente_con_quincho else "",
                    quincho_hora_fin=(reserva_pendiente_excel.get("quincho_hora_fin") or "") if reserva_pendiente_con_quincho else "",
                    quincho_duracion_horas=(reserva_pendiente_excel.get("quincho_duracion_horas") or None) if reserva_pendiente_con_quincho else None,
                    senia_estado="pendiente",
                    senia_monto=reserva_pendiente_excel.get("senia_monto") or _monto_humano(
                        _senia_para_total(reserva_pendiente_excel.get("precio_total"))
                    )
                )
                conv_state = get_conversation_state(telefono or "unknown")
                fase_actual = "senia_pendiente"
                print(
                    f"   🧾 [SEÑA] Contexto pendiente recuperado del CSV: "
                    f"{conv_state.get('dia_propuesto')} {conv_state.get('hora_propuesta')} {conv_state.get('cancha_propuesta')}"
                )

        if fase_actual == "senia_pendiente":
            dia_pendiente = conv_state.get("dia_propuesto")
            hora_pendiente = conv_state.get("hora_propuesta")
            cancha_pendiente = conv_state.get("cancha_propuesta")

            # ============================================================
            # ROUTER DE LOTE READ-ONLY
            # ============================================================
            # Una seña pendiente aporta contexto, pero no puede secuestrar nuevas
            # consultas. Si TODO el lote son preguntas/lecturas, ejecutamos TODAS
            # las sub-intenciones antes del router transaccional de la seña.
            if sub_intenciones_lote and lote_es_solo_lectura(sub_intenciones_lote):
                respuesta_lote = await resolver_lote_solo_lectura(
                    sub_intenciones_lote,
                    conv_state,
                    prospecto,
                    telefono or "unknown",
                )
                if respuesta_lote:
                    print(
                        f"   ✅ [SEÑA/BATCH] Respondidas {len(sub_intenciones_lote)} "
                        "sub-intenciones sin modificar el turno pendiente"
                    )
                    respuesta_lote = aplicar_negrita_fechas_horas_whatsapp(respuesta_lote)
                    await send_message(page, respuesta_lote)
                    add_to_history(telefono or "unknown", "assistant", respuesta_lote)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta_lote)
                    await asyncio.sleep(3)
                    continue

            ajuste_quincho = await detectar_ajuste_quincho_pendiente_ia(ultimo_mensaje, conv_state, prospecto)
            ajuste_quincho_valido = (
                bool(ajuste_quincho.get("ajustar"))
                and hora_es_valida(ajuste_quincho.get("hora_inicio"))
                and normalizar_duracion_horas(ajuste_quincho.get("duracion_horas") or None) > 0
            )
            monto_senia_pendiente_int = _senia_guardada_o_configurada(
                reserva_pendiente_excel or {},
                (reserva_pendiente_excel or {}).get("precio_total")
                or calcular_precio_total(
                    (reserva_pendiente_excel or {}).get("duracion_horas")
                    or conv_state.get("duracion_propuesta")
                    or DEFAULT_TURN_DURATION_HOURS
                ),
            )
            monto_senia_pendiente = _monto_humano(monto_senia_pendiente_int)

            if (
                ajuste_quincho_valido
                and float(ajuste_quincho.get("confianza", 0.0) or 0.0) >= 0.5
                and dia_pendiente
                and hora_es_valida(hora_pendiente)
                and cancha_pendiente
            ):
                reserva_actual_q = calendario.obtener_reserva_por_telefono(telefono or "unknown", prospecto.get("nombre", ""))
                if not reserva_actual_q and prospecto.get("nombre"):
                    reserva_actual_q = calendario.obtener_reserva_por_nombre(prospecto.get("nombre", ""))

                quincho_nombre_q = normalizar_nombre_quincho(
                    conv_state.get("quincho")
                    or (reserva_actual_q or {}).get("quincho")
                    or ""
                )
                quincho_inicio_q = normalizar_hora_detectada(ajuste_quincho.get("hora_inicio"))
                quincho_duracion_q = normalizar_duracion_horas(
                    ajuste_quincho.get("duracion_horas")
                    or conv_state.get("quincho_duracion_horas")
                    or (reserva_actual_q or {}).get("quincho_duracion_horas")
                    or DEFAULT_TURN_DURATION_HOURS
                )
                duracion_cancha_q = normalizar_duracion_horas(
                    conv_state.get("duracion_cancha_horas")
                    or (reserva_actual_q or {}).get("duracion_horas")
                    or DEFAULT_TURN_DURATION_HOURS
                )
                if not quincho_inicio_q:
                    quincho_inicio_q = (
                        conv_state.get("quincho_hora_inicio")
                        or _quincho_default_start_after_court(
                            hora_pendiente,
                            conv_state.get("duracion_cancha_horas")
                            or conv_state.get("duracion_propuesta")
                            or DEFAULT_TURN_DURATION_HOURS,
                        )
                    )
                quincho_fin_q = hora_fin_bloque(quincho_inicio_q, quincho_duracion_q)

                if not quincho_libre_para_bloque_excluyendo_reserva(
                    dia_pendiente,
                    quincho_inicio_q,
                    quincho_duracion_q,
                    quincho_nombre_q,
                    telefono=telefono or "unknown",
                    hora_reserva=hora_pendiente,
                    cancha=cancha_pendiente,
                ):
                    respuesta = (
                        f"Tengo tu cancha reservada a las {formatear_hora_para_mensaje(hora_pendiente)}, "
                        f"pero {quincho_nombre_q} no está libre de {rango_horario_texto(quincho_inicio_q, quincho_duracion_q)}. "
                        "¿Querés que busque otro horario de quincho/parrilla?"
                    )
                    await send_message(page, aplicar_negrita_fechas_horas_whatsapp(respuesta))
                    add_to_history(telefono or "unknown", "assistant", respuesta)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                    await asyncio.sleep(3)
                    continue

                precio_cancha_q = calcular_precio_total(duracion_cancha_q)
                precio_quincho_q = calcular_precio_quincho_total(quincho_nombre_q, quincho_duracion_q)
                precio_total_q = precio_cancha_q + precio_quincho_q
                senia_valor_q = _senia_para_total(precio_total_q)
                monto_pendiente_q = calcular_monto_pendiente(precio_total_q, senia_valor_q)

                actualizar_metadata_reserva_bloque(
                    dia_pendiente,
                    slots_para_bloque(hora_pendiente, duracion_cancha_q),
                    cancha_pendiente,
                    telefono or "unknown",
                    duracion_cancha_q,
                    precio_total_q,
                    senia_valor_q,
                    monto_pendiente_q,
                    extra_fields={
                        "con_quincho": "Si",
                        "quincho": quincho_nombre_q,
                        "quincho_hora_inicio": quincho_inicio_q,
                        "quincho_hora_fin": quincho_fin_q,
                        "quincho_duracion_horas": str(quincho_duracion_q),
                        "quincho_precio_hora": str(precio_hora_quincho(quincho_nombre_q)),
                        "quincho_precio_total": str(precio_quincho_q),
                    }
                )
                marcar_quincho_solicitado_en_draft(
                    telefono or "unknown",
                    True,
                    origen="usuario",
                )
                update_conversation_state(
                    telefono or "unknown",
                    fase="senia_pendiente",
                    dia_propuesto=dia_pendiente,
                    hora_propuesta=hora_pendiente,
                    cancha_propuesta=cancha_pendiente,
                    duracion_propuesta=duracion_cancha_q,
                    duracion_cancha_horas=duracion_cancha_q,
                    con_quincho=True,
                    quincho_confirmacion_origen="usuario",
                    quincho=quincho_nombre_q,
                    quincho_hora_inicio=quincho_inicio_q,
                    quincho_hora_fin=quincho_fin_q,
                    quincho_duracion_horas=quincho_duracion_q,
                    senia_estado="pendiente",
                    senia_monto=_monto_humano(senia_valor_q),
                )
                respuesta = build_reserva_pendiente_senia_message(
                    dia_pendiente,
                    hora_pendiente,
                    cancha_pendiente,
                    duracion_cancha_q,
                    precio_total_q,
                    senia_valor_q,
                    monto_pendiente_q,
                    con_quincho=True,
                    quincho=quincho_nombre_q,
                    quincho_hora_inicio=quincho_inicio_q,
                    quincho_duracion_horas=quincho_duracion_q,
                    quincho_precio_total=precio_quincho_q,
                ).replace("__NO_CONSOLIDAR__", "", 1).strip()
                respuesta = aplicar_negrita_fechas_horas_whatsapp(respuesta)
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            accion_senia = await detectar_accion_senia_pendiente_ia(ultimo_mensaje, conv_state, prospecto)
            accion_senia_tipo = accion_senia.get("accion", "ambiguo")

            if accion_senia_tipo == "responder_pregunta_directa":
                respuesta = await responder_pregunta_directa_con_ia(
                    ultimo_mensaje,
                    conv_state,
                    prospecto,
                    incluir_recordatorio_senia=bool(accion_senia.get("requiere_recordatorio_senia", False)),
                )
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            print(f"   🧾 [SEÑA] Acción contextual: {accion_senia_tipo} - {accion_senia.get('razon', '')}")

            if accion_senia_tipo == "cancelar_turno":
                cancelacion = ejecutar_cancelacion_turno_contacto(telefono or "unknown", prospecto)
                respuesta = cancelacion["respuesta"]
                if cancelacion.get("ok"):
                    await avisar_waitlist_slot_liberado(page, cancelacion.get("reserva") or {})
                    update_conversation_state(
                        telefono or "unknown",
                        fase="esperando_motivo_cancelacion",
                        dia_propuesto=None,
                        hora_propuesta=None,
                        cancha_propuesta=None,
                        senia_estado="",
                        senia_monto="",
                        motivo_cancelacion_pendiente=cancelacion.get("reserva") or {}
                    )
                else:
                    update_conversation_state(telefono or "unknown", fase="inicial")

                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            if accion_senia_tipo == "pagar_en_lugar":
                pago_presencial = marcar_reserva_pendiente_pago_presencial(
                    telefono or "unknown",
                    prospecto,
                    conv_state,
                )
                respuesta = pago_presencial.get("respuesta") or (
                    f"Perfecto. Te esperamos en {BUSINESS_NAME}, en {BUSINESS_ADDRESS}, "
                    "para abonar en efectivo. ¡Nos vemos!"
                )
                if pago_presencial.get("ok"):
                    update_conversation_state(
                        telefono or "unknown",
                        fase="senia_pendiente",
                        senia_estado="pendiente_efectivo",
                        payment_method="efectivo",
                        reservation_id=pago_presencial.get("reservation_id"),
                    )
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            if (
                accion_senia_tipo == "posible_comprobante"
                and not image_path_recibida
                and sigue_senia_pendiente_actual(telefono or "unknown", prospecto, conv_state)
            ):
                respuesta = (
                    "Todavia no detecte ningun comprobante en tu mensaje. "
                    "Por favor, envia el screenshot o la foto del comprobante de transferencia "
                    f"por {monto_senia_pendiente} al alias {PAYMENT_ALIAS} para poder confirmar tu turno."
                )
                update_conversation_state(
                    telefono or "unknown",
                    fase="senia_pendiente",
                    dia_propuesto=dia_pendiente,
                    hora_propuesta=hora_pendiente,
                    cancha_propuesta=cancha_pendiente,
                    senia_estado="pendiente",
                    senia_monto=monto_senia_pendiente
                )
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            comprobante_path = image_path_recibida or await capturar_ultimo_comprobante(page)
            if comprobante_path:
                comprobante = analizar_comprobante_senia(
                    comprobante_path,
                    monto_esperado=monto_senia_pendiente_int,
                )
                try:
                    os.remove(comprobante_path)
                except Exception:
                    pass

                if comprobante.get("es_comprobante") and comprobante.get("monto_valido"):
                    resultado_pago = confirmar_senia_reserva_pendiente(
                        telefono or "desconocido",
                        prospecto,
                        conv_state,
                        comprobante
                    )
                    respuesta = resultado_pago["respuesta"]
                    if resultado_pago.get("ok"):
                        update_conversation_state(
                            telefono or "unknown",
                            fase="coordinacion_confirmada",
                            dia_propuesto=resultado_pago.get("dia") or dia_pendiente,
                            hora_propuesta=resultado_pago.get("hora") or hora_pendiente,
                            cancha_propuesta=resultado_pago.get("cancha") or cancha_pendiente,
                            senia_estado="pagada",
                            senia_monto=monto_senia_pendiente
                        )
                    else:
                        update_conversation_state(
                            telefono or "unknown",
                            fase="senia_pendiente",
                            dia_propuesto=dia_pendiente,
                            hora_propuesta=hora_pendiente,
                            cancha_propuesta=cancha_pendiente,
                            senia_estado="pendiente",
                            senia_monto=monto_senia_pendiente
                        )
                else:
                    razon_comprobante = comprobante.get("razon", "")
                    respuesta = (
                        f"No pude validar bien el comprobante ({razon_comprobante}). "
                        f"La seña esperada es de {monto_senia_pendiente} al alias {PAYMENT_ALIAS}. "
                        "¿Podés reenviarlo más claro?"
                    )

                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            dia_usuario_senia = await extraer_dia_con_ia(texto_combinado, conv_state)
            hora_usuario_senia = await extraer_hora_de_texto(texto_combinado, conv_state)
            cancha_usuario_senia = extraer_cancha_de_mensaje(texto_combinado, conv_state)

            if accion_senia_tipo == "consultar_horarios":
                dia_para_listar = dia_usuario_senia or "hoy"

                if hora_es_valida(hora_usuario_senia):
                    # El usuario preguntó por una hora puntual (ej: "tenés hora a las 17?")
                    # → respuesta corta, sin listar todo el día
                    dia_resuelto_consulta = resolver_fecha(dia_para_listar)
                    canchas_libres_hora = [
                        court["name"] for court in COURTS
                        if calendario.slot_esta_libre_en_cancha(dia_resuelto_consulta, hora_usuario_senia, court["name"])
                    ]

                    if canchas_libres_hora:
                        hora_txt = formatear_hora_para_mensaje(hora_usuario_senia)
                        dia_txt = formatear_dia_para_cliente_con_mensaje(dia_para_listar, texto_combinado or ultimo_mensaje)
                        if len(canchas_libres_hora) == 1:
                            respuesta_base = (
                                f"Sí, tengo {canchas_libres_hora[0]} libre para {dia_txt} "
                                f"a las {hora_txt}. ¿La reservo?"
                            )
                        else:
                            canchas_str = " o ".join(canchas_libres_hora)
                            respuesta_base = (
                                f"Sí, tengo {canchas_str} libre para {dia_txt} "
                                f"a las {hora_txt}. ¿Cuál preferís?"
                            )
                        update_conversation_state(
                            telefono or "unknown",
                            fase="coordinacion_propuesta",
                            dia_propuesto=dia_resuelto_consulta,
                            hora_propuesta=hora_usuario_senia,
                            cancha_propuesta=canchas_libres_hora[0] if len(canchas_libres_hora) == 1 else None,
                            canchas_libres=canchas_libres_hora,
                            duracion_propuesta=normalizar_duracion_horas(DEFAULT_TURN_DURATION_HOURS),
                            duracion_cancha_horas=normalizar_duracion_horas(DEFAULT_TURN_DURATION_HOURS),
                            duracion_cancha_explicita=False,
                            senia_estado="",
                            senia_monto="",
                        )
                        conv_state = get_conversation_state(telefono or "unknown")
                        fase_actual = "coordinacion_propuesta"
                    else:
                        dia_alt, hora_alt = calendario.proximo_slot_libre(dia_resuelto_consulta, hora_usuario_senia)
                        respuesta_base = (
                            f"A las {formatear_hora_para_mensaje(hora_usuario_senia)} no tengo lugar. "
                            f"¿Te sirve {dia_alt} a las {formatear_hora_para_mensaje(hora_alt)}?"
                        )
                else:
                    # No pidió hora puntual → sí tiene sentido listar el día completo
                    respuesta_base = obtener_resumen_horarios_disponibles(dia_para_listar)

                if debe_anexar_recordatorio_senia_contextual(
                    accion_senia,
                    dia_usuario_senia,
                    hora_usuario_senia,
                    dia_pendiente,
                    hora_pendiente,
                ):
                    respuesta = anexar_recordatorio_senia(respuesta_base, dia_pendiente, hora_pendiente)
                else:
                    respuesta = respuesta_base
                respuesta = aplicar_saludo_primer_contacto_si_corresponde(respuesta, conv_state)
                respuesta = aplicar_negrita_fechas_horas_whatsapp(respuesta)
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            if accion_senia_tipo == "reprogramar_turno":
                dia_objetivo = dia_usuario_senia or dia_pendiente
                hora_objetivo = hora_usuario_senia or hora_pendiente
                cancha_objetivo = cancha_usuario_senia or cancha_pendiente

                reserva_actual = calendario.obtener_reserva_por_telefono(telefono or "unknown")
                if not reserva_actual:
                    reserva_actual = calendario.obtener_reserva_por_nombre(prospecto.get("nombre", ""))

                tiene_senia_pagada = False
                if reserva_actual:
                    senia_estado = str(reserva_actual.get("senia_estado", "")).lower()
                    estado = str(reserva_actual.get("estado", "")).lower()
                    tiene_senia_pagada = (senia_estado == "pagada" or estado == BOOKING_STATUS_RESERVED)
                    print(f"   💰 [Reprogramación] Reserva actual: senia_estado={senia_estado}, estado={estado} → tiene_senia_pagada={tiene_senia_pagada}")

                if not dia_objetivo:
                    respuesta = "Dale, ¿para qué día querés hacer el cambio?"
                    await send_message(page, respuesta)
                    add_to_history(telefono or "unknown", "assistant", respuesta)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                    await asyncio.sleep(3)
                    continue

                if not hora_es_valida(hora_objetivo):
                    respuesta = "Dale, ¿a qué hora querés pasarlo?"
                    await send_message(page, respuesta)
                    add_to_history(telefono or "unknown", "assistant", respuesta)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                    await asyncio.sleep(3)
                    continue

                if not validar_hora_en_franja(hora_objetivo):
                    respuesta = (
                        f"Ese horario se me va de la franja de atención. "
                        f"Puedo adaptarme a la franja de {descripcion_franjas_atencion_mensaje()}."
                    )
                    await send_message(page, respuesta)
                    add_to_history(telefono or "unknown", "assistant", respuesta)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                    await asyncio.sleep(3)
                    continue

                dia_resuelto_objetivo = resolver_fecha(dia_objetivo)

                slot_ok, (dia_reprogramado, hora_reprogramada, cancha_reprogramada) = calendario.reprogramar_reserva(
                    telefono or "desconocido",
                    prospecto.get("nombre", ""),
                    dia_resuelto_objetivo,
                    hora_objetivo,
                    senia_estado_preservado="pagada" if tiene_senia_pagada else "",
                    senia_monto_preservado=monto_senia_preservado(reserva_actual, conv_state) if tiene_senia_pagada else ""
                )

                if slot_ok:
                    dia_confirmado = dia_reprogramado
                    hora_confirmada = hora_reprogramada
                    cancha_confirmada = cancha_reprogramada or cancha_objetivo

                    if tiene_senia_pagada:
                        respuesta = (
                            f"✅ Listo, te cambio tu turno para {dia_confirmado} "
                            f"a las {formatear_hora_para_mensaje(hora_confirmada)}.\n"
                            f"Cancha: {cancha_confirmada}\n\n"
                            f"✅ La seña ya estaba registrada correctamente.\n\n"
                            f"Te esperamos en {BUSINESS_NAME}.\n\n"
                            f"📌 Si necesitan cambiar o cancelar, avisen con tiempo por este WhatsApp."
                        )
                        update_conversation_state(
                            telefono or "unknown",
                            fase="coordinacion_confirmada",
                            dia_propuesto=dia_confirmado,
                            hora_propuesta=hora_confirmada,
                            cancha_propuesta=cancha_confirmada,
                            senia_estado="pagada",
                            senia_monto=monto_senia_preservado(reserva_actual, conv_state)
                        )
                    else:
                        monto_reprogramado = _senia_para_total(calcular_precio_total(
                            (reserva_actual or {}).get("duracion_horas")
                            or conv_state.get("duracion_propuesta")
                            or DEFAULT_TURN_DURATION_HOURS
                        ))
                        respuesta = build_senia_request_message(
                            dia_confirmado,
                            hora_confirmada,
                            monto=monto_reprogramado,
                        )
                        update_conversation_state(
                            telefono or "unknown",
                            fase="senia_pendiente",
                            dia_propuesto=dia_confirmado,
                            hora_propuesta=hora_confirmada,
                            cancha_propuesta=cancha_confirmada,
                            senia_estado="pendiente",
                            senia_monto=_monto_humano(monto_reprogramado)
                        )

                    registrar_turno_confirmado_en_csv(
                        telefono or "desconocido",
                        prospecto,
                        user_messages,
                        dia_confirmado,
                        hora_confirmada
                    )
                else:
                    respuesta = (
                        f"Ese horario está ocupado. ¿Te sirve {dia_reprogramado} "
                        f"a las {formatear_hora_para_mensaje(hora_reprogramada)}?"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_reprogramado,
                        hora_propuesta=hora_reprogramada,
                        cancha_propuesta=cancha_reprogramada or cancha_objetivo
                    )

                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

        # En consultas puramente informativas, el router semántico manda antes que
        # los clasificadores operativos legacy. Esto evita convertir una pregunta
        # sobre características del negocio en una consulta de calendario.
        if (
            len(sub_intenciones_lote) == 1
            and sub_intenciones_lote[0].get("intencion") == "consulta_informativa"
        ):
            fragmento_info = sub_intenciones_lote[0].get("fragmento") or ultimo_mensaje
            respuesta_info = await responder_consulta_informativa_ia(
                fragmento_info,
                conv_state,
                prospecto,
            )
            await send_message(page, respuesta_info)
            add_to_history(telefono or "unknown", "assistant", respuesta_info)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta_info)
            await asyncio.sleep(3)
            continue

        intencion_previa = await detectar_intencion_usuario(texto_combinado, len(conv_state.get("historial", [])) > 0)
        estado_operativo_actual = obtener_estado_operativo_predio()
        # Planner operativo legacy: queda como segunda capa para operaciones
        # transaccionales todavía no migradas al executor del Decision Engine.
        decision_operativa = await construir_decision_operativa_ia(
            ultimo_mensaje,
            conv_state,
            prospecto,
            telefono or "unknown",
            intencion=intencion_previa,
            estado_operativo=estado_operativo_actual
        )
        plan_operativo = crear_plan_operativo(decision_operativa, conv_state)
        update_conversation_state(
            telefono or "unknown",
            decision_actual=decision_operativa,
            plan_actual=plan_operativo
        )
        registrar_metrica_operativa("decision_operativa", {
            "telefono": telefono or "unknown",
            "situacion": decision_operativa.get("situacion"),
            "accion": decision_operativa.get("accion_recomendada"),
            "plan": plan_operativo.get("objetivo"),
            "riesgo": decision_operativa.get("riesgo")
        })

        pedido_humano_ia = (
            intencion_previa.get("intencion") == "derivar_humano"
            and float(intencion_previa.get("confianza", 0.0) or 0.0) >= 0.65
        )
        if (
            not pedido_humano_ia
            and (
                intencion_previa.get("intencion") in ("necesita_contexto", "saludo_sin_intencion")
                or float(intencion_previa.get("confianza", 0.0) or 0.0) < 0.75
            )
        ):
            humano_check = await detectar_pedido_humano_ia(ultimo_mensaje, conv_state)
            pedido_humano_ia = (
                humano_check.get("es_pedido_humano")
                and float(humano_check.get("confianza", 0.0) or 0.0) >= 0.7
            )
        if pedido_humano_ia:
            auditor_humano = await validar_derivacion_humano_con_ia(
                mensaje_original=ultimo_mensaje,
                fragmento=ultimo_mensaje,
                conv_state=conv_state,
                primera_decision=str(intencion_previa.get("razon") or intencion_previa),
            )
            pedido_humano_ia = (
                auditor_humano.get("derivar")
                and float(auditor_humano.get("confianza", 0.0) or 0.0) >= 0.6
            )

        pedido_evento_dia_completo_ia = (
            intencion_previa.get("intencion") == "evento_dia_completo"
            and float(intencion_previa.get("confianza", 0.0) or 0.0) >= 0.65
        )
        if (
            not pedido_evento_dia_completo_ia
            and (
                intencion_previa.get("intencion") in ("quiere_reservar", "necesita_contexto", "derivar_humano")
                or float(intencion_previa.get("confianza", 0.0) or 0.0) < 0.85
            )
        ):
            evento_check = await detectar_evento_dia_completo_ia(ultimo_mensaje, conv_state)
            pedido_evento_dia_completo_ia = (
                evento_check.get("es_evento_dia_completo")
                and float(evento_check.get("confianza", 0.0) or 0.0) >= 0.7
            )

        pedido_quincho_ia = (
            intencion_previa.get("intencion") == "reservar_quincho"
            and float(intencion_previa.get("confianza", 0.0) or 0.0) >= 0.65
        )
        if (
            not pedido_quincho_ia
            and (
                intencion_previa.get("intencion") in ("quiere_reservar", "pide_horarios", "pide_precio", "necesita_contexto", "derivar_humano", "evento_dia_completo")
                or float(intencion_previa.get("confianza", 0.0) or 0.0) < 0.85
            )
        ):
            quincho_check = await detectar_reserva_quincho_ia(ultimo_mensaje, conv_state)
            pedido_quincho_ia = (
                quincho_check.get("es_reserva_quincho")
                and float(quincho_check.get("confianza", 0.0) or 0.0) >= 0.7
            )

        if pedido_quincho_ia:
            print("   [Quincho IA] Pedido detectado. Se procesa como complemento reservable por hora.")
            update_conversation_state(
                telefono or "unknown",
                con_quincho=True,
                quincho=normalizar_nombre_quincho(conv_state.get("quincho") or "")
            )
            conv_state = get_conversation_state(telefono or "unknown")

        if pedido_evento_dia_completo_ia:
            print("   [Evento dia completo IA] Pedido detectado. Avisando al cliente y al autorizado.")
            await manejar_evento_dia_completo(page, telefono or "unknown", user_messages, ultimo_mensaje, prospecto)
            await asyncio.sleep(3)
            continue

        if pedido_humano_ia:
            print("   [Derivacion humano IA] Pedido detectado. Avisando al cliente y al autorizado.")
            await manejar_derivacion_humano(page, telefono or "unknown", user_messages, ultimo_mensaje, prospecto)
            await asyncio.sleep(3)
            continue

        if intencion_previa.get("intencion") == "cancela":
            print(f"   🧠 [Cancelación IA] Pedido detectado: {intencion_previa.get('razon', '')}")
            reserva_actual_control = calendario.obtener_reserva_por_telefono(telefono or "unknown", prospecto.get("nombre", ""))
            control = validar_control_autonomia(decision_operativa, plan_operativo, reserva_actual_control)
            if not control.get("ok"):
                respuesta = (
                    "Para evitar un error con el turno, prefiero que lo revise una persona del predio. "
                    f"Te paso con {HUMAN_CONTACT_NAME} al {HUMAN_WHATSAPP}."
                )
                registrar_metrica_operativa("accion_bloqueada_control", {"telefono": telefono or "unknown", "control": control, "decision": decision_operativa})
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue
            cancelacion = ejecutar_cancelacion_turno_contacto(telefono or "unknown", prospecto)
            respuesta = cancelacion["respuesta"]
            if cancelacion.get("ok"):
                await avisar_waitlist_slot_liberado(page, cancelacion.get("reserva") or {})
                update_conversation_state(
                    telefono or "unknown",
                    fase="esperando_motivo_cancelacion",
                    dia_propuesto=None,
                    hora_propuesta=None,
                    cancha_propuesta=None,
                    senia_estado="",
                    senia_monto="",
                    motivo_cancelacion_pendiente=cancelacion.get("reserva") or {}
                )
            else:
                update_conversation_state(telefono or "unknown", fase="inicial")

            print(f"\n💬 RESPUESTA [Cancelación]:")
            print(f"   {respuesta}")
            await send_message(page, respuesta)
            add_to_history(telefono or "unknown", "assistant", respuesta)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
            await asyncio.sleep(3)
            continue

        es_despedida_actual = detectar_despedida_ia(ultimo_mensaje, conv_state)

        if es_despedida_actual:
            print(f"   👋 [Despedida] Mensaje detectado como despedida")
            if historial_tiene_despedida_previa(conv_state):
                print(f"   🔁 [Despedida] Cliente se despide después de nuestro cierre → misión cumplida. ESC.")
                await escape_chat(page)
                await asyncio.sleep(3)
                continue
            else:
                print(f"   👋 [Despedida] Cliente inicia despedida antes de nuestro cierre. Generando cierre con IA.")
                respuesta_despedida = generar_cierre_despedida_ia(ultimo_mensaje, conv_state, prospecto)
                if respuesta_despedida:
                    await send_message(page, respuesta_despedida)
                    add_to_history(telefono or "unknown", "assistant", respuesta_despedida)
                    guardar_historial_chat(telefono or "unknown", user_messages, respuesta_despedida)
                else:
                    print("   ⚠️ [Despedida IA] No se generó respuesta; se cierra sin enviar plantilla.")
                await escape_chat(page)
                await asyncio.sleep(3)
                continue

        if (
            intencion_previa.get("intencion") == "necesita_contexto"
            and float(intencion_previa.get("confianza", 0.0) or 0.0) >= 0.75
            and len(sub_intenciones_lote) <= 1
        ):
            dia_contextual = await extraer_dia_con_ia(ultimo_mensaje, conv_state)
            hora_contextual = conv_state.get("hora_propuesta")
            if dia_contextual and hora_es_valida(hora_contextual):
                dia_resuelto_contextual = resolver_fecha(dia_contextual)
                canchas_libres_contextual = [
                    court["name"] for court in COURTS
                    if calendario.slot_esta_libre_en_cancha(dia_resuelto_contextual, hora_contextual, court["name"])
                ]
                if canchas_libres_contextual:
                    canchas_txt = " o ".join(canchas_libres_contextual)
                    respuesta = (
                        f"Tenés razón, me refería a {formatear_dia_para_cliente(dia_contextual)}. "
                        f"A las {formatear_hora_para_mensaje(hora_contextual)} tengo {canchas_txt} libre. "
                        "¿Cuál preferís?"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_resuelto_contextual,
                        hora_propuesta=hora_contextual,
                        cancha_propuesta=None,
                        canchas_libres=canchas_libres_contextual
                    )
                else:
                    dia_alt, hora_alt = calendario.proximo_slot_libre(dia_resuelto_contextual, hora_contextual)
                    respuesta = (
                        f"Tenés razón, me refería a {formatear_dia_para_cliente(dia_contextual)}. "
                        f"A las {formatear_hora_para_mensaje(hora_contextual)} no tengo lugar. "
                        f"¿Te sirve {dia_alt} a las {formatear_hora_para_mensaje(hora_alt)}?"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_alt,
                        hora_propuesta=hora_alt,
                        cancha_propuesta=None
                    )
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

            print("   🧠 [Agente contextual] Mensaje sin pedido operativo claro; no se consulta calendario.")
            respuesta = generar_respuesta_agentica_contextual(
                ultimo_mensaje,
                conv_state,
                prospecto,
                motivo=intencion_previa.get("razon", "")
            )
            await send_message(page, respuesta)
            add_to_history(telefono or "unknown", "assistant", respuesta)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
            await asyncio.sleep(3)
            continue

        tiene_historial = len(conv_state.get("historial", [])) >= 2
        es_saludo_retorno = detectar_saludo_retorno_ia(ultimo_mensaje, tiene_historial)

        if es_saludo_retorno and not cliente_existente_actual:
            print(f"   👋 [Saludo retorno] Retomando consulta de reserva")
            try:
                historial_para_modelo = []
                for msg in conv_state.get("historial", [])[-6:]:
                    role = "user" if msg["role"] == "user" else "assistant"
                    historial_para_modelo.append({"role": role, "content": msg["content"]})

                resp_saludo = await call_openai_async(
                    model=OPENAI_MODEL,
                    messages=[
                        {
                            "role": "system",
                            "content": (
                                f"Sos {AGENT_NAME}, asistente de reservas de {BUSINESS_NAME}. "
                                "El usuario saludó de vuelta. Respondé breve, recordale que podés ayudar "
                                "a consultar disponibilidad o reservar cancha. Máximo 3 líneas. "
                                "Tono natural, argentino, tuteo. Sin plantillas."
                            )
                        },
                        *historial_para_modelo,
                        {"role": "user", "content": ultimo_mensaje}
                    ],
                    temperature=0.8,
                    max_tokens=150
                )
                register_cost(resp_saludo)
                respuesta = resp_saludo.choices[0].message.content.strip()
            except Exception as e:
                print(f"   ⚠️ Error generando saludo retorno: {e}")
                # 🔧 FIX: Emoji al inicio de la segunda línea
                respuesta = f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}\n\n🏟️ Decime qué día y horario querés cancha y te confirmo disponibilidad."

            await send_message(page, respuesta)
            add_to_history(telefono or "unknown", "assistant", respuesta)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
            await asyncio.sleep(3)
            continue

        print(f"\n🤖 [IA] Descomponiendo intenciones del lote completo...")
        sub_intenciones = sub_intenciones_lote or await detectar_multiples_intenciones(lote_semantico or ultimo_mensaje)

        # ============================================================
        # 🔧 SOLUCIÓN DE CLAUDE - DETECCIÓN DE RESPUESTA A PREGUNTA DE REPROGRAMACIÓN/NUEVO
        # 🔧 MEJORADA: Detecta consultas de horario en fase esperando_decision_reprogramacion
        # ============================================================
        fase_actual = conv_state.get("fase", "")
        if fase_actual == "esperando_decision_reprogramacion":
            mensaje_lower = ultimo_mensaje.lower().strip()

            # 🆕 EXTRAER HORA Y DÍA DEL MENSAJE ACTUAL
            hora_respuesta = await extraer_hora_de_texto(ultimo_mensaje, conv_state)
            dia_respuesta = await extraer_dia_con_ia(ultimo_mensaje, conv_state)

            # 🆕 Si el usuario pregunta por OTRO horario (sin decir "reprogramar" o "nuevo")
            # Esto cubre el caso: "tenes hora para las 22hs?" cuando está en fase de espera
            if hora_respuesta or dia_respuesta:
                # Está pidiendo cambiar a otro horario → es REPROGRAMACIÓN
                print(f"   🔄 [Decisión] Usuario pregunta por {hora_respuesta or dia_respuesta} → interpretando como reprogramación")

                # Guardar el nuevo horario en estado
                dia_a_usar = dia_respuesta or conv_state.get("dia_propuesto", "hoy")
                hora_a_usar = hora_respuesta or conv_state.get("hora_propuesta", "")

                update_conversation_state(
                    telefono or "unknown",
                    fase="coordinacion_propuesta",
                    en_proceso_cambio=True,
                    dia_propuesto=dia_a_usar,
                    hora_propuesta=hora_a_usar,
                    en_consulta_disponibilidad=False,
                    quiere_nuevo_turno=False
                )

                # Reconstruir mensaje para que el flujo lo procese como reprogramación
                if hora_respuesta:
                    ultimo_mensaje = f"cambiar mi turno para las {hora_respuesta}"
                else:
                    ultimo_mensaje = f"cambiar mi turno para {dia_respuesta}"

                sub_intenciones = await detectar_multiples_intenciones(ultimo_mensaje)
                print(f"   🔄 [Decisión] Forzando reprogramación: {ultimo_mensaje}")
                # No hacemos continue aquí, dejamos que el flujo procese normalmente

            elif "reprogramar" in mensaje_lower or "cambiar" in mensaje_lower or "mover" in mensaje_lower:
                print(f"   🔄 [Decisión] Usuario QUIERE REPROGRAMAR su turno")
                hora_seleccionada = conv_state.get("hora_propuesta", "21:00")
                ultimo_mensaje = f"cambiar mi turno para {hora_seleccionada}" 
                update_conversation_state(
                    telefono or "unknown",
                    fase="coordinacion_propuesta",
                    en_proceso_cambio=True,
                    en_consulta_disponibilidad=False,
                    quiere_nuevo_turno=False
                )
                sub_intenciones = await detectar_multiples_intenciones(ultimo_mensaje)
                print(f"   🔄 [Decisión] Forzando reprogramación: {ultimo_mensaje}")

            elif "nuevo" in mensaje_lower or "aparte" in mensaje_lower or "nuevo turno" in mensaje_lower:
                print(f"   🔄 [Decisión] Usuario QUIERE UN NUEVO TURNO (no reprogramar)")
                hora_seleccionada = conv_state.get("hora_propuesta", "")
                dia_seleccionado = conv_state.get("dia_propuesto", "hoy")
                if hora_seleccionada:
                    ultimo_mensaje = f"quiero un turno nuevo para las {hora_seleccionada}"
                else:
                    ultimo_mensaje = f"quiero un turno nuevo para {dia_seleccionado}"
                update_conversation_state(
                    telefono or "unknown",
                    fase="coordinacion_propuesta",
                    en_proceso_cambio=False,
                    en_consulta_disponibilidad=False,
                    quiere_nuevo_turno=True
                )
                sub_intenciones = await detectar_multiples_intenciones(ultimo_mensaje)
                print(f"   🔄 [Decisión] Forzando nuevo turno: {ultimo_mensaje}")

            elif "no" in mensaje_lower or "dejá" in mensaje_lower or "mejor no" in mensaje_lower:
                print(f"   🔄 [Decisión] Usuario NO quiere modificar su turno")
                respuesta = "Ok, mantenemos tu turno actual. Si necesitás algo más, avisame."
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                update_conversation_state(
                    telefono or "unknown",
                    fase="coordinacion_confirmada",
                    en_consulta_disponibilidad=False,
                    quiere_nuevo_turno=False
                )
                await asyncio.sleep(3)
                continue
            else:
                # 🆕 Si no responde claramente, REPETIR la pregunta
                print(f"   🔄 [Decisión] Usuario no respondió claramente a la pregunta")
                dia_actual = conv_state.get("dia_propuesto", "")
                hora_actual = conv_state.get("hora_propuesta", "")
                cancha_actual = conv_state.get("cancha_propuesta", "")
                respuesta = (
                    f"Tenés un turno actual para {dia_actual} a las "
                    f"{formatear_hora_para_mensaje(hora_actual)} en {cancha_actual}. "
                    f"¿Querés REPROGRAMAR tu turno actual para ese horario o querés un NUEVO turno aparte? "
                    f"Respondé 'reprogramar' o 'nuevo turno'."
                )
                await send_message(page, respuesta)
                add_to_history(telefono or "unknown", "assistant", respuesta)
                guardar_historial_chat(telefono or "unknown", user_messages, respuesta)
                await asyncio.sleep(3)
                continue

        respuestas_pendientes = []
        pending_admin_alert_payloads = []

        def agregar_respuesta_pendiente(texto: str, origen: str):
            texto = (texto or "").strip()
            if not texto:
                return
            print(f"   [Respuesta parcial] {origen}: {texto[:100]}")
            respuestas_pendientes.append(texto)

        for idx, sub in enumerate(sub_intenciones):
            fragmento = sub.get("fragmento", ultimo_mensaje)
            intencion_sub = sub.get("intencion", "otra")
            print(f"\n   🔁 [Sub-intent {idx+1}/{len(sub_intenciones)}] {intencion_sub}: '{fragmento[:60]}'")

            if intencion_sub == "consulta_informativa":
                print("   🧠 [Consulta informativa] Resolviendo contra configuración del negocio")
                respuesta_info = await responder_consulta_informativa_ia(
                    fragmento or ultimo_mensaje,
                    conv_state,
                    prospecto,
                )
                agregar_respuesta_pendiente(
                    respuesta_info,
                    f"consulta_informativa sub-intent {idx+1}",
                )
                if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                    await asyncio.sleep(1.0)
                continue

            if intencion_sub == "evento_dia_completo":
                print("   [Evento dia completo IA] Sub-intencion detectada. Derivando a coordinacion manual.")
                respuestas_pendientes.clear()
                await manejar_evento_dia_completo(page, telefono or "unknown", user_messages, fragmento or ultimo_mensaje, prospecto)
                break

            if intencion_sub == "reservar_quincho":
                print("   [Quincho IA] Sub-intencion detectada. Se suma como complemento reservable.")
                update_conversation_state(
                    telefono or "unknown",
                    con_quincho=True,
                    quincho=normalizar_nombre_quincho()
                )

            conv_state = get_conversation_state(telefono or "unknown")

            cancha_extraida = extraer_cancha_de_mensaje(fragmento, conv_state)
            if cancha_extraida:
                print(f"   🧠 [MEMORIA] Usuario eligió cancha: {cancha_extraida}")
                update_conversation_state(
                    telefono or "unknown",
                    cancha_propuesta=cancha_extraida
                )
                conv_state = get_conversation_state(telefono or "unknown")
                fragmento = f"{fragmento} (usuario eligió {cancha_extraida})"

            analysis = await analyze_message_with_context(
                fragmento, conv_state, prospecto, telefono or "unknown"
            )

            tipo = analysis.get("tipo", "otro")
            dia_detectado = analysis.get("dia_detectado")
            hora_detectada = analysis.get("hora_detectada")
            cancha_detectada = analysis.get("cancha_detectada") or conv_state.get("cancha_propuesta")
            duracion_detectada = normalizar_duracion_horas(
                analysis.get("duracion_detectada"),
                conv_state.get("duracion_propuesta") or DEFAULT_TURN_DURATION_HOURS
            )
            nueva_fase = analysis.get("nueva_fase", conv_state["fase"])
            respuesta = analysis.get("respuesta", "")
            razon = analysis.get("razon", "")
            if dia_detectado and hora_es_valida(hora_detectada):
                dia_resuelto_guard = resolver_fecha(dia_detectado)
                if not validar_fecha_en_dias_atencion(dia_resuelto_guard):
                    respuesta_dia_cerrado = construir_respuesta_dia_fuera_de_atencion(
                        dia_detectado,
                        hora_detectada,
                        cancha_detectada
                    )
                    print(
                        f"   [Calendario] {dia_resuelto_guard} fuera de dias de atencion. "
                        f"Respuesta deterministica: {respuesta_dia_cerrado['respuesta']}"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=respuesta_dia_cerrado["dia"],
                        hora_propuesta=respuesta_dia_cerrado["hora"],
                        duracion_propuesta=duracion_detectada,
                        cancha_propuesta=None
                    )
                    agregar_respuesta_pendiente(
                        respuesta_dia_cerrado["respuesta"],
                        f"dia_fuera_de_atencion sub-intent {idx+1}"
                    )
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue
            es_reprogramacion_en_curso = (
                intencion_sub == "reprogramar_turno"
                or tipo in ("renegociacion", "reprogramacion", "reprogramacion_automatica")
                or bool(conv_state.get("en_proceso_cambio"))
            )

            print(f"      Tipo: {tipo} | Día: {dia_detectado} | Hora: {hora_detectada} | Cancha: {cancha_detectada}")

            if tipo == "respuesta_directa":
                if respuesta_es_placeholder_verificacion(respuesta) and hora_es_valida(hora_detectada):
                    print(
                        "   ⚠️ [Respuesta directa] Era un placeholder de verificación; "
                        "redirijo a validación de calendario."
                    )
                    tipo = "coordinacion_nueva"
                    nueva_fase = "coordinacion_propuesta"
                    respuesta = ""
                else:
                    print(f"   💬 [Respuesta directa] Acumulando: {respuesta[:100]}")
                    agregar_respuesta_pendiente(respuesta, f"respuesta_directa sub-intent {idx+1}")
                    update_conversation_state(telefono or "unknown", fase="inicial")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue

            if tipo == "derivar_humano":
                auditor_humano = await validar_derivacion_humano_con_ia(
                    mensaje_original=ultimo_mensaje,
                    fragmento=fragmento or ultimo_mensaje,
                    conv_state=conv_state,
                    primera_decision=str(analysis.get("razon") or analysis),
                    respuesta_ya_generada="\n".join(respuestas_pendientes),
                )
                if not (
                    auditor_humano.get("derivar")
                    and float(auditor_humano.get("confianza", 0.0) or 0.0) >= 0.6
                ):
                    print("   [Derivación] Segunda lectura IA: no corresponde derivar; continúo con la reserva.")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue
                print(f"   🧑 [Derivación] Enviando contacto del encargado")
                respuestas_pendientes.clear()
                await manejar_derivacion_humano(page, telefono or "unknown", user_messages, fragmento or ultimo_mensaje, prospecto)
                break

            if tipo == "lista_horarios":
                print(f"   📋 [Lista horarios] Acumulando lista de horarios disponibles")
                agregar_respuesta_pendiente(respuesta, f"lista_horarios sub-intent {idx+1}")
                update_conversation_state(
                    telefono or "unknown",
                    fase="coordinacion_propuesta",
                    dia_propuesto=dia_detectado
                )
                if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                    await asyncio.sleep(1.5)
                continue

            # ============================================================
            # 🔧 SOLUCIÓN DE CLAUDE - RENEGOCIACIÓN CORREGIDA
            # El atajo de "Renegociación" solo debe aplicarse cuando NO hay un turno 
            # confirmado/pagado. Si ya hay turno confirmado, debe pasar por el 
            # flujo normal que pregunta "reprogramar o nuevo turno".
            # ============================================================
            fase_tiene_turno_confirmado = conv_state.get("fase") in ("coordinacion_confirmada", "senia_pendiente")

            if (
                tipo in ("renegociacion", "coordinacion_nueva")
                and hora_es_valida(hora_detectada)
                and not dia_detectado
                and conv_state.get("dia_propuesto")
                and not fase_tiene_turno_confirmado   # 🔧 CLAUDE FIX: no colapsar si ya hay turno confirmado/pagado
            ):
                dia_detectado = conv_state.get("dia_propuesto")
                tipo = "confirmado"
                nueva_fase = "coordinacion_confirmada"
                respuesta = ""
                es_reprogramacion_en_curso = True
                print(f"   🔁 [Renegociación] Mantengo día existente: {dia_detectado} y actualizo hora a {hora_detectada}")

            if tipo in ("coordinacion_nueva", "renegociacion", "coordinacion_propuesta"):
                decision_calendario = await decidir_accion_calendario_ia(
                    fragmento,
                    intencion_sub,
                    tipo,
                    dia_detectado=dia_detectado,
                    hora_detectada=hora_detectada,
                    cancha_detectada=cancha_detectada,
                    conv_state=conv_state,
                    prospecto=prospecto
                )
                accion_calendario = decision_calendario.get("accion")

                if accion_calendario == "listar_horarios":
                    dia_para_consultar = (
                        decision_calendario.get("dia")
                        or dia_detectado
                        or "hoy"
                    )
                    print(f"   📋 [Horarios] Calendario IA decidió listar turnos para {dia_para_consultar}")

                    respuesta_horarios = obtener_resumen_horarios_disponibles(dia_para_consultar)
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_para_consultar,
                        hora_propuesta=hora_detectada if hora_es_valida(hora_detectada) else conv_state.get("hora_propuesta"),
                        cancha_propuesta=None
                    )

                    agregar_respuesta_pendiente(respuesta_horarios, f"listar_horarios sub-intent {idx+1}")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue

                if accion_calendario == "responder_contextual":
                    print("   🧠 [Calendario IA] Decidió no tocar calendario; respuesta contextual.")
                    respuesta_contextual = generar_respuesta_agentica_contextual(
                        fragmento,
                        conv_state,
                        prospecto,
                        motivo=decision_calendario.get("razon", "")
                    )
                    agregar_respuesta_pendiente(respuesta_contextual, f"respuesta_contextual sub-intent {idx+1}")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue

                usar_memoria_calendario = bool(decision_calendario.get("usar_memoria"))
                dia_a_validar = (
                    decision_calendario.get("dia")
                    or dia_detectado
                    or (conv_state.get("dia_propuesto") if usar_memoria_calendario else None)
                )
                hora_a_validar = (
                    decision_calendario.get("hora")
                    or hora_detectada
                    or (conv_state.get("hora_propuesta") if usar_memoria_calendario else None)
                )

                if not hora_es_valida(hora_a_validar):
                    print(
                        "   🧠 [Calendario IA] Eligió validar, pero no hay hora usable. "
                        "Respuesta contextual."
                    )
                    respuesta_contextual = generar_respuesta_agentica_contextual(
                        fragmento,
                        conv_state,
                        prospecto,
                        motivo=decision_calendario.get("razon", "")
                    )
                    agregar_respuesta_pendiente(respuesta_contextual, f"calendario_contextual sub-intent {idx+1}")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue

                if not validar_hora_en_franja(hora_a_validar):
                    respuesta = (
                        f"Ese horario esta fuera de nuestra franja de atencion "
                        f"({descripcion_franjas_atencion_mensaje()}). ¿Que horario dentro de esa franja te sirve?"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_a_validar,
                        hora_propuesta=None
                    )
                    agregar_respuesta_pendiente(respuesta, f"fuera_de_franja sub-intent {idx+1}")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue

                if not dia_a_validar:
                    dia_a_validar = "hoy"
                    print(f"   🕒 [Hora específica] Usuario no especificó día, usando 'hoy' para verificar disponibilidad a las {hora_a_validar}")

                dia_resuelto_validar = resolver_fecha(dia_a_validar)
                if not validar_fecha_en_dias_atencion(dia_resuelto_validar):
                    respuesta_dia_cerrado = construir_respuesta_dia_fuera_de_atencion(
                        dia_a_validar,
                        hora_a_validar,
                        cancha_detectada
                    )
                    respuesta = respuesta_dia_cerrado["respuesta"]
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=respuesta_dia_cerrado["dia"],
                        hora_propuesta=respuesta_dia_cerrado["hora"],
                        cancha_propuesta=None
                    )
                    agregar_respuesta_pendiente(respuesta, f"dia_fuera_de_atencion sub-intent {idx+1}")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue
                    dia_libre, hora_libre = calendario.proximo_slot_libre(
                        dia_preferido=dia_resuelto_validar,
                        hora_preferida=hora_a_validar,
                        cancha=cancha_detectada
                    )
                    dia_fuera_msg = "Hoy no abrimos la cancha" if str(dia_a_validar or "").strip().lower() == "hoy" else "Ese dia no atendemos"
                    respuesta = (
                        f"{dia_fuera_msg}. Estamos abiertos {descripcion_atencion_mensaje()}. "
                        f"¿Te sirve {dia_libre} a las {formatear_hora_para_mensaje(hora_libre)}?"
                    )
                    print(
                        f"   [Calendario] {dia_resuelto_validar} fuera de dias de atencion. "
                        f"Propongo alternativa: {dia_libre} {hora_libre}"
                    )
                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_libre,
                        hora_propuesta=hora_libre,
                        cancha_propuesta=cancha_detectada
                    )
                    agregar_respuesta_pendiente(respuesta, f"dia_fuera_de_atencion sub-intent {idx+1}")
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.5)
                    continue

                print(f"   🕒 [Hora específica] Verificando disponibilidad para {dia_a_validar} a las {hora_a_validar}")

                reserva_actual = calendario.obtener_reserva_por_telefono(telefono or "unknown")
                misma_reserva_actual = _misma_reserva_fecha_hora(
                    reserva_actual,
                    dia_a_validar,
                    hora_a_validar,
                    cancha_detectada,
                )

                if misma_reserva_actual:
                    print(f"   📅 [Calendario] Slot {dia_a_validar} {hora_a_validar} ya es la reserva activa de este contacto")
                    respuesta = f"Ya tenés reservado para {formatear_dia_para_cliente_con_mensaje(dia_a_validar, fragmento or ultimo_mensaje)} a las {formatear_hora_para_mensaje(hora_a_validar)}. ¿Querés reprogramar o cancelar?"
                    nueva_fase = "coordinacion_propuesta"
                else:
                    slot_libre = calendario.slot_esta_libre(dia_a_validar, hora_a_validar, cancha=cancha_detectada)
                    if not slot_libre:
                        print(f"   📅 [Calendario] Slot {dia_a_validar} {hora_a_validar} NO disponible")
                        slot_ya_paso = (
                            str(dia_a_validar or "").strip().lower() == "hoy"
                            and (minutos_hasta_turno(dia_resuelto_validar, hora_a_validar) or 0) < 0
                        )
                        if slot_ya_paso:
                            dia_libre, hora_libre = proximo_dia_con_misma_hora_disponible(
                                hora_a_validar,
                                cancha=cancha_detectada,
                                desde_dia="mañana"
                            )
                            canchas_libres_pasado = canchas_libres_para_bloque(dia_libre, hora_libre, duracion_detectada, cancha_detectada)
                            canchas_txt = " o ".join(canchas_libres_pasado) if canchas_libres_pasado else "cancha"
                            print(f"   → El horario ya pasó. Propongo misma hora futura: {dia_libre} {hora_libre}")
                            respuesta = (
                                f"Esa hora para hoy ya pasó. Tengo {canchas_txt} libre para {dia_libre} "
                                f"a las {formatear_hora_para_mensaje(hora_libre)}. ¿Cuál preferís?"
                            )
                            update_conversation_state(
                                telefono or "unknown",
                                fase="coordinacion_propuesta",
                                dia_propuesto=dia_libre,
                                hora_propuesta=hora_libre,
                                cancha_propuesta=canchas_libres_pasado[0] if len(canchas_libres_pasado) == 1 else cancha_detectada,
                                canchas_libres=canchas_libres_pasado,
                                duracion_propuesta=duracion_detectada,
                                duracion_cancha_horas=duracion_detectada,
                            )
                        else:
                            dia_libre, hora_libre = calendario.proximo_slot_libre(
                                dia_preferido=dia_a_validar,
                                hora_preferida=hora_a_validar,
                                cancha=cancha_detectada
                            )
                            print(f"   → Propongo alternativa: {dia_libre} {hora_libre}")
                            respuesta = f"Ese horario está ocupado. ¿Te sirve {dia_libre} a las {formatear_hora_para_mensaje(hora_libre)} para reservar cancha?"
                        dia_detectado = dia_libre
                        hora_detectada = hora_libre
                        nueva_fase = "coordinacion_propuesta"
                        tipo = "coordinacion_propuesta_con_alternativa"
                    else:
                        print(f"   ✅ [Calendario] Slot {dia_a_validar} {hora_a_validar} disponible")
                        con_quincho_actual = bool(conv_state.get("con_quincho"))
                        duracion_cancha_actual = (
                            duracion_cancha_para_pedido(fragmento, conv_state, duracion_detectada)
                            if con_quincho_actual
                            else duracion_detectada
                        )
                        duracion_cancha_explicita_actual = extraer_duracion_de_texto(fragmento) is not None
                        canchas_libres = canchas_libres_para_bloque(
                            dia_a_validar,
                            hora_a_validar,
                            duracion_cancha_actual
                        )
                        quincho_actual = normalizar_nombre_quincho(conv_state.get("quincho") or "") if con_quincho_actual else ""

                        # 🔧 CLAUDE FIX: Verificar bandera quiere_nuevo_turno para evitar loop
                        if not canchas_libres:
                            dia_libre, hora_libre = calendario.proximo_slot_libre(
                                dia_preferido=dia_a_validar,
                                hora_preferida=hora_a_validar,
                                cancha=cancha_detectada
                            )
                            respuesta = f"No tengo ese bloque completo disponible. ¿Te sirve {dia_libre} a las {formatear_hora_para_mensaje(hora_libre)}?"
                            update_conversation_state(
                                telefono or "unknown",
                                fase="coordinacion_propuesta",
                                dia_propuesto=dia_libre,
                                hora_propuesta=hora_libre,
                                duracion_propuesta=duracion_detectada,
                                cancha_propuesta=None
                            )
                            agregar_respuesta_pendiente(respuesta, f"bloque_no_disponible sub-intent {idx+1}")
                            if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                                await asyncio.sleep(1.5)
                            continue

                        quincho_duracion_actual = conv_state.get("quincho_duracion_horas")
                        if con_quincho_actual and not quincho_duracion_actual:
                            if len(canchas_libres) == 1:
                                cancha_detectada = canchas_libres[0]
                            respuesta = build_pregunta_duracion_quincho_con_precios(
                                dia_a_validar,
                                hora_a_validar,
                                canchas_libres,
                                quincho_actual,
                                duracion_cancha_actual
                            )
                            update_conversation_state(
                                telefono or "unknown",
                                fase="esperando_duracion_quincho",
                                dia_propuesto=dia_a_validar,
                                hora_propuesta=hora_a_validar,
                                duracion_propuesta=duracion_cancha_actual,
                                duracion_cancha_horas=duracion_cancha_actual,
                                duracion_cancha_explicita=duracion_cancha_explicita_actual,
                                con_quincho=True,
                                quincho=quincho_actual,
                                quincho_hora_inicio=_quincho_default_start_after_court(
                                    hora_a_validar, duracion_cancha_actual
                                ),
                                quincho_hora_fin="",
                                canchas_libres=canchas_libres,
                                cancha_propuesta=cancha_detectada if len(canchas_libres) == 1 else None
                            )
                            agregar_respuesta_pendiente(respuesta, f"pregunta_duracion_quincho sub-intent {idx+1}")
                            if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                                await asyncio.sleep(1.5)
                            continue

                        quincho_duracion_actual = quincho_duracion_actual or duracion_detectada
                        quincho_hora_inicio_actual = (
                            conv_state.get("quincho_hora_inicio")
                            or _quincho_default_start_after_court(
                                hora_a_validar, duracion_cancha_actual
                            )
                        )
                        if (
                            con_quincho_actual
                            and not quincho_libre_para_bloque(dia_a_validar, quincho_hora_inicio_actual, quincho_duracion_actual, quincho_actual)
                        ):
                            respuesta = (
                                f"Tengo cancha disponible a las {formatear_hora_para_mensaje(hora_a_validar)}, "
                                f"pero {quincho_actual} no está libre de {rango_horario_texto(quincho_hora_inicio_actual, quincho_duracion_actual)}. "
                                "¿Querés que busque otro horario con cancha y quincho disponibles?"
                            )
                            update_conversation_state(
                                telefono or "unknown",
                                fase="coordinacion_propuesta",
                                dia_propuesto=dia_a_validar,
                                hora_propuesta=hora_a_validar,
                                duracion_propuesta=duracion_cancha_actual,
                                duracion_cancha_horas=duracion_cancha_actual,
                                duracion_cancha_explicita=duracion_cancha_explicita_actual,
                                con_quincho=True,
                                quincho=quincho_actual,
                                quincho_hora_inicio=quincho_hora_inicio_actual,
                                quincho_hora_fin=hora_fin_bloque(quincho_hora_inicio_actual, quincho_duracion_actual),
                                quincho_duracion_horas=quincho_duracion_actual,
                                cancha_propuesta=None
                            )
                            agregar_respuesta_pendiente(respuesta, f"quincho_no_disponible sub-intent {idx+1}")
                            if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                                await asyncio.sleep(1.5)
                            continue

                        conv_state_actualizado = get_conversation_state(telefono or "unknown")
                        quiere_nuevo_turno = conv_state_actualizado.get("quiere_nuevo_turno", False)
                        reserva_mismo_dia = _misma_fecha_reserva(reserva_actual, dia_a_validar)
                        debe_consultar_reprogramacion = (
                            reserva_actual
                            and canchas_libres
                            and not quiere_nuevo_turno
                            and (es_reprogramacion_en_curso or reserva_mismo_dia)
                        )

                        dia_txt_validar = formatear_dia_para_cliente_con_mensaje(dia_a_validar, fragmento or ultimo_mensaje)

                        # Si el usuario ya confirmó que quiere un turno NUEVO, NO volver a preguntar
                        if debe_consultar_reprogramacion:
                            canchas_str = " o ".join(canchas_libres)
                            dia_actual_reserva = reserva_actual.get("fecha", "")
                            hora_actual_reserva = reserva_actual.get("hora", "")
                            cancha_actual_reserva = reserva_actual.get("cancha", "")
                            respuesta = (
                                f"Tenés un turno actual para {dia_actual_reserva} a las {formatear_hora_para_mensaje(hora_actual_reserva)} en {cancha_actual_reserva}. "
                                f"¿Querés REPROGRAMAR tu turno actual para ese horario o querés un NUEVO turno aparte? "
                                f"Respondé 'reprogramar' o 'nuevo turno'."
                            )
                            nueva_fase = "esperando_decision_reprogramacion"
                            update_conversation_state(telefono or "unknown", canchas_libres=canchas_libres)
                            print(f"   🔄 [Calendario] Usuario con turno activo → consultando reprogramar/nuevo turno")
                        elif len(canchas_libres) == 1:
                            respuesta = f"Sí, tengo disponible {canchas_libres[0]} para {dia_txt_validar} a las {formatear_hora_para_mensaje(hora_a_validar)}. ¿La reservo?"
                            cancha_detectada = canchas_libres[0]
                        elif len(canchas_libres) > 1:
                            canchas_str = " o ".join(canchas_libres)
                            respuesta = f"Sí, tengo {canchas_str} libre para {dia_txt_validar} a las {formatear_hora_para_mensaje(hora_a_validar)}. ¿Cuál preferís?"
                        else:
                            respuesta = f"Sí, tengo disponibilidad para {dia_txt_validar} a las {formatear_hora_para_mensaje(hora_a_validar)}. ¿En qué cancha querés?"

                        if debe_consultar_reprogramacion:
                            pass  # ya seteamos nueva_fase arriba, no auto-confirmar
                        elif cancha_detectada and cancha_detectada in canchas_libres:
                            tipo = "confirmado"
                            nueva_fase = "coordinacion_confirmada"
                            respuesta = f"Perfecto, {cancha_detectada} está libre para {dia_txt_validar} a las {formatear_hora_para_mensaje(hora_a_validar)}. ¿Confirmamos?"
                        else:
                            nueva_fase = "coordinacion_propuesta"

            update_kwargs = {"fase": nueva_fase}
            update_kwargs["duracion_propuesta"] = duracion_detectada
            if dia_detectado:
                update_kwargs["dia_propuesto"] = dia_detectado
            if hora_es_valida(hora_detectada):
                update_kwargs["hora_propuesta"] = hora_detectada
            if cancha_detectada:
                update_kwargs["cancha_propuesta"] = cancha_detectada
                print(f"   🧠 [MEMORIA] Guardando cancha en estado: {cancha_detectada}")
            if (
                conv_state.get("con_quincho")
                and str(conv_state.get("quincho_confirmacion_origen") or "") == "usuario"
            ):
                duracion_cancha_estado = (
                    conv_state.get("duracion_cancha_horas")
                    if conv_state.get("duracion_cancha_explicita")
                    else DEFAULT_TURN_DURATION_HOURS
                )
                update_kwargs["con_quincho"] = True
                update_kwargs["quincho"] = normalizar_nombre_quincho(conv_state.get("quincho") or "")
                update_kwargs["quincho_hora_inicio"] = conv_state.get("quincho_hora_inicio") or (hora_detectada if hora_es_valida(hora_detectada) else conv_state.get("hora_propuesta"))
                update_kwargs["quincho_hora_fin"] = conv_state.get("quincho_hora_fin") or ""
                update_kwargs["quincho_duracion_horas"] = conv_state.get("quincho_duracion_horas") or duracion_detectada
                update_kwargs["duracion_propuesta"] = normalizar_duracion_horas(duracion_cancha_estado)
                update_kwargs["duracion_cancha_horas"] = normalizar_duracion_horas(duracion_cancha_estado)
                update_kwargs["duracion_cancha_explicita"] = bool(conv_state.get("duracion_cancha_explicita"))

            if respuesta and not hora_es_valida(hora_detectada):
                respuesta_sin_rangos = quitar_rangos_horarios(respuesta)
                hora_en_respuesta = await extraer_hora_de_texto(respuesta_sin_rangos)
                if hora_en_respuesta:
                    update_kwargs["hora_propuesta"] = hora_en_respuesta
                dia_en_respuesta = extraer_dia_de_texto(respuesta_sin_rangos)
                if dia_en_respuesta and not dia_detectado:
                    update_kwargs["dia_propuesto"] = dia_en_respuesta

            update_conversation_state(telefono or "unknown", **update_kwargs)
            conv_state_actualizado = get_conversation_state(telefono or "unknown")

            # ============================================================
            # REPROGRAMACIÓN AUTOMÁTICA (cuando el usuario ya confirmó que quiere reprogramar)
            # ============================================================
            if tipo == "reprogramacion_automatica":
                dia_raw = analysis.get("dia_detectado") or dia_detectado
                hora_final = analysis.get("hora_detectada") or hora_detectada
                cancha_final = analysis.get("cancha_detectada") or cancha_detectada

                print(f"   🔄 [Reprogramación Automática] Procesando...")
                print(f"      Día: {dia_raw}, Hora: {hora_final}, Cancha: {cancha_final}")

                if not validar_hora_en_franja(hora_final):
                    respuesta = (
                        f"Ese horario esta fuera de nuestra franja de atencion "
                        f"({descripcion_franjas_atencion_mensaje()}). ¿Que horario dentro de esa franja te sirve?"
                    )
                    agregar_respuesta_pendiente(respuesta, f"reprogramacion_fuera_de_franja sub-intent {idx+1}")
                    continue

                reserva_actual = calendario.obtener_reserva_por_telefono(telefono or "unknown")
                if not reserva_actual:
                    reserva_actual = calendario.obtener_reserva_por_nombre(prospecto.get("nombre", ""))

                tiene_senia_pagada = reserva_o_memoria_tiene_senia_pagada(reserva_actual, conv_state_actualizado)
                monto_senia_actual = monto_senia_preservado(reserva_actual, conv_state_actualizado)
                nombre_reserva = reserva_actual.get("nombre", prospecto.get("nombre", "")) if reserva_actual else prospecto.get("nombre", "")

                print(
                    f"   💰 [Reprogramación] Estado seña actual: "
                    f"{'pagada' if tiene_senia_pagada else (reserva_actual or {}).get('senia_estado', 'sin seña')}, "
                    f"Monto: {monto_senia_actual}"
                )

                dia_resuelto_nuevo = resolver_fecha(dia_raw or "hoy")

                if not calendario.slot_esta_libre_en_cancha(dia_resuelto_nuevo, hora_final, cancha_final):
                    dia_alternativo, hora_alternativa = calendario.proximo_slot_libre(dia_resuelto_nuevo, hora_final, cancha=cancha_final)
                    respuesta = f"Ese horario ya está ocupado. ¿Te sirve {dia_alternativo} a las {formatear_hora_para_mensaje(hora_alternativa)}?"
                    agregar_respuesta_pendiente(respuesta, f"reprogramacion_alternativa sub-intent {idx+1}")
                    continue

                slot_ok, (dia_reservado, hora_reservada, cancha_preservada) = calendario.reprogramar_reserva(
                    telefono or "desconocido",
                    nombre_reserva,
                    dia_resuelto_nuevo,
                    hora_final,
                    senia_estado_preservado="pagada" if tiene_senia_pagada else "",
                    senia_monto_preservado=monto_senia_actual if tiene_senia_pagada else ""
                )
                cancha_final = cancha_preservada or cancha_final

                if slot_ok:
                    if tiene_senia_pagada:
                        respuesta = (
                            f"✅ Listo, te cambio tu turno para {dia_reservado} a las {formatear_hora_para_mensaje(hora_reservada)}.\n"
                            f"Te esperamos en {BUSINESS_NAME}.\n"
                            f"Cancha: {cancha_final}\n\n"
                            f"✅ La seña ya estaba registrada.\n\n"
                            f"📌 Si necesitan cambiar o cancelar, avisen con tiempo por este WhatsApp."
                        )
                    else:
                        senia_msg = build_senia_request_message(dia_reservado, hora_reservada)
                        respuesta = (
                            f"✅ Listo, te cambio tu turno para {dia_reservado} a las {formatear_hora_para_mensaje(hora_reservada)}.\n"
                            f"Te esperamos en {BUSINESS_NAME}.\n"
                            f"Cancha: {cancha_final}\n\n"
                            f"{senia_msg}\n\n"
                            f"📌 Si necesitan cambiar o cancelar, avisen con tiempo por este WhatsApp."
                        )

                    registrar_turno_confirmado_en_csv(
                        telefono or "desconocido",
                        prospecto,
                        user_messages,
                        dia_reservado,
                        hora_reservada
                    )

                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_confirmada" if tiene_senia_pagada else "senia_pendiente",
                        dia_propuesto=dia_reservado,
                        hora_propuesta=hora_reservada,
                        cancha_propuesta=cancha_final,
                        senia_estado="pagada" if tiene_senia_pagada else "pendiente",
                        senia_monto=monto_senia_actual if tiene_senia_pagada else _monto_humano(
                            _senia_para_total(calcular_precio_total(duracion_cancha_turno))
                        )
                    )

                    print(f"   ✅ [Reprogramación] Turno cambiado automáticamente")
                else:
                    respuesta = f"Hubo un problema al reprogramar el turno. ¿Podés intentar de nuevo?"
                    print(f"   ⚠️ [Reprogramación] Falló la reserva")

                agregar_respuesta_pendiente(respuesta, f"reprogramacion_automatica sub-intent {idx+1}")
                continue

            if tipo == "reprogramacion_con_alternativa":
                respuesta = analysis.get("respuesta", "")
                update_conversation_state(
                    telefono or "unknown",
                    fase="coordinacion_propuesta",
                    en_proceso_cambio=True,
                    dia_propuesto=analysis.get("dia_detectado") or dia_detectado,
                    hora_propuesta=analysis.get("hora_detectada") or hora_detectada
                )
                agregar_respuesta_pendiente(respuesta, f"reprogramacion_con_alternativa sub-intent {idx+1}")
                if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                    await asyncio.sleep(1.5)
                continue

            # ── TIPO CONFIRMADO: RESERVAR EN CALENDARIO ──
            if tipo == "confirmado":
                dia_raw = dia_detectado or conv_state_actualizado.get("dia_propuesto", "")
                if str(dia_raw).strip().lower() in ("null", "none", ""):
                    dia_raw = ""
                hora_final = hora_detectada or conv_state_actualizado.get("hora_propuesta", "")
                cancha_final = cancha_detectada or conv_state_actualizado.get("cancha_propuesta")
                con_quincho_turno = quincho_autorizado_para_confirmacion(
                    conv_state_actualizado,
                    dia_raw,
                    hora_final,
                    cancha_final or "",
                )
                if conv_state_actualizado.get("con_quincho") and not con_quincho_turno:
                    print(
                        "   🛡️ [ADDON GUARD] Ignoro con_quincho=True sin procedencia válida "
                        "para el borrador/reserva actual"
                    )
                quincho_turno = normalizar_nombre_quincho(conv_state_actualizado.get("quincho") or "") if con_quincho_turno else ""
                quincho_hora_inicio_turno = (
                    conv_state_actualizado.get("quincho_hora_inicio")
                    or _quincho_default_start_after_court(
                        hora_final,
                        conv_state_actualizado.get("duracion_cancha_horas")
                        or conv_state_actualizado.get("duracion_propuesta")
                        or DEFAULT_TURN_DURATION_HOURS,
                    )
                ) if con_quincho_turno else ""
                quincho_hora_fin_turno = hora_fin_bloque(quincho_hora_inicio_turno, conv_state_actualizado.get("quincho_duracion_horas") or duracion_detectada) if con_quincho_turno else ""
                quincho_duracion_turno = conv_state_actualizado.get("quincho_duracion_horas") or duracion_detectada
                if con_quincho_turno and not conv_state_actualizado.get("duracion_cancha_explicita"):
                    duracion_cancha_turno = normalizar_duracion_horas(DEFAULT_TURN_DURATION_HOURS)
                else:
                    duracion_cancha_turno = normalizar_duracion_horas(
                        conv_state_actualizado.get("duracion_cancha_horas")
                        or conv_state_actualizado.get("duracion_propuesta")
                        or duracion_detectada
                        or DEFAULT_TURN_DURATION_HOURS
                    )

                # Si la IA clasificó como confirmación pero todavía falta elegir cancha,
                # NO se puede reservar ni prometer verificar: consultar calendario real y proponer.
                if normalizar_valor_nullable(dia_raw) and hora_es_valida(hora_final) and not cancha_final:
                    dia_resuelto_confirmado = resolver_fecha(dia_raw)
                    minutos_confirmado = minutos_hasta_turno(dia_resuelto_confirmado, hora_final)
                    if (
                        MIN_BOOKING_NOTICE_MINUTES > 0
                        and minutos_confirmado is not None
                        and minutos_confirmado < MIN_BOOKING_NOTICE_MINUTES
                    ):
                        alt_dia, alt_hora = proximo_slot_reservable_con_anticipacion(
                            dia_resuelto_confirmado,
                            hora_final,
                            duracion_horas=duracion_cancha_turno,
                        )
                        if alt_dia and alt_hora:
                            respuesta_falta_cancha = (
                                f"Ese horario queda dentro del mínimo de "
                                f"{MIN_BOOKING_NOTICE_MINUTES // 60} horas de anticipación. "
                                f"El próximo horario reservable que encontré es {alt_dia} a las "
                                f"{formatear_hora_para_mensaje(alt_hora)}. ¿Te sirve?"
                            )
                        else:
                            respuesta_falta_cancha = (
                                f"Ese horario queda dentro del mínimo de "
                                f"{MIN_BOOKING_NOTICE_MINUTES // 60} horas de anticipación. "
                                "¿Querés que te muestre los próximos horarios reservables?"
                            )
                        update_conversation_state(
                            telefono or "unknown",
                            fase="coordinacion_propuesta",
                            dia_propuesto=dia_resuelto_confirmado,
                            hora_propuesta=hora_final,
                            cancha_propuesta=None,
                            duracion_propuesta=duracion_cancha_turno,
                        )
                        agregar_respuesta_pendiente(
                            respuesta_falta_cancha,
                            f"confirmado_sin_cancha_anticipacion sub-intent {idx+1}",
                        )
                        continue

                    canchas_confirmado = canchas_libres_para_bloque(
                        dia_resuelto_confirmado,
                        hora_final,
                        duracion_cancha_turno,
                    )
                    dia_txt_confirmado = formatear_dia_para_cliente_con_mensaje(
                        dia_resuelto_confirmado,
                        fragmento or ultimo_mensaje,
                    )
                    if len(canchas_confirmado) == 1:
                        cancha_unica = canchas_confirmado[0]
                        respuesta_falta_cancha = (
                            f"Sí, tengo {cancha_unica} libre para {dia_txt_confirmado} a las "
                            f"{formatear_hora_para_mensaje(hora_final)}. ¿La reservo?"
                        )
                        cancha_estado = cancha_unica
                    elif len(canchas_confirmado) > 1:
                        respuesta_falta_cancha = (
                            f"Sí, tengo {' o '.join(canchas_confirmado)} libre para {dia_txt_confirmado} "
                            f"a las {formatear_hora_para_mensaje(hora_final)}. ¿Cuál preferís?"
                        )
                        cancha_estado = None
                    else:
                        alt_dia, alt_hora = calendario.proximo_slot_libre(
                            dia_resuelto_confirmado,
                            hora_final,
                            cancha=None,
                        )
                        respuesta_falta_cancha = (
                            f"No tengo cancha libre para {dia_txt_confirmado} a las "
                            f"{formatear_hora_para_mensaje(hora_final)}. "
                            f"El próximo horario libre que encontré es {alt_dia} a las "
                            f"{formatear_hora_para_mensaje(alt_hora)}. ¿Te sirve?"
                        )
                        cancha_estado = None

                    update_conversation_state(
                        telefono or "unknown",
                        fase="coordinacion_propuesta",
                        dia_propuesto=dia_resuelto_confirmado,
                        hora_propuesta=hora_final,
                        cancha_propuesta=cancha_estado,
                        canchas_libres=canchas_confirmado,
                        duracion_propuesta=duracion_cancha_turno,
                        duracion_cancha_horas=duracion_cancha_turno,
                    )
                    agregar_respuesta_pendiente(
                        respuesta_falta_cancha,
                        f"confirmado_sin_cancha sub-intent {idx+1}",
                    )
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.0)
                    continue

                if normalizar_valor_nullable(dia_raw) and hora_es_valida(hora_final) and cancha_final:
                    if not nombre_cliente_identificado(prospecto):
                        update_conversation_state(
                            telefono or "unknown",
                            fase="esperando_nombre_reserva",
                            dia_propuesto=dia_raw,
                            hora_propuesta=hora_final,
                            cancha_propuesta=cancha_final,
                            duracion_propuesta=duracion_cancha_turno,
                            duracion_cancha_horas=duracion_cancha_turno,
                            duracion_cancha_explicita=bool(conv_state_actualizado.get("duracion_cancha_explicita")),
                            con_quincho=con_quincho_turno,
                            quincho_confirmacion_origen=("usuario" if con_quincho_turno else None),
                            quincho=quincho_turno,
                            quincho_hora_inicio=quincho_hora_inicio_turno,
                            quincho_hora_fin=quincho_hora_fin_turno,
                            quincho_duracion_horas=quincho_duracion_turno,
                            senia_estado="pendiente",
                            senia_monto="",
                            nombre_reserva_pendiente=True
                        )
                        respuesta = build_pedido_nombre_reserva_message()
                        agregar_respuesta_pendiente(respuesta, f"pedido_nombre_reserva sub-intent {idx+1}")
                        if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                            await asyncio.sleep(1.5)
                        continue

                    reserva_actual_cliente = calendario.obtener_reserva_por_telefono(
                        telefono or "unknown",
                        prospecto.get("nombre", "")
                    )
                    if not reserva_actual_cliente and prospecto.get("nombre"):
                        reserva_actual_cliente = calendario.obtener_reserva_por_nombre(prospecto.get("nombre", ""))
                    quiere_nuevo_turno = bool(conv_state_actualizado.get("quiere_nuevo_turno"))

                    # IDEMPOTENCIA: una confirmación repetida del MISMO turno no intenta
                    # reservar otra vez ni puede responder que está "ocupado" por sí mismo.
                    if (
                        reserva_actual_cliente
                        and not quiere_nuevo_turno
                        and reserva_coincide_con_pedido(
                            reserva_actual_cliente,
                            dia_raw,
                            hora_final,
                            cancha_final,
                        )
                    ):
                        duracion_existente = normalizar_duracion_horas(
                            reserva_actual_cliente.get("duracion_horas")
                            or duracion_cancha_turno
                            or DEFAULT_TURN_DURATION_HOURS
                        )
                        precio_existente = (
                            _monto_a_int(reserva_actual_cliente.get("precio_total"))
                            or calcular_precio_total(duracion_existente)
                        )
                        senia_existente = _senia_guardada_o_configurada(
                            reserva_actual_cliente,
                            precio_existente,
                        )
                        saldo_existente = (
                            _monto_a_int(reserva_actual_cliente.get("monto_pendiente"))
                        )
                        if saldo_existente is None:
                            saldo_existente = calcular_monto_pendiente(
                                precio_existente,
                                senia_existente,
                            )

                        if reserva_tiene_senia_pendiente(reserva_actual_cliente):
                            respuesta = (
                                "Sí, ya quedó tomado a tu nombre; no hace falta reservarlo otra vez.\n\n"
                                + build_reserva_pendiente_senia_message(
                                    reserva_actual_cliente.get("fecha") or dia_raw,
                                    reserva_actual_cliente.get("hora") or hora_final,
                                    reserva_actual_cliente.get("cancha") or cancha_final,
                                    duracion_existente,
                                    precio_existente,
                                    senia_existente,
                                    saldo_existente,
                                    con_quincho=_reserva_indica_quincho(reserva_actual_cliente),
                                    quincho=reserva_actual_cliente.get("quincho") or "",
                                    quincho_hora_inicio=reserva_actual_cliente.get("quincho_hora_inicio") or "",
                                    quincho_duracion_horas=reserva_actual_cliente.get("quincho_duracion_horas") or duracion_existente,
                                    quincho_precio_total=_monto_a_int(reserva_actual_cliente.get("quincho_precio_total")) or 0,
                                ).replace("__NO_CONSOLIDAR__\n", "")
                            )
                            update_conversation_state(
                                telefono or "unknown",
                                fase="senia_pendiente",
                                senia_estado="pendiente",
                            )
                        else:
                            respuesta = build_confirmacion_senia_registrada_message(
                                reserva_actual_cliente
                            )

                        print(
                            f"   ♻️ [IDEMPOTENCIA] Confirmación repetida del mismo turno "
                            f"{dia_raw} {hora_final} {cancha_final} → no reservo de nuevo"
                        )
                        agregar_respuesta_pendiente(
                            respuesta,
                            f"confirmacion_idempotente sub-intent {idx+1}",
                        )
                        continue

                    if (
                        reserva_actual_cliente
                        and not quiere_nuevo_turno
                        and not reserva_coincide_con_pedido(reserva_actual_cliente, dia_raw, hora_final, cancha_final)
                    ):
                        respuesta = build_pregunta_reprogramar_o_nuevo(
                            reserva_actual_cliente,
                            dia_raw,
                            hora_final,
                            cancha_final
                        )
                        update_conversation_state(
                            telefono or "unknown",
                            fase="esperando_decision_reprogramacion",
                            dia_propuesto=dia_raw,
                            hora_propuesta=hora_final,
                            cancha_propuesta=cancha_final,
                            duracion_propuesta=duracion_cancha_turno,
                            duracion_cancha_horas=duracion_cancha_turno,
                            duracion_cancha_explicita=bool(conv_state_actualizado.get("duracion_cancha_explicita")),
                            con_quincho=con_quincho_turno,
                            quincho=quincho_turno,
                            quincho_hora_inicio=quincho_hora_inicio_turno,
                            quincho_hora_fin=quincho_hora_fin_turno,
                            quincho_duracion_horas=quincho_duracion_turno,
                            reserva_actual=reserva_actual_cliente,
                            quiere_nuevo_turno=False
                        )
                        agregar_respuesta_pendiente(respuesta, f"doble_reserva_guard sub-intent {idx+1}")
                        if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                            await asyncio.sleep(1.5)
                        continue

                    print(f"   📝 [Calendario] Guardando reserva PENDIENTE en calendario_turnos.csv")
                    print(f"      Día: {dia_raw}, Hora: {hora_final}, Cancha: {cancha_final}")
                    await avisar_cliente_riesgoso_admin(page, telefono or "desconocido", prospecto, dia_raw, hora_final, cancha_final)

                    resultado_pendiente = reservar_turno_en_calendario(
                        telefono or "desconocido",
                        prospecto,
                        dia_raw,
                        hora_final,
                        cancha=cancha_final,
                        estado_reserva=BOOKING_STATUS_PENDING,
                        senia_estado="pendiente",
                        senia_monto="",
                        duracion_horas=duracion_cancha_turno,
                        con_quincho=con_quincho_turno,
                        quincho=quincho_turno,
                        quincho_hora_inicio=quincho_hora_inicio_turno,
                        quincho_duracion_horas=quincho_duracion_turno,
                        es_nuevo_turno=quiere_nuevo_turno
                    )

                    if resultado_pendiente.get("ok"):
                        print(f"   ✅ [Calendario] Reserva PENDIENTE guardada: {resultado_pendiente['dia']} {resultado_pendiente['hora']} - {cancha_final}")

                        dia_guardado = resultado_pendiente["dia"]
                        hora_guardada = resultado_pendiente["hora"]
                        cancha_guardada = resultado_pendiente.get("cancha") or cancha_final

                        update_conversation_state(
                            telefono or "unknown",
                            fase="senia_pendiente",
                            dia_propuesto=dia_guardado,
                            hora_propuesta=hora_guardada,
                            cancha_propuesta=cancha_guardada,
                            duracion_propuesta=duracion_cancha_turno,
                            duracion_cancha_horas=duracion_cancha_turno,
                            duracion_cancha_explicita=bool(conv_state_actualizado.get("duracion_cancha_explicita")),
                            con_quincho=con_quincho_turno,
                            quincho=quincho_turno,
                            quincho_hora_inicio=resultado_pendiente.get("quincho_hora_inicio") or quincho_hora_inicio_turno,
                            quincho_hora_fin=resultado_pendiente.get("quincho_hora_fin") or quincho_hora_fin_turno,
                            quincho_duracion_horas=quincho_duracion_turno,
                            senia_estado="pendiente",
                            senia_monto=_monto_humano(
                                _monto_a_int(resultado_pendiente.get("senia_valor"))
                                if _monto_a_int(resultado_pendiente.get("senia_valor")) is not None
                                else _senia_para_total(resultado_pendiente.get("precio_total"))
                            ),
                            quiere_nuevo_turno=False,
                            seleccion_cancha_pendiente=None,
                            consulta_disponibilidad_pendiente=None,
                            aclaracion_hora_contexto=None,
                            booking_draft=None
                        )

                        registrar_turno_confirmado_en_csv(
                            telefono or "desconocido",
                            prospecto,
                            user_messages,
                            dia_guardado,
                            hora_guardada
                        )

                        if REQUIRES_DEPOSIT:
                            precio_total_pendiente = _monto_a_int(resultado_pendiente.get("precio_total")) or calcular_precio_total(duracion_cancha_turno)
                            senia_valor_pendiente = _monto_a_int(resultado_pendiente.get("senia_valor"))
                            if senia_valor_pendiente is None:
                                senia_valor_pendiente = _senia_para_total(precio_total_pendiente)
                            monto_pendiente_reserva = calcular_monto_pendiente(precio_total_pendiente, senia_valor_pendiente)
                            respuesta = build_reserva_pendiente_senia_message(
                                dia_guardado,
                                hora_guardada,
                                cancha_guardada,
                                duracion_cancha_turno,
                                precio_total_pendiente,
                                senia_valor_pendiente,
                                monto_pendiente_reserva,
                                con_quincho=bool(resultado_pendiente.get("con_quincho")),
                                quincho=resultado_pendiente.get("quincho") or quincho_turno,
                                quincho_hora_inicio=resultado_pendiente.get("quincho_hora_inicio") or quincho_hora_inicio_turno,
                                quincho_duracion_horas=resultado_pendiente.get("quincho_duracion_horas") or quincho_duracion_turno,
                                quincho_precio_total=_monto_a_int(resultado_pendiente.get("quincho_precio_total")) or 0,
                            )
                        else:
                            respuesta = f"✅ Listo, {cancha_guardada} reservada para {dia_guardado} a las {formatear_hora_para_mensaje(hora_guardada)}. Te esperamos en {BUSINESS_NAME}."

                        agregar_respuesta_pendiente(respuesta, f"confirmado sub-intent {idx+1}")
                        if REQUIRES_DEPOSIT:
                            pending_admin_alert_payloads.append(dict(resultado_pendiente))
                        if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                            await asyncio.sleep(1.5)
                        continue
                    else:
                        print(f"   ⚠️ [Calendario] No se pudo guardar reserva pendiente: {resultado_pendiente.get('respuesta')}")
                        # Contrato transaccional: si calendario dice ok=False, NUNCA puede
                        # sobrevivir un texto generativo que afirme que la reserva quedó hecha.
                        respuesta_fallo = (
                            resultado_pendiente.get("respuesta")
                            or "No pude guardar ese turno. ¿Querés que busque otra opción?"
                        )
                        update_conversation_state(
                            telefono or "unknown",
                            fase="coordinacion_propuesta",
                            dia_propuesto=resultado_pendiente.get("dia") or dia_raw,
                            hora_propuesta=resultado_pendiente.get("hora") or hora_final,
                            cancha_propuesta=resultado_pendiente.get("cancha") or cancha_final,
                            duracion_propuesta=duracion_cancha_turno,
                            duracion_cancha_horas=duracion_cancha_turno,
                            con_quincho=con_quincho_turno,
                            quincho=quincho_turno,
                            senia_estado="",
                        )
                        agregar_respuesta_pendiente(
                            respuesta_fallo,
                            f"reserva_fallida sub-intent {idx+1}",
                        )
                        if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                            await asyncio.sleep(1.0)
                        continue

                # ... (resto del código de tipo confirmado - igual que antes)
                # (este bloque es muy largo, se mantiene igual)

            if respuesta and tipo != "respuesta_directa":
                if respuesta_es_placeholder_verificacion(respuesta):
                    print(
                        f"   ⚠️ [Respuesta genérica] Placeholder detectado; "
                        "ejecuto la consulta real antes de responder."
                    )
                    estado_placeholder = get_conversation_state(telefono or "unknown")
                    dia_placeholder = dia_detectado or estado_placeholder.get("dia_propuesto") or "hoy"
                    hora_placeholder = hora_detectada or estado_placeholder.get("hora_propuesta")
                    cancha_placeholder = cancha_detectada or estado_placeholder.get("cancha_propuesta")
                    duracion_placeholder = normalizar_duracion_horas(
                        estado_placeholder.get("duracion_cancha_horas")
                        or estado_placeholder.get("duracion_propuesta")
                        or duracion_detectada
                        or DEFAULT_TURN_DURATION_HOURS
                    )

                    if hora_es_valida(hora_placeholder):
                        dia_resuelto_placeholder = resolver_fecha(dia_placeholder)
                        libres_placeholder = canchas_libres_para_bloque(
                            dia_resuelto_placeholder,
                            hora_placeholder,
                            duracion_placeholder,
                            cancha_placeholder,
                        )
                        dia_txt_placeholder = formatear_dia_para_cliente_con_mensaje(
                            dia_resuelto_placeholder,
                            fragmento or ultimo_mensaje,
                        )
                        if libres_placeholder:
                            if len(libres_placeholder) == 1:
                                respuesta_real = (
                                    f"Sí, tengo {libres_placeholder[0]} libre para {dia_txt_placeholder} "
                                    f"a las {formatear_hora_para_mensaje(hora_placeholder)}. ¿La reservo?"
                                )
                            else:
                                respuesta_real = (
                                    f"Sí, tengo {' o '.join(libres_placeholder)} libre para {dia_txt_placeholder} "
                                    f"a las {formatear_hora_para_mensaje(hora_placeholder)}. ¿Cuál preferís?"
                                )
                        else:
                            alt_dia, alt_hora = calendario.proximo_slot_libre(
                                dia_resuelto_placeholder,
                                hora_placeholder,
                                cancha=cancha_placeholder,
                            )
                            respuesta_real = (
                                f"No tengo disponibilidad para {dia_txt_placeholder} a las "
                                f"{formatear_hora_para_mensaje(hora_placeholder)}. "
                                f"El próximo horario libre que encontré es {alt_dia} a las "
                                f"{formatear_hora_para_mensaje(alt_hora)}. ¿Te sirve?"
                            )
                    else:
                        respuesta_real = obtener_resumen_horarios_disponibles(dia_placeholder)

                    agregar_respuesta_pendiente(
                        respuesta_real,
                        f"placeholder_resuelto sub-intent {idx+1}",
                    )
                    if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                        await asyncio.sleep(1.0)
                    continue
                print(f"   💬 Acumulando respuesta sub-intent {idx+1}: {respuesta[:100]}")
                agregar_respuesta_pendiente(respuesta, f"generica sub-intent {idx+1}")
                if len(sub_intenciones) > 1 and idx < len(sub_intenciones) - 1:
                    await asyncio.sleep(1.5)

        if respuestas_pendientes:
            conv_state_final = get_conversation_state(telefono or "unknown")
            respuestas_formateadas = [
                str(r or "").replace("__NO_CONSOLIDAR__", "", 1).strip()
                for r in respuestas_pendientes
                if str(r or "").lstrip().startswith("__NO_CONSOLIDAR__")
            ]
            if respuestas_formateadas:
                respuesta_final = respuestas_formateadas[0]
                respuesta_final = await formatear_respuesta_whatsapp_con_ia(
                    ultimo_mensaje,
                    respuesta_final,
                    conv_state_final,
                    prospecto
                )
                print("   [Consolidacion] Envio directo de respuesta formateada.")
            else:
                respuestas_originales = [
                    str(r or "").replace("__NO_CONSOLIDAR__", "", 1).strip()
                    for r in respuestas_pendientes
                ]
                respuesta_final = await consolidar_respuestas_ia(
                    ultimo_mensaje,
                    respuestas_originales,
                    conv_state_final,
                    prospecto
                )
                respuesta_final = limpiar_identidad_agente_en_respuesta(respuesta_final)

                validacion, nueva = await asyncio.gather(
                    validar_respuesta_con_ia(
                        ultimo_mensaje,
                        respuesta_final,
                        conv_state_final,
                        prospecto
                    ),
                    regenerar_respuesta_con_ia(
                        ultimo_mensaje,
                        conv_state_final,
                        "Generá una alternativa solo si mejora la respuesta original. No cambies datos factuales.",
                        prospecto,
                        respuesta_original=respuesta_final
                    )
                )

                candidatos_finales = [
                    {"origen": f"parcial_{i + 1}", "texto": r}
                    for i, r in enumerate(respuestas_originales)
                    if r
                ]
                candidatos_finales.append({"origen": "consolidada", "texto": respuesta_final})
                if nueva:
                    candidatos_finales.append({"origen": "regenerada", "texto": limpiar_identidad_agente_en_respuesta(nueva)})

                respuesta_arbitrada = await arbitrar_respuesta_final_ia(
                    ultimo_mensaje,
                    candidatos_finales,
                    validacion,
                    conv_state_final,
                    prospecto
                )
                if respuesta_arbitrada:
                    respuesta_final = respuesta_arbitrada

                respuesta_final = await formatear_respuesta_whatsapp_con_ia(
                    ultimo_mensaje,
                    respuesta_final,
                    conv_state_final,
                    prospecto
                )

            legacy_failure_signal = next((
                signal
                for candidate in [*respuestas_pendientes, respuesta_final]
                if (
                    signal := _agent_v2_v140_internal_failure_signal(
                        str(candidate or "")
                    )
                )
            ), "")
            if legacy_failure_signal:
                respuesta_final, final_response_sent = (
                    await _agent_v2_v140_send_legacy_internal_handoff(
                        page,
                        source=legacy_failure_signal,
                        original_response=respuesta_final,
                        telefono=telefono or "unknown",
                        prospecto=prospecto,
                        mensaje_usuario=" ".join(user_messages or []),
                    )
                )
            else:
                final_response_sent = await send_message(page, respuesta_final)
            if final_response_sent is True:
                for pending_payload in pending_admin_alert_payloads:
                    enqueue_pending_booking_admin_alert(
                        pending_payload,
                        telefono or "unknown",
                        prospecto,
                    )
            add_to_history(telefono or "unknown", "assistant", respuesta_final)
            guardar_historial_chat(telefono or "unknown", user_messages, respuesta_final)

        await asyncio.sleep(3)

