BROWSER_SESSION_MAX_CONSECUTIVE_RESTARTS = max(
    1,
    int(os.getenv("WPSETTER_BROWSER_MAX_RESTARTS", "5")),
)
BROWSER_SESSION_STABLE_RESET_SECONDS = max(
    30,
    int(os.getenv("WPSETTER_BROWSER_STABLE_RESET_SECONDS", "300")),
)
BROWSER_SESSION_MAX_BACKOFF_SECONDS = max(
    3,
    int(os.getenv("WPSETTER_BROWSER_MAX_BACKOFF_SECONDS", "30")),
)
PROFILE_INSTANCE_LOCK_FILENAME = ".wpsetter.instance.lock"
PROFILE_INSTANCE_LOCK_OFFSET = 4095


def _profile_instance_lock_metadata(handle) -> Dict[str, Any]:
    try:
        handle.seek(0)
        raw = (
            handle.read(PROFILE_INSTANCE_LOCK_OFFSET)
            .decode("utf-8", errors="replace")
            .strip("\x00 \r\n\t")
        )
        data = json.loads(raw) if raw else {}
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def acquire_profile_instance_lock(profile: str) -> Dict[str, Any]:
    """Impide dos WPSetter simultáneos sobre el mismo perfil de Chrome.

    El descriptor permanece abierto durante toda la vida del proceso. El lock
    lo libera el sistema operativo incluso ante un cierre abrupto, por lo que
    un archivo remanente nunca bloquea por sí solo el siguiente arranque.
    """
    normalized_profile = os.path.realpath(os.path.abspath(str(profile or "")))
    os.makedirs(normalized_profile, exist_ok=True)
    lock_path = os.path.join(normalized_profile, PROFILE_INSTANCE_LOCK_FILENAME)
    try:
        handle = open(lock_path, "r+b", buffering=0)
    except FileNotFoundError:
        handle = open(lock_path, "w+b", buffering=0)
    handle.seek(0, os.SEEK_END)
    if handle.tell() <= PROFILE_INSTANCE_LOCK_OFFSET:
        handle.seek(PROFILE_INSTANCE_LOCK_OFFSET)
        handle.write(b"\x00")
    handle.seek(PROFILE_INSTANCE_LOCK_OFFSET)

    try:
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except (OSError, IOError):
        owner = _profile_instance_lock_metadata(handle)
        handle.close()
        return {
            "acquired": False,
            "path": lock_path,
            "profile": normalized_profile,
            "owner": owner,
        }

    owner = {
        "pid": os.getpid(),
        "started_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "profile": normalized_profile,
        "script": os.path.abspath(__file__),
    }
    payload = json.dumps(owner, ensure_ascii=False).encode("utf-8")
    if len(payload) >= PROFILE_INSTANCE_LOCK_OFFSET:
        release_profile_instance_lock({"handle": handle})
        raise RuntimeError("profile_instance_lock_metadata_too_large")
    handle.seek(0)
    handle.write(payload.ljust(PROFILE_INSTANCE_LOCK_OFFSET, b"\x00"))
    handle.flush()
    handle.seek(PROFILE_INSTANCE_LOCK_OFFSET)
    return {
        "acquired": True,
        "path": lock_path,
        "profile": normalized_profile,
        "owner": owner,
        "handle": handle,
    }


def release_profile_instance_lock(lock: Optional[Dict[str, Any]]) -> None:
    handle = (lock or {}).get("handle") if isinstance(lock, dict) else None
    if handle is None:
        return
    try:
        handle.seek(0)
        handle.write(b"\x00" * PROFILE_INSTANCE_LOCK_OFFSET)
        handle.flush()
        handle.seek(PROFILE_INSTANCE_LOCK_OFFSET)
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    except (OSError, IOError):
        pass
    finally:
        try:
            handle.close()
        except Exception:
            pass


def _browser_session_restart_policy(
    previous_attempts: int,
    session_uptime_seconds: float,
) -> Dict[str, Any]:
    """Circuit breaker para cierres consecutivos del navegador.

    Una sesión que sobrevivió el umbral estable inicia una serie nueva. Los
    cierres rápidos consecutivos tienen un máximo estricto; al superarlo el
    proceso termina con error para no abrir Chrome indefinidamente.
    """
    stable_reset = float(session_uptime_seconds or 0) >= float(
        BROWSER_SESSION_STABLE_RESET_SECONDS
    )
    base_attempts = 0 if stable_reset else max(0, int(previous_attempts or 0))
    next_attempt = base_attempts + 1
    return {
        "attempt": next_attempt,
        "allowed": next_attempt <= BROWSER_SESSION_MAX_CONSECUTIVE_RESTARTS,
        "backoff_seconds": min(
            BROWSER_SESSION_MAX_BACKOFF_SECONDS,
            3 * next_attempt,
        ),
        "stable_reset": stable_reset,
        "max_attempts": BROWSER_SESSION_MAX_CONSECUTIVE_RESTARTS,
        "session_uptime_seconds": max(0.0, float(session_uptime_seconds or 0)),
    }


async def main(profile):
    print("=" * 60)
    print("🚀 WPSetter - Agente IA Recepcionista")
    print("=" * 60)
    print(f"📱 Número autorizado: {AUTHORIZED_NUMBER}")
    print(f"📁 Archivo de negocios: {NEGOCIOS_CSV}")
    print(f"📂 Perfil principal: {profile}")
    print(f"📅 Calendario CSV: calendario_llamadas.csv")
    try:
        _learning_status = AGENT_LEARNING_MANAGER.status()
        print(
            f"🧠 Learning: {'ON' if _learning_status.get('enabled') else 'OFF'} | "
            f"policy v{_learning_status.get('policy_version')} | "
            f"experiencias={_learning_status.get('experience_count')} | "
            f"fallos={_learning_status.get('failure_count')}"
        )
    except Exception:
        pass
    print("=" * 60)

    async with async_playwright() as p:
        restart_attempt = 0
        while True:
            browser = None
            restart_requested = False
            session_started_monotonic = None
            try:
                browser = await p.chromium.launch_persistent_context(
                    **persistent_context_options(profile)
                )

                page = browser.pages[0] if browser.pages else await browser.new_page()
                print("🌐 Abriendo WhatsApp Web...")
                await page.goto(
                    "https://web.whatsapp.com",
                    timeout=120000,
                    wait_until="domcontentloaded",
                )
                await asyncio.sleep(40)
                print("✅ WhatsApp Web cargado")

                await wait_for_qr_scan_with_change_detection(page)

                print("✅ [SESIÓN] Sesión activa → iniciando automatización")

                # V199 MEDIA RESTART RECOVERY:
                # antes de volver al router general, reabrimos explícitamente el
                # chat cuyo lote multimedia derribó Chrome. Se usa /send con text=
                # vacío: abre el chat, pero NO envía ningún mensaje.
                if _media_browser_recovery_pending():
                    restored = await _restore_media_chat_after_browser_restart(page)
                    if not restored:
                        print(
                            "   ⚠️ [MEDIA RECOVERY] el target sigue pendiente; "
                            "el inbox normal intentará recuperarlo sin descartarlo"
                        )

                session_started_monotonic = time.monotonic()
                loop_result = await automation_loop(page, profile)
                restart_requested = loop_result == "restart_browser"
                if not restart_requested:
                    return
            except Exception as exc:
                error_text = str(exc).lower()
                restart_requested = any(marker in error_text for marker in (
                    "target page, context or browser has been closed",
                    "browser has been closed",
                    "context has been closed",
                    "page has been closed",
                    "connection closed",
                ))
                if not restart_requested:
                    raise
                registrar_metrica_operativa(
                    "browser_session_auto_restart",
                    {"profile": str(profile), "error": str(exc)},
                )
                print(
                    "♻️ [BROWSER] La sesión se cerró inesperadamente; "
                    "WPSetter la va a abrir de nuevo automáticamente"
                )
            finally:
                if browser is not None:
                    try:
                        await browser.close()
                    except Exception:
                        pass

            if not restart_requested:
                return
            session_uptime_seconds = (
                time.monotonic() - session_started_monotonic
                if session_started_monotonic is not None
                else 0.0
            )
            restart_policy = _browser_session_restart_policy(
                restart_attempt,
                session_uptime_seconds,
            )
            restart_attempt = int(restart_policy["attempt"])
            if not restart_policy.get("allowed"):
                registrar_metrica_operativa(
                    "browser_session_restart_circuit_open",
                    {
                        "profile": str(profile),
                        "attempt": restart_attempt,
                        "max_attempts": restart_policy.get("max_attempts"),
                        "session_uptime_seconds": session_uptime_seconds,
                    },
                )
                print(
                    "🛑 [BROWSER CIRCUIT BREAKER] "
                    f"{restart_policy.get('max_attempts')} reinicios consecutivos "
                    "fallaron; detengo WPSetter para evitar un bucle infinito"
                )
                raise RuntimeError(
                    "browser_restart_limit_exceeded: "
                    f"{restart_policy.get('max_attempts')} intentos consecutivos"
                )
            if restart_policy.get("stable_reset"):
                print(
                    "♻️ [BROWSER] La sesión anterior fue estable; "
                    "reinicio el contador de recuperación"
                )
            backoff_seconds = int(restart_policy["backoff_seconds"])
            print(
                f"♻️ [BROWSER] Reinicio #{restart_attempt} en "
                f"{backoff_seconds}s; el mensaje pendiente se volverá a procesar"
            )
            await asyncio.sleep(backoff_seconds)

# ============================================================================
# PARALLEL COURTS: CONTINUIDAD ENTRE LA POLICY FAQ Y LA RESERVA
# ============================================================================
# La consulta "¿puedo reservar dos canchas?" es un READ.  Cuando la respuesta
# ofrece continuar con día/hora, ese alcance debe pasar a ser una decisión
# stateful; de lo contrario el siguiente mensaje temporal se degradaba a una
# reserva simple.  Estos adaptadores se declaran al final para conservar las
# implementaciones existentes y extenderlas sin alterar sus contratos.

def _agent_v2_pending_parallel_courts_question(
    world: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """Obtiene la pregunta vigente que conserva un pedido multi-cancha."""
    for field in ("dia_hora_reserva", "hora", "hora_aclaracion", "dia"):
        question = _agent_v2_pending_question(world or {}, field) or {}
        try:
            count = int(float(
                question.get("requested_court_count")
                or question.get("court_count")
                or 0
            ))
        except (TypeError, ValueError):
            count = 0
        if (
            count >= 2
            and (
                question.get("parallel_courts")
                or question.get("booking_shape") == "multiple_separate"
            )
        ):
            return {
                **question,
                "requested_court_count": count,
                "court_count": count,
            }
    return None


_agent_v2_apply_parallel_courts_policy_authority_base = (
    _agent_v2_apply_parallel_courts_policy_authority
)


def _agent_v2_ground_explicit_daypart_hour(
    hour: Any,
    daypart: Any,
) -> Optional[str]:
    """
    Reconcilia una hora 12h ya extraída por Perception con su franja explícita.

    No interpreta intención ni busca palabras en el mensaje: recibe dos hechos
    estructurados del SemanticFrame. Por ejemplo, ``06:00`` + ``tarde`` sólo
    puede representar 18:00 en el reloj operacional de 24 horas.
    """
    normalized_hour = normalizar_hora_detectada(hour)
    normalized_daypart = normalizar_texto_ia(str(daypart or ""))
    if not hora_es_valida(normalized_hour):
        return None
    try:
        hour_value, minute_value = (
            int(part) for part in normalized_hour.split(":")
        )
    except (TypeError, ValueError):
        return normalized_hour
    if normalized_daypart in {"tarde", "noche"} and 1 <= hour_value <= 11:
        return f"{hour_value + 12:02d}:{minute_value:02d}"
    return normalized_hour


def _agent_v2_apply_parallel_courts_policy_authority(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Conserva el grounding multi-cancha del turno actual y, sólo cuando el
    usuario responde una pregunta pendiente de ese flujo, restaura count=2
    antes del Goal Compiler.
    """
    # ContextAuthorization vacía las vistas operativas cuando Perception dice
    # ``no_pending``, pero conserva la memoria durable en ``stored_memory``.
    # Para decidir si una respuesta temporal autoriza ESTE pending específico,
    # trabajamos con una copia acotada; no publicamos memoria genérica.
    stored_pending = [
        dict(item)
        for item in (
            _agent_v2_stored_memory(world or {}).get("pending_decisions")
            or []
        )
        if isinstance(item, dict)
    ]
    continuity_world = dict(world or {})
    if stored_pending:
        continuity_world["pending_decisions"] = stored_pending
        continuity_world["open_questions"] = stored_pending

    clean = _agent_v2_apply_parallel_courts_policy_authority_base(
        perception, mensaje, world
    )

    # El turno actual siempre gana: no heredar alcance si lo expresó de nuevo
    # (ni si explícitamente suspendió el pending por una pregunta nueva).
    current_count = _agent_v2_requested_court_count(clean, mensaje)
    if (current_count and current_count >= 2) or clean.get("suspend_pending_this_turn"):
        return clean

    # Una cantidad explícita nueva (por ejemplo "una cancha") reemplaza el
    # alcance pendiente. Sólo heredamos cantidad cuando este turno no expresó
    # ninguna cantidad propia.
    if current_count is not None:
        return clean

    pending = _agent_v2_pending_parallel_courts_question(continuity_world)
    if not pending:
        return clean

    entities = dict(clean.get("entities") or {})
    has_temporal_answer = bool(
        entities.get("dia")
        or entities.get("dia_resuelto")
        or entities.get("hora")
        or entities.get("franja_dia")
    )
    if not has_temporal_answer:
        return clean

    frame_before = _agent_v2_semantic_frame(clean) or {}
    relation_before = _agent_v2_semantic_context_relation(frame_before) or {}
    pending_fields = {"dia_hora_reserva", "hora", "hora_aclaracion", "dia"}
    answers_pending = bool(
        clean.get("answers_pending_field") in pending_fields
        or relation_before.get("type") == "answers_pending"
        or relation_before.get("answers_pending_question") is True
    )

    # Perception puede entender correctamente el efecto (create_booking), el
    # día y la hora, pero etiquetar una respuesta temporal desnuda como
    # ``no_pending``. La pregunta stateful verificada sigue siendo autoridad:
    # si esperaba día/hora para varias canchas y el turno actual aporta tiempo
    # sin una cantidad de canchas nueva, la respuesta pertenece a ese pending.
    # Esto no habilita memoria genérica ni reutiliza reservas históricas.
    relation_type = str(relation_before.get("type") or "").strip().casefold()
    current_operations = {
        str(act.get("operation") or "").strip()
        for act in (frame_before.get("acts") or [])
        if isinstance(act, dict)
    }
    temporal_pending_reply = bool(
        not answers_pending
        and relation_type in {"", "unknown", "no_pending"}
        and current_operations
        and current_operations.issubset({"create_booking", "query_availability"})
        and not (clean.get("question_domains") or [])
        and (
            _agent_v2_has_original_semantic_time_evidence(
                frame_before,
                clean.get("temporal_mentions") or [],
            )
            or any(
                str(item.get("source") or "").strip().casefold()
                == "current_user_turn"
                and str(item.get("field") or "").strip().casefold()
                in {"temporal.day", "day", "dia"}
                and str(item.get("evidence") or "").strip()
                for act in (frame_before.get("acts") or [])
                if isinstance(act, dict)
                for item in (act.get("provenance") or [])
                if isinstance(item, dict)
            )
        )
    )
    if temporal_pending_reply:
        answers_pending = True
        print(
            "   🧷 [AgentV2 PARALLEL COURTS CONTEXT RECOVERY] "
            "respuesta temporal actual + pending multi-cancha → answers_pending"
        )
    if not answers_pending:
        return clean

    count = int(pending["requested_court_count"])
    entities["court_count"] = count
    entities["booking_shape"] = "multiple_separate"
    entities["duracion_horas"] = (
        entities.get("duracion_horas")
        or pending.get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )
    clean["entities"] = entities
    clean["booking_shape"] = "multiple_separate"
    clean["pending_relation"] = "answers_pending"
    clean["suspend_pending_this_turn"] = False
    # Campo legacy sin autoridad. ContextAuthorization decide la continuidad.
    clean["allow_historical_booking_context_this_turn"] = False

    raw_hour = normalizar_hora_detectada(entities.get("hora"))
    hour = _agent_v2_ground_explicit_daypart_hour(
        raw_hour,
        entities.get("franja_dia"),
    )
    if hour and hour != raw_hour:
        entities["hora"] = hour
        entities["horas"] = [hour]
        # Conservar la evidencia semántica actual, pero actualizar su valor
        # operativo. Las capas posteriores no pueden volver a degradarlo a 06h.
        mentions = []
        replaced = False
        for item in (clean.get("temporal_mentions") or []):
            if not isinstance(item, dict):
                continue
            patched = dict(item)
            if not replaced and str(patched.get("kind") or "").lower() == "time":
                patched["original_resolved_value"] = patched.get("resolved_value")
                patched["resolved_value"] = hour
                patched["grounding_source"] = "explicit_semantic_daypart"
                replaced = True
            mentions.append(patched)
        if mentions:
            clean["temporal_mentions"] = mentions
        clean["_deterministic_hour_grounding"] = {
            "kind": "explicit_semantic_daypart",
            "resolved_hour": hour,
            "original_hour": raw_hour,
            "source": "semantic_daypart",
        }
        print(
            "   🕒 [AgentV2 PARALLEL COURTS TIME GROUNDING] "
            f"IA={raw_hour} daypart={entities.get('franja_dia')} → negocio={hour}"
        )
    if not hora_es_valida(hour):
        print(
            "   🧷 [AgentV2 PARALLEL COURTS CONTINUITY] "
            f"mantengo count={count}; todavía falta hora exacta"
        )
        return clean

    entities["hora"] = hour
    entities["horas"] = [hour]
    batch = _agent_v2_build_multiple_separate_request(entities)
    if not (batch and batch.get("parallel_courts") and batch.get("duration_valid")):
        return clean

    clean["booking_multiple_request"] = batch
    clean["booking_multiple_choice"] = True
    clean["booking_time_choice"] = False
    clean["speech_act"] = "answer"
    clean["commitment"] = "confirms_action"
    clean["explicit_actions"] = list(dict.fromkeys([
        action for action in (clean.get("explicit_actions") or [])
        if action != "crear_reserva"
    ] + ["crear_reservas_multiples"]))

    question_id = pending.get("question_id")
    updated_acts = []
    found_create = False
    for raw_act in _agent_v2_authoritative_semantic_acts(clean):
        if not isinstance(raw_act, dict):
            continue
        act = dict(raw_act)
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        is_create_court = (
            act.get("operation") == "create_booking"
            and str(target.get("resource") or "").strip().lower() == "court"
        )
        if is_create_court:
            found_create = True
            target = dict(target)
            target.update({
                "source": "pending_option",
                "evidence": str(question_id or "parallel_courts_pending"),
                "question_id": question_id,
            })
            quantity = dict(act.get("quantity") or {})
            quantity.update({"count": count, "duration_hours": entities["duracion_horas"]})
            temporal = dict(act.get("temporal") or {})
            temporal.update({
                "day": entities.get("dia_resuelto") or entities.get("dia"),
                "start": hour,
                "times": [hour],
                "duration_hours": entities["duracion_horas"],
                "structure": "multiple_separate",
            })
            provenance = list(act.get("provenance") or [])
            if not any(
                isinstance(item, dict) and item.get("field") == "quantity.count"
                for item in provenance
            ):
                provenance.append({
                    "field": "quantity.count",
                    "source": "pending_option",
                    "evidence": str(question_id or "parallel_courts_pending"),
                    "question_id": question_id,
                    "scope_id": pending.get("scope_id"),
                    "option_id": None,
                    "reference_id": None,
                })
            if not any(
                isinstance(item, dict)
                and item.get("field") == "quantity.duration_hours"
                for item in provenance
            ):
                provenance.append({
                    "field": "quantity.duration_hours",
                    "source": "pending_option",
                    "evidence": str(question_id or "parallel_courts_pending"),
                    "question_id": question_id,
                    "scope_id": pending.get("scope_id"),
                    "option_id": None,
                    "reference_id": None,
                })
            act.update({
                "target": target,
                "quantity": quantity,
                "temporal": temporal,
                "provenance": provenance,
                "commitment": {"wants_write": True, "wants_information": False},
            })
        updated_acts.append(act)

    if not found_create:
        synthetic_provenance = [{
            "field": "quantity.count",
            "source": "pending_option",
            "evidence": str(question_id or "parallel_courts_pending"),
            "question_id": question_id,
            "scope_id": pending.get("scope_id"),
            "option_id": None,
            "reference_id": None,
        }, {
            "field": "quantity.duration_hours",
            "source": "pending_option",
            "evidence": str(question_id or "parallel_courts_pending"),
            "question_id": question_id,
            "scope_id": pending.get("scope_id"),
            "option_id": None,
            "reference_id": None,
        }]
        day_evidence = str(
            (
                clean.get("validated_temporal_resolution")
                if isinstance(clean.get("validated_temporal_resolution"), dict)
                else {}
            ).get("evidence")
            or next((
                item.get("evidence")
                for act in (frame_before.get("acts") or [])
                if isinstance(act, dict)
                for item in (act.get("provenance") or [])
                if isinstance(item, dict)
                and str(item.get("field") or "").strip().casefold()
                in {"temporal.day", "day", "dia"}
                and str(item.get("source") or "").strip().casefold()
                == "current_user_turn"
                and str(item.get("evidence") or "").strip()
            ), "")
            or ""
        ).strip()
        if (
            (entities.get("dia_resuelto") or entities.get("dia"))
            and day_evidence
        ):
            synthetic_provenance.append({
                "field": "temporal.day",
                "source": "current_user_turn",
                "evidence": day_evidence,
                "question_id": None,
                "scope_id": None,
                "option_id": None,
                "reference_id": None,
            })

        updated_acts.append({
            "act_id": "parallel_courts_pending_booking",
            "operation": "create_booking",
            "domain": "booking",
            "target": {
                "resource": "court",
                "reservation_id": None,
                "selection_policy": "any_available",
                "source": "pending_option",
                "question_id": question_id,
                "evidence": str(question_id or "parallel_courts_pending"),
            },
            "temporal": {
                "day": entities.get("dia_resuelto") or entities.get("dia"),
                "start": hour,
                "times": [hour],
                "duration_hours": entities["duracion_horas"],
                "structure": "multiple_separate",
            },
            "quantity": {"count": count, "duration_hours": entities["duracion_horas"]},
            "changes": [],
            "requested_facts": [],
            "commitment": {"wants_write": True, "wants_information": False},
            "selection": {},
            "provenance": synthetic_provenance,
        })

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    frame.update({
        "source": "system_pending_grounding",
        "schema_valid": True,
        "turn_type": "request",
        "intent": {"domain": "booking", "operation": "create_booking"},
        "temporal": {
            "day": entities.get("dia_resuelto") or entities.get("dia"),
            "start": hour,
            "times": [hour],
            "duration_hours": entities["duracion_horas"],
            "structure": "multiple_separate",
        },
        "commitment": {"wants_write": True, "wants_information": False},
        "context_relation": {
            "type": "answers_pending",
            "question_id": question_id,
            "references_previous_user_turn": False,
            "references_agent_offer": True,
            "answers_pending_question": True,
        },
        "acts": updated_acts,
    })
    clean["semantic_frame"] = _agent_v2_normalize_semantic_frame(
        {**clean, "semantic_frame": frame}, continuity_world, mensaje
    )
    clean["execution_contract"] = _agent_v2_build_execution_contract(
        clean,
        continuity_world,
    )

    # La continuidad acaba de quedar probada contra question_id + scope_id.
    # Publicarla también en el World original evita que la normalización final
    # vuelva a ver pending=[] y convierta el nuevo batch en una reprogramación
    # de una reserva individual histórica.
    verified_context = (
        clean.get("execution_contract")
        if isinstance(clean.get("execution_contract"), dict)
        else {}
    ).get("authorized_context") or {}
    if verified_context.get("authorized"):
        _agent_v2_publish_context_authorization(
            world,
            verified_context,
        )

    print(
        "   🏟️🏟️ [AgentV2 PARALLEL COURTS CONTINUITY] "
        f"pending count={count} hora={hour} → booking_multiple_request restaurado"
    )
    return clean


def _agent_v2_parallel_policy_booking_bridge_candidate(
    world: Dict,
    perception: Dict,
    observations: List[Dict],
) -> Optional[Dict[str, Any]]:
    """Convierte una policy multi-cancha comprobada en una CTA stateful."""
    policy_obs = _agent_v2_policy_contract_observation(observations)
    contract = (((policy_obs or {}).get("data") or {}).get("policy_fact_contract") or {})
    if (
        contract.get("type") != "parallel_courts_policy"
        or contract.get("requires_human_attention")
        or not contract.get("can_reserve_count")
    ):
        return None
    try:
        count = int(float(contract.get("requested_court_count") or 0))
    except (TypeError, ValueError):
        return None
    if count < 2:
        return None
    return {
        "action": "ask_booking_datetime",
        "question": {
            "field": "dia_hora_reserva",
            "options": [],
            "booking_choice": True,
            "requested_court_count": count,
            "court_count": count,
            "parallel_courts": True,
            "booking_shape": "multiple_separate",
            "duracion_horas": DEFAULT_TURN_DURATION_HOURS,
            "requested_hours": [],
            "goal_context": ["buscar_turno", "crear_reservas_multiples"],
            "source": "next_best_action_current_turn",
            "source_message": world.get("message") or "",
            "replace_booking_questions": True,
        },
        "reason_code": "parallel_courts_policy_booking_bridge",
        "reason": "capacidad multi-cancha confirmada; conservar cantidad y pedir día+hora",
    }



def _agent_v2_quote_offer_contract_from_observations(
    observations: List[Dict],
) -> Dict[str, Any]:
    """Construye un bundle sólo con cotizaciones verificadas del turno actual."""
    resources = []
    court = {}
    quincho = {}
    evidence_ids = []
    for obs in observations or []:
        if not isinstance(obs, dict) or obs.get("tool") != "consultar_precio" or not obs.get("ok"):
            continue
        data = obs.get("data") or {}
        obs_id = str(obs.get("evidence_id") or obs.get("observation_id") or "").strip()
        if obs_id:
            evidence_ids.append(obs_id)
        if data.get("incluir_cancha"):
            duration = normalizar_duracion_horas(data.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS)
            court = {
                "duration_hours": duration,
                "price": _monto_a_int(data.get("precio_cancha")),
            }
            if "court" not in resources:
                resources.append("court")
        if data.get("incluir_quincho"):
            qduration = normalizar_duracion_horas(data.get("quincho_duracion_horas") or 1.0, 1.0)
            quincho = {
                "name": data.get("quincho"),
                "duration_hours": qduration,
                "price": _monto_a_int(data.get("precio_quincho")),
                "start_policy": "with_court",
            }
            if "quincho" not in resources:
                resources.append("quincho")
    if not resources:
        return {}
    return {
        "version": 1,
        "source": "verified_price_quote",
        "requested_resources": resources,
        "court": court,
        "quincho": quincho,
        "evidence_ids": list(dict.fromkeys(evidence_ids)),
    }

def _agent_v2_price_quote_booking_bridge_candidate(
    world: Dict,
    perception: Dict,
    observations: List[Dict],
) -> Optional[Dict[str, Any]]:
    """
    Continuidad comercial stateful después de una cotización de cancha.

    REGLA CENTRAL:
        una FAQ de precio puede SUSPENDER una pregunta de reserva, pero no debe
        reemplazarla por una pregunta genérica sin provenance.

    Si antes de la cotización existía una pregunta booking_choice verificable
    (por ejemplo field='hora' con opciones reales provenientes del calendario),
    se retoma ESA MISMA pregunta preservando question_id, scope_id, opciones,
    día y goal_context.

    Sólo si no existe un pending booking verificable se crea una CTA nueva.
    Nunca se inventa día/hora ni se reactiva memoria de otro scope.
    """

    quote_obs = next((
        obs
        for obs in reversed(observations or [])
        if (
            isinstance(obs, dict)
            and obs.get("tool") == "consultar_precio"
            and obs.get("ok")
            and (obs.get("data") or {}).get("incluir_cancha")
        )
    ), None)

    if not quote_obs:
        return None

    quote_data = quote_obs.get("data") or {}

    # RESOURCE-SCOPE AUTHORITY:
    # la consulta de precio puede ser "cancha de tenis", "padel", "fútbol", etc.
    # Perception ya resolvió semánticamente ese lenguaje contra config.COURTS.
    # Ese scope debe viajar con la oferta/pending; de lo contrario, una respuesta
    # posterior sólo con hora volvería a abrir todas las canchas.
    current_resource_types = _agent_v2_resource_type_constraints(
        perception,
        world,
    )
    current_resource_type = (
        current_resource_types[0]
        if len(current_resource_types) == 1
        else None
    )

    offer_contract = _agent_v2_quote_offer_contract_from_observations(observations)

    if offer_contract and current_resource_types:
        scoped_court_offer = dict(
            offer_contract.get("court")
            if isinstance(offer_contract.get("court"), dict)
            else {}
        )
        scoped_court_offer["resource_types"] = list(current_resource_types)
        scoped_court_offer["resource_type"] = current_resource_type
        offer_contract["court"] = scoped_court_offer

    if offer_contract:
        print(
            "   🧾 [AgentV2 PRICE OFFER CONTRACT] "
            f"resources={offer_contract.get('requested_resources') or []} "
            f"court={offer_contract.get('court') or {}} "
            f"quincho={offer_contract.get('quincho') or {}} "
            f"resource_types={current_resource_types}"
        )

    # =========================================================
    # 1. DURACIÓN COTIZADA
    # =========================================================

    quoted_duration = normalizar_duracion_horas(
        quote_data.get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )

    allowed_durations = set()

    for item in (ALLOWED_TURN_DURATIONS or []):
        try:
            allowed_durations.add(
                round(float(item), 4)
            )
        except (TypeError, ValueError):
            continue

    try:
        normalized_quoted_duration = round(
            float(quoted_duration),
            4,
        )
    except (TypeError, ValueError):
        return None

    if (
        allowed_durations
        and normalized_quoted_duration not in allowed_durations
    ):
        return None

    # =========================================================
    # 2. RESERVA REAL EXISTENTE
    # =========================================================

    real_reservations = (
        (world.get("facts") or {}).get("reservas_reales")
        or []
    )

    # V57 — UNA RESERVA EXISTENTE NO ANULA LA MEMORIA DE UNA COTIZACIÓN NUEVA.
    #
    # Antes se hacía `if real_reservations: return None`. Eso provocaba exactamente
    # este fallo conversacional:
    #   1) el usuario ya tenía una reserva/hold anterior;
    #   2) preguntaba precio de cancha + quincho;
    #   3) se construía PRICE OFFER CONTRACT;
    #   4) pero NO se persistía ninguna CTA/pending stateful;
    #   5) el siguiente "sí, quiero para hoy..." nacía como `no_pending` y perdía
    #      requested_resources=['court', 'quincho'].
    #
    # Una cotización nueva abre un scope comercial independiente. La existencia de
    # reservas reales sólo impide HEREDARLAS sin referencia explícita; no puede
    # impedir recordar la oferta actual.
    has_real_reservations = bool(real_reservations)

    # =========================================================
    # 3. FAQ INTERMEDIA:
    #    RECUPERAR LA PREGUNTA DESDE STORED MEMORY
    # =========================================================
    #
    # world.open_questions puede estar vacío intencionalmente.
    #
    # Eso significa:
    #   memoria NO autorizada para el turno actual
    #
    # NO significa:
    #   memoria eliminada.
    #
    # Después de responder la FAQ podemos reactivar la misma
    # pregunta de booking, conservando identidad y scope.
    # =========================================================

    if _agent_v2_pending_is_suspended_this_turn(
        perception or {}
    ):

        stored = _agent_v2_stored_memory(
            world or {}
        )

        stored_pending = [
            dict(q)
            for q in (
                stored.get("pending_decisions")
                or []
            )
            if isinstance(q, dict)
        ]

        stored_availability = dict(
            stored.get("availability_context")
            or {}
        )

        expected_owner = str(
            ((world or {}).get("facts") or {}).get(
                "memory_owner"
            )
            or ""
        ).strip()

        availability_scope = str(
            stored_availability.get("scope_id")
            or ""
        ).strip()

        now = datetime.datetime.now(
            TIMEZONE
        )

        field_priority = {
            "hora": 0,
            "hora_aclaracion": 1,
            "cancha": 2,
            "duracion_horas": 3,
            "dia": 4,
            "dia_hora_reserva": 5,
        }

        candidates = []

        for index, question in enumerate(
            stored_pending
        ):

            field = str(
                question.get("field")
                or ""
            ).strip()

            if field not in field_priority:
                continue

            goal_context = {
                str(goal or "").strip()
                for goal in (
                    question.get("goal_context")
                    or []
                )
                if str(goal or "").strip()
            }

            booking_question = bool(
                question.get("booking_choice")
                or goal_context.intersection({
                    "buscar_turno",
                    "crear_reserva",
                    "crear_reservas_multiples",
                })
            )

            if not booking_question:
                continue

            question_id = str(
                question.get("question_id")
                or ""
            ).strip()

            scope_id = str(
                question.get("scope_id")
                or ""
            ).strip()

            # Sin identidad estructural no existe memoria
            # contextual autorizable.
            if not question_id or not scope_id:
                continue

            owner = str(
                question.get("_memory_owner")
                or ""
            ).strip()

            if (
                expected_owner
                and owner
                and owner != expected_owner
            ):
                continue

            expires_at = _parse_context_timestamp(
                question.get("expires_at")
            )

            if (
                expires_at
                and now > expires_at
            ):
                continue

            # Una disponibilidad de otro scope nunca puede
            # reactivar esta pregunta.
            if (
                availability_scope
                and scope_id != availability_scope
            ):
                continue

            # Para hora necesitamos opciones REALES del calendario.
            if field in {
                "hora",
                "hora_aclaracion",
            }:

                offered_hours = _agent_v2_dedupe_hours(
                    question.get("options")
                    or []
                )

                if not offered_hours:
                    continue

            candidates.append((
                field_priority[field],
                -index,
                question,
            ))

        if candidates:

            candidates.sort(
                key=lambda item: (
                    item[0],
                    item[1],
                )
            )

            pending = dict(
                candidates[0][2]
            )

            # Reactivamos la pregunta.
            # Conservamos:
            #
            # question_id
            # scope_id
            # options
            # dia
            # goal_context
            #
            # pero deja de ser memoria pasiva.
            pending.pop(
                "context_only",
                None,
            )

            pending["source"] = (
                "next_best_action_current_turn"
            )

            # Si availability pertenece exactamente al mismo scope,
            # puede completar el día estructurado.
            if (
                not pending.get("dia")
                and availability_scope
                and str(
                    pending.get("scope_id")
                    or ""
                ) == availability_scope
            ):
                pending["dia"] = (
                    stored_availability.get("dia")
                    or stored_availability.get(
                        "dia_resuelto"
                    )
                )

            # La duración de la cotización puede completar la
            # pregunta si todavía no estaba definida.
            if pending.get(
                "duracion_horas"
            ) in (
                None,
                "",
            ):
                pending["duracion_horas"] = (
                    quoted_duration
                )

            # La cotización CURRENT-TURN manda sobre un pending anterior que
            # podía ser genérico. Ejemplo real:
            #   disponibilidad general -> pregunta por Tenis + precio -> "sí, 20hs".
            # Reactivar la hora SIN este scope permitiría autoasignar Fútbol.
            if current_resource_types:
                pending["resource_types"] = list(current_resource_types)
                pending["resource_type"] = current_resource_type
                print(
                    "   🏷️ [AgentV2 PRICE RESOURCE SCOPE] "
                    f"pending={pending.get('question_id')} "
                    f"→ {current_resource_types}"
                )

            if offer_contract:
                pending["offer_contract"] = dict(offer_contract)
                pending["requested_resources"] = list(
                    offer_contract.get("requested_resources") or []
                )

            print(
                "   🔗 [AgentV2 PRICE NBA] "
                f"retomo pending verificable "
                f"field={pending.get('field')} "
                f"question_id={pending.get('question_id')} "
                f"scope_id={pending.get('scope_id')} "
                f"options={len(pending.get('options') or [])}"
            )

            return {
                "action": "resume_pending",

                "question": pending,

                "reason_code": (
                    "price_quote_resume_verified_booking_pending"
                ),

                "reason": (
                    "precio resuelto; retomar la misma decisión "
                    "de reserva verificable que estaba abierta "
                    "antes de la FAQ"
                ),
            }

    # =========================================================
    # 4. SIN PENDING VERIFICABLE
    # =========================================================
    #
    # Acá sí usamos SOLAMENTE datos del turno actual.
    # =========================================================

    entities = (
        (perception or {}).get("entities")
        or {}
    )

    known_day = (
        entities.get("dia_resuelto")
        or entities.get("dia")
    )

    known_hour = normalizar_hora_detectada(
        entities.get("hora")
    )

    if (
        known_day
        and hora_es_valida(
            known_hour
        )
    ):
        return None

    if known_day:
        field = "hora"

    elif hora_es_valida(
        known_hour
    ):
        field = "dia"

    else:
        field = "dia_hora_reserva"

    # La oferta obtiene SIEMPRE un scope propio cuando no estamos retomando un
    # pending verificable. Esto evita que una reserva histórica y la cotización
    # recién emitida compartan identidad conversacional por accidente.
    offer_scope_id = f"price_offer_{uuid.uuid4().hex[:16]}"

    if has_real_reservations:
        print(
            "   🧾 [AgentV2 PRICE OFFER MEMORY] "
            f"reservas_existentes={len(real_reservations)} → "
            f"oferta nueva persistida en scope={offer_scope_id}"
        )

    return {
        "action": "ask_booking_datetime",

        "question": {
            "field": field,

            "scope_id": offer_scope_id,

            "options": [],

            "booking_choice": True,

            "dia": known_day,

            "hora": (
                known_hour
                if hora_es_valida(
                    known_hour
                )
                else None
            ),

            "duracion_horas": (
                quoted_duration
            ),

            "resource_types": list(current_resource_types),
            "resource_type": current_resource_type,

            "requested_resources": list(
                (offer_contract or {}).get("requested_resources") or []
            ),

            "offer_contract": dict(offer_contract or {}),

            "booking_shape": (
                "contiguous_block"
                if quoted_duration
                else None
            ),

            "goal_context": [
                "buscar_turno",
                "crear_reserva",
            ],

            "source": (
                "next_best_action_current_turn"
            ),

            # Si existe otra reserva activa, no borramos preguntas financieras o
            # contextos de esa reserva. La nueva oferta vive en su propio scope.
            "replace_booking_questions": (not has_real_reservations),
        },

        "reason_code": (
            "price_quote_booking_bridge"
        ),

        "reason": (
            "cotización resuelta sin pending booking verificable; "
            "pedir únicamente el dato temporal faltante"
        ),
    }

def aplicar_next_best_action_agent_v2(
    telefono: str,
    nba: Dict[str, Any],
) -> None:
    """
    Persiste la Next Best Action.

    `resume_pending` significa REACTIVAR la MISMA pregunta,
    no copiarla como memoria pasiva.

    Conserva:
        question_id
        scope_id
        options
        contexto estructurado

    Y elimina:
        context_only

    Esto permite:

        disponibilidad
            ↓
        FAQ precio
            ↓
        misma pregunta de horario
            ↓
        usuario elige hora
            ↓
        reserva
    """

    action = str(
        (nba or {}).get("action")
        or "none"
    )

    agent_v2_reduce(
        telefono,
        {
            "type": "NEXT_BEST_ACTION_SET",
            "payload": nba or {},
        },
    )

    question = (
        (nba or {}).get("question")
    )

    if not (
        action != "none"
        and isinstance(
            question,
            dict,
        )
        and question.get("field")
    ):
        return

    payload = dict(
        question
    )

    # =========================================================
    # RESUME PENDING
    # =========================================================

    if action == "resume_pending":

        # La pregunta vuelve a estar activa.
        payload.pop(
            "context_only",
            None,
        )

        payload["created_at"] = (
            datetime.datetime.now(
                TIMEZONE
            ).isoformat()
        )

        # IMPORTANTE:
        # NO modificar expires_at.
        #
        # Si una oferta tiene TTL operacional explícito,
        # reanudar la conversación no debe extenderlo.

        print(
            "   🔗 [AgentV2 RESUME PENDING] "
            f"field={payload.get('field')} "
            f"question_id={payload.get('question_id')} "
            f"scope_id={payload.get('scope_id')} "
            f"options={len(payload.get('options') or [])}"
        )

    # =========================================================
    # CTA NUEVA
    # =========================================================
    #
    # Sólo una CTA realmente nueva puede reemplazar preguntas.
    #
    # resume_pending nunca pasa por acá.
    # =========================================================

    if (
        action in {
            "ask_booking_datetime",
            "confirm_exact_slot",
        }
        and payload.get(
            "replace_booking_questions"
        )
    ):

        for old_field in (
            "hora",
            "hora_aclaracion",
            "cancha",
            "dia",
            "dia_hora_reserva",
            "duracion_horas",
            "reserva",
            "reserva_especifica",
            "comprobante",
            "released_booking_rebook",
        ):

            agent_v2_reduce(
                telefono,
                {
                    "type": "CLEAR_OPEN_QUESTION",

                    "payload": {
                        "field": old_field,
                    },
                },
            )

    payload["source"] = (
        "next_best_action_current_turn"
    )

    payload["nba_action"] = (
        action
    )

    agent_v2_reduce(
        telefono,
        {
            "type": "SET_OPEN_QUESTION",
            "payload": payload,
        },
    )

def _agent_v2_reconcile_booking_phase_semantics(
    frame: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str = "",
    temporal_mentions: Any = None,
) -> Dict[str, Any]:
    """
    Vincula una hora ACTUAL del usuario con una opción REAL de una pregunta de
    booking previamente ofrecida.

    NO interpreta lenguaje mediante regex.

    Trabaja únicamente con:
      - temporal.start interpretado por Perception;
      - evidencia temporal current_user_turn;
      - pending estructurado persistido;
      - question_id;
      - scope_id;
      - option_id.

    MEMORY EXISTS != MEMORY IS AUTHORIZED.
    """

    clean = (
        _agent_v2_reconcile_existing_reservation_correction(
            frame,
            world,
            mensaje,
            temporal_mentions,
        )
    )

    acts = [
        dict(act)
        for act in (
            clean.get("acts")
            or []
        )
        if isinstance(
            act,
            dict,
        )
    ]

    if not acts:
        return clean

    # Una reprogramación REAL no pertenece al pending
    # de una reserva nueva.
    if any(
        str(
            act.get("operation")
            or ""
        )
        == "reschedule_booking"
        for act in acts
    ):
        return clean

    # =========================================================
    # 1. STORED MEMORY
    # =========================================================
    #
    # El pending puede estar oculto del World operativo por una
    # FAQ intermedia, pero sigue disponible para VERIFICACIÓN.
    # =========================================================

    stored = _agent_v2_stored_memory(
        world or {}
    )

    expected_owner = str(
        ((world or {}).get("facts") or {}).get(
            "memory_owner"
        )
        or ""
    ).strip()

    now = datetime.datetime.now(
        TIMEZONE
    )

    pending_raw = []

    for raw_question in (
        stored.get("pending_decisions")
        or []
    ):

        if not isinstance(
            raw_question,
            dict,
        ):
            continue

        question = dict(
            raw_question
        )

        if question.get("field") not in {
            "hora",
            "hora_aclaracion",
        }:
            continue

        if not question.get(
            "booking_choice"
        ):
            continue

        question_id = str(
            question.get("question_id")
            or ""
        ).strip()

        scope_id = str(
            question.get("scope_id")
            or ""
        ).strip()

        # Sin identidad no existe memoria autorizable.
        if not question_id or not scope_id:
            continue

        owner = str(
            question.get("_memory_owner")
            or ""
        ).strip()

        if (
            expected_owner
            and owner
            and owner != expected_owner
        ):
            continue

        expires_at = _parse_context_timestamp(
            question.get("expires_at")
        )

        if (
            expires_at
            and now > expires_at
        ):
            continue

        options = _agent_v2_dedupe_hours(
            question.get("options")
            or []
        )

        # Una selección pendiente por hora sin opciones no puede
        # autorizar ninguna hora.
        if not options:
            continue

        pending_raw.append(
            question
        )

    if not pending_raw:
        return clean

    # =========================================================
    # 2. EVIDENCIA DEL TURNO ACTUAL
    # =========================================================

    if not _agent_v2_has_original_semantic_time_evidence(
        clean,
        temporal_mentions,
    ):
        return clean

    snapshot_world = {
        **dict(
            world or {}
        ),

        "pending_decisions": (
            pending_raw
        ),
    }

    pending_snapshot = (
        _agent_v2_pending_semantic_snapshot(
            snapshot_world
        )
    )

    # =========================================================
    # 3. MATCH ACTUAL → PENDING OPTION
    # =========================================================

    resolved = None
    resolved_act_index = None

    for act_index, act in enumerate(
        acts
    ):

        if str(
            act.get("operation")
            or ""
        ) != "create_booking":
            continue

        temporal = (
            act.get("temporal")
            if isinstance(
                act.get("temporal"),
                dict,
            )
            else {}
        )

        selected_hour = (
            normalizar_hora_detectada(
                temporal.get("start")
            )
        )

        if not hora_es_valida(
            selected_hour
        ):
            continue

        matches = []

        for question in (
            pending_raw
        ):

            options = (
                _agent_v2_dedupe_hours(
                    question.get("options")
                    or []
                )
            )

            resolved_hour = (
                _agent_v2_resolve_semantic_hour_against_pending_options(
                    selected_hour,
                    options,
                )
            )

            if resolved_hour:

                matches.append((
                    question,
                    resolved_hour,
                ))

        # Una sola pregunta debe explicar la selección.
        if len(matches) == 1:

            resolved = (
                matches[0]
            )

            resolved_act_index = (
                act_index
            )

            break

    if (
        not resolved
        or resolved_act_index is None
    ):
        return clean

    question, selected_hour = (
        resolved
    )

    question_id = str(
        question.get("question_id")
        or ""
    ).strip()

    scope_id = str(
        question.get("scope_id")
        or ""
    ).strip()

    if not question_id or not scope_id:
        return clean

    # =========================================================
    # 4. OPTION ID
    # =========================================================

    snapshot_question = next(
        (
            q
            for q in pending_snapshot
            if str(
                q.get("question_id")
                or ""
            )
            == question_id
        ),
        None,
    )

    selected_option = next(
        (
            option
            for option in (
                (
                    snapshot_question
                    or {}
                ).get("options")
                or []
            )
            if normalizar_hora_detectada(
                option.get("value")
            )
            == selected_hour
        ),
        None,
    )

    if (
        not snapshot_question
        or not selected_option
    ):
        return clean

    option_id = str(
        selected_option.get("option_id")
        or ""
    ).strip()

    if not option_id:
        return clean

    act = dict(
        acts[
            resolved_act_index
        ]
    )

    temporal = dict(
        act.get("temporal")
        or {}
    )

    original_selected_hour = (
        normalizar_hora_detectada(
            temporal.get("start")
        )
    )

    if (
        original_selected_hour
        != selected_hour
    ):

        print(
            "   🧭 [AgentV2 PENDING HOUR CONTEXT] "
            f"{original_selected_hour} "
            f"→ {selected_hour} "
            "por única opción equivalente ofrecida"
        )

    # =========================================================
    # 5. DÍA DEL MISMO SCOPE
    # =========================================================

    question_day = (
        question.get("dia")
        or (
            (
                question.get("context")
                or {}
            ).get("dia")
            if isinstance(
                question.get("context"),
                dict,
            )
            else None
        )
    )

    stored_availability = dict(
        stored.get("availability_context")
        or {}
    )

    if (
        not question_day
        and str(
            stored_availability.get("scope_id")
            or ""
        ).strip()
        == scope_id
    ):

        question_day = (
            stored_availability.get("dia")
            or stored_availability.get(
                "dia_resuelto"
            )
        )

    current_day = (
        temporal.get("day")
    )

    # Un temporal.day existente NO significa necesariamente
    # que el usuario lo dijo AHORA.
    current_day_is_explicit = any(
        isinstance(item, dict)
        and str(
            item.get("source")
            or ""
        ).strip().casefold()
        == "current_user_turn"
        and str(
            item.get("field")
            or ""
        ).strip().casefold()
        in {
            "temporal.day",
            "day",
            "dia",
        }
        and str(
            item.get("evidence")
            or ""
        ).strip()
        for item in (
            act.get("provenance")
            or []
        )
    )

    def _same_resolved_day(
        left: Any,
        right: Any,
    ) -> bool:

        if not left or not right:
            return True

        try:
            left_resolved = resolver_fecha(
                str(left)
            )
        except Exception:
            left_resolved = str(
                left
            )

        try:
            right_resolved = resolver_fecha(
                str(right)
            )
        except Exception:
            right_resolved = str(
                right
            )

        left_date = _parse_fecha_row(
            left_resolved
        )

        right_date = _parse_fecha_row(
            right_resolved
        )

        if (
            left_date is not None
            and right_date is not None
        ):
            return (
                left_date
                == right_date
            )

        return (
            str(left_resolved).strip()
            == str(right_resolved).strip()
        )

    # Si el usuario ACTUALMENTE dijo otro día, no podemos usar
    # las opciones horarias del scope anterior.
    if (
        current_day_is_explicit
        and current_day
        and question_day
        and not _same_resolved_day(
            current_day,
            question_day,
        )
    ):

        print(
            "   🚫 [AgentV2 BOOKING PHASE] "
            f"hora={selected_hour} coincide con pending, "
            f"pero día actual={current_day!r} "
            f"!= día scope={question_day!r}; "
            "no autorizo memoria"
        )

        return clean

    # =========================================================
    # 6. HORA
    # =========================================================

    temporal["start"] = (
        selected_hour
    )

    if (
        str(
            temporal.get("structure")
            or ""
        )
        .strip()
        .casefold()
        == "contiguous_block"
        and (
            temporal.get("end")
            or temporal.get(
                "duration_hours"
            )
        )
    ):

        temporal["times"] = (
            _agent_v2_dedupe_hours(
                [
                    selected_hour,
                    *(
                        temporal.get("times")
                        or []
                    ),
                ]
            )
        )

    else:

        temporal["times"] = [
            selected_hour
        ]

    provenance = [
        dict(item)
        for item in (
            act.get("provenance")
            or []
        )
        if isinstance(
            item,
            dict,
        )
    ]

    # Quitamos únicamente un binding pending viejo de start.
    provenance = [
        item
        for item in provenance
        if not (
            str(
                item.get("field")
                or ""
            ).strip().lower()
            == "temporal.start"
            and item.get("source")
            == "pending_option"
        )
    ]

    provenance.append({
        "field": "temporal.start",

        "source": "pending_option",

        "evidence": (
            f"{selected_hour} pertenece a opciones verificadas "
            f"de question_id={question_id}"
        ),

        "question_id": (
            question_id
        ),

        "option_id": (
            option_id
        ),

        "scope_id": (
            scope_id
        ),

        "reference_id": None,
    })

    # =========================================================
    # 7. HERENCIA DEL DÍA AUTORIZADA
    # =========================================================

    if (
        not current_day_is_explicit
        and question_day
    ):

        temporal["day"] = (
            question_day
        )

        provenance = [
            item
            for item in provenance
            if not (
                str(
                    item.get("field")
                    or ""
                ).strip().casefold()
                in {
                    "temporal.day",
                    "day",
                    "dia",
                }
                and item.get("source")
                == "pending_option"
            )
        ]

        provenance.append({
            "field": "temporal.day",

            "source": "pending_option",

            "evidence": (
                "día heredado exclusivamente del scope "
                f"de question_id={question_id}"
            ),

            "question_id": (
                question_id
            ),

            "option_id": (
                option_id
            ),

            "scope_id": (
                scope_id
            ),

            "reference_id": None,
        })

    # =========================================================
    # 8. DURACIÓN DEL MISMO SCOPE
    # =========================================================

    question_duration = (
        question.get("duracion_horas")
    )

    current_duration_is_explicit = any(
        isinstance(item, dict)
        and str(
            item.get("source")
            or ""
        ).strip().casefold()
        == "current_user_turn"
        and str(
            item.get("field")
            or ""
        ).strip().casefold()
        in {
            "temporal.duration_hours",
            "quantity.duration_hours",
            "duration_hours",
            "duracion_horas",
        }
        and str(
            item.get("evidence")
            or ""
        ).strip()
        for item in provenance
    )

    if (
        not current_duration_is_explicit
        and question_duration
        not in (
            None,
            "",
        )
    ):

        temporal["duration_hours"] = (
            question_duration
        )

        provenance = [
            item
            for item in provenance
            if not (
                str(
                    item.get("field")
                    or ""
                ).strip().casefold()
                in {
                    "temporal.duration_hours",
                    "quantity.duration_hours",
                    "duration_hours",
                    "duracion_horas",
                }
                and item.get("source")
                == "pending_option"
            )
        ]

        provenance.append({
            "field": "temporal.duration_hours",

            "source": "pending_option",

            "evidence": (
                "duración heredada del mismo scope "
                f"question_id={question_id}"
            ),

            "question_id": (
                question_id
            ),

            "option_id": (
                option_id
            ),

            "scope_id": (
                scope_id
            ),

            "reference_id": None,
        })

    act["temporal"] = (
        temporal
    )

    # =========================================================
    # 9. BINDING EXACTO
    # =========================================================

    act["selection"] = {
        "question_id": (
            question_id
        ),

        "option_id": (
            option_id
        ),
    }

    target = dict(
        act.get("target")
        or {}
    )

    # =========================================================
    # 9A. RESOURCE TYPE DEL MISMO SCOPE
    # =========================================================
    # Elegir una hora de un pending scoped a Tenis/Pádel/Fútbol NO autoriza
    # volver a "todas las canchas". Python sólo transporta la restricción ya
    # interpretada por IA y persistida en la pregunta verificada.
    question_resource_types = _canonical_configured_court_types(
        question.get("resource_types")
        or (
            [question.get("resource_type")]
            if question.get("resource_type")
            else []
        )
    )
    target_resource_types = _canonical_configured_court_types(
        target.get("resource_types")
        or (
            [target.get("resource_type")]
            if target.get("resource_type")
            else []
        )
    )

    if question_resource_types and target_resource_types:
        question_keys = {
            normalizar_texto_ia(value)
            for value in question_resource_types
        }
        effective_resource_types = [
            value
            for value in target_resource_types
            if normalizar_texto_ia(value) in question_keys
        ]
        if not effective_resource_types:
            print(
                "   🚫 [AgentV2 RESOURCE SCOPE] "
                f"turn={target_resource_types} contradice "
                f"pending={question_resource_types} "
                f"question_id={question_id} → no autorizo binding"
            )
            return clean
    elif question_resource_types:
        effective_resource_types = list(question_resource_types)
    else:
        effective_resource_types = list(target_resource_types)

    if effective_resource_types:
        target["resource_types"] = list(effective_resource_types)
        target["resource_type"] = (
            effective_resource_types[0]
            if len(effective_resource_types) == 1
            else None
        )

        # Provenance auditable sólo cuando el dato vino del pending.
        if question_resource_types and not target_resource_types:
            provenance.append({
                "field": "target.resource_type",
                "source": "pending_option",
                "evidence": (
                    "tipo de cancha heredado del mismo scope "
                    f"question_id={question_id}: {effective_resource_types}"
                ),
                "question_id": question_id,
                "option_id": option_id,
                "scope_id": scope_id,
                "reference_id": None,
            })

        print(
            "   🏷️ [AgentV2 RESOURCE SCOPE] "
            f"question_id={question_id} "
            f"→ {effective_resource_types}"
        )

    if (
        target.get("selection_policy")
        == "any_available"
        and not target.get("source")
        and not target.get("evidence")
    ):
        # Elegir hora != elegir cualquier cancha.
        # La autoasignación pertenece a Policy.
        target["selection_policy"] = (
            None
        )

    target["question_id"] = (
        question_id
    )

    target["option_id"] = (
        option_id
    )

    act["target"] = (
        target
    )

    act["provenance"] = (
        provenance
    )

    acts[
        resolved_act_index
    ] = act

    clean["acts"] = (
        acts
    )

    clean["temporal"] = {
        **dict(
            clean.get("temporal")
            or {}
        ),

        "day": temporal.get(
            "day"
        ),

        "start": (
            selected_hour
        ),

        "duration_hours": (
            temporal.get(
                "duration_hours"
            )
        ),
    }

    # =========================================================
    # 10. RELACIÓN CONTEXTUAL VERIFICADA
    # =========================================================

    clean["context_relation"] = {
        "type": "answers_pending",

        "question_id": (
            question_id
        ),

        "references_previous_user_turn": False,

        "references_agent_offer": True,

        "answers_pending_question": True,
    }

    clean["phase_resolution"] = {
        "phase": (
            "selecting_booking_time"
        ),

        "field": (
            question.get("field")
        ),

        "question_id": (
            question_id
        ),

        "option_id": (
            option_id
        ),

        "scope_id": (
            scope_id
        ),

        "value": (
            selected_hour
        ),

        "day": temporal.get(
            "day"
        ),

        "resource_types": list(
            target.get("resource_types")
            or []
        ),

        "resource_type": target.get(
            "resource_type"
        ),

        "source": (
            "verified_pending_option"
        ),
    }

    print(
        "   🔗 [AgentV2 BOOKING PHASE] "
        f"{selected_hour} responde "
        f"{question.get('field')} "
        f"question_id={question_id} "
        f"scope_id={scope_id} "
        f"option_id={option_id} "
        f"day={temporal.get('day')}"
    )

    return clean

def _agent_v2_validate_semantic_references(
    acts: List[Dict[str, Any]],
    relation: Dict[str, Any],
    world: Dict,
) -> bool:
    """
    Valida referencias a pending sin otorgarles autoridad por existir.

    La pregunta puede estar suspendida/oculta del World operativo durante
    una FAQ intermedia.

    STORED MEMORY se usa solamente para verificar el question_id exacto.

    NO existe fallback:
        "hay una sola pregunta, entonces debe ser esa".

    La autorización real sigue perteneciendo a
    _agent_v2_context_authorization().
    """

    if str(
        (relation or {}).get("type")
        or ""
    ) != "answers_pending":
        return True

    question_id = str(
        (relation or {}).get("question_id")
        or ""
    ).strip()

    if not question_id:
        return False

    stored = _agent_v2_stored_memory(
        world or {}
    )

    pending_raw = [
        dict(q)
        for q in (
            stored.get("pending_decisions")
            or []
        )
        if isinstance(
            q,
            dict,
        )
    ]

    snapshot_world = {
        **dict(
            world or {}
        ),

        "pending_decisions": (
            pending_raw
        ),
    }

    pending = (
        _agent_v2_pending_semantic_snapshot(
            snapshot_world
        )
    )

    question = next(
        (
            q
            for q in pending
            if str(
                q.get("question_id")
                or ""
            )
            == question_id
        ),
        None,
    )

    if not question:
        return False

    valid_options = {
        str(
            option.get("option_id")
            or ""
        ): option.get("value")

        for option in (
            question.get("options")
            or []
        )

        if (
            isinstance(option, dict)
            and str(
                option.get("option_id")
                or ""
            ).strip()
        )
    }

    for act in (
        acts or []
    ):

        if not isinstance(
            act,
            dict,
        ):
            return False

        selection = (
            act.get("selection")
            if isinstance(
                act.get("selection"),
                dict,
            )
            else {}
        )

        selected_question_id = str(
            selection.get("question_id")
            or (
                (
                    act.get("target")
                    or {}
                ).get("question_id")
                if isinstance(
                    act.get("target"),
                    dict,
                )
                else ""
            )
            or ""
        ).strip()

        option_id = str(
            selection.get("option_id")
            or (
                (
                    act.get("target")
                    or {}
                ).get("option_id")
                if isinstance(
                    act.get("target"),
                    dict,
                )
                else ""
            )
            or ""
        ).strip()

        if (
            selected_question_id
            and selected_question_id
            != question_id
        ):
            return False

        if option_id:

            if option_id not in valid_options:
                return False

            selection["question_id"] = (
                question_id
            )

            selection["option_id"] = (
                option_id
            )

            selection["resolved_value"] = (
                valid_options[
                    option_id
                ]
            )

            act["selection"] = (
                selection
            )

    return True

def _agent_v2_pending_answer_is_structurally_compatible(
    perception: Dict[str, Any],
    acts: List[Dict[str, Any]],
    relation: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    """
    Valida que el tipo de dato del turno actual pueda responder la
    pregunta pending EXACTA indicada por question_id.

    No interpreta texto.
    No usa singleton fallback.

    Puede inspeccionar STORED MEMORY para conocer el schema de la pregunta
    aunque ésta esté suspendida.

    Eso NO autoriza su contenido.
    La autorización sigue en _agent_v2_context_authorization().
    """

    if str(
        (relation or {}).get("type")
        or ""
    ) != "answers_pending":
        return True

    question_id = str(
        (relation or {}).get("question_id")
        or ""
    ).strip()

    if not question_id:
        return False

    stored = _agent_v2_stored_memory(
        world or {}
    )

    pending_raw = [
        dict(q)
        for q in (
            stored.get("pending_decisions")
            or []
        )
        if isinstance(
            q,
            dict,
        )
    ]

    snapshot_world = {
        **dict(
            world or {}
        ),

        "pending_decisions": (
            pending_raw
        ),
    }

    pending = (
        _agent_v2_pending_semantic_snapshot(
            snapshot_world
        )
    )

    question = next(
        (
            item
            for item in pending
            if str(
                item.get("question_id")
                or ""
            )
            == question_id
        ),
        None,
    )

    if not question:
        return False

    field = str(
        question.get("field")
        or ""
    ).strip().casefold()

    frame = (
        _agent_v2_semantic_frame(
            perception or {}
        )
    )

    temporal_mentions = [
        item
        for item in (
            (perception or {}).get(
                "temporal_mentions"
            )
            or []
        )
        if isinstance(
            item,
            dict,
        )
    ]

    def has_current_provenance(
        field_names: set[str],
    ) -> bool:

        return any(
            str(
                item.get("source")
                or ""
            ).strip().casefold()
            == "current_user_turn"

            and str(
                item.get("field")
                or ""
            ).strip().casefold()
            in field_names

            and str(
                item.get("evidence")
                or ""
            ).strip()

            for act in (
                acts or []
            )

            if isinstance(
                act,
                dict,
            )

            for item in (
                act.get("provenance")
                or []
            )

            if isinstance(
                item,
                dict,
            )
        )

    def has_selection() -> bool:

        return any(
            str(
                (
                    (
                        act.get("selection")
                        or {}
                    ).get("option_id")
                )
                or ""
            ).strip()

            or str(
                (
                    (
                        act.get("target")
                        or {}
                    ).get("option_id")
                )
                or ""
            ).strip()

            for act in (
                acts or []
            )

            if isinstance(
                act,
                dict,
            )
        )

    # =========================================================
    # HORA
    # =========================================================

    if field in {
        "hora",
        "hora_aclaracion",
    }:

        has_time_value = any(
            (
                act.get("temporal")
                or {}
            ).get("start")

            or (
                act.get("temporal")
                or {}
            ).get("times")

            for act in (
                acts or []
            )

            if isinstance(
                act,
                dict,
            )
        )

        return bool(
            _agent_v2_has_original_semantic_time_evidence(
                frame,
                temporal_mentions,
            )
            and (
                has_time_value
                or has_selection()
            )
        )

    # =========================================================
    # DÍA
    # =========================================================

    if field == "dia":

        return has_current_provenance({
            "temporal.day",
            "day",
            "dia",
        })

    # =========================================================
    # DÍA + HORA
    # =========================================================

    if field == "dia_hora_reserva":

        return bool(
            has_current_provenance({
                "temporal.day",
                "day",
                "dia",
            })
            or _agent_v2_has_original_semantic_time_evidence(
                frame,
                temporal_mentions,
            )
        )

    # =========================================================
    # CANCHA
    # =========================================================

    if field == "cancha":

        return bool(
            has_selection()

            or has_current_provenance({
                "target",
                "target.label",
                "cancha",
                "court",
            })

            or any(
                str(
                    (
                        (
                            act.get("target")
                            or {}
                        ).get("evidence")
                    )
                    or ""
                ).strip()

                for act in (
                    acts or []
                )

                if isinstance(
                    act,
                    dict,
                )
            )
        )

    # =========================================================
    # DURACIÓN
    # =========================================================

    if field in {
        "duracion",
        "duracion_horas",
    }:

        return bool(
            any(
                str(
                    item.get("kind")
                    or ""
                ).strip().casefold()
                == "duration"

                and str(
                    item.get("evidence")
                    or ""
                ).strip()

                for item in (
                    temporal_mentions or []
                )
            )

            or has_current_provenance({
                "quantity.duration_hours",
                "temporal.duration_hours",
                "duration_hours",
                "duracion_horas",
            })
        )

    # =========================================================
    # RESERVA
    # =========================================================

    if field == "reserva_especifica":

        return bool(
            has_selection()

            or any(
                str(
                    (
                        (
                            act.get("target")
                            or {}
                        ).get("reservation_id")
                    )
                    or ""
                ).strip()

                for act in (
                    acts or []
                )

                if isinstance(
                    act,
                    dict,
                )
            )
        )

    # =========================================================
    # WAITLIST
    # =========================================================

    if field == "waitlist_offer":

        return any(
            act.get("operation")
            == "join_waitlist"

            and bool(
                (
                    act.get("commitment")
                    or {}
                ).get("wants_write")
            )

            for act in (
                acts or []
            )

            if isinstance(
                act,
                dict,
            )
        )

    # =========================================================
    # PAGO
    # =========================================================

    if field in {
        "comprobante",
        "pago",
        "senia",
    }:

        return bool(
            (perception or {}).get(
                "has_payment_image"
            )

            or any(
                act.get("operation")
                == "register_payment"

                for act in (
                    acts or []
                )

                if isinstance(
                    act,
                    dict,
                )
            )
        )

    # =========================================================
    # CONFIRMACIÓN EXACTA
    # =========================================================

    if field in {
        "confirmar_slot",
        "confirmacion",
        "confirmar",
    }:

        return bool(
            has_selection()

            or any(
                bool(
                    (
                        act.get("commitment")
                        or {}
                    ).get("wants_write")
                )

                for act in (
                    acts or []
                )

                if isinstance(
                    act,
                    dict,
                )
            )
        )

    # Campos futuros no deben romper el schema por no estar
    # enumerados todavía.
    return True



_agent_v2_nba_candidates_base = _agent_v2_nba_candidates


def _agent_v2_nba_candidates(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
) -> List[Dict[str, Any]]:
    """Mantiene el NBA existente, pero autoriza waitlist sólo para hora exacta."""
    contract_auth = ((perception or {}).get("execution_contract") or {}).get(
        "authorized_context"
    ) or _agent_v2_context_authorization(perception or {}, world or {})
    _agent_v2_publish_context_authorization(world, contract_auth)
    candidates = _agent_v2_nba_candidates_base(
        world, perception, goals, observations, status
    )

    # La hora que autoriza una lista de espera debe venir de la Observation
    # factual de esta consulta. Nunca se recupera de perception.entities:
    # allí puede sobrevivir una hora vieja o inferida (el "07:00 fantasma").
    exact_unavailable = next(
        (
            obs
            for obs in reversed(observations or [])
            if (
                obs.get("tool") == "consultar_disponibilidad"
                and not obs.get("ok")
                and obs.get("status") == "unavailable"
                and hora_es_valida(
                    normalizar_hora_detectada((obs.get("data") or {}).get("hora"))
                )
            )
        ),
        None,
    )

    if candidates and exact_unavailable is None:
        before = len(candidates)
        candidates = [
            candidate
            for candidate in candidates
            if candidate.get("action") != "offer_waitlist"
        ]
        if len(candidates) != before:
            print(
                "   🛑 [AgentV2 WAITLIST GUARD] "
                "consulta sin hora exacta → offer_waitlist descartado"
            )

    if candidates:
        return candidates
    bridge = _agent_v2_parallel_policy_booking_bridge_candidate(
        world, perception, observations
    )
    if bridge:
        print(
            "   🏟️🏟️ [AgentV2 PARALLEL COURTS NBA] "
            f"count={bridge['question']['requested_court_count']} "
            "→ abro dia_hora_reserva stateful"
        )
        return [bridge]
    return []


_aplicar_observation_agent_v2_base = aplicar_observation_agent_v2


def aplicar_observation_agent_v2(
    telefono: str,
    observation: Dict,
    world: Dict,
    perception: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Propaga el alcance multi-cancha si la pregunta se divide en día/hora."""
    parallel_parent = _agent_v2_pending_parallel_courts_question(world or {})
    state = _aplicar_observation_agent_v2_base(
        telefono, observation, world, perception
    )
    if not parallel_parent or not (
        observation.get("tool") == "solicitar_dato"
        and observation.get("status") == "needs_user_input"
    ):
        return state
    data = observation.get("data") or {}
    field = str(data.get("field") or "").strip()
    if field not in {"dia", "hora", "hora_aclaracion", "dia_hora_reserva"}:
        return state
    av2 = _agent_v2_state(state)
    child = next((
        dict(q) for q in reversed(av2.get("open_questions") or [])
        if str(q.get("field") or "") == field
    ), {})
    if not child:
        return state
    count = int(parallel_parent["requested_court_count"])
    child.update({
        "requested_court_count": count,
        "court_count": count,
        "parallel_courts": True,
        "booking_shape": "multiple_separate",
        "booking_choice": True,
    })
    child["goal_context"] = list(dict.fromkeys([
        goal for goal in (child.get("goal_context") or [])
        if goal != "crear_reserva"
    ] + ["buscar_turno", "crear_reservas_multiples"]))
    state = agent_v2_reduce(
        telefono, {"type": "SET_OPEN_QUESTION", "payload": child}
    )
    print(
        "   🧷 [AgentV2 PARALLEL COURTS PENDING] "
        f"propago count={count} → field={field}"
    )
    return state


def _agent_v2_attach_availability_price_facts(
    observation: Dict[str, Any],
    world: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Adjunta tarifas configuradas a la Observation que autoriza mostrarlas."""
    if not (
        isinstance(observation, dict)
        and observation.get("tool") == "consultar_disponibilidad"
        and observation.get("ok")
    ):
        return observation

    data = dict(observation.get("data") or {})
    nested_day = (
        data.get("day_availability")
        if isinstance(data.get("day_availability"), dict)
        else {}
    )
    schedule = (
        data.get("canchas_libres_por_franja")
        or nested_day.get("canchas_libres_por_franja")
        or {}
    )
    court_names = [
        str(name).strip()
        for name, hours in schedule.items()
        if str(name).strip() and hours
    ]
    if not court_names:
        court_names = [
            str(name).strip()
            for name in (data.get("canchas_libres") or [])
            if str(name).strip()
        ]
    if not court_names:
        return observation

    business = (
        ((world or {}).get("facts") or {}).get("negocio")
        if isinstance(((world or {}).get("facts") or {}).get("negocio"), dict)
        else {}
    )
    if not business:
        business = _business_knowledge_snapshot()

    configured: Dict[str, int] = {}
    for item in business.get("precios") or []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("description") or item.get("descripcion") or "").strip()
        hourly = _monto_a_int(
            item.get("amount") if "amount" in item else item.get("monto")
        )
        if name and hourly is not None:
            configured[normalizar_texto_ia(name)] = int(hourly)

    duration = normalizar_duracion_horas(
        data.get("duracion_horas")
        or nested_day.get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )
    price_facts = []
    for court_name in court_names:
        hourly = configured.get(normalizar_texto_ia(court_name))
        if hourly is None:
            continue
        price_facts.append({
            "cancha": court_name,
            "precio_por_hora": hourly,
            "duracion_horas": duration,
            "precio_cancha": int(round(float(hourly) * float(duration))),
        })
    if not price_facts:
        return observation

    data["precios_por_cancha"] = price_facts
    enriched = dict(observation)
    enriched["data"] = data
    verified_facts = dict(enriched.get("verified_facts") or {})
    verified_facts["availability_prices"] = price_facts
    enriched["verified_facts"] = verified_facts
    return enriched


def _agent_v2_reconcile_broad_availability_observation(
    observation: Dict[str, Any],
    args: Dict[str, Any],
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    """Revalida una consulta amplia contra los slots reales del calendario."""
    if not isinstance(observation, dict):
        return observation
    if observation.get("tool") != "consultar_disponibilidad":
        return observation

    requested_hour = (
        normalizar_hora_detectada(args.get("hora"))
        if args.get("hora")
        else None
    )
    if hora_es_valida(requested_hour):
        return observation

    data = dict(observation.get("data") or {})
    entities = (perception or {}).get("entities") or {}
    day = (
        data.get("dia")
        or args.get("dia")
        or entities.get("dia_resuelto")
        or entities.get("dia")
    )
    if not day:
        return observation

    resolved_day = resolver_fecha(str(day))
    if not resolved_day or not validar_fecha_en_dias_atencion(resolved_day):
        return observation

    court = normalizar_valor_nullable(args.get("cancha") or data.get("cancha"))
    duration = normalizar_duracion_horas(
        args.get("duracion_horas")
        or data.get("duracion_horas")
        or DEFAULT_TURN_DURATION_HOURS
    )

    resource_types = _canonical_configured_court_types(
        args.get("resource_types") or _agent_v2_resource_type_constraints(perception)
    )
    fresh = tool_buscar_disponibilidad(
        resolved_day, None, court, resource_types=resource_types
    )
    if not fresh.get("ok"):
        return observation

    by_court: Dict[str, List[str]] = {}
    for court_name, raw_hours in (
        fresh.get("canchas_libres_por_franja") or {}
    ).items():
        if court and str(court_name) != str(court):
            continue
        valid_hours = []
        seen = set()
        for raw_hour in raw_hours or []:
            hour = normalizar_hora_detectada(raw_hour)
            if not hora_es_valida(hour) or hour in seen:
                continue
            notice = minutos_hasta_turno(resolved_day, hour)
            if notice is None or notice < MIN_BOOKING_NOTICE_MINUTES:
                continue
            if not canchas_libres_para_bloque(
                resolved_day, hour, duration, str(court_name),
                resource_types=resource_types,
            ):
                continue
            seen.add(hour)
            valid_hours.append(hour)
        by_court[str(court_name)] = valid_hours

    franja = (
        args.get("franja_dia")
        or data.get("franja_dia")
        or entities.get("franja_dia")
    )
    franja = str(franja or "").strip().lower() or None
    if franja not in AGENT_V2_DAYPART_WINDOWS:
        franja = None

    if franja:
        by_court, available_hours = _agent_v2_filter_daypart(by_court, franja)
    else:
        available_hours = sorted(
            {
                hour
                for hours in by_court.values()
                for hour in (hours or [])
                if hora_es_valida(hour)
            },
            key=lambda value: (
                _hora_a_minutos_local(value)
                if _hora_a_minutos_local(value) is not None
                else 10**9
            ),
        )

    after_time = args.get("after_time") or data.get("after_time")
    before_time = args.get("before_time") or data.get("before_time")
    temporal_relation = (
        args.get("temporal_relation") or data.get("temporal_relation")
    )
    if after_time or before_time:
        by_court, available_hours = _agent_v2_filter_temporal_bounds(
            by_court,
            after_time=after_time,
            before_time=before_time,
            relation=temporal_relation,
        )

    fixed_data = dict(data)
    fixed_data.update({
        "ok": bool(available_hours),
        "dia": resolved_day,
        "hora": None,
        "cancha": court,
        "duracion_horas": duration,
        "franja_dia": franja,
        "after_time": after_time,
        "before_time": before_time,
        "temporal_relation": temporal_relation or None,
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "canchas_libres_por_franja": by_court,
        "horas_disponibles": available_hours,
        "razon": (
            "disponibilidad_amplia_verificada"
            if available_hours
            else (
                "sin_disponibilidad_en_franja"
                if franja
                else "sin_disponibilidad_amplia"
            )
        ),
    })

    fixed = dict(observation)
    fixed["data"] = fixed_data
    verified_facts = dict(fixed.get("verified_facts") or {})
    verified_facts["last_availability"] = fixed_data
    fixed["verified_facts"] = verified_facts

    if available_hours:
        read_only = _agent_v2_is_read_only_turn(perception or {})
        fixed["ok"] = True
        fixed["status"] = "success" if read_only else "needs_user_input"
        if read_only:
            fixed.pop("missing", None)
            fixed.pop("options", None)
        else:
            fixed["missing"] = ["hora"]
            fixed["options"] = list(available_hours)
        print(
            "   ✅ [AgentV2 BROAD AVAILABILITY AUTHORITY] "
            f"dia={resolved_day} franja={franja or '-'} "
            f"horas={available_hours} → ok=True status={fixed['status']}"
        )
        return fixed

    fixed["ok"] = False
    fixed["status"] = "unavailable"
    fixed.pop("missing", None)
    fixed.pop("options", None)
    print(
        "   ℹ️ [AgentV2 BROAD AVAILABILITY AUTHORITY] "
        f"dia={resolved_day} franja={franja or '-'} → sin slots reales"
    )
    return fixed


_ejecutar_tool_agent_v2_base = ejecutar_tool_agent_v2


async def ejecutar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    telefono: str,
    prospecto: Dict,
    user_messages: List[str],
    page=None,
    image_path: str = "",
) -> Dict[str, Any]:
    """Revalida disponibilidad amplia y enriquece batches verificados."""
    observation = await _ejecutar_tool_agent_v2_base(
        tool, args, world, perception, goals, telefono, prospecto,
        user_messages, page=page, image_path=image_path,
    )
    if tool == "consultar_disponibilidad":
        observation = _agent_v2_reconcile_broad_availability_observation(
            observation, args, perception
        )
        return _agent_v2_attach_availability_price_facts(observation, world)
    if not (
        tool == "crear_reservas_multiples"
        and isinstance(observation, dict)
        and observation.get("ok")
        and observation.get("status") == "success"
    ):
        return observation
    data = dict(observation.get("data") or {})
    rows = [row for row in (data.get("reservas") or []) if isinstance(row, dict)]
    if len(rows) < 2:
        return observation
    def row_amount(row: Dict[str, Any], field: str, fallback: int = 0) -> int:
        parsed = _monto_a_int(row.get(field))
        return fallback if parsed is None else parsed
    precio_total = sum(row_amount(row, "precio_total") for row in rows)
    senia_total = sum(
        row_amount(row, "senia_monto", _senia_para_total(row.get("precio_total")))
        for row in rows
    )
    saldo_total = sum(
        row_amount(
            row, "monto_pendiente",
            max(0, row_amount(row, "precio_total") - row_amount(
                row, "senia_monto", _senia_para_total(row.get("precio_total"))
            )),
        )
        for row in rows
    )
    hours = [normalizar_hora_detectada(row.get("hora")) for row in rows]
    parallel = bool(
        len(hours) == len(rows)
        and all(hora_es_valida(hour) for hour in hours)
        and len(set(hours)) == 1
    )
    data.update({
        "parallel_courts": parallel,
        "precio_total": precio_total,
        "senia_monto": senia_total if REQUIRES_DEPOSIT else 0,
        "monto_pendiente": saldo_total,
    })
    enriched = dict(observation)
    enriched["data"] = data
    verified_facts = dict(enriched.get("verified_facts") or {})
    verified_facts["multiple_reservations_created"] = data
    enriched["verified_facts"] = verified_facts
    return enriched


_build_agent_v2_multiple_created_message_base = build_agent_v2_multiple_created_message


def build_agent_v2_multiple_created_message(observation: Dict[str, Any]) -> str:
    """Presenta dos canchas simultáneas y sus totales factuales como un batch."""
    data = (observation or {}).get("data") or {}
    rows = [row for row in (data.get("reservas") or []) if isinstance(row, dict)]
    if not rows:
        return ""
    hours = [normalizar_hora_detectada(row.get("hora")) for row in rows]
    same_hour = bool(
        data.get("parallel_courts")
        or (
            len(rows) >= 2
            and all(hora_es_valida(hour) for hour in hours)
            and len(set(hours)) == 1
        )
    )
    lines = []
    # El batch conserva la misma referencia temporal verificable que una
    # reserva individual. La tool normalmente publica `dia`; las filas sirven
    # de respaldo para ejecuciones antiguas que sólo incluyan fecha/día.
    dia = (
        data.get("dia")
        or data.get("fecha")
        or rows[0].get("dia")
        or rows[0].get("fecha")
        or ""
    )
    hora_principal = normalizar_hora_detectada(rows[0].get("hora"))
    duracion_principal = normalizar_duracion_horas(
        rows[0].get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )
    if same_hour and hora_es_valida(hora_principal):
        lines.append(
            f"Sí, ambas canchas de {rango_horario_texto(hora_principal, duracion_principal)} "
            "están disponibles. ✅"
        )
    elif same_hour:
        lines.append("Sí, ambas canchas están disponibles. ✅")
    else:
        lines.append("✅ Los turnos están disponibles.")
    if REQUIRES_DEPOSIT:
        # Misma secuencia operacional que una cancha: disponibilidad → pedido
        # explícito de comprobante → plazo de hold. Sólo se pluraliza el scope.
        lines.extend([
            "",
            (
                "Para dejar firmes los turnos, por favor envía el comprobante "
                f"de la seña total de {_fmt_precio(_monto_a_int(data.get('senia_monto')) or 0)} "
                f"al alias {PAYMENT_ALIAS}."
            ),
            (
                f"⏳ Te mantengo estos horarios bloqueados durante "
                f"{PENDING_DEPOSIT_HOLD_MINUTES} minutos mientras espero el comprobante. "
                "Si no podemos validar el pago dentro de ese plazo, los horarios se liberan automáticamente."
            ),
            f"Si tenés efectivo, podés acercarte a {BUSINESS_ADDRESS} para reservar. Gracias.",
            "",
        ])
    if dia:
        lines.append(f"📅 Día: {dia}")
    if hora_es_valida(hora_principal):
        lines.append(
            "🕐 Horario: "
            f"{rango_horario_texto(hora_principal, duracion_principal)}"
        )
    for row in rows:
        lines.append(
            f"⚽ *{row.get('cancha')}* — "
            f"*{formatear_hora_para_mensaje(row.get('hora'))}* "
            f"({float(row.get('duracion_horas') or 1):g}h)"
        )
    precio_total = _monto_a_int(data.get("precio_total"))
    senia_total = _monto_a_int(data.get("senia_monto"))
    saldo_total = _monto_a_int(data.get("monto_pendiente"))
    if precio_total is not None:
        lines.extend(["", f"💰 *Total: {_monto_humano(precio_total)}*"])
    if REQUIRES_DEPOSIT:
        if senia_total is not None:
            lines.append(f"💵 *Seña total: {_monto_humano(senia_total)}*")
        if saldo_total is not None:
            lines.append(f"💸 Saldo pendiente: {_monto_humano(saldo_total)}")
    return "\n".join(lines).strip()



# ============================================================================
# V80 — RESOURCE SCOPE CONTINUITY (tenis / pádel / tipos configurados)
# ============================================================================
# Principio: la IA decide si dos turnos hablan del mismo tipo de recurso.
# Python únicamente valida que el tipo exista en config.COURTS y preserva la
# provenance/reference_id. No se agregan regex ni keyword routers de deportes.


def _agent_v2_recent_resource_scope_focus(
    world: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """Devuelve un scope de tipo de cancha reciente, todavía PASIVO.

    La mera existencia de este objeto no autoriza memoria. Se usa sólo como
    candidato para que ContextResolver/IA decida si el turno actual continúa el
    tema anterior. El valor procede de una Observation real de disponibilidad.
    """
    stored = _agent_v2_stored_memory(world or {})
    availability = dict(stored.get("availability_context") or {})
    resource_types = _canonical_configured_court_types(
        availability.get("resource_types")
        or ([availability.get("resource_type")] if availability.get("resource_type") else [])
    )
    if not resource_types:
        return None

    created_at = _parse_context_timestamp(availability.get("created_at"))
    now = datetime.datetime.now(TIMEZONE)
    if created_at:
        age = (now - created_at).total_seconds()
        if age < 0 or age > PENDING_AVAILABILITY_CONTEXT_TTL_MINUTES * 60:
            return None

    source_message = str(availability.get("source_message") or "").strip()
    previous_turn = None
    if source_message:
        for row in reversed(_agent_v2_history_with_reference_ids(world or {})):
            if str(row.get("content") or "").strip() == source_message:
                previous_turn = dict(row)
                break

    if previous_turn is None:
        # Sin identidad verificable de un turno USER no autorizamos continuidad.
        return None

    return {
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "scope_id": str(availability.get("scope_id") or "").strip() or None,
        "source_message": source_message,
        "reference_id": str(previous_turn.get("reference_id") or "").strip(),
        "created_at": availability.get("created_at"),
    }


_agent_v2_context_inventory_v79 = _agent_v2_context_inventory


def _agent_v2_context_inventory(world: Dict[str, Any]) -> Dict[str, Any]:
    inventory = dict(_agent_v2_context_inventory_v79(world) or {})
    focus = _agent_v2_recent_resource_scope_focus(world)
    inventory["has_resource_scope_focus"] = bool(focus)
    inventory["resource_scope_focus_kind"] = "court_type" if focus else None
    return inventory


def _agent_v2_inject_resource_types_into_read_frame(
    perception: Dict[str, Any],
    resource_types: Any,
    *,
    provenance_source: str = "current_user_turn",
    evidence: str = "",
    reference_id: Optional[str] = None,
    scope_id: Optional[str] = None,
) -> Dict[str, Any]:
    """Inyecta sólo el scope de tipo en acts READ de cancha ya reconocidos."""
    clean = dict(perception or {})
    canonical = _canonical_configured_court_types(resource_types)
    if not canonical:
        return clean

    entities = dict(clean.get("entities") or {})
    entities["resource_types"] = list(canonical)
    entities["resource_type"] = canonical[0] if len(canonical) == 1 else None
    clean["entities"] = entities

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts = []
    for raw_act in frame.get("acts") or []:
        if not isinstance(raw_act, dict):
            continue
        act = dict(raw_act)
        operation = str(act.get("operation") or "")
        target = dict(act.get("target") or {})
        if (
            operation in {"query_availability", "query_policy", "query_price", "create_booking"}
            and str(target.get("resource") or "") == "court"
        ):
            target["resource_types"] = list(canonical)
            target["resource_type"] = canonical[0] if len(canonical) == 1 else None
            act["target"] = target
            provenance = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
            ]
            if not any(
                str(item.get("field") or "") in {"target.resource_type", "target.resource_types"}
                and str(item.get("source") or "") == provenance_source
                and str(item.get("reference_id") or "") == str(reference_id or "")
                for item in provenance
            ):
                provenance.append({
                    "field": "target.resource_types",
                    "source": provenance_source,
                    "evidence": str(evidence or "")[:500],
                    "reference_id": reference_id,
                    "scope_id": scope_id,
                    "question_id": None,
                    "option_id": None,
                })
            act["provenance"] = provenance
        acts.append(act)
    frame["acts"] = acts

    targets = []
    for raw_target in frame.get("targets") or []:
        if not isinstance(raw_target, dict):
            continue
        target = dict(raw_target)
        if str(target.get("resource") or "") == "court":
            target["resource_types"] = list(canonical)
            target["resource_type"] = canonical[0] if len(canonical) == 1 else None
        targets.append(target)
    frame["targets"] = targets
    clean["semantic_frame"] = frame
    return clean


async def _agent_v2_repair_current_court_resource_scope_with_ai(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Recupera un tipo EXPLÍCITO actual sólo mediante una lectura semántica IA.

    Se limita a tipos que realmente existen en config.COURTS. No hereda memoria,
    no decide disponibilidad y no cambia READ/WRITE; sólo repara resource_type.
    """
    clean = dict(perception or {})
    if _agent_v2_resource_type_constraints(clean, world):
        return clean

    frame = _agent_v2_semantic_frame(clean)
    relevant = False
    for act in frame.get("acts") or []:
        if not isinstance(act, dict):
            continue
        operation = str(act.get("operation") or "")
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        requested_facts = {str(v or "").strip() for v in (act.get("requested_facts") or [])}
        if (
            str(target.get("resource") or "") == "court"
            and operation in {"query_policy", "query_availability", "query_price", "create_booking"}
        ) or requested_facts.intersection({"court.catalog", "court.types", "available_slots"}):
            relevant = True
            break
    if not relevant:
        return clean

    configured_types = _canonical_configured_court_types([
        str(item.get("type") or item.get("tipo") or "").strip()
        for item in (COURTS or [])
        if isinstance(item, dict)
    ])
    if not configured_types:
        return clean

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos RESOURCE SCOPE EXTRACTOR. Determiná únicamente si el current_user_turn "
                        "menciona de forma semánticamente explícita uno o más tipos de cancha de la lista "
                        "configured_types. No uses memoria ni completes tipos implícitos. Si pregunta por "
                        "disponibilidad genérica sin nombrar tipo, devolvé []. Si menciona un tipo configurado, "
                        "devolvé exactamente su valor canónico. evidence debe ser una cita literal no vacía del "
                        "mensaje actual. No decidas tools, fecha ni intención. Respondé sólo JSON: "
                        "{resource_types:[string], evidence:string}."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "configured_types": configured_types,
                        "semantic_frame": frame,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        decision = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 RESOURCE SCOPE EXTRACTOR] "
            f"sin reparación segura: {type(exc).__name__}: {exc}"
        )
        return clean

    proposed = _canonical_configured_court_types(decision.get("resource_types") or [])
    evidence = str(decision.get("evidence") or "").strip()
    if not proposed or not evidence:
        return clean
    if normalizar_texto_ia(evidence) not in normalizar_texto_ia(mensaje or ""):
        return clean

    clean = _agent_v2_inject_resource_types_into_read_frame(
        clean,
        proposed,
        provenance_source="current_user_turn",
        evidence=evidence,
    )
    clean.pop("execution_contract", None)
    clean = _agent_v2_normalize_perception(clean, world, mensaje, "")
    print(
        "   🏷️ [AgentV2 RESOURCE SCOPE EXTRACTOR] "
        f"current_turn={proposed} evidence={evidence!r}"
    )
    return clean


_agent_v2_resolve_context_reference_v79 = _agent_v2_resolve_context_reference


async def _agent_v2_resolve_context_reference(
    mensaje: str,
    first_perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """V80: permite continuidad semántica de un tipo de cancha reciente."""
    resolved = await _agent_v2_resolve_context_reference_v79(
        mensaje,
        first_perception,
        world,
    )

    existing_resolution = (
        resolved.get("context_resolution")
        if isinstance(resolved.get("context_resolution"), dict)
        else {}
    )
    if existing_resolution.get("resolved"):
        return resolved

    frame = _agent_v2_semantic_frame(resolved)
    operations = {
        str(act.get("operation") or "")
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
    }
    if "query_availability" not in operations:
        return resolved

    # Un tipo mencionado AHORA siempre gana; no se hereda nada.
    if _agent_v2_resource_type_constraints(resolved, world):
        return resolved

    focus = _agent_v2_recent_resource_scope_focus(world)
    if not focus or not focus.get("reference_id"):
        return resolved

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos RESOURCE SCOPE CONTINUITY ADJUDICATOR. Decidí si la consulta actual de "
                        "disponibilidad continúa semánticamente el tipo de cancha del turno USER anterior. "
                        "No heredes el scope sólo porque existe. Si el usuario cambia de deporte, pide cualquier "
                        "cancha/todas las canchas, cambia de tema o la referencia no es clara, devolvé false. "
                        "Si la pregunta es elíptica y naturalmente continúa el mismo objeto conversacional, "
                        "devolvé true. No decidas horarios ni reservas. evidence debe ser una cita literal exacta "
                        "del mensaje actual. Respondé sólo JSON: "
                        "{continues_previous_resource_scope:boolean,evidence:string,reason:string}."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "previous_user_turn": focus.get("source_message"),
                        "previous_resource_types": focus.get("resource_types"),
                        "current_semantic_frame": frame,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=200,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        decision = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 RESOURCE SCOPE CONTINUITY] "
            f"sin decisión segura: {type(exc).__name__}: {exc}"
        )
        return resolved

    evidence = str(decision.get("evidence") or "").strip()
    if not decision.get("continues_previous_resource_scope"):
        return resolved
    if not evidence or normalizar_texto_ia(evidence) not in normalizar_texto_ia(mensaje or ""):
        return resolved

    reference_id = str(focus.get("reference_id") or "").strip()
    scope_id = str(focus.get("scope_id") or "").strip() or None
    resource_types = list(focus.get("resource_types") or [])
    clean = _agent_v2_inject_resource_types_into_read_frame(
        resolved,
        resource_types,
        provenance_source="previous_user_turn",
        evidence=str(focus.get("source_message") or ""),
        reference_id=reference_id,
        scope_id=scope_id,
    )

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    relation = dict(frame.get("context_relation") or {})
    relation.update({
        "type": "references_previous",
        "question_id": None,
        "references_previous_user_turn": True,
        "references_agent_offer": False,
        "answers_pending_question": False,
    })
    frame["context_relation"] = relation
    # ContextAuthorization exige un binding histórico real y único.
    acts = []
    for raw_act in frame.get("acts") or []:
        if not isinstance(raw_act, dict):
            continue
        act = dict(raw_act)
        if str(act.get("operation") or "") == "query_availability":
            provenance = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
            ]
            if not any(
                str(item.get("field") or "") == "context.reference"
                and str(item.get("reference_id") or "") == reference_id
                for item in provenance
            ):
                provenance.append({
                    "field": "context.reference",
                    "source": "previous_user_turn",
                    "evidence": str(focus.get("source_message") or "")[:500],
                    "reference_id": reference_id,
                    "scope_id": scope_id,
                })
            act["provenance"] = provenance
        acts.append(act)
    frame["acts"] = acts
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "references_previous"
    clean["references_prior_user_input"] = True
    clean["context_request"] = {
        "needed": True,
        "relation": "references_previous",
        "candidate_types": ["resource_scope_focus"],
        "reason": "semantic_resource_scope_continuation",
    }
    clean["context_resolution"] = {
        "requested": True,
        "resolved": True,
        "relation": "references_previous",
        "question_id": None,
        "reference_id": reference_id,
        "scope_id": scope_id,
        "resolved_value": resource_types[0] if len(resource_types) == 1 else None,
        "reason": str(decision.get("reason") or "resource_scope_continuity_validated"),
    }
    clean["reference_resolution"] = {
        "source": "user_history",
        "resolved": True,
        "reference_id": reference_id,
        "text": str(focus.get("source_message") or "")[:500],
    }
    print(
        "   🎾 [AgentV2 RESOURCE SCOPE CONTINUITY] "
        f"reference_id={reference_id} resource_types={resource_types} "
        f"evidence={evidence!r}"
    )
    return clean


_agent_v2_apply_court_catalog_perception_authority_v79 = (
    _agent_v2_apply_court_catalog_perception_authority
)


def _agent_v2_apply_court_catalog_perception_authority(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """V80: catálogo específico + disponibilidad del mismo tipo para hoy."""
    current_types = _agent_v2_resource_type_constraints(perception, world)
    clean = _agent_v2_apply_court_catalog_perception_authority_v79(
        perception,
        mensaje,
        world,
    )
    if not current_types:
        return clean

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    catalog_acts = [
        act for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") == "query_policy"
    ]
    if not catalog_acts:
        return clean

    # Comparaciones detalladas (diferencias, superficie, equipamiento) siguen
    # siendo policy-only. La mejora aplica a "¿tenés cancha de X?"/catálogo de
    # tipos, donde mostrar disponibilidad de hoy agrega valor sin asumir reserva.
    requested_facts = {
        str(value or "")
        for act in catalog_acts
        for value in (act.get("requested_facts") or [])
    }
    if requested_facts.intersection({"court.differences", "court.features", "court.characteristics", "court.details"}):
        return clean

    today_iso = datetime.datetime.now(TIMEZONE).date().isoformat()
    entities = dict(clean.get("entities") or {})
    entities.update({
        "dia": today_iso,
        "dia_resuelto": resolver_fecha(today_iso),
        "resource_types": list(current_types),
        "resource_type": current_types[0] if len(current_types) == 1 else None,
    })
    clean["entities"] = entities

    patched_acts = []
    for raw_act in frame.get("acts") or []:
        if not isinstance(raw_act, dict):
            continue
        act = dict(raw_act)
        if str(act.get("operation") or "") == "query_policy":
            target = dict(act.get("target") or {})
            if str(target.get("resource") or "") == "court":
                target["resource_types"] = list(current_types)
                target["resource_type"] = current_types[0] if len(current_types) == 1 else None
                act["target"] = target
        patched_acts.append(act)

    availability_target = {
        "resource": "court",
        "reservation_id": None,
        "selection_policy": "any_available",
        "source": "current_user_turn",
        "evidence": mensaje,
        "resource_types": list(current_types),
        "resource_type": current_types[0] if len(current_types) == 1 else None,
    }
    availability_act = {
        "act_id": "court_type_today_availability_v80",
        "operation": "query_availability",
        "domain": "booking",
        "target": availability_target,
        "temporal": {
            "day": today_iso,
            "start": None,
            "end": None,
            "times": [],
            "daypart": None,
            "mode": None,
            "after": None,
            "before": None,
            "relation": None,
            "duration_hours": DEFAULT_TURN_DURATION_HOURS,
            "structure": "single",
        },
        "quantity": {"duration_hours": DEFAULT_TURN_DURATION_HOURS, "count": None},
        "changes": [],
        "provenance": [
            {
                "field": "target.resource_types",
                "source": "current_user_turn",
                "evidence": mensaje,
                "question_id": None,
                "option_id": None,
                "reference_id": None,
            },
            {
                "field": "temporal.day",
                "source": "world_fact",
                "evidence": "business_clock.proactive_today_for_specific_court_catalog",
                "reference_id": None,
            },
        ],
        "requested_facts": ["available_slots"],
        "commitment": {"wants_write": False, "wants_information": True},
        "selection": {},
    }
    if not any(
        isinstance(act, dict)
        and str(act.get("operation") or "") == "query_availability"
        for act in patched_acts
    ):
        patched_acts.append(availability_act)

    frame["acts"] = patched_acts
    frame["targets"] = [
        dict(act.get("target") or {})
        for act in patched_acts
        if isinstance(act, dict) and isinstance(act.get("target"), dict)
    ]
    frame["requested_facts"] = list(dict.fromkeys([
        *(frame.get("requested_facts") or []),
        "available_slots",
    ]))
    frame["commitment"] = {"wants_write": False, "wants_information": True}
    clean["semantic_frame"] = frame
    # V84: marca estructurada del bundle creado por SYSTEM grounding. No deriva
    # intención desde texto libre; conserva únicamente el resource_type que la
    # IA ya resolvió y el default informativo HOY decidido por esta authority.
    clean["_specific_court_catalog_today_bundle"] = {
        "resource_types": list(current_types),
        "resource_type": current_types[0] if len(current_types) == 1 else None,
        "dia": entities.get("dia_resuelto") or resolver_fecha(today_iso),
        "source": "system_config_grounding",
    }
    domains = list(_agent_v2_normalize_question_domains(clean))
    if "availability" not in domains:
        domains.append("availability")
    clean["question_domains"] = domains
    clean["current_turn_read_only"] = False
    clean.pop("execution_contract", None)
    clean = _agent_v2_normalize_perception(clean, world, mensaje, "")
    print(
        "   🎾 [AgentV2 COURT TYPE + TODAY AVAILABILITY] "
        f"resource_types={current_types} dia={entities.get('dia_resuelto')} "
        "→ query_policy + query_availability"
    )
    return clean


_agent_v2_apply_fresh_availability_perception_authority_v79 = (
    _agent_v2_apply_fresh_availability_perception_authority
)


def _agent_v2_apply_fresh_availability_perception_authority(
    perception: Dict[str, Any],
    mensaje: str,
    world: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """V80: limpia slots viejos, pero NO un resource scope autorizado."""
    before = dict(perception or {})
    before_frame = _agent_v2_semantic_frame(before)
    before_relation = dict(_agent_v2_semantic_context_relation(before_frame) or {})
    before_types = _agent_v2_resource_type_constraints(before, world or {})
    before_contract = before.get("execution_contract") if isinstance(before.get("execution_contract"), dict) else {}
    before_auth = before_contract.get("authorized_context") if isinstance(before_contract.get("authorized_context"), dict) else {}
    before_resolution = before.get("context_resolution") if isinstance(before.get("context_resolution"), dict) else {}

    preserve_contextual_type = bool(
        before_types
        and str(before_relation.get("type") or "") == "references_previous"
        and (
            before_auth.get("authorized")
            or (
                before_resolution.get("resolved")
                and before_resolution.get("reference_id")
            )
        )
    )

    clean = _agent_v2_apply_fresh_availability_perception_authority_v79(
        perception,
        mensaje,
        world,
    )
    if not preserve_contextual_type:
        return clean

    reference_id = str(
        before_auth.get("reference_id")
        or before_resolution.get("reference_id")
        or ""
    ).strip()
    scope_id = str(
        before_auth.get("scope_id")
        or before_resolution.get("scope_id")
        or ""
    ).strip() or None
    source_text = str(
        (before.get("reference_resolution") or {}).get("text")
        if isinstance(before.get("reference_resolution"), dict)
        else ""
    ).strip()

    clean = _agent_v2_inject_resource_types_into_read_frame(
        clean,
        before_types,
        provenance_source="previous_user_turn",
        evidence=source_text,
        reference_id=reference_id,
        scope_id=scope_id,
    )
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    frame["context_relation"] = dict(before_relation)
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "references_previous"
    clean["references_prior_user_input"] = True
    clean["suspend_pending_this_turn"] = True
    clean["context_resolution"] = dict(before_resolution)
    if isinstance(before.get("reference_resolution"), dict):
        clean["reference_resolution"] = dict(before.get("reference_resolution") or {})
    clean.pop("execution_contract", None)
    clean = _agent_v2_normalize_perception(clean, world or {}, mensaje, "")
    print(
        "   🎾 [AgentV2 FRESH AVAILABILITY RESOURCE SCOPE] "
        f"preservo resource_types={before_types} reference_id={reference_id} "
        "mientras limpio hora/cancha históricas"
    )
    return clean



# ============================================================================
# V81 — RESOURCE SCOPE PLANNER AUTHORITY + DURABLE SEMANTIC FOCUS
# ============================================================================
# V80 ya lograba dos cosas importantes:
#   1) Perception/IA podía resolver resource_type (p.ej. Tenis) sin regex.
#   2) Court Catalog Authority añadía un query_availability para HOY.
#
# El bug real estaba después: Tool-First no copiaba resource_types a la tool y,
# como "hoy" era un default de sistema (no evidencia literal del usuario), el
# Current-Turn Firewall podía retirar el día antes de Planner. Resultado: el
# query_availability terminaba degradado a solicitar_dato y nunca se generaba
# availability_context. Sin ese contexto, el siguiente turno elíptico tampoco
# tenía un scope pasivo que ContextResolver pudiera evaluar.
#
# V81 NO interpreta deportes con Python. Sólo consume resource_types ya decididos
# por SemanticFrame/IA y validados contra config.COURTS.


def _agent_v2_v81_resource_types_for_availability_act(
    act: Optional[Dict[str, Any]],
    perception: Optional[Dict[str, Any]],
    world: Optional[Dict[str, Any]],
) -> List[str]:
    act = act or {}
    target = act.get("target") if isinstance(act.get("target"), dict) else {}
    candidates: List[Any] = []
    candidates.extend(target.get("resource_types") or [])
    if target.get("resource_type"):
        candidates.append(target.get("resource_type"))
    if not candidates:
        candidates.extend(_agent_v2_resource_type_constraints(perception or {}, world or {}))
    return _canonical_configured_court_types(candidates)


def _agent_v2_v81_availability_args_from_act(
    act: Dict[str, Any],
    perception: Dict[str, Any],
    world: Dict[str, Any],
    *,
    force_today: bool = False,
) -> Dict[str, Any]:
    """Compila args READ sin reinterpretar texto libre."""
    entities = perception.get("entities") if isinstance(perception.get("entities"), dict) else {}
    temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
    target = act.get("target") if isinstance(act.get("target"), dict) else {}

    day = entities.get("dia_resuelto") or entities.get("dia") or temporal.get("day")
    if force_today and not day:
        # Este default sólo se usa para el act Python-inyectado de catálogo
        # específico. No convierte consultas arbitrarias sin fecha en "hoy".
        today_iso = datetime.datetime.now(TIMEZONE).date().isoformat()
        day = resolver_fecha(today_iso)

    requested_hours = _agent_v2_dedupe_hours(
        list(temporal.get("times") or []) + list(entities.get("horas") or [])
    )
    hour = normalizar_hora_detectada(temporal.get("start") or entities.get("hora"))
    if hora_es_valida(hour) and hour not in requested_hours:
        requested_hours.insert(0, hour)
    daypart = temporal.get("daypart") or entities.get("franja_dia")
    if daypart and not _agent_v2_has_distinct_structured_time_evidence(perception):
        hour = None
        requested_hours = []

    resource_types = _agent_v2_v81_resource_types_for_availability_act(
        act, perception, world
    )
    return {
        "dia": day,
        "hora": hour if hora_es_valida(hour) else None,
        "franja_dia": daypart,
        "cancha": (
            target.get("label") if target.get("resource") == "court" else None
        ) or entities.get("cancha"),
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "duracion_horas": (
            (act.get("quantity") or {}).get("duration_hours")
            or temporal.get("duration_hours")
            or entities.get("duracion_horas")
            or DEFAULT_TURN_DURATION_HOURS
        ),
        "requested_hours": requested_hours,
        "booking_shape": temporal.get("structure") or perception.get("booking_shape") or "single",
        "temporal_mode": temporal.get("mode") or entities.get("temporal_mode"),
        "after_time": temporal.get("after") or entities.get("after_time"),
        "before_time": temporal.get("before") or entities.get("before_time"),
        "temporal_relation": temporal.get("relation") or entities.get("temporal_relation"),
    }


_agent_v2_tool_first_read_plan_v80 = _agent_v2_tool_first_read_plan


def _agent_v2_tool_first_read_plan(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
) -> Optional[Dict[str, Any]]:
    """V81: Tool-First conserva resource scope y el default HOY autorizado."""
    plan = _agent_v2_tool_first_read_plan_v80(
        world, perception, goals, observations
    )
    if plan is None:
        return None

    contract = (perception or {}).get("execution_contract") or {}
    acts = [
        act for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    ]
    availability_acts = [
        act for act in acts
        if str(act.get("operation") or "") == "query_availability"
    ]
    if not availability_acts:
        return plan

    # En una consulta de catálogo específico V80 creó este act en Python. Aunque
    # el firewall de fecha retire su temporal.day por no haber sido escrito por el
    # usuario, la intención del sistema sigue siendo: catálogo + disponibilidad
    # del MISMO tipo para hoy. Sólo este act puede recuperar ese default.
    proactive_act = next((
        act for act in availability_acts
        if str(act.get("act_id") or "") == "court_type_today_availability_v80"
    ), None)

    steps = [dict(step) for step in (plan.get("steps") or []) if isinstance(step, dict)]

    # 1) Propagar resource_types explícitamente a cada READ de agenda.
    #    La tool ya sabe filtrarlos y fail-closed contra config.COURTS.
    for step in steps:
        if str(step.get("tool") or "") != "consultar_disponibilidad":
            continue
        args = dict(step.get("args") or {})
        chosen_act = availability_acts[0]
        scoped = _agent_v2_v81_resource_types_for_availability_act(
            chosen_act, perception, world
        )
        if scoped:
            args["resource_types"] = list(scoped)
            args["resource_type"] = scoped[0] if len(scoped) == 1 else None
            step["args"] = args

    # 2) Reparar el caso exacto del log: policy + query_availability específico
    #    acababa como policy + solicitar_dato porque el día proactivo fue limpiado.
    if proactive_act is not None:
        scoped = _agent_v2_v81_resource_types_for_availability_act(
            proactive_act, perception, world
        )
        if scoped:
            proactive_args = _agent_v2_v81_availability_args_from_act(
                proactive_act,
                perception,
                world,
                force_today=True,
            )
            replacement_needed = any(
                str(step.get("tool") or "") == "solicitar_dato"
                and str((step.get("args") or {}).get("campo") or "")
                in {"dia", "dia_hora_reserva"}
                for step in steps
            )
            already_has_availability = any(
                str(step.get("tool") or "") == "consultar_disponibilidad"
                for step in steps
            )
            if replacement_needed and proactive_args.get("dia"):
                steps = [
                    step for step in steps
                    if not (
                        str(step.get("tool") or "") == "solicitar_dato"
                        and str((step.get("args") or {}).get("campo") or "")
                        in {"dia", "dia_hora_reserva"}
                    )
                ]
                if not already_has_availability:
                    steps.append({
                        "tool": "consultar_disponibilidad",
                        "args": proactive_args,
                        "reason": (
                            "V81 catálogo específico: disponibilidad factual del mismo "
                            "resource_type para hoy"
                        ),
                        "replan_after": False,
                    })
                print(
                    "   🎾 [AgentV2 V81 CATALOG→TODAY PLAN] "
                    f"resource_types={scoped} dia={proactive_args.get('dia')} "
                    "solicitar_dato reemplazado por consultar_disponibilidad"
                )

    # Dejar disponibilidad al final: una lectura amplia puede terminar en
    # needs_user_input y cortar el executor. Primero deben resolverse las otras
    # consultas READ del mismo mensaje (catálogo/precio/policy).
    non_availability = [
        step for step in steps
        if str(step.get("tool") or "") != "consultar_disponibilidad"
    ]
    availability_steps = [
        step for step in steps
        if str(step.get("tool") or "") == "consultar_disponibilidad"
    ]
    steps = non_availability + availability_steps

    # Deduplicación final por tool+args.
    deduped = []
    signatures = set()
    for step in steps:
        signature = json.dumps(
            {"tool": step.get("tool"), "args": step.get("args") or {}},
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
        if signature in signatures:
            continue
        signatures.add(signature)
        deduped.append(step)

    fixed = dict(plan)
    fixed["steps"] = deduped[:AGENT_V2_MAX_PLAN_STEPS]
    return fixed


_agent_v2_recent_resource_scope_focus_v80 = _agent_v2_recent_resource_scope_focus


def _agent_v2_recent_resource_scope_focus(
    world: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """V81: focus pasivo desde Observation o último SemanticFrame verificado.

    Preferimos availability_context porque proviene de una Observation real.
    Como fallback, aceptamos el último Perception persistido únicamente cuando:
      - contiene un resource_type válido de config.COURTS;
      - existe provenance current_user_turn para ese scope;
      - podemos vincularlo a un mensaje USER real del historial.
    Ese focus todavía NO autoriza nada: el adjudicador IA del turno siguiente
    decide si la elipsis continúa ese objeto conversacional.
    """
    focus = _agent_v2_recent_resource_scope_focus_v80(world)
    if focus:
        return focus

    stored = _agent_v2_stored_memory(world or {})
    inferences = stored.get("inferences") if isinstance(stored.get("inferences"), dict) else {}
    previous = inferences.get("perception") if isinstance(inferences.get("perception"), dict) else {}
    if not previous:
        return None

    resource_types = _agent_v2_resource_type_constraints(previous, world or {})
    if not resource_types:
        return None

    frame = _agent_v2_semantic_frame(previous)
    scope_provenance = []
    for act in frame.get("acts") or []:
        if not isinstance(act, dict):
            continue
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        target_types = _canonical_configured_court_types(
            target.get("resource_types")
            or ([target.get("resource_type")] if target.get("resource_type") else [])
        )
        if not target_types:
            continue
        for item in act.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            if str(item.get("source") or "").strip().casefold() != "current_user_turn":
                continue
            if str(item.get("field") or "").strip() not in {
                "target.resource_type", "target.resource_types"
            }:
                continue
            evidence = str(item.get("evidence") or "").strip()
            if evidence:
                scope_provenance.append((item, evidence))
    if not scope_provenance:
        return None

    source_message = str(
        ((previous.get("customer_context") or {}).get("source_message"))
        if isinstance(previous.get("customer_context"), dict)
        else ""
    ).strip()
    if not source_message:
        source_message = scope_provenance[-1][1]

    history = _agent_v2_history_with_reference_ids(world or {})
    matching = [
        dict(row) for row in history
        if str(row.get("role") or "").strip().casefold() == "user"
        and str(row.get("content") or "").strip() == source_message
    ]
    if not matching:
        return None
    previous_turn = matching[-1]

    # Evita ofrecer como focus un tema remoto: debe ser uno de los últimos dos
    # mensajes USER previos disponibles. La IA sigue teniendo la última palabra.
    recent_user_rows = [
        row for row in history
        if str(row.get("role") or "").strip().casefold() == "user"
    ][-2:]
    if recent_user_rows and not any(
        str(row.get("reference_id") or "") == str(previous_turn.get("reference_id") or "")
        for row in recent_user_rows
    ):
        return None

    scope_item = scope_provenance[-1][0]
    return {
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "scope_id": str(scope_item.get("scope_id") or "").strip() or None,
        "source_message": source_message,
        "reference_id": str(previous_turn.get("reference_id") or "").strip(),
        "created_at": None,
        "source": "previous_verified_semantic_frame",
    }




# ============================================================================
# V82 — SPECIFIC COURT CATALOG + TODAY AVAILABILITY AS ONE VERIFIED BUNDLE
# ============================================================================
# V81 resolvió correctamente la continuidad semántica entre turnos. El caso
# restante era el PRIMER turno: Perception ya había producido query_policy +
# query_availability(resource_types=[...]), pero Planner/Composer podían priorizar
# el catálogo y ocultar la agenda. V82 no reinterpreta deportes con Python.
# Consume exclusivamente el resource_type ya decidido por IA/SemanticFrame y
# validado contra config.COURTS, asegura el READ de calendario y renderiza ambos
# resultados como una única respuesta determinista.


def _agent_v2_v82_specific_court_catalog_bundle(
    perception: Optional[Dict[str, Any]],
    world: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    perception = perception or {}
    contract = (
        perception.get("execution_contract")
        if isinstance(perception.get("execution_contract"), dict)
        else {}
    )
    acts = [
        act for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    ]
    if not acts:
        acts = [
            act for act in (_agent_v2_semantic_frame(perception).get("acts") or [])
            if isinstance(act, dict)
        ]

    policy_acts = []
    availability_acts = []
    for act in acts:
        operation = str(act.get("operation") or "")
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        if str(target.get("resource") or "") != "court":
            continue
        if operation == "query_policy":
            facts = {
                str(value or "").strip()
                for value in (act.get("requested_facts") or [])
                if str(value or "").strip()
            }
            if not facts or facts.intersection({"court.catalog", "court.types"}):
                policy_acts.append(act)
        elif operation == "query_availability":
            availability_acts.append(act)

    if not policy_acts or not availability_acts:
        return None

    # El scope debe provenir del frame estructurado; jamás del texto libre.
    selected_act = None
    resource_types: List[str] = []
    for act in availability_acts:
        scoped = _agent_v2_v81_resource_types_for_availability_act(
            act,
            perception,
            world or {},
        )
        if scoped:
            selected_act = act
            resource_types = scoped
            break
    if not selected_act or not resource_types:
        return None

    # No interceptamos comparaciones/características detalladas: esas siguen
    # perteneciendo al renderer de Policy Fact Contract.
    policy_facts = {
        str(value or "").strip()
        for act in policy_acts
        for value in (act.get("requested_facts") or [])
        if str(value or "").strip()
    }
    if policy_facts.intersection({
        "court.differences", "court.features", "court.characteristics",
        "court.details", "court.comparison",
    }):
        return None

    temporal = (
        selected_act.get("temporal")
        if isinstance(selected_act.get("temporal"), dict)
        else {}
    )
    entities = (
        perception.get("entities")
        if isinstance(perception.get("entities"), dict)
        else {}
    )
    day = (
        entities.get("dia_resuelto")
        or entities.get("dia")
        or temporal.get("day")
    )
    if not day:
        day = resolver_fecha(datetime.datetime.now(TIMEZONE).date().isoformat())
    else:
        day = resolver_fecha(str(day))

    return {
        "policy_act": policy_acts[0],
        "availability_act": selected_act,
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "dia": day,
    }


_agent_v2_tool_first_read_plan_v81 = _agent_v2_tool_first_read_plan


def _agent_v2_tool_first_read_plan(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
) -> Optional[Dict[str, Any]]:
    """V82: el bundle catálogo específico + agenda de hoy siempre ejecuta ambos READs."""
    plan = _agent_v2_tool_first_read_plan_v81(
        world,
        perception,
        goals,
        observations,
    )
    bundle = _agent_v2_v82_specific_court_catalog_bundle(perception, world)
    if not bundle:
        return plan

    # V85 — Planner nunca amplía permisos. El bundle sólo puede materializar la
    # consulta de agenda si ExecutionContract ya autorizó AMBOS READs. Si esta
    # invarianta falla, devolvemos el plan original y dejamos evidencia en log;
    # Policy Guard sigue siendo la última frontera de seguridad.
    contract = (perception or {}).get("execution_contract") or {}
    contract_ops = {
        str(act.get("operation") or "")
        for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    }
    allowed_tools = set(contract.get("allowed_tools") or [])
    if not (
        contract.get("authoritative") is True
        and {"query_policy", "query_availability"}.issubset(contract_ops)
        and {"consultar_informacion_negocio", "consultar_disponibilidad"}.issubset(allowed_tools)
    ):
        print(
            "   🛡️ [AgentV2 V85 BUNDLE PLAN FAIL-CLOSED] "
            f"ops={sorted(contract_ops)} allowed_tools={sorted(allowed_tools)}"
        )
        return plan

    fixed = dict(plan or {})
    steps = [
        dict(step) for step in (fixed.get("steps") or [])
        if isinstance(step, dict)
    ]

    # Un solicitar_dato de día/día+hora es incorrecto para este bundle: V80/V82
    # definieron explícitamente HOY como default informativo, no como una elección
    # de reserva del usuario.
    steps = [
        step for step in steps
        if not (
            str(step.get("tool") or "") == "solicitar_dato"
            and str((step.get("args") or {}).get("campo") or "")
            in {"dia", "dia_hora_reserva"}
        )
    ]

    policy_act = bundle["policy_act"]
    if not any(str(step.get("tool") or "") == "consultar_informacion_negocio" for step in steps):
        info_args = {
            **_agent_v2_policy_fact_request_for_act(policy_act),
            "pregunta": (world or {}).get("message") or "",
        }
        steps.insert(0, {
            "tool": "consultar_informacion_negocio",
            "args": info_args,
            "reason": "V82 catálogo configurado del mismo turno",
            "replan_after": False,
        })

    availability_act = bundle["availability_act"]
    availability_args = _agent_v2_v81_availability_args_from_act(
        availability_act,
        perception,
        world,
        force_today=True,
    )
    availability_args["dia"] = bundle.get("dia") or availability_args.get("dia")
    availability_args["resource_types"] = list(bundle["resource_types"])
    availability_args["resource_type"] = bundle.get("resource_type")
    availability_args["cancha"] = None

    existing_availability_index = next((
        index for index, step in enumerate(steps)
        if str(step.get("tool") or "") == "consultar_disponibilidad"
    ), None)
    availability_step = {
        "tool": "consultar_disponibilidad",
        "args": availability_args,
        "reason": "V82 disponibilidad de hoy del resource_type verificado",
        "replan_after": False,
    }
    if existing_availability_index is None:
        steps.append(availability_step)
    else:
        steps[existing_availability_index] = availability_step

    # Policy primero y agenda al final. Si la agenda abre selección de hora, el
    # executor ya habrá resuelto el catálogo y conservará ambas Observations.
    steps = [
        step for step in steps
        if str(step.get("tool") or "") != "consultar_disponibilidad"
    ] + [availability_step]

    deduped: List[Dict[str, Any]] = []
    seen = set()
    for step in steps:
        signature = json.dumps(
            {"tool": step.get("tool"), "args": step.get("args") or {}},
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
        if signature in seen:
            continue
        seen.add(signature)
        deduped.append(step)

    fixed["steps"] = deduped[:AGENT_V2_MAX_PLAN_STEPS]
    fixed["reason"] = "V82 specific court catalog + today availability bundle"
    print(
        "   🎾 [AgentV2 V82 FIRST-TURN BUNDLE PLAN] "
        f"resource_types={bundle['resource_types']} dia={bundle.get('dia')} "
        "→ catalog + consultar_disponibilidad"
    )
    return fixed


def _agent_v2_v82_catalog_message_from_config() -> str:
    """Renderiza el catálogo desde config viva, sin releer lenguaje del usuario."""
    try:
        business = _business_knowledge_snapshot()
        contract = _agent_v2_court_catalog_contract(
            "",
            business,
            requested_facts=["court.catalog", "court.types"],
        )
        return build_agent_v2_policy_fact_message({
            "data": {"policy_fact_contract": contract}
        }).strip()
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V82 CATALOG RENDER] "
            f"no pude renderizar config viva: {type(exc).__name__}: {exc}"
        )
        return ""


def _agent_v2_v82_catalog_today_availability_message(
    mensaje: str,
    world: Dict,
    perception: Dict,
    observations: List[Dict],
) -> str:
    """Une catálogo y agenda filtrada cuando ambas pertenecen al mismo bundle."""
    bundle = _agent_v2_v82_specific_court_catalog_bundle(perception, world)
    if not bundle:
        return ""

    availability_obs = next((
        obs for obs in reversed(observations or [])
        if isinstance(obs, dict)
        and obs.get("tool") == "consultar_disponibilidad"
        and obs.get("ok")
        and (
            (obs.get("data") or {}).get("canchas_libres_por_franja")
            or isinstance((obs.get("data") or {}).get("day_availability"), dict)
        )
    ), None)
    if not availability_obs:
        return ""

    # Defensa de alcance: aunque la tool ya filtra por resource_types, nunca
    # renderizamos una cancha incompatible con el scope semántico del bundle.
    obs_copy = dict(availability_obs)
    data = dict(obs_copy.get("data") or {})
    nested = (
        dict(data.get("day_availability") or {})
        if isinstance(data.get("day_availability"), dict)
        else {}
    )
    schedule_key_owner = data if data.get("canchas_libres_por_franja") else nested
    raw_schedule = dict(schedule_key_owner.get("canchas_libres_por_franja") or {})
    filtered_schedule = {
        str(court): list(hours or [])
        for court, hours in raw_schedule.items()
        if _court_matches_resource_types(str(court), bundle["resource_types"])
    }
    if raw_schedule and not filtered_schedule:
        return ""
    if raw_schedule:
        schedule_key_owner["canchas_libres_por_franja"] = filtered_schedule
        filtered_hours = sorted({
            normalizar_hora_detectada(hour)
            for hours in filtered_schedule.values()
            for hour in (hours or [])
            if hora_es_valida(normalizar_hora_detectada(hour))
        }, key=lambda value: _hora_a_minutos(value))
        schedule_key_owner["horas_disponibles"] = filtered_hours
        if schedule_key_owner is nested:
            data["day_availability"] = nested
        else:
            data.update(schedule_key_owner)
        obs_copy["data"] = data

    policy_obs = _agent_v2_policy_contract_observation(observations)
    catalog_message = (
        build_agent_v2_policy_fact_message(policy_obs).strip()
        if policy_obs
        else _agent_v2_v82_catalog_message_from_config()
    )
    if not catalog_message:
        return ""

    # El renderer clásico exige una pregunta de hora para consultas que no eran
    # originalmente broad-availability. Creamos sólo ese estado de RENDER local;
    # no se persiste ni altera la conversación.
    render_world = dict(world or {})
    render_questions = [
        dict(question) for question in ((world or {}).get("open_questions") or [])
        if isinstance(question, dict)
    ]
    if not any(str(question.get("field") or "") == "hora" for question in render_questions):
        render_questions.append({
            "field": "hora",
            "booking_choice": True,
            "source": "v82_specific_court_catalog_bundle_renderer",
        })
    render_world["open_questions"] = render_questions

    observations_for_render = [
        obs_copy if obs is availability_obs else obs
        for obs in (observations or [])
    ]
    availability_message = build_agent_v2_detailed_availability_price_message(
        mensaje,
        render_world,
        observations_for_render,
        perception,
    ).strip()
    if not availability_message:
        availability_message = _agent_v2_format_availability_observation(
            obs_copy.get("data") or {}
        ).strip()
    if not availability_message:
        return ""

    # V83 — el saludo institucional, si el renderer clásico lo agregó, siempre
    # debe ser el PRIMER bloque de la respuesta. V82 concatenaba catálogo antes
    # de availability_message y por eso podía quedar catálogo → saludo → agenda.
    # No inferimos saludos con regex ni keywords nuevas: sólo movemos el prefijo
    # institucional exacto que el propio renderer de disponibilidad ya decidió
    # emitir para este turno.
    institutional_greeting = (
        f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}."
    )
    availability_body = availability_message
    greeting_first = False
    if availability_body.startswith(institutional_greeting):
        availability_body = availability_body[len(institutional_greeting):].lstrip()
        greeting_first = True

    print(
        "   🎾 [AgentV2 V83 FIRST-TURN BUNDLE COMPOSER] "
        f"resource_types={bundle['resource_types']} "
        f"greeting_first={greeting_first} → saludo + catálogo + disponibilidad"
    )

    blocks = []
    if greeting_first:
        blocks.append(institutional_greeting)
    blocks.append(catalog_message)
    if availability_body:
        blocks.append(availability_body)
    return "\n\n".join(block.strip() for block in blocks if block.strip()).strip()




# ============================================================================
# V84 — BUNDLE EXECUTION-CONTRACT AUTHORITY
# ============================================================================
def _agent_v2_v84_authorize_specific_court_catalog_bundle_contract(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    """Congela catálogo + disponibilidad dentro del contrato, no en Planner.

    V82 podía reconstruir ``consultar_disponibilidad`` después del contrato. Eso
    era incorrecto: Policy Guard debía bloquearla si ExecutionContract no la
    autorizaba. V84 conserva esa defensa y mueve la reparación al borde correcto.

    La función sólo actúa cuando existe la marca estructurada creada por
    ``_agent_v2_apply_court_catalog_perception_authority`` o el act SYSTEM
    inequívoco ``court_type_today_availability_v80``. Nunca interpreta deportes,
    saludos ni intención desde texto libre.
    """
    clean = dict(perception or {})
    marker = (
        clean.get("_specific_court_catalog_today_bundle")
        if isinstance(clean.get("_specific_court_catalog_today_bundle"), dict)
        else {}
    )
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    raw_acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict)
    ]

    special_act = next((
        dict(act) for act in raw_acts
        if str(act.get("act_id") or "") == "court_type_today_availability_v80"
        and str(act.get("operation") or "") == "query_availability"
    ), None)
    if not marker and special_act is None:
        return clean

    resource_types = _canonical_configured_court_types(
        (marker.get("resource_types") or [])
        or (
            ((special_act or {}).get("target") or {}).get("resource_types")
            if isinstance((special_act or {}).get("target"), dict)
            else []
        )
        or _agent_v2_resource_type_constraints(clean, world or {})
    )
    if not resource_types:
        return clean

    policy_act = next((
        dict(act) for act in raw_acts
        if str(act.get("operation") or "") == "query_policy"
        and str(((act.get("target") or {}).get("resource") or "")) == "court"
    ), None)
    if policy_act is None:
        return clean

    # El catálogo es un hecho config-grounded; normalizamos su dirección factual
    # si el primer pase IA la había dejado incompleta.
    policy_target = dict(policy_act.get("target") or {})
    policy_target.update({
        "resource": "court",
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
    })
    policy_act["target"] = policy_target
    policy_act["domain"] = str(policy_act.get("domain") or "business")
    policy_facts = [
        str(value or "").strip()
        for value in (policy_act.get("requested_facts") or [])
        if str(value or "").strip()
    ]
    for fact in ("court.catalog", "court.types"):
        if fact not in policy_facts:
            policy_facts.append(fact)
    policy_act["requested_facts"] = policy_facts
    policy_act["commitment"] = {"wants_write": False, "wants_information": True}

    day = str(marker.get("dia") or "").strip()
    if not day:
        today_iso = datetime.datetime.now(TIMEZONE).date().isoformat()
        day = resolver_fecha(today_iso)

    availability_act = dict(special_act or {})
    if not availability_act:
        availability_act = {
            "act_id": "court_type_today_availability_v80",
            "operation": "query_availability",
            "domain": "booking",
            "target": {},
            "temporal": {},
            "quantity": {"duration_hours": DEFAULT_TURN_DURATION_HOURS, "count": None},
            "changes": [],
            "provenance": [],
            "requested_facts": ["available_slots"],
            "commitment": {"wants_write": False, "wants_information": True},
            "selection": {},
        }

    availability_target = dict(availability_act.get("target") or {})
    availability_target.update({
        "resource": "court",
        "reservation_id": None,
        "selection_policy": "any_available",
        "source": "current_user_turn",
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
    })
    availability_act["target"] = availability_target
    availability_act["domain"] = "booking"
    availability_act["operation"] = "query_availability"
    availability_act["act_id"] = "court_type_today_availability_v80"
    availability_temporal = dict(availability_act.get("temporal") or {})
    availability_temporal.update({
        "day": day,
        "start": None,
        "end": None,
        "times": [],
        "daypart": None,
        "duration_hours": (
            availability_temporal.get("duration_hours")
            or DEFAULT_TURN_DURATION_HOURS
        ),
        "structure": availability_temporal.get("structure") or "single",
    })
    availability_act["temporal"] = availability_temporal
    availability_act["requested_facts"] = ["available_slots"]
    availability_act["commitment"] = {"wants_write": False, "wants_information": True}

    provenance = [
        dict(item) for item in (availability_act.get("provenance") or [])
        if isinstance(item, dict)
    ]
    if not any(str(item.get("field") or "") == "target.resource_types" for item in provenance):
        provenance.append({
            "field": "target.resource_types",
            "source": "current_user_turn",
            "evidence": str(mensaje or "")[:500],
            "question_id": None,
            "option_id": None,
            "reference_id": None,
        })
    if not any(str(item.get("field") or "") == "temporal.day" for item in provenance):
        provenance.append({
            "field": "temporal.day",
            "source": "world_fact",
            "evidence": "business_clock.proactive_today_for_specific_court_catalog",
            "reference_id": None,
        })
    availability_act["provenance"] = provenance

    # Reemplazar únicamente los dos READs del bundle; conservar cualquier otro act
    # semántico independiente del mismo turno.
    preserved = [
        dict(act) for act in raw_acts
        if not (
            str(act.get("operation") or "") == "query_policy"
            and str(((act.get("target") or {}).get("resource") or "")) == "court"
        )
        and str(act.get("act_id") or "") != "court_type_today_availability_v80"
    ]
    frame["acts"] = [policy_act, availability_act, *preserved]
    frame["targets"] = [
        dict(act.get("target") or {})
        for act in frame["acts"]
        if isinstance(act.get("target"), dict)
    ]
    frame["requested_facts"] = list(dict.fromkeys([
        *(frame.get("requested_facts") or []),
        "court.catalog", "court.types", "available_slots",
    ]))
    frame["commitment"] = {"wants_write": False, "wants_information": True}
    frame["source"] = "system_config_grounding"
    frame["schema_valid"] = True
    clean["semantic_frame"] = frame

    entities = dict(clean.get("entities") or {})
    entities.update({
        "dia": day,
        "dia_resuelto": day,
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
    })
    clean["entities"] = entities

    domains = list(_agent_v2_normalize_question_domains(clean))
    for domain in ("court_catalog", "availability"):
        if domain not in domains:
            domains.append(domain)
    clean["question_domains"] = domains

    # V85 — el primer pase READ pudo entrar en modo degradado porque la IA
    # dejó query_policy sin dirección factual. A esta altura ese problema ya no
    # existe: system_config_grounding verificó el catálogo desde config.COURTS,
    # el resource_type configurado y agregó query_availability con available_slots
    # + día HOY proveniente del reloj del negocio. Mantener el recovery viejo haría
    # que ExecutionContract reduzca allowed_tools a consultar_informacion_negocio
    # y bloquee precisamente el READ que acabamos de groundear. Cerramos SOLO este
    # recovery scoped; no relajamos la protección global para otros READs.
    if clean.get("read_grounding_recovery"):
        clean["read_grounding_recovery"] = False
        clean["read_meaning_repair_needed"] = False
        clean.pop("read_recovery_reason", None)
        print(
            "   🧹 [AgentV2 V85 READ RECOVERY CLOSED] "
            f"resource_types={resource_types} dia={day} source=system_config_grounding"
        )

    repaired_contract = _agent_v2_build_execution_contract(clean, world or {})
    contract_ops = {
        str(act.get("operation") or "")
        for act in (repaired_contract.get("acts") or [])
        if isinstance(act, dict)
    }
    required_ops = {"query_policy", "query_availability"}
    if not required_ops.issubset(contract_ops):
        print(
            "   🚫 [AgentV2 V85 BUNDLE CONTRACT] reparación rechazada; "
            f"contract_ops={sorted(contract_ops)} required={sorted(required_ops)}"
        )
        return clean

    allowed_tools = set(repaired_contract.get("allowed_tools") or [])
    if "consultar_disponibilidad" not in allowed_tools:
        print(
            "   🚫 [AgentV2 V85 BUNDLE CONTRACT] contrato sin tool de disponibilidad; "
            f"allowed_tools={sorted(allowed_tools)}"
        )
        return clean

    clean["execution_contract"] = repaired_contract
    clean["semantic_clarification_required"] = False
    clean.pop("semantic_clarification", None)
    clean["_specific_court_catalog_today_bundle"] = {
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "dia": day,
        "source": "system_config_grounding",
    }
    print(
        "   🧾 [AgentV2 V85 BUNDLE CONTRACT] "
        f"resource_types={resource_types} dia={day} "
        f"ops={sorted(contract_ops)} tools={sorted(allowed_tools)}"
    )
    return clean


