# ============================================================
# V86 — DYNAMIC RESCHEDULE CONTINUITY
# ============================================================
# Objetivo:
#   1) Un WRITE reschedule_booking verificado sobre la única reserva real se
#      ejecuta sin una confirmación redundante.
#   2) Si por una ambigüedad real el agente pregunta si debe proceder, esa
#      pregunta se persiste como contrato stateful y una respuesta posterior
#      se resuelve semánticamente contra question_id/scope_id. No hay regex de
#      afirmación ni keywords de intención.


def _agent_v2_v86_verified_reschedule_act(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """Devuelve el único reschedule WRITE que el Effect Verifier ya autorizó."""
    verification = (
        (perception or {}).get("semantic_effect_verification")
        if isinstance((perception or {}).get("semantic_effect_verification"), dict)
        else {}
    )
    if verification.get("status") != "verified":
        return None
    authorized_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }
    acts = [
        dict(act)
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "reschedule_booking"
        and str(act.get("act_id") or "").strip() in authorized_ids
        and bool((act.get("commitment") or {}).get("wants_write"))
    ]
    if len(acts) != 1:
        return None

    act = acts[0]
    real = [
        dict(row)
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
    ]
    if not real:
        return None

    target = dict(act.get("target") or {}) if isinstance(act.get("target"), dict) else {}
    rid = str(target.get("reservation_id") or "").strip()
    if not rid and len(real) == 1:
        rid = str(_agent_v2_reservation_id(real[0]) or real[0].get("reservation_id") or "").strip()
    if not rid:
        return None
    row = next((
        item for item in real
        if str(_agent_v2_reservation_id(item) or item.get("reservation_id") or "").strip() == rid
    ), None)
    if not row:
        return None

    clean = dict(act)
    clean_target = dict(target)
    clean_target.update({
        "resource": "reservation",
        "reservation_id": rid,
        "source": "world_fact",
    })
    clean["target"] = clean_target
    return clean


def _agent_v2_v86_semantic_clarification_pending_payload(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    semantic_clarification: Dict[str, Any],
) -> Dict[str, Any]:
    """Construye una pregunta stateful específica si el WRITE ya fue verificado.

    No interpreta el texto del usuario. Sólo convierte evidencia estructurada ya
    producida por Perception + Effect Verifier en memoria conversacional durable.
    """
    clarification = dict(semantic_clarification or {})
    fallback = {
        "field": clarification.get("field") or "operation",
        "options": clarification.get("alternatives") or [],
        "goal_context": ["otro"],
        "source": "semantic_adjudicator",
        "reason": clarification.get("reasons") or [],
    }
    act = _agent_v2_v86_verified_reschedule_act(perception or {}, world or {})
    if not act:
        return fallback

    target = dict(act.get("target") or {})
    temporal = dict(act.get("temporal") or {})
    rid = str(target.get("reservation_id") or "").strip()
    start = normalizar_hora_detectada(temporal.get("start"))
    if not rid or not hora_es_valida(start):
        return fallback

    real = next((
        dict(row)
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
        and str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "").strip() == rid
    ), {})
    day = str(temporal.get("day") or real.get("fecha") or real.get("dia") or "").strip()

    return {
        "field": "confirmar_reprogramacion",
        "type": "confirmar_reprogramacion",
        "options": [],
        "goal_context": ["reprogramar_reserva"],
        "source": "semantic_adjudicator_verified_write",
        "reason": clarification.get("reasons") or [],
        "operation": "reschedule_booking",
        "reservation_id": rid,
        "dia": day,
        "hora": start,
        "cancha": real.get("cancha"),
        "duracion_horas": (
            (act.get("quantity") or {}).get("duration_hours")
            or temporal.get("duration_hours")
            or real.get("duracion_horas")
            or DEFAULT_TURN_DURATION_HOURS
        ),
        "operation_contract": act,
        "source_message": str((world or {}).get("message") or "")[:500],
    }


def _agent_v2_v86_active_reschedule_confirmation_questions(
    world: Dict[str, Any],
) -> List[Dict[str, Any]]:
    stored = _agent_v2_stored_memory(world or {})
    expected_owner = str(((world or {}).get("facts") or {}).get("memory_owner") or "").strip()
    out = []
    for raw in (stored.get("pending_decisions") or []):
        if not isinstance(raw, dict):
            continue
        q = dict(raw)
        if str(q.get("field") or "") != "confirmar_reprogramacion":
            continue
        owner = str(q.get("_memory_owner") or "").strip()
        if expected_owner and owner and owner != expected_owner:
            continue
        if str(q.get("operation") or "") != "reschedule_booking":
            continue
        if not str(q.get("question_id") or "").strip() or not str(q.get("scope_id") or "").strip():
            continue
        if not isinstance(q.get("operation_contract"), dict):
            continue
        out.append(q)
    return out


# ContextAuthorization: una confirmación enlazada a SU pregunta puede apuntar
# a la reserva del contrato pendiente. El texto actual nunca elige la reserva.
_agent_v2_context_authorization_v85 = _agent_v2_context_authorization


def _agent_v2_context_authorization(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    auth = dict(_agent_v2_context_authorization_v85(perception, world) or {})
    if not auth.get("authorized"):
        return auth
    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame)
    if str(relation.get("type") or "") != "answers_pending":
        return auth
    qid = str(relation.get("question_id") or "").strip()
    if not qid:
        return auth
    question = next((
        q for q in _agent_v2_v86_active_reschedule_confirmation_questions(world or {})
        if str(q.get("question_id") or "").strip() == qid
    ), None)
    if not question:
        return auth
    operations = {
        str(act.get("operation") or "")
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
    }
    if operations != {"reschedule_booking"}:
        return {**auth, "authorized": False, "reason": "reschedule_confirmation_operation_mismatch"}
    rid = str(question.get("reservation_id") or "").strip()
    real_ids = {
        str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "").strip()
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
    }
    if not rid or rid not in real_ids:
        return {**auth, "authorized": False, "reason": "reschedule_confirmation_reservation_missing"}
    auth["reference_id"] = rid
    auth["reason"] = "verified_pending_reschedule_confirmation_binding"
    return auth


# V86 wraps the latest V85/V80 resolver. A bare answer is not classified by
# Python; a small semantic adjudicator decides whether it confirms the exact
# persisted action question.
_agent_v2_resolve_context_reference_v85 = _agent_v2_resolve_context_reference


async def _agent_v2_resolve_context_reference(
    mensaje: str,
    first_perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    resolved = await _agent_v2_resolve_context_reference_v85(
        mensaje, first_perception, world
    )
    existing = (
        resolved.get("context_resolution")
        if isinstance(resolved.get("context_resolution"), dict)
        else {}
    )
    if existing.get("resolved"):
        return resolved

    candidates = _agent_v2_v86_active_reschedule_confirmation_questions(world or {})
    if len(candidates) != 1:
        return resolved
    question = candidates[0]
    qid = str(question.get("question_id") or "").strip()
    scope_id = str(question.get("scope_id") or "").strip()
    rid = str(question.get("reservation_id") or "").strip()

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos ACTION CONFIRMATION RESOLVER. Decidí si el current_user_turn "
                        "responde la pregunta pendiente del agente sobre ejecutar UNA reprogramación "
                        "ya estructurada. Interpretá el significado completo, no palabras aisladas. "
                        "decision debe ser confirm, deny o unrelated. confirm sólo si el usuario "
                        "acepta inequívocamente proceder con ESA acción; deny si la rechaza; unrelated "
                        "si pregunta/cambia de tema. evidence debe ser una cita literal no vacía del "
                        "current_user_turn. No inventes operaciones, horarios, IDs ni datos. Respondé "
                        "sólo JSON: {decision:string,evidence:string,reason:string}."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "pending_question": {
                            "question_id": qid,
                            "scope_id": scope_id,
                            "operation": "reschedule_booking",
                            "reservation_id": rid,
                            "dia": question.get("dia"),
                            "hora": question.get("hora"),
                            "cancha": question.get("cancha"),
                        },
                        "first_semantic_frame": _agent_v2_semantic_frame(resolved),
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        decision = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V86 ACTION CONTINUITY] "
            f"sin decisión segura: {type(exc).__name__}: {exc}"
        )
        return resolved

    evidence = str(decision.get("evidence") or "").strip()
    if not evidence or normalizar_texto_ia(evidence) not in normalizar_texto_ia(mensaje or ""):
        return resolved
    if str(decision.get("decision") or "").strip().lower() != "confirm":
        return resolved

    act = dict(question.get("operation_contract") or {})
    act_id = str(act.get("act_id") or "reschedule_pending_confirmation").strip()
    act["act_id"] = act_id
    act["operation"] = "reschedule_booking"
    act["domain"] = "reservation"
    target = dict(act.get("target") or {})
    target.update({
        "resource": "reservation",
        "reservation_id": rid,
        "source": "world_fact",
    })
    act["target"] = target
    act["commitment"] = {
        **dict(act.get("commitment") or {}),
        "wants_write": True,
        "wants_information": False,
    }
    provenance = [
        dict(item) for item in (act.get("provenance") or [])
        if isinstance(item, dict)
        and str(item.get("source") or "") != "pending_option"
    ]
    provenance.append({
        "field": "operation_confirmation",
        "source": "pending_option",
        "evidence": evidence,
        "question_id": qid,
        "scope_id": scope_id,
        "option_id": None,
        "reference_id": rid,
    })
    act["provenance"] = provenance

    frame = dict(_agent_v2_semantic_frame(resolved) or {})
    frame.update({
        "turn_type": "confirmation",
        "intent": {"domain": "reservation", "operation": "reschedule_booking"},
        "targets": [dict(target)],
        "temporal": dict(act.get("temporal") or {}),
        "requested_changes": list(act.get("changes") or []),
        "requested_facts": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "context_relation": {
            "type": "answers_pending",
            "question_id": qid,
            "references_previous_user_turn": False,
            "references_agent_offer": True,
            "answers_pending_question": True,
        },
        "acts": [act],
        "ambiguity": {"required": False, "field": None, "reason": "", "alternatives": []},
    })
    clean = dict(resolved or {})
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "answers_pending"
    clean["answers_pending_field"] = "confirmar_reprogramacion"
    clean["context_request"] = {
        "needed": True,
        "relation": "answers_pending",
        "candidate_types": ["pending_operation_confirmation"],
        "reason": "verified_agent_action_confirmation",
    }
    clean["context_resolution"] = {
        "requested": True,
        "resolved": True,
        "relation": "answers_pending",
        "question_id": qid,
        "reference_id": rid,
        "scope_id": scope_id,
        "resolved_value": "confirm",
        "reason": str(decision.get("reason") or "semantic_action_confirmation"),
    }
    clean["reference_resolution"] = {
        "source": "pending_question",
        "resolved": True,
        "reference_id": rid,
        "question_id": qid,
        "scope_id": scope_id,
    }
    print(
        "   ✅ [AgentV2 V86 ACTION CONTINUITY] "
        f"question_id={qid} operation=reschedule_booking reservation_id={rid} "
        f"evidence={evidence!r}"
    )
    return clean


def _agent_v2_v86_reschedule_confirmation_authorization(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame)
    if not (
        str(relation.get("type") or "") == "answers_pending"
        and relation.get("answers_pending_question") is True
        and relation.get("references_agent_offer") is True
    ):
        return None
    qid = str(relation.get("question_id") or "").strip()
    question = next((
        q for q in _agent_v2_v86_active_reschedule_confirmation_questions(world or {})
        if str(q.get("question_id") or "").strip() == qid
    ), None)
    if not question:
        return None
    scope_id = str(question.get("scope_id") or "").strip()
    rid = str(question.get("reservation_id") or "").strip()
    acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") == "reschedule_booking"
    ]
    if len(acts) != 1:
        return None
    act = acts[0]
    if str((act.get("target") or {}).get("reservation_id") or "").strip() != rid:
        return None
    if not any(
        isinstance(item, dict)
        and str(item.get("field") or "") == "operation_confirmation"
        and str(item.get("source") or "") == "pending_option"
        and str(item.get("question_id") or "").strip() == qid
        and str(item.get("scope_id") or "").strip() == scope_id
        for item in (act.get("provenance") or [])
    ):
        return None
    real_ids = {
        str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "").strip()
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
    }
    if rid not in real_ids:
        return None
    return {
        "act_id": str(act.get("act_id") or ""),
        "authorized": True,
        "evidence_type": "pending_option",
        "evidence": "semantic confirmation of persisted reschedule action",
        "question_id": qid,
        "option_id": None,
    }


# ContextResolver already made the linguistic decision. From here on Python only
# validates the stateful identity and grants the same narrow write authority.
_agent_v2_verify_semantic_effects_v85 = _agent_v2_verify_semantic_effects


async def _agent_v2_verify_semantic_effects(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    pending_auth = _agent_v2_v86_reschedule_confirmation_authorization(
        perception or {}, world or {}
    )
    if pending_auth:
        clean = dict(perception or {})
        clean["semantic_effect_verification"] = {
            "status": "verified",
            "verified_operations": ["reschedule_booking"],
            "write_authorizations": [pending_auth],
            "mode": "verified_pending_reschedule_confirmation",
        }
        print(
            "   ⚖️ [AgentV2 V86 PENDING WRITE AUTHORITY] "
            f"reschedule_booking act_id={pending_auth.get('act_id')} "
            f"question_id={pending_auth.get('question_id')}"
        )
        return clean
    return await _agent_v2_verify_semantic_effects_v85(
        mensaje, perception, world
    )




# ============================================================
# V87 — SEMANTIC FREEZE / LLM BUDGET
# ============================================================
# PRINCIPIO:
#   IA entiende una vez. Python valida hechos/estado. Una vez que el
#   ExecutionContract es autoritativo y todo WRITE quedó verificado, las capas
#   posteriores NO vuelven a reinterpretar intención, target ni compromiso.
#
# El freeze NO desactiva Policy, tools, calendario, money guards ni validators
# deterministas. Sólo permite omitir llamadas LLM redundantes cuando ya existe
# una autoridad estructurada suficiente.

AGENT_V2_SEMANTIC_FREEZE_VERSION = "v87"

_AGENT_V2_V87_EXISTING_RESERVATION_WRITES = {
    "reschedule_booking",
    "cancel_booking",
    "modify_resource",
    "add_resource",
    "remove_resource",
    "choose_payment_method",
}

_AGENT_V2_V87_TERMINAL_FAST_PATH_OPERATIONS = {
    "reschedule_booking",
    "cancel_booking",
    "modify_resource",
    "add_resource",
    "remove_resource",
    "choose_payment_method",
}


def _agent_v2_v87_current_turn_has_explicit_day_semantics(
    perception: Dict[str, Any],
) -> bool:
    """Sólo inspecciona provenance/mentions ya producidos por IA; no parsea texto."""
    data = perception if isinstance(perception, dict) else {}
    for item in data.get("temporal_mentions") or []:
        if not isinstance(item, dict):
            continue
        if (
            str(item.get("kind") or "").strip().casefold() == "day"
            and bool(str(item.get("evidence") or "").strip())
        ):
            return True

    frame = _agent_v2_semantic_frame(data)
    for act in frame.get("acts") or []:
        if not isinstance(act, dict):
            continue
        for item in act.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            if (
                str(item.get("source") or "").strip().casefold() == "current_user_turn"
                and str(item.get("field") or "").strip().casefold()
                in {"temporal.day", "day", "dia"}
                and bool(str(item.get("evidence") or "").strip())
            ):
                return True
    return False


def _agent_v2_v87_real_reservation_map(world: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    rows = (((world or {}).get("facts") or {}).get("reservas_reales") or [])
    out: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        rid = str(
            _agent_v2_reservation_id(row)
            or row.get("reservation_id")
            or ""
        ).strip()
        if rid:
            out[rid] = dict(row)
    return out


def _agent_v2_v87_ground_reschedule_unchanged_day(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Si el usuario sólo cambia hora, preserva el día de ESA reserva real.

    Esto no interpreta lenguaje. La ausencia/presencia de día ya viene de la
    semántica estructurada; Python sólo evita que un default "hoy" de una
    solicitud autónoma pueda mover accidentalmente una reprogramación existente.
    """
    clean = dict(perception or {})
    if _agent_v2_v87_current_turn_has_explicit_day_semantics(clean):
        return clean

    contract = clean.get("execution_contract") or {}
    if not isinstance(contract, dict) or not contract.get("authoritative"):
        return clean

    reservation_map = _agent_v2_v87_real_reservation_map(world)
    if not reservation_map:
        return clean

    changed = False
    new_contract_acts = []
    day_by_act_id: Dict[str, str] = {}
    for raw_act in contract.get("acts") or []:
        act = dict(raw_act) if isinstance(raw_act, dict) else raw_act
        if not isinstance(act, dict) or str(act.get("operation") or "") != "reschedule_booking":
            new_contract_acts.append(act)
            continue
        target = dict(act.get("target") or {}) if isinstance(act.get("target"), dict) else {}
        rid = str(target.get("reservation_id") or "").strip()
        row = reservation_map.get(rid) or {}
        existing_day = str(row.get("fecha") or row.get("dia") or "").strip()
        if not existing_day:
            new_contract_acts.append(act)
            continue
        temporal = dict(act.get("temporal") or {}) if isinstance(act.get("temporal"), dict) else {}
        if str(temporal.get("day") or "").strip() != existing_day:
            temporal["day"] = existing_day
            act["temporal"] = temporal
            provenance = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
            ]
            provenance = [
                item for item in provenance
                if str(item.get("field") or "").strip().casefold()
                not in {"temporal.day", "day", "dia"}
            ]
            provenance.append({
                "field": "temporal.day",
                "source": "world_fact",
                "evidence": f"reservation:{rid}.existing_day_preserved",
                "reference_id": rid,
                "question_id": None,
                "option_id": None,
            })
            act["provenance"] = provenance
            changed = True
        day_by_act_id[str(act.get("act_id") or "")] = existing_day
        new_contract_acts.append(act)

    if not changed:
        return clean

    contract_copy = dict(contract)
    contract_copy["acts"] = new_contract_acts
    clean["execution_contract"] = contract_copy

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    frame_acts = []
    for raw_act in frame.get("acts") or []:
        act = dict(raw_act) if isinstance(raw_act, dict) else raw_act
        if not isinstance(act, dict):
            frame_acts.append(act)
            continue
        act_id = str(act.get("act_id") or "")
        if act_id in day_by_act_id:
            temporal = dict(act.get("temporal") or {}) if isinstance(act.get("temporal"), dict) else {}
            temporal["day"] = day_by_act_id[act_id]
            act["temporal"] = temporal
            provenance = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
                and str(item.get("field") or "").strip().casefold()
                not in {"temporal.day", "day", "dia"}
            ]
            rid = str((act.get("target") or {}).get("reservation_id") or "").strip()
            provenance.append({
                "field": "temporal.day",
                "source": "world_fact",
                "evidence": f"reservation:{rid}.existing_day_preserved",
                "reference_id": rid,
                "question_id": None,
                "option_id": None,
            })
            act["provenance"] = provenance
        frame_acts.append(act)
    frame["acts"] = frame_acts
    clean["semantic_frame"] = frame
    print(
        "   📌 [AgentV2 V87 TARGET GROUNDING] "
        "reprogramación sin día nuevo → preservo día de la reserva real"
    )
    return clean


def _agent_v2_v87_semantic_freeze_payload(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    data = perception if isinstance(perception, dict) else {}
    contract = data.get("execution_contract") or {}
    if (
        not isinstance(contract, dict)
        or not contract.get("authoritative")
        or not contract.get("frozen")
        or data.get("semantic_clarification_required")
        or data.get("read_grounding_recovery")
    ):
        return {}

    acts = [
        dict(act) for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    ]
    if not acts:
        return {}

    writes = [
        act for act in acts
        if str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
    ]
    if not writes:
        return {}

    verification = (
        data.get("semantic_effect_verification")
        if isinstance(data.get("semantic_effect_verification"), dict)
        else {}
    )
    if verification.get("status") != "verified":
        return {}

    authorized_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }
    write_ids = {
        str(act.get("act_id") or "").strip()
        for act in writes
        if str(act.get("act_id") or "").strip()
    }
    if not write_ids or not write_ids.issubset(authorized_ids):
        return {}

    relation = contract.get("context_relation") or {}
    if str(relation.get("type") or "") == "answers_pending":
        context_auth = contract.get("authorized_context") or {}
        if not context_auth.get("authorized"):
            return {}

    reservation_map = _agent_v2_v87_real_reservation_map(world)
    operations = []
    targets = {}
    execution_ready = True
    for act in acts:
        operation = str(act.get("operation") or "")
        if operation and operation not in operations:
            operations.append(operation)
        if operation not in AGENT_V2_WRITE_OPERATIONS:
            continue
        act_id = str(act.get("act_id") or "").strip()
        target = dict(act.get("target") or {}) if isinstance(act.get("target"), dict) else {}
        rid = str(target.get("reservation_id") or "").strip()
        if operation in _AGENT_V2_V87_EXISTING_RESERVATION_WRITES:
            if not rid or rid not in reservation_map:
                execution_ready = False
                break
            targets[act_id or operation] = rid
        if operation == "reschedule_booking":
            temporal = dict(act.get("temporal") or {}) if isinstance(act.get("temporal"), dict) else {}
            start = normalizar_hora_detectada(temporal.get("start"))
            day = str(temporal.get("day") or "").strip()
            if not hora_es_valida(start) and not day:
                execution_ready = False
                break

    if not execution_ready:
        return {}

    current_day_semantics = _agent_v2_v87_current_turn_has_explicit_day_semantics(data)
    court_semantic_ops = {
        "query_availability", "query_policy", "query_price", "create_booking"
    }
    needs_resource_scope = any(
        str(act.get("operation") or "") in court_semantic_ops
        and str((act.get("target") or {}).get("resource") or "") == "court"
        and not _agent_v2_resource_type_constraints(data, world)
        for act in acts
        if isinstance(act, dict)
    )
    has_availability_op = any(
        str(act.get("operation") or "") == "query_availability"
        for act in acts
    )
    terminal_fast_path = bool(
        all(
            str(act.get("operation") or "") in _AGENT_V2_V87_TERMINAL_FAST_PATH_OPERATIONS
            for act in writes
        )
        and not any(
            str(act.get("operation") or "") == "create_booking"
            for act in writes
        )
    )

    return {
        "active": True,
        "version": AGENT_V2_SEMANTIC_FREEZE_VERSION,
        "contract_id": str(contract.get("contract_id") or ""),
        "operations": operations,
        "write_act_ids": sorted(write_ids),
        "targets": targets,
        "write_authority": contract.get("write_authority"),
        "lock_intent": True,
        "lock_operations": True,
        "lock_targets": bool(targets),
        "skip_date_resolver": not current_day_semantics,
        "skip_resource_scope_repair": not needs_resource_scope,
        "skip_availability_day_recovery": not has_availability_op,
        "terminal_fast_path": terminal_fast_path,
        "reason": "authoritative_execution_contract_with_verified_writes",
    }


def _agent_v2_v87_attach_semantic_freeze(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = _agent_v2_v87_ground_reschedule_unchanged_day(
        perception or {}, world or {}
    )
    freeze = _agent_v2_v87_semantic_freeze_payload(clean, world or {})
    if not freeze:
        clean.pop("semantic_freeze", None)
        return clean
    clean["semantic_freeze"] = freeze
    print(
        "   🧊 [AgentV2 SEMANTIC FREEZE] "
        f"ops={freeze.get('operations')} targets={freeze.get('targets')} "
        f"terminal_fast_path={freeze.get('terminal_fast_path')}"
    )
    return clean


def _agent_v2_v87_freeze(perception: Dict[str, Any]) -> Dict[str, Any]:
    freeze = (
        (perception or {}).get("semantic_freeze")
        if isinstance((perception or {}).get("semantic_freeze"), dict)
        else {}
    )
    return freeze if freeze.get("active") is True else {}


