async def _agent_v2_resolve_current_turn_date_with_ai(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    freeze = _agent_v2_v87_freeze(perception)
    if freeze and freeze.get("skip_date_resolver"):
        print(
            "   🧊 [AgentV2 SEMANTIC FREEZE] "
            "Date Resolver IA omitido; el turno no aporta un día nuevo"
        )
        return perception
    resolved = await _agent_v2_resolve_current_turn_date_with_ai_v86(
        perception, mensaje, world
    )
    # El resolver temporal puede validar/corregir fecha, pero no adquiere derecho
    # a reinterpretar operación/target. Recalculamos el freeze sobre el contrato
    # resultante para mantener una única frontera de autoridad.
    return _agent_v2_v87_attach_semantic_freeze(resolved, world)


