def _agent_v2_v87_successful_write_observation(
    observations: List[Dict[str, Any]],
) -> bool:
    return any(
        isinstance(obs, dict)
        and obs.get("ok")
        and obs.get("status") in {"success", "already_exists", "confirmed"}
        and (AGENT_V2_TOOL_CATALOG.get(str(obs.get("tool") or ""), {}) or {}).get("effect") == "write"
        for obs in (observations or [])
    )


def _agent_v2_v87_terminal_fast_path_allowed(
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> bool:
    freeze = _agent_v2_v87_freeze(perception)
    return bool(
        freeze
        and freeze.get("terminal_fast_path")
        and _agent_v2_v87_successful_write_observation(observations)
    )


