# ============================================================================
# V91 — EARLY CONTEXTUAL AVAILABILITY RESOLUTION
# ============================================================================
# V90 todavía dependía de que Perception clasificara el follow-up dentro de una
# forma demasiado estrecha y de que availability_context pudiera reconstruir un
# reference_id exacto desde historial. V91 trata availability_context como lo que
# realmente es: memoria pasiva creada por una Observation REAL de calendario.
#
# Una sola IA estrecha decide si el turno actual continúa ESA consulta de
# disponibilidad. Python valida TTL/tipos/provenance y proyecta un READ puro.
# No hay regex ni keywords para inferir deporte, intención o continuidad.

AGENT_V2_CONTEXTUAL_AVAILABILITY_VERSION = "v91"


def _agent_v2_v91_verified_availability_focus(
    world: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    stored = _agent_v2_stored_memory(world or {})
    availability = dict(stored.get("availability_context") or {})
    if not availability:
        return None

    created_at = _parse_context_timestamp(availability.get("created_at"))
    now = datetime.datetime.now(TIMEZONE)
    if created_at:
        age = (now - created_at).total_seconds()
        if age < 0 or age > PENDING_AVAILABILITY_CONTEXT_TTL_MINUTES * 60:
            return None

    day_label = str(
        availability.get("dia")
        or availability.get("dia_resuelto")
        or availability.get("dia_consulta")
        or ""
    ).strip()
    day_obj = _parse_fecha_row(day_label) if day_label else None
    day_iso = day_obj.isoformat() if day_obj else None

    hour = normalizar_hora_detectada(availability.get("hora"))
    if not hora_es_valida(hour):
        hour = None
    daypart = str(availability.get("franja_dia") or "").strip() or None
    duration = availability.get("duracion_horas")

    if not day_label and not hour and not daypart:
        return None

    source_message = str(availability.get("source_message") or "").strip()
    if not source_message:
        return None

    resource_types = _canonical_configured_court_types(
        availability.get("resource_types")
        or ([availability.get("resource_type")] if availability.get("resource_type") else [])
    )

    # Historial sólo enriquece provenance. No invalida una Observation real si
    # el buffer rotó o el mensaje todavía no estaba persistido al crear World.
    history = _agent_v2_history_with_reference_ids(world or {})
    matching = [
        dict(row) for row in history
        if str(row.get("content") or "").strip() == source_message
    ]
    previous_turn = matching[-1] if matching else {}
    reference_id = str(previous_turn.get("reference_id") or "").strip()
    if not reference_id:
        stable = str(availability.get("source_turn_id") or source_message)
        digest = hashlib.sha1(stable.encode("utf-8", errors="ignore")).hexdigest()[:16]
        reference_id = f"availability_context:{digest}"

    recent_user_rows = history[-3:]
    history_recent_match = any(
        str(row.get("content") or "").strip() == source_message
        for row in recent_user_rows
        if isinstance(row, dict)
    )

    return {
        "dia": day_label or None,
        "dia_resuelto": day_label or None,
        "day_iso": day_iso,
        "hora": hour,
        "franja_dia": daypart,
        "duracion_horas": duration,
        "resource_types": list(resource_types),
        "resource_type": resource_types[0] if len(resource_types) == 1 else None,
        "scope_id": str(availability.get("scope_id") or "").strip() or None,
        "source_turn_id": str(availability.get("source_turn_id") or "").strip() or None,
        "source_message": source_message,
        "reference_id": reference_id,
        "created_at": availability.get("created_at"),
        "history_recent_match": history_recent_match,
        "source": "verified_availability_context",
    }


def _agent_v2_v91_context_candidate(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Optional[Dict[str, Any]], str]:
    data = perception if isinstance(perception, dict) else {}
    if data.get("_v91_contextual_availability_resolved") is True:
        return None, "already_resolved"

    focus = _agent_v2_v91_verified_availability_focus(world or {})
    if not focus:
        return None, "no_recent_verified_availability"

    frame = _agent_v2_semantic_frame(data)
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    operational = [act for act in acts if str(act.get("operation") or "") != "greet"]
    operations = [str(act.get("operation") or "") for act in operational]

    # Un write inequívoco no puede adquirir semántica READ por memoria. Sólo
    # create_booking se admite como etiqueta PROVISIONAL porque el bug observado
    # consiste precisamente en confundir un follow-up informativo con reserva.
    forbidden_writes = set(AGENT_V2_WRITE_OPERATIONS) - {"create_booking"}
    if any(op in forbidden_writes for op in operations):
        return None, "explicit_nonavailability_write"

    allowed = {
        "query_availability", "query_policy", "query_price", "create_booking",
        "clarify", "unknown",
    }
    if operational and any(op not in allowed for op in operations):
        return None, "operation_outside_availability_followup"

    current_types = _agent_v2_resource_type_constraints(data, world or {})
    current_temporal = _agent_v2_v88_current_availability_temporal_snapshot(data)

    target_court = any(
        str((act.get("target") or {}).get("resource") or "") == "court"
        for act in operational
        if isinstance(act.get("target"), dict)
    )
    requested_facts = {
        str(value or "").strip()
        for act in operational
        for value in (act.get("requested_facts") or [])
        if str(value or "").strip()
    }
    court_fact = bool(requested_facts.intersection(
        {"court.catalog", "court.types", "available_slots", "court.price"}
    ))
    op_relevant = bool(set(operations).intersection(allowed))

    if not (current_types or target_court or court_fact or op_relevant):
        return None, "current_turn_not_court_relevant"

    return {
        "focus": dict(focus),
        "current_resource_types": list(current_types),
        "current_temporal": dict(current_temporal),
        "current_operations": operations,
        "current_requested_facts": sorted(requested_facts),
    }, "candidate_ready"


def _agent_v2_v91_project_contextual_read(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
    candidate: Dict[str, Any],
    current_types: List[str],
    *,
    evidence: str,
    reason: str,
    inherit_day: bool,
    inherit_start: bool,
    inherit_daypart: bool,
    inherit_duration: bool,
) -> Dict[str, Any]:
    clean = dict(perception or {})
    focus = dict((candidate or {}).get("focus") or {})
    types = _canonical_configured_court_types(current_types or [])
    if not types:
        return perception

    current_temporal = dict((candidate or {}).get("current_temporal") or {})
    current_day = str(current_temporal.get("day") or "").strip() or None
    current_hour = normalizar_hora_detectada(current_temporal.get("hour"))
    if not hora_es_valida(current_hour):
        current_hour = None
    current_daypart = str(current_temporal.get("daypart") or "").strip() or None
    current_duration = current_temporal.get("duration_hours")

    temporal: Dict[str, Any] = {}
    inherited_fields: List[str] = []

    # La decisión IA sobre qué se omitió gana sobre defaults/stale values de
    # Perception. Si inherit_* es True usamos la Observation anterior.
    if inherit_day:
        value = str(focus.get("day_iso") or focus.get("dia") or "").strip()
        if value:
            temporal["day"] = value
            inherited_fields.append("temporal.day")
    elif current_day:
        temporal["day"] = current_day

    if inherit_start:
        value = normalizar_hora_detectada(focus.get("hora"))
        if hora_es_valida(value):
            temporal["start"] = value
            inherited_fields.append("temporal.start")
    elif current_hour:
        temporal["start"] = current_hour

    if inherit_daypart:
        value = str(focus.get("franja_dia") or "").strip()
        if value:
            temporal["daypart"] = value
            inherited_fields.append("temporal.daypart")
    elif current_daypart:
        temporal["daypart"] = current_daypart

    if inherit_duration and focus.get("duracion_horas") not in (None, ""):
        temporal["duration_hours"] = focus.get("duracion_horas")
        inherited_fields.append("temporal.duration_hours")
    elif current_duration not in (None, ""):
        temporal["duration_hours"] = current_duration

    reference_id = str(focus.get("reference_id") or "").strip()
    scope_id = str(focus.get("scope_id") or "").strip() or None
    source_message = str(focus.get("source_message") or "")[:500]

    # V93: availability_context es memoria derivada de una Observation real,
    # pero su identidad histórica pertenece al USER turn que la originó.
    # Usamos previous_user_turn + reference_id real para que el mismo
    # ContextAuthorization del núcleo valide la lectura; no inventamos una
    # fuente paralela que el contrato no reconoce.
    provenance = [{
        "field": "target.resource_types",
        "source": "current_user_turn",
        "evidence": str(evidence or mensaje or "")[:500],
        "reference_id": None,
        "scope_id": None,
        "question_id": None,
        "option_id": None,
    }]
    for field in inherited_fields:
        provenance.append({
            "field": field,
            "source": "previous_user_turn",
            "evidence": source_message,
            "reference_id": reference_id,
            "scope_id": scope_id,
            "question_id": None,
            "option_id": None,
        })
    provenance.append({
        "field": "context.reference",
        "source": "previous_user_turn",
        "evidence": source_message,
        "reference_id": reference_id,
        "scope_id": scope_id,
        "question_id": None,
        "option_id": None,
    })

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    greet_acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") == "greet"
    ]
    availability_act = {
        "act_id": "act_v91_contextual_availability",
        "operation": "query_availability",
        "domain": "booking",
        "target": {
            "resource": "court",
            "resource_types": list(types),
            "resource_type": types[0] if len(types) == 1 else None,
            "source": "current_user_turn",
        },
        "temporal": temporal,
        "changes": [],
        "requested_facts": ["available_slots"],
        "commitment": {"wants_write": False, "wants_information": True},
        "provenance": provenance,
        "confidence": 1.0,
    }
    frame["acts"] = greet_acts + [availability_act]
    frame["targets"] = [dict(availability_act["target"])]
    frame["requested_facts"] = ["available_slots"]
    frame["commitment"] = {"wants_write": False, "wants_information": True}
    frame["context_relation"] = {
        "type": "references_previous",
        "question_id": None,
        "references_previous_user_turn": True,
        "references_agent_offer": False,
        "answers_pending_question": False,
    }
    clean["semantic_frame"] = frame

    entities = dict(clean.get("entities") or {})
    entities["resource_types"] = list(types)
    entities["resource_type"] = types[0] if len(types) == 1 else None
    if inherit_day:
        day_label = str(focus.get("dia") or focus.get("dia_resuelto") or "").strip()
        if day_label:
            entities["dia"] = day_label
            entities["dia_resuelto"] = day_label
    if inherit_start and temporal.get("start"):
        entities["hora"] = temporal.get("start")
    if inherit_daypart and temporal.get("daypart"):
        entities["franja_dia"] = temporal.get("daypart")
    if inherit_duration and temporal.get("duration_hours") not in (None, ""):
        entities["duracion_horas"] = temporal.get("duration_hours")
    clean["entities"] = entities

    clean.update({
        "pending_relation": "references_previous",
        "references_prior_user_input": True,
        "suspend_pending_this_turn": True,
        "current_turn_read_only": True,
        "booking_time_choice": False,
        "booking_block_choice": False,
        "accepts_any_option": False,
        "answers_pending_field": None,
        "references_operational_context": True,
        "_v88_availability_dimension_refinement": True,
        "_v88_inherited_dimensions": list(inherited_fields),
        "_v90_pre_catalog_contextual_availability": True,
        "_v91_contextual_availability_resolved": True,
        "read_grounding_recovery": False,
        "read_meaning_repair_needed": False,
    })
    clean.pop("read_recovery_reason", None)
    clean.pop("_read_grounding_validated_response", None)
    clean.pop("_specific_court_catalog_today_bundle", None)
    clean.pop("execution_contract", None)
    clean.pop("semantic_freeze", None)

    clean["context_request"] = {
        "needed": True,
        "relation": "references_previous",
        "candidate_types": ["availability_temporal_scope"],
        "reason": "availability_dimension_refinement",
    }
    clean["context_resolution"] = {
        "requested": True,
        "resolved": True,
        "relation": "references_previous",
        "question_id": None,
        "reference_id": reference_id,
        "scope_id": scope_id,
        "resolved_value": {
            "resource_types": list(types),
            "inherited_dimensions": list(inherited_fields),
            "day": temporal.get("day"),
            "start": temporal.get("start"),
            "daypart": temporal.get("daypart"),
            "duration_hours": temporal.get("duration_hours"),
        },
        "reason": str(reason or "early_contextual_availability_validated"),
    }
    clean["reference_resolution"] = {
        "source": "previous_user_turn",
        "resolved": True,
        "reference_id": reference_id,
        "text": source_message,
    }

    validation = [
        str(item or "")
        for item in (clean.get("validation_errors") or clean.get("validation") or [])
        if str(item or "") not in {
            "repairable_read_fact_inconsistency",
            "policy_fact_address_missing",
            "missing_recognized_operation",
            "write_not_authorized_by_effect_verifier",
            "unauthorized_write_discarded",
        }
    ]
    if "validation_errors" in clean:
        clean["validation_errors"] = validation
    if "validation" in clean and isinstance(clean.get("validation"), list):
        clean["validation"] = validation

    domains = [
        d for d in _agent_v2_normalize_question_domains(clean)
        if d not in {"court_catalog", "other"}
    ]
    if "availability" not in domains:
        domains.append("availability")
    clean["question_domains"] = list(dict.fromkeys(domains))

    clean = _agent_v2_normalize_perception(clean, world or {}, mensaje, "")
    clean["execution_contract"] = _agent_v2_build_execution_contract(clean, world or {})

    print(
        "   🔗 [AgentV2 V91 EARLY CONTEXTUAL AVAILABILITY] "
        f"resource_types={types} inherited={inherited_fields} "
        f"reference_id={reference_id} → query_availability READ"
    )
    return clean


async def _agent_v2_v91_resolve_early_context(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    candidate, gate_reason = _agent_v2_v91_context_candidate(perception, world or {})
    focus = _agent_v2_v91_verified_availability_focus(world or {})

    if not candidate:
        if focus:
            ops = [
                str(act.get("operation") or "")
                for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
                if isinstance(act, dict)
            ]
            print(
                "   🧭 [AgentV2 V91 CONTEXT GATE] "
                f"eligible=False reason={gate_reason} ops={ops} "
                f"current_types={_agent_v2_resource_type_constraints(perception or {}, world or {})}"
            )
        return perception

    configured_types = _canonical_configured_court_types([
        str(item.get("type") or item.get("tipo") or "").strip()
        for item in (COURTS or []) if isinstance(item, dict)
    ])
    if not configured_types:
        return perception

    print(
        "   🧭 [AgentV2 V91 CONTEXT GATE] "
        f"eligible=True ops={candidate.get('current_operations') or []} "
        f"current_types={candidate.get('current_resource_types') or []} "
        f"previous_types={focus.get('resource_types') or []} "
        f"history_match={focus.get('history_recent_match')}"
    )

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos CONTEXTUAL AVAILABILITY RESOLVER. Decidí únicamente si "
                        "current_user_turn continúa la consulta de DISPONIBILIDAD del "
                        "previous_user_turn. previous_availability_context viene de una "
                        "consulta REAL al calendario. Un mensaje corto puede cambiar sólo "
                        "el tipo de cancha y omitir día/hora porque siguen implícitos. "
                        "continues_availability_query=true sólo si el turno actual sigue "
                        "preguntando/comparando disponibilidad. Debe ser false si confirma "
                        "una reserva, cancela, reprograma, paga, pregunta una política "
                        "independiente o cambia de tema. read_only debe ser true para una "
                        "continuación de disponibilidad. resource_types debe incluir sólo "
                        "tipos EXPLÍCITOS del mensaje actual y usar exactamente valores de "
                        "configured_types; nunca heredes el recurso anterior. Las flags "
                        "inherit_previous_* sólo son true para dimensiones omitidas por el "
                        "mensaje actual que deben conservarse del contexto anterior. evidence "
                        "debe ser una cita literal no vacía de current_user_turn. Respondé SOLO "
                        "JSON: {continues_availability_query:boolean,read_only:boolean," 
                        "resource_types:[string],inherit_previous_day:boolean," 
                        "inherit_previous_start:boolean,inherit_previous_daypart:boolean," 
                        "inherit_previous_duration:boolean,evidence:string,reason:string}."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "configured_types": configured_types,
                        "current_semantic_frame": _agent_v2_semantic_frame(perception or {}),
                        "current_resource_types_structured": candidate.get("current_resource_types") or [],
                        "current_temporal_scope": candidate.get("current_temporal") or {},
                        "previous_user_turn": focus.get("source_message"),
                        "previous_resource_types": focus.get("resource_types") or [],
                        "previous_availability_context": {
                            "day": focus.get("day_iso") or focus.get("dia"),
                            "start": focus.get("hora"),
                            "daypart": focus.get("franja_dia"),
                            "duration_hours": focus.get("duracion_horas"),
                        },
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=240,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        decision = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V91 CONTEXT RESOLVER] "
            f"sin decisión segura: {type(exc).__name__}: {exc}"
        )
        return perception

    evidence = str(decision.get("evidence") or "").strip()
    if not decision.get("continues_availability_query") or not decision.get("read_only"):
        print(
            "   🧭 [AgentV2 V91 CONTEXT RESOLVER] "
            f"continues=False reason={decision.get('reason')}"
        )
        return perception
    if not evidence or normalizar_texto_ia(evidence) not in normalizar_texto_ia(mensaje or ""):
        print("   🧭 [AgentV2 V91 CONTEXT RESOLVER] continues=False reason=invalid_evidence")
        return perception

    structured_types = _canonical_configured_court_types(candidate.get("current_resource_types") or [])
    decided_types = _canonical_configured_court_types(decision.get("resource_types") or [])
    if structured_types and decided_types and set(structured_types) != set(decided_types):
        print(
            "   🧭 [AgentV2 V91 CONTEXT RESOLVER] "
            f"continues=False reason=resource_disagreement structured={structured_types} ai={decided_types}"
        )
        return perception
    current_types = decided_types or structured_types
    if not current_types:
        print("   🧭 [AgentV2 V91 CONTEXT RESOLVER] continues=False reason=no_current_resource")
        return perception

    inherit_day = bool(decision.get("inherit_previous_day") and (focus.get("day_iso") or focus.get("dia")))
    inherit_start = bool(decision.get("inherit_previous_start") and focus.get("hora"))
    inherit_daypart = bool(decision.get("inherit_previous_daypart") and focus.get("franja_dia"))
    inherit_duration = bool(
        decision.get("inherit_previous_duration")
        and focus.get("duracion_horas") not in (None, "")
    )

    # Si no hay ninguna dimensión fuerte que heredar, no hace falta reescribir
    # el contrato: la consulta actual puede seguir su camino normal.
    if not any((inherit_day, inherit_start, inherit_daypart)):
        print("   🧭 [AgentV2 V91 CONTEXT RESOLVER] continues=False reason=no_temporal_inheritance")
        return perception

    return _agent_v2_v91_project_contextual_read(
        perception,
        mensaje,
        world or {},
        candidate,
        current_types,
        evidence=evidence,
        reason=str(decision.get("reason") or "early_contextual_availability_validated"),
        inherit_day=inherit_day,
        inherit_start=inherit_start,
        inherit_daypart=inherit_daypart,
        inherit_duration=inherit_duration,
    )


