def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v90_context_base()
    results = list(result.get("results") or [])

    configured = _canonical_configured_court_types([
        str(item.get("type") or item.get("tipo") or "").strip()
        for item in (COURTS or []) if isinstance(item, dict)
    ])
    previous_type = configured[0] if configured else "futbol 5"
    current_type = configured[-1] if len(configured) > 1 else previous_type
    world = {
        "stored_memory": {
            "availability_context": {
                "dia": "Lunes 21/09",
                "dia_resuelto": "Lunes 21/09",
                "resource_types": [previous_type],
                "resource_type": previous_type,
                "source_message": "consulta disponibilidad anterior",
                "source_turn_id": "v91_previous_turn",
                "scope_id": "v91_scope",
                "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
            },
            "history": [],
        },
        "facts": {"reservas_reales": []},
    }
    provisional = {
        "entities": {"resource_types": [current_type], "resource_type": current_type},
        "semantic_frame": {
            "acts": [{
                "act_id": "v91_provisional",
                "operation": "create_booking",
                "target": {"resource": "court", "resource_types": [current_type]},
                "temporal": {},
                "requested_facts": [],
                "commitment": {"wants_write": True, "wants_information": False},
            }],
            "context_relation": {"type": "new_request"},
        },
    }
    focus = _agent_v2_v91_verified_availability_focus(world)
    candidate, gate_reason = _agent_v2_v91_context_candidate(provisional, world)
    results.extend([
        {
            "name": "v91_verified_availability_survives_missing_history_reference",
            "ok": bool(focus and str(focus.get("reference_id") or "").startswith("availability_context:")),
        },
        {
            "name": "v91_provisional_create_booking_reaches_context_resolver",
            "ok": bool(candidate and gate_reason == "candidate_ready"),
        },
    ])
    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V92 — STRUCTURAL AVAILABILITY ELLIPSIS
# ============================================================================
# Bug real observado en producción:
#
#   USER: "qué horas libres tenés hoy para canchas de pádel?"
#   BOT : disponibilidad REAL de Pádel para hoy
#   USER: "¿y en cancha de fútbol 5?"
#
# En V91, Perception YA había producido:
#   operation=query_availability
#   current_resource_types=['Futbol 5']
#   availability_context previo=['Pádel', día de hoy]
#
# pero una SEGUNDA IA volvió a decidir la continuidad y respondió
# "no_temporal_inheritance". Eso contradijo el contrato semántico ya resuelto.
#
# V92 elimina ese veto redundante para el caso estructural inequívoco:
#   - el turno inmediatamente anterior produjo availability_context REAL;
#   - el turno actual YA fue entendido por IA como query_availability;
#   - el tipo de recurso ACTUAL YA fue extraído por IA;
#   - el recurso cambió;
#   - el turno actual omitió fecha/hora que sí existían en el contexto previo.
#
# Python no interpreta palabras ni deportes. Sólo compone dos salidas ya
# estructuradas por IA/tool: intención actual + memoria verificada anterior.


AGENT_V2_CONTEXTUAL_AVAILABILITY_VERSION = "v92"


def _agent_v2_v92_last_user_turn_matches_availability(
    world: Optional[Dict[str, Any]],
    focus: Optional[Dict[str, Any]],
) -> bool:
    """Verifica adyacencia real entre availability_context y CURRENT USER turn.

    El runtime de producción persiste el mensaje USER actual ANTES de construir
    World. Los evals/offline pueden construir World antes de persistirlo.

    Por eso existen exactamente dos layouts válidos:

        PRE-PERSIST:
            history[-1] == source_message

        PRODUCCIÓN:
            history[-2] == source_message
            history[-1] == world.message

    No interpreta lenguaje, deporte, fecha ni intención. Sólo identidad y orden.
    """
    world = dict(world or {})
    focus = dict(focus or {})

    source_message = str(focus.get("source_message") or "").strip()
    if not source_message:
        return False

    history = _agent_v2_history_with_reference_ids(world)
    if not history:
        return False

    current_message = str(
        world.get("message")
        or ((world.get("current_turn_context") or {}).get("message")
            if isinstance(world.get("current_turn_context"), dict)
            else "")
        or ""
    ).strip()

    last_user = history[-1] if isinstance(history[-1], dict) else {}
    last_content = str(last_user.get("content") or "").strip()

    # Layout pre-persist / fixture: el último USER conocido todavía es el que
    # originó availability_context. También cubre replay exacto current==source.
    if last_content == source_message:
        return True

    # Layout REAL de producción: automation_loop ya hizo add_to_history() con el
    # CURRENT USER turn antes de construir World. Sólo autorizamos herencia si:
    #   1) el último USER coincide exactamente con world.message, y
    #   2) el USER inmediatamente anterior coincide exactamente con source_message.
    if (
        current_message
        and last_content == current_message
        and current_message != source_message
        and len(history) >= 2
    ):
        previous_user = history[-2] if isinstance(history[-2], dict) else {}
        previous_content = str(previous_user.get("content") or "").strip()

        if previous_content == source_message:
            print(
                "   🧭 [AgentV2 V94 HISTORY ADJACENCY] "
                "current_user_already_persisted=True "
                "source_position=-2 current_position=-1"
            )
            return True

    return False


def _agent_v2_v92_structural_ellipsis_candidate(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Optional[Dict[str, Any]], str]:
    """Detecta continuidad usando únicamente semántica estructurada ya resuelta.

    NO lee palabras del mensaje. NO usa regex. NO infiere deporte.
    """
    data = perception if isinstance(perception, dict) else {}
    if data.get("_v91_contextual_availability_resolved") is True:
        return None, "already_resolved"

    focus = _agent_v2_v91_verified_availability_focus(world or {})
    if not focus:
        return None, "no_verified_availability_context"

    if not _agent_v2_v92_last_user_turn_matches_availability(world or {}, focus):
        return None, "availability_not_immediately_previous_user_turn"

    frame = _agent_v2_semantic_frame(data)
    operational = [
        dict(act)
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") != "greet"
    ]
    if not operational:
        return None, "no_operational_act"

    operations = [
        str(act.get("operation") or "")
        for act in operational
    ]

    # Ésta es la pieza decisiva de V92: la IA de Perception ya clasificó el
    # mensaje actual como disponibilidad. No se le pide a otra IA que lo vote.
    if any(op != "query_availability" for op in operations):
        return None, "current_semantics_not_pure_availability_read"

    if any(
        str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
        for act in operational
    ):
        return None, "write_present"

    if not any(
        str((act.get("target") or {}).get("resource") or "") == "court"
        for act in operational
        if isinstance(act.get("target"), dict)
    ):
        return None, "availability_target_is_not_court"

    current_types = _canonical_configured_court_types(
        _agent_v2_resource_type_constraints(data, world or {})
    )
    if not current_types:
        return None, "current_resource_type_missing"

    previous_types = _canonical_configured_court_types(
        focus.get("resource_types")
        or ([focus.get("resource_type")] if focus.get("resource_type") else [])
    )
    if not previous_types:
        return None, "previous_resource_type_missing"

    # V92 sólo cubre el cambio explícito de recurso. Otros tipos de continuidad
    # siguen siendo responsabilidad de V80/V88/V91.
    if set(current_types) == set(previous_types):
        return None, "resource_type_did_not_change"

    current_temporal = _agent_v2_v88_current_availability_temporal_snapshot(data)

    inherit_day = bool(
        (focus.get("day_iso") or focus.get("dia"))
        and not str(current_temporal.get("day") or "").strip()
    )

    current_hour = normalizar_hora_detectada(current_temporal.get("hour"))
    if not hora_es_valida(current_hour):
        current_hour = None
    current_daypart = str(current_temporal.get("daypart") or "").strip() or None

    inherit_start = bool(
        focus.get("hora")
        and not current_hour
        and not current_daypart
    )
    inherit_daypart = bool(
        focus.get("franja_dia")
        and not current_daypart
        and not current_hour
    )

    current_duration = current_temporal.get("duration_hours")
    inherit_duration = bool(
        focus.get("duracion_horas") not in (None, "")
        and current_duration in (None, "")
    )

    # Debe existir al menos una dimensión temporal fuerte que completar.
    if not any((inherit_day, inherit_start, inherit_daypart)):
        return None, "no_missing_temporal_dimension"

    return {
        "focus": dict(focus),
        "current_resource_types": list(current_types),
        "previous_resource_types": list(previous_types),
        "current_temporal": dict(current_temporal),
        "current_operations": list(operations),
        "inherit_day": inherit_day,
        "inherit_start": inherit_start,
        "inherit_daypart": inherit_daypart,
        "inherit_duration": inherit_duration,
    }, "structural_ellipsis_ready"


def _agent_v2_v92_current_resource_evidence(
    perception: Dict[str, Any],
    mensaje: str,
) -> str:
    """Usa provenance de Perception cuando existe; el mensaje completo sólo es fallback."""
    frame = _agent_v2_semantic_frame(perception or {})
    for act in frame.get("acts") or []:
        if not isinstance(act, dict):
            continue
        if str(act.get("operation") or "") != "query_availability":
            continue
        for item in act.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            if (
                str(item.get("field") or "") in {
                    "target.resource_type",
                    "target.resource_types",
                }
                and str(item.get("source") or "") == "current_user_turn"
            ):
                evidence = str(item.get("evidence") or "").strip()
                if evidence:
                    return evidence
    return str(mensaje or "").strip()[:500]


def _agent_v2_v92_resolve_structural_availability_ellipsis(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    candidate, reason = _agent_v2_v92_structural_ellipsis_candidate(
        perception,
        world or {},
    )

    if not candidate:
        focus = _agent_v2_v91_verified_availability_focus(world or {})
        if focus:
            print(
                "   🧭 [AgentV2 V92 STRUCTURAL ELLIPSIS] "
                f"eligible=False reason={reason}"
            )
        return perception, False

    evidence = _agent_v2_v92_current_resource_evidence(
        perception,
        mensaje,
    )

    print(
        "   ✅ [AgentV2 V92 STRUCTURAL ELLIPSIS] "
        f"current_types={candidate.get('current_resource_types') or []} "
        f"previous_types={candidate.get('previous_resource_types') or []} "
        f"inherit_day={candidate.get('inherit_day')} "
        f"inherit_start={candidate.get('inherit_start')} "
        f"inherit_daypart={candidate.get('inherit_daypart')} "
        "→ segunda adjudicación IA omitida"
    )

    projected = _agent_v2_v91_project_contextual_read(
        perception,
        mensaje,
        world or {},
        candidate,
        candidate.get("current_resource_types") or [],
        evidence=evidence,
        reason="v92_structural_semantic_availability_ellipsis",
        inherit_day=bool(candidate.get("inherit_day")),
        inherit_start=bool(candidate.get("inherit_start")),
        inherit_daypart=bool(candidate.get("inherit_daypart")),
        inherit_duration=bool(candidate.get("inherit_duration")),
    )
    projected["_v92_structural_availability_ellipsis"] = True

    print(
        "   🔗 [AgentV2 V92 CONTEXT COMMIT] "
        f"inherited={projected.get('_v88_inherited_dimensions') or []} "
        "→ query_availability READ congelado"
    )
    return projected, True


# ---------------------------------------------------------------------------
# V92 reemplaza únicamente el wrapper de entrada de V91. Para los casos que no
# cumplen la continuidad estructural exacta, V91 sigue disponible como fallback
# semántico. Así no ampliamos autoridad innecesariamente.
# ---------------------------------------------------------------------------
async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    # Llamamos deliberadamente al baseline PRE-V91. Si llamáramos al wrapper
    # V91 actual, consumiría primero la adjudicación que produjo
    # no_temporal_inheritance en el log real.
    perception = await _percibir_turno_agent_v2_v90_context_base(
        mensaje,
        world,
        image_path,
        learning_policy,
    )

    perception, structurally_resolved = (
        _agent_v2_v92_resolve_structural_availability_ellipsis(
            perception,
            mensaje,
            world or {},
        )
    )
    if structurally_resolved:
        return perception

    return await _agent_v2_v91_resolve_early_context(
        perception,
        mensaje,
        world or {},
    )


# ---------------------------------------------------------------------------
# Evals V92 — no consumen API. Reproducen exactamente el estado que muestra el
# log: query_availability + nuevo resource_type + previous availability context.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v91_structural_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v91_structural_base()
    results = list(result.get("results") or [])

    configured = _canonical_configured_court_types([
        str(item.get("type") or item.get("tipo") or "").strip()
        for item in (COURTS or [])
        if isinstance(item, dict)
    ])
    previous_type = configured[0] if configured else "Pádel"
    current_type = (
        next(
            (value for value in configured if value != previous_type),
            None,
        )
        or ("Futbol 5" if previous_type != "Futbol 5" else "Pádel")
    )

    now_iso = datetime.datetime.now(TIMEZONE).isoformat()
    previous_message = "consulta disponibilidad anterior"
    world = {
        "stored_memory": {
            "availability_context": {
                "dia": "Lunes 21/09",
                "dia_resuelto": "Lunes 21/09",
                "resource_types": [previous_type],
                "resource_type": previous_type,
                "source_message": previous_message,
                "source_turn_id": "v92_previous_turn",
                "scope_id": "v92_scope",
                "created_at": now_iso,
            },
            "history": [{
                "role": "user",
                "content": previous_message,
                "timestamp": now_iso,
                "reference_id": "v92_previous_user",
            }],
        },
        "facts": {"reservas_reales": []},
    }

    perception = {
        "entities": {
            "resource_types": [current_type],
            "resource_type": current_type,
        },
        "semantic_frame": {
            "source": "ai",
            "schema_valid": True,
            "acts": [{
                "act_id": "v92_availability",
                "operation": "query_availability",
                "domain": "booking",
                "target": {
                    "resource": "court",
                    "resource_types": [current_type],
                    "resource_type": current_type,
                },
                "temporal": {},
                "changes": [],
                "requested_facts": ["available_slots"],
                "commitment": {
                    "wants_write": False,
                    "wants_information": True,
                },
                "provenance": [{
                    "field": "target.resource_types",
                    "source": "current_user_turn",
                    "evidence": "tipo actual",
                }],
            }],
            "requested_facts": ["available_slots"],
            "context_relation": {"type": "new_request"},
        },
    }

    candidate, candidate_reason = _agent_v2_v92_structural_ellipsis_candidate(
        perception,
        world,
    )
    projected = perception
    resolved = False
    if candidate:
        projected, resolved = _agent_v2_v92_resolve_structural_availability_ellipsis(
            perception,
            "seguimiento disponibilidad",
            world,
        )

    pframe = _agent_v2_semantic_frame(projected)
    pops = [
        str(act.get("operation") or "")
        for act in (pframe.get("acts") or [])
        if isinstance(act, dict)
    ]
    availability = next((
        act
        for act in (pframe.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "query_availability"
    ), {})
    temporal = (
        availability.get("temporal")
        if isinstance(availability.get("temporal"), dict)
        else {}
    )
    target = (
        availability.get("target")
        if isinstance(availability.get("target"), dict)
        else {}
    )

    results.extend([
        {
            "name": "v92_pure_availability_resource_switch_is_structural_candidate",
            "ok": bool(
                candidate
                and candidate_reason == "structural_ellipsis_ready"
            ),
        },
        {
            "name": "v92_structural_candidate_inherits_previous_day_without_second_llm",
            "ok": bool(
                resolved
                and temporal.get("day") in {"2026-09-21", "Lunes 21/09"}
            ),
        },
        {
            "name": "v92_current_resource_replaces_previous_resource",
            "ok": bool(
                target.get("resource_type") == current_type
                and previous_type not in (target.get("resource_types") or [])
            ),
        },
        {
            "name": "v92_projection_remains_read_only",
            "ok": bool(
                pops.count("query_availability") == 1
                and not any(op in AGENT_V2_WRITE_OPERATIONS for op in pops)
            ),
        },
        {
            "name": "v92_nonadjacent_context_does_not_get_structural_authority",
            "ok": bool(
                _agent_v2_v92_structural_ellipsis_candidate(
                    perception,
                    {
                        **world,
                        "stored_memory": {
                            **world["stored_memory"],
                            "history": [{
                                "role": "user",
                                "content": "otro tema intermedio",
                                "timestamp": now_iso,
                            }],
                        },
                    },
                )[0] is None
            ),
        },
    ])

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V93 — CONTEXT PROVENANCE + SAME-SOURCE REPLAY GUARD
# ============================================================================
# Log real que motivó este build:
#
#   1) El usuario consulta disponibilidad de Pádel.
#   2) El agente responde correctamente.
#   3) WhatsApp/InBox vuelve a entregar el MISMO mensaje como pendiente.
#   4) V92 ve current_types == previous_types y cae a V91.
#   5) V91 transforma el replay en references_previous.
#   6) El provenance usado por V91 era "verified_availability_context", fuente
#      que el núcleo de ContextAuthorization NO reconoce.
#   7) ExecutionContract => historical_context_not_authorized.
#   8) Policy bloquea consultar_disponibilidad.
#   9) Safe Exit termina en handoff humano.
#
# V93 fija ambas fronteras sin regex de intención:
#
#   A) mismo mensaje fuente == replay / consulta actual, NO follow-up histórico;
#   B) un dato heredado desde availability_context se acredita al
#      previous_user_turn REAL usando su reference_id real.
#
# IA entiende. Python verifica identidad/provenance. Policy conserva autoridad.


AGENT_V2_CONTEXTUAL_AVAILABILITY_VERSION = "v93"


def _agent_v2_v93_same_availability_source_replay(
    mensaje: str,
    world: Optional[Dict[str, Any]],
) -> bool:
    """True sólo para igualdad exacta con el USER turn que creó availability_context.

    No interpreta lenguaje, intención, deporte ni fechas.
    """
    focus = _agent_v2_v91_verified_availability_focus(world or {})
    if not focus:
        return False

    current_text = str(mensaje or "").strip()
    source_text = str(focus.get("source_message") or "").strip()
    if not current_text or not source_text:
        return False

    if current_text != source_text:
        return False

    # El source debe seguir siendo el último USER turn conocido. Esto evita que
    # una frase idéntica remota sea confundida con un replay operativo.
    return _agent_v2_v92_last_user_turn_matches_availability(
        world or {},
        focus,
    )


def _agent_v2_v93_context_contract_health(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Diagnóstico estructurado de la autorización contextual; no modifica nada."""
    contract = dict((perception or {}).get("execution_contract") or {})
    auth = _agent_v2_context_authorization(perception or {}, world or {})
    return {
        "contract_authoritative": bool(contract.get("authoritative")),
        "allowed_tools": sorted({
            str(name)
            for name in (contract.get("allowed_tools") or [])
            if str(name)
        }),
        "context_authorized": bool(auth.get("authorized")),
        "context_reason": str(auth.get("reason") or ""),
        "reference_id": str(auth.get("reference_id") or ""),
    }


# Reemplazamos el wrapper de V92. Seguimos entrando por el baseline PRE-V91
# para que ninguna adjudicación contextual consuma una llamada antes de aplicar
# el replay guard.
async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v90_context_base(
        mensaje,
        world,
        image_path,
        learning_policy,
    )

    # El MISMO mensaje que originó la Observation anterior no puede convertirse
    # en "references_previous". Si WhatsApp lo reentrega, mantenemos exactamente
    # la semántica CURRENT-TURN que ya produjo Perception y evitamos una llamada
    # contextual redundante.
    if _agent_v2_v93_same_availability_source_replay(
        mensaje,
        world or {},
    ):
        perception = dict(perception or {})
        perception["_v93_same_source_replay_bypass"] = True
        print(
            "   ♻️ [AgentV2 V93 SAME-SOURCE REPLAY] "
            "mensaje actual == source_message de availability_context "
            "→ NO references_previous; V91/V92 omitidos"
        )
        return perception

    # Caso útil: query_availability actual + cambio estructurado de resource_type
    # + dimensión temporal ausente => V92 hereda desde Observation verificada.
    perception, structurally_resolved = (
        _agent_v2_v92_resolve_structural_availability_ellipsis(
            perception,
            mensaje,
            world or {},
        )
    )
    if structurally_resolved:
        health = _agent_v2_v93_context_contract_health(
            perception,
            world or {},
        )
        print(
            "   🔐 [AgentV2 V93 CONTEXT AUTHORITY] "
            f"authorized={health.get('context_authorized')} "
            f"reason={health.get('context_reason')} "
            f"contract_authoritative={health.get('contract_authoritative')} "
            f"tools={health.get('allowed_tools')}"
        )
        return perception

    # Otros follow-ups semánticos siguen disponibles en V91.
    resolved = await _agent_v2_v91_resolve_early_context(
        perception,
        mensaje,
        world or {},
    )

    if (resolved or {}).get("_v91_contextual_availability_resolved") is True:
        health = _agent_v2_v93_context_contract_health(
            resolved,
            world or {},
        )
        print(
            "   🔐 [AgentV2 V93 CONTEXT AUTHORITY] "
            f"authorized={health.get('context_authorized')} "
            f"reason={health.get('context_reason')} "
            f"contract_authoritative={health.get('contract_authoritative')} "
            f"tools={health.get('allowed_tools')}"
        )

    return resolved


# ---------------------------------------------------------------------------
# V93 invariant evals — offline, sin API.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v92_context_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v92_context_base()
    results = list(result.get("results") or [])

    configured = _canonical_configured_court_types([
        str(item.get("type") or item.get("tipo") or "").strip()
        for item in (COURTS or [])
        if isinstance(item, dict)
    ])
    previous_type = configured[0] if configured else "Pádel"
    current_type = next(
        (value for value in configured if value != previous_type),
        "Futbol 5" if previous_type != "Futbol 5" else "Pádel",
    )

    now_iso = datetime.datetime.now(TIMEZONE).isoformat()
    previous_message = "consulta disponibilidad fuente v93"
    previous_reference_id = "user_turn:v93_previous:0"

    world = {
        "stored_memory": {
            "availability_context": {
                "dia": "Lunes 21/09",
                "dia_resuelto": "Lunes 21/09",
                "resource_types": [previous_type],
                "resource_type": previous_type,
                "source_message": previous_message,
                "source_turn_id": "v93_previous_turn",
                "scope_id": "v93_scope",
                "created_at": now_iso,
            },
            "history": [{
                "role": "user",
                "content": previous_message,
                "timestamp": now_iso,
                "reference_id": previous_reference_id,
            }],
        },
        "facts": {
            "reservas_reales": [],
            "memory_owner": "",
        },
    }

    replay_ok = _agent_v2_v93_same_availability_source_replay(
        previous_message,
        world,
    )
    different_ok = not _agent_v2_v93_same_availability_source_replay(
        "consulta diferente",
        world,
    )

    switch_perception = {
        "entities": {
            "resource_types": [current_type],
            "resource_type": current_type,
        },
        "semantic_frame": {
            "source": "ai",
            "schema_valid": True,
            "acts": [{
                "act_id": "v93_switch",
                "operation": "query_availability",
                "domain": "booking",
                "target": {
                    "resource": "court",
                    "resource_types": [current_type],
                    "resource_type": current_type,
                    "source": "current_user_turn",
                },
                "temporal": {},
                "changes": [],
                "requested_facts": ["available_slots"],
                "commitment": {
                    "wants_write": False,
                    "wants_information": True,
                },
                "provenance": [{
                    "field": "target.resource_types",
                    "source": "current_user_turn",
                    "evidence": "nuevo tipo de cancha",
                    "reference_id": None,
                    "scope_id": None,
                    "question_id": None,
                    "option_id": None,
                }],
            }],
            "requested_facts": ["available_slots"],
            "context_relation": {"type": "new_question"},
        },
    }

    candidate, reason = _agent_v2_v92_structural_ellipsis_candidate(
        switch_perception,
        world,
    )

    projected = switch_perception
    if candidate:
        projected = _agent_v2_v91_project_contextual_read(
            switch_perception,
            "seguimiento de disponibilidad",
            world,
            candidate,
            candidate.get("current_resource_types") or [],
            evidence="nuevo tipo de cancha",
            reason="v93_eval",
            inherit_day=bool(candidate.get("inherit_day")),
            inherit_start=bool(candidate.get("inherit_start")),
            inherit_daypart=bool(candidate.get("inherit_daypart")),
            inherit_duration=bool(candidate.get("inherit_duration")),
        )

    auth = _agent_v2_context_authorization(
        projected,
        world,
    )
    contract = dict(projected.get("execution_contract") or {})

    projected_availability = next((
        act
        for act in (_agent_v2_semantic_frame(projected).get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "query_availability"
    ), {})
    inherited_provenance = [
        dict(item)
        for item in (projected_availability.get("provenance") or [])
        if isinstance(item, dict)
        and str(item.get("field") or "").startswith("temporal.")
    ]

    results.extend([
        {
            "name": "v93_same_source_message_is_replay_not_context_followup",
            "ok": bool(replay_ok),
        },
        {
            "name": "v93_different_message_is_not_replay",
            "ok": bool(different_ok),
        },
        {
            "name": "v93_resource_switch_remains_structural_candidate",
            "ok": bool(candidate and reason == "structural_ellipsis_ready"),
        },
        {
            "name": "v93_inherited_availability_uses_previous_user_turn_provenance",
            "ok": bool(
                inherited_provenance
                and all(
                    item.get("source") == "previous_user_turn"
                    and item.get("reference_id") == previous_reference_id
                    for item in inherited_provenance
                )
            ),
        },
        {
            "name": "v93_context_authorization_accepts_verified_previous_turn",
            "ok": bool(
                auth.get("authorized")
                and auth.get("reason") == "verified_historical_reference"
                and auth.get("reference_id") == previous_reference_id
            ),
        },
        {
            "name": "v93_contextual_availability_contract_is_authoritative",
            "ok": bool(
                contract.get("authoritative")
                and "consultar_disponibilidad" in set(
                    contract.get("allowed_tools") or []
                )
            ),
        },
    ])

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V94 — REAL RUNTIME HISTORY ADJACENCY
# ============================================================================
# Producción persiste CURRENT USER turn antes de construir World.
# V92 había sido evaluado con history=[previous_turn] pero producción entrega:
#
#     history=[..., previous_turn, current_turn]
#
# La guarda V94 de arriba acepta ambas formas únicamente por identidad/orden.
# No agrega regex ni reinterpreta intención.
AGENT_V2_CONTEXTUAL_AVAILABILITY_VERSION = "v94"


# ---------------------------------------------------------------------------
# V94 invariant evals — reproducen el orden REAL de automation_loop.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v93_history_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v93_history_base()
    results = list(result.get("results") or [])

    configured = _canonical_configured_court_types([
        str(item.get("type") or item.get("tipo") or "").strip()
        for item in (COURTS or [])
        if isinstance(item, dict)
    ])
    previous_type = configured[0] if configured else "Pádel"
    current_type = next(
        (value for value in configured if value != previous_type),
        "Futbol 5" if previous_type != "Futbol 5" else "Pádel",
    )

    now_iso = datetime.datetime.now(TIMEZONE).isoformat()
    previous_message = "consulta disponibilidad pádel hoy"
    current_message = "seguimiento disponibilidad otro recurso"
    previous_ref = "user_turn:v94_previous:0"
    current_ref = "user_turn:v94_current:1"

    # Estado real de producción: current_message YA está en historial.
    world_runtime_order = {
        "message": current_message,
        "current_turn_context": {
            "message": current_message,
            "turn_id": "v94_current_turn",
            "now": now_iso,
        },
        "stored_memory": {
            "availability_context": {
                "dia": "Lunes 21/09",
                "dia_resuelto": "Lunes 21/09",
                "resource_types": [previous_type],
                "resource_type": previous_type,
                "source_message": previous_message,
                "source_turn_id": "v94_previous_turn",
                "scope_id": "v94_scope",
                "created_at": now_iso,
            },
            "history": [
                {
                    "role": "user",
                    "content": previous_message,
                    "timestamp": now_iso,
                    "reference_id": previous_ref,
                },
                {
                    "role": "user",
                    "content": current_message,
                    "timestamp": now_iso,
                    "reference_id": current_ref,
                },
            ],
        },
        "facts": {
            "reservas_reales": [],
            "memory_owner": "",
        },
    }

    focus = _agent_v2_v91_verified_availability_focus(
        world_runtime_order,
    )

    adjacency_ok = _agent_v2_v92_last_user_turn_matches_availability(
        world_runtime_order,
        focus,
    )

    switch_perception = {
        "entities": {
            "resource_types": [current_type],
            "resource_type": current_type,
        },
        "semantic_frame": {
            "source": "ai",
            "schema_valid": True,
            "acts": [{
                "act_id": "v94_switch",
                "operation": "query_availability",
                "domain": "booking",
                "target": {
                    "resource": "court",
                    "resource_types": [current_type],
                    "resource_type": current_type,
                    "source": "current_user_turn",
                },
                "temporal": {},
                "changes": [],
                "requested_facts": ["available_slots"],
                "commitment": {
                    "wants_write": False,
                    "wants_information": True,
                },
                "provenance": [{
                    "field": "target.resource_types",
                    "source": "current_user_turn",
                    "evidence": "nuevo resource type",
                    "reference_id": None,
                    "scope_id": None,
                    "question_id": None,
                    "option_id": None,
                }],
            }],
            "requested_facts": ["available_slots"],
            "context_relation": {"type": "new_question"},
        },
    }

    candidate, candidate_reason = (
        _agent_v2_v92_structural_ellipsis_candidate(
            switch_perception,
            world_runtime_order,
        )
    )

    projected = switch_perception
    if candidate:
        projected = _agent_v2_v91_project_contextual_read(
            switch_perception,
            current_message,
            world_runtime_order,
            candidate,
            candidate.get("current_resource_types") or [],
            evidence="nuevo resource type",
            reason="v94_runtime_history_order_eval",
            inherit_day=bool(candidate.get("inherit_day")),
            inherit_start=bool(candidate.get("inherit_start")),
            inherit_daypart=bool(candidate.get("inherit_daypart")),
            inherit_duration=bool(candidate.get("inherit_duration")),
        )

    frame = _agent_v2_semantic_frame(projected)
    availability = next((
        act
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "query_availability"
    ), {})
    temporal = (
        availability.get("temporal")
        if isinstance(availability.get("temporal"), dict)
        else {}
    )
    target = (
        availability.get("target")
        if isinstance(availability.get("target"), dict)
        else {}
    )

    auth = _agent_v2_context_authorization(
        projected,
        world_runtime_order,
    )
    contract = dict(projected.get("execution_contract") or {})

    # Fail-closed: si existe un USER intermedio distinto, el source ya no es
    # inmediatamente anterior al current turn.
    nonadjacent_world = {
        **world_runtime_order,
        "stored_memory": {
            **world_runtime_order["stored_memory"],
            "history": [
                {
                    "role": "user",
                    "content": previous_message,
                    "timestamp": now_iso,
                    "reference_id": previous_ref,
                },
                {
                    "role": "user",
                    "content": "otro turno usuario intermedio",
                    "timestamp": now_iso,
                    "reference_id": "user_turn:v94_middle:1",
                },
                {
                    "role": "user",
                    "content": current_message,
                    "timestamp": now_iso,
                    "reference_id": current_ref,
                },
            ],
        },
    }
    nonadjacent_focus = _agent_v2_v91_verified_availability_focus(
        nonadjacent_world,
    )
    nonadjacent_rejected = not _agent_v2_v92_last_user_turn_matches_availability(
        nonadjacent_world,
        nonadjacent_focus,
    )

    results.extend([
        {
            "name": "v94_production_history_order_recognizes_previous_availability_turn",
            "ok": bool(adjacency_ok),
        },
        {
            "name": "v94_production_history_order_enables_structural_resource_switch",
            "ok": bool(
                candidate
                and candidate_reason == "structural_ellipsis_ready"
            ),
        },
        {
            "name": "v94_resource_switch_inherits_verified_day",
            "ok": bool(
                candidate
                and temporal.get("day") in {"2026-09-21", "Lunes 21/09"}
            ),
        },
        {
            "name": "v94_current_resource_replaces_previous_resource",
            "ok": bool(
                candidate
                and target.get("resource_type") == current_type
                and previous_type not in (target.get("resource_types") or [])
            ),
        },
        {
            "name": "v94_context_reference_resolves_to_previous_user_turn_not_current",
            "ok": bool(
                candidate
                and auth.get("authorized")
                and auth.get("reference_id") == previous_ref
                and auth.get("reference_id") != current_ref
            ),
        },
        {
            "name": "v94_projected_contract_authorizes_availability_tool",
            "ok": bool(
                candidate
                and contract.get("authoritative")
                and "consultar_disponibilidad" in set(
                    contract.get("allowed_tools") or []
                )
            ),
        },
        {
            "name": "v94_nonadjacent_user_turn_remains_fail_closed",
            "ok": bool(nonadjacent_rejected),
        },
    ])

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V96 — OBSERVATION-FIRST AVAILABILITY RENDERER
# ============================================================================
# El renderer no reautoriza semántica ya aprobada por Contract/Policy.
# Una Observation real de consultar_disponibilidad con parrilla por cancha y sin
# hora exacta se presenta siempre con la plantilla comercial determinista.
AGENT_V2_CONTEXTUAL_AVAILABILITY_VERSION = "v96"



# ============================================================================
# V100 — UNIFIED CONVERSATION KERNEL
# ============================================================================
# Objetivo arquitectónico:
#   IA entiende una vez; Python valida realidad/identidad/efectos.
#
# Este kernel reemplaza los resolvers conversacionales específicos por una sola
# frontera genérica que resuelve:
#   - respuestas a preguntas del propio agente (PendingInteraction),
#   - continuidad/elipsis contra el foco conversacional anterior,
#   - cambios de tema sin destruir contexto útil,
#   - referencias históricas READ con una política de riesgo más permisiva,
#   - Desired State + TaskGraph como representación intermedia estable.
#
# Importante:
#   - no contiene regex/keywords para decidir intención del cliente;
#   - no amplía permisos de tools;
#   - no reemplaza Policy Guard, idempotencia, calendario, pagos ni montos;
#   - WRITEs siguen necesitando Semantic Effect Verification + target válido.

AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v102"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_late_context_arbitration_v102"
AGENT_V2_GENERIC_PENDING_TTL_MINUTES = 6 * 60
AGENT_V2_V102_DEFER_CONTEXT_MANAGER = contextvars.ContextVar(
    "agent_v2_v102_defer_context_manager", default=False
)
AGENT_V2_GENERIC_CONTEXT_HISTORY_LIMIT = 10


def _agent_v2_v100_conversation_frame(av2: Dict[str, Any]) -> Dict[str, Any]:
    frame = av2.get("conversation_frame") if isinstance(av2, dict) else None
    if not isinstance(frame, dict):
        frame = {}
    frame.setdefault("focus", None)
    frame.setdefault("active_tasks", [])
    frame.setdefault("pending_interactions", [])
    frame.setdefault("commitments", [])
    frame.setdefault("referenced_entities", [])
    frame.setdefault("completed_tasks", [])
    frame.setdefault("last_understanding", None)
    frame.setdefault("last_internal_repair", None)
    frame.setdefault("version", AGENT_V2_UNIFIED_CONVERSATION_KERNEL)
    return frame


def _agent_v2_v100_nonempty(value: Any) -> bool:
    return value not in (None, "", [], {}, ())


def _agent_v2_v100_operation_risk(operation: Any) -> str:
    op = str(operation or "").strip()
    if op.startswith("query_") or op in {"greet", "close_conversation", "clarify"}:
        return "read"
    if op in {"create_booking", "reschedule_booking", "modify_resource", "add_resource", "remove_resource", "join_waitlist", "register_event"}:
        return "reversible_write"
    if op in {"cancel_booking", "register_payment", "choose_payment_method", "register_event_payment", "choose_event_payment_method"}:
        return "sensitive_write"
    if op in {"handoff_human", "special_event"}:
        return "support"
    return "unknown"


def _agent_v2_v100_goal_to_operations() -> Dict[str, List[str]]:
    reverse: Dict[str, List[str]] = {}
    for operation, goals in (AGENT_V2_OPERATION_GOALS or {}).items():
        for goal in goals or []:
            reverse.setdefault(str(goal), []).append(str(operation))
    return reverse


def _agent_v2_v100_allowed_operations_for_question(question: Dict[str, Any]) -> List[str]:
    q = dict(question or {})
    explicit = [
        str(op).strip()
        for op in (q.get("allowed_operations") or [])
        if str(op or "").strip() in AGENT_V2_SEMANTIC_OPERATIONS
    ]
    if explicit:
        return list(dict.fromkeys(explicit))

    snapshot = (
        q.get("action_snapshot")
        if isinstance(q.get("action_snapshot"), dict)
        else q.get("operation_contract")
        if isinstance(q.get("operation_contract"), dict)
        else {}
    )
    operation = str(snapshot.get("operation") or q.get("operation") or "").strip()
    if operation in AGENT_V2_SEMANTIC_OPERATIONS:
        explicit.append(operation)

    reverse = _agent_v2_v100_goal_to_operations()
    for goal in q.get("goal_context") or []:
        explicit.extend(reverse.get(str(goal), []))

    # Compatibilidad de migración para pendings creados por builds anteriores.
    # Esto clasifica un CAMPO TIPADO del sistema, nunca lenguaje del cliente.
    legacy_typed_schema = {
        "hora": ["create_booking", "query_availability", "reschedule_booking"],
        "hora_aclaracion": ["create_booking", "query_availability", "reschedule_booking"],
        "dia": ["create_booking", "query_availability", "reschedule_booking"],
        "dia_hora_reserva": ["create_booking", "query_availability"],
        "cancha": ["create_booking"],
        "confirmar_slot": ["create_booking"],
        "released_booking_rebook": ["create_booking"],
        "confirmar_reprogramacion": ["reschedule_booking"],
        "waitlist_offer": ["join_waitlist"],
        "reserva_especifica": [
            "cancel_booking", "reschedule_booking", "modify_resource",
            "add_resource", "remove_resource", "register_payment",
            "choose_payment_method", "query_reservation",
        ],
        "comprobante": ["register_payment"],
        "team_name": ["register_event"],
        "event_selection": ["register_event", "query_event"],
        "inscripcion_evento": ["register_event_payment"],
        "payment_destination": ["register_payment", "register_event_payment"],
    }
    explicit.extend(legacy_typed_schema.get(str(q.get("field") or q.get("type") or ""), []))
    return list(dict.fromkeys(
        op for op in explicit if op in AGENT_V2_SEMANTIC_OPERATIONS
    ))


def _agent_v2_v100_question_to_interaction(
    question: Dict[str, Any],
    *,
    owner: str = "",
) -> Dict[str, Any]:
    q = dict(question or {})
    interaction_id = str(q.get("interaction_id") or q.get("question_id") or uuid.uuid4())
    question_id = str(q.get("question_id") or interaction_id)
    scope_id = str(q.get("scope_id") or "")
    raw_options = list(q.get("options") or [])
    # Las preguntas legacy suelen persistir valores escalares. El Conversation
    # Manager necesita identidades estables para expresar una selección semántica
    # ("la primera", "la de las ocho", etc.) sin reinterpretar texto en Python.
    options = []
    for option_index, raw_option in enumerate(raw_options):
        if isinstance(raw_option, dict):
            option = dict(raw_option)
            value = (
                option.get("value")
                or option.get("hora")
                or option.get("cancha")
                or option.get("label")
            )
            option_id = option.get("option_id") or option.get("reservation_id")
        else:
            option = {}
            value = raw_option
            option_id = None
        option["option_id"] = str(
            option_id or f"{question_id}:option_{option_index + 1}"
        )
        option["value"] = value
        options.append(option)
    action_snapshot = (
        dict(q.get("action_snapshot") or {})
        if isinstance(q.get("action_snapshot"), dict)
        else dict(q.get("operation_contract") or {})
        if isinstance(q.get("operation_contract"), dict)
        else dict(q.get("offer_contract") or {})
        if isinstance(q.get("offer_contract"), dict)
        else {}
    )
    allowed_operations = _agent_v2_v100_allowed_operations_for_question(q)
    if q.get("interaction_kind"):
        kind = str(q.get("interaction_kind"))
    elif options:
        kind = "choice"
    elif action_snapshot and any(
        op in AGENT_V2_WRITE_OPERATIONS for op in allowed_operations
    ):
        kind = "confirmation"
    elif str(q.get("field") or "").endswith("offer") or q.get("offer_contract"):
        kind = "offer"
    else:
        kind = "value"

    target_refs = []
    for key in ("reservation_id", "registration_id", "event_id", "reference_id"):
        value = str(q.get(key) or "").strip()
        if value:
            target_refs.append({"kind": key, "id": value})
    target = action_snapshot.get("target") if isinstance(action_snapshot.get("target"), dict) else {}
    for key in ("reservation_id", "registration_id", "event_id"):
        value = str(target.get(key) or "").strip()
        if value and not any(item.get("kind") == key and item.get("id") == value for item in target_refs):
            target_refs.append({"kind": key, "id": value})

    return {
        "interaction_id": interaction_id,
        "question_id": question_id,
        "scope_id": scope_id,
        "owner": str(q.get("_memory_owner") or owner or ""),
        "kind": kind,
        "field": str(q.get("field") or q.get("type") or "value"),
        "status": str(q.get("interaction_status") or "active"),
        "options": options,
        "goal_context": list(q.get("goal_context") or []),
        "allowed_operations": allowed_operations,
        "action_snapshot": action_snapshot,
        "target_refs": target_refs,
        "question_text": str(q.get("question") or q.get("prompt") or q.get("message") or ""),
        "source": str(q.get("source") or ""),
        "source_turn_id": q.get("source_turn_id"),
        "created_at": q.get("created_at"),
        "expires_at": q.get("expires_at"),
        "context": {
            key: q.get(key)
            for key in (
                "dia", "hora", "cancha", "duracion_horas", "franja_dia",
                "booking_shape", "requested_hours", "requested_court_count",
                "resource_type", "resource_types", "reservation_id",
                "registration_id", "event_id", "event_name", "event_date",
                "team_name", "payment_method",
            )
            if _agent_v2_v100_nonempty(q.get(key))
        },
    }


def _agent_v2_v100_active_interactions_from_world(world: Dict[str, Any]) -> List[Dict[str, Any]]:
    direct = world.get("pending_interactions") if isinstance(world, dict) else None
    if isinstance(direct, list):
        rows = [dict(item) for item in direct if isinstance(item, dict)]
    else:
        frame = (world or {}).get("conversation_frame") or {}
        rows = [
            dict(item) for item in (frame.get("pending_interactions") or [])
            if isinstance(item, dict)
        ]
    owner = str(((world or {}).get("facts") or {}).get("memory_owner") or "")
    now = datetime.datetime.now(TIMEZONE)
    out = []
    for item in rows:
        if str(item.get("status") or "active") not in {"active", "suspended", "engaged"}:
            continue
        if owner and item.get("owner") and str(item.get("owner")) != owner:
            continue
        expires = _parse_context_timestamp(item.get("expires_at"))
        if expires and now > expires:
            continue
        out.append(item)
    if out:
        return out[-12:]

    # Migración transparente desde open_questions de builds anteriores.
    questions = list((world or {}).get("open_questions") or [])
    return [
        _agent_v2_v100_question_to_interaction(q, owner=owner)
        for q in questions
        if isinstance(q, dict)
    ][-12:]


def _agent_v2_v100_focus_from_world(world: Dict[str, Any]) -> Dict[str, Any]:
    frame = (world or {}).get("conversation_frame") or {}
    focus = frame.get("focus") if isinstance(frame, dict) else None
    if isinstance(focus, dict) and focus.get("operation"):
        return dict(focus)

    # Migración desde availability_context: se convierte en foco genérico, sin
    # otorgarle por sí solo autoridad de escritura.
    stored = _agent_v2_stored_memory(world or {})
    availability = dict(stored.get("availability_context") or {})
    if availability:
        target = {
            "resource": "court",
            "resource_types": list(availability.get("resource_types") or []),
            "resource_type": availability.get("resource_type"),
        }
        temporal = {
            "day": availability.get("day_iso") or availability.get("dia_resuelto") or availability.get("dia"),
            "start": availability.get("hora"),
            "daypart": availability.get("franja_dia"),
            "duration_hours": availability.get("duracion_horas"),
        }
        act = {
            "act_id": "v100_migrated_availability_focus",
            "operation": "query_availability",
            "domain": "booking",
            "target": target,
            "temporal": temporal,
            "quantity": {},
            "changes": [],
            "requested_facts": ["available_slots"],
            "commitment": {"wants_write": False, "wants_information": True},
            "provenance": [],
        }
        source_message = str(availability.get("source_message") or "")
        ref_id = ""
        if source_message:
            for row in reversed(_agent_v2_history_with_reference_ids(world or {})):
                if row.get("role") == "user" and str(row.get("content") or "").strip() == source_message.strip():
                    ref_id = str(row.get("reference_id") or "")
                    break
        return {
            "focus_id": str(availability.get("scope_id") or availability.get("source_turn_id") or "legacy_availability"),
            "operation": "query_availability",
            "risk": "read",
            "act": act,
            "scope_id": availability.get("scope_id"),
            "reference_id": ref_id,
            "source_message": source_message,
            "updated_at": availability.get("created_at"),
            "verified_context": {"availability": availability},
        }

    last = stored.get("last_perception") if isinstance(stored.get("last_perception"), dict) else {}
    frame_last = _agent_v2_semantic_frame(last)
    operational = [
        dict(act) for act in (frame_last.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") not in {"greet", "close_conversation", "clarify", "unknown", ""}
    ]
    if len(operational) == 1:
        act = operational[0]
        return {
            "focus_id": str(stored.get("last_turn_id") or "legacy_last_perception"),
            "operation": str(act.get("operation") or ""),
            "risk": _agent_v2_v100_operation_risk(act.get("operation")),
            "act": act,
            "scope_id": stored.get("active_scope_id"),
            "reference_id": "",
            "source_message": "",
            "updated_at": stored.get("last_updated"),
            "verified_context": {},
        }
    return {}


def _agent_v2_v100_context_needed(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame)
    if str(relation.get("type") or "") in {"answers_pending", "references_previous", "unknown"}:
        return True
    interactions = _agent_v2_v100_active_interactions_from_world(world or {})
    focus = _agent_v2_v100_focus_from_world(world or {})
    acts = [
        act for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") not in {"greet", "close_conversation"}
    ]
    if interactions and (not acts or any(str(a.get("operation") or "") in {"unknown", "clarify"} for a in acts)):
        return True
    if not focus:
        return False
    if not acts:
        return True

    # Una consulta/pedido completamente direccionado por el turno actual no
    # necesita tocar memoria. La comprobación es estructural, no lingüística.
    for act in acts:
        op = str(act.get("operation") or "")
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
        requested = list(act.get("requested_facts") or [])
        if op == "query_policy" and requested:
            continue
        if op == "query_price" and (target.get("resource") or requested):
            continue
        if op == "query_availability" and any(
            _agent_v2_v100_nonempty(temporal.get(key))
            for key in ("day", "start", "daypart", "mode", "after", "before")
        ):
            continue
        if op in AGENT_V2_WRITE_OPERATIONS and any(
            isinstance(item, dict)
            and item.get("source") == "current_user_turn"
            and str(item.get("evidence") or "").strip()
            for item in (act.get("provenance") or [])
        ):
            continue
        return True
    return False


def _agent_v2_v100_known_reference_ids(world: Dict[str, Any]) -> set:
    refs = {
        str(row.get("reference_id") or "")
        for row in _agent_v2_history_with_reference_ids(world or {})[-AGENT_V2_GENERIC_CONTEXT_HISTORY_LIMIT:]
        if isinstance(row, dict) and str(row.get("reference_id") or "")
    }
    focus = _agent_v2_v100_focus_from_world(world or {})
    if focus.get("reference_id"):
        refs.add(str(focus.get("reference_id")))
    for interaction in _agent_v2_v100_active_interactions_from_world(world or {}):
        for item in interaction.get("target_refs") or []:
            if isinstance(item, dict) and item.get("id"):
                refs.add(str(item.get("id")))
    return refs


def _agent_v2_v100_current_act_for_operation(
    perception: Dict[str, Any], operation: str,
) -> Optional[Dict[str, Any]]:
    frame = _agent_v2_semantic_frame(perception or {})
    exact = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") == operation
    ]
    if exact:
        return exact[0]
    operational = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") not in {"greet", "close_conversation", "clarify", "unknown", ""}
    ]
    return operational[0] if len(operational) == 1 else None


def _agent_v2_v100_merge_structured_dict(base: Dict[str, Any], current: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(base or {})
    for key, value in (current or {}).items():
        if _agent_v2_v100_nonempty(value):
            merged[key] = value
    return merged


def _agent_v2_v100_question_defaults(question: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    q = dict(question or {})
    return {
        "target": {
            "reservation_id": q.get("reservation_id"),
            "registration_id": q.get("registration_id"),
            "event_id": q.get("event_id"),
            "label": q.get("cancha") or q.get("event_name"),
            "resource_type": q.get("resource_type"),
            "resource_types": q.get("resource_types"),
        },
        "temporal": {
            "day": q.get("dia") or q.get("event_date"),
            "start": q.get("hora"),
            "daypart": q.get("franja_dia"),
            "duration_hours": q.get("duracion_horas"),
            "structure": q.get("booking_shape"),
            "times": q.get("requested_hours"),
        },
        "quantity": {
            "count": q.get("requested_court_count"),
            "duration_hours": q.get("duracion_horas"),
        },
    }


def _agent_v2_v100_project_pending_resolution(
    perception: Dict[str, Any],
    interaction: Dict[str, Any],
    decision: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    clean = dict(perception or {})
    mode = str(decision.get("resolution") or "supply")
    qid = str(interaction.get("question_id") or interaction.get("interaction_id") or "")
    scope_id = str(interaction.get("scope_id") or "")
    evidence = str(decision.get("evidence") or "").strip()

    # Una interacción choice se materializa desde el option_id elegido por la
    # IA. Para horas también recuperamos ese ID desde el valor temporal que ya
    # entendió Perception. Sólo comparamos estructuras tipadas; no hay reglas de
    # intención ni frases del usuario hardcodeadas.
    option_rows = [
        dict(item) for item in (interaction.get("options") or [])
        if isinstance(item, dict) and item.get("option_id")
    ]
    selected_option = next((
        item for item in option_rows
        if str(item.get("option_id") or "") == str(decision.get("option_id") or "")
    ), None)
    interaction_field = str(interaction.get("field") or "").strip()
    if (
        selected_option is None
        and option_rows
        and interaction_field in {"hora", "hora_aclaracion"}
    ):
        offered_hours = [item.get("value") for item in option_rows]
        current_frame = _agent_v2_semantic_frame(clean)
        candidates = []
        for current in current_frame.get("acts") or []:
            if not isinstance(current, dict):
                continue
            temporal = current.get("temporal") if isinstance(current.get("temporal"), dict) else {}
            candidates.extend([temporal.get("start"), *(temporal.get("times") or [])])
        entities = clean.get("entities") if isinstance(clean.get("entities"), dict) else {}
        candidates.extend([entities.get("hora"), *(entities.get("horas") or [])])
        matched_hours = []
        for candidate in candidates:
            matched = _agent_v2_resolve_semantic_hour_against_pending_options(
                candidate, offered_hours,
            )
            if matched and matched not in matched_hours:
                matched_hours.append(matched)
        if len(matched_hours) == 1:
            selected_option = next((
                item for item in option_rows
                if normalizar_hora_detectada(item.get("value")) == matched_hours[0]
            ), None)
            if selected_option:
                decision = {
                    **dict(decision or {}),
                    "option_id": selected_option.get("option_id"),
                }

    if (
        str(interaction.get("kind") or "") == "choice"
        and str(decision.get("resolution") or "") in {"select", "supply"}
        and option_rows
        and selected_option is None
    ):
        print(
            "   🚫 [AgentV2 V149 PENDING CHOICE] "
            "la IA no vinculó una opción real; selección no materializada"
        )
        return perception

    if mode == "deny":
        deny_act = {
            "act_id": f"v100_pending_denial_{qid or uuid.uuid4().hex[:8]}",
            "operation": "clarify",
            "domain": "conversation",
            "target": {"resource": "conversation"},
            "temporal": {},
            "quantity": {},
            "changes": [],
            "requested_facts": [],
            "commitment": {"wants_write": False, "wants_information": False},
            "provenance": [{
                "field": "context.pending_resolution",
                "source": "current_user_turn",
                "evidence": evidence,
                "question_id": qid,
                "scope_id": scope_id,
            }],
        }
        frame = dict(_agent_v2_semantic_frame(clean) or {})
        frame.update({
            "source": "ai",
            "schema_valid": True,
            "turn_type": "denial",
            "intent": {"domain": "conversation", "operation": "clarify"},
            "targets": [deny_act["target"]],
            "temporal": {},
            "requested_changes": [],
            "requested_facts": [],
            "commitment": deny_act["commitment"],
            "context_relation": {
                "type": "answers_pending",
                "question_id": qid,
                "scope_id": scope_id,
                "references_previous_user_turn": False,
                "references_agent_offer": True,
                "answers_pending_question": True,
            },
            "acts": [deny_act],
            "ambiguity": {"required": False, "field": None, "reason": "", "alternatives": []},
        })
        clean["semantic_frame"] = frame
        clean["pending_relation"] = "answers_pending"
        clean["answers_pending_field"] = interaction.get("field")
        clean["_v100_pending_resolution"] = {
            "interaction_id": interaction.get("interaction_id"),
            "question_id": qid,
            "scope_id": scope_id,
            "mode": "deny",
        }
        return clean

    allowed = list(interaction.get("allowed_operations") or [])
    operation = str(decision.get("operation") or "").strip()
    if operation not in allowed:
        if len(allowed) == 1:
            operation = allowed[0]
        else:
            current_ops = [
                str(act.get("operation") or "")
                for act in (_agent_v2_semantic_frame(clean).get("acts") or [])
                if isinstance(act, dict)
                and str(act.get("operation") or "") in allowed
            ]
            operation = current_ops[0] if len(set(current_ops)) == 1 else ""
    if not operation:
        return perception

    snapshot = dict(interaction.get("action_snapshot") or {})
    if str(snapshot.get("operation") or "") != operation:
        snapshot = {}
    current_act = _agent_v2_v100_current_act_for_operation(clean, operation) or {}
    defaults = _agent_v2_v100_question_defaults(interaction.get("context") or {})

    act = dict(snapshot or current_act or {})
    act.setdefault("act_id", f"v100_pending_{operation}_{uuid.uuid4().hex[:8]}")
    act["operation"] = operation
    act.setdefault("domain", current_act.get("domain") or snapshot.get("domain") or "booking")
    act["target"] = _agent_v2_v100_merge_structured_dict(
        _agent_v2_v100_merge_structured_dict(defaults.get("target") or {}, snapshot.get("target") or {}),
        current_act.get("target") or {},
    )
    act["temporal"] = _agent_v2_v100_merge_structured_dict(
        _agent_v2_v100_merge_structured_dict(defaults.get("temporal") or {}, snapshot.get("temporal") or {}),
        current_act.get("temporal") or {},
    )
    act["quantity"] = _agent_v2_v100_merge_structured_dict(
        _agent_v2_v100_merge_structured_dict(defaults.get("quantity") or {}, snapshot.get("quantity") or {}),
        current_act.get("quantity") or {},
    )
    if selected_option is not None:
        selected_value = selected_option.get("value")
        act["selection"] = {
            "type": interaction_field or "option",
            "option_id": selected_option.get("option_id"),
            "value": selected_value,
        }
        if interaction_field in {"hora", "hora_aclaracion"}:
            selected_hour = normalizar_hora_detectada(selected_value)
            if hora_es_valida(selected_hour):
                act["temporal"] = dict(act.get("temporal") or {})
                act["temporal"]["start"] = selected_hour
                act["temporal"]["times"] = [selected_hour]
                clean_entities = dict(clean.get("entities") or {})
                clean_entities["hora"] = selected_hour
                clean_entities["horas"] = [selected_hour]
                clean["entities"] = clean_entities
        elif interaction_field == "cancha":
            act["target"] = dict(act.get("target") or {})
            act["target"]["label"] = selected_value
        elif interaction_field == "resource_type":
            act["target"] = dict(act.get("target") or {})
            act["target"]["resource_type"] = selected_value
    if current_act.get("changes"):
        by_field = {
            str(item.get("field") or uuid.uuid4()): dict(item)
            for item in (snapshot.get("changes") or [])
            if isinstance(item, dict)
        }
        for item in current_act.get("changes") or []:
            if isinstance(item, dict):
                by_field[str(item.get("field") or uuid.uuid4())] = dict(item)
        act["changes"] = list(by_field.values())
    else:
        act["changes"] = list(snapshot.get("changes") or [])
    act["requested_facts"] = list(dict.fromkeys([
        *(snapshot.get("requested_facts") or []),
        *(current_act.get("requested_facts") or []),
    ]))
    wants_write = operation in AGENT_V2_WRITE_OPERATIONS
    act["commitment"] = {
        "wants_write": wants_write,
        "wants_information": not wants_write,
    }
    provenance = [
        dict(item) for item in (
            list(snapshot.get("provenance") or []) + list(current_act.get("provenance") or [])
        ) if isinstance(item, dict)
    ]
    target_ref = next((
        str(item.get("id") or "")
        for item in interaction.get("target_refs") or []
        if isinstance(item, dict) and item.get("id")
    ), "")
    provenance.append({
        "field": "context.pending_interaction",
        "source": "pending_option",
        "evidence": evidence,
        "question_id": qid,
        "scope_id": scope_id,
        "option_id": decision.get("option_id"),
        "reference_id": target_ref or None,
    })
    act["provenance"] = provenance

    current_frame = dict(_agent_v2_semantic_frame(clean) or {})
    greet_acts = [
        dict(item) for item in (current_frame.get("acts") or [])
        if isinstance(item, dict) and item.get("operation") == "greet"
    ]
    relation = {
        "type": "answers_pending",
        "question_id": qid,
        "scope_id": scope_id,
        "references_previous_user_turn": False,
        "references_agent_offer": True,
        "answers_pending_question": True,
    }
    current_frame.update({
        "source": "ai",
        "schema_valid": True,
        "turn_type": "request" if wants_write else "question",
        "intent": {"domain": act.get("domain") or "booking", "operation": operation},
        "targets": [dict(act.get("target") or {})],
        "temporal": dict(act.get("temporal") or {}),
        "requested_changes": list(act.get("changes") or []),
        "requested_facts": list(act.get("requested_facts") or []),
        "commitment": dict(act.get("commitment") or {}),
        "context_relation": relation,
        "acts": greet_acts + [act],
        "ambiguity": {"required": False, "field": None, "reason": "", "alternatives": []},
    })
    clean["semantic_frame"] = current_frame
    clean["pending_relation"] = "answers_pending"
    clean["answers_pending_field"] = interaction.get("field")
    clean["_v100_pending_resolution"] = {
        "interaction_id": interaction.get("interaction_id"),
        "question_id": qid,
        "scope_id": scope_id,
        "mode": mode,
        "operation": operation,
    }
    return clean


def _agent_v2_v100_get_path(data: Dict[str, Any], path: str) -> Any:
    current: Any = data
    for part in str(path or "").split("."):
        if not isinstance(current, dict):
            return None
        current = current.get(part)
    return current


def _agent_v2_v100_set_path(data: Dict[str, Any], path: str, value: Any) -> None:
    parts = str(path or "").split(".")
    current = data
    for part in parts[:-1]:
        if not isinstance(current.get(part), dict):
            current[part] = {}
        current = current[part]
    if parts:
        current[parts[-1]] = value


def _agent_v2_v100_project_focus_delta(
    perception: Dict[str, Any],
    focus: Dict[str, Any],
    decision: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    clean = dict(perception or {})
    operation = str(decision.get("operation") or focus.get("operation") or "").strip()
    if operation not in AGENT_V2_SEMANTIC_OPERATIONS:
        return perception
    focus_act = dict(focus.get("act") or {})
    current_act = _agent_v2_v100_current_act_for_operation(clean, operation)
    if current_act is None:
        frame_now = _agent_v2_semantic_frame(clean)
        candidates = [
            dict(act) for act in (frame_now.get("acts") or [])
            if isinstance(act, dict)
            and str(act.get("operation") or "") not in {"greet", "close_conversation", "clarify", "unknown", ""}
        ]
        current_act = candidates[0] if len(candidates) == 1 else {}
    inherit_fields = {
        str(value or "").strip()
        for value in (decision.get("inherit_fields") or [])
        if str(value or "").strip()
    }

    # Start from a clean operation shell. Only explicitly requested inheritance
    # can cross turns; the current semantic delta always wins.
    act = {
        "act_id": str((current_act or {}).get("act_id") or f"v100_focus_{operation}_{uuid.uuid4().hex[:8]}"),
        "operation": operation,
        "domain": (current_act or {}).get("domain") or focus_act.get("domain") or "booking",
        "target": {},
        "temporal": {},
        "quantity": {},
        "changes": list((current_act or {}).get("changes") or []),
        "requested_facts": list((current_act or {}).get("requested_facts") or []),
        "commitment": {},
        "provenance": [
            dict(item) for item in ((current_act or {}).get("provenance") or [])
            if isinstance(item, dict)
        ],
    }
    source_paths = {
        "target.resource", "target.resource_type", "target.resource_types",
        "target.label", "target.reservation_id", "target.registration_id",
        "temporal.day", "temporal.start", "temporal.daypart",
        "temporal.duration_hours", "temporal.mode", "temporal.after",
        "temporal.before", "quantity.count", "quantity.duration_hours",
    }
    for path in source_paths:
        current_value = _agent_v2_v100_get_path(current_act or {}, path)
        if _agent_v2_v100_nonempty(current_value):
            _agent_v2_v100_set_path(act, path, current_value)
            continue
        if path in inherit_fields:
            previous_value = _agent_v2_v100_get_path(focus_act, path)
            if _agent_v2_v100_nonempty(previous_value):
                _agent_v2_v100_set_path(act, path, previous_value)
                act["provenance"].append({
                    "field": path,
                    "source": "previous_user_turn",
                    "evidence": str(focus.get("source_message") or "")[:500],
                    "reference_id": focus.get("reference_id"),
                    "scope_id": focus.get("scope_id"),
                    "question_id": None,
                    "option_id": None,
                })

    # Preserve current structured target/temporal fields not in the canonical map.
    act["target"] = _agent_v2_v100_merge_structured_dict(act.get("target") or {}, (current_act or {}).get("target") or {})
    act["temporal"] = _agent_v2_v100_merge_structured_dict(act.get("temporal") or {}, (current_act or {}).get("temporal") or {})
    act["quantity"] = _agent_v2_v100_merge_structured_dict(act.get("quantity") or {}, (current_act or {}).get("quantity") or {})

    if operation == "query_availability" and not act["requested_facts"]:
        act["requested_facts"] = ["available_slots"]
    wants_write = operation in AGENT_V2_WRITE_OPERATIONS
    current_commitment = (current_act or {}).get("commitment") if isinstance((current_act or {}).get("commitment"), dict) else {}
    act["commitment"] = {
        "wants_write": bool(current_commitment.get("wants_write")) if current_commitment else wants_write,
        "wants_information": bool(current_commitment.get("wants_information")) if current_commitment else not wants_write,
    }

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    greet_acts = [
        dict(item) for item in (frame.get("acts") or [])
        if isinstance(item, dict) and item.get("operation") == "greet"
    ]
    reference_id = str(decision.get("reference_id") or focus.get("reference_id") or "")
    relation = {
        "type": "references_previous",
        "question_id": None,
        "reference_id": reference_id or None,
        "scope_id": focus.get("scope_id"),
        "references_previous_user_turn": True,
        "references_agent_offer": False,
        "answers_pending_question": False,
    }
    frame.update({
        "source": "ai",
        "schema_valid": True,
        "turn_type": "request" if act["commitment"].get("wants_write") else "question",
        "intent": {"domain": act.get("domain") or "booking", "operation": operation},
        "targets": [dict(act.get("target") or {})],
        "temporal": dict(act.get("temporal") or {}),
        "requested_changes": list(act.get("changes") or []),
        "requested_facts": list(act.get("requested_facts") or []),
        "commitment": dict(act.get("commitment") or {}),
        "context_relation": relation,
        "acts": greet_acts + [act],
        "ambiguity": {"required": False, "field": None, "reason": "", "alternatives": []},
    })
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "references_previous"
    clean["references_prior_user_input"] = True
    clean["_v100_focus_resolution"] = {
        "focus_id": focus.get("focus_id"),
        "operation": operation,
        "reference_id": reference_id,
        "inherit_fields": sorted(inherit_fields),
    }
    return clean


def _agent_v2_v102_conservative_read_inheritance(
    perception: Dict[str, Any],
    focus: Dict[str, Any],
    decision: Dict[str, Any],
) -> Dict[str, Any]:
    """Completa sólo contexto READ omitido después de que IA decidió continuidad.

    No interpreta texto. Usa estructuras ya tipadas. Para disponibilidad hereda
    únicamente día/duración y target omitido; nunca una hora exacta por defecto.
    El turno actual siempre gana.
    """
    clean = dict(decision or {})
    operation = str(clean.get("operation") or focus.get("operation") or "").strip()
    if _agent_v2_v100_operation_risk(operation) != "read":
        return clean
    if operation != str(focus.get("operation") or ""):
        return clean

    current_act = _agent_v2_v100_current_act_for_operation(perception or {}, operation) or {}
    focus_act = dict(focus.get("act") or {})
    inherited = {
        str(path or "").strip() for path in (clean.get("inherit_fields") or [])
        if str(path or "").strip()
    }

    # Disponibilidad amplia: día/duración y recurso omitido son contexto seguro.
    # Una hora exacta NO se hereda automáticamente porque cambiaría una consulta
    # amplia en un slot específico sin evidencia del turno actual.
    safe_paths = (
        "temporal.day",
        "temporal.daypart",
        "temporal.duration_hours",
        "target.resource",
        "target.resource_type",
        "target.resource_types",
        "quantity.duration_hours",
    ) if operation == "query_availability" else ()

    for path in safe_paths:
        if _agent_v2_v100_nonempty(_agent_v2_v100_get_path(current_act, path)):
            continue
        if _agent_v2_v100_nonempty(_agent_v2_v100_get_path(focus_act, path)):
            inherited.add(path)

    clean["inherit_fields"] = sorted(inherited)
    return clean


def _agent_v2_v102_context_is_already_grounded(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    """Evita una segunda reinterpretación si una capa madura ya probó el binding."""
    if (perception or {}).get("_v91_contextual_availability_resolved") is True:
        # V91 puede reconstruir un READ histórico, pero eso no demuestra que el
        # turno sea independiente de una pregunta abierta. Si existe una
        # interacción activa, el Conversation Manager debe arbitrarla y devolver
        # IDs reales antes de congelar el significado.
        interactions = _agent_v2_v100_active_interactions_from_world(world or {})
        auth = _agent_v2_context_authorization(perception or {}, world or {})
        if interactions and not (
            auth.get("authorized")
            and str(auth.get("relation") or "") == "answers_pending"
        ):
            print(
                "   🔄 [AgentV2 V149 CONTEXT ARBITRATION] "
                "V91 produjo un READ pero existe una interacción activa; "
                "Conversation Manager decide continuidad"
            )
            return False
        return True
    if (perception or {}).get("_v93_same_source_replay_bypass") is True:
        return True
    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame) or {}
    if str(relation.get("type") or "") not in {"answers_pending", "references_previous"}:
        return False
    auth = _agent_v2_context_authorization(perception or {}, world or {})
    return bool(auth.get("authorized"))


async def _agent_v2_v100_resolve_conversation_context(
    mensaje: str,
    first_perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Única autoridad IA para relacionar el turno actual con memoria.

    No decide tools ni modifica calendario. La salida únicamente selecciona una
    relación conversacional y Python la proyecta contra objetos stateful reales.
    """
    perception = dict(first_perception or {})
    if not _agent_v2_v100_context_needed(perception, world or {}):
        return perception

    interactions = _agent_v2_v100_active_interactions_from_world(world or {})
    focus = _agent_v2_v100_focus_from_world(world or {})
    history = [
        {
            "role": row.get("role"),
            "content": str(row.get("content") or "")[:800],
            "reference_id": row.get("reference_id"),
            "timestamp": row.get("timestamp"),
        }
        for row in _agent_v2_history_with_reference_ids(world or {})[-AGENT_V2_GENERIC_CONTEXT_HISTORY_LIMIT:]
        if isinstance(row, dict)
    ]
    interaction_payload = [
        {
            "interaction_id": item.get("interaction_id"),
            "question_id": item.get("question_id"),
            "scope_id": item.get("scope_id"),
            "kind": item.get("kind"),
            "field": item.get("field"),
            "status": item.get("status"),
            "options": item.get("options") or [],
            "allowed_operations": item.get("allowed_operations") or [],
            "target_refs": item.get("target_refs") or [],
            "context": item.get("context") or {},
            "action_snapshot": item.get("action_snapshot") or {},
        }
        for item in interactions
    ]
    focus_payload = {
        "focus_id": focus.get("focus_id"),
        "operation": focus.get("operation"),
        "risk": focus.get("risk"),
        "scope_id": focus.get("scope_id"),
        "reference_id": focus.get("reference_id"),
        "source_message": focus.get("source_message"),
        "act": focus.get("act") or {},
        "verified_context": focus.get("verified_context") or {},
    } if focus else {}

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos CONVERSATION MANAGER de un agente de reservas. Tu única tarea es decidir "
                        "cómo se relaciona CURRENT_USER_TURN con objetos conversacionales YA EXISTENTES. "
                        "No elijas tools, no inventes datos del negocio y no hagas keyword matching. Interpretá significado.\n\n"
                        "RELATION debe ser una de: independent, answers_pending, modifies_focus, references_previous, changes_topic. "
                        "RESOLUTION debe ser una de: confirm, deny, select, supply, modify, continue, unrelated. "
                        "Si responde una pregunta del agente, elegí exactamente un interaction_id real. "
                        "Si esa interacción es kind=choice, resolution debe ser select y option_id debe ser "
                        "exactamente uno de los IDs ofrecidos; resolvé equivalencias horarias, expresiones "
                        "coloquiales y referencias ordinales por su significado dentro del diálogo. "
                        "answers_pending se usa SOLO cuando CURRENT_USER_TURN realmente resuelve esa interacción: aporta/selecciona "
                        "el dato pedido, confirma/niega una confirmación, o modifica explícitamente el action_snapshot. Una pregunta, "
                        "corrección o reclamo sobre otra dimensión NO responde el pending aunque empiece con una afirmación. "
                        "Si el usuario corrige al agente o cambia una dimensión de la consulta anterior dejando otras implícitas, "
                        "usá modifies_focus/references_previous; para READs podés reparar una clasificación base equivocada si el "
                        "diálogo demuestra que continúa la misma consulta. "
                        "Si continúa/modifica el foco anterior, elegí el operation que realmente continúa y declarÁ inherit_fields "
                        "sólo para dimensiones OMITIDAS ahora que deben mantenerse. CURRENT_USER_TURN siempre gana sobre memoria. "
                        "No heredes una dimensión que el usuario cambió, negó o volvió irrelevante. "
                        "Para una consulta nueva/autónoma usá independent o changes_topic y no heredes nada. "
                        "resolution=continue NO es una respuesta válida a PendingInteraction; continue corresponde a continuidad del foco. "
                        "Para WRITEs nunca inventes reservation_id/registration_id: esos IDs sólo pueden venir del interaction/focus. "
                        "evidence debe ser una cita literal no vacía de CURRENT_USER_TURN. "
                        "operation debe ser una operación válida y, para answers_pending, pertenecer a allowed_operations del interaction. "
                        "inherit_fields sólo puede usar rutas estructuradas como temporal.day, temporal.start, temporal.daypart, "
                        "temporal.duration_hours, target.resource, target.resource_type, target.resource_types, target.label, "
                        "target.reservation_id, target.registration_id, quantity.count, quantity.duration_hours.\n\n"
                        "Respondé SOLO JSON: {"
                        "\"relation\":\"independent|answers_pending|modifies_focus|references_previous|changes_topic\","
                        "\"resolution\":\"confirm|deny|select|supply|modify|continue|unrelated\","
                        "\"interaction_id\":null,\"reference_id\":null,\"operation\":null,"
                        "\"inherit_fields\":[],\"option_id\":null,\"evidence\":\"literal\",\"reason\":\"breve\"}."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "CURRENT_USER_TURN": mensaje,
                        "BASE_SEMANTIC_FRAME": _agent_v2_semantic_frame(perception),
                        "BASE_ENTITIES": perception.get("entities") or {},
                        "PENDING_INTERACTIONS": interaction_payload,
                        "CONVERSATION_FOCUS": focus_payload,
                        "RECENT_DIALOGUE": history,
                        "VALID_OPERATIONS": sorted(AGENT_V2_SEMANTIC_OPERATIONS),
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=420,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        decision = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V100 CONVERSATION MANAGER] "
            f"sin resolución contextual: {type(exc).__name__}: {exc}"
        )
        return perception

    relation = str(decision.get("relation") or "independent")
    resolution = str(decision.get("resolution") or "unrelated")
    evidence = str(decision.get("evidence") or "").strip()
    if relation not in {"independent", "answers_pending", "modifies_focus", "references_previous", "changes_topic"}:
        return perception
    if resolution not in {"confirm", "deny", "select", "supply", "modify", "continue", "unrelated"}:
        return perception
    if not evidence or normalizar_texto_ia(evidence) not in normalizar_texto_ia(mensaje or ""):
        print("   🚫 [AgentV2 V100 CONVERSATION MANAGER] evidencia no pertenece al turno actual")
        return perception

    if relation == "answers_pending" and resolution == "continue":
        # "continue" means the user is continuing/correcting the conversational
        # focus, not resolving the value/choice/confirmation we asked for.
        # This prevents messages like "sí, pero te pregunté horarios..." from
        # being consumed as the answer to an hour PendingInteraction.
        if focus:
            relation = "modifies_focus"
            decision = {
                **decision,
                "relation": relation,
                "operation": str(decision.get("operation") or focus.get("operation") or ""),
            }
            print("   🧭 [AgentV2 V102 PENDING/FOCUS ARBITRATION] continue → modifies_focus")
        else:
            return perception

    if relation == "answers_pending":
        interaction_id = str(decision.get("interaction_id") or "")
        matches = [
            item for item in interactions
            if str(item.get("interaction_id") or "") == interaction_id
        ]
        if len(matches) != 1:
            print("   🚫 [AgentV2 V100 CONVERSATION MANAGER] pending target no único")
            return perception
        interaction = matches[0]
        operation = str(decision.get("operation") or "")
        allowed = set(interaction.get("allowed_operations") or [])
        if resolution != "deny" and allowed and operation and operation not in allowed:
            print("   🚫 [AgentV2 V100 CONVERSATION MANAGER] operation fuera del PendingInteraction")
            return perception
        projected = _agent_v2_v100_project_pending_resolution(
            perception, interaction, decision, mensaje
        )
        projected["context_resolution"] = {
            "resolved": True,
            "type": "answers_pending",
            "interaction_id": interaction_id,
            "question_id": interaction.get("question_id"),
            "scope_id": interaction.get("scope_id"),
            "resolution": resolution,
            "evidence": evidence,
            "reason": decision.get("reason"),
        }
        print(
            "   ✅ [AgentV2 V100 PENDING INTERACTION] "
            f"id={interaction_id} resolution={resolution} operation={decision.get('operation')}"
        )
        return projected

    if relation in {"modifies_focus", "references_previous"}:
        if not focus:
            return perception
        reference_id = str(decision.get("reference_id") or focus.get("reference_id") or "")
        if reference_id and reference_id not in _agent_v2_v100_known_reference_ids(world or {}):
            print("   🚫 [AgentV2 V100 CONVERSATION MANAGER] reference_id no verificable")
            return perception
        decision = _agent_v2_v102_conservative_read_inheritance(
            perception, focus, decision
        )
        projected = _agent_v2_v100_project_focus_delta(
            perception, focus, {**decision, "reference_id": reference_id}, mensaje
        )
        projected["context_resolution"] = {
            "resolved": True,
            "type": "references_previous",
            "focus_id": focus.get("focus_id"),
            "reference_id": reference_id,
            "resolution": resolution,
            "inherit_fields": list(decision.get("inherit_fields") or []),
            "evidence": evidence,
            "reason": decision.get("reason"),
        }
        print(
            "   🔗 [AgentV2 V100 CONTEXT DELTA] "
            f"focus={focus.get('focus_id')} operation={decision.get('operation') or focus.get('operation')} "
            f"inherit={decision.get('inherit_fields') or []}"
        )
        return projected

    # Independiente/cambio de tema: memoria permanece disponible pero NO opera.
    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    relation_type = "new_request" if any(
        isinstance(act, dict) and str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
        for act in (frame.get("acts") or [])
    ) else "new_question"
    frame["context_relation"] = {
        "type": relation_type,
        "question_id": None,
        "reference_id": None,
        "references_previous_user_turn": False,
        "references_agent_offer": False,
        "answers_pending_question": False,
    }
    clean["semantic_frame"] = frame
    clean["pending_relation"] = relation_type
    clean["context_resolution"] = {
        "resolved": True,
        "type": relation_type,
        "resolution": resolution,
        "evidence": evidence,
        "reason": decision.get("reason"),
    }
    print(
        "   🥇 [AgentV2 V100 CURRENT TURN] "
        f"relation={relation} → memoria pasiva"
    )
    return clean


# Reemplaza los resolvers contextuales específicos. La función original de
# Perception la invoca por lookup global, por lo que todo el dominio usa esta
# única frontera desde este build.
async def _agent_v2_resolve_context_reference(
    mensaje: str,
    first_perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    if AGENT_V2_V102_DEFER_CONTEXT_MANAGER.get():
        # Core Perception must finish understanding CURRENT_USER_TURN before
        # conversational memory is allowed to participate.
        return first_perception
    return await _agent_v2_v100_resolve_conversation_context(
        mensaje, first_perception, world or {}
    )


# ---------------------------------------------------------------------------
# Pending freshness: lifecycle > adjacency física de mensajes.
# ---------------------------------------------------------------------------
def _agent_v2_open_question_is_fresh(state: Dict, question: Dict) -> bool:
    if not isinstance(question, dict):
        return False
    status = str(question.get("interaction_status") or question.get("status") or "active")
    if status in {"resolved", "cancelled", "superseded", "expired"}:
        return False
    created = _parse_context_timestamp(question.get("created_at"))
    if not created:
        return False
    now = datetime.datetime.now(TIMEZONE)
    expires = _parse_context_timestamp(question.get("expires_at"))
    if expires:
        return now <= expires
    age = (now - created).total_seconds()
    if age < 0:
        return False
    ttl_minutes = (
        PENDING_AVAILABILITY_CONTEXT_TTL_MINUTES
        if question.get("context_only")
        else AGENT_V2_GENERIC_PENDING_TTL_MINUTES
    )
    return age <= float(ttl_minutes) * 60.0


# ---------------------------------------------------------------------------
# Generic ContextAuthorization: READ flexible; WRITE strong.
# ---------------------------------------------------------------------------
_agent_v2_context_authorization_v100_base = _agent_v2_context_authorization


def _agent_v2_context_authorization(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    base = dict(_agent_v2_context_authorization_v100_base(perception, world) or {})

    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame)
    relation_type = str(relation.get("type") or "")
    # answers_pending puede haber sido validado por el contrato legacy sin
    # materializar el reference_id del target. V100 conserva la autorización
    # pero la enriquece desde el PendingInteraction tipado.
    if base.get("authorized") and relation_type != "answers_pending":
        return base
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    operations = {
        str(act.get("operation") or "")
        for act in acts if str(act.get("operation") or "")
    }
    owner = str(((world or {}).get("facts") or {}).get("memory_owner") or "")

    if relation_type == "answers_pending":
        qid = str(relation.get("question_id") or "").strip()
        scope_id = str(relation.get("scope_id") or "").strip()
        candidates = [
            item for item in _agent_v2_v100_active_interactions_from_world(world or {})
            if str(item.get("question_id") or "") == qid
        ]
        if len(candidates) != 1:
            return base
        interaction = candidates[0]
        if owner and interaction.get("owner") and str(interaction.get("owner")) != owner:
            return {**base, "authorized": False, "reason": "pending_interaction_owner_mismatch"}
        expected_scope = str(interaction.get("scope_id") or "")
        if expected_scope and scope_id and expected_scope != scope_id:
            return {**base, "authorized": False, "reason": "pending_interaction_scope_mismatch"}
        allowed = set(interaction.get("allowed_operations") or [])
        # En un turno mixto sólo la operación que consume memoria pendiente debe
        # estar limitada por ``allowed_operations``. Los READs independientes,
        # probados exclusivamente por current_user_turn (p.ej. consultar
        # parrilla), no deben invalidar el binding de create_booking.
        context_bound_operations = {
            str(act.get("operation") or "")
            for act in acts
            if any(
                isinstance(item, dict)
                and str(item.get("source") or "") in {"pending_option", "previous_user_turn"}
                for item in (act.get("provenance") or [])
            )
        }
        checked_operations = context_bound_operations or operations
        if (
            allowed
            and checked_operations
            and not checked_operations.issubset(allowed | {"greet", "clarify"})
        ):
            return {**base, "authorized": False, "reason": "pending_interaction_operation_mismatch"}
        reference_id = next((
            str(item.get("id") or "")
            for item in interaction.get("target_refs") or []
            if isinstance(item, dict) and item.get("id")
        ), "")
        return {
            "relation": "answers_pending",
            "authorized": True,
            "question_id": qid,
            "reference_id": reference_id or None,
            "scope_id": expected_scope or scope_id or None,
            "allowed_fields": [str(interaction.get("field") or "")],
            "allowed_sources": ["pending_option", "world_fact", "current_user_turn"],
            "bindings": [{
                "interaction_id": interaction.get("interaction_id"),
                "question_id": qid,
                "scope_id": expected_scope or scope_id,
                "reference_id": reference_id or None,
            }],
            "reason": "v100_verified_pending_interaction",
        }

    if relation_type == "references_previous" and acts:
        # READ histórico puede ser flexible siempre que el referente exista y
        # ninguna operación tenga efectos laterales.
        if all(_agent_v2_v100_operation_risk(op) == "read" for op in operations):
            reference_id = str(relation.get("reference_id") or "").strip()
            focus = _agent_v2_v100_focus_from_world(world or {})
            if not reference_id:
                reference_id = str(focus.get("reference_id") or "")
            if reference_id and reference_id in _agent_v2_v100_known_reference_ids(world or {}):
                return {
                    "relation": "references_previous",
                    "authorized": True,
                    "question_id": None,
                    "reference_id": reference_id,
                    "scope_id": relation.get("scope_id") or focus.get("scope_id"),
                    "allowed_fields": ["context.reference", "target", "temporal", "quantity"],
                    "allowed_sources": ["previous_user_turn", "world_fact"],
                    "bindings": [{"reference_id": reference_id}],
                    "reason": "v100_low_risk_historical_read",
                }
        # WRITEs no reciben relajación. Deben pasar por la autorización fuerte
        # original o por un PendingInteraction stateful.
    return base


# ---------------------------------------------------------------------------
# ConversationFrame persistence adapter.
# ---------------------------------------------------------------------------
_agent_v2_reduce_v100_base = agent_v2_reduce


def _agent_v2_v100_focus_from_perception_payload(
    payload: Dict[str, Any],
    av2: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    frame = _agent_v2_semantic_frame(payload or {})
    acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") not in {"greet", "close_conversation", "clarify", "unknown", ""}
    ]
    if not acts:
        return None
    primary = acts[0]
    relation = _agent_v2_semantic_context_relation(frame)
    reference_id = str(relation.get("reference_id") or "")
    if not reference_id:
        # El mensaje actual suele estar ya persistido al entrar al runtime.
        state_history = list((get_conversation_state(str((payload or {}).get("_v100_owner") or "")) or {}).get("historial") or []) if (payload or {}).get("_v100_owner") else []
        for row in reversed(state_history):
            if isinstance(row, dict) and row.get("role") == "user":
                reference_id = str(row.get("reference_id") or "")
                break
    return {
        "focus_id": str(av2.get("last_turn_id") or uuid.uuid4()),
        "operation": str(primary.get("operation") or ""),
        "risk": _agent_v2_v100_operation_risk(primary.get("operation")),
        "act": primary,
        "semantic_frame": {
            "intent": frame.get("intent"),
            "context_relation": frame.get("context_relation"),
            "turn_type": frame.get("turn_type"),
        },
        "scope_id": relation.get("scope_id") or av2.get("active_scope_id"),
        "reference_id": reference_id,
        "source_message": str((payload or {}).get("_v100_current_message") or ""),
        "updated_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "verified_context": {},
    }


def _agent_v2_v100_sync_state_after_event(
    telefono: str,
    event: Dict[str, Any],
    state: Dict[str, Any],
) -> Dict[str, Any]:
    etype = str((event or {}).get("type") or "").upper()
    payload = (event or {}).get("payload") or {}
    av2 = _agent_v2_state(state)
    cf = _agent_v2_v100_conversation_frame(av2)
    owner = _memory_owner_key(telefono)

    # Keep interactions aligned with actual open_questions first.
    open_by_qid = {
        str(q.get("question_id") or ""): dict(q)
        for q in (av2.get("open_questions") or [])
        if isinstance(q, dict) and str(q.get("question_id") or "")
    }
    interactions = [
        dict(item) for item in (cf.get("pending_interactions") or [])
        if isinstance(item, dict)
    ]

    if etype == "SET_OPEN_QUESTION":
        # Base reducer has already normalized question_id/scope_id.
        field = str(payload.get("field") or payload.get("type") or "")
        candidates = [
            q for q in (av2.get("open_questions") or [])
            if isinstance(q, dict) and str(q.get("field") or q.get("type") or "") == field
        ]
        if candidates:
            q = dict(candidates[-1])
            focus = cf.get("focus") if isinstance(cf.get("focus"), dict) else {}
            focus_act = focus.get("act") if isinstance(focus.get("act"), dict) else {}
            focus_target = focus_act.get("target") if isinstance(focus_act.get("target"), dict) else {}
            focus_temporal = focus_act.get("temporal") if isinstance(focus_act.get("temporal"), dict) else {}
            focus_quantity = focus_act.get("quantity") if isinstance(focus_act.get("quantity"), dict) else {}
            asked_field = str(q.get("field") or q.get("type") or "")
            # Persist the operation context that produced the question. This is
            # typed state, not language parsing. Never fill the very datum asked.
            if asked_field != "dia" and not q.get("dia") and focus_temporal.get("day"):
                q["dia"] = focus_temporal.get("day")
            if asked_field not in {"hora", "hora_aclaracion"} and not q.get("hora") and focus_temporal.get("start"):
                q["hora"] = focus_temporal.get("start")
            if asked_field != "franja_dia" and not q.get("franja_dia") and focus_temporal.get("daypart"):
                q["franja_dia"] = focus_temporal.get("daypart")
            if asked_field != "duracion_horas" and not q.get("duracion_horas"):
                q["duracion_horas"] = focus_temporal.get("duration_hours") or focus_quantity.get("duration_hours")
            if asked_field != "cancha" and not q.get("cancha") and focus_target.get("label"):
                q["cancha"] = focus_target.get("label")
            if not q.get("resource_type") and focus_target.get("resource_type"):
                q["resource_type"] = focus_target.get("resource_type")
            if not q.get("resource_types") and focus_target.get("resource_types"):
                q["resource_types"] = list(focus_target.get("resource_types") or [])
            if not q.get("reservation_id") and focus_target.get("reservation_id"):
                q["reservation_id"] = focus_target.get("reservation_id")
            if not q.get("registration_id") and focus_target.get("registration_id"):
                q["registration_id"] = focus_target.get("registration_id")
            if not q.get("event_id") and focus_target.get("event_id"):
                q["event_id"] = focus_target.get("event_id")
            if not q.get("booking_shape") and focus_temporal.get("structure"):
                q["booking_shape"] = focus_temporal.get("structure")
            interaction = _agent_v2_v100_question_to_interaction(q, owner=owner)
            q.update({
                "interaction_id": interaction["interaction_id"],
                "interaction_kind": interaction["kind"],
                "interaction_status": "active",
                "allowed_operations": interaction["allowed_operations"],
                "action_snapshot": interaction["action_snapshot"],
            })
            av2["open_questions"] = [
                q if str(item.get("question_id") or "") == str(q.get("question_id") or "") else item
                for item in (av2.get("open_questions") or [])
            ]
            interactions = [
                item for item in interactions
                if str(item.get("interaction_id") or "") != interaction["interaction_id"]
                and not (
                    str(item.get("field") or "") == interaction["field"]
                    and str(item.get("scope_id") or "") == interaction["scope_id"]
                )
            ]
            interactions.append(interaction)

    elif etype == "CLEAR_OPEN_QUESTION":
        field = str(payload.get("field") or "")
        interactions = [
            item for item in interactions
            if str(item.get("field") or "") != field
        ]

    elif etype == "SUSPEND_PENDING_FOR_INFORMATION":
        for item in interactions:
            if str(item.get("status") or "active") == "active":
                item["status"] = "suspended"
        objective = cf.get("booking_objective")
        if (
            isinstance(objective, dict)
            and str(objective.get("status") or "") in {"active", "collecting", "ready", "preflight"}
        ):
            objective = dict(objective)
            objective["status"] = "suspended"
            objective["suspended_at"] = datetime.datetime.now(TIMEZONE).isoformat()
            cf["booking_objective"] = objective

    elif etype == "PERCEPTION_UPDATED":
        understanding = {
            "turn_id": av2.get("last_turn_id"),
            "semantic_frame": _agent_v2_semantic_frame(payload or {}),
            "execution_contract": dict((payload or {}).get("execution_contract") or {}),
            "context_resolution": dict((payload or {}).get("context_resolution") or {}),
            "desired_state": dict((payload or {}).get("desired_state") or {}),
            "task_graph": dict((payload or {}).get("task_graph") or {}),
            "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
        }
        cf["last_understanding"] = understanding
        focus = _agent_v2_v100_focus_from_perception_payload(payload, av2)
        if focus:
            cf["focus"] = focus
        pending_resolution = (payload or {}).get("_v100_pending_resolution")
        if isinstance(pending_resolution, dict):
            iid = str(pending_resolution.get("interaction_id") or "")
            mode = str(pending_resolution.get("mode") or "")
            for item in interactions:
                if str(item.get("interaction_id") or "") == iid:
                    item["status"] = "resolved" if mode == "deny" else "engaged"
                    item["last_resolution"] = dict(pending_resolution)
            if mode == "deny":
                qid = str(pending_resolution.get("question_id") or "")
                av2["open_questions"] = [
                    q for q in (av2.get("open_questions") or [])
                    if str((q or {}).get("question_id") or "") != qid
                ]
                interactions = [
                    item for item in interactions
                    if str(item.get("interaction_id") or "") != iid
                ]

    elif etype == "OBSERVATION":
        obs = dict(payload or {})
        if obs.get("ok"):
            focus = cf.get("focus") if isinstance(cf.get("focus"), dict) else None
            if focus is not None:
                verified = dict(focus.get("verified_context") or {})
                verified[str(obs.get("tool") or "observation")] = {
                    "status": obs.get("status"),
                    "data": dict(obs.get("data") or {}),
                    "verified_facts": dict(obs.get("verified_facts") or {}),
                }
                focus["verified_context"] = verified
                focus["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                cf["focus"] = focus
            if (
                (AGENT_V2_TOOL_CATALOG.get(str(obs.get("tool") or ""), {}) or {}).get("effect") == "write"
                and obs.get("status") in {"success", "already_exists", "confirmed"}
            ):
                engaged = [item for item in interactions if item.get("status") == "engaged"]
                if len(engaged) == 1:
                    iid = str(engaged[0].get("interaction_id") or "")
                    qid = str(engaged[0].get("question_id") or "")
                    interactions = [item for item in interactions if str(item.get("interaction_id") or "") != iid]
                    av2["open_questions"] = [
                        q for q in (av2.get("open_questions") or [])
                        if str((q or {}).get("question_id") or "") != qid
                    ]
                    completed = list(cf.get("completed_tasks") or [])
                    completed.append({
                        "interaction_id": iid,
                        "tool": obs.get("tool"),
                        "status": obs.get("status"),
                        "completed_at": datetime.datetime.now(TIMEZONE).isoformat(),
                    })
                    cf["completed_tasks"] = completed[-50:]

    elif etype in {"RESET_TRANSIENT_BOOKING_SCOPE", "BEGIN_CONTEXT_SCOPE", "PURGE_GHOST_RESERVATION_STATE"}:
        live_qids = set(open_by_qid)
        interactions = [
            item for item in interactions
            if str(item.get("question_id") or "") in live_qids
        ]

    elif etype == "TURN_STARTED":
        # No se mata un pending porque el asistente haya emitido otra oración.
        # Sólo expira por lifecycle/TTL o porque el reducer real lo eliminó.
        live_qids = {
            str(q.get("question_id") or "")
            for q in (av2.get("open_questions") or [])
            if isinstance(q, dict) and str(q.get("question_id") or "")
        }
        interactions = [
            item for item in interactions
            if (
                str(item.get("question_id") or "") in live_qids
                or str(item.get("status") or "") == "engaged"
            )
        ]

    cf["pending_interactions"] = interactions[-30:]
    cf["version"] = AGENT_V2_UNIFIED_CONVERSATION_KERNEL
    av2["conversation_frame"] = cf
    av2["version"] = AGENT_V2_VERSION
    update_conversation_state(telefono, agent_v2=av2)
    return get_conversation_state(telefono)


def agent_v2_reduce(telefono: str, event: Dict[str, Any]) -> Dict[str, Any]:
    state = _agent_v2_reduce_v100_base(telefono, event)
    try:
        return _agent_v2_v100_sync_state_after_event(telefono, event, state)
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V100 CONVERSATION STATE] "
            f"sync no fatal: {type(exc).__name__}: {exc}"
        )
        return state


# ---------------------------------------------------------------------------
# World adapter: ConversationFrame becomes a first-class input.
# ---------------------------------------------------------------------------
_construir_world_state_agent_v2_v100_base = construir_world_state_agent_v2


def construir_world_state_agent_v2(
    telefono: str,
    prospecto: Dict,
    conv_state: Dict,
    mensaje_actual: str,
    image_path: str = "",
) -> Dict[str, Any]:
    world = _construir_world_state_agent_v2_v100_base(
        telefono, prospecto, conv_state, mensaje_actual, image_path
    )
    av2 = _agent_v2_state(conv_state or {})
    cf = _agent_v2_v100_conversation_frame(av2)
    interactions = [
        dict(item) for item in (cf.get("pending_interactions") or [])
        if isinstance(item, dict)
    ]
    if not interactions:
        interactions = [
            _agent_v2_v100_question_to_interaction(
                q,
                owner=str(((world or {}).get("facts") or {}).get("memory_owner") or ""),
            )
            for q in (world.get("open_questions") or [])
            if isinstance(q, dict)
        ]
    world["conversation_frame"] = cf
    world["pending_interactions"] = interactions
    world.setdefault("stored_memory", {})["conversation_frame"] = cf
    world.setdefault("stored_memory", {})["pending_interactions"] = interactions
    return world


# ---------------------------------------------------------------------------
# Desired State + TaskGraph: meaning is frozen before planning.
# ---------------------------------------------------------------------------
def _agent_v2_v100_find_real_reservation(world: Dict[str, Any], rid: Any) -> Dict[str, Any]:
    rid = str(rid or "").strip()
    if not rid:
        return {}
    for row in (((world or {}).get("facts") or {}).get("reservas_reales") or []):
        if not isinstance(row, dict):
            continue
        row_id = str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "").strip()
        if row_id == rid:
            return dict(row)
    return {}


def _agent_v2_v100_apply_act_to_desired(
    current: Dict[str, Any], act: Dict[str, Any]
) -> Dict[str, Any]:
    desired = dict(current or {})
    operation = str(act.get("operation") or "")
    target = act.get("target") if isinstance(act.get("target"), dict) else {}
    temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
    quantity = act.get("quantity") if isinstance(act.get("quantity"), dict) else {}

    if _agent_v2_v100_nonempty(temporal.get("day")):
        desired["fecha"] = temporal.get("day")
    if _agent_v2_v100_nonempty(temporal.get("start")):
        desired["hora"] = temporal.get("start")
    if _agent_v2_v100_nonempty(temporal.get("duration_hours")):
        desired["duracion_horas"] = temporal.get("duration_hours")
    elif _agent_v2_v100_nonempty(quantity.get("duration_hours")):
        desired["duracion_horas"] = quantity.get("duration_hours")
    if _agent_v2_v100_nonempty(target.get("label")) and target.get("resource") == "court":
        desired["cancha"] = target.get("label")

    for change in act.get("changes") or []:
        if not isinstance(change, dict):
            continue
        field = str(change.get("field") or "").strip()
        if field:
            desired[field] = change.get("value")

    if operation == "add_resource":
        resource = str(target.get("resource") or "")
        if resource:
            desired[f"has_{resource}"] = True
    elif operation == "remove_resource":
        resource = str(target.get("resource") or "")
        if resource:
            desired[f"has_{resource}"] = False
    elif operation == "cancel_booking":
        desired["estado_deseado"] = "cancelled"
    elif operation == "create_booking":
        desired.setdefault("estado_deseado", "pending_or_reserved")
    return desired


def _agent_v2_v100_attach_desired_state_and_task_graph(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = dict(perception or {})
    contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    acts = [
        dict(act) for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    ]
    mutations = []
    nodes = []
    for index, act in enumerate(acts):
        operation = str(act.get("operation") or "")
        effect = "write" if operation in AGENT_V2_WRITE_OPERATIONS else "read" if operation.startswith("query_") else "social"
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        current = {}
        rid = str(target.get("reservation_id") or "").strip()
        if rid:
            current = _agent_v2_v100_find_real_reservation(world or {}, rid)
        desired = _agent_v2_v100_apply_act_to_desired(current, act)
        delta = []
        for key in sorted(set(current) | set(desired)):
            if current.get(key) != desired.get(key):
                delta.append({"field": key, "from": current.get(key), "to": desired.get(key)})
        if effect == "write":
            mutations.append({
                "act_id": act.get("act_id"),
                "operation": operation,
                "target": target,
                "current_state": current,
                "desired_state": desired,
                "delta": delta,
            })
        dependencies = []
        if operation in {"create_booking", "reschedule_booking"}:
            dependencies.append("verified_availability")
        if operation in {"cancel_booking", "reschedule_booking", "modify_resource", "add_resource", "remove_resource", "register_payment", "choose_payment_method"}:
            dependencies.append("verified_target")
        nodes.append({
            "node_id": str(act.get("act_id") or f"node_{index+1}"),
            "operation": operation,
            "effect": effect,
            "risk": _agent_v2_v100_operation_risk(operation),
            "target": target,
            "dependencies": dependencies,
            "allowed_tools": sorted(AGENT_V2_OPERATION_TOOLS.get(operation, set())),
            "status": "pending",
        })
    clean["desired_state"] = {
        "mutations": mutations,
        "generated_from": "execution_contract",
    }
    clean["task_graph"] = {
        "nodes": nodes,
        "meaning_frozen": bool(contract.get("authoritative")),
        "source": AGENT_V2_UNIFIED_CONVERSATION_KERNEL,
    }
    return clean


# ---------------------------------------------------------------------------
# Structural preconditions. These enforce business reality but do not parse text.
# ---------------------------------------------------------------------------
def _agent_v2_v100_apply_structural_preconditions(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    changed = False
    rebuilt = []
    for act in acts:
        op = str(act.get("operation") or "")
        temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
        if (
            op == "create_booking"
            and bool((act.get("commitment") or {}).get("wants_write"))
            and not hora_es_valida(normalizar_hora_detectada(temporal.get("start")))
        ):
            # Desired booking without an exact slot is not executable yet. The
            # semantic desire remains visible, but the operational act becomes a
            # READ for the missing availability dimension.
            converted = dict(act)
            converted["operation"] = "query_availability"
            converted["requested_facts"] = list(dict.fromkeys([
                *(act.get("requested_facts") or []), "available_slots"
            ]))
            converted["commitment"] = {"wants_write": False, "wants_information": True}
            converted["provenance"] = list(act.get("provenance") or []) + [{
                "field": "operation.precondition",
                "source": "world_fact",
                "evidence": "booking_requires_exact_available_slot_before_write",
            }]
            act = converted
            changed = True
        rebuilt.append(act)
    if changed:
        operational = [a for a in rebuilt if a.get("operation") != "greet"]
        primary = operational[0] if operational else (rebuilt[0] if rebuilt else {})
        frame["acts"] = rebuilt
        frame["intent"] = {
            "domain": primary.get("domain") or "booking",
            "operation": primary.get("operation") or "unknown",
        }
        frame["commitment"] = dict(primary.get("commitment") or {})
        frame["requested_facts"] = list(dict.fromkeys(
            fact for a in rebuilt for fact in (a.get("requested_facts") or [])
        ))
        clean["semantic_frame"] = frame
        clean.pop("semantic_effect_verification", None)
        print(
            "   🧭 [AgentV2 V100 DESIRED STATE PRECONDITION] "
            "booking sin slot exacto → query_availability antes de WRITE"
        )
    return clean


# ---------------------------------------------------------------------------
# V102 Perception ordering: preserve the latest proven pre-kernel perception
# (V91–V94 continuity + V96 renderer compatibility). Generic conversational
# arbitration runs only AFTER this pipeline and only if context remains unresolved.
# ---------------------------------------------------------------------------
_percibir_turno_agent_v2_v100_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    # Phase 1: understand CURRENT USER TURN with the mature pipeline. The generic
    # manager is explicitly deferred so memory cannot contaminate base meaning.
    token = AGENT_V2_V102_DEFER_CONTEXT_MANAGER.set(True)
    try:
        perception = await _percibir_turno_agent_v2_v100_base(
            mensaje,
            world,
            image_path,
            learning_policy,
        )
    finally:
        AGENT_V2_V102_DEFER_CONTEXT_MANAGER.reset(token)

    # Phase 2: only unresolved conversation continuity reaches the generic
    # Conversation Manager.  The final V126 entry point may already have built a
    # verified TurnSemanticPlan *before* entering this legacy wrapper chain.  In
    # that case this late manager must stay passive: otherwise it would classify
    # the isolated utterance again and could replace answers_pending with a READ.
    early_plan_context = globals().get("AGENT_V2_DIALOGUE_CONTEXT_PLAN")
    early_plan = (
        early_plan_context.get()
        if early_plan_context is not None
        else {}
    )
    if isinstance(early_plan, dict) and early_plan.get("status") == "verified":
        print("   🧊 [AgentV2 DIALOGUE GATE] arbitraje tardío omitido; TurnSemanticPlan verificado")
    elif not _agent_v2_v102_context_is_already_grounded(perception, world or {}):
        perception = await _agent_v2_v100_resolve_conversation_context(
            mensaje, perception, world or {}
        )
    else:
        print("   ✅ [AgentV2 V102 CONTEXT] binding maduro preservado; arbitraje genérico omitido")

    # If late arbitration produced a WRITE from a real PendingInteraction, run
    # the final Effect Verifier now, before freezing. READs pass through cheaply.
    if any(
        isinstance(act, dict) and str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
    ):
        perception = await _agent_v2_verify_semantic_effects(
            mensaje, perception, world or {}
        )

    perception = _agent_v2_v100_apply_structural_preconditions(
        perception, world or {}
    )
    perception = dict(perception or {})

    # Remove stale READ artifacts if late context changed the semantic operation.
    final_ops = {
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(perception).get("acts") or [])
        if isinstance(act, dict)
    }
    if "query_availability" in final_ops:
        perception["read_grounding_recovery"] = False
        perception["read_meaning_repair_needed"] = False
        perception.pop("read_recovery_reason", None)
        perception.pop("_read_grounding_validated_response", None)
        perception.pop("_specific_court_catalog_today_bundle", None)
        domains = [
            domain for domain in _agent_v2_normalize_question_domains(perception)
            if domain not in {"court_catalog", "other"}
        ]
        if "availability" not in domains:
            domains.append("availability")
        perception["question_domains"] = list(dict.fromkeys(domains))

    # Freeze only after current semantics + verified conversation delta agree.
    perception["_v100_semantic_frozen"] = True
    perception["_v100_current_message"] = str(mensaje or "")
    perception["_v100_owner"] = str(((world or {}).get("facts") or {}).get("memory_owner") or "")
    perception.pop("execution_contract", None)
    perception["execution_contract"] = _agent_v2_build_execution_contract(
        perception, world or {}
    )
    perception = _agent_v2_v100_attach_desired_state_and_task_graph(
        perception, world or {}
    )
    print(
        "   🧠 [AgentV2 V102 LATE CONTEXT ARBITRATION] "
        f"ops={[a.get('operation') for a in ((perception.get('execution_contract') or {}).get('acts') or [])]} "
        f"relation={(_agent_v2_semantic_context_relation(_agent_v2_semantic_frame(perception)) or {}).get('type')} "
        f"authoritative={bool((perception.get('execution_contract') or {}).get('authoritative'))}"
    )
    return perception


