# ---------------------------------------------------------------------------
# Planner consumes the frozen TaskGraph; it cannot expand semantic authority.
# ---------------------------------------------------------------------------
_planificar_agent_v2_v100_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    plan = await _planificar_agent_v2_v100_base(
        world, perception, goals, observations, offline_mode, learning_policy
    )
    if not (perception or {}).get("_v100_semantic_frozen"):
        return plan
    plan = dict(plan or {})
    graph = dict((perception or {}).get("task_graph") or {})
    plan["task_graph"] = graph
    plan["semantic_source"] = AGENT_V2_UNIFIED_CONVERSATION_KERNEL
    allowed = set(((perception or {}).get("execution_contract") or {}).get("allowed_tools") or [])
    safe_steps = []
    dropped = []
    for step in plan.get("steps") or []:
        if not isinstance(step, dict):
            continue
        tool = str(step.get("tool") or "")
        if tool in allowed or tool == "solicitar_dato":
            safe_steps.append(step)
        else:
            dropped.append(tool)
    if dropped:
        print(
            "   🧊 [AgentV2 V100 TASKGRAPH GUARD] "
            f"Planner intentó ampliar tools={dropped}; descartadas"
        )
    plan["steps"] = safe_steps
    return plan


# ---------------------------------------------------------------------------
# Safe Exit: internal representation mismatch != business handoff.
# ---------------------------------------------------------------------------
_aplicar_regla_universal_salida_segura_agent_v2_v100_base = aplicar_regla_universal_salida_segura_agent_v2


def _agent_v2_v100_is_internal_representation_failure(
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> bool:
    if any(
        obs.get("status") in {"needs_human_review", "error"}
        for obs in (observations or []) if isinstance(obs, dict)
    ):
        return False
    operations = {
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict)
    }
    if operations.intersection({"handoff_human", "special_event"}):
        return False
    contract = (perception or {}).get("execution_contract") or {}
    issues = set(contract.get("clarification_reasons") or [])
    issues.update(contract.get("validation_issues") or [])
    internal_markers = {
        "missing_recognized_operation",
        "write_not_authorized_by_effect_verifier",
        "historical_context_not_authorized",
        "pending_answer_type_mismatch",
        "semantic_value_invalid",
        "fact_operation_inconsistent",
        "provenance_invalid",
        "references_invalid",
    }
    if issues.intersection(internal_markers):
        return True
    blocking = [
        obs for obs in (observations or [])
        if isinstance(obs, dict) and obs.get("status") == "policy_blocked"
    ]
    return bool(blocking and not any((obs.get("data") or {}).get("requires_handoff") for obs in blocking))


def aplicar_regla_universal_salida_segura_agent_v2(
    response: str,
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    status: str,
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    page=None,
    dry_run: bool = False,
) -> Tuple[str, Dict[str, Any]]:
    if not (perception or {}).get("_v100_semantic_frozen"):
        return _aplicar_regla_universal_salida_segura_agent_v2_v100_base(
            response, world, perception, goals, observations, status,
            telefono, prospecto, page, dry_run,
        )
    assessment = evaluar_salida_segura_agent_v2(
        response, world, perception, goals, observations, status
    )
    if assessment.get("safe"):
        print(
            "   ✅ [AgentV2 SAFE EXIT] "
            f"state={assessment.get('state')} evidence={assessment.get('evidence') or assessment.get('field')}"
        )
        return response, assessment

    if _agent_v2_v100_is_internal_representation_failure(perception, observations):
        # Never wake a human merely because internal representations disagreed.
        # Prefer the already stateful missing question if one exists.
        missing = _agent_v2_verified_missing_input_response(observations)
        if missing:
            print("   ♻️ [AgentV2 V100 INTERNAL RECOVERY] internal mismatch → stateful clarification, no handoff")
            return missing, {
                "safe": True,
                "state": "internal_recovery_question",
                "fallback_applied": True,
                "reason_code": "internal_representation_failure",
                "evidence": [],
            }
        if str(response or "").strip() and all(
            _agent_v2_v100_operation_risk(act.get("operation")) == "read"
            for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
            if isinstance(act, dict)
        ):
            print("   ♻️ [AgentV2 V100 INTERNAL RECOVERY] READ grounded preservado, no handoff")
            return response, {
                "safe": True,
                "state": "internal_recovery_read",
                "fallback_applied": True,
                "reason_code": "internal_representation_failure",
                "evidence": [],
            }
        # WRITE unresolved: fail conversationally without pretending success and
        # without escalating an implementation mismatch to the business owner.
        recovery = (
            "No pude completar la operación porque una validación interna no llegó a cerrarse. "
            "No apliqué ningún cambio que no pudiera verificar."
        )
        registrar_metrica_operativa("agent_v2_internal_representation_recovery", {
            "telefono": telefono,
            "goal": (goals or {}).get("primary_goal"),
            "status": status,
            "contract_issues": list(((perception or {}).get("execution_contract") or {}).get("clarification_reasons") or []),
        })
        print("   ♻️ [AgentV2 V100 INTERNAL RECOVERY] WRITE no ejecutado → no handoff humano")
        return recovery, {
            "safe": True,
            "state": "internal_recovery_write",
            "fallback_applied": True,
            "reason_code": "internal_representation_failure",
            "evidence": [],
        }

    return _aplicar_regla_universal_salida_segura_agent_v2_v100_base(
        response, world, perception, goals, observations, status,
        telefono, prospecto, page, dry_run,
    )


