def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v100_base()
    results = list(result.get("results") or [])

    now_iso = datetime.datetime.now(TIMEZONE).isoformat()
    q = {
        "question_id": "v100_q1",
        "scope_id": "v100_scope",
        "field": "confirm_generic",
        "created_at": now_iso,
        "goal_context": ["reprogramar_reserva"],
        "operation_contract": {
            "act_id": "v100_reschedule",
            "operation": "reschedule_booking",
            "domain": "booking",
            "target": {"resource": "reservation", "reservation_id": "77"},
            "temporal": {"day": "2026-09-21", "start": "18:00"},
            "quantity": {}, "changes": [], "requested_facts": [],
            "commitment": {"wants_write": True, "wants_information": False},
            "provenance": [],
        },
        "reservation_id": "77",
    }
    interaction = _agent_v2_v100_question_to_interaction(q, owner="owner")
    results.append({
        "name": "v100_pending_interaction_derives_operation_generically",
        "ok": interaction.get("allowed_operations") == ["reschedule_booking"],
    })

    state = {"historial": [
        {"role": "assistant", "content": "pregunta", "timestamp": now_iso},
        {"role": "assistant", "content": "dato adicional", "timestamp": now_iso},
    ]}
    results.append({
        "name": "v100_pending_freshness_not_based_on_assistant_adjacency",
        "ok": bool(_agent_v2_open_question_is_fresh(state, q)),
    })

    focus = {
        "focus_id": "f1", "operation": "query_availability", "risk": "read",
        "scope_id": "s1", "reference_id": "user_turn:prev:1",
        "source_message": "horarios de padel hoy",
        "act": {
            "act_id": "a1", "operation": "query_availability", "domain": "booking",
            "target": {"resource": "court", "resource_types": ["Pádel"], "resource_type": "Pádel"},
            "temporal": {"day": "2026-09-21", "duration_hours": 1.0},
            "quantity": {}, "changes": [], "requested_facts": ["available_slots"],
            "commitment": {"wants_write": False, "wants_information": True},
            "provenance": [],
        },
    }
    base_perception = {
        "semantic_frame": {
            "source": "ai", "schema_valid": True, "turn_type": "question",
            "intent": {"domain": "business", "operation": "query_policy"},
            "acts": [{
                "act_id": "cur", "operation": "query_policy", "domain": "business",
                "target": {"resource": "court", "resource_types": ["Futbol 5"], "resource_type": "Futbol 5"},
                "temporal": {}, "quantity": {}, "changes": [], "requested_facts": [],
                "commitment": {"wants_write": False, "wants_information": True}, "provenance": [],
            }],
            "context_relation": {"type": "new_question"},
        }
    }
    projected = _agent_v2_v100_project_focus_delta(
        base_perception,
        focus,
        {
            "operation": "query_availability",
            "inherit_fields": ["temporal.day", "temporal.duration_hours"],
            "reference_id": "user_turn:prev:1",
        },
        "y futbol 5?",
    )
    projected_act = next((
        act for act in (_agent_v2_semantic_frame(projected).get("acts") or [])
        if act.get("operation") == "query_availability"
    ), {})
    results.append({
        "name": "v100_context_delta_keeps_day_and_replaces_resource",
        "ok": bool(
            (projected_act.get("temporal") or {}).get("day") == "2026-09-21"
            and (projected_act.get("target") or {}).get("resource_type") == "Futbol 5"
            and "Pádel" not in ((projected_act.get("target") or {}).get("resource_types") or [])
        ),
    })

    desired_perception = {
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "r1", "operation": "reschedule_booking",
                "target": {"resource": "reservation", "reservation_id": "77"},
                "temporal": {"day": "2026-09-21", "start": "18:00"},
                "quantity": {}, "changes": [],
            }],
        }
    }
    desired_world = {"facts": {"reservas_reales": [{
        "reservation_id": "77", "fecha": "2026-09-21", "hora": "16:00",
        "cancha": "Cancha 1", "duracion_horas": 1.0,
    }]}}
    desired = _agent_v2_v100_attach_desired_state_and_task_graph(desired_perception, desired_world)
    mutations = ((desired.get("desired_state") or {}).get("mutations") or [])
    results.append({
        "name": "v100_desired_state_exposes_reschedule_delta",
        "ok": bool(
            mutations
            and any(item.get("field") == "hora" and item.get("from") == "16:00" and item.get("to") == "18:00"
                    for item in mutations[0].get("delta") or [])
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V102 — LATE CONTEXT ARBITRATION + UNIFIED AGENTIC CORE
# ============================================================================
# Conserva el core agentic pero corrige el orden de autoridad conversacional:
#   - una continuidad libre nunca puede fabricar un WRITE desde memoria;
#   - cualquier PendingInteraction puede autorizar su action_snapshot tipado,
#     sin regex/keywords y sin excepciones por frase del usuario;
#   - ConversationFrame mantiene tasks/commitments/entities como memoria canónica;
#   - NBA puede proponer lenguaje natural, pero Python valida el dato faltante;
#   - una PendingInteraction se cierra por lifecycle, no por adyacencia física.
#
# El Planner sigue usando las tools maduras del sistema, pero TaskGraph y
# ExecutionContract delimitan estrictamente qué tools puede ejecutar. Así se
# conserva toda la ingeniería de calendario/pagos/torneos sin volver a
# reinterpretar el lenguaje humano en capas posteriores.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v102"
# Las funciones V100 consultan este símbolo en runtime; desde aquí todo nuevo
# ConversationFrame/TaskGraph queda versionado como V101.
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE

_AGENT_V2_V101_GENERIC_PENDING_WRITES = {
    "create_booking",
    "cancel_booking",
    "reschedule_booking",
    "modify_resource",
    "add_resource",
    "remove_resource",
    "choose_payment_method",
    "join_waitlist",
}

_AGENT_V2_V101_EXISTING_RESERVATION_WRITES = {
    "cancel_booking",
    "reschedule_booking",
    "modify_resource",
    "add_resource",
    "remove_resource",
    "choose_payment_method",
}


def _agent_v2_v101_current_semantic_operations(
    perception: Dict[str, Any],
) -> set:
    return {
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "")
    }


# ---------------------------------------------------------------------------
# ContextDelta safety: history may fill omitted READ dimensions, but it cannot
# invent a side effect that Perception did not understand in the current turn.
# ---------------------------------------------------------------------------
_agent_v2_v101_focus_delta_base = _agent_v2_v100_project_focus_delta


def _agent_v2_v100_project_focus_delta(
    perception: Dict[str, Any],
    focus: Dict[str, Any],
    decision: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    requested_operation = str(
        (decision or {}).get("operation")
        or (focus or {}).get("operation")
        or ""
    ).strip()
    current_operations = _agent_v2_v101_current_semantic_operations(perception or {})
    if (
        requested_operation in AGENT_V2_WRITE_OPERATIONS
        and requested_operation not in current_operations
    ):
        print(
            "   🚫 [AgentV2 V101 CONTEXT DELTA] "
            f"WRITE histórico no propuesto por current turn: {requested_operation}"
        )
        return perception
    return _agent_v2_v101_focus_delta_base(
        perception, focus, decision, mensaje
    )


# ---------------------------------------------------------------------------
# Generic PendingInteraction WRITE authority.
# La IA sólo vincula el mensaje con una interacción existente. Python verifica
# qid/scope/action_snapshot/evidencia/target real. No se buscan palabras como
# “sí”, “dale”, “ok”, etc.
# ---------------------------------------------------------------------------

def _agent_v2_v101_real_reservation_ids(world: Dict[str, Any]) -> set:
    return {
        str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "")
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
        and str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "")
    }


def _agent_v2_v101_pending_interaction_by_qid(
    world: Dict[str, Any],
    question_id: str,
) -> Optional[Dict[str, Any]]:
    qid = str(question_id or "").strip()
    rows = [
        dict(item)
        for item in _agent_v2_v100_active_interactions_from_world(world or {})
        if isinstance(item, dict)
        and str(item.get("question_id") or "") == qid
    ]
    return rows[0] if len(rows) == 1 else None


def _agent_v2_v101_pending_write_authorizations(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> List[Dict[str, Any]]:
    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame) or {}
    if str(relation.get("type") or "") != "answers_pending":
        return []

    qid = str(relation.get("question_id") or "").strip()
    interaction = _agent_v2_v101_pending_interaction_by_qid(world or {}, qid)
    if not interaction:
        return []

    scope_id = str(interaction.get("scope_id") or "").strip()
    relation_scope = str(relation.get("scope_id") or "").strip()
    if scope_id and relation_scope and scope_id != relation_scope:
        return []

    allowed = {
        str(op or "").strip()
        for op in (interaction.get("allowed_operations") or [])
        if str(op or "").strip()
    }
    snapshot = (
        dict(interaction.get("action_snapshot") or {})
        if isinstance(interaction.get("action_snapshot"), dict)
        else {}
    )
    snapshot_operation = str(snapshot.get("operation") or "").strip()
    real_reservation_ids = _agent_v2_v101_real_reservation_ids(world or {})
    normalized_message = normalizar_texto_ia(mensaje or "")
    authorizations: List[Dict[str, Any]] = []

    for act in (frame.get("acts") or []):
        if not isinstance(act, dict):
            continue
        operation = str(act.get("operation") or "").strip()
        act_id = str(act.get("act_id") or "").strip()
        if (
            not act_id
            or operation not in _AGENT_V2_V101_GENERIC_PENDING_WRITES
            or operation not in allowed
        ):
            continue
        # Una confirmación genérica sólo puede activar el efecto que estaba
        # explícitamente detrás de la pregunta. Si el snapshot está vacío, no
        # damos autoridad WRITE nueva.
        if not snapshot_operation or snapshot_operation != operation:
            continue

        proof = next((
            item for item in (act.get("provenance") or [])
            if isinstance(item, dict)
            and str(item.get("source") or "") == "pending_option"
            and str(item.get("question_id") or "") == qid
            and (not scope_id or str(item.get("scope_id") or "") == scope_id)
            and bool(str(item.get("evidence") or "").strip())
        ), None)
        if not proof:
            continue
        evidence = str(proof.get("evidence") or "").strip()
        if normalizar_texto_ia(evidence) not in normalized_message:
            continue

        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        if operation in _AGENT_V2_V101_EXISTING_RESERVATION_WRITES:
            reservation_id = str(target.get("reservation_id") or "").strip()
            if not reservation_id or reservation_id not in real_reservation_ids:
                continue

        # Si el usuario MODIFICÓ el action_snapshot al responder, los cambios
        # nuevos deben venir del current_user_turn. Los valores ya presentes en
        # el snapshot son precisamente lo que el agente acababa de preguntar.
        snapshot_changes = {
            str(item.get("field") or ""): item.get("value")
            for item in (snapshot.get("changes") or [])
            if isinstance(item, dict) and str(item.get("field") or "")
        }
        unsafe_change = False
        for change in (act.get("changes") or []):
            if not isinstance(change, dict):
                continue
            field = str(change.get("field") or "")
            value = change.get("value")
            if field in snapshot_changes and snapshot_changes[field] == value:
                continue
            change_evidence = str(change.get("evidence") or "").strip()
            if (
                str(change.get("source") or "") != "current_user_turn"
                or not change_evidence
                or normalizar_texto_ia(change_evidence) not in normalized_message
            ):
                unsafe_change = True
                break
        if unsafe_change:
            continue

        authorizations.append({
            "act_id": act_id,
            "authorized": True,
            "evidence_type": "v101_pending_interaction_snapshot",
            "evidence": evidence,
            "question_id": qid,
            "scope_id": scope_id,
            "interaction_id": interaction.get("interaction_id"),
            "operation": operation,
        })

    return authorizations


_agent_v2_v101_verify_effects_base = _agent_v2_verify_semantic_effects


async def _agent_v2_verify_semantic_effects(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    # Preservar primero todas las autoridades maduras (media, torneo, V86, etc.).
    base = await _agent_v2_v101_verify_effects_base(
        mensaje, perception, world
    )
    existing_verification = (
        base.get("semantic_effect_verification")
        if isinstance(base, dict)
        and isinstance(base.get("semantic_effect_verification"), dict)
        else {}
    )
    if existing_verification.get("status") == "verified":
        return base

    working = dict(base or perception or {})
    candidate = _agent_v2_normalize_semantic_frame(
        working, world or {}, mensaje
    )
    working["semantic_frame"] = candidate
    write_acts = [
        act for act in (candidate.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") in _AGENT_V2_V101_GENERIC_PENDING_WRITES
    ]
    if not write_acts:
        return base

    auths = _agent_v2_v101_pending_write_authorizations(
        mensaje, working, world or {}
    )
    wanted = {
        str(act.get("act_id") or "")
        for act in write_acts
        if str(act.get("act_id") or "")
    }
    authorized = {
        str(item.get("act_id") or "")
        for item in auths
        if str(item.get("act_id") or "")
    }
    if wanted and wanted == authorized:
        working["semantic_effect_verification"] = {
            "status": "verified",
            "verified_operations": sorted({
                str(act.get("operation") or "") for act in write_acts
            }),
            "write_authorizations": auths,
            "mode": "verified_v101_pending_interaction_snapshot",
        }
        print(
            "   ⚖️ [AgentV2 V101 PENDING WRITE AUTHORITY] "
            f"writes={sorted(wanted)} operations={sorted({a.get('operation') for a in write_acts})}"
        )
        return working
    return base


# ---------------------------------------------------------------------------
# ConversationFrame completion: active_tasks, commitments and referenced
# entities become first-class state instead of living in separate special cases.
# ---------------------------------------------------------------------------
_agent_v2_v101_reduce_base = agent_v2_reduce


def _agent_v2_v101_task_completed_by_observation(
    task: Dict[str, Any],
    obs: Dict[str, Any],
) -> bool:
    if not isinstance(task, dict) or not isinstance(obs, dict) or not obs.get("ok"):
        return False
    tool = str(obs.get("tool") or "")
    if tool not in set(task.get("allowed_tools") or []):
        return False
    task_effect = str(task.get("effect") or "")
    tool_effect = str((AGENT_V2_TOOL_CATALOG.get(tool) or {}).get("effect") or "")
    status = str(obs.get("status") or "")
    if task_effect == "write":
        return tool_effect == "write" and status in {"success", "already_exists", "confirmed"}
    if task_effect == "read":
        return tool_effect == "read" and status in {
            "success", "needs_user_input", "unavailable", "not_found"
        }
    return False


def _agent_v2_v101_sync_conversation_frame(
    telefono: str,
    event: Dict[str, Any],
    state: Dict[str, Any],
) -> Dict[str, Any]:
    etype = str((event or {}).get("type") or "").upper()
    payload = (event or {}).get("payload") or {}
    av2 = _agent_v2_state(state)
    cf = _agent_v2_v100_conversation_frame(av2)

    if etype == "PERCEPTION_UPDATED":
        graph = dict((payload or {}).get("task_graph") or {})
        nodes = [
            dict(node) for node in (graph.get("nodes") or [])
            if isinstance(node, dict)
        ]
        cf["active_tasks"] = nodes
        contract = dict((payload or {}).get("execution_contract") or {})
        acts = [
            dict(act) for act in (contract.get("acts") or [])
            if isinstance(act, dict)
        ]
        cf["commitments"] = [
            {
                "act_id": act.get("act_id"),
                "operation": act.get("operation"),
                "risk": _agent_v2_v100_operation_risk(act.get("operation")),
                "target": dict(act.get("target") or {}),
                "commitment": dict(act.get("commitment") or {}),
                "turn_id": av2.get("last_turn_id"),
            }
            for act in acts
            if bool((act.get("commitment") or {}).get("wants_write"))
        ]
        entities = []
        for act in acts:
            target = act.get("target") if isinstance(act.get("target"), dict) else {}
            ref = {
                key: target.get(key)
                for key in (
                    "resource", "reservation_id", "registration_id", "event_id",
                    "label", "resource_type", "resource_types",
                )
                if _agent_v2_v100_nonempty(target.get(key))
            }
            if ref and ref not in entities:
                entities.append(ref)
        cf["referenced_entities"] = entities[-30:]

    elif etype == "OBSERVATION":
        obs = dict(payload or {})
        active = []
        completed = list(cf.get("completed_tasks") or [])
        for task in (cf.get("active_tasks") or []):
            if _agent_v2_v101_task_completed_by_observation(task, obs):
                completed.append({
                    **dict(task),
                    "status": "completed",
                    "tool": obs.get("tool"),
                    "observation_id": obs.get("observation_id"),
                    "completed_at": datetime.datetime.now(TIMEZONE).isoformat(),
                })
            else:
                active.append(dict(task))
        cf["active_tasks"] = active[-30:]
        cf["completed_tasks"] = completed[-80:]

    elif etype == "RESOLVE_PENDING_INTERACTION":
        qid = str(payload.get("question_id") or "").strip()
        iid = str(payload.get("interaction_id") or "").strip()
        outcome = str(payload.get("outcome") or "resolved")
        interactions = []
        resolved = None
        for item in (cf.get("pending_interactions") or []):
            if not isinstance(item, dict):
                continue
            matches = bool(
                (qid and str(item.get("question_id") or "") == qid)
                or (iid and str(item.get("interaction_id") or "") == iid)
            )
            if matches:
                resolved = dict(item)
                continue
            interactions.append(dict(item))
        cf["pending_interactions"] = interactions
        if qid:
            av2["open_questions"] = [
                q for q in (av2.get("open_questions") or [])
                if str((q or {}).get("question_id") or "") != qid
            ]
        if resolved:
            completed = list(cf.get("completed_tasks") or [])
            completed.append({
                "interaction_id": resolved.get("interaction_id"),
                "question_id": resolved.get("question_id"),
                "outcome": outcome,
                "completed_at": datetime.datetime.now(TIMEZONE).isoformat(),
            })
            cf["completed_tasks"] = completed[-80:]

    cf["version"] = AGENT_V2_UNIFIED_AGENTIC_CORE
    av2["conversation_frame"] = cf
    update_conversation_state(telefono, agent_v2=av2)
    return get_conversation_state(telefono)


def agent_v2_reduce(telefono: str, event: Dict[str, Any]) -> Dict[str, Any]:
    state = _agent_v2_v101_reduce_base(telefono, event)
    try:
        return _agent_v2_v101_sync_conversation_frame(
            telefono, event, state
        )
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V101 CONVERSATION FRAME] "
            f"sync no fatal: {type(exc).__name__}: {exc}"
        )
        return state


# ---------------------------------------------------------------------------
# Agentic Next Best Action: IA propone la forma natural de preguntar; Python
# sólo acepta un field que una Observation real ya declaró faltante.
# ---------------------------------------------------------------------------
_agent_v2_v101_nba_base = elegir_next_best_action_agent_v2


def _agent_v2_v101_missing_fields(
    observations: List[Dict[str, Any]],
) -> List[str]:
    fields: List[str] = []
    for obs in observations or []:
        if not isinstance(obs, dict) or obs.get("status") != "needs_user_input":
            continue
        data = obs.get("data") if isinstance(obs.get("data"), dict) else {}
        values = list(obs.get("missing") or []) + [data.get("field")]
        for value in values:
            field = str(value or "").strip()
            if field and field not in fields:
                fields.append(field)
    return fields


async def elegir_next_best_action_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    chosen = await _agent_v2_v101_nba_base(
        world, perception, goals, observations, status, learning_policy
    )
    if str((chosen or {}).get("action") or "none") != "none":
        return chosen

    missing_fields = _agent_v2_v101_missing_fields(observations)
    if not missing_fields:
        return chosen
    if _agent_v2_v100_active_interactions_from_world(world or {}):
        return chosen

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos NEXT CONVERSATIONAL MOVE. Python ya verificó qué dato falta. "
                        "Elegí EXACTAMENTE un field de missing_fields y redactá UNA pregunta natural, "
                        "breve y contextual. No inventes campos, tools, reservas ni hechos. "
                        "Respondé SOLO JSON: "
                        '{"field":null,"question_text":"","reason":"breve"}.'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": world.get("message"),
                        "missing_fields": missing_fields,
                        "desired_state": (perception or {}).get("desired_state") or {},
                        "task_graph": (perception or {}).get("task_graph") or {},
                        "goals": goals,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        proposal = _loads_llm_json_object(
            response.choices[0].message.content.strip()
        )
    except Exception:
        return chosen

    field = str(proposal.get("field") or "").strip()
    question_text = str(proposal.get("question_text") or "").strip()
    if (
        field not in missing_fields
        or not question_text
        or ("?" not in question_text and "¿" not in question_text)
    ):
        return chosen
    return {
        "action": "agentic_question",
        "reason": str(proposal.get("reason") or "dato faltante verificado"),
        "decision_reason": "V101 IA propone wording; Python valida missing_field",
        "question": {
            "field": field,
            "options": [],
            "question_text": question_text,
            "interaction_kind": "value",
            "goal_context": [
                str(goal.get("goal") or "")
                for goal in (goals.get("goals") or [])
                if isinstance(goal, dict) and str(goal.get("goal") or "")
            ],
            "source": "v101_agentic_next_move",
        },
    }


_agent_v2_v101_render_question_base = _agent_v2_render_open_question


def _agent_v2_render_open_question(question: Dict[str, Any]) -> str:
    custom = str((question or {}).get("question_text") or "").strip()
    if custom:
        return custom
    return _agent_v2_v101_render_question_base(question)


# ---------------------------------------------------------------------------
# Interaction lifecycle closure. El significado ya quedó enlazado durante
# Perception; después de una salida segura cerramos esa interacción concreta.
# Un fallo interno se mantiene abierto para permitir retry sin perder contexto.
# ---------------------------------------------------------------------------
_agent_v2_v101_safe_exit_base = aplicar_regla_universal_salida_segura_agent_v2


def aplicar_regla_universal_salida_segura_agent_v2(
    response: str,
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    status: str,
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    page=None,
    dry_run: bool = False,
) -> Tuple[str, Dict[str, Any]]:
    final_response, safe_exit = _agent_v2_v101_safe_exit_base(
        response, world, perception, goals, observations, status,
        telefono, prospecto, page=page, dry_run=dry_run,
    )
    state = str((safe_exit or {}).get("state") or "")
    if (
        (safe_exit or {}).get("safe")
        and state not in {
            "human_handoff",
            "internal_recovery_question",
            "internal_recovery_read",
            "internal_recovery_write",
            "internal_repair_fallback",
        }
    ):
        relation = _agent_v2_semantic_context_relation(
            _agent_v2_semantic_frame(perception or {})
        ) or {}
        if str(relation.get("type") or "") == "answers_pending":
            qid = str(relation.get("question_id") or "").strip()
            if qid:
                interaction = _agent_v2_v101_pending_interaction_by_qid(
                    world or {}, qid
                )
                agent_v2_reduce(telefono, {
                    "type": "RESOLVE_PENDING_INTERACTION",
                    "payload": {
                        "question_id": qid,
                        "interaction_id": (
                            interaction.get("interaction_id")
                            if isinstance(interaction, dict)
                            else None
                        ),
                        "outcome": state or "resolved",
                    },
                })
                print(
                    "   ✅ [AgentV2 V101 INTERACTION LIFECYCLE] "
                    f"question_id={qid} outcome={state or 'resolved'}"
                )
    return final_response, safe_exit


# ---------------------------------------------------------------------------
# V101 invariant extensions — deterministic, no API.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v101_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v101_base()
    results = list(result.get("results") or [])

    # 1) ContextDelta no puede transformar un READ ambiguo en WRITE sólo por memoria.
    focus = {
        "operation": "reschedule_booking",
        "act": {
            "act_id": "old_write",
            "operation": "reschedule_booking",
            "target": {"resource": "reservation", "reservation_id": "77"},
            "temporal": {"start": "18:00"},
            "provenance": [],
        },
    }
    current = {
        "semantic_frame": {
            "acts": [{
                "act_id": "cur_read",
                "operation": "query_policy",
                "target": {"resource": "court"},
                "temporal": {},
                "quantity": {},
                "changes": [],
                "requested_facts": [],
                "provenance": [],
            }]
        }
    }
    guarded = _agent_v2_v100_project_focus_delta(
        current,
        focus,
        {"operation": "reschedule_booking", "inherit_fields": ["temporal.start"]},
        "mensaje actual",
    )
    results.append({
        "name": "v101_loose_context_cannot_manufacture_write",
        "ok": "reschedule_booking" not in _agent_v2_v101_current_semantic_operations(guarded),
    })

    # 2) PendingInteraction genérico autoriza exactamente su snapshot y target real.
    pending_world = {
        "facts": {
            "reservas_reales": [{"reservation_id": "77"}],
            "memory_owner": "owner",
        },
        "pending_interactions": [{
            "interaction_id": "i1",
            "question_id": "q1",
            "scope_id": "s1",
            "owner": "owner",
            "status": "active",
            "allowed_operations": ["reschedule_booking"],
            "action_snapshot": {
                "act_id": "a1",
                "operation": "reschedule_booking",
                "target": {"resource": "reservation", "reservation_id": "77"},
                "temporal": {"start": "18:00"},
                "changes": [],
            },
            "target_refs": [{"kind": "reservation_id", "id": "77"}],
        }],
    }
    pending_perception = {
        "semantic_frame": {
            "context_relation": {
                "type": "answers_pending",
                "question_id": "q1",
                "scope_id": "s1",
            },
            "acts": [{
                "act_id": "a1",
                "operation": "reschedule_booking",
                "target": {"resource": "reservation", "reservation_id": "77"},
                "temporal": {"start": "18:00"},
                "changes": [],
                "provenance": [{
                    "field": "context.pending_interaction",
                    "source": "pending_option",
                    "evidence": "confirmo",
                    "question_id": "q1",
                    "scope_id": "s1",
                    "reference_id": "77",
                }],
            }],
        }
    }
    pending_auth = _agent_v2_v101_pending_write_authorizations(
        "confirmo", pending_perception, pending_world
    )
    results.append({
        "name": "v101_generic_pending_snapshot_authorizes_exact_write",
        "ok": bool(
            len(pending_auth) == 1
            and pending_auth[0].get("act_id") == "a1"
            and pending_auth[0].get("operation") == "reschedule_booking"
        ),
    })

    # 3) El mismo snapshot no autoriza otra operación.
    wrong = dict(pending_perception)
    wrong_frame = dict(pending_perception["semantic_frame"])
    wrong_frame["acts"] = [{
        **dict(pending_perception["semantic_frame"]["acts"][0]),
        "operation": "cancel_booking",
    }]
    wrong["semantic_frame"] = wrong_frame
    wrong_auth = _agent_v2_v101_pending_write_authorizations(
        "confirmo", wrong, pending_world
    )
    results.append({
        "name": "v101_pending_snapshot_cannot_expand_to_different_write",
        "ok": not wrong_auth,
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ---------------------------------------------------------------------------
# V102 invariant extensions — order-of-authority and pending-context safety.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v102_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v102_base()
    results = list(result.get("results") or [])

    focus = {
        "operation": "query_availability",
        "act": {
            "act_id": "v102_focus",
            "operation": "query_availability",
            "domain": "booking",
            "target": {"resource": "court", "resource_type": "Tenis", "resource_types": ["Tenis"]},
            "temporal": {"day": "2026-09-21", "duration_hours": 1.0},
            "quantity": {}, "changes": [], "requested_facts": ["available_slots"],
            "commitment": {"wants_write": False, "wants_information": True},
            "provenance": [],
        },
    }
    current = {
        "semantic_frame": {
            "acts": [{
                "act_id": "v102_current",
                "operation": "query_availability",
                "domain": "booking",
                "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
                "temporal": {}, "quantity": {}, "changes": [],
                "requested_facts": ["available_slots"],
                "commitment": {"wants_write": False, "wants_information": True},
                "provenance": [],
            }]
        }
    }
    decision = _agent_v2_v102_conservative_read_inheritance(
        current, focus, {"operation": "query_availability", "inherit_fields": []}
    )
    projected = _agent_v2_v100_project_focus_delta(
        current, focus, decision, "Y de padel?"
    )
    projected_act = next((
        a for a in (_agent_v2_semantic_frame(projected).get("acts") or [])
        if a.get("operation") == "query_availability"
    ), {})
    results.append({
        "name": "v102_read_refinement_inherits_day_not_previous_resource",
        "ok": bool(
            (projected_act.get("temporal") or {}).get("day") == "2026-09-21"
            and (projected_act.get("target") or {}).get("resource_type") == "Pádel"
            and "Tenis" not in ((projected_act.get("target") or {}).get("resource_types") or [])
        ),
    })

    q = {
        "question_id": "v102_q",
        "scope_id": "v102_s",
        "field": "hora",
        "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
        "dia": "2026-09-21",
        "resource_type": "Pádel",
        "resource_types": ["Pádel"],
        "goal_context": ["buscar_turno"],
    }
    interaction = _agent_v2_v100_question_to_interaction(q, owner="owner")
    results.append({
        "name": "v102_pending_hour_keeps_day_and_resource_context",
        "ok": bool(
            (interaction.get("context") or {}).get("dia") == "2026-09-21"
            and (interaction.get("context") or {}).get("resource_type") == "Pádel"
            and not (interaction.get("context") or {}).get("hora")
        ),
    })

    token = AGENT_V2_V102_DEFER_CONTEXT_MANAGER.set(True)
    try:
        deferred_ok = AGENT_V2_V102_DEFER_CONTEXT_MANAGER.get() is True
    finally:
        AGENT_V2_V102_DEFER_CONTEXT_MANAGER.reset(token)
    results.append({
        "name": "v102_context_manager_can_be_deferred_until_base_perception_finishes",
        "ok": bool(deferred_ok and AGENT_V2_V102_DEFER_CONTEXT_MANAGER.get() is False),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V103 — PROGRESSIVE BOOKING OBJECTIVE / AGENTIC SLOT COMPLETION
# ============================================================================
# Principio:
#   El usuario no tiene que seguir un guion. Un create_booking incompleto sigue
#   siendo un OBJETIVO DE RESERVA, no se degrada a query_availability.
#
#   IA: entiende el mensaje y redacta la próxima pregunta.
#   Python: mantiene el estado tipado, calcula qué slots faltan, valida config,
#           calendario, targets, pagos y efectos.
#
# No hay regex/keywords nuevas para interpretar lenguaje del cliente.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v103"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_progressive_booking_objective_v103"

# La tool genérica puede transportar contexto de conversación. No ejecuta efectos.
AGENT_V2_TOOL_CATALOG.setdefault("solicitar_dato", {}).setdefault("args", {}).update({
    "question_text": "str|null",
    "resource_type": "str|null",
    "resource_types": "list|null",
    "cancha": "str|null",
    "quincho": "str|null",
    "con_quincho": "bool|null",
    "quincho_duracion_horas": "number|null",
    "action_snapshot": "dict|null",
    "allowed_operations": "list|null",
    "booking_objective_id": "str|null",
})
try:
    AGENT_V2_SAFE_MISSING_FIELDS.update({"resource_type", "quincho"})
except Exception:
    pass


def _agent_v2_v103_ops(perception: Dict[str, Any]) -> set:
    return {
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "")
    }


def _agent_v2_v103_primary_act(perception: Dict[str, Any], operation: str = "") -> Dict[str, Any]:
    acts = [
        dict(act) for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") not in {"greet", "close_conversation", "unknown", ""}
    ]
    if operation:
        match = next((a for a in acts if str(a.get("operation") or "") == operation), None)
        return dict(match or {})
    return dict(acts[0]) if acts else {}


def _agent_v2_v103_active_objective_from_world(world: Dict[str, Any]) -> Dict[str, Any]:
    frame = (world or {}).get("conversation_frame") or {}
    objective = frame.get("booking_objective") if isinstance(frame, dict) else None
    if not isinstance(objective, dict):
        objective = ((world or {}).get("stored_memory") or {}).get("booking_objective")
    if not isinstance(objective, dict):
        return {}
    # ``suspended`` significa que otro acto independiente tomó el turno, no que
    # el objetivo haya terminado. Sigue siendo el único objetivo reanudable; los
    # estados terminales (resolved/superseded/expired) quedan fuera del routing.
    if str(objective.get("status") or "active") not in {
        "active", "collecting", "ready", "preflight", "suspended",
    }:
        return {}
    return dict(objective)


def _agent_v2_v103_interaction_for_relation(perception: Dict[str, Any], world: Dict[str, Any]) -> Dict[str, Any]:
    relation = _agent_v2_semantic_context_relation(_agent_v2_semantic_frame(perception or {})) or {}
    qid = str(relation.get("question_id") or "").strip()
    if qid:
        rows = [
            dict(item) for item in _agent_v2_v100_active_interactions_from_world(world or {})
            if isinstance(item, dict) and str(item.get("question_id") or "") == qid
        ]
        if len(rows) == 1:
            return rows[0]
    return {}


def _agent_v2_v103_unique_booking_interaction(world: Dict[str, Any]) -> Dict[str, Any]:
    rows = []
    for item in _agent_v2_v100_active_interactions_from_world(world or {}):
        if not isinstance(item, dict):
            continue
        allowed = {str(op or "") for op in (item.get("allowed_operations") or [])}
        snapshot = item.get("action_snapshot") if isinstance(item.get("action_snapshot"), dict) else {}
        if "create_booking" in allowed or str(snapshot.get("operation") or "") == "create_booking":
            rows.append(dict(item))
    return rows[0] if len(rows) == 1 else {}


def _agent_v2_v103_quincho_names() -> List[str]:
    names: List[str] = []
    for item in (QUINCHOS or []):
        if isinstance(item, dict):
            value = str(item.get("name") or item.get("nombre") or "").strip()
        else:
            value = str(item or "").strip()
        if value and value not in names:
            names.append(value)
    return names


def _agent_v2_v103_normalized_day(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        resolved = resolver_fecha(raw)
    except Exception:
        resolved = raw
    return str(resolved or raw).strip()


def _agent_v2_v103_action_snapshot(objective: Dict[str, Any]) -> Dict[str, Any]:
    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    snapshot = {
        "act_id": str(objective.get("act_id") or f"v103_booking_{objective.get('objective_id') or uuid.uuid4().hex[:8]}"),
        "operation": "create_booking",
        "domain": "booking",
        "target": target,
        "temporal": temporal,
        "quantity": {"duration_hours": temporal.get("duration_hours")},
        "changes": [],
        "requested_facts": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "provenance": list(objective.get("provenance") or []),
    }
    if isinstance(objective.get("temporal_constraint"), dict):
        snapshot["temporal_constraint"] = dict(
            objective.get("temporal_constraint") or {}
        )
    return snapshot


def _agent_v2_v103_compute_missing(objective: Dict[str, Any]) -> List[str]:
    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    addons = dict(objective.get("addons") or {})
    qaddon = dict(addons.get("quincho") or {})
    missing: List[str] = []

    day = _agent_v2_v103_normalized_day(temporal.get("day"))
    hour = normalizar_hora_detectada(temporal.get("start"))
    types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    label = str(target.get("label") or "").strip()

    if not day:
        missing.append("dia")
    if not hora_es_valida(hour):
        missing.append("hora")
    # ``resource_types`` puede ser el catálogo/candidatos heredados de una
    # consulta de disponibilidad. Sólo una categoría inequívoca completa la
    # elección; varias categorías no significan que el usuario eligió todas.
    if not label and len(types) != 1 and len(_configured_court_type_labels()) > 1:
        missing.append("resource_type")

    if bool(qaddon.get("requested")):
        qname = str(qaddon.get("name") or "").strip()
        if not qname and len(_agent_v2_v103_quincho_names()) > 1:
            missing.append("quincho")

    return list(dict.fromkeys(missing))


def _agent_v2_v103_build_objective(perception: Dict[str, Any], world: Dict[str, Any]) -> Tuple[Dict[str, Any], bool]:
    operations = _agent_v2_v103_ops(perception)
    relation = _agent_v2_semantic_context_relation(_agent_v2_semantic_frame(perception or {})) or {}
    relation_type = str(relation.get("type") or "")
    previous = _agent_v2_v103_active_objective_from_world(world or {})
    interaction = _agent_v2_v103_interaction_for_relation(perception, world)

    explicit_booking = "create_booking" in operations
    continuing_booking = bool(
        previous
        and relation_type == "answers_pending"
    )

    # Desde el Context Binding Gate una interacción sólo puede participar si el
    # TurnSemanticPlan la vinculó por question_id/scope_id/objective_id. La antigua
    # heurística de "hay una sola pregunta de booking" mezclaba un request nuevo
    # con un objetivo collecting anterior y dejaba dos fuentes de verdad activas.
    # Si no hay relation=answers_pending, la memoria permanece pasiva.

    engaged = bool(explicit_booking or continuing_booking)
    if not engaged:
        return (previous, False) if previous else ({}, False)

    now = datetime.datetime.now(TIMEZONE).isoformat()
    objective = dict(previous or {}) if continuing_booking else {}
    if not objective:
        objective = {
            "objective_id": str(uuid.uuid4()),
            "owner": str(((world or {}).get("facts") or {}).get("memory_owner") or ""),
            "status": "collecting",
            "operation": "create_booking",
            "target": {"resource": "court"},
            "temporal": {},
            "addons": {},
            "provenance": [],
            "created_at": now,
        }

    objective["updated_at"] = now
    objective["status"] = "collecting"
    objective["operation"] = "create_booking"
    objective.setdefault("target", {"resource": "court"})
    objective.setdefault("temporal", {})
    objective.setdefault("addons", {})
    objective.setdefault("provenance", [])

    target = dict(objective.get("target") or {})
    target["resource"] = "court"
    temporal = dict(objective.get("temporal") or {})

    # 1) Contexto tipado de la pregunta vigente.
    ictx = dict(interaction.get("context") or {}) if interaction else {}
    snapshot = dict(interaction.get("action_snapshot") or {}) if interaction else {}
    starget = dict(snapshot.get("target") or {}) if isinstance(snapshot.get("target"), dict) else {}
    stemporal = dict(snapshot.get("temporal") or {}) if isinstance(snapshot.get("temporal"), dict) else {}

    inherited_day = ictx.get("dia") or stemporal.get("day")
    inherited_hour = ictx.get("hora") or stemporal.get("start")
    inherited_duration = ictx.get("duracion_horas") or stemporal.get("duration_hours")
    inherited_types = ictx.get("resource_types") or starget.get("resource_types") or ictx.get("resource_type") or starget.get("resource_type")
    inherited_label = ictx.get("cancha") or starget.get("label")

    if inherited_day and not temporal.get("day"):
        temporal["day"] = _agent_v2_v103_normalized_day(inherited_day)
    if inherited_hour and not temporal.get("start"):
        ih = normalizar_hora_detectada(inherited_hour)
        if hora_es_valida(ih):
            temporal["start"] = ih
    if inherited_duration and not temporal.get("duration_hours"):
        temporal["duration_hours"] = inherited_duration
    inherited_types = _canonical_configured_court_types(inherited_types)
    if inherited_types and not (target.get("resource_types") or target.get("resource_type")):
        target["resource_types"] = inherited_types
        target["resource_type"] = inherited_types[0] if len(inherited_types) == 1 else None
    if inherited_label and not target.get("label"):
        target["label"] = inherited_label

    # 2) Current turn SIEMPRE gana.
    current_act = _agent_v2_v103_primary_act(perception, "create_booking")
    if not current_act and continuing_booking:
        current_act = _agent_v2_v103_primary_act(perception)
    ctarget = dict(current_act.get("target") or {}) if isinstance(current_act.get("target"), dict) else {}
    ctemporal = dict(current_act.get("temporal") or {}) if isinstance(current_act.get("temporal"), dict) else {}
    cquantity = dict(current_act.get("quantity") or {}) if isinstance(current_act.get("quantity"), dict) else {}
    entities = dict((perception or {}).get("entities") or {})

    current_day = ctemporal.get("day") or entities.get("dia_resuelto") or entities.get("dia")
    if current_day:
        temporal["day"] = _agent_v2_v103_normalized_day(current_day)
    current_hour = normalizar_hora_detectada(ctemporal.get("start") or entities.get("hora"))
    if hora_es_valida(current_hour):
        temporal["start"] = current_hour
    current_duration = ctemporal.get("duration_hours") or cquantity.get("duration_hours") or entities.get("duracion_horas")
    if current_duration not in (None, ""):
        temporal["duration_hours"] = current_duration
    temporal.setdefault("duration_hours", DEFAULT_TURN_DURATION_HOURS)

    current_types = _canonical_configured_court_types(
        ctarget.get("resource_types") or ctarget.get("resource_type")
    )
    if not current_types:
        try:
            current_types = _agent_v2_resource_type_constraints(perception, world)
        except Exception:
            current_types = []
    if current_types:
        target["resource_types"] = list(current_types)
        target["resource_type"] = current_types[0] if len(current_types) == 1 else None
    current_label = str(ctarget.get("label") or entities.get("cancha") or "").strip()
    if current_label:
        target["label"] = current_label
        inferred_type = _court_type_for_name(current_label)
        if inferred_type:
            target["resource_types"] = [inferred_type]
            target["resource_type"] = inferred_type

    objective["target"] = target
    objective["temporal"] = temporal

    # 3) Addons son parte del objetivo, no un goal paralelo que pueda perderse.
    addons = dict(objective.get("addons") or {})
    qaddon = dict(addons.get("quincho") or {})
    explicit_q = bool((perception or {}).get("explicit_quincho_request"))
    remove_q = False
    try:
        remove_q = bool(_agent_v2_semantics_explicitly_remove_quincho(perception or {}))
    except Exception:
        remove_q = any(
            str(a.get("operation") or "") == "remove_resource"
            and str((a.get("target") or {}).get("resource") or "") == "quincho"
            for a in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
            if isinstance(a, dict)
        )
    if remove_q:
        qaddon = {"requested": False, "name": "", "duration_hours": None, "start": ""}
    elif explicit_q:
        qaddon["requested"] = True

    if bool(qaddon.get("requested")):
        qnames = _agent_v2_v103_quincho_names()
        qname = str(entities.get("quincho") or qaddon.get("name") or "").strip()
        if not qname and len(qnames) == 1:
            qname = qnames[0]
        qaddon["name"] = qname
        qdur = entities.get("quincho_duracion_horas") or qaddon.get("duration_hours")
        if qdur in (None, ""):
            qdur = DEFAULT_TURN_DURATION_HOURS
        qaddon["duration_hours"] = qdur
    addons["quincho"] = qaddon
    objective["addons"] = addons

    if current_act.get("act_id"):
        objective["act_id"] = current_act.get("act_id")
    objective["missing_fields"] = _agent_v2_v103_compute_missing(objective)
    objective["status"] = "ready" if not objective["missing_fields"] else "collecting"
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    return objective, True


def _agent_v2_v103_apply_objective_to_perception(perception: Dict[str, Any], objective: Dict[str, Any]) -> Dict[str, Any]:
    clean = dict(perception or {})
    if not objective:
        return clean
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts = [dict(a) for a in (frame.get("acts") or []) if isinstance(a, dict)]
    booking_index = next((i for i, a in enumerate(acts) if str(a.get("operation") or "") == "create_booking"), None)
    if booking_index is None:
        relation = _agent_v2_semantic_context_relation(frame) or {}
        if str(relation.get("type") or "") == "answers_pending":
            acts = [a for a in acts if str(a.get("operation") or "") in {"greet"}]
            acts.append(_agent_v2_v103_action_snapshot(objective))
            booking_index = len(acts) - 1
    if booking_index is not None:
        act = dict(acts[booking_index])
        target = dict(act.get("target") or {})
        temporal = dict(act.get("temporal") or {})
        otarget = dict(objective.get("target") or {})
        otemporal = dict(objective.get("temporal") or {})
        for key in ("resource", "resource_type", "resource_types", "label"):
            if _agent_v2_v100_nonempty(otarget.get(key)):
                target[key] = otarget.get(key)
        for key in ("day", "start", "duration_hours", "daypart"):
            if _agent_v2_v100_nonempty(otemporal.get(key)):
                temporal[key] = otemporal.get(key)
        act["target"] = target
        act["temporal"] = temporal
        act["quantity"] = {
            **dict(act.get("quantity") or {}),
            "duration_hours": temporal.get("duration_hours"),
        }
        act["operation"] = "create_booking"
        act["commitment"] = {"wants_write": True, "wants_information": False}
        acts[booking_index] = act
        frame["acts"] = acts
        frame["intent"] = {"domain": "booking", "operation": "create_booking"}
        frame["commitment"] = dict(act["commitment"])
        frame["targets"] = [dict(target)]
        frame["temporal"] = dict(temporal)
        clean["semantic_frame"] = frame

    entities = dict(clean.get("entities") or {})
    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    if temporal.get("day"):
        entities["dia"] = temporal.get("day")
        entities["dia_resuelto"] = temporal.get("day")
    if hora_es_valida(normalizar_hora_detectada(temporal.get("start"))):
        entities["hora"] = normalizar_hora_detectada(temporal.get("start"))
    if temporal.get("duration_hours") not in (None, ""):
        entities["duracion_horas"] = temporal.get("duration_hours")
    types = _canonical_configured_court_types(target.get("resource_types") or target.get("resource_type"))
    if types:
        entities["resource_types"] = list(types)
        entities["resource_type"] = types[0] if len(types) == 1 else None
    if target.get("label"):
        entities["cancha"] = target.get("label")
    qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
    if bool(qaddon.get("requested")):
        clean["explicit_quincho_request"] = True
        entities["quincho"] = qaddon.get("name") or entities.get("quincho")
        entities["quincho_duracion_horas"] = qaddon.get("duration_hours")
    clean["entities"] = entities
    clean["booking_objective"] = dict(objective)
    clean["_v103_booking_engaged"] = True
    return clean


# V100 convertía create_booking incompleto a query_availability. V103 conserva
# la intención y deja que el controlador de slots decida el siguiente movimiento.
def _agent_v2_v100_apply_structural_preconditions(perception: Dict[str, Any], world: Dict[str, Any]) -> Dict[str, Any]:
    clean = dict(perception or {})
    frame = _agent_v2_semantic_frame(clean)
    incomplete = False
    for act in (frame.get("acts") or []):
        if not isinstance(act, dict) or str(act.get("operation") or "") != "create_booking":
            continue
        temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
        if not hora_es_valida(normalizar_hora_detectada(temporal.get("start"))):
            incomplete = True
    if incomplete:
        clean["_v103_incomplete_booking"] = True
        print("   🧭 [AgentV2 V103 OBJECTIVE] create_booking incompleto preservado; NO se degrada a query_availability")
    return clean


_percibir_turno_agent_v2_v103_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v103_base(
        mensaje, world, image_path, learning_policy
    )
    objective, engaged = _agent_v2_v103_build_objective(perception, world or {})
    if not engaged:
        if objective:
            perception = dict(perception or {})
            perception["booking_objective"] = dict(objective)
        return perception

    perception = _agent_v2_v103_apply_objective_to_perception(perception, objective)
    # El act_id y la voluntad WRITE vienen de Current Turn/PendingInteraction;
    # sólo agregamos slots estructurados autorizados. Recompilamos contrato.
    perception.pop("execution_contract", None)
    perception["execution_contract"] = _agent_v2_build_execution_contract(perception, world or {})
    perception = _agent_v2_v100_attach_desired_state_and_task_graph(perception, world or {})
    perception["desired_state"]["booking_objective"] = dict(objective)
    perception["task_graph"]["booking_missing_fields"] = list(objective.get("missing_fields") or [])
    perception["task_graph"]["booking_objective_id"] = objective.get("objective_id")
    perception["_v100_semantic_frozen"] = True
    print(
        "   🧠 [AgentV2 V103 PROGRESSIVE BOOKING] "
        f"status={objective.get('status')} missing={objective.get('missing_fields')} "
        f"type={(objective.get('target') or {}).get('resource_type')} "
        f"day={(objective.get('temporal') or {}).get('day')} "
        f"hour={(objective.get('temporal') or {}).get('start')} "
        f"quincho={bool((((objective.get('addons') or {}).get('quincho') or {}).get('requested')))}"
    )
    return perception


async def _agent_v2_v103_question_for_missing(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    objective: Dict[str, Any],
) -> Tuple[str, str]:
    missing = list(objective.get("missing_fields") or [])
    if not missing:
        return "", ""
    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
    options_by_field = {
        "resource_type": _configured_court_type_labels(),
        "quincho": _agent_v2_v103_quincho_names(),
    }
    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos el recepcionista inteligente de un complejo de reservas. El cliente NO sigue formularios: "
                        "puede dar datos en cualquier orden y en varios mensajes. Python ya reconstruyó el objetivo de reserva "
                        "y calculó exactamente qué datos faltan. Redactá UNA sola pregunta breve, natural y humana que "
                        "solicite TODOS los missing_fields; el cliente puede contestarlos juntos o en cualquier orden. "
                        "Devolvé en field el primer campo mencionado, sólo como ancla estructural de la pregunta. "
                        "Nunca preguntes algo que ya figura en known_state. No vuelvas a mostrar toda la disponibilidad salvo que "
                        "el usuario la haya pedido. No inventes disponibilidad, precios, canchas, fechas ni políticas. "
                        "Podés reconocer naturalmente lo que ya pidió (por ejemplo deporte o addon) sin sonar robótico. "
                        "No uses una frase fija. Respondé SOLO JSON: "
                        '{"field":"...","question_text":"...","reason":"..."}.'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": (world or {}).get("message"),
                        "missing_fields": missing,
                        "known_state": {
                            "resource_type": target.get("resource_type"),
                            "resource_types": target.get("resource_types") or [],
                            "court": target.get("label"),
                            "day": temporal.get("day"),
                            "hour": temporal.get("start"),
                            "duration_hours": temporal.get("duration_hours"),
                            "quincho_requested": bool(qaddon.get("requested")),
                            "quincho": qaddon.get("name"),
                        },
                        "options_by_field": options_by_field,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        data = _loads_llm_json_object(response.choices[0].message.content.strip())
        field = str(data.get("field") or "").strip()
        text = str(data.get("question_text") or "").strip()
        if field in missing and text and ("?" in text or "¿" in text):
            return field, text
    except Exception as exc:
        print(f"   ⚠️ [AgentV2 V103 NEXT MOVE] IA no disponible: {type(exc).__name__}: {exc}")

    # Resiliencia operativa: no interpreta lenguaje; verbaliza exclusivamente
    # los fields que Python ya demostró faltantes.
    field = missing[0]
    prompts = {
        "dia": "qué día exacto",
        "hora": "a qué hora",
        "resource_type": "qué deporte",
        "quincho": "qué quincho",
    }
    requested = [prompts.get(item, str(item)) for item in missing]
    if len(requested) == 1:
        body = requested[0]
    else:
        body = ", ".join(requested[:-1]) + " y " + requested[-1]
    fallback = f"¿Me indicás {body} querés reservar?"
    return field, fallback


_planificar_agent_v2_v103_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    objective = dict((perception or {}).get("booking_objective") or {})
    engaged = bool((perception or {}).get("_v103_booking_engaged"))
    contract = dict((perception or {}).get("execution_contract") or {})
    if engaged and objective and contract.get("authoritative"):
        missing = list(objective.get("missing_fields") or [])
        if missing:
            field, question_text = await _agent_v2_v103_question_for_missing(
                world or {}, perception or {}, objective
            )
            if field in missing:
                target = dict(objective.get("target") or {})
                temporal = dict(objective.get("temporal") or {})
                qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
                options = []
                if field == "resource_type":
                    options = _configured_court_type_labels()
                elif field == "quincho":
                    options = _agent_v2_v103_quincho_names()
                step = {
                    "tool": "solicitar_dato",
                    "args": {
                        "campo": field,
                        "opciones": options,
                        "motivo": "dato faltante del objetivo de reserva activo",
                        "booking_choice": True,
                        "question_text": question_text,
                        "dia": temporal.get("day"),
                        "hora": temporal.get("start"),
                        "duracion_horas": temporal.get("duration_hours"),
                        "cancha": target.get("label"),
                        "resource_type": target.get("resource_type"),
                        "resource_types": list(target.get("resource_types") or []),
                        "con_quincho": bool(qaddon.get("requested")),
                        "quincho": qaddon.get("name"),
                        "quincho_duracion_horas": qaddon.get("duration_hours"),
                        "action_snapshot": _agent_v2_v103_action_snapshot(objective),
                        "allowed_operations": ["create_booking", "query_availability"],
                        "booking_objective_id": objective.get("objective_id"),
                    },
                    "reason": f"V103 objetivo incompleto: falta {field}",
                    "replan_after": False,
                }
                print(
                    "   🧭 [AgentV2 V103 NEXT MOVE] "
                    f"missing={missing} → ask={field}; no se ejecuta fallback dia_hora_reserva"
                )
                return {
                    "steps": [step],
                    "done_if": f"booking objective recibe {field}",
                    "reason": "V103 progressive booking slot completion",
                    "goal_progress": _agent_v2_goal_progress(goals, observations),
                    "task_graph": (perception or {}).get("task_graph") or {},
                    "semantic_source": AGENT_V2_UNIFIED_AGENTIC_CORE,
                }

        print("   ✅ [AgentV2 V103 OBJECTIVE READY] slots conversacionales completos → Planner operativo")

    return await _planificar_agent_v2_v103_base(
        world, perception, goals, observations, offline_mode, learning_policy
    )


_ejecutar_tool_agent_v2_v103_base = ejecutar_tool_agent_v2


async def ejecutar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    telefono: str,
    prospecto: Dict,
    user_messages: List[str],
    page=None,
    image_path: str = "",
) -> Dict[str, Any]:
    observation = await _ejecutar_tool_agent_v2_v103_base(
        tool, args, world, perception, goals, telefono, prospecto,
        user_messages, page=page, image_path=image_path,
    )
    if tool == "solicitar_dato" and isinstance(observation, dict):
        data = dict(observation.get("data") or {})
        for key in (
            "question_text", "resource_type", "resource_types", "cancha",
            "quincho", "con_quincho", "quincho_duracion_horas",
            "action_snapshot", "allowed_operations", "booking_objective_id",
        ):
            if args.get(key) not in (None, "", []):
                data[key] = args.get(key)
        observation = dict(observation)
        observation["data"] = data
    return observation


_agent_v2_verified_missing_input_response_v103_base = _agent_v2_verified_missing_input_response


def _agent_v2_verified_missing_input_response(
    observations: List[Dict[str, Any]],
    world: Optional[Dict[str, Any]] = None,
) -> str:
    rows = [obs for obs in (observations or []) if isinstance(obs, dict)]
    if rows and all(
        obs.get("tool") == "solicitar_dato" and obs.get("status") == "needs_user_input"
        for obs in rows
    ):
        custom = str(((rows[-1].get("data") or {}).get("question_text")) or "").strip()
        if custom:
            print("   🧠 [AgentV2 V103 AGENTIC QUESTION] wording generado por IA; template rígido omitido")
            return custom
    return _agent_v2_verified_missing_input_response_v103_base(observations, world)


_agent_v2_v100_question_to_interaction_v103_base = _agent_v2_v100_question_to_interaction


def _agent_v2_v100_question_to_interaction(question: Dict[str, Any], *, owner: str = "") -> Dict[str, Any]:
    q = dict(question or {})
    if q.get("question_text") and not (q.get("question") or q.get("prompt") or q.get("message")):
        q["question"] = q.get("question_text")
    interaction = _agent_v2_v100_question_to_interaction_v103_base(q, owner=owner)
    if isinstance(q.get("action_snapshot"), dict):
        interaction["action_snapshot"] = dict(q.get("action_snapshot") or {})
    if q.get("allowed_operations"):
        interaction["allowed_operations"] = list(dict.fromkeys(
            str(op) for op in q.get("allowed_operations") or [] if str(op or "") in AGENT_V2_SEMANTIC_OPERATIONS
        ))
    if q.get("booking_objective_id"):
        interaction.setdefault("context", {})["booking_objective_id"] = q.get("booking_objective_id")
    if isinstance(q.get("temporal_constraint"), dict):
        interaction.setdefault("context", {})["temporal_constraint"] = dict(
            q.get("temporal_constraint") or {}
        )
    return interaction


_agent_v2_reduce_v103_base = agent_v2_reduce


def _agent_v2_v103_persist_objective(telefono: str, objective: Dict[str, Any]) -> Dict[str, Any]:
    state = get_conversation_state(telefono)
    av2 = _agent_v2_state(state)
    cf = _agent_v2_v100_conversation_frame(av2)
    cf["booking_objective"] = dict(objective or {})
    cf["version"] = AGENT_V2_UNIFIED_AGENTIC_CORE
    av2["conversation_frame"] = cf
    update_conversation_state(telefono, agent_v2=av2)
    return get_conversation_state(telefono)


def _agent_v2_v103_supersede_previous_objective(
    telefono: str,
    payload: Dict[str, Any],
) -> None:
    """Aplica el lifecycle antes de persistir un BookingObjective independiente.

    La memoria histórica se conserva, pero el objetivo y sus interacciones dejan de
    competir en routing activo. La decisión de independencia ya viene del plan
    semántico; esta función sólo valida identidades y actualiza estado tipado.
    """
    incoming = (
        dict((payload or {}).get("booking_objective") or {})
        if isinstance((payload or {}).get("booking_objective"), dict)
        else {}
    )
    if not incoming or str(incoming.get("operation") or "") != "create_booking":
        return

    relation = _agent_v2_semantic_context_relation(
        _agent_v2_semantic_frame(payload or {})
    ) or {}
    if str(relation.get("type") or "") not in {
        "new_request", "new_question", "unrelated", "no_pending",
    }:
        return

    state = get_conversation_state(telefono)
    av2 = _agent_v2_state(state)
    cf = _agent_v2_v100_conversation_frame(av2)
    previous = (
        dict(cf.get("booking_objective") or {})
        if isinstance(cf.get("booking_objective"), dict)
        else {}
    )
    previous_id = str(previous.get("objective_id") or "").strip()
    incoming_id = str(incoming.get("objective_id") or "").strip()
    if not previous_id or not incoming_id or previous_id == incoming_id:
        return
    if str(previous.get("status") or "") not in {
        "active", "collecting", "ready", "preflight", "suspended",
    }:
        return

    now = datetime.datetime.now(TIMEZONE).isoformat()
    previous["status"] = "superseded"
    previous["superseded_at"] = now
    previous["superseded_by_objective_id"] = incoming_id
    history = [
        dict(item) for item in (cf.get("objective_history") or [])
        if isinstance(item, dict)
    ]
    history.append(previous)
    cf["objective_history"] = history[-30:]

    superseded_qids = set()
    interactions = []
    for raw in (cf.get("pending_interactions") or []):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        bound_id = str(
            ((item.get("context") or {}).get("booking_objective_id")) or ""
        ).strip()
        if bound_id == previous_id and str(item.get("status") or "active") in {
            "active", "suspended", "engaged",
        }:
            item["status"] = "superseded"
            item["superseded_at"] = now
            item["superseded_by_objective_id"] = incoming_id
            superseded_qids.add(str(item.get("question_id") or "").strip())
        interactions.append(item)
    cf["pending_interactions"] = interactions[-30:]
    cf["booking_objective"] = previous
    av2["open_questions"] = [
        q for q in (av2.get("open_questions") or [])
        if str((q or {}).get("question_id") or "").strip() not in superseded_qids
    ]
    av2["conversation_frame"] = cf
    update_conversation_state(telefono, agent_v2=av2)
    print(
        "   🧬 [AgentV2 OBJECTIVE LIFECYCLE] "
        f"objective={previous_id} ACTIVE→SUPERSEDED new_objective={incoming_id}"
    )


def agent_v2_reduce(telefono: str, event: Dict[str, Any]) -> Dict[str, Any]:
    evt = dict(event or {})
    etype = str(evt.get("type") or "").upper()
    payload = dict(evt.get("payload") or {}) if isinstance(evt.get("payload"), dict) else {}

    if etype == "PERCEPTION_UPDATED":
        _agent_v2_v103_supersede_previous_objective(telefono, payload)

    # Toda pregunta dentro de un objetivo de reserva transporta el snapshot del
    # objetivo. Así una respuesta fragmentaria puede continuar sin repetir slots.
    if etype == "SET_OPEN_QUESTION":
        before = get_conversation_state(telefono)
        av2_before = _agent_v2_state(before)
        cf_before = _agent_v2_v100_conversation_frame(av2_before)
        objective = cf_before.get("booking_objective") if isinstance(cf_before.get("booking_objective"), dict) else {}
        if objective and str(objective.get("status") or "") in {"active", "collecting", "ready", "preflight"}:
            target = dict(objective.get("target") or {})
            temporal = dict(objective.get("temporal") or {})
            qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
            payload.setdefault("goal_context", ["crear_reserva"])
            payload.setdefault("allowed_operations", ["create_booking", "query_availability"])
            payload.setdefault("action_snapshot", _agent_v2_v103_action_snapshot(objective))
            payload.setdefault("booking_objective_id", objective.get("objective_id"))
            if isinstance(objective.get("temporal_constraint"), dict):
                payload.setdefault(
                    "temporal_constraint",
                    dict(objective.get("temporal_constraint") or {}),
                )
            payload.setdefault("dia", temporal.get("day"))
            if str(payload.get("field") or "") not in {"hora", "hora_aclaracion"}:
                payload.setdefault("hora", temporal.get("start"))
            payload.setdefault("duracion_horas", temporal.get("duration_hours"))
            payload.setdefault("cancha", target.get("label"))
            payload.setdefault("resource_type", target.get("resource_type"))
            payload.setdefault("resource_types", list(target.get("resource_types") or []))
            payload.setdefault("con_quincho", bool(qaddon.get("requested")))
            payload.setdefault("quincho", qaddon.get("name"))
            payload.setdefault("quincho_duracion_horas", qaddon.get("duration_hours"))
            evt["payload"] = payload

    state = _agent_v2_reduce_v103_base(telefono, evt)

    if etype == "PERCEPTION_UPDATED":
        objective = payload.get("booking_objective") if isinstance(payload.get("booking_objective"), dict) else {}
        if objective and payload.get("_v103_booking_engaged"):
            state = _agent_v2_v103_persist_objective(telefono, objective)
    elif etype == "OBSERVATION":
        tool = str(payload.get("tool") or "")
        if tool in {"crear_reserva", "crear_reservas_multiples"} and payload.get("ok") and str(payload.get("status") or "") in {"success", "confirmed", "already_exists"}:
            current = get_conversation_state(telefono)
            av2 = _agent_v2_state(current)
            cf = _agent_v2_v100_conversation_frame(av2)
            objective = dict(cf.get("booking_objective") or {})
            if objective:
                objective["status"] = "completed"
                objective["completed_at"] = datetime.datetime.now(TIMEZONE).isoformat()
                state = _agent_v2_v103_persist_objective(telefono, objective)
    return state


_construir_world_state_agent_v2_v103_base = construir_world_state_agent_v2


def construir_world_state_agent_v2(
    telefono: str,
    prospecto: Dict,
    conv_state: Dict,
    mensaje_actual: str,
    image_path: str = "",
) -> Dict[str, Any]:
    world = _construir_world_state_agent_v2_v103_base(
        telefono, prospecto, conv_state, mensaje_actual, image_path
    )
    cf = (world or {}).get("conversation_frame") or {}
    objective = cf.get("booking_objective") if isinstance(cf, dict) else None
    if isinstance(objective, dict):
        world["booking_objective"] = dict(objective)
        world.setdefault("stored_memory", {})["booking_objective"] = dict(objective)
    return world


# Invariantes V103: el estado faltante se calcula desde slots tipados; no desde
# frases particulares del usuario.
_run_agent_v2_invariant_evals_v103_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v103_base()
    results = list(result.get("results") or [])

    objective = {
        "objective_id": "obj_v103",
        "status": "collecting",
        "operation": "create_booking",
        "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
        "temporal": {"day": "Lunes 21/09", "start": None, "duration_hours": 1.0},
        "addons": {"quincho": {"requested": True, "name": (_agent_v2_v103_quincho_names() or [""])[0], "duration_hours": 1.0}},
    }
    missing = _agent_v2_v103_compute_missing(objective)
    results.append({
        "name": "v103_padel_today_with_quincho_asks_only_hour",
        "ok": missing == ["hora"],
    })

    objective_hour = json.loads(json.dumps(objective, ensure_ascii=False, default=str))
    objective_hour["temporal"]["start"] = "20:00"
    results.append({
        "name": "v103_after_hour_booking_objective_is_ready",
        "ok": _agent_v2_v103_compute_missing(objective_hour) == [],
    })

    snapshot = _agent_v2_v103_action_snapshot(objective)
    results.append({
        "name": "v103_pending_question_keeps_create_booking_snapshot",
        "ok": bool(
            snapshot.get("operation") == "create_booking"
            and (snapshot.get("target") or {}).get("resource_type") == "Pádel"
            and (snapshot.get("temporal") or {}).get("day") == "Lunes 21/09"
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V104 — BOOKING COLLECTION AUTHORITY / GOAL-POLICY CONTINUITY
# ============================================================================
# Problema resuelto:
#   V103 podía reconstruir correctamente un objetivo incompleto, por ejemplo:
#       Pádel + hoy + quincho + falta hora
#   pero ExecutionContract podía quedar no-autoritativo porque todavía no era
#   seguro EJECUTAR el write. Eso hacía que Goal Compiler degradara a `otro` y
#   Policy bloqueara incluso `solicitar_dato`.
#
# Principio V104:
#   "No puedo ejecutar todavía" != "no puedo continuar la conversación".
#
# Se separan dos autoridades:
#   1. BookingCollectionContract: sólo puede completar slots del objetivo activo.
#      ÚNICA tool permitida: solicitar_dato. No autoriza writes.
#   2. ExecutionContract: conserva toda la autoridad exclusiva sobre calendario,
#      holds, pagos y mutaciones reales.
#
# IA decide cómo formular la próxima pregunta; Python sólo decide qué campo falta
# y comprueba que la pregunta pertenece exactamente al objetivo tipado vigente.
# No se agregan regex ni keyword routers para interpretar lenguaje del usuario.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v104"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_booking_collection_authority_v104"


def _agent_v2_v104_current_objective(
    perception: Optional[Dict[str, Any]],
    world: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = perception or {}
    objective = perception.get("booking_objective")
    if not isinstance(objective, dict):
        objective = _agent_v2_v103_active_objective_from_world(world or {})
    if not isinstance(objective, dict):
        return {}
    if str(objective.get("operation") or "") != "create_booking":
        return {}
    if str(objective.get("status") or "") not in {"active", "collecting", "ready", "preflight"}:
        return {}
    return dict(objective)


def _agent_v2_v104_verified_booking_intent(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    objective: Dict[str, Any],
) -> bool:
    """Prueba que existe voluntad de reserva sin autorizar todavía el write.

    Aceptamos únicamente:
      - un create_booking del turno actual autorizado por Semantic Effect Verifier;
      - o una respuesta a una PendingInteraction de create_booking ya stateful.

    Nunca se infiere intención desde texto/regex en esta capa.
    """
    if not objective:
        return False

    act_id = str(objective.get("act_id") or "").strip()
    verification = (
        perception.get("semantic_effect_verification")
        if isinstance(perception.get("semantic_effect_verification"), dict)
        else {}
    )
    for item in (verification.get("write_authorizations") or []):
        if not isinstance(item, dict) or item.get("authorized") is not True:
            continue
        if str(item.get("operation") or "create_booking") not in {"", "create_booking"}:
            continue
        authorized_id = str(item.get("act_id") or "").strip()
        if not act_id or not authorized_id or authorized_id == act_id:
            return True

    relation = _agent_v2_semantic_context_relation(
        _agent_v2_semantic_frame(perception or {})
    ) or {}
    if str(relation.get("type") or "") == "answers_pending":
        interaction = _agent_v2_v103_interaction_for_relation(perception, world or {})
        snapshot = (
            interaction.get("action_snapshot")
            if isinstance(interaction.get("action_snapshot"), dict)
            else {}
        )
        allowed = {str(op or "") for op in (interaction.get("allowed_operations") or [])}
        if str(snapshot.get("operation") or "") == "create_booking" or "create_booking" in allowed:
            objective_id = str(objective.get("objective_id") or "").strip()
            interaction_objective_id = str(
                ((interaction.get("context") or {}).get("booking_objective_id")) or ""
            ).strip()
            if not interaction_objective_id or not objective_id or interaction_objective_id == objective_id:
                return True

    return False


def _agent_v2_v104_build_collection_contract(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    objective = _agent_v2_v104_current_objective(perception, world)
    if not objective:
        return {}

    missing = _agent_v2_v103_compute_missing(objective)
    if not missing:
        return {}

    safe_fields = {"dia", "hora", "resource_type", "quincho"}
    if any(field not in safe_fields for field in missing):
        return {}

    if not _agent_v2_v104_verified_booking_intent(perception, world, objective):
        return {}

    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    addons = dict(objective.get("addons") or {})
    qaddon = dict(addons.get("quincho") or {})

    configured_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if (target.get("resource_types") or target.get("resource_type")) and not configured_types:
        return {}

    objective_id = str(objective.get("objective_id") or "").strip()
    if not objective_id:
        return {}

    return {
        "contract_id": str(uuid.uuid4()),
        "version": AGENT_V2_UNIFIED_AGENTIC_CORE,
        "authoritative": True,
        "phase": "collecting_booking_objective",
        "objective_id": objective_id,
        "operation": "create_booking",
        "missing_fields": list(missing),
        "allowed_fields": list(missing),
        "allowed_tools": ["solicitar_dato"],
        "effects": ["state"],
        "write_authority": None,
        "write_allowed": False,
        "objective_snapshot": {
            "target": target,
            "temporal": temporal,
            "addons": addons,
        },
        "known_state": {
            "resource_type": target.get("resource_type"),
            "resource_types": list(target.get("resource_types") or []),
            "cancha": target.get("label"),
            "dia": temporal.get("day"),
            "hora": temporal.get("start"),
            "duracion_horas": temporal.get("duration_hours"),
            "con_quincho": bool(qaddon.get("requested")),
            "quincho": qaddon.get("name"),
            "quincho_duracion_horas": qaddon.get("duration_hours"),
        },
        "action_snapshot": _agent_v2_v103_action_snapshot(objective),
    }


def _agent_v2_v104_collection_contract(
    perception: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    contract = (perception or {}).get("booking_collection_contract")
    if not isinstance(contract, dict) or contract.get("authoritative") is not True:
        return {}
    if str(contract.get("phase") or "") != "collecting_booking_objective":
        return {}
    if str(contract.get("operation") or "") != "create_booking":
        return {}
    if set(contract.get("allowed_tools") or []) != {"solicitar_dato"}:
        return {}
    if contract.get("write_allowed") is not False:
        return {}
    return dict(contract)


_percibir_turno_agent_v2_v104_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v104_base(
        mensaje, world, image_path, learning_policy
    )
    clean = dict(perception or {})
    collection = _agent_v2_v104_build_collection_contract(clean, world or {})
    if not collection:
        clean.pop("booking_collection_contract", None)
        return clean

    clean["booking_collection_contract"] = collection
    clean["_v104_booking_collection_authority"] = True

    # Una reserva incompleta puede no estar lista para WRITE, pero eso no es una
    # ambigüedad conversacional: el dato faltante ya está tipado por Python.
    # Por lo tanto no dejamos que Semantic Clarification interrumpa la recolección.
    clean["semantic_clarification_required"] = False
    clean.pop("semantic_clarification", None)

    print(
        "   🧭 [AgentV2 V104 BOOKING COLLECTION AUTHORITY] "
        f"objective={collection.get('objective_id')} "
        f"missing={collection.get('missing_fields')} "
        "allowed_tools=['solicitar_dato']; writes=False"
    )
    return clean


_inferir_goals_agent_v2_v104_base = inferir_goals_agent_v2


async def inferir_goals_agent_v2(
    perception: Dict,
    world: Dict,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    collection = _agent_v2_v104_collection_contract(perception)
    if collection:
        print(
            "   🧩 [AgentV2 V104 GOAL AUTHORITY] "
            "objetivo incompleto sigue siendo booking → buscar_turno + crear_reserva"
        )
        return {
            "goals": [
                {
                    "goal": "buscar_turno",
                    "priority": 1.0,
                    "reason": "V104 active booking objective requires slot completion",
                },
                {
                    "goal": "crear_reserva",
                    "priority": 0.99,
                    "reason": "V104 user already committed to create_booking",
                },
            ],
            "primary_goal": "buscar_turno",
            "reason": "v104_booking_collection_contract",
        }
    return await _inferir_goals_agent_v2_v104_base(
        perception, world, learning_policy=learning_policy
    )


_agent_v2_execution_contract_freezes_meaning_v104_base = _agent_v2_execution_contract_freezes_meaning


def _agent_v2_execution_contract_freezes_meaning(
    perception: Dict[str, Any],
    goals_override: Any = None,
) -> bool:
    if not isinstance(goals_override, dict) and _agent_v2_v104_collection_contract(perception):
        # Congela únicamente el significado del objetivo conversacional. La
        # autoridad WRITE continúa siendo exclusiva del ExecutionContract real.
        return True
    return _agent_v2_execution_contract_freezes_meaning_v104_base(
        perception, goals_override
    )


def _agent_v2_v104_collection_step_args(
    objective: Dict[str, Any],
    field: str,
    question_text: str,
) -> Dict[str, Any]:
    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
    options: List[str] = []
    if field == "resource_type":
        options = _configured_court_type_labels()
    elif field == "quincho":
        options = _agent_v2_v103_quincho_names()

    return {
        "campo": field,
        "opciones": options,
        "motivo": "dato faltante del objetivo de reserva activo",
        "booking_choice": True,
        "question_text": question_text,
        "dia": temporal.get("day"),
        "hora": temporal.get("start"),
        "duracion_horas": temporal.get("duration_hours"),
        "cancha": target.get("label"),
        "resource_type": target.get("resource_type"),
        "resource_types": list(target.get("resource_types") or []),
        "con_quincho": bool(qaddon.get("requested")),
        "quincho": qaddon.get("name"),
        "quincho_duracion_horas": qaddon.get("duration_hours"),
        "action_snapshot": _agent_v2_v103_action_snapshot(objective),
        "allowed_operations": ["create_booking", "query_availability"],
        "booking_objective_id": objective.get("objective_id"),
    }


_planificar_agent_v2_v104_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    collection = _agent_v2_v104_collection_contract(perception)
    objective = _agent_v2_v104_current_objective(perception, world)
    if collection and objective:
        missing = [
            field for field in _agent_v2_v103_compute_missing(objective)
            if field in set(collection.get("allowed_fields") or [])
        ]
        if missing:
            field, question_text = await _agent_v2_v103_question_for_missing(
                world or {}, perception or {}, objective
            )
            if field not in missing:
                field = missing[0]
                # Este renderer no interpreta el mensaje: sólo verbaliza el field
                # que el contrato tipado ya determinó como faltante.
                question_text = _agent_v2_render_open_question({
                    "field": field,
                    "options": (
                        _configured_court_type_labels()
                        if field == "resource_type"
                        else _agent_v2_v103_quincho_names()
                        if field == "quincho"
                        else []
                    ),
                    "booking_choice": True,
                })

            args = _agent_v2_v104_collection_step_args(
                objective, field, question_text
            )
            print(
                "   🧭 [AgentV2 V104 NEXT MOVE] "
                f"objective={collection.get('objective_id')} missing={missing} "
                f"→ ask={field}; contexto preservado"
            )
            return {
                "steps": [{
                    "tool": "solicitar_dato",
                    "args": args,
                    "reason": f"V104 completar objetivo activo: falta {field}",
                    "replan_after": False,
                }],
                "done_if": f"booking objective recibe {field}",
                "reason": "v104_booking_collection_contract",
                "goal_progress": _agent_v2_goal_progress(goals, observations),
                "task_graph": (perception or {}).get("task_graph") or {},
                "semantic_source": AGENT_V2_UNIFIED_AGENTIC_CORE,
            }

    return await _planificar_agent_v2_v104_base(
        world, perception, goals, observations, offline_mode, learning_policy
    )


def _agent_v2_v104_collection_args_match(
    args: Dict[str, Any],
    perception: Dict[str, Any],
) -> Tuple[bool, str]:
    collection = _agent_v2_v104_collection_contract(perception)
    objective = _agent_v2_v104_current_objective(perception, {})
    if not collection or not objective:
        return False, "no_booking_collection_contract"

    field = str((args or {}).get("campo") or "").strip()
    allowed_fields = {str(x or "") for x in (collection.get("allowed_fields") or [])}
    if not field or field not in allowed_fields:
        return False, "field_outside_booking_collection_contract"

    objective_id = str(objective.get("objective_id") or "").strip()
    arg_objective_id = str((args or {}).get("booking_objective_id") or "").strip()
    if not objective_id or arg_objective_id != objective_id:
        return False, "booking_objective_id_mismatch"

    snapshot = (args or {}).get("action_snapshot")
    if not isinstance(snapshot, dict) or str(snapshot.get("operation") or "") != "create_booking":
        return False, "booking_action_snapshot_missing"

    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))

    expected_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    provided_types = _canonical_configured_court_types(
        (args or {}).get("resource_types") or (args or {}).get("resource_type")
    )
    if expected_types and provided_types and provided_types != expected_types:
        return False, "booking_resource_type_context_mismatch"

    expected_day = _agent_v2_v103_normalized_day(temporal.get("day"))
    provided_day = _agent_v2_v103_normalized_day((args or {}).get("dia"))
    if field != "dia" and expected_day and provided_day and provided_day != expected_day:
        return False, "booking_day_context_mismatch"

    if bool(qaddon.get("requested")) != bool((args or {}).get("con_quincho")):
        return False, "booking_addon_context_mismatch"

    return True, "v104_booking_collection_authority"


_validar_tool_agent_v2_v104_base = validar_tool_agent_v2


def validar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    image_path: str = "",
) -> Dict[str, Any]:
    # Excepción extremadamente angosta: sólo una pregunta stateful, sin efecto
    # externo, que complete exactamente un field declarado por el objetivo.
    if tool == "solicitar_dato":
        matches, reason = _agent_v2_v104_collection_args_match(
            args or {}, perception or {}
        )
        if matches:
            print(
                "   🔐 [AgentV2 V104 COLLECTION POLICY] "
                f"autoriza solicitar_dato field={(args or {}).get('campo')} "
                "sin autorizar ningún WRITE"
            )
            return {
                "ok": True,
                "args": dict(args or {}),
                "authority": reason,
                "write_allowed": False,
            }

    return _validar_tool_agent_v2_v104_base(
        tool, args, world, perception, goals, image_path
    )


_agent_v2_nba_candidates_v104_base = _agent_v2_nba_candidates


def _agent_v2_nba_candidates(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
) -> List[Dict[str, Any]]:
    # Si V104 ya abrió exactamente la pregunta del slot faltante, NBA no agrega
    # una segunda pregunta ni un fallback genérico en el mismo turno.
    if _agent_v2_v104_collection_contract(perception) and any(
        isinstance(obs, dict)
        and obs.get("tool") == "solicitar_dato"
        and obs.get("status") == "needs_user_input"
        for obs in (observations or [])
    ):
        return []
    return _agent_v2_nba_candidates_v104_base(
        world, perception, goals, observations, status
    )


# Invariantes V104 — prueban la separación entre conversación y mutación.
_run_agent_v2_invariant_evals_v104_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v104_base()
    results = list(result.get("results") or [])

    objective = {
        "objective_id": "obj_v104",
        "act_id": "act_v104",
        "status": "collecting",
        "operation": "create_booking",
        "target": {
            "resource": "court",
            "resource_type": "Pádel",
            "resource_types": ["Pádel"],
        },
        "temporal": {
            "day": "Lunes 21/09",
            "start": None,
            "duration_hours": 1.0,
        },
        "addons": {
            "quincho": {
                "requested": True,
                "name": (_agent_v2_v103_quincho_names() or [""])[0],
                "duration_hours": 1.0,
            }
        },
        "missing_fields": ["hora"],
    }
    perception = {
        "_v103_booking_engaged": True,
        "booking_objective": objective,
        "semantic_frame": {
            "schema_valid": True,
            "context_relation": {"type": "new_request"},
            "acts": [_agent_v2_v103_action_snapshot(objective)],
        },
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [{
                "act_id": "act_v104",
                "operation": "create_booking",
                "authorized": True,
            }],
        },
        # Simula exactamente el caso roto: write contract no autoritativo.
        "execution_contract": {
            "authoritative": False,
            "allowed_tools": [],
            "clarification_reasons": ["historical_context_not_authorized"],
        },
    }
    collection = _agent_v2_v104_build_collection_contract(perception, {})
    perception["booking_collection_contract"] = collection

    results.append({
        "name": "v104_non_authoritative_write_contract_can_still_collect_missing_hour",
        "ok": bool(
            collection.get("authoritative")
            and collection.get("missing_fields") == ["hora"]
            and collection.get("allowed_tools") == ["solicitar_dato"]
            and collection.get("write_allowed") is False
        ),
    })

    ask_args = _agent_v2_v104_collection_step_args(
        objective, "hora", "¿A qué hora te gustaría reservar?"
    )
    ask_validation = validar_tool_agent_v2(
        "solicitar_dato",
        ask_args,
        {},
        perception,
        {
            "primary_goal": "buscar_turno",
            "goals": [
                {"goal": "buscar_turno", "priority": 1.0},
                {"goal": "crear_reserva", "priority": 0.99},
            ],
        },
    )
    results.append({
        "name": "v104_collection_policy_allows_only_matching_missing_field_question",
        "ok": bool(ask_validation.get("ok") and ask_validation.get("write_allowed") is False),
    })

    wrong_args = dict(ask_args)
    wrong_args["campo"] = "dia"
    wrong_match, _ = _agent_v2_v104_collection_args_match(wrong_args, perception)
    results.append({
        "name": "v104_collection_contract_cannot_ask_already_known_day",
        "ok": not wrong_match,
    })

    results.append({
        "name": "v104_collection_contract_freezes_goal_reinterpretation",
        "ok": _agent_v2_execution_contract_freezes_meaning(perception) is True,
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V105 — PENDING BOOKING COMPLETION / READY-TO-HOLD AUTHORITY
# ============================================================================
# Problema resuelto:
#   Un objetivo create_booking podía quedar correctamente en modo collecting
#   (ej. Pádel + hoy + quincho + falta hora), pero cuando el usuario respondía
#   solamente el dato faltante la Perception general podía reinterpretar ese
#   turno como query_availability. El objetivo quedaba huérfano y el agente se
#   limitaba a decir que el slot estaba libre, sin crear hold ni pedir seña.
#
# Principio V105:
#   Una PendingInteraction tipada pertenece al objetivo que la originó. Si hay
#   una única interacción activa de create_booking y el turno actual aporta el
#   campo que esa interacción pidió, primero se completa ESE objetivo. No se
#   vuelve a empezar la conversación desde cero.
#
#   IA posee el significado del lenguaje. Python sólo:
#     - verifica identidad/owner/question_id/objective_id;
#     - valida valores contra configuración/horarios;
#     - conserva el snapshot del objetivo;
#     - mantiene cerrada toda mutación hasta que Effect Verifier la autoriza.
#
# No se agregan regex/keywords para inferir intención del usuario.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v105"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_pending_booking_completion_v105"


def _agent_v2_v105_normalize_missing_field(field: Any) -> str:
    value = str(field or "").strip()
    aliases = {
        "hora_aclaracion": "hora",
        "dia_hora_reserva": "hora",
        "tipo_cancha": "resource_type",
    }
    return aliases.get(value, value)


def _agent_v2_v105_matching_booking_interaction(
    world: Dict[str, Any],
    objective: Dict[str, Any],
) -> Tuple[Dict[str, Any], str]:
    """Devuelve una única interacción activa que complete el objetivo vigente.

    No interpreta texto. Vincula exclusivamente estructuras persistidas:
    objective_id + action_snapshot/allowed_operations + field faltante.
    """
    if not isinstance(objective, dict):
        return {}, ""
    objective_id = str(objective.get("objective_id") or "").strip()
    missing = {
        _agent_v2_v105_normalize_missing_field(field)
        for field in _agent_v2_v103_compute_missing(objective)
        if _agent_v2_v105_normalize_missing_field(field)
    }
    if not objective_id or not missing:
        return {}, ""

    matches: List[Tuple[Dict[str, Any], str]] = []
    for item in _agent_v2_v100_active_interactions_from_world(world or {}):
        if not isinstance(item, dict):
            continue
        field = _agent_v2_v105_normalize_missing_field(item.get("field"))
        if field not in missing:
            continue
        allowed = {
            str(op or "").strip()
            for op in (item.get("allowed_operations") or [])
            if str(op or "").strip()
        }
        snapshot = (
            dict(item.get("action_snapshot") or {})
            if isinstance(item.get("action_snapshot"), dict)
            else {}
        )
        if (
            "create_booking" not in allowed
            and str(snapshot.get("operation") or "") != "create_booking"
        ):
            continue
        interaction_objective_id = str(
            ((item.get("context") or {}).get("booking_objective_id")) or ""
        ).strip()
        if interaction_objective_id and interaction_objective_id != objective_id:
            continue
        if not str(item.get("question_id") or "").strip():
            continue
        matches.append((dict(item), field))

    if len(matches) != 1:
        return {}, ""
    return matches[0]


def _agent_v2_v105_current_provenance_matches(
    perception: Dict[str, Any],
    fields: set,
    mensaje: str,
) -> bool:
    message_key = normalizar_texto_ia(mensaje or "")
    for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or []):
        if not isinstance(act, dict):
            continue
        for item in (act.get("provenance") or []):
            if not isinstance(item, dict):
                continue
            if str(item.get("source") or "") != "current_user_turn":
                continue
            if str(item.get("field") or "").strip() not in fields:
                continue
            evidence = normalizar_texto_ia(item.get("evidence") or "")
            if not evidence or not message_key or evidence in message_key:
                return True
    return False


def _agent_v2_v105_structured_answer_value(
    perception: Dict[str, Any],
    field: str,
    mensaje: str,
    world: Dict[str, Any],
) -> Tuple[Any, str]:
    """Extrae un valor YA entendido por las capas semánticas actuales.

    Esto no clasifica intención. Sólo reutiliza campos tipados con evidencia del
    current turn. Si no hay evidencia fuerte devuelve vacío y la capa IA de
    resolución contextual decide si corresponde continuar.
    """
    field = _agent_v2_v105_normalize_missing_field(field)
    frame = _agent_v2_semantic_frame(perception or {})
    acts = [
        act for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") not in {"greet", "close_conversation", "unknown", ""}
    ]
    entities = dict((perception or {}).get("entities") or {})

    if field == "hora":
        values: List[Any] = []
        for act in acts:
            temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
            values.append(temporal.get("start"))
        values.extend([
            (frame.get("temporal") or {}).get("start") if isinstance(frame.get("temporal"), dict) else None,
            entities.get("hora"),
        ])
        grounded = bool(
            _agent_v2_v105_current_provenance_matches(
                perception,
                {"temporal.start", "hora", "start_time"},
                mensaje,
            )
            or _agent_v2_has_grounded_current_exact_time(perception or {}, mensaje or "")
            or (perception or {}).get("_deterministic_hour_grounding")
        )
        if grounded:
            for value in values:
                hour = normalizar_hora_detectada(value)
                if hora_es_valida(hour):
                    return hour, "structured_current_turn"
        return None, ""

    if field == "dia":
        current_grounded = _agent_v2_v105_current_provenance_matches(
            perception,
            {"temporal.day", "day", "dia"},
            mensaje,
        )
        if current_grounded:
            values: List[Any] = []
            for act in acts:
                temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
                values.append(temporal.get("day"))
            values.extend([
                (frame.get("temporal") or {}).get("day") if isinstance(frame.get("temporal"), dict) else None,
                entities.get("dia_resuelto"),
                entities.get("dia"),
            ])
            for value in values:
                resolved = _agent_v2_v103_normalized_day(value)
                if resolved:
                    return resolved, "structured_current_turn"
        return None, ""

    if field == "resource_type":
        current_grounded = _agent_v2_v105_current_provenance_matches(
            perception,
            {"target.resource_type", "target.resource_types", "resource_type", "resource_types"},
            mensaje,
        )
        candidate_types: List[str] = []
        for act in acts:
            target = act.get("target") if isinstance(act.get("target"), dict) else {}
            candidate_types.extend(_canonical_configured_court_types(
                target.get("resource_types") or target.get("resource_type")
            ))
        if not candidate_types and current_grounded:
            candidate_types = _canonical_configured_court_types(
                entities.get("resource_types") or entities.get("resource_type")
            )
        candidate_types = list(dict.fromkeys(candidate_types))
        if current_grounded and len(candidate_types) == 1:
            return candidate_types[0], "structured_current_turn"
        return None, ""

    if field == "quincho":
        qname = str(entities.get("quincho") or "").strip()
        valid_names = _agent_v2_v103_quincho_names()
        if qname and any(normalizar_texto_ia(qname) == normalizar_texto_ia(name) for name in valid_names):
            return next(name for name in valid_names if normalizar_texto_ia(qname) == normalizar_texto_ia(name)), "structured_current_turn"
        return None, ""

    return None, ""


def _agent_v2_v105_validate_ai_slot_value(field: str, value: Any) -> Any:
    field = _agent_v2_v105_normalize_missing_field(field)
    if field == "hora":
        hour = normalizar_hora_detectada(value)
        return hour if hora_es_valida(hour) else None
    if field == "dia":
        resolved = _agent_v2_v103_normalized_day(value)
        return resolved or None
    if field == "resource_type":
        types = _canonical_configured_court_types(value)
        return types[0] if len(types) == 1 else None
    if field == "quincho":
        if isinstance(value, bool):
            return value
        names = _agent_v2_v103_quincho_names()
        key = normalizar_texto_ia(value or "")
        rows = [name for name in names if normalizar_texto_ia(name) == key]
        return rows[0] if len(rows) == 1 else None
    if field == "cancha":
        key = normalizar_texto_ia(value or "")
        rows = [
            name for name in _agent_v2_v105_configured_court_names()
            if normalizar_texto_ia(name) == key
        ]
        return rows[0] if len(rows) == 1 else None
    if field in {"duracion_horas", "duration_hours"}:
        try:
            candidate = float(value)
        except (TypeError, ValueError):
            return None
        allowed = [float(item) for item in (ALLOWED_TURN_DURATIONS or [])]
        return candidate if any(abs(candidate - item) < 0.001 for item in allowed) else None
    return None


async def _agent_v2_v105_ai_pending_slot_resolution(
    mensaje: str,
    perception: Dict[str, Any],
    objective: Dict[str, Any],
    interaction: Dict[str, Any],
    field: str,
) -> Tuple[Any, str]:
    """Fallback semántico sólo para una PendingInteraction ya verificada.

    El modelo decide relación conversacional, no autoridad de escritura. Python
    valida el valor y Effect Verifier conserva la frontera de mutación.
    """
    try:
        target = dict(objective.get("target") or {})
        temporal = dict(objective.get("temporal") or {})
        qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos PENDING BOOKING SLOT RESOLVER. Existe un objetivo de reserva activo y una pregunta "
                        "del asistente todavía pendiente. Decidí si current_user_turn responde ESA pregunta o si "
                        "abre un pedido independiente. Los humanos responden de forma elíptica: una hora sola puede "
                        "responder una pregunta de hora; un día solo puede responder una pregunta de día. No inventes "
                        "datos omitidos y no autorices ninguna escritura. Si responde, extraé únicamente el valor del "
                        "field solicitado. Respondé SOLO JSON: "
                        '{"answers_pending":true,"field":"...","value":null,"confidence":0.0,"reason":"..."}'
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "pending_question": interaction.get("question_text"),
                        "pending_field": field,
                        "objective": {
                            "resource_type": target.get("resource_type"),
                            "resource_types": target.get("resource_types") or [],
                            "court": target.get("label"),
                            "day": temporal.get("day"),
                            "hour": temporal.get("start"),
                            "duration_hours": temporal.get("duration_hours"),
                            "quincho_requested": bool(qaddon.get("requested")),
                            "quincho": qaddon.get("name"),
                        },
                        "current_semantic_frame": _agent_v2_semantic_frame(perception or {}),
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=180,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        data = _loads_llm_json_object(response.choices[0].message.content.strip())
        if data.get("answers_pending") is not True:
            return None, ""
        if _agent_v2_v105_normalize_missing_field(data.get("field")) != field:
            return None, ""
        if float(data.get("confidence") or 0.0) < 0.75:
            return None, ""
        validated = _agent_v2_v105_validate_ai_slot_value(field, data.get("value"))
        if validated is None:
            return None, ""
        return validated, "ai_pending_slot_resolver"
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V105 SLOT RESOLVER] "
            f"fallback IA no disponible: {type(exc).__name__}: {exc}"
        )
        return None, ""


def _agent_v2_v105_promote_pending_answer_frame(
    perception: Dict[str, Any],
    objective: Dict[str, Any],
    interaction: Dict[str, Any],
    field: str,
    value: Any,
    mensaje: str,
) -> Dict[str, Any]:
    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    qid = str(interaction.get("question_id") or "").strip()
    scope_id = str(interaction.get("scope_id") or "").strip()
    snapshot = _agent_v2_v103_action_snapshot(objective)

    current_acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") not in {"greet", "close_conversation", "unknown", ""}
    ]
    # Sólo un create_booking previo puede aportar identidad al act reconstruido.
    # En un turno binding + READ, el único act inicial suele ser query_policy;
    # copiar su act_id hacía que el WRITE y el READ quedaran con el mismo nodo.
    current_booking_acts = [
        act for act in current_acts
        if str(act.get("operation") or "") == "create_booking"
    ]
    current = current_booking_acts[0] if len(current_booking_acts) == 1 else {}
    act = dict(snapshot)
    if current.get("act_id"):
        act["act_id"] = current.get("act_id")

    target = dict(snapshot.get("target") or {})
    temporal = dict(snapshot.get("temporal") or {})
    quantity = dict(snapshot.get("quantity") or {})

    if field == "hora":
        temporal["start"] = value
        temporal["times"] = [value]
    elif field == "dia":
        temporal["day"] = value
    elif field == "resource_type":
        target["resource_types"] = [value]
        target["resource_type"] = value
        # Un label genérico heredado no debe competir con un tipo nuevo.
        if target.get("label") and not _court_type_for_name(str(target.get("label"))):
            target["label"] = None
    elif field == "quincho":
        entities = dict(clean.get("entities") or {})
        if value is False:
            entities["quincho"] = ""
            clean["explicit_quincho_request"] = False
            clean["remove_quincho_request"] = True
        elif value is True:
            entities.pop("quincho", None)
            clean["explicit_quincho_request"] = True
        else:
            entities["quincho"] = value
            clean["explicit_quincho_request"] = True
        clean["entities"] = entities
    elif field == "cancha":
        target["label"] = value
        inferred_type = _court_type_for_name(str(value or ""))
        if inferred_type:
            target["resource_type"] = inferred_type
            target["resource_types"] = [inferred_type]
    elif field in {"duracion_horas", "duration_hours"}:
        temporal["duration_hours"] = value
        quantity["duration_hours"] = value

    act["target"] = target
    act["temporal"] = temporal
    act["quantity"] = quantity
    act["operation"] = "create_booking"
    act["domain"] = "booking"
    act["requested_facts"] = []
    act["commitment"] = {"wants_write": True, "wants_information": False}
    act["selection"] = {
        "question_id": qid,
        "option_id": None,
    }

    proof_field = {
        "hora": "temporal.start",
        "dia": "temporal.day",
        "resource_type": "target.resource_type",
        "quincho": "target.resource",
    }.get(field, field)
    # El primer pending proof es deliberadamente el valor que el usuario acaba
    # de aportar. V101 puede así demostrarlo contra el current_user_turn exacto.
    provenance = [{
        "field": proof_field,
        "source": "pending_option",
        "evidence": str(mensaje or "").strip(),
        "question_id": qid,
        "option_id": None,
        "scope_id": scope_id or None,
        "reference_id": None,
    }, {
        "field": proof_field,
        "source": "current_user_turn",
        "evidence": str(mensaje or "").strip(),
        "question_id": qid,
        "option_id": None,
        "scope_id": scope_id or None,
        "reference_id": None,
    }]
    act["provenance"] = provenance

    greetings = [
        dict(a) for a in (frame.get("acts") or [])
        if isinstance(a, dict) and str(a.get("operation") or "") == "greet"
    ]
    frame.update({
        "source": str(frame.get("source") or "ai"),
        "schema_valid": True,
        "turn_type": "answer",
        "intent": {"domain": "booking", "operation": "create_booking"},
        "targets": [dict(target)],
        "temporal": dict(temporal),
        "requested_facts": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "context_relation": {
            "type": "answers_pending",
            "question_id": qid,
            "scope_id": scope_id or None,
            "references_previous_user_turn": False,
            "references_agent_offer": True,
            "answers_pending_question": True,
        },
        "acts": greetings + [act],
        "ambiguity": {"required": False, "alternatives": []},
    })

    entities = dict(clean.get("entities") or {})
    if field == "hora":
        entities["hora"] = value
        entities["horas"] = [value]
    elif field == "dia":
        entities["dia"] = value
        entities["dia_resuelto"] = value
    elif field == "resource_type":
        entities["resource_type"] = value
        entities["resource_types"] = [value]
    elif field == "cancha":
        entities["cancha"] = value
    elif field in {"duracion_horas", "duration_hours"}:
        entities["duracion_horas"] = value
    clean["entities"] = entities
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "answers_pending"
    clean["answers_pending_field"] = field
    clean["speech_act"] = "answer"
    clean["commitment"] = "confirms_action"
    clean["explicit_actions"] = list(dict.fromkeys(
        list(clean.get("explicit_actions") or []) + ["crear_reserva"]
    ))
    clean["suspend_pending_this_turn"] = False
    clean["current_turn_read_only"] = False
    clean["allow_historical_booking_context_this_turn"] = True

    # Todo contrato READ construido antes de reconocer la respuesta queda viejo.
    for key in (
        "semantic_effect_verification",
        "execution_contract",
        "booking_collection_contract",
        "read_grounding_recovery",
        "_v88_availability_dimension_refinement",
        "_v90_pre_catalog_contextual_availability",
        "_v91_contextual_availability_resolved",
        "_v92_structural_availability_ellipsis",
        "_v93_same_source_replay_bypass",
        # V107: una respuesta verificada a un BookingObjective nuevo reemplaza
        # cualquier resolución de fase/referencia que una capa anterior hubiese
        # inferido antes de vincular la PendingInteraction correcta.
        "phase_resolution",
        "reference_resolution",
        "reservation_target",
    ):
        clean.pop(key, None)
    return clean


_percibir_turno_agent_v2_v105_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v105_base(
        mensaje, world, image_path, learning_policy
    )

    # La resolución V105 se conserva como implementación de proyección/validación,
    # pero ya no vuelve a llamar a IA cuando el gate inicial resolvió el turno.
    # El entry point final aplicará ese plan una sola vez al terminar Perception.
    early_plan_context = globals().get("AGENT_V2_DIALOGUE_CONTEXT_PLAN")
    early_plan = (
        early_plan_context.get()
        if early_plan_context is not None
        else {}
    )
    if isinstance(early_plan, dict) and early_plan.get("status") == "verified":
        return perception

    previous = _agent_v2_v103_active_objective_from_world(world or {})
    if not previous or str(previous.get("operation") or "") != "create_booking":
        return perception
    if not _agent_v2_v103_compute_missing(previous):
        return perception

    interaction, field = _agent_v2_v105_matching_booking_interaction(
        world or {}, previous
    )
    if not interaction or not field:
        return perception

    # Nunca secuestrar una cancelación/reprogramación/pago/etc. nueva para
    # convertirla en respuesta al formulario de reserva anterior.
    current_ops = {
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "")
        not in {"", "greet", "close_conversation", "unknown"}
    }
    conflicting_writes = {
        op for op in current_ops
        if op in AGENT_V2_WRITE_OPERATIONS and op != "create_booking"
    }
    if conflicting_writes:
        return perception

    value, source = _agent_v2_v105_structured_answer_value(
        perception or {}, field, mensaje, world or {}
    )
    if value is None:
        value, source = await _agent_v2_v105_ai_pending_slot_resolution(
            mensaje, perception or {}, previous, interaction, field
        )
    if value is None:
        return perception

    promoted = _agent_v2_v105_promote_pending_answer_frame(
        perception or {}, previous, interaction, field, value, mensaje
    )

    # Reconstruir el objetivo con el mismo question_id y snapshot. V103 hace el
    # merge tipado: current turn gana en el field respondido; lo demás persiste.
    objective, engaged = _agent_v2_v103_build_objective(promoted, world or {})
    if not engaged or not objective:
        return perception
    promoted = _agent_v2_v103_apply_objective_to_perception(promoted, objective)

    # La mutación sigue cerrada hasta verificar el efecto contra la
    # PendingInteraction persistida. No basta con que el slot esté completo.
    promoted.pop("semantic_effect_verification", None)
    promoted.pop("execution_contract", None)
    verified = await _agent_v2_verify_semantic_effects(
        mensaje, promoted, world or {}
    )
    verification = dict((verified or {}).get("semantic_effect_verification") or {})
    authorized_create = any(
        isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("operation") or "create_booking") == "create_booking"
        for item in (verification.get("write_authorizations") or [])
    )
    if verification.get("status") != "verified" or not authorized_create:
        print(
            "   🚫 [AgentV2 V105 BOOKING COMPLETION] "
            "slot entendido pero Effect Verifier no autorizó create_booking"
        )
        return perception

    verified["booking_objective"] = dict(objective)
    verified["_v103_booking_engaged"] = True
    verified["_v105_pending_booking_completed"] = True
    verified["booking_collection_contract"] = {}
    verified.pop("execution_contract", None)
    verified["execution_contract"] = _agent_v2_build_execution_contract(
        verified, world or {}
    )
    verified = _agent_v2_v100_attach_desired_state_and_task_graph(
        verified, world or {}
    )
    verified.setdefault("desired_state", {})["booking_objective"] = dict(objective)
    verified.setdefault("task_graph", {})["booking_missing_fields"] = list(
        objective.get("missing_fields") or []
    )
    verified["task_graph"]["booking_objective_id"] = objective.get("objective_id")
    verified["_v100_semantic_frozen"] = True

    print(
        "   ✅ [AgentV2 V105 BOOKING COMPLETION] "
        f"objective={objective.get('objective_id')} field={field} value={value} "
        f"source={source} missing={objective.get('missing_fields')} "
        f"quincho={bool((((objective.get('addons') or {}).get('quincho') or {}).get('requested')))} "
        "→ create_booking reanudado"
    )
    return verified


_inferir_goals_agent_v2_v105_base = inferir_goals_agent_v2


async def inferir_goals_agent_v2(
    perception: Dict,
    world: Dict,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    objective = dict((perception or {}).get("booking_objective") or {})
    contract = dict((perception or {}).get("execution_contract") or {})
    if (
        (perception or {}).get("_v105_pending_booking_completed") is True
        and objective
        and not _agent_v2_v103_compute_missing(objective)
        and contract.get("authoritative") is True
        and any(
            isinstance(act, dict) and str(act.get("operation") or "") == "create_booking"
            for act in (contract.get("acts") or [])
        )
    ):
        print(
            "   🎯 [AgentV2 V105 GOAL AUTHORITY] "
            "booking objective completo → crear_reserva + buscar_turno"
        )
        return {
            "primary_goal": "crear_reserva",
            "goals": [
                {"goal": "crear_reserva", "priority": 1.0, "reason": "V105 completed booking objective"},
                {"goal": "buscar_turno", "priority": 0.95, "reason": "preflight calendar before hold"},
            ],
            "reason": "v105_pending_booking_completed",
        }
    return await _inferir_goals_agent_v2_v105_base(
        perception, world, learning_policy
    )


def _agent_v2_v105_configured_court_names() -> set:
    names = set()
    for item in (COURTS or []):
        if isinstance(item, dict):
            name = str(item.get("name") or item.get("nombre") or "").strip()
        else:
            name = str(item or "").strip()
        if name:
            names.add(name)
    return names


def _agent_v2_v105_exact_availability_observation(
    observations: List[Dict[str, Any]],
    day: str,
    hour: str,
) -> Optional[Dict[str, Any]]:
    for obs in reversed(observations or []):
        if not isinstance(obs, dict) or obs.get("tool") != "consultar_disponibilidad":
            continue
        data = dict(obs.get("data") or {})
        obs_hour = normalizar_hora_detectada(data.get("hora"))
        if obs_hour != normalizar_hora_detectada(hour):
            continue
        obs_day = data.get("dia") or data.get("dia_resuelto")
        try:
            same_day = _misma_fecha_reserva({"fecha": obs_day}, day)
        except Exception:
            same_day = str(obs_day or "").strip() == str(day or "").strip()
        if same_day:
            return obs
    return None


def _agent_v2_v105_ready_booking_plan(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    if (perception or {}).get("_v105_pending_booking_completed") is not True:
        return None
    objective = dict((perception or {}).get("booking_objective") or {})
    if not objective or _agent_v2_v103_compute_missing(objective):
        return None
    contract = dict((perception or {}).get("execution_contract") or {})
    if contract.get("authoritative") is not True:
        return None
    if not any(
        isinstance(act, dict) and str(act.get("operation") or "") == "create_booking"
        for act in (contract.get("acts") or [])
    ):
        return None

    target = dict(objective.get("target") or {})
    temporal = dict(objective.get("temporal") or {})
    qaddon = dict(((objective.get("addons") or {}).get("quincho") or {}))
    day = _agent_v2_v103_normalized_day(temporal.get("day"))
    hour = normalizar_hora_detectada(temporal.get("start"))
    duration = normalizar_duracion_horas(
        temporal.get("duration_hours") or DEFAULT_TURN_DURATION_HOURS,
        DEFAULT_TURN_DURATION_HOURS,
    )
    types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if not day or not hora_es_valida(hour):
        return None

    valid_court_names = _agent_v2_v105_configured_court_names()
    requested_court = str(target.get("label") or "").strip()
    if requested_court not in valid_court_names:
        requested_court = None

    availability_args = {
        "dia": day,
        "hora": hour,
        "franja_dia": None,
        "cancha": requested_court,
        "duracion_horas": duration,
        "requested_hours": [hour],
        "booking_shape": "single",
        "temporal_mode": None,
        "resource_types": list(types),
        "resource_type": types[0] if len(types) == 1 else None,
    }
    exact_obs = _agent_v2_v105_exact_availability_observation(
        observations or [], day, hour
    )
    progress = _agent_v2_goal_progress(goals or {}, observations or [])

    if exact_obs is None:
        print(
            "   🔎 [AgentV2 V105 READY BOOKING] "
            f"preflight {day} {hour} types={types or ['any']}"
        )
        return {
            "steps": [{
                "tool": "consultar_disponibilidad",
                "args": availability_args,
                "reason": "V105 validar slot completo antes de crear hold",
                "replan_after": True,
            }],
            "done_if": "slot exacto validado",
            "reason": "v105_ready_booking_preflight",
            "goal_progress": progress,
            "task_graph": (perception or {}).get("task_graph") or {},
            "semantic_source": AGENT_V2_UNIFIED_AGENTIC_CORE,
        }

    if not exact_obs.get("ok"):
        data = dict(exact_obs.get("data") or {})
        alternatives = list(data.get("alternativas") or exact_obs.get("alternatives") or [])
        alt_hours = list(dict.fromkeys(
            normalizar_hora_detectada(item.get("hora"))
            for item in alternatives
            if isinstance(item, dict)
            and hora_es_valida(normalizar_hora_detectada(item.get("hora")))
        ))
        args = _agent_v2_v104_collection_step_args(
            objective,
            "hora",
            _agent_v2_render_open_question({
                "field": "hora",
                "options": alt_hours,
                "booking_choice": True,
            }),
        )
        args["opciones"] = alt_hours
        args["motivo"] = "el horario elegido no está disponible; falta una nueva hora"
        print(
            "   🧭 [AgentV2 V105 READY BOOKING] "
            f"slot ocupado → pedir alternativa horas={alt_hours}"
        )
        return {
            "steps": [{
                "tool": "solicitar_dato",
                "args": args,
                "reason": "V105 slot no disponible; conservar objetivo y pedir sólo otra hora",
                "replan_after": False,
            }],
            "done_if": "usuario elige otro horario",
            "reason": "v105_ready_booking_unavailable",
            "goal_progress": progress,
            "task_graph": (perception or {}).get("task_graph") or {},
            "semantic_source": AGENT_V2_UNIFIED_AGENTIC_CORE,
        }

    data = dict(exact_obs.get("data") or {})
    selected_court = str(
        data.get("auto_assigned_court")
        or data.get("single_court")
        or requested_court
        or ""
    ).strip()
    options = [
        str(value or "").strip()
        for value in (data.get("canchas_libres") or data.get("available_courts") or [])
        if str(value or "").strip()
    ]
    if not selected_court and len(options) == 1:
        selected_court = options[0]
    if (
        not selected_court
        and options
        and _agent_v2_v126r2_can_auto_assign_equivalent_court(
            perception,
            options,
        )
    ):
        selected_court = options[0]
        print(
            "   🎯 [AgentV2 V126R2 EQUIVALENT COURT AUTOASSIGN] "
            f"objective={(objective or {}).get('objective_id')} "
            f"resource_type={(target or {}).get('resource_type')} "
            f"court={selected_court}"
        )
    if not selected_court:
        # Si el calendario devuelve varias canchas y no existe autoridad para
        # autoasignar una equivalente, se conserva la elección explícita.
        return {
            "steps": [{
                "tool": "solicitar_dato",
                "args": {
                    **_agent_v2_v104_collection_step_args(
                        objective,
                        "cancha",
                        _agent_v2_render_open_question({
                            "field": "cancha",
                            "options": options,
                            "booking_choice": True,
                        }),
                    ),
                    "campo": "cancha",
                    "opciones": options,
                    "motivo": "hay más de una cancha válida para ese horario",
                },
                "reason": "V105 falta elegir entre canchas equivalentes",
                "replan_after": False,
            }],
            "done_if": "cancha elegida",
            "reason": "v105_ready_booking_court_choice",
            "goal_progress": progress,
            "task_graph": (perception or {}).get("task_graph") or {},
            "semantic_source": AGENT_V2_UNIFIED_AGENTIC_CORE,
        }

    quincho_requested = bool(qaddon.get("requested"))
    quincho_name = str(qaddon.get("name") or "").strip()
    if quincho_requested and not quincho_name:
        qnames = _agent_v2_v103_quincho_names()
        if len(qnames) == 1:
            quincho_name = qnames[0]

    create_args = {
        "dia": day,
        "hora": hour,
        "cancha": selected_court,
        "duracion_horas": duration,
        "requested_hours": [hour],
        "booking_shape": "single",
        "con_quincho": quincho_requested,
        "quincho": quincho_name,
        "quincho_hora_inicio": str(
            qaddon.get("start")
            or _quincho_default_start_after_court(hour, duration)
        ),
        "quincho_duracion_horas": qaddon.get("duration_hours") or 1.0,
    }
    print(
        "   🔒 [AgentV2 V105 READY BOOKING] "
        f"slot validado → crear HOLD {day} {hour} {selected_court} "
        f"quincho={quincho_requested}; reservas_previas="
        f"{len((((world or {}).get('facts') or {}).get('reservas_reales') or []))}"
    )
    return {
        "steps": [{
            "tool": "crear_reserva",
            "args": create_args,
            "reason": "V105 objetivo completo + slot validado; crear hold temporal",
            "replan_after": False,
        }],
        "done_if": "hold temporal creado; esperar comprobante",
        "reason": "v105_ready_booking_commit",
        "goal_progress": progress,
        "task_graph": (perception or {}).get("task_graph") or {},
        "semantic_source": AGENT_V2_UNIFIED_AGENTIC_CORE,
    }


_planificar_agent_v2_v105_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    v105_plan = _agent_v2_v105_ready_booking_plan(
        world or {}, perception or {}, goals or {}, observations or []
    )
    if v105_plan:
        return v105_plan
    return await _planificar_agent_v2_v105_base(
        world, perception, goals, observations, offline_mode, learning_policy
    )


# Invariantes V105: prueban la transición tipada, no frases particulares.
_run_agent_v2_invariant_evals_v105_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v105_base()
    results = list(result.get("results") or [])

    objective = {
        "objective_id": "obj_v105",
        "status": "collecting",
        "operation": "create_booking",
        "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
        "temporal": {"day": "Lunes 21/09", "start": None, "duration_hours": 1.0},
        "addons": {"quincho": {"requested": True, "name": (_agent_v2_v103_quincho_names() or [""])[0], "duration_hours": 1.0}},
        "missing_fields": ["hora"],
    }
    interaction = {
        "interaction_id": "interaction_v105",
        "question_id": "question_v105",
        "scope_id": "scope_v105",
        "status": "active",
        "field": "hora",
        "allowed_operations": ["create_booking", "query_availability"],
        "action_snapshot": _agent_v2_v103_action_snapshot(objective),
        "context": {"booking_objective_id": "obj_v105", "dia": "Lunes 21/09", "resource_type": "Pádel"},
        "question_text": "pregunta de hora generada por el agente",
    }
    world = {
        "facts": {"memory_owner": "+5491100000004", "reservas_reales": [{"reservation_id": "77"}]},
        "pending_interactions": [interaction],
        "conversation_frame": {"booking_objective": objective},
        "stored_memory": {"booking_objective": objective},
    }
    matched, field = _agent_v2_v105_matching_booking_interaction(world, objective)
    results.append({
        "name": "v105_unique_pending_field_binds_same_booking_objective",
        "ok": bool(matched and field == "hora" and matched.get("question_id") == "question_v105"),
    })

    ready = json.loads(json.dumps(objective, ensure_ascii=False, default=str))
    ready["temporal"]["start"] = "20:00"
    ready["status"] = "ready"
    ready["missing_fields"] = []
    ready_perception = {
        "_v105_pending_booking_completed": True,
        "booking_objective": ready,
        "execution_contract": {
            "authoritative": True,
            "acts": [_agent_v2_v103_action_snapshot(ready)],
            "allowed_tools": ["consultar_disponibilidad", "crear_reserva"],
        },
        "task_graph": {},
    }
    preflight = _agent_v2_v105_ready_booking_plan(
        world,
        ready_perception,
        {"primary_goal": "crear_reserva", "goals": [{"goal": "crear_reserva", "priority": 1.0}]},
        [],
    ) or {}
    results.append({
        "name": "v105_ready_booking_preflights_even_with_existing_reservation",
        "ok": bool(
            ((preflight.get("steps") or [{}])[0]).get("tool") == "consultar_disponibilidad"
            and ((preflight.get("steps") or [{}])[0]).get("replan_after") is True
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V106 — EXPLICIT ARGUMENT OWNERSHIP / ANTI-CONTAMINATION BOUNDARY
# ============================================================================
# Problema observado:
#   Un plan correcto de booking preflight emitía:
#       cancha=None, resource_types=['Pádel']
#   pero _agent_v2_merge_known_args() reinterpretaba None como "dato faltante"
#   y reinyectaba una cancha histórica de otra modalidad. Policy bloqueaba luego
#   con resource_type_mismatch y jamás se llegaba a crear el HOLD/pedir seña.
#
# Regla general:
#   SemanticFrame/TaskGraph decide qué dimensiones están presentes en el plan.
#   Policy puede validar sus valores, pero no puede rellenar una dimensión que el
#   Planner ya declaró explícitamente, ni siquiera cuando su valor sea None/[] .
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v106"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_explicit_argument_ownership_v106"


_run_agent_v2_invariant_evals_v106_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v106_base()
    results = list(result.get("results") or [])

    stale_perception = {
        "entities": {
            "dia": "Lunes 21/09",
            "dia_resuelto": "Lunes 21/09",
            "hora": "19:00",
            "cancha": "Cancha 1",
            "resource_type": "Futbol 5",
            "resource_types": ["Futbol 5"],
            "duracion_horas": 2.0,
        },
        "execution_contract": {
            "authoritative": True,
            "authorized_context": {"authorized": True},
        },
    }
    stale_world = {}
    preflight_args = {
        "dia": "Lunes 21/09",
        "hora": "20:00",
        "franja_dia": None,
        "cancha": None,
        "duracion_horas": 1.0,
        "requested_hours": ["20:00"],
        "booking_shape": "single",
        "temporal_mode": None,
        "after_time": None,
        "before_time": None,
        "temporal_relation": None,
        "resource_types": ["Pádel"],
        "resource_type": "Pádel",
    }
    merged = _agent_v2_merge_known_args(
        preflight_args,
        stale_perception,
        stale_world,
    )
    results.append({
        "name": "v106_explicit_none_court_is_not_rehydrated_from_stale_entities",
        "ok": bool(
            merged.get("cancha") is None
            and merged.get("resource_types") == ["Pádel"]
            and merged.get("resource_type") == "Pádel"
            and merged.get("hora") == "20:00"
            and float(merged.get("duracion_horas") or 0) == 1.0
        ),
    })

    # Compatibilidad: si una dimensión NO fue incluida por el Planner, todavía
    # puede completarse desde Perception. V106 no elimina el merge; sólo define
    # ownership explícito.
    inherited = _agent_v2_merge_known_args(
        {"dia": "Lunes 21/09"},
        stale_perception,
        stale_world,
    )
    results.append({
        "name": "v106_absent_field_can_still_be_completed_from_perception",
        "ok": bool(
            inherited.get("cancha") == "Cancha 1"
            and inherited.get("hora") == "19:00"
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V107 — BOOKING OBJECTIVE LINEAGE + INTERNAL PREFLIGHT REPLAN
# ============================================================================
# Problema real observado:
#   El usuario ya tenía una reserva histórica real (#77), pero además estaba
#   construyendo una NUEVA reserva de Pádel + quincho mediante un BookingObjective.
#   Al responder la hora faltante, V105 completó correctamente ese objetivo.
#   Después, _agent_v2_reconcile_existing_reservation_correction() vio una única
#   reserva histórica y convirtió el create_booking nuevo en reschedule_booking.
#
# Regla general:
#   - SemanticFrame / BookingObjective poseen la identidad de la acción.
#   - Una reserva histórica es un FACT, no una instrucción para reinterpretar la
#     intención actual.
#   - Mientras exista un BookingObjective activo de create_booking cuyo target no
#     sea una reservation existente, ninguna heurística de "única reserva" puede
#     retargetearlo a reschedule_booking.
#   - Una reprogramación real sigue permitida cuando la semántica actual ya apunta
#     explícitamente a reservation/reservation_id o a una PendingInteraction de
#     reschedule_booking.
#   - Los READ de preflight marcados replan_after=True se consumen internamente;
#     sólo se pregunta al usuario si la Observation descubre un missing real.
#
# No se agregan regex ni keywords para inferir intención del usuario.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v107"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_booking_objective_lineage_v107"


def _agent_v2_should_replan_after_observation(
    step: Dict[str, Any],
    observation: Dict[str, Any],
) -> bool:
    """Decide si una Observation pertenece al preflight interno del TaskGraph.

    No interpreta lenguaje. Respeta el contrato explícito del Planner:
    replan_after=True + Observation exitosa + cero datos faltantes.
    """
    if not isinstance(step, dict) or not isinstance(observation, dict):
        return False
    if step.get("replan_after") is not True:
        return False
    if observation.get("ok") is not True:
        return False
    missing = [
        str(field or "").strip()
        for field in (observation.get("missing") or [])
        if str(field or "").strip()
    ]
    if missing:
        return False
    return True


def _agent_v2_v107_explicit_existing_reservation_semantics(
    frame: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    """True sólo si la estructura actual YA identifica una reserva existente.

    La mera presencia de una única reserva en world.facts no cuenta como señal.
    """
    semantic = dict(frame or {})
    acts = [
        dict(act)
        for act in (semantic.get("acts") or [])
        if isinstance(act, dict)
    ]
    existing_ops = {
        "reschedule_booking",
        "cancel_booking",
        "modify_resource",
        "remove_resource",
        "register_payment",
        "choose_payment_method",
        "query_reservation",
    }
    for act in acts:
        operation = str(act.get("operation") or "").strip()
        target = dict(act.get("target") or {}) if isinstance(act.get("target"), dict) else {}
        if operation in existing_ops:
            return True
        if str(target.get("resource") or "").strip() == "reservation":
            return True
        if str(target.get("reservation_id") or "").strip():
            return True
        for item in (act.get("provenance") or []):
            if not isinstance(item, dict):
                continue
            field = str(item.get("field") or "").strip()
            reference_id = str(item.get("reference_id") or "").strip()
            if field == "target.reservation_id" and reference_id:
                return True

    relation = _agent_v2_semantic_context_relation(semantic) or {}
    qid = str(relation.get("question_id") or "").strip()
    if qid:
        for interaction in _agent_v2_v100_active_interactions_from_world(world or {}):
            if not isinstance(interaction, dict):
                continue
            if str(interaction.get("question_id") or "").strip() != qid:
                continue
            snapshot = (
                dict(interaction.get("action_snapshot") or {})
                if isinstance(interaction.get("action_snapshot"), dict)
                else {}
            )
            allowed = {
                str(op or "").strip()
                for op in (interaction.get("allowed_operations") or [])
                if str(op or "").strip()
            }
            if (
                str(snapshot.get("operation") or "").strip() == "reschedule_booking"
                or "reschedule_booking" in allowed
                or str(interaction.get("field") or "").strip() == "confirmar_reprogramacion"
            ):
                return True
    return False


def _agent_v2_v107_active_new_booking_lineage(
    frame: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[bool, str]:
    """Detecta identidad persistida de una reserva NUEVA en construcción."""
    objective = _agent_v2_v103_active_objective_from_world(world or {})
    if not isinstance(objective, dict):
        return False, ""
    if str(objective.get("operation") or "").strip() != "create_booking":
        return False, ""
    if str(objective.get("status") or "").strip() in {"completed", "cancelled", "abandoned"}:
        return False, ""

    objective_id = str(objective.get("objective_id") or "").strip()
    if not objective_id:
        return False, ""

    objective_target = (
        dict(objective.get("target") or {})
        if isinstance(objective.get("target"), dict)
        else {}
    )
    if (
        str(objective_target.get("resource") or "").strip() == "reservation"
        or str(objective_target.get("reservation_id") or "").strip()
    ):
        return False, ""

    semantic = dict(frame or {})
    create_acts = [
        act
        for act in (semantic.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "").strip() == "create_booking"
        and bool((act.get("commitment") or {}).get("wants_write"))
    ]
    if not create_acts:
        return False, ""

    if _agent_v2_v107_explicit_existing_reservation_semantics(semantic, world or {}):
        return False, ""

    # Si existe una PendingInteraction enlazada al mismo objective, la identidad
    # es todavía más fuerte. No la hacemos obligatoria para soportar estados
    # migrados V103/V104 en los que el objective_id ya es suficiente autoridad.
    linked = False
    for interaction in _agent_v2_v100_active_interactions_from_world(world or {}):
        if not isinstance(interaction, dict):
            continue
        interaction_objective_id = str(
            ((interaction.get("context") or {}).get("booking_objective_id")) or ""
        ).strip()
        snapshot = (
            dict(interaction.get("action_snapshot") or {})
            if isinstance(interaction.get("action_snapshot"), dict)
            else {}
        )
        allowed = {
            str(op or "").strip()
            for op in (interaction.get("allowed_operations") or [])
            if str(op or "").strip()
        }
        if (
            interaction_objective_id == objective_id
            and (
                str(snapshot.get("operation") or "").strip() == "create_booking"
                or "create_booking" in allowed
            )
        ):
            linked = True
            break

    return True, objective_id + (":pending" if linked else ":objective")


_agent_v2_reconcile_existing_reservation_correction_v107_base = (
    _agent_v2_reconcile_existing_reservation_correction
)


def _agent_v2_reconcile_existing_reservation_correction(
    frame: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str = "",
    temporal_mentions: Any = None,
) -> Dict[str, Any]:
    protected, lineage = _agent_v2_v107_active_new_booking_lineage(
        frame or {}, world or {}
    )
    if protected:
        print(
            "   🧬 [AgentV2 V107 BOOKING LINEAGE] "
            f"{lineage} create_booking nuevo protegido → "
            "reservas históricas NO pueden convertirlo en reschedule_booking"
        )
        return dict(frame or {})

    return _agent_v2_reconcile_existing_reservation_correction_v107_base(
        frame, world, mensaje, temporal_mentions
    )


_run_agent_v2_invariant_evals_v107_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v107_base()
    results = list(result.get("results") or [])

    objective = {
        "objective_id": "obj_v107_new_booking",
        "status": "collecting",
        "operation": "create_booking",
        "target": {
            "resource": "court",
            "resource_type": "Pádel",
            "resource_types": ["Pádel"],
        },
        "temporal": {
            "day": "Lunes 21/09",
            "start": None,
            "duration_hours": 1.0,
        },
        "addons": {
            "quincho": {
                "requested": True,
                "name": (_agent_v2_v103_quincho_names() or [""])[0],
                "duration_hours": 1.0,
            },
        },
        "missing_fields": ["hora"],
    }
    interaction = {
        "interaction_id": "int_v107",
        "question_id": "q_v107",
        "scope_id": "scope_v107",
        "status": "active",
        "field": "hora",
        "allowed_operations": ["create_booking"],
        "action_snapshot": _agent_v2_v103_action_snapshot(objective),
        "context": {"booking_objective_id": objective["objective_id"]},
    }
    world = {
        "facts": {
            # Esta reserva histórica NO es el target del objetivo nuevo.
            "reservas_reales": [{
                "reservation_id": "77",
                "fecha": "21/09/2026",
                "hora": "20:00",
                "cancha": "Cancha 1",
                "duracion_horas": 1.0,
            }],
        },
        "booking_objective": objective,
        "conversation_frame": {"booking_objective": objective},
        "stored_memory": {"booking_objective": objective},
        "pending_interactions": [interaction],
    }
    frame = {
        "source": "ai",
        "schema_valid": True,
        "turn_type": "answer",
        "intent": {"domain": "booking", "operation": "create_booking"},
        "targets": [{"resource": "court", "resource_type": "Pádel"}],
        "temporal": {"day": "Lunes 21/09", "start": "21:00"},
        "commitment": {"wants_write": True, "wants_information": False},
        "context_relation": {
            "type": "answers_pending",
            "question_id": "q_v107",
            "answers_pending_question": True,
            "references_agent_offer": True,
        },
        "acts": [{
            "act_id": "act_v107_create",
            "operation": "create_booking",
            "domain": "booking",
            "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
            "temporal": {"day": "Lunes 21/09", "start": "21:00", "times": ["21:00"]},
            "commitment": {"wants_write": True, "wants_information": False},
            "provenance": [{
                "field": "temporal.start",
                "source": "current_user_turn",
                "evidence": "a las 9 de la noche",
                "question_id": "q_v107",
                "scope_id": "scope_v107",
            }],
        }],
    }
    protected = _agent_v2_reconcile_existing_reservation_correction(
        frame, world, "a las 9 de la noche", [{
            "kind": "time",
            "evidence": "a las 9 de la noche",
            "resolved_value": "21:00",
        }]
    )
    protected_acts = [
        act for act in (protected.get("acts") or []) if isinstance(act, dict)
    ]
    results.append({
        "name": "v107_new_booking_objective_cannot_be_captured_by_old_unique_reservation",
        "ok": bool(
            len(protected_acts) == 1
            and protected_acts[0].get("operation") == "create_booking"
            and str((protected_acts[0].get("target") or {}).get("resource") or "") == "court"
            and not (protected_acts[0].get("target") or {}).get("reservation_id")
        ),
    })

    results.append({
        "name": "v107_internal_preflight_success_replans_even_if_status_is_conversational",
        "ok": _agent_v2_should_replan_after_observation(
            {"tool": "consultar_disponibilidad", "replan_after": True},
            {"tool": "consultar_disponibilidad", "ok": True, "status": "needs_user_input", "data": {}},
        ) is True,
    })
    results.append({
        "name": "v107_real_missing_field_still_waits_for_user",
        "ok": _agent_v2_should_replan_after_observation(
            {"tool": "consultar_disponibilidad", "replan_after": True},
            {"tool": "consultar_disponibilidad", "ok": True, "status": "needs_user_input", "missing": ["cancha"]},
        ) is False,
    })

    explicit_reschedule = json.loads(json.dumps(frame, ensure_ascii=False, default=str))
    explicit_reschedule["intent"] = {"domain": "reservation", "operation": "reschedule_booking"}
    explicit_reschedule["acts"][0]["operation"] = "reschedule_booking"
    explicit_reschedule["acts"][0]["domain"] = "reservation"
    explicit_reschedule["acts"][0]["target"] = {
        "resource": "reservation",
        "reservation_id": "77",
    }
    blocked, _ = _agent_v2_v107_active_new_booking_lineage(explicit_reschedule, world)
    results.append({
        "name": "v107_explicit_reschedule_is_not_hidden_by_new_booking_guard",
        "ok": blocked is False,
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V108 — DIALOGUE-ADJACENT BOOKING MEMORY + UNIFIED READY BOOKING PREFLIGHT
# ============================================================================
# Problemas observados en producción:
#   1) Una PendingInteraction de create_booking perteneciente a una conversación
#      anterior seguía activa en memoria. Conversation Manager podía usarla como
#      si fuera la pregunta inmediatamente anterior y rellenar un BookingObjective
#      NUEVO con slots viejos (ej. hora=20:00) que el usuario no había dado.
#   2) Un BookingObjective que ya estaba completo en el mismo turno no entraba al
#      preflight tipado de V105 porque ese camino estaba condicionado a
#      _v105_pending_booking_completed. El Planner genérico podía degradar
#      resource_type='Pádel' a cancha='padel', que Policy rechazaba.
#
# Principios V108:
#   - Una pregunta de create_booking sólo posee autoridad conversacional mientras
#     sea la pregunta realmente adyacente al turno actual. La identidad se prueba
#     por historial/turno, nunca por regex ni keywords del mensaje del usuario.
#   - Las interacciones no adyacentes se conservan en memoria persistida, pero se
#     vuelven PASIVAS para este turno: no pueden contaminar Current Turn.
#   - Todo BookingObjective create_booking completo y autorizado usa EL MISMO
#     preflight determinista: resource_type permanece como tipo hasta que la tool
#     de disponibilidad resuelve una cancha física configurada.
#   - Policy/Effect Verifier siguen cerrando cualquier WRITE no autorizado.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v108"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_dialogue_adjacent_booking_memory_v108"


def _agent_v2_v108_raw_history(world: Dict[str, Any]) -> List[Dict[str, Any]]:
    stored = _agent_v2_stored_memory(world or {})
    return [
        dict(item)
        for item in (stored.get("history") or [])
        if isinstance(item, dict)
    ]


def _agent_v2_v108_last_assistant_turn(world: Dict[str, Any]) -> Dict[str, Any]:
    """Último mensaje ASSISTANT anterior al CURRENT USER turn.

    Producción persiste CURRENT USER antes de construir World. Recorremos el
    historial hacia atrás y simplemente tomamos el último assistant. No se
    interpreta lenguaje ni intención.
    """
    for item in reversed(_agent_v2_v108_raw_history(world or {})):
        if str(item.get("role") or "").strip() == "assistant":
            return dict(item)
    return {}


def _agent_v2_v108_is_create_booking_interaction(item: Dict[str, Any]) -> bool:
    if not isinstance(item, dict):
        return False
    allowed = {
        str(op or "").strip()
        for op in (item.get("allowed_operations") or [])
        if str(op or "").strip()
    }
    snapshot = (
        dict(item.get("action_snapshot") or {})
        if isinstance(item.get("action_snapshot"), dict)
        else {}
    )
    return bool(
        "create_booking" in allowed
        or str(snapshot.get("operation") or "").strip() == "create_booking"
    )


def _agent_v2_v108_booking_interaction_is_adjacent(
    item: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    """Prueba que la pregunta de booking sigue siendo la pregunta vigente.

    Autoridad por identidad conversacional:
      - question_text debe estar representado en el último mensaje assistant; o
      - si no existe question_text (estado migrado), created_at debe ser posterior
        al último assistant conocido o suficientemente cercano a él.

    Nunca se inspeccionan palabras del mensaje USER para decidir intención.
    """
    if not _agent_v2_v108_is_create_booking_interaction(item):
        return True

    last_assistant = _agent_v2_v108_last_assistant_turn(world or {})
    if not last_assistant:
        # Fixtures/offline antiguos pueden no persistir assistant history.
        return True

    assistant_text = str(last_assistant.get("content") or "").strip()
    question_text = str(item.get("question_text") or "").strip()
    if question_text and assistant_text:
        qkey = normalizar_texto_ia(question_text)
        akey = normalizar_texto_ia(assistant_text)
        if qkey and akey and (qkey in akey or akey in qkey):
            return True
        return False

    # Compatibilidad con estados viejos sin question_text: usar únicamente
    # timestamps persistidos. No damos autoridad indefinida a una pregunta vieja.
    interaction_at = _parse_context_timestamp(item.get("created_at"))
    assistant_at = _parse_context_timestamp(last_assistant.get("timestamp"))
    if interaction_at and assistant_at:
        delta = abs((interaction_at - assistant_at).total_seconds())
        return delta <= 120.0

    # Sin identidad textual ni temporal verificable, la interacción de WRITE no
    # puede gobernar el turno actual. Fail closed sólo para esa memoria vieja.
    return False


_agent_v2_v100_active_interactions_from_world_v108_base = (
    _agent_v2_v100_active_interactions_from_world
)


def _agent_v2_v100_active_interactions_from_world(
    world: Dict[str, Any],
) -> List[Dict[str, Any]]:
    rows = _agent_v2_v100_active_interactions_from_world_v108_base(world or {})
    filtered: List[Dict[str, Any]] = []
    dropped: List[str] = []
    for item in rows:
        if (
            _agent_v2_v108_is_create_booking_interaction(item)
            and not _agent_v2_v108_booking_interaction_is_adjacent(item, world or {})
        ):
            dropped.append(str(item.get("question_id") or item.get("interaction_id") or "?"))
            continue
        filtered.append(dict(item))

    if dropped:
        print(
            "   🧹 [AgentV2 V108 BOOKING MEMORY FRESHNESS] "
            f"interacciones create_booking no adyacentes → pasivas ids={dropped}"
        )
    return filtered


# V103 puede consultar una única interacción cuando Current Turn ya decidió
# create_booking. Desde V108 esa interacción debe estar vinculada al diálogo
# actual; el wrapper anterior hace esa frontera antes de que V103 la vea.


def _agent_v2_v108_interaction_belongs_to_objective(
    interaction: Dict[str, Any],
    objective: Dict[str, Any],
) -> bool:
    if not isinstance(interaction, dict) or not isinstance(objective, dict):
        return False
    objective_id = str(objective.get("objective_id") or "").strip()
    if not objective_id:
        return False
    interaction_objective_id = str(
        ((interaction.get("context") or {}).get("booking_objective_id")) or ""
    ).strip()
    if interaction_objective_id != objective_id:
        return False
    allowed = {
        str(op or "").strip()
        for op in (interaction.get("allowed_operations") or [])
        if str(op or "").strip()
    }
    snapshot = (
        dict(interaction.get("action_snapshot") or {})
        if isinstance(interaction.get("action_snapshot"), dict)
        else {}
    )
    return bool(
        "create_booking" in allowed
        or str(snapshot.get("operation") or "").strip() == "create_booking"
    )


def _agent_v2_v108_current_turn_create_booking(perception: Dict[str, Any]) -> bool:
    return any(
        isinstance(act, dict)
        and str(act.get("operation") or "").strip() == "create_booking"
        and bool((act.get("commitment") or {}).get("wants_write"))
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
    )


def _agent_v2_v108_detach_stale_booking_relation(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    """Impide que answers_pending sin identidad vigente reutilice un objective viejo."""
    clean = dict(perception or {})
    previous = _agent_v2_v103_active_objective_from_world(world or {})
    if not previous or not _agent_v2_v108_current_turn_create_booking(clean):
        return clean, False

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    relation = _agent_v2_semantic_context_relation(frame) or {}
    if str(relation.get("type") or "").strip() != "answers_pending":
        return clean, False

    interaction = _agent_v2_v103_interaction_for_relation(clean, world or {})
    if (
        interaction
        and _agent_v2_v108_interaction_belongs_to_objective(interaction, previous)
        and _agent_v2_v108_booking_interaction_is_adjacent(interaction, world or {})
    ):
        return clean, False

    # La IA actual sí decidió create_booking, pero el pending que intentó ligar
    # no posee identidad conversacional vigente. Conservamos el WRITE actual y
    # convertimos sólo la RELACIÓN a new_request para que V103 cree un objetivo
    # nuevo en vez de copiar slots de una reserva en construcción vieja.
    frame["context_relation"] = {
        "type": "new_request",
        "question_id": None,
        "reference_id": None,
        "references_previous_user_turn": False,
        "references_agent_offer": False,
        "answers_pending_question": False,
    }
    clean["semantic_frame"] = frame
    clean["pending_relation"] = "new_request"
    clean.pop("_v100_pending_resolution", None)
    clean.pop("context_resolution", None)
    clean.pop("authorized_context", None)
    print(
        "   🧼 [AgentV2 V108 OBJECTIVE LINEAGE] "
        "answers_pending sin pregunta adyacente/objective_id válido → "
        "create_booking tratado como objetivo nuevo"
    )
    return clean, True


def _agent_v2_v108_inherit_recent_availability_into_new_booking(
    objective: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Hereda sólo contexto seguro de la disponibilidad inmediatamente anterior.

    Para un WRITE nuevo heredamos día/tipo/duración omitidos, nunca una hora
    exacta por defecto. La hora debe venir del Current Turn o de una
    PendingInteraction vigente (ej. respuesta a la pregunta de hora).
    """
    obj = dict(objective or {})
    focus = _agent_v2_v91_verified_availability_focus(world or {})
    if not focus or not _agent_v2_v92_last_user_turn_matches_availability(world or {}, focus):
        return obj

    target = dict(obj.get("target") or {})
    temporal = dict(obj.get("temporal") or {})
    inherited: List[str] = []

    if not str(temporal.get("day") or "").strip():
        day = str(focus.get("day_iso") or focus.get("dia") or "").strip()
        if day:
            temporal["day"] = _agent_v2_v103_normalized_day(day)
            inherited.append("temporal.day")

    current_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if not current_types:
        focus_types = _canonical_configured_court_types(
            focus.get("resource_types")
            or ([focus.get("resource_type")] if focus.get("resource_type") else [])
        )
        if focus_types:
            target["resource_types"] = list(focus_types)
            target["resource_type"] = focus_types[0] if len(focus_types) == 1 else None
            inherited.append("target.resource_types")

    if temporal.get("duration_hours") in (None, "") and focus.get("duracion_horas") not in (None, ""):
        temporal["duration_hours"] = focus.get("duracion_horas")
        inherited.append("temporal.duration_hours")

    obj["target"] = target
    obj["temporal"] = temporal
    if inherited:
        provenance = list(obj.get("provenance") or [])
        reference_id = str(focus.get("reference_id") or "").strip() or None
        scope_id = str(focus.get("scope_id") or "").strip() or None
        evidence = str(focus.get("source_message") or "")[:500]
        for field in inherited:
            provenance.append({
                "field": field,
                "source": "previous_user_turn",
                "evidence": evidence,
                "reference_id": reference_id,
                "scope_id": scope_id,
                "question_id": None,
                "option_id": None,
            })
        obj["provenance"] = provenance
        print(
            "   🔗 [AgentV2 V108 BOOKING FROM AVAILABILITY] "
            f"inherit={inherited} reference_id={reference_id}"
        )

    obj["missing_fields"] = _agent_v2_v103_compute_missing(obj)
    obj["status"] = "ready" if not obj["missing_fields"] else "collecting"
    obj["action_snapshot"] = _agent_v2_v103_action_snapshot(obj)
    return obj


_agent_v2_v103_build_objective_v108_base = _agent_v2_v103_build_objective


def _agent_v2_v103_build_objective(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    projected, forced_new = _agent_v2_v108_detach_stale_booking_relation(
        perception or {}, world or {}
    )
    previous = _agent_v2_v103_active_objective_from_world(world or {})
    objective, engaged = _agent_v2_v103_build_objective_v108_base(
        projected, world or {}
    )
    if not engaged or not objective:
        return objective, engaged

    explicit_current = _agent_v2_v108_current_turn_create_booking(projected)
    previous_id = str(previous.get("objective_id") or "").strip() if previous else ""
    current_id = str(objective.get("objective_id") or "").strip()
    is_new_objective = bool(
        explicit_current
        and (
            forced_new
            or not previous_id
            or (current_id and current_id != previous_id)
        )
    )
    if is_new_objective:
        objective = _agent_v2_v108_inherit_recent_availability_into_new_booking(
            objective, world or {}
        )
    return objective, engaged


_agent_v2_v105_ready_booking_plan_v108_base = _agent_v2_v105_ready_booking_plan


def _agent_v2_v105_ready_booking_plan(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """Ruta única para TODO BookingObjective create_booking completo.

    V105 originalmente sólo se activaba después de completar un pending field.
    V108 también la activa cuando el usuario entrega todos los slots en un mismo
    mensaje o cuando V103 reconstruye un objetivo completo de forma segura.
    """
    direct = _agent_v2_v105_ready_booking_plan_v108_base(
        world or {}, perception or {}, goals or {}, observations or []
    )
    if direct:
        return direct

    objective = dict((perception or {}).get("booking_objective") or {})
    if not objective:
        return None
    if str(objective.get("operation") or "").strip() != "create_booking":
        return None
    if _agent_v2_v103_compute_missing(objective):
        return None
    if not bool((perception or {}).get("_v103_booking_engaged")):
        return None

    contract = dict((perception or {}).get("execution_contract") or {})
    if contract.get("authoritative") is not True:
        return None
    if not any(
        isinstance(act, dict)
        and str(act.get("operation") or "").strip() == "create_booking"
        for act in (contract.get("acts") or [])
    ):
        return None

    projected = dict(perception or {})
    projected["_v105_pending_booking_completed"] = True
    print(
        "   🔁 [AgentV2 V108 UNIFIED READY BOOKING] "
        "objective completo → preflight tipado V105 (sin Planner genérico)"
    )
    return _agent_v2_v105_ready_booking_plan_v108_base(
        world or {}, projected, goals or {}, observations or []
    )


# La función planificar_agent_v2 definida por V105 hace lookup global de
# _agent_v2_v105_ready_booking_plan, por lo que el wrapper anterior se aplica
# tanto a respuestas de PendingInteraction como a reservas completas one-shot.


_run_agent_v2_invariant_evals_v108_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v108_base()
    results = list(result.get("results") or [])

    now = datetime.datetime.now(TIMEZONE)
    old_question = {
        "interaction_id": "int_v108_old",
        "question_id": "q_v108_old",
        "status": "active",
        "field": "confirmar_slot",
        "allowed_operations": ["create_booking"],
        "action_snapshot": {"operation": "create_booking"},
        "question_text": "¿Confirmás el turno viejo?",
        "created_at": (now - datetime.timedelta(minutes=20)).isoformat(),
    }
    current_question = {
        "interaction_id": "int_v108_current",
        "question_id": "q_v108_current",
        "status": "active",
        "field": "hora",
        "allowed_operations": ["create_booking"],
        "action_snapshot": {"operation": "create_booking"},
        "question_text": "¿A qué hora te gustaría reservar?",
        "created_at": now.isoformat(),
    }
    world = {
        "stored_memory": {
            "history": [
                {"role": "assistant", "content": "¿Confirmás el turno viejo?", "timestamp": (now - datetime.timedelta(minutes=20)).isoformat()},
                {"role": "user", "content": "otra conversación", "timestamp": (now - datetime.timedelta(minutes=19)).isoformat()},
                {"role": "assistant", "content": "¿A qué hora te gustaría reservar?", "timestamp": now.isoformat()},
                {"role": "user", "content": "dale quiero pádel con quincho", "timestamp": now.isoformat()},
            ],
        },
        "pending_interactions": [old_question, current_question],
        "facts": {"memory_owner": ""},
        "message": "dale quiero pádel con quincho",
    }
    active = _agent_v2_v100_active_interactions_from_world(world)
    ids = {str(item.get("question_id") or "") for item in active}
    results.append({
        "name": "v108_stale_booking_question_cannot_govern_current_turn",
        "ok": "q_v108_old" not in ids and "q_v108_current" in ids,
    })

    objective = {
        "objective_id": "obj_v108_ready",
        "status": "ready",
        "operation": "create_booking",
        "target": {
            "resource": "court",
            "resource_type": "Pádel",
            "resource_types": ["Pádel"],
        },
        "temporal": {
            "day": "Lunes 21/09",
            "start": "21:00",
            "duration_hours": 1.0,
        },
        "addons": {
            "quincho": {
                "requested": True,
                "name": (_agent_v2_v103_quincho_names() or [""])[0],
                "duration_hours": 1.0,
            },
        },
        "missing_fields": [],
    }
    perception = {
        "_v103_booking_engaged": True,
        "booking_objective": objective,
        "execution_contract": {
            "authoritative": True,
            "acts": [_agent_v2_v103_action_snapshot(objective)],
            "allowed_tools": ["consultar_disponibilidad", "crear_reserva", "solicitar_dato"],
        },
        "task_graph": {},
    }
    plan = _agent_v2_v105_ready_booking_plan(
        {"facts": {"reservas_reales": []}},
        perception,
        {"primary_goal": "crear_reserva", "goals": [{"goal": "crear_reserva", "priority": 1.0}]},
        [],
    ) or {}
    first = (plan.get("steps") or [{}])[0]
    args = dict(first.get("args") or {})
    results.append({
        "name": "v108_one_shot_ready_booking_uses_typed_preflight",
        "ok": bool(
            first.get("tool") == "consultar_disponibilidad"
            and args.get("cancha") is None
            and args.get("resource_types") == ["Pádel"]
            and args.get("resource_type") == "Pádel"
            and first.get("replan_after") is True
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V109 — MISSING-FIELD OWNERSHIP + VERIFIED BOOKING AUTHORITY
# ============================================================================
# Incidente real resuelto:
#   El agente preguntaba por la HORA de un BookingObjective, pero la propia
#   PendingInteraction podía transportar una hora histórica (p.ej. 20:00) en su
#   context/action_snapshot. Al siguiente turno, V103 reutilizaba ese valor como
#   si el usuario lo hubiese dado, marcaba el objetivo READY y capas posteriores
#   podían volver no-autoritativo el ExecutionContract.
#
# Regla general (sin regex / sin keywords del cliente):
#   1) Si una PendingInteraction pregunta por X, esa interacción NO PUEDE ser la
#      fuente de X. Sólo puede transportar los demás slots del objetivo.
#   2) X se completa únicamente con evidencia estructurada del current_user_turn
#      o con una resolución semántica explícita de esa pregunta.
#   3) Un BookingObjective READY proveniente de una PendingInteraction cuya
#      finalización fue re-verificada por Semantic Effect Verifier conserva
#      autoridad operativa hasta terminar su preflight/hold. Una capa de contexto
#      posterior no puede degradarlo a `otro` ni bloquear su READ de preflight.
#   4) Policy sigue validando configuración, disponibilidad, targets y writes.
#      V109 no infiere intención desde texto y no habilita writes desde memoria.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v109"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_missing_field_ownership_v109"


def _agent_v2_v109_clear_field_from_snapshot(
    snapshot: Dict[str, Any],
    field: str,
) -> Dict[str, Any]:
    """Quita del snapshot únicamente el campo que la pregunta declara faltante.

    Una pregunta no puede responderse a sí misma con un valor histórico. El
    resto del snapshot permanece intacto para conservar el objetivo conversacional.
    """
    clean = json.loads(json.dumps(snapshot or {}, ensure_ascii=False, default=str))
    field = _agent_v2_v105_normalize_missing_field(field)
    target = dict(clean.get("target") or {})
    temporal = dict(clean.get("temporal") or {})

    if field == "hora":
        temporal.pop("start", None)
        temporal.pop("times", None)
    elif field == "dia":
        temporal.pop("day", None)
    elif field == "resource_type":
        target.pop("resource_type", None)
        target.pop("resource_types", None)
        target.pop("label", None)
    elif field == "cancha":
        target.pop("label", None)
    elif field == "quincho":
        # El deseo de incluir quincho puede seguir siendo parte del objetivo;
        # lo que la pregunta no puede aportar es la identidad concreta faltante.
        if str(target.get("resource") or "") == "quincho":
            target.pop("label", None)

    clean["target"] = target
    clean["temporal"] = temporal
    return clean


def _agent_v2_v109_sanitize_missing_field_interaction(
    interaction: Dict[str, Any],
) -> Dict[str, Any]:
    """Una PendingInteraction jamás es autoridad para el field que pregunta."""
    if not isinstance(interaction, dict) or not interaction:
        return {}
    clean = json.loads(json.dumps(interaction, ensure_ascii=False, default=str))
    field = _agent_v2_v105_normalize_missing_field(clean.get("field"))
    if not field:
        return clean

    context = dict(clean.get("context") or {})
    if field == "hora":
        context.pop("hora", None)
    elif field == "dia":
        context.pop("dia", None)
    elif field == "resource_type":
        context.pop("resource_type", None)
        context.pop("resource_types", None)
        context.pop("cancha", None)
    elif field == "cancha":
        context.pop("cancha", None)
    elif field == "quincho":
        context.pop("quincho", None)
    clean["context"] = context

    if isinstance(clean.get("action_snapshot"), dict):
        clean["action_snapshot"] = _agent_v2_v109_clear_field_from_snapshot(
            clean.get("action_snapshot") or {}, field
        )

    clean["_v109_missing_field_owner"] = "current_user_turn"
    return clean


_agent_v2_v103_interaction_for_relation_v109_base = _agent_v2_v103_interaction_for_relation


def _agent_v2_v103_interaction_for_relation(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    interaction = _agent_v2_v103_interaction_for_relation_v109_base(
        perception or {}, world or {}
    )
    return _agent_v2_v109_sanitize_missing_field_interaction(interaction)


_agent_v2_v103_unique_booking_interaction_v109_base = _agent_v2_v103_unique_booking_interaction


def _agent_v2_v103_unique_booking_interaction(
    world: Dict[str, Any],
) -> Dict[str, Any]:
    interaction = _agent_v2_v103_unique_booking_interaction_v109_base(world or {})
    return _agent_v2_v109_sanitize_missing_field_interaction(interaction)


def _agent_v2_v109_clear_objective_field(
    objective: Dict[str, Any],
    field: str,
) -> Dict[str, Any]:
    """Vuelve a marcar como faltante un slot sin ownership válido."""
    obj = json.loads(json.dumps(objective or {}, ensure_ascii=False, default=str))
    field = _agent_v2_v105_normalize_missing_field(field)
    target = dict(obj.get("target") or {})
    temporal = dict(obj.get("temporal") or {})
    addons = dict(obj.get("addons") or {})

    if field == "hora":
        temporal["start"] = None
        temporal.pop("times", None)
    elif field == "dia":
        temporal["day"] = None
    elif field == "resource_type":
        target["resource_type"] = None
        target["resource_types"] = []
        target.pop("label", None)
    elif field == "cancha":
        target.pop("label", None)
    elif field == "quincho":
        qaddon = dict(addons.get("quincho") or {})
        if qaddon.get("requested"):
            qaddon["name"] = ""
            addons["quincho"] = qaddon

    obj["target"] = target
    obj["temporal"] = temporal
    obj["addons"] = addons
    obj["missing_fields"] = _agent_v2_v103_compute_missing(obj)
    obj["status"] = "ready" if not obj["missing_fields"] else "collecting"
    obj["action_snapshot"] = _agent_v2_v103_action_snapshot(obj)
    return obj


def _agent_v2_v109_interaction_governing_objective(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    objective: Dict[str, Any],
) -> Dict[str, Any]:
    """Obtiene la interacción tipada que está gobernando el slot faltante."""
    interaction = _agent_v2_v103_interaction_for_relation(perception or {}, world or {})
    if interaction:
        return interaction
    try:
        matched, _field = _agent_v2_v105_matching_booking_interaction(
            world or {}, objective or {}
        )
        if matched:
            return _agent_v2_v109_sanitize_missing_field_interaction(matched)
    except Exception:
        pass
    return _agent_v2_v103_unique_booking_interaction(world or {})


def _agent_v2_v109_current_turn_owns_field(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    field: str,
) -> bool:
    """True sólo cuando el slot preguntado fue entendido desde ESTE turno."""
    field = _agent_v2_v105_normalize_missing_field(field)
    mensaje = str((world or {}).get("message") or "")

    # Un binding del gate inicial ya demostró identidad, scope, objective, field,
    # evidencia literal y valor canónico. V109 debe reconocer esa prueba como
    # ownership del turno actual; volver a inferirla aquí destruiría una conclusión
    # semántica verificada por una defensa pensada para memoria histórica.
    semantic_plan = (
        (perception or {}).get("turn_semantic_plan")
        if isinstance((perception or {}).get("turn_semantic_plan"), dict)
        else {}
    )
    for binding in (semantic_plan.get("bindings") or []):
        if not isinstance(binding, dict) or binding.get("verified") is not True:
            continue
        if _agent_v2_v105_normalize_missing_field(binding.get("field")) != field:
            continue
        # El Dialogue Context Gate ya validó que la evidencia pertenece al
        # current_user_turn y que interaction/question/scope/objective/field
        # corresponden a una interacción vigente. Repetir aquí una comparación
        # textual contra world["message"] puede fallar por proyecciones parciales
        # del World Model y destruir un binding correcto. La prueba verificada es
        # monotónica dentro del mismo turno.
        print(
            "   ✅ [AgentV2 V109 BINDING OWNERSHIP] "
            f"field={field} question_id={binding.get('question_id')} "
            "→ ownership current-turn preservado"
        )
        return True
    try:
        value, _source = _agent_v2_v105_structured_answer_value(
            perception or {}, field, mensaje, world or {}
        )
        if value is not None:
            return True
    except Exception:
        pass

    # Para campos no escalares, la voluntad semántica explícita puede ser el
    # valor en sí. No usamos texto; consumimos exclusivamente SemanticFrame.
    frame = _agent_v2_semantic_frame(perception or {})
    acts = [a for a in (frame.get("acts") or []) if isinstance(a, dict)]
    if field == "quincho":
        return bool((perception or {}).get("explicit_quincho_request"))
    if field == "cancha":
        return any(str((a.get("target") or {}).get("label") or "").strip() for a in acts)
    return False


_agent_v2_v103_build_objective_v109_base = _agent_v2_v103_build_objective


def _agent_v2_v103_build_objective(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    objective, engaged = _agent_v2_v103_build_objective_v109_base(
        perception or {}, world or {}
    )
    if not engaged or not objective:
        return objective, engaged

    interaction = _agent_v2_v109_interaction_governing_objective(
        perception or {}, world or {}, objective
    )
    field = _agent_v2_v105_normalize_missing_field(
        (interaction or {}).get("field")
    )
    if field and not _agent_v2_v109_current_turn_owns_field(
        perception or {}, world or {}, field
    ):
        before = list(_agent_v2_v103_compute_missing(objective))
        objective = _agent_v2_v109_clear_objective_field(objective, field)
        after = list(objective.get("missing_fields") or [])
        if field in after or before != after:
            print(
                "   🧭 [AgentV2 V109 MISSING-FIELD OWNERSHIP] "
                f"field={field} no pertenece al current_user_turn → "
                f"se mantiene faltante; missing={after}"
            )

    return objective, engaged


def _agent_v2_v109_verified_create_authority(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    objective: Dict[str, Any],
) -> bool:
    """Autoridad de write scoped al objective; nunca nace de memoria histórica."""
    if not objective or str(objective.get("operation") or "") != "create_booking":
        return False
    if _agent_v2_v103_compute_missing(objective):
        return False

    # Camino más fuerte: V105 ya reconstruyó el pending, volvió a ejecutar
    # Semantic Effect Verifier y marcó la finalización del slot.
    if (perception or {}).get("_v105_pending_booking_completed") is True:
        verification = (
            perception.get("semantic_effect_verification")
            if isinstance(perception.get("semantic_effect_verification"), dict)
            else {}
        )
        if verification.get("status") == "verified" and any(
            isinstance(item, dict)
            and item.get("authorized") is True
            and str(item.get("operation") or "create_booking") == "create_booking"
            for item in (verification.get("write_authorizations") or [])
        ):
            return True

    # Camino one-shot: Effect Verifier autorizó el create_booking del current turn.
    verification = (
        perception.get("semantic_effect_verification")
        if isinstance(perception.get("semantic_effect_verification"), dict)
        else {}
    )
    if verification.get("status") != "verified":
        return False
    current_create_ids = {
        str(act.get("act_id") or "")
        for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "create_booking"
    }
    authorized_ids = {
        str(item.get("act_id") or "")
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("operation") or "create_booking") == "create_booking"
    }
    if not (current_create_ids & authorized_ids):
        return False

    # Para ejecutar un booking READY la hora exacta debe estar poseída por este
    # turno o haber sido completada por V105. Esto evita resucitar 20:00 desde
    # una reserva histórica / world_fact.
    if not _agent_v2_v109_current_turn_owns_field(
        perception or {}, world or {}, "hora"
    ):
        return False
    return True


def _agent_v2_v109_ready_execution_contract(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    objective: Dict[str, Any],
) -> Dict[str, Any]:
    if not _agent_v2_v109_verified_create_authority(
        perception or {}, world or {}, objective or {}
    ):
        return {}
    act = _agent_v2_v103_action_snapshot(objective)
    previous = dict((perception or {}).get("execution_contract") or {})
    return {
        **previous,
        "contract_id": str(previous.get("contract_id") or uuid.uuid4()),
        "version": AGENT_V2_UNIFIED_AGENTIC_CORE,
        "source": "verified_booking_objective",
        "schema_valid": True,
        "authoritative": True,
        "acts": [act],
        "allowed_tools": [
            "consultar_disponibilidad",
            "crear_reserva",
            "solicitar_dato",
        ],
        "effects": ["read", "write", "state"],
        "clarification_reasons": [],
        "validation_issues": [],
        "rejected_acts": [],
        "booking_objective_id": objective.get("objective_id"),
        "write_authority": "semantic_effect_verifier",
        "legacy_semantic_fallback_used": False,
    }


_percibir_turno_agent_v2_v109_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v109_base(
        mensaje, world, image_path, learning_policy
    )
    objective = dict((perception or {}).get("booking_objective") or {})
    if not objective or str(objective.get("operation") or "") != "create_booking":
        return perception

    # Recalcular siempre después de todas las capas anteriores: el estado del
    # objetivo es la fuente operativa para la progresión de la reserva.
    missing = _agent_v2_v103_compute_missing(objective)
    objective["missing_fields"] = list(missing)
    objective["status"] = "ready" if not missing else "collecting"
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    perception = dict(perception or {})
    perception["booking_objective"] = dict(objective)

    if missing:
        # Un objective incompleto jamás debe ejecutar write. V104 conserva su
        # BookingCollectionContract y formula sólo el próximo dato faltante.
        perception.pop("_v105_pending_booking_completed", None)
        perception.pop("_v109_ready_booking_authorized", None)
        collection = _agent_v2_v104_build_collection_contract(
            perception, world or {}
        )
        if collection:
            perception["booking_collection_contract"] = collection
        perception = _agent_v2_v100_attach_desired_state_and_task_graph(
            perception, world or {}
        )
        perception.setdefault("desired_state", {})["booking_objective"] = dict(objective)
        perception.setdefault("task_graph", {})["booking_missing_fields"] = list(missing)
        perception["task_graph"]["booking_objective_id"] = objective.get("objective_id")
        perception["_v100_semantic_frozen"] = True
        return perception

    repaired = _agent_v2_v109_ready_execution_contract(
        perception, world or {}, objective
    )
    if repaired:
        perception["execution_contract"] = repaired
        perception["booking_collection_contract"] = {}
        perception["_v105_pending_booking_completed"] = True
        perception["_v109_ready_booking_authorized"] = True
        perception["_v100_semantic_frozen"] = True
        perception = _agent_v2_v100_attach_desired_state_and_task_graph(
            perception, world or {}
        )
        perception.setdefault("desired_state", {})["booking_objective"] = dict(objective)
        perception.setdefault("task_graph", {})["booking_missing_fields"] = []
        perception["task_graph"]["booking_objective_id"] = objective.get("objective_id")
        print(
            "   🔐 [AgentV2 V109 VERIFIED BOOKING AUTHORITY] "
            f"objective={objective.get('objective_id')} READY → "
            "preflight/hold preservados hasta crear_reserva"
        )
    return perception


_inferir_goals_agent_v2_v109_base = inferir_goals_agent_v2


async def inferir_goals_agent_v2(
    perception: Dict,
    world: Dict,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    objective = dict((perception or {}).get("booking_objective") or {})
    contract = dict((perception or {}).get("execution_contract") or {})
    semantic_plan = dict((perception or {}).get("turn_semantic_plan") or {})
    if (
        semantic_plan.get("status") == "verified"
        and semantic_plan.get("semantic_frozen") is True
    ):
        if (perception or {}).get("booking_collection_contract"):
            # La semántica sigue congelada, pero V104 debe compilar la próxima
            # pregunta tipada de un objetivo todavía incompleto.
            pass
        elif contract.get("authoritative") is True:
            compiled = _agent_v2_compile_goals_from_execution_contract(
                perception or {}, world or {}
            )
            print(
                "   🎯 [GOALS] final frozen TurnSemanticPlan → "
                f"{[item.get('goal') for item in (compiled.get('goals') or [])]}"
            )
            return compiled
        else:
            print(
                "   🚫 [GOALS] TurnSemanticPlan congelado sin contrato autorizado → aclaración"
            )
            return {
                "primary_goal": "otro",
                "goals": [{
                    "goal": "otro",
                    "priority": 1.0,
                    "reason": "verified semantic plan blocked; no reinterpretation",
                }],
                "reason": "frozen_semantic_plan_fail_closed",
            }
    if (
        (perception or {}).get("_v109_ready_booking_authorized") is True
        and objective
        and not _agent_v2_v103_compute_missing(objective)
        and contract.get("authoritative") is True
    ):
        print(
            "   🎯 [AgentV2 V109 GOAL AUTHORITY] "
            "objetivo READY verificado → crear_reserva + buscar_turno"
        )
        return {
            "primary_goal": "crear_reserva",
            "goals": [
                {
                    "goal": "crear_reserva",
                    "priority": 1.0,
                    "reason": "V109 verified ready BookingObjective",
                },
                {
                    "goal": "buscar_turno",
                    "priority": 0.95,
                    "reason": "preflight exacto antes del hold",
                },
            ],
            "reason": "v109_verified_booking_objective",
        }
    return await _inferir_goals_agent_v2_v109_base(
        perception, world, learning_policy
    )


# V109 extiende invariantes deterministas. No dependen de frases particulares;
# prueban ownership del field y autoridad del objetivo tipado.
_run_agent_v2_invariant_evals_v109_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v109_base()
    results = list(result.get("results") or [])

    stale_interaction = {
        "interaction_id": "v109_i",
        "question_id": "v109_q",
        "field": "hora",
        "status": "active",
        "allowed_operations": ["create_booking"],
        "context": {
            "booking_objective_id": "v109_obj",
            "dia": "Lunes 21/09",
            "hora": "20:00",
            "resource_type": "Pádel",
        },
        "action_snapshot": {
            "operation": "create_booking",
            "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
            "temporal": {"day": "Lunes 21/09", "start": "20:00", "duration_hours": 1.0},
        },
    }
    sanitized = _agent_v2_v109_sanitize_missing_field_interaction(stale_interaction)
    results.append({
        "name": "v109_question_cannot_supply_its_own_missing_hour",
        "ok": bool(
            "hora" not in (sanitized.get("context") or {})
            and not ((sanitized.get("action_snapshot") or {}).get("temporal") or {}).get("start")
            and ((sanitized.get("action_snapshot") or {}).get("temporal") or {}).get("day") == "Lunes 21/09"
        ),
    })

    phantom_ready = {
        "objective_id": "v109_obj",
        "operation": "create_booking",
        "status": "ready",
        "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
        "temporal": {"day": "Lunes 21/09", "start": "20:00", "duration_hours": 1.0},
        "addons": {"quincho": {"requested": True, "name": (_agent_v2_v103_quincho_names() or [""])[0], "duration_hours": 1.0}},
    }
    cleared = _agent_v2_v109_clear_objective_field(phantom_ready, "hora")
    results.append({
        "name": "v109_phantom_hour_returns_objective_to_collecting",
        "ok": bool(
            (cleared.get("temporal") or {}).get("start") is None
            and cleared.get("status") == "collecting"
            and "hora" in (cleared.get("missing_fields") or [])
            and bool((((cleared.get("addons") or {}).get("quincho") or {}).get("requested")))
        ),
    })

    verified_perception = {
        "_v105_pending_booking_completed": True,
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [{
                "act_id": "act_v109",
                "operation": "create_booking",
                "authorized": True,
            }],
        },
        "semantic_frame": {
            "source": "ai",
            "schema_valid": True,
            "acts": [{
                "act_id": "act_v109",
                "operation": "create_booking",
                "target": {"resource": "court", "resource_type": "Pádel", "resource_types": ["Pádel"]},
                "temporal": {"day": "Lunes 21/09", "start": "21:00"},
                "commitment": {"wants_write": True, "wants_information": False},
                "provenance": [{
                    "field": "temporal.start",
                    "source": "current_user_turn",
                    "evidence": "21:00",
                }],
            }],
        },
    }
    ready = json.loads(json.dumps(phantom_ready, ensure_ascii=False, default=str))
    ready["temporal"]["start"] = "21:00"
    ready["act_id"] = "act_v109"
    ready["missing_fields"] = []
    ready["status"] = "ready"
    contract = _agent_v2_v109_ready_execution_contract(
        verified_perception,
        {"message": "21:00"},
        ready,
    )
    results.append({
        "name": "v109_verified_pending_completion_keeps_ready_booking_authority",
        "ok": bool(
            contract.get("authoritative") is True
            and "consultar_disponibilidad" in (contract.get("allowed_tools") or [])
            and "crear_reserva" in (contract.get("allowed_tools") or [])
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V110 — QUINCHO AFTER-COURT DEFAULT AUTHORITY
# ============================================================================
# Regla única: si el usuario pidió quincho pero no especificó su horario, el
# inicio implícito es el FINAL del bloque de cancha. Los horarios explícitos del
# usuario conservan prioridad y no son sobrescritos por esta regla.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v110"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_quincho_after_court_default_v110"


_run_agent_v2_invariant_evals_v110_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v110_base()
    results = list(result.get("results") or [])

    q_21 = _agent_v2_default_quincho_schedule_after_court("21:00", 1.0)
    results.append({
        "name": "v110_court_21_22_defaults_quincho_22_23",
        "ok": bool(
            q_21.get("hora_inicio") == "22:00"
            and q_21.get("hora_fin") == "23:00"
            and q_21.get("source") == "default_after_court"
        ),
    })

    q_two_hours = _agent_v2_default_quincho_schedule_after_court("19:00", 2.0)
    results.append({
        "name": "v110_two_hour_court_defaults_quincho_after_full_court_block",
        "ok": bool(
            q_two_hours.get("hora_inicio") == "21:00"
            and q_two_hours.get("hora_fin") == "22:00"
        ),
    })

    explicit = _agent_v2_extract_explicit_quincho_schedule(
        "quiero el quincho de 20 a 21"
    )
    results.append({
        "name": "v110_explicit_quincho_schedule_still_wins",
        "ok": bool(
            explicit.get("explicit")
            and explicit.get("hora_inicio") == "20:00"
            and explicit.get("hora_fin") == "21:00"
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V112 — VERIFIED RESERVATION FOCUS + RESOURCE RESCHEDULE AUTHORITY
# ============================================================================
# Objetivo:
# - permitir reprogramar una cancha o el quincho de una reserva ACTIVA aunque
#   el contacto tenga varias reservas;
# - conservar un foco de reserva tipado producido por writes verificados;
# - distinguir por estructura semántica `reschedule_booking` (cancha/reserva)
#   de `modify_resource` (quincho), sin interpretar texto libre en Python;
# - mantener el settlement intacto tanto en turnos pendientes como firmes.
#
# La IA sigue siendo dueña del significado. Python sólo resuelve identidad,
# estado real, disponibilidad, permisos y postcondiciones.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v112"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_resource_reschedule_state_v112"


# modify_resource/add/remove son operaciones semánticas reales. El goal compiler
# no debe degradarlas a `otro` una vez que ExecutionContract ya las autorizó.
AGENT_V2_OPERATION_GOALS.update({
    "modify_resource": ["agregar_quincho"],
    "add_resource": ["agregar_quincho"],
    "remove_resource": ["quitar_quincho"],
})


def _agent_v2_v111_extract_reservation_id(value: Any) -> str:
    """Extrae identidad sólo de objetos estructurados producidos por el sistema."""
    if not isinstance(value, dict):
        return ""

    direct = str(
        value.get("reservation_id")
        or value.get("reserva_id")
        or ""
    ).strip()
    if direct:
        return direct

    for key in (
        "reserva",
        "reserva_verificada",
        "reservation",
        "final_reservation_state",
    ):
        nested = value.get(key)
        if isinstance(nested, dict):
            rid = _agent_v2_v111_extract_reservation_id(nested)
            if rid:
                return rid

    for key in ("rows", "reservas"):
        rows = value.get(key)
        if not isinstance(rows, list):
            continue
        ids = {
            _agent_v2_v111_extract_reservation_id(row)
            for row in rows
            if isinstance(row, dict)
        }
        ids.discard("")
        if len(ids) == 1:
            return next(iter(ids))

    return ""


def _agent_v2_v111_active_logical_reservations(
    world: Dict[str, Any],
) -> Dict[str, Dict[str, Any]]:
    logical: Dict[str, Dict[str, Any]] = {}
    for raw in (((world or {}).get("facts") or {}).get("reservas_reales") or []):
        if not isinstance(raw, dict) or not _reserva_activa(raw):
            continue
        row = _agent_v2_enrich_reservation(raw)
        rid = str(_agent_v2_reservation_id(row) or "").strip()
        if rid:
            logical.setdefault(rid, row)
    return logical


def _agent_v2_v111_verified_reservation_focus(
    world: Dict[str, Any],
    perception: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    """
    Resuelve el booking actualmente enfocado sin leer lenguaje.

    Prioridad:
      1) entidades operativas del turno actual si identifican UNA reserva;
      2) reservation_target canónico persistido;
      3) último write verificado que transporta reservation_id;
      4) única reserva activa.

    Con varias reservas y sin ninguna de esas pruebas devuelve None.
    """
    world = world or {}
    perception = perception or {}
    logical = _agent_v2_v111_active_logical_reservations(world)
    if not logical:
        return None

    entities = dict(perception.get("entities") or {})
    if entities:
        entity_matches: Dict[str, Dict[str, Any]] = {}
        for rid, row in logical.items():
            if _agent_v2_reservation_matches_current_entities(row, entities):
                entity_matches[rid] = row
        if len(entity_matches) == 1:
            rid, row = next(iter(entity_matches.items()))
            print(
                "   🎯 [AgentV2 V112 BOOKING FOCUS] "
                f"current_entities → reservation_id={rid}"
            )
            return row

    stored = (world.get("stored_memory") or {})
    stored_desires = stored.get("desires") if isinstance(stored.get("desires"), dict) else {}
    live_desires = world.get("desires") if isinstance(world.get("desires"), dict) else {}
    facts = world.get("facts") if isinstance(world.get("facts"), dict) else {}

    candidates = [
        stored_desires.get("reservation_target"),
        live_desires.get("reservation_target"),
        facts.get("last_quincho_change"),
        facts.get("last_reservation_reprogrammed"),
        facts.get("last_payment_method_selection"),
        facts.get("last_payment"),
        facts.get("last_partial_payment"),
        facts.get("last_reservation_created"),
    ]

    for candidate in candidates:
        rid = _agent_v2_v111_extract_reservation_id(candidate)
        if rid and rid in logical:
            print(
                "   🎯 [AgentV2 V112 BOOKING FOCUS] "
                f"verified_state → reservation_id={rid}"
            )
            return logical[rid]

    if len(logical) == 1:
        rid, row = next(iter(logical.items()))
        print(
            "   🎯 [AgentV2 V112 BOOKING FOCUS] "
            f"unique_active → reservation_id={rid}"
        )
        return row

    return None


def _agent_v2_v111_has_schedule_change(act: Dict[str, Any]) -> bool:
    """Detecta estructura de horario; no interpreta el mensaje del usuario."""
    act = act or {}
    temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
    if any(temporal.get(key) not in (None, "", []) for key in (
        "start", "end", "times", "day", "offset",
    )):
        return True

    schedule_fields = {
        "start_time", "end_time", "hora", "hora_inicio", "hora_fin",
        "temporal.start", "temporal.end",
        "quincho.start_time", "quincho.end_time",
        "quincho.hora_inicio", "quincho.hora_fin",
    }
    return any(
        isinstance(change, dict)
        and str(change.get("field") or "").strip().casefold() in schedule_fields
        for change in (act.get("changes") or [])
    )


def _agent_v2_v111_canonicalize_resource_schedule_acts(
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Canonicaliza únicamente el TIPO de operación usando target estructurado.

    - horario de cancha/reserva -> reschedule_booking
    - horario de quincho       -> modify_resource

    No clasifica texto y no crea una autorización WRITE nueva.
    """
    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean))
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    if not acts:
        return clean

    changed = False
    normalized = []
    for act in acts:
        target = dict(act.get("target") or {}) if isinstance(act.get("target"), dict) else {}
        operation = str(act.get("operation") or "").strip()
        resource = str(target.get("resource") or "").strip().casefold()

        # Un Act sin schedule no se toca: podría ser otra clase de mutación.
        if not _agent_v2_v111_has_schedule_change(act):
            normalized.append(act)
            continue

        if resource == "quincho" and operation == "reschedule_booking":
            act["operation"] = "modify_resource"
            changed = True
        elif resource in {"court", "cancha", "reservation", "reserva"} and operation == "modify_resource":
            act["operation"] = "reschedule_booking"
            target["resource"] = "reservation"
            act["target"] = target
            changed = True

        normalized.append(act)

    if not changed:
        return clean

    frame["acts"] = normalized
    if len(normalized) == 1:
        frame.setdefault("intent", {})["operation"] = normalized[0].get("operation")
    clean["semantic_frame"] = frame
    print(
        "   🔀 [AgentV2 V112 RESOURCE OPERATION] "
        f"ops={[act.get('operation') for act in normalized]}"
    )
    return clean


_agent_v2_build_execution_contract_v111_base = _agent_v2_build_execution_contract


def _agent_v2_build_execution_contract(
    perception: Dict[str, Any],
    world: Dict,
) -> Dict[str, Any]:
    """
    ExecutionContract con foco de reserva verificado.

    Si Effect Verifier autorizó una mutación de una reserva existente y el
    SemanticFrame no trajo reservation_id, el contrato puede limitar SU vista
    de `reservas_reales` al booking enfocado. Así reutiliza la autoridad segura
    ya existente de "única reserva" sin ocultar reservas al Planner/Tools reales.
    """
    prepared = _agent_v2_v111_canonicalize_resource_schedule_acts(perception or {})
    frame = _agent_v2_semantic_frame(prepared)
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    verification = (
        prepared.get("semantic_effect_verification")
        if isinstance(prepared.get("semantic_effect_verification"), dict)
        else {}
    )
    authorized_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }

    existing_ops = {
        "reschedule_booking", "modify_resource", "add_resource", "remove_resource",
    }
    needs_focus = []
    has_create_booking = any(
        str(act.get("operation") or "") == "create_booking"
        for act in acts
    )
    for act in acts:
        op = str(act.get("operation") or "")
        act_id = str(act.get("act_id") or "").strip()
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        rid = str(target.get("reservation_id") or "").strip()
        if op not in existing_ops or rid or act_id not in authorized_ids:
            continue
        # add_resource sin reservation_id puede ser el addon de una reserva NUEVA.
        if op == "add_resource" and has_create_booking:
            continue
        needs_focus.append(act)

    if needs_focus:
        focus = _agent_v2_v111_verified_reservation_focus(world or {}, prepared)
        if focus:
            scoped_world = dict(world or {})
            scoped_facts = dict(scoped_world.get("facts") or {})
            scoped_facts["reservas_reales"] = [dict(focus)]
            scoped_world["facts"] = scoped_facts
            contract = _agent_v2_build_execution_contract_v111_base(
                prepared, scoped_world
            )
            bound_ids = {
                str(((act.get("target") or {}).get("reservation_id")) or "")
                for act in (contract.get("acts") or [])
                if isinstance(act, dict)
            }
            focus_id = str(_agent_v2_reservation_id(focus) or "")
            if contract.get("authoritative") and focus_id in bound_ids:
                contract = dict(contract)
                contract["reservation_focus_authority"] = {
                    "reservation_id": focus_id,
                    "source": "verified_conversation_focus",
                }
                print(
                    "   🔐 [AgentV2 V112 FOCUSED WRITE AUTHORITY] "
                    f"reservation_id={focus_id} "
                    f"ops={[act.get('operation') for act in contract.get('acts') or []]}"
                )
                return contract

    return _agent_v2_build_execution_contract_v111_base(prepared, world)


# Proyección final de Perception. El ExecutionContract ya puede resolver el
# booking enfocado; ahora hacemos visible ESA MISMA identidad verificada a las
# capas posteriores (Planner/Tool target resolution). Esto es especialmente
# importante al actualizar un proceso que ya tenía varias reservas creadas antes
# de V112: last_payment/last_reprogrammed pueden recuperar el foco sin pedir IDs.
_percibir_turno_agent_v2_v112_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v112_base(
        mensaje, world, image_path, learning_policy
    )
    clean = _agent_v2_v111_canonicalize_resource_schedule_acts(
        perception or {}
    )

    frame = _agent_v2_semantic_frame(clean)
    operations = {
        str(act.get("operation") or "").strip()
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
    }
    existing_resource_write = bool(
        operations.intersection({
            "reschedule_booking", "modify_resource",
            "add_resource", "remove_resource",
        })
    )

    if existing_resource_write:
        contract = _agent_v2_build_execution_contract(clean, world or {})
        clean["execution_contract"] = contract

        focus_meta = (
            contract.get("reservation_focus_authority")
            if isinstance(contract, dict)
            and isinstance(contract.get("reservation_focus_authority"), dict)
            else {}
        )
        focus_id = str(focus_meta.get("reservation_id") or "").strip()
        if focus_id:
            clean["reservation_target"] = {
                "reservation_id": focus_id,
                "source": "verified_conversation_focus",
            }

        # Una vez que el contrato es autoritativo, proyectamos el act tipado del
        # quincho a resource_mutation. No se vuelve a interpretar el mensaje.
        if contract.get("authoritative"):
            mutation = _agent_v2_resource_mutation_from_semantics(
                clean, world or {}
            )
            if mutation and mutation.get("resource") == "quincho":
                clean["resource_mutation"] = mutation
                if mutation.get("operation") == "update_schedule":
                    schedule = dict(mutation.get("fields") or {})
                    if schedule:
                        schedule["explicit"] = True
                        schedule["source"] = "verified_execution_contract"
                        clean["quincho_schedule_update"] = schedule
                        clean["explicit_quincho_request"] = True
                        actions = [
                            str(x) for x in (clean.get("explicit_actions") or [])
                            if str(x) not in {
                                "crear_reserva", "reprogramar_reserva",
                                "reprogramar_turno", "cambiar_turno",
                                "pagar_senia",
                            }
                        ]
                        if "agregar_quincho" not in actions:
                            actions.append("agregar_quincho")
                        clean["explicit_actions"] = actions
                elif mutation.get("operation") == "remove":
                    clean["explicit_quincho_request"] = False
                    actions = [
                        str(x) for x in (clean.get("explicit_actions") or [])
                        if str(x) not in {"agregar_quincho", "reservar_quincho"}
                    ]
                    if "quitar_quincho" not in actions:
                        actions.append("quitar_quincho")
                    clean["explicit_actions"] = actions

        print(
            "   🧠 [AgentV2 V112 RESOURCE WRITE FRAME] "
            f"ops={sorted(operations)} "
            f"focus={focus_id or '-'} "
            f"authoritative={bool(contract.get('authoritative'))}"
        )

    return clean


# Mantener el foco después de cada write verificado. Las capas anteriores
# limpiaban reservation_target tras pago/reprogramación y obligaban al agente a
# tratar una conversación natural como si no supiera de qué turno se hablaba.
_agent_v2_reduce_v111_base = agent_v2_reduce


def agent_v2_reduce(telefono: str, event: Dict[str, Any]) -> Dict[str, Any]:
    state = _agent_v2_reduce_v111_base(telefono, event)
    evt = dict(event or {})
    etype = str(evt.get("type") or "").upper()
    payload = evt.get("payload") if isinstance(evt.get("payload"), dict) else {}

    focus_events = {
        "RESERVATION_CREATED",
        "RESERVATION_REPROGRAMMED",
        "PAYMENT_CONFIRMED",
        "PAYMENT_PARTIAL",
        "PAYMENT_METHOD_SELECTED",
        "QUINCHO_CHANGED",
    }
    if etype not in focus_events:
        return state

    rid = _agent_v2_v111_extract_reservation_id(payload)
    if not rid:
        # QUINCHO_CHANGED(remove) legacy puede no transportar fila. En ese caso
        # conservar el foco que ya existía, nunca fabricar uno.
        return state

    current = get_conversation_state(telefono)
    av2 = _agent_v2_state(current)
    target = {
        "reservation_id": rid,
        "source": "verified_write_focus",
        "updated_at": datetime.datetime.now(TIMEZONE).isoformat(),
    }
    row = None
    try:
        rows = calendario.listar_reservas() or []
        row = _agent_v2_find_reservation_by_id(rows, rid)
    except Exception:
        row = None
    if isinstance(row, dict):
        target.update({
            "dia": row.get("fecha") or row.get("dia"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha"),
        })

    av2.setdefault("desires", {})["reservation_target"] = target
    update_conversation_state(telefono, agent_v2=av2)
    print(
        "   🎯 [AgentV2 V112 FOCUS PERSIST] "
        f"event={etype} reservation_id={rid}"
    )
    return get_conversation_state(telefono)


# Un cambio de horario de quincho sobre un turno firme debe conservar exactamente
# el mismo settlement que una reprogramación de cancha. Reutilizamos el renderer
# financiero verificado en lugar de volver a pedir una seña ya comprometida.
_build_agent_v2_quincho_change_message_v111_base = build_agent_v2_quincho_change_message


def build_agent_v2_quincho_change_message(
    observation: Dict[str, Any],
) -> str:
    data = (observation or {}).get("data") or {}
    row = dict(data.get("reserva") or {})
    if not row or not _agent_v2_reprogrammed_booking_is_firm(row):
        return _build_agent_v2_quincho_change_message_v111_base(observation)

    rid = str(row.get("reservation_id") or _agent_v2_reservation_id(row) or "").strip()
    synthetic = {
        "tool": "reprogramar_reserva",
        "ok": True,
        "status": "success",
        "data": {
            "reservation_id": rid,
            "dia": row.get("fecha") or row.get("dia"),
            "hora": row.get("hora"),
            "cancha": row.get("cancha"),
        },
        "verified_facts": {},
    }
    rendered = build_agent_v2_reprogrammed_reservation_message(synthetic).strip()
    if not rendered:
        return _build_agent_v2_quincho_change_message_v111_base(observation)

    # Propagar FactPack financiero al observation real para Money Guard.
    if isinstance(observation, dict):
        observation.setdefault("data", {}).update(dict(synthetic.get("data") or {}))
        observation.setdefault("verified_facts", {}).update(
            dict(synthetic.get("verified_facts") or {})
        )

    first = "✅ Listo, reprogramé tu turno."
    replacement = "✅ Listo, actualicé el horario del quincho."
    if rendered.startswith(first):
        rendered = replacement + rendered[len(first):]

    print(
        "   🔥 [AgentV2 V112 QUINCHO RESCHEDULE TEMPLATE] "
        f"reservation_id={rid} settlement_preserved=True"
    )
    return rendered


# Invariantes V112: prueban estructura/identidad, no frases particulares.
_run_agent_v2_invariant_evals_v111_base = run_agent_v2_invariant_evals


