# Planner V113 — add_resource sobre reserva existente
# ---------------------------------------------------------------------------
_agent_v2_plan_current_resource_mutation_v113_base = _agent_v2_plan_current_resource_mutation


def _agent_v2_plan_current_resource_mutation(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    progress: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    mutation = (
        (perception or {}).get("resource_mutation")
        if isinstance((perception or {}).get("resource_mutation"), dict)
        else {}
    )
    if not (
        mutation.get("resource") == "quincho"
        and mutation.get("operation") == "add"
        and mutation.get("scope") == "existing_reservation"
        and mutation.get("write_intent") is True
    ):
        return _agent_v2_plan_current_resource_mutation_v113_base(
            world, perception, goals, observations, progress
        )

    real_reservations = list(
        (((world or {}).get("facts") or {}).get("reservas_reales") or [])
    )
    if not real_reservations:
        return {
            "steps": [{
                "tool": "solicitar_dato",
                "args": {
                    "campo": "reserva",
                    "opciones": [],
                    "motivo": "no encontré una reserva activa a la que agregar el quincho",
                },
                "reason": "add_resource requiere una reserva real existente",
                "replan_after": False,
            }],
            "done_if": "reserva existente identificada",
            "reason": "existing reservation required for resource addition",
            "goal_progress": progress,
        }

    explicit_id = str(mutation.get("reservation_id") or "").strip()
    target = _agent_v2_resolve_reservation_target(
        world or {}, perception or {}, explicit_id or None
    )
    if not target and len(real_reservations) == 1:
        target = _agent_v2_enrich_reservation(real_reservations[0])

    if not target:
        return {
            "steps": [{
                "tool": "solicitar_dato",
                "args": {
                    "campo": "reserva_especifica",
                    "opciones": _agent_v2_reservation_options(real_reservations),
                    "motivo": "hay varias reservas activas y necesito saber a cuál agregar el quincho",
                },
                "reason": "add_resource necesita reservation_id inequívoco",
                "replan_after": False,
            }],
            "done_if": "reservation_id validado",
            "reason": "resource addition reservation targeting",
            "goal_progress": progress,
        }

    qnames: List[str] = []
    for item in (QUINCHOS or []):
        if isinstance(item, dict):
            name = str(item.get("name") or item.get("nombre") or "").strip()
        else:
            name = str(item or "").strip()
        if name:
            qnames.append(name)

    entities = (perception or {}).get("entities") if isinstance((perception or {}).get("entities"), dict) else {}
    qname = normalizar_nombre_quincho(
        entities.get("quincho")
        or (qnames[0] if len(qnames) == 1 else "")
    )
    if not qname:
        return {
            "steps": [{
                "tool": "solicitar_dato",
                "args": {
                    "campo": "quincho",
                    "opciones": qnames,
                    "motivo": "hay más de un quincho y necesito saber cuál querés agregar",
                },
                "reason": "resource addition necesita identificar el quincho",
                "replan_after": False,
            }],
            "done_if": "quincho identificado",
            "reason": "resource addition missing subresource",
            "goal_progress": progress,
        }

    fields = mutation.get("fields") if isinstance(mutation.get("fields"), dict) else {}
    reservation_id = str(
        target.get("reservation_id") or _agent_v2_reservation_id(target) or ""
    ).strip()

    print(
        "   🔥 [AgentV2 V113 ADD RESOURCE PLAN] "
        f"reservation_id={reservation_id} quincho={qname} "
        f"hora_inicio={fields.get('hora_inicio') or 'tool_default'}"
    )
    return {
        "steps": [{
            "tool": "agregar_quincho",
            "args": {
                "reservation_id": reservation_id,
                "quincho": qname,
                "hora_inicio": fields.get("hora_inicio"),
                "duracion_horas": fields.get("duracion_horas"),
            },
            "reason": (
                "ExecutionContract autorizó add_resource quincho sobre una "
                "reserva real enfocada; la tool valida disponibilidad y recalcula "
                "total/seña/saldo antes de persistir"
            ),
            "replan_after": False,
        }],
        "done_if": "quincho agregado o disponibilidad rechazada por la tool",
        "reason": "verified existing reservation resource addition",
        "goal_progress": progress,
    }


