# ============================================================================
# AGENT V2 V114 — UNIFIED EXISTING BOOKING MUTATION + FRESH HOLD LEASE
# 21/09/2026
#
# Objetivo:
#   - reprogramar fecha y/o hora de una reserva existente;
#   - agregar / quitar / reprogramar quincho;
#   - mantener una única reserva objetivo verificada;
#   - si el booking sigue pendiente de seña, CADA mutación exitosa crea un hold
#     nuevo de PENDING_DEPOSIT_HOLD_MINUTES desde el momento de la modificación;
#   - si el booking ya está firme/confirmado, jamás crear un hold nuevo.
#
# No interpreta frases con regex. La autoridad nace de:
#   SemanticFrame -> Semantic Effect Verifier -> semantic_freeze -> WORLD_STATE.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v114"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_existing_booking_mutation_hold_v114"

_AGENT_V2_V114_EXISTING_MUTATION_OPERATIONS = {
    "reschedule_booking",
    "modify_resource",
    "add_resource",
    "remove_resource",
}
_AGENT_V2_V114_MUTATION_TOOLS = {
    "reprogramar_reserva",
    "agregar_quincho",
    "quitar_quincho",
}


def _agent_v2_v114_real_reservation_map(world: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    result: Dict[str, Dict[str, Any]] = {}
    for raw in (((world or {}).get("facts") or {}).get("reservas_reales") or []):
        if not isinstance(raw, dict):
            continue
        row = dict(raw)
        rid = str(_agent_v2_reservation_id(row) or row.get("reservation_id") or "").strip()
        if rid:
            result[rid] = row
    return result


# ---------------------------------------------------------------------------
# ContextAuthorization V114
# ---------------------------------------------------------------------------
# V113 abrió references_previous sólo para quincho. V114 generaliza exactamente
# la misma frontera de seguridad a TODAS las mutaciones explícitas soportadas de
# una reserva existente: reprogramar fecha/hora y add/modify/remove_resource.
_agent_v2_context_authorization_v114_base = _agent_v2_context_authorization


def _agent_v2_context_authorization(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    base = dict(_agent_v2_context_authorization_v114_base(perception, world) or {})
    if base.get("authorized"):
        return base

    frame = _agent_v2_semantic_frame(perception or {})
    relation = _agent_v2_semantic_context_relation(frame)
    if str(relation.get("type") or "") != "references_previous":
        return base

    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    write_acts = [
        act for act in acts
        if str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
        or bool((act.get("commitment") or {}).get("wants_write"))
    ]
    if not write_acts:
        return base

    # La autorización lingüística del WRITE debe venir del Effect Verifier y de
    # evidencia explícita del turno actual. No se acepta memoria como sustituto.
    verified = _agent_v2_v113_verified_write_auth_by_id(perception or {})
    if not verified:
        return base

    for act in write_acts:
        operation = str(act.get("operation") or "").strip()
        act_id = str(act.get("act_id") or "").strip()
        if operation not in _AGENT_V2_V114_EXISTING_MUTATION_OPERATIONS or act_id not in verified:
            return base

    focus = _agent_v2_v111_verified_reservation_focus(world or {}, perception or {})
    if not focus:
        return base
    focus_id = str(_agent_v2_reservation_id(focus) or focus.get("reservation_id") or "").strip()
    if not focus_id:
        return base

    real_map = _agent_v2_v114_real_reservation_map(world or {})
    if focus_id not in real_map:
        return base

    # Si el SemanticFrame ya transporta un ID, nunca puede saltar a otra reserva.
    for act in write_acts:
        target = act.get("target") if isinstance(act.get("target"), dict) else {}
        explicit_id = str(target.get("reservation_id") or "").strip()
        if explicit_id and explicit_id != focus_id:
            return {
                **base,
                "authorized": False,
                "reason": "v114_existing_booking_focus_mismatch",
            }

    print(
        "   🔐 [AgentV2 V114 CONTEXT WRITE AUTHORITY] "
        f"reservation_id={focus_id} "
        f"ops={[str(act.get('operation') or '') for act in write_acts]}"
    )
    return {
        "relation": "references_previous",
        "authorized": True,
        "question_id": None,
        "reference_id": focus_id,
        "scope_id": relation.get("scope_id"),
        "allowed_fields": [
            "context.reference", "target", "temporal", "quantity", "changes",
        ],
        "allowed_sources": [
            "current_user_turn", "previous_user_turn", "world_fact",
        ],
        "bindings": [{
            "reference_id": focus_id,
            "authority": "semantic_effect_verifier+verified_reservation_focus_v114",
        }],
        "reason": "v114_verified_existing_booking_mutation",
    }


# ---------------------------------------------------------------------------
# Semantic freeze recovery V114
# ---------------------------------------------------------------------------
def _agent_v2_v114_restore_frozen_mutation_authority(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Un segundo Effect Verifier no puede borrar un WRITE que YA quedó congelado
    como verified en semantic_freeze durante el mismo turno.

    Esto no inventa autoridad: semantic_freeze sólo existe cuando el contrato
    anterior era authoritative/frozen y TODOS sus write_act_ids estaban dentro
    de write_authorizations(status=verified).
    """
    clean = dict(perception or {})
    freeze = _agent_v2_v87_freeze(clean)
    if (
        not freeze
        or freeze.get("reason") != "authoritative_execution_contract_with_verified_writes"
    ):
        return clean

    frozen_ops = {
        str(op or "").strip()
        for op in (freeze.get("operations") or [])
        if str(op or "").strip()
    }
    mutation_ops = frozen_ops.intersection(_AGENT_V2_V114_EXISTING_MUTATION_OPERATIONS)
    if not mutation_ops:
        return clean

    # No usar esta recuperación para un booking nuevo que casualmente también
    # contiene add_resource. V114 sólo gobierna reservas ya existentes.
    if "create_booking" in frozen_ops:
        return clean

    current_contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    current_ops = {
        str(act.get("operation") or "")
        for act in (current_contract.get("acts") or [])
        if isinstance(act, dict)
    }
    current_allowed = set(current_contract.get("allowed_tools") or [])
    expected_allowed = set()
    for op in mutation_ops:
        expected_allowed.update(AGENT_V2_OPERATION_TOOLS.get(op, set()))

    # Si nada fue degradado, no tocar el contrato maduro.
    if (
        current_contract.get("authoritative")
        and mutation_ops.issubset(current_ops)
        and expected_allowed.issubset(current_allowed)
    ):
        return clean

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    frame_acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    frozen_write_ids = {
        str(value or "").strip()
        for value in (freeze.get("write_act_ids") or [])
        if str(value or "").strip()
    }
    target_map = {
        str(k): str(v)
        for k, v in dict(freeze.get("targets") or {}).items()
        if str(k or "").strip() and str(v or "").strip()
    }
    real_map = _agent_v2_v114_real_reservation_map(world or {})

    restored_acts: List[Dict[str, Any]] = []
    restored_write_ids = set()
    restored_ids = set()

    for original in frame_acts:
        act = dict(original)
        operation = str(act.get("operation") or "").strip()
        act_id = str(act.get("act_id") or "").strip()
        if operation not in mutation_ops or act_id not in frozen_write_ids:
            continue

        target = dict(act.get("target") or {}) if isinstance(act.get("target"), dict) else {}
        rid = str(
            target.get("reservation_id")
            or target_map.get(act_id)
            or target_map.get(operation)
            or ""
        ).strip()
        row = real_map.get(rid)
        if not rid or not row:
            # Fail closed: no reconstruir una mutación si el target real desapareció.
            return clean

        target.update({
            "reservation_id": rid,
            "source": "semantic_freeze_verified_world_target",
        })
        if operation == "reschedule_booking":
            target.setdefault("resource", "reservation")
        act["target"] = target

        # Reprogramar sólo fecha conserva la hora actual; reprogramar sólo hora
        # conserva la fecha actual. Al menos UNA dimensión debe haber venido del
        # act verificado original; de lo contrario no convertimos un deseo vago en WRITE.
        if operation == "reschedule_booking":
            temporal = dict(act.get("temporal") or {}) if isinstance(act.get("temporal"), dict) else {}
            supplied_day = bool(str(temporal.get("day") or "").strip())
            supplied_hour = hora_es_valida(normalizar_hora_detectada(temporal.get("start")))
            if not supplied_day and not supplied_hour:
                return clean
            if not supplied_day:
                temporal["day"] = row.get("fecha") or row.get("dia")
            if not supplied_hour:
                temporal["start"] = normalizar_hora_detectada(row.get("hora"))
            act["temporal"] = temporal

        provenance = [dict(x) for x in (act.get("provenance") or []) if isinstance(x, dict)]
        if not any(
            str(x.get("field") or "") == "target.reservation_id"
            and str(x.get("reference_id") or "") == rid
            for x in provenance
        ):
            provenance.append({
                "field": "target.reservation_id",
                "source": "world_fact",
                "evidence": f"semantic_freeze_target:{rid}",
                "reference_id": rid,
                "question_id": None,
                "option_id": None,
            })
        act["provenance"] = provenance
        restored_acts.append(act)
        restored_write_ids.add(act_id)
        restored_ids.add(rid)

    if not restored_acts or not frozen_write_ids.issubset(restored_write_ids):
        return clean

    restored_frame = dict(frame)
    restored_frame["acts"] = restored_acts
    if len(restored_acts) == 1:
        restored_frame["intent"] = {
            "domain": "booking",
            "operation": restored_acts[0].get("operation"),
        }
    restored_frame["source"] = restored_frame.get("source") or "ai"
    restored_frame["schema_valid"] = True

    # semantic_freeze certifica que estos mismos act_ids ya pasaron Effect Verifier
    # en ESTE turno. Reinyectamos esa prueba para que el constructor final no la
    # exija por segunda vez y no convierta un verified WRITE en ops=[].
    restored_verification = {
        "status": "verified",
        "mode": "independent_effect_verifier",
        "recovered_from": "semantic_freeze_v114",
        "write_authorizations": [
            {
                "act_id": act_id,
                "authorized": True,
                "evidence_type": "current_user_turn",
                "evidence": f"verified_semantic_freeze:{freeze.get('contract_id') or act_id}",
                "question_id": None,
                "option_id": None,
            }
            for act_id in sorted(restored_write_ids)
        ],
    }

    prepared = dict(clean)
    prepared["semantic_frame"] = restored_frame
    prepared["semantic_effect_verification"] = restored_verification
    prepared.pop("execution_contract", None)
    candidate = _agent_v2_build_execution_contract(prepared, world or {})
    candidate_ops = {
        str(act.get("operation") or "")
        for act in (candidate.get("acts") or [])
        if isinstance(act, dict)
    }
    if not candidate.get("authoritative") or not mutation_ops.issubset(candidate_ops):
        print(
            "   🚫 [AgentV2 V114 FROZEN WRITE RESTORE] "
            f"rechazado candidate_ops={sorted(candidate_ops)} mutation_ops={sorted(mutation_ops)}"
        )
        return clean

    clean["semantic_frame"] = restored_frame
    clean["semantic_effect_verification"] = restored_verification
    clean["execution_contract"] = candidate
    clean.pop("semantic_clarification_required", None)
    clean.pop("semantic_clarification", None)

    if len(restored_ids) == 1:
        rid = next(iter(restored_ids))
        clean["reservation_target"] = {
            "reservation_id": rid,
            "source": "semantic_freeze_verified_world_target",
        }

    # Resource mutation es una proyección del contrato, no una clasificación de texto.
    resource_mutation = _agent_v2_resource_mutation_from_semantics(clean, world or {})
    if resource_mutation:
        clean["resource_mutation"] = resource_mutation

    clean = _agent_v2_v100_attach_desired_state_and_task_graph(clean, world or {})
    print(
        "   ♻️ [AgentV2 V114 FROZEN WRITE RESTORE] "
        f"ops={sorted(candidate_ops)} reservation_ids={sorted(restored_ids)} "
        f"allowed_tools={candidate.get('allowed_tools') or []}"
    )
    return clean


_percibir_turno_agent_v2_v114_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    clean = await _percibir_turno_agent_v2_v114_base(
        mensaje, world, image_path, learning_policy
    )
    clean = _agent_v2_v114_restore_frozen_mutation_authority(clean, world or {})

    # Reproyectar explicit_actions después de una restauración para consumidores
    # legacy. La fuente sigue siendo ExecutionContract authoritative.
    contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    if contract.get("authoritative"):
        operations = {
            str(act.get("operation") or "")
            for act in (contract.get("acts") or [])
            if isinstance(act, dict)
        }
        actions = [str(x) for x in (clean.get("explicit_actions") or [])]
        if "reschedule_booking" in operations and "reprogramar_reserva" not in actions:
            actions.append("reprogramar_reserva")
        mutation = clean.get("resource_mutation") if isinstance(clean.get("resource_mutation"), dict) else {}
        if mutation.get("resource") == "quincho":
            desired = "quitar_quincho" if mutation.get("operation") == "remove" else "agregar_quincho"
            opposite = "agregar_quincho" if desired == "quitar_quincho" else "quitar_quincho"
            actions = [x for x in actions if x != opposite]
            if desired not in actions:
                actions.append(desired)
        clean["explicit_actions"] = actions
    return clean


# ---------------------------------------------------------------------------
# Planner V114: postcondition de seguridad del TaskGraph
# ---------------------------------------------------------------------------
_planificar_agent_v2_v114_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    plan = await _planificar_agent_v2_v114_base(
        world, perception, goals, observations, offline_mode, learning_policy
    )
    steps = [step for step in ((plan or {}).get("steps") or []) if isinstance(step, dict)]
    if steps:
        return plan

    contract = (perception or {}).get("execution_contract") if isinstance((perception or {}).get("execution_contract"), dict) else {}
    if not contract.get("authoritative"):
        return plan

    operations = {
        str(act.get("operation") or "")
        for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    }
    if not operations.intersection(_AGENT_V2_V114_EXISTING_MUTATION_OPERATIONS):
        return plan

    progress = _agent_v2_goal_progress(goals or {}, observations or [])
    direct = _agent_v2_plan_current_resource_mutation(
        world or {}, perception or {}, goals or {}, observations or [], progress
    )
    if not isinstance(direct, dict):
        return plan

    allowed = set(contract.get("allowed_tools") or [])
    direct_steps = [step for step in (direct.get("steps") or []) if isinstance(step, dict)]
    if not direct_steps or any(
        str(step.get("tool") or "") not in allowed and str(step.get("tool") or "") != "solicitar_dato"
        for step in direct_steps
    ):
        return plan

    print(
        "   ♻️ [AgentV2 V114 TASKGRAPH RECOVERY] "
        f"empty_plan → tools={[step.get('tool') for step in direct_steps]}"
    )
    return direct


# ---------------------------------------------------------------------------
# Unified HOLD lifecycle after mutation
# ---------------------------------------------------------------------------
def _agent_v2_v114_apply_mutation_hold_policy(
    before_row: Optional[Dict[str, Any]],
    after_row: Optional[Dict[str, Any]],
    *,
    reason: str,
) -> Dict[str, Any]:
    before = dict(before_row or {})
    after = dict(after_row or {})
    if not after:
        return {"hold_restarted": False, "reason": "missing_final_reservation"}

    state = _json_read(PROACTIVE_STATE_FILE, {"sent": {}})
    if before:
        _clear_pending_hold_tracking(before, state=state, persist=False)
        _discard_stale_hold_expiration_notifications(state, before)
    _clear_pending_hold_tracking(after, state=state, persist=False)
    _discard_stale_hold_expiration_notifications(state, after)

    now = datetime.datetime.now(TIMEZONE)
    rid = str(after.get("reservation_id") or _agent_v2_reservation_id(after) or "").strip()

    if _pending_hold_row_is_temporary(after):
        key = _pending_hold_key(after)
        expires_at = now + datetime.timedelta(minutes=PENDING_DEPOSIT_HOLD_MINUTES)
        state.setdefault("pending_deposit_seen_at", {})[key] = now.isoformat()
        state.setdefault("pending_deposit_holds", {})[key] = {
            "started_at": now.isoformat(),
            "expires_at": expires_at.isoformat(),
            "reserva": {
                "reservation_id": rid,
                "telefono": after.get("telefono"),
                "nombre": after.get("nombre"),
                "fecha": after.get("fecha"),
                "hora": after.get("hora"),
                "cancha": after.get("cancha"),
                "duracion_horas": after.get("duracion_horas"),
            },
        }
        state["updated_at"] = now.isoformat()
        _json_write(PROACTIVE_STATE_FILE, state)
        print(
            "   🔄 [HOLD LEASE RESET V114] "
            f"reason={reason} reservation_id={rid or '-'} fresh={PENDING_DEPOSIT_HOLD_MINUTES}m "
            f"slot={after.get('fecha')} {after.get('hora')} {after.get('cancha')}"
        )
        return {
            "hold_restarted": True,
            "hold_minutes": PENDING_DEPOSIT_HOLD_MINUTES,
            "hold_started_at": now.isoformat(),
            "hold_expires_at": expires_at.isoformat(),
            "reservation_id": rid,
        }

    # Firme/confirmada/parcial con dinero registrado: no lease descartable.
    state["updated_at"] = now.isoformat()
    _json_write(PROACTIVE_STATE_FILE, state)
    print(
        "   ✅ [HOLD POLICY V114] "
        f"reason={reason} reservation_id={rid or '-'} firm=True → sin hold nuevo"
    )
    return {
        "hold_restarted": False,
        "hold_minutes": 0,
        "hold_started_at": None,
        "hold_expires_at": None,
        "reservation_id": rid,
    }


def _agent_v2_v114_mutation_before_snapshot(
    tool: str,
    args: Dict[str, Any],
    world: Dict[str, Any],
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    if tool not in _AGENT_V2_V114_MUTATION_TOOLS:
        return {}
    rid = str((args or {}).get("reservation_id") or "").strip()
    target = _agent_v2_resolve_reservation_target(
        world or {}, perception or {}, rid or None
    )
    if isinstance(target, dict) and target:
        return dict(target)
    rows = [
        dict(row) for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
    ]
    if rid:
        found = _agent_v2_find_reservation_by_id(rows, rid)
        return dict(found or {})
    if len(rows) == 1:
        return dict(rows[0])
    return {}


def _agent_v2_v114_final_reservation_from_observation(
    observation: Dict[str, Any],
    fallback_id: str = "",
) -> Dict[str, Any]:
    data = (observation or {}).get("data") if isinstance((observation or {}).get("data"), dict) else {}
    for key in ("reserva_verificada", "reserva", "final_reservation_state"):
        row = data.get(key)
        if isinstance(row, dict) and row:
            return dict(row)
    rid = str(
        data.get("reservation_id")
        or fallback_id
        or ""
    ).strip()
    if not rid:
        return {}
    try:
        rows = calendario.listar_reservas() or []
    except Exception:
        rows = []
    found = _agent_v2_find_reservation_by_id(rows, rid)
    return dict(found or {})


_ejecutar_tool_agent_v2_v114_base = ejecutar_tool_agent_v2


async def ejecutar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    telefono: str,
    prospecto: Dict,
    user_messages: List[str],
    page=None,
    image_path: str = "",
) -> Dict[str, Any]:
    before = _agent_v2_v114_mutation_before_snapshot(
        tool, args or {}, world or {}, perception or {}
    )
    observation = await _ejecutar_tool_agent_v2_v114_base(
        tool, args, world, perception, goals, telefono, prospecto,
        user_messages, page=page, image_path=image_path,
    )

    if tool not in _AGENT_V2_V114_MUTATION_TOOLS or not isinstance(observation, dict) or not observation.get("ok"):
        return observation

    fallback_id = str(
        ((observation.get("data") or {}).get("reservation_id"))
        or (args or {}).get("reservation_id")
        or before.get("reservation_id")
        or _agent_v2_reservation_id(before)
        or ""
    ).strip()
    after = _agent_v2_v114_final_reservation_from_observation(observation, fallback_id)
    if not after:
        # Fail safe: el write ya ocurrió, pero si no podemos demostrar estado final
        # no tocamos el lease ni fabricamos una confirmación financiera.
        print(
            "   ⚠️ [HOLD POLICY V114] write exitoso sin fila final verificable; "
            f"tool={tool} reservation_id={fallback_id or '-'}"
        )
        return observation

    hold = _agent_v2_v114_apply_mutation_hold_policy(
        before, after, reason=tool
    )
    enriched = dict(observation)
    data = dict(enriched.get("data") or {})
    data.update({
        "reservation_id": str(after.get("reservation_id") or fallback_id or ""),
        "reserva": after,
        "reserva_verificada": after,
        "hold_restarted": bool(hold.get("hold_restarted")),
        "hold_minutes": hold.get("hold_minutes"),
        "hold_started_at": hold.get("hold_started_at"),
        "hold_expires_at": hold.get("hold_expires_at"),
        "booking_confirmed": not _pending_hold_row_is_temporary(after),
    })
    enriched["data"] = data
    facts = dict(enriched.get("verified_facts") or {})
    facts["mutation_hold_policy"] = dict(hold)
    facts["final_reservation_state"] = dict(after)
    enriched["verified_facts"] = facts
    return enriched


