_run_agent_v2_invariant_evals_v114_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v114_base()
    results = list(result.get("results") or [])

    pending = {
        "reservation_id": "80",
        "fecha": "21/09/2026",
        "hora": "18:00",
        "cancha": "Cancha 4",
        "estado": str(BOOKING_STATUS_PENDING or "pendiente"),
        "senia_estado": "pendiente",
        "duracion_horas": "1.0",
    }
    world = {
        "message": "offline_eval_fixture",
        "facts": {
            "reservas_reales": [pending],
            "memory_owner": "eval_v114",
            "last_reservation_created": {"reservation_id": "80", "reserva": pending},
        },
        "stored_memory": {
            "desires": {"reservation_target": {"reservation_id": "80"}},
            "pending_decisions": [], "history": [], "scopes": {},
        },
        "desires": {"reservation_target": {"reservation_id": "80"}},
        "pending_decisions": [], "open_questions": [], "history": [],
    }

    add_act = {
        "act_id": "v114_add_q",
        "operation": "add_resource",
        "target": {"resource": "quincho", "reservation_id": "80"},
        "temporal": {}, "quantity": {}, "requested_facts": [], "changes": [],
        "provenance": [{
            "field": "target.resource", "source": "current_user_turn",
            "evidence": "offline_eval_fixture",
        }],
        "commitment": {"wants_write": True, "wants_information": False},
    }
    degraded = {
        "_v100_semantic_frozen": True,
        "semantic_frame": {
            "source": "ai", "schema_valid": True, "turn_type": "command",
            "acts": [add_act],
            "intent": {"domain": "booking", "operation": "add_resource"},
            "context_relation": {
                "type": "references_previous",
                "references_previous_user_turn": True,
                "references_agent_offer": False,
                "answers_pending_question": False,
            },
        },
        "semantic_effect_verification": {
            "status": "verified", "mode": "independent_effect_verifier",
            "write_authorizations": [],
        },
        "semantic_freeze": {
            "active": True,
            "contract_id": "v114_prior_verified_contract",
            "operations": ["add_resource"],
            "write_act_ids": ["v114_add_q"],
            "targets": {"v114_add_q": "80"},
            "write_authority": "semantic_effect_verifier",
            "terminal_fast_path": True,
            "reason": "authoritative_execution_contract_with_verified_writes",
        },
        "execution_contract": {
            "authoritative": False, "acts": [], "allowed_tools": [],
            "clarification_reasons": ["write_not_authorized_by_effect_verifier"],
        },
        "entities": {},
    }
    repaired = _agent_v2_v114_restore_frozen_mutation_authority(degraded, world)
    repaired_contract = repaired.get("execution_contract") or {}
    results.append({
        "name": "v114_second_verifier_cannot_erase_verified_add_resource",
        "ok": bool(
            repaired_contract.get("authoritative")
            and "agregar_quincho" in (repaired_contract.get("allowed_tools") or [])
            and any(
                isinstance(act, dict)
                and act.get("operation") == "add_resource"
                and str((act.get("target") or {}).get("reservation_id") or "") == "80"
                for act in (repaired_contract.get("acts") or [])
            )
        ),
    })

    # Date-only reprogram must preserve current hour structurally.
    reschedule_act = {
        "act_id": "v114_move_day",
        "operation": "reschedule_booking",
        "target": {"resource": "reservation", "reservation_id": "80"},
        "temporal": {"day": "Martes 22/09"},
        "quantity": {}, "requested_facts": [], "changes": [],
        "provenance": [{
            "field": "temporal.day", "source": "current_user_turn",
            "evidence": "offline_eval_fixture",
        }],
        "commitment": {"wants_write": True, "wants_information": False},
    }
    degraded_move = {
        **degraded,
        "semantic_frame": {
            **dict(degraded.get("semantic_frame") or {}),
            "acts": [reschedule_act],
            "intent": {"domain": "booking", "operation": "reschedule_booking"},
        },
        "semantic_freeze": {
            **dict(degraded.get("semantic_freeze") or {}),
            "operations": ["reschedule_booking"],
            "write_act_ids": ["v114_move_day"],
            "targets": {"v114_move_day": "80"},
        },
    }
    repaired_move = _agent_v2_v114_restore_frozen_mutation_authority(degraded_move, world)
    move_acts = ((repaired_move.get("execution_contract") or {}).get("acts") or [])
    move_act = next((a for a in move_acts if isinstance(a, dict) and a.get("operation") == "reschedule_booking"), {})
    results.append({
        "name": "v114_date_only_reschedule_preserves_existing_hour",
        "ok": bool(
            normalizar_hora_detectada((move_act.get("temporal") or {}).get("start")) == "18:00"
            and str((move_act.get("target") or {}).get("reservation_id") or "") == "80"
            and "reprogramar_reserva" in ((repaired_move.get("execution_contract") or {}).get("allowed_tools") or [])
        ),
    })

    # Policy invariant independent of language: only pending rows are temporary.
    firm = dict(pending)
    firm["estado"] = str(BOOKING_STATUS_CONFIRMED or BOOKING_STATUS_RESERVED or "confirmado")
    firm["senia_estado"] = "pagada"
    results.append({
        "name": "v114_hold_policy_pending_vs_firm",
        "ok": bool(
            _pending_hold_row_is_temporary(pending)
            and not _pending_hold_row_is_temporary(firm)
        ),
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# AGENT V2 V115 — AGENTIC QUINCHO DEFAULTS + PENDING VALUE CONTINUITY
# 21/09/2026
#
# Incidentes corregidos:
#   1) "agregame quincho" sobre una reserva existente NO debe preguntar duración.
#      Regla comercial: si el usuario no la especifica, el quincho comienza cuando
#      termina la cancha y dura 1 hora.
#   2) Una respuesta escalar a una pregunta pendiente tipada (ej. "2" cuando el
#      sistema acaba de pedir quincho_duracion_horas) completa ESE campo; no se
#      vuelve a clasificar como una orden independiente sin operación.
#   3) Tras una mutación exitosa sobre una reserva pendiente, la respuesta terminal
#      vuelve a ser el pedido de comprobante + resumen financiero actualizado. El
#      hold ya se reinicia por V114.
#
# No se agregan regex de intención. Los defaults nacen de política de negocio y la
# continuidad escalar sólo se habilita contra un PendingInteraction estructurado.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v115"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_agentic_quincho_defaults_v115"

_AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS = 1.0


def _agent_v2_v115_find_existing_target_row(
    world: Dict[str, Any],
    reservation_id: str = "",
) -> Dict[str, Any]:
    rows = [
        dict(row)
        for row in (((world or {}).get("facts") or {}).get("reservas_reales") or [])
        if isinstance(row, dict)
    ]
    rid = str(reservation_id or "").strip()
    if rid:
        found = _agent_v2_find_reservation_by_id(rows, rid)
        if isinstance(found, dict):
            return dict(found)
    if len(rows) == 1:
        return dict(rows[0])
    return {}


def _agent_v2_v115_default_quincho_fields(
    row: Dict[str, Any],
    fields: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Completa sólo defaults de negocio; nunca interpreta intención."""
    result = dict(fields or {})
    if not row:
        return result

    court_start = normalizar_hora_detectada(row.get("hora"))
    court_duration = normalizar_duracion_horas(
        row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )

    start = normalizar_hora_detectada(result.get("hora_inicio"))
    duration_raw = result.get("duracion_horas")
    duration = (
        normalizar_duracion_horas(
            duration_raw,
            _AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS,
        )
        if duration_raw is not None
        else _AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS
    )

    if not hora_es_valida(start) and hora_es_valida(court_start):
        start = normalizar_hora_detectada(
            hora_fin_bloque(court_start, court_duration)
        )

    if hora_es_valida(start):
        result["hora_inicio"] = start
        result["duracion_horas"] = float(duration)
        result["hora_fin"] = hora_fin_bloque(start, duration)

    return result


# ---------------------------------------------------------------------------
# Semantic projection: add_resource sin horario/duración ya está completo.
# ---------------------------------------------------------------------------
_agent_v2_resource_mutation_from_semantics_v115_base = _agent_v2_resource_mutation_from_semantics


def _agent_v2_resource_mutation_from_semantics(
    perception: Dict[str, Any],
    world: Dict,
) -> Dict[str, Any]:
    mutation = dict(
        _agent_v2_resource_mutation_from_semantics_v115_base(
            perception or {}, world or {}
        )
        or {}
    )
    if not mutation or mutation.get("resource") != "quincho":
        return mutation
    if mutation.get("operation") not in {"add", "update_schedule"}:
        return mutation
    if mutation.get("scope") != "existing_reservation":
        return mutation

    rid = str(mutation.get("reservation_id") or "").strip()
    row = _agent_v2_v115_find_existing_target_row(world or {}, rid)
    if not row:
        return mutation

    fields = _agent_v2_v115_default_quincho_fields(
        row,
        mutation.get("fields") if isinstance(mutation.get("fields"), dict) else {},
    )
    if fields:
        mutation["fields"] = fields
        print(
            "   🔥 [AgentV2 V115 QUINCHO DEFAULTS] "
            f"reservation_id={rid or _agent_v2_reservation_id(row) or '-'} "
            f"inicio={fields.get('hora_inicio')} fin={fields.get('hora_fin')} "
            f"duracion={fields.get('duracion_horas')}h"
        )
    return mutation


# ---------------------------------------------------------------------------
# Planner: nunca convertir el default comercial de 1h en una pregunta al usuario.
# ---------------------------------------------------------------------------
_agent_v2_plan_current_resource_mutation_v115_base = _agent_v2_plan_current_resource_mutation


def _agent_v2_plan_current_resource_mutation(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    progress: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    plan = _agent_v2_plan_current_resource_mutation_v115_base(
        world, perception, goals, observations, progress
    )
    if not isinstance(plan, dict):
        return plan

    mutation = (
        (perception or {}).get("resource_mutation")
        if isinstance((perception or {}).get("resource_mutation"), dict)
        else {}
    )
    if not (
        mutation.get("resource") == "quincho"
        and mutation.get("operation") in {"add", "update_schedule"}
        and mutation.get("scope") == "existing_reservation"
    ):
        return plan

    rid = str(mutation.get("reservation_id") or "").strip()
    row = _agent_v2_v115_find_existing_target_row(world or {}, rid)
    defaults = _agent_v2_v115_default_quincho_fields(row, mutation.get("fields") or {})

    clean = dict(plan)
    clean_steps = []
    changed = False
    for raw in (plan.get("steps") or []):
        if not isinstance(raw, dict):
            continue
        step = dict(raw)
        if step.get("tool") == "agregar_quincho":
            args = dict(step.get("args") or {})
            if not args.get("reservation_id") and rid:
                args["reservation_id"] = rid
            if not hora_es_valida(normalizar_hora_detectada(args.get("hora_inicio"))):
                args["hora_inicio"] = defaults.get("hora_inicio")
            if args.get("duracion_horas") in (None, ""):
                args["duracion_horas"] = defaults.get("duracion_horas") or _AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS
            step["args"] = args
            changed = True
        clean_steps.append(step)
    clean["steps"] = clean_steps

    if changed:
        print(
            "   🧭 [AgentV2 V115 AGENTIC ADDON PLAN] "
            "quincho sin horario/duración explícitos → usa default de negocio; "
            "no solicitar dato redundante"
        )
    return clean


# ---------------------------------------------------------------------------
# Policy: defensa final. Si un planner legacy entrega duración vacía para
# agregar_quincho, el contrato de negocio la completa con 1h en vez de bloquear.
# ---------------------------------------------------------------------------
_validar_tool_agent_v2_v115_base = validar_tool_agent_v2


def validar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    image_path: str = "",
) -> Dict[str, Any]:
    if tool == "agregar_quincho" and isinstance(args, dict):
        if args.get("duracion_horas") in (None, ""):
            args["duracion_horas"] = _AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS
            print(
                "   🔐 [AgentV2 V115 POLICY DEFAULT] "
                "agregar_quincho.duracion_horas=1.0h"
            )
    return _validar_tool_agent_v2_v115_base(
        tool, args, world, perception, goals, image_path
    )


# ---------------------------------------------------------------------------
# PendingInteraction continuity for scalar duration answers.
# This is not intent parsing: the pending interaction already declares the field,
# operation, scope and target. We only coerce the current value into that field.
# ---------------------------------------------------------------------------
def _agent_v2_v115_scalar_duration_value(mensaje: str) -> Optional[float]:
    raw = str(mensaje or "").strip().casefold()
    if not raw:
        return None

    # Accept a bare scalar or a scalar followed by an exact duration unit.
    # No regex and no operation inference.
    candidates = [raw]
    units = (" horas", " hora", " hrs", " hr", " hs", " h")
    for unit in units:
        if raw.endswith(unit):
            candidates.append(raw[:-len(unit)].strip())

    value = None
    for candidate in candidates:
        normalized = candidate.replace(",", ".").strip()
        try:
            parsed = float(normalized)
        except (TypeError, ValueError):
            continue
        value = parsed
        break
    if value is None:
        return None

    allowed = {
        float(item)
        for item in (ALLOWED_TURN_DURATIONS or [1.0, 1.5, 2.0])
    }
    # El quincho admite las mismas duraciones operativas del motor actual.
    return float(value) if float(value) in allowed else None


def _agent_v2_v115_pending_duration_interaction(
    world: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    interactions = [
        dict(item)
        for item in _agent_v2_v100_active_interactions_from_world(world or {})
        if isinstance(item, dict)
        and str(item.get("field") or "") == "quincho_duracion_horas"
        and str(item.get("status") or "active") in {"active", "engaged", "suspended"}
    ]
    return interactions[-1] if interactions else None


def _agent_v2_v115_repair_pending_duration_answer(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    duration = _agent_v2_v115_scalar_duration_value(mensaje)
    if duration is None:
        return perception

    interaction = _agent_v2_v115_pending_duration_interaction(world or {})
    if not interaction:
        return perception

    qid = str(interaction.get("question_id") or "").strip()
    scope_id = str(interaction.get("scope_id") or "").strip()
    snapshot = (
        dict(interaction.get("action_snapshot") or {})
        if isinstance(interaction.get("action_snapshot"), dict)
        else {}
    )
    operation = str(snapshot.get("operation") or "").strip()
    allowed_operations = {
        str(value or "").strip()
        for value in (interaction.get("allowed_operations") or [])
        if str(value or "").strip()
    }
    if operation not in {"add_resource", "modify_resource"}:
        operation = next(
            (
                op for op in ("add_resource", "modify_resource")
                if op in allowed_operations
            ),
            "",
        )
    if not operation:
        return perception
    if allowed_operations and operation not in allowed_operations:
        return perception

    target = dict(snapshot.get("target") or {}) if isinstance(snapshot.get("target"), dict) else {}
    target["resource"] = "quincho"
    rid = str(target.get("reservation_id") or "").strip()
    if not rid:
        rid = next((
            str(item.get("id") or "").strip()
            for item in (interaction.get("target_refs") or [])
            if isinstance(item, dict)
            and str(item.get("kind") or "") == "reservation_id"
            and str(item.get("id") or "").strip()
        ), "")
    row = _agent_v2_v115_find_existing_target_row(world or {}, rid)
    if not row:
        return perception
    rid = str(_agent_v2_reservation_id(row) or row.get("reservation_id") or rid).strip()
    if not rid:
        return perception
    target["reservation_id"] = rid

    act_id = f"v115_pending_duration:{qid or uuid.uuid4()}"
    evidence = str(mensaje or "").strip()
    act = {
        "act_id": act_id,
        "operation": operation,
        "target": target,
        "temporal": dict(snapshot.get("temporal") or {}) if isinstance(snapshot.get("temporal"), dict) else {},
        "quantity": {"duration_hours": duration},
        "requested_facts": [],
        "changes": [{
            "field": "quincho.duration_hours",
            "value": duration,
            "source": "current_user_turn",
            "evidence": evidence,
        }],
        "provenance": [{
            "field": "quantity.duration_hours",
            "source": "pending_option",
            "question_id": qid,
            "scope_id": scope_id,
            "evidence": evidence,
        }],
        "commitment": {"wants_write": True, "wants_information": False},
    }

    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    frame.update({
        "source": "pending_interaction_v115",
        "schema_valid": True,
        "turn_type": "answer",
        "acts": [act],
        "intent": {"domain": "booking", "operation": operation},
        "targets": [target],
        "requested_facts": [],
        "requested_changes": list(act.get("changes") or []),
        "commitment": {"wants_write": True, "wants_information": False},
        "context_relation": {
            "type": "answers_pending",
            "question_id": qid,
            "scope_id": scope_id or None,
            "reference_id": rid,
            "references_previous_user_turn": False,
            "references_agent_offer": True,
            "answers_pending_question": True,
        },
    })
    clean["semantic_frame"] = frame
    clean["semantic_effect_verification"] = {
        "status": "verified",
        "verified_operations": [operation],
        "write_authorizations": [{
            "act_id": act_id,
            "authorized": True,
            "evidence_type": "current_user_turn",
            "evidence": evidence,
            "question_id": qid,
            "scope_id": scope_id,
            "interaction_id": interaction.get("interaction_id"),
            "operation": operation,
        }],
        "mode": "v115_pending_interaction_scalar_value",
    }
    clean["speech_act"] = "answer"
    clean["commitment"] = "wants_action"
    clean["answers_pending_field"] = "quincho_duracion_horas"
    clean["pending_relation"] = "answers_pending"
    clean["semantic_clarification_required"] = False
    clean.pop("semantic_clarification", None)
    clean.pop("semantic_validation_issues", None)

    entities = dict(clean.get("entities") or {})
    entities["quincho_duracion_horas"] = duration
    clean["entities"] = entities

    contract = _agent_v2_build_execution_contract(clean, world or {})
    if not isinstance(contract, dict) or not contract.get("authoritative"):
        return perception
    clean["execution_contract"] = contract

    mutation = _agent_v2_resource_mutation_from_semantics(clean, world or {})
    if not mutation:
        return perception
    clean["resource_mutation"] = mutation
    clean["explicit_quincho_request"] = True
    actions = [
        str(value) for value in (clean.get("explicit_actions") or [])
        if str(value) not in {
            "crear_reserva", "reprogramar_reserva", "reprogramar_turno",
            "cambiar_turno", "quitar_quincho", "pagar_senia",
        }
    ]
    if "agregar_quincho" not in actions:
        actions.append("agregar_quincho")
    clean["explicit_actions"] = actions
    clean = _agent_v2_v100_attach_desired_state_and_task_graph(clean, world or {})

    print(
        "   🔗 [AgentV2 V115 PENDING VALUE RESOLUTION] "
        f"field=quincho_duracion_horas value={duration}h "
        f"operation={operation} reservation_id={rid}"
    )
    return clean


_percibir_turno_agent_v2_v115_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    clean = await _percibir_turno_agent_v2_v115_base(
        mensaje, world, image_path, learning_policy
    )
    clean = _agent_v2_v115_repair_pending_duration_answer(
        mensaje, clean, world or {}
    )

    # Un add/update de quincho authoritative queda completo con defaults aunque
    # el SemanticFrame no haya traído cantidad explícita.
    contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    if contract.get("authoritative"):
        operations = {
            str(act.get("operation") or "")
            for act in (contract.get("acts") or [])
            if isinstance(act, dict)
        }
        if operations.intersection({"add_resource", "modify_resource"}):
            mutation = _agent_v2_resource_mutation_from_semantics(clean, world or {})
            if mutation and mutation.get("resource") == "quincho":
                clean["resource_mutation"] = mutation
    return clean


# ---------------------------------------------------------------------------
# Terminal guarantee: mutation pending => deterministic payment request + full
# updated summary. Existing builder already formats the correct business message;
# V115 only guarantees the final verified row is the one it receives.
# ---------------------------------------------------------------------------
_build_agent_v2_quincho_change_message_v115_base = build_agent_v2_quincho_change_message


def build_agent_v2_quincho_change_message(
    observation: Dict[str, Any],
) -> str:
    data = (observation or {}).get("data") if isinstance((observation or {}).get("data"), dict) else {}
    row = dict(data.get("reserva_verificada") or data.get("reserva") or {})
    if row:
        patched = dict(observation or {})
        patched_data = dict(data)
        patched_data["reserva"] = row
        patched_data["reserva_verificada"] = row
        patched["data"] = patched_data
        rendered = _build_agent_v2_quincho_change_message_v115_base(patched).strip()
        if rendered:
            if _pending_hold_row_is_temporary(row):
                print(
                    "   🧾 [AgentV2 V115 PENDING MUTATION TEMPLATE] "
                    "pedido de comprobante + resumen actualizado + hold renovado"
                )
            return rendered
    return _build_agent_v2_quincho_change_message_v115_base(observation)


