def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v115_base()
    results = list(result.get("results") or [])

    row = {
        "reservation_id": "81",
        "fecha": "Lunes 21/09",
        "hora": "19:00",
        "cancha": "Cancha 4 Pádel",
        "duracion_horas": "1.0",
        "estado": BOOKING_STATUS_PENDING,
        "senia_estado": "pendiente",
        "precio_total": "20000",
        "senia_monto": "10000",
        "monto_pendiente": "10000",
    }
    world = {
        "facts": {"reservas_reales": [row], "memory_owner": "eval_v115"},
        "stored_memory": {"pending_decisions": [], "history": [], "scopes": {}},
        "pending_decisions": [], "open_questions": [], "history": [],
    }

    defaults = _agent_v2_v115_default_quincho_fields(row, {})
    results.append({
        "name": "v115_quincho_default_is_after_court_for_one_hour",
        "ok": bool(
            defaults.get("hora_inicio") == "20:00"
            and defaults.get("hora_fin") == "21:00"
            and float(defaults.get("duracion_horas") or 0) == 1.0
        ),
    })

    planner_perception = {
        "resource_mutation": {
            "resource": "quincho",
            "operation": "add",
            "scope": "existing_reservation",
            "write_intent": True,
            "reservation_id": "81",
            "fields": {},
        },
        "entities": {},
    }
    qnames = []
    for item in (QUINCHOS or []):
        if isinstance(item, dict):
            name = str(item.get("name") or item.get("nombre") or "").strip()
        else:
            name = str(item or "").strip()
        if name:
            qnames.append(name)
    if len(qnames) == 1:
        planner_perception["entities"]["quincho"] = qnames[0]
        direct = _agent_v2_plan_current_resource_mutation(
            world,
            planner_perception,
            {"goals": [{"goal": "agregar_quincho", "priority": 1.0}]},
            [],
            {"agregar_quincho": {"state": "pending"}},
        ) or {}
        add_step = next((
            step for step in (direct.get("steps") or [])
            if isinstance(step, dict) and step.get("tool") == "agregar_quincho"
        ), {})
        results.append({
            "name": "v115_add_quincho_planner_never_asks_default_duration",
            "ok": bool(
                add_step
                and float((add_step.get("args") or {}).get("duracion_horas") or 0) == 1.0
                and (add_step.get("args") or {}).get("hora_inicio") == "20:00"
            ),
        })

    results.append({
        "name": "v115_scalar_two_is_valid_duration_value",
        "ok": _agent_v2_v115_scalar_duration_value("2") == 2.0,
    })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# AGENT V2 V116 — VERIFIED FINANCIAL FACTPACK FOR BOOKING MUTATIONS
# 21/09/2026
#
# Incidente corregido:
#   agregar_quincho se ejecutaba correctamente y el renderer determinista
#   construía el resumen correcto, pero Money Guard rechazaba el precio de la
#   cancha porque la Observation del WRITE sólo exponía quincho/total y no el
#   componente cancha. El WRITE era verdadero; el FactPack era incompleto.
#
# Regla V116:
#   toda mutación de reserva que pueda terminar en un resumen monetario publica
#   en la MISMA Observation un contrato financiero completo y verificable:
#       - precio cancha
#       - precio quincho (si aplica)
#       - total
#       - seña
#       - saldo pendiente
#   Money Guard sigue fail-closed. No se desactiva ni acepta importes del LLM.
# ============================================================================
AGENT_V2_UNIFIED_AGENTIC_CORE = "v116"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = AGENT_V2_UNIFIED_AGENTIC_CORE
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_verified_financial_factpack_v116"

_AGENT_V2_V116_FINANCIAL_MUTATION_TOOLS = {
    "agregar_quincho",
    "quitar_quincho",
    "reprogramar_reserva",
}


def _agent_v2_v116_boolish(value: Any) -> bool:
    return str(value or "").strip().casefold() in {
        "si", "sí", "true", "1", "yes", "y"
    }


def _agent_v2_v116_mutation_financial_factpack(
    observation: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Completa la autoridad monetaria de un WRITE ya verificado.

    No interpreta el mensaje del usuario y no confía en texto generado.
    Deriva únicamente desde:
      1) la fila final persistida/verificada de la reserva;
      2) calculadoras deterministas de config.py para componentes faltantes.
    """
    if not isinstance(observation, dict):
        return observation

    tool = str(observation.get("tool") or "").strip()
    if (
        tool not in _AGENT_V2_V116_FINANCIAL_MUTATION_TOOLS
        or not observation.get("ok")
        or observation.get("status") not in {"success", "already_exists"}
    ):
        return observation

    data = dict(observation.get("data") or {})
    row = dict(
        data.get("reserva_verificada")
        or data.get("reserva")
        or data.get("final_reservation_state")
        or {}
    )
    if not row:
        return observation

    duracion_cancha = normalizar_duracion_horas(
        row.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS
    )

    precio_cancha = _monto_a_int(row.get("precio_cancha_total"))
    if precio_cancha is None:
        precio_cancha = calcular_precio_total(duracion_cancha)

    def first_money(*values: Any) -> Optional[int]:
        for candidate in values:
            parsed = _monto_a_int(candidate)
            if parsed is not None:
                return parsed
        return None

    con_quincho = bool(
        _agent_v2_v116_boolish(row.get("con_quincho"))
        or (
            tool == "agregar_quincho"
            and bool(data.get("enabled", True))
        )
    )
    if tool == "quitar_quincho":
        con_quincho = False

    quincho = normalizar_nombre_quincho(
        data.get("quincho") or row.get("quincho") or ""
    ) if con_quincho else ""

    duracion_quincho = normalizar_duracion_horas(
        data.get("duracion_horas")
        or row.get("quincho_duracion_horas")
        or 1.0,
        1.0,
    ) if con_quincho else 0.0

    precio_quincho = 0
    if con_quincho:
        precio_quincho = first_money(
            row.get("quincho_precio_total"),
            data.get("precio_quincho_total"),
            data.get("precio_quincho"),
        )
        if precio_quincho is None:
            precio_quincho = calcular_precio_quincho_total(
                quincho, duracion_quincho
            ) or 0

    schedule_only_mutation = bool(data.get("schedule_only_mutation"))
    structural_add = bool(
        tool == "agregar_quincho"
        and con_quincho
        and not schedule_only_mutation
    )

    # V218 — INVARIANTE MONETARIA DE ADDON:
    # al AGREGAR quincho, el total verdadero es siempre cancha + quincho.
    # No aceptamos un precio_total persistido viejo que todavía represente sólo
    # la cancha (incidente real: 40k + 10k se publicó como total 40k).
    if structural_add:
        precio_total = int(precio_cancha or 0) + int(precio_quincho or 0)
    else:
        precio_total = first_money(
            row.get("precio_total"),
            data.get("precio_total"),
            data.get("total"),
        )
        if precio_total is None:
            precio_total = int(precio_cancha or 0) + int(precio_quincho or 0)

    senia_estado = str(row.get("senia_estado") or "").strip().casefold()

    # Si el precio cambió estructuralmente y todavía no hubo un pago real,
    # recalculamos seña y saldo desde el NUEVO total. Un valor viejo de la fila
    # no puede mantener una seña de la cancha sola después de sumar el addon.
    if structural_add and senia_estado not in {
        "pagada", "parcial", "parcial_efectivo_pendiente", "pendiente_efectivo"
    }:
        senia = _senia_para_total(precio_total)
        saldo = calcular_monto_pendiente(precio_total, senia)
    else:
        senia = first_money(
            row.get("senia_monto"),
            row.get("senia_valor"),
            data.get("senia_monto"),
            data.get("senia_valor"),
        )
        if senia is None:
            senia = (
                _senia_guardada_o_configurada(row, precio_total)
                if senia_estado == "pagada"
                else _senia_para_total(precio_total)
            )

        saldo = first_money(
            row.get("monto_pendiente"),
            data.get("monto_pendiente"),
        )
        if saldo is None:
            saldo = calcular_monto_pendiente(precio_total, senia)

    contract = {
        "precio_cancha": int(precio_cancha or 0),
        "precio_cancha_total": int(precio_cancha or 0),
        "precio_quincho": int(precio_quincho or 0),
        "precio_quincho_total": int(precio_quincho or 0),
        "precio_total": int(precio_total or 0),
        "total": int(precio_total or 0),
        "senia_monto": int(senia or 0),
        "senia_valor": int(senia or 0),
        "monto_pendiente": int(saldo or 0),
        "saldo": int(saldo or 0),
    }

    # Exponer el FactPack en data es intencional: _agent_v2_current_financial_facts
    # sólo autoriza dinero producido por Observations del turno actual.
    data.update({
        "precio_cancha": contract["precio_cancha"],
        "precio_cancha_total": contract["precio_cancha_total"],
        "precio_quincho": contract["precio_quincho"],
        "precio_quincho_total": contract["precio_quincho_total"],
        "precio_total": contract["precio_total"],
        "total": contract["total"],
        "senia_monto": contract["senia_monto"],
        "senia_valor": contract["senia_valor"],
        "monto_pendiente": contract["monto_pendiente"],
        "saldo": contract["saldo"],
        "financial_fact_contract": dict(contract),
        "reserva": row,
        "reserva_verificada": row,
    })

    enriched = dict(observation)
    enriched["data"] = data
    verified_facts = dict(enriched.get("verified_facts") or {})
    verified_facts["financial_fact_contract"] = dict(contract)
    verified_facts["final_reservation_state"] = dict(row)
    enriched["verified_facts"] = verified_facts

    print(
        "   💰 [AgentV2 V116 FINANCIAL FACTPACK] "
        f"tool={tool} "
        f"cancha={contract['precio_cancha_total']} "
        f"quincho={contract['precio_quincho_total']} "
        f"total={contract['precio_total']} "
        f"senia={contract['senia_monto']} "
        f"saldo={contract['monto_pendiente']}"
    )
    return enriched


_ejecutar_tool_agent_v2_v116_base = ejecutar_tool_agent_v2


