_run_agent_v2_invariant_evals_v116_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v116_base()
    results = list(result.get("results") or [])

    qnames = []
    for item in (QUINCHOS or []):
        if isinstance(item, dict):
            name = str(item.get("name") or item.get("nombre") or "").strip()
        else:
            name = str(item or "").strip()
        if name:
            qnames.append(name)

    if qnames:
        qname = qnames[0]
        court_price = int(calcular_precio_total(1.0) or 0)
        qprice = int(calcular_precio_quincho_total(qname, 1.0) or 0)
        total = court_price + qprice
        senia = int(_senia_para_total(total) or 0)
        saldo = int(calcular_monto_pendiente(total, senia) or 0)

        row = {
            "reservation_id": "82",
            "fecha": "Lunes 21/09",
            "hora": "18:00",
            "cancha": "Cancha 4 Pádel",
            "duracion_horas": "1.0",
            "estado": BOOKING_STATUS_PENDING,
            "senia_estado": "pendiente",
            "con_quincho": "Si",
            "quincho": qname,
            "quincho_hora_inicio": "19:00",
            "quincho_duracion_horas": "1.0",
            "quincho_precio_total": str(qprice),
            "precio_total": str(total),
            "senia_monto": str(senia),
            "monto_pendiente": str(saldo),
        }
        obs = {
            "tool": "agregar_quincho",
            "ok": True,
            "status": "success",
            "data": {
                "reservation_id": "82",
                "enabled": True,
                "quincho": qname,
                "hora_inicio": "19:00",
                "duracion_horas": 1.0,
                "precio_quincho": qprice,
                "total": total,
                "reserva": row,
                "reserva_verificada": row,
            },
            "verified_facts": {},
        }
        enriched = _agent_v2_v116_mutation_financial_factpack(obs)
        rendered = build_agent_v2_quincho_change_message(enriched)
        claims = _agent_v2_money_claims(rendered)
        allowed = {
            value
            for fact in _agent_v2_current_financial_facts([enriched])
            if (value := _agent_v2_parse_money_value(fact.get("value"))) is not None
        }
        results.append({
            "name": "v116_add_quincho_money_guard_accepts_full_verified_summary",
            "ok": bool(
                rendered
                and claims.issubset(allowed)
                and _agent_v2_monetary_claims_valid(rendered, [enriched])
            ),
        })
        results.append({
            "name": "v116_financial_factpack_contains_court_component",
            "ok": bool(
                _monto_a_int((enriched.get("data") or {}).get("precio_cancha_total"))
                == court_price
            ),
        })
    else:
        results.append({
            "name": "v116_add_quincho_money_guard_accepts_full_verified_summary",
            "ok": True,
            "skipped": "quincho_disabled_or_not_configured",
        })
        results.append({
            "name": "v116_financial_factpack_contains_court_component",
            "ok": True,
            "skipped": "quincho_disabled_or_not_configured",
        })

    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }


# ============================================================================
# V117 — DYNAMIC MULTI-SUBINTENT TRANSACTION + READ ORCHESTRATION
# ============================================================================
# Problema corregido:
#   "reservame mañana a las 18 y quiero saber sobre el torneo"
# no es UN goal. Es un turno compuesto con, como mínimo:
#   1) un WRITE transaccional de booking;
#   2) un READ independiente de negocio/evento.
#
# Las capas previas ya detectaban subintenciones, pero el Planner de Event
# Registration podía monopolizar el TaskGraph y el terminal fast-path de WRITE
# podía devolver antes de renderizar los READs restantes. V117 separa ambos
# efectos sin reinterpretar lenguaje:
#
#   SemanticFrame / ExecutionContract = significado y autoridad
#   V117 Planner                  = orquestación de ramas ya verificadas
#   Tools                         = hechos / mutaciones
#   V117 Composer                 = respuesta única con TODAS las obligaciones
#
# No hay regex ni keywords de intención en esta capa.

AGENT_V2_UNIFIED_AGENTIC_CORE = "v117"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v117"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_dynamic_multi_subintent_write_read_v117"

_AGENT_V2_V117_EVENT_QUERY_TOOLS = {
    "listar_eventos", "consultar_evento", "consultar_cupos_evento",
}
_AGENT_V2_V117_EVENT_OPERATIONS = {
    "query_event", "register_event", "register_event_payment",
    "choose_event_payment_method",
}
_AGENT_V2_V117_TRANSACTION_OPERATIONS = {
    "create_booking", "cancel_booking", "reschedule_booking",
    "modify_resource", "add_resource", "remove_resource",
    "register_payment", "choose_payment_method", "join_waitlist",
}


def _agent_v2_v117_contract_acts(perception: Dict[str, Any]) -> List[Dict[str, Any]]:
    contract = (
        (perception or {}).get("execution_contract")
        if isinstance((perception or {}).get("execution_contract"), dict)
        else {}
    )
    if not contract.get("authoritative"):
        return []
    return [dict(act) for act in (contract.get("acts") or []) if isinstance(act, dict)]


def _agent_v2_v117_mixed_write_read(perception: Dict[str, Any]) -> bool:
    acts = _agent_v2_v117_contract_acts(perception)
    if not acts:
        return False
    operations = {str(act.get("operation") or "") for act in acts}
    has_transaction = bool(operations.intersection(_AGENT_V2_V117_TRANSACTION_OPERATIONS))
    has_read = any(str(op).startswith("query_") for op in operations)
    return bool(has_transaction and has_read)


def _agent_v2_v117_split_perception(
    perception: Dict[str, Any],
    *,
    keep_reads: bool,
    drop_event_query: bool = False,
) -> Dict[str, Any]:
    """Proyecta una rama del ExecutionContract SIN reinterpretar el texto.

    Sólo filtra Semantic Acts ya aceptados por el contrato autoritativo. La rama
    WRITE conserva exactamente las autorizaciones del Effect Verifier; la rama
    READ nunca crea autoridad de escritura.
    """
    import copy

    clean = copy.deepcopy(perception or {})
    contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    original_acts = [dict(act) for act in (contract.get("acts") or []) if isinstance(act, dict)]

    def _keep(act: Dict[str, Any]) -> bool:
        op = str(act.get("operation") or "")
        is_read = op.startswith("query_")
        if drop_event_query and op == "query_event":
            return False
        return is_read if keep_reads else not is_read

    acts = [act for act in original_acts if _keep(act)]
    if not acts:
        contract["acts"] = []
        contract["allowed_tools"] = []
        contract["effects"] = []
        contract["authoritative"] = False
        clean["execution_contract"] = contract
        return clean

    allowed_tools = set()
    effects = set()
    for act in acts:
        op = str(act.get("operation") or "")
        allowed_tools.update(AGENT_V2_OPERATION_TOOLS.get(op, set()))
        effects.add("write" if op in AGENT_V2_WRITE_OPERATIONS else "read")

    contract["acts"] = acts
    contract["allowed_tools"] = sorted(allowed_tools)
    contract["effects"] = sorted(effects)
    contract["authoritative"] = True
    contract["requires_clarification"] = False
    contract["clarification_reasons"] = []
    clean["execution_contract"] = contract
    clean["semantic_clarification_required"] = False
    clean.pop("semantic_clarification", None)

    frame = clean.get("semantic_frame") if isinstance(clean.get("semantic_frame"), dict) else {}
    frame_acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict) and _keep(act)
    ]
    frame["acts"] = frame_acts
    frame["targets"] = [
        dict(act.get("target") or {})
        for act in frame_acts
        if isinstance(act.get("target"), dict)
    ]
    frame["requested_facts"] = list(dict.fromkeys(
        str(fact)
        for act in frame_acts
        for fact in (act.get("requested_facts") or [])
        if str(fact or "").strip()
    ))
    frame["commitment"] = {
        "wants_write": any(
            str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
            or bool((act.get("commitment") or {}).get("wants_write"))
            for act in frame_acts
        ),
        "wants_information": any(
            str(act.get("operation") or "").startswith("query_")
            or bool((act.get("commitment") or {}).get("wants_information"))
            for act in frame_acts
        ),
    }
    if frame_acts:
        first = frame_acts[0]
        frame["intent"] = {
            "domain": str(first.get("domain") or "other"),
            "operation": str(first.get("operation") or "unknown"),
        }
    clean["semantic_frame"] = frame
    if keep_reads:
        clean["current_turn_read_only"] = True
    else:
        clean["current_turn_read_only"] = False
    return clean


def _agent_v2_v117_split_goals(
    goals: Dict[str, Any],
    perception: Dict[str, Any],
    *,
    keep_reads: bool,
) -> Dict[str, Any]:
    acts = _agent_v2_v117_contract_acts(perception)
    selected_operations = {
        str(act.get("operation") or "")
        for act in acts
        if str(act.get("operation") or "").startswith("query_") == keep_reads
    }
    selected_goal_names = set()
    for operation in selected_operations:
        selected_goal_names.update(AGENT_V2_OPERATION_GOALS.get(operation, []))

    # Algunos goals son compartidos (query_availability/create_booking). Si la
    # rama WRITE contiene create_booking, buscar_turno pertenece también al WRITE.
    if not keep_reads:
        write_operations = {
            str(act.get("operation") or "")
            for act in acts
            if not str(act.get("operation") or "").startswith("query_")
        }
        for operation in write_operations:
            selected_goal_names.update(AGENT_V2_OPERATION_GOALS.get(operation, []))

    selected = [
        dict(goal) for goal in ((goals or {}).get("goals") or [])
        if isinstance(goal, dict) and str(goal.get("goal") or "") in selected_goal_names
    ]
    if not selected:
        selected = [
            {
                "goal": name,
                "priority": max(0.5, 1.0 - idx * 0.04),
                "reason": "V117 split from authoritative ExecutionContract",
            }
            for idx, name in enumerate(selected_goal_names)
            if name in AGENT_V2_GOALS
        ]
    return {
        "goals": selected,
        "primary_goal": (selected[0].get("goal") if selected else "otro"),
        "reason": "v117_execution_contract_branch",
    }


def _agent_v2_v117_event_read_step(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    acts = _agent_v2_v117_contract_acts(perception)
    if not any(str(act.get("operation") or "") == "query_event" for act in acts):
        return None

    # Una observación factual de evento ya satisface este READ en el turno actual.
    if any(
        obs.get("tool") in _AGENT_V2_V117_EVENT_QUERY_TOOLS
        and (
            obs.get("ok")
            or (obs.get("data") or {}).get("reason") in {"no_active_events", "event_full"}
        )
        for obs in (observations or [])
        if isinstance(obs, dict)
    ):
        return None

    values = _event_registration_semantic_values(perception, world or {})
    event = _event_registration_find_event(values)
    if event is not None:
        return {
            "tool": "consultar_evento",
            "args": {"event_id": event.get("event_id")},
            "reason": "V117 residual READ: información factual del torneo",
            "replan_after": False,
        }
    return {
        "tool": "listar_eventos",
        "args": {
            "event_name": values.get("event_name"),
            "event_date": values.get("event_date"),
            "for_registration": False,
        },
        "reason": "V117 residual READ: información general de torneos activos",
        "replan_after": False,
    }


def _agent_v2_v117_read_steps(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Compila todos los READs independientes del mismo turno.

    Reusa el Tool-First READ existente para disponibilidad/precio/policy/reserva y
    agrega query_event mediante su engine factual. Ningún READ puede ampliar una
    autorización WRITE.
    """
    read_perception = _agent_v2_v117_split_perception(perception, keep_reads=True)
    read_goals = _agent_v2_v117_split_goals(goals, perception, keep_reads=True)
    if not (read_perception.get("execution_contract") or {}).get("authoritative"):
        return []

    steps: List[Dict[str, Any]] = []

    # Todos los READs generales ya tienen un compilador estable. Se excluye
    # query_event porque Event Registration tiene tools/facts propios.
    non_event_read = _agent_v2_v117_split_perception(
        perception, keep_reads=True, drop_event_query=True
    )
    if (non_event_read.get("execution_contract") or {}).get("authoritative"):
        non_event_goals = _agent_v2_v117_split_goals(
            read_goals, non_event_read, keep_reads=True
        )
        generic_plan = _agent_v2_tool_first_read_plan(
            world or {}, non_event_read, non_event_goals, observations or []
        )
        if isinstance(generic_plan, dict):
            steps.extend(
                dict(step) for step in (generic_plan.get("steps") or [])
                if isinstance(step, dict)
            )

    event_step = _agent_v2_v117_event_read_step(
        perception, world or {}, observations or []
    )
    if event_step:
        steps.append(event_step)

    allowed = set(((perception or {}).get("execution_contract") or {}).get("allowed_tools") or [])
    deduped = []
    signatures = set()
    for step in steps:
        tool = str(step.get("tool") or "")
        if not tool or tool not in allowed:
            continue
        if AGENT_V2_TOOL_CATALOG.get(tool, {}).get("effect") != "read":
            continue
        signature = json.dumps(
            {"tool": tool, "args": step.get("args") or {}},
            sort_keys=True, ensure_ascii=False, default=str,
        )
        if signature in signatures:
            continue
        signatures.add(signature)
        deduped.append(step)
    return deduped


_planificar_agent_v2_v117_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if not _agent_v2_v117_mixed_write_read(perception):
        return await _planificar_agent_v2_v117_base(
            world, perception, goals, observations, offline_mode, learning_policy
        )

    write_perception = _agent_v2_v117_split_perception(
        perception, keep_reads=False
    )
    write_goals = _agent_v2_v117_split_goals(
        goals, perception, keep_reads=False
    )
    write_plan = await _planificar_agent_v2_v117_base(
        world,
        write_perception,
        write_goals,
        observations,
        offline_mode,
        learning_policy,
    )
    write_steps = [
        dict(step) for step in ((write_plan or {}).get("steps") or [])
        if isinstance(step, dict)
    ]
    # Por construcción la rama transaccional no puede ejecutar un READ de torneo.
    write_steps = [
        step for step in write_steps
        if str(step.get("tool") or "") not in _AGENT_V2_V117_EVENT_QUERY_TOOLS
    ]

    read_steps = _agent_v2_v117_read_steps(
        world, perception, goals, observations
    )

    # Evitar duplicar una lectura que ya forma parte del preflight transaccional.
    existing_signatures = {
        json.dumps(
            {"tool": step.get("tool"), "args": step.get("args") or {}},
            sort_keys=True, ensure_ascii=False, default=str,
        )
        for step in write_steps
    }
    merged = list(write_steps)
    for step in read_steps:
        signature = json.dumps(
            {"tool": step.get("tool"), "args": step.get("args") or {}},
            sort_keys=True, ensure_ascii=False, default=str,
        )
        if signature not in existing_signatures:
            merged.append(step)
            existing_signatures.add(signature)

    print(
        "   🧩 [AgentV2 V117 MIXED TASKGRAPH] "
        f"write_tools={[step.get('tool') for step in write_steps]} "
        f"read_tools={[step.get('tool') for step in read_steps]}"
    )
    return {
        "steps": merged[:AGENT_V2_MAX_PLAN_STEPS],
        "done_if": "todas las subintenciones WRITE y READ verificadas del turno quedan satisfechas",
        "reason": "V117 multi-subintent transaction + residual reads",
        "goal_progress": _agent_v2_goal_progress(goals or {}, observations or []),
    }


def _agent_v2_v117_is_generic_fallback(text: str) -> bool:
    normalized = _agent_learning_normalize_text(text or "")
    return normalized in {
        "me falta un dato para seguir me lo confirmas",
        "no pude confirmar el resultado de esa consulta",
    }


def _agent_v2_v117_read_observations(
    observations: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    out = []
    for obs in observations or []:
        if not isinstance(obs, dict):
            continue
        tool = str(obs.get("tool") or "")
        effect = AGENT_V2_TOOL_CATALOG.get(tool, {}).get("effect")
        if effect == "read" or tool in _AGENT_V2_V117_EVENT_QUERY_TOOLS:
            out.append(obs)
    return out


async def _agent_v2_v117_compose_read_branch(
    mensaje: str,
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> str:
    read_perception = _agent_v2_v117_split_perception(perception, keep_reads=True)
    read_goals = _agent_v2_v117_split_goals(goals, perception, keep_reads=True)
    read_observations = _agent_v2_v117_read_observations(observations)
    if not read_observations:
        return ""

    parts: List[str] = []
    operations = {
        str(act.get("operation") or "")
        for act in _agent_v2_v117_contract_acts(read_perception)
    }

    # Event Registration tiene renderer factual propio y no necesita LLM.
    if "query_event" in operations:
        event_message = build_agent_v2_event_registration_message(read_observations)
        if event_message:
            parts.append(event_message.strip())

    # Para el resto de READs reutilizamos el compositor multi-subintención ya
    # existente. Al trabajar sólo con Observations READ no puede repetir ni
    # reescribir el resultado transaccional.
    non_event_read = _agent_v2_v117_split_perception(
        read_perception, keep_reads=True, drop_event_query=True
    )
    if (non_event_read.get("execution_contract") or {}).get("authoritative"):
        non_event_goals = _agent_v2_v117_split_goals(
            read_goals, non_event_read, keep_reads=True
        )
        non_event_obs = [
            obs for obs in read_observations
            if str(obs.get("tool") or "") not in _AGENT_V2_V117_EVENT_QUERY_TOOLS
        ]
        if non_event_obs:
            rendered = _agent_v2_fallback_response_event_base(
                non_event_goals,
                non_event_obs,
                world,
                non_event_read,
            )
            if rendered and not _agent_v2_v117_is_generic_fallback(rendered):
                parts.append(str(rendered).strip())
            else:
                dynamic = await _agent_v2_compose_from_fact_pack(
                    mensaje,
                    world,
                    non_event_read,
                    non_event_goals,
                    non_event_obs,
                    status,
                    learning_policy,
                )
                if dynamic and not _agent_v2_v117_is_generic_fallback(dynamic):
                    parts.append(str(dynamic).strip())

    unique = []
    seen = set()
    for part in parts:
        key = _agent_learning_normalize_text(part)
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(part)
    return "\n\n".join(unique).strip()


_componer_respuesta_agent_v2_v117_base = componer_respuesta_agent_v2


async def componer_respuesta_agent_v2(
    mensaje: str,
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> str:
    # El terminal fast-path de V87 sigue siendo válido para el WRITE, pero ya no
    # puede retornar antes de resolver READs independientes del mismo mensaje.
    if _agent_v2_v117_mixed_write_read(perception):
        transaction_message = ""
        if callable(globals().get("_agent_v2_verified_terminal_template_event_base")):
            transaction_message = str(
                _agent_v2_verified_terminal_template_event_base(observations) or ""
            ).strip()
        read_message = await _agent_v2_v117_compose_read_branch(
            mensaje,
            world,
            perception,
            goals,
            observations,
            status,
            learning_policy,
        )

        if transaction_message and read_message:
            print(
                "   🧩 [AgentV2 V117 MULTI-SUBINTENT RESPONSE] "
                "terminal WRITE + READs residuales → respuesta única"
            )
            return f"{transaction_message}\n\n{read_message}".strip()
        if transaction_message:
            # Si todavía falta ejecutar un READ, el goal_status no debería llegar
            # normalmente al Composer; se conserva el terminal seguro como defensa.
            return transaction_message
        if read_message:
            return read_message

    response = await _componer_respuesta_agent_v2_v117_base(
        mensaje,
        world,
        perception,
        goals,
        observations,
        status,
        learning_policy,
    )
    if response and not _agent_v2_v117_is_generic_fallback(response):
        return response

    # Última defensa de flexibilidad: una salida no renderizada se vuelve a
    # componer desde FactPack + World State. Nunca se usa la frase genérica que
    # ocultaba cuál subintención faltaba.
    if observations:
        dynamic = await _agent_v2_compose_from_fact_pack(
            mensaje,
            world,
            perception,
            goals,
            observations,
            status,
            learning_policy,
        )
        if dynamic and not _agent_v2_v117_is_generic_fallback(dynamic):
            print(
                "   🧠 [AgentV2 V117 GROUNDED DYNAMIC RESPONSE] "
                "fallback genérico eliminado → Composer desde FactPack"
            )
            return str(dynamic).strip()

    # No inventamos un hecho si no existe Observation verificable. Si existe una
    # pregunta stateful conocida, se renderiza; si no, se deriva al humano en vez
    # de fingir que sólo 'falta un dato'.
    open_questions = [
        q for q in ((world or {}).get("open_questions") or [])
        if isinstance(q, dict) and not q.get("context_only")
    ]
    if open_questions:
        rendered_question = _agent_v2_render_open_question(open_questions[-1])
        if rendered_question:
            return rendered_question
    return build_human_derivation_response()


