async def _agent_v2_v100_resolve_conversation_context(
    mensaje: str,
    first_perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    # Defensa en profundidad. Aunque otro caller ignore context_needed(), un
    # contrato actual autocontenido jamás vuelve a enlazarse con pending/focus viejo.
    if _agent_v2_v118_current_turn_contract_is_self_contained(
        first_perception, world or {}
    ):
        print(
            "   🛑 [AgentV2 V118 MEMORY QUARANTINE] "
            "pending/focus histórico no puede sobrescribir el turno actual"
        )
        return first_perception
    return await _agent_v2_v100_resolve_conversation_context_v118_base(
        mensaje, first_perception, world or {}
    )


# ---------------------------------------------------------------------------
# Planner V118: memoria conversacional pasiva para el turno independiente.
# ---------------------------------------------------------------------------
def _agent_v2_v118_planning_world_without_dialogue_memory(
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Copia de World State que conserva negocio/reservas pero no pendientes viejos."""
    import copy

    clean = copy.deepcopy(world or {})
    clean["pending_interactions"] = []
    clean["open_questions"] = []

    frame = clean.get("conversation_frame")
    if isinstance(frame, dict):
        frame = dict(frame)
        frame["pending_interactions"] = []
        frame["focus"] = {}
        clean["conversation_frame"] = frame

    # availability_context/drafts del mismo turno son reconstruidos por el
    # pipeline transaccional. Para un NEW REQUEST no deben venir de memoria.
    facts = clean.get("facts")
    if isinstance(facts, dict):
        facts = dict(facts)
        facts["dialogue_memory_mode"] = "passive_current_turn_v118"
        clean["facts"] = facts
    return clean


_planificar_agent_v2_v118_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    planning_world = world
    if _agent_v2_v118_current_turn_contract_is_self_contained(perception, world or {}):
        planning_world = _agent_v2_v118_planning_world_without_dialogue_memory(world or {})
        print(
            "   🧹 [AgentV2 V118 PASSIVE MEMORY PLAN] "
            "Planner ignora pending/focus históricos; conserva reservas y hechos de negocio"
        )
    return await _planificar_agent_v2_v118_base(
        planning_world,
        perception,
        goals,
        observations,
        offline_mode,
        learning_policy,
    )


