_percibir_turno_agent_v2_v118_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    clean = await _percibir_turno_agent_v2_v118_base(
        mensaje, world, image_path, learning_policy
    )
    if _agent_v2_v118_current_turn_contract_is_self_contained(clean, world or {}):
        # Ningún consumidor downstream debe confundir un pending histórico con
        # respuesta del usuario a ese pending.
        clean = dict(clean)
        clean["pending_relation"] = "new_request"
        clean.pop("answers_pending_field", None)
        clean.pop("_v100_pending_resolution", None)
        clean.pop("semantic_clarification_required", None)
        clean.pop("semantic_clarification", None)
        clean["_v118_current_turn_authority"] = True
        clean = _agent_v2_v100_attach_desired_state_and_task_graph(
            clean, world or {}
        )
        print(
            "   🔒 [AgentV2 V118 POSTCONDITION] "
            "current-turn contract preservado hasta Goal Compiler/Planner"
        )
    return clean


