_aplicar_regla_universal_salida_segura_agent_v2_v118_base = (
    aplicar_regla_universal_salida_segura_agent_v2
)


def aplicar_regla_universal_salida_segura_agent_v2(
    response: str,
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    status: str,
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    page=None,
    dry_run: bool = False,
) -> Tuple[str, Dict[str, Any]]:
    final_response, assessment = _aplicar_regla_universal_salida_segura_agent_v2_v118_base(
        response, world, perception, goals, observations, status,
        telefono, prospecto, page, dry_run,
    )
    if (
        isinstance(assessment, dict)
        and assessment.get("state") == "internal_recovery_write"
        and _agent_v2_v108_current_turn_create_booking(perception or {})
    ):
        # Sigue siendo fail-closed: jamás fingimos reserva creada si no hubo tool
        # exitosa. Pero tampoco confundimos un alta nueva con una modificación.
        final_response = (
            "No pude completar la reserva en este intento porque una validación interna "
            "no llegó a cerrarse. No marqué ningún turno como confirmado."
        )
    return final_response, assessment


