# ============================================================================
# V119 — MONOTONIC SEMANTIC AUTHORITY + STRUCTURAL READ COVERAGE
# ============================================================================
# Problemas corregidos a partir del log real de producción:
#   1) El auditor de subintenciones detectaba un READ faltante (por ejemplo,
#      información de torneo) pero un segundo LLM de validación podía rechazarlo
#      aun cuando el propio auditor había aportado una cita literal del turno.
#   2) Después de congelar un ExecutionContract autoritativo con WRITE verificado,
#      V102 volvía a llamar Semantic Effect Verifier. Esa segunda pasada podía
#      sustituir el frame completo (p.ej. create_booking -> query_policy) y borrar
#      una operación transaccional ya autorizada.
#
# Principio V119:
#   - Los WRITEs siguen siendo estrictos: nunca ganan autoridad por esta capa.
#   - Los READs faltantes se aceptan sólo si el auditor ya produjo una operación
#     READ válida + evidencia literal exacta del CURRENT USER TURN.
#   - Un contrato congelado y autoritativo con WRITE verificado es MONOTÓNICO:
#     una verificación tardía puede validar más cosas, pero jamás reemplazar o
#     eliminar un WRITE ya autorizado del turno actual.
#   - No hay regex/keywords de intención. Se opera sobre Semantic Acts y
#     provenance ya generados por los pilares de IA.

AGENT_V2_UNIFIED_AGENTIC_CORE = "v119"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v119"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_monotonic_multi_subintent_authority_v119"


def _agent_v2_v119_literal_current_turn_evidence(
    mensaje: str,
    candidate: Dict[str, Any],
) -> str:
    """Devuelve evidencia literal ya propuesta por el auditor, o vacío.

    Esto NO clasifica intención. Sólo comprueba que el fragmento aportado por
    Perception/Auditor existe literalmente en el mensaje actual.
    """
    evidence = str((candidate or {}).get("request_evidence") or "").strip()
    if not evidence:
        return ""
    current = " ".join(str(mensaje or "").casefold().split())
    literal = " ".join(evidence.casefold().split())
    if not literal or literal not in current:
        return ""
    return evidence


def _agent_v2_v119_is_read_operation(operation: Any) -> bool:
    op = _agent_v2_semantic_operation_alias(operation)
    if op not in AGENT_V2_SEMANTIC_OPERATIONS:
        return False
    if op in AGENT_V2_WRITE_OPERATIONS:
        return False
    return op not in {"unknown", "clarify", "greet", "close_conversation"}


def _agent_v2_v119_ground_read_candidate(
    mensaje: str,
    candidate: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """Grounding estructural de un READ propuesto por el auditor.

    Requisitos:
      - operación READ válida ya elegida por IA;
      - evidencia literal exacta del turno actual;
      - commitment sin WRITE;
      - requested_facts/target se conservan tal cual los produjo el auditor.

    La función no transforma query_policy en query_event ni viceversa.
    """
    if not isinstance(candidate, dict):
        return None
    operation = _agent_v2_semantic_operation_alias(candidate.get("operation"))
    if not _agent_v2_v119_is_read_operation(operation):
        return None
    evidence = _agent_v2_v119_literal_current_turn_evidence(mensaje, candidate)
    if not evidence:
        return None

    grounded = dict(candidate)
    grounded["operation"] = operation
    commitment = dict(grounded.get("commitment") or {})
    commitment["wants_write"] = False
    commitment["wants_information"] = True
    grounded["commitment"] = commitment

    provenance = [
        dict(item) for item in (grounded.get("provenance") or [])
        if isinstance(item, dict)
    ]
    if not any(
        str(item.get("source") or "").strip() == "current_user_turn"
        and bool(str(item.get("evidence") or "").strip())
        for item in provenance
    ):
        provenance.append({
            "field": "subintent.coverage",
            "source": "current_user_turn",
            "evidence": evidence,
        })
    grounded["provenance"] = provenance
    grounded["request_evidence"] = evidence
    return grounded


_agent_v2_verify_coverage_additions_v119_base = _agent_v2_verify_coverage_additions


async def _agent_v2_verify_coverage_additions(
    mensaje: str,
    audit: Dict[str, Any],
) -> Dict[str, Any]:
    """V119: READ coverage grounded por evidencia literal; WRITE conserva verifier.

    El auditor de cobertura ya es un pilar IA independiente. Para READs, una
    segunda IA no puede vetar arbitrariamente un candidato que trae evidencia
    literal válida. Para WRITEs mantenemos el verificador previo completo.
    """
    raw_candidates = [
        dict(item) for item in ((audit or {}).get("missing_acts") or [])
        if isinstance(item, dict)
    ]
    if not raw_candidates:
        return audit

    accepted_reads: List[Dict[str, Any]] = []
    write_candidates: List[Dict[str, Any]] = []
    structurally_rejected = 0

    for candidate in raw_candidates:
        operation = _agent_v2_semantic_operation_alias(candidate.get("operation"))
        if operation in AGENT_V2_WRITE_OPERATIONS:
            write_candidates.append(candidate)
            continue
        grounded = _agent_v2_v119_ground_read_candidate(mensaje, candidate)
        if grounded is None:
            structurally_rejected += 1
            continue
        accepted_reads.append(grounded)

    accepted_writes: List[Dict[str, Any]] = []
    rejected_writes = 0
    if write_candidates:
        write_audit = dict(audit or {})
        write_audit["missing_acts"] = write_candidates
        # La consistencia atomic_request_count del auditor no debe ser alterada,
        # pero el verifier previo sólo decide autoridad de estos WRITEs.
        verified_write_audit = await _agent_v2_verify_coverage_additions_v119_base(
            mensaje, write_audit
        )
        accepted_writes = [
            dict(item) for item in (verified_write_audit.get("missing_acts") or [])
            if isinstance(item, dict)
        ]
        rejected_writes = max(0, len(write_candidates) - len(accepted_writes))

    accepted = accepted_reads + accepted_writes
    verified = dict(audit or {})
    verified["missing_acts"] = accepted
    verified["missing_question_domains"] = list(dict.fromkeys(
        str(domain)
        for act in accepted
        for domain in (act.get("question_domains") or [])
        if str(domain or "").strip()
    ))
    verified["rejected_acts"] = structurally_rejected + rejected_writes
    verified["coverage_complete"] = bool((audit or {}).get("coverage_complete")) and not verified["rejected_acts"]
    verified.pop("_existing_semantic_act_count", None)

    print(
        "   🔎 [AgentV2 V119 READ COVERAGE AUTHORITY] "
        f"reads_grounded={len(accepted_reads)} writes_verified={len(accepted_writes)} "
        f"rejected={verified['rejected_acts']}"
    )
    return verified


# ---------------------------------------------------------------------------
# Monotonic Effect Verifier
# ---------------------------------------------------------------------------
_agent_v2_verify_semantic_effects_v119_base = _agent_v2_verify_semantic_effects


def _agent_v2_v119_frozen_verified_write_contract(
    perception: Dict[str, Any],
    world: Optional[Dict[str, Any]] = None,
) -> bool:
    clean = perception if isinstance(perception, dict) else {}
    contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    if not contract.get("authoritative") or not contract.get("frozen"):
        return False

    acts = [
        dict(act) for act in (contract.get("acts") or [])
        if isinstance(act, dict)
    ]
    write_acts = [
        act for act in acts
        if str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
    ]
    if not write_acts:
        return False

    verification = clean.get("semantic_effect_verification") if isinstance(clean.get("semantic_effect_verification"), dict) else {}
    if verification.get("status") != "verified":
        return False
    authorized_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }
    write_ids = {
        str(act.get("act_id") or "").strip()
        for act in write_acts if str(act.get("act_id") or "").strip()
    }
    if not write_ids or not write_ids.issubset(authorized_ids):
        return False

    freeze = _agent_v2_v87_freeze(clean)
    frozen_ops = {
        str(op or "").strip() for op in (freeze.get("operations") or [])
        if str(op or "").strip()
    } if isinstance(freeze, dict) else set()
    write_ops = {str(act.get("operation") or "").strip() for act in write_acts}
    if frozen_ops and not write_ops.issubset(frozen_ops):
        return False
    return True


async def _agent_v2_verify_semantic_effects(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    # En un contrato congelado, la segunda pasada de V102 no puede sustituir
    # semántica ya verificada. Esto es exactamente la condición observada en el
    # log V118: create_booking fue autorizado y luego apareció query_policy.
    if _agent_v2_v119_frozen_verified_write_contract(perception, world or {}):
        contract = (perception or {}).get("execution_contract") or {}
        print(
            "   🛡️ [AgentV2 V119 MONOTONIC EFFECT] "
            "ExecutionContract WRITE ya verificado → omito reverificación destructiva; "
            f"ops={[act.get('operation') for act in (contract.get('acts') or []) if isinstance(act, dict)]}"
        )
        return perception
    return await _agent_v2_verify_semantic_effects_v119_base(
        mensaje, perception, world or {}
    )


# ---------------------------------------------------------------------------
# Postcondition final: si el contrato actual contiene WRITE + READ, conservarlo
# como unidad hasta Goal Compiler/Planner. V117 se ocupa de separar las ramas.
# ---------------------------------------------------------------------------
_percibir_turno_agent_v2_v119_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    clean = await _percibir_turno_agent_v2_v119_base(
        mensaje, world, image_path, learning_policy
    )
    contract = clean.get("execution_contract") if isinstance(clean.get("execution_contract"), dict) else {}
    if contract.get("authoritative"):
        operations = [
            str(act.get("operation") or "")
            for act in (contract.get("acts") or [])
            if isinstance(act, dict) and str(act.get("operation") or "")
        ]
        has_write = any(op in AGENT_V2_WRITE_OPERATIONS for op in operations)
        has_read = any(_agent_v2_v119_is_read_operation(op) for op in operations)
        if has_write and has_read:
            clean = dict(clean)
            clean["_v119_mixed_contract_authority"] = True
            clean["pending_relation"] = "new_request"
            clean.pop("semantic_clarification_required", None)
            clean.pop("semantic_clarification", None)
            clean = _agent_v2_v100_attach_desired_state_and_task_graph(
                clean, world or {}
            )
            print(
                "   🔒 [AgentV2 V119 MIXED CONTRACT POSTCONDITION] "
                f"ops={operations} preservadas hasta Planner"
            )
    return clean


