_run_agent_v2_invariant_evals_v119_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v119_base()
    results = list(result.get("results") or [])

    message = "Me gustaria reservar a las 18 mañana y saber sobre torneo"
    read_candidate = {
        "operation": "query_event",
        "domain": "event_registration",
        "target": {"resource": "event"},
        "requested_facts": ["event.general_information"],
        "commitment": {"wants_write": False, "wants_information": True},
        "request_evidence": "saber sobre torneo",
        "question_domains": ["event_registration"],
    }
    grounded = _agent_v2_v119_ground_read_candidate(message, read_candidate)
    results.append({
        "name": "v119_read_subintent_with_literal_evidence_is_structurally_grounded",
        "ok": bool(
            grounded
            and grounded.get("operation") == "query_event"
            and any(
                item.get("source") == "current_user_turn"
                for item in (grounded.get("provenance") or [])
                if isinstance(item, dict)
            )
        ),
    })

    create_act = {
        "act_id": "v119_create",
        "operation": "create_booking",
        "domain": "booking",
        "target": {"resource": "court"},
        "temporal": {"day": "2026-09-22", "start": "18:00"},
        "quantity": {"duration_hours": 1.0},
        "requested_facts": [],
        "changes": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "provenance": [{
            "field": "temporal.start",
            "source": "current_user_turn",
            "evidence": "18 mañana",
        }],
    }
    event_act = dict(grounded or read_candidate)
    event_act["act_id"] = "v119_event"
    perception = {
        "semantic_frame": {
            "source": "ai",
            "schema_valid": True,
            "acts": [create_act, event_act],
            "context_relation": {"type": "new_request"},
        },
        "semantic_effect_verification": {
            "status": "verified",
            "verified_operations": ["create_booking"],
            "write_authorizations": [{
                "act_id": "v119_create",
                "authorized": True,
                "evidence_type": "current_user_turn",
                "evidence": "reservar a las 18 mañana",
            }],
        },
        "execution_contract": {
            "authoritative": True,
            "frozen": True,
            "acts": [create_act, event_act],
            "allowed_tools": sorted(
                set(AGENT_V2_OPERATION_TOOLS.get("create_booking", set()))
                | set(AGENT_V2_OPERATION_TOOLS.get("query_event", set()))
            ),
        },
        "semantic_freeze": {
            "active": True,
            "reason": "authoritative_execution_contract_with_verified_writes",
            "operations": ["create_booking", "query_event"],
            "write_act_ids": ["v119_create"],
            "targets": {},
        },
    }
    results.extend([
        {
            "name": "v119_frozen_verified_write_contract_detected",
            "ok": _agent_v2_v119_frozen_verified_write_contract(perception, {}),
        },
        {
            "name": "v119_mixed_contract_detected_by_v117_orchestrator",
            "ok": _agent_v2_v117_mixed_write_read(perception),
        },
        {
            "name": "v119_mixed_contract_is_self_contained_for_v118",
            "ok": _agent_v2_v118_current_turn_contract_is_self_contained(perception, {}),
        },
    ])
    return {
        "ok": all(bool(item.get("ok")) for item in results),
        "results": results,
        "count": len(results),
    }



# ============================================================================
# V120 — EFFECT-ISOLATED MULTI-SUBINTENT VERIFICATION
# ============================================================================
# Hallazgo del log real V119:
#   - El auditor recompuso correctamente el turno mixto.
#   - El mismo Semantic Effect Verifier recibió WRITE + READ juntos.
#   - Aunque proposed_writes=1, devolvió verified_ops=['query_event'] y borró
#     create_booking antes del semantic freeze.
#
# Principio V120:
#   1) El significado multi-subintención ya pertenece a Perception/Coverage.
#   2) El Effect Verifier NO debe volver a elegir qué subintenciones existen.
#   3) Cuando coexisten WRITE + READ, el WRITE se verifica en una rama aislada.
#   4) Los READs del mismo frame se preservan sin poder otorgar autoridad WRITE.
#   5) Sólo si TODOS los WRITEs aislados quedan autorizados se recomponen ambas
#      ramas. Si no, el WRITE sigue fail-closed y sobreviven únicamente READs.
#
# No hay regex ni keywords de intención. Esta capa opera exclusivamente sobre
# Semantic Acts estructurados ya producidos por los pilares anteriores.

AGENT_V2_UNIFIED_AGENTIC_CORE = "v120"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v120"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_effect_isolated_multi_subintent_v120"


def _agent_v2_v120_semantic_acts(perception: Dict[str, Any]) -> List[Dict[str, Any]]:
    frame = _agent_v2_semantic_frame(perception or {})
    return [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]


def _agent_v2_v120_split_effect_frame(
    perception: Dict[str, Any],
    *,
    keep_writes: bool,
) -> Dict[str, Any]:
    """Proyecta el SemanticFrame por efecto sin reinterpretar lenguaje."""
    import copy

    clean = copy.deepcopy(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]

    selected = []
    for act in acts:
        op = _agent_v2_semantic_operation_alias(act.get("operation"))
        is_write = op in AGENT_V2_WRITE_OPERATIONS
        if is_write == keep_writes:
            item = dict(act)
            item["operation"] = op
            selected.append(item)

    frame["acts"] = selected
    frame["targets"] = [
        dict(act.get("target") or {})
        for act in selected
        if isinstance(act.get("target"), dict)
    ]
    frame["requested_facts"] = list(dict.fromkeys(
        str(fact)
        for act in selected
        for fact in (act.get("requested_facts") or [])
        if str(fact or "").strip()
    ))
    frame["source"] = "ai"
    frame["schema_valid"] = True
    clean["semantic_frame"] = frame

    # Un contrato viejo jamás gobierna esta proyección de Effect Verification.
    # El contrato autoritativo definitivo se recompila downstream desde el frame
    # recombinado, salvo en la segunda pasada V119 donde ya se preserva el freeze.
    if isinstance(clean.get("execution_contract"), dict) and not clean["execution_contract"].get("frozen"):
        clean.pop("execution_contract", None)
    clean.pop("semantic_effect_verification", None)
    return clean


def _agent_v2_v120_authorized_write_ids(perception: Dict[str, Any]) -> set:
    verification = (
        (perception or {}).get("semantic_effect_verification")
        if isinstance((perception or {}).get("semantic_effect_verification"), dict)
        else {}
    )
    return {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict)
        and item.get("authorized", True) is not False
        and str(item.get("act_id") or "").strip()
    }


def _agent_v2_v120_recompose_verified_effects(
    original: Dict[str, Any],
    verified_write_branch: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Recompone WRITE verificado + READ original, manteniendo autoridad separada."""
    import copy

    original_acts = _agent_v2_v120_semantic_acts(original)
    original_reads = [
        dict(act) for act in original_acts
        if _agent_v2_semantic_operation_alias(act.get("operation")) not in AGENT_V2_WRITE_OPERATIONS
    ]
    original_writes = [
        dict(act) for act in original_acts
        if _agent_v2_semantic_operation_alias(act.get("operation")) in AGENT_V2_WRITE_OPERATIONS
    ]

    write_frame = _agent_v2_semantic_frame(verified_write_branch or {})
    verified_writes = [
        dict(act) for act in (write_frame.get("acts") or [])
        if isinstance(act, dict)
        and _agent_v2_semantic_operation_alias(act.get("operation")) in AGENT_V2_WRITE_OPERATIONS
    ]
    authorized_ids = _agent_v2_v120_authorized_write_ids(verified_write_branch)

    expected_ids = {
        str(act.get("act_id") or "").strip()
        for act in original_writes
        if str(act.get("act_id") or "").strip()
    }
    verified_ids = {
        str(act.get("act_id") or "").strip()
        for act in verified_writes
        if str(act.get("act_id") or "").strip()
    }

    # Seguridad: sólo recomponemos el WRITE si el verificador aislado conservó
    # todos los actos transaccionales y todos tienen autorización real.
    writes_ok = bool(original_writes)
    if expected_ids:
        writes_ok = writes_ok and expected_ids.issubset(verified_ids) and expected_ids.issubset(authorized_ids)
    else:
        # Compatibilidad defensiva con acts antiguos sin act_id: exige misma
        # cantidad y al menos una autorización emitida por el verifier.
        writes_ok = writes_ok and len(verified_writes) == len(original_writes) and bool(authorized_ids)

    if not writes_ok:
        # Fail-closed: nunca restaurar un WRITE que el branch verifier no autorizó.
        fallback = copy.deepcopy(verified_write_branch or original or {})
        frame = dict(_agent_v2_semantic_frame(fallback) or {})
        frame["acts"] = original_reads
        frame["targets"] = [
            dict(act.get("target") or {}) for act in original_reads
            if isinstance(act.get("target"), dict)
        ]
        frame["requested_facts"] = list(dict.fromkeys(
            str(fact)
            for act in original_reads
            for fact in (act.get("requested_facts") or [])
            if str(fact or "").strip()
        ))
        frame["source"] = "ai"
        frame["schema_valid"] = True
        fallback["semantic_frame"] = frame
        fallback["semantic_effect_verification"] = {
            "status": "verified",
            "mode": "v120_mixed_write_failed_closed",
            "write_authorizations": [],
            "verified_operations": [
                str(act.get("operation") or "") for act in original_reads
            ],
        }
        print(
            "   🧱 [AgentV2 V120 EFFECT ISOLATION] "
            "WRITE aislado no obtuvo autoridad completa → fail-closed; READs preservados"
        )
        return fallback

    merged = copy.deepcopy(verified_write_branch or original or {})
    merged_frame = dict(_agent_v2_semantic_frame(merged) or {})

    # Deduplicación por act_id y por firma semántica para no repetir READs.
    combined: List[Dict[str, Any]] = []
    seen_ids = set()
    seen_signatures = set()
    for act in list(verified_writes) + list(original_reads):
        item = dict(act)
        item["operation"] = _agent_v2_semantic_operation_alias(item.get("operation"))
        act_id = str(item.get("act_id") or "").strip()
        signature = _agent_v2_semantic_coverage_signature(item)
        if act_id and act_id in seen_ids:
            continue
        if signature in seen_signatures:
            continue
        if act_id:
            seen_ids.add(act_id)
        seen_signatures.add(signature)
        combined.append(item)

    merged_frame["acts"] = combined
    merged_frame["targets"] = [
        dict(act.get("target") or {})
        for act in combined
        if isinstance(act.get("target"), dict)
    ]
    merged_frame["requested_facts"] = list(dict.fromkeys(
        str(fact)
        for act in combined
        for fact in (act.get("requested_facts") or [])
        if str(fact or "").strip()
    ))
    merged_frame["source"] = "ai"
    merged_frame["schema_valid"] = True
    merged["semantic_frame"] = merged_frame

    # Canonicalización sólo de READs; no vuelve a decidir autoridad de WRITE.
    merged = _agent_v2_canonicalize_semantic_reads(merged, mensaje)

    verification = dict(
        (verified_write_branch or {}).get("semantic_effect_verification") or {}
    )
    verification["status"] = "verified"
    verification["mode"] = "v120_effect_isolated_mixed_turn"
    verification["verified_operations"] = [
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(merged).get("acts") or [])
        if isinstance(act, dict)
    ]
    verification["mixed_read_count"] = len(original_reads)
    verification["mixed_write_count"] = len(verified_writes)
    merged["semantic_effect_verification"] = verification

    # Cualquier contrato no congelado construido antes de esta recomposición ya
    # es stale. Downstream lo volverá a construir desde el frame final.
    contract = merged.get("execution_contract")
    if isinstance(contract, dict) and not contract.get("frozen"):
        merged.pop("execution_contract", None)

    print(
        "   🧩 [AgentV2 V120 EFFECT ISOLATION] "
        f"write_ops={[a.get('operation') for a in verified_writes]} "
        f"read_ops={[a.get('operation') for a in original_reads]} "
        "→ recomposición monotónica"
    )
    return merged


_agent_v2_verify_semantic_effects_v120_base = _agent_v2_verify_semantic_effects


async def _agent_v2_verify_semantic_effects(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    # La segunda pasada de V119 sobre un contrato ya congelado conserva su
    # comportamiento monotónico intacto.
    if _agent_v2_v119_frozen_verified_write_contract(perception, world or {}):
        return await _agent_v2_verify_semantic_effects_v120_base(
            mensaje, perception, world or {}
        )

    acts = _agent_v2_v120_semantic_acts(perception)
    writes = [
        act for act in acts
        if _agent_v2_semantic_operation_alias(act.get("operation")) in AGENT_V2_WRITE_OPERATIONS
    ]
    reads = [
        act for act in acts
        if _agent_v2_semantic_operation_alias(act.get("operation")) not in AGENT_V2_WRITE_OPERATIONS
        and _agent_v2_v119_is_read_operation(act.get("operation"))
    ]

    if not writes or not reads:
        return await _agent_v2_verify_semantic_effects_v120_base(
            mensaje, perception, world or {}
        )

    # Verificación por efecto: el verifier ve únicamente WRITEs, por lo que un
    # query_event/query_price/query_policy concurrente no puede reemplazarlos.
    write_branch = _agent_v2_v120_split_effect_frame(
        perception, keep_writes=True
    )
    verified_write_branch = await _agent_v2_verify_semantic_effects_v120_base(
        mensaje, write_branch, world or {}
    )
    return _agent_v2_v120_recompose_verified_effects(
        perception,
        verified_write_branch,
        mensaje,
        world or {},
    )


# ---------------------------------------------------------------------------
# Postcondición V120: un turno mixto autorizado debe llegar intacto al compiler.
# ---------------------------------------------------------------------------
_percibir_turno_agent_v2_v120_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    clean = await _percibir_turno_agent_v2_v120_base(
        mensaje, world, image_path, learning_policy
    )
    acts = _agent_v2_v120_semantic_acts(clean)
    write_ops = [
        str(act.get("operation") or "") for act in acts
        if str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
    ]
    read_ops = [
        str(act.get("operation") or "") for act in acts
        if _agent_v2_v119_is_read_operation(act.get("operation"))
    ]
    verification = (
        clean.get("semantic_effect_verification")
        if isinstance(clean.get("semantic_effect_verification"), dict)
        else {}
    )
    auth_ids = _agent_v2_v120_authorized_write_ids(clean)

    if write_ops and read_ops and auth_ids:
        clean = dict(clean)
        clean["_v120_effect_isolated_mixed_turn"] = True
        clean["pending_relation"] = "new_request"
        clean = _agent_v2_v100_attach_desired_state_and_task_graph(clean, world or {})
        print(
            "   🔒 [AgentV2 V120 MIXED POSTCONDITION] "
            f"writes={write_ops} reads={read_ops} auth={sorted(auth_ids)}"
        )
    elif verification.get("mode") == "v120_effect_isolated_mixed_turn" and write_ops and not auth_ids:
        # Defensa imposible-en-condiciones-normales: no dejar un WRITE vivo si
        # por algún wrapper posterior desaparecieron sus autorizaciones.
        frame = dict(_agent_v2_semantic_frame(clean) or {})
        frame["acts"] = [
            act for act in (frame.get("acts") or [])
            if isinstance(act, dict)
            and str(act.get("operation") or "") not in AGENT_V2_WRITE_OPERATIONS
        ]
        clean = dict(clean)
        clean["semantic_frame"] = frame
        print(
            "   🧱 [AgentV2 V120 POSTCONDITION] WRITE sin authorization desaparecida → fail-closed"
        )
    return clean


