_run_agent_v2_invariant_evals_v121_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v121_base()
    results = list(result.get("results") or [])

    message = "Me gustaria reservar a las 18 mañana y saber sobre torneo"
    missing_write = {
        "operation": "create_booking",
        "domain": "booking",
        "target": {"resource": "court"},
        "temporal": {"day": "2026-09-22", "start": "18:00"},
        "quantity": {"duration_hours": 1.0},
        "requested_facts": [],
        "question_domains": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "request_evidence": "reservar a las 18 mañana",
    }
    missing_read = {
        "operation": "query_event",
        "domain": "event_registration",
        "target": {"resource": "event"},
        "temporal": {},
        "quantity": {},
        "requested_facts": ["event.general_information"],
        "question_domains": ["event_registration"],
        "commitment": {"wants_write": False, "wants_information": True},
        "request_evidence": "saber sobre torneo",
    }

    grounded_write = _agent_v2_v121_ground_coverage_candidate(message, missing_write)
    grounded_read = _agent_v2_v121_ground_coverage_candidate(message, missing_read)

    results.extend([
        {
            "name": "v121_coverage_keeps_grounded_missing_write_for_effect_verifier",
            "passed": bool(
                grounded_write
                and grounded_write.get("operation") == "create_booking"
                and grounded_write.get("coverage_write_pending_effect") is True
                and grounded_write.get("coverage_authority") == "candidate_only"
            ),
        },
        {
            "name": "v121_coverage_keeps_grounded_missing_read",
            "passed": bool(
                grounded_read
                and grounded_read.get("operation") == "query_event"
                and grounded_read.get("coverage_authority") == "grounded_read"
            ),
        },
        {
            "name": "v121_write_candidate_never_claims_execution_authority",
            "passed": bool(
                grounded_write
                and grounded_write.get("coverage_authority") != "authorized_write"
            ),
        },
    ])

    passed = sum(1 for item in results if item.get("passed"))
    total = len(results)
    return {"passed": passed, "total": total, "results": results}

# ============================================================================
# V123 — LEGACY MULTI-SUBINTENT ORCHESTRATION BRIDGE
# ============================================================================
# Hallazgo de producción V122:
#   - El pilar Perception/Coverage moderno todavía puede reducir un mensaje con
#     varias obligaciones a un único act antes de Planner (ej. query_event),
#     aunque el mensaje también contenga una reserva explícita.
#   - El legacy ya resolvía este problema de forma más robusta: primero llamaba
#     detectar_multiples_intenciones(), procesaba cada fragmento independientemente
#     y al final enviaba UNA sola respuesta.
#
# Principio V123:
#   1) Reutilizar el descomponedor semántico legacy (LLM, no regex/keywords).
#   2) Si existe más de una subintención real, ejecutar CADA fragmento mediante
#      el pipeline Agent V2 completo, secuencialmente y sin enviar respuestas
#      parciales al cliente.
#   3) Cada WRITE sigue pasando por Semantic Effect / Policy / Tools de Agent V2;
#      el bridge no concede autoridad transaccional.
#   4) Unir TODAS las respuestas parciales en un único mensaje de WhatsApp.
#      La unión es lossless/determinista para que ninguna subintención desaparezca.
#   5) Las notificaciones a admins siguen ejecutándose DESPUÉS del único mensaje
#      al cliente, usando las observations agregadas de todos los subturnos.
#
# Esto elimina la dependencia de que un único semantic_frame.acts sea perfecto
# para poder satisfacer varias obligaciones independientes del mismo mensaje.

AGENT_V2_UNIFIED_AGENTIC_CORE = "v123"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v123"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_legacy_multi_subintent_bridge_v123"


def _agent_v2_v123_normalize_fragment(text: Any) -> str:
    return " ".join(str(text or "").split()).casefold()


def _agent_v2_v123_prepare_subintents(items: Any, original_message: str) -> List[Dict[str, str]]:
    """Normaliza la salida del descomponedor legacy sin inferir intención por texto.

    Sólo usa los campos estructurados ``intencion`` + ``fragmento`` que ya produjo
    la IA. No hay regex ni clasificación determinista del mensaje del usuario.
    """
    prepared: List[Dict[str, str]] = []
    seen = set()
    for raw in (items or []):
        if not isinstance(raw, dict):
            continue
        intent = str(raw.get("intencion") or "otra").strip() or "otra"
        fragment = str(raw.get("fragmento") or "").strip()
        if not fragment:
            fragment = str(original_message or "").strip()
        if not fragment:
            continue
        # Dedupe únicamente representacional: mismo intent + mismo fragmento.
        # No fusiona dos intents diferentes aunque compartan texto.
        signature = (intent.casefold(), _agent_v2_v123_normalize_fragment(fragment))
        if signature in seen:
            continue
        seen.add(signature)
        prepared.append({"intencion": intent, "fragmento": fragment})
    return prepared


def _agent_v2_v123_unique_responses(parts: List[Dict[str, Any]]) -> List[str]:
    """Deduplica respuestas idénticas sin perder bloques complementarios."""
    out: List[str] = []
    seen = set()
    for item in parts or []:
        if not isinstance(item, dict):
            continue
        text = str(item.get("response") or "").strip()
        if not text:
            continue
        key = _agent_v2_v123_normalize_fragment(text)
        if key in seen:
            continue
        seen.add(key)
        out.append(text)
    return out


def _agent_v2_v123_lossless_single_response(parts: List[Dict[str, Any]]) -> str:
    """Una sola respuesta sin permitir que el compositor elimine subintenciones.

    Cada bloque ya fue compuesto/validado por Agent V2 para SU fragmento. El bridge
    sólo los concatena con una línea en blanco. Esto reproduce la propiedad útil
    del legacy (respuestas_pendientes -> un único send_message) sin volver a pedir
    a otra IA que elija cuál intención "gana".
    """
    responses = _agent_v2_v123_unique_responses(parts)
    return "\n\n".join(responses).strip()


def _agent_v2_v123_merge_goal_payload(subresults: List[Dict[str, Any]]) -> Dict[str, Any]:
    goals: List[Dict[str, Any]] = []
    seen = set()
    for result in subresults or []:
        payload = result.get("goals") if isinstance(result, dict) else None
        if not isinstance(payload, dict):
            continue
        for goal in (payload.get("goals") or []):
            if not isinstance(goal, dict):
                continue
            key = str(goal.get("goal") or "").strip()
            if not key or key in seen:
                continue
            seen.add(key)
            goals.append(dict(goal))
    primary = goals[0].get("goal") if goals else "otro"
    return {
        "primary_goal": primary,
        "goals": goals,
        "multi_subintent": len(subresults or []) > 1,
    }


def _agent_v2_v123_merge_plan_payload(subresults: List[Dict[str, Any]]) -> Dict[str, Any]:
    steps: List[Dict[str, Any]] = []
    for result in subresults or []:
        plan = result.get("plan") if isinstance(result, dict) else None
        if not isinstance(plan, dict):
            continue
        steps.extend(
            dict(step) for step in (plan.get("steps") or [])
            if isinstance(step, dict)
        )
    return {
        "steps": steps,
        "done_if": "todas las subintenciones descompuestas fueron ejecutadas por Agent V2",
        "reason": "V123 legacy semantic decomposition -> independent Agent V2 subturns -> single response",
    }


_ejecutar_agente_real_v2_turno_v123_base = ejecutar_agente_real_v2_turno


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """V123: descompone multi-intent como legacy y ejecuta cada fragmento en V2.

    La descomposición no ejecuta writes. Cada fragmento vuelve a entrar al Agent V2
    completo, por lo que Semantic Effect / ExecutionContract / Policy siguen siendo
    la única autoridad de escritura.
    """
    # Los runners/evals inyectan semántica deliberadamente y deben conservar el
    # camino exacto que están evaluando.
    if isinstance(eval_context, dict) and eval_context:
        return await _ejecutar_agente_real_v2_turno_v123_base(
            mensaje, conv_state, prospecto, telefono,
            user_messages=user_messages, page=page, image_path=image_path,
            dry_run=dry_run, eval_context=eval_context,
        )

    try:
        detected = await detectar_multiples_intenciones(str(mensaje or ""))
        subintents = _agent_v2_v123_prepare_subintents(detected, mensaje)
    except Exception as exc:
        print(f"   ⚠️ [AgentV2 V123 MULTI-INTENT BRIDGE] detector legacy no disponible: {exc}")
        subintents = []

    if len(subintents) <= 1:
        return await _ejecutar_agente_real_v2_turno_v123_base(
            mensaje, conv_state, prospecto, telefono,
            user_messages=user_messages, page=page, image_path=image_path,
            dry_run=dry_run, eval_context=eval_context,
        )

    print(
        "   🧩 [AgentV2 V123 LEGACY MULTI-INTENT BRIDGE] "
        f"subintenciones={len(subintents)} "
        f"intents={[item.get('intencion') for item in subintents]}"
    )

    partials: List[Dict[str, Any]] = []
    subresults: List[Dict[str, Any]] = []
    all_observations: List[Dict[str, Any]] = []
    total_llm_calls = 0

    for idx, item in enumerate(subintents, start=1):
        fragment = str(item.get("fragmento") or "").strip()
        intent = str(item.get("intencion") or "otra").strip()
        if not fragment:
            continue

        print(
            "   🔀 [AgentV2 V123 SUBTURN] "
            f"{idx}/{len(subintents)} intent={intent} fragment={fragment[:120]!r}"
        )

        # Rehidratar estado entre subturnos para que un WRITE previo sea visible
        # al siguiente fragmento sin inventar una respuesta assistant intermedia.
        state_now = get_conversation_state(telefono or "unknown")
        result = await _ejecutar_agente_real_v2_turno_v123_base(
            fragment,
            state_now,
            prospecto,
            telefono,
            user_messages=user_messages,
            page=page,
            image_path=image_path,
            dry_run=dry_run,
            eval_context=None,
        )
        subresults.append(result)
        total_llm_calls += int(result.get("llm_calls") or 0)
        all_observations.extend(
            dict(obs) for obs in (result.get("observations") or [])
            if isinstance(obs, dict)
        )

        response = str(result.get("response") or "").strip()
        if response:
            partials.append({
                "index": idx,
                "intent": intent,
                "fragment": fragment,
                "response": response,
                "status": result.get("status"),
                "goals": result.get("goals") or {},
                "observations": result.get("observations") or [],
            })

        # Si un subturno pausó al humano, no seguimos ejecutando acciones sobre
        # el mismo chat. Las respuestas ya obtenidas se preservan.
        if result.get("status") == "paused_human":
            break

    final_response = _agent_v2_v123_lossless_single_response(partials)

    if not final_response:
        # Defensa: si la descomposición existió pero ningún subturno produjo una
        # respuesta utilizable, ejecutar una sola vez el mensaje original evita
        # devolver vacío. Esto sólo ocurre antes de enviar nada al cliente.
        return await _ejecutar_agente_real_v2_turno_v123_base(
            mensaje,
            get_conversation_state(telefono or "unknown"),
            prospecto,
            telefono,
            user_messages=user_messages,
            page=page,
            image_path=image_path,
            dry_run=dry_run,
            eval_context=None,
        )

    print(
        "   🧩 [AgentV2 V123 SINGLE RESPONSE] "
        f"partials={len(partials)} observations={len(all_observations)} "
        "→ un único mensaje con todas las subintenciones"
    )

    last = subresults[-1] if subresults else {}
    merged_goals = _agent_v2_v123_merge_goal_payload(subresults)
    merged_plan = _agent_v2_v123_merge_plan_payload(subresults)

    # `handled=True` evita caer al executor legacy después de haber ejecutado
    # writes V2. Las observations agregadas permiten que las alertas post-response
    # se disparen una sola vez, después del único mensaje al cliente.
    return {
        "handled": True,
        "delegate_legacy": False,
        "response": final_response,
        "world": last.get("world") or {},
        "perception": {
            "source": "v123_legacy_multi_intent_bridge",
            "subintents": subintents,
            "subperceptions": [
                result.get("perception") or {} for result in subresults
            ],
        },
        "goals": merged_goals,
        "plan": merged_plan,
        "observations": all_observations,
        "status": (
            "paused_human"
            if any(result.get("status") == "paused_human" for result in subresults)
            else "complete"
        ),
        "next_best_action": last.get("next_best_action") or {},
        "safe_exit": last.get("safe_exit") or {},
        "llm_calls": total_llm_calls,
        "multi_subintent_bridge": {
            "version": "v123",
            "subintent_count": len(subintents),
            "partial_response_count": len(partials),
            "all_subintent_responses_preserved": True,
        },
    }


# ---------------------------------------------------------------------------
# Invariantes V123 (sin API / sin WhatsApp)
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v123_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v123_base()
    results = list(result.get("results") or [])

    synthetic = [
        {"intencion": "reservar_cancha", "fragmento": "Me gustaria reservar a las 18 mañana"},
        {"intencion": "consulta_informativa", "fragmento": "saber sobre torneo"},
    ]
    prepared = _agent_v2_v123_prepare_subintents(
        synthetic,
        "Me gustaria reservar a las 18 mañana y saber sobre torneo",
    )
    merged = _agent_v2_v123_lossless_single_response([
        {"response": "✅ Reserva procesada para mañana a las 18:00."},
        {"response": "🏆 Copa Primavera: inscripción $15.000."},
    ])

    results.extend([
        {
            "name": "v123_legacy_decomposer_preserves_two_independent_subintents",
            "passed": bool(
                len(prepared) == 2
                and prepared[0].get("intencion") == "reservar_cancha"
                and prepared[1].get("intencion") == "consulta_informativa"
            ),
        },
        {
            "name": "v123_single_response_is_lossless_for_booking_and_event",
            "passed": bool(
                "Reserva procesada" in merged
                and "Copa Primavera" in merged
                and merged.count("\n\n") == 1
            ),
        },
    ])

    passed = sum(1 for item in results if item.get("passed"))
    total = len(results)
    # Compatibilidad: la CLI histórica inspecciona `ok`.
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }



# ============================================================================
# V124 — SAME-TURN CONTINUATION PRESERVATION + DYNAMIC PENDING ANSWERS
# ============================================================================
# Hallazgo de producción V123:
#   - La descomposición multi-subintent ya funciona.
#   - Un subturno puede quedar waiting_user (p.ej. preguntar resource_type).
#   - V123 seguía ejecutando subturnos hermanos del MISMO mensaje y al final
#     devolvía status=complete + world/next_action del último READ.
#   - Ese subturno hermano podía mover/suspender ConversationFrame y dejar el
#     BookingObjective fuera del camino dinámico V105.
#   - En el siguiente mensaje, una respuesta humana elíptica ("futbol") ya no
#     llegaba al PENDING BOOKING SLOT RESOLVER; Perception la trataba como FAQ.
#
# Principio V124:
#   1) Los subturnos hermanos pertenecen al MISMO turno del usuario.
#   2) Si uno abre una PendingInteraction, los siblings posteriores pueden
#      responder otras subintenciones, pero NO pueden invalidar esa continuación.
#   3) Se preservan de forma estructurada question_id/scope/action_snapshot/
#      booking_objective y se restauran al terminar el batch.
#   4) El resultado agregado conserva status=waiting_user y toma como anchor
#      conversacional el subturno que realmente espera respuesta.
#   5) El lenguaje libre de la respuesta sigue siendo entendido por V105
#      PENDING BOOKING SLOT RESOLVER (IA). V124 no agrega regex/keywords.
#   6) Restaurar continuidad NO autoriza writes: V105 todavía debe reconstruir
#      el objetivo y pasar Semantic Effect / ExecutionContract / Policy.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v124"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v124"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_same_turn_continuation_v124"


def _agent_v2_v124_waiting_result(result: Dict[str, Any]) -> bool:
    if not isinstance(result, dict):
        return False
    if str(result.get("status") or "") in {"waiting_user", "needs_user_input"}:
        return True
    return any(
        isinstance(obs, dict)
        and str(obs.get("tool") or "") == "solicitar_dato"
        and str(obs.get("status") or "") == "needs_user_input"
        for obs in (result.get("observations") or [])
    )


def _agent_v2_v124_asked_fields(result: Dict[str, Any]) -> List[str]:
    """Campos realmente preguntados por ESTE subturno; no interpreta lenguaje."""
    fields: List[str] = []
    plan = result.get("plan") if isinstance(result, dict) else {}
    if isinstance(plan, dict):
        for step in (plan.get("steps") or []):
            if not isinstance(step, dict) or str(step.get("tool") or "") != "solicitar_dato":
                continue
            args = step.get("args") if isinstance(step.get("args"), dict) else {}
            field = str(args.get("campo") or args.get("field") or "").strip()
            if field and field not in fields:
                fields.append(field)
    for obs in ((result or {}).get("observations") or []):
        if not isinstance(obs, dict) or str(obs.get("tool") or "") != "solicitar_dato":
            continue
        data = obs.get("data") if isinstance(obs.get("data"), dict) else {}
        field = str(data.get("campo") or data.get("field") or "").strip()
        if field and field not in fields:
            fields.append(field)
    return fields


def _agent_v2_v124_capture_continuation(
    telefono: str,
    result: Dict[str, Any],
) -> Dict[str, Any]:
    """Captura sólo la continuación abierta por el subturno waiting_user."""
    if not _agent_v2_v124_waiting_result(result):
        return {}

    fields = set(_agent_v2_v124_asked_fields(result))
    state = get_conversation_state(telefono or "unknown")
    av2 = _agent_v2_state(state or {})
    cf = _agent_v2_v100_conversation_frame(av2)

    open_questions = [
        dict(q)
        for q in (av2.get("open_questions") or [])
        if isinstance(q, dict)
        and (
            not fields
            or str(q.get("field") or q.get("type") or "").strip() in fields
        )
    ]
    qids = {
        str(q.get("question_id") or "").strip()
        for q in open_questions
        if str(q.get("question_id") or "").strip()
    }

    interactions = [
        dict(item)
        for item in (cf.get("pending_interactions") or [])
        if isinstance(item, dict)
        and (
            str(item.get("question_id") or "").strip() in qids
            or (
                not qids
                and (
                    not fields
                    or str(item.get("field") or "").strip() in fields
                )
            )
        )
    ]

    objective = (
        dict(cf.get("booking_objective") or {})
        if isinstance(cf.get("booking_objective"), dict)
        else {}
    )
    if objective and str(objective.get("status") or "active") not in {
        "active", "collecting", "ready", "preflight"
    }:
        objective = {}

    scope_id = ""
    if open_questions:
        scope_id = str(open_questions[-1].get("scope_id") or "").strip()
    if not scope_id and interactions:
        scope_id = str(interactions[-1].get("scope_id") or "").strip()
    if not scope_id:
        scope_id = str(av2.get("active_scope_id") or "").strip()

    snapshot = {
        "fields": sorted(fields),
        "question_ids": sorted(qids),
        "open_questions": open_questions,
        "pending_interactions": interactions,
        "booking_objective": objective,
        "focus": (
            dict(cf.get("focus") or {})
            if isinstance(cf.get("focus"), dict)
            else {}
        ),
        "active_scope_id": scope_id,
        "captured_at": datetime.datetime.now(TIMEZONE).isoformat(),
    }
    return snapshot if (open_questions or interactions or objective) else {}


def _agent_v2_v124_merge_by_identity(
    current: List[Dict[str, Any]],
    preserved: List[Dict[str, Any]],
    *,
    primary_key: str,
) -> List[Dict[str, Any]]:
    """Merge estructural estable; el preserved actual reemplaza su versión sibling."""
    out: List[Dict[str, Any]] = [
        dict(item) for item in (current or []) if isinstance(item, dict)
    ]

    def identity(item: Dict[str, Any]) -> Tuple[str, str, str]:
        primary = str(item.get(primary_key) or "").strip()
        qid = str(item.get("question_id") or "").strip()
        field = str(item.get("field") or item.get("type") or "").strip()
        scope = str(item.get("scope_id") or "").strip()
        return primary or qid, field, scope

    for raw in (preserved or []):
        if not isinstance(raw, dict):
            continue
        item = dict(raw)
        ident = identity(item)
        out = [
            existing
            for existing in out
            if identity(existing) != ident
            and not (
                ident[0]
                and str(existing.get("question_id") or "").strip() == str(item.get("question_id") or "").strip()
            )
        ]
        out.append(item)
    return out


def _agent_v2_v124_restore_continuations(
    telefono: str,
    snapshots: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Restaura el formulario conversacional abierto por siblings del mismo turno."""
    rows = [row for row in (snapshots or []) if isinstance(row, dict) and row]
    if not rows:
        return get_conversation_state(telefono or "unknown")

    current = get_conversation_state(telefono or "unknown")
    av2 = _agent_v2_state(current or {})
    cf = _agent_v2_v100_conversation_frame(av2)

    preserved_questions: List[Dict[str, Any]] = []
    preserved_interactions: List[Dict[str, Any]] = []
    preserved_objective: Dict[str, Any] = {}
    preserved_focus: Dict[str, Any] = {}
    preserved_availability: Dict[str, Any] = {}
    preserved_scope = ""

    for row in rows:
        preserved_questions.extend(
            dict(q) for q in (row.get("open_questions") or [])
            if isinstance(q, dict)
        )
        preserved_interactions.extend(
            dict(item) for item in (row.get("pending_interactions") or [])
            if isinstance(item, dict)
        )
        objective = row.get("booking_objective")
        if isinstance(objective, dict) and objective:
            preserved_objective = dict(objective)
        focus = row.get("focus")
        if isinstance(focus, dict) and focus:
            preserved_focus = dict(focus)
        availability = row.get("availability_context")
        if isinstance(availability, dict) and availability:
            preserved_availability = dict(availability)
        scope = str(row.get("active_scope_id") or "").strip()
        if scope:
            preserved_scope = scope

    av2["open_questions"] = _agent_v2_v124_merge_by_identity(
        list(av2.get("open_questions") or []),
        preserved_questions,
        primary_key="question_id",
    )
    cf["pending_interactions"] = _agent_v2_v124_merge_by_identity(
        list(cf.get("pending_interactions") or []),
        preserved_interactions,
        primary_key="interaction_id",
    )

    if preserved_objective:
        cf["booking_objective"] = preserved_objective
    if preserved_focus:
        cf["focus"] = preserved_focus
    if preserved_availability:
        av2["availability_context"] = preserved_availability
    if preserved_scope:
        av2["active_scope_id"] = preserved_scope

    cf["version"] = AGENT_V2_UNIFIED_CONVERSATION_KERNEL
    av2["conversation_frame"] = cf
    av2["version"] = AGENT_V2_VERSION
    update_conversation_state(telefono or "unknown", agent_v2=av2)

    fields = sorted({
        str(q.get("field") or q.get("type") or "").strip()
        for q in preserved_questions
        if isinstance(q, dict) and str(q.get("field") or q.get("type") or "").strip()
    })
    qids = sorted({
        str(q.get("question_id") or "").strip()
        for q in preserved_questions
        if isinstance(q, dict) and str(q.get("question_id") or "").strip()
    })
    print(
        "   🔗 [AgentV2 V124 SAME-TURN CONTINUATION] "
        f"restored_fields={fields} question_ids={qids} "
        f"booking_objective={str(preserved_objective.get('objective_id') or '-')}"
    )
    return get_conversation_state(telefono or "unknown")


def _agent_v2_v124_aggregate_status(subresults: List[Dict[str, Any]]) -> str:
    rows = [row for row in (subresults or []) if isinstance(row, dict)]
    if any(str(row.get("status") or "") == "paused_human" for row in rows):
        return "paused_human"
    # Un hold creado en este mismo lote es el resultado conversacional terminal.
    # No debe quedar degradado a ``waiting_user`` porque otro sibling, ya
    # obsoleto, haya vuelto a preguntar un slot que el BookingObjective posee.
    if any(
        isinstance(obs, dict)
        and str(obs.get("tool") or "") == "crear_reserva"
        and obs.get("ok") is True
        and str(obs.get("status") or "") in {"success", "already_exists"}
        for row in rows
        for obs in (row.get("observations") or [])
    ):
        return "complete"
    if any(_agent_v2_v124_waiting_result(row) for row in rows):
        return "waiting_user"
    return "complete"


def _agent_v2_v124_continuation_anchor(
    subresults: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """El resultado waiting_user gobierna continuidad aunque un READ sibling termine después."""
    rows = [row for row in (subresults or []) if isinstance(row, dict)]
    waiting = [row for row in rows if _agent_v2_v124_waiting_result(row)]
    if waiting:
        return waiting[-1]
    return rows[-1] if rows else {}


_ejecutar_agente_real_v2_turno_v124_base = _ejecutar_agente_real_v2_turno_v123_base


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """V124: multi-subintent lossless + continuidad stateful del mismo turno."""
    if isinstance(eval_context, dict) and eval_context:
        return await _ejecutar_agente_real_v2_turno_v124_base(
            mensaje, conv_state, prospecto, telefono,
            user_messages=user_messages, page=page, image_path=image_path,
            dry_run=dry_run, eval_context=eval_context,
        )

    try:
        detected = await detectar_multiples_intenciones(str(mensaje or ""))
        subintents = _agent_v2_v123_prepare_subintents(detected, mensaje)
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V124 MULTI-INTENT] "
            f"detector legacy no disponible: {type(exc).__name__}: {exc}"
        )
        subintents = []

    if len(subintents) <= 1:
        return await _ejecutar_agente_real_v2_turno_v124_base(
            mensaje, conv_state, prospecto, telefono,
            user_messages=user_messages, page=page, image_path=image_path,
            dry_run=dry_run, eval_context=eval_context,
        )

    print(
        "   🧩 [AgentV2 V124 MULTI-INTENT SAME TURN] "
        f"subintenciones={len(subintents)} "
        f"intents={[item.get('intencion') for item in subintents]}"
    )

    partials: List[Dict[str, Any]] = []
    subresults: List[Dict[str, Any]] = []
    all_observations: List[Dict[str, Any]] = []
    continuation_snapshots: List[Dict[str, Any]] = []
    total_llm_calls = 0

    for idx, item in enumerate(subintents, start=1):
        fragment = str(item.get("fragmento") or "").strip()
        intent = str(item.get("intencion") or "otra").strip()
        if not fragment:
            continue

        print(
            "   🔀 [AgentV2 V124 SUBTURN] "
            f"{idx}/{len(subintents)} intent={intent} fragment={fragment[:120]!r}"
        )

        state_now = get_conversation_state(telefono or "unknown")
        result = await _ejecutar_agente_real_v2_turno_v124_base(
            fragment,
            state_now,
            prospecto,
            telefono,
            user_messages=user_messages,
            page=page,
            image_path=image_path,
            dry_run=dry_run,
            eval_context=None,
        )
        subresults.append(result)
        total_llm_calls += int(result.get("llm_calls") or 0)
        all_observations.extend(
            dict(obs) for obs in (result.get("observations") or [])
            if isinstance(obs, dict)
        )

        response = str(result.get("response") or "").strip()
        if response:
            partials.append({
                "index": idx,
                "intent": intent,
                "fragment": fragment,
                "response": response,
                "status": result.get("status"),
                "goals": result.get("goals") or {},
                "observations": result.get("observations") or [],
            })

        if _agent_v2_v124_waiting_result(result):
            snapshot = _agent_v2_v124_capture_continuation(
                telefono or "unknown", result
            )
            if snapshot:
                continuation_snapshots.append(snapshot)
                print(
                    "   🧠 [AgentV2 V124 CONTINUATION SNAPSHOT] "
                    f"fields={snapshot.get('fields')} "
                    f"qids={snapshot.get('question_ids')} "
                    "→ siblings posteriores no pueden cerrarlo"
                )

        if str(result.get("status") or "") == "paused_human":
            break

    final_response = _agent_v2_v123_lossless_single_response(partials)
    if not final_response:
        return await _ejecutar_agente_real_v2_turno_v124_base(
            mensaje,
            get_conversation_state(telefono or "unknown"),
            prospecto,
            telefono,
            user_messages=user_messages,
            page=page,
            image_path=image_path,
            dry_run=dry_run,
            eval_context=None,
        )

    if continuation_snapshots:
        _agent_v2_v124_restore_continuations(
            telefono or "unknown",
            continuation_snapshots,
        )

    aggregate_status = _agent_v2_v124_aggregate_status(subresults)
    anchor = _agent_v2_v124_continuation_anchor(subresults)
    merged_goals = _agent_v2_v123_merge_goal_payload(subresults)
    merged_plan = _agent_v2_v123_merge_plan_payload(subresults)

    print(
        "   🧩 [AgentV2 V124 SINGLE RESPONSE] "
        f"partials={len(partials)} observations={len(all_observations)} "
        f"status={aggregate_status} continuation={'yes' if continuation_snapshots else 'no'} "
        "→ un único mensaje, contexto abierto preservado"
    )

    return {
        "handled": True,
        "delegate_legacy": False,
        "response": final_response,
        "world": anchor.get("world") or {},
        "perception": {
            "source": "v124_same_turn_multi_intent",
            "subintents": subintents,
            "subperceptions": [
                result.get("perception") or {} for result in subresults
            ],
            "continuation_preserved": bool(continuation_snapshots),
        },
        "goals": merged_goals,
        "plan": merged_plan,
        "observations": all_observations,
        "status": aggregate_status,
        "next_best_action": anchor.get("next_best_action") or {},
        "safe_exit": anchor.get("safe_exit") or {},
        "llm_calls": total_llm_calls,
        "multi_subintent_bridge": {
            "version": "v124",
            "subintent_count": len(subintents),
            "partial_response_count": len(partials),
            "all_subintent_responses_preserved": True,
            "same_user_turn": True,
            "continuation_preserved": bool(continuation_snapshots),
        },
    }


# ---------------------------------------------------------------------------
# Invariantes V124
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v124_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v124_base()
    results = list(result.get("results") or [])

    waiting = {
        "status": "waiting_user",
        "plan": {
            "steps": [{
                "tool": "solicitar_dato",
                "args": {"campo": "resource_type"},
            }]
        },
        "observations": [{
            "tool": "solicitar_dato",
            "ok": True,
            "status": "needs_user_input",
            "data": {"field": "resource_type"},
        }],
        "next_best_action": {"action": "agentic_question", "field": "resource_type"},
        "safe_exit": {"state": "one_missing_datum", "evidence": ["resource_type"]},
    }
    completed_read = {
        "status": "complete",
        "observations": [{"tool": "consultar_evento", "ok": True, "status": "success"}],
        "next_best_action": {"action": "none"},
        "safe_exit": {"state": "confirmed_fact"},
    }

    synthetic_item = {
        "question_id": "v124_q_resource_type",
        "interaction_id": "v124_i_resource_type",
        "field": "resource_type",
        "scope_id": "v124_scope",
        "question_text": "¿Qué tipo de deporte te gustaría reservar, fútbol 5, tenis o pádel?",
        "status": "active",
        "allowed_operations": ["create_booking", "query_availability"],
        "action_snapshot": {
            "operation": "create_booking",
            "target": {"resource": "court"},
            "temporal": {"day": "Martes 22/09", "start": "18:00", "duration_hours": 1.0},
        },
    }
    synthetic_world = {
        "stored_memory": {
            "history": [{
                "role": "assistant",
                "content": (
                    "¿Qué tipo de deporte te gustaría reservar, fútbol 5, tenis o pádel?\n\n"
                    "🏆 Copa Primavera"
                ),
            }],
        },
    }

    results.extend([
        {
            "name": "v124_waiting_subturn_survives_completed_read_sibling",
            "passed": (
                _agent_v2_v124_aggregate_status([waiting, completed_read])
                == "waiting_user"
            ),
        },
        {
            "name": "v124_waiting_subturn_is_continuation_anchor",
            "passed": (
                _agent_v2_v124_continuation_anchor([waiting, completed_read])
                is waiting
            ),
        },
        {
            "name": "v124_resource_type_question_is_detected_as_asked_field",
            "passed": (
                _agent_v2_v124_asked_fields(waiting) == ["resource_type"]
            ),
        },
        {
            "name": "v124_combined_assistant_response_keeps_booking_question_adjacent",
            "passed": bool(
                _agent_v2_v108_booking_interaction_is_adjacent(
                    synthetic_item,
                    synthetic_world,
                )
            ),
        },
    ])

    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }



# ============================================================================
# V124 — FINAL BOOTSTRAP MARKER
# ============================================================================
# Todas las overrides anteriores ya están definidas antes de entrar al loop.
AGENT_V2_UNIFIED_AGENTIC_CORE = "v124"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v124"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_same_turn_continuation_v124"


# ============================================================================
# V125 — SAME-TURN SIBLING BRANCH ISOLATION
# ============================================================================
# Hallazgo de producción V124:
#   - el descomponedor detectó correctamente todas las subintenciones;
#   - el primer sibling (create_booking) abrió una PendingInteraction legítima;
#   - el segundo sibling (query_event) vio esa memoria creada MILISEGUNDOS antes
#     como si viniera de un turno anterior;
#   - Conversation Manager la reinterpretó como references_previous y TaskGraph
#     Guard eliminó consultar_evento.
#
# Principio V125:
#   1) Todos los siblings del MISMO mensaje parten de la MISMA memoria pre-turno.
#   2) Cada sibling ejecuta Agent V2 completo en una rama conversacional aislada.
#   3) Los efectos externos reales de Tools (calendario/eventos/pagos) NO se
#      deshacen: sólo se aísla la memoria conversacional entre siblings.
#   4) Al terminar, se hace commit de la rama stateful con mayor prioridad:
#        paused_human > waiting_user > WRITE real > state transition > READ.
#   5) Todas las respuestas parciales se conservan y se envían juntas una sola vez.
#   6) Las continuaciones waiting_user de cualquier sibling se fusionan después
#      del commit, por question_id/scope_id, usando las garantías V124.
#
# No interpreta lenguaje con regex ni keywords. La descomposición sigue siendo
# detectar_multiples_intenciones() (IA) y cada rama vuelve a pasar por
# Perception -> Semantic Effect -> ExecutionContract -> Planner -> Policy -> Tools.
# ============================================================================

import copy as _agent_v2_v125_copy

AGENT_V2_UNIFIED_AGENTIC_CORE = "v125"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v125"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_same_turn_sibling_isolation_v125"


def _agent_v2_v125_snapshot_conversation_state(telefono: str) -> Dict[str, Any]:
    """Snapshot profundo de la memoria conversacional canónica del chat."""
    state = get_conversation_state(telefono or "unknown")
    return _agent_v2_v125_copy.deepcopy(state)


def _agent_v2_v125_replace_conversation_state(
    telefono: str,
    snapshot: Dict[str, Any],
    *,
    reason: str = "",
) -> Dict[str, Any]:
    """Reemplaza SOLO memoria conversacional; jamás revierte efectos de Tools."""
    key = _memory_owner_key(telefono or "unknown")
    if key == "unknown":
        return get_conversation_state(telefono or "unknown")

    restored = _agent_v2_v125_copy.deepcopy(snapshot or {})
    restored["_memory_owner"] = key
    restored["ultima_actualizacion"] = datetime.datetime.now(TIMEZONE)
    conversation_states[key] = restored
    _persist_conversation_states()

    if reason:
        print(
            "   🌿 [AgentV2 V125 BRANCH STATE] "
            f"restore={reason} owner={key}"
        )
    return conversation_states[key]


def _agent_v2_v125_observation_effect(obs: Dict[str, Any]) -> str:
    if not isinstance(obs, dict):
        return ""
    tool = str(obs.get("tool") or "").strip()
    spec = AGENT_V2_TOOL_CATALOG.get(tool) if isinstance(AGENT_V2_TOOL_CATALOG, dict) else {}
    return str((spec or {}).get("effect") or "").strip().lower()


def _agent_v2_v125_result_state_priority(result: Dict[str, Any]) -> int:
    """Prioridad de la rama que debe gobernar memoria después del batch."""
    if not isinstance(result, dict):
        return 0

    status = str(result.get("status") or "").strip()
    if status == "paused_human":
        return 500

    # El write terminal de la reserva gobierna el estado del lote. Antes tenía
    # prioridad 300 y una rama ``solicitar_dato`` (400) podía sobreescribir el
    # hold recién creado y resucitar una pregunta ya contestada.
    if any(
        isinstance(obs, dict)
        and str(obs.get("tool") or "") == "crear_reserva"
        and obs.get("ok") is True
        and str(obs.get("status") or "") in {"success", "already_exists"}
        for obs in (result.get("observations") or [])
    ):
        return 480
    if _agent_v2_v124_waiting_result(result):
        return 400

    observations = [
        obs for obs in (result.get("observations") or [])
        if isinstance(obs, dict)
    ]
    successful = [
        obs for obs in observations
        if bool(obs.get("ok"))
        and str(obs.get("status") or "") not in {
            "error", "policy_blocked", "needs_human_review"
        }
    ]
    effects = {
        _agent_v2_v125_observation_effect(obs)
        for obs in successful
    }
    if "write" in effects:
        return 300
    if "state" in effects:
        return 200
    return 100


def _agent_v2_v125_select_commit_branch(
    subresults: List[Dict[str, Any]],
) -> int:
    """Selecciona qué sibling conserva el foco conversacional tras el merge."""
    if not subresults:
        return -1
    scored = [
        (_agent_v2_v125_result_state_priority(result), idx)
        for idx, result in enumerate(subresults)
    ]
    return max(scored)[1]


def _agent_v2_v125_branch_summary(
    idx: int,
    item: Dict[str, Any],
    result: Dict[str, Any],
) -> Dict[str, Any]:
    observations = [
        dict(obs) for obs in (result.get("observations") or [])
        if isinstance(obs, dict)
    ]
    return {
        "index": idx,
        "intent": str(item.get("intencion") or "otra"),
        "fragment": str(item.get("fragmento") or ""),
        "status": str(result.get("status") or ""),
        "priority": _agent_v2_v125_result_state_priority(result),
        "tools": [
            str(obs.get("tool") or "")
            for obs in observations
            if str(obs.get("tool") or "")
        ],
        "effects": sorted({
            _agent_v2_v125_observation_effect(obs)
            for obs in observations
            if _agent_v2_v125_observation_effect(obs)
        }),
    }


_ejecutar_agente_real_v2_turno_v125_single_base = _ejecutar_agente_real_v2_turno_v124_base


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """V125: multi-subintent con ramas de memoria aisladas dentro del mismo turno."""
    if isinstance(eval_context, dict) and eval_context:
        return await _ejecutar_agente_real_v2_turno_v125_single_base(
            mensaje, conv_state, prospecto, telefono,
            user_messages=user_messages, page=page, image_path=image_path,
            dry_run=dry_run, eval_context=eval_context,
        )

    # El gate decide primero si el turno se vincula al pending. Si NO hay binding,
    # esa decisión sólo vuelve pasiva la memoria vieja: Perception/V125 siguen
    # siendo dueños de entender exhaustivamente todas las subintenciones nuevas.
    early_plan: Dict[str, Any] = {}
    try:
        routing_world = construir_world_state_agent_v2(
            telefono or "unknown",
            prospecto or {},
            conv_state or {},
            str(mensaje or ""),
            image_path,
        )
        early_plan = await _agent_v2_v126_resolve_dialogue_context_before_perception(
            str(mensaje or ""), routing_world
        )
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 DIALOGUE GATE] pre-routing no disponible; "
            f"continúo con V125: {type(exc).__name__}: {exc}"
        )

    if early_plan.get("status") == "verified" and not early_plan.get("bindings"):
        early_plan = dict(early_plan)
        early_plan["route_to_general_perception"] = True
        early_plan["semantic_frozen"] = False
        print(
            "   ↪️ [AgentV2 DIALOGUE GATE] relation=independent → "
            "Perception/V125 conservan cobertura exhaustiva del turno"
        )

    force_branch_reresolution = False

    async def _run_single_with_dialogue_decision(
        current_message: str,
        current_state: Dict[str, Any],
        current_eval_context: Optional[Dict[str, Any]] = None,
        dialogue_plan_override: Optional[Dict[str, Any]] = None,
        router_subintent_override: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        token = None
        router_token = None
        plan_for_subturn = (
            dialogue_plan_override
            if isinstance(dialogue_plan_override, dict)
            else early_plan
        )
        explicit_override = isinstance(dialogue_plan_override, dict)
        if (
            plan_for_subturn.get("status") == "verified"
            and (explicit_override or not force_branch_reresolution)
        ):
            token = AGENT_V2_DIALOGUE_CONTEXT_PLAN.set(plan_for_subturn)
        if isinstance(router_subintent_override, dict):
            router_token = AGENT_V2_CURRENT_ROUTER_SUBINTENT.set(
                dict(router_subintent_override)
            )
        try:
            return await _ejecutar_agente_real_v2_turno_v125_single_base(
                current_message, current_state, prospecto, telefono,
                user_messages=user_messages, page=page, image_path=image_path,
                dry_run=dry_run, eval_context=current_eval_context,
            )
        finally:
            if router_token is not None:
                AGENT_V2_CURRENT_ROUTER_SUBINTENT.reset(router_token)
            if token is not None:
                AGENT_V2_DIALOGUE_CONTEXT_PLAN.reset(token)

    try:
        detected = await detectar_multiples_intenciones(str(mensaje or ""))
        subintents = _agent_v2_v123_prepare_subintents(detected, mensaje)
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V125 MULTI-INTENT] "
            f"detector no disponible: {type(exc).__name__}: {exc}"
        )
        subintents = []

    # V126R3 — CURRENT-TURN OBLIGATION PRIORITY
    # El Dialogue Gate corre antes del router multi-intent y por eso puede ver
    # evidencia parcial (p.ej. "18") y enlazarla a un pending viejo antes de
    # descubrir que el turno completo contiene un booking NUEVO. La salida del
    # router IA es semántica estructurada, no parsing de texto; si un único
    # sibling fue clasificado inequívocamente como obligación nueva, el pending
    # histórico queda pasivo para ese sibling/turno.
    if (
        len(subintents) == 1
        and _agent_v2_v126r3_subintent_is_current_turn_independent(
            subintents[0].get("intencion")
        )
        and early_plan.get("bindings")
        and not _agent_v2_v132_should_preserve_pending_binding(
            mensaje, subintents, early_plan
        )
    ):
        stale_qids = [
            str(item.get("question_id") or "")
            for item in (early_plan.get("bindings") or [])
            if isinstance(item, dict)
        ]

        # V126R7: el pending/objetivo histórico puede quedar pasivo, pero si el
        # Dialogue Gate YA verificó que el current turn responde una pregunta
        # scoped (p.ej. hora) y esa pregunta lleva un resource_type inequívoco,
        # no se destruye esa identidad contextual. Sólo se transporta el tipo de
        # cancha; día/hora/duración/addons siguen perteneciendo al current turn.
        resource_carry = _agent_v2_v126r7_resource_carry_from_verified_plan(
            early_plan,
            routing_world,
        )

        independent_plan = _agent_v2_v126r3_independent_sibling_plan(
            1,
            1,
            str(subintents[0].get("intencion") or "otra"),
            source="v126r3_single_current_turn_obligation",
        )
        if resource_carry:
            independent_plan["verified_resource_carry"] = dict(resource_carry)

        early_plan = independent_plan
        print(
            "   🧭 [AgentV2 V126R3 CURRENT-TURN PRIORITY] "
            f"intent={subintents[0].get('intencion')} "
            f"pending_pasivo={stale_qids} "
            f"resource_carry={resource_carry.get('resource_type') if resource_carry else None}"
        )

    semantic_units = len(early_plan.get("bindings") or []) + len(
        early_plan.get("independent_acts") or []
    )
    detected_units = len(subintents)
    if early_plan.get("covers_entire_physical_turn") is True:
        # V131: varios mensajes adyacentes pueden ser fragmentos de UN valor
        # (p.ej. "ftbol" + "5"). El Dialogue Gate validó el lote completo
        # contra una opción configurada; no se lo vuelve a separar por cantidad
        # de fragmentos del router.
        semantic_units = max(semantic_units, detected_units)
    if (
        early_plan.get("status") == "verified"
        and early_plan.get("bindings")
        and detected_units > max(1, semantic_units)
    ):
        # Un binding global nunca puede apropiarse de todo un lote multi-sibling.
        # Incluso si "cantidad de unidades" coincide, pueden ser unidades de
        # significado distintas (incidente live: answers_pending(hora) +
        # query_event vs reservar_cancha + query_event). Cada sibling vuelve a
        # decidir su relación contextual desde el MISMO baseline.
        force_branch_reresolution = True
        print(
            "   🧩 [AgentV2 V126R3 SEMANTIC COVERAGE] "
            f"gate_units={semantic_units} v125_units={detected_units} "
            "→ binding global descartado; resolución aislada por sibling"
        )

    # Un binding completo es un TurnSemanticPlan; no hace falta ejecutar ramas
    # cuando su cobertura alcanza todas las unidades detectadas. Esto también
    # vale para un turno mixto: respuesta al slot pendiente + consulta de
    # quincho. El plan congelado conserva ambas obligaciones y permite que el
    # BookingObjective llegue a READY antes de componer una única respuesta.
    if (
        early_plan.get("status") == "verified"
        and early_plan.get("bindings")
        and not force_branch_reresolution
        and semantic_units >= max(1, len(subintents))
    ):
        return await _run_single_with_dialogue_decision(
            mensaje,
            conv_state,
            eval_context,
            router_subintent_override=(subintents[0] if len(subintents) == 1 else None),
        )

    if len(subintents) <= 1:
        return await _run_single_with_dialogue_decision(
            mensaje,
            conv_state,
            eval_context,
            router_subintent_override=(subintents[0] if subintents else None),
        )

    print(
        "   🌳 [AgentV2 V125 SAME-TURN BRANCHES] "
        f"subintenciones={len(subintents)} "
        f"intents={[item.get('intencion') for item in subintents]}"
    )

    baseline_state = _agent_v2_v125_snapshot_conversation_state(
        telefono or "unknown"
    )

    partials: List[Dict[str, Any]] = []
    subresults: List[Dict[str, Any]] = []
    branch_states: List[Dict[str, Any]] = []
    continuation_snapshots: List[Dict[str, Any]] = []
    all_observations: List[Dict[str, Any]] = []
    branch_summaries: List[Dict[str, Any]] = []
    total_llm_calls = 0

    for idx, item in enumerate(subintents, start=1):
        fragment = str(item.get("fragmento") or "").strip()
        intent = str(item.get("intencion") or "otra").strip()
        if not fragment:
            continue

        _agent_v2_v125_replace_conversation_state(
            telefono or "unknown",
            baseline_state,
            reason=f"baseline_before_sibling_{idx}",
        )

        print(
            "   🔀 [AgentV2 V125 SUBTURN] "
            f"{idx}/{len(subintents)} intent={intent} "
            f"fragment={fragment[:120]!r}"
        )

        # ``detectar_multiples_intenciones`` ya estableció que cada fragmento es
        # un sibling del CURRENT USER TURN. Cuando el gate estructural no tenía
        # candidatos pendientes, esta marca no inventa una intención ni congela
        # una operación: solamente impide que el Conversation Manager tardío
        # rebautice el fragmento como ``references_previous`` por mirar historial.
        # Perception sigue siendo quien entiende semánticamente cada fragmento.
        sibling_dialogue_plan = None

        # Si el Dialogue Gate ya vinculó evidencia literal de ESTE fragmento a
        # una PendingInteraction, esa identidad tiene precedencia sobre la
        # etiqueta genérica del router (p.ej. ``reservar_cancha``). Marcarla
        # independent hacía que "fútbol 5" dejara de completar resource_type.
        fragment_bindings = [
            dict(binding)
            for binding in (early_plan.get("bindings") or [])
            if isinstance(binding, dict)
            and _agent_v2_v126_literal_evidence(
                fragment,
                binding.get("evidence"),
            )
        ]
        fragment_acts = [
            dict(act)
            for act in (early_plan.get("independent_acts") or [])
            if isinstance(act, dict)
            and _agent_v2_v126_literal_evidence(
                fragment,
                next((
                    item.get("evidence")
                    for item in (act.get("provenance") or [])
                    if isinstance(item, dict)
                    and str(item.get("source") or "") == "current_user_turn"
                ), ""),
            )
        ]
        if fragment_bindings:
            sibling_dialogue_plan = {
                "status": "verified",
                "relation": "mixed" if fragment_acts else str(
                    fragment_bindings[0].get("relation") or "answers_pending"
                ),
                "bindings": fragment_bindings,
                "independent_acts": fragment_acts,
                "reason": "verified_binding_scoped_to_same_turn_fragment",
                "semantic_frozen": True,
            }
            print(
                "   🔗 [AgentV2 V127 SIBLING BINDING] "
                f"sibling={idx}/{len(subintents)} "
                f"fields={[item.get('field') for item in fragment_bindings]}"
            )
        elif _agent_v2_v126r3_subintent_is_current_turn_independent(intent):
            sibling_dialogue_plan = _agent_v2_v126r3_independent_sibling_plan(
                idx,
                len(subintents),
                intent,
                source="v126r3_ai_router_current_turn_obligation",
            )
            print(
                "   🧭 [AgentV2 V126R3 SIBLING CONTEXT] "
                f"sibling={idx}/{len(subintents)} intent={intent} "
                "relation=current_turn_independent pending=passive"
            )
        elif (
            not force_branch_reresolution
            and str(early_plan.get("status") or "") in {"no_candidates", "verified"}
            and not early_plan.get("bindings")
        ):
            sibling_dialogue_plan = _agent_v2_v126r3_independent_sibling_plan(
                idx,
                len(subintents),
                intent,
                source="v125_same_turn_sibling",
            )
            print(
                "   🧭 [AgentV2 V125 SIBLING CONTEXT] "
                f"sibling={idx}/{len(subintents)} relation=current_turn_independent "
                "late_rebinding=False"
            )

        result = await _run_single_with_dialogue_decision(
            fragment,
            get_conversation_state(telefono or "unknown"),
            None,
            sibling_dialogue_plan,
            item,
        )

        branch_state = _agent_v2_v125_snapshot_conversation_state(
            telefono or "unknown"
        )
        branch_states.append(branch_state)
        subresults.append(result)
        branch_summaries.append(
            _agent_v2_v125_branch_summary(idx, item, result)
        )
        total_llm_calls += int(result.get("llm_calls") or 0)

        all_observations.extend(
            dict(obs) for obs in (result.get("observations") or [])
            if isinstance(obs, dict)
        )

        response = str(result.get("response") or "").strip()
        if response:
            partials.append({
                "index": idx,
                "intent": intent,
                "fragment": fragment,
                "response": response,
                "status": result.get("status"),
                "goals": result.get("goals") or {},
                "observations": result.get("observations") or [],
            })

        if _agent_v2_v124_waiting_result(result):
            snapshot = _agent_v2_v124_capture_continuation(
                telefono or "unknown",
                result,
            )
            if snapshot:
                continuation_snapshots.append(snapshot)
                print(
                    "   🧠 [AgentV2 V125 CONTINUATION SNAPSHOT] "
                    f"sibling={idx} fields={snapshot.get('fields')} "
                    f"qids={snapshot.get('question_ids')}"
                )
        else:
            # V139: una rama READ exacta puede abrir una continuación durable
            # (p.ej. preguntar resource_type después de mostrar disponibilidad)
            # aunque su respuesta ya tenga status=complete. El efecto de estado
            # se detecta comparando snapshots, no por la posición/status sibling.
            snapshot = _agent_v2_v139_capture_branch_continuation(
                baseline_state,
                branch_state,
                branch_index=idx,
            )
            if snapshot:
                continuation_snapshots.append(snapshot)
                print(
                    "   🧠 [AgentV2 V139 STATEFUL READ CONTINUATION] "
                    f"sibling={idx} fields={snapshot.get('fields')} "
                    f"qids={snapshot.get('question_ids')}"
                )

        if str(result.get("status") or "") == "paused_human":
            break

    commit_idx = _agent_v2_v125_select_commit_branch(subresults)
    if 0 <= commit_idx < len(branch_states):
        _agent_v2_v125_replace_conversation_state(
            telefono or "unknown",
            branch_states[commit_idx],
            reason=f"commit_sibling_{commit_idx + 1}",
        )
    else:
        _agent_v2_v125_replace_conversation_state(
            telefono or "unknown",
            baseline_state,
            reason="commit_baseline",
        )

    committed_booking_write = bool(
        0 <= commit_idx < len(subresults)
        and any(
            isinstance(obs, dict)
            and str(obs.get("tool") or "") == "crear_reserva"
            and obs.get("ok") is True
            and str(obs.get("status") or "") in {"success", "already_exists"}
            for obs in (subresults[commit_idx].get("observations") or [])
        )
    )

    # Una reserva ya creada cerró el objetivo. Restaurar snapshots waiting_user
    # de siblings anteriores reabría preguntas de hora/deporte después del hold.
    if continuation_snapshots and not committed_booking_write:
        _agent_v2_v124_restore_continuations(
            telefono or "unknown",
            continuation_snapshots,
        )

    final_response = _agent_v2_v123_lossless_single_response(partials)
    if not final_response:
        _agent_v2_v125_replace_conversation_state(
            telefono or "unknown",
            baseline_state,
            reason="fallback_original_message",
        )
        return await _run_single_with_dialogue_decision(
            mensaje,
            get_conversation_state(telefono or "unknown"),
            None,
        )

    aggregate_status = _agent_v2_v124_aggregate_status(subresults)
    restored_continuation = bool(
        continuation_snapshots and not committed_booking_write
    )
    if restored_continuation and aggregate_status == "complete":
        aggregate_status = "waiting_user"
    continuation_anchor_idx = -1
    if restored_continuation:
        try:
            continuation_anchor_idx = int(
                continuation_snapshots[-1].get("branch_index") or 0
            ) - 1
        except (TypeError, ValueError):
            continuation_anchor_idx = -1
    anchor_idx = (
        continuation_anchor_idx
        if 0 <= continuation_anchor_idx < len(subresults)
        else commit_idx
    )
    anchor = (
        subresults[anchor_idx]
        if 0 <= anchor_idx < len(subresults)
        else _agent_v2_v124_continuation_anchor(subresults)
    )
    merged_goals = _agent_v2_v123_merge_goal_payload(subresults)
    merged_plan = _agent_v2_v123_merge_plan_payload(subresults)

    print(
        "   🌳 [AgentV2 V125 BRANCH MERGE] "
        f"commit={commit_idx + 1 if commit_idx >= 0 else '-'} "
        f"status={aggregate_status} "
        f"partials={len(partials)}/{len(subresults)} "
        f"observations={len(all_observations)} "
        f"branches={branch_summaries}"
    )
    print(
        "   🧩 [AgentV2 V125 SINGLE RESPONSE] "
        "todas las respuestas sibling válidas se preservan en un único mensaje"
    )

    return {
        "handled": True,
        "delegate_legacy": False,
        "response": final_response,
        "world": anchor.get("world") or {},
        "perception": {
            "source": "v125_same_turn_sibling_isolation",
            "subintents": subintents,
            "subperceptions": [
                result.get("perception") or {}
                for result in subresults
            ],
            "branch_summaries": branch_summaries,
            "commit_branch_index": commit_idx,
            "continuation_branch_index": continuation_anchor_idx,
            "continuation_preserved": bool(continuation_snapshots),
        },
        "goals": merged_goals,
        "plan": merged_plan,
        "observations": all_observations,
        "status": aggregate_status,
        "next_best_action": anchor.get("next_best_action") or {},
        "safe_exit": anchor.get("safe_exit") or {},
        "llm_calls": total_llm_calls,
        "multi_subintent_bridge": {
            "version": "v125",
            "subintent_count": len(subintents),
            "partial_response_count": len(partials),
            "same_user_turn": True,
            "siblings_isolated": True,
            "commit_branch_index": commit_idx,
            "continuation_preserved": bool(continuation_snapshots),
        },
    }


_run_agent_v2_invariant_evals_v125_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v125_base()
    results = list(result.get("results") or [])

    waiting_booking = {
        "status": "waiting_user",
        "observations": [{
            "tool": "solicitar_dato",
            "ok": True,
            "status": "needs_user_input",
            "data": {"field": "resource_type"},
        }],
    }
    completed_read = {
        "status": "complete",
        "observations": [{
            "tool": "consultar_evento",
            "ok": True,
            "status": "success",
        }],
    }
    completed_write = {
        "status": "complete",
        "observations": [{
            "tool": "crear_reserva",
            "ok": True,
            "status": "success",
        }],
    }

    results.extend([
        {
            "name": "v125_waiting_branch_beats_later_read_for_state_commit",
            "passed": (
                _agent_v2_v125_select_commit_branch(
                    [waiting_booking, completed_read]
                ) == 0
            ),
        },
        {
            "name": "v125_write_branch_beats_read_for_state_commit",
            "passed": (
                _agent_v2_v125_select_commit_branch(
                    [completed_write, completed_read]
                ) == 0
            ),
        },
        {
            "name": "v125_read_branch_cannot_gain_write_priority",
            "passed": (
                _agent_v2_v125_result_state_priority(completed_read)
                < _agent_v2_v125_result_state_priority(completed_write)
            ),
        },
        {
            "name": "v125_waiting_branch_has_highest_non_human_priority",
            "passed": (
                _agent_v2_v125_result_state_priority(waiting_booking)
                > _agent_v2_v125_result_state_priority(completed_write)
            ),
        },
    ])

    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


AGENT_V2_UNIFIED_AGENTIC_CORE = "v125"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v125"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_same_turn_sibling_isolation_v125"


# ============================================================================
# V126 — STRUCTURAL PENDING CONTINUITY + EVENT RESPONSE HEADING
# ============================================================================
# Producción V125 demostró dos cosas:
#   1) SAME-TURN sibling isolation ya conserva y responde todas las ramas.
#   2) En el turno siguiente, V108 podía volver pasiva una PendingInteraction
#      legítima porque comparaba question_text contra el último bloque assistant.
#      En una respuesta multi-subintención, ese bloque también contiene otras
#      respuestas (ej. información del torneo), por lo que la continuidad no debe
#      depender de igualdad textual del mensaje assistant.
#
# Principio V126:
#   - La vigencia de una pregunta de booking se demuestra primero por identidad
#     estructural: owner + question_id + scope_id + booking_objective_id +
#     action_snapshot/allowed_operations + status/TTL.
#   - El lenguaje del nuevo turno lo interpreta IA mediante el resolver V105.
#     Python NO usa regex/keywords para decidir que "futbol", "padel", una hora,
#     un día, etc. responden el formulario pendiente.
#   - Un pedido realmente independiente sigue ganando si V105 lo clasifica como
#     independiente o si aparece un WRITE incompatible.
#   - query_event siempre expone un encabezado factual estable antes del detalle.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_structural_pending_continuity_v126"


def _agent_v2_v126_raw_pending_interactions(world: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Lee las PendingInteraction persistidas sin aplicar el filtro textual V108."""
    if not isinstance(world, dict):
        return []
    direct = world.get("pending_interactions")
    if isinstance(direct, list):
        rows = [dict(item) for item in direct if isinstance(item, dict)]
    else:
        frame = world.get("conversation_frame") or {}
        rows = [
            dict(item) for item in (frame.get("pending_interactions") or [])
            if isinstance(item, dict)
        ]
    return rows[-30:]


def _agent_v2_v126_structural_booking_binding(
    world: Dict[str, Any],
    interaction_hint: Optional[Dict[str, Any]] = None,
) -> Tuple[Dict[str, Any], str, Dict[str, Any]]:
    """Encuentra una única pregunta vigente ligada al BookingObjective activo.

    No inspecciona el texto USER ni el texto ASSISTANT. La identidad conversacional
    ya fue creada por Agent V2 al hacer ``solicitar_dato``.
    """
    objective = _agent_v2_v103_active_objective_from_world(world or {})
    if not objective or str(objective.get("operation") or "") != "create_booking":
        return {}, "", {}

    missing = {
        _agent_v2_v105_normalize_missing_field(field)
        for field in _agent_v2_v103_compute_missing(objective)
        if _agent_v2_v105_normalize_missing_field(field)
    }
    if not missing:
        return {}, "", objective

    expected_owner = str(((world or {}).get("facts") or {}).get("memory_owner") or "").strip()
    now = datetime.datetime.now(TIMEZONE)
    hint_qid = str((interaction_hint or {}).get("question_id") or "").strip()
    hint_iid = str((interaction_hint or {}).get("interaction_id") or "").strip()
    matches: List[Tuple[Dict[str, Any], str]] = []

    for raw in _agent_v2_v126_raw_pending_interactions(world or {}):
        item = dict(raw)
        if str(item.get("status") or "active") not in {"active", "suspended", "engaged"}:
            continue
        owner = str(item.get("owner") or "").strip()
        if expected_owner and owner and owner != expected_owner:
            continue
        expires = _parse_context_timestamp(item.get("expires_at"))
        if expires and now > expires:
            continue
        if hint_qid and str(item.get("question_id") or "").strip() != hint_qid:
            continue
        if hint_iid and str(item.get("interaction_id") or "").strip() != hint_iid:
            continue
        if not _agent_v2_v108_interaction_belongs_to_objective(item, objective):
            continue

        qid = str(item.get("question_id") or "").strip()
        scope_id = str(item.get("scope_id") or "").strip()
        objective_id = str(((item.get("context") or {}).get("booking_objective_id")) or "").strip()
        if not qid or not scope_id or objective_id != str(objective.get("objective_id") or "").strip():
            continue

        field = _agent_v2_v105_normalize_missing_field(item.get("field"))
        if field not in missing:
            continue
        matches.append((item, field))

    if len(matches) != 1:
        return {}, "", objective
    item, field = matches[0]
    return dict(item), field, dict(objective)


_agent_v2_v108_booking_interaction_is_adjacent_v126_base = (
    _agent_v2_v108_booking_interaction_is_adjacent
)


def _agent_v2_v108_booking_interaction_is_adjacent(
    item: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    """V126: identidad estructural válida prevalece sobre comparación textual."""
    if _agent_v2_v108_booking_interaction_is_adjacent_v126_base(item, world or {}):
        return True

    bound, field, objective = _agent_v2_v126_structural_booking_binding(
        world or {},
        interaction_hint=item,
    )
    if bound and field and objective:
        print(
            "   🔗 [AgentV2 V126 STRUCTURAL PENDING FRESHNESS] "
            f"question_id={bound.get('question_id')} field={field} "
            f"objective={objective.get('objective_id')} → interacción vigente"
        )
        return True
    return False


def _agent_v2_v126_authorized_create_booking(perception: Dict[str, Any]) -> bool:
    verification = dict((perception or {}).get("semantic_effect_verification") or {})
    return bool(
        verification.get("status") == "verified"
        and any(
            isinstance(item, dict)
            and item.get("authorized") is True
            and str(item.get("operation") or "create_booking") == "create_booking"
            for item in (verification.get("write_authorizations") or [])
        )
    )


AGENT_V2_DIALOGUE_CONTEXT_PLAN = contextvars.ContextVar(
    "agent_v2_dialogue_context_plan", default={}
)

# La clasificación exhaustiva del router pertenece al turno físico actual. Se
# transporta separada del DialogueContextPlan porque puede existir aun cuando no
# haya ninguna PendingInteraction previa que vincular. Nunca se persiste como
# memoria ni se usa para extraer slots: sólo evita perder una intención de
# reserva que Perception haya degradado accidentalmente a un READ de disponibilidad.
AGENT_V2_CURRENT_ROUTER_SUBINTENT = contextvars.ContextVar(
    "agent_v2_current_router_subintent", default={}
)


def _agent_v2_v126_binding_candidates(
    world: Dict[str, Any],
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Construye candidatos de routing usando sólo estado tipado y vigente.

    No mira el texto del usuario ni exige que ``question_text`` sea el último
    bloque enviado. Un BookingObjective terminal nunca vuelve a competir.
    """
    world = world or {}
    objective = _agent_v2_v103_active_objective_from_world(world)
    objective_id = str(objective.get("objective_id") or "").strip()
    owner = str((world.get("facts") or {}).get("memory_owner") or "").strip()
    current_scope = str(world.get("current_scope_id") or "").strip()
    now = datetime.datetime.now(TIMEZONE)
    candidates: List[Dict[str, Any]] = []

    for raw in _agent_v2_v126_raw_pending_interactions(world):
        item = dict(raw)
        if str(item.get("status") or "active") not in {"active", "suspended"}:
            continue
        iid = str(item.get("interaction_id") or "").strip()
        qid = str(item.get("question_id") or "").strip()
        scope_id = str(item.get("scope_id") or "").strip()
        item_owner = str(item.get("owner") or "").strip()
        if not iid or not qid or not scope_id:
            continue
        if owner and item_owner != owner:
            continue
        expires = _parse_context_timestamp(item.get("expires_at"))
        if expires and now > expires:
            continue
        created = _parse_context_timestamp(item.get("created_at"))
        if created:
            age = (now - created).total_seconds()
            if age < 0 or age > AGENT_V2_GENERIC_PENDING_TTL_MINUTES * 60:
                continue

        context = dict(item.get("context") or {})
        bound_objective_id = str(context.get("booking_objective_id") or "").strip()
        snapshot = dict(item.get("action_snapshot") or {})
        allowed = [
            str(op) for op in (item.get("allowed_operations") or [])
            if str(op) in AGENT_V2_SEMANTIC_OPERATIONS
        ]
        snapshot_operation = str(snapshot.get("operation") or "").strip()
        is_booking = bool(
            bound_objective_id
            or snapshot_operation == "create_booking"
            or "create_booking" in allowed
        )
        if is_booking:
            if not objective_id or bound_objective_id != objective_id:
                continue
            objective_owner = str(objective.get("owner") or "").strip()
            if owner and objective_owner and objective_owner != owner:
                continue
        elif current_scope and scope_id != current_scope:
            continue

        candidates.append({
            "interaction_id": iid,
            "question_id": qid,
            "scope_id": scope_id,
            "objective_id": bound_objective_id or None,
            "owner": item_owner,
            "field": _agent_v2_v105_normalize_missing_field(item.get("field")),
            "status": str(item.get("status") or "active"),
            "kind": str(item.get("kind") or "value"),
            "question_text": str(item.get("question_text") or ""),
            "options": list(item.get("options") or []),
            "allowed_operations": allowed,
            "action_snapshot": snapshot,
            "temporal_constraint": dict(
                context.get("temporal_constraint")
                or snapshot.get("temporal_constraint")
                or objective.get("temporal_constraint")
                or {}
            ),
            "_interaction": item,
        })

    return candidates[-12:], dict(objective or {})


def _agent_v2_v126_literal_evidence(mensaje: str, evidence: Any) -> bool:
    message_key = normalizar_texto_ia(mensaje or "")
    evidence_key = normalizar_texto_ia(evidence or "")
    return bool(message_key and evidence_key and evidence_key in message_key)


def _agent_v2_v126_option_value(
    interaction: Dict[str, Any], value: Any,
) -> Any:
    """Valida una selección ya entendida contra opciones estructuradas."""
    key = normalizar_texto_ia(value or "")
    matches: List[Any] = []
    for option in interaction.get("options") or []:
        if isinstance(option, dict):
            candidate = option.get("value")
            if candidate in (None, ""):
                candidate = option.get("id") or option.get("option_id")
        else:
            candidate = option
        if candidate not in (None, "") and normalizar_texto_ia(candidate) == key:
            matches.append(candidate)
    return matches[0] if len(matches) == 1 else None


def _agent_v2_v126_validate_binding_value(
    interaction: Dict[str, Any], field: str, value: Any,
) -> Any:
    validated = _agent_v2_v105_validate_ai_slot_value(field, value)
    if validated is not None:
        if _agent_v2_v105_normalize_missing_field(field) == "dia":
            return _agent_v2_v132_constrain_pending_day(interaction, validated)
        return validated
    if isinstance(value, bool) and str(interaction.get("kind") or "") in {
        "confirmation", "offer",
    }:
        return value
    return _agent_v2_v126_option_value(interaction, value)


def _agent_v2_v126_validate_independent_act(
    raw: Dict[str, Any], mensaje: str,
) -> Dict[str, Any]:
    if not isinstance(raw, dict):
        return {}
    operation = _agent_v2_semantic_operation_alias(raw.get("operation"))
    if operation not in AGENT_V2_SEMANTIC_OPERATIONS or operation == "unknown":
        return {}
    evidence = str(raw.get("evidence") or "").strip()
    if not _agent_v2_v126_literal_evidence(mensaje, evidence):
        return {}
    wants_write = operation in AGENT_V2_WRITE_OPERATIONS
    return {
        "act_id": str(raw.get("act_id") or f"dialogue_{uuid.uuid4().hex[:12]}"),
        "operation": operation,
        "domain": str(raw.get("domain") or "general"),
        "target": dict(raw.get("target") or {}),
        "temporal": dict(raw.get("temporal") or {}),
        "quantity": dict(raw.get("quantity") or {}),
        "changes": list(raw.get("changes") or []),
        "requested_facts": list(raw.get("requested_facts") or []),
        "commitment": {
            "wants_write": wants_write,
            "wants_information": not wants_write,
        },
        "provenance": [{
            "field": "operation",
            "source": "current_user_turn",
            "evidence": evidence,
            "question_id": None,
            "scope_id": None,
        }],
    }


async def _agent_v2_v126_resolve_dialogue_context_before_perception(
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Primera y única decisión contextual cuando hay interacciones activas.

    La IA entiende relación, elipsis y actos múltiples. Python no clasifica el
    castellano: sólo valida identidad, vigencia, evidencia y configuración.
    """
    candidates, objective = _agent_v2_v126_binding_candidates(world or {})
    if not candidates:
        return {"status": "no_candidates", "bindings": [], "independent_acts": []}

    public_candidates = [{
        key: value for key, value in item.items() if not key.startswith("_")
    } for item in candidates]
    resolver_payload = {
        "current_user_turn": mensaje,
        "pending_interactions": public_candidates,
        "active_booking_objective": objective or None,
        "configuration": {
            "court_types": _configured_court_type_labels(),
            "courts": sorted(_agent_v2_v105_configured_court_names()),
            "durations_hours": list(ALLOWED_TURN_DURATIONS or []),
            "quinchos": _agent_v2_v103_quincho_names(),
            "valid_operations": sorted(AGENT_V2_SEMANTIC_OPERATIONS),
        },
        "recent_dialogue": list(
            ((world or {}).get("stored_memory") or {}).get("history") or []
        )[-AGENT_V2_GENERIC_CONTEXT_HISTORY_LIMIT:],
    }
    resolver_system = (
        "Sos DIALOGUE CONTEXT RESOLVER. Antes de interpretar el turno como una intención aislada, "
        "decidí si alguna parte responde, modifica o continúa una PendingInteraction estructurada, "
        "y extraé además todos los actos independientes del MISMO turno. Entendé elipsis, referencias "
        "y lenguaje natural; no uses coincidencias de palabras. Evaluá primero si el contenido semántico "
        "del current_user_turn puede completar el field solicitado usando question_text, options, "
        "action_snapshot y active_booking_objective. Una respuesta humana puede ser muy breve y la "
        "pregunta pendiente puede haber sido acompañada por otros bloques informativos del asistente; no "
        "exijas adyacencia textual. Si el turno es explicable como valor de la pregunta activa y no expresa "
        "por sí mismo una consulta o acción nueva, vinculalo al pending. A la vez, una pregunta activa no "
        "secuestra una consulta o acción verdaderamente nueva. No autorices escrituras. No inventes IDs ni "
        "valores. Para un binding copiá exactamente interaction_id, question_id, scope_id, objective_id y "
        "field del candidato, y devolvé un valor canónico permitido por configuration. Para cada acto "
        "independiente devolvé el SemanticAct completo y evidence como fragmento literal del current_user_turn. "
        "REGLA DE EVIDENCIA: la configuración y el historial sólo describen servicios disponibles; jamás prueban "
        "que el usuario los pidió. No devuelvas un acto sobre un recurso adicional si current_user_turn no lo "
        "menciona o solicita explícitamente. REGLA COMERCIAL: cuando el turno completa/continúa un "
        "active_booking_objective y además pregunta explícitamente si "
        "hay quincho o parrilla, conservá el binding de la reserva y devolvé también un independent_act "
        "query_policy con target.resource='quincho' y requested_facts=['service.available']; ese acto permite "
        "responder la consulta y el runtime lo incorporará como addon del mismo objetivo. Si no existe un "
        "active_booking_objective vinculado, la consulta sigue siendo sólo informativa. Una duración explícita "
        "que coincide o modifica el objetivo pertenece al mismo objetivo y no debe convertirse en una consulta "
        "general de horarios. Expresar que quiere señar, dejar señado o confirmar el turno activo es continuidad "
        "del mismo objetivo; si todavía falta un dato mínimo, no lo conviertas en query_policy ni en una operación "
        "independiente: el runtime debe completar primero ese dato. "
        "Nunca devuelvas una decisión vacía: relation=independent requiere al menos un independent_act que "
        "cubra evidencia literal; si hay un binding, incluílo. Respondé SOLO JSON con: "
        "{\"relation\":\"answers_pending|modifies_pending|continues_focus|independent|mixed\","
        "\"bindings\":[{\"relation\":\"answers_pending\",\"interaction_id\":\"...\","
        "\"question_id\":\"...\",\"scope_id\":\"...\",\"objective_id\":\"...\","
        "\"field\":\"...\",\"value\":null,\"evidence\":\"...\",\"confidence\":0.0}],"
        "\"independent_acts\":[{\"operation\":\"...\",\"domain\":\"...\","
        "\"target\":{},\"temporal\":{},\"quantity\":{},\"changes\":[],"
        "\"requested_facts\":[],\"evidence\":\"...\"}],\"reason\":\"...\"}."
    )

    async def _ask_context_resolver(repair: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        system = resolver_system
        payload = dict(resolver_payload)
        if isinstance(repair, dict):
            system += (
                " REPARACIÓN ÚNICA: la decisión anterior no produjo ninguna unidad semántica "
                "validable. Reanalizá el turno, cubrilo por completo y copiá literalmente las identidades "
                "estructurales del candidato. No conviertas una respuesta elíptica en consulta aislada."
            )
            payload["invalid_previous_decision"] = repair
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False, default=str)},
            ],
            temperature=0.0,
            max_tokens=900,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        return _loads_llm_json_object(response.choices[0].message.content.strip())

    try:
        data = await _ask_context_resolver()
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 DIALOGUE BINDING] resolver no disponible; "
            f"fail-closed al pipeline general: {type(exc).__name__}: {exc}"
        )
        return {"status": "resolver_unavailable", "bindings": [], "independent_acts": []}

    by_identity = {
        (
            item["interaction_id"], item["question_id"], item["scope_id"],
            str(item.get("objective_id") or ""), item["field"],
        ): item
        for item in candidates
    }
    def _validate_resolver_units(candidate_data: Dict[str, Any]):
        verified_bindings: List[Dict[str, Any]] = []
        used_interactions = set()
        for raw in candidate_data.get("bindings") or []:
            if not isinstance(raw, dict) or float(raw.get("confidence") or 0.0) < 0.75:
                continue
            relation = str(raw.get("relation") or "").strip()
            if relation not in {"answers_pending", "modifies_pending", "continues_focus"}:
                continue
            raw_interaction_id = str(raw.get("interaction_id") or "").strip()
            raw_question_id = str(raw.get("question_id") or "").strip()
            raw_scope_id = str(raw.get("scope_id") or "").strip()
            raw_objective_id = str(raw.get("objective_id") or "").strip()
            raw_field = _agent_v2_v105_normalize_missing_field(raw.get("field"))
            identity = (
                raw_interaction_id,
                raw_question_id,
                raw_scope_id,
                raw_objective_id,
                raw_field,
            )
            candidate = by_identity.get(identity)

            # Si el LLM omitió SOLAMENTE objective_id, se recupera desde la
            # PendingInteraction ya identificada inequívocamente por los demás
            # IDs. No se interpreta lenguaje y no se amplía autoridad.
            if candidate is None and not raw_objective_id:
                structural_matches = [
                    item for item in candidates
                    if str(item.get("interaction_id") or "").strip() == raw_interaction_id
                    and str(item.get("question_id") or "").strip() == raw_question_id
                    and str(item.get("scope_id") or "").strip() == raw_scope_id
                    and _agent_v2_v105_normalize_missing_field(item.get("field")) == raw_field
                ]
                if len(structural_matches) == 1:
                    candidate = structural_matches[0]
                    identity = (
                        raw_interaction_id,
                        raw_question_id,
                        raw_scope_id,
                        str(candidate.get("objective_id") or "").strip(),
                        raw_field,
                    )
                    print(
                        "   🧩 [AgentV2 DIALOGUE IDENTITY RECOVERY] "
                        f"question_id={raw_question_id} field={raw_field} "
                        f"objective_id={identity[3]} ← state estructural"
                    )

            evidence = str(raw.get("evidence") or "").strip()
            if not candidate or identity[0] in used_interactions:
                continue
            if not _agent_v2_v126_literal_evidence(mensaje, evidence):
                continue
            value = _agent_v2_v126_validate_binding_value(
                candidate["_interaction"], candidate["field"], raw.get("value")
            )
            if value is None:
                continue
            used_interactions.add(identity[0])
            verified_bindings.append({
                "relation": relation,
                "interaction_id": identity[0],
                "question_id": identity[1],
                "scope_id": identity[2],
                "objective_id": identity[3] or None,
                "field": identity[4],
                "value": value,
                "evidence": evidence,
                "confidence": float(raw.get("confidence") or 0.0),
                "verified": True,
                "_interaction": candidate["_interaction"],
            })
        verified_acts = [
            act for act in (
                _agent_v2_v126_validate_independent_act(raw, mensaje)
                for raw in (candidate_data.get("independent_acts") or [])
            ) if act
        ]
        return verified_bindings, verified_acts

    bindings, independent_acts = _validate_resolver_units(data)
    if not bindings and not independent_acts:
        print(
            "   🧩 [AgentV2 DIALOGUE COVERAGE] units=0 con pending activo → "
            "reparación semántica única antes de Perception"
        )
        try:
            data = await _ask_context_resolver(data)
            bindings, independent_acts = _validate_resolver_units(data)
        except Exception as exc:
            print(
                "   ⚠️ [AgentV2 DIALOGUE COVERAGE] reparación no disponible: "
                f"{type(exc).__name__}: {exc}"
            )

    if not bindings and not independent_acts:
        # Fallback SEMÁNTICO pending-specific. Se activa sólo con una única
        # interacción booking candidata inequívoca. V105 decide con IA si el
        # current_user_turn responde esa pregunta; Python valida el valor contra
        # configuración. No hay keywords/regex ni autorización de escritura.
        booking_candidates = [
            item for item in candidates
            if (
                str(((item.get("_interaction") or {}).get("action_snapshot") or {}).get("operation") or "")
                == "create_booking"
                or str(item.get("objective_id") or "").strip()
            )
        ]
        if len(booking_candidates) == 1 and objective:
            candidate = booking_candidates[0]
            interaction = dict(candidate.get("_interaction") or {})
            field = _agent_v2_v105_normalize_missing_field(candidate.get("field"))
            try:
                fallback_value, fallback_source = (
                    await _agent_v2_v105_ai_pending_slot_resolution(
                        mensaje,
                        {"semantic_frame": {"acts": []}, "entities": {}},
                        objective,
                        interaction,
                        field,
                    )
                )
            except Exception as exc:
                fallback_value, fallback_source = None, ""
                print(
                    "   ⚠️ [AgentV2 DIALOGUE FALLBACK] "
                    f"V105 resolver no disponible: {type(exc).__name__}: {exc}"
                )

            if fallback_value is not None:
                fallback_value = _agent_v2_v126_validate_binding_value(
                    interaction, field, fallback_value
                )
            if fallback_value is not None:
                binding = {
                    "relation": "answers_pending",
                    "interaction_id": str(candidate.get("interaction_id") or ""),
                    "question_id": str(candidate.get("question_id") or ""),
                    "scope_id": str(candidate.get("scope_id") or ""),
                    "objective_id": str(candidate.get("objective_id") or "") or None,
                    "field": field,
                    "value": fallback_value,
                    "evidence": str(mensaje or "").strip(),
                    "confidence": 0.99,
                    "verified": True,
                    "_interaction": interaction,
                    "source": fallback_source or "v105_pending_slot_resolver",
                }
                bindings = [binding]
                print(
                    "   ✅ [AgentV2 DIALOGUE FALLBACK] "
                    f"relation=answers_pending question_id={binding['question_id']} "
                    f"field={field} value={fallback_value} "
                    f"source={binding['source']}"
                )

    if not bindings and not independent_acts:
        print(
            "   🚫 [AgentV2 DIALOGUE COVERAGE] decisión vacía rechazada; "
            "no se congela como independent"
        )
        return {
            "status": "unresolved", "relation": "unresolved",
            "bindings": [], "independent_acts": [],
            "reason": "dialogue_resolver_zero_validated_coverage",
            "semantic_frozen": False,
        }
    relation = "mixed" if bindings and independent_acts else (
        bindings[0]["relation"] if bindings else "independent"
    )
    plan = {
        "status": "verified",
        "relation": relation,
        "bindings": bindings,
        "independent_acts": independent_acts,
        "reason": str(data.get("reason") or ""),
        "semantic_frozen": True,
    }
    if bindings:
        for binding in bindings:
            print(
                "   🔗 [DIALOGUE BINDING] "
                f"relation={binding['relation']} question_id={binding['question_id']} "
                f"field={binding['field']} value={binding['value']}"
            )
    else:
        print(
            "   🔗 [DIALOGUE BINDING] relation=independent "
            f"ops={[act.get('operation') for act in independent_acts]}"
        )
    return plan


def _agent_v2_v126_perception_from_plan(plan: Dict[str, Any]) -> Dict[str, Any]:
    acts = [dict(act) for act in (plan.get("independent_acts") or []) if isinstance(act, dict)]
    primary = acts[0] if acts else {}
    relation = str(plan.get("relation") or "independent")
    frame = {
        "source": "dialogue_context_resolver",
        "schema_valid": True,
        "turn_type": "request" if acts else "answer",
        "intent": {
            "domain": str(primary.get("domain") or "general"),
            "operation": str(primary.get("operation") or "unknown"),
        },
        "acts": acts,
        "targets": [dict(act.get("target") or {}) for act in acts],
        "temporal": dict(primary.get("temporal") or {}),
        "requested_facts": list(primary.get("requested_facts") or []),
        "commitment": dict(primary.get("commitment") or {}),
        "context_relation": {
            "type": "new_request" if relation in {"independent", "mixed"} else relation,
            "question_id": None,
            "scope_id": None,
            "answers_pending_question": False,
        },
        "ambiguity": {"required": False, "alternatives": []},
    }
    return {
        "semantic_frame": frame,
        "entities": {},
        "explicit_actions": [],
        "pending_relation": "new_request" if relation in {"independent", "mixed"} else relation,
        "suspend_pending_this_turn": not bool(plan.get("bindings")),
        "current_turn_read_only": bool(acts) and not any(
            str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS for act in acts
        ),
        "turn_semantic_plan": plan,
        "context_resolution": {"source": "early_dialogue_context_gate", "relation": relation},
    }


def _agent_v2_v126_frozen_execution_contract(
    perception: Dict[str, Any],
    plan: Dict[str, Any],
) -> Dict[str, Any]:
    """Compila el plan verificado sin aplicar un binding a actos hermanos.

    Los READs provienen de evidencia literal validada. Cada WRITE debe aparecer
    autorizado, con el mismo act_id, por Semantic Effect Verifier.
    """
    acts = [
        dict(act) for act in (_agent_v2_semantic_frame(perception or {}).get("acts") or [])
        if isinstance(act, dict) and str(act.get("operation") or "") in AGENT_V2_SEMANTIC_OPERATIONS
    ]
    verification = dict((perception or {}).get("semantic_effect_verification") or {})
    authorized_ids = {
        str(item.get("act_id") or "").strip()
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict) and item.get("authorized") is True
    }
    accepted: List[Dict[str, Any]] = []
    rejected: List[Dict[str, Any]] = []
    for act in acts:
        operation = str(act.get("operation") or "")
        if operation in AGENT_V2_WRITE_OPERATIONS:
            if (
                verification.get("status") == "verified"
                and str(act.get("act_id") or "").strip() in authorized_ids
            ):
                accepted.append(act)
            else:
                rejected.append({
                    "act_id": act.get("act_id"),
                    "operation": operation,
                    "reason": "write_not_authorized_by_effect_verifier",
                })
        else:
            accepted.append(act)

    allowed_tools = sorted({
        tool
        for act in accepted
        for tool in AGENT_V2_OPERATION_TOOLS.get(str(act.get("operation") or ""), set())
    } | ({"solicitar_dato"} if (perception or {}).get("booking_collection_contract") else set()))
    bindings = [
        b for b in (plan.get("bindings") or [])
        if isinstance(b, dict) and b.get("verified") is True
    ]
    primary_binding = bindings[0] if bindings else {}
    relation = "mixed" if bindings and plan.get("independent_acts") else (
        str(primary_binding.get("relation") or "new_request")
    )
    return {
        "contract_id": str(uuid.uuid4()),
        "version": AGENT_V2_UNIFIED_AGENTIC_CORE,
        "source": "verified_turn_semantic_plan",
        "schema_valid": True,
        "authoritative": bool(accepted),
        "frozen": True,
        "acts": accepted,
        "allowed_tools": allowed_tools,
        "effects": list(dict.fromkeys(
            "write" if str(act.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS else "read"
            for act in accepted
        )),
        "context_relation": {
            "type": relation,
            "question_id": primary_binding.get("question_id"),
            "scope_id": primary_binding.get("scope_id"),
        },
        "authorized_context": {
            "relation": primary_binding.get("relation") or "new_request",
            "authorized": bool(primary_binding),
            "question_id": primary_binding.get("question_id"),
            "scope_id": primary_binding.get("scope_id"),
            "bindings": bindings,
        },
        "clarification_reasons": list(dict.fromkeys(
            item["reason"] for item in rejected
        )),
        "validation_issues": [],
        "rejected_acts": rejected,
        "write_authority": "semantic_effect_verifier",
        "legacy_semantic_fallback_used": False,
    }


def _agent_v2_v127_plan_requests_booking_quincho(
    plan: Dict[str, Any],
) -> bool:
    """Detecta el addon desde actos semánticos verificados, no desde texto libre.

    La regla sólo se habilita si el mismo TurnSemanticPlan contiene un binding
    de un BookingObjective activo. Una FAQ aislada continúa siendo read-only.
    """
    booking_objective_ids = {
        str(binding.get("objective_id") or "").strip()
        for binding in (plan.get("bindings") or [])
        if isinstance(binding, dict)
        and str(binding.get("objective_id") or "").strip()
    }
    if not booking_objective_ids or not CON_QUINCHO:
        return False

    configured_aliases = {"quincho", "parrilla", "quincho/parrilla"}
    for raw in (QUINCHOS or []):
        if isinstance(raw, dict):
            values = [
                raw.get("name"), raw.get("nombre"),
                raw.get("type"), raw.get("tipo"),
            ]
        else:
            values = [raw]
        for value in values:
            key = normalizar_texto_ia(value or "")
            if key:
                configured_aliases.add(key)
                configured_aliases.update(
                    part.strip() for part in key.split("/") if part.strip()
                )

    for act in (plan.get("independent_acts") or []):
        if not isinstance(act, dict):
            continue
        if str(act.get("operation") or "") != "query_policy":
            continue
        target = dict(act.get("target") or {})
        candidates = [target.get("resource"), target.get("label"), target.get("name")]
        for plural_key in ("labels", "target_labels"):
            plural_value = target.get(plural_key)
            if isinstance(plural_value, (list, tuple, set)):
                candidates.extend(plural_value)
            elif plural_value not in (None, ""):
                candidates.append(plural_value)
        candidate_keys = {
            normalizar_texto_ia(value or "")
            for value in candidates
            if str(value or "").strip()
        }
        if candidate_keys & configured_aliases:
            return True
    return False


def _agent_v2_v127_choose_booking_quincho(
    objective: Dict[str, Any],
) -> str:
    """Autoasigna un quincho equivalente; prioriza uno realmente disponible."""
    names = _agent_v2_v103_quincho_names()
    if not names:
        return ""

    # Con un único recurso no existe elección.
    if len(names) == 1:
        return names[0]

    # La autoasignación múltiple sólo es segura si tipo y tarifa coinciden.
    signatures = set()
    for name in names:
        qtype = ""
        key = normalizar_texto_ia(name)
        for raw in (QUINCHOS or []):
            if not isinstance(raw, dict):
                continue
            raw_name = str(raw.get("name") or raw.get("nombre") or "").strip()
            if normalizar_texto_ia(raw_name) == key:
                qtype = str(raw.get("type") or raw.get("tipo") or "").strip().casefold()
                break
        signatures.add((qtype, int(precio_hora_quincho(name) or 0)))
    if len(signatures) != 1:
        return ""

    temporal = dict((objective or {}).get("temporal") or {})
    day = str(temporal.get("day") or "").strip()
    hour = normalizar_hora_detectada(temporal.get("start"))
    duration = normalizar_duracion_horas(
        temporal.get("duration_hours") or DEFAULT_TURN_DURATION_HOURS,
        DEFAULT_TURN_DURATION_HOURS,
    )
    qstart = (
        _quincho_default_start_after_court(hour, duration)
        if hora_es_valida(hour)
        else ""
    )
    if day and hora_es_valida(qstart):
        for name in names:
            try:
                if quincho_libre_para_bloque(day, qstart, 1.0, name):
                    return name
            except Exception:
                continue

    # Se conserva un target concreto para que el preflight/commit falle de forma
    # verificable si ningún quincho está libre; nunca se degrada a cancha sola.
    return names[0]


async def _agent_v2_v126_apply_verified_turn_plan(
    mensaje: str,
    plan: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = _agent_v2_v126_perception_from_plan(plan)
    bindings = [b for b in (plan.get("bindings") or []) if isinstance(b, dict)]
    booking_bindings = [
        b for b in bindings
        if str(b.get("objective_id") or "")
        and str(((b.get("_interaction") or {}).get("action_snapshot") or {}).get("operation") or "")
        == "create_booking"
    ]

    if booking_bindings:
        # Un objetivo sólo puede tener una pregunta activa propietaria del turno.
        binding = booking_bindings[0]
        interaction = dict(binding.get("_interaction") or {})
        previous = _agent_v2_v103_active_objective_from_world(world or {})
        clean = _agent_v2_v105_promote_pending_answer_frame(
            clean, previous, interaction, binding["field"], binding["value"], mensaje
        )

        # Regla comercial V127: dentro de un turno que completa una reserva
        # activa, una consulta estructurada sobre disponibilidad de
        # quincho/parrilla solicita incluir el addon en ese mismo pedido. La
        # consulta sigue siendo un READ y se responde, pero el bundle de reserva
        # se construye con quincho. Sin ese acto estructurado, la cancha se
        # reserva sola.
        if _agent_v2_v127_plan_requests_booking_quincho(plan):
            clean["explicit_quincho_request"] = True
            entities = dict(clean.get("entities") or {})
            chosen_quincho = _agent_v2_v127_choose_booking_quincho(previous)
            if chosen_quincho:
                entities["quincho"] = chosen_quincho
            clean["entities"] = entities
            clean["_v127_contextual_booking_addon"] = {
                "verified": True,
                "resource": "quincho",
                "source": "verified_query_policy_in_active_booking_turn",
                "autoassigned": chosen_quincho or None,
            }
            print(
                "   🔥 [AgentV2 V127 BOOKING ADDON] "
                f"consulta de quincho + booking activo → incluir addon "
                f"quincho={chosen_quincho or '-'}"
            )
        frame = dict(_agent_v2_semantic_frame(clean) or {})
        booking_acts = [
            dict(act) for act in (frame.get("acts") or [])
            if isinstance(act, dict) and str(act.get("operation") or "") == "create_booking"
        ]
        independent = [
            dict(act) for act in (plan.get("independent_acts") or [])
            if isinstance(act, dict)
        ]
        frame["acts"] = booking_acts + independent
        clean["semantic_frame"] = frame
        clean["turn_semantic_plan"] = plan
        clean["_v100_pending_resolution"] = {
            "interaction_id": binding["interaction_id"],
            "question_id": binding["question_id"],
            "scope_id": binding["scope_id"],
            "mode": "accept",
            "operation": "create_booking",
        }

        objective, engaged = _agent_v2_v103_build_objective(clean, world or {})
        if not engaged or not objective:
            clean["semantic_clarification_required"] = True
            clean["semantic_clarification"] = {
                "reason": "verified_binding_could_not_rebuild_objective"
            }
            clean["_v100_semantic_frozen"] = True
            return clean

        # Una pregunta compuesta puede recibir varios slots en el mismo lote
        # físico (p.ej. "el martes\nfútbol 5"). Cada binding ya fue validado
        # contra una PendingInteraction distinta del mismo BookingObjective.
        # Los proyectamos secuencialmente para que ninguno dependa del orden.
        for extra_binding in booking_bindings[1:]:
            clean = _agent_v2_v103_apply_objective_to_perception(clean, objective)
            extra_interaction = dict(extra_binding.get("_interaction") or {})
            clean = _agent_v2_v105_promote_pending_answer_frame(
                clean,
                objective,
                extra_interaction,
                extra_binding["field"],
                extra_binding["value"],
                mensaje,
            )
            rebuilt, rebuilt_engaged = _agent_v2_v103_build_objective(
                clean, world or {}
            )
            if not rebuilt_engaged or not rebuilt:
                clean["semantic_clarification_required"] = True
                clean["semantic_clarification"] = {
                    "reason": "verified_multi_binding_could_not_rebuild_objective"
                }
                clean["_v100_semantic_frozen"] = True
                return clean
            objective = rebuilt

        # promote_pending_answer_frame conserva el WRITE y puede reemplazar los
        # READ siblings; restaurarlos desde el TurnSemanticPlan verificado.
        if booking_bindings[1:]:
            frame = dict(_agent_v2_semantic_frame(clean) or {})
            booking_acts = [
                dict(act) for act in (frame.get("acts") or [])
                if isinstance(act, dict)
                and str(act.get("operation") or "") == "create_booking"
            ]
            independent = [
                dict(act) for act in (plan.get("independent_acts") or [])
                if isinstance(act, dict)
            ]
            frame["acts"] = booking_acts + independent
            clean["semantic_frame"] = frame
            clean["turn_semantic_plan"] = plan

        clean = _agent_v2_v103_apply_objective_to_perception(clean, objective)
        clean["booking_objective"] = dict(objective)
        clean["_v103_booking_engaged"] = True

        clean.pop("semantic_effect_verification", None)
        clean.pop("execution_contract", None)
        frozen_frame = _agent_v2_v125_copy.deepcopy(
            _agent_v2_semantic_frame(clean)
        )
        verified = await _agent_v2_verify_semantic_effects(mensaje, clean, world or {})
        # Effect Verifier decide autoridad, no significado. Cualquier frame que
        # haya producido es diagnóstico; el TurnSemanticPlan conserva sus actos.
        verified["semantic_frame"] = frozen_frame
        verified["turn_semantic_plan"] = plan
        verified["booking_objective"] = dict(objective)
        verified["_v103_booking_engaged"] = True
        verified["_v100_pending_resolution"] = dict(clean["_v100_pending_resolution"])
        missing = list(_agent_v2_v103_compute_missing(objective))
        if not missing:
            if _agent_v2_v126_authorized_create_booking(verified):
                verified["_v105_pending_booking_completed"] = True
                verified["booking_collection_contract"] = {}
                print("   🔐 [EFFECT AUTH] create_booking authorized=True")
            else:
                verified["semantic_clarification_required"] = True
                verified["semantic_clarification"] = {
                    "reason": "effect_verifier_denied_verified_continuation"
                }
                print("   🔐 [EFFECT AUTH] create_booking authorized=False")
        else:
            verified["booking_collection_contract"] = _agent_v2_v104_build_collection_contract(
                verified, world or {}
            )

        verified.pop("execution_contract", None)
        verified["execution_contract"] = _agent_v2_v126_frozen_execution_contract(
            verified, plan
        )
        clean = verified
    else:
        # El plan independiente ya es la lectura semántica del turno. Para WRITEs
        # se conserva la frontera de Effect Verifier; los READs no obtienen jamás
        # autoridad de mutación por esta vía.
        frozen_frame = _agent_v2_v125_copy.deepcopy(
            _agent_v2_semantic_frame(clean)
        )
        clean = await _agent_v2_verify_semantic_effects(mensaje, clean, world or {})
        clean["semantic_frame"] = frozen_frame
        clean["turn_semantic_plan"] = plan
        clean.pop("execution_contract", None)
        clean["execution_contract"] = _agent_v2_v126_frozen_execution_contract(
            clean, plan
        )

    clean = _agent_v2_v100_attach_desired_state_and_task_graph(clean, world or {})
    if clean.get("booking_objective"):
        objective = dict(clean["booking_objective"])
        clean.setdefault("desired_state", {})["booking_objective"] = objective
        clean.setdefault("task_graph", {})["booking_missing_fields"] = list(
            objective.get("missing_fields") or []
        )
        clean["task_graph"]["booking_objective_id"] = objective.get("objective_id")
    if (
        not (clean.get("execution_contract") or {}).get("authoritative")
        and not clean.get("booking_collection_contract")
    ):
        clean["semantic_clarification_required"] = True
        clean["semantic_clarification"] = {
            "reason": "verified_turn_plan_has_no_authorized_executable_acts"
        }
    clean["_v100_semantic_frozen"] = True
    operations = [
        str(act.get("operation") or "")
        for act in (_agent_v2_semantic_frame(clean).get("acts") or [])
        if isinstance(act, dict)
    ]
    print(
        "   🧊 [SEMANTIC PLAN] "
        f"ops={operations} continuation={bool(bindings)} frozen=True"
    )
    return clean


_percibir_turno_agent_v2_v126_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    # El Context Binding Gate corre antes de cualquier clasificación aislada.
    # Sólo un binding verificado congela significado. Una decisión ``independent``
    # vuelve pasiva la memoria, pero deja que Perception entienda el turno completo.
    plan = AGENT_V2_DIALOGUE_CONTEXT_PLAN.get()
    if not isinstance(plan, dict) or plan.get("status") != "verified":
        plan = await _agent_v2_v126_resolve_dialogue_context_before_perception(
            mensaje, world or {}
        )
        if plan.get("status") == "verified" and not plan.get("bindings"):
            plan = dict(plan)
            plan["route_to_general_perception"] = True
            plan["semantic_frozen"] = False

    if plan.get("status") == "verified" and plan.get("route_to_general_perception"):
        token = AGENT_V2_DIALOGUE_CONTEXT_PLAN.set(plan)
        try:
            perception = await _percibir_turno_agent_v2_v126_base(
                mensaje, world, image_path, learning_policy
            )
        finally:
            AGENT_V2_DIALOGUE_CONTEXT_PLAN.reset(token)
        perception = dict(perception or {})
        perception["dialogue_context_resolution"] = {
            "status": "verified",
            "relation": "independent",
            "source": "early_dialogue_context_gate",
        }
        # La Perception general es la fuente semántica. El pending queda pasivo
        # para este turno, sin perderse de memoria ni autorizar ningún WRITE.
        perception["pending_relation"] = "new_request"
        perception["suspend_pending_this_turn"] = True
        return perception

    if plan.get("status") == "verified" and plan.get("bindings"):
        token = AGENT_V2_DIALOGUE_CONTEXT_PLAN.set(plan)
        try:
            return await _agent_v2_v126_apply_verified_turn_plan(
                mensaje, plan, world or {}
            )
        finally:
            AGENT_V2_DIALOGUE_CONTEXT_PLAN.reset(token)

    return await _percibir_turno_agent_v2_v126_base(
        mensaje, world, image_path, learning_policy
    )


def _agent_v2_build_response_obligations(
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
    world: Dict[str, Any],
    status: str,
) -> Dict[str, Any]:
    """Compila qué debe decirse desde resultados ya decididos.

    No infiere intención. Cada obligación nace de una Observation o de una
    pregunta stateful concreta y conserva un render determinístico verificable.
    """
    rows = [dict(obs) for obs in (observations or []) if isinstance(obs, dict)]
    items: List[Dict[str, Any]] = []
    covered_tools = set()

    for obs in rows:
        if (
            str(obs.get("tool") or "") == "solicitar_dato"
            and str(obs.get("status") or "") == "needs_user_input"
        ):
            text = _agent_v2_verified_missing_input_response([obs], world or {})
            if text:
                data = dict(obs.get("data") or {})
                items.append({
                    "type": "missing_field_question",
                    "field": data.get("field") or data.get("campo"),
                    "question_id": data.get("question_id"),
                    "text": str(text).strip(),
                })
                covered_tools.add("solicitar_dato")

    event_rows = [
        obs for obs in rows
        if str(obs.get("tool") or "") == "consultar_evento"
        and obs.get("ok") is True
    ]
    if event_rows:
        event_text = build_agent_v2_event_registration_message(rows)
        if event_text:
            items.append({
                "type": "event_information",
                "text": str(event_text).strip(),
                "required_heading": "*INFORMACION DEL EVENTO*",
            })
            covered_tools.add("consultar_evento")

    # Las consultas informativas que acompañan un WRITE son obligaciones de
    # respuesta, no ruido auxiliar. Renderizamos exclusivamente el contrato
    # factual verificado y lo conservamos en el mismo mensaje que el pedido de
    # comprobante.
    policy_rows = [
        obs for obs in rows
        if str(obs.get("tool") or "") == "consultar_informacion_negocio"
        and obs.get("ok") is True
        and isinstance((obs.get("data") or {}).get("policy_fact_contract"), dict)
    ]
    for policy_obs in policy_rows:
        policy_text = str(build_agent_v2_policy_fact_message(policy_obs) or "").strip()
        if not policy_text:
            continue
        if not any(
            normalizar_texto_ia((item or {}).get("text") or "")
            == normalizar_texto_ia(policy_text)
            for item in items
        ):
            items.append({
                "type": "policy_information",
                "text": policy_text,
            })
        covered_tools.add("consultar_informacion_negocio")

    terminal = str(_agent_v2_verified_terminal_template(rows) or "").strip()
    write_tools = {
        str(obs.get("tool") or "") for obs in rows
        if (AGENT_V2_TOOL_CATALOG.get(str(obs.get("tool") or ""), {}) or {}).get("effect")
        == "write"
    }
    if terminal and write_tools:
        # El CTA transaccional queda al final: primero se responde la consulta
        # del cliente y luego se pide el comprobante con el resumen completo.
        items.append({
            "type": "verified_tool_result",
            "tools": sorted(write_tools),
            "text": terminal,
        })
        covered_tools.update(write_tools)

    observable_tools = {
        str(obs.get("tool") or "") for obs in rows
        if str(obs.get("tool") or "")
        and str(obs.get("status") or "") not in {"skipped", "ignored"}
    }
    complete = bool(items) and observable_tools.issubset(covered_tools)
    return {
        "items": items,
        "complete": complete,
        "status": status,
        "semantic_plan_frozen": bool((perception or {}).get("_v100_semantic_frozen")),
    }


def _agent_v2_render_complete_response_obligations(
    obligations: Dict[str, Any],
) -> str:
    if not isinstance(obligations, dict) or obligations.get("complete") is not True:
        return ""
    parts: List[str] = []
    seen = set()
    for item in obligations.get("items") or []:
        text = str((item or {}).get("text") or "").strip()
        key = normalizar_texto_ia(text)
        if text and key not in seen:
            seen.add(key)
            parts.append(text)
    return "\n\n".join(parts).strip()


def _agent_v2_enforce_response_obligations(
    response: str,
    obligations: Dict[str, Any],
) -> str:
    """Restaura sólo bloques ausentes; jamás cambia Goals ni Tools ejecutadas."""
    obligation_items = [
        item for item in ((obligations or {}).get("items") or [])
        if isinstance(item, dict) and str(item.get("text") or "").strip()
    ]
    obligation_types = {
        str(item.get("type") or "") for item in obligation_items
    }
    if {"policy_information", "verified_tool_result"}.issubset(obligation_types):
        # Para un READ informativo + WRITE terminal no dejamos que el texto
        # generativo invierta el orden comercial. La fuente completa ya son
        # observations verificadas: primero respondemos la consulta y cerramos
        # con el CTA del comprobante y su resumen financiero.
        ordered = []
        seen = set()
        for item in obligation_items:
            text = str(item.get("text") or "").strip()
            key = normalizar_texto_ia(text)
            if key and key not in seen:
                seen.add(key)
                ordered.append(text)
        if ordered:
            print(
                "   🧾 [AgentV2 V127 READ+WRITE RESPONSE] "
                "respuesta factual primero; pedido de comprobante al cierre"
            )
            return "\n\n".join(ordered).strip()

    result = str(response or "").strip()
    additions: List[str] = []
    result_key = normalizar_texto_ia(result)
    for item in (obligations or {}).get("items") or []:
        if not isinstance(item, dict):
            continue
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        kind = str(item.get("type") or "")
        if kind == "event_information":
            heading = str(item.get("required_heading") or "").strip()
            if heading and heading in result:
                continue
        elif normalizar_texto_ia(text) in result_key:
            continue
        additions.append(text)
    if additions:
        print(
            "   🧾 [AgentV2 RESPONSE OBLIGATIONS] "
            f"restauro únicamente bloques faltantes={[item.get('type') for item in (obligations or {}).get('items') or []]}"
        )
        result = "\n\n".join([part for part in [result, *additions] if part]).strip()
    return result


_build_agent_v2_event_registration_message_v126_base = (
    build_agent_v2_event_registration_message
)


def build_agent_v2_event_registration_message(
    observations: List[Dict[str, Any]],
) -> str:
    """V126: query_event siempre comienza con un encabezado de evento estable."""
    text = _build_agent_v2_event_registration_message_v126_base(observations)
    if not text:
        return text

    event_obs = next((
        obs for obs in reversed(observations or [])
        if isinstance(obs, dict)
        and str(obs.get("tool") or "") in {
            "listar_eventos", "consultar_evento", "consultar_cupos_evento",
            "crear_hold_inscripcion_evento", "obtener_inscripcion_evento",
            "registrar_pago_inscripcion_evento", "registrar_saldo_efectivo_inscripcion_evento",
        }
    ), None)
    if not event_obs or str(event_obs.get("tool") or "") != "consultar_evento":
        return text

    heading = "*INFORMACION DEL EVENTO*"
    stripped = str(text or "").strip()
    if stripped.startswith(heading) or stripped.startswith("**INFORMACION DEL EVENTO**"):
        return stripped
    return f"{heading}\n\n{stripped}"


_run_agent_v2_invariant_evals_v126_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126_base()
    results = list(result.get("results") or [])

    objective = {
        "objective_id": "v126_obj",
        "status": "collecting",
        "operation": "create_booking",
        "target": {"resource": "court"},
        "temporal": {"day": "Martes 22/09", "start": "18:00", "duration_hours": 1.0},
        "missing_fields": ["resource_type"],
    }
    interaction = {
        "interaction_id": "v126_int",
        "question_id": "v126_q",
        "scope_id": "v126_scope",
        "owner": "v126_owner",
        "field": "resource_type",
        "status": "active",
        "allowed_operations": ["create_booking", "query_availability"],
        "action_snapshot": {
            "operation": "create_booking",
            "target": {"resource": "court"},
            "temporal": {"day": "Martes 22/09", "start": "18:00", "duration_hours": 1.0},
        },
        "question_text": "¿Qué tipo de deporte te gustaría reservar, fútbol 5, tenis o pádel?",
        "context": {"booking_objective_id": "v126_obj"},
    }
    world = {
        "facts": {"memory_owner": "v126_owner"},
        "conversation_frame": {
            "booking_objective": objective,
            "pending_interactions": [interaction],
        },
        "pending_interactions": [interaction],
        "stored_memory": {
            "booking_objective": objective,
            # Deliberadamente el último assistant NO coincide con question_text:
            # reproduce una respuesta multi-subintención donde el evento quedó
            # como otro bloque del mismo mensaje.
            "history": [{
                "role": "assistant",
                "content": "*INFORMACION DEL EVENTO*\n\n🏆 Copa Primavera",
            }],
        },
    }
    bound, field, bound_obj = _agent_v2_v126_structural_booking_binding(world)
    event_text = build_agent_v2_event_registration_message([{
        "tool": "consultar_evento",
        "ok": True,
        "status": "success",
        "data": {
            "event": {
                "name": "Copa Primavera",
                "date": "2026-09-24",
                "registration_price": 15000,
                "capacity": 16,
            },
            "available": 15,
            "is_full": False,
        },
    }])

    results.extend([
        {
            "name": "v126_structural_identity_keeps_pending_booking_without_textual_adjacency",
            "passed": bool(
                bound
                and field == "resource_type"
                and bound_obj.get("objective_id") == "v126_obj"
            ),
        },
        {
            "name": "v126_query_event_has_information_heading",
            "passed": bool(
                event_text.startswith("*INFORMACION DEL EVENTO*\n\n")
                and "Copa Primavera" in event_text
            ),
        },
    ])

    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


AGENT_V2_UNIFIED_AGENTIC_CORE = "v126"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_dialogue_binding_repair_v126r1"


# ============================================================================
# V126R2 — OBJECTIVE-SCOPED FIELD AUTHORITY
# ============================================================================
# Incidente live:
#   Turno 1: "reservar mañana a las 18 ..." -> BookingObjective conserva 18:00.
#   Turno 2: pending resource_type -> "futbol" -> binding correcto Futbol 5.
#   V105 marca create_booking autorizado y arma preflight 18:00.
#   Policy bloqueaba consultar_disponibilidad con hora_sin_evidencia_del_usuario
#   porque exigía que 18:00 apareciera otra vez en el MENSAJE ACTUAL.
#
# Regla:
#   - un campo aportado por el usuario y aceptado por un Semantic Effect verificado
#     pertenece al BookingObjective, no solamente al mensaje físico que lo originó;
#   - una continuación answers_pending verificada puede reutilizar ESOS campos del
#     MISMO objective_id;
#   - no se acepta ningún valor histórico de otro objective_id;
#   - IA sigue entendiendo lenguaje; Python sólo mantiene y verifica provenance.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r2"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r2"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_objective_field_authority_v126r2"


def _agent_v2_v126r2_verified_current_booking_act(
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    """Devuelve el create_booking actual sólo si Effect Verifier lo autorizó."""
    frame = _agent_v2_semantic_frame(perception or {}) or {}
    acts = [
        dict(act) for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "create_booking"
    ]
    if not acts:
        return {}

    verification = (
        (perception or {}).get("semantic_effect_verification")
        if isinstance((perception or {}).get("semantic_effect_verification"), dict)
        else {}
    )
    if verification.get("status") != "verified":
        return {}

    authorized_ids = {
        str(item.get("act_id") or "")
        for item in (verification.get("write_authorizations") or [])
        if isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("operation") or "create_booking") == "create_booking"
    }
    for act in acts:
        act_id = str(act.get("act_id") or "")
        if act_id and act_id in authorized_ids:
            return act
    return {}


def _agent_v2_v126r2_authority_record(
    objective: Dict[str, Any],
    act: Dict[str, Any],
    field: str,
    value: Any,
) -> Dict[str, Any]:
    evidence = ""
    proof_fields = {
        "hora": {"temporal.start", "start_time", "hora"},
        "dia": {"temporal.day", "day", "dia"},
        "resource_type": {"target.resource_type", "resource_type"},
        "cancha": {"target.label", "cancha"},
        "duracion_horas": {"temporal.duration_hours", "quantity.duration_hours", "duracion_horas"},
    }.get(field, {field})
    for item in (act.get("provenance") or []):
        if not isinstance(item, dict):
            continue
        if str(item.get("field") or "") not in proof_fields:
            continue
        if str(item.get("source") or "") != "current_user_turn":
            continue
        evidence = str(item.get("evidence") or "").strip()
        if evidence:
            break
    return {
        "field": field,
        "value": value,
        "objective_id": str((objective or {}).get("objective_id") or ""),
        "act_id": str((act or {}).get("act_id") or ""),
        "source": "verified_current_user_semantics",
        "evidence": evidence,
        "verified": True,
        "verified_at": datetime.datetime.now(TIMEZONE).isoformat(),
    }


_agent_v2_v103_build_objective_v126r2_base = _agent_v2_v103_build_objective


def _agent_v2_v103_build_objective(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    """V126R2: conserva autoridad de slots ya aportados dentro del mismo objetivo."""
    objective, engaged = _agent_v2_v103_build_objective_v126r2_base(
        perception or {}, world or {}
    )
    if not engaged or not isinstance(objective, dict) or not objective:
        return objective, engaged

    authority = dict(objective.get("field_authority") or {})
    act = _agent_v2_v126r2_verified_current_booking_act(perception or {})
    if act:
        temporal = dict(act.get("temporal") or {})
        target = dict(act.get("target") or {})
        quantity = dict(act.get("quantity") or {})

        hour = normalizar_hora_detectada(temporal.get("start"))
        if hora_es_valida(hour):
            authority["hora"] = _agent_v2_v126r2_authority_record(
                objective, act, "hora", hour
            )

        day = _agent_v2_v103_normalized_day(temporal.get("day"))
        if day:
            authority["dia"] = _agent_v2_v126r2_authority_record(
                objective, act, "dia", day
            )

        types = _canonical_configured_court_types(
            target.get("resource_types") or target.get("resource_type")
        )
        if len(types) == 1:
            authority["resource_type"] = _agent_v2_v126r2_authority_record(
                objective, act, "resource_type", types[0]
            )

        label = str(target.get("label") or "").strip()
        if label:
            authority["cancha"] = _agent_v2_v126r2_authority_record(
                objective, act, "cancha", label
            )

        duration = temporal.get("duration_hours") or quantity.get("duration_hours")
        if duration not in (None, ""):
            authority["duracion_horas"] = _agent_v2_v126r2_authority_record(
                objective, act, "duracion_horas", duration
            )

    objective["field_authority"] = authority
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    return objective, engaged


def _agent_v2_v126r2_verified_binding_for_objective(
    perception: Dict[str, Any],
    objective_id: str,
) -> Optional[Dict[str, Any]]:
    plan = (
        (perception or {}).get("turn_semantic_plan")
        if isinstance((perception or {}).get("turn_semantic_plan"), dict)
        else {}
    )
    for binding in (plan.get("bindings") or []):
        if not isinstance(binding, dict) or binding.get("verified") is not True:
            continue
        if str(binding.get("objective_id") or "") == str(objective_id or ""):
            return binding
    return None


def _agent_v2_v126r2_objective_hour_grounding(
    requested: str,
    perception: Dict[str, Any],
) -> bool:
    """Autoriza una hora heredada sólo dentro de la continuación verificada del mismo objective."""
    requested = normalizar_hora_detectada(requested)
    if not hora_es_valida(requested):
        return False

    objective = (
        (perception or {}).get("booking_objective")
        if isinstance((perception or {}).get("booking_objective"), dict)
        else {}
    )
    if str(objective.get("operation") or "") != "create_booking":
        return False
    objective_id = str(objective.get("objective_id") or "").strip()
    if not objective_id:
        return False

    record = dict((objective.get("field_authority") or {}).get("hora") or {})
    if record.get("verified") is not True:
        return False
    if str(record.get("objective_id") or "") != objective_id:
        return False
    if normalizar_hora_detectada(record.get("value")) != requested:
        return False

    objective_hour = normalizar_hora_detectada(
        ((objective.get("temporal") or {}).get("start"))
    )
    if objective_hour != requested:
        return False

    relation = _agent_v2_semantic_context_relation(
        _agent_v2_semantic_frame(perception or {})
    ) or {}
    if str(relation.get("type") or "") != "answers_pending":
        return False

    binding = _agent_v2_v126r2_verified_binding_for_objective(
        perception or {}, objective_id
    )
    if not binding:
        return False

    verification = (
        (perception or {}).get("semantic_effect_verification")
        if isinstance((perception or {}).get("semantic_effect_verification"), dict)
        else {}
    )
    authorized = any(
        isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("operation") or "create_booking") == "create_booking"
        for item in (verification.get("write_authorizations") or [])
    )
    if verification.get("status") != "verified" or not authorized:
        return False

    print(
        "   🔐 [AgentV2 V126R2 OBJECTIVE FIELD AUTHORITY] "
        f"field=hora value={requested} objective={objective_id} "
        "→ evidencia heredada del mismo BookingObjective aceptada"
    )
    return True


