def _agent_v2_v126r2_can_auto_assign_equivalent_court(
    perception: Dict[str, Any],
    available_courts: List[str],
) -> bool:
    """Completar resource_type autoriza elegir una cancha libre equivalente de ese tipo."""
    courts = [
        str(value or "").strip()
        for value in (available_courts or [])
        if str(value or "").strip()
    ]
    if not courts:
        return False

    objective = (
        (perception or {}).get("booking_objective")
        if isinstance((perception or {}).get("booking_objective"), dict)
        else {}
    )
    objective_id = str(objective.get("objective_id") or "").strip()
    if not objective_id:
        return False

    target = dict(objective.get("target") or {})
    if str(target.get("label") or "").strip():
        return False
    types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if len(types) != 1:
        return False

    binding = _agent_v2_v126r2_verified_binding_for_objective(
        perception or {}, objective_id
    )
    if not binding:
        return False
    if _agent_v2_v105_normalize_missing_field(binding.get("field")) != "resource_type":
        return False

    if not all(
        _court_matches_resource_types(court, types)
        for court in courts
    ):
        return False

    print(
        "   ✅ [AgentV2 V126R2 AUTOASSIGN AUTHORITY] "
        f"objective={objective_id} resource_type={types[0]} courts={courts}"
    )
    return True


