# ============================================================================
# V126R3 — CURRENT-TURN OBLIGATION PRIORITY
# ============================================================================
# Incidente live:
#   Mensaje actual: "Me gustaría reservar mañana a las 18 y saber sobre torneo".
#   Persistía un PendingInteraction viejo que preguntaba `hora`.
#   El Dialogue Gate, que corre antes del decomposer multi-intent, tomó "18" como
#   answers_pending del objetivo viejo y además detectó query_event.
#   Como gate_units == v125_units == 2, el runner creyó que la cobertura era
#   completa y congeló:
#       answers_pending(hora=18:00) + query_event
#   en lugar de:
#       create_booking NUEVO + query_event.
#
# Principio V126R3:
#   1) La salida del router multi-intent ES evidencia semántica generada por IA.
#      Python no mira palabras del usuario.
#   2) Un lote multi-sibling nunca puede ser short-circuited por un binding global
#      a una interacción histórica. Se resuelve cada sibling desde el mismo baseline.
#   3) Un sibling que el router IA clasificó como solicitud/pregunta nueva vuelve
#      pasivo el pending histórico sólo para esa rama.
#   4) Intenciones ambiguas/contextuales (otra, necesita_contexto, confirmar_reserva)
#      siguen pasando por Dialogue Context Resolver, por lo que respuestas elípticas
#      como "futbol", "19", "la dos", "sí" pueden contestar el pending.
#   5) No se agrega ninguna regla sobre palabras, regex ni sinónimos.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r3"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r3"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_current_turn_obligation_priority_v126r3"


AGENT_V2_V126R3_CURRENT_TURN_INDEPENDENT_INTENTS = frozenset({
    # Ontología del router IA detectar_multiples_intenciones().
    # Esto clasifica la SALIDA estructurada del modelo, no el texto del usuario.
    "reservar_cancha",
    "reservar_quincho",
    "pedir_horarios",
    "pedir_precio",
    "consulta_informativa",
    "cancelar_turno",
    "reprogramar_turno",
    "consultar_mi_turno",
    "evento_dia_completo",
})


def _agent_v2_v126r3_subintent_is_current_turn_independent(
    intent: Any,
) -> bool:
    return (
        str(intent or "").strip()
        in AGENT_V2_V126R3_CURRENT_TURN_INDEPENDENT_INTENTS
    )


def _agent_v2_v126r3_independent_sibling_plan(
    sibling_index: int,
    sibling_count: int,
    intent: str,
    *,
    source: str,
) -> Dict[str, Any]:
    """Marca sólo la relación conversacional.

    No inventa SemanticActs ni autoriza efectos. Perception sigue interpretando
    el fragmento; esta marca únicamente evita que un pending histórico lo rebautice
    como respuesta/continuación cuando el router IA ya lo clasificó como obligación
    nueva del current user turn.
    """
    return {
        "status": "verified",
        "relation": "independent",
        "bindings": [],
        "independent_acts": [],
        "route_to_general_perception": True,
        "semantic_frozen": False,
        "source": source,
        "router_intent": str(intent or "otra"),
        "sibling_index": int(sibling_index),
        "sibling_count": int(sibling_count),
    }


