# ============================================================================
# V126R4 — CONFIG-SINGLETON RESOURCE TYPE INVARIANT
# ============================================================================
# Invariante del negocio (NO interpreta lenguaje):
#   0 tipos configurados -> configuración inválida / fail-closed.
#   1 tipo configurado -> si el cliente no eligió explícitamente otro tipo/cancha,
#                         resource_type se infiere automáticamente desde config.py.
#   2+ tipos configurados -> si falta resource_type/cancha, V103 pregunta.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r4"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r4"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_single_resource_type_invariant_v126r4"


class AgentV2BusinessConfigurationError(RuntimeError):
    """Configuración del negocio incompatible con el dominio de reservas."""


def _agent_v2_v126r4_court_type_labels_from(courts: Any) -> List[str]:
    labels: List[str] = []
    seen = set()
    for court in (courts or []):
        if not isinstance(court, dict):
            continue
        label = str(court.get("type") or court.get("tipo") or "").strip()
        key = normalizar_texto_ia(label)
        if not label or not key or key in seen:
            continue
        seen.add(key)
        labels.append(label)
    return labels


def _agent_v2_v126r4_require_court_type_configuration(courts: Any = None) -> List[str]:
    source = COURTS if courts is None else courts
    labels = _agent_v2_v126r4_court_type_labels_from(source)
    if not labels:
        raise AgentV2BusinessConfigurationError(
            "CONFIGURACION INVALIDA: COURTS debe contener al menos una cancha "
            "con un campo type/tipo no vacío. No se puede crear una reserva "
            "sin una taxonomía de resource_type."
        )
    return labels


def _agent_v2_v126r4_explicit_resource_selection(perception: Dict[str, Any]) -> bool:
    """Detecta selección de tipo/cancha sólo desde semántica estructurada, nunca texto."""
    perception = perception or {}
    entities = perception.get("entities") if isinstance(perception.get("entities"), dict) else {}
    if entities.get("resource_type"):
        return True
    if any(str(v or "").strip() for v in (entities.get("resource_types") or [])):
        return True
    if str(entities.get("cancha") or "").strip():
        return True

    frame = _agent_v2_semantic_frame(perception) or {}
    targets: List[Dict[str, Any]] = []
    for target in (frame.get("targets") or []):
        if isinstance(target, dict):
            targets.append(target)
    for act in (frame.get("acts") or []):
        if isinstance(act, dict) and isinstance(act.get("target"), dict):
            targets.append(act.get("target"))

    for target in targets:
        if str(target.get("resource") or "") not in {"", "court"}:
            continue
        if target.get("resource_type"):
            return True
        if any(str(v or "").strip() for v in (target.get("resource_types") or [])):
            return True
        if str(target.get("label") or "").strip():
            return True
    return False


def _agent_v2_v126r4_apply_singleton_resource_type(
    objective: Dict[str, Any],
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    obj = dict(objective or {})
    if not obj or str(obj.get("operation") or "") != "create_booking":
        return obj

    configured_types = _agent_v2_v126r4_require_court_type_configuration()
    target = dict(obj.get("target") or {})
    target["resource"] = "court"
    existing_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    explicit_label = str(target.get("label") or "").strip()

    if existing_types or explicit_label:
        if existing_types:
            target["resource_types"] = list(existing_types)
            target["resource_type"] = existing_types[0] if len(existing_types) == 1 else None
        obj["target"] = target
        obj.pop("resource_type_config_conflict", None)
        return obj

    explicit_semantic_selection = _agent_v2_v126r4_explicit_resource_selection(perception or {})

    if len(configured_types) == 1 and not explicit_semantic_selection:
        singleton = configured_types[0]
        target["resource_types"] = [singleton]
        target["resource_type"] = singleton
        obj["target"] = target
        authority = dict(obj.get("field_authority") or {})
        authority["resource_type"] = {
            "field": "resource_type",
            "value": singleton,
            "objective_id": str(obj.get("objective_id") or ""),
            "act_id": str(obj.get("act_id") or ""),
            "source": "business_config_singleton",
            "evidence": "COURTS[*].type",
            "verified": True,
            "verified_at": datetime.datetime.now(TIMEZONE).isoformat(),
        }
        obj["field_authority"] = authority
        obj["resource_type_inference"] = {
            "source": "business_config_singleton",
            "value": singleton,
            "configured_type_count": 1,
        }
        print(
            "   🧩 [AgentV2 V126R4 RESOURCE TYPE INVARIANT] "
            f"configured_types=1 → resource_type={singleton!r} inferido automáticamente desde config"
        )
        return obj

    if len(configured_types) == 1 and explicit_semantic_selection:
        obj["target"] = target
        obj["resource_type_config_conflict"] = {
            "configured_types": list(configured_types),
            "reason": "explicit_resource_selection_not_canonicalized",
        }
        print(
            "   🛡️ [AgentV2 V126R4 RESOURCE TYPE CONFLICT] "
            "selección explícita no coincide con el único type configurado; no se reemplaza silenciosamente"
        )
        return obj

    obj["target"] = target
    return obj


_agent_v2_v103_build_objective_v126r4_base = _agent_v2_v103_build_objective


def _agent_v2_v103_build_objective(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    objective, engaged = _agent_v2_v103_build_objective_v126r4_base(
        perception or {}, world or {}
    )
    if not engaged or not isinstance(objective, dict) or not objective:
        return objective, engaged

    objective = _agent_v2_v126r4_apply_singleton_resource_type(
        objective, perception or {}
    )
    missing = list(_agent_v2_v103_compute_missing(objective))
    if objective.get("resource_type_config_conflict") and "resource_type" not in missing:
        missing.append("resource_type")
    objective["missing_fields"] = list(dict.fromkeys(missing))
    objective["status"] = "ready" if not objective["missing_fields"] else "collecting"
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    return objective, engaged


_agent_v2_v126r2_can_auto_assign_equivalent_court_v126r4_base = (
    _agent_v2_v126r2_can_auto_assign_equivalent_court
)


def _agent_v2_v126r2_can_auto_assign_equivalent_court(
    perception: Dict[str, Any],
    available_courts: List[str],
) -> bool:
    if _agent_v2_v126r2_can_auto_assign_equivalent_court_v126r4_base(
        perception or {}, available_courts or []
    ):
        return True

    courts = [str(v or "").strip() for v in (available_courts or []) if str(v or "").strip()]
    if not courts:
        return False

    objective = (
        (perception or {}).get("booking_objective")
        if isinstance((perception or {}).get("booking_objective"), dict)
        else {}
    )
    objective_id = str(objective.get("objective_id") or "").strip()
    if not objective_id:
        return False
    target = dict(objective.get("target") or {})
    if str(target.get("label") or "").strip():
        return False

    target_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    configured_types = _agent_v2_v126r4_require_court_type_configuration()
    if len(configured_types) != 1 or target_types != configured_types:
        return False

    authority = dict((objective.get("field_authority") or {}).get("resource_type") or {})
    if authority.get("verified") is not True:
        return False
    if str(authority.get("source") or "") != "business_config_singleton":
        return False
    if str(authority.get("objective_id") or "") != objective_id:
        return False
    if _canonical_configured_court_type(authority.get("value")) != configured_types[0]:
        return False
    if not all(_court_matches_resource_types(court, configured_types) for court in courts):
        return False

    print(
        "   ✅ [AgentV2 V126R4 SINGLETON AUTOASSIGN] "
        f"objective={objective_id} resource_type={configured_types[0]} courts={courts}"
    )
    return True


_reload_runtime_config_v126r4_base = _reload_runtime_config


def _reload_runtime_config(reason: str = "admin") -> bool:
    try:
        from cancheria.config import legacy_config as config_module
        candidate = importlib.reload(config_module)
        _agent_v2_v126r4_require_court_type_configuration(getattr(candidate, "COURTS", []))
    except Exception as exc:
        print(f"   ❌ [AgentV2 V126R4 CONFIG INVALID] hot reload rechazado: {exc}")
        return False
    return _reload_runtime_config_v126r4_base(reason)


_run_agent_v2_invariant_evals_v126r4_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126r4_base()
    results = list(result.get("results") or [])
    global COURTS
    original_courts = COURTS
    try:
        COURTS = []
        zero_rejected = False
        try:
            _agent_v2_v126r4_require_court_type_configuration()
        except AgentV2BusinessConfigurationError:
            zero_rejected = True

        COURTS = [
            {"name": "Cancha 1", "type": "Futbol 5"},
            {"name": "Cancha 2", "type": "Futbol 5"},
        ]
        base_obj = {
            "objective_id": "v126r4_singleton",
            "operation": "create_booking",
            "status": "collecting",
            "target": {"resource": "court"},
            "temporal": {"day": "Martes 22/09", "start": "18:00", "duration_hours": 1.0},
            "addons": {},
            "field_authority": {},
        }
        no_type_perception = {
            "semantic_frame": {
                "acts": [{
                    "act_id": "act_singleton",
                    "operation": "create_booking",
                    "domain": "booking",
                    "target": {"resource": "court"},
                    "temporal": {"day": "Martes 22/09", "start": "18:00", "duration_hours": 1.0},
                }]
            }
        }
        singleton = _agent_v2_v126r4_apply_singleton_resource_type(base_obj, no_type_perception)
        singleton_missing = _agent_v2_v103_compute_missing(singleton)
        singleton_ok = bool(
            (singleton.get("target") or {}).get("resource_type") == "Futbol 5"
            and (singleton.get("target") or {}).get("resource_types") == ["Futbol 5"]
            and "resource_type" not in singleton_missing
            and ((singleton.get("field_authority") or {}).get("resource_type") or {}).get("source") == "business_config_singleton"
        )
        singleton_autoassign_ok = _agent_v2_v126r2_can_auto_assign_equivalent_court(
            {"booking_objective": singleton, "turn_semantic_plan": {"status": "verified", "relation": "independent", "bindings": []}},
            ["Cancha 1", "Cancha 2"],
        )

        COURTS = [
            {"name": "Cancha 1", "type": "Futbol 5"},
            {"name": "Cancha 2", "type": "Tenis"},
        ]
        multi = _agent_v2_v126r4_apply_singleton_resource_type(base_obj, no_type_perception)
        multi_missing = _agent_v2_v103_compute_missing(multi)
        multi_ok = bool(
            not (multi.get("target") or {}).get("resource_type")
            and "resource_type" in multi_missing
        )

        COURTS = [
            {"name": "Cancha 1", "type": "Futbol 5"},
            {"name": "Cancha 2", "type": "Futbol 5"},
        ]
        explicit_invalid = {
            "semantic_frame": {
                "acts": [{
                    "operation": "create_booking",
                    "domain": "booking",
                    "target": {"resource": "court", "resource_type": "Tenis"},
                }]
            }
        }
        conflict = _agent_v2_v126r4_apply_singleton_resource_type(base_obj, explicit_invalid)
        conflict_ok = bool(
            not (conflict.get("target") or {}).get("resource_type")
            and conflict.get("resource_type_config_conflict")
        )
    finally:
        COURTS = original_courts

    results.extend([
        {"name": "v126r4_zero_types_is_invalid_configuration", "passed": zero_rejected},
        {"name": "v126r4_single_type_is_inferred_without_user_question", "passed": singleton_ok},
        {"name": "v126r4_single_type_can_autoassign_equivalent_court", "passed": singleton_autoassign_ok},
        {"name": "v126r4_multiple_types_still_require_resource_type", "passed": multi_ok},
        {"name": "v126r4_explicit_unconfigured_type_is_not_silently_overwritten", "passed": conflict_ok},
    ])
    passed = sum(1 for item in results if bool(item.get("passed") if "passed" in item else item.get("ok")))
    total = len(results)
    return {"ok": passed == total, "passed": passed, "total": total, "results": results}


AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r4"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r4"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-21_single_resource_type_invariant_v126r4"


# ============================================================================
# V126R5 — SEMANTIC SIBLING COVERAGE + CROSS-TURN RESOURCE CONTINUITY
# ============================================================================
# Incidente live:
#
# Turno A:
#   "Tienen cancha libre mañana de padel y cuales son los horarios de atencion?
#    Y tienen quincho?"
#
# El router produjo:
#   pedir_horarios("...padel + horarios de atención")
#   consulta_informativa("quincho")
#
# El primer sibling terminó reducido a query_policy(attention_schedule), por lo
# que la consulta real de disponibilidad de Pádel se perdió.
#
# Turno B:
#   "Ok quiero para hoy a las 4 de la tarde con quincho"
#
# V126R3 protegió correctamente el request nuevo contra pendings viejos, pero al
# volver toda la memoria "pasiva" también perdió el recurso conversacional Pádel.
# Además, el router separó "reservar_cancha" y "reservar_quincho" aunque el quincho
# era un addon del MISMO objetivo transaccional.
#
# Principios V126R5:
#   1) El router sigue siendo IA. Python NO interpreta palabras del usuario.
#   2) Un auditor semántico independiente revisa lotes multi-sibling:
#      - obligaciones que requieren fuentes/efectos distintos se separan;
#      - addons/modificadores del mismo objetivo se mantienen juntos.
#   3) Un booking nuevo sin resource_type puede heredar el recurso de la
#      conversación INMEDIATAMENTE anterior sólo si una IA de continuidad lo
#      confirma y cita evidencia literal del turno USER anterior.
#   4) Python valida esa salida contra config.COURTS. Nunca inventa ni traduce
#      deporte/tipo por keywords.
#   5) El current turn siempre gana: si ya especificó tipo/cancha, no se hereda.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r5"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r5"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-22_resource_focus_continuity_v126r5"


# ---------------------------------------------------------------------------
# 1) Auditor de cobertura / agrupación del router multi-subintención.
# ---------------------------------------------------------------------------
_detectar_multiples_intenciones_v126r5_base = detectar_multiples_intenciones


def _agent_v2_v126r5_fragment_belongs_to_message(
    mensaje: str,
    fragmento: str,
) -> bool:
    """Validación representacional; no clasifica significado."""
    whole = normalizar_texto_ia(mensaje or "")
    part = normalizar_texto_ia(fragmento or "")
    return bool(part and whole and part in whole)


async def _agent_v2_v126r5_audit_subintent_coverage(
    mensaje: str,
    initial: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    rows = [
        {
            "intencion": str(item.get("intencion") or "otra"),
            "fragmento": str(item.get("fragmento") or ""),
        }
        for item in (initial or [])
        if isinstance(item, dict)
    ]
    if len(rows) <= 1:
        return rows

    allowed = {
        "reservar_cancha", "reservar_quincho", "pedir_horarios", "pedir_precio",
        "consulta_informativa", "confirmar_reserva", "cancelar_turno",
        "reprogramar_turno", "consultar_mi_turno", "evento_dia_completo",
        "otra", "necesita_contexto",
    }

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos SEMANTIC SIBLING COVERAGE AUDITOR de un agente de reservas. "
                        "Recibís el mensaje ORIGINAL y una descomposición previa. Corregí "
                        "SOLAMENTE la cobertura y agrupación de obligaciones por significado; "
                        "no ejecutes tools ni inventes información.\n\n"

                        "PRINCIPIO: cada sibling debe representar una obligación que pueda "
                        "resolverse independientemente. Dos preguntas/acciones que requieren "
                        "fuentes o efectos diferentes deben ser siblings distintos. En cambio, "
                        "un addon/modificador que forma parte del MISMO objetivo transaccional "
                        "debe permanecer dentro del mismo sibling.\n\n"

                        "DISTINCIÓN IMPORTANTE:\n"
                        "- pedir_horarios = consultar disponibilidad/slots del CALENDARIO "
                        "(cancha libre, turnos disponibles, disponibilidad por día/hora).\n"
                        "- los horarios generales de apertura/atención del NEGOCIO son "
                        "consulta_informativa, porque salen de la política/configuración y no "
                        "del calendario de ocupación.\n"
                        "Si el mismo enunciado pide disponibilidad del calendario Y horarios "
                        "generales de atención, separalos aunque estén en la misma oración.\n\n"

                        "OBJETIVOS COMPUESTOS:\n"
                        "Si el usuario quiere reservar una cancha y además pide un quincho como "
                        "parte de ESA MISMA reserva (addon del mismo plan), NO lo conviertas en "
                        "dos objetivos independientes. Devolvé un único reservar_cancha cuyo "
                        "fragmento conserve también el pedido de quincho. Sólo devolvé "
                        "reservar_quincho por separado cuando sea realmente una reserva/acción "
                        "independiente con identidad propia.\n"
                        "REGLA COMERCIAL DE ESTE NEGOCIO: si el mismo lote está creando o "
                        "completando una reserva de cancha y además consulta si hay "
                        "quincho/parrilla, esa consulta también solicita incluir el addon en "
                        "ESA reserva. Conservá todo en el mismo sibling reservar_cancha; la "
                        "respuesta final igualmente debe informar disponibilidad y precio del "
                        "servicio. Una consulta de quincho sin objetivo de reserva en curso "
                        "sigue siendo consulta_informativa.\n\n"

                        "SLOTS DEL MISMO OBJETIVO:\n"
                        "Una afirmación de duración como '1 hora' o 'hora y media' NO es "
                        "pedir_horarios. Si en el mismo lote hay una reserva/selección, "
                        "mantenela dentro del sibling reservar_cancha como dato del mismo "
                        "objetivo. Del mismo modo, 'quiero reservar mañana a las 18, ¿tendrán "
                        "disponible?' es un único objetivo reservar_cancha: consultar el slot "
                        "exacto es su preflight, no una obligación sibling independiente.\n\n"

                        "No uses keyword matching. Razoná por significado. No elimines ninguna "
                        "obligación. No agregues nada que el usuario no haya dicho. Cada fragmento "
                        "debe ser una cita literal CONTIGUA del mensaje original; para un objetivo "
                        "compuesto podés usar el tramo literal completo que contiene todos sus "
                        "modificadores.\n\n"

                        "INTENCIONES VÁLIDAS: reservar_cancha, reservar_quincho, pedir_horarios, "
                        "pedir_precio, consulta_informativa, confirmar_reserva, cancelar_turno, "
                        "reprogramar_turno, consultar_mi_turno, evento_dia_completo, otra, "
                        "necesita_contexto.\n\n"

                        "Respondé SOLO JSON: "
                        "{\"intenciones\":[{\"intencion\":\"...\",\"fragmento\":\"...\"}],"
                        "\"reason\":\"...\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "mensaje_original": mensaje,
                        "descomposicion_previa": rows,
                    }, ensure_ascii=False),
                },
            ],
            temperature=0.0,
            max_tokens=700,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        data = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V126R5 SIBLING AUDIT] "
            f"auditor no disponible: {type(exc).__name__}: {exc}"
        )
        return rows

    audited: List[Dict[str, Any]] = []
    seen = set()
    for raw in (data.get("intenciones") or []):
        if not isinstance(raw, dict):
            continue
        intent = str(raw.get("intencion") or "").strip()
        fragment = str(raw.get("fragmento") or "").strip()
        if intent not in allowed:
            continue
        if not _agent_v2_v126r5_fragment_belongs_to_message(mensaje, fragment):
            continue
        signature = (
            intent.casefold(),
            normalizar_texto_ia(fragment),
        )
        if signature in seen:
            continue
        seen.add(signature)
        audited.append({
            "intencion": intent,
            "fragmento": fragment,
        })

    if not audited:
        return rows

    print(
        "   🧩 [AgentV2 V126R5 SIBLING AUDIT] "
        f"before={[(x['intencion'], x['fragmento'][:36]) for x in rows]} "
        f"after={[(x['intencion'], x['fragmento'][:36]) for x in audited]}"
    )
    return audited


async def detectar_multiples_intenciones(mensaje: str) -> List[Dict]:
    initial = await _detectar_multiples_intenciones_v126r5_base(mensaje)
    # El segundo pase sólo existe cuando el primer router vio más de una unidad:
    # ahí es donde aparecen los errores de frontera sibling/addon que V126R5 trata.
    if len(initial or []) <= 1:
        return initial
    return await _agent_v2_v126r5_audit_subintent_coverage(
        mensaje,
        initial,
    )


# ---------------------------------------------------------------------------
# 2) Continuidad semántica del resource_type entre turnos.
# ---------------------------------------------------------------------------
def _agent_v2_v126r5_current_booking_has_resource(
    perception: Dict[str, Any],
) -> bool:
    entities = (
        (perception or {}).get("entities")
        if isinstance((perception or {}).get("entities"), dict)
        else {}
    )
    if _canonical_configured_court_types(
        entities.get("resource_types") or entities.get("resource_type")
    ):
        return True
    if str(entities.get("cancha") or "").strip():
        return True

    frame = _agent_v2_semantic_frame(perception or {}) or {}
    for act in (frame.get("acts") or []):
        if not isinstance(act, dict):
            continue
        if str(act.get("operation") or "") != "create_booking":
            continue
        target = dict(act.get("target") or {})
        if _canonical_configured_court_types(
            target.get("resource_types") or target.get("resource_type")
        ):
            return True
        if str(target.get("label") or "").strip():
            return True
    return False


def _agent_v2_v126r5_previous_user_turn(
    world: Dict[str, Any],
    current_message: str,
) -> Dict[str, Any]:
    """Último turno USER distinto del mensaje actual; no busca contexto lejano."""
    rows = []
    try:
        rows = list(_agent_v2_history_with_reference_ids(world or {}))
    except Exception:
        rows = list(
            (((world or {}).get("stored_memory") or {}).get("history") or [])
        )

    current_key = normalizar_texto_ia(current_message or "")
    for raw in reversed(rows):
        if not isinstance(raw, dict):
            continue
        if str(raw.get("role") or "") != "user":
            continue
        content = str(raw.get("content") or "").strip()
        if not content:
            continue
        if normalizar_texto_ia(content) == current_key:
            continue
        return {
            "role": "user",
            "content": content,
            "reference_id": raw.get("reference_id"),
            "timestamp": raw.get("timestamp"),
        }
    return {}


def _agent_v2_v126r5_recent_dialogue(
    world: Dict[str, Any],
    current_message: str,
) -> List[Dict[str, Any]]:
    try:
        rows = list(_agent_v2_history_with_reference_ids(world or {}))
    except Exception:
        rows = list(
            (((world or {}).get("stored_memory") or {}).get("history") or [])
        )

    current_key = normalizar_texto_ia(current_message or "")
    cleaned: List[Dict[str, Any]] = []
    skipped_current = False
    for raw in rows[-8:]:
        if not isinstance(raw, dict):
            continue
        role = str(raw.get("role") or "")
        content = str(raw.get("content") or "").strip()
        if role not in {"user", "assistant"} or not content:
            continue
        if (
            role == "user"
            and normalizar_texto_ia(content) == current_key
            and not skipped_current
        ):
            skipped_current = True
            continue
        cleaned.append({
            "role": role,
            "content": content[:1200],
            "reference_id": raw.get("reference_id"),
            "timestamp": raw.get("timestamp"),
        })
    return cleaned[-6:]


def _agent_v2_v126r5_validate_resource_continuity(
    decision: Dict[str, Any],
    *,
    current_message: str,
    previous_user_turn: Dict[str, Any],
) -> Dict[str, Any]:
    if not isinstance(decision, dict):
        return {}
    if decision.get("inherit") is not True:
        return {}
    try:
        confidence = float(decision.get("confidence") or 0.0)
    except Exception:
        confidence = 0.0
    if confidence < 0.80:
        return {}

    canonical = _canonical_configured_court_type(
        decision.get("resource_type")
    )
    if not canonical:
        return {}

    previous_evidence = str(decision.get("previous_user_evidence") or "").strip()
    current_evidence = str(decision.get("current_user_evidence") or "").strip()
    previous_text = str((previous_user_turn or {}).get("content") or "")

    if not previous_evidence or not current_evidence:
        return {}
    if normalizar_texto_ia(previous_evidence) not in normalizar_texto_ia(previous_text):
        return {}
    if normalizar_texto_ia(current_evidence) not in normalizar_texto_ia(current_message):
        return {}

    return {
        "resource_type": canonical,
        "confidence": confidence,
        "previous_user_evidence": previous_evidence,
        "current_user_evidence": current_evidence,
        "reason": str(decision.get("reason") or "").strip(),
        "previous_reference_id": (previous_user_turn or {}).get("reference_id"),
    }


async def _agent_v2_v126r5_resolve_resource_continuity(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Decide sólo continuidad de tipo de cancha; no autoriza ninguna escritura."""
    if "create_booking" not in _agent_v2_v103_ops(perception or {}):
        return {}
    if _agent_v2_v126r5_current_booking_has_resource(perception or {}):
        return {}

    configured_types = _configured_court_type_labels()
    # 0/1 tipos pertenecen a V126R4. V126R5 sólo resuelve continuidad cuando
    # realmente existe una elección contextual entre múltiples tipos.
    if len(configured_types) <= 1:
        return {}

    previous_user = _agent_v2_v126r5_previous_user_turn(
        world or {}, mensaje
    )
    if not previous_user:
        return {}

    recent = _agent_v2_v126r5_recent_dialogue(
        world or {}, mensaje
    )

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos RESOURCE CONTINUITY RESOLVER. El CURRENT_USER_TURN ya fue "
                        "interpretado como create_booking pero NO contiene un resource_type "
                        "estructurado. Tu única tarea es decidir si el nuevo booking continúa "
                        "inequívocamente el tipo de cancha establecido por el TURNO USER "
                        "INMEDIATAMENTE ANTERIOR.\n\n"

                        "No decidas intención general, no elijas tools, no autorices writes y "
                        "no uses coincidencias de palabras. Interpretá continuidad conversacional.\n\n"

                        "HEREDÁ sólo si el usuario actual está continuando naturalmente ese "
                        "mismo recurso y omitió el tipo porque ya estaba establecido. Si parece "
                        "un pedido autónomo, un cambio de tema o existe duda real, inherit=false. "
                        "No uses conversaciones antiguas: la autoridad de recurso sólo puede "
                        "venir del previous_user_turn suministrado.\n\n"

                        "resource_type debe ser EXACTAMENTE una de configured_court_types. "
                        "previous_user_evidence debe ser una cita literal del previous_user_turn "
                        "que establezca el recurso. current_user_evidence debe ser una cita literal "
                        "del current_user_turn que demuestre continuidad/acción actual. "
                        "No inventes evidencia.\n\n"

                        "Respondé SOLO JSON: "
                        "{\"inherit\":true|false,\"resource_type\":null|\"...\","
                        "\"previous_user_evidence\":\"...\",\"current_user_evidence\":\"...\","
                        "\"confidence\":0.0,\"reason\":\"...\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "current_semantic_frame": _agent_v2_semantic_frame(
                            perception or {}
                        ),
                        "configured_court_types": configured_types,
                        "previous_user_turn": previous_user,
                        "recent_dialogue_for_disambiguation": recent,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=320,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        data = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V126R5 RESOURCE CONTINUITY] "
            f"resolver no disponible: {type(exc).__name__}: {exc}"
        )
        return {}

    verified = _agent_v2_v126r5_validate_resource_continuity(
        data,
        current_message=mensaje,
        previous_user_turn=previous_user,
    )
    if verified:
        print(
            "   🔗 [AgentV2 V126R5 RESOURCE CONTINUITY] "
            f"resource_type={verified.get('resource_type')} "
            f"confidence={verified.get('confidence'):.2f} "
            "← previous_user_turn"
        )
    return verified


def _agent_v2_v126r5_inject_resource_context(
    perception: Dict[str, Any],
    resolved: Dict[str, Any],
) -> Dict[str, Any]:
    clean = dict(perception or {})
    resource_type = str(resolved.get("resource_type") or "").strip()
    if not resource_type:
        return clean

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts = []
    changed = False
    for raw in (frame.get("acts") or []):
        if not isinstance(raw, dict):
            continue
        act = dict(raw)
        if str(act.get("operation") or "") == "create_booking":
            target = dict(act.get("target") or {})
            existing = _canonical_configured_court_types(
                target.get("resource_types") or target.get("resource_type")
            )
            if not existing and not str(target.get("label") or "").strip():
                target["resource"] = "court"
                target["resource_types"] = [resource_type]
                target["resource_type"] = resource_type
                act["target"] = target
                provenance = [
                    dict(item)
                    for item in (act.get("provenance") or [])
                    if isinstance(item, dict)
                ]
                provenance.append({
                    "field": "target.resource_type",
                    "source": "previous_user_turn",
                    "evidence": resolved.get("previous_user_evidence"),
                    "reference_id": resolved.get("previous_reference_id"),
                    "scope_id": None,
                    "question_id": None,
                    "option_id": None,
                })
                act["provenance"] = provenance
                changed = True
        acts.append(act)

    if not changed:
        return clean

    frame["acts"] = acts
    create_acts = [
        act for act in acts
        if str(act.get("operation") or "") == "create_booking"
    ]
    if create_acts:
        primary_target = dict(create_acts[0].get("target") or {})
        frame["targets"] = [primary_target]
    clean["semantic_frame"] = frame

    entities = dict(clean.get("entities") or {})
    entities["resource_types"] = [resource_type]
    entities["resource_type"] = resource_type
    clean["entities"] = entities
    clean["resource_context_resolution"] = {
        "resolved": True,
        "source": "v126r5_previous_user_turn",
        **resolved,
    }
    return clean


def _agent_v2_v126r5_rebuild_booking_after_resource_inheritance(
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = dict(perception or {})
    objective, engaged = _agent_v2_v103_build_objective(
        clean, world or {}
    )
    if not engaged or not objective:
        return clean

    missing = list(_agent_v2_v103_compute_missing(objective))
    objective["missing_fields"] = list(dict.fromkeys(missing))
    objective["status"] = "ready" if not missing else "collecting"
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)

    clean = _agent_v2_v103_apply_objective_to_perception(
        clean, objective
    )
    clean["booking_objective"] = dict(objective)
    clean["_v103_booking_engaged"] = True

    if missing:
        clean.pop("_v105_pending_booking_completed", None)
        clean.pop("_v109_ready_booking_authorized", None)
        collection = _agent_v2_v104_build_collection_contract(
            clean, world or {}
        )
        if collection:
            clean["booking_collection_contract"] = collection
        else:
            clean.pop("booking_collection_contract", None)
    else:
        repaired_contract = _agent_v2_v109_ready_execution_contract(
            clean, world or {}, objective
        )
        if repaired_contract:
            clean["execution_contract"] = repaired_contract
            clean["booking_collection_contract"] = {}
            clean["_v105_pending_booking_completed"] = True
            clean["_v109_ready_booking_authorized"] = True

    clean = _agent_v2_v100_attach_desired_state_and_task_graph(
        clean, world or {}
    )
    clean.setdefault("desired_state", {})["booking_objective"] = dict(objective)
    clean.setdefault("task_graph", {})["booking_missing_fields"] = list(missing)
    clean["task_graph"]["booking_objective_id"] = objective.get("objective_id")
    clean["_v100_semantic_frozen"] = True

    print(
        "   🧠 [AgentV2 V126R5 BOOKING REBUILD] "
        f"objective={objective.get('objective_id')} "
        f"resource_type={(objective.get('target') or {}).get('resource_type')} "
        f"missing={missing}"
    )
    return clean


_percibir_turno_agent_v2_v126r5_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v126r5_base(
        mensaje, world, image_path, learning_policy
    )

    if "create_booking" not in _agent_v2_v103_ops(perception or {}):
        return perception
    if _agent_v2_v126r5_current_booking_has_resource(perception or {}):
        return perception

    resolved = await _agent_v2_v126r5_resolve_resource_continuity(
        mensaje,
        perception or {},
        world or {},
    )
    if not resolved:
        return perception

    repaired = _agent_v2_v126r5_inject_resource_context(
        perception or {},
        resolved,
    )
    return _agent_v2_v126r5_rebuild_booking_after_resource_inheritance(
        repaired,
        world or {},
    )


