_run_agent_v2_invariant_evals_v126r5_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126r5_base()
    results = list(result.get("results") or [])

    prior = {
        "role": "user",
        "content": "Tienen cancha libre mañana de padel",
        "reference_id": "prior_ref",
    }
    valid_decision = {
        "inherit": True,
        "resource_type": "Pádel",
        "previous_user_evidence": "cancha libre mañana de padel",
        "current_user_evidence": "quiero para hoy a las 4 de la tarde",
        "confidence": 0.96,
        "reason": "continuidad del recurso consultado inmediatamente antes",
    }
    verified = _agent_v2_v126r5_validate_resource_continuity(
        valid_decision,
        current_message="Ok quiero para hoy a las 4 de la tarde con quincho",
        previous_user_turn=prior,
    )

    invalid_stale_evidence = _agent_v2_v126r5_validate_resource_continuity(
        {
            **valid_decision,
            "previous_user_evidence": "tenis",
        },
        current_message="Ok quiero para hoy a las 4 de la tarde con quincho",
        previous_user_turn=prior,
    )

    fake_perception = {
        "semantic_frame": {
            "acts": [{
                "act_id": "a1",
                "operation": "create_booking",
                "domain": "booking",
                "target": {"resource": "court"},
                "temporal": {"day": "Martes 22/09", "start": "16:00"},
                "commitment": {"wants_write": True, "wants_information": False},
                "provenance": [],
            }]
        },
        "entities": {
            "dia_resuelto": "Martes 22/09",
            "hora": "16:00",
        },
    }
    injected = _agent_v2_v126r5_inject_resource_context(
        fake_perception,
        {
            "resource_type": "Pádel",
            "previous_user_evidence": "padel",
            "current_user_evidence": "quiero para hoy",
            "previous_reference_id": "prior_ref",
            "confidence": 0.95,
            "reason": "test",
        },
    )
    injected_type = _canonical_configured_court_types(
        (((_agent_v2_semantic_frame(injected).get("acts") or [{}])[0])
         .get("target") or {}).get("resource_types")
    )

    results.extend([
        {
            "name": "v126r5_resource_continuity_accepts_immediate_verified_prior_user_evidence",
            "passed": bool(
                verified
                and verified.get("resource_type") == "Pádel"
            ),
        },
        {
            "name": "v126r5_resource_continuity_rejects_nonliteral_prior_evidence",
            "passed": not bool(invalid_stale_evidence),
        },
        {
            "name": "v126r5_resource_injection_updates_create_booking_semantics",
            "passed": injected_type == ["Pádel"],
        },
    ])

    passed = sum(
        1
        for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


