def _agent_v2_v126r6_same_physical_user_turn(
    row_content: str,
    current_message: str,
) -> bool:
    """Representational identity for a V125 sibling vs its full physical turn."""
    row_key = normalizar_texto_ia(row_content or "")
    current_key = normalizar_texto_ia(current_message or "")
    if not row_key or not current_key:
        return False
    return row_key == current_key or current_key in row_key


def _agent_v2_v126r5_previous_user_turn(
    world: Dict[str, Any],
    current_message: str,
) -> Dict[str, Any]:
    """Return previous USER turn, skipping the current full turn when processing a sibling."""
    try:
        rows = list(_agent_v2_history_with_reference_ids(world or {}))
    except Exception:
        rows = list((((world or {}).get("stored_memory") or {}).get("history") or []))

    skipped_current = False
    for raw in reversed(rows):
        if not isinstance(raw, dict) or str(raw.get("role") or "") != "user":
            continue
        content = str(raw.get("content") or "").strip()
        if not content:
            continue
        if (
            not skipped_current
            and _agent_v2_v126r6_same_physical_user_turn(content, current_message)
        ):
            skipped_current = True
            continue
        return {
            "role": "user",
            "content": content,
            "reference_id": raw.get("reference_id"),
            "timestamp": raw.get("timestamp"),
        }
    return {}


def _agent_v2_v126r5_recent_dialogue(
    world: Dict[str, Any],
    current_message: str,
) -> List[Dict[str, Any]]:
    try:
        rows = list(_agent_v2_history_with_reference_ids(world or {}))
    except Exception:
        rows = list((((world or {}).get("stored_memory") or {}).get("history") or []))

    out: List[Dict[str, Any]] = []
    skipped_current = False
    for raw in reversed(rows):
        if not isinstance(raw, dict):
            continue
        role = str(raw.get("role") or "")
        content = str(raw.get("content") or "").strip()
        if role not in {"user", "assistant"} or not content:
            continue
        if (
            role == "user"
            and not skipped_current
            and _agent_v2_v126r6_same_physical_user_turn(content, current_message)
        ):
            skipped_current = True
            continue
        out.append({
            "role": role,
            "content": content[:1200],
            "reference_id": raw.get("reference_id"),
            "timestamp": raw.get("timestamp"),
        })
        if len(out) >= 6:
            break
    out.reverse()
    return out


def _agent_v2_v126r6_verified_resource_focus(
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Use only availability context that came from a real calendar observation."""
    focus = _agent_v2_v91_verified_availability_focus(world or {}) or {}
    if not focus:
        return {}
    types = _canonical_configured_court_types(
        focus.get("resource_types")
        or ([focus.get("resource_type")] if focus.get("resource_type") else [])
    )
    if not types:
        return {}
    return {
        "resource_types": list(types),
        "resource_type": types[0] if len(types) == 1 else None,
        "day_iso": focus.get("day_iso"),
        "dia": focus.get("dia"),
        "hora": focus.get("hora"),
        "franja_dia": focus.get("franja_dia"),
        "duracion_horas": focus.get("duracion_horas"),
        "source_message": focus.get("source_message"),
        "reference_id": focus.get("reference_id"),
        "scope_id": focus.get("scope_id"),
        "created_at": focus.get("created_at"),
        "source": "verified_availability_context",
    }


def _agent_v2_v126r6_validate_focus_decision(
    decision: Dict[str, Any],
    *,
    current_message: str,
    focus: Dict[str, Any],
) -> Dict[str, Any]:
    if not isinstance(decision, dict) or decision.get("continues_resource_focus") is not True:
        return {}
    try:
        confidence = float(decision.get("confidence") or 0.0)
    except Exception:
        confidence = 0.0
    if confidence < 0.80:
        return {}

    evidence = str(decision.get("current_user_evidence") or "").strip()
    if not evidence:
        return {}
    if normalizar_texto_ia(evidence) not in normalizar_texto_ia(current_message or ""):
        return {}

    decided = _canonical_configured_court_types(
        decision.get("resource_types") or decision.get("resource_type")
    )
    focused = _canonical_configured_court_types(
        focus.get("resource_types") or focus.get("resource_type")
    )
    if not decided or not focused or set(decided) != set(focused):
        return {}

    return {
        "resource_types": list(focused),
        "resource_type": focused[0] if len(focused) == 1 else None,
        "confidence": confidence,
        "current_user_evidence": evidence,
        "reason": str(decision.get("reason") or "").strip(),
        "previous_reference_id": focus.get("reference_id"),
        "source": "verified_availability_context",
    }


async def _agent_v2_v126r5_resolve_resource_continuity(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Inherit only the court type from verified recent availability when AI confirms continuity."""
    if "create_booking" not in _agent_v2_v103_ops(perception or {}):
        return {}
    if _agent_v2_v126r5_current_booking_has_resource(perception or {}):
        return {}
    # An explicit current-turn resource selection always wins, even if it is invalid.
    if _agent_v2_v126r4_explicit_resource_selection(perception or {}):
        return {}

    configured_types = _configured_court_type_labels()
    if len(configured_types) <= 1:
        return {}

    focus = _agent_v2_v126r6_verified_resource_focus(world or {})
    if not focus:
        print(
            "   🧭 [AgentV2 V126R6 RESOURCE FOCUS] "
            "inherit=False reason=no_verified_availability_focus"
        )
        return {}

    previous_user = _agent_v2_v126r5_previous_user_turn(world or {}, mensaje)
    recent = _agent_v2_v126r5_recent_dialogue(world or {}, mensaje)

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos RESOURCE FOCUS CONTINUITY RESOLVER. "
                        "El current_user_turn ya es create_booking y NO trae un tipo de cancha "
                        "explícito estructurado. verified_availability_focus proviene de una "
                        "consulta REAL reciente al calendario. Decidí únicamente si el booking "
                        "actual mantiene ese mismo tipo de cancha como foco conversacional. "
                        "No decidas día, hora, duración, cancha concreta, addons, tools ni writes. "
                        "El usuario puede cambiar día/hora y seguir con el mismo recurso. "
                        "Agregar o modificar addons/servicios del mismo booking no significa "
                        "cambiar el recurso principal. Si el booking es autónomo o hay duda real, "
                        "continues_resource_focus=false. Si true, resource_types debe copiar "
                        "EXACTAMENTE verified_availability_focus.resource_types. "
                        "current_user_evidence debe ser una cita literal del current_user_turn. "
                        "Respondé SOLO JSON: "
                        "{\"continues_resource_focus\":true|false,"
                        "\"resource_types\":[],"
                        "\"current_user_evidence\":\"\","
                        "\"confidence\":0.0,"
                        "\"reason\":\"\"}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps({
                        "current_user_turn": mensaje,
                        "current_semantic_frame": _agent_v2_semantic_frame(perception or {}),
                        "verified_availability_focus": focus,
                        "previous_user_turn": previous_user,
                        "recent_dialogue": recent,
                        "configured_court_types": configured_types,
                    }, ensure_ascii=False, default=str),
                },
            ],
            temperature=0.0,
            max_tokens=320,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        decision = _loads_llm_json_object(response.choices[0].message.content.strip())
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V126R6 RESOURCE FOCUS] "
            f"resolver no disponible: {type(exc).__name__}: {exc}"
        )
        return {}

    verified = _agent_v2_v126r6_validate_focus_decision(
        decision,
        current_message=mensaje,
        focus=focus,
    )
    if not verified:
        print(
            "   🧭 [AgentV2 V126R6 RESOURCE FOCUS] "
            f"inherit=False reason={decision.get('reason')}"
        )
        return {}

    print(
        "   🔗 [AgentV2 V126R6 RESOURCE FOCUS] "
        f"inherit=True resource_types={verified.get('resource_types')} "
        f"confidence={verified.get('confidence'):.2f}"
    )
    return verified


_agent_v2_build_response_obligations_v126r6_base = _agent_v2_build_response_obligations


def _agent_v2_build_response_obligations(
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
    world: Dict[str, Any],
    status: str,
) -> Dict[str, Any]:
    """Do not append a second missing-field question already owned by availability."""
    obligations = _agent_v2_build_response_obligations_v126r6_base(
        perception, observations, world, status
    )
    rows = [dict(o) for o in (observations or []) if isinstance(o, dict)]

    covered_fields = set()
    for obs in rows:
        if str(obs.get("tool") or "") != "consultar_disponibilidad":
            continue
        if obs.get("ok") is not True or str(obs.get("status") or "") != "needs_user_input":
            continue
        data = dict(obs.get("data") or {})
        options = list(obs.get("options") or data.get("options") or [])
        hours = list(data.get("horas_disponibles") or [])
        if not (options or hours):
            continue
        for field in list(obs.get("missing") or data.get("missing") or []):
            normalized = _agent_v2_v105_normalize_missing_field(field)
            if normalized:
                covered_fields.add(normalized)

    if not covered_fields:
        return obligations

    kept = []
    removed = []
    for item in (obligations or {}).get("items") or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("type") or "") == "missing_field_question":
            field = _agent_v2_v105_normalize_missing_field(item.get("field"))
            if field in covered_fields:
                removed.append(field)
                continue
        kept.append(item)

    if removed:
        print(
            "   🧾 [AgentV2 V126R6 OBLIGATION DEDUPE] "
            f"availability ya cubre fields={sorted(set(removed))} "
            "→ omito pregunta duplicada"
        )

    obligations = dict(obligations or {})
    obligations["items"] = kept
    covered_tools = set(obligations.get("covered_tools") or [])
    if removed:
        covered_tools.update({"consultar_disponibilidad", "solicitar_dato"})
    obligations["covered_tools"] = sorted(covered_tools)
    # Removing a duplicate obligation must not reopen the generative response path.
    if removed:
        obligations["complete"] = True
    return obligations


_run_agent_v2_invariant_evals_v126r6_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126r6_base()
    results = list(result.get("results") or [])

    focus = {"resource_types": ["Pádel"], "resource_type": "Pádel", "reference_id": "r1"}
    good = _agent_v2_v126r6_validate_focus_decision(
        {
            "continues_resource_focus": True,
            "resource_types": ["Pádel"],
            "current_user_evidence": "quiero para hoy a las 4",
            "confidence": 0.95,
            "reason": "continúa el foco",
        },
        current_message="Ok quiero para hoy a las 4 con quincho",
        focus=focus,
    )
    bad = _agent_v2_v126r6_validate_focus_decision(
        {
            "continues_resource_focus": True,
            "resource_types": ["Tenis"],
            "current_user_evidence": "quiero para hoy a las 4",
            "confidence": 0.95,
            "reason": "cambio no permitido",
        },
        current_message="Ok quiero para hoy a las 4 con quincho",
        focus=focus,
    )

    results.extend([
        {
            "name": "v126r6_sibling_fragment_matches_current_physical_turn",
            "passed": _agent_v2_v126r6_same_physical_user_turn(
                "Ok quiero para hoy a las 4 de la tarde con quincho",
                "quiero para hoy a las 4 de la tarde con quincho",
            ),
        },
        {
            "name": "v126r6_unrelated_previous_turn_not_skipped",
            "passed": not _agent_v2_v126r6_same_physical_user_turn(
                "Tienen cancha libre mañana de padel",
                "quiero para hoy a las 4 de la tarde con quincho",
            ),
        },
        {
            "name": "v126r6_focus_can_only_inherit_verified_type",
            "passed": bool(good and good.get("resource_type") == "Pádel"),
        },
        {
            "name": "v126r6_focus_model_cannot_switch_type",
            "passed": not bool(bad),
        },
    ])

    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {"ok": passed == total, "passed": passed, "total": total, "results": results}


