AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-22_verified_resource_focus_v126r6"


# ============================================================================
# V126R7 — PENDING QUESTION RESOURCE PROVENANCE
# ============================================================================
# Regla:
#   - Si Dialogue Context Resolver verificó que el current turn responde una
#     PendingInteraction concreta (answers_pending/modifies_pending),
#   - y ESA interacción lleva exactamente un resource_type canónico en su
#     contexto/action_snapshot (o en availability_context del mismo scope),
#   - V126R3 puede volver pasivo el objetivo/pending histórico PERO conserva
#     ese resource_type como provenance del turno actual.
#
# Esto resuelve:
#   availability(Pádel) -> "¿Qué hora querés?"
#   usuario -> "Ok quiero para hoy a las 4 con quincho"
#
# La hora actual puede cambiar el día y el quincho puede agregarse como addon,
# pero no existe razón para olvidar el resource_type de la pregunta que se está
# respondiendo.
#
# No hay regex/keywords de intención. No se infiere lenguaje con Python:
# se conserva identidad estructural ya validada por question_id/scope_id.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r7"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r7"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-22_pending_resource_provenance_v126r7"


def _agent_v2_v126r7_types_from_interaction(
    interaction: Dict[str, Any],
    world: Optional[Dict[str, Any]] = None,
) -> List[str]:
    interaction = dict(interaction or {})
    context = (
        dict(interaction.get("context") or {})
        if isinstance(interaction.get("context"), dict)
        else {}
    )

    types = _canonical_configured_court_types(
        context.get("resource_types") or context.get("resource_type")
    )
    if len(types) == 1:
        return types

    snapshot = (
        dict(interaction.get("action_snapshot") or {})
        if isinstance(interaction.get("action_snapshot"), dict)
        else {}
    )
    target = (
        dict(snapshot.get("target") or {})
        if isinstance(snapshot.get("target"), dict)
        else {}
    )
    types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if len(types) == 1:
        return types

    # Fallback estrictamente estructural: una pregunta de la MISMA scope que
    # availability_context puede recuperar el tipo verificado por calendario.
    availability = dict((world or {}).get("availability_context") or {})
    interaction_scope = str(interaction.get("scope_id") or "").strip()
    availability_scope = str(availability.get("scope_id") or "").strip()
    if (
        interaction_scope
        and availability_scope
        and interaction_scope == availability_scope
    ):
        types = _canonical_configured_court_types(
            availability.get("resource_types")
            or availability.get("resource_type")
        )
        if len(types) == 1:
            return types

    return []


def _agent_v2_v126r7_resource_carry_from_verified_plan(
    plan: Dict[str, Any],
    world: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Extrae sólo resource_type desde bindings ya verificados.

    Nunca interpreta el texto del usuario y nunca autoriza el WRITE por sí mismo.
    """
    if not isinstance(plan, dict) or plan.get("status") != "verified":
        return {}

    carries: List[Dict[str, Any]] = []
    for binding in (plan.get("bindings") or []):
        if not isinstance(binding, dict):
            continue
        if binding.get("verified") is not True:
            continue
        if str(binding.get("relation") or "") not in {
            "answers_pending",
            "modifies_pending",
        }:
            continue

        interaction = (
            dict(binding.get("_interaction") or {})
            if isinstance(binding.get("_interaction"), dict)
            else {}
        )
        if not interaction:
            continue

        allowed_operations = {
            str(op)
            for op in (interaction.get("allowed_operations") or [])
            if str(op)
        }
        snapshot = (
            dict(interaction.get("action_snapshot") or {})
            if isinstance(interaction.get("action_snapshot"), dict)
            else {}
        )
        snapshot_operation = str(snapshot.get("operation") or "").strip()
        goal_context = {
            str(goal)
            for goal in (interaction.get("goal_context") or [])
            if str(goal)
        }

        booking_scoped = bool(
            "create_booking" in allowed_operations
            or snapshot_operation == "create_booking"
            or "crear_reserva" in goal_context
            or "buscar_turno" in goal_context
        )
        if not booking_scoped:
            continue

        types = _agent_v2_v126r7_types_from_interaction(
            interaction,
            world or {},
        )
        if len(types) != 1:
            continue

        carries.append({
            "verified": True,
            "resource_type": types[0],
            "resource_types": [types[0]],
            "source": "verified_pending_question_context",
            "question_id": str(binding.get("question_id") or ""),
            "interaction_id": str(binding.get("interaction_id") or ""),
            "scope_id": str(binding.get("scope_id") or ""),
            "binding_field": _agent_v2_v105_normalize_missing_field(
                binding.get("field")
            ),
            "binding_value": binding.get("value"),
            "evidence": str(binding.get("evidence") or ""),
        })

    if not carries:
        return {}

    unique_types = {
        str(item.get("resource_type") or "")
        for item in carries
        if str(item.get("resource_type") or "")
    }
    if len(unique_types) != 1:
        return {}

    # Si hay más de un binding compatible pero todos pertenecen al mismo tipo,
    # no ampliamos autoridad: transportamos sólo ese tipo común.
    chosen = dict(carries[0])
    print(
        "   🔗 [AgentV2 V126R7 PENDING RESOURCE CARRY] "
        f"question_id={chosen.get('question_id')} "
        f"field={chosen.get('binding_field')} "
        f"resource_type={chosen.get('resource_type')}"
    )
    return chosen


def _agent_v2_v126r7_plan_resource_carry() -> Dict[str, Any]:
    context = globals().get("AGENT_V2_DIALOGUE_CONTEXT_PLAN")
    plan = context.get() if context is not None else {}
    if not isinstance(plan, dict):
        return {}
    carry = plan.get("verified_resource_carry")
    return dict(carry) if isinstance(carry, dict) else {}


_agent_v2_v126r5_resolve_resource_continuity_v126r7_base = (
    _agent_v2_v126r5_resolve_resource_continuity
)


async def _agent_v2_v126r5_resolve_resource_continuity(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """V126R7: provenance del pending verificado tiene prioridad sobre re-adjudicar memoria."""
    if "create_booking" not in _agent_v2_v103_ops(perception or {}):
        return {}

    # Cualquier recurso explícito del current turn gana y bloquea herencia.
    if _agent_v2_v126r5_current_booking_has_resource(perception or {}):
        return {}
    if _agent_v2_v126r4_explicit_resource_selection(perception or {}):
        return {}

    carry = _agent_v2_v126r7_plan_resource_carry()
    if carry and carry.get("verified") is True:
        types = _canonical_configured_court_types(
            carry.get("resource_types") or carry.get("resource_type")
        )
        if len(types) == 1:
            print(
                "   ✅ [AgentV2 V126R7 RESOURCE AUTHORITY] "
                f"resource_type={types[0]} "
                f"question_id={carry.get('question_id')} "
                f"source={carry.get('source')}"
            )
            return {
                "resource_type": types[0],
                "resource_types": [types[0]],
                "confidence": 1.0,
                "source": "verified_pending_question_context",
                "question_id": carry.get("question_id"),
                "interaction_id": carry.get("interaction_id"),
                "scope_id": carry.get("scope_id"),
                "binding_field": carry.get("binding_field"),
                "binding_value": carry.get("binding_value"),
                "current_user_evidence": carry.get("evidence"),
                "previous_user_evidence": carry.get("evidence"),
                "previous_reference_id": None,
                "reason": (
                    "resource_type preservado desde la PendingInteraction "
                    "que el Dialogue Gate verificó como respondida"
                ),
            }

    # Sólo si no existe provenance estructural usamos el fallback semántico V126R6.
    return await _agent_v2_v126r5_resolve_resource_continuity_v126r7_base(
        mensaje,
        perception or {},
        world or {},
    )


_agent_v2_v126r5_inject_resource_context_v126r7_base = (
    _agent_v2_v126r5_inject_resource_context
)


def _agent_v2_v126r5_inject_resource_context(
    perception: Dict[str, Any],
    resolved: Dict[str, Any],
) -> Dict[str, Any]:
    if str((resolved or {}).get("source") or "") != "verified_pending_question_context":
        return _agent_v2_v126r5_inject_resource_context_v126r7_base(
            perception,
            resolved,
        )

    clean = dict(perception or {})
    types = _canonical_configured_court_types(
        (resolved or {}).get("resource_types")
        or (resolved or {}).get("resource_type")
    )
    if len(types) != 1:
        return clean
    resource_type = types[0]

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts: List[Dict[str, Any]] = []
    changed = False

    for raw in (frame.get("acts") or []):
        if not isinstance(raw, dict):
            continue
        act = dict(raw)
        if str(act.get("operation") or "") == "create_booking":
            target = dict(act.get("target") or {})

            # Current turn explícito siempre gana.
            existing = _canonical_configured_court_types(
                target.get("resource_types") or target.get("resource_type")
            )
            if not existing and not str(target.get("label") or "").strip():
                target["resource"] = "court"
                target["resource_type"] = resource_type
                target["resource_types"] = [resource_type]
                act["target"] = target

                provenance = [
                    dict(item)
                    for item in (act.get("provenance") or [])
                    if isinstance(item, dict)
                ]
                provenance.append({
                    "field": "target.resource_type",
                    "source": "pending_interaction_context",
                    "evidence": resolved.get("current_user_evidence"),
                    "reference_id": None,
                    "scope_id": resolved.get("scope_id"),
                    "question_id": resolved.get("question_id"),
                    "option_id": None,
                })
                act["provenance"] = provenance
                changed = True
        acts.append(act)

    if not changed:
        return clean

    frame["acts"] = acts
    create_acts = [
        act
        for act in acts
        if str(act.get("operation") or "") == "create_booking"
    ]
    if create_acts:
        frame["targets"] = [dict(create_acts[0].get("target") or {})]
    clean["semantic_frame"] = frame

    entities = dict(clean.get("entities") or {})
    entities["resource_type"] = resource_type
    entities["resource_types"] = [resource_type]
    clean["entities"] = entities

    clean["resource_context_resolution"] = {
        "resolved": True,
        **dict(resolved or {}),
    }
    return clean


