def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126r8_base()
    results = list(result.get("results") or [])

    verified_add = {
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "act_add_q",
                "operation": "add_resource",
                "domain": "booking",
                "target": {
                    "resource": "quincho",
                    "reservation_id": "86",
                },
            }],
            # Simula exactamente la regresión live: contrato autoritativo pero
            # lista allowed_tools stale/incompleta.
            "allowed_tools": ["obtener_reserva", "solicitar_dato"],
        },
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [{
                "act_id": "act_add_q",
                "operation": "add_resource",
                "authorized": True,
            }],
        },
        "task_graph": {
            "nodes": [{
                "node_id": "act_add_q",
                "operation": "add_resource",
                "effect": "write",
                "allowed_tools": ["obtener_reserva", "solicitar_dato"],
                "status": "pending",
            }],
            "meaning_frozen": True,
        },
    }
    repaired = _agent_v2_v126r8_repair_mutation_tool_authority(verified_add)
    repaired_contract_tools = set(
        (repaired.get("execution_contract") or {}).get("allowed_tools") or []
    )
    repaired_node_tools = set(
        (((repaired.get("task_graph") or {}).get("nodes") or [{}])[0])
        .get("allowed_tools") or []
    )

    unverified = {
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "act_unverified",
                "operation": "add_resource",
            }],
            "allowed_tools": ["obtener_reserva"],
        },
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [{
                "act_id": "act_unverified",
                "operation": "add_resource",
                "authorized": False,
            }],
        },
    }
    unverified_repaired = _agent_v2_v126r8_repair_mutation_tool_authority(
        unverified
    )

    non_mutation = {
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "act_query",
                "operation": "query_policy",
            }],
            "allowed_tools": ["consultar_informacion_negocio"],
        },
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [],
        },
    }
    non_mutation_repaired = _agent_v2_v126r8_repair_mutation_tool_authority(
        non_mutation
    )

    results.extend([
        {
            "name": "v126r8_verified_add_resource_restores_agregar_quincho",
            "passed": "agregar_quincho" in repaired_contract_tools,
        },
        {
            "name": "v126r8_taskgraph_node_receives_same_verified_tool_authority",
            "passed": "agregar_quincho" in repaired_node_tools,
        },
        {
            "name": "v126r8_does_not_authorize_unverified_write",
            "passed": (
                "agregar_quincho"
                not in set(
                    (unverified_repaired.get("execution_contract") or {})
                    .get("allowed_tools") or []
                )
            ),
        },
        {
            "name": "v126r8_does_not_expand_non_mutation_contracts",
            "passed": (
                set(
                    (non_mutation_repaired.get("execution_contract") or {})
                    .get("allowed_tools") or []
                )
                == {"consultar_informacion_negocio"}
            ),
        },
        {
            "name": "v126r8_never_grants_create_booking_tool_to_add_resource",
            "passed": "crear_reserva" not in repaired_contract_tools,
        },
    ])

    passed = sum(
        1
        for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


