# ============================================================================
# V126R9 — NON-MUTATION TRANSPARENCY + VERIFIED CURRENT-TURN TIME EVIDENCE
# ============================================================================
# Regresión observada después de V126R8:
#
#   "cancha para mañana a las 4 de la tarde 2 horas de futbol"
#
# Perception / SemanticFrame:
#   create_booking
#   day=Miércoles 23/09
#   start=16:00
#   duration=2h
#   resource_type=Futbol 5
#
# BookingObjective:
#   READY, missing=[]
#
# Policy:
#   hora_sin_evidencia_del_usuario
#
# Causa:
#   La hora semántica estaba correctamente resuelta, pero en ese turno Perception
#   no materializó un temporal_mentions/provenance utilizable por el validador
#   estricto de Policy. V126R8 además envolvía TODOS los calls de Planner/Policy
#   aunque su propósito era exclusivamente mutaciones.
#
# Reglas V126R9:
#   1) V126R8 es un NO-OP de identidad para operaciones no mutacionales.
#   2) Si un create_booking WRITE ya fue verificado por Semantic Effect Verifier,
#      tiene una hora válida en el SemanticFrame, pero Policy no puede demostrar
#      todavía su evidencia, un verificador IA de CAMPO (no de intención) puede
#      devolver una cita literal del turno actual y su hora resuelta.
#   3) Python valida:
#        - misma hora que el act semántico ya congelado;
#        - cita literal realmente contenida en el turno actual;
#        - mismo act_id autorizado por Effect Verifier;
#        - mismo BookingObjective;
#        - ninguna ambigüedad temporal declarada.
#   4) El verificador NO puede cambiar intención, fecha, recurso, duración ni hora.
#      Sólo certifica provenance de un valor YA entendido.
#   5) No usa regex/keywords para interpretar lenguaje.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r9"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r9"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-22_verified_time_evidence_v126r9"


# ---------------------------------------------------------------------------
# A) V126R8 debe ser totalmente transparente fuera de mutaciones verificadas.
# ---------------------------------------------------------------------------
_agent_v2_v126r8_repair_mutation_tool_authority_v126r9_base = (
    _agent_v2_v126r8_repair_mutation_tool_authority
)


def _agent_v2_v126r8_repair_mutation_tool_authority(
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    original = perception if isinstance(perception, dict) else {}
    verified_acts = _agent_v2_v126r8_verified_mutation_acts(original)
    if not verified_acts:
        # Identidad exacta: create_booking/query/etc. no atraviesan ninguna copia
        # ni transformación introducida por V126R8.
        return original

    return _agent_v2_v126r8_repair_mutation_tool_authority_v126r9_base(
        original
    )


def _agent_v2_v126r9_verified_create_booking_act(
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    frame = _agent_v2_semantic_frame(perception or {}) or {}
    acts = [
        dict(act)
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "create_booking"
    ]
    if len(acts) != 1:
        return {}

    act = acts[0]
    act_id = str(act.get("act_id") or "").strip()
    if not act_id:
        return {}

    verification = (
        (perception or {}).get("semantic_effect_verification")
        if isinstance(
            (perception or {}).get("semantic_effect_verification"),
            dict,
        )
        else {}
    )
    if verification.get("status") != "verified":
        return {}

    authorized = any(
        isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("act_id") or "").strip() == act_id
        and str(item.get("operation") or "create_booking") == "create_booking"
        for item in (verification.get("write_authorizations") or [])
    )
    return act if authorized else {}


def _agent_v2_v126r9_current_semantic_hour(
    perception: Dict[str, Any],
) -> str:
    act = _agent_v2_v126r9_verified_create_booking_act(perception or {})
    if not act:
        return ""
    temporal = (
        act.get("temporal")
        if isinstance(act.get("temporal"), dict)
        else {}
    )
    hour = normalizar_hora_detectada(temporal.get("start"))
    return hour if hora_es_valida(hour) else ""


def _agent_v2_v126r9_has_temporal_ambiguity(
    perception: Dict[str, Any],
) -> bool:
    frame = _agent_v2_semantic_frame(perception or {}) or {}
    ambiguity = (
        frame.get("ambiguity")
        if isinstance(frame.get("ambiguity"), dict)
        else {}
    )
    hour_resolution = (
        (perception or {}).get("hour_resolution")
        if isinstance((perception or {}).get("hour_resolution"), dict)
        else {}
    )
    return bool(
        ambiguity.get("required")
        and str(ambiguity.get("field") or "") in {
            "temporal.start", "hora", "start_time"
        }
    ) or hour_resolution.get("ambiguous") is True


def _agent_v2_v126r9_validate_time_verifier_output(
    raw: Dict[str, Any],
    *,
    mensaje: str,
    expected_hour: str,
) -> Dict[str, Any]:
    if not isinstance(raw, dict) or raw.get("supported") is not True:
        return {}

    evidence = str(raw.get("evidence") or "").strip()
    resolved = normalizar_hora_detectada(raw.get("resolved_hour"))
    try:
        confidence = float(raw.get("confidence") or 0.0)
    except Exception:
        confidence = 0.0

    if confidence < 0.90:
        return {}
    if not evidence:
        return {}
    if resolved != normalizar_hora_detectada(expected_hour):
        return {}

    message_key = normalizar_texto_ia(mensaje or "")
    evidence_key = normalizar_texto_ia(evidence)
    if not message_key or not evidence_key or evidence_key not in message_key:
        return {}

    return {
        "supported": True,
        "evidence": evidence,
        "resolved_hour": resolved,
        "confidence": confidence,
        "reason": str(raw.get("reason") or "").strip(),
    }


async def _agent_v2_v126r9_recover_current_turn_time_authority(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = perception if isinstance(perception, dict) else {}

    if _agent_v2_v126r9_has_temporal_ambiguity(clean):
        return clean

    act = _agent_v2_v126r9_verified_create_booking_act(clean)
    if not act:
        return clean

    expected_hour = _agent_v2_v126r9_current_semantic_hour(clean)
    if not expected_hour:
        return clean

    # Si el mecanismo maduro ya puede probarla, no gastamos otra llamada.
    check_world = dict(world or {})
    check_world["message"] = str(mensaje or "")
    if _agent_v2_booking_hour_has_user_grounding(
        {"hora": expected_hour},
        clean,
        check_world,
    ):
        return clean

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos CURRENT-TURN TIME EVIDENCE VERIFIER. "
                        "No clasifiques intención y NO cambies ningún valor. "
                        "Recibís un mensaje de usuario y una hora HH:MM que otra capa "
                        "semántica YA resolvió para un create_booking autorizado. "
                        "Tu única tarea es verificar si el mensaje actual contiene una "
                        "expresión temporal literal que respalda EXACTAMENTE esa hora.\n\n"
                        "Si la respalda, devolvé una cita literal CONTIGUA del mensaje "
                        "en evidence y la MISMA expected_hour en resolved_hour. "
                        "Interpretá expresiones naturales de hora y franja (por ejemplo, "
                        "hora coloquial + mañana/tarde/noche) semánticamente. "
                        "No inventes evidencia. No uses memoria ni contexto anterior. "
                        "Si existe ambigüedad real o el mensaje no respalda exactamente "
                        "expected_hour, supported=false.\n\n"
                        "Respondé SOLO JSON:\n"
                        "{"
                        "\"supported\":true|false,"
                        "\"evidence\":\"\","
                        "\"resolved_hour\":\"HH:MM|null\","
                        "\"confidence\":0.0,"
                        "\"reason\":\"\""
                        "}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "current_user_turn": mensaje,
                            "expected_hour": expected_hour,
                            "semantic_act": {
                                "act_id": act.get("act_id"),
                                "operation": act.get("operation"),
                                "temporal": act.get("temporal"),
                            },
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=220,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        raw = _loads_llm_json_object(
            response.choices[0].message.content.strip()
        )
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V126R9 TIME EVIDENCE] "
            f"verificador no disponible: {type(exc).__name__}: {exc}"
        )
        return clean

    verified = _agent_v2_v126r9_validate_time_verifier_output(
        raw,
        mensaje=mensaje,
        expected_hour=expected_hour,
    )
    if not verified:
        print(
            "   🧭 [AgentV2 V126R9 TIME EVIDENCE] "
            f"verified=False expected_hour={expected_hour} "
            f"reason={raw.get('reason') if isinstance(raw, dict) else ''}"
        )
        return clean

    patched = dict(clean)
    frame = dict(_agent_v2_semantic_frame(patched) or {})
    patched_acts: List[Dict[str, Any]] = []
    act_id = str(act.get("act_id") or "").strip()

    for raw_act in (frame.get("acts") or []):
        if not isinstance(raw_act, dict):
            continue
        current = dict(raw_act)
        if str(current.get("act_id") or "").strip() == act_id:
            provenance = [
                dict(item)
                for item in (current.get("provenance") or [])
                if isinstance(item, dict)
                and str(item.get("field") or "") not in {
                    "temporal.start", "start_time", "hora"
                }
            ]
            provenance.append({
                "field": "temporal.start",
                "source": "current_user_turn",
                "evidence": verified["evidence"],
                "verification": "v126r9_field_evidence_verifier",
            })
            current["provenance"] = provenance
        patched_acts.append(current)

    frame["acts"] = patched_acts
    patched["semantic_frame"] = frame

    mentions = [
        dict(item)
        for item in (patched.get("temporal_mentions") or [])
        if isinstance(item, dict)
    ]
    has_same = any(
        str(item.get("kind") or "").lower() == "time"
        and normalizar_hora_detectada(item.get("resolved_value")) == expected_hour
        and normalizar_texto_ia(item.get("evidence") or "")
            == normalizar_texto_ia(verified["evidence"])
        for item in mentions
    )
    if not has_same:
        mentions.append({
            "kind": "time",
            "evidence": verified["evidence"],
            "resolved_value": expected_hour,
            "clock_system": "semantic_verified",
            "meridiem_explicit": None,
            "precision": "exact",
            "grounding_source": "v126r9_field_evidence_verifier",
        })
    patched["temporal_mentions"] = mentions

    objective = (
        dict(patched.get("booking_objective") or {})
        if isinstance(patched.get("booking_objective"), dict)
        else {}
    )
    if objective:
        objective_id = str(objective.get("objective_id") or "").strip()
        objective_hour = normalizar_hora_detectada(
            ((objective.get("temporal") or {}).get("start"))
        )
        if objective_id and objective_hour == expected_hour:
            authority = dict(objective.get("field_authority") or {})
            authority["hora"] = {
                "field": "hora",
                "value": expected_hour,
                "objective_id": objective_id,
                "act_id": act_id,
                "source": "v126r9_current_user_time_verifier",
                "evidence": verified["evidence"],
                "verified": True,
                "verified_at": datetime.datetime.now(TIMEZONE).isoformat(),
            }
            objective["field_authority"] = authority
            patched["booking_objective"] = objective

    patched["_v126r9_time_authority"] = {
        "verified": True,
        "hour": expected_hour,
        "evidence": verified["evidence"],
        "act_id": act_id,
        "objective_id": str(objective.get("objective_id") or ""),
        "message_normalized": normalizar_texto_ia(mensaje or ""),
        "confidence": verified["confidence"],
        "source": "current_user_turn",
    }

    print(
        "   ✅ [AgentV2 V126R9 TIME EVIDENCE] "
        f"hora={expected_hour} evidence={verified['evidence']!r} "
        f"confidence={verified['confidence']:.2f}"
    )
    return patched


