# ---------------------------------------------------------------------------
# Policy grounding postcondition: acepta exclusivamente el recibo V126R9 si
# sigue siendo el MISMO act WRITE autorizado, la MISMA hora y la evidencia
# sigue perteneciendo al mensaje que llega a Policy.
# ---------------------------------------------------------------------------
_agent_v2_booking_hour_has_user_grounding_v126r9_base = (
    _agent_v2_booking_hour_has_user_grounding
)


def _agent_v2_booking_hour_has_user_grounding(
    args: Dict[str, Any],
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    if _agent_v2_booking_hour_has_user_grounding_v126r9_base(
        args or {},
        perception or {},
        world or {},
    ):
        return True

    requested = normalizar_hora_detectada((args or {}).get("hora"))
    if not hora_es_valida(requested):
        return False

    record = (
        (perception or {}).get("_v126r9_time_authority")
        if isinstance((perception or {}).get("_v126r9_time_authority"), dict)
        else {}
    )
    if record.get("verified") is not True:
        return False
    if str(record.get("source") or "") != "current_user_turn":
        return False
    if normalizar_hora_detectada(record.get("hour")) != requested:
        return False

    evidence = str(record.get("evidence") or "").strip()
    current_message = str((world or {}).get("message") or "")
    evidence_key = normalizar_texto_ia(evidence)
    current_key = normalizar_texto_ia(current_message)

    # V125 puede pasar un fragmento sibling y Policy puede recibir el mensaje
    # físico completo. La evidencia debe existir en el mensaje actual y ambos
    # textos deben pertenecer al mismo turno por contención representacional.
    source_key = str(record.get("message_normalized") or "")
    if not evidence_key or not current_key or evidence_key not in current_key:
        return False
    if source_key and not (
        source_key == current_key
        or source_key in current_key
        or current_key in source_key
    ):
        return False

    act = _agent_v2_v126r9_verified_create_booking_act(perception or {})
    if not act:
        return False
    act_id = str(act.get("act_id") or "").strip()
    if act_id != str(record.get("act_id") or "").strip():
        return False
    act_hour = normalizar_hora_detectada(
        ((act.get("temporal") or {}).get("start"))
    )
    if act_hour != requested:
        return False

    objective = (
        (perception or {}).get("booking_objective")
        if isinstance((perception or {}).get("booking_objective"), dict)
        else {}
    )
    if objective:
        objective_hour = normalizar_hora_detectada(
            ((objective.get("temporal") or {}).get("start"))
        )
        if objective_hour != requested:
            return False
        record_objective_id = str(record.get("objective_id") or "").strip()
        objective_id = str(objective.get("objective_id") or "").strip()
        if record_objective_id and objective_id != record_objective_id:
            return False

    print(
        "   🔐 [AgentV2 V126R9 CURRENT-TURN HOUR AUTHORITY] "
        f"hora={requested} evidence={evidence!r}"
    )
    return True


