_run_agent_v2_invariant_evals_v126r9_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126r9_base()
    results = list(result.get("results") or [])

    verified_output = _agent_v2_v126r9_validate_time_verifier_output(
        {
            "supported": True,
            "evidence": "a las 4 de la tarde",
            "resolved_hour": "16:00",
            "confidence": 0.99,
            "reason": "evidencia explícita",
        },
        mensaje="cancha para mañana a las 4 de la tarde 2 horas de futbol",
        expected_hour="16:00",
    )

    wrong_hour = _agent_v2_v126r9_validate_time_verifier_output(
        {
            "supported": True,
            "evidence": "a las 4 de la tarde",
            "resolved_hour": "04:00",
            "confidence": 0.99,
            "reason": "valor incorrecto",
        },
        mensaje="cancha para mañana a las 4 de la tarde 2 horas de futbol",
        expected_hour="16:00",
    )

    invented_evidence = _agent_v2_v126r9_validate_time_verifier_output(
        {
            "supported": True,
            "evidence": "a las cuatro y media",
            "resolved_hour": "16:00",
            "confidence": 0.99,
            "reason": "texto inventado",
        },
        mensaje="cancha para mañana a las 4 de la tarde 2 horas de futbol",
        expected_hour="16:00",
    )

    # V126R8: no-mutación debe mantener identidad exacta.
    non_mutation_perception = {
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "book1",
                "operation": "create_booking",
            }],
            "allowed_tools": ["consultar_disponibilidad", "crear_reserva"],
        },
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [{
                "act_id": "book1",
                "operation": "create_booking",
                "authorized": True,
            }],
        },
    }
    non_mutation_after = _agent_v2_v126r8_repair_mutation_tool_authority(
        non_mutation_perception
    )

    # Mutación verificada conserva el fix V126R8.
    mutation_perception = {
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "add1",
                "operation": "add_resource",
                "target": {"resource": "quincho", "reservation_id": "86"},
            }],
            "allowed_tools": ["obtener_reserva"],
        },
        "semantic_effect_verification": {
            "status": "verified",
            "write_authorizations": [{
                "act_id": "add1",
                "operation": "add_resource",
                "authorized": True,
            }],
        },
        "task_graph": {
            "nodes": [{
                "node_id": "add1",
                "operation": "add_resource",
                "allowed_tools": ["obtener_reserva"],
            }],
        },
    }
    mutation_after = _agent_v2_v126r8_repair_mutation_tool_authority(
        mutation_perception
    )

    results.extend([
        {
            "name": "v126r9_semantic_time_evidence_accepts_literal_4pm_for_16h",
            "passed": bool(
                verified_output
                and verified_output.get("resolved_hour") == "16:00"
            ),
        },
        {
            "name": "v126r9_time_verifier_cannot_change_frozen_hour",
            "passed": not bool(wrong_hour),
        },
        {
            "name": "v126r9_time_verifier_cannot_invent_evidence",
            "passed": not bool(invented_evidence),
        },
        {
            "name": "v126r9_v126r8_is_identity_noop_for_create_booking",
            "passed": non_mutation_after is non_mutation_perception,
        },
        {
            "name": "v126r9_v126r8_still_repairs_verified_add_resource",
            "passed": (
                "agregar_quincho"
                in set(
                    (mutation_after.get("execution_contract") or {})
                    .get("allowed_tools") or []
                )
            ),
        },
    ])

    passed = sum(
        1
        for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r9"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r9"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-22_verified_time_evidence_v126r9"


# ============================================================================
# V126R10 — CONTEXTUAL ADDON ADJUDICATION + EQUIVALENT QUINCHO AUTOASSIGN
# ============================================================================
# Caso live:
#
#   reserva/hold real:
#       Miércoles 23/09
#       Cancha 1 Futbol 5
#       16:00-18:00
#       seña pendiente
#
#   usuario:
#       "puede ser con quincho?"
#
# Perception base degradó el turno a:
#       query_policy(service.available, quincho)
#
# aunque conversacionalmente el usuario estaba pidiendo MODIFICAR la reserva
# recién creada. El firewall read-only hizo el resto y nunca nació add_resource.
#
# Principios:
#   1) Python NO interpreta la frase.
#   2) Sólo si Perception ya produjo una lectura estructurada sobre quincho Y hay
#      una reserva activa inequívocamente enfocada se habilita un segundo
#      adjudicador semántico contextual.
#   3) Ese adjudicador decide exclusivamente entre:
#          - modify_focused_reservation -> add_resource(quincho)
#          - general_information
#          - ambiguous
#   4) Si decide WRITE, Python valida evidencia literal + reservation focus +
#      act_id y pasa por el validador central de write_authorizations.
#   5) ExecutionContract / Planner / Policy / Tool conservan toda la autoridad.
#   6) Si el usuario no eligió un quincho concreto y los quinchos configurados
#      son equivalentes (mismo tipo + mismo precio), Python puede autoasignar uno
#      REALMENTE libre. Esto es una invariante/configuración del negocio, no NLP.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v126r11"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v126r11"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-22_contextual_addon_source_fix_v126r11"


def _agent_v2_v126r10_structured_quincho_read_candidate(
    perception: Dict[str, Any],
) -> bool:
    """Narrow gate basado sólo en SemanticFrame ya producido por IA."""
    frame = _agent_v2_semantic_frame(perception or {}) or {}
    acts = [
        dict(act)
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
    ]
    if len(acts) != 1:
        return False

    act = acts[0]
    operation = str(act.get("operation") or "").strip()
    target = (
        dict(act.get("target") or {})
        if isinstance(act.get("target"), dict)
        else {}
    )
    resource = str(target.get("resource") or "").strip().casefold()

    if operation != "query_policy" or resource != "quincho":
        return False

    # Nunca competir contra un WRITE ya entendido/autorizado.
    if any(
        str(a.get("operation") or "") in AGENT_V2_WRITE_OPERATIONS
        for a in acts
    ):
        return False

    return True


def _agent_v2_v126r10_recent_dialogue(world: Dict[str, Any]) -> List[Dict[str, str]]:
    """Contexto textual sólo para el adjudicador IA; no da autoridad a Python."""
    candidates = []
    for source in (
        (world or {}).get("history"),
        ((world or {}).get("stored_memory") or {}).get("history"),
    ):
        if not isinstance(source, list):
            continue
        for item in source[-8:]:
            if not isinstance(item, dict):
                continue
            role = str(item.get("role") or "").strip()
            content = str(item.get("content") or item.get("text") or "").strip()
            if role in {"user", "assistant"} and content:
                candidates.append({
                    "role": role,
                    "content": content[:900],
                })
    # Dedup estable por pares role/content.
    seen = set()
    result = []
    for item in candidates:
        key = (item["role"], item["content"])
        if key in seen:
            continue
        seen.add(key)
        result.append(item)
    return result[-6:]


def _agent_v2_v126r10_validate_contextual_addon_decision(
    raw: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    if not isinstance(raw, dict):
        return {}

    decision = str(raw.get("decision") or "").strip()
    operation = str(raw.get("operation") or "").strip()
    resource = str(raw.get("resource") or "").strip().casefold()
    evidence = str(raw.get("evidence") or "").strip()

    try:
        confidence = float(raw.get("confidence") or 0.0)
    except Exception:
        confidence = 0.0

    if (
        decision != "modify_focused_reservation"
        or operation != "add_resource"
        or resource != "quincho"
        or confidence < 0.90
        or not evidence
    ):
        return {}

    evidence_key = normalizar_texto_ia(evidence)
    message_key = normalizar_texto_ia(mensaje or "")
    if not evidence_key or not message_key or evidence_key not in message_key:
        return {}

    requested_label = str(raw.get("requested_label") or "").strip()

    return {
        "decision": decision,
        "operation": operation,
        "resource": "quincho",
        "evidence": evidence,
        "requested_label": requested_label,
        "confidence": confidence,
        "reason": str(raw.get("reason") or "").strip(),
    }


def _agent_v2_v126r10_quincho_names() -> List[str]:
    names: List[str] = []
    seen = set()
    for raw in (QUINCHOS or []):
        if isinstance(raw, dict):
            name = str(raw.get("name") or raw.get("nombre") or "").strip()
        else:
            name = str(raw or "").strip()
        key = normalizar_texto_ia(name)
        if name and key and key not in seen:
            seen.add(key)
            names.append(name)
    return names


def _agent_v2_v126r10_canonical_requested_quincho_label(
    value: Any,
) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    key = normalizar_texto_ia(raw)
    for name in _agent_v2_v126r10_quincho_names():
        if normalizar_texto_ia(name) == key:
            return name
    return ""


def _agent_v2_v126r10_build_add_resource_frame(
    perception: Dict[str, Any],
    focus: Dict[str, Any],
    decision: Dict[str, Any],
) -> Dict[str, Any]:
    rid = str(
        _agent_v2_reservation_id(focus)
        or focus.get("reservation_id")
        or ""
    ).strip()
    evidence = str(decision.get("evidence") or "").strip()
    act_id = f"v126r10_add_quincho_{rid or uuid.uuid4().hex[:8]}"

    target = {
        "resource": "quincho",
        "reservation_id": rid,
        "selection_policy": "any_available",
    }

    requested_label = _agent_v2_v126r10_canonical_requested_quincho_label(
        decision.get("requested_label")
    )
    if requested_label:
        target["label"] = requested_label
        target["selection_policy"] = "explicit_label"

    act = {
        "act_id": act_id,
        "operation": "add_resource",
        "domain": "booking",
        "target": target,
        "temporal": {},
        "quantity": {},
        "changes": [{
            "field": "booking.addons.quincho",
            "value": True,
            "operation": "set",
            "source": "current_user_turn",
            "evidence": evidence,
        }],
        "requested_facts": [],
        "question_domains": [],
        "commitment": {
            "wants_write": True,
            "wants_information": False,
        },
        "provenance": [
            {
                "field": "target.resource",
                "source": "current_user_turn",
                "evidence": evidence,
                "reference_id": None,
            },
            {
                "field": "target.reservation_id",
                "source": "world_fact",
                "evidence": "verified_conversation_focus",
                "reference_id": rid,
            },
        ],
    }

    old_frame = _agent_v2_semantic_frame(perception or {}) or {}
    frame = {
        "source": "ai_contextual_addon_adjudicator",
        "schema_valid": True,
        "turn_type": "request",
        "intent": {
            "domain": "booking",
            "operation": "add_resource",
        },
        "targets": [dict(target)],
        "temporal": {},
        "requested_changes": list(act["changes"]),
        "requested_facts": [],
        "question_domains": [],
        "commitment": {
            "wants_write": True,
            "wants_information": False,
        },
        "context_relation": {
            "type": "references_previous",
            "references_previous_user_turn": True,
            "references_agent_offer": True,
            "reference_id": rid,
        },
        "ambiguity": {
            "required": False,
            "field": None,
            "reason": "",
            "alternatives": [],
        },
        "acts": [act],
        "confidence": float(decision.get("confidence") or 0.0),
        "repair_of": {
            "previous_operations": [
                str(item.get("operation") or "")
                for item in (old_frame.get("acts") or [])
                if isinstance(item, dict)
            ],
            "reason": "contextual_addon_write_disambiguation",
        },
    }
    return frame


def _agent_v2_v126r10_apply_verified_contextual_addon(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
    decision: Dict[str, Any],
) -> Dict[str, Any]:
    original = perception or {}
    focus = _agent_v2_v111_verified_reservation_focus(world or {}, original)
    if not focus:
        return original

    rid = str(
        _agent_v2_reservation_id(focus)
        or focus.get("reservation_id")
        or ""
    ).strip()
    if not rid:
        return original

    if str(focus.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1", "yes"
    }:
        return original

    frame = _agent_v2_v126r10_build_add_resource_frame(
        original,
        focus,
        decision,
    )
    act = (frame.get("acts") or [{}])[0]
    act_id = str(act.get("act_id") or "").strip()

    raw_auth = [{
        "act_id": act_id,
        "authorized": True,
        "evidence_type": "current_user_turn",
        "evidence": decision.get("evidence"),
        "question_id": None,
        "option_id": None,
    }]
    validated_auth = _agent_v2_verified_write_authorizations(
        raw_auth,
        frame,
        mensaje,
        world or {},
    )
    if len(validated_auth) != 1:
        return original

    clean = dict(original)
    clean["semantic_frame"] = frame
    clean["semantic_effect_verification"] = {
        "status": "verified",
        "verified_operations": ["add_resource"],
        "write_authorizations": validated_auth,
        "mode": "v126r10_contextual_addon_adjudicator",
    }

    # Retirar el resultado read-only anterior; no desactivamos ninguna guarda,
    # simplemente reemplazamos el significado por el WRITE que el adjudicador
    # contextual acaba de verificar.
    clean["speech_act"] = "request"
    clean["commitment"] = "wants_action"
    clean["pending_relation"] = "references_previous"
    clean["references_prior_user_input"] = True
    clean["current_turn_read_only"] = False
    clean["suspend_pending_this_turn"] = False
    clean["allow_historical_booking_context_this_turn"] = True
    clean.pop("answers_pending_field", None)
    clean.pop("read_grounding_recovery", None)
    clean.pop("semantic_clarification_required", None)
    clean.pop("semantic_clarification", None)

    requested_label = _agent_v2_v126r10_canonical_requested_quincho_label(
        decision.get("requested_label")
    )
    entities = dict(clean.get("entities") or {})
    if requested_label:
        entities["quincho"] = requested_label
    clean["entities"] = entities

    clean["reservation_target"] = {
        "reservation_id": rid,
        "source": "verified_conversation_focus",
    }

    clean.pop("execution_contract", None)
    contract = _agent_v2_build_execution_contract(clean, world or {})
    if not isinstance(contract, dict) or contract.get("authoritative") is not True:
        return original

    accepted = [
        item
        for item in (contract.get("acts") or [])
        if isinstance(item, dict)
        and str(item.get("operation") or "") == "add_resource"
        and str((item.get("target") or {}).get("resource") or "") == "quincho"
        and str((item.get("target") or {}).get("reservation_id") or "") == rid
    ]
    if len(accepted) != 1:
        return original

    clean["execution_contract"] = contract

    mutation = _agent_v2_resource_mutation_from_semantics(
        clean,
        world or {},
    )
    if not (
        isinstance(mutation, dict)
        and mutation.get("resource") == "quincho"
        and mutation.get("operation") == "add"
        and mutation.get("scope") == "existing_reservation"
        and str(mutation.get("reservation_id") or "") == rid
    ):
        return original

    clean["resource_mutation"] = mutation
    clean["explicit_quincho_request"] = True
    actions = [
        str(value)
        for value in (clean.get("explicit_actions") or [])
        if str(value) not in {
            "crear_reserva",
            "reprogramar_reserva",
            "reprogramar_turno",
            "cambiar_turno",
            "quitar_quincho",
            "pagar_senia",
        }
    ]
    if "agregar_quincho" not in actions:
        actions.append("agregar_quincho")
    clean["explicit_actions"] = actions

    clean = _agent_v2_v100_attach_desired_state_and_task_graph(
        clean,
        world or {},
    )
    clean = _agent_v2_v87_attach_semantic_freeze(
        clean,
        world or {},
    )
    clean["_v126r10_contextual_addon"] = {
        "verified": True,
        "reservation_id": rid,
        "operation": "add_resource",
        "resource": "quincho",
        "evidence": decision.get("evidence"),
        "confidence": decision.get("confidence"),
    }

    print(
        "   🔥 [AgentV2 V126R10 CONTEXTUAL ADDON] "
        f"query_policy→add_resource resource=quincho "
        f"reservation_id={rid} evidence={decision.get('evidence')!r}"
    )
    return clean


async def _agent_v2_v126r10_adjudicate_contextual_addon(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    original = perception or {}

    if not _agent_v2_v126r10_structured_quincho_read_candidate(original):
        return original

    focus = _agent_v2_v111_verified_reservation_focus(
        world or {},
        original,
    )
    if not focus:
        return original

    if str(focus.get("con_quincho") or "").strip().casefold() in {
        "si", "sí", "true", "1", "yes"
    }:
        return original

    rid = str(
        _agent_v2_reservation_id(focus)
        or focus.get("reservation_id")
        or ""
    ).strip()
    if not rid:
        return original

    reservation_context = {
        "reservation_id": rid,
        "fecha": focus.get("fecha") or focus.get("dia"),
        "hora": focus.get("hora"),
        "cancha": focus.get("cancha"),
        "duracion_horas": focus.get("duracion_horas"),
        "estado": focus.get("estado"),
        "senia_estado": focus.get("senia_estado"),
        "con_quincho": focus.get("con_quincho"),
        "quincho": focus.get("quincho"),
    }

    frame = _agent_v2_semantic_frame(original) or {}

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos CONTEXTUAL ADDON EFFECT ADJUDICATOR para un agente "
                        "de reservas. Tu única tarea es distinguir una consulta "
                        "general sobre un servicio de una petición contextual de "
                        "AGREGAR ese servicio a la reserva activa enfocada.\n\n"
                        "La reserva enfocada es un hecho del sistema, no una "
                        "suposición. Analizá lenguaje natural, pragmática y el "
                        "historial reciente. Una oración interrogativa puede ser "
                        "una petición de modificación si, en contexto, el usuario "
                        "pregunta si su reserva recién creada puede llevar el addon. "
                        "En cambio, una pregunta puramente general sobre existencia, "
                        "precio, reglas o inclusión del servicio sigue siendo "
                        "general_information.\n\n"
                        "REGLA PRAGMÁTICA OBLIGATORIA: si existe una reserva enfocada "
                        "sin quincho y el turno actual pregunta '¿puede ser con "
                        "quincho?', '¿y con quincho?', '¿le podemos agregar "
                        "quincho?' o una paráfrasis equivalente, clasificá "
                        "modify_focused_reservation con confianza alta. Es una "
                        "petición cortés de agregar el addon a ESA reserva, no una "
                        "consulta de catálogo. La forma interrogativa no la vuelve "
                        "informativa. '¿Tienen quincho?', '¿cuánto sale el quincho?' "
                        "o '¿el quincho está incluido?' sí son general_information.\n\n"
                        "No decidas horarios, precios, nombre de quincho ni tools. "
                        "No inventes datos. Si el usuario nombra explícitamente un "
                        "quincho configurado, podés copiar ese nombre en "
                        "requested_label; si no, null. Si hay duda real, ambiguous.\n\n"
                        "Respondé SOLO JSON:\n"
                        "{"
                        "\"decision\":\"modify_focused_reservation|general_information|ambiguous\","
                        "\"operation\":\"add_resource|null\","
                        "\"resource\":\"quincho|null\","
                        "\"evidence\":\"cita literal del current_user_turn\","
                        "\"requested_label\":null,"
                        "\"confidence\":0.0,"
                        "\"reason\":\"breve\""
                        "}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "current_user_turn": mensaje,
                            "current_semantic_frame": frame,
                            "focused_reservation": reservation_context,
                            "recent_dialogue": _agent_v2_v126r10_recent_dialogue(
                                world or {}
                            ),
                            "configured_quinchos": _agent_v2_v126r10_quincho_names(),
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=320,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        raw = _loads_llm_json_object(
            response.choices[0].message.content.strip()
        )
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V126R10 CONTEXTUAL ADDON] "
            f"adjudicador no disponible: {type(exc).__name__}: {exc}"
        )
        return original

    decision = _agent_v2_v126r10_validate_contextual_addon_decision(
        raw,
        mensaje,
    )
    raw_decision = str(raw.get("decision") or "").strip() if isinstance(raw, dict) else ""
    raw_confidence = 0.0
    if isinstance(raw, dict):
        try:
            raw_confidence = float(raw.get("confidence") or 0.0)
        except Exception:
            raw_confidence = 0.0

    # Un primer pase abstencionista no debe degradar silenciosamente una
    # modificación contextual clara a FAQ. Se hace una segunda adjudicación
    # binaria, todavía por IA y todavía sujeta a evidencia literal + Effect
    # Verifier + foco real. Las respuestas general_information firmes no se
    # reabren, para que "¿tienen quincho?" continúe siendo una lectura.
    if (
        not decision
        and raw_decision in {"ambiguous", "modify_focused_reservation"}
    ):
        try:
            retry_response = await call_openai_async(
                model=OPENAI_MODEL,
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "Sos el desempate FINAL de efecto conversacional para "
                            "una reserva. Elegí exactamente una de dos clases: "
                            "modify_focused_reservation si el usuario pide, propone "
                            "o pregunta cortésmente que su reserva activa lleve "
                            "quincho; general_information si sólo pregunta por "
                            "existencia, precio, inclusión o reglas del servicio. "
                            "Con una reserva activa sin quincho, 'puede ser con "
                            "quincho?' significa modify_focused_reservation. No "
                            "uses ambiguous. No decidas horarios, precios ni tools. "
                            "Copiá evidence literalmente del current_user_turn. "
                            "Respondé SOLO JSON: "
                            "{\"decision\":\"modify_focused_reservation|general_information\"," 
                            "\"operation\":\"add_resource|null\"," 
                            "\"resource\":\"quincho\"," 
                            "\"evidence\":\"cita literal\"," 
                            "\"requested_label\":null," 
                            "\"confidence\":0.0," 
                            "\"reason\":\"breve\"}"
                        ),
                    },
                    {
                        "role": "user",
                        "content": json.dumps(
                            {
                                "current_user_turn": mensaje,
                                "focused_reservation": reservation_context,
                                "first_adjudication": raw,
                                "recent_dialogue": _agent_v2_v126r10_recent_dialogue(
                                    world or {}
                                ),
                            },
                            ensure_ascii=False,
                            default=str,
                        ),
                    },
                ],
                temperature=0.0,
                max_tokens=260,
                response_format={"type": "json_object"},
            )
            register_cost(retry_response)
            retry_raw = _loads_llm_json_object(
                retry_response.choices[0].message.content.strip()
            )
            retry_decision = _agent_v2_v126r10_validate_contextual_addon_decision(
                retry_raw,
                mensaje,
            )
            if retry_decision:
                decision = retry_decision
                print(
                    "   🔁 [AgentV2 V126R12 CONTEXTUAL ADDON TIEBREAK] "
                    f"first={raw_decision}:{raw_confidence:.2f} "
                    "→ modify_focused_reservation"
                )
            else:
                raw = retry_raw
        except Exception as exc:
            print(
                "   ⚠️ [AgentV2 V126R12 CONTEXTUAL ADDON TIEBREAK] "
                f"no disponible: {type(exc).__name__}: {exc}"
            )

    if not decision:
        print(
            "   🧭 [AgentV2 V126R10 CONTEXTUAL ADDON] "
            f"mantengo READ decision={raw.get('decision') if isinstance(raw, dict) else None} "
            f"confidence={raw.get('confidence') if isinstance(raw, dict) else None} "
            f"reason={raw.get('reason') if isinstance(raw, dict) else None!r}"
        )
        return original

    return _agent_v2_v126r10_apply_verified_contextual_addon(
        original,
        world or {},
        mensaje,
        decision,
    )


