# Autoassign de quincho equivalente y disponible.
# ---------------------------------------------------------------------------
def _agent_v2_v126r10_explicit_quincho_name(
    perception: Dict[str, Any],
) -> str:
    names = _agent_v2_v126r10_quincho_names()
    if not names:
        return ""

    candidates: List[Any] = []
    entities = (
        (perception or {}).get("entities")
        if isinstance((perception or {}).get("entities"), dict)
        else {}
    )
    candidates.append(entities.get("quincho"))

    frame = _agent_v2_semantic_frame(perception or {}) or {}
    for act in (frame.get("acts") or []):
        if not isinstance(act, dict):
            continue
        target = (
            act.get("target")
            if isinstance(act.get("target"), dict)
            else {}
        )
        if str(target.get("resource") or "") != "quincho":
            continue
        candidates.extend([
            target.get("label"),
            target.get("name"),
        ])

    for raw in candidates:
        key = normalizar_texto_ia(raw or "")
        if not key:
            continue
        for name in names:
            if normalizar_texto_ia(name) == key:
                return name
    return ""


def _agent_v2_v126r10_quincho_signature(name: str) -> Tuple[str, int]:
    qtype = ""
    target_key = normalizar_texto_ia(name)
    for raw in (QUINCHOS or []):
        if not isinstance(raw, dict):
            continue
        raw_name = str(raw.get("name") or raw.get("nombre") or "").strip()
        if normalizar_texto_ia(raw_name) != target_key:
            continue
        qtype = str(raw.get("type") or raw.get("tipo") or "").strip().casefold()
        break
    return (
        qtype,
        int(precio_hora_quincho(name) or 0),
    )


def _agent_v2_v126r10_equivalent_quinchos() -> List[str]:
    names = _agent_v2_v126r10_quincho_names()
    if not names:
        return []
    signatures = {
        _agent_v2_v126r10_quincho_signature(name)
        for name in names
    }
    if len(signatures) != 1:
        return []
    return names


def _agent_v2_v126r10_autoassign_available_quincho(
    world: Dict[str, Any],
    perception: Dict[str, Any],
) -> Dict[str, Any]:
    original = perception or {}
    mutation = (
        original.get("resource_mutation")
        if isinstance(original.get("resource_mutation"), dict)
        else {}
    )
    if not (
        mutation.get("resource") == "quincho"
        and mutation.get("operation") == "add"
        and mutation.get("scope") == "existing_reservation"
        and mutation.get("write_intent") is True
    ):
        return original

    if _agent_v2_v126r10_explicit_quincho_name(original):
        return original

    pool = _agent_v2_v126r10_equivalent_quinchos()
    if not pool:
        return original

    rid = str(mutation.get("reservation_id") or "").strip()
    row = _agent_v2_v115_find_existing_target_row(world or {}, rid)
    if not row:
        focus = _agent_v2_v111_verified_reservation_focus(
            world or {},
            original,
        )
        row = dict(focus or {})
    if not row:
        return original

    rid = str(
        rid
        or _agent_v2_reservation_id(row)
        or row.get("reservation_id")
        or ""
    ).strip()
    if not rid:
        return original

    defaults = _agent_v2_v115_default_quincho_fields(
        row,
        mutation.get("fields") if isinstance(mutation.get("fields"), dict) else {},
    )
    qstart = normalizar_hora_detectada(defaults.get("hora_inicio"))
    qdur = normalizar_duracion_horas(
        defaults.get("duracion_horas")
        or _AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS,
        _AGENT_V2_V115_DEFAULT_QUINCHO_DURATION_HOURS,
    )
    dia = row.get("fecha") or row.get("dia") or ""

    if not dia or not hora_es_valida(qstart) or not qdur:
        return original

    try:
        rows = _calendar_rows_with_universal_ids()
    except Exception:
        rows = []

    available = []
    for name in pool:
        try:
            free = _quincho_disponible_excluyendo_id(
                rid,
                dia,
                qstart,
                qdur,
                name,
                rows,
            )
        except Exception:
            free = False
        if free:
            available.append(name)

    if not available:
        return original

    chosen = available[0]
    clean = dict(original)
    entities = dict(clean.get("entities") or {})
    entities["quincho"] = chosen
    clean["entities"] = entities

    patched_mutation = dict(mutation)
    patched_mutation["autoassigned_quincho"] = chosen
    patched_mutation["autoassign_source"] = (
        "equivalent_configured_quinchos+verified_availability"
    )
    clean["resource_mutation"] = patched_mutation

    print(
        "   🏡 [AgentV2 V126R10 QUINCHO AUTOASSIGN] "
        f"reservation_id={rid} elegido={chosen} "
        f"libres={available} rango={qstart}-{hora_fin_bloque(qstart, qdur)}"
    )
    return clean


_agent_v2_plan_current_resource_mutation_v126r10_base = (
    _agent_v2_plan_current_resource_mutation
)


def _agent_v2_plan_current_resource_mutation(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    progress: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    prepared = _agent_v2_v126r10_autoassign_available_quincho(
        world or {},
        perception or {},
    )
    return _agent_v2_plan_current_resource_mutation_v126r10_base(
        world,
        prepared,
        goals,
        observations,
        progress,
    )


