# Invariantes V126R10
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v126r10_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v126r10_base()
    results = list(result.get("results") or [])

    literal_decision = _agent_v2_v126r10_validate_contextual_addon_decision(
        {
            "decision": "modify_focused_reservation",
            "operation": "add_resource",
            "resource": "quincho",
            "evidence": "puede ser con quincho?",
            "requested_label": None,
            "confidence": 0.99,
            "reason": "modifica la reserva enfocada",
        },
        "puede ser con quincho?",
    )

    fake_evidence = _agent_v2_v126r10_validate_contextual_addon_decision(
        {
            "decision": "modify_focused_reservation",
            "operation": "add_resource",
            "resource": "quincho",
            "evidence": "agregame Quincho 2",
            "confidence": 0.99,
        },
        "puede ser con quincho?",
    )

    read_decision = _agent_v2_v126r10_validate_contextual_addon_decision(
        {
            "decision": "general_information",
            "operation": None,
            "resource": "quincho",
            "evidence": "tienen quincho?",
            "confidence": 0.99,
        },
        "tienen quincho?",
    )

    read_candidate = _agent_v2_v126r10_structured_quincho_read_candidate({
        "semantic_frame": {
            "acts": [{
                "act_id": "q1",
                "operation": "query_policy",
                "target": {"resource": "quincho"},
                "requested_facts": ["service.available"],
                "commitment": {
                    "wants_write": False,
                    "wants_information": True,
                },
            }]
        }
    })

    already_write = _agent_v2_v126r10_structured_quincho_read_candidate({
        "semantic_frame": {
            "acts": [{
                "act_id": "w1",
                "operation": "add_resource",
                "target": {"resource": "quincho"},
                "commitment": {
                    "wants_write": True,
                    "wants_information": False,
                },
            }]
        }
    })

    results.extend([
        {
            "name": "v126r10_contextual_addon_accepts_literal_write_decision",
            "passed": bool(
                literal_decision
                and literal_decision.get("operation") == "add_resource"
            ),
        },
        {
            "name": "v126r10_contextual_addon_rejects_invented_evidence",
            "passed": not bool(fake_evidence),
        },
        {
            "name": "v126r10_general_information_never_becomes_write_in_python",
            "passed": not bool(read_decision),
        },
        {
            "name": "v126r10_only_structured_quincho_query_enters_adjudicator",
            "passed": bool(read_candidate),
        },
        {
            "name": "v126r10_existing_write_is_never_reinterpreted",
            "passed": not bool(already_write),
        },
    ])

    passed = sum(
        1
        for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


# ============================================================================
# V128 — BOOKING-INTENT → DURABLE OBJECTIVE AFTER EXACT AVAILABILITY
# ============================================================================
# Incidente live:
#   T1: "Quiero alquilar una hora mañana a las 18, ¿tendría disponible?"
#       El router auditado entendió ``reservar_cancha`` pero Perception conservó
#       sólo ``query_availability``. La tool verificó 18:00 y NBA abrió una mera
#       confirmación de slot, sin guardar día/hora/duración como objetivo.
#   T2: "Fútbol 5 / 1 hora / ¿tienen parrilla?"
#       Al no existir BookingObjective, el deporte se convirtió en una consulta
#       nueva y se perdió el jueves a las 18:00.
#
# Regla V128:
#   - el router IA auditado aporta únicamente la voluntad de reservar;
#   - la Observation aporta únicamente el slot disponible verificado;
#   - Python une ambas estructuras, sin releer ni clasificar texto, y persiste un
#     BookingObjective collecting ligado a la pregunta realmente faltante;
#   - completar ese pending en otro mensaje habilita el pipeline normal V105+
#     V126R2, incluida la consulta informativa de quincho en el mismo turno.
# ============================================================================


def _agent_v2_v128_router_booking_intent() -> bool:
    context = globals().get("AGENT_V2_CURRENT_ROUTER_SUBINTENT")
    if context is None:
        return False
    try:
        item = context.get()
    except Exception:
        return False
    return bool(
        isinstance(item, dict)
        and str(item.get("intencion") or "").strip() == "reservar_cancha"
        and str(item.get("fragmento") or "").strip()
    )


def _agent_v2_v128_router_subintent() -> Dict[str, Any]:
    context = globals().get("AGENT_V2_CURRENT_ROUTER_SUBINTENT")
    if context is None:
        return {}
    try:
        item = context.get()
    except Exception:
        return {}
    return dict(item) if isinstance(item, dict) else {}


def _agent_v2_v128_current_provenance_evidence(
    perception: Dict[str, Any],
    accepted_fields: set,
) -> str:
    for act in _agent_v2_authoritative_semantic_acts(perception or {}):
        if not isinstance(act, dict):
            continue
        for item in (act.get("provenance") or []):
            if not isinstance(item, dict):
                continue
            if str(item.get("source") or "") != "current_user_turn":
                continue
            if str(item.get("field") or "") not in accepted_fields:
                continue
            evidence = str(item.get("evidence") or "").strip()
            if evidence:
                return evidence
    return ""


def _agent_v2_v128_booking_objective_candidate(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Materializa sólo slots que ya fueron verificados por capas anteriores."""
    if not _agent_v2_is_pure_exact_availability_read(perception or {}):
        return {}

    configured_types = _configured_court_type_labels()
    if len(configured_types) <= 1:
        return {}
    if _agent_v2_resource_type_constraints(perception or {}, world or {}):
        return {}

    slot = _agent_v2_current_available_slot(
        perception or {}, observations or []
    )
    if not slot:
        return {}

    day = _agent_v2_v103_normalized_day(slot.get("dia"))
    hour = normalizar_hora_detectada(slot.get("hora"))
    courts = _agent_v2_exact_available_courts(slot)
    duration = normalizar_duracion_horas(
        slot.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS,
        DEFAULT_TURN_DURATION_HOURS,
    )
    if not day or not hora_es_valida(hour) or not courts or not duration:
        return {}

    # La respuesta canónica de un slot con más de un deporte pregunta
    # explícitamente cuál quiere reservar. Esa invitación también debe dejar
    # un pending tipado `resource_type`, aunque el mensaje original haya sido
    # una consulta pura de disponibilidad ("tenés cancha a las 18?"). Si no lo
    # hacemos, la UI pregunta por deporte pero el estado guarda
    # `confirmar_slot`; una respuesta corta como "Futbol" queda sin campo al
    # cual vincularse y termina en el clasificador general.
    available_types = _canonical_configured_court_types([
        _court_type_for_name(court) for court in courts
    ])
    offered_multi_sport_choice = len(available_types) > 1
    router_booking_intent = _agent_v2_v128_router_booking_intent()
    if not router_booking_intent and not offered_multi_sport_choice:
        return {}

    now = datetime.datetime.now(TIMEZONE).isoformat()
    objective_id = str(uuid.uuid4())
    act_id = f"v128_booking_{uuid.uuid4().hex[:12]}"
    router_item = _agent_v2_v128_router_subintent()
    fragment = str(
        router_item.get("fragmento")
        or (world or {}).get("message")
        or ""
    ).strip()

    provenance = []
    for act in _agent_v2_authoritative_semantic_acts(perception or {}):
        if str((act or {}).get("operation") or "") == "query_availability":
            provenance.extend(
                dict(item)
                for item in (act.get("provenance") or [])
                if isinstance(item, dict)
            )
    provenance.append({
        "field": (
            "intent.operation"
            if router_booking_intent
            else "dialogue.pending.resource_type"
        ),
        "source": (
            "current_user_turn"
            if router_booking_intent
            else "verified_exact_slot_offer"
        ),
        "evidence": fragment,
        "verification": (
            "v125_audited_multi_intent_router"
            if router_booking_intent
            else "canonical_multi_sport_selection_question"
        ),
    })

    objective = {
        "objective_id": objective_id,
        "act_id": act_id,
        "owner": str(((world or {}).get("facts") or {}).get("memory_owner") or ""),
        "status": "collecting",
        "operation": "create_booking",
        "target": {
            "resource": "court",
            "resource_type": None,
            "resource_types": [],
        },
        "temporal": {
            "day": day,
            "start": hour,
            "duration_hours": duration,
        },
        "addons": {
            "quincho": {
                "requested": False,
                "name": "",
                "duration_hours": None,
                "start": "",
            }
        },
        "provenance": provenance,
        "created_at": now,
        "updated_at": now,
    }

    authority_specs = {
        "dia": (
            day,
            {"temporal.day", "day", "dia"},
        ),
        "hora": (
            hour,
            {"temporal.start", "start_time", "hora"},
        ),
        "duracion_horas": (
            duration,
            {"temporal.duration_hours", "quantity.duration_hours", "duracion_horas"},
        ),
    }
    objective["field_authority"] = {
        field: {
            "field": field,
            "value": value,
            "objective_id": objective_id,
            "act_id": act_id,
            "source": "verified_current_user_semantics+availability_observation",
            "evidence": _agent_v2_v128_current_provenance_evidence(
                perception or {}, evidence_fields
            ),
            "verified": True,
            "verified_at": now,
        }
        for field, (value, evidence_fields) in authority_specs.items()
    }
    objective["missing_fields"] = _agent_v2_v103_compute_missing(objective)
    if objective["missing_fields"] != ["resource_type"]:
        return {}
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    return objective


def _agent_v2_v128_resource_type_question(objective: Dict[str, Any]) -> str:
    options = _configured_court_type_labels()
    if not options:
        return "¿Qué deporte querés reservar?"
    if len(options) == 1:
        return f"¿Querés reservar {options[0]}?"
    if len(options) == 2:
        choices = " o ".join(options)
    else:
        choices = ", ".join(options[:-1]) + f" o {options[-1]}"
    return f"¿Qué deporte querés reservar: {choices}?"


_agent_v2_nba_candidates_v128_base = _agent_v2_nba_candidates


def _agent_v2_nba_candidates(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
) -> List[Dict[str, Any]]:
    candidates = _agent_v2_nba_candidates_v128_base(
        world, perception, goals, observations, status
    )
    objective = _agent_v2_v128_booking_objective_candidate(
        world or {}, perception or {}, observations or []
    )
    if not objective:
        return candidates

    temporal = dict(objective.get("temporal") or {})
    question = {
        "field": "resource_type",
        "options": _configured_court_type_labels(),
        "question_text": _agent_v2_v128_resource_type_question(objective),
        "booking_choice": True,
        "interaction_kind": "value",
        "dia": temporal.get("day"),
        "hora": temporal.get("start"),
        "duracion_horas": temporal.get("duration_hours"),
        "canchas": _agent_v2_exact_available_courts(
            _agent_v2_current_available_slot(perception or {}, observations or []) or {}
        ),
        "goal_context": ["crear_reserva", "buscar_turno"],
        "source": "v128_verified_booking_intent_bridge",
        "source_message": str((world or {}).get("message") or ""),
        "replace_booking_questions": True,
        "booking_objective_id": objective.get("objective_id"),
        "action_snapshot": _agent_v2_v103_action_snapshot(objective),
        "allowed_operations": ["create_booking", "query_availability"],
    }
    print(
        "   🧠 [AgentV2 V128 DURABLE BOOKING OBJECTIVE] "
        f"objective={objective.get('objective_id')} "
        f"day={temporal.get('day')} hour={temporal.get('start')} "
        "missing=resource_type"
    )
    return [{
        # Se conserva una action ya comprendida por el selector y el reducer;
        # el field tipado expresa cuál dato falta realmente.
        "action": "ask_booking_datetime",
        "reason_code": "v128_booking_intent_exact_slot_bridge",
        "reason": (
            "el router auditado verificó intención de reservar y la tool verificó "
            "el slot exacto; persistir el objetivo y pedir sólo el deporte"
        ),
        "booking_objective": objective,
        "question": question,
    }]


_elegir_next_best_action_agent_v2_v128_base = elegir_next_best_action_agent_v2


async def elegir_next_best_action_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    status: str,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    bridge = next((
        candidate
        for candidate in _agent_v2_nba_candidates(
            world, perception, goals, observations, status
        )
        if str(candidate.get("reason_code") or "")
        == "v128_booking_intent_exact_slot_bridge"
    ), None)
    if bridge:
        chosen = dict(bridge)
        chosen["decision_reason"] = (
            "continuidad determinista: slot exacto verificado + próxima selección tipada"
        )
        return chosen
    return await _elegir_next_best_action_agent_v2_v128_base(
        world,
        perception,
        goals,
        observations,
        status,
        learning_policy,
    )


_aplicar_next_best_action_agent_v2_v128_base = aplicar_next_best_action_agent_v2


def aplicar_next_best_action_agent_v2(
    telefono: str,
    nba: Dict[str, Any],
) -> None:
    objective = (
        dict((nba or {}).get("booking_objective") or {})
        if isinstance((nba or {}).get("booking_objective"), dict)
        else {}
    )
    if (
        str((nba or {}).get("reason_code") or "")
        == "v128_booking_intent_exact_slot_bridge"
        and str(objective.get("operation") or "") == "create_booking"
        and objective.get("missing_fields") == ["resource_type"]
    ):
        _agent_v2_v103_supersede_previous_objective(
            telefono,
            {
                "booking_objective": objective,
                "semantic_frame": {
                    "context_relation": {"type": "new_request"},
                },
            },
        )
        _agent_v2_v103_persist_objective(telefono, objective)
        for field in ("confirmar_slot", "resource_type"):
            agent_v2_reduce(telefono, {
                "type": "CLEAR_OPEN_QUESTION",
                "payload": {"field": field},
            })
        print(
            "   💾 [AgentV2 V128 OBJECTIVE PERSISTED] "
            f"objective={objective.get('objective_id')} "
            "pending=resource_type"
        )
    _aplicar_next_best_action_agent_v2_v128_base(telefono, nba)


AGENT_V2_UNIFIED_AGENTIC_CORE = "v128"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v128"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-23_durable_booking_intent_v128"


# ============================================================================
# V129 — SEMANTIC BOOKING COMMITMENT → DURABLE OBJECTIVE
# ============================================================================
# Incidente live:
#
#   "Quiero alquilar una hora mañana a las 18, ¿tendría disponible?"
#
# El router IA puede etiquetar correctamente la acción inmediata como
# `pedir_horarios` porque primero hay que consultar disponibilidad. Sin embargo,
# el turno también contiene una voluntad transaccional de reservar. V128 sólo
# activaba su bridge durable cuando el router decía EXACTAMENTE
# `reservar_cancha`, de modo que el slot 18:00 verificado se mostraba pero no se
# conservaba dentro de BookingObjective.
#
# Consecuencia:
#   T2 "Futbol 5 / 1 hora / Servicio de parrilla tiene?"
#   ya no tenía un objetivo activo propietario de día=24/09, hora=18:00,
#   duración=1h. V127 no podía vincular `resource_type` ni convertir la consulta
#   contextual de parrilla en addon de esa misma reserva.
#
# V129 separa dos conceptos:
#
#   ROUTER INTENT
#       Qué debe hacer el agente AHORA (p.ej. query_availability)
#
#   BOOKING COMMITMENT
#       Si esa consulta de disponibilidad pertenece a una intención real de
#       concretar una reserva.
#
# Una IA adjudica exclusivamente esa segunda propiedad. Python sólo valida:
#   - que el router ya haya producido un único `pedir_horarios`;
#   - evidencia literal del turno actual;
#   - confidence >= 0.90;
#   - que no exista otro BookingObjective activo que deba gobernar el turno.
#
# La decisión NO cambia SemanticFrame, día, hora, duración, resource_type ni
# tools. Únicamente permite que V128 materialice un BookingObjective DESPUÉS de
# una Observation real de disponibilidad exacta.
#
# Sin regex ni keywords para interpretar intención.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v129"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v129"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-23_semantic_booking_commitment_v129"


AGENT_V2_V129_TURN_CONTEXT = contextvars.ContextVar(
    "agent_v2_v129_turn_context",
    default={},
)

AGENT_V2_V129_BOOKING_COMMITMENT = contextvars.ContextVar(
    "agent_v2_v129_booking_commitment",
    default={},
)


def _agent_v2_v129_active_objective_from_context() -> Dict[str, Any]:
    ctx = AGENT_V2_V129_TURN_CONTEXT.get()
    if not isinstance(ctx, dict):
        return {}
    objective = ctx.get("active_booking_objective")
    return dict(objective) if isinstance(objective, dict) else {}


def _agent_v2_v129_validate_booking_commitment(
    raw: Dict[str, Any],
    *,
    mensaje: str,
    router_intent: str,
) -> Dict[str, Any]:
    if not isinstance(raw, dict):
        return {}

    if raw.get("booking_commitment") is not True:
        return {}

    try:
        confidence = float(raw.get("confidence") or 0.0)
    except Exception:
        confidence = 0.0
    if confidence < 0.90:
        return {}

    evidence = str(raw.get("evidence") or "").strip()
    if not evidence:
        return {}

    # Reutiliza el validador literal maduro de V126. No interpreta significado.
    if not _agent_v2_v126_literal_evidence(mensaje, evidence):
        return {}

    return {
        "verified": True,
        "booking_commitment": True,
        "router_intent": str(router_intent or ""),
        "evidence": evidence,
        "confidence": confidence,
        "reason": str(raw.get("reason") or "").strip(),
        "source": "v129_semantic_booking_commitment_adjudicator",
        "message_normalized": normalizar_texto_ia(mensaje or ""),
    }


async def _agent_v2_v129_adjudicate_booking_commitment(
    mensaje: str,
    initial: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Decide sólo si un READ de disponibilidad pertenece a voluntad de reservar."""
    rows = [
        dict(item)
        for item in (initial or [])
        if isinstance(item, dict)
    ]
    if len(rows) != 1:
        return {}

    item = rows[0]
    router_intent = str(item.get("intencion") or "").strip()

    # Gate estructural: V129 corrige únicamente la frontera
    # disponibilidad-vs-compromiso. No reinterpreta otros intents.
    if router_intent != "pedir_horarios":
        return {}

    # Si ya hay un objetivo activo, su Context Binding Gate es la autoridad.
    # V129 no crea un segundo objetivo competidor.
    active = _agent_v2_v129_active_objective_from_context()
    if active and str(active.get("status") or "") in {
        "active", "collecting", "ready", "preflight", "suspended"
    }:
        return {}

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos BOOKING COMMITMENT ADJUDICATOR. "
                        "El router ya decidió que la acción inmediata del turno es "
                        "consultar disponibilidad/horarios. Tu ÚNICA tarea es decidir "
                        "si, además de esa consulta, el usuario está expresando una "
                        "voluntad real de concretar una reserva si el slot está disponible.\n\n"

                        "booking_commitment=true cuando la consulta de disponibilidad "
                        "es un paso dentro de una petición de alquilar/reservar un turno. "
                        "booking_commitment=false cuando el usuario sólo explora horarios, "
                        "disponibilidad u opciones sin expresar voluntad de reservar.\n\n"

                        "No cambies intent, fecha, hora, duración, recurso ni operación. "
                        "No decidas disponibilidad. No uses memoria anterior. "
                        "evidence debe ser una cita LITERAL CONTIGUA del current_user_turn "
                        "que demuestre la voluntad transaccional; no inventes texto. "
                        "Si existe duda real, false.\n\n"

                        "Respondé SOLO JSON:\n"
                        "{"
                        "\"booking_commitment\":true|false,"
                        "\"evidence\":\"\","
                        "\"confidence\":0.0,"
                        "\"reason\":\"breve\""
                        "}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "current_user_turn": mensaje,
                            "router_result": rows,
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=240,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        raw = _loads_llm_json_object(
            response.choices[0].message.content.strip()
        )
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V129 BOOKING COMMITMENT] "
            f"adjudicador no disponible: {type(exc).__name__}: {exc}"
        )
        return {}

    verified = _agent_v2_v129_validate_booking_commitment(
        raw,
        mensaje=mensaje,
        router_intent=router_intent,
    )
    if verified:
        print(
            "   🎯 [AgentV2 V129 BOOKING COMMITMENT] "
            f"router={router_intent} durable_booking=True "
            f"evidence={verified.get('evidence')!r} "
            f"confidence={verified.get('confidence'):.2f}"
        )
    else:
        print(
            "   🧭 [AgentV2 V129 BOOKING COMMITMENT] "
            f"router={router_intent} durable_booking=False "
            f"reason={raw.get('reason') if isinstance(raw, dict) else ''!r}"
        )
    return verified


# ---------------------------------------------------------------------------
# Router wrapper: no cambia la ontología ni la etiqueta. Sólo deja un receipt
# semántico consumible por V128 más tarde, después de consultar calendario.
# ---------------------------------------------------------------------------
_detectar_multiples_intenciones_v129_base = detectar_multiples_intenciones


async def detectar_multiples_intenciones(mensaje: str) -> List[Dict]:
    initial = await _detectar_multiples_intenciones_v129_base(mensaje)
    decision = await _agent_v2_v129_adjudicate_booking_commitment(
        str(mensaje or ""),
        initial or [],
    )
    if decision:
        AGENT_V2_V129_BOOKING_COMMITMENT.set(dict(decision))
    return initial


# ---------------------------------------------------------------------------
# V128 bridge authority extension.
# Router reservar_cancha sigue funcionando como antes. V129 añade una segunda
# fuente estrictamente semántica para el caso pedir_horarios+booking_commitment.
# ---------------------------------------------------------------------------
_agent_v2_v128_router_booking_intent_v129_base = (
    _agent_v2_v128_router_booking_intent
)


def _agent_v2_v128_router_booking_intent() -> bool:
    if _agent_v2_v128_router_booking_intent_v129_base():
        return True

    decision = AGENT_V2_V129_BOOKING_COMMITMENT.get()
    if not isinstance(decision, dict) or decision.get("verified") is not True:
        return False
    if decision.get("booking_commitment") is not True:
        return False
    if str(decision.get("router_intent") or "") != "pedir_horarios":
        return False

    current = _agent_v2_v128_router_subintent()
    if not isinstance(current, dict):
        return False
    if str(current.get("intencion") or "") != "pedir_horarios":
        return False

    # El receipt sólo vive dentro del wrapper de este turno. Esta comprobación
    # impide reutilizarlo accidentalmente en otro mensaje/subturn.
    turn_ctx = AGENT_V2_V129_TURN_CONTEXT.get()
    physical_message = str(
        (turn_ctx or {}).get("physical_message")
        if isinstance(turn_ctx, dict)
        else ""
    )
    recorded = str(decision.get("message_normalized") or "")
    if physical_message and recorded:
        physical_key = normalizar_texto_ia(physical_message)
        if physical_key != recorded:
            return False

    return True


# ---------------------------------------------------------------------------
# Turn wrapper: acota los ContextVars a un único mensaje físico.
# También expone el BookingObjective actual al adjudicador para que jamás cree
# un objetivo paralelo cuando el Conversation Manager ya tiene uno activo.
# ---------------------------------------------------------------------------
_ejecutar_agente_real_v2_turno_v129_base = ejecutar_agente_real_v2_turno


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    turn_token = None
    commitment_token = None
    try:
        routing_world = construir_world_state_agent_v2(
            telefono or "unknown",
            prospecto or {},
            conv_state or {},
            str(mensaje or ""),
            image_path,
        )
        active = _agent_v2_v103_active_objective_from_world(
            routing_world or {}
        )
        turn_token = AGENT_V2_V129_TURN_CONTEXT.set({
            "physical_message": str(mensaje or ""),
            "telefono": telefono or "unknown",
            "active_booking_objective": dict(active or {}),
        })
        commitment_token = AGENT_V2_V129_BOOKING_COMMITMENT.set({})

        return await _ejecutar_agente_real_v2_turno_v129_base(
            mensaje,
            conv_state,
            prospecto,
            telefono,
            user_messages=user_messages,
            page=page,
            image_path=image_path,
            dry_run=dry_run,
            eval_context=eval_context,
        )
    finally:
        if commitment_token is not None:
            AGENT_V2_V129_BOOKING_COMMITMENT.reset(commitment_token)
        if turn_token is not None:
            AGENT_V2_V129_TURN_CONTEXT.reset(turn_token)


# ---------------------------------------------------------------------------
# Invariantes V129.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v129_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v129_base()
    results = list(result.get("results") or [])

    valid = _agent_v2_v129_validate_booking_commitment(
        {
            "booking_commitment": True,
            "evidence": "Quiero alquilar una hora",
            "confidence": 0.99,
            "reason": "la disponibilidad es precondición de una reserva",
        },
        mensaje="Quiero alquilar una hora mañana a las 18 tendria disponible",
        router_intent="pedir_horarios",
    )

    invented = _agent_v2_v129_validate_booking_commitment(
        {
            "booking_commitment": True,
            "evidence": "quiero confirmar la reserva",
            "confidence": 0.99,
            "reason": "inventado",
        },
        mensaje="Quiero alquilar una hora mañana a las 18 tendria disponible",
        router_intent="pedir_horarios",
    )

    low_conf = _agent_v2_v129_validate_booking_commitment(
        {
            "booking_commitment": True,
            "evidence": "Quiero alquilar una hora",
            "confidence": 0.60,
            "reason": "dudoso",
        },
        mensaje="Quiero alquilar una hora mañana a las 18 tendria disponible",
        router_intent="pedir_horarios",
    )

    results.extend([
        {
            "name": "v129_booking_commitment_accepts_literal_current_turn_evidence",
            "passed": bool(
                valid
                and valid.get("booking_commitment") is True
            ),
        },
        {
            "name": "v129_booking_commitment_rejects_invented_evidence",
            "passed": not bool(invented),
        },
        {
            "name": "v129_booking_commitment_rejects_low_confidence",
            "passed": not bool(low_conf),
        },
    ])

    passed = sum(
        1
        for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


AGENT_V2_UNIFIED_AGENTIC_CORE = "v129"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v129"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-23_semantic_booking_commitment_v129"



# ============================================================================
# V130 — PRESERVE MIXED SUBINTENT LANES + DURABLE NEXT-QUESTION RESPONSE
# ============================================================================
# V126R5 puede agrupar modificadores del mismo booking, pero una consulta READ
# independiente debe seguir existiendo como semantic lane aunque esté ligada al
# mismo bundle comercial. V127 usa justamente ese plan MIXED para completar el
# BookingObjective y responder la consulta en el mismo turno.
#
# Además, V128 ya persiste el BookingObjective después de una disponibilidad
# exacta; V130 conserva también la pregunta NBA autorizada (p.ej. resource_type)
# en la respuesta exact-slot, sin inventar wording ni releer texto libre.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v130"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v130"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-23_mixed_subintent_lanes_v130"

AGENT_V2_V130_READ_LANE_INTENTS = {
    "consulta_informativa",
    "pedir_precio",
    "consultar_mi_turno",
}

AGENT_V2_V130_TRANSACTION_LANE_INTENTS = {
    "reservar_cancha",
    "reservar_quincho",
    "confirmar_reserva",
    "cancelar_turno",
    "reprogramar_turno",
}


def _agent_v2_v130_restore_semantic_lanes(
    mensaje: str,
    initial: List[Dict[str, Any]],
    audited: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Restaura READ siblings absorbidos por el auditor, sin interpretar texto."""
    initial_rows = [
        {
            "intencion": str(item.get("intencion") or "otra").strip(),
            "fragmento": str(item.get("fragmento") or "").strip(),
        }
        for item in (initial or [])
        if isinstance(item, dict) and str(item.get("fragmento") or "").strip()
    ]
    audited_rows = [
        {
            "intencion": str(item.get("intencion") or "otra").strip(),
            "fragmento": str(item.get("fragmento") or "").strip(),
        }
        for item in (audited or [])
        if isinstance(item, dict) and str(item.get("fragmento") or "").strip()
    ]
    if not initial_rows or not audited_rows:
        return audited_rows or initial_rows

    original_reads = [
        row for row in initial_rows
        if row["intencion"] in AGENT_V2_V130_READ_LANE_INTENTS
    ]
    if not original_reads:
        return audited_rows

    audited_reads = [
        row for row in audited_rows
        if row["intencion"] in AGENT_V2_V130_READ_LANE_INTENTS
    ]

    def represented(row):
        key = normalizar_texto_ia(row.get("fragmento") or "")
        return bool(key) and any(
            key in normalizar_texto_ia(candidate.get("fragmento") or "")
            for candidate in audited_reads
        )

    missing_reads = [row for row in original_reads if not represented(row)]
    if not missing_reads:
        return audited_rows

    tx_rows = [
        row for row in audited_rows
        if row["intencion"] in AGENT_V2_V130_TRANSACTION_LANE_INTENTS
    ]
    if len(tx_rows) != 1:
        return audited_rows

    tx = tx_rows[0]
    tx_key = normalizar_texto_ia(tx["fragmento"])
    swallowed_reads = [
        row for row in missing_reads
        if normalizar_texto_ia(row["fragmento"]) in tx_key
    ]
    if not swallowed_reads:
        return audited_rows

    tx_parts = []
    seen_parts = set()
    for row in initial_rows:
        if row["intencion"] in AGENT_V2_V130_READ_LANE_INTENTS:
            continue
        part = str(row.get("fragmento") or "").strip()
        part_key = normalizar_texto_ia(part)
        if not part_key or part_key in seen_parts:
            continue
        if part_key in tx_key:
            seen_parts.add(part_key)
            tx_parts.append(part)

    rebuilt_tx = "\n".join(tx_parts).strip()
    if not rebuilt_tx or not _agent_v2_v126r5_fragment_belongs_to_message(
        mensaje, rebuilt_tx
    ):
        return audited_rows

    restored = [{
        "intencion": tx["intencion"],
        "fragmento": rebuilt_tx,
    }]
    restored.extend(dict(row) for row in original_reads)

    signatures = {
        (row["intencion"].casefold(), normalizar_texto_ia(row["fragmento"]))
        for row in restored
    }
    for row in audited_rows:
        sig = (
            row["intencion"].casefold(),
            normalizar_texto_ia(row["fragmento"]),
        )
        if sig in signatures:
            continue
        if row["intencion"] in AGENT_V2_V130_READ_LANE_INTENTS:
            continue
        if row == tx:
            continue
        signatures.add(sig)
        restored.append(dict(row))

    print(
        "   🛤️ [AgentV2 V130 SEMANTIC LANES] "
        f"audited={[(x['intencion'], x['fragmento'][:36]) for x in audited_rows]} "
        f"restored={[(x['intencion'], x['fragmento'][:36]) for x in restored]}"
    )
    return restored


_agent_v2_v126r5_audit_subintent_coverage_v130_base = (
    _agent_v2_v126r5_audit_subintent_coverage
)


async def _agent_v2_v126r5_audit_subintent_coverage(
    mensaje: str,
    initial: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    audited = await _agent_v2_v126r5_audit_subintent_coverage_v130_base(
        mensaje,
        initial,
    )
    return _agent_v2_v130_restore_semantic_lanes(
        mensaje,
        initial,
        audited,
    )


