_agent_v2_v126_resolve_dialogue_context_before_perception_v130_base = (
    _agent_v2_v126_resolve_dialogue_context_before_perception
)


async def _agent_v2_v126_resolve_dialogue_context_before_perception(
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    plan = await _agent_v2_v126_resolve_dialogue_context_before_perception_v130_base(
        mensaje,
        world,
    )
    if isinstance(plan, dict) and plan.get("status") == "verified":
        bindings = [b for b in (plan.get("bindings") or []) if isinstance(b, dict)]
        acts = [a for a in (plan.get("independent_acts") or []) if isinstance(a, dict)]
        if bindings and acts:
            print(
                "   🔗 [AgentV2 V130 MIXED PLAN PRESERVED] "
                f"bindings={[(b.get('field'), b.get('value')) for b in bindings]} "
                f"independent_ops={[a.get('operation') for a in acts]}"
            )
    return plan


AGENT_V2_V130_NEXT_QUESTION = contextvars.ContextVar(
    "agent_v2_v130_next_question",
    default={},
)

_aplicar_next_best_action_agent_v2_v130_base = aplicar_next_best_action_agent_v2


def aplicar_next_best_action_agent_v2(
    telefono: str,
    nba: Dict[str, Any],
) -> None:
    if (
        isinstance(nba, dict)
        and str(nba.get("reason_code") or "")
        == "v128_booking_intent_exact_slot_bridge"
    ):
        question = dict(nba.get("question") or {}) if isinstance(
            nba.get("question"), dict
        ) else {}
        text = str(question.get("question_text") or "").strip()
        field = str(question.get("field") or "").strip()
        if text and field:
            AGENT_V2_V130_NEXT_QUESTION.set({
                "field": field,
                "question_text": text,
                "booking_objective_id": question.get("booking_objective_id"),
                "source": "v128_verified_booking_intent_bridge",
            })
            print(
                "   🧾 [AgentV2 V130 NEXT QUESTION RECEIPT] "
                f"field={field} objective={question.get('booking_objective_id')}"
            )
    _aplicar_next_best_action_agent_v2_v130_base(telefono, nba)


_agent_v2_verified_exact_availability_response_v130_base = (
    _agent_v2_verified_exact_availability_response
)


def _agent_v2_verified_exact_availability_response(
    goals: Dict,
    observations: List[Dict],
    world: Dict,
    perception: Dict,
) -> str:
    response = _agent_v2_verified_exact_availability_response_v130_base(
        goals,
        observations,
        world,
        perception,
    )
    if not response:
        return response

    receipt = AGENT_V2_V130_NEXT_QUESTION.get()
    if not isinstance(receipt, dict):
        return response
    if str(receipt.get("source") or "") != "v128_verified_booking_intent_bridge":
        return response

    question_text = str(receipt.get("question_text") or "").strip()
    if not question_text:
        return response
    if normalizar_texto_ia(question_text) in normalizar_texto_ia(response):
        return response

    print(
        "   🧾 [AgentV2 V130 EXACT SLOT + MISSING FIELD] "
        f"append_question field={receipt.get('field')}"
    )
    return f"{response.rstrip()}\n\n{question_text}".strip()


