def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v130_base()
    results = list(result.get("results") or [])

    msg = "Futbol 5\n1 hora\nServicio de parrilla tiene?"
    initial = [
        {"intencion": "reservar_cancha", "fragmento": "Futbol 5"},
        {"intencion": "pedir_horarios", "fragmento": "1 hora"},
        {"intencion": "consulta_informativa", "fragmento": "Servicio de parrilla tiene?"},
    ]
    swallowed = [{"intencion": "reservar_cancha", "fragmento": msg}]
    restored = _agent_v2_v130_restore_semantic_lanes(msg, initial, swallowed)

    first_msg = "Quiero alquilar una hora mañana a las 18 tendria disponible"
    first_initial = [
        {"intencion": "reservar_cancha", "fragmento": "Quiero alquilar una hora mañana a las 18"},
        {"intencion": "pedir_horarios", "fragmento": "tendria disponible"},
    ]
    first_audited = [{"intencion": "reservar_cancha", "fragmento": first_msg}]
    first_restored = _agent_v2_v130_restore_semantic_lanes(
        first_msg, first_initial, first_audited
    )

    results.extend([
        {
            "name": "v130_preserves_booking_and_information_as_two_semantic_lanes",
            "passed": bool(
                len(restored) == 2
                and restored[0].get("intencion") == "reservar_cancha"
                and restored[0].get("fragmento") == "Futbol 5\n1 hora"
                and restored[1].get("intencion") == "consulta_informativa"
            ),
        },
        {
            "name": "v130_keeps_exact_booking_preflight_compound",
            "passed": bool(first_restored == first_audited),
        },
    ])

    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


