# ============================================================================
# V131 — TEMPORAL GRANULARITY + ORDER-INDEPENDENT BOOKING SLOT COLLECTION
# ============================================================================
# A BookingObjective is the source of truth.  Every missing minimum field is
# exposed in one conversational question and represented by its own typed
# PendingInteraction, so the user may answer one, several, or all fields in any
# order.  Coarse periods never become an invented exact date.
# ============================================================================

AGENT_V2_UNIFIED_AGENTIC_CORE = "v131"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v131"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-24_dynamic_booking_slots_v131"


# ============================================================================
# V132 — DURABLE TEMPORAL RANGE + VERIFIED PENDING ANSWER PRIORITY
# ============================================================================


def _agent_v2_v132_should_preserve_pending_binding(
    mensaje: str,
    subintents: List[Dict[str, Any]],
    plan: Dict[str, Any],
) -> bool:
    """Evita que el router genérico desplace una respuesta pending verificada.

    La excepción es deliberadamente estructural: el binding debe cubrir todo el
    mensaje físico, o formar un plan mixto validado con actos cuyas evidencias
    también pertenecen literalmente al mismo lote. Un valor parcial hallado en
    un pedido nuevo más largo no obtiene esta prioridad.
    """
    if not isinstance(plan, dict) or plan.get("status") != "verified":
        return False
    bindings = [
        dict(item) for item in (plan.get("bindings") or [])
        if isinstance(item, dict) and item.get("verified") is True
    ]
    if not bindings:
        return False
    if plan.get("covers_entire_physical_turn") is True:
        return True

    message_key = normalizar_texto_ia(mensaje or "")
    if not message_key:
        return False
    if any(
        normalizar_texto_ia(item.get("evidence") or "") == message_key
        for item in bindings
    ):
        return True

    acts = [
        dict(item) for item in (plan.get("independent_acts") or [])
        if isinstance(item, dict)
    ]
    if not acts:
        return False

    evidences = [str(item.get("evidence") or "").strip() for item in bindings]
    for act in acts:
        evidence = next((
            str(item.get("evidence") or "").strip()
            for item in (act.get("provenance") or [])
            if isinstance(item, dict)
            and str(item.get("source") or "") == "current_user_turn"
        ), "")
        evidences.append(evidence)
    return bool(evidences) and all(
        evidence and _agent_v2_v126_literal_evidence(mensaje, evidence)
        for evidence in evidences
    )


def _agent_v2_v132_constrain_pending_day(
    interaction: Dict[str, Any],
    value: Any,
) -> Any:
    """Proyecta un weekday contestado sobre el rango temporal del objetivo."""
    interaction = dict(interaction or {})
    context = dict(interaction.get("context") or {})
    snapshot = dict(interaction.get("action_snapshot") or {})
    constraint = dict(
        context.get("temporal_constraint")
        or snapshot.get("temporal_constraint")
        or {}
    )
    start_raw = str(constraint.get("start_date") or "").strip()
    end_raw = str(constraint.get("end_date") or "").strip()
    if not start_raw or not end_raw:
        return value
    try:
        start = datetime.date.fromisoformat(start_raw)
        end = datetime.date.fromisoformat(end_raw)
    except ValueError:
        return value
    if end < start or (end - start).days > 62:
        return value

    candidate = _parse_fecha_row(str(value or ""))
    if candidate is None or start <= candidate <= end:
        return value

    matches = [
        start + datetime.timedelta(days=offset)
        for offset in range((end - start).days + 1)
        if (start + datetime.timedelta(days=offset)).weekday()
        == candidate.weekday()
    ]
    if len(matches) != 1:
        return value
    corrected = matches[0]
    corrected_value = f"{nombre_dia_es(corrected)} {corrected.strftime('%d/%m')}"
    print(
        "   📅 [AgentV2 V132 RANGE-CONSTRAINED DAY] "
        f"candidate={value!r} range={start_raw}..{end_raw} "
        f"→ {corrected_value}"
    )
    return corrected_value


_agent_v2_resolve_current_turn_date_with_ai_v132_base = (
    _agent_v2_resolve_current_turn_date_with_ai
)


def _agent_v2_v177_has_current_turn_day_evidence(
    perception: Dict[str, Any],
    mensaje: str,
) -> bool:
    """Indica si el turno actual aportó una referencia de día verificable.

    El freeze semántico protege la intención y el recurso elegidos, pero no debe
    convertir una fecha ISO calculada por el modelo en verdad calendario. La
    evidencia sigue siendo semántica (temporal_mentions/provenance); acá sólo se
    comprueba que realmente pertenezca al mensaje físico actual.
    """
    clean = dict(perception or {})
    authority = dict(clean.get("validated_temporal_resolution") or {})
    if authority.get("validated") is True:
        return False

    evidences: List[str] = []
    for item in clean.get("temporal_mentions") or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("kind") or "").strip().casefold() != "day":
            continue
        evidence = str(item.get("evidence") or "").strip()
        if evidence:
            evidences.append(evidence)

    for act in (_agent_v2_semantic_frame(clean).get("acts") or []):
        if not isinstance(act, dict):
            continue
        for item in act.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            if str(item.get("source") or "").strip() != "current_user_turn":
                continue
            field = str(item.get("field") or "").strip().casefold()
            if field not in {"temporal.day", "day", "dia", "entities.dia"}:
                continue
            evidence = str(item.get("evidence") or "").strip()
            if evidence:
                evidences.append(evidence)

    return any(
        _agent_v2_v126_literal_evidence(mensaje, evidence)
        for evidence in dict.fromkeys(evidences)
    )


async def _agent_v2_resolve_current_turn_date_with_ai(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Valida el calendario del turno sin reabrir intención ni recurso.

    V100 puede congelar correctamente ``query_availability`` y, aun así, traer
    un ISO aritméticamente incompatible con el weekday entendido por la IA. Si
    existe evidencia de día del turno actual, se ejecuta el adjudicador temporal
    dedicado: la IA devuelve la etiqueta semántica y Python calcula/verifica la
    fecha. Esto evita aceptar casos como ``lunes -> sábado``.
    """
    mentions = [
        item for item in ((perception or {}).get("temporal_mentions") or [])
        if isinstance(item, dict)
        and str(item.get("kind") or "").strip().casefold() == "day"
        and str(item.get("precision") or "").strip().casefold() == "range"
    ]
    objective = dict((perception or {}).get("booking_objective") or {})
    constraint = dict(
        objective.get("temporal_constraint")
        or (perception or {}).get("temporal_constraint")
        or {}
    )
    anchored = bool(
        constraint.get("start_date") and constraint.get("end_date")
    )
    if mentions and not anchored:
        print(
            "   📅 [AgentV2 V132 RANGE ANCHOR] "
            "rango semántico sin límites → adjudicación temporal dedicada"
        )
        # Esta es la implementación dedicada anterior al freeze V87/V100. Sólo
        # se habilita para completar el rango; operación, target y commitment no
        # se reinterpretan.
        return await _agent_v2_resolve_current_turn_date_with_ai_v86(
            perception, mensaje, world
        )
    if _agent_v2_v177_has_current_turn_day_evidence(perception, mensaje):
        print(
            "   📅 [AgentV2 V178 WEEKDAY CONSISTENCY] "
            "día explícito current-turn → validación calendario antes del freeze"
        )
        resolved = await _agent_v2_resolve_current_turn_date_with_ai_v86(
            perception, mensaje, world
        )
        authority = dict(
            (resolved or {}).get("validated_temporal_resolution") or {}
        )
        if authority.get("validated") is True:
            return resolved
        print(
            "   🚫 [AgentV2 V178 WEEKDAY CONSISTENCY] "
            "la fecha explícita no pudo validarse; rechazo el ISO candidato"
        )
        return _agent_v2_clear_non_exact_current_turn_day(
            perception,
            evidence="current_user_turn_day_requires_calendar_validation",
            mode="unknown",
            world=world,
        )
    return await _agent_v2_resolve_current_turn_date_with_ai_v132_base(
        perception, mensaje, world
    )


