_percibir_turno_agent_v2_v131_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v131_base(
        mensaje, world, image_path, learning_policy
    )
    range_mentions = [
        dict(item)
        for item in (perception.get("temporal_mentions") or [])
        if isinstance(item, dict)
        and str(item.get("kind") or "").strip().casefold() == "day"
        and str(item.get("precision") or "").strip().casefold() == "range"
        and str(item.get("evidence") or "").strip()
    ]
    if not range_mentions:
        return perception

    evidence = " ".join(
        str(item.get("evidence") or "").strip()
        for item in range_mentions
    ).strip()
    first_range = range_mentions[0]
    range_kind = str(first_range.get("range_kind") or "").strip().casefold()
    try:
        week_offset = (
            int(first_range.get("week_offset"))
            if first_range.get("week_offset") is not None
            else None
        )
    except (TypeError, ValueError):
        week_offset = None
    return _agent_v2_clear_non_exact_current_turn_day(
        perception,
        evidence=evidence,
        mode="week_range" if range_kind == "calendar_week" else "date_range",
        week_offset=week_offset,
        world=world or {},
    )


def _agent_v2_v131_render_missing_fields_question(
    missing_fields: List[str],
) -> str:
    labels = {
        "dia": "qué día exacto",
        "hora": "a qué hora",
        "resource_type": "qué deporte",
        "quincho": "qué quincho",
    }
    parts = [
        labels.get(str(field), str(field).replace("_", " "))
        for field in (missing_fields or [])
        if str(field or "").strip()
    ]
    if not parts:
        return ""
    body = parts[0] if len(parts) == 1 else (
        ", ".join(parts[:-1]) + " y " + parts[-1]
    )
    return f"¿Me indicás {body} querés reservar?"


_planificar_agent_v2_v131_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    plan = await _planificar_agent_v2_v131_base(
        world,
        perception,
        goals,
        observations,
        offline_mode,
        learning_policy,
    )
    objective = dict((perception or {}).get("booking_objective") or {})
    missing = list(_agent_v2_v103_compute_missing(objective)) if objective else []
    constraint = dict(objective.get("temporal_constraint") or {}) if objective else {}

    clean = dict(plan or {})
    steps = []
    changed = False
    for raw in clean.get("steps") or []:
        step = dict(raw) if isinstance(raw, dict) else raw
        if isinstance(step, dict) and step.get("tool") == "solicitar_dato":
            args = dict(step.get("args") or {})
            if str(args.get("booking_objective_id") or "") == str(
                objective.get("objective_id") or ""
            ):
                if constraint:
                    args["temporal_constraint"] = dict(constraint)
                    step["args"] = args
                    changed = True
                if len(missing) <= 1:
                    steps.append(step)
                    continue
                anchor = str(args.get("campo") or missing[0])
                if anchor not in missing:
                    anchor = missing[0]
                args["campo"] = anchor
                args["accepted_fields"] = list(missing)
                args["options_by_field"] = {
                    "resource_type": _configured_court_type_labels(),
                    "quincho": _agent_v2_v103_quincho_names(),
                }
                args["question_text"] = (
                    _agent_v2_v131_render_missing_fields_question(missing)
                )
                step["args"] = args
                step["reason"] = (
                    "V131 completar campos mínimos en cualquier orden: "
                    + ", ".join(missing)
                )
                changed = True
        steps.append(step)
    if changed:
        clean["steps"] = steps
        if len(missing) > 1:
            clean["done_if"] = "booking objective recibe cualquier subconjunto de missing_fields"
            clean["reason"] = "v131_order_independent_booking_collection"
            print(
                "   🧩 [AgentV2 V131 MULTI-SLOT QUESTION] "
                f"objective={objective.get('objective_id')} missing={missing}"
            )
        elif constraint:
            print(
                "   📅 [AgentV2 V132 RANGE CARRY] "
                f"objective={objective.get('objective_id')} missing={missing} "
                f"range={constraint.get('start_date')}..{constraint.get('end_date')}"
            )
    return clean


_ejecutar_tool_agent_v2_v131_base = ejecutar_tool_agent_v2


async def ejecutar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    telefono: str,
    prospecto: Dict,
    user_messages: List[str],
    page=None,
    image_path: str = "",
) -> Dict[str, Any]:
    observation = await _ejecutar_tool_agent_v2_v131_base(
        tool,
        args,
        world,
        perception,
        goals,
        telefono,
        prospecto,
        user_messages,
        page=page,
        image_path=image_path,
    )
    if tool == "solicitar_dato" and isinstance(observation, dict):
        accepted = [
            _agent_v2_v105_normalize_missing_field(field)
            for field in (args.get("accepted_fields") or [])
            if _agent_v2_v105_normalize_missing_field(field)
        ]
        if accepted or isinstance(args.get("temporal_constraint"), dict):
            data = dict(observation.get("data") or {})
            if accepted:
                data["accepted_fields"] = list(dict.fromkeys(accepted))
                data["options_by_field"] = dict(args.get("options_by_field") or {})
            data["question_text"] = str(args.get("question_text") or "")
            if isinstance(args.get("temporal_constraint"), dict):
                data["temporal_constraint"] = dict(
                    args.get("temporal_constraint") or {}
                )
            observation = dict(observation)
            observation["data"] = data
    return observation


_aplicar_observation_agent_v2_v131_base = aplicar_observation_agent_v2


def aplicar_observation_agent_v2(
    telefono: str,
    observation: Dict,
    world: Dict,
    perception: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    state = _aplicar_observation_agent_v2_v131_base(
        telefono, observation, world, perception
    )
    if not (
        observation.get("tool") == "solicitar_dato"
        and observation.get("status") == "needs_user_input"
    ):
        return state

    data = dict(observation.get("data") or {})
    accepted = list(dict.fromkeys(
        _agent_v2_v105_normalize_missing_field(field)
        for field in (data.get("accepted_fields") or [])
        if _agent_v2_v105_normalize_missing_field(field)
    ))
    if len(accepted) <= 1:
        return state

    objective_id = str(data.get("booking_objective_id") or "").strip()
    snapshot = dict(data.get("action_snapshot") or {})
    question_text = str(data.get("question_text") or "").strip()
    options_by_field = dict(data.get("options_by_field") or {})
    primary = _agent_v2_v105_normalize_missing_field(data.get("field"))
    common = {
        "scope_id": str((world or {}).get("current_scope_id") or ""),
        "reason": "campos faltantes del objetivo de reserva activo",
        "goal_context": ["buscar_turno", "crear_reserva"],
        "booking_choice": True,
        "question": question_text,
        "question_text": question_text,
        "action_snapshot": snapshot,
        "allowed_operations": ["create_booking", "query_availability"],
        "booking_objective_id": objective_id,
        "dia": data.get("dia"),
        "hora": data.get("hora"),
        "duracion_horas": data.get("duracion_horas"),
        "cancha": data.get("cancha"),
        "resource_type": data.get("resource_type"),
        "resource_types": list(data.get("resource_types") or []),
        "con_quincho": bool(data.get("con_quincho")),
        "quincho": data.get("quincho"),
        "quincho_duracion_horas": data.get("quincho_duracion_horas"),
        "accepted_fields": list(accepted),
        "temporal_constraint": dict(data.get("temporal_constraint") or {}),
        "source": "v131_multi_slot_collection",
        "source_message": (world or {}).get("message"),
    }

    # El reducer base ya abrió el anchor. Publicamos una interacción hermana
    # por cada otro field; comparten objetivo y pregunta, no identidad.
    for field in accepted:
        if field == primary:
            continue
        qid = f"{objective_id}:{field}" if objective_id else str(uuid.uuid4())
        payload = {
            **common,
            "interaction_id": qid,
            "question_id": qid,
            "field": field,
            "options": list(options_by_field.get(field) or []),
        }
        state = agent_v2_reduce(
            telefono,
            {"type": "SET_OPEN_QUESTION", "payload": payload},
        )

    print(
        "   🧩 [AgentV2 V131 TYPED PENDINGS] "
        f"objective={objective_id} fields={accepted}"
    )
    return state


def _agent_v2_v131_unique_configured_option(
    mensaje: str,
    candidate: Dict[str, Any],
) -> Any:
    """Recuperación genérica para una opción tipada con typo/fragmentos."""
    field = _agent_v2_v105_normalize_missing_field(candidate.get("field"))
    if field == "resource_type":
        options = list(_configured_court_type_labels())
    elif field == "cancha":
        options = sorted(_agent_v2_v105_configured_court_names())
    elif field == "quincho":
        options = list(_agent_v2_v103_quincho_names())
    else:
        return None
    source = normalizar_texto_ia(mensaje or "")
    if not source or not options:
        return None
    source_words = source.split()
    spans = {source}
    for start in range(len(source_words)):
        for width in range(1, min(4, len(source_words) - start) + 1):
            spans.add(" ".join(source_words[start:start + width]))
    scored = sorted(
        (
            max(
                difflib.SequenceMatcher(
                    None, span, normalizar_texto_ia(option or "")
                ).ratio()
                for span in spans
            ),
            option,
        )
        for option in options
        if str(option or "").strip()
    )
    if not scored:
        return None
    best_score, best_value = scored[-1]
    runner_up = scored[-2][0] if len(scored) > 1 else 0.0
    if best_score < 0.78 or best_score - runner_up < 0.10:
        return None
    return _agent_v2_v126_validate_binding_value(
        candidate.get("_interaction") or {}, field, best_value
    )


_agent_v2_v126_resolve_dialogue_context_before_perception_v131_base = (
    _agent_v2_v126_resolve_dialogue_context_before_perception
)


async def _agent_v2_v126_resolve_dialogue_context_before_perception(
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    plan = await _agent_v2_v126_resolve_dialogue_context_before_perception_v131_base(
        mensaje, world
    )
    if isinstance(plan, dict) and plan.get("status") == "verified":
        bindings = [b for b in (plan.get("bindings") or []) if isinstance(b, dict)]
        acts = [a for a in (plan.get("independent_acts") or []) if isinstance(a, dict)]
        candidates, _ = _agent_v2_v126_binding_candidates(world or {})
        bound_keys = {
            (
                str(item.get("interaction_id") or ""),
                _agent_v2_v105_normalize_missing_field(item.get("field")),
            )
            for item in bindings
        }
        supplemental = []
        binding_objective_ids = {
            str(item.get("objective_id") or "").strip()
            for item in bindings
            if str(item.get("objective_id") or "").strip()
        }
        for candidate in candidates:
            key = (
                str(candidate.get("interaction_id") or ""),
                _agent_v2_v105_normalize_missing_field(candidate.get("field")),
            )
            if key in bound_keys:
                continue
            candidate_objective_id = str(candidate.get("objective_id") or "").strip()
            if (
                binding_objective_ids
                and candidate_objective_id
                and candidate_objective_id not in binding_objective_ids
            ):
                continue
            value = _agent_v2_v131_unique_configured_option(mensaje, candidate)
            if value is None:
                continue
            supplemental.append({
                "relation": "answers_pending",
                "interaction_id": str(candidate.get("interaction_id") or ""),
                "question_id": str(candidate.get("question_id") or ""),
                "scope_id": str(candidate.get("scope_id") or ""),
                "objective_id": candidate_objective_id or None,
                "field": key[1],
                "value": value,
                "evidence": str(mensaje or "").strip(),
                "confidence": 0.99,
                "verified": True,
                "_interaction": dict(candidate.get("_interaction") or {}),
                "source": "v135_supplemental_typed_binding",
            })
        if supplemental:
            plan = dict(plan)
            bindings = bindings + supplemental
            plan["bindings"] = bindings
            if not acts:
                plan["covers_entire_physical_turn"] = True
            print(
                "   ✅ [AgentV2 V135 MULTI-FIELD BINDING] "
                f"fields={[item.get('field') for item in bindings]}"
            )
        unique_full_turn_option = False
        if len(bindings) == 1 and not acts:
            binding = bindings[0]
            candidate = next((
                item for item in candidates
                if str(item.get("interaction_id") or "")
                == str(binding.get("interaction_id") or "")
                and _agent_v2_v105_normalize_missing_field(item.get("field"))
                == _agent_v2_v105_normalize_missing_field(binding.get("field"))
            ), None)
            fuzzy_value = (
                _agent_v2_v131_unique_configured_option(mensaje, candidate)
                if candidate else None
            )
            unique_full_turn_option = bool(
                fuzzy_value is not None
                and normalizar_texto_ia(fuzzy_value)
                == normalizar_texto_ia(binding.get("value") or "")
                and normalizar_texto_ia(binding.get("evidence") or "")
                == normalizar_texto_ia(mensaje or "")
            )
        if unique_full_turn_option:
            plan = dict(plan)
            plan["covers_entire_physical_turn"] = True
        return plan

    candidates, objective = _agent_v2_v126_binding_candidates(world or {})
    matches = []
    for candidate in candidates:
        value = _agent_v2_v131_unique_configured_option(mensaje, candidate)
        if value is None:
            continue
        matches.append((candidate, value))
    if len(matches) != 1 or not objective:
        return plan

    candidate, value = matches[0]
    binding = {
        "relation": "answers_pending",
        "interaction_id": str(candidate.get("interaction_id") or ""),
        "question_id": str(candidate.get("question_id") or ""),
        "scope_id": str(candidate.get("scope_id") or ""),
        "objective_id": str(candidate.get("objective_id") or "") or None,
        "field": _agent_v2_v105_normalize_missing_field(candidate.get("field")),
        "value": value,
        "evidence": str(mensaje or "").strip(),
        "confidence": 0.99,
        "verified": True,
        "_interaction": dict(candidate.get("_interaction") or {}),
        "source": "v131_unique_configured_option",
    }
    print(
        "   ✅ [AgentV2 V131 FRAGMENTED OPTION] "
        f"field={binding['field']} value={value} covers_entire_turn=True"
    )
    return {
        "status": "verified",
        "relation": "answers_pending",
        "bindings": [binding],
        "independent_acts": [],
        "reason": "unique configured option across physical message batch",
        "semantic_frozen": True,
        "covers_entire_physical_turn": True,
    }


_run_agent_v2_invariant_evals_v131_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v131_base()
    results = list(result.get("results") or [])
    question = _agent_v2_v131_render_missing_fields_question(
        ["dia", "resource_type"]
    )
    fake_interaction = {
        "field": "resource_type",
        "options": _configured_court_type_labels(),
        "_interaction": {"options": _configured_court_type_labels()},
    }
    fuzzy_value = _agent_v2_v131_unique_configured_option(
        "ftbol\n5", fake_interaction
    )
    results.extend([
        {
            "name": "v131_compound_question_requests_every_missing_booking_field",
            "passed": bool("día exacto" in question and "deporte" in question),
        },
        {
            "name": "v131_fragmented_typed_option_resolves_uniquely",
            "passed": bool(
                normalizar_texto_ia(fuzzy_value or "")
                == normalizar_texto_ia("Futbol 5")
            ),
        },
    ])
    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


# ============================================================================
# V133 — PARTIAL BOOKING INTENT → DURABLE BOOKING OBJECTIVE
# ============================================================================
# El router puede reconocer una petición de reserva mientras Perception conserva
# query_availability porque todavía falta un día exacto. Ese READ no debe perder
# hora, rango ni los demás mínimos: se promueve a un objetivo collecting y V131
# pregunta todos los campos faltantes antes del preflight.
# ============================================================================


async def _agent_v2_v133_promote_partial_booking_intent(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    clean = dict(perception or {})
    router = _agent_v2_v128_router_subintent()
    if str(router.get("intencion") or "").strip() != "reservar_cancha":
        return clean

    active = _agent_v2_v103_active_objective_from_world(world or {})
    if active and str(active.get("status") or "") in {
        "active", "collecting", "ready", "preflight", "suspended",
    }:
        return clean

    frame = dict(_agent_v2_semantic_frame(clean) or {})
    acts = [dict(item) for item in (frame.get("acts") or []) if isinstance(item, dict)]
    operations = {
        str(item.get("operation") or "").strip()
        for item in acts
        if str(item.get("operation") or "").strip() not in {"", "greet"}
    }
    if operations != {"query_availability"}:
        return clean

    temporal = dict(frame.get("temporal") or {})
    entities = dict(clean.get("entities") or {})
    hour = normalizar_hora_detectada(
        temporal.get("start") or entities.get("hora")
    )

    fragment = str(router.get("fragmento") or "").strip()
    if not fragment or not _agent_v2_v126_literal_evidence(mensaje, fragment):
        return clean

    promoted_acts = []
    for raw in acts:
        act = dict(raw)
        if str(act.get("operation") or "") == "query_availability":
            act["operation"] = "create_booking"
            act["domain"] = "booking"
            act["requested_facts"] = []
            act["commitment"] = {
                "wants_write": True,
                "wants_information": False,
            }
            provenance = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
            ]
            provenance.append({
                "field": "intent.operation",
                "source": "current_user_turn",
                "evidence": fragment,
                "verification": "v133_audited_booking_router",
            })
            act["provenance"] = provenance
        promoted_acts.append(act)

    intent = dict(frame.get("intent") or {})
    intent["domain"] = "booking"
    intent["operation"] = "create_booking"
    frame["intent"] = intent
    frame["acts"] = promoted_acts
    frame["commitment"] = {
        "wants_write": True,
        "wants_information": False,
    }
    frame["booking_commitment"] = "conditional_booking"
    clean["semantic_frame"] = frame
    clean["commitment"] = "wants_action"
    clean.pop("execution_contract", None)
    clean.pop("semantic_effect_verification", None)
    clean.pop("booking_collection_contract", None)
    clean.pop("_v100_semantic_frozen", None)

    verified = await _agent_v2_verify_semantic_effects(
        mensaje, clean, world or {}
    )
    verified["semantic_frame"] = frame
    objective, engaged = _agent_v2_v103_build_objective(
        verified, world or {}
    )
    if not engaged or not objective:
        return perception

    booking_act = next((
        dict(item) for item in promoted_acts
        if str(item.get("operation") or "") == "create_booking"
    ), {})
    objective["provenance"] = [
        dict(item) for item in (booking_act.get("provenance") or [])
        if isinstance(item, dict)
    ]
    constraint = dict(
        clean.get("temporal_constraint")
        or (clean.get("validated_temporal_resolution") or {}).get(
            "temporal_constraint"
        )
        or {}
    )
    if constraint:
        objective["temporal_constraint"] = constraint
    objective["missing_fields"] = _agent_v2_v103_compute_missing(objective)
    objective["status"] = (
        "ready" if not objective["missing_fields"] else "collecting"
    )
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)

    verified = _agent_v2_v103_apply_objective_to_perception(
        verified, objective
    )
    verified["booking_objective"] = dict(objective)
    verified["_v103_booking_engaged"] = True
    collection = _agent_v2_v104_build_collection_contract(
        verified, world or {}
    )
    if not collection and objective.get("missing_fields"):
        # Semantic Effect Verifier puede negar correctamente el WRITE porque aún
        # faltan slots. Esa negativa no debe impedir una pregunta sin efectos.
        # Usamos una copia con autoridad efímera sólo para construir el contrato
        # V104 de recolección; nunca persistimos esa autorización ni habilitamos
        # crear_reserva/consultar_disponibilidad.
        collection_seed = _agent_v2_v125_copy.deepcopy(verified)
        collection_seed["semantic_effect_verification"] = {
            "status": "verified",
            "write_authorizations": [{
                "act_id": objective.get("act_id"),
                "operation": "create_booking",
                "authorized": True,
            }],
        }
        collection = _agent_v2_v104_build_collection_contract(
            collection_seed, world or {}
        )
        if collection:
            collection["intent_authority"] = {
                "source": "v133_audited_booking_router",
                "evidence": fragment,
                "write_allowed": False,
            }
            print(
                "   🔐 [AgentV2 V135 COLLECTION AUTHORITY] "
                "write rechazado/incompleto; solicitar_dato autorizado sin efectos"
            )
    verified["booking_collection_contract"] = collection
    verified.pop("execution_contract", None)
    verified["execution_contract"] = _agent_v2_build_execution_contract(
        verified, world or {}
    )
    verified = _agent_v2_v100_attach_desired_state_and_task_graph(
        verified, world or {}
    )
    verified.setdefault("task_graph", {})["booking_missing_fields"] = list(
        objective.get("missing_fields") or []
    )
    verified["task_graph"]["booking_objective_id"] = objective.get(
        "objective_id"
    )
    verified["_v100_semantic_frozen"] = True
    print(
        "   🎯 [AgentV2 V133 PARTIAL BOOKING OBJECTIVE] "
        f"objective={objective.get('objective_id')} hour={hour or '-'} "
        f"missing={objective.get('missing_fields')} "
        f"range={constraint.get('start_date')}..{constraint.get('end_date')}"
    )
    return verified


def _agent_v2_v135_seed_current_turn_hour_authority(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Certifica una hora literal también sobre objetivos activos pre-V135."""
    clean = dict(perception or {})
    objective = (
        dict(clean.get("booking_objective") or {})
        if isinstance(clean.get("booking_objective"), dict)
        else _agent_v2_v103_active_objective_from_world(world or {})
    )
    if str(objective.get("operation") or "") != "create_booking":
        return clean
    hour = normalizar_hora_detectada(
        ((objective.get("temporal") or {}).get("start"))
    )
    if not hora_es_valida(hour):
        return clean

    hour_evidence = next((
        str(item.get("evidence") or "").strip()
        for item in (clean.get("temporal_mentions") or [])
        if isinstance(item, dict)
        and str(item.get("kind") or "").lower() == "time"
        and normalizar_hora_detectada(item.get("resolved_value")) == hour
        and _agent_v2_v126_literal_evidence(
            mensaje, str(item.get("evidence") or "").strip()
        )
    ), "")
    if not hour_evidence:
        frame = _agent_v2_semantic_frame(clean) or {}
        hour_evidence = next((
            str(item.get("evidence") or "").strip()
            for act in (frame.get("acts") or [])
            if isinstance(act, dict)
            for item in (act.get("provenance") or [])
            if isinstance(item, dict)
            and str(item.get("field") or "") in {
                "temporal.start", "start_time", "hora"
            }
            and _agent_v2_v126_literal_evidence(
                mensaje, str(item.get("evidence") or "").strip()
            )
        ), "")
    if (
        not hour_evidence
        and hour in _agent_v2_current_message_exact_hours(mensaje)
    ):
        hour_evidence = str(mensaje or "").strip()
    if not hour_evidence:
        return clean

    field_authority = dict(objective.get("field_authority") or {})
    field_authority["hora"] = {
        "field": "hora",
        "value": hour,
        "objective_id": objective.get("objective_id"),
        "act_id": objective.get("act_id"),
        "source": "v135_current_user_time",
        "evidence": hour_evidence,
        "verified": True,
        "verified_at": datetime.datetime.now(TIMEZONE).isoformat(),
    }
    objective["field_authority"] = field_authority
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    clean["booking_objective"] = objective
    if isinstance((clean.get("desired_state") or {}).get("booking_objective"), dict):
        desired = dict(clean.get("desired_state") or {})
        desired["booking_objective"] = dict(objective)
        clean["desired_state"] = desired
    print(
        "   🔐 [AgentV2 V135 CURRENT-TURN TIME AUTHORITY] "
        f"objective={objective.get('objective_id')} hora={hour}"
    )
    return clean


_percibir_turno_agent_v2_v133_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    perception = await _percibir_turno_agent_v2_v133_base(
        mensaje, world, image_path, learning_policy
    )
    perception = await _agent_v2_v133_promote_partial_booking_intent(
        perception, mensaje, world or {}
    )
    return _agent_v2_v135_seed_current_turn_hour_authority(
        perception, mensaje, world or {}
    )


