# ============================================================================
# V136 — READY BOOKING MAY AUTOASSIGN AN EQUIVALENT COURT
# ============================================================================
# Incidente live:
#   El objetivo ya estaba READY (día, hora, duración y Futbol 5), el Effect
#   Verifier había autorizado create_booking y el calendario devolvió dos canchas
#   libres del mismo tipo. La regla V126R2 sólo autoasignaba si el ÚLTIMO binding
#   era resource_type. Cuando el último dato faltante era `dia`, la disponibilidad
#   terminaba en needs_user_input y el turno nunca llegaba al HOLD/comprobante.
#
# Invariante V136:
#   La autoridad pertenece al BookingObjective completo, no al orden en que el
#   usuario entregó sus campos. Un objetivo READY y autorizado puede elegir la
#   primera cancha libre si (y sólo si) todas las candidatas son equivalentes al
#   único resource_type solicitado y no hubo selección explícita de cancha.
# ============================================================================

_agent_v2_v126r2_can_auto_assign_equivalent_court_v136_base = (
    _agent_v2_v126r2_can_auto_assign_equivalent_court
)


def _agent_v2_v126r2_can_auto_assign_equivalent_court(
    perception: Dict[str, Any],
    available_courts: List[str],
) -> bool:
    if _agent_v2_v126r2_can_auto_assign_equivalent_court_v136_base(
        perception or {}, available_courts or []
    ):
        return True

    courts = [
        str(value or "").strip()
        for value in (available_courts or [])
        if str(value or "").strip()
    ]
    if not courts:
        return False

    objective = (
        dict((perception or {}).get("booking_objective") or {})
        if isinstance((perception or {}).get("booking_objective"), dict)
        else {}
    )
    objective_id = str(objective.get("objective_id") or "").strip()
    if (
        not objective_id
        or str(objective.get("operation") or "") != "create_booking"
        or _agent_v2_v103_compute_missing(objective)
        or not _agent_v2_v126_authorized_create_booking(perception or {})
    ):
        return False

    target = dict(objective.get("target") or {})
    if str(target.get("label") or "").strip():
        return False
    types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if len(types) != 1:
        return False

    # Exige una continuación verificada del mismo objetivo. El campo contestado
    # puede ser día, hora, duración o deporte: su orden no cambia la intención.
    binding = _agent_v2_v126r2_verified_binding_for_objective(
        perception or {}, objective_id
    )
    if not binding:
        return False
    if _agent_v2_v105_normalize_missing_field(binding.get("field")) not in {
        "dia", "hora", "duracion", "resource_type", "cancha"
    }:
        return False

    if not all(_court_matches_resource_types(court, types) for court in courts):
        return False

    print(
        "   ✅ [AgentV2 V136 READY OBJECTIVE AUTOASSIGN] "
        f"objective={objective_id} completed_field={binding.get('field')} "
        f"resource_type={types[0]} courts={courts}"
    )
    return True


