# ============================================================================
# V137 — CURRENT-TURN EVIDENCE FIREWALL FOR BOOKING ADDONS
# ============================================================================
# Incidente live:
#   El Dialogue Context Resolver completó correctamente `dia` y `resource_type`
#   desde "Viernes futbol", pero además inventó query_policy(resource=quincho).
#   La única evidence era la frase completa, que no mencionaba ese servicio.
#   V127 interpretó el acto alucinado como un addon pedido y cobró un quincho.
#
# Invariante V137:
#   Memoria, configuración y objetivo activo pueden aportar slots de la cancha,
#   pero un recurso adicional sólo sobrevive si el mensaje ACTUAL contiene
#   evidencia literal de ese servicio. Esto no fija ningún orden conversacional:
#   únicamente protege un efecto comercial/cobrable de evidencia inventada.
# ============================================================================


def _agent_v2_v137_quincho_policy_act_has_current_turn_evidence(
    act: Dict[str, Any],
    mensaje: str,
) -> bool:
    if not isinstance(act, dict):
        return False
    if str(act.get("operation") or "") != "query_policy":
        return True
    target = dict(act.get("target") or {})
    if str(target.get("resource") or "").strip().casefold() != "quincho":
        return True

    evidence_values = [
        str(item.get("evidence") or "").strip()
        for item in (act.get("provenance") or [])
        if isinstance(item, dict)
        and str(item.get("source") or "current_user_turn") == "current_user_turn"
    ]
    evidence_values.extend([
        str(act.get("evidence") or "").strip(),
        str(target.get("evidence") or "").strip(),
    ])
    return any(
        evidence
        and _agent_v2_v126_literal_evidence(mensaje, evidence)
        and mensaje_pide_quincho(evidence)
        for evidence in evidence_values
    )


def _agent_v2_v137_drop_ungrounded_booking_addons(
    plan: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    if not isinstance(plan, dict) or plan.get("status") != "verified":
        return plan

    original_acts = [
        dict(act)
        for act in (plan.get("independent_acts") or [])
        if isinstance(act, dict)
    ]
    kept_acts = [
        act for act in original_acts
        if _agent_v2_v137_quincho_policy_act_has_current_turn_evidence(
            act, mensaje
        )
    ]
    if len(kept_acts) == len(original_acts):
        return plan

    bindings = [
        dict(binding)
        for binding in (plan.get("bindings") or [])
        if isinstance(binding, dict)
    ]
    clean = dict(plan)
    clean["independent_acts"] = kept_acts
    if bindings and kept_acts:
        clean["relation"] = "mixed"
    elif bindings:
        clean["relation"] = str(
            bindings[0].get("relation") or "answers_pending"
        )
    elif kept_acts:
        clean["relation"] = "independent"
    else:
        clean.update({
            "status": "unresolved",
            "relation": "unresolved",
            "semantic_frozen": False,
        })
    clean["reason"] = "v137_dropped_addon_without_current_turn_evidence"
    print(
        "   🚫 [AgentV2 V137 UNGROUNDED ADDON DROPPED] "
        f"removed={len(original_acts) - len(kept_acts)} "
        f"bindings={[(b.get('field'), b.get('value')) for b in bindings]}"
    )
    return clean


_agent_v2_v126_resolve_dialogue_context_before_perception_v137_base = (
    _agent_v2_v126_resolve_dialogue_context_before_perception
)


async def _agent_v2_v126_resolve_dialogue_context_before_perception(
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    plan = await _agent_v2_v126_resolve_dialogue_context_before_perception_v137_base(
        mensaje,
        world,
    )
    return _agent_v2_v137_drop_ungrounded_booking_addons(plan, mensaje)


