def build_agent_v2_internal_failure_handoff_response() -> str:
    """Mensaje cliente-safe para un error confirmado que ya fue derivado."""
    return (
        "Tuve un inconveniente al procesar esta gestión y no quiero darte una "
        "confirmación incorrecta. Ya derivé el caso al encargado para que lo "
        "revise manualmente.\n\n"
        f"{HUMAN_CONTACT_NAME} se va a comunicar con vos para ayudarte.\n\n"
        f"📱 Su WhatsApp es {HUMAN_WHATSAPP}.\n\n"
        "Tu consulta quedó registrada para revisión."
    )


def _agent_v2_v140_internal_failure_signal(
    response: str = "",
    observations: Optional[List[Dict[str, Any]]] = None,
    assessment: Optional[Dict[str, Any]] = None,
) -> str:
    """Devuelve un código estructurado sólo para fallos internos confirmados.

    Los rechazos de negocio verificados (comprobante reutilizado, torneo lleno,
    etc.) siguen su flujo propio: no son errores de representación del sistema.
    """
    observations = list(observations or [])
    if any(
        obs.get("tool") == "solicitar_handoff_humano"
        and (obs.get("ok") or (obs.get("data") or {}).get("handoff_registered"))
        for obs in observations
        if isinstance(obs, dict)
    ):
        return ""

    state = str((assessment or {}).get("state") or "").strip()
    reason_code = str((assessment or {}).get("reason_code") or "").strip()
    # V100 ya clasificó estos estados como recuperación conversacional segura.
    # Reescalarlos aquí contradice el contrato "no handoff" y convierte un dato
    # faltante o policy guard recuperable en una derivación humana.
    if state in {
        "internal_recovery_write",
        "internal_recovery_question",
        "internal_recovery_read",
    }:
        return ""
    if state == "internal_read_representation_failure":
        return f"safe_exit:{state}"
    if reason_code in {"internal_representation_failure", "internal_read_representation_failure"}:
        return f"safe_exit:{reason_code}"

    for obs in observations:
        if not isinstance(obs, dict):
            continue
        data = obs.get("data") or {}
        reason = str(
            data.get("reason") or data.get("motivo") or data.get("reason_code") or ""
        ).strip().casefold()
        if reason in _AGENT_V2_V140_CONFIRMED_TRANSACTIONAL_REJECTIONS:
            continue
        if reason in _AGENT_V2_V140_INTERNAL_PAYMENT_REASONS:
            return f"observation:{obs.get('tool')}:{reason}"
        contract = data.get("policy_fact_contract") or {}
        if isinstance(contract, dict) and contract.get("requires_human_attention"):
            return f"observation:{obs.get('tool')}:policy_requires_human_attention"
        if data.get("requires_human_review") is True:
            return f"observation:{obs.get('tool')}:requires_human_review"
        if obs.get("status") == "needs_human_review":
            return f"observation:{obs.get('tool')}:needs_human_review"

    normalized = normalizar_texto_ia(str(response or ""))
    for marker in _AGENT_V2_V140_INTERNAL_FAILURE_TEXTS:
        if marker in normalized:
            return f"response:{marker[:80]}"
    return ""


def _agent_v2_v140_register_internal_failure_handoff(
    *,
    source: str,
    original_response: str,
    world: Optional[Dict[str, Any]],
    observations: List[Dict[str, Any]],
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    perception: Optional[Dict[str, Any]] = None,
    page=None,
    dry_run: bool = False,
) -> Tuple[str, Dict[str, Any], Dict[str, Any]]:
    """Registra el caso, pausa el agente y deja la alerta lista para post-send."""
    for obs in reversed(observations or []):
        data = (obs or {}).get("data") or {}
        if (
            (obs or {}).get("tool") == "solicitar_handoff_humano"
            and ((obs or {}).get("ok") or data.get("handoff_registered"))
        ):
            return (
                str(data.get("respuesta") or build_agent_v2_internal_failure_handoff_response()),
                {"safe": True, "state": "human_handoff", "evidence": [obs.get("observation_id")]},
                obs,
            )

    message = str((world or {}).get("message") or "").strip()
    reason = f"universal_safe_exit:internal_system_failure:{source}"[:1000]
    case = {}
    if not dry_run:
        case = registrar_caso_humano(
            "humano",
            message,
            telefono,
            prospecto or {},
            reason=reason,
            source="agent_v2_internal_failure_v140",
        )
    data = {
        "tipo": "humano",
        "reason": reason,
        "mensaje_usuario": message,
        "original_response_suppressed": str(original_response or "")[:1000],
        "case_id": case.get("case_id"),
        "admin_notified": False,
        "notification_attempted": False,
        "notification_pending": bool(page is not None and not dry_run),
        "handoff_registered": True,
        "safe_exit_fallback": True,
        "internal_failure": True,
        "silent_handoff": True,
        "handoff_mode": "silent_internal_failure",
        "customer_response_suppressed": True,
        "delivery_policy": "suppress_customer",
        "respuesta": "",
    }
    handoff = _agent_v2_observation(
        "solicitar_handoff_humano",
        True,
        "success",
        data,
        verified_facts={"handoff": data},
    )
    observations.append(handoff)
    if not dry_run:
        aplicar_observation_agent_v2(
            telefono,
            handoff,
            world or {},
            perception or {},
        )
    registrar_metrica_operativa("agent_v2_internal_failure_handoff", {
        "telefono": telefono,
        "case_id": data.get("case_id"),
        "source": source[:500],
        "suppressed_response": str(original_response or "")[:500],
    })
    assessment = {
        "safe": True,
        "state": "human_handoff",
        "fallback_applied": True,
        "reason_code": "internal_system_failure",
        "reason": source,
        "evidence": [handoff.get("observation_id")],
        "terminal_outcome": "internal_failure",
        "customer_response_suppressed": True,
        "delivery_policy": "suppress_customer",
        "silent_handoff": True,
    }
    print(f"   🧑‍💼 [AgentV2 V140 INTERNAL FAILURE] handoff registrado source={source}")
    return "", assessment, handoff


async def _agent_v2_v140_send_legacy_internal_handoff(
    page,
    *,
    source: str,
    original_response: str,
    telefono: str,
    prospecto: Optional[Dict[str, Any]],
    mensaje_usuario: str,
) -> Tuple[str, bool]:
    """Adapta rutas legacy de envío directo al mismo contrato durable de handoff."""
    observations: List[Dict[str, Any]] = []
    response, _, handoff = _agent_v2_v140_register_internal_failure_handoff(
        source=f"legacy:{source}",
        original_response=original_response,
        world={"message": mensaje_usuario},
        observations=observations,
        telefono=telefono,
        prospecto=prospecto,
        perception={},
        page=page,
        dry_run=False,
    )
    data = handoff.get("data") or {}
    if data.get("notification_pending"):
        notified = await enviar_alerta_humano_admin(
            page,
            mensaje_usuario,
            telefono,
            prospecto,
            reason=str(data.get("reason") or ""),
            case_id=data.get("case_id"),
        )
        data["notification_pending"] = False
        data["notification_attempted"] = True
        data["admin_notified"] = notified is True
    print(
        "   🤫 [AgentV2 LEGACY SILENT HANDOFF] "
        "respuesta cliente suprimida; alerta administrativa procesada"
    )
    return "", True


_aplicar_regla_universal_salida_segura_agent_v2_v140_base = (
    aplicar_regla_universal_salida_segura_agent_v2
)


def aplicar_regla_universal_salida_segura_agent_v2(
    response: str,
    world: Dict[str, Any],
    perception: Dict[str, Any],
    goals: Dict[str, Any],
    observations: List[Dict[str, Any]],
    status: str,
    telefono: str,
    prospecto: Optional[Dict[str, Any]] = None,
    page=None,
    dry_run: bool = False,
) -> Tuple[str, Dict[str, Any]]:
    final_response, assessment = _aplicar_regla_universal_salida_segura_agent_v2_v140_base(
        response, world, perception, goals, observations, status,
        telefono, prospecto, page, dry_run,
    )
    signal = _agent_v2_v140_internal_failure_signal(
        final_response, observations, assessment
    )
    if not signal:
        return final_response, assessment
    escalated, escalated_assessment, _ = _agent_v2_v140_register_internal_failure_handoff(
        source=signal,
        original_response=final_response,
        world=world,
        observations=observations,
        telefono=telefono,
        prospecto=prospecto,
        perception=perception,
        page=page,
        dry_run=dry_run,
    )
    return escalated, escalated_assessment


_ejecutar_agente_real_v2_turno_v140_base = ejecutar_agente_real_v2_turno


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Barrera final: también captura fallos introducidos después de Safe Exit."""
    result = await _ejecutar_agente_real_v2_turno_v140_base(
        mensaje,
        conv_state,
        prospecto,
        telefono,
        user_messages=user_messages,
        page=page,
        image_path=image_path,
        dry_run=dry_run,
        eval_context=eval_context,
    )
    if not isinstance(result, dict) or not result.get("handled"):
        return result
    observations = result.setdefault("observations", [])
    signal = _agent_v2_v140_internal_failure_signal(
        result.get("response") or "",
        observations,
        result.get("safe_exit") or {},
    )
    if not signal:
        return result
    response, assessment, _ = _agent_v2_v140_register_internal_failure_handoff(
        source=signal,
        original_response=result.get("response") or "",
        world=result.get("world") or {"message": mensaje},
        observations=observations,
        telefono=telefono,
        prospecto=prospecto,
        perception=result.get("perception") or {},
        page=page,
        dry_run=dry_run,
    )
    result["response"] = aplicar_negrita_fechas_horas_whatsapp(response)
    result["safe_exit"] = assessment
    result["status"] = "complete"
    return result


def _agent_v2_v141_verified_exact_slot_followup_hour(
    args: Dict[str, Any],
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    """Autoriza una hora heredada sólo para continuar un slot exacto verificado.

    El usuario no tiene que repetir la hora después de que el calendario ya la
    ofreció. Aun así, la memoria por sí sola nunca alcanza: deben coincidir el
    AvailabilityContext, ContextAuthorization, el create_booking verificado y
    el BookingObjective listo que va a consumir Policy.
    """
    args = args or {}
    perception = perception or {}
    world = world or {}

    requested_hour = normalizar_hora_detectada(args.get("hora"))
    requested_day = str(args.get("dia") or args.get("dia_resuelto") or "").strip()
    if not hora_es_valida(requested_hour) or not requested_day:
        return False

    availability = (
        world.get("availability_context")
        if isinstance(world.get("availability_context"), dict)
        else {}
    )
    if str(availability.get("kind") or "") != "exact_slot_offer":
        return False
    offered_hour = normalizar_hora_detectada(availability.get("hora"))
    offered_day = str(
        availability.get("dia_resuelto") or availability.get("dia") or ""
    ).strip()
    if offered_hour != requested_hour or not offered_day:
        return False
    if not _misma_fecha_reserva({"fecha": offered_day}, requested_day):
        return False

    contract = (
        perception.get("execution_contract")
        if isinstance(perception.get("execution_contract"), dict)
        else {}
    )
    if contract.get("authoritative") is not True:
        return False

    contract_booking_acts = [
        item
        for item in (contract.get("acts") or [])
        if isinstance(item, dict)
        and str(item.get("operation") or "") == "create_booking"
    ]
    if len(contract_booking_acts) != 1:
        return False

    authorization = (
        contract.get("authorized_context")
        if isinstance(contract.get("authorized_context"), dict)
        else {}
    )
    if not authorization:
        authorization = (
            world.get("authorized_context")
            if isinstance(world.get("authorized_context"), dict)
            else {}
        )
    if authorization.get("authorized") is not True:
        return False
    if str(authorization.get("relation") or "") not in {
        "references_previous",
        "answers_pending",
    }:
        return False

    allowed_fields = {
        str(value or "").strip()
        for value in (authorization.get("allowed_fields") or [])
    }
    if not allowed_fields.intersection({"temporal.start", "hora", "confirmar_slot"}):
        return False
    allowed_sources = {
        str(value or "").strip()
        for value in (
            authorization.get("allowed_sources")
            or authorization.get("sources")
            or []
        )
    }
    if not allowed_sources.intersection(
        {"previous_user_turn", "pending_option", "verified_availability_context"}
    ):
        return False

    reference_id = str(authorization.get("reference_id") or "").strip()
    question_id = str(authorization.get("question_id") or "").strip()
    if not reference_id and not question_id:
        return False

    act = _agent_v2_v126r9_verified_create_booking_act(perception)
    if not act:
        return False
    if str(contract_booking_acts[0].get("act_id") or "").strip() != str(
        act.get("act_id") or ""
    ).strip():
        return False
    act_temporal = act.get("temporal") if isinstance(act.get("temporal"), dict) else {}
    act_hour = normalizar_hora_detectada(act_temporal.get("start"))
    act_day = str(act_temporal.get("day") or act_temporal.get("date") or "").strip()
    if act_hour != requested_hour or not act_day:
        return False
    if not _misma_fecha_reserva({"fecha": act_day}, requested_day):
        return False

    objective = (
        perception.get("booking_objective")
        if isinstance(perception.get("booking_objective"), dict)
        else {}
    )
    if str(objective.get("operation") or "") != "create_booking":
        return False
    if [value for value in (objective.get("missing_fields") or []) if value]:
        return False
    objective_temporal = (
        objective.get("temporal")
        if isinstance(objective.get("temporal"), dict)
        else {}
    )
    objective_hour = normalizar_hora_detectada(objective_temporal.get("start"))
    objective_day = str(
        objective_temporal.get("day") or objective_temporal.get("date") or ""
    ).strip()
    if objective_hour != requested_hour or not objective_day:
        return False
    if not _misma_fecha_reserva({"fecha": objective_day}, requested_day):
        return False

    target = act.get("target") if isinstance(act.get("target"), dict) else {}
    raw_requested_types = (
        args.get("resource_types")
        or args.get("resource_type")
        or target.get("resource_types")
        or target.get("resource_type")
    )
    requested_types = _canonical_configured_court_types(raw_requested_types)
    if raw_requested_types and not requested_types:
        return False
    offered_courts = [
        str(value or "").strip()
        for value in (availability.get("canchas") or [])
        if str(value or "").strip()
    ]
    if requested_types and not any(
        _court_matches_resource_types(court, requested_types)
        for court in offered_courts
    ):
        return False

    print(
        "   🔐 [AgentV2 V141 VERIFIED EXACT-SLOT FOLLOWUP] "
        f"dia={requested_day} hora={requested_hour} "
        f"act_id={act.get('act_id')}"
    )
    return True


_agent_v2_booking_hour_has_user_grounding_v141_base = (
    _agent_v2_booking_hour_has_user_grounding
)


def _agent_v2_booking_hour_has_user_grounding(
    args: Dict[str, Any],
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    if _agent_v2_booking_hour_has_user_grounding_v141_base(
        args or {}, perception or {}, world or {}
    ):
        return True
    return _agent_v2_v141_verified_exact_slot_followup_hour(
        args or {}, perception or {}, world or {}
    )


AGENT_V2_UNIFIED_AGENTIC_CORE = "v141"
AGENT_V2_UNIFIED_CONVERSATION_KERNEL = "v141"
AGENT_V2_EXACT_SLOT_CONFIRM_BUILD = "2026-09-28_verified_exact_slot_followup_v141"


async def _agent_v2_v138_arbitrate_booking_operation(
    mensaje: str,
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Decide únicamente READ de disponibilidad vs compromiso transaccional.

    No selecciona tools concretas, no consulta calendario, no decide precio,
    no crea reservas y no completa slots faltantes.
    """
    frame = dict(_agent_v2_semantic_frame(perception or {}) or {})
    acts = [
        dict(act)
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
    ]
    operations = [
        str(act.get("operation") or "").strip()
        for act in acts
        if str(act.get("operation") or "").strip()
        and str(act.get("operation") or "").strip() != "greet"
    ]

    # V138 sólo arbitra el borde exacto que V133 podía reescribir.
    if set(operations) != {"query_availability"}:
        return {
            "status": "not_applicable",
            "mode": "preserve_semantic_frame",
            "confidence": 1.0,
        }

    try:
        response = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Sos CURRENT-TURN OPERATION ARBITER para un agente de reservas. "
                        "Tu única tarea es decidir qué significa el FRAGMENTO ACTUAL "
                        "respecto de disponibilidad/reserva.\n\n"

                        "Elegí exactamente uno:\n"
                        "1. availability_read: el usuario pregunta si hay lugar, qué "
                        "horarios hay, si está libre, disponibilidad, etc. Quiere "
                        "conocer un hecho antes de comprometer una reserva.\n"
                        "2. booking_commitment: el usuario expresa que quiere reservar, "
                        "alquilar, tomar, dejar señado o concretar un turno. Puede faltar "
                        "día/deporte/hora; eso no cambia que quiera ejecutar una reserva.\n"
                        "3. mixed_read_then_booking: el mismo fragmento contiene una "
                        "consulta de disponibilidad Y un compromiso explícito de reservar "
                        "si el slot sirve. En ese caso el flujo transaccional puede "
                        "mantener create_booking porque su preflight consulta calendario.\n"
                        "4. unclear: no hay evidencia suficiente.\n\n"

                        "REGLAS CRÍTICAS:\n"
                        "- Una pregunta como 'tenes cancha mañana a las 20?' es "
                        "availability_read aunque probablemente el usuario reserve luego.\n"
                        "- No conviertas una pregunta de disponibilidad en booking sólo "
                        "porque contiene día/hora/cancha.\n"
                        "- Una frase como 'quiero alquilar una hora mañana a las 18' "
                        "sí expresa booking_commitment aunque termine preguntando si hay.\n"
                        "- El router_hint es una pista NO autoritativa. El texto actual y "
                        "su intención pragmática mandan.\n"
                        "- evidence debe ser una cita LITERAL y breve del current fragment.\n"
                        "- No decidas tool names.\n\n"

                        "Respondé SOLO JSON:\n"
                        "{"
                        "\"mode\":\"availability_read|booking_commitment|mixed_read_then_booking|unclear\","
                        "\"confidence\":0.0,"
                        "\"evidence\":\"fragmento literal\","
                        "\"reason\":\"breve\""
                        "}"
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "current_fragment": str(mensaje or ""),
                            "semantic_frame": {
                                "intent": dict(frame.get("intent") or {}),
                                "acts": acts,
                                "commitment": dict(frame.get("commitment") or {})
                                if isinstance(frame.get("commitment"), dict)
                                else frame.get("commitment"),
                                "turn_type": frame.get("turn_type"),
                            },
                            "router_hint": _agent_v2_v128_router_subintent(),
                            "active_booking_objective": (
                                _agent_v2_v103_active_objective_from_world(world or {})
                                or None
                            ),
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                },
            ],
            temperature=0.0,
            max_tokens=220,
            response_format={"type": "json_object"},
        )
        register_cost(response)
        data = _loads_llm_json_object(
            response.choices[0].message.content.strip()
        )
    except Exception as exc:
        print(
            "   ⚠️ [AgentV2 V138 OPERATION ARBITER] "
            f"falló={type(exc).__name__}: {exc}; preservo SemanticFrame original"
        )
        return {
            "status": "unresolved",
            "mode": "preserve_semantic_frame",
            "confidence": 0.0,
            "reason": "arbiter_error",
        }

    mode = str(data.get("mode") or "").strip()
    try:
        confidence = float(data.get("confidence") or 0.0)
    except (TypeError, ValueError):
        confidence = 0.0
    evidence = str(data.get("evidence") or "").strip()

    allowed = {
        "availability_read",
        "booking_commitment",
        "mixed_read_then_booking",
        "unclear",
    }
    if mode not in allowed:
        mode = "unclear"

    # Fail closed: una decisión que cambia el tipo de operación necesita
    # evidencia literal del mensaje actual.
    evidence_ok = bool(
        evidence
        and _agent_v2_v126_literal_evidence(
            str(mensaje or ""),
            evidence,
        )
    )

    if confidence < 0.85 or not evidence_ok:
        print(
            "   🧭 [AgentV2 V138 OPERATION ARBITER] "
            f"mode={mode} confidence={confidence:.2f} evidence_ok={evidence_ok} "
            "→ preservo SemanticFrame original"
        )
        return {
            "status": "unresolved",
            "mode": "preserve_semantic_frame",
            "confidence": confidence,
            "evidence": evidence,
            "reason": str(data.get("reason") or ""),
        }

    decision = {
        "status": "verified",
        "mode": mode,
        "confidence": confidence,
        "evidence": evidence,
        "reason": str(data.get("reason") or ""),
    }
    print(
        "   🧭 [AgentV2 V138 OPERATION ARBITER] "
        f"mode={mode} confidence={confidence:.2f} evidence={evidence!r}"
    )
    return decision


_agent_v2_v133_promote_partial_booking_intent_v138_base = (
    _agent_v2_v133_promote_partial_booking_intent
)


async def _agent_v2_v133_promote_partial_booking_intent(
    perception: Dict[str, Any],
    mensaje: str,
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """
    V138 convierte V133 de una prioridad procedural a una promoción semánticamente
    autorizada.

    Si Perception ya dijo query_availability:
      - availability_read -> NO promover a create_booking.
      - booking_commitment / mixed -> V133 puede promover.
      - unclear/error -> conservar significado original (fail closed).
    """
    clean = dict(perception or {})
    frame = dict(_agent_v2_semantic_frame(clean) or {})
    operations = {
        str(act.get("operation") or "").strip()
        for act in (frame.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "").strip() not in {"", "greet"}
    }

    if operations != {"query_availability"}:
        return await _agent_v2_v133_promote_partial_booking_intent_v138_base(
            clean,
            mensaje,
            world or {},
        )

    decision = await _agent_v2_v138_arbitrate_booking_operation(
        mensaje,
        clean,
        world or {},
    )
    clean["_v138_operation_authority"] = dict(decision)

    mode = str(decision.get("mode") or "")
    if (
        decision.get("status") == "verified"
        and mode == "availability_read"
    ):
        # Éste es el caso live. No creamos BookingObjective ni collection contract.
        # El query_availability original continúa hasta Tool-First READ / calendario.
        clean.pop("booking_collection_contract", None)
        clean.pop("_v104_booking_collection_authority", None)
        clean.pop("_v103_booking_engaged", None)

        contract = dict(clean.get("execution_contract") or {})
        if contract:
            contract_acts = [
                dict(act)
                for act in (contract.get("acts") or [])
                if isinstance(act, dict)
            ]
            if any(
                str(act.get("operation") or "") == "query_availability"
                for act in contract_acts
            ):
                clean["execution_contract"] = contract

        print(
            "   ✅ [AgentV2 V138 READ PRESERVED] "
            "query_availability mantiene autoridad; V133 promotion omitida"
        )
        return clean

    if (
        decision.get("status") == "verified"
        and mode in {"booking_commitment", "mixed_read_then_booking"}
    ):
        promoted = await _agent_v2_v133_promote_partial_booking_intent_v138_base(
            clean,
            mensaje,
            world or {},
        )
        promoted = dict(promoted or {})
        promoted["_v138_operation_authority"] = dict(decision)
        print(
            "   ✅ [AgentV2 V138 WRITE PROMOTION] "
            f"mode={mode} → V133 autorizado semánticamente"
        )
        return promoted

    # Incertidumbre: jamás convertimos un READ demostrado a WRITE por prioridad
    # de router. El significado ya producido por Perception se conserva.
    print(
        "   🛡️ [AgentV2 V138 FAIL-CLOSED] "
        "sin autoridad semántica suficiente → preservo query_availability"
    )
    return clean


# ---------------------------------------------------------------------------
# Invariante de Planner:
# Si V138 congeló availability_read, ninguna capa posterior puede volver a
# insertar un contrato de recolección de BookingObjective para ese mismo fragmento.
# No elegimos una tool aquí: únicamente protegemos el significado congelado.
# ---------------------------------------------------------------------------
_planificar_agent_v2_v138_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    authority = dict((perception or {}).get("_v138_operation_authority") or {})
    mode = str(authority.get("mode") or "")
    verified_read = bool(
        authority.get("status") == "verified"
        and mode == "availability_read"
    )

    planning_perception = perception
    if verified_read:
        planning_perception = dict(perception or {})
        planning_perception.pop("booking_collection_contract", None)
        planning_perception.pop("_v104_booking_collection_authority", None)
        planning_perception.pop("_v103_booking_engaged", None)

    plan = await _planificar_agent_v2_v138_base(
        world,
        planning_perception,
        goals,
        observations,
        offline_mode,
        learning_policy,
    )

    if not verified_read:
        return plan

    # Observabilidad únicamente: la selección concreta sigue viniendo del
    # Planner normal basado en ExecutionContract.
    tools = [
        str(step.get("tool") or "")
        for step in ((plan or {}).get("steps") or [])
        if isinstance(step, dict)
    ]
    print(
        "   🧠 [AgentV2 V138 AI-CHOSEN FLOW] "
        f"semantic_mode=availability_read planner_tools={tools}"
    )
    return plan


