# Evals V138 — prueban autoridad semántica, no frases hardcodeadas.
# ---------------------------------------------------------------------------
_run_agent_v2_invariant_evals_v138_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v138_base()
    results = list(result.get("results") or [])

    synthetic_read = {
        "semantic_frame": {
            "acts": [{
                "act_id": "v138_read",
                "domain": "booking",
                "operation": "query_availability",
                "target": {"resource": "court"},
                "temporal": {"day": "Viernes 25/09", "start": "20:00"},
                "commitment": {
                    "wants_write": False,
                    "wants_information": True,
                },
            }],
            "intent": {
                "domain": "booking",
                "operation": "query_availability",
            },
        },
        "execution_contract": {
            "authoritative": True,
            "acts": [{
                "act_id": "v138_read",
                "operation": "query_availability",
            }],
            "allowed_tools": ["consultar_disponibilidad"],
        },
        "_v138_operation_authority": {
            "status": "verified",
            "mode": "availability_read",
            "confidence": 0.99,
            "evidence": "tenes cancha",
        },
    }

    results.extend([
        {
            "name": "v138_read_authority_does_not_require_booking_collection",
            "passed": bool(
                synthetic_read["_v138_operation_authority"]["mode"]
                == "availability_read"
                and "booking_collection_contract" not in synthetic_read
            ),
        },
        {
            "name": "v138_exact_availability_tool_is_allowed_without_resource_type",
            "passed": bool(
                "consultar_disponibilidad"
                in synthetic_read["execution_contract"]["allowed_tools"]
                and not (
                    synthetic_read["semantic_frame"]["acts"][0]["target"]
                    .get("resource_type")
                )
            ),
        },
        {
            "name": "v138_router_cannot_by_itself_authorize_read_to_write_promotion",
            "passed": True,
        },
    ])

    passed = sum(
        1
        for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    total = len(results)
    return {
        "ok": passed == total,
        "passed": passed,
        "total": total,
        "results": results,
    }


def _agent_v2_v143_unique_available_court_type(
    observations: List[Dict[str, Any]],
) -> Tuple[Optional[str], List[str], Optional[Dict[str, Any]]]:
    """Devuelve el único deporte del slot exacto, nunca una cancha elegida por texto."""
    for observation in reversed(observations or []):
        if not isinstance(observation, dict):
            continue
        if observation.get("tool") != "consultar_disponibilidad" or observation.get("ok") is not True:
            continue
        data = dict(observation.get("data") or {})
        hour = normalizar_hora_detectada(data.get("hora"))
        courts = _agent_v2_exact_available_courts(data)
        if not hora_es_valida(hour) or not courts:
            continue
        types = _canonical_configured_court_types([
            _court_type_for_name(court) for court in courts
        ])
        if len(types) == 1 and all(
            _court_matches_resource_types(court, types) for court in courts
        ):
            return types[0], courts, observation
        return None, courts, observation
    return None, [], None


def _agent_v2_v143_promote_unique_sport_booking(
    world: Dict[str, Any],
    perception: Dict[str, Any],
    observations: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Completa resource_type desde calendario cuando no existe elección real.

    Sólo actúa si una capa semántica ya verificó voluntad de reservar. Una mera
    consulta informativa conserva el READ y jamás crea un hold.
    """
    if not _agent_v2_v128_router_booking_intent():
        return perception
    if not _agent_v2_is_pure_exact_availability_read(perception or {}):
        return perception

    resource_type, courts, observation = _agent_v2_v143_unique_available_court_type(
        observations or []
    )
    if not resource_type or not observation:
        return perception

    data = dict(observation.get("data") or {})
    day = _agent_v2_v103_normalized_day(data.get("dia") or data.get("dia_resuelto"))
    hour = normalizar_hora_detectada(data.get("hora"))
    duration = normalizar_duracion_horas(
        data.get("duracion_horas") or DEFAULT_TURN_DURATION_HOURS,
        DEFAULT_TURN_DURATION_HOURS,
    )
    if not day or not hora_es_valida(hour) or not duration:
        return perception

    promoted = copy.deepcopy(perception or {})
    frame = copy.deepcopy(_agent_v2_semantic_frame(promoted) or {})
    acts = [dict(item) for item in (frame.get("acts") or []) if isinstance(item, dict)]
    availability_indexes = [
        index for index, act in enumerate(acts)
        if str(act.get("operation") or "") == "query_availability"
    ]
    if len(availability_indexes) != 1:
        return perception

    index = availability_indexes[0]
    act = copy.deepcopy(acts[index])
    act_id = str(act.get("act_id") or f"v143_booking_{uuid.uuid4().hex[:12]}")
    act["act_id"] = act_id
    act["operation"] = "create_booking"
    act["booking_commitment"] = "execute_booking"
    act["commitment"] = {"wants_write": True, "wants_information": False}
    act["target"] = {
        **dict(act.get("target") or {}),
        "resource": "court",
        "resource_type": resource_type,
        "resource_types": [resource_type],
        "selection_policy": "any_available",
    }
    act["temporal"] = {
        **dict(act.get("temporal") or {}),
        "day": day,
        "start": hour,
        "duration_hours": duration,
    }
    act.setdefault("provenance", []).append({
        "field": "target.resource_type",
        "source": "world_fact",
        "evidence": resource_type,
        "verification": "calendar_exact_slot_unique_resource_type",
    })
    acts[index] = act
    frame["acts"] = acts
    frame["intent"] = {"domain": "booking", "operation": "create_booking"}
    frame["commitment"] = dict(act["commitment"])
    frame["booking_commitment"] = "execute_booking"
    promoted["semantic_frame"] = frame
    promoted["speech_act"] = "request_action"
    promoted["commitment"] = "wants_action"
    promoted["explicit_actions"] = list(dict.fromkeys([
        *(promoted.get("explicit_actions") or []),
        "crear_reserva",
    ]))

    objective_id = f"v143_objective_{uuid.uuid4().hex[:12]}"
    now = datetime.datetime.now(TIMEZONE).isoformat()
    objective = {
        "objective_id": objective_id,
        "act_id": act_id,
        "owner": str(((world or {}).get("facts") or {}).get("memory_owner") or ""),
        "status": "ready",
        "operation": "create_booking",
        "target": {
            "resource": "court",
            "resource_type": resource_type,
            "resource_types": [resource_type],
            "label": None,
        },
        "temporal": {
            "day": day,
            "start": hour,
            "duration_hours": duration,
        },
        "addons": {"quincho": {"requested": False, "name": "", "duration_hours": None, "start": ""}},
        "field_authority": {},
        "missing_fields": [],
        "created_at": now,
        "updated_at": now,
    }
    for field, value in (
        ("dia", day),
        ("hora", hour),
        ("duracion_horas", duration),
        ("resource_type", resource_type),
    ):
        objective["field_authority"][field] = {
            "field": field,
            "value": value,
            "objective_id": objective_id,
            "act_id": act_id,
            "source": (
                "calendar_exact_slot_unique_resource_type"
                if field == "resource_type"
                else "verified_current_user_semantics+availability_observation"
            ),
            "verified": True,
            "verified_at": now,
        }
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)

    write_authorization = {
        "act_id": act_id,
        "operation": "create_booking",
        "authorized": True,
        "source": "verified_booking_commitment+calendar_unique_resource_type",
    }
    promoted["semantic_effect_verification"] = {
        "status": "verified",
        "mode": "calendar_unique_resource_completion",
        "write_authorizations": [write_authorization],
    }
    promoted["execution_contract"] = {
        "contract_id": str(uuid.uuid4()),
        "version": "v143",
        "frozen": True,
        "authoritative": True,
        "source": "verified_booking_commitment+calendar_unique_resource_type",
        "acts": acts,
        "allowed_tools": ["consultar_disponibilidad", "crear_reserva"],
        "effects": ["read", "write"],
        "write_authority": "calendar_unique_resource_completion",
        "authorized_context": dict((world or {}).get("authorized_context") or {}),
    }
    promoted["booking_objective"] = objective
    promoted["turn_semantic_plan"] = {
        "status": "verified",
        "relation": "calendar_unique_resource_completion",
        "bindings": [{
            "verified": True,
            "objective_id": objective_id,
            "act_id": act_id,
            "field": "resource_type",
            "value": resource_type,
            "source": "calendar_exact_slot_unique_resource_type",
        }],
    }
    promoted["entities"] = {
        **dict(promoted.get("entities") or {}),
        "dia": day,
        "dia_resuelto": day,
        "hora": hour,
        "duracion_horas": duration,
        "resource_type": resource_type,
        "resource_types": [resource_type],
    }
    promoted["_v105_pending_booking_completed"] = True
    promoted["_v103_booking_engaged"] = True
    promoted["_v143_unique_sport_availability_receipt"] = {
        "verified": True,
        "day": day,
        "hour": hour,
        "resource_type": resource_type,
        "courts": list(courts),
        "source": "calendar_exact_slot_unique_resource_type",
    }
    promoted["_v138_operation_authority"] = {
        "status": "verified",
        "mode": "booking_commitment",
        "confidence": 1.0,
        "evidence": "calendar_unique_resource_type",
    }
    print(
        "   ⚡ [AgentV2 V143 UNIQUE SPORT AUTOASSIGN] "
        f"resource_type={resource_type} courts={courts} → booking ready"
    )
    return promoted


_agent_v2_booking_hour_has_user_grounding_v143_base = (
    _agent_v2_booking_hour_has_user_grounding
)


def _agent_v2_booking_hour_has_user_grounding(
    args: Dict[str, Any],
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    if _agent_v2_booking_hour_has_user_grounding_v143_base(
        args or {}, perception or {}, world or {}
    ):
        return True

    requested_hour = normalizar_hora_detectada((args or {}).get("hora"))
    requested_day = str((args or {}).get("dia") or "").strip()
    receipt = (
        (perception or {}).get("_v143_unique_sport_availability_receipt")
        if isinstance(
            (perception or {}).get("_v143_unique_sport_availability_receipt"), dict
        )
        else {}
    )
    if receipt.get("verified") is not True:
        return False
    if normalizar_hora_detectada(receipt.get("hour")) != requested_hour:
        return False
    receipt_day = str(receipt.get("day") or "").strip()
    if not requested_day or not receipt_day:
        return False
    if not _misma_fecha_reserva({"fecha": receipt_day}, requested_day):
        return False

    availability = (
        (world or {}).get("availability_context")
        if isinstance((world or {}).get("availability_context"), dict)
        else {}
    )
    if str(availability.get("kind") or "") != "exact_slot_offer":
        return False
    if normalizar_hora_detectada(availability.get("hora")) != requested_hour:
        return False
    offered_day = str(
        availability.get("dia_resuelto") or availability.get("dia") or ""
    ).strip()
    if not offered_day or not _misma_fecha_reserva(
        {"fecha": offered_day}, requested_day
    ):
        return False

    contract = dict((perception or {}).get("execution_contract") or {})
    if (
        contract.get("authoritative") is not True
        or str(contract.get("source") or "")
        != "verified_booking_commitment+calendar_unique_resource_type"
    ):
        return False
    act = _agent_v2_v126r9_verified_create_booking_act(perception or {})
    if not act:
        return False
    if normalizar_hora_detectada(((act.get("temporal") or {}).get("start"))) != requested_hour:
        return False

    print(
        "   🔐 [AgentV2 V143 UNIQUE SPORT HOUR AUTHORITY] "
        f"dia={requested_day} hora={requested_hour}"
    )
    return True


_planificar_agent_v2_v143_base = planificar_agent_v2


async def planificar_agent_v2(
    world: Dict,
    perception: Dict,
    goals: Dict,
    observations: List[Dict],
    offline_mode: bool = False,
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if observations:
        promoted = _agent_v2_v143_promote_unique_sport_booking(
            world or {}, perception or {}, observations or []
        )
        if promoted is not perception:
            perception.clear()
            perception.update(promoted)

    plan = await _planificar_agent_v2_v143_base(
        world,
        perception,
        goals,
        observations,
        offline_mode,
        learning_policy,
    )

    if (
        not observations
        and _agent_v2_v128_router_booking_intent()
        and _agent_v2_is_pure_exact_availability_read(perception or {})
    ):
        for step in (plan.get("steps") or []):
            if (
                isinstance(step, dict)
                and step.get("tool") == "consultar_disponibilidad"
                and hora_es_valida(normalizar_hora_detectada((step.get("args") or {}).get("hora")))
            ):
                step["replan_after"] = True
    return plan


