# ============================================================================
# V169 — VERIFIED PENDING-SLOT COMMITMENT AUTHORITY
# ============================================================================
# Regresión observada 2026-10-01 (build v168):
#   exact availability -> pending confirmar_slot -> usuario confirma ->
#   create_booking queda semanticamente verificado -> preflight OK -> Policy
#   rechaza crear_reserva con sin_voluntad_explicita_de_reservar.
#
# Principios:
#   - NO interpreta lenguaje con regex/keywords.
#   - NO autoriza una operación nueva.
#   - Sólo reusa una autorización WRITE ya verificada por Semantic Effect
#     Verifier y una resolución stateful de PendingInteraction=confirm.
#   - El validator base corre PRIMERO. Sólo se corrige exactamente el rechazo
#     sin_voluntad_explicita_de_reservar; cualquier otro guard sigue fail-closed.
#   - internal_recovery_write sigue siendo recuperación interna y NO handoff.
# ============================================================================


def _agent_v2_v169_verified_pending_slot_commitment(
    perception: Dict[str, Any],
) -> bool:
    """Prueba estructural de que el turno actual confirmó un pending de reserva.

    Esta función no decide intención desde texto. Consume exclusivamente
    decisiones ya verificadas por las capas semánticas/contextuales del agente.
    """
    perception = perception or {}

    resolution = (
        perception.get("context_resolution")
        if isinstance(perception.get("context_resolution"), dict)
        else {}
    )
    if resolution.get("resolved") is not True:
        return False
    if str(resolution.get("type") or "") != "answers_pending":
        return False
    if str(resolution.get("resolution") or "") not in {
        "confirm",
        "accept",
        "select",
    }:
        return False
    if not str(
        resolution.get("question_id")
        or resolution.get("interaction_id")
        or ""
    ).strip():
        return False

    contract = (
        perception.get("execution_contract")
        if isinstance(perception.get("execution_contract"), dict)
        else {}
    )
    if contract.get("authoritative") is not True:
        return False

    create_acts = [
        dict(act)
        for act in (contract.get("acts") or [])
        if isinstance(act, dict)
        and str(act.get("operation") or "") == "create_booking"
    ]
    if len(create_acts) != 1:
        # Algunas capas conservan el frame autoritativo fuera del contrato.
        frame = _agent_v2_semantic_frame(perception)
        create_acts = [
            dict(act)
            for act in (frame.get("acts") or [])
            if isinstance(act, dict)
            and str(act.get("operation") or "") == "create_booking"
        ]
    if len(create_acts) != 1:
        return False

    act_id = str(create_acts[0].get("act_id") or "").strip()
    if not act_id:
        return False

    verification = (
        perception.get("semantic_effect_verification")
        if isinstance(perception.get("semantic_effect_verification"), dict)
        else {}
    )
    if str(verification.get("status") or "") != "verified":
        return False

    verified_write = False
    for item in (verification.get("write_authorizations") or []):
        if not isinstance(item, dict) or item.get("authorized") is not True:
            continue
        item_act_id = str(item.get("act_id") or "").strip()
        item_operation = str(item.get("operation") or "").strip()
        if item_act_id == act_id and item_operation in {"", "create_booking"}:
            verified_write = True
            break
    if not verified_write:
        return False

    # Si existe BookingObjective, debe ser el mismo write y estar listo.
    objective = (
        perception.get("booking_objective")
        if isinstance(perception.get("booking_objective"), dict)
        else {}
    )
    if objective:
        operation = str(objective.get("operation") or "")
        if operation and operation != "create_booking":
            return False
        missing = [
            str(value or "").strip()
            for value in (objective.get("missing_fields") or [])
            if str(value or "").strip()
        ]
        if missing:
            return False

    return True


_validar_tool_agent_v2_v169_base = validar_tool_agent_v2


def validar_tool_agent_v2(
    tool: str,
    args: Dict,
    world: Dict,
    perception: Dict,
    goals: Dict,
    image_path: str = "",
) -> Dict[str, Any]:
    """V169: continuidad monotónica de un create_booking ya confirmado."""
    result = _validar_tool_agent_v2_v169_base(
        tool,
        args,
        world,
        perception,
        goals,
        image_path,
    )

    if (
        str(tool or "") != "crear_reserva"
        or not isinstance(result, dict)
        or result.get("ok") is not False
        or str(result.get("reason") or "")
        != "sin_voluntad_explicita_de_reservar"
    ):
        return result

    if not _agent_v2_v169_verified_pending_slot_commitment(perception or {}):
        return result

    print(
        "   🔐 [AgentV2 V169 PENDING SLOT WRITE AUTHORITY] "
        "confirmación stateful + write semántico verificado → crear_reserva autorizada"
    )
    return {
        "ok": True,
        "args": args,
        "reason": "v169_verified_pending_slot_commitment",
    }


# V140/V168 regression guard: un estado que V100 clasificó como recovery interno
# no debe convertirse después en HANDOFF. Los handoffs de negocio explícitos y
# los requires_human_review reales siguen pasando por la implementación base.
_agent_v2_v140_internal_failure_signal_v169_base = (
    _agent_v2_v140_internal_failure_signal
)


def _agent_v2_v140_internal_failure_signal(
    response: str = "",
    observations: Optional[List[Dict[str, Any]]] = None,
    assessment: Optional[Dict[str, Any]] = None,
) -> str:
    assessment = assessment or {}
    state = str(assessment.get("state") or "").strip()
    reason_code = str(assessment.get("reason_code") or "").strip()

    if state in {
        "internal_recovery_write",
        "internal_recovery_question",
        "internal_recovery_read",
    }:
        print(
            "   🛡️ [AgentV2 V169 NO FALSE HANDOFF] "
            f"state={state} preservado como recovery interno"
        )
        return ""

    if (
        reason_code == "internal_representation_failure"
        and state.startswith("internal_recovery_")
    ):
        return ""

    return _agent_v2_v140_internal_failure_signal_v169_base(
        response,
        observations,
        assessment,
    )


