# ============================================================================
# V171 — EXACT SLOT UX + VERIFIED CONFIRMATION AUTOASSIGN
# ============================================================================
# Incidente live 2026-10-01 (build V170):
#   1) Una lectura exacta de un único resource_type mostraba cada cancha física
#      aunque la selección concreta debe ser automática al reservar.
#   2) Al responder al pending `confirmar_slot`, el Effect Verifier autorizaba
#      create_booking y el BookingObjective estaba READY, pero el preflight
#      devolvía needs_user_input(missing=['cancha']) porque V136 sólo aceptaba
#      bindings de dia/hora/duracion/resource_type/cancha y no `confirmar_slot`.
#
# Invariantes V171:
#   - Una lectura exacta con UN único tipo pedido renderiza el tipo, no las
#     canchas equivalentes. No altera la Observation ni oculta indisponibilidad.
#   - Una confirmación stateful de `confirmar_slot` ya verificada como
#     create_booking puede autoasignar una cancha sólo si el objetivo está READY,
#     no hay cancha específica pedida y TODAS las candidatas pertenecen al único
#     resource_type solicitado.
#   - No hay regex ni keywords para interpretar intención.
# ============================================================================

_build_agent_v2_exact_slot_confirmation_message_v171_base = (
    build_agent_v2_exact_slot_confirmation_message
)


def build_agent_v2_exact_slot_confirmation_message(
    observation: Dict[str, Any],
) -> str:
    """Renderer compacto para exact availability de un único tipo de cancha.

    La cancha física sigue almacenada en `canchas_libres` para que el booking
    posterior pueda autoasignarla; simplemente no obligamos al cliente a elegir
    entre recursos equivalentes cuando no lo pidió.
    """
    data = (observation or {}).get("data") or {}
    day = str(data.get("dia") or "").strip()
    hour = normalizar_hora_detectada(data.get("hora"))
    courts = _agent_v2_exact_available_courts(data)

    resource_types = _canonical_configured_court_types(
        data.get("resource_types") or data.get("resource_type")
    )
    if not resource_types and courts:
        inferred = []
        for court in courts:
            court_type = _court_type_for_name(str(court or "").strip())
            if court_type and court_type not in inferred:
                inferred.append(court_type)
        resource_types = inferred

    # Sólo compactamos cuando el hecho observado es exacto y el alcance de
    # recurso es inequívoco. Para múltiples tipos conservamos el renderer base.
    if (
        not day
        or not hora_es_valida(hour)
        or not courts
        or len(resource_types) != 1
    ):
        return _build_agent_v2_exact_slot_confirmation_message_v171_base(
            observation
        )

    resource_type = resource_types[0]
    lines = [
        f"✅ Sí, para el {day} a las {hour} tenemos disponibilidad en {resource_type}:",
        "",
    ]

    if REQUIRES_DEPOSIT:
        lines.append(
            "Si querés dejarlo firme, confirmame y te envío el resumen del turno, "
            "el alias y el pedido del comprobante para señarlo."
        )
    else:
        lines.append(
            "Si querés dejarlo firme, confirmame y te envío el resumen del turno."
        )

    address = str(BUSINESS_ADDRESS or "").strip()
    if address:
        lines.extend([
            "",
            f"💵 Si tenés efectivo, podés acercarte a {address} para hacer la reserva.",
        ])

    return "\n".join(lines).strip()


_agent_v2_v126r2_can_auto_assign_equivalent_court_v171_base = (
    _agent_v2_v126r2_can_auto_assign_equivalent_court
)


def _agent_v2_v171_verified_confirm_slot_autoassign_authority(
    perception: Dict[str, Any],
    available_courts: List[str],
) -> bool:
    """Autoridad estructural para autoasignar tras confirmar un exact slot.

    No interpreta el texto actual. Requiere que capas anteriores ya hayan:
      * enlazado el turno al pending `confirmar_slot`;
      * verificado y autorizado exactamente un create_booking;
      * mantenido un BookingObjective READY del mismo flujo.
    """
    perception = perception or {}
    if str(perception.get("answers_pending_field") or "").strip() != "confirmar_slot":
        return False
    if not _agent_v2_v126_authorized_create_booking(perception):
        return False

    contract = (
        perception.get("execution_contract")
        if isinstance(perception.get("execution_contract"), dict)
        else {}
    )
    if contract and contract.get("authoritative") is not True:
        return False
    if contract.get("requires_clarification") is True:
        return False

    objective = (
        dict(perception.get("booking_objective") or {})
        if isinstance(perception.get("booking_objective"), dict)
        else {}
    )
    objective_id = str(objective.get("objective_id") or "").strip()
    if (
        not objective_id
        or str(objective.get("operation") or "") != "create_booking"
        or _agent_v2_v103_compute_missing(objective)
    ):
        return False

    frame = _agent_v2_semantic_frame(perception) or {}
    relation = _agent_v2_semantic_context_relation(frame) or {}
    commitment = _agent_v2_semantic_commitment(frame) or {}
    if str(relation.get("type") or "") != "answers_pending":
        return False
    if relation.get("answers_pending_question") is not True:
        return False
    if commitment.get("wants_write") is not True or commitment.get("wants_information") is True:
        return False

    target = dict(objective.get("target") or {})
    # Una cancha explícita nunca se reemplaza por autoasignación.
    if str(target.get("label") or "").strip():
        return False

    resource_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if len(resource_types) != 1:
        return False

    courts = [
        str(value or "").strip()
        for value in (available_courts or [])
        if str(value or "").strip()
    ]
    if not courts:
        return False
    if not all(
        _court_matches_resource_types(court, resource_types)
        for court in courts
    ):
        return False

    print(
        "   ✅ [AgentV2 V171 CONFIRMED SLOT AUTOASSIGN] "
        f"objective={objective_id} field=confirmar_slot "
        f"resource_type={resource_types[0]} courts={courts}"
    )
    return True


def _agent_v2_v126r2_can_auto_assign_equivalent_court(
    perception: Dict[str, Any],
    available_courts: List[str],
) -> bool:
    if _agent_v2_v126r2_can_auto_assign_equivalent_court_v171_base(
        perception or {}, available_courts or []
    ):
        return True
    return _agent_v2_v171_verified_confirm_slot_autoassign_authority(
        perception or {}, available_courts or []
    )


# ============================================================================
# V172 — CONSUMED PENDING EXECUTION AUTHORITY
# ============================================================================
# Regresión live observada en V171:
#   confirmar_slot -> create_booking verificado -> preflight -> autoassign OK ->
#   pending consumido -> World refresh -> ContextAuthorization queda vacío ->
#   Policy bloquea crear_reserva con hora_sin_evidencia_del_usuario.
#
# La hora NO es nueva ni inferida: pertenece al mismo BookingObjective READY que
# el usuario acaba de confirmar. V172 permite que esa autoridad temporal
# sobreviva hasta ejecutar el write, siempre que coincidan:
#   * PendingInteraction resuelta como confirm/accept/select;
#   * ContextAuthorization congelada del mismo question_id;
#   * create_booking autoritativo y WRITE verificado;
#   * BookingObjective READY del mismo act_id;
#   * hora/día exactos del objective y su field_authority verificada.
# No usa regex ni keywords para decidir intención.
# ============================================================================


_agent_v2_booking_hour_has_user_grounding_v172_base = (
    _agent_v2_booking_hour_has_user_grounding
)


def _agent_v2_v172_confirmed_slot_hour_authority(
    args: Dict[str, Any],
    perception: Dict[str, Any],
) -> bool:
    args = args or {}
    perception = perception or {}

    requested_hour = normalizar_hora_detectada(
        args.get("hora")
    )
    requested_day = str(
        args.get("dia")
        or args.get("dia_resuelto")
        or ""
    ).strip()
    if (
        not hora_es_valida(requested_hour)
        or not requested_day
    ):
        return False

    resolution = (
        perception.get("context_resolution")
        if isinstance(
            perception.get("context_resolution"),
            dict,
        )
        else {}
    )
    if (
        resolution.get("resolved") is not True
        or str(resolution.get("type") or "")
        != "answers_pending"
        or str(resolution.get("resolution") or "")
        not in {"confirm", "accept", "select"}
    ):
        return False

    contract = (
        perception.get("execution_contract")
        if isinstance(
            perception.get("execution_contract"),
            dict,
        )
        else {}
    )
    if contract.get("authoritative") is not True:
        return False

    frozen_auth = (
        contract.get("authorized_context")
        if isinstance(
            contract.get("authorized_context"),
            dict,
        )
        else {}
    )
    if frozen_auth.get("authorized") is not True:
        return False

    frozen_question_id = str(
        frozen_auth.get("question_id") or ""
    ).strip()
    resolved_question_id = str(
        resolution.get("question_id")
        or resolution.get("interaction_id")
        or ""
    ).strip()
    if (
        not frozen_question_id
        or resolved_question_id != frozen_question_id
    ):
        return False

    allowed_fields = {
        str(value or "").strip()
        for value in (
            frozen_auth.get("allowed_fields")
            or []
        )
    }
    if "confirmar_slot" not in allowed_fields:
        return False

    create_acts = [
        dict(item)
        for item in (contract.get("acts") or [])
        if isinstance(item, dict)
        and str(item.get("operation") or "")
        == "create_booking"
    ]
    if len(create_acts) != 1:
        return False

    act = create_acts[0]
    act_id = str(
        act.get("act_id") or ""
    ).strip()
    if not act_id:
        return False

    verification = (
        perception.get("semantic_effect_verification")
        if isinstance(
            perception.get("semantic_effect_verification"),
            dict,
        )
        else {}
    )
    if verification.get("status") != "verified":
        return False
    if not any(
        isinstance(item, dict)
        and item.get("authorized") is True
        and str(item.get("act_id") or "").strip()
        == act_id
        and str(item.get("operation") or "").strip()
        in {"", "create_booking"}
        for item in (
            verification.get("write_authorizations")
            or []
        )
    ):
        return False

    objective = (
        perception.get("booking_objective")
        if isinstance(
            perception.get("booking_objective"),
            dict,
        )
        else {}
    )
    if (
        str(objective.get("operation") or "")
        != "create_booking"
        or str(objective.get("act_id") or "").strip()
        != act_id
        or [
            str(value or "").strip()
            for value in (
                objective.get("missing_fields")
                or []
            )
            if str(value or "").strip()
        ]
    ):
        return False

    objective_temporal = (
        objective.get("temporal")
        if isinstance(
            objective.get("temporal"),
            dict,
        )
        else {}
    )
    objective_hour = normalizar_hora_detectada(
        objective_temporal.get("start")
    )
    objective_day = str(
        objective_temporal.get("day")
        or objective_temporal.get("date")
        or ""
    ).strip()
    if (
        objective_hour != requested_hour
        or not objective_day
        or not _misma_fecha_reserva(
            {"fecha": objective_day},
            requested_day,
        )
    ):
        return False

    act_temporal = (
        act.get("temporal")
        if isinstance(
            act.get("temporal"),
            dict,
        )
        else {}
    )
    act_hour = normalizar_hora_detectada(
        act_temporal.get("start")
    )
    act_day = str(
        act_temporal.get("day")
        or act_temporal.get("date")
        or ""
    ).strip()
    if (
        act_hour != requested_hour
        or not act_day
        or not _misma_fecha_reserva(
            {"fecha": act_day},
            requested_day,
        )
    ):
        return False

    field_authority = (
        objective.get("field_authority")
        if isinstance(
            objective.get("field_authority"),
            dict,
        )
        else {}
    )
    hour_authority = (
        field_authority.get("hora")
        if isinstance(
            field_authority.get("hora"),
            dict,
        )
        else {}
    )
    if (
        hour_authority.get("verified") is not True
        or normalizar_hora_detectada(
            hour_authority.get("value")
        )
        != requested_hour
    ):
        return False

    authority_objective_id = str(
        hour_authority.get("objective_id") or ""
    ).strip()
    objective_id = str(
        objective.get("objective_id") or ""
    ).strip()
    if (
        authority_objective_id
        and objective_id
        and authority_objective_id != objective_id
    ):
        return False

    authority_act_id = str(
        hour_authority.get("act_id") or ""
    ).strip()
    if (
        authority_act_id
        and authority_act_id != act_id
    ):
        return False

    print(
        "   🔐 [AgentV2 V172 CONFIRMED SLOT HOUR AUTHORITY] "
        f"question_id={frozen_question_id} "
        f"objective={objective_id or 'n/a'} "
        f"dia={requested_day} hora={requested_hour}"
    )
    return True


def _agent_v2_booking_hour_has_user_grounding(
    args: Dict[str, Any],
    perception: Dict[str, Any],
    world: Dict[str, Any],
) -> bool:
    if _agent_v2_booking_hour_has_user_grounding_v172_base(
        args or {},
        perception or {},
        world or {},
    ):
        return True

    return _agent_v2_v172_confirmed_slot_hour_authority(
        args or {},
        perception or {},
    )


# ============================================================================
# V181 — VERIFIED PENDING SCOPE, HOLD CONTINUITY AND SILENT FALLBACK
# ============================================================================
# Incidente real:
#   usuario consulta disponibilidad para el miércoles -> el agente pregunta hora
#   -> usuario responde "sí, de fútbol" + "a las 3 de la tarde" -> Perception
#   reconoce correctamente create_booking y 15:00, pero un default temporal del
#   turno nuevo inyecta "hoy" y termina consultando Jueves 01/10.
#
# La corrección ocurre ANTES de Goal/Planner/Tools. No interpreta palabras ni
# parchea el renderer: consume el PendingInteraction tipado y el
# availability_context persistido. Sólo vincula el día cuando question_id,
# scope_id y fecha coinciden, la pregunta activa solicita `hora`, el write fue
# verificado y el turno físico actual no aportó otro día literal.
# ============================================================================


def _agent_v2_v181_current_turn_has_literal_day(
    perception: Dict[str, Any],
    mensaje: str,
) -> bool:
    """Comprueba evidencia literal de día sin confiar en un ISO calculado."""
    evidences: List[str] = []
    for item in (perception or {}).get("temporal_mentions") or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("kind") or "").strip().casefold() != "day":
            continue
        evidence = str(item.get("evidence") or "").strip()
        if evidence:
            evidences.append(evidence)

    frame = _agent_v2_semantic_frame(perception or {}) or {}
    for act in frame.get("acts") or []:
        if not isinstance(act, dict):
            continue
        for item in act.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            if str(item.get("source") or "").strip() != "current_user_turn":
                continue
            if str(item.get("field") or "").strip().casefold() not in {
                "temporal.day", "day", "dia", "entities.dia",
            }:
                continue
            evidence = str(item.get("evidence") or "").strip()
            if evidence:
                evidences.append(evidence)

    return any(
        _agent_v2_v126_literal_evidence(mensaje or "", evidence)
        for evidence in dict.fromkeys(evidences)
    )


def _agent_v2_v181_active_hour_question_and_availability(
    world: Dict[str, Any],
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """Devuelve un único binding hora↔disponibilidad del mismo scope."""
    stored = _agent_v2_stored_memory(world or {}) or {}
    availability = dict(
        stored.get("availability_context")
        or (world or {}).get("availability_context")
        or {}
    )
    availability_scope = str(availability.get("scope_id") or "").strip()
    availability_day = str(
        availability.get("day_iso")
        or availability.get("dia_resuelto")
        or availability.get("dia")
        or availability.get("dia_consulta")
        or ""
    ).strip()
    if not availability_scope or not availability_day:
        return {}, {}

    candidates: List[Dict[str, Any]] = []
    rows = list(stored.get("pending_decisions") or [])
    if not rows:
        rows = list((world or {}).get("open_questions") or [])
    for raw in rows:
        if not isinstance(raw, dict):
            continue
        field = str(raw.get("field") or "").strip().casefold()
        status = str(
            raw.get("interaction_status") or raw.get("status") or "active"
        ).strip().casefold()
        scope_id = str(raw.get("scope_id") or "").strip()
        question_id = str(
            raw.get("question_id") or raw.get("interaction_id") or ""
        ).strip()
        question_day = str(raw.get("dia") or "").strip()
        allowed = {
            str(value or "").strip()
            for value in (raw.get("allowed_operations") or [])
        }
        if field not in {"hora", "hora_aclaracion"}:
            continue
        if status not in {"active", "engaged", "suspended"}:
            continue
        if not question_id or scope_id != availability_scope:
            continue
        if allowed and "create_booking" not in allowed:
            continue
        if not question_day:
            continue
        candidates.append(dict(raw))

    if len(candidates) != 1:
        return {}, {}
    candidate_day = str(candidates[0].get("dia") or "").strip()
    if candidate_day and not _misma_fecha_reserva(
        {"fecha": candidate_day}, availability_day
    ):
        # El pending se genera después de responder la disponibilidad. Builds
        # anteriores podían contaminar su snapshot con el default "hoy". El
        # availability_context del MISMO scope es el recibo de la consulta real
        # al calendario y por eso es la autoridad temporal del binding.
        print(
            "   🧹 [AgentV2 V181 PENDING SNAPSHOT REPAIR] "
            f"scope={availability_scope} pending_day={candidate_day} "
            f"availability_day={availability_day}"
        )
    return candidates[0], availability


def _agent_v2_v181_verified_dialogue_hour_binding(
    world: Dict[str, Any],
) -> Dict[str, Any]:
    """Obtiene el binding tipado del resolver, aunque Perception lo haya perdido."""
    plan: Dict[str, Any] = {}
    try:
        candidate = AGENT_V2_DIALOGUE_CONTEXT_PLAN.get()
        if isinstance(candidate, dict):
            plan = dict(candidate)
    except Exception:
        plan = {}
    if (
        plan.get("status") != "verified"
        or str(plan.get("relation") or "") != "answers_pending"
    ):
        return {}

    question, availability = (
        _agent_v2_v181_active_hour_question_and_availability(world or {})
    )
    if not question or not availability:
        return {}
    qid = str(question.get("question_id") or question.get("interaction_id") or "").strip()
    scope_id = str(question.get("scope_id") or "").strip()
    matches = []
    for raw in plan.get("bindings") or []:
        if not isinstance(raw, dict) or raw.get("verified") is not True:
            continue
        field = _agent_v2_v105_normalize_missing_field(raw.get("field"))
        hour = normalizar_hora_detectada(raw.get("value"))
        if field != "hora" or not hora_es_valida(hour):
            continue
        if str(raw.get("question_id") or "").strip() != qid:
            continue
        if str(raw.get("scope_id") or "").strip() != scope_id:
            continue
        item = dict(raw)
        item["value"] = hour
        matches.append(item)
    return matches[0] if len(matches) == 1 else {}


def _agent_v2_v181_restore_degraded_pending_booking(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    """Impide que un pending de reserva verificado se degrade a un READ.

    La autoridad no proviene de keywords: exige el router IA del turno físico,
    el DialogueContextPlan verificado, identidad exacta question/scope y una
    única categoría de cancha ya entendida por Perception.
    """
    original = perception or {}
    if _agent_v2_v126r9_verified_create_booking_act(original):
        return original
    if not _agent_v2_v128_router_booking_intent():
        return original
    binding = _agent_v2_v181_verified_dialogue_hour_binding(world or {})
    if not binding:
        return original
    if _agent_v2_v181_current_turn_has_literal_day(original, mensaje):
        return original

    frame = _agent_v2_semantic_frame(original) or {}
    acts = [
        dict(item) for item in (frame.get("acts") or [])
        if isinstance(item, dict)
    ]
    if len(acts) != 1 or str(acts[0].get("operation") or "") != "query_availability":
        return original
    source_act = acts[0]
    target = dict(source_act.get("target") or {})
    resource_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if len(resource_types) != 1:
        return original

    question, _ = _agent_v2_v181_active_hour_question_and_availability(world or {})
    question_id = str(binding.get("question_id") or "").strip()
    scope_id = str(binding.get("scope_id") or "").strip()
    hour = normalizar_hora_detectada(binding.get("value"))
    evidence = str(binding.get("evidence") or mensaje or "").strip()
    clean = copy.deepcopy(original)
    frame = _agent_v2_semantic_frame(clean) or {}
    act = dict(source_act)
    act["operation"] = "create_booking"
    act["booking_commitment"] = "execute_booking"
    act["requested_facts"] = []
    act["question_domains"] = []
    act["commitment"] = {"wants_write": True, "wants_information": False}
    act_target = dict(act.get("target") or {})
    act_target["resource_types"] = resource_types
    act_target["resource_type"] = resource_types[0]
    act_target["selection_policy"] = "any_available"
    act["target"] = act_target
    act_temporal = dict(act.get("temporal") or {})
    act_temporal["start"] = hour
    act_temporal["times"] = [hour]
    act_temporal["duration_hours"] = (
        act_temporal.get("duration_hours") or DEFAULT_TURN_DURATION_HOURS
    )
    act["temporal"] = act_temporal
    provenance = [
        dict(item) for item in (act.get("provenance") or [])
        if isinstance(item, dict)
        and str(item.get("field") or "") != "temporal.start"
    ]
    provenance.append({
        "field": "temporal.start",
        "source": "current_user_turn",
        "evidence": evidence,
        "question_id": question_id,
        "scope_id": scope_id,
    })
    act["provenance"] = provenance
    frame["acts"] = [act]
    frame["intent"] = {"domain": "booking", "operation": "create_booking"}
    frame["commitment"] = {"wants_write": True, "wants_information": False}
    frame["context_relation"] = {
        "type": "answers_pending",
        "question_id": question_id,
        "interaction_id": question_id,
        "scope_id": scope_id,
        "answers_pending_question": True,
        "references_agent_offer": True,
        "references_previous_user_turn": False,
    }
    clean["semantic_frame"] = frame
    clean["explicit_actions"] = ["crear_reserva"]
    clean["commitment"] = "confirms_action"
    clean["speech_act"] = "answer"
    clean["pending_relation"] = "answers_pending"
    clean["answers_pending_field"] = "hora"
    clean["semantic_effect_verification"] = {
        "status": "verified",
        "mode": "verified_dialogue_booking_recovery",
        "write_authorizations": [{
            "act_id": str(act.get("act_id") or ""),
            "operation": "create_booking",
            "authorized": True,
            "evidence_type": "current_user_turn+pending_binding",
            "evidence": evidence,
            "question_id": question_id,
        }],
    }

    previous = dict(clean.get("booking_objective") or {})
    previous_id = str(previous.get("objective_id") or "").strip()
    expected_id = str(
        ((question.get("context") or {}).get("booking_objective_id"))
        or question.get("booking_objective_id")
        or previous_id
        or uuid.uuid4()
    )
    objective = previous if previous_id in {"", expected_id} else {}
    objective.update({
        "objective_id": expected_id,
        "act_id": str(act.get("act_id") or ""),
        "operation": "create_booking",
        "status": "ready",
        "target": act_target,
        "temporal": {
            "day": act_temporal.get("day"),
            "start": hour,
            "duration_hours": act_temporal.get("duration_hours"),
        },
        "addons": dict(objective.get("addons") or {}),
    })
    authority = dict(objective.get("field_authority") or {})
    authority["hora"] = {
        "value": hour,
        "verified": True,
        "source": "verified_dialogue_pending_binding",
        "question_id": question_id,
        "scope_id": scope_id,
        "objective_id": expected_id,
        "act_id": str(act.get("act_id") or ""),
    }
    objective["field_authority"] = authority
    objective["missing_fields"] = _agent_v2_v103_compute_missing(objective)
    objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
    clean["booking_objective"] = objective
    clean.pop("execution_contract", None)
    clean.pop("task_graph", None)
    clean.pop("desired_state", None)
    print(
        "   🔁 [AgentV2 V181 DEGRADED BOOKING RESTORE] "
        f"query_availability → create_booking question_id={question_id} "
        f"scope={scope_id} hora={hour} resource_type={resource_types[0]}"
    )
    return clean


def _agent_v2_v181_bind_verified_pending_booking_day(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    """Proyecta el día verificado del pending antes de compilar el plan."""
    original = _agent_v2_v181_restore_degraded_pending_booking(
        perception or {}, world or {}, mensaje
    )
    verified_act = _agent_v2_v126r9_verified_create_booking_act(original)
    if not verified_act:
        return original
    temporal = dict(verified_act.get("temporal") or {})
    if not hora_es_valida(normalizar_hora_detectada(temporal.get("start"))):
        return original
    if _agent_v2_v181_current_turn_has_literal_day(original, mensaje):
        return original

    question, availability = (
        _agent_v2_v181_active_hour_question_and_availability(world or {})
    )
    if not question or not availability:
        return original

    # La fecha operativa proviene del recibo de disponibilidad del mismo scope.
    # El snapshot de la pregunta es sólo el enlace y puede haber sido contaminado
    # por un default temporal anterior (el incidente real guardó "hoy").
    pending_date = _parse_fecha_row(str(
        availability.get("day_iso")
        or availability.get("dia_resuelto")
        or availability.get("dia")
        or availability.get("dia_consulta")
        or ""
    ))
    if not pending_date:
        return original
    pending_iso = pending_date.isoformat()
    pending_display = _agent_v2_v103_normalized_day(pending_iso)
    current_day = str(temporal.get("day") or temporal.get("date") or "").strip()
    if current_day and _misma_fecha_reserva({"fecha": current_day}, pending_iso):
        return original

    clean = copy.deepcopy(original)
    frame = _agent_v2_semantic_frame(clean) or {}
    acts = [dict(act) for act in (frame.get("acts") or []) if isinstance(act, dict)]
    act_id = str(verified_act.get("act_id") or "").strip()
    question_id = str(
        question.get("question_id") or question.get("interaction_id") or ""
    ).strip()
    scope_id = str(question.get("scope_id") or "").strip()
    evidence = str(
        availability.get("source_message")
        or question.get("question_text")
        or ""
    ).strip()
    provenance_binding = {
        "field": "temporal.day",
        "source": "pending_option",
        "evidence": evidence,
        "question_id": question_id,
        "scope_id": scope_id,
    }

    updated_acts: List[Dict[str, Any]] = []
    for act in acts:
        if str(act.get("act_id") or "").strip() == act_id:
            act_temporal = dict(act.get("temporal") or {})
            act_temporal["day"] = pending_iso
            act["temporal"] = act_temporal
            provenance = [
                dict(item) for item in (act.get("provenance") or [])
                if isinstance(item, dict)
                and not (
                    str(item.get("field") or "").strip().casefold()
                    in {"temporal.day", "day", "dia", "entities.dia"}
                    and str(item.get("source") or "").strip()
                    != "current_user_turn"
                )
            ]
            provenance.append(provenance_binding)
            act["provenance"] = provenance
        updated_acts.append(act)
    frame["acts"] = updated_acts
    frame_temporal = dict(frame.get("temporal") or {})
    frame_temporal["day"] = pending_iso
    frame["temporal"] = frame_temporal
    frame["context_relation"] = {
        "type": "answers_pending",
        "question_id": question_id,
        "interaction_id": question_id,
        "scope_id": scope_id,
        "answers_pending_question": True,
        "references_agent_offer": True,
        "references_previous_user_turn": False,
    }
    clean["semantic_frame"] = frame

    entities = dict(clean.get("entities") or {})
    entities["dia"] = pending_iso
    entities["dia_resuelto"] = pending_display
    clean["entities"] = entities
    clean["pending_relation"] = "answers_pending"
    clean["answers_pending_field"] = str(question.get("field") or "hora")
    clean["context_resolution"] = {
        "resolved": True,
        "type": "answers_pending",
        "resolution": "select",
        "question_id": question_id,
        "interaction_id": question_id,
        "scope_id": scope_id,
        "field": str(question.get("field") or "hora"),
        "source": "verified_pending_availability_scope",
    }

    objective = dict(clean.get("booking_objective") or {})
    if objective and str(objective.get("operation") or "") == "create_booking":
        objective_temporal = dict(objective.get("temporal") or {})
        objective_temporal["day"] = pending_display
        objective["temporal"] = objective_temporal
        objective["act_id"] = act_id
        authority = dict(objective.get("field_authority") or {})
        authority["dia"] = {
            "value": pending_display,
            "verified": True,
            "source": "pending_option+verified_availability_context",
            "question_id": question_id,
            "scope_id": scope_id,
            "objective_id": objective.get("objective_id"),
            "act_id": act_id,
        }
        objective["field_authority"] = authority
        objective["missing_fields"] = _agent_v2_v103_compute_missing(objective)
        objective["status"] = (
            "ready" if not objective["missing_fields"] else "collecting"
        )
        objective["action_snapshot"] = _agent_v2_v103_action_snapshot(objective)
        clean["booking_objective"] = objective
        # Este binding completa exactamente la PendingInteraction de booking;
        # publica la misma señal tipada que consume el preflight/hold V105.
        clean["_v103_booking_engaged"] = True
        clean["_v105_pending_booking_completed"] = not bool(
            objective["missing_fields"]
        )
        clean["_v109_ready_booking_authorized"] = not bool(
            objective["missing_fields"]
        )

    # El significado se vuelve a congelar desde el frame ya vinculado. De este
    # modo Goal Compiler y Planner nunca alcanzan a ver el default incorrecto.
    clean.pop("execution_contract", None)
    clean.pop("task_graph", None)
    clean.pop("desired_state", None)
    clean["execution_contract"] = _agent_v2_build_execution_contract(
        clean, world or {}
    )
    clean = _agent_v2_v100_attach_desired_state_and_task_graph(clean, world or {})
    clean["_v100_semantic_frozen"] = True

    print(
        "   🔗 [AgentV2 V181 PENDING DAY BINDING] "
        f"question_id={question_id} scope={scope_id} "
        f"default_descartado={current_day or 'vacío'} → dia={pending_display}"
    )
    return clean


_percibir_turno_agent_v2_v181_base = percibir_turno_agent_v2


async def percibir_turno_agent_v2(
    mensaje: str,
    world: Dict,
    image_path: str = "",
    learning_policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    clean = await _percibir_turno_agent_v2_v181_base(
        mensaje, world, image_path, learning_policy
    )
    return _agent_v2_v181_bind_verified_pending_booking_day(
        clean, world or {}, mensaje
    )


_run_agent_v2_invariant_evals_v181_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v181_base()
    results = list(result.get("results") or [])
    scope_id = "turn_v181_wednesday"
    question_id = "question_v181_hour"
