_ejecutar_agente_real_v2_turno_v181_base = ejecutar_agente_real_v2_turno


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    result = await _ejecutar_agente_real_v2_turno_v181_base(
        mensaje,
        conv_state,
        prospecto,
        telefono,
        user_messages=user_messages,
        page=page,
        image_path=image_path,
        dry_run=dry_run,
        eval_context=eval_context,
    )
    if not isinstance(result, dict) or not result.get("handled"):
        return result
    perception = result.get("perception") or {}
    observations = result.setdefault("observations", [])
    assessment = result.get("safe_exit") or {}
    state = str(assessment.get("state") or "").strip()
    silent_failure = bool(
        _agent_v2_v181_reasks_verified_objective_field(perception)
        or (
        state == "internal_recovery_write"
        and _agent_v2_v181_verified_ready_booking_failed(
            perception, observations
        )
        )
    )
    if silent_failure:
        raw_obligations = perception.get("response_obligations")
        if isinstance(raw_obligations, dict):
            obligations = dict(raw_obligations)
        elif isinstance(raw_obligations, list):
            obligations = next((
                dict(item) for item in raw_obligations
                if isinstance(item, dict)
                and str(item.get("type") or "") == "missing_field_question"
            ), {})
        else:
            obligations = {}
        source = (
            f"safe_exit:verified_field_reasked:{obligations.get('field')}"
            if _agent_v2_v181_reasks_verified_objective_field(perception)
            else "safe_exit:internal_recovery_write:verified_create_booking_not_executed"
        )
        response, new_assessment, _ = (
            _agent_v2_v140_register_internal_failure_handoff(
                source=source,
                original_response=result.get("response") or "",
                world=result.get("world") or {"message": mensaje},
                observations=observations,
                telefono=telefono,
                prospecto=prospecto,
                perception=perception,
                page=page,
                dry_run=dry_run,
            )
        )
        result["response"] = response
        result["safe_exit"] = new_assessment
        result["status"] = "complete"
        result["customer_response_suppressed"] = True
        result["delivery_policy"] = "suppress_customer"
        result["silent_handoff"] = True
    return result


def _agent_v2_v181_ready_verified_pending_booking(
    perception: Dict[str, Any],
) -> bool:
    perception = perception or {}
    objective = dict(perception.get("booking_objective") or {})
    contract = dict(perception.get("execution_contract") or {})
    authorization = dict(contract.get("authorized_context") or {})
    contract_acts = [
        item for item in (contract.get("acts") or [])
        if isinstance(item, dict)
    ]
    return bool(
        perception.get("_v105_pending_booking_completed") is True
        and _agent_v2_v126r9_verified_create_booking_act(perception)
        and str(objective.get("operation") or "") == "create_booking"
        and not _agent_v2_v103_compute_missing(objective)
        and contract.get("authoritative") is True
        and len(contract_acts) == 1
        and str(contract_acts[0].get("operation") or "") == "create_booking"
        and authorization.get("authorized") is True
        and str(authorization.get("relation") or "") == "answers_pending"
    )


