def _agent_v2_v126r2_can_auto_assign_equivalent_court(
    perception: Dict[str, Any],
    available_courts: List[str],
) -> bool:
    if _agent_v2_v126r2_can_auto_assign_equivalent_court_v181_base(
        perception or {}, available_courts or []
    ):
        return True
    if not _agent_v2_v181_ready_verified_pending_booking(perception or {}):
        return False
    objective = dict((perception or {}).get("booking_objective") or {})
    target = dict(objective.get("target") or {})
    if str(target.get("label") or "").strip():
        return False
    resource_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    courts = [
        str(value or "").strip()
        for value in (available_courts or [])
        if str(value or "").strip()
    ]
    if len(resource_types) != 1 or not courts:
        return False
    if not all(
        _court_matches_resource_types(court, resource_types)
        for court in courts
    ):
        return False
    print(
        "   ✅ [AgentV2 V181 EQUIVALENT COURT AUTOASSIGN] "
        f"resource_type={resource_types[0]} courts={courts}"
    )
    return True


