# ============================================================================
# V182 — VERIFIED PENDING HOUR RESOURCE-CARRY RECOVERY
# ============================================================================
# Incidente live 2026-10-01 18:58/18:59:
#   T1: usuario consulta disponibilidad amplia para Miércoles 07/10.
#   T2: responde en el mismo lote "si de futbol" + "a las 3 de la tarde".
# El Dialogue Gate verificó correctamente la hora pendiente (15:00) y V126R7
# preservó el resource_type=Futbol 5, pero V126R3 degradó el binding a un plan
# independiente. Perception terminó como query_availability autónoma, aplicó el
# default "hoy" y más tarde Policy rechazó la propia hora verificada.
#
# V182 no relee texto ni usa regex. La recuperación exige simultáneamente:
#   - receipt estructurado verified_resource_carry del Dialogue Gate;
#   - router IA del sibling = reservar_cancha;
#   - question_id/scope_id idénticos a la PendingInteraction activa;
#   - binding tipado field=hora con valor horario válido y evidencia literal;
#   - availability_context del mismo scope;
#   - exactamente una categoría de cancha ya entendida por Perception;
#   - ausencia de un día literal nuevo en el current turn.
# Con esas pruebas reconstruye el TurnSemanticPlan answers_pending y reutiliza
# la promoción V181 ya validada para obtener create_booking + día del recibo de
# disponibilidad + autoridad de hora.


def _agent_v2_v182_restore_booking_from_verified_resource_carry(
    perception: Dict[str, Any],
    world: Dict[str, Any],
    mensaje: str,
) -> Dict[str, Any]:
    original = perception or {}

    if _agent_v2_v126r9_verified_create_booking_act(original):
        return original
    if not _agent_v2_v128_router_booking_intent():
        return original
    if _agent_v2_v181_current_turn_has_literal_day(original, mensaje):
        return original

    try:
        raw_plan = AGENT_V2_DIALOGUE_CONTEXT_PLAN.get()
    except Exception:
        raw_plan = {}
    if not isinstance(raw_plan, dict) or raw_plan.get("status") != "verified":
        return original
    # Si el binding original sigue vivo, V181 ya es dueño de resolverlo.
    if raw_plan.get("bindings"):
        return original

    carry = raw_plan.get("verified_resource_carry")
    if not isinstance(carry, dict) or carry.get("verified") is not True:
        return original
    field = _agent_v2_v105_normalize_missing_field(carry.get("binding_field"))
    hour = normalizar_hora_detectada(carry.get("binding_value"))
    question_id = str(carry.get("question_id") or "").strip()
    scope_id = str(carry.get("scope_id") or "").strip()
    evidence = str(carry.get("evidence") or "").strip()
    carry_type = str(carry.get("resource_type") or "").strip()
    if (
        field != "hora"
        or not hora_es_valida(hour)
        or not question_id
        or not scope_id
        or not evidence
        or not _agent_v2_v126_literal_evidence(mensaje or "", evidence)
    ):
        return original

    question, availability = _agent_v2_v181_active_hour_question_and_availability(
        world or {}
    )
    if not question or not availability:
        return original
    active_qid = str(
        question.get("question_id") or question.get("interaction_id") or ""
    ).strip()
    active_scope = str(question.get("scope_id") or "").strip()
    if active_qid != question_id or active_scope != scope_id:
        return original

    frame = _agent_v2_semantic_frame(original) or {}
    acts = [
        dict(item) for item in (frame.get("acts") or [])
        if isinstance(item, dict)
    ]
    if len(acts) != 1 or str(acts[0].get("operation") or "") != "query_availability":
        return original
    target = dict(acts[0].get("target") or {})
    resource_types = _canonical_configured_court_types(
        target.get("resource_types") or target.get("resource_type")
    )
    if len(resource_types) != 1:
        return original
    if carry_type and normalizar_texto_ia(carry_type) != normalizar_texto_ia(resource_types[0]):
        return original

    # El binding que V126R3 volvió pasivo se reconstruye exclusivamente desde
    # receipts verificados; no se infiere ningún dato adicional del mensaje.
    recovered_binding = {
        "verified": True,
        "relation": "answers_pending",
        "field": "hora",
        "value": hour,
        "evidence": evidence,
        "question_id": question_id,
        "interaction_id": question_id,
        "scope_id": scope_id,
        "objective_id": str(
            question.get("booking_objective_id")
            or ((question.get("context") or {}).get("booking_objective_id"))
            or ""
        ),
        "_interaction": dict(question),
    }
    recovery_plan = dict(raw_plan)
    recovery_plan.update({
        "status": "verified",
        "relation": "answers_pending",
        "bindings": [recovered_binding],
        "independent_acts": [],
        "route_to_general_perception": False,
        "semantic_frozen": True,
        "reason": "v182_verified_resource_carry_recovers_pending_booking",
    })

    token = AGENT_V2_DIALOGUE_CONTEXT_PLAN.set(recovery_plan)
    try:
        restored = _agent_v2_v181_bind_verified_pending_booking_day(
            original, world or {}, mensaje
        )
    finally:
        AGENT_V2_DIALOGUE_CONTEXT_PLAN.reset(token)

    restored_act = _agent_v2_v126r9_verified_create_booking_act(restored or {})
    if not restored_act:
        return original

    objective = dict((restored or {}).get("booking_objective") or {})
    print(
        "   🔁 [AgentV2 V182 VERIFIED PENDING BOOKING RESTORE] "
        f"question_id={question_id} scope={scope_id} "
        f"dia={(objective.get('temporal') or {}).get('day')} "
        f"hora={(objective.get('temporal') or {}).get('start')} "
        f"resource_type={resource_types[0]}"
    )
    return restored


