# ============================================================================
# V183 — CANONICAL CONVERSATION STATE + SINGLE AI ORCHESTRATOR (BOOKING V1)
# ============================================================================
# Objetivo arquitectónico:
#   1) Una única memoria operativa canónica por contacto (SQLite + espejo JSON).
#   2) Una única decisión semántica del AI Orchestrator para continuar una
#      transacción de reserva ya activa.
#   3) Una vez congelada esa decisión, ninguna capa posterior vuelve a
#      reinterpretar el lenguaje del usuario.
#   4) Python sólo valida hechos objetivos y ejecuta tools deterministas.
#
# Migración segura:
# - Los flujos todavía no migrados siguen usando Agent V2 legacy como fallback.
# - Booking follow-ups con contexto activo usan el fast path V183.
# - Media, pagos, torneos, scheduler, admin y handlers existentes permanecen.
# ============================================================================

CANONICAL_V183_DB_FILE = str(runtime_file("canonical_agent_state.sqlite3"))
_CANONICAL_V183_LOCK = threading.RLock()
_CANONICAL_V183_SCHEMA_READY = False


def _canonical_v183_init_db() -> None:
    global _CANONICAL_V183_SCHEMA_READY
    if _CANONICAL_V183_SCHEMA_READY:
        return
    with _CANONICAL_V183_LOCK:
        if _CANONICAL_V183_SCHEMA_READY:
            return
        conn = sqlite3.connect(CANONICAL_V183_DB_FILE, timeout=10)
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA synchronous=NORMAL")
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS canonical_conversation_state (
                    owner TEXT PRIMARY KEY,
                    state_json TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                )
                """
            )
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS canonical_turn_decisions (
                    turn_id TEXT PRIMARY KEY,
                    owner TEXT NOT NULL,
                    message_hash TEXT NOT NULL,
                    decision_json TEXT NOT NULL,
                    created_at TEXT NOT NULL
                )
                """
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_canonical_turn_owner "
                "ON canonical_turn_decisions(owner, created_at)"
            )
            conn.commit()
            _CANONICAL_V183_SCHEMA_READY = True
        finally:
            conn.close()


def _canonical_v183_default_state(owner: str) -> Dict[str, Any]:
    return {
        "version": "v183",
        "owner": str(owner or "unknown"),
        "active_flow": None,
        "booking": {
            "day": None,
            "time": None,
            "resource_type": None,
            "duration_hours": DEFAULT_TURN_DURATION_HOURS,
            "court": None,
            "status": None,
            "reservation_id": None,
        },
        "availability": None,
        "pending": None,
        "event_registration": None,
        "last_decision": None,
        "recent_messages": [],
        "updated_at": datetime.datetime.now(TIMEZONE).isoformat(),
    }


def _canonical_v183_load(owner: str) -> Dict[str, Any]:
    owner_key = _memory_owner_key(owner)
    _canonical_v183_init_db()
    state = _canonical_v183_default_state(owner_key)
    with _CANONICAL_V183_LOCK:
        conn = sqlite3.connect(CANONICAL_V183_DB_FILE, timeout=10)
        try:
            row = conn.execute(
                "SELECT state_json FROM canonical_conversation_state WHERE owner = ?",
                (owner_key,),
            ).fetchone()
        finally:
            conn.close()
    if row:
        try:
            loaded = json.loads(str(row[0] or "{}"))
            if isinstance(loaded, dict):
                state.update(loaded)
        except Exception as exc:
            print(
                "   ⚠️ [CANONICAL V183 STATE] estado SQLite ilegible; "
                f"uso estado nuevo: {type(exc).__name__}: {exc}"
            )
    state["version"] = "v183"
    state["owner"] = owner_key
    if not isinstance(state.get("booking"), dict):
        state["booking"] = _canonical_v183_default_state(owner_key)["booking"]
    if not isinstance(state.get("recent_messages"), list):
        state["recent_messages"] = []
    return state


def _canonical_v183_save(owner: str, state: Dict[str, Any]) -> Dict[str, Any]:
    owner_key = _memory_owner_key(owner)
    _canonical_v183_init_db()
    clean = copy.deepcopy(state or {})
    clean["version"] = "v183"
    clean["owner"] = owner_key
    clean["updated_at"] = datetime.datetime.now(TIMEZONE).isoformat()
    payload = json.dumps(clean, ensure_ascii=False, default=str)
    with _CANONICAL_V183_LOCK:
        conn = sqlite3.connect(CANONICAL_V183_DB_FILE, timeout=10)
        try:
            conn.execute(
                """
                INSERT INTO canonical_conversation_state(owner, state_json, updated_at)
                VALUES (?, ?, ?)
                ON CONFLICT(owner) DO UPDATE SET
                    state_json=excluded.state_json,
                    updated_at=excluded.updated_at
                """,
                (owner_key, payload, clean["updated_at"]),
            )
            conn.commit()
        finally:
            conn.close()
    # Espejo legible dentro del JSON histórico. SQLite sigue siendo la autoridad.
    try:
        update_conversation_state(owner_key, canonical_state_v183=clean)
    except Exception as exc:
        print(
            "   ⚠️ [CANONICAL V183 STATE] espejo conversation_states no fatal: "
            f"{type(exc).__name__}: {exc}"
        )
    return clean


def _canonical_v183_record_decision(
    owner: str,
    turn_id: str,
    message: str,
    decision: Dict[str, Any],
) -> None:
    _canonical_v183_init_db()
    owner_key = _memory_owner_key(owner)
    digest = hashlib.sha256(str(message or "").encode("utf-8")).hexdigest()
    payload = json.dumps(decision or {}, ensure_ascii=False, default=str)
    now = datetime.datetime.now(TIMEZONE).isoformat()
    with _CANONICAL_V183_LOCK:
        conn = sqlite3.connect(CANONICAL_V183_DB_FILE, timeout=10)
        try:
            conn.execute(
                """
                INSERT OR REPLACE INTO canonical_turn_decisions(
                    turn_id, owner, message_hash, decision_json, created_at
                ) VALUES (?, ?, ?, ?, ?)
                """,
                (turn_id, owner_key, digest, payload, now),
            )
            conn.commit()
        finally:
            conn.close()


def _canonical_v183_booking_question(question: Dict[str, Any]) -> bool:
    if not isinstance(question, dict):
        return False
    field = _agent_v2_v105_normalize_missing_field(question.get("field"))
    goals = {
        str(value or "").strip()
        for value in (question.get("goal_context") or [])
    }
    return bool(
        field in {
            "dia", "hora", "hora_aclaracion", "resource_type",
            "cancha", "duracion_horas", "confirmar_slot",
        }
        or goals.intersection({"crear_reserva", "buscar_turno"})
    )


def _canonical_v183_hydrate_from_legacy(
    owner: str,
    conv_state: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    owner_key = _memory_owner_key(owner)
    state = _canonical_v183_load(owner_key)
    conv = conv_state if isinstance(conv_state, dict) else get_conversation_state(owner_key)
    av2 = _agent_v2_state(conv)
    booking = dict(state.get("booking") or {})

    availability = dict(av2.get("availability_context") or {})
    draft = dict(((av2.get("desires") or {}).get("booking_draft")) or {})
    questions = [
        dict(q) for q in (av2.get("open_questions") or [])
        if isinstance(q, dict) and _canonical_v183_booking_question(q)
    ]
    active_question = questions[-1] if questions else {}

    # Un pending creado por el fast path canónico es más reciente y preciso que
    # los drafts/open_questions del puente legado. El incidente del 08/10/2026
    # mostró que rehidratar primero el draft viejo podía reemplazar "hoy 16:00"
    # por "miércoles 18:00" justo antes de que el cliente respondiera el deporte.
    canonical_pending = (
        dict(state.get("pending") or {})
        if isinstance(state.get("pending"), dict)
        else {}
    )
    canonical_pending_source = str(canonical_pending.get("source") or "").strip()
    canonical_owned_booking_pending = bool(
        _canonical_v183_booking_question(canonical_pending)
        and canonical_pending_source.startswith("canonical_")
        and str(canonical_pending.get("operation") or "").strip()
        in {"create_booking", "query_availability"}
    )

    active_booking_context = bool(
        canonical_owned_booking_pending or availability or draft or active_question
    )
    if active_booking_context:
        state["active_flow"] = "booking"

        day = str(
            (canonical_pending.get("day") if canonical_owned_booking_pending else None)
            or booking.get("day")
            or draft.get("dia")
            or availability.get("dia")
            or availability.get("dia_resuelto")
            or active_question.get("dia")
            or ""
        ).strip()
        if day:
            booking["day"] = day

        hour = normalizar_hora_detectada(
            (canonical_pending.get("time") if canonical_owned_booking_pending else None)
            or booking.get("time")
            or draft.get("hora")
            or active_question.get("hora")
        )
        if hora_es_valida(hour):
            booking["time"] = hour

        resource_types = _canonical_configured_court_types(
            (canonical_pending.get("resource_type") if canonical_owned_booking_pending else None)
            or booking.get("resource_type")
            or draft.get("resource_types")
            or draft.get("resource_type")
            or availability.get("resource_types")
            or availability.get("resource_type")
            or active_question.get("resource_types")
            or active_question.get("resource_type")
        )
        if len(resource_types) == 1:
            booking["resource_type"] = resource_types[0]

        duration = normalizar_duracion_horas(
            (canonical_pending.get("duration_hours") if canonical_owned_booking_pending else None)
            or booking.get("duration_hours")
            or draft.get("duracion_horas")
            or active_question.get("duracion_horas")
            or DEFAULT_TURN_DURATION_HOURS,
            DEFAULT_TURN_DURATION_HOURS,
        )
        booking["duration_hours"] = duration

        if draft.get("cancha"):
            booking["court"] = draft.get("cancha")

        if availability and not canonical_owned_booking_pending:
            state["availability"] = {
                "scope_id": availability.get("scope_id"),
                "day": availability.get("dia") or availability.get("dia_resuelto"),
                "resource_type": availability.get("resource_type"),
                "resource_types": list(availability.get("resource_types") or []),
                "source_message": availability.get("source_message"),
                "created_at": availability.get("created_at"),
            }

        if active_question and not canonical_owned_booking_pending:
            state["pending"] = {
                "field": active_question.get("field"),
                "question_id": active_question.get("question_id"),
                "scope_id": active_question.get("scope_id"),
                "day": active_question.get("dia") or booking.get("day"),
                "resource_type": active_question.get("resource_type") or booking.get("resource_type"),
                "options": list(active_question.get("options") or []),
            }
    elif state.get("active_flow") == "booking":
        # Si Agent V2 ya cerró draft/pending/availability, no mantener un scope
        # conversacional viejo activo por mera persistencia SQLite.
        state["active_flow"] = None
        state["pending"] = None
        state["availability"] = None

    state["booking"] = booking
    history = []
    for item in (conv.get("historial") or [])[-12:]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip()
        content = str(item.get("content") or "").strip()
        if role and content:
            history.append({"role": role, "content": content[:900]})
    state["recent_messages"] = history
    return _canonical_v183_save(owner_key, state)


def _canonical_v183_has_active_booking_context(state: Dict[str, Any]) -> bool:
    if not isinstance(state, dict) or state.get("active_flow") != "booking":
        return False
    pending = state.get("pending") if isinstance(state.get("pending"), dict) else {}
    availability = state.get("availability") if isinstance(state.get("availability"), dict) else {}
    return bool(pending or availability)


def _canonical_v183_missing_question(field: str) -> str:
    field = _agent_v2_v105_normalize_missing_field(field)
    if field == "dia":
        return "¿Qué día te gustaría reservar?"
    if field in {"hora", "hora_aclaracion"}:
        return "¿Qué hora te sirve?"
    if field == "resource_type":
        options = list(_configured_court_type_labels())
        if options:
            return f"¿Qué querés reservar: {_agent_v2_join_human_options(options)}?"
        return "¿Qué tipo de cancha querés reservar?"
    if field == "duracion_horas":
        labels = [f"{float(v):g} h" for v in (ALLOWED_TURN_DURATIONS or [])]
        return (
            f"¿Cuánto tiempo querés reservar? Opciones: {_agent_v2_join_human(labels)}."
            if labels else "¿Cuánto tiempo querés reservar?"
        )
    return "¿Qué dato te falta definir para la reserva?"


async def _canonical_v183_orchestrate_booking(
    message: str,
    user_messages: List[str],
    state: Dict[str, Any],
) -> Dict[str, Any]:
    """Una sola interpretación AI para continuar un booking ya activo."""
    booking = dict(state.get("booking") or {})
    pending = dict(state.get("pending") or {}) if isinstance(state.get("pending"), dict) else {}
    availability = dict(state.get("availability") or {}) if isinstance(state.get("availability"), dict) else {}
    recent = list(state.get("recent_messages") or [])[-10:]
    configured_types = list(_configured_court_type_labels())

    payload = {
        "now": datetime.datetime.now(TIMEZONE).isoformat(),
        "latest_user_messages": [str(x) for x in (user_messages or [message]) if str(x).strip()],
        "latest_user_turn": str(message or "").strip(),
        "canonical_state": {
            "active_flow": state.get("active_flow"),
            "booking": booking,
            "pending": pending,
            "availability": availability,
        },
        "recent_messages": recent,
        "business_constraints": {
            "configured_resource_types": configured_types,
            "allowed_durations_hours": list(ALLOWED_TURN_DURATIONS or []),
            "default_duration_hours": DEFAULT_TURN_DURATION_HOURS,
        },
    }

    system = (
        "Sos el UNICO AI ORCHESTRATOR semántico de una conversación de reservas. "
        "Recibís un estado canónico ya persistido y el último turno físico del usuario. "
        "Tu única tarea es decidir la próxima operación; después de tu JSON ninguna capa "
        "vuelve a reinterpretar el lenguaje.\n\n"
        "REGLAS:\n"
        "- Usá datos del latest_user_turn y del canonical_state; no inventes.\n"
        "- Si el estado muestra una disponibilidad/pregunta activa y el usuario responde "
        "con la hora, deporte o confirmación necesarios para reservar, elegí create_booking.\n"
        "- Si el usuario solamente pregunta o refina disponibilidad, elegí refine_availability.\n"
        "- Si realmente falta un dato para crear la reserva, elegí ask_missing y listalo.\n"
        "- Si el turno cambia de dominio, cancela/modifica una reserva, habla de pago, torneo, "
        "quincho complejo, administración o cualquier cosa fuera de este booking simple, "
        "elegí delegate_legacy.\n"
        "- La disponibilidad real, precios, dinero y escritura de calendario NO los decidís: "
        "eso lo valida Python con tools.\n"
        "- create_booking sólo significa que el usuario quiere ejecutar la reserva, no que el "
        "slot esté libre.\n\n"
        "Respondé SOLO JSON con esta forma exacta:\n"
        "{\n"
        "  \"operation\": \"create_booking|refine_availability|ask_missing|delegate_legacy\",\n"
        "  \"confidence\": 0.0,\n"
        "  \"booking\": {\n"
        "    \"day\": null,\n"
        "    \"time\": null,\n"
        "    \"resource_type\": null,\n"
        "    \"duration_hours\": null\n"
        "  },\n"
        "  \"missing_fields\": [],\n"
        "  \"reason\": \"breve\"\n"
        "}"
    )

    try:
        resp = await call_openai_async(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": system},
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False, default=str)},
            ],
            max_tokens=500,
            response_format={"type": "json_object"},
        )
        register_cost(resp)
        decision = _loads_llm_json_object(resp.choices[0].message.content)
    except Exception as exc:
        print(
            "   ⚠️ [CANONICAL V183 ORCHESTRATOR] fallo no fatal → legacy: "
            f"{type(exc).__name__}: {exc}"
        )
        return {"operation": "delegate_legacy", "confidence": 0.0, "reason": "orchestrator_error"}

    # V204 — la operación replace_pending_booking tiene una precondición de
    # realidad: debe existir un hold activo AHORA. Si la IA arrastró un hold
    # expirado desde recent_messages/availability histórica, no escalamos a humano
    # ni reinterpretamos con reglas Python; hacemos una segunda adjudicación IA
    # informándole la verdad transaccional actual.
    pending_focus_v204 = _canonical_v203_pending_hold_focus(state)
    resolution_v204 = (
        decision.get("context_resolution")
        if isinstance(decision.get("context_resolution"), dict)
        else {}
    )
    invalid_pending_hold_operation = bool(
        not pending_focus_v204.get("active")
        and (
            str(decision.get("operation") or "").strip() == "replace_pending_booking"
            or str(resolution_v204.get("effective_operation") or "").strip()
            == "replace_pending_booking"
        )
    )
    if invalid_pending_hold_operation:
        print(
            "   🧹 [CANONICAL V204 PENDING HOLD PRECONDITION] "
            "replace_pending_booking rechazado: no existe hold activo; re-arbitro con IA"
        )
        recovered_v204 = await _canonical_v204_recover_without_active_pending_hold(
            message,
            user_messages,
            state,
            image_path=image_path,
        )
        if recovered_v204:
            decision = recovered_v204
        else:
            return {
                "operation": "delegate_legacy",
                "confidence": 0.0,
                "reason": "expired_hold_semantic_recovery_failed",
                "_canonical_internal_error": "v204_expired_hold_semantic_recovery_failed",
                "_suppress_legacy_fallback": True,
            }

    operation = str(decision.get("operation") or "delegate_legacy").strip()
    if operation not in {
        "create_booking", "refine_availability", "ask_missing", "delegate_legacy"
    }:
        operation = "delegate_legacy"
    decision["operation"] = operation
    try:
        decision["confidence"] = max(0.0, min(1.0, float(decision.get("confidence") or 0.0)))
    except Exception:
        decision["confidence"] = 0.0
    if not isinstance(decision.get("booking"), dict):
        decision["booking"] = {}
    if not isinstance(decision.get("missing_fields"), list):
        decision["missing_fields"] = []
    return decision


def _canonical_v183_merge_booking_decision(
    state: Dict[str, Any],
    decision: Dict[str, Any],
) -> Dict[str, Any]:
    stored = dict(state.get("booking") or {})
    incoming = dict(decision.get("booking") or {})
    availability = dict(state.get("availability") or {}) if isinstance(state.get("availability"), dict) else {}
    pending = dict(state.get("pending") or {}) if isinstance(state.get("pending"), dict) else {}

    raw_day = (
        incoming.get("day")
        or stored.get("day")
        or pending.get("day")
        or availability.get("day")
    )
    parsed_day = _parse_fecha_row(str(raw_day or ""))
    day = _agent_v2_v103_normalized_day(parsed_day.isoformat()) if parsed_day else str(raw_day or "").strip()

    hour = normalizar_hora_detectada(
        incoming.get("time") or stored.get("time") or pending.get("time")
    )

    resource_types = _canonical_configured_court_types(
        incoming.get("resource_type")
        or stored.get("resource_type")
        or pending.get("resource_type")
        or availability.get("resource_type")
        or availability.get("resource_types")
    )
    resource_type = resource_types[0] if len(resource_types) == 1 else None

    duration = normalizar_duracion_horas(
        incoming.get("duration_hours")
        or stored.get("duration_hours")
        or pending.get("duration_hours")
        or DEFAULT_TURN_DURATION_HOURS,
        DEFAULT_TURN_DURATION_HOURS,
    )
    return {
        "day": day or None,
        "time": hour if hora_es_valida(hour) else None,
        "time_specificity": (
            str(
                incoming.get("time_specificity")
                or stored.get("time_specificity")
                or pending.get("time_specificity")
                or ""
            ).strip().casefold()
            or ("exact" if hora_es_valida(hour) else "none")
        ),
        "time_source": incoming.get("time_source") or stored.get("time_source"),
        "time_evidence": incoming.get("time_evidence") or stored.get("time_evidence"),
        "resource_type": resource_type,
        "duration_hours": duration,
    }


def _canonical_v183_build_perception(
    state: Dict[str, Any],
    booking: Dict[str, Any],
    message: str,
) -> Dict[str, Any]:
    act_id = f"canonical_{uuid.uuid4().hex[:16]}"
    pending = dict(state.get("pending") or {}) if isinstance(state.get("pending"), dict) else {}
    qid = str(pending.get("question_id") or "").strip()
    scope_id = str(
        pending.get("scope_id")
        or ((state.get("availability") or {}).get("scope_id") if isinstance(state.get("availability"), dict) else "")
        or f"canonical_scope_{uuid.uuid4().hex[:16]}"
    )
    relation = "answers_pending" if qid else "new_request"
    day = booking.get("day")
    hour = booking.get("time")
    resource_type = booking.get("resource_type")
    duration = booking.get("duration_hours") or DEFAULT_TURN_DURATION_HOURS

    act = {
        "act_id": act_id,
        "operation": "create_booking",
        "domain": "booking",
        "booking_commitment": "execute_booking",
        "target": {
            "resource": "court",
            "resource_type": resource_type,
            "resource_types": [resource_type] if resource_type else [],
            "selection_policy": "any_available",
        },
        "temporal": {
            "day": day,
            "start": hour,
            "times": [hour] if hour else [],
            "duration_hours": duration,
        },
        "quantity": {"duration_hours": duration},
        "requested_facts": [],
        "question_domains": [],
        "commitment": {"wants_write": True, "wants_information": False},
        "provenance": [
            {
                "field": "temporal.start",
                "source": "canonical_ai_orchestrator_v183",
                "evidence": str(message or ""),
                "question_id": qid or None,
                "scope_id": scope_id,
            },
            {
                "field": "temporal.day",
                "source": "canonical_state_v183",
                "evidence": str(day or ""),
                "question_id": qid or None,
                "scope_id": scope_id,
            },
            {
                "field": "target.resource_type",
                "source": "canonical_ai_orchestrator_v183",
                "evidence": str(resource_type or ""),
                "question_id": qid or None,
                "scope_id": scope_id,
            },
        ],
    }
    authority = {
        "authorized": True,
        "relation": relation,
        "question_id": qid or None,
        "scope_id": scope_id,
        "allowed_fields": ["dia", "hora", "resource_type", "duracion_horas"],
        "allowed_sources": ["canonical_state_v183", "canonical_ai_orchestrator_v183"],
        "reason": "single_ai_orchestrator_frozen_decision",
    }
    field_authority = {
        "dia": {"verified": True, "value": day, "source": "canonical_state_v183", "act_id": act_id},
        "hora": {"verified": True, "value": hour, "source": "canonical_ai_orchestrator_v183", "act_id": act_id},
        "resource_type": {"verified": True, "value": resource_type, "source": "canonical_ai_orchestrator_v183", "act_id": act_id},
        "duracion_horas": {"verified": True, "value": duration, "source": "canonical_state_v183", "act_id": act_id},
    }
    return {
        "source": "canonical_ai_orchestrator_v183",
        "speech_act": "answer",
        "commitment": "confirms_action",
        "explicit_actions": ["crear_reserva"],
        "booking_time_choice": True,
        "accepts_any_option": True,
        "answers_pending_field": pending.get("field") or "hora",
        "pending_relation": relation,
        "entities": {
            "dia": day,
            "hora": hour,
            "resource_type": resource_type,
            "duracion_horas": duration,
        },
        "semantic_frame": {
            "source": "canonical_ai_orchestrator_v183",
            "schema_valid": True,
            "intent": {"domain": "booking", "operation": "create_booking"},
            "acts": [act],
            "commitment": {"wants_write": True, "wants_information": False},
            "context_relation": {
                "type": relation,
                "question_id": qid or None,
                "interaction_id": qid or None,
                "scope_id": scope_id,
                "answers_pending_question": bool(qid),
            },
        },
        "semantic_effect_verification": {
            "status": "verified",
            "mode": "canonical_ai_orchestrator_v183",
            "write_authorizations": [{
                "act_id": act_id,
                "operation": "create_booking",
                "authorized": True,
                "evidence_type": "single_ai_orchestrator+canonical_state",
                "evidence": str(message or ""),
                "question_id": qid or None,
            }],
        },
        "execution_contract": {
            "authoritative": True,
            "acts": [act],
            "allowed_tools": ["consultar_disponibilidad", "crear_reserva"],
            "authorized_context": authority,
            "context_relation": {"type": relation},
        },
        "booking_objective": {
            "objective_id": f"canonical_objective_{uuid.uuid4().hex[:16]}",
            "act_id": act_id,
            "operation": "create_booking",
            "status": "ready",
            "target": act["target"],
            "temporal": {
                "day": day,
                "start": hour,
                "duration_hours": duration,
            },
            "addons": {},
            "field_authority": field_authority,
            "missing_fields": [],
        },
        "_v103_booking_engaged": True,
        "_v105_pending_booking_completed": True,
        "_v109_ready_booking_authorized": True,
        "_v183_canonical_frozen": True,
    }


async def _canonical_v183_execute_booking(
    message: str,
    user_messages: List[str],
    state: Dict[str, Any],
    decision: Dict[str, Any],
    prospecto: Dict[str, Any],
    telefono: str,
    page=None,
    image_path: str = "",
) -> Optional[Dict[str, Any]]:
    booking = _canonical_v183_merge_booking_decision(state, decision)
    missing = []
    if not booking.get("day"):
        missing.append("dia")
    if not booking.get("time"):
        missing.append("hora")
    if not booking.get("resource_type"):
        missing.append("resource_type")
    allowed_durations = {
        float(value) for value in (ALLOWED_TURN_DURATIONS or [])
        if value not in (None, "")
    }
    try:
        duration_value = float(booking.get("duration_hours"))
    except Exception:
        duration_value = float(DEFAULT_TURN_DURATION_HOURS)
    if allowed_durations and duration_value not in allowed_durations:
        missing.append("duracion_horas")
    booking["duration_hours"] = duration_value

    if missing:
        field = missing[0]
        state["active_flow"] = "booking"
        state["booking"].update(booking)
        state["pending"] = {
            "type": "booking_question",
            "field": field,
            "question_id": f"canonical_{uuid.uuid4().hex[:16]}",
            "scope_id": str(((state.get("availability") or {}).get("scope_id") if isinstance(state.get("availability"), dict) else "") or f"canonical_scope_{uuid.uuid4().hex[:16]}"),
            "day": booking.get("day"),
            "time": booking.get("time"),
            "time_specificity": booking.get("time_specificity"),
            "resource_type": booking.get("resource_type"),
            "duration_hours": booking.get("duration_hours"),
            "operation": "create_booking",
            "source": "canonical_v225_booking_question",
            "goal_context": ["crear_reserva"],
            "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
        }
        _canonical_v183_save(telefono, state)
        print(
            "   🧩 [CANONICAL V183 MISSING] "
            f"field={field} → pregunta única; legacy omitido"
        )
        return {
            "handled": True,
            "delegate_legacy": False,
            "status": "waiting_user",
            "response": _canonical_v183_missing_question(field),
            "observations": [],
            "goals": {"primary_goal": "crear_reserva", "goals": [{"goal": "crear_reserva", "priority": 1.0}]},
            "perception": {"source": "canonical_ai_orchestrator_v183", "_v183_canonical_frozen": True},
            "canonical_decision": decision,
        }

    # Fecha y hora deben ser operacionalmente válidas antes de ejecutar tools.
    parsed_day = _parse_fecha_row(str(booking.get("day") or ""))
    if not parsed_day or not hora_es_valida(booking.get("time")):
        return None
    if not validar_fecha_en_dias_atencion(parsed_day):
        return None
    if not validar_hora_en_franja(booking.get("time")):
        return None

    perception = _canonical_v183_build_perception(state, booking, message)
    goals = {
        "primary_goal": "crear_reserva",
        "goals": [
            {"goal": "crear_reserva", "priority": 1.0},
            {"goal": "buscar_turno", "priority": 0.95},
        ],
    }
    telefono_key = telefono or "unknown"
    world = construir_world_state_agent_v2(
        telefono_key,
        prospecto or {},
        get_conversation_state(telefono_key),
        message,
        image_path,
    )
    availability_args = {
        "dia": booking["day"],
        "hora": booking["time"],
        "franja_dia": None,
        "cancha": None,
        "duracion_horas": booking["duration_hours"],
        "requested_hours": [booking["time"]],
        "booking_shape": "single",
        "temporal_mode": None,
        "resource_types": [booking["resource_type"]],
        "resource_type": booking["resource_type"],
    }
    observations: List[Dict[str, Any]] = []
    try:
        availability_obs = await ejecutar_tool_agent_v2(
            "consultar_disponibilidad",
            availability_args,
            world,
            perception,
            goals,
            telefono_key,
            prospecto or {},
            user_messages or [message],
            page=page,
            image_path=image_path,
        )
    except Exception as exc:
        print(
            "   ⚠️ [CANONICAL V183 TOOL] consultar_disponibilidad exception → legacy: "
            f"{type(exc).__name__}: {exc}"
        )
        return None

    observations.append(availability_obs)
    print(
        "   👁️ [CANONICAL V183 TOOL] consultar_disponibilidad "
        f"ok={availability_obs.get('ok')} status={availability_obs.get('status')}"
    )
    if availability_obs.get("ok"):
        aplicar_observation_agent_v2(telefono_key, availability_obs, world, perception)

    if not availability_obs.get("ok"):
        response = _agent_v2_fallback_response(goals, observations, world, perception)
        return {
            "handled": True,
            "delegate_legacy": False,
            "status": "complete",
            "response": response,
            "observations": observations,
            "goals": goals,
            "perception": perception,
            "world": world,
            "canonical_decision": decision,
        }

    adata = dict(availability_obs.get("data") or {})
    available_courts = [
        str(value or "").strip()
        for value in (adata.get("canchas_libres") or [])
        if str(value or "").strip()
    ]
    selected_court = str(
        adata.get("auto_assigned_court")
        or adata.get("single_court")
        or (available_courts[0] if available_courts else "")
    ).strip()
    if not selected_court:
        return None
    if not _court_matches_resource_types(selected_court, [booking["resource_type"]]):
        return None

    world = construir_world_state_agent_v2(
        telefono_key,
        prospecto or {},
        get_conversation_state(telefono_key),
        message,
        image_path,
    )
    create_args = {
        "dia": booking["day"],
        "hora": booking["time"],
        "cancha": selected_court,
        "duracion_horas": booking["duration_hours"],
        "requested_hours": [booking["time"]],
        "booking_shape": "single",
        "con_quincho": False,
        "quincho": "",
        "quincho_hora_inicio": hora_fin_bloque(
            booking["time"], booking["duration_hours"]
        ),
        "quincho_duracion_horas": 1.0,
    }
    try:
        create_obs = await ejecutar_tool_agent_v2(
            "crear_reserva",
            create_args,
            world,
            perception,
            goals,
            telefono_key,
            prospecto or {},
            user_messages or [message],
            page=page,
            image_path=image_path,
        )
    except Exception as exc:
        print(
            "   ⚠️ [CANONICAL V183 TOOL] crear_reserva exception → handoff legacy: "
            f"{type(exc).__name__}: {exc}"
        )
        return None

    observations.append(create_obs)
    print(
        "   👁️ [CANONICAL V183 TOOL] crear_reserva "
        f"ok={create_obs.get('ok')} status={create_obs.get('status')}"
    )
    if create_obs.get("ok"):
        aplicar_observation_agent_v2(telefono_key, create_obs, world, perception)

    if not create_obs.get("ok"):
        response = _agent_v2_fallback_response(goals, observations, world, perception)
        return {
            "handled": True,
            "delegate_legacy": False,
            "status": "complete",
            "response": response,
            "observations": observations,
            "goals": goals,
            "perception": perception,
            "world": world,
            "canonical_decision": decision,
        }

    response = _canonical_v189_created_reservation_message(create_obs)
    if not response:
        response = _agent_v2_fallback_response(goals, observations, world, perception)

    cdata = dict(create_obs.get("data") or {})
    state["active_flow"] = "awaiting_payment" if REQUIRES_DEPOSIT else None
    state["booking"].update({
        **booking,
        "court": selected_court,
        "status": "hold_pending_payment" if REQUIRES_DEPOSIT else "reserved",
        "reservation_id": cdata.get("reservation_id") or cdata.get("id"),
    })
    state["pending"] = None
    state["availability"] = None
    state["last_decision"] = decision
    _canonical_v183_save(telefono_key, state)

    world = construir_world_state_agent_v2(
        telefono_key,
        prospecto or {},
        get_conversation_state(telefono_key),
        message,
        image_path,
    )
    print(
        "   ✅ [CANONICAL V183 BOOKING COMPLETE] "
        f"{booking['day']} {booking['time']} {selected_court} → "
        "resumen + seña sin reinterpretación posterior"
    )
    return {
        "handled": True,
        "delegate_legacy": False,
        "status": "complete",
        "response": response,
        "observations": observations,
        "goals": goals,
        "perception": perception,
        "world": world,
        "safe_exit": {
            "state": "verified_operation",
            "evidence": [str(create_obs.get("observation_id") or "")],
        },
        "plan": {
            "source": "canonical_ai_orchestrator_v183",
            "steps": [
                {"tool": "consultar_disponibilidad", "args": availability_args},
                {"tool": "crear_reserva", "args": create_args},
            ],
        },
        "canonical_decision": decision,
        "canonical_fast_path": True,
    }


def _canonical_v183_sync_from_legacy_result(
    telefono: str,
    message: str,
    result: Dict[str, Any],
) -> None:
    try:
        state = _canonical_v183_hydrate_from_legacy(
            telefono,
            get_conversation_state(telefono),
        )
        observations = [
            dict(obs) for obs in (result.get("observations") or [])
            if isinstance(obs, dict)
        ]
        for obs in observations:
            tool = str(obs.get("tool") or "")
            data = dict(obs.get("data") or {})
            if tool == "consultar_disponibilidad" and obs.get("ok"):
                state["active_flow"] = "booking"
                booking = dict(state.get("booking") or {})
                if data.get("dia"):
                    booking["day"] = data.get("dia")
                if hora_es_valida(normalizar_hora_detectada(data.get("hora"))):
                    booking["time"] = normalizar_hora_detectada(data.get("hora"))
                types = _canonical_configured_court_types(
                    data.get("resource_types") or data.get("resource_type")
                )
                if len(types) == 1:
                    booking["resource_type"] = types[0]
                state["booking"] = booking
                state["availability"] = {
                    "scope_id": ((result.get("world") or {}).get("current_scope_id")),
                    "day": data.get("dia"),
                    "resource_type": data.get("resource_type"),
                    "resource_types": list(data.get("resource_types") or []),
                    "source_message": message,
                    "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
                }
            elif tool == "crear_reserva" and obs.get("ok"):
                state["active_flow"] = "awaiting_payment" if REQUIRES_DEPOSIT else None
                state["pending"] = None
                state["availability"] = None
                booking = dict(state.get("booking") or {})
                booking.update({
                    "day": data.get("dia") or booking.get("day"),
                    "time": normalizar_hora_detectada(data.get("hora")) or booking.get("time"),
                    "court": data.get("cancha") or booking.get("court"),
                    "reservation_id": data.get("reservation_id") or data.get("id"),
                    "status": "hold_pending_payment" if REQUIRES_DEPOSIT else "reserved",
                })
                state["booking"] = booking
        _canonical_v183_save(telefono, state)
    except Exception as exc:
        print(
            "   ⚠️ [CANONICAL V183 SYNC] sync legacy no fatal: "
            f"{type(exc).__name__}: {exc}"
        )


# ---------------------------------------------------------------------------
# V183 crash fix: response_obligations es LISTA desde el compiler actual.
# V181 asumía dict(...) y podía derribar el proceso DESPUÉS de crear la reserva.
# ---------------------------------------------------------------------------

def _agent_v2_v183_obligation_items(perception: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw = (perception or {}).get("response_obligations")
    if isinstance(raw, dict):
        if isinstance(raw.get("items"), list):
            return [dict(x) for x in raw.get("items") or [] if isinstance(x, dict)]
        return [dict(raw)]
    if isinstance(raw, list):
        return [dict(x) for x in raw if isinstance(x, dict)]
    return []


def _agent_v2_v181_reasks_verified_objective_field(
    perception: Dict[str, Any],
) -> bool:
    """V183: compatible con response_obligations list|dict; nunca lanza TypeError."""
    perception = perception or {}
    items = _agent_v2_v183_obligation_items(perception)
    objective = dict(perception.get("booking_objective") or {})
    if str(objective.get("operation") or "") != "create_booking":
        return False
    authority_map = objective.get("field_authority") or {}
    if not isinstance(authority_map, dict):
        return False
    for obligations in items:
        if str(obligations.get("type") or "") != "missing_field_question":
            continue
        field = _agent_v2_v105_normalize_missing_field(obligations.get("field"))
        if field not in {"dia", "hora", "resource_type", "cancha", "duracion_horas"}:
            continue
        authority = authority_map.get(field) or {}
        if not isinstance(authority, dict) or authority.get("verified") is not True:
            continue
        value = authority.get("value")
        if field == "hora":
            if hora_es_valida(normalizar_hora_detectada(value)):
                return True
        elif value not in (None, "", [], {}):
            return True
    return False


_ejecutar_agente_real_v2_turno_v183_legacy = ejecutar_agente_real_v2_turno


async def ejecutar_agente_real_v2_turno(
    mensaje: str,
    conv_state: Dict,
    prospecto: Dict,
    telefono: str,
    user_messages: List[str] = None,
    page=None,
    image_path: str = "",
    dry_run: bool = False,
    eval_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """V183: Canonical State → 1 AI decision → deterministic tools → legacy fallback."""
    telefono_key = telefono or "unknown"

    # Evals, media/pagos y dry-run conservan exactamente la ruta existente.
    can_use_canonical = bool(
        not dry_run
        and not (isinstance(eval_context, dict) and eval_context)
        and not str(image_path or "").strip()
        and _memory_owner_key(telefono_key) != "unknown"
    )

    if can_use_canonical:
        try:
            canonical_state = _canonical_v183_hydrate_from_legacy(
                telefono_key,
                conv_state if isinstance(conv_state, dict) else get_conversation_state(telefono_key),
            )
            if _canonical_v183_has_active_booking_context(canonical_state):
                print(
                    "   🧠 [CANONICAL V183 STATE] "
                    f"flow={canonical_state.get('active_flow')} "
                    f"booking={canonical_state.get('booking')} "
                    f"pending={(canonical_state.get('pending') or {}).get('field') if isinstance(canonical_state.get('pending'), dict) else None}"
                )
                decision = await _canonical_v183_orchestrate_booking(
                    mensaje,
                    user_messages or [mensaje],
                    canonical_state,
                )
                turn_id = f"canonical_turn_{uuid.uuid4().hex}"
                _canonical_v183_record_decision(
                    telefono_key,
                    turn_id,
                    mensaje,
                    decision,
                )
                canonical_state["last_decision"] = decision
                _canonical_v183_save(telefono_key, canonical_state)
                print(
                    "   🎯 [CANONICAL V183 ORCHESTRATOR] "
                    f"operation={decision.get('operation')} "
                    f"confidence={decision.get('confidence')} "
                    f"booking={decision.get('booking')}"
                )

                if (
                    decision.get("operation") == "create_booking"
                    and float(decision.get("confidence") or 0.0) >= 0.80
                ):
                    print(
                        "   🧊 [CANONICAL V183 DECISION FROZEN] "
                        "create_booking → legacy semantic pillars omitidos"
                    )
                    handled = await _canonical_v183_execute_booking(
                        mensaje,
                        user_messages or [mensaje],
                        canonical_state,
                        decision,
                        prospecto or {},
                        telefono_key,
                        page=page,
                        image_path=image_path,
                    )
                    if isinstance(handled, dict) and handled.get("handled"):
                        return handled

                if (
                    decision.get("operation") == "ask_missing"
                    and float(decision.get("confidence") or 0.0) >= 0.80
                ):
                    merged = _canonical_v183_merge_booking_decision(
                        canonical_state, decision
                    )
                    fields = [
                        _agent_v2_v105_normalize_missing_field(x)
                        for x in (decision.get("missing_fields") or [])
                        if _agent_v2_v105_normalize_missing_field(x)
                    ]
                    if not fields:
                        if not merged.get("day"):
                            fields.append("dia")
                        if not merged.get("time"):
                            fields.append("hora")
                        if not merged.get("resource_type"):
                            fields.append("resource_type")
                    if fields:
                        field = fields[0]
                        canonical_state["booking"].update(merged)
                        canonical_state["pending"] = {
                            "type": "booking_question",
                            "field": field,
                            "question_id": f"canonical_{uuid.uuid4().hex[:16]}",
                            "scope_id": str(((canonical_state.get("availability") or {}).get("scope_id") if isinstance(canonical_state.get("availability"), dict) else "") or f"canonical_scope_{uuid.uuid4().hex[:16]}"),
                            "day": merged.get("day"),
                            "time": merged.get("time"),
                            "time_specificity": merged.get("time_specificity"),
                            "resource_type": merged.get("resource_type"),
                            "duration_hours": merged.get("duration_hours"),
                            "operation": "create_booking",
                            "source": "canonical_v225_booking_question",
                            "goal_context": ["crear_reserva"],
                            "created_at": datetime.datetime.now(TIMEZONE).isoformat(),
                        }
                        _canonical_v183_save(telefono_key, canonical_state)
                        print(
                            "   🧩 [CANONICAL V183 ASK] "
                            f"field={field} → legacy semantic pillars omitidos"
                        )
                        return {
                            "handled": True,
                            "delegate_legacy": False,
                            "status": "waiting_user",
                            "response": _canonical_v183_missing_question(field),
                            "observations": [],
                            "goals": {"primary_goal": "crear_reserva", "goals": [{"goal": "crear_reserva", "priority": 1.0}]},
                            "perception": {"source": "canonical_ai_orchestrator_v183", "_v183_canonical_frozen": True},
                            "canonical_decision": decision,
                            "canonical_fast_path": True,
                        }

                print(
                    "   ↩️ [CANONICAL V183 FALLBACK] "
                    f"operation={decision.get('operation')} → Agent V2 legacy"
                )
        except Exception as exc:
            print(
                "   ⚠️ [CANONICAL V183] fast path no fatal → Agent V2 legacy: "
                f"{type(exc).__name__}: {exc}"
            )

    result = await _ejecutar_agente_real_v2_turno_v183_legacy(
        mensaje,
        conv_state,
        prospecto,
        telefono,
        user_messages=user_messages,
        page=page,
        image_path=image_path,
        dry_run=dry_run,
        eval_context=eval_context,
    )
    if isinstance(result, dict):
        _canonical_v183_sync_from_legacy_result(
            telefono_key,
            mensaje,
            result,
        )
    return result


