# ============================================================================
# V212 — INFORMATION ANSWER + SOCIAL ACK + TRANSACTIONAL NEXT BEST ACTION
# ============================================================================
# Las tools informativas resuelven hechos; esta capa opera UNA sola vez sobre la
# respuesta canónica final (también si hubo varias subintenciones) y elige la
# continuación comercial usando estado transaccional verificado. No interpreta
# keywords: las señales sociales vienen del único Orchestrator semántico.
# ============================================================================


def _canonical_v212_information_only_operations(
    decision: Dict[str, Any],
) -> bool:
    actions = decision.get("_v188_actions") if isinstance(decision, dict) else None
    if isinstance(actions, list) and actions:
        operations = {
            str(item.get("operation") or "").strip()
            for item in actions
            if isinstance(item, dict)
        }
    else:
        operations = {str((decision or {}).get("operation") or "").strip()}
    operations.discard("")
    return bool(operations and operations.issubset({"business_info", "query_price"}))


def _canonical_v212_valid_booking_day(value: Any) -> Optional[str]:
    raw = str(value or "").strip()
    parsed = _parse_fecha_row(raw)
    if parsed is None or parsed < datetime.datetime.now(TIMEZONE).date():
        return None
    return _agent_v2_v103_normalized_day(parsed.isoformat())


def _canonical_v212_social_prefix(
    decision: Dict[str, Any],
    full_turn: str,
) -> str:
    style = dict((decision or {}).get("conversation_style") or {})
    evidence = str(style.get("greeting_evidence") or "").strip()
    if (
        style.get("greeting_present") is True
        and _canonical_v200_literal_evidence(full_turn, evidence)
    ):
        # La identidad comercial proviene siempre de config.py (también después
        # de hot reload); el compositor no inventa un saludo social alternativo.
        return f"🙋 ¡Hola! Soy {AGENT_NAME} de {BUSINESS_NAME}."
    return ""


def _canonical_v212_information_continuation(
    *,
    state: Dict[str, Any],
    decision: Dict[str, Any],
    telefono: str,
) -> Dict[str, Any]:
    """Calcula CTA y pending sin convertir una FAQ en una escritura."""
    style = dict((decision or {}).get("conversation_style") or {})
    if any(
        style.get(key) is True
        for key in ("closing", "declines_booking", "information_only_boundary")
    ):
        return {"action": "none", "reason": "explicit_conversation_boundary"}

    reservations = [
        dict(row) for row in ((state or {}).get("reservations") or [])
        if isinstance(row, dict)
    ]
    pending_payment = next((
        row for row in reservations
        if str(row.get("deposit_status") or "").strip().casefold()
        in {"pendiente", "parcial", "pendiente_efectivo", "parcial_efectivo_pendiente"}
    ), None)
    if pending_payment:
        day = str(pending_payment.get("day") or "").strip()
        hour = normalizar_hora_detectada(pending_payment.get("time"))
        court = str(pending_payment.get("court") or "").strip()
        resource = str(_court_type_for_name(court) or "").strip()
        slot = " ".join(x for x in (resource, day, f"a las {hour}" if hour else "") if x)
        return {
            "action": "request_payment_proof",
            "field": "comprobante",
            "text": (
                f"Tu turno{f' de {slot}' if slot else ''} sigue bloqueado. "
                "Cuando puedas, enviame el comprobante de la seña para confirmarlo."
            ),
            "reservation_id": pending_payment.get("reservation_id"),
        }

    event = dict((state or {}).get("event_registration") or {})
    if str(event.get("status") or "").strip().casefold() == "pending_payment":
        return {
            "action": "request_event_payment_proof",
            "field": "comprobante_evento",
            "text": (
                "Tu inscripción al torneo sigue pendiente de confirmación. "
                "Cuando puedas, enviame el comprobante de la seña."
            ),
            "registration_id": event.get("registration_id"),
        }

    confirmed_statuses = {
        str(BOOKING_STATUS_RESERVED or "").strip().casefold(),
        str(BOOKING_STATUS_CONFIRMED or "").strip().casefold(),
        "confirmada", "confirmado", "reservada", "reservado",
    }
    if any(
        str(row.get("status") or "").strip().casefold() in confirmed_statuses
        for row in reservations
    ):
        return {"action": "none", "reason": "confirmed_booking_exists"}

    pending = (state or {}).get("pending")
    pending = dict(pending) if isinstance(pending, dict) else {}
    availability = (state or {}).get("availability")
    availability = dict(availability) if isinstance(availability, dict) else {}
    booking = dict((state or {}).get("booking") or {})

    has_live_booking_context = bool(
        _canonical_v183_booking_question(pending) or availability
    )
    state_day_raw = booking.get("day") or availability.get("day") or availability.get("dia")
    state_day = _canonical_v212_valid_booking_day(state_day_raw)
    if state_day_raw and not state_day:
        # Un objetivo vencido nunca personaliza la nueva CTA informativa.
        has_live_booking_context = False

    day = state_day if has_live_booking_context else None
    hour = normalizar_hora_detectada(
        booking.get("time") or availability.get("time") or availability.get("hora")
    ) if has_live_booking_context else None
    resource = str(booking.get("resource_type") or "").strip() if has_live_booking_context else ""

    # Un deporte mencionado en la consulta actual puede abrir el nuevo objetivo,
    # pero nunca heredamos día/hora históricos sin un pending vigente.
    current_resource_types = _canonical_configured_court_types(
        ((decision or {}).get("booking") or {}).get("resource_type")
    )
    if not resource and len(current_resource_types) == 1:
        resource = current_resource_types[0]

    if not day and not hour:
        field = "dia"
        question = "¿Qué día y a qué hora te gustaría reservar?"
    elif not day:
        field = "dia"
        question = f"¿Para qué día querés reservar a las {hour}?"
    elif not hour:
        field = "hora"
        question = f"¿A qué hora te gustaría reservar el {day}?"
    elif not resource:
        field = "resource_type"
        configured = list(_configured_court_type_labels())
        question = (
            f"Para {day} a las {hour}, ¿qué querés reservar: "
            f"{_agent_v2_join_human_options(configured)}?"
            if configured else
            f"Para {day} a las {hour}, ¿qué tipo de cancha querés reservar?"
        )
    else:
        field = "confirmar_slot"
        question = (
            f"¿Querés que consulte disponibilidad de {resource} "
            f"para {day} a las {hour}?"
        )

    state_booking = (
        dict((state or {}).get("booking") or {})
        if has_live_booking_context
        else dict(
            _canonical_v183_default_state(
                str((state or {}).get("owner") or telefono or "unknown")
            )["booking"]
        )
    )
    state_booking.setdefault("with_quincho", False)
    state_booking.setdefault("quincho", None)
    state_booking.setdefault("quincho_start", None)
    state_booking.setdefault("quincho_duration_hours", 1.0)
    state_booking.setdefault("daypart", None)
    state_booking.setdefault("time_specificity", None)
    if day:
        state_booking["day"] = day
    if hour:
        state_booking["time"] = hour
    if resource:
        state_booking["resource_type"] = resource
    state["booking"] = state_booking
    state["active_flow"] = "booking"
    state["pending"] = {
        "type": "booking_question",
        "field": field,
        "question_text": question,
        "question_id": f"info_bridge_{uuid.uuid4().hex[:12]}",
        "scope_id": f"info_booking_{uuid.uuid4().hex[:12]}",
        "goal_context": ["buscar_turno", "crear_reserva"],
        "source": "canonical_v212_information_booking_bridge",
    }
    _canonical_v183_save(telefono, state)
    return {
        "action": "ask_booking_detail",
        "field": field,
        "text": question,
    }


_canonical_v184_execute_decision_v212_base = _canonical_v184_execute_decision


async def _canonical_v184_execute_decision(
    message: str,
    user_messages: List[str],
    state: Dict[str, Any],
    decision: Dict[str, Any],
    prospecto: Dict[str, Any],
    telefono: str,
    *,
    page=None,
    image_path: str = "",
) -> Optional[Dict[str, Any]]:
    result = await _canonical_v184_execute_decision_v212_base(
        message,
        user_messages,
        state,
        decision,
        prospecto,
        telefono,
        page=page,
        image_path=image_path,
    )
    if not isinstance(result, dict) or not result.get("handled"):
        return result
    if not _canonical_v212_information_only_operations(decision):
        return result
    if result.get("silent_handoff") or result.get("customer_response_suppressed"):
        return result
    if str(result.get("delivery_policy") or "") == "suppress_customer":
        return result

    full_turn = _canonical_v200_current_turn_text(message, user_messages)
    prefix = _canonical_v212_social_prefix(decision, full_turn)
    continuation = _canonical_v212_information_continuation(
        state=state,
        decision=decision,
        telefono=telefono,
    )
    parts = [prefix, str(result.get("response") or "").strip()]
    if continuation.get("text"):
        parts.append(str(continuation.get("text") or "").strip())
        result["status"] = "waiting_user"
    result["response"] = "\n\n".join(part for part in parts if part).strip()
    result["next_best_action"] = {
        key: value for key, value in continuation.items() if key != "text"
    }
    result["canonical_v212_information_bridge"] = True
    print(
        "   🤝 [CANONICAL V212 INFORMATION → BOOKING] "
        f"greeting={bool(prefix)} action={continuation.get('action')} "
        f"field={continuation.get('field')}"
    )
    return result

# ============================================================================
# CANONICAL V218 — QUINCHO FINANCIAL + PARTIAL-MUTATION INTEGRITY
# 06/10/2026
#
# Incidentes cubiertos:
#   A) Cancha $40.000 + quincho $10.000 no puede publicar total $40.000 / seña $20.000.
#      Debe publicar total $50.000 / seña $25.000 (con seña porcentual 50%).
#   B) "de 14 a 15 queremos la cancha" modifica sólo el bloque de cancha; no
#      elimina un quincho existente ni su vínculo de tercer tiempo.
# ============================================================================
_run_agent_v2_invariant_evals_v218_base = run_agent_v2_invariant_evals


def run_agent_v2_invariant_evals() -> Dict[str, Any]:
    result = _run_agent_v2_invariant_evals_v218_base()
    results = list(result.get("results") or [])

    # Guard semántico exacto del incidente real.
    results.append({
        "name": "v218_court_time_correction_does_not_remove_quincho",
        "passed": (
            _canonical_v218_quincho_receipt_has_explicit_evidence(
                "remove", "queremos la cancha"
            ) is False
            and _canonical_v218_quincho_receipt_has_explicit_evidence(
                "remove", "solo la cancha"
            ) is True
            and _canonical_v218_quincho_receipt_has_explicit_evidence(
                "remove", "sacalo"
            ) is True
        ),
    })

    # Confirmación corta: no hereda duración stale de otro turno.
    duration_state = {
        "booking": {
            "day": "Martes 06/10",
            "time": "17:00",
            "resource_type": "Tenis",
            "duration_hours": 1.0,
        },
        "availability": {
            "day": "Martes 06/10",
            "resource_type": "Tenis",
            "resource_types": ["Tenis"],
            "source_message": "tenes cancha de tenis para hoy a las 5?",
        },
        "active_flow": "booking",
    }
    duration_decision = {
        "operation": "create_booking",
        "booking": {
            "day": "Martes 06/10",
            "time": "17:00",
            "resource_type": "Tenis",
            "duration_hours": 2.0,
        },
        "actions": [],
    }
    duration_fixed = _canonical_v218_preserve_verified_duration_on_confirmation(
        duration_decision, duration_state, "si metele", ["si metele"]
    )
    results.append({
        "name": "v218_short_confirmation_keeps_verified_duration",
        "passed": abs(float((duration_fixed.get("booking") or {}).get("duration_hours") or 0) - 1.0) < 1e-9,
    })

    # FactPack financiero: un alta estructural de addon no puede conservar el
    # total anterior de la cancha sola aunque la fila de entrada venga stale.
    fake_obs = {
        "tool": "agregar_quincho",
        "ok": True,
        "status": "success",
        "data": {
            "enabled": True,
            "quincho": "Quincho 1",
            "duracion_horas": 1.0,
            "precio_quincho": 10000,
            "schedule_only_mutation": False,
            "reserva": {
                "duracion_horas": 2.0,
                "precio_cancha_total": 40000,
                "con_quincho": "Si",
                "quincho": "Quincho 1",
                "quincho_duracion_horas": 1.0,
                "quincho_precio_total": 10000,
                # Snapshot stale que reprodujo el bug real.
                "precio_total": 40000,
                "senia_estado": "pendiente",
                "senia_monto": 20000,
                "monto_pendiente": 20000,
            },
        },
    }
    enriched = _agent_v2_v116_mutation_financial_factpack(fake_obs)
    facts = ((enriched.get("data") or {}).get("financial_fact_contract") or {})
    expected_total = 50000
    expected_deposit = _senia_para_total(expected_total)
    results.append({
        "name": "v218_add_quincho_recomputes_total_and_pending_deposit",
        "passed": bool(
            facts.get("precio_total") == expected_total
            and facts.get("senia_monto") == expected_deposit
            and facts.get("monto_pendiente")
                == calcular_monto_pendiente(expected_total, expected_deposit)
        ),
    })

    passed = sum(
        1 for item in results
        if bool(item.get("passed") if "passed" in item else item.get("ok"))
    )
    return {
        **result,
        "ok": passed == len(results),
        "passed": passed,
        "total": len(results),
        "results": results,
        "build": "v227-partial-cash-context-binding",
    }


